window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["其他部门"] = {"zhuanxiangguihuahuanjingyingxiangbaogaoshushenchab509cb1":[{"i":1,"n":"第一条","txt":"为规范对专项规划环境影响报告书的审查，保障审查的客观性和公正性，根据《中华人民共和国环境影响评价法》，制定本办法。"},{"i":2,"n":"第二条","txt":"符合下列条件的专项规划的环境影响报告书应当按照本办法规定进行审查： （一）列入国务院规定应进行环境影响评价范围的； （二）依法由省级以上人民政府有关部门负责审批的。"},{"i":3,"n":"第三条","txt":"专项规划环境影响报告书的审查必须客观、公开、公正，从经济、社会和环境可持续发展的角度，综合考虑专项规划实施后对各种环境因素及其所构成的生态系统可能造成的影响。"},{"i":4,"n":"第四条","txt":"专项规划编制机关在报批专项规划草案时，应依法将环境影响报告书一并附送审批机关；专项规划的审批机关在作出审批专项规划草案的决定前，应当将专项规划环境影响报告书送同级环境保护行政主管部门，由同级环境保护行政主管部门会同专项规划的审批机关对环境影响报告书进行审查。"},{"i":5,"n":"第五条","txt":"环境保护行政主管部门应当自收到专项规划环境影响报告书之日起30日内，会同专项规划审批机关召集有关部门代表和专家组成审查小组，对专项规划环境影响报告书进行审查；审查小组应当提出书面审查意见。"},{"i":6,"n":"第六条","txt":"参加审查小组的专家，应当从国务院环境保护行政主管部门规定设立的环境影响评价审查专家库内的相关专业、行业专家名单中，以随机抽取的方式确定。专家人数应当不少于审查小组总人数的二分之一。"},{"i":7,"n":"第七条","txt":"审查意见应当包括下列内容： （一）实施该专项规划对环境可能造成影响的分析、预测的合理性和准确性； （二）预防或者减轻不良环境影响的对策和措施的可行性、有效性及调整建议； （三）对专项规划环境影响评价报告书和评价结论的基本评价； （四）从经济、社会和环境可持续发展的角度对专项规划的合理性、可行性的总体评价及改进建议。 审查意见应当如实、客观地记录专家意见，并由专家签字。"},{"i":8,"n":"第八条","txt":"环境保护行政主管部门应在审查小组提出书面审查意见之日起10日内将审查意见提交专项规划审批机关。 专项规划审批机关应当将环境影响报告书结论及审查意见作为决策的重要依据。专项规划环境影响报告书未经审查，专项规划审批机关不得审批专项规划。在审批中未采纳审查意见的，应当作出说明，并存档备查。"},{"i":9,"n":"第九条","txt":"专项规划环境影响报告书审查所需费用，从专项规划环境影响报告书编制费用中列支。"},{"i":10,"n":"第十条","txt":"国家规定需要保密的专项规划环境影响报告书的审查，按有关规定执行。"},{"i":11,"n":"第十一条","txt":"本办法自发布之日起施行。"}],"gerenxinxichujingrenzhengbanfa":[{"i":1,"n":"第一条","txt":"为了保护个人信息权益，规范个人信息出境认证活动，促进个人信息高效安全跨境流动，根据《中华人民共和国个人信息保护法》、《网络数据安全管理条例》、《中华人民共和国认证认可条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"个人信息处理者通过个人信息保护认证的方式向中华人民共和国境外提供个人信息，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称个人信息出境认证，是指按照《中华人民共和国个人信息保护法》第三十八条第一款第二项规定，由依法取得个人信息保护认证资质的专业认证机构，证明个人信息处理者向中华人民共和国境外提供个人信息等个人信息处理活动符合相关法律、行政法规、部门规章、标准、技术规范的合格评定活动。"},{"i":4,"n":"第四条","txt":"国家网信部门会同国家数据管理部门和其他有关部门制定个人信息出境认证相关标准、技术规范。国家市场监督管理部门会同国家网信部门制定个人信息保护认证规则、统一认证证书及标志。"},{"i":5,"n":"第五条","txt":"个人信息处理者通过个人信息出境认证的方式向境外提供个人信息的，应当同时符合下列情形： （一）非关键信息基础设施运营者； （二）自当年1月1日起累计向境外提供10万人以上、不满100万人个人信息（不含敏感个人信息）或者不满1万人敏感个人信息。 前款所称向境外提供的个人信息，不包括重要数据。 法律、行政法规或者国家网信部门另有规定的，从其规定。 个人信息处理者不得采取数量拆分等手段，将依法应当通过出境安全评估的个人信息通过个人信息出境认证的方式向境外提供。"},{"i":6,"n":"第六条","txt":"个人信息处理者在申请认证向境外提供个人信息前，应当按照法律、行政法规的规定履行告知、取得个人单独同意、进行个人信息保护影响评估等义务。个人信息保护影响评估重点评估以下内容： （一）个人信息处理者和境外接收方处理个人信息的目的、范围、方式等的合法性、正当性、必要性； （二）出境个人信息的规模、范围、种类、敏感程度，个人信息出境可能对国家安全、公共利益、个人信息权益带来的风险； （三）境外接收方承诺承担的义务，以及履行义务的管理和技术措施、能力等能否保障出境个人信息的安全； （四）个人信息出境后遭到篡改、破坏、泄露、丢失、非法利用等的风险，个人信息权益维护的渠道是否通畅等； （五）境外接收方所在国家或者地区的个人信息保护政策和法规对出境个人信息安全和个人信息权益的影响； （六）其他可能影响个人信息出境安全的事项。"},{"i":7,"n":"第七条","txt":"个人信息处理者通过认证方式向境外提供个人信息的，应当向专业认证机构申请个人信息出境认证。 中华人民共和国境外的个人信息处理者申请个人信息出境认证的，应当由其在境内设立的专门机构或者指定代表协助进行申请。"},{"i":8,"n":"第八条","txt":"专业认证机构应当按照认证基本规范、个人信息保护认证规则开展个人信息出境认证活动。符合认证要求的，专业认证机构应当及时出具认证证书。 认证证书的有效期为3年。证书到期需继续使用的，个人信息处理者应当在有效期届满前6个月提出认证申请。"},{"i":9,"n":"第九条","txt":"专业认证机构应当在出具认证证书或者认证证书状态发生变化后5个工作日内，向全国认证认可信息公共服务平台报送个人信息出境认证证书相关信息，包括认证证书编号、获证个人信息处理者名称、认证范围以及证书状态变化信息等。 国家市场监督管理部门与国家网信部门建立认证信息共享机制。"},{"i":10,"n":"第十条","txt":"专业认证机构发现获证个人信息处理者存在个人信息出境情况与认证范围不一致等情形，不再符合认证要求的，应当暂停其使用直至撤销相关认证证书。 国家网信部门和有关部门在个人信息保护监督管理工作中发现获证个人信息处理者存在前款情形的，专业认证机构应当配合暂停其使用直至撤销相关认证证书。 前两款规定的情形，应当通过全国认证认可信息公共服务平台予以公布。"},{"i":11,"n":"第十一条","txt":"专业认证机构在开展认证活动中，发现个人信息出境活动违反法律、行政法规和国家有关规定的，应当及时向国家网信部门和有关部门报告。"},{"i":12,"n":"第十二条","txt":"开展个人信息出境认证的专业认证机构应当自国家市场监督管理部门批准取得个人信息保护认证资质之日起10个工作日内向国家网信部门办理备案手续。办理备案时，应当提交下列材料： （一）取得的个人信息保护领域的认证资质情况； （二）近3年从事数据安全、个人信息保护领域专业工作情况； （三）专业认证机构人员安全背景审查材料； （四）个人信息保护认证实施细则及工作计划； （五）个人信息安全风险防范机制； （六）对获证个人信息处理者进行的个人信息出境活动符合认证标准情况的持续监督机制； （七）投诉受理和争议解决机制； （八）其他需要提交的材料。 专业认证机构应当对所备案材料的真实性负责。 国家网信部门收到专业认证机构提交的备案材料后，会同国家数据管理部门对备案材料进行审核。材料齐全的，应当在30个工作日内予以备案并进行公示；材料不齐全的，不予备案，应当在30个工作日内通知专业认证机构并说明理由。"},{"i":13,"n":"第十三条","txt":"国家市场监督管理部门和国家网信部门对个人信息出境认证活动进行监督，开展定期或者不定期的检查，对认证过程和认证结果进行抽查，对专业认证机构进行抽查和评价。"},{"i":14,"n":"第十四条","txt":"国家机关、专业认证机构等从事认证活动的机构及其工作人员对在履行职责中知悉的个人隐私、个人信息、商业秘密、保密商务信息等应当依法予以保密，不得泄露或者非法向他人提供、非法使用。"},{"i":15,"n":"第十五条","txt":"任何组织和个人发现获证个人信息处理者违反本办法规定向境外提供个人信息的，可以向专业认证机构、网信部门和有关部门投诉、举报。"},{"i":16,"n":"第十六条","txt":"省级以上网信部门和有关部门发现获证个人信息处理者个人信息出境活动存在较大风险或者发生个人信息安全事件的，可以依法对获证个人信息处理者进行约谈。获证个人信息处理者应当按照要求整改，消除隐患。"},{"i":17,"n":"第十七条","txt":"违反本办法规定的，依据《中华人民共和国个人信息保护法》、《网络数据安全管理条例》、《中华人民共和国认证认可条例》等法律法规处理；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"本办法施行前制定的关于个人信息出境认证的相关规定与本办法不一致的，按照本办法执行。"},{"i":19,"n":"第十九条","txt":"本办法自2026年1月1日起施行。"}],"guojiashenjizhunze":[{"i":1,"n":"第一条","txt":"为了规范和指导审计机关和审计人员执行审计业务的行为，保证审计质量，防范审计风险，发挥审计保障国家经济和社会健康运行的“免疫系统”功能，根据《中华人民共和国审计法》、《中华人民共和国审计法实施条例》和其他有关法律法规，制定本准则。"},{"i":2,"n":"第二条","txt":"本准则是审计机关和审计人员履行法定审计职责的行为规范，是执行审计业务的职业标准，是评价审计质量的基本尺度。"},{"i":3,"n":"第三条","txt":"本准则中使用“应当”、“不得”词汇的条款为约束性条款，是审计机关和审计人员执行审计业务必须遵守的职业要求。 本准则中使用“可以”词汇的条款为指导性条款，是对良好审计实务的推介。"},{"i":4,"n":"第四条","txt":"审计机关和审计人员执行审计业务，应当适用本准则。其他组织或者人员接受审计机关的委托、聘用，承办或者参加审计业务，也应当适用本准则。"},{"i":5,"n":"第五条","txt":"审计机关和审计人员执行审计业务，应当区分被审计单位的责任和审计机关的责任。 在财政收支、财务收支以及有关经济活动中，履行法定职责、遵守相关法律法规、建立并实施内部控制、按照有关会计准则和会计制度编报财务会计报告、保持财务会计资料的真实性和完整性，是被审计单位的责任。 依据法律法规和本准则的规定，对被审计单位财政收支、财务收支以及有关经济活动独立实施审计并作出审计结论，是审计机关的责任。"},{"i":6,"n":"第六条","txt":"审计机关的主要工作目标是通过监督被审计单位财政收支、财务收支以及有关经济活动的真实性、合法性、效益性，维护国家经济安全，推进民主法治，促进廉政建设，保障国家经济和社会健康发展。 真实性是指反映财政收支、财务收支以及有关经济活动的信息与实际情况相符合的程度。 合法性是指财政收支、财务收支以及有关经济活动遵守法律、法规或者规章的情况。 效益性是指财政收支、财务收支以及有关经济活动实现的经济效益、社会效益和环境效益。"},{"i":7,"n":"第七条","txt":"审计机关对依法属于审计机关审计监督对象的单位、项目、资金进行审计。 审计机关按照国家有关规定，对依法属于审计机关审计监督对象的单位的主要负责人经济责任进行审计。"},{"i":8,"n":"第八条","txt":"审计机关依法对预算管理或者国有资产管理使用等与国家财政收支有关的特定事项向有关地方、部门、单位进行专项审计调查。 审计机关进行专项审计调查时，也应当适用本准则。"},{"i":9,"n":"第九条","txt":"审计机关和审计人员执行审计业务，应当依据年度审计项目计划，编制审计实施方案，获取审计证据，作出审计结论。 审计机关应当委派具备相应资格和能力的审计人员承办审计业务，并建立和执行审计质量控制制度。"},{"i":10,"n":"第十条","txt":"审计机关依据法律法规规定，公开履行职责的情况及其结果，接受社会公众的监督。"},{"i":11,"n":"第十一条","txt":"审计机关和审计人员未遵守本准则约束性条款的，应当说明原因。"},{"i":12,"n":"第十二条","txt":"审计机关和审计人员执行审计业务，应当具备本准则规定的资格条件和职业要求。"},{"i":13,"n":"第十三条","txt":"审计机关执行审计业务，应当具备下列资格条件： （一）符合法定的审计职责和权限； （二）有职业胜任能力的审计人员； （三）建立适当的审计质量控制制度； （四）必需的经费和其他工作条件。"},{"i":14,"n":"第十四条","txt":"审计人员执行审计业务，应当具备下列职业要求： （一）遵守法律法规和本准则； （二）恪守审计职业道德； （三）保持应有的审计独立性； （四）具备必需的职业胜任能力； （五）其他职业要求。"},{"i":15,"n":"第十五条","txt":"审计人员应当恪守严格依法、正直坦诚、客观公正、勤勉尽责、保守秘密的基本审计职业道德。 严格依法就是审计人员应当严格依照法定的审计职责、权限和程序进行审计监督，规范审计行为。 正直坦诚就是审计人员应当坚持原则，不屈从于外部压力；不歪曲事实，不隐瞒审计发现的问题；廉洁自律，不利用职权谋取私利；维护国家利益和公共利益。 客观公正就是审计人员应当保持客观公正的立场和态度，以适当、充分的审计证据支持审计结论，实事求是地作出审计评价和处理审计发现的问题。 勤勉尽责就是审计人员应当爱岗敬业，勤勉高效，严谨细致，认真履行审计职责，保证审计工作质量。 保守秘密就是审计人员应当保守其在执行审计业务中知悉的国家秘密、商业秘密；对于执行审计业务取得的资料、形成的审计记录和掌握的相关情况，未经批准不得对外提供和披露，不得用于与审计工作无关的目的。"},{"i":16,"n":"第十六条","txt":"审计人员执行审计业务时，应当保持应有的审计独立性，遇有下列可能损害审计独立性情形的，应当向审计机关报告： （一）与被审计单位负责人或者有关主管人员有夫妻关系、直系血亲关系、三代以内旁系血亲以及近姻亲关系； （二）与被审计单位或者审计事项有直接经济利益关系； （三）对曾经管理或者直接办理过的相关业务进行审计； （四）可能损害审计独立性的其他情形。"},{"i":17,"n":"第十七条","txt":"审计人员不得参加影响审计独立性的活动，不得参与被审计单位的管理活动。"},{"i":18,"n":"第十八条","txt":"审计机关组成审计组时，应当了解审计组成员可能损害审计独立性的情形，并根据具体情况采取下列措施，避免损害审计独立性： （一）依法要求相关审计人员回避； （二）对相关审计人员执行具体审计业务的范围作出限制； （三）对相关审计人员的工作追加必要的复核程序； （四）其他措施。"},{"i":19,"n":"第十九条","txt":"审计机关应当建立审计人员交流等制度，避免审计人员因执行审计业务长期与同一被审计单位接触可能对审计独立性造成的损害。"},{"i":20,"n":"第二十条","txt":"审计机关可以聘请外部人员参加审计业务或者提供技术支持、专业咨询、专业鉴定。 审计机关聘请的外部人员应当具备本准则第十四条规定的职业要求。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的外部人员，审计机关不得聘请： （一）被刑事处罚的； （二）被劳动教养的； （三）被行政拘留的； （四）审计独立性可能受到损害的； （五）法律规定不得从事公务的其他情形。"},{"i":22,"n":"第二十二条","txt":"审计人员应当具备与其从事审计业务相适应的专业知识、职业能力和工作经验。 审计机关应当建立和实施审计人员录用、继续教育、培训、业绩评价考核和奖惩激励制度，确保审计人员具有与其从事业务相适应的职业胜任能力。"},{"i":23,"n":"第二十三条","txt":"审计机关应当合理配备审计人员，组成审计组，确保其在整体上具备与审计项目相适应的职业胜任能力。 被审计单位的信息技术对实现审计目标有重大影响的，审计组的整体胜任能力应当包括信息技术方面的胜任能力。"},{"i":24,"n":"第二十四条","txt":"审计人员执行审计业务时，应当合理运用职业判断，保持职业谨慎，对被审计单位可能存在的重要问题保持警觉，并审慎评价所获取审计证据的适当性和充分性，得出恰当的审计结论。"},{"i":25,"n":"第二十五条","txt":"审计人员执行审计业务时，应当从下列方面保持与被审计单位的工作关系： （一）与被审计单位沟通并听取其意见； （二）客观公正地作出审计结论，尊重并维护被审计单位的合法权益； （三）严格执行审计纪律； （四）坚持文明审计，保持良好的职业形象。"},{"i":26,"n":"第二十六条","txt":"审计机关应当根据法定的审计职责和审计管辖范围，编制年度审计项目计划。 编制年度审计项目计划应当服务大局，围绕政府工作中心，突出审计工作重点，合理安排审计资源，防止不必要的重复审计。"},{"i":27,"n":"第二十七条","txt":"审计机关按照下列步骤编制年度审计项目计划： （一）调查审计需求，初步选择审计项目； （二）对初选审计项目进行可行性研究，确定备选审计项目及其优先顺序； （三）评估审计机关可用审计资源，确定审计项目，编制年度审计项目计划。"},{"i":28,"n":"第二十八条","txt":"审计机关从下列方面调查审计需求，初步选择审计项目： （一）国家和地区财政收支、财务收支以及有关经济活动情况； （二）政府工作中心； （三）本级政府行政首长和相关领导机关对审计工作的要 求； （四）上级审计机关安排或者授权审计的事项； （五）有关部门委托或者提请审计机关审计的事项； （六）群众举报、公众关注的事项； （七）经分析相关数据认为应当列入审计的事项； （八）其他方面的需求。"},{"i":29,"n":"第二十九条","txt":"审计机关对初选审计项目进行可行性研究，确定初选审计项目的审计目标、审计范围、审计重点和其他重要事项。 进行可行性研究重点调查研究下列内容： （一）与确定和实施审计项目相关的法律法规和政策； （二）管理体制、组织结构、主要业务及其开展情况； （三）财政收支、财务收支状况及结果； （四）相关的信息系统及其电子数据情况； （五）管理和监督机构的监督检查情况及结果； （六）以前年度审计情况； （七）其他相关内容。"},{"i":30,"n":"第三十条","txt":"审计机关在调查审计需求和可行性研究过程中，从下列方面对初选审计项目进行评估，以确定备选审计项目及其优先顺序： （一）项目重要程度，评估在国家经济和社会发展中的重要性、政府行政首长和相关领导机关及公众关注程度、资金和资产规模等； （二）项目风险水平，评估项目规模、管理和控制状况等； （三）审计预期效果； （四）审计频率和覆盖面； （五）项目对审计资源的要求。"},{"i":31,"n":"第三十一条","txt":"年度审计项目计划应当按照审计机关规定的程序审定。 审计机关在审定年度审计项目计划前，根据需要，可以组织专家进行论证。"},{"i":32,"n":"第三十二条","txt":"下列审计项目应当作为必选审计项目： （一）法律法规规定每年应当审计的项目； （二）本级政府行政首长和相关领导机关要求审计的项目； （三）上级审计机关安排或者授权的审计项目。 审计机关对必选审计项目，可以不进行可行性研究。"},{"i":33,"n":"第三十三条","txt":"上级审计机关直接审计下级审计机关审计管辖范围内的重大审计事项，应当列入上级审计机关年度审计项目计划，并及时通知下级审计机关。"},{"i":34,"n":"第三十四条","txt":"上级审计机关可以依法将其审计管辖范围内的审计事项，授权下级审计机关进行审计。对于上级审计机关审计管辖范围内的审计事项，下级审计机关也可以提出授权申请，报有管辖权的上级审计机关审批。 获得授权的审计机关应当将授权的审计事项列入年度审计项目计划。"},{"i":35,"n":"第三十五条","txt":"根据中国政府及其机构与国际组织、外国政府及其机构签订的协议和上级审计机关的要求，审计机关确定对国际组织、外国政府及其机构援助、贷款项目进行审计的，应当纳入年度审计项目计划。"},{"i":36,"n":"第三十六条","txt":"对于预算管理或者国有资产管理使用等与国家财政收支有关的特定事项，符合下列情形的，可以进行专项审计调查： （一）涉及宏观性、普遍性、政策性或者体制、机制问题的； （二）事项跨行业、跨地区、跨单位的； （三）事项涉及大量非财务数据的； （四）其他适宜进行专项审计调查的。"},{"i":37,"n":"第三十七条","txt":"审计机关年度审计项目计划的内容主要包括： （一）审计项目名称； （二）审计目标，即实施审计项目预期要完成的任务和结? 果； （三）审计范围，即审计项目涉及的具体单位、事项和所属期间； （四）审计重点； （五）审计项目组织和实施单位； （六）审计资源。 采取跟踪审计方式实施的审计项目，年度审计项目计划应当列明跟踪的具体方式和要求。 专项审计调查项目的年度审计项目计划应当列明专项审计调查的要求。"},{"i":38,"n":"第三十八条","txt":"审计机关编制年度审计项目计划可以采取文字、表格或者两者相结合的形式。"},{"i":39,"n":"第三十九条","txt":"审计机关计划管理部门与业务部门或者派出机构，应当建立经常性的沟通和协调机制。 调查审计需求、进行可行性研究和确定备选审计项目，以业务部门或者派出机构为主实施；备选审计项目排序、配置审计资源和编制年度审计项目计划草案，以计划管理部门为主实施。"},{"i":40,"n":"第四十条","txt":"审计机关根据项目评估结果，确定年度审计项目计划。"},{"i":41,"n":"第四十一条","txt":"审计机关应当将年度审计项目计划报经本级政府行政首长批准并向上一级审计机关报告。"},{"i":42,"n":"第四十二条","txt":"审计机关应当对确定的审计项目配置必要的审计人力资源、审计时间、审计技术装备、审计经费等审计资源。"},{"i":43,"n":"第四十三条","txt":"审计机关同一年度内对同一被审计单位实施不同的审计项目，应当在人员和时间安排上进行协调，尽量避免给被审计单位工作带来不必要的影响。"},{"i":44,"n":"第四十四条","txt":"审计机关应当将年度审计项目计划下达审计项目组织和实施单位执行。 年度审计项目计划一经下达，审计项目组织和实施单位应当确保完成，不得擅自变更。"},{"i":45,"n":"第四十五条","txt":"年度审计项目计划执行过程中，遇有下列情形之一的，应当按照原审批程序调整： （一）本级政府行政首长和相关领导机关临时交办审计项目的； （二）上级审计机关临时安排或者授权审计项目的； （三）突发重大公共事件需要进行审计的； （四）原定审计项目的被审计单位发生重大变化，导致原计划无法实施的； （五）需要更换审计项目实施单位的； （六）审计目标、审计范围等发生重大变化需要调整的； （七）需要调整的其他情形。"},{"i":46,"n":"第四十六条","txt":"上级审计机关应当指导下级审计机关编制年度审计项目计划，提出下级审计机关重点审计领域或者审计项目安排的指导意见。"},{"i":47,"n":"第四十七条","txt":"年度审计项目计划确定审计机关统一组织多个审计组共同实施一个审计项目或者分别实施同一类审计项目的，审计机关业务部门应当编制审计工作方案。"},{"i":48,"n":"第四十八条","txt":"审计机关业务部门编制审计工作方案，应当根据年度审计项目计划形成过程中调查审计需求、进行可行性研究的情况，开展进一步调查，对审计目标、范围、重点和项目组织实施等进行确定。"},{"i":49,"n":"第四十九条","txt":"审计工作方案的内容主要包括： （一）审计目标； （二）审计范围； （三）审计内容和重点； （四）审计工作组织安排； （五）审计工作要求。"},{"i":50,"n":"第五十条","txt":"审计机关业务部门编制的审计工作方案应当按照审计机关规定的程序审批。在年度审计项目计划确定的实施审计起始时间之前，下达到审计项目实施单位。 审计机关批准审计工作方案前，根据需要，可以组织专家进行论证。"},{"i":51,"n":"第五十一条","txt":"审计机关业务部门根据审计实施过程中情况的变化，可以申请对审计工作方案的内容进行调整，并按审计机关规定的程序报批。"},{"i":52,"n":"第五十二条","txt":"审计机关应当定期检查年度审计项目计划执行情况，评估执行效果。 审计项目实施单位应当向下达审计项目计划的审计机关报告计划执行情况。"},{"i":53,"n":"第五十三条","txt":"审计机关应当按照国家有关规定，建立和实施审计项目计划执行情况及其结果的统计制度。"},{"i":54,"n":"第五十四条","txt":"审计机关应当在实施项目审计前组成审计组。 审计组由审计组组长和其他成员组成。审计组实行审计组组长负责制。审计组组长由审计机关确定，审计组组长可以根据需要在审计组成员中确定主审，主审应当履行其规定职责和审计组组长委托履行的其他职责。"},{"i":55,"n":"第五十五条","txt":"审计机关应当依照法律法规的规定，向被审计单位送达审计通知书。"},{"i":56,"n":"第五十六条","txt":"审计通知书的内容主要包括被审计单位名称、审计依据、审计范围、审计起始时间、审计组组长及其他成员名单和被审计单位配合审计工作的要求。同时，还应当向被审计单位告知审计组的审计纪律要求。 采取跟踪审计方式实施审计的，审计通知书应当列明跟踪审计的具体方式和要求。 专项审计调查项目的审计通知书应当列明专项审计调查的要求。"},{"i":57,"n":"第五十七条","txt":"审计组应当调查了解被审计单位及其相关情况，评估被审计单位存在重要问题的可能性，确定审计应对措施，编制审计实施方案。 对于审计机关已经下达审计工作方案的，审计组应当按照审计工作方案的要求编制审计实施方案。"},{"i":58,"n":"第五十八条","txt":"审计实施方案的内容主要包括： （一）审计目标； （二）审计范围； （三）审计内容、重点及审计措施，包括审计事项和根据本准则第七十三条确定的审计应对措施； （四）审计工作要求，包括项目审计进度安排、审计组内部重要管理事项及职责分工等。 采取跟踪审计方式实施审计的，审计实施方案应当对整个跟踪审计工作作出统筹安排。 专项审计调查项目的审计实施方案应当列明专项审计调查的要求。"},{"i":59,"n":"第五十九条","txt":"审计组调查了解被审计单位及其相关情况，为作出下列职业判断提供基础： （一）确定职业判断适用的标准； （二）判断可能存在的问题； （三）判断问题的重要性； （四）确定审计应对措施。"},{"i":60,"n":"第六十条","txt":"审计人员可以从下列方面调查了解被审计单位及其相关情况： （一）单位性质、组织结构； （二）职责范围或者经营范围、业务活动及其目标； （三）相关法律法规、政策及其执行情况； （四）财政财务管理体制和业务管理体制； （五）适用的业绩指标体系以及业绩评价情况； （六）相关内部控制及其执行情况； （七）相关信息系统及其电子数据情况； （八）经济环境、行业状况及其他外部因素； （九）以往接受审计和监管及其整改情况； （十）需要了解的其他情况。"},{"i":61,"n":"第六十一条","txt":"审计人员可以从下列方面调查了解被审计单位相关内部控制及其执行情况： （一）控制环境，即管理模式、组织结构、责权配置、人力资源制度等； （二）风险评估，即被审计单位确定、分析与实现内部控制目标相关的风险，以及采取的应对措施； （三）控制活动，即根据风险评估结果采取的控制措施，包括不相容职务分离控制、授权审批控制、资产保护控制、预算控制、业绩分析和绩效考评控制等； （四）信息与沟通，即收集、处理、传递与内部控制相关的信息，并能有效沟通的情况； （五）对控制的监督，即对各项内部控制设计、职责及其履行情况的监督检查。"},{"i":62,"n":"第六十二条","txt":"审计人员可以从下列方面调查了解被审计单位信息系统控制情况： （一）一般控制，即保障信息系统正常运行的稳定性、有效性、安全性等方面的控制； （二）应用控制，即保障信息系统产生的数据的真实性、完整性、可靠性等方面的控制。"},{"i":63,"n":"第六十三条","txt":"审计人员可以采取下列方法调查了解被审计单位及其相关情况： （一）书面或者口头询问被审计单位内部和外部相关人员； （二）检查有关文件、报告、内部管理手册、信息系统的技术文档和操作手册； （三）观察有关业务活动及其场所、设施和有关内部控制的执行情况； （四）追踪有关业务的处理过程； （五）分析相关数据。"},{"i":64,"n":"第六十四条","txt":"审计人员根据审计目标和被审计单位的实际情况，运用职业判断确定调查了解的范围和程度。 对于定期审计项目，审计人员可以利用以往审计中获得的信息，重点调查了解已经发生变化的情况。"},{"i":65,"n":"第六十五条","txt":"审计人员在调查了解被审计单位及其相关情况的过程中，可以选择下列标准作为职业判断的依据： （一）法律、法规、规章和其他规范性文件； （二）国家有关方针和政策； （三）会计准则和会计制度； （四）国家和行业的技术标准； （五）预算、计划和合同； （六）被审计单位的管理制度和绩效目标； （七）被审计单位的历史数据和历史业绩； （八）公认的业务惯例或者良好实务； （九）专业机构或者专家的意见； （十）其他标准。 审计人员在审计实施过程中需要持续关注标准的适用性。"},{"i":66,"n":"第六十六条","txt":"职业判断所选择的标准应当具有客观性、适用性、相关性、公认性。 标准不一致时，审计人员应当采用权威的和公认程度高的标准。"},{"i":67,"n":"第六十七条","txt":"审计人员应当结合适用的标准，分析调查了解的被审计单位及其相关情况，判断被审计单位可能存在的问题。"},{"i":68,"n":"第六十八条","txt":"审计人员应当运用职业判断，根据可能存在问题的性质、数额及其发生的具体环境，判断其重要性。"},{"i":69,"n":"第六十九条","txt":"审计人员判断重要性时，可以关注下列因素： （一）是否属于涉嫌犯罪的问题； （二）是否属于法律法规和政策禁止的问题； （三）是否属于故意行为所产生的问题； （四）可能存在问题涉及的数量或者金额； （五）是否涉及政策、体制或者机制的严重缺陷； （六）是否属于信息系统设计缺陷； （七）政府行政首长和相关领导机关及公众的关注程度； （八）需要关注的其他因素。"},{"i":70,"n":"第七十条","txt":"审计人员实施审计时，应当根据重要性判断的结果，重点关注被审计单位可能存在的重要问题。"},{"i":71,"n":"第七十一条","txt":"需要对财务报表发表审计意见的，审计人员可以参照中国注册会计师执业准则的有关规定确定和运用重要性。"},{"i":72,"n":"第七十二条","txt":"审计组应当评估被审计单位存在重要问题的可能性，以确定审计事项和审计应对措施。"},{"i":73,"n":"第七十三条","txt":"审计组针对审计事项确定的审计应对措施包括： （一）评估对内部控制的依赖程度，确定是否及如何测试相关内部控制的有效性； （二）评估对信息系统的依赖程度，确定是否及如何检查相关信息系统的有效性、安全性； （三）确定主要审计步骤和方法； （四）确定审计时间； （五）确定执行的审计人员； （六）其他必要措施。"},{"i":74,"n":"第七十四条","txt":"审计组在分配审计资源时，应当为重要审计事项分派有经验的审计人员和安排充足的审计时间，并评估特定审计事项是否需要利用外部专家的工作。"},{"i":75,"n":"第七十五条","txt":"审计人员认为存在下列情形之一的，应当测试相关内部控制的有效性： （一）某项内部控制设计合理且预期运行有效，能够防止重要问题的发生； （二）仅实施实质性审查不足以为发现重要问题提供适当、充分的审计证据。 审计人员决定不依赖某项内部控制的，可以对审计事项直接进行实质性审查。 被审计单位规模较小、业务比较简单的，审计人员可以对审计事项直接进行实质性审查。"},{"i":76,"n":"第七十六条","txt":"审计人员认为存在下列情形之一的，应当检查相关信息系统的有效性、安全性： （一）仅审计电子数据不足以为发现重要问题提供适当、充分的审计证据； （二）电子数据中频繁出现某类差异。 审计人员在检查被审计单位相关信息系统时，可以利用被审计单位信息系统的现有功能或者采用其他计算机技术和工具，检查中应当避免对被审计单位相关信息系统及其电子数据造成不良影响。"},{"i":77,"n":"第七十七条","txt":"审计人员实施审计时，应当持续关注已作出的重要性判断和对存在重要问题可能性的评估是否恰当，及时作出修正，并调整审计应对措施。"},{"i":78,"n":"第七十八条","txt":"遇有下列情形之一的，审计组应当及时调整审计实施方案： （一）年度审计项目计划、审计工作方案发生变化的； （二）审计目标发生重大变化的； （三）重要审计事项发生变化的； （四）被审计单位及其相关情况发生重大变化的； （五）审计组人员及其分工发生重大变化的； （六）需要调整的其他情形。"},{"i":79,"n":"第七十九条","txt":"一般审计项目的审计实施方案应当经审计组组长审定，并及时报审计机关业务部门备案。 重要审计项目的审计实施方案应当报经审计机关负责人审定。"},{"i":80,"n":"第八十条","txt":"审计组调整审计实施方案中的下列事项，应当报经审计机关主要负责人批准： （一）审计目标； （二）审计组组长； （三）审计重点； （四）现场审计结束时间。"},{"i":81,"n":"第八十一条","txt":"编制和调整审计实施方案可以采取文字、表格或者两者相结合的形式。"},{"i":82,"n":"第八十二条","txt":"审计证据是指审计人员获取的能够为审计结论提供合理基础的全部事实，包括审计人员调查了解被审计单位及其相关情况和对确定的审计事项进行审查所获取的证据。"},{"i":83,"n":"第八十三条","txt":"审计人员应当依照法定权限和程序获取审计证据。"},{"i":84,"n":"第八十四条","txt":"审计人员获取的审计证据，应当具有适当性和充分性。 适当性是对审计证据质量的衡量，即审计证据在支持审计结论方面具有的相关性和可靠性。相关性是指审计证据与审计事项及其具体审计目标之间具有实质性联系。可靠性是指审计证据真实、可信。 充分性是对审计证据数量的衡量。审计人员在评估存在重要问题的可能性和审计证据质量的基础上，决定应当获取审计证据的数量。"},{"i":85,"n":"第八十五条","txt":"审计人员对审计证据的相关性分析时，应当关注下列方面： （一）一种取证方法获取的审计证据可能只与某些具体审计目标相关，而与其他具体审计目标无关； （二）针对一项具体审计目标可以从不同来源获取审计证据或者获取不同形式的审计证据。"},{"i":86,"n":"第八十六条","txt":"审计人员可以从下列方面分析审计证据的可靠性： （一）从被审计单位外部获取的审计证据比从内部获取的审计证据更可靠； （二）内部控制健全有效情况下形成的审计证据比内部控制缺失或者无效情况下形成的审计证据更可靠； （三）直接获取的审计证据比间接获取的审计证据更可靠； （四）从被审计单位财务会计资料中直接采集的审计证据比经被审计单位加工处理后提交的审计证据更可靠； （五）原件形式的审计证据比复制件形式的审计证据更可 靠。 不同来源和不同形式的审计证据存在不一致或者不能相互印证时，审计人员应当追加必要的审计措施，确定审计证据的可靠性。"},{"i":87,"n":"第八十七条","txt":"审计人员获取的电子审计证据包括与信息系统控制相关的配置参数、反映交易记录的电子数据等。 采集被审计单位电子数据作为审计证据的，审计人员应当记录电子数据的采集和处理过程。"},{"i":88,"n":"第八十八条","txt":"审计人员根据实际情况，可以在审计事项中选取全部项目或者部分特定项目进行审查，也可以进行审计抽样，以获取审计证据。"},{"i":89,"n":"第八十九条","txt":"存在下列情形之一的，审计人员可以对审计事项中的全部项目进行审查： （一）审计事项由少量大额项目构成的； （二）审计事项可能存在重要问题，而选取其中部分项目进行审查无法提供适当、充分的审计证据的； （三）对审计事项中的全部项目进行审查符合成本效益原则的。"},{"i":90,"n":"第九十条","txt":"审计人员可以在审计事项中选取下列特定项目进行审查： （一）大额或者重要项目； （二）数量或者金额符合设定标准的项目； （三）其他特定项目。 选取部分特定项目进行审查的结果，不能用于推断整个审计事项。"},{"i":91,"n":"第九十一条","txt":"在审计事项包含的项目数量较多，需要对审计事项某一方面的总体特征作出结论时，审计人员可以进行审计抽样。 审计人员进行审计抽样时，可以参照中国注册会计师执业准则的有关规定。"},{"i":92,"n":"第九十二条","txt":"审计人员可以采取下列方法向有关单位和个人获取审计证据： （一）检查，是指对纸质、电子或者其他介质形式存在的文件、资料进行审查，或者对有形资产进行审查； （二）观察，是指察看相关人员正在从事的活动或者执行的程序； （三）询问，是指以书面或者口头方式向有关人员了解关于审计事项的信息； （四）外部调查，是指向与审计事项有关的第三方进行调查； （五）重新计算，是指以手工方式或者使用信息技术对有关数据计算的正确性进行核对； （六）重新操作，是指对有关业务程序或者控制活动独立进行重新操作验证； （七）分析，是指研究财务数据之间、财务数据与非财务数据之间可能存在的合理关系，对相关信息作出评价，并关注异常波动和差异。 审计人员进行专项审计调查，可以使用上述方法及其以外的其他方法。"},{"i":93,"n":"第九十三条","txt":"审计人员应当依照法律法规规定，取得被审计单位负责人对本单位提供资料真实性和完整性的书面承诺。"},{"i":94,"n":"第九十四条","txt":"审计人员取得证明被审计单位存在违反国家规定的财政收支、财务收支行为以及其他重要审计事项的审计证据材料，应当由提供证据的有关人员、单位签名或者盖章；不能取得签名或者盖章不影响事实存在的，该审计证据仍然有效，但审计人员应当注明原因。 审计事项比较复杂或者取得的审计证据数量较大的，可以对审计证据进行汇总分析，编制审计取证单，由证据提供者签名或者盖章。"},{"i":95,"n":"第九十五条","txt":"被审计单位的相关资料、资产可能被转移、隐匿、篡改、毁弃并影响获取审计证据的，审计机关应当依照法律法规的规定采取相应的证据保全措施。"},{"i":96,"n":"第九十六条","txt":"审计机关执行审计业务过程中，因行使职权受到限制而无法获取适当、充分的审计证据，或者无法制止违法行为对国家利益的侵害时，根据需要，可以按照有关规定提请有权处理的机关或者相关单位予以协助和配合。"},{"i":97,"n":"第九十七条","txt":"审计人员需要利用所聘请外部人员的专业咨询和专业鉴定作为审计证据的，应当对下列方面作出判断： （一）依据的样本是否符合审计项目的具体情况； （二）使用的方法是否适当和合理； （三）专业咨询、专业鉴定是否与其他审计证据相符。"},{"i":98,"n":"第九十八条","txt":"审计人员需要使用有关监管机构、中介机构、内部审计机构等已经形成的工作结果作为审计证据的，应当对该工作结果的下列方面作出判断： （一）是否与审计目标相关； （二）是否可靠； （三）是否与其他审计证据相符。"},{"i":99,"n":"第九十九条","txt":"审计人员对于重要问题，可以围绕下列方面获取审计证据： （一）标准，即判断被审计单位是否存在问题的依据； （二）事实，即客观存在和发生的情况。事实与标准之间的差异构成审计发现的问题； （三）影响，即问题产生的后果； （四）原因，即问题产生的条件。"},{"i":100,"n":"第一百条","txt":"审计人员在审计实施过程中，应当持续评价审计证据的适当性和充分性。 已采取的审计措施难以获取适当、充分审计证据的，审计人员应当采取替代审计措施；仍无法获取审计证据的，由审计组报请审计机关采取其他必要的措施或者不作出审计结论。"},{"i":101,"n":"第一百零一条","txt":"审计人员应当真实、完整地记录实施审计的过程、得出的结论和与审计项目有关的重要管理事项，以实现下列目标： （一）支持审计人员编制审计实施方案和审计报告； （二）证明审计人员遵循相关法律法规和本准则； （三）便于对审计人员的工作实施指导、监督和检查。"},{"i":102,"n":"第一百零二条","txt":"审计人员作出的记录，应当使未参与该项业务的有经验的其他审计人员能够理解其执行的审计措施、获取的审计证据、作出的职业判断和得出的审计结论。"},{"i":103,"n":"第一百零三条","txt":"审计记录包括调查了解记录、审计工作底稿和重要管理事项记录。"},{"i":104,"n":"第一百零四条","txt":"审计组在编制审计实施方案前，应当对调查了解被审计单位及其相关情况作出记录。调查了解记录的内容主要包括： （一）对被审计单位及其相关情况的调查了解情况； （二）对被审计单位存在重要问题可能性的评估情况； （三）确定的审计事项及其审计应对措施。"},{"i":105,"n":"第一百零五条","txt":"审计工作底稿主要记录审计人员依据审计实施方案执行审计措施的活动。 审计人员对审计实施方案确定的每一审计事项，均应当编制审计工作底稿。一个审计事项可以根据需要编制多份审计工作底稿。"},{"i":106,"n":"第一百零六条","txt":"审计工作底稿的内容主要包括： （一）审计项目名称； （二）审计事项名称； （三）审计过程和结论； （四）审计人员姓名及审计工作底稿编制日期并签名； （五）审核人员姓名、审核意见及审核日期并签名； （六）索引号及页码； （七）附件数量。"},{"i":107,"n":"第一百零七条","txt":"审计工作底稿记录的审计过程和结论主要包括： （一）实施审计的主要步骤和方法； （二）取得的审计证据的名称和来源； （三）审计认定的事实摘要； （四）得出的审计结论及其相关标准。"},{"i":108,"n":"第一百零八条","txt":"审计证据材料应当作为调查了解记录和审计工作底稿的附件。一份审计证据材料对应多个审计记录时，审计人员可以将审计证据材料附在与其关系最密切的审计记录后面，并在其他审计记录中予以注明。"},{"i":109,"n":"第一百零九条","txt":"审计组起草审计报告前，审计组组长应当对审计工作底稿的下列事项进行审核： （一）具体审计目标是否实现； （二）审计措施是否有效执行； （三）事实是否清楚； （四）审计证据是否适当、充分； （五）得出的审计结论及其相关标准是否适当； （六）其他有关重要事项。"},{"i":110,"n":"第一百一十条","txt":"审计组组长审核审计工作底稿，应当根据不同情况分别提出下列意见： （一）予以认可； （二）责成采取进一步审计措施，获取适当、充分的审计证据； （三）纠正或者责成纠正不恰当的审计结论。"},{"i":111,"n":"第一百一十一条","txt":"重要管理事项记录应当记载与审计项目相关并对审计结论有重要影响的下列管理事项： （一）可能损害审计独立性的情形及采取的措施； （二）所聘请外部人员的相关情况； （三）被审计单位承诺情况； （四）征求被审计对象或者相关单位及人员意见的情况、被审计对象或者相关单位及人员反馈的意见及审计组的采纳情况； （五）审计组对审计发现的重大问题和审计报告讨论的过程及结论； （六）审计机关业务部门对审计报告、审计决定书等审计项目材料的复核情况和意见； （七）审理机构对审计项目的审理情况和意见； （八）审计机关对审计报告的审定过程和结论； （九）审计人员未能遵守本准则规定的约束性条款及其原 因； （十）因外部因素使审计任务无法完成的原因及影响； （十一）其他重要管理事项。 重要管理事项记录可以使用被审计单位承诺书、审计机关内部审批文稿、会议记录、会议纪要、审理意见书或者其他书面形式。"},{"i":112,"n":"第一百一十二条","txt":"审计人员执行审计业务时，应当保持职业谨慎，充分关注可能存在的重大违法行为。"},{"i":113,"n":"第一百一十三条","txt":"本准则所称重大违法行为是指被审计单位和相关人员违反法律法规、涉及金额比较大、造成国家重大经济损失或者对社会造成重大不良影响的行为。"},{"i":114,"n":"第一百一十四条","txt":"审计人员检查重大违法行为，应当评估被审计单位和相关人员实施重大违法行为的动机、性质、后果和违法构成。"},{"i":115,"n":"第一百一十五条","txt":"审计人员调查了解被审计单位及其相关情况时，可以重点了解可能与重大违法行为有关的下列事项： （一）被审计单位所在行业发生重大违法行为的状况； （二）有关的法律法规及其执行情况； （三）监管部门已经发现和了解的与被审计单位有关的重大违法行为的事实或者线索； （四）可能形成重大违法行为的动机和原因； （五）相关的内部控制及其执行情况； （六）其他情况。"},{"i":116,"n":"第一百一十六条","txt":"审计人员可以通过关注下列情况，判断可能存在的重大违法行为： （一）具体经济活动中存在的异常事项； （二）财务和非财务数据中反映出的异常变化； （三）有关部门提供的线索和群众举报； （四）公众、媒体的反映和报道； （五）其他情况。"},{"i":117,"n":"第一百一十七条","txt":"审计人员根据被审计单位实际情况、工作经验和审计发现的异常现象，判断可能存在重大违法行为的性质，并确定检查重点。 审计人员在检查重大违法行为时，应当关注重大违法行为的高发领域和环节。"},{"i":118,"n":"第一百一十八条","txt":"发现重大违法行为的线索，审计组或者审计机关可以采取下列应对措施： （一）增派具有相关经验和能力的人员； （二）避免让有关单位和人员事先知晓检查的时间、事项、范围和方式； （三）扩大检查范围，使其能够覆盖重大违法行为可能涉及的领域； （四）获取必要的外部证据； （五）依法采取保全措施； （六）提请有关机关予以协助和配合； （七）向政府和有关部门报告； （八）其他必要的应对措施。"},{"i":119,"n":"第一百一十九条","txt":"审计报告包括审计机关进行审计后出具的审计报告以及专项审计调查后出具的专项审计调查报告。"},{"i":120,"n":"第一百二十条","txt":"审计组实施审计或者专项审计调查后，应当向派出审计组的审计机关提交审计报告。审计机关审定审计组的审计报告后，应当出具审计机关的审计报告。遇有特殊情况，审计机关可以不向被调查单位出具专项审计调查报告。"},{"i":121,"n":"第一百二十一条","txt":"审计报告应当内容完整、事实清楚、结论正确、用词恰当、格式规范。"},{"i":122,"n":"第一百二十二条","txt":"审计机关的审计报告（审计组的审计报告）包括下列基本要素： （一）标题； （二）文号（审计组的审计报告不含此项）； （三）被审计单位名称； （四）审计项目名称； （五）内容； （六）审计机关名称（审计组名称及审计组组长签名）； （七）签发日期（审计组向审计机关提交报告的日期）。 经济责任审计报告还包括被审计人员姓名及所担任职务。"},{"i":123,"n":"第一百二十三条","txt":"审计报告的内容主要包括： （一）审计依据，即实施审计所依据的法律法规规定； （二）实施审计的基本情况，一般包括审计范围、内容、方式和实施的起止时间； （三）被审计单位基本情况； （四）审计评价意见，即根据不同的审计目标，以适当、充分的审计证据为基础发表的评价意见； （五）以往审计决定执行情况和审计建议采纳情况； （六）审计发现的被审计单位违反国家规定的财政收支、财务收支行为和其他重要问题的事实、定性、处理处罚意见以及依据的法律法规和标准； （七）审计发现的移送处理事项的事实和移送处理意见，但是涉嫌犯罪等不宜让被审计单位知悉的事项除外； （八）针对审计发现的问题，根据需要提出的改进建议。 审计期间被审计单位对审计发现的问题已经整改的，审计报告还应当包括有关整改情况。 经济责任审计报告还应当包括被审计人员履行经济责任的基本情况，以及被审计人员对审计发现问题承担的责任。 核查社会审计机构相关"},{"i":124,"n":"第一百二十四条","txt":"采取跟踪审计方式实施审计的，审计组在跟踪审计过程中发现的问题，应当以审计机关的名义及时向被审计单位通报，并要求其整改。 跟踪审计实施工作全部结束后，应当以审计机关的名义出具审计报告。审计报告应当反映审计发现但尚未整改的问题，以及已经整改的重要问题及其整改情况。"},{"i":125,"n":"第一百二十五条","txt":"专项审计调查报告除符合审计报告的要素和内容要求外，还应当根据专项审计调查目标重点分析宏观性、普遍性、政策性或者体制、机制问题并提出改进建议。"},{"i":126,"n":"第一百二十六条","txt":"对审计或者专项审计调查中发现被审计单位违反国家规定的财政收支、财务收支行为，依法应当由审计机关在法定职权范围内作出处理处罚决定的，审计机关应当出具审计决定书。"},{"i":127,"n":"第一百二十七条","txt":"审计决定书的内容主要包括： （一）审计的依据、内容和时间； （二）违反国家规定的财政收支、财务收支行为的事实、定性、处理处罚决定以及法律法规依据； （三）处理处罚决定执行的期限和被审计单位书面报告审计决定执行结果等要求； （四）依法提请政府裁决或者申请行政复议、提起行政诉讼的途径和期限。"},{"i":128,"n":"第一百二十八条","txt":"审计或者专项审计调查发现的依法需要移送其他有关主管机关或者单位纠正、处理处罚或者追究有关人员责任的事项，审计机关应当出具审计移送处理书。"},{"i":129,"n":"第一百二十九条","txt":"审计移送处理书的内容主要包括： （一）审计的时间和内容； （二）依法需要移送有关主管机关或者单位纠正、处理处罚或者追究有关人员责任事项的事实、定性及其依据和审计机关的意见； （三）移送的依据和移送处理说明，包括将处理结果书面告知审计机关的说明； （四）所附的审计证据材料。"},{"i":130,"n":"第一百三十条","txt":"出具对国际组织、外国政府及其机构援助、贷款项目的审计报告，按照审计机关的相关规定执行。"},{"i":131,"n":"第一百三十一条","txt":"审计组在起草审计报告前，应当讨论确定下列事项： （一）评价审计目标的实现情况； （二）审计实施方案确定的审计事项完成情况； （三）评价审计证据的适当性和充分性； （四）提出审计评价意见； （五）评估审计发现问题的重要性； （六）提出对审计发现问题的处理处罚意见； （七）其他有关事项。 审计组应当对讨论前款事项的情况及其结果作出记录。"},{"i":132,"n":"第一百三十二条","txt":"审计组组长应当确认审计工作底稿和审计证据已经审核，并从总体上评价审计证据的适当性和充分性。"},{"i":133,"n":"第一百三十三条","txt":"审计组根据不同的审计目标，以审计认定的事实为基础，在防范审计风险的情况下，按照重要性原则，从真实性、合法性、效益性方面提出审计评价意见。 审计组应当只对所审计的事项发表审计评价意见。对审计过程中未涉及、审计证据不适当或者不充分、评价依据或者标准不明确以及超越审计职责范围的事项，不得发表审计评价意见。"},{"i":134,"n":"第一百三十四条","txt":"审计组应当根据审计发现问题的性质、数额及其发生的原因和审计报告的使用对象，评估审计发现问题的重要性，如实在审计报告中予以反映。"},{"i":135,"n":"第一百三十五条","txt":"审计组对审计发现的问题提出处理处罚意见时，应当关注下列因素： （一）法律法规的规定； （二）审计职权范围：属于审计职权范围的，直接提出处理处罚意见，不属于审计职权范围的，提出移送处理意见； （三）问题的性质、金额、情节、原因和后果； （四）对同类问题处理处罚的一致性； （五）需要关注的其他因素。 审计发现被审计单位信息系统存在重大漏洞或者不符合国家规定的，应当责成被审计单位在规定期限内整改。"},{"i":136,"n":"第一百三十六条","txt":"审计组应当针对经济责任审计发现的问题，根据被审计人员履行职责情况，界定其应当承担的责任。"},{"i":137,"n":"第一百三十七条","txt":"审计组实施审计或者专项审计调查后，应当提出审计报告，按照审计机关规定的程序审批后，以审计机关的名义征求被审计单位、被调查单位和拟处罚的有关责任人员的意见。 经济责任审计报告还应当征求被审计人员的意见；必要时，征求有关干部监督管理部门的意见。 审计报告中涉及的重大经济案件调查等特殊事项，经审计机关主要负责人批准，可以不征求被审计单位或者被审计人员的意见。"},{"i":138,"n":"第一百三十八条","txt":"被审计单位、被调查单位、被审计人员或者有关责任人员对征求意见的审计报告有异议的，审计组应当进一步核实，并根据核实情况对审计报告作出必要的修改。 审计组应当对采纳被审计单位、被调查单位、被审计人员、有关责任人员意见的情况和原因，或者上述单位或人员未在法定时间内提出书面意见的情况作出书面说明。"},{"i":139,"n":"第一百三十九条","txt":"对被审计单位或者被调查单位违反国家规定的财政收支、财务收支行为，依法应当由审计机关进行处理处罚的，审计组应当起草审计决定书。 对依法应当由其他有关部门纠正、处理处罚或者追究有关责任人员责任的事项，审计组应当起草审计移送处理书。"},{"i":140,"n":"第一百四十条","txt":"审计组应当将下列材料报送审计机关业务部门复核： （一）审计报告； （二）审计决定书； （三）被审计单位、被调查单位、被审计人员或者有关责任人员对审计报告的书面意见及审计组采纳情况的书面说明； （四）审计实施方案； （五）调查了解记录、审计工作底稿、重要管理事项记录、审计证据材料； （六）其他有关材料。"},{"i":141,"n":"第一百四十一条","txt":"审计机关业务部门应当对下列事项进行复核，并提出书面复核意见： （一）审计目标是否实现； （二）审计实施方案确定的审计事项是否完成； （三）审计发现的重要问题是否在审计报告中反映； （四）事实是否清楚、数据是否正确； （五）审计证据是否适当、充分； （六）审计评价、定性、处理处罚和移送处理意见是否恰当，适用法律法规和标准是否适当； （七）被审计单位、被调查单位、被审计人员或者有关责任人员提出的合理意见是否采纳； （八）需要复核的其他事项。"},{"i":142,"n":"第一百四十二条","txt":"审计机关业务部门应当将复核修改后的审计报告、审计决定书等审计项目材料连同书面复核意见，报送审理机构审理。"},{"i":143,"n":"第一百四十三条","txt":"审理机构以审计实施方案为基础，重点关注审计实施的过程及结果，主要审理下列内容： （一）审计实施方案确定的审计事项是否完成； （二）审计发现的重要问题是否在审计报告中反映； （三）主要事实是否清楚、相关证据是否适当、充分； （四）适用法律法规和标准是否适当； （五）评价、定性、处理处罚意见是否恰当； （六）审计程序是否符合规定。"},{"i":144,"n":"第一百四十四条","txt":"审理机构审理时，应当就有关事项与审计组及相关业务部门进行沟通。 必要时，审理机构可以参加审计组与被审计单位交换意见的会议，或者向被审计单位和有关人员了解相关情况。"},{"i":145,"n":"第一百四十五条","txt":"审理机构审理后，可以根据情况采取下列措施： （一）要求审计组补充重要审计证据； （二）对审计报告、审计决定书进行修改。 审理过程中遇有复杂问题的，经审计机关负责人同意后，审理机构可以组织专家进行论证。 审理机构审理后，应当出具审理意见书。"},{"i":146,"n":"第一百四十六条","txt":"审理机构将审理后的审计报告、审计决定书连同审理意见书报送审计机关负责人。"},{"i":147,"n":"第一百四十七条","txt":"审计报告、审计决定书原则上应当由审计机关审计业务会议审定；特殊情况下，经审计机关主要负责人授权，可以由审计机关其他负责人审定。"},{"i":148,"n":"第一百四十八条","txt":"审计决定书经审定，处罚的事实、理由、依据、决定与审计组征求意见的审计报告不一致并且加重处罚的，审计机关应当依照有关法律法规的规定及时告知被审计单位、被调查单位和有关责任人员，并听取其陈述和申辩。"},{"i":149,"n":"第一百四十九条","txt":"对于拟作出罚款的处罚决定，符合法律法规规定的听证条件的，审计机关应当依照有关法律法规的规定履行听证程序。"},{"i":150,"n":"第一百五十条","txt":"审计报告、审计决定书经审计机关负责人签发后，按照下列要求办理： （一）审计报告送达被审计单位、被调查单位； （二）经济责任审计报告送达被审计单位和被审计人员； （三）审计决定书送达被审计单位、被调查单位、被处罚的有关责任人员。"},{"i":151,"n":"第一百五十一条","txt":"审计机关在审计中发现的下列事项，可以采用专题报告、审计信息等方式向本级政府、上一级审计机关报告： （一）涉嫌重大违法犯罪的问题； （二）与国家财政收支、财务收支有关政策及其执行中存在的重大问题； （三）关系国家经济安全的重大问题； （四）关系国家信息安全的重大问题； （五）影响人民群众经济利益的重大问题； （六）其他重大事项。"},{"i":152,"n":"第一百五十二条","txt":"专题报告应当主题突出、事实清楚、定性准确、建议适当。 审计信息应当事实清楚、定性准确、内容精炼、格式规范、反映及时。"},{"i":153,"n":"第一百五十三条","txt":"审计机关统一组织审计项目的，可以根据需要汇总审计情况和结果，编制审计综合报告。必要时，审计综合报告应当征求有关主管机关的意见。 审计综合报告按照审计机关规定的程序审定后，向本级政府和上一级审计机关报送，或者向有关部门通报。"},{"i":154,"n":"第一百五十四条","txt":"审计机关实施经济责任审计项目后，应当按照相关规定，向本级政府行政首长和有关干部监督管理部门报告经济责任审计结果。"},{"i":155,"n":"第一百五十五条","txt":"审计机关依照法律法规的规定，每年汇总对本级预算执行情况和其他财政收支情况的审计报告，形成审计结果报告，报送本级政府和上一级审计机关。"},{"i":156,"n":"第一百五十六条","txt":"审计机关依照法律法规的规定，代本级政府起草本级预算执行情况和其他财政收支情况的审计工作报告（稿），经本级政府行政首长审定后，受本级政府委托向本级人民代表大会常务委员会报告。"},{"i":157,"n":"第一百五十七条","txt":"审计机关依法实行公告制度。审计机关的审计结果、审计调查结果依法向社会公布。"},{"i":158,"n":"第一百五十八条","txt":"审计机关公布的审计和审计调查结果主要包括下列信息： （一）被审计（调查）单位基本情况； （二）审计（调查）评价意见； （三）审计（调查）发现的主要问题； （四）处理处罚决定及审计（调查）建议； （五）被审计（调查）单位的整改情况。"},{"i":159,"n":"第一百五十九条","txt":"在公布审计和审计调查结果时，审计机关不得公布下列信息： （一）涉及国家秘密、商业秘密的信息； （二）正在调查、处理过程中的事项； （三）依照法律法规的规定不予公开的其他信息。 涉及商业秘密的信息，经权利人同意或者审计机关认为不公布可能对公共利益造成重大影响的，可以予以公布。 审计机关公布审计和审计调查结果应当客观公正。"},{"i":160,"n":"第一百六十条","txt":"审计机关公布审计和审计调查结果，应当指定专门机构统一办理，履行规定的保密审查和审核手续，报经审计机关主要负责人批准。 审计机关内设机构、派出机构和个人，未经授权不得向社会公布审计和审计调查结果。"},{"i":161,"n":"第一百六十一条","txt":"审计机关统一组织不同级次审计机关参加的审计项目，其审计和审计调查结果原则上由负责该项目组织工作的审计机关统一对外公布。"},{"i":162,"n":"第一百六十二条","txt":"审计机关公布审计和审计调查结果按照国家有关规定需要报批的，未经批准不得公布。"},{"i":163,"n":"第一百六十三条","txt":"审计机关应当建立审计整改检查机制，督促被审计单位和其他有关单位根据审计结果进行整改。"},{"i":164,"n":"第一百六十四条","txt":"审计机关主要检查或者了解下列事项： （一）执行审计机关作出的处理处罚决定情况； （二）对审计机关要求自行纠正事项采取措施的情况； （三）根据审计机关的审计建议采取措施的情况； （四）对审计机关移送处理事项采取措施的情况。"},{"i":165,"n":"第一百六十五条","txt":"审计组在审计实施过程中，应当及时督促被审计单位整改审计发现的问题。 审计机关在出具审计报告、作出审计决定后，应当在规定的时间内检查或者了解被审计单位和其他有关单位的整改情况。"},{"i":166,"n":"第一百六十六条","txt":"审计机关可以采取下列方式检查或者了解被审计单位和其他有关单位的整改情况： （一）实地检查或者了解； （二）取得并审阅相关书面材料； （三）其他方式。 对于定期审计项目，审计机关可以结合下一次审计，检查或者了解被审计单位的整改情况。 检查或者了解被审计单位和其他有关单位的整改情况应当取得相关证明材料。"},{"i":167,"n":"第一百六十七条","txt":"审计机关指定的部门负责检查或者了解被审计单位和其他有关单位整改情况，并向审计机关提出检查报告。"},{"i":168,"n":"第一百六十八条","txt":"检查报告的内容主要包括： （一）检查工作开展情况，主要包括检查时间、范围、对象、和方式等； （二）被审计单位和其他有关单位的整改情况； （三）没有整改或者没有完全整改事项的原因和建议。"},{"i":169,"n":"第一百六十九条","txt":"审计机关对被审计单位没有整改或者没有完全整改的事项，依法采取必要措施。"},{"i":170,"n":"第一百七十条","txt":"审计机关对审计决定书中存在的重要错误事项，应当予以纠正。"},{"i":171,"n":"第一百七十一条","txt":"审计机关汇总审计整改情况，向本级政府报送关于审计工作报告中指出问题的整改情况的报告。"},{"i":172,"n":"第一百七十二条","txt":"审计机关应当建立审计质量控制制度，以保证实现下列目标： （一）遵守法律法规和本准则； （二）作出恰当的审计结论； （三）依法进行处理处罚。"},{"i":173,"n":"第一百七十三条","txt":"审计机关应当针对下列要素建立审计质量控制制度： （一）审计质量责任； （二）审计职业道德； （三）审计人力资源； （四）审计业务执行； （五）审计质量监控。 对前款第二、三、四项应当按照本准则第二至五章的有关要求建立审计质量控制制度。"},{"i":174,"n":"第一百七十四条","txt":"审计机关实行审计组成员、审计组主审、审计组组长、审计机关业务部门、审理机构、总审计师和审计机关负责人对审计业务的分级质量控制。"},{"i":175,"n":"第一百七十五条","txt":"审计组成员的工作职责包括： （一）遵守本准则，保持审计独立性； （二）按照分工完成审计任务，获取审计证据； （三）如实记录实施的审计工作并报告工作结果； （四）完成分配的其他工作。"},{"i":176,"n":"第一百七十六条","txt":"审计组成员应当对下列事项承担责任： （一）未按审计实施方案实施审计导致重大问题未被发现的； （二）未按照本准则的要求获取审计证据导致审计证据不适当、不充分的； （三）审计记录不真实、不完整的； （四）对发现的重要问题隐瞒不报或者不如实报告的。"},{"i":177,"n":"第一百七十七条","txt":"审计组组长的工作职责包括： （一）编制或者审定审计实施方案； （二）组织实施审计工作； （三）督导审计组成员的工作； （四）审核审计工作底稿和审计证据； （五）组织编制并审核审计组起草的审计报告、审计决定书、审计移送处理书、专题报告、审计信息； （六）配置和管理审计组的资源； （七）审计机关规定的其他职责。"},{"i":178,"n":"第一百七十八条","txt":"审计组组长应当从下列方面督导审计组成员的工作： （一）将具体审计事项和审计措施等信息告知审计组成员，并与其讨论； （二）检查审计组成员的工作进展，评估审计组成员的工作质量，并解决工作中存在的问题； （三）给予审计组成员必要的培训和指导。"},{"i":179,"n":"第一百七十九条","txt":"审计组组长应当对审计项目的总体质量负责，并对下列事项承担责任： （一）审计实施方案编制或者组织实施不当，造成审计目标未实现或者重要问题未被发现的； （二）审核未发现或者未纠正审计证据不适当、不充分问题的； （三）审核未发现或者未纠正审计工作底稿不真实、不完整问题的； （四）得出的审计结论不正确的； （五）审计组起草的审计文书和审计信息反映的问题严重失实的； （六）提出的审计处理处罚意见或者移送处理意见不正确的； （七）对审计组发现的重要问题隐瞒不报或者不如实报告的； （八）违反法定审计程序的。"},{"i":180,"n":"第一百八十条","txt":"根据工作需要，审计组可以设立主审。主审根据审计分工和审计组组长的委托，主要履行下列职责： （一）起草审计实施方案、审计文书和审计信息； （二）对主要审计事项进行审计查证； （三）协助组织实施审计； （四）督导审计组成员的工作； （五）审核审计工作底稿和审计证据； （六）组织审计项目归档工作； （七）完成审计组组长委托的其他工作。"},{"i":181,"n":"第一百八十一条","txt":"审计组组长将其工作职责委托给主审或者审计组其他成员的，仍应当对委托事项承担责任。受委托的成员在受托范围内承担相应责任。"},{"i":182,"n":"第一百八十二条","txt":"审计机关业务部门的工作职责包括： （一）提出审计组组长人选； （二）确定聘请外部人员事宜； （三）指导、监督审计组的审计工作； （四）复核审计报告、审计决定书等审计项目材料； （五）审计机关规定的其他职责。 业务部门统一组织审计项目的，应当承担编制审计工作方案，组织、协调审计实施和汇总审计结果的职责。"},{"i":183,"n":"第一百八十三条","txt":"审计机关业务部门应当及时发现和纠正审计组工作中存在的重要问题，并对下列事项承担责任： （一）对审计组请示的问题未及时采取适当措施导致严重后果的； （二）复核未发现审计报告、审计决定书等审计项目材料中存在的重要问题的； （三）复核意见不正确的； （四）要求审计组不在审计文书和审计信息中反映重要问题的。 业务部门对统一组织审计项目的汇总审计结果出现重大错误、造成严重不良影响的事项承担责任。"},{"i":184,"n":"第一百八十四条","txt":"审计机关审理机构的工作职责包括： （一）审查修改审计报告、审计决定书； （二）提出审理意见； （三）审计机关规定的其他职责。"},{"i":185,"n":"第一百八十五条","txt":"审计机关审理机构对下列事项承担责任： （一）审理意见不正确的； （二）对审计报告、审计决定书作出的修改不正确的； （三）审理时应当发现而未发现重要问题的。"},{"i":186,"n":"第一百八十六条","txt":"审计机关负责人的工作职责包括： （一）审定审计项目目标、范围和审计资源的配置； （二）指导和监督检查审计工作； （三）审定审计文书和审计信息； （四）审计管理中的其他重要事项。 审计机关负责人对审计项目实施结果承担最终责任。"},{"i":187,"n":"第一百八十七条","txt":"审计机关对审计人员违反法律法规和本准则的行为，应当按照相关规定追究其责任。"},{"i":188,"n":"第一百八十八条","txt":"审计机关应当按照国家有关规定，建立健全审计项目档案管理制度，明确审计项目归档要求、保存期限、保存措施、档案利用审批程序等。"},{"i":189,"n":"第一百八十九条","txt":"审计项目归档工作实行审计组组长负责制，审计组组长应当确定立卷责任人。 立卷责任人应当收集审计项目的文件材料，并在审计项目终结后及时立卷归档，由审计组组长审查验收。"},{"i":190,"n":"第一百九十条","txt":"审计机关实行审计业务质量检查制度，对其业务部门、派出机构和下级审计机关的审计业务质量进行检查。"},{"i":191,"n":"第一百九十一条","txt":"审计机关可以通过查阅有关文件和审计档案、询问相关人员等方式、方法，检查下列事项： （一）建立和执行审计质量控制制度的情况； （二）审计工作中遵守法律法规和本准则的情况； （三）与审计业务质量有关的其他事项。 审计业务质量检查应当重点关注审计结论的恰当性、审计处理处罚意见的合法性和适当性。"},{"i":192,"n":"第一百九十二条","txt":"审计机关开展审计业务质量检查，应当向被检查单位通报检查结果。"},{"i":193,"n":"第一百九十三条","txt":"审计机关在审计业务质量检查中，发现被检查的派出机构或者下级审计机关应当作出审计决定而未作出的，可以依法直接或者责成其在规定期限内作出审计决定；发现其作出的审计决定违反国家有关规定的，可以依法直接或者责成其在规定期限内变更、撤销审计决定。"},{"i":194,"n":"第一百九十四条","txt":"审计机关应当对其业务部门、派出机构实行审计业务年度考核制度，考核审计质量控制目标的实现情况。"},{"i":195,"n":"第一百九十五条","txt":"审计机关可以定期组织优秀审计项目评选，对被评为优秀审计项目的予以表彰。"},{"i":196,"n":"第一百九十六条","txt":"审计机关应当对审计质量控制制度及其执行情况进行持续评估，及时发现审计质量控制制度及其执行中存在的问题，并采取措施加以纠正或者改进。 审计机关可以结合日常管理工作或者通过开展审计业务质量检查、考核和优秀审计项目评选等方式，对审计质量控制制度及其执行情况进行持续评估。"},{"i":197,"n":"第一百九十七条","txt":"审计机关和审计人员开展下列工作，不适用本准则的规定： （一）配合有关部门查处案件； （二）与有关部门共同办理检查事项； （三）接受交办或者接受委托办理不属于法定审计职责范围的事项。"},{"i":198,"n":"第一百九十八条","txt":"地方审计机关可以根据本地实际情况，在遵循本准则规定的基础上制定实施细则。"},{"i":199,"n":"第一百九十九条","txt":"本准则由审计署负责解释。"},{"i":200,"n":"第二百条","txt":"本准则自2011年1月1日起施行。附件所列的审计署以前发布的审计准则和规定同时废止。 附件：废止的审计准则和规定目录 附件 废止的审计准则和规定目录 1．中华人民共和国国家审计基本准则（2000年审计署第1号令） 2．审计机关审计处理处罚的规定（2000年审计署第1号令） 3．审计机关审计方案准则（2000年审计署第2号令） 4．审计机关审计证据准则（2000年审计署第2号令） 5．审计机关审计工作底稿准则（试行）（2000年审计署第2号令） 6．审计机关审计报告编审准则（2000年审计署第2号令） 7．审计机关审计复核准则（2000年审计署第2号令） 8．审计机关专项审计调查准则（2001年审计署第3号令） 9．审计机关公布审计结果准则（2001年审计署第3号令） 10．审计机关审计人员职业道德准则（2001年审计署第3号令） 11．审计机关国家建设项目审计准则（2001年审计署第3"}],"jingneiwaiguorenzongjiaohuodongguanliguidingshishi875fb2":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国境内外国人宗教活动管理规定》，制定本实施细则。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内外国人（以下简称“境内外国人”）是指依照《中华人民共和国国籍法》的规定，在中国境内不具有中国国籍的人，包括在华常住人员和短期来华人员。"},{"i":3,"n":"第三条","txt":"境内外国人宗教活动是指外国人在中国境内按照各自的宗教信仰习惯举行和参与的各种宗教仪式，与中国宗教社会团体、宗教活动场所和宗教教职人员所发生的宗教事务方面的联系，及其有关的各种活动。"},{"i":4,"n":"第四条","txt":"中华人民共和国尊重在中国境内的外国人的宗教信仰自由，依法保护和管理境内外国人的宗教活动。 中华人民共和国依法保护境内外国人在宗教方面同中国宗教界进行的友好往来和文化学术交流活动。"},{"i":5,"n":"第五条","txt":"外国人在中国境内可以根据自己的宗教信仰在依法登记的寺院、宫观、清真寺、教堂参加宗教活动。"},{"i":6,"n":"第六条","txt":"以宗教教职人员身份来访的外国人，经省、自治区、直辖市以上宗教社会团体邀请，可以在依法登记的宗教活动场所讲经、讲道。 以其他身份入境的外国宗教教职人员，经省、自治区、直辖市以上宗教社会团体邀请，并经省级以上人民政府宗教事务部门同意，可以在依法登记的宗教活动场所讲经、讲道。 应邀在依法登记的宗教活动场所讲经、讲道的外国宗教教职人员，应该遵守该场所的管理规章，尊重该场所人员的信仰习惯。"},{"i":7,"n":"第七条","txt":"境内外国人集体进行宗教活动要在由县级以上人民政府宗教事务部门认可的经依法登记的寺院、宫观、清真寺、教堂，或在由省、自治区、直辖市人民政府宗教事务部门指定的临时地点举行。 境内外国人在临时地点集体进行宗教活动时，应由县级以上人民政府宗教事务部门负责管理。"},{"i":8,"n":"第八条","txt":"外国人同中国宗教界的友好往来和文化学术交流活动，应通过省、自治区、直辖市以上宗教社会团体进行。"},{"i":9,"n":"第九条","txt":"凡在中国境内没有相应的合法的中国宗教组织的外国宗教组织及其成员，以宗教组织或宗教教职人员身份与中国政府有关部门或宗教界进行交往活动的，须经省级政府宗教事务部门同意后，报国家宗教事务局批准。"},{"i":10,"n":"第十条","txt":"经中国的宗教社会团体同意，境内外国人可以邀请中国宗教教职人员按各教习惯为其举行洗礼、婚礼、葬礼和道场、法会等宗教仪式。其中，举行婚礼的外国人必须是已经依法缔结婚姻关系的男女双方。 中国宗教教职人员是指由依法登记的宗教社会团体认定、备案的各种宗教教职人员。"},{"i":11,"n":"第十一条","txt":"经有关全国性宗教社会团体或省、自治区、直辖市有关宗教社会团体同意，并经当地省级以上人民政府宗教事务部门批准认可，外国人可以根据有关宗教文化学术交流的项目或协议，携带用于宗教文化学术交流的宗教用品入境。 符合上款规定和海关有关规定的宗教用品入境，海关凭省、自治区、直辖市人民政府宗教事务部门或国家宗教事务局的证明予以放行。"},{"i":12,"n":"第十二条","txt":"下列宗教印刷品、宗教音像制品和其他宗教用品不得进境： (一)超出个人自用合理数量，且不属于第十一条规定范围的； （二）有危害中国国家安全和社会公共利益内容的。 发现有违反上款规定的宗教印刷品、宗教音像制品和其他宗教用品，由海关依法进行处理。 违反第一款规定已经携带入境或通过其他手段运入境内的宗教印刷品、宗教音像制品和其他宗教用品，一经发现，由县级以上人民政府宗教事务部门或其他有关部门依法进行处理。"},{"i":13,"n":"第十三条","txt":"外国组织或个人向中国提供的以培养宗教教职人员为目的的出国留学人员名额或资金，由中国全国性宗教社会团体根据需要接受并统筹选派出国留学人员。 外国组织或个人不得在中国境内擅自招收以培养宗教教职人员为目的的出国留学人员。"},{"i":14,"n":"第十四条","txt":"外国人到中国宗教院校留学，须符合《高等学校接受外国留学生管理规定》的有关规定，并经全国性宗教社会团体同意。"},{"i":15,"n":"第十五条","txt":"外国人到中国宗教院校讲学，须根据《宗教院校聘用外籍专业人员办法》的规定办理。"},{"i":16,"n":"第十六条","txt":"外国人在中国境内进行宗教活动，应当遵守中国的法律、法规。 外国人不得干涉中国宗教社会团体、宗教活动场所的设立和变更，不得干涉中国宗教社会团体对宗教教职人员的选任和变更，不得干涉和支配中国宗教社会团体的其他内部事务。 外国人在中国境内不得以任何名义或形式成立宗教组织、设立宗教办事机构、设立宗教活动场所或者开办宗教院校、举办宗教培训班。"},{"i":17,"n":"第十七条","txt":"外国人不得在中国境内进行下列传教活动： （一）在中国公民中委任宗教教职人员； （二）在中国公民中发展宗教教徒； （三）擅自在宗教活动场所讲经、讲道； （四）未经批准在依法登记的宗教活动场所以外的处所讲经、讲道，进行宗教聚会活动； （五）在宗教活动临时地点举行有中国公民参加的宗教活动，被邀请主持宗教活动的中国宗教教职人员除外； （六）制作或销售宗教书刊、宗教音像制品、宗教电子出版物等宗教用品； （七）散发宗教宣传品； （八）其他形式的传教活动。"},{"i":18,"n":"第十八条","txt":"国际性宗教组织、机构及其成员与中国宗教社会团体、宗教活动场所和宗教教职人员发生宗教事务方面的联系，及其有关活动，须事先向省级以上人民政府宗教事务部门提出申请，经同意后方可进行。"},{"i":19,"n":"第十九条","txt":"境内外国人违反本细则进行宗教活动的，由县级以上人民政府宗教事务部门和其他有关部门依法予以制止。 境内外国人违反本细则进行宗教活动，构成违反《中华人民共和国外国人入境出境管理法》、《中华人民共和国治安管理处罚条例》等法律法规的，由公安机关依法予以处理；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"外国组织在中华人民共和国境内的宗教活动适用本细则。"},{"i":21,"n":"第二十一条","txt":"本细则由国家宗教事务局负责解释。"},{"i":22,"n":"第二十二条","txt":"本细则自发布之日起施行。"}],"zhiwuxinpinzhongbaohuminglu-6":[],"yuyexingzhengzhifachuanboguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强渔业行政执法船舶管理，根据《中华人民共和国渔业法》等法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称渔业行政执法船舶是指各级渔业行政主管部门执行渔业行政执法任务的专用公务船、艇，以下称为渔政船。"},{"i":3,"n":"第三条","txt":"渔政船实行建造审批，注册登记，统一编号，统一规范。"},{"i":4,"n":"第四条","txt":"各级渔业行政主管部门依照本办法的规定对所属渔政船进行管理。"},{"i":5,"n":"第五条","txt":"凡新建、改造、购置和报废渔政船的，必须填写《中华人民共和国渔政船新建、改造、购置、报废申请表》（格式见附件1），经批准后方可进行。未经批准，不得新建、改造、购置和报废渔政船。 农业部直属渔政渔港监督管理机构和省级渔业行政主管部门需新建、改造、购置和报废渔政船的，报（沿海省级渔政船经所在海区局审核后）中华人民共和国渔政渔港监督管理局审批。 省级以下各级渔业行政主管部门需新建、改造、购置和报废渔政船的，由各省（区、市）渔业行政主管部门审批，报中华人民共和国渔政渔港监督管理局（海洋渔政船同时报所在海区渔政渔港监督管理局）备案。 渔政船的设计、建造规范和安装的设备必须符合国家有关规定。"},{"i":6,"n":"第六条","txt":"所有渔政船必须向中华人民共和国渔政渔港监督管理局申请注册登记，经核准后，方可执行渔业行政执法任务。 海区渔政渔港监督管理局和各级渔业行政主管部门根据本办法第九条的编号规则，对所属渔政船编写船名号，并填写《中华人民共和国渔政船注册登记申请表》（格式见附件2），向中华人民共和国渔政渔港监督管理局申请注册登记。 中华人民共和国渔政渔港监督管理局对所有核准注册登记的渔政船，采用合适的方式向社会公布。"},{"i":7,"n":"第七条","txt":"中华人民共和国渔政渔港监督管理局对服役的渔政船每三年重新注册一次。"},{"i":8,"n":"第八条","txt":"渔政船实行统一外观颜色和标志。渔政船船体外部水线以上部分为白色，船首两侧用黑色宋体汉字标写船名号。有条件的渔政船应在驾驶室外两侧上方用红色宋体汉字标写船名号，夜间应有灯光照明或设夜间显示灯箱。烟囱两侧或驾驶楼两侧应刷制中国渔政徽标。"},{"i":9,"n":"第九条","txt":"渔政船实行全国统一编号。经中华人民共和国渔政渔港监督管理局注册登记的海区渔政船的编号为\"中国渔政×××\"。编号中的第一位数字为海区渔政渔港监督管理局的代码（附件3），第二、三位数字为所属渔政船序号。 经中华人民共和国渔政渔港监督管理局注册登记的省级以下（含省级）渔业行政主管部门所属渔政船的编号为\"中国渔政×××××\"，编号中的第一、二位数字为省级渔业行政主管部门的代码（附件3），第三、四、五位数字为各级渔业行政主管部门所属渔政船的序号。省以下各级渔业行政主管部门所属渔政船的序号排列，由各省自行确定，报中华人民共和国渔政渔港监督管理局备案。 单独执行渔业行政执法任务的快艇，也按上述规则编号。 渔政船备有快艇的，快艇名号为母船名号之后加\"－×\"，该位数代表快艇序号，由主管该渔政船的渔业行政主管部门编定。"},{"i":10,"n":"第十条","txt":"渔政船的外观颜色、标志和\"中国渔政\"的名称，未经中华人民共和国渔政渔港监督管理局批准，不得擅自更改。"},{"i":11,"n":"第十一条","txt":"渔政船必须服从其渔业行政主管部门的调度指挥，认真执行下达的执法任务。"},{"i":12,"n":"第十二条","txt":"上一级渔业行政主管部门可以根据执法任务的需要，调用下一级渔业行政主管部门的渔政船执行执法任务。渔政船被调用期间服从上级渔业行政主管部门的指挥。"},{"i":13,"n":"第十三条","txt":"任何单位和个人不得利用渔政船从事生产、营运等以盈利为目的的经营活动。因渔业资源调查等活动或配合政府其它部门的公务活动需使用渔政船时，应报上一级渔业行政主管部门备案。"},{"i":14,"n":"第十四条","txt":"凡执行渔业行政执法任务需使用船、艇时，必须使用渔政船。 内陆地区或因特殊原因需借用、租用非渔政船执行渔业行政执法任务时，必须事先报经省级渔业行政主管部门批准。报告时应说明拟执行的任务、时间、范围以及拟借用、租用船舶的船名号等有关情况。执行任务时，借用、租用的非渔政船的船名号必须清晰可见，在不影响公务的前提下还应有明显的渔业行政执法标识。任务结束后应向批准部门报告执行情况。"},{"i":15,"n":"第十五条","txt":"渔政船执行渔业行政执法任务时，有关执法检查和行政处罚等具体渔业行政执法事宜，由随船执行任务的渔业行政执法官员依法决定。 船长对渔政船的航泊安全负责，依照执法任务的要求制定航行计划。当船上渔业行政执法官员因执法任务的需要，要求调整原定的航行计划时，在不影响安全的情况下，船长应予以配合。"},{"i":16,"n":"第十六条","txt":"各级渔业行政主管部门要按渔业船舶管理的有关规定，对所属的渔政船配齐职务船员，按执法任务需要配备渔业行政执法官员。 海洋渔政船还要按中华人民共和国渔政渔港监督管理局统一规定的标准配备通讯导航设备。"},{"i":17,"n":"第十七条","txt":"渔政船发生事故时，船长应及时采取有效措施组织抢救，尽量减少损失，并及时报告其渔业行政主管部门。"},{"i":18,"n":"第十八条","txt":"渔政船须按规定向渔业船舶检验部门申报船舶检验，向渔港监督部门办理船舶登记。"},{"i":19,"n":"第十九条","txt":"违反本办法规定的，将追究有关人员的责任。"},{"i":20,"n":"第二十条","txt":"本办法由中华人民共和国渔政渔港监督管理局负责组织实施。"},{"i":21,"n":"第二十一条","txt":"本办法由农业部负责解释。"},{"i":22,"n":"第二十二条","txt":"本办法自2001年1月1日起施行。原国家水产总局《渔政船管理暂行办法》[（79）渔总（管）字第23号]同时废止。"}],"zhongguogongminminzuchengfendengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范公民民族成份的管理工作，根据宪法和《中华人民共和国户口登记条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国公民适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称民族成份，是指在户口登记中填写的经国家正式确认的民族名称。"},{"i":4,"n":"第四条","txt":"国务院民族事务部门和公安部门负责指导、监管公民民族成份的登记和管理工作。"},{"i":5,"n":"第五条","txt":"公民的民族成份，只能依据其父亲或者母亲的民族成份确认、登记。 本办法所称的父母，包括生父母、养父母和与继子女有抚养教育关系的继父母。"},{"i":6,"n":"第六条","txt":"公安部门在办理新增人口户口登记时，应当根据新增人口父母的民族成份，确认其民族成份。 新增人口的父母民族成份不相同的，应当根据其父母共同签署的民族成份填报申请书予以确认并登记。"},{"i":7,"n":"第七条","txt":"公民民族成份经确认登记后，一般不得变更。 未满十八周岁的公民，有下列情况之一的，可以申请变更其民族成份一次。 （一）父母婚姻关系发生变化，其民族成份与直接抚养的一方不同的； （二）父母婚姻关系发生变化，其民族成份与继父（母）的民族成份不同的； （三）其民族成份与养父（母）的民族成份不同的。 年满十八周岁的公民，在其年满十八周岁之日起的两年内，可以依据其父或者其母的民族成份申请变更一次。"},{"i":8,"n":"第八条","txt":"未满十八周岁的公民变更民族成份，应当由其父母或者其他法定监护人提出申请；年满十八周岁的公民申请变更民族成份，应当由其本人提出申请。"},{"i":9,"n":"第九条","txt":"未满十八周岁公民申请变更民族成份，需提交以下证明材料： （一）书面申请书； 根据生父（母）的民族成份提出变更申请的，书面申请书应当由直接抚养的一方签署；根据养父（母）的民族成份提出变更申请的，书面申请书应当由公民养父母共同签署；根据继父（母）的民族成份提出变更申请的，书面申请书应当由与公民共同生活的生父（母）与继母（父）共同签署。申请之日公民已年满十六周岁的，申请人应当征求公民本人的意见。 （二）公民本人的居民户口簿及公民的养（继）父（母）的居民户口簿、居民身份证； （三）依据生父（母）的民族成份申请变更的，需提供离婚证明；依据继父（母）的民族成份申请变更的，需提供生父（母）与继母（父）的婚姻关系证明；依据养父（母）的民族成份申请变更的，需提供收养证明； （四）如居民户口簿不能体现父母子女关系的，需提供公民户籍所在地的乡（镇）人民政府、街道办事处出具的父母子女关系证明； （五）其他相关"},{"i":10,"n":"第十条","txt":"年满十八周岁的公民申请变更民族成份，需提交以下证明材料： （一）由本人提交的书面申请书； （二）公民本人及其父母的居民户口簿、居民身份证； （三）如居民户口簿不能体现公民与父母子女关系的，需要提供公民户籍所在地的乡(镇)人民政府、街道办事处出具的父母子女关系证明； （四）其他相关证明材料。"},{"i":11,"n":"第十一条","txt":"申请变更民族成份，按照下列程序办理： （一）申请人向户籍所在地的县级人民政府民族事务部门提出申请； （二）县级人民政府民族事务部门对变更申请提出初审意见，对不符合条件的申请予以退回，并书面说明不予受理的理由；对符合条件的申请，自受理之日起的十个工作日内报上一级人民政府民族事务部门审批。 对于十个工作日内不能提出初审意见的，经县级人民政府民族事务部门负责人批准，可以延长十个工作日； （三）上一级人民政府民族事务部门应当在收到审批申请之日起的十个工作日内，出具书面审批意见，并反馈给县级人民政府民族事务部门； （四）县级人民政府民族事务部门应当在收到审批意见的十个工作日内，将审批意见告知申请人。审批同意的，并将审批意见、公民申请书及相关证明材料抄送县级人民政府公安部门； （五）公安部门应当依据市级人民政府民族事务部门的审批意见，严格按照公民户籍主项信息变更的管理程序，在十五个工作日内办理公民"},{"i":12,"n":"第十二条","txt":"各级民族事务部门应当建立民族成份变更定期备案制度。 地市级人民政府民族事务部门应当每半年将本行政辖区内的民族成份变更审批情况向省级人民政府民族事务部门备案一次。 省级人民政府民族事务部门应当每一年将本行政辖区内的民族成份变更统计数据向国务院民族事务部门备案一次。"},{"i":13,"n":"第十三条","txt":"各级民族事务部门与公安部门应当加强公民民族成份登记信息化建设，建立民族成份信息共享机制，定期交换民族成份登记、变更统计信息。"},{"i":14,"n":"第十四条","txt":"各级民族事务部门与公安部门应当建立公民民族成份登记的协商联络和监督检查机制。"},{"i":15,"n":"第十五条","txt":"公民对本人或者其未满十八周岁的子女的民族成份的确认、登记、变更决定有异议的，可以依法申请行政复议或者提起行政诉讼。"},{"i":16,"n":"第十六条","txt":"公民隐瞒真实情况，伪造、篡改、提供虚假证明材料，申请变更民族成份的，民族事务部门应当撤销审批意见，公安部门应当撤销变更登记，同时通报相关部门收回该公民依据虚假民族成份享受的相关权益；构成违反治安管理行为的，依法予以治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"民族事务部门、公安部门有下列情形之一的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法予以处理。 （一）对符合条件的公民变更民族成份的申请不予受理的； （二）无正当理由未在规定期限内登记、审批、变更公民民族成份的； （三）违规审批公民民族成份变更申请的； （四）违规登记或者变更公民民族成份的。"},{"i":18,"n":"第十八条","txt":"违规确认或者更改的公民民族成份，由公安部门按照市级人民政府民族事务部门出具的调查处理意见书予以更正。 公民民族成份在户籍管理过程中被错报、误登的，由公安部门按照纠错程序更正其民族成份。"},{"i":19,"n":"第十九条","txt":"未定族称公民的民族成份，按照国家有关规定进行管理。"},{"i":20,"n":"第二十条","txt":"中国公民同外国人结婚生育或者依法收养的子女取得中国国籍的，其民族成份应当依据中国公民的民族成份确定。 外国人取得中国国籍的，其民族成份按照国家有关规定进行管理。"},{"i":21,"n":"第二十一条","txt":"各省、自治区、直辖市人民政府民族事务部门和公安部门可根据本办法制定具体实施细则。 各省、自治区、直辖市人民政府民族事务部门和公安部门，可以结合本地实际，适当调整确认公民民族成份变更申请的审批权限，并向国务院民族事务部门备案。"},{"i":22,"n":"第二十二条","txt":"本办法自2016年1月1日起施行。此前有关公民民族成份登记管理的文件、规定与本办法不符的，依照本办法执行。"}],"zhongwaihezuoshezhidianyingpianguanliguiding":[{"i":1,"n":"第一条","txt":"为繁荣电影创作生产，维护中外合作摄制电影片的制片者及相关人员的合法权益，促进中外电影交流，根据《电影管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称中外合作摄制电影片，是指依法取得《摄制电影许可证》或《摄制电影片许可证（单片）》的境内电影制片者（以下简称中方）与境外电影制片者（以下简称外方）在中国境内外联合摄制、协作摄制、委托摄制电影片。"},{"i":3,"n":"第三条","txt":"本规定适用于中外电影制片者在中国境内外合作摄制的故事片、美术片、科教片、纪录片、专题片等电影片（含胶片电影、数字电影、电视电影等）。"},{"i":4,"n":"第四条","txt":"国务院广播影视行政部门负责中外合作摄制电影的管理工作。"},{"i":5,"n":"第五条","txt":"中外合作摄制电影片包括下列形式： （一）联合摄制，即由中外双方共同投资（含资金、劳务或实物）、共同摄制、共同分享利益及共同承担风险的摄制形式； （二）协作摄制，即外方出资，在中国境内拍摄，中方有偿提供设备、器材、场地、劳务等予以协助的摄制形式； （三）委托摄制，即外方委托中方在中国境内代为摄制的摄制形式。"},{"i":6,"n":"第六条","txt":"中外合作摄制电影片应当遵循以下原则： （一）符合中国宪法、法律、法规及有关规定； （二）尊重中国各民族的风俗、宗教、信仰和生活习惯； （三）有利于弘扬中华民族的优秀文化传统； （四）有利于中国的经济建设、文化建设、思想道德建设和社会安定； （五）有利于中外电影交流； （六）不得损害第三国的利益。"},{"i":7,"n":"第七条","txt":"国家对中外合作摄制电影片实行许可制度。 境内任何单位或个人未取得《中外合作摄制电影片许可证》或批准文件，不得与境外单位或个人合作摄制电影片。未经批准，境外单位或个人不得在中国境内独立摄制电影片。"},{"i":8,"n":"第八条","txt":"申请中外合作摄制电影片，除应当符合有关法律法规要求外，还应当具备下列条件： （一）中方制片单位原则上需参与出品过两部或者以上获得电影公映许可证的国产电影； （二）中外合作双方均不在因违反《中华人民共和国电影产业促进法》、《电影管理条例》而被禁止摄制电影的处罚期内。"},{"i":9,"n":"第九条","txt":"申请中外合作摄制电影片应当向国务院广播影视行政部门提供下列材料： （一）中方制片单位的摄制立项申请； （二）中方制片单位参与出品的国产电影的电影公映许可证复印件（两部或者以上）； （三）电影文学剧本（规范汉字）一式三份； （四）外方的资信证明和合拍影片情况； （五）中外双方合作意向书或协议书，主要内容应明确：合作各方投资比例、中外主创人员比例、是否参加国内外电影节（展）等； （六）主创人员简介。"},{"i":10,"n":"第十条","txt":"中外合作摄制电影片立项申报审批程序： （一）中方制片单位向国务院广播影视行政部门提出申请； （二）国务院广播影视行政部门按照《行政许可法》的规定期限受理申请单位提出的书面申请； （三）决定受理的，国务院广播影视行政部门应当在二十个工作日内作出批准或不批准立项的决定。电影剧本须经专家评审的，应书面告知申请单位，其评审时间应在二十个工作日内完成； （四）符合联合摄制条件的，发给一次性《中外合作摄制电影片许可证》；符合协作摄制、委托摄制条件的，发给批准文件。不批准的，应当书面说明理由。"},{"i":11,"n":"第十一条","txt":"取得《中外合作摄制电影片许可证》或批准文件后，中外双方应根据批准立项的内容签订合同。"},{"i":12,"n":"第十二条","txt":"《中外合作摄制电影片许可证》有效期为两年。"},{"i":13,"n":"第十三条","txt":"联合摄制中需聘用境外主创人员的，应当报国务院广播影视行政部门批准，且外方主要演员比例不得超过主要演员总数的三分之二。"},{"i":14,"n":"第十四条","txt":"联合摄制的电影片，应当制作普通话语言版本，其字幕须使用规范汉字。根据影片发行的需要，允许以普通话版本为标准，制作相应国家、地区、少数民族的语言文字版本。"},{"i":15,"n":"第十五条","txt":"中外合作摄制完成的电影片，经当地省级广播影视行政部门提出初审意见后，报国务院广播影视行政部门电影审查委员会审查；中央和国家机关所属电影制片单位和持有《摄制电影片许可证（单片）》的单位申请立项并摄制完成的电影片，直接报国务院广播影视行政部门电影审查委员会审查。"},{"i":16,"n":"第十六条","txt":"联合摄制的电影片，经审查合格，取得国务院广播影视行政部门颁发的《电影片公映许可证》后，方可在中国境内外发行公映。 协作摄制、委托摄制的电影片，经审查合格的，可持国务院广播影视行政部门的批准文件办理出境手续。"},{"i":17,"n":"第十七条","txt":"中外双方如需更改已经取得《电影片公映许可证》的电影片，应当报国务院广播影视行政部门审批。"},{"i":18,"n":"第十八条","txt":"联合摄制的电影片，需参加中外电影节（展）的，应按照举办、参加中外电影节（展）的有关规定报国务院广播影视行政部门备案。"},{"i":19,"n":"第十九条","txt":"外方应通过中方在中国内地聘用电影创作及劳务人员，并依据中国法律、法规与应聘者签订合同。"},{"i":20,"n":"第二十条","txt":"对违反本规定的行为，依据《电影管理条例》的有关规定处罚。"},{"i":21,"n":"第二十一条","txt":"本规定适用于香港、澳门特别行政区及台湾地区的电影制片者在境内合作摄制电影。"},{"i":22,"n":"第二十二条","txt":"本规定自2004年8月10日起施行。广电总局《中外合作摄制电影片管理规定》（广电总局令第19号）同时废止。"}],"zhongyangguojiajiguanxingzhengdanweicaiwuguizeshis41adfd":[{"i":1,"n":"第一条","txt":"为规范中央国家机关各部门的行政财务行为，加强财务管理，提高资金使用效益，保障各部门行政工作任务的完成，根据财政部印发的《行政单位财务规则》，结合中央国家机关的实际情况，制定本实施细则。"},{"i":2,"n":"第二条","txt":"国务院各部门、各直属机构，最高人民法院、最高人民检察院，以及实行预算管理的其他事业单位和社会团体（以下统称各部门）的行政财务活动，应遵守本实施细则。"},{"i":3,"n":"第三条","txt":"各部门必须依据国家有关法律、法规和财务规章制度开展行政财务活动。在财务管理工作中，要厉行节约，制止奢侈浪费，量入为出，科学、合理地安排各项支出，注重资金使用效益。"},{"i":4,"n":"第四条","txt":"行政财务管理的基本任务是： （一）根据本部门工作任务的需要和主管预算单位的要求，编制本部门的预算； （二）依照国家有关法规，搞好预算外资金收入和其他收入管理； （三）根据核定的预算，统筹安排、使用各项资金，保障本部门正常运转的资金需要； （四）加强国有资产价值形态的管理，防止国有资产流失； （五）定期编制财务报告，如实反映财务收支状况，科学分析财务活动，积极参与财务决策； （六）建立、健全内部财务管理的各项规章制度，对本部门的行政财务活动进行控制、监督，厉行节约，制止奢侈浪费，不断提高资金使用效益； （七）对机关后勤服务单位的有关财务活动进行指导和监督； （八）完成上级主管部门和本部门领导交办的其他各项工作。"},{"i":5,"n":"第五条","txt":"各部门应设置相应的行政财务管理部门，并配备必要的财务人员。个别人员编制少或财务工作量小的部门，经上级主管部门批准，可不设立专门的财务管理机构，作为单据报销单位管理。"},{"i":6,"n":"第六条","txt":"各部门行政财务管理部门负责人要有较强业务和组织能力，能坚持原则、廉洁奉公，并具备相当于会计师以上专业技术水平。 行政财务人员必须具有财务会计专业或相近专业大专以上学历，遵守职业道德，并持有会计征。行政财务人员应保持相对稳定。"},{"i":7,"n":"第七条","txt":"行政财务活动应在部门行政负责人的领导下，由行政财务管理部门统一管理，不得随意分散管理，确有必要分散管理的，应报上级主管部门批准。"},{"i":8,"n":"第八条","txt":"预算是指各部门为完成工作任务，按照上级主管部门要求编制的年度财务收支计划。各部门的预算包括收入预算和支出预算。"},{"i":9,"n":"第九条","txt":"按照预算管理权限和经费领拨关系，中央国家机关的预算管理分为下列三个级次； （一）向财政部报领经费的国务院机关事务管理局（以下简称国管局）,是中央国家机关行政经费预算的主管预算单位； （二）向国管局报领经费，并对下级部门核拨经费的单位，为二级预算单位； （三）向上级预算单位报领经费，没有下级拨款单位的；为基层预算单位。"},{"i":10,"n":"第十条","txt":"国管局负责中央国家机关各部门经费预算的申请、领拨、分配、调整，以及执行情况的监督、检查，负责制定中央国家机关经费预算管理、财务管理办法及其监督执行工作，并向财政部负责； 二级预算单位负责本部门和下一级预算单位经费预算的申请、领拨、分配、调整以及预算执行情况的监督、检查，制订本部门经费预算管理及财务管理的具体实施办法,并向国管局负责； 基层预算单位负责本部门经费预算的申请和使用，制订本单位经费预算管理及财务管理具体实施办法，并向上级主管单位负责。 各级预算单位应按上述预算管理级次和管理权限报领、核拨经费，并按照批准的预算组织实施。"},{"i":11,"n":"第十一条","txt":"中央国家机关经费预算实行收支统一管理，定额、定项拨款，结余留用的管理办法。 各部门的各项收入和支出应当全部纳入单位预算统一管理，并由行政财务管理机构统筹安排使用。各部门取得的预算外资金收入和其他收入应当首先用于弥补经常性支出不足和必要的专项支出。"},{"i":12,"n":"第十二条","txt":"各部门的预算按下列程序编报和审批： （一）各部门根据下一年度工作任务和收入、支出增减因素，测算、编制下一年度收入、支出概算，于每年10月上旬报送国管局； （二）国管局审核、汇总各部门下一年度收入、支出概算后，于每年10月下旬报送财政部； （三）国管局根据财政部下达的预算指标，参考各部门的概算，核定各部门的经费预算； （四）各部门根据国管局核定的预算指标，正式编制年度预算，按规定时间报送，一式两份。 （五）国管局核定各部门年度预算。"},{"i":13,"n":"第十三条","txt":"国管局按照以下办法核定各部门的预算： （一）个人部分支出预算按照有关政策规定的开支标准确定； （二）公用部分支出预算按照保证需要、节约开支和公开、公平、合理的原则，根据人员编制和确定的预算定额核定； （三）专项经费根据财政部核定的专项经费预算指标或当年可调剂的财力，按照兼顾需要和可能的原则核定。 （四）预算外资金收入和其他收入预算按部门上报的预计数核定。"},{"i":14,"n":"第十四条","txt":"各部门应当严格执行年度预算，按照收支平衡、略有结余的原则，统筹安排各项支出，不得超预算或无预算安排支出。"},{"i":15,"n":"第十五条","txt":"各部门在预算执行过程中，原则上不调整财政预算拨款收入和从财政专户核拨的预算外资金收入。因国家政策、人员编制、工作任务等有重大调整，对预算执行影响较大，确需调整预算时，应以书面文件形式于每年9月底前报送国管局审核批准后进行调整。各部门非拨款收入部分的预算需要调整的，应报送国管局备案，并在年终决算中说明，国管局在决算批复时予以审核确认。"},{"i":16,"n":"第十六条","txt":"收入是指各部门依法取得的非偿还性资金，包括财政预算拨款收入、预算外资金收入和其他收入。"},{"i":17,"n":"第十七条","txt":"财政预算拨款收入是指主管预算单位核拨的财政预算资金，是各部门主要经费来源。 财政预算拨款可分为经常性经费拨款和专项经费拨款。 经常性经费拨款是指为维持各部门正常运转和完成日常工作任务所需的经费拨款。 专项经费拨款是指各部门为完成专项或特殊工作任务所需的经费拨款。"},{"i":18,"n":"第十八条","txt":"预算外资金收入是指按规定从财政预算外资金专户核拨给各部门的预算外资金，以及经财政部门核准留给部门按计划使用，不上缴财政预算外资金专户的少量预算外资金。"},{"i":19,"n":"第十九条","txt":"预算外资金主要包括： （一）各部门根据国家法律、法规和具有法律效力的规章收取、提取的各种行政事业性收费、基金（资金、附加收入）和凭借政府职权筹集的资金等； （二）各部门按照经财政部和国家发展计划委员会共同审批的项目和标准，收取、提取的各种行政事业性收费收入； （三）各部门按照国务院或财政部审批的项目和标准，向企业、事业单位和个人征收、募集或以政府信誉建立的具有特定用途的各项基金（资金、附加收入）； （四）各部门按照国家规定从所属企事业单位和社会团体集中的管理费及其他资金； （五）其他未纳入财政预算管理的财政性资金，主要包括各部门以政府名义获得的各种捐赠资金和派驻境外机构的非经营收入、财政专户利息等。 各部门必须合法取得预算外资金，并按国家有关规定进行管理。从财政预算外资金专户取得的预算外资金收入，是部门预算的重要组成部分，不是执收部门的自有资金，执收部门不得按比例提成、分配。"},{"i":20,"n":"第二十条","txt":"其他收入是指各部门取得的除财政预算拨款收入、预算外资金收入以外的其他各项合法收入。其他收入主要包括固定资产临时出租收入、固定资产有偿转让收入、固定资产报废残值收入、废旧物品变卖收入、财产物资损失赔偿收入、利息收入、劳务服务性收入、机关后勤单位上缴收入等。"},{"i":21,"n":"第二十一条","txt":"各部门合理、合法组织的劳务服务性收入，主要包括机关组织的劳务收入、咨询收入、科技文化活动收入、非独立核算机关后勤单位的服务收入、书刊发行收入等。 各部门在合理、合法组织劳务服务性收入时，应注重经济效益，引入激励机制，可采取按收入的一定比例提成的办法，对参与组织收入的单位或个人进行适当劳务补助，提成比例不得超过该项收入总额的10%，具体提成比例、分配办法，由部门根据实际情况确定后报国管局备案。"},{"i":22,"n":"第二十二条","txt":"各部门取得的预算外资金收入、其他收入，应当纳入单位预算进行统一管理，不得分散于各职能部门管理。"},{"i":23,"n":"第二十三条","txt":"支出是各部门开展业务活动所发生的资金耗费。 各部门的经费支出包括经常性经费支出、专项经费支出和自筹基本建设支出三部分。"},{"i":24,"n":"第二十四条","txt":"经常性经费支出是指各部门为维持正常运转和完成日常工作任务所发生的资金耗费，包括人员经费支出和公用经费支出。"},{"i":25,"n":"第二十五条","txt":"人员经费支出是指直接用于公务员个人待遇部分的支出，包括工资、补助工资、其他工资、职工福利费、社会保障费。"},{"i":26,"n":"第二十六条","txt":"各部门应加强人员经费支出的管理，严格按核定的人员编制控制经费开支人数。 用于职工待遇方面的支出，必须依据国家规定执行，不得随意扩大开支范围或提高开支标准。"},{"i":27,"n":"第二十七条","txt":"公用经费支出是指各部门为完成工作任务，用于设备和设施购置、维持、消耗，以及直接用于开展业务活动所发生的资金消耗，包括公务费、设备购置费、修缮费、业务费、业务招待费、其他费用。"},{"i":28,"n":"第二十八条","txt":"各部门应按国家有关规定，加强公用经费支出的管理；国家没有明确规定的，各部门可根据实际情况，在既能保证工作任务完成、又能节约开支的前提下，分别采取定额包干、超支不补或规定支出限额、超支自负等办法，努力减少公用经费支出中的浪费现象，加强公用经费支出的管理。"},{"i":29,"n":"第二十九条","txt":"各部门要根据有关规定，明确各款经费的开支界限，按规定的开支范围和开支内容列支，努力做到互不挤占。对垫付的款项，要制定相应的回收办法，对合署办公垫支的款项，要制定合理的分摊办法，收回的垫付款项冲减相应支出。"},{"i":30,"n":"第三十条","txt":"各部门开展业务活动所需的劳务和商品，要遵照国家有关“政府采购”规定，由有关采购部门按照集中统一、公开招标、公开竞价的方式进行采购。"},{"i":31,"n":"第三十一条","txt":"各部门要严格控制会议数量，对批准召开的会议，要严格控制会议人数和会议天数，逐步实行会议定点管理。会议的各项支出，应按规定的开支标准和范围列支。"},{"i":32,"n":"第三十二条","txt":"各部门要充分提高现有办公设备的利用率，按照合理、节约、高效的原则，根据财力可能，统筹安排好必需办公设备的购置。"},{"i":33,"n":"第三十三条","txt":"专项经费支出是指各部门为完成专项或特殊工作任务所发生的资金耗费。 专项经费支出应当严格按照批准用途和数额安排使用，不得任意改变其用途。项目完成后，要向主管预算单位报送专项经费支出决算和专项经费使用效果的报告。"},{"i":34,"n":"第三十四条","txt":"自筹基本建设支出是指各部门经批准用财政预算拨款以外的资金安排的基本建设支出。各部门的预算外资金收入和其他收入在保证机关正常开支所需后，确有余力需要用于基本建设的，应当报经国管局审批后，列自筹基本建设支出，其结转资金纳入基本建设财务统一管理。"},{"i":35,"n":"第三十五条","txt":"各部门应按照有关规定，建立、健全支出的审批、报销制度，防止多头审批和无计划开支、重大支出项目，应科学论证后报部门领导集体研究决定。"},{"i":36,"n":"第三十六条","txt":"各部门年度各项收入与支出相抵后的结余，年终结转下年度继续使用，不进行分配，其中专项经费结余，需报主管预算单位批准后结转下年度继续使用。"},{"i":37,"n":"第三十七条","txt":"各部门收回本年度已列为经费支出的款项，冲减当年的经费支出；收回以前年度已经列为经费支出的款项，增加结余，不得冲减当年经费支出。"},{"i":38,"n":"第三十八条","txt":"资产是指各部门占有或者使用的、并能以货币计量的经济资源。资产分为流动资产和固定资产。"},{"i":39,"n":"第三十九条","txt":"流动资产是指可以在一年内变现或者耗用的资产，包括现金、银行存款、库存材料、暂付款。各部门购买的有价证券视同流动资产。"},{"i":40,"n":"第四十条","txt":"各部门必须认真执行国家有关现金管理的规定，指定专职出纳人员，负责现金的管理。各项现金收付必须严密手续，保证安全。除银行规定的库存限额以外，库存现金都必须存入银行。现金管理必须做到日清月结，账款相符，不得以白条抵库。"},{"i":41,"n":"第四十一条","txt":"各部门应认真执行国家有关银行存款管理的规定，指定专职出纳人员负责银行存款的管理，各部门只能在当地就近的国有商业银行或国家政策性银行开设财政资金基本存款户和其他资金存款户，因特殊情况需要增设的，须报国管局审批。"},{"i":42,"n":"第四十二条","txt":"各部门应严格遵守银行的各项结算制度，超过银行规定结算起点限额的各项资金往来，都必须通过银行办理转账结算。 各部门不准出租、出借、转让银行账户，套取银行信用。要严格支票管理，不得签发“空头支票”，空白支票必须严格领用、注销手续，银行账户印鉴和支票应分设专人保管。各部门应及时与银行送达的对账单逐笔核对银行日记账，年终时，必须全部核对无误。"},{"i":43,"n":"第四十三条","txt":"库存材料是指各部门大宗购入的、需要库存的物资材料。各部门购买的库存材料，应严格入库验收、出库领用手续，并进行定期清查，做到账实相符。"},{"i":44,"n":"第四十四条","txt":"暂付款是指各部门在业务活动中与其他单位、所属单位或本单位职工发生的临时性结算款项。 各部门应当严格控制暂付款的范围，暂付款不能用于与业务活动无关的事项。暂付款应当及时收回和清理，不得长期挂账。"},{"i":45,"n":"第四十五条","txt":"各部门用结余资金购买的有价证券，应当作为货币资金妥善保管。各部门只能购买国债，不得购买其他有价证券。"},{"i":46,"n":"第四十六条","txt":"固定资产是指单位价值在规定标准以上，使用期限在一年以上，并在使用过程中能基本保持原有物质形态的资产。固定资产的单位价值标准是：一般设备单位价值在500元以上，专用设备单位价值在800元以上。单位价值虽不足以上规定价值标准，但使用时间在一年以上的大批同类物资，应当视作固定资产管理。 固定资产包括房屋及建筑物、专用设备、一般设备、交通工具、图书、其他固定资产。"},{"i":47,"n":"第四十七条","txt":"各部门占有、使用的固定资产，由财务部门统一建账、核算，由资产管理部门统一登记、管理。财务部门和资产管理部门要定期核对，做到账账相符，账实相符，发现问题应查明原因，明确责任，问题严重的报请主管预算单位处理。固定资产的转移、出售、报废和报损，按照国有资产处置规定办理报批后，由财务部门作相应的账务处理。 各部门取得的固定资产出租收入、固定资产占用费收入、固定资产有偿转让收入，原则上仍应用于固定资产的更新和维修。"},{"i":48,"n":"第四十八条","txt":"各部门应当根据合理、节约、有效的原则，进行固定资产配置。购置固定资产时，要兼顾单位财力的可能，防止盲目购置、重复购置，造成资金浪费和资产闲置。"},{"i":49,"n":"第四十九条","txt":"各部门固定资产的管理，按固定资产管理的有关规定执行，非经营性固定资产不计提折旧。非经营性资产转为经营性资产的，应当按照《中央国家机关非经营性资产转经营性资产管理暂行规定》的有关规定，进行资产评估，报有关部门批准，并收取一定比例的资产占用费。"},{"i":50,"n":"第五十条","txt":"应缴预算款是各部门依法取得并应上缴国库的预算资金。包括按规定纳入预算管理的基金收入，行政性收费收入、罚没款、赃款、礼品变价收入等。"},{"i":51,"n":"第五十一条","txt":"应缴财政专户款是各部门按规定代收的应上缴财政专户的预算外资金。应缴财政专户的预算外资金范围及管理办法，按有关规定办理。"},{"i":52,"n":"第五十二条","txt":"各部门取得应缴预算款、应缴财政专户款时，应当出示有关收费许可证，并按规定使用合法票据。 应缴预算款、应缴财政专户款应按照规定及时、足额上缴，不得挪用、截留或者坐支。"},{"i":53,"n":"第五十三条","txt":"暂存款是各部门在业务活动中发生的暂时存放、持结算的款项，主要包括代扣的房租费、水电费，以及党费、团费、工会经费、公费医疗款等。 各部门的暂存款项应按暂存部门的有关要求进行管理，及时清理、结算，不得长期挂账。"},{"i":54,"n":"第五十四条","txt":"暂存款中的代管经费是指各部门的行政财务部门在规定职责之外，受职能部门或其他单位的委托，代其管理的不属于本部门行政财务活动范围的款项。 各部门应按照委托单位的要求和国家有关规定，及时办理款项收付。定期向委托单位核对和报告。年终时向委托单位编报决算。临时代其他单位管理的经费，业务结束时，应及时结清，退回余款。各部门为其他单位代管经费，可适当提取一定的劳务费，其提取比例应与委托代管单位协议确定。为本单位或职能部门代管的经费，不得计提劳务费。"},{"i":55,"n":"第五十五条","txt":"各部门不得将应纳入单位预算管理的预算外资金收入、其他收入作为暂存款或代管经费管理。"},{"i":56,"n":"第五十六条","txt":"各部门依法划转撤并时，应在财政部门、主管预算单位的监督、指导下，进行全面的财务清查，编制有关财务报表，提供所有的财产物资和往来款项的清单，做好各项财产物资的移交、划转、接收等各项工作。"},{"i":57,"n":"第五十七条","txt":"划转撤并部门的资产分别按照下列规定处理： （一）转为事业单位和改变隶属关系的部门，经主管预算单位批准，全部资产无偿移交，并相应调整经费预算指标。 （二）转为企业的部门，由原单位负责对其全部资产进行清理和登记造册，并按照有关规定进行评估作价，经主管预算单位审核并报财政部审批后，其资产全额转作企业的国家资本金。 （三）撤销的部门，应在往来款项处理完毕后，将其全部资产上缴主管预算单位； （四）合并的部门，其全部资产移交新组建的单位。合并后多余的国有资产，由主管预算单位负责处理。"},{"i":58,"n":"第五十八条","txt":"各部门依法划转撤并的，由主管预算单位组织人员或委托社会中介审计机构对其财务活动进行审计。"},{"i":59,"n":"第五十九条","txt":"财务报告是指全面反映部门一定时期财务状况和预算执行结果的总结性书面文件。包括财务报表和财务情况说明书。"},{"i":60,"n":"第六十条","txt":"财务报表包括资产负债表、收入支出总表、支出明细表、基本数字表以及预算外资金收支明细表、专项资金支出情况表及其他有关报表或附表。"},{"i":61,"n":"第六十一条","txt":"财务情况说明书应当反映本期收入、支出、结余、专项经费使用、资产增减变动情况，说明影响本期或下期财务状况的重要事项及原因，总结本期财务管理经验，对存在的问题提出改进意见等。 各部门进行财务分析，按照财政部的有关规定执行，也可根据本部门的实际情况增加其他财务分析指标。"},{"i":62,"n":"第六十二条","txt":"财务报告必须真实、准确、完整地反映本部门的财务状况，财务报告的编制必须依据会计核算资料和有关文件进行，做到账表一致。"},{"i":63,"n":"第六十三条","txt":"财务监督是各部门根据国家有关法律、法规和财务规章制度，对本部门及其后勤单位财务活动进行审核、检查、纠正的行为。各部门的财务监督是国家财政监督的重要组成部分。"},{"i":64,"n":"第六十四条","txt":"财务监督的主要内容包括： （一）对预算编制和财务报告的真实性、准确性、完整性进行审核、检查； （二）对各项收入、支出的范围和标准是否符合国家法律、法规和财务规章制度的情况进行审核，检查； （三）对财产物资、货币资金管理要求和措施的落实情况进行审核、督促； （四）检查内部审计制度、岗位责任制是否真正贯彻落实； （五）对违反财务规章制度问题的纠正情况进行检查。"},{"i":65,"n":"第六十五条","txt":"各部门应当建立健全内部稽核制度和审计制度，指定专人负责财务监督工作。各部门要通过账务检查、现场抽查、联审互查、重点检查等方式，搞好经常性的财务监督工作。"},{"i":66,"n":"第六十六条","txt":"独立核算的机关后勤服务单位的财务监督工作，由行政财务管理部门负责，必要时由主管预算单位进行专项审核、检查。"},{"i":67,"n":"第六十七条","txt":"各部门在财务监督中要坚持原则，依法办事，有错必纠，对违反财务规章制度的问题，要根据有关规定及时进行处理。"},{"i":68,"n":"第六十八条","txt":"各部门要积极、主动配合上级审计部门依法进行的审计、检查活动。"},{"i":69,"n":"第六十九条","txt":"本实施细则由国务院机关事务管理局负责解释。"},{"i":70,"n":"第七十条","txt":"本实施细则自一九九八年七月一日起施行。《中央国家机关机关基金管理办法》（〔92〕国管财字第311号）同时废止。"}],"zhongyangguojiajiguanrenminfangkongxingzhengchufas6853ec":[{"i":1,"n":"第一条","txt":"为了规范中央国家机关人民防空行政处罚行为，保证有效地组织人民防空，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国人民防空法》（以下简称《人民防空法》）、《中华人民共和国行政处罚法》（以下简称《行政处罚法》）和其他有关法律、法规的规定，结合中央国家机关人民防空工作实际情况，制定本办法。"},{"i":2,"n":"第二条","txt":"中央国家机关人民防空办公室负责管理中央国家机关各部门的人民防空工作，依法对违反《人民防空法》的行为实施行政处罚。 中央国家机关人民防空办公室可以依法委托中央国家机关各部门人民防空办公室（以下简称部门人防办）实施行政处罚。"},{"i":3,"n":"第三条","txt":"部门人防办应当按照《人民防空法》的要求，对本部门及其在京直属单位的人民防空工作，依法进行管理和监督检查；受委托对违反《人民防空法》的行为实施行政处罚。 受委托部门人防办，应当与中央国家机关人民防空办公室签订委托书，在委托范围内实施行政处罚；不得再委托其他单位或个人实施行政处罚。"},{"i":4,"n":"第四条","txt":"人民防空行政处罚遵循公开、公正、处罚与教育相结合的原则，坚持以事实为依据，以法律为准绳，严格按照法律规定的程序实施。"},{"i":5,"n":"第五条","txt":"实施人民防空行政处罚的执法人员，须持证上岗，实行执法责任制和评议考核制。"},{"i":6,"n":"第六条","txt":"中央国家机关人民防空办公室管辖中央国家机关各部门的人民防空行政处罚案件。 受委托实施行政处罚的部门人防办具体办理本部门及其在京直属单位的人民防空行政处罚案件。 法律、行政法规对人民防空行政处罚管辖另有规定的，从其规定。"},{"i":7,"n":"第七条","txt":"涉外人民防空行政处罚案件或者有重大影响的人民防空行政处罚案件，由中央国家机关人民防空办公室直接办理。"},{"i":8,"n":"第八条","txt":"两个以上部门人防办对同一人民防空行政处罚案件都可以受理的，由先受理的部门人防办办理。如果后受理的部门人防办办理更为合适，经中央国家机关人民防空办公室同意，可以由后受理的部门人防办办理。"},{"i":9,"n":"第九条","txt":"部门人防办发现受理的案件不应当由其办理的，将有关材料及时移送有关部门人防办处理。受移送的部门人防办如认为移送不当的，报请中央国家机关人民防空办公室处理，不得再自行移送。"},{"i":10,"n":"第十条","txt":"同级部门人防办因受理人民防空行政处罚案件发生争议的，由中央国家机关人民防空办公室指定受理。"},{"i":11,"n":"第十一条","txt":"违法事实清楚，情节简单，对个人处以50元以下、对单位处以1000元以下罚款的，或者对个人、单位处以警告的，执法人员可以运用简易程序，当场作出行政处罚决定。"},{"i":12,"n":"第十二条","txt":"执法人员当场作出行政处罚决定的，应当出示《中央国家机关人民防空行政执法证》；填写统一编号的《行政（当场）处罚决定书》，当场交付当事人。"},{"i":13,"n":"第十三条","txt":"实施行政处罚，有下列情形之一的，执法人员可以当场收缴罚款： （一）依法给予20元以下罚款的； （二）不当场收缴事后难以执行的； （三）具备《行政处罚法》第四十八条规定情形，当事人向指定银行缴纳罚款确有困难，并要求当场缴纳的。 当场收缴罚款，必须向当事人出具按国家规定统一制发的罚款收据。不能当场收缴罚款的，应告知当事人在15日内到指定银行缴纳罚款。 执法人员当场收缴的罚款，应当自收缴之日起2日内交至执法部门；执法部门应当在2日内将罚款交至指定银行。"},{"i":14,"n":"第十四条","txt":"除依法可以当场处罚的以外，执法人员对符合下列规定的，应当在7日内立案： （一）有明确的当事人； （二）有违反《人民防空法》的行为事实并应依法受到行政处罚的； （三）符合本办法第二章第一节的规定。"},{"i":15,"n":"第十五条","txt":"执法部门在办理人民防空行政处罚案件时，应当按照《行政处罚法》第三十六条、第三十七条的规定进行。 执法人员与当事人有直接利害关系的，应当回避。"},{"i":16,"n":"第十六条","txt":"人民防空行政处罚案件调查终结，应当按照《行政处罚法》的有关规定作出行政处罚决定，将《行政处罚决定书》送达当事人。 在作出行政处罚决定之前，应当告知当事人给予行政处罚的事实、理由和依据，听取当事人的陈述和申辩。"},{"i":17,"n":"第十七条","txt":"人民防空行政处罚案件应当自立案之日起30日内办理完毕；情况复杂的，可以延长至3个月，情况特别复杂的，经批准可以延长至6个月。"},{"i":18,"n":"第十八条","txt":"执法部门对个人处以1000元以上罚款、对单位处以1万元以上罚款的行政处罚决定作出之前，应当告知当事人有要求举行听证的权利；当事人要求听证的，中央国家机关人民防空办公室应当按照《行政处罚法》第四十二条规定的程序组织听证。"},{"i":19,"n":"第十九条","txt":"人民防空行政处罚决定依法作出之后，当事人应当在规定的期限内予以执行。"},{"i":20,"n":"第二十条","txt":"当事人不服人民防空行政处罚决定的，可以在收到《行政处罚决定书》之日起15日内申请行政复议，或者在3个月内向人民法院提起行政诉讼。 对拒不执行人民防空行政处罚决定又不申请行政复议或者提起行政诉讼的，执法部门可以向人民法院申请强制执行。"},{"i":21,"n":"第二十一条","txt":"人民防空行政处罚实行罚款决定与罚款收缴相分离的制度，由中央国家机关人民防空办公室根据《罚款决定与罚款收缴分离实施办法》具体组织实施。"},{"i":22,"n":"第二十二条","txt":"中央国家机关人民防空办公室应建立健全行政处罚监督制度，对受委托部门人防办实施行政处罚的行为进行监督。 部门人防办在办理人民防空行政处罚案件中有事实不清、证据不足、违反法定程序等情况的，中央国家机关人民防空办公室应当予以纠正。 对严重违反法律、法规或已经丧失委托条件的部门人防办，中央国家机关人民防空办公室可以终止委托关系。"},{"i":23,"n":"第二十三条","txt":"对执法人员在办理行政处罚案件中的违法行为，当事人有权向中央国家机关人民防空办公室进行检举控告，中央国家机关人民防空办公室应当受理并在7日内给予答复。"},{"i":24,"n":"第二十四条","txt":"执法人员如有执法不严、执法违法等情况时，中央国家机关人民防空办公室可以责令其改正或建议有关部门予以行政处分；情节严重的，按照《人民防空法》、《行政处罚法》及其他有关法律的规定追究法律责任。"},{"i":25,"n":"第二十五条","txt":"中央国家机关人民防空办公室可以定期或不定期对部门人防办实施人民防空行政处罚的情况进行检查，督促其正确执行法律、法规和规章，发现问题及时处理。"},{"i":26,"n":"第二十六条","txt":"中央国家机关人民防空办公室每年对部门人防办实施人民防空行政处罚的情况，应进行评议考核，并对考核情况进行通报。"},{"i":27,"n":"第二十七条","txt":"中央国家机关人民防空办公室可以邀请有关部门和人员参加人民防空行政处罚执法检查。"},{"i":28,"n":"第二十八条","txt":"部门人防办应当将办理完毕的人民防空行政处罚案件，于10日内报中央国家机关人民防空办公室备案。 中央国家机关人民防空办公室应当将重要案件的行政处罚决定报国家人民防空主管部门备案。"},{"i":29,"n":"第二十九条","txt":"人民防空行政处罚案件应当在该案件处理完毕后15日内，按照一案一卷的要求编号归档。"},{"i":30,"n":"第三十条","txt":"部门人防办监督检查本部门及其在京直属单位的人民防空工作，其工作人员可以使用《中央国家机关人民防空行政执法证》或者《中央国家机关人民防空工作监督检查证》；对终止委托关系的或者违反规定使用证件的，证件收回。"},{"i":31,"n":"第三十一条","txt":"人民防空行政处罚的文书格式由中央国家机关人民防空办公室统一制定。"},{"i":32,"n":"第三十二条","txt":"中央国家机关人民防空办公室委托国务院直属企事业单位的人民防空工作机构实施人民防空行政处罚，应当符合《行政处罚法》第十九条的规定，并按照本办法办理。"},{"i":33,"n":"第三十三条","txt":"本办法由国务院机关事务管理局负责解释。"},{"i":34,"n":"第三十四条","txt":"本办法自1999年1月1日起施行。"}],"zhongyangguojiajiguanxingzhengdanweikuaijizhidu":[{"i":1,"n":"第一条","txt":"为了加强中央国家机关行政单位会计工作，规范会计核算行为，保证会计信息质量，根据财政部印发的《行政单位会计制度》，结合中央国家机关的实际情况，制定本制度。"},{"i":2,"n":"第二条","txt":"本制度适用于国务院各部委、各直属机构，最高人民法院、最高人民检察院，以及实行行政财务管理的有关事业单位和社会团体（以下简称各部门）。"},{"i":3,"n":"第三条","txt":"行政单位会计是预算会计的组成部分，其会计核算必须遵守国家有关法律、法规及本制度的规定，保证会计工作依法有序地进行。"},{"i":4,"n":"第四条","txt":"根据机构建制和经费报领关系，中央国家机关行政单位会计组织体系分为主管会计单位、二级会计单位和基层会计单位三级。 向财政部报领经费的国务院机关事务管理局，为主管会计单位。 向主管会计单位报领经费，并有下一级会计单位的，为二级会计单位。 向上一级会计单位报领经费，没有下一级会计单位的，为基层会计单位。 不具备独立核算条件的，可向基层会计单位领取备用金，实行单据报账制度，作为“报销单位”管理。"},{"i":5,"n":"第五条","txt":"行政单位会计工作的基本任务是： （一）进行会计核算，主要包括经费领拨、收入、支出、货币资金、往来款项、财产物资等事项的会计核算，并根据会计核算的结果编报有关会计报表； （二）实行会计监督，按照国家有关规定，对会计凭证、会计账簿、会计报表等会计信息、资料的真实性、合法性和有效性进行监督； （三）参与本部门有关业务计划的拟定，考核、分析预算执行情况，妥善调度、合理安排和有效使用资金，保证行政工作任务的完成； （四）依据有关规定，结合本部门实际情况，制定会计事务管理的具体办法； （五）建立内部稽核制度和岗位责任制，保证国家资金和财产物资的安全完整。"},{"i":6,"n":"第六条","txt":"各部门应当根据本部门人员编制、业务规模以及承担的会计工作任务，设置相应的会计工作机构，配备必要的会计人员。 行政财务人员必须具有财务会计专业或相近专业大专以上学历，遵守职业道德，并持有会计征。行政财务人员应保持相对稳定。"},{"i":7,"n":"第七条","txt":"各部门应当按《会计基础工作规范》的要求及本单位会计工作的实际，设置会计工作岗位。"},{"i":8,"n":"第八条","txt":"各部门的会计机构应当设置在相应的承担行政管理职能的部门内。会计人员必须持有会计证。"},{"i":9,"n":"第九条","txt":"会计核算应当以实际发生的经济业务为依据，客观真实地记录、反映各项收支情况和结果。"},{"i":10,"n":"第十条","txt":"会计信息应当符合国家宏观经济管理的要求，适应预算管理和有关方面了解本部门财务状况及收支结果的需要，有利于单位加强内部财务管理。"},{"i":11,"n":"第十一条","txt":"会计核算应当按照规定的会计处理方法进行，同类单位会计核算指标应当口径一致，相互可比。"},{"i":12,"n":"第十二条","txt":"会计处理方法应当前后各期一致，不得随意变更。如确有必要变更，应报经主管会计单位同意，并在会计报表中说明变更的原因以及对单位财务收支情况及结果的影响。"},{"i":13,"n":"第十三条","txt":"会计核算应当及时进行。一般情况，当月的会计处理工作应在次月4日前完成。"},{"i":14,"n":"第十四条","txt":"会计记录和会计报表应当清晰明了，便于理解和运用。"},{"i":15,"n":"第十五条","txt":"会计核算应当划分会计期间，分期结算账目和编制会计报表。会计期间分为年度、季度和月份，起讫日期采用公历日期。"},{"i":16,"n":"第十六条","txt":"会计记账统一采用借贷记账法。"},{"i":17,"n":"第十七条","txt":"会计核算以收付实现制为基础，即本期发生的收支，不论本期是否受益，均作为本期的收入或支出进行处理。"},{"i":18,"n":"第十八条","txt":"会计核算以人民币为记账本位币，以元为位，元以下记至角、分。发生外币收支的，应当按照中国人民银行公布的当日人民币外汇汇率折算为人民币核算，同时登记外币辅助账。"},{"i":19,"n":"第十九条","txt":"各部门应当使用会计主管单位统一推广使用的会计电算化软件进行会计事务处理。各部门自行开发或购置的账务处理或会计报表软件不得与统一推广使用的软件相抵触。"},{"i":20,"n":"第二十条","txt":"各部门应按“款”分账进行会计核算，每一款为一个核算体系。"},{"i":21,"n":"第二十一条","txt":"行政单位会计要素分为资产、负债、净资产、收入、支出五类。"},{"i":22,"n":"第二十二条","txt":"资产是行政单位占有或使用的，能以货币计量的经济资源。包括流动资产和固定资产。 （一）流动资产是指可以在一年内变现或者耗用的资产，包括现金、银行存款、暂付款、有价证券、库存材料等。 现金和银行存款按照实际收入和支出数额记账。 暂付款按实际发生数额记账。 有价证券按购买时实际支付金额记账。 库存材料按购入时实际支付的金额记账，按领用数列记经费支出。 （二）固定资产是指单位价值在规定标准以上，使用年限在一年以上，并在使用过程中基本保持原来物质形态的资产。单位价值虽未达到规定标准，但使用时间在一年以上的大批同类物资，应作为固定资产核算。"},{"i":23,"n":"第二十三条","txt":"负债是行政单位承担的能以货币计量，需要以资产偿付的债务，包括应缴预算款、应缴财政专户款、暂存款等。各项负债应按实际发生数额记账。"},{"i":24,"n":"第二十四条","txt":"净资产是行政单位资产减负债和收入减支出的差额，包括固定基金、结余等。 固定基金是行政单位固定资产所占用的基金。固定基金按实际发生数额记账。 结余是行政单位各项收入与支出相抵后的余额。"},{"i":25,"n":"第二十五条","txt":"收入是指行政单位为开展业务活动，依法取得的非偿还性资金，包括财政拨款收入、预算外资金收入、其他收入等。"},{"i":26,"n":"第二十六条","txt":"各部门收回本年度已列为经费支出的款项，冲减当年的经费支出；收回以前年度已经列为经费支出的款项，增加上年结余，不得冲减当年经费支出。"},{"i":27,"n":"第二十七条","txt":"本制度规定的会计科目，是汇总和检查行政单位资金活动情况和结果的总账科目。非经主管会计单位同意，各部门不得减并或自行增设，不得擅自更改科目名称。不需要的科目可以不用。本制度统一规定的会计科目编号，应与会计科目名称同时使用。可以只使用会计科目名称，不用会计科目编号，但不得只填会计科目编号，不写科目名称。"},{"i":28,"n":"第二十八条","txt":"会计科目名称 （一）资产类 科目编号 科目名称 101　　现金 102　　银行存款 103　　有价证券 104　　暂付款 105　　库存材料 106　　固定资产 （二）负债类 201　　应缴预算款 202　　应缴财政专户款 203　　暂存款 （三）净资产类 301　　固定基金 303　　结余 （四）收入类 401　　拨入经费 404　　预算外资金收入 407　　其他收入 （五）支出类 501　　经费支出 502　　拨出经费 505　　结转自筹基建"},{"i":29,"n":"第二十九条","txt":"会计科目的使用 （一）资产类： 1.第101号科目 现金 本科目核算各部门的库存现金。收到现金时，借记本科目，贷记有关科目；支出现金时，贷记本科目，借记有关科目。 本科目的借方余额，反映库存现金数额。 各部门必须设立“现金日记账”，按时间顺序逐笔登记库存现金的收支。实行手工登记的“现金日记账”由出纳人员根据现金收付的原始凭证登记。“现金日记账”必须使用订本式账簿。“现金日记账”在每个工作日终了时必须结账，并填制“库存现金日报表”。实行会计电算化的单位每日的“现金日报表”必须与库存现金数额相符，“现金日记账”账页必须连续满页，因特殊情况不能连续满页的必须注明原因，并报主管人员签字盖章。库存现金不得以白条抵库，必须账款相符。 2.102号科目 银行存款 本科目核算各部门存入银行的各种款项。将款项存入银行时，借记本科目，贷记有关科目；提取现金或支出存款时，贷记本科目，借记有关科目。 本科目的"},{"i":30,"n":"第三十条","txt":"各部门必须按照财政部制定的《会计基础工作规范》和本制度的规定，取得、填制和审核会计凭证。会计凭证包括原始凭证和记账凭证。"},{"i":31,"n":"第三十一条","txt":"原始凭证 原始凭证是经济业务发生时取得的书面证明，是会计事项唯一合法凭证，是填制记账凭证的依据。 原始凭证必须具备下列内容：凭证的名称和填制日期、填制凭证的单位和填制人以及单位公章、接受凭证的单位名称、经济业务的内容、品名、　数量、单价和金额、经办人员签字或盖章。"},{"i":32,"n":"第三十二条","txt":"记账凭证 记账凭证是根据原始凭证填制、用来确定会计分录并据以登记账簿的依据。 记账凭证必须具备下列内容：凭证名称、填制日期、凭证编号、经济业务的内容摘要、会计科目的名称和金额、所附原始凭证的张数以及制单、复核、记账等人员的签章。"},{"i":33,"n":"第三十三条","txt":"实现会计电算化的部门，在同一台机器上填制的记账凭证编号必须连续。编号出现间断时，应在断号后的第一张凭证上注明间断的编号、原因并经主管人员签字或盖章。"},{"i":34,"n":"第三十四条","txt":"凭证保管 各部门的会计凭证必须按照编号顺序，及时装订成册，不得散乱丢失。会计凭证的保管年限按照《会计档案管理办法》的规定执行。"},{"i":35,"n":"第三十五条","txt":"遗失处理 原始凭证如有遗失，应取得原签发单位盖有公章的证明，并注明原来凭证的号码、金额和内容等，由经办单位负责人批准后，才能代作原始凭证；确实无法取得证明的，由当事人写出详细情况，由经办单位负责人批准，会计主管人员核准后，代作原始凭证。"},{"i":36,"n":"第三十六条","txt":"各部门必须按照本制度的规定和会计业务的需要设置会计账簿，并依据《会计基础工作规范》和本制度的规定登记发生的各项经济业务。"},{"i":37,"n":"第三十七条","txt":"各部门的会计账簿包括总账、明细账、日记账和其他辅助性账簿。具体设置要求如下（没有相应业务的可以不设）： （一）总分类账（简称总账） 总分类账按照第六章第二十八条规定的会计科目设置。 （二）明细账及日记账 1.拨出经费明细账； 2.正常经费支出明细账； 3.专项经费支出明细账； 4.其他收入明细账； 5.暂存、暂付款项明细账； 6.代管经费明细账； 7.银行存款日记账。 8.现金日记账； 9.固定资产明细账。 （三）备查账簿 备查账用于登记所设日记账、分类账未能反映的有关经济业务。备查账由部门根据需要设置。"},{"i":38,"n":"第三十八条","txt":"登记账簿 各部门根据审核无误的记账凭证和原始凭证登记账簿。 实现会计电算化的部门必须定期将存贮在机器上的账簿数据打印出书面账簿。"},{"i":39,"n":"第三十九条","txt":"结账 各部门必须按规定定期结账。现金日记账必须做到日清月结，总账、明细账必须按月结账。"},{"i":40,"n":"第四十条","txt":"对账 各部门应当定期或不定期地进行对账工作，做到账实相符、账证相符、账账相符。"},{"i":41,"n":"第四十一条","txt":"错误更正 （一）填制的记账凭证发生错误时，不得挖补、涂抹、刮擦或使用化学药水消字，应按下列方法更正： 1.发现未登记账簿的记账凭证错误，应将原记账凭证作废，重新编制记账凭证。 2.发现已经登记账簿的记账凭证错误，应采用“红字冲正法”或“补充登记法”更正。采用计算机做记账凭证的，用“红字冲正法”时，以负数表示。 （二）账薄记录如发生错误，不得挖补、涂抹、刮擦或使用化学药水除迹，应按下列方法更正： 发生文字或数字书写错误，用“划线更正法”更正，并由记账人员在更正处盖章。 由于记账凭证科目对应关系填错引起的，应按更正的记账凭证登记账簿。"},{"i":42,"n":"第四十二条","txt":"财政拨款原则 财政拨款的领拨必须根据核定的预算，按规定的预算管理级次逐级办理，不得向没有经费领拨关系的单位拨款，同级单位之间不能直接办理转拨手续。 因机构撤销或合并而必须划转经费的，通过上级主管会计单位办理。各部门的经费预算原则上每月拨款一次，特殊情况可以临时拨款。各部门不得申请办理无预算或超预算拨款。"},{"i":43,"n":"第四十三条","txt":"账户设置 各部门必须设置“拨入经费”、“预算外资金收入”和“其他收入”总账账户。"},{"i":44,"n":"第四十四条","txt":"账务处理 （一）拨入经费的核算 1.收到上级会计单位拨来经费 借：银行存款 贷：拨入经费 2.缴回上级会计单位所拨经费 借：拨入经费 贷：银行存款 3.年终结转拨入经费 借：拨入经费 贷：结余 （二）预算外资金收入的核算 1.收到核拨的预算外资金收入 借：银行存款 贷：预算外资金收入 2.年终结转 借：预算外资金收入 贷：结余 （三）其他收入的核算 1.发生其他收入 借：银行存款（或现金） 贷：其他收入 2.年终结转 借：其他收入 贷：结余"},{"i":45,"n":"第四十五条","txt":"账户设置 各部门应设置“现金”、“银行存款”、“有价证券”总账账户。"},{"i":46,"n":"第四十六条","txt":"账务处理 （一）从银行提取现金 借：现金 贷：银行存款 （二）现金送存银行 借：银行存款 贷：现金 （三）购买有价证券 借：有价证券 贷：银行存款 （四）兑现有价证券 借：银行存款 贷：有价证券（本金） 贷：其他收入（利息） （五）购入大宗、需要库存的材料 借：库存材料 贷：银行存款"},{"i":47,"n":"第四十七条","txt":"各项支出的核算，应当按照财政部门或上级主管会计单位规定的预算支出科目、范围、内容执行。"},{"i":48,"n":"第四十八条","txt":"各项支全的核算必须以实际发生数为准。支出的报销规定如下： （一）发给个人的工资、津贴、补贴等，应根据实有人数和实发金额，取得本人签收的凭证，列为支出，不得以定额或预算计划数列支； （二）职工福利费和工会经费，按照国家有关规定标准提取，直接列为支出； （三）拨给所属单位的款项，以银行转拨凭证为依据列支出； （四）购入固定资产，经验收后以购进时发生的实际费用列报支出； （五）其他各项费用，均以实际报销的数字列为支出； （六）凡应由个人支付的罚没款，不得由单位支付； （七）购买国库券和其他有价证券，应作为有价证券入账，不得列为支出。"},{"i":49,"n":"第四十九条","txt":"各部门必须按照批准的预算或计划办理支出，不得办理无预算或无计划的支出，对手续不全、凭证不实、不符合有关财政、财务制度的开支，应拒绝报销。"},{"i":50,"n":"第五十条","txt":"各部门必须设置“经费支出”、“拨出经费”、“结转自筹基建”总账账户和相关的明细账户。"},{"i":51,"n":"第五十一条","txt":"账务处理 （一）支出报销 借：经费支出 贷：银行存款（或现金） （二）购置固定资产 借：经费支出 贷：银行存款 同时记： 借：固定资产 贷：固定基金 （三）经费支出收回 1.收回本年度已列为经费支出的款项 借：银行存款（或现金） 贷：经费支出 2.收回以前年度已列为经费支出的款项 借：银行存款（或现金） 贷：结余 （四）年终结转本年经费支出 借：结余 贷：经费支出 （五）转拨给所属会计单位经费 借：拨出经费 贷：银行存款 （六）所属会计单位缴回拨给的经费 借：银行存款 贷：拨出经费 （七）年终结转所属会计单位的拨出经费 借：结余 贷：拨出经费 （八）将自筹的基本建设资金转存建设银行 借：结转自筹基建 贷：银行存款 （九）年终结转 借：结余 贷：结转自筹基建"},{"i":52,"n":"第五十二条","txt":"往来款项是指单位在资金活动过程中发生的暂存暂付、应收应付、预收预付和借入借出等待结算款项。"},{"i":53,"n":"第五十三条","txt":"账户设置 各部门应设置“暂存款”、“暂付款”、“应缴预算款”、“应缴财政专户款”总账账户。"},{"i":54,"n":"第五十四条","txt":"代管经费 各部门会计机构在规定职责之外，受职能部门或其他单位的委托，代其管理的经费（本单位的党费、团费、公费医疗款等，不属于代管经费），应按照委托单位的要求，及时办理款项收付。设立“暂存款--代管经费”二级科目，并设立相应账户进行核算。各部门会计机构应定期向委托单位核对和报告代管经费收付情况，年终时向委托单位编报决算。 临时代其他单位管理的经费，业务结束时，应及时结清，退回余款。"},{"i":55,"n":"第五十五条","txt":"账务处理 （一）暂存款 1.收到预收、暂存或应付款 借：银行存款（或现金） 贷：暂存款 2.有退款情况时： 借：暂存款 贷：银行存款（或现金） （二）暂付款 1.发生暂付款时 借：暂付款 贷：银行存款（或现金） 2.暂付款核销和收回 借：经费支出 借：现金（或银行存款） 贷：暂付款 借：经费支出 贷：现金（或银行存款） 贷：暂付款 （三）应缴预算款 1.发生应缴预算款时： 借：银行存款（或现金） 贷：应缴预算款 2.上缴应缴预算款时： 借：应缴预算款 贷：银行存款 （四）应缴财政专户款 1.收到应上缴财政专户的各项收入 借：银行存款（或现金） 贷：应缴财政专户款 2.上缴财政专户 借：应缴财政专户款 贷：银行存款 3.实行预算外资金结余上缴财政专户办法的定期结算预算外资金结余 借：预算外资金收入 贷：应缴财政专户款 4.实行按比例上缴财政专户的预算外资金收入 借：银行存款 贷：预算外资"},{"i":56,"n":"第五十六条","txt":"账户设置 各部门应设置“固定基金”、“固定资产”和“库存材料”总账账户。"},{"i":57,"n":"第五十七条","txt":"固定资产计价 （一）新建、购入和调入的固定资产分别按造价、购价、调拨价和相应发生的运杂费、保险费、安装费、车辆购置附加费入账； （二）自制或自行建造的固定资产，按发生的实际支出入账； （三）改扩建的，按改扩建过程中发生的实际支出减去变价收入的净增加值增记固定资产价值； （四）接受捐赠的固定资产，按同类固定资产的市场价格或有关凭据及发生的各项费用入账； （五）盘盈、无偿调入的固定资产，不能查明原值的，估价入账； （六）盘亏、报废、变卖和调出的固定资产，按账面原值注销。"},{"i":58,"n":"第五十八条","txt":"账务处理 （一）领用库存材料 借：经费支出 贷：库存材料 （二）购进、建造、调入、自制、改扩建或自行建造固定资产 借：固定资产 贷：固定基金 同时记： 借：经费支出 贷：银行存款 （三）报废、变卖固定资产 1.核销　　　　　　　　　　　　2.收回残值和变价收入 借：固定基金　　　　　　　　　借：银行存款(或现金） 贷：固定资产　　　 　　　　　 贷：其他收入 （四）盘盈、盘亏固定资产 1.盘盈　　　　　　　　　　　　2.盘亏 借：固定资产　　　　　　　　　借：固定基金 贷：固定基金　　　　　　　　　贷：固定资产"},{"i":59,"n":"第五十九条","txt":"编报要求 各部门必须根据会计账簿数据和有关文件资料定期编报会计报表，对主管部门要求编报的会计报表，不得拒报、漏报。会计报表必须数字准确、内容完整、报送及时。"},{"i":60,"n":"第六十条","txt":"报表种类 各部门的会计报表主要包括资产负债表、收入支出总表、支出明细表、其他报表等。 （一）资产负债表是反映各部门在某一特定日期财务状况的报表。资产负债表的项目应按会计要素的类别分别列示。 （二）收入支出总表是反映各部门年度收支规模的报表。收入支出总表按各部门各项收支项目汇总列示。 （三）支出明细表是反映各部门在一定时期内预算执行情况的报表。支出明细表的项目，应按规定的“预算支出目节级科目”列示。 （四）其他报表包括专项经费支出明细表、往来款项明细表、其他报表或附表。"},{"i":61,"n":"第六十一条","txt":"报送期限 各部门的各种会计报表必须在规定的时间内报送： 季报在季度终了后7天内报达（有京外所属单位的可延至10天）。 年报在年度终了后40天内报达。 报表的格式及编制说明按主管部门要求办理。"},{"i":62,"n":"第六十二条","txt":"报销单位的设立 办公地点与机关本部不在一处，所需经费不多，财务收支简单，或人员编制少，业务量小的单位，不需建立基层会计单位，作为报销单位管理。"},{"i":63,"n":"第六十三条","txt":"经费报销 （一）报销单位经费预算由各部门统一编制。报销单位日常报销所需经费，由各部门拨给一定数额的备用金。 （二）报销单位的备用金应按现金管理的有关规定进行管理。 （三）报销单位的会计人员应定期持原始单据到机关财务部门报销、结算。 （四）报销单位的备用金年终必须全部收回，下年度开始，由各部门重新的拨给。"},{"i":64,"n":"第六十四条","txt":"会计人员调动工作或者离职，应按《会计法》和《会计基础工作规范》的有关规定办理交接手续并编制移交清册，对未了事项及其他应交待事项等要作出书面说明。"},{"i":65,"n":"第六十五条","txt":"部门撤销或合并的，由会计人员负责经费领拨、财产物资、债权债务、现金、存款等事项的清理，并负责编报决算。在向接收单位移交之前，不得调走会计人员。"},{"i":66,"n":"第六十六条","txt":"会计人员在办理交接中，如存在交代不清或故意为难等问题，部门领导应及时处理。年度预算执行中发生会计交接的，接替的会计人员，必须继续使用移交的账簿连续记账，不得另行自立新账。"},{"i":67,"n":"第六十七条","txt":"会计档案的管理按《会计档案管理办法》执行。"},{"i":68,"n":"第六十八条","txt":"使用电子计算机进行会计核算的，其存贮软件和数据的磁盘、磁带等存贮媒体和打印输出的账、表，单等都是会计档案，在规定的保管期内，应妥善保管，未打印输出的数据不得删除。各部门必须经常对硬盘上的数据，建立软盘备份，备份次数每月不得少于一次，并妥善保管好备份软盘。备份软盘应贴上写保护标签并用印章或封条签封。磁盘会计数据外借使用时，只能使用备份软盘的副本，磁盘和正式备份软盘不得外借使用。"},{"i":69,"n":"第六十九条","txt":"本制度由国务院机关事务管理局负责解释。"},{"i":70,"n":"第七十条","txt":"本制度自一九九八年一月一日起执行。我局一九九一年制定的《中央国家机关行政单位会计制度》同时废止。"}],"hulianwangzongjiaoxinxifuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范互联网宗教信息服务，保障公民宗教信仰自由，根据《中华人民共和国网络安全法》《互联网信息服务管理办法》《宗教事务条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事互联网宗教信息服务，适用本办法。 本办法所称互联网宗教信息服务，包括互联网宗教信息发布服务、转载服务、传播平台服务以及其他与互联网宗教信息相关的服务。"},{"i":3,"n":"第三条","txt":"从事互联网宗教信息服务，应当遵守宪法、法律、法规和规章，践行社会主义核心价值观，坚持我国宗教独立自主自办原则，坚持我国宗教中国化方向，积极引导宗教与社会主义社会相适应，维护宗教和顺、社会和谐、民族和睦。"},{"i":4,"n":"第四条","txt":"互联网宗教信息服务管理坚持保护合法、制止非法、遏制极端、抵御渗透、打击犯罪的原则。"},{"i":5,"n":"第五条","txt":"宗教事务部门依法对互联网宗教信息服务进行监督管理，网信部门、电信主管部门、公安机关、国家安全机关等在各自职责范围内依法负责有关行政管理工作。 省级以上人民政府宗教事务部门应当会同网信部门、电信主管部门、公安机关、国家安全机关等建立互联网宗教信息服务管理协调机制。"},{"i":6,"n":"第六条","txt":"通过互联网站、应用程序、论坛、博客、微博客、公众账号、即时通信工具、网络直播等形式，以文字、图片、音视频等方式向社会公众提供宗教教义教规、宗教知识、宗教文化、宗教活动等信息的服务，应当取得互联网宗教信息服务许可，并具备下列条件： （一）申请人是在中华人民共和国境内依法设立的法人组织或者非法人组织，其法定代表人或者主要负责人是具有中国国籍的内地居民； （二）有熟悉国家宗教政策法规和相关宗教知识的信息审核人员； （三）有健全的互联网宗教信息服务管理制度； （四）有健全的信息安全管理制度和安全可控的技术保障措施； （五）有与服务相匹配的场所、设施和资金； （六）申请人及其法定代表人或者主要负责人近3年内无犯罪记录、无违反国家宗教事务管理有关规定的行为。 境外组织或者个人及其在境内成立的组织不得在境内从事互联网宗教信息服务。"},{"i":7,"n":"第七条","txt":"从事互联网宗教信息服务，应当向所在地省、自治区、直辖市人民政府宗教事务部门提出申请，填报互联网宗教信息服务申请表，并提交下列材料： （一）申请人依法设立或者登记备案的材料以及法定代表人或者主要负责人身份证件； （二）宗教信息审核人员参加宗教政策法规和相关宗教知识的教育培训，以及具备审核能力的情况说明； （三）互联网宗教信息服务管理制度、信息安全管理制度和技术保障措施材料； （四）用于从事互联网宗教信息服务的场所、设施和资金情况说明； （五）申请人及其法定代表人或者主要负责人近3年内无犯罪记录和无违反国家宗教事务管理有关规定情况承诺书； （六）拟从事互联网宗教信息服务的栏目、功能设置和域名注册相关材料。 申请提供互联网宗教信息传播平台服务的，还应当提交平台注册用户管理规章制度、用户协议范本、投诉举报处理机制等。用户协议范本涉及互联网宗教信息服务的内容应当符合本办法有关规定。 互联网宗教信"},{"i":8,"n":"第八条","txt":"从事互联网宗教信息服务所使用的名称，除与申请人名称相同以外，不得使用宗教团体、宗教院校和宗教活动场所等名称，不得含有法律、行政法规禁止的内容。"},{"i":9,"n":"第九条","txt":"省级以上人民政府宗教事务部门自受理申请之日起20日内作出批准或者不予批准的决定。作出批准决定的，核发《互联网宗教信息服务许可证》；作出不予批准决定的，应当书面通知申请人并说明理由。 《互联网宗教信息服务许可证》由国家宗教事务局印制。 申请人取得《互联网宗教信息服务许可证》后，还应当按照国家互联网信息服务管理有关规定办理相关手续。"},{"i":10,"n":"第十条","txt":"从事互联网宗教信息服务，应当在显著位置明示《互联网宗教信息服务许可证》编号。"},{"i":11,"n":"第十一条","txt":"申请人取得《互联网宗教信息服务许可证》后，发生影响许可条件重大事项的，应当报原发证机关审核批准；其他事项变更，应当向原发证机关备案。"},{"i":12,"n":"第十二条","txt":"终止互联网宗教信息服务的，应当自终止之日起30日内，到原发证机关办理注销手续。"},{"i":13,"n":"第十三条","txt":"《互联网宗教信息服务许可证》有效期3年。有效期届满后拟继续从事互联网宗教信息服务的，应当在有效期届满30日前，向原发证机关重新提出申请。"},{"i":14,"n":"第十四条","txt":"互联网宗教信息不得含有下列内容： （一）利用宗教煽动颠覆国家政权、反对中国共产党的领导，破坏社会主义制度、国家统一、民族团结和社会稳定，宣扬极端主义、恐怖主义、民族分裂主义和宗教狂热的； （二）利用宗教妨碍国家司法、教育、婚姻、社会管理等制度实施的； （三）利用宗教宣扬邪教和封建迷信，或者利用宗教损害公民身体健康，欺骗、胁迫取得财物的； （四）违背我国宗教独立自主自办原则的； （五）破坏不同宗教之间、同一宗教内部以及信教公民与不信教公民之间和睦相处的; （六）歧视、侮辱信教公民或者不信教公民，损害信教公民或者不信教公民合法权益的； （七）从事违法宗教活动或者为违法宗教活动提供便利的； （八）诱导未成年人信教，或者组织、强迫未成年人参加宗教活动的； （九）以宗教名义进行商业宣传，经销、发送宗教用品、宗教内部资料性出版物和非法出版物的； （十）假冒宗教教职人员开展活动的； （十一）有关法律"},{"i":15,"n":"第十五条","txt":"取得《互联网宗教信息服务许可证》的宗教团体、宗教院校和寺观教堂，可以且仅限于通过其依法自建的互联网站、应用程序、论坛等由宗教教职人员、宗教院校教师讲经讲道，阐释教义教规中有利于社会和谐、时代进步、健康文明的内容，引导信教公民爱国守法。参与讲经讲道的人员实行实名管理。"},{"i":16,"n":"第十六条","txt":"取得《互联网宗教信息服务许可证》的宗教院校，可以且仅限于通过其依法自建的专用互联网站、应用程序、论坛等开展面向宗教院校学生、宗教教职人员的宗教教育培训。专用互联网站、应用程序、论坛等对外须使用虚拟专用网络连接，并对参加教育培训的人员进行身份验证。"},{"i":17,"n":"第十七条","txt":"除本办法第十五条、第十六条规定的情形外，任何组织或者个人不得在互联网上传教，不得开展宗教教育培训、发布讲经讲道内容或者转发、链接相关内容，不得在互联网上组织开展宗教活动，不得以文字、图片、音视频等方式直播或者录播拜佛、烧香、受戒、诵经、礼拜、弥撒、受洗等宗教仪式。"},{"i":18,"n":"第十八条","txt":"任何组织或者个人不得在互联网上成立宗教组织、设立宗教院校和宗教活动场所、发展教徒。"},{"i":19,"n":"第十九条","txt":"任何组织或者个人不得在互联网上以宗教名义开展募捐。 宗教团体、宗教院校和宗教活动场所发起设立的慈善组织在互联网上开展慈善募捐，应当符合《中华人民共和国慈善法》相关规定。"},{"i":20,"n":"第二十条","txt":"提供互联网宗教信息传播平台服务的，应当与平台注册用户签订协议，核验注册用户真实身份信息。"},{"i":21,"n":"第二十一条","txt":"未取得《互联网宗教信息服务许可证》的互联网信息传播平台，应当加强平台注册用户管理，不得为用户提供互联网宗教信息发布服务。"},{"i":22,"n":"第二十二条","txt":"从事互联网宗教信息服务，发现违反本办法规定的信息的，应当立即停止传输该信息，采取消除等处置措施，防止信息扩散，保存有关记录，并向有关主管部门报告。"},{"i":23,"n":"第二十三条","txt":"宗教事务部门应当加强对互联网宗教信息服务的日常指导、监督、检查，建立互联网宗教信息服务违规档案、失信联合惩戒对象名单和约谈制度，加强对互联网宗教信息服务相关从业人员的专业培训，接受对违法从事互联网宗教信息服务的举报，研判互联网宗教信息，会同网信部门、电信主管部门、公安机关、国家安全机关依法处置违法行为。"},{"i":24,"n":"第二十四条","txt":"网信部门应当加强互联网信息内容管理，依法处置违法互联网宗教信息。"},{"i":25,"n":"第二十五条","txt":"电信主管部门应当加强互联网行业监管，依法配合处置违法从事互联网宗教信息服务的行为。"},{"i":26,"n":"第二十六条","txt":"公安机关应当依法加强互联网信息服务安全监督管理，防范和处置互联网宗教信息服务中的违法犯罪活动。"},{"i":27,"n":"第二十七条","txt":"国家安全机关应当依法防范和处置境外机构、组织、个人，以及境内机构、组织、个人与境外机构、组织、个人相勾结在互联网上利用宗教进行的危害国家安全活动。"},{"i":28,"n":"第二十八条","txt":"申请人隐瞒有关情况或者提供虚假材料申请互联网宗教信息服务许可的，宗教事务部门不予受理或者不予许可，已经许可的应当依法撤销许可，并给予警告。 擅自从事互联网宗教信息服务的，由宗教事务部门会同电信主管部门依据职责责令停止相关服务活动。"},{"i":29,"n":"第二十九条","txt":"违反本办法第十条、第十一条、第十四条、第十五条、第十六条、第十七条、第十八条、第十九条规定的，由宗教事务部门责令限期改正；拒不改正的，会同网信部门、电信主管部门、公安机关、国家安全机关等依照有关法律、行政法规的规定给予处罚。"},{"i":30,"n":"第三十条","txt":"互联网宗教信息传播平台注册用户违反本办法规定的，由宗教事务部门会同网信部门、公安机关责令互联网宗教信息传播平台提供者依法依约采取警示整改、限制功能直至关闭账号等处置措施。"},{"i":31,"n":"第三十一条","txt":"违反本办法规定，同时还违反《互联网信息服务管理办法》及国家对互联网新闻信息服务、互联网视听节目服务、网络出版服务等相关管理规定的，由宗教事务部门、网信部门、电信主管部门、公安机关、广播电视主管部门、电影主管部门、出版主管部门等依法处置。"},{"i":32,"n":"第三十二条","txt":"国家工作人员在互联网宗教信息服务管理工作中滥用职权、玩忽职守、徇私舞弊，依法给予处分。"},{"i":33,"n":"第三十三条","txt":"违反本办法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"本办法施行前已经从事互联网宗教信息服务的，应当自本办法施行之日起6个月内依照本办法有关规定办理相关手续。"},{"i":35,"n":"第三十五条","txt":"本办法由国家宗教事务局、国家互联网信息办公室、工业和信息化部、公安部和国家安全部负责解释。"},{"i":36,"n":"第三十六条","txt":"本办法自2022年3月1日起施行。"}],"hulianwangzhuzuoquanxingzhengbaohubanfa":[{"i":1,"n":"第一条","txt":"为了加强互联网信息服务活动中信息网络传播权的行政保护，规范行政执法行为，根据《中华人民共和国著作权法》及有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于互联网信息服务活动中根据互联网内容提供者的指令，通过互联网自动提供作品、录音录像制品等内容的上载、存储、链接或搜索等功能，且对存储或传输的内容不进行任何编辑、修改或选择的行为。 互联网信息服务活动中直接提供互联网内容的行为，适用著作权法。 本办法所称“互联网内容提供者”是指在互联网上发布相关内容的上网用户。"},{"i":3,"n":"第三条","txt":"各级著作权行政管理部门依照法律、行政法规和本办法对互联网信息服务活动中的信息网络传播权实施行政保护。国务院信息产业主管部门和各省、自治区、直辖市电信管理机构依法配合相关工作。"},{"i":4,"n":"第四条","txt":"著作权行政管理部门对侵犯互联网信息服务活动中的信息网络传播权的行为实施行政处罚，适用《著作权行政处罚实施办法》。 侵犯互联网信息服务活动中的信息网络传播权的行为由侵权行为实施地的著作权行政管理部门管辖。侵权行为实施地包括提供本办法第二条所列的互联网信息服务活动的服务器等设备所在地。"},{"i":5,"n":"第五条","txt":"著作权人发现互联网传播的内容侵犯其著作权，向互联网信息服务提供者或者其委托的其他机构（以下统称“互联网信息服务提供者”）发出通知后，互联网信息服务提供者应当立即采取措施移除相关内容，并保留著作权人的通知6个月。"},{"i":6,"n":"第六条","txt":"互联网信息服务提供者收到著作权人的通知后，应当记录提供的信息内容及其发布的时间、互联网地址或者域名。互联网接入服务提供者应当记录互联网内容提供者的接入时间、用户帐号、互联网地址或者域名、主叫电话号码等信息。 前款所称记录应当保存60日，并在著作权行政管理部门查询时予以提供。"},{"i":7,"n":"第七条","txt":"互联网信息服务提供者根据著作权人的通知移除相关内容的，互联网内容提供者可以向互联网信息服务提供者和著作权人一并发出说明被移除内容不侵犯著作权的反通知。反通知发出后，互联网信息服务提供者即可恢复被移除的内容，且对该恢复行为不承担行政法律责任。"},{"i":8,"n":"第八条","txt":"著作权人的通知应当包含以下内容： （一）涉嫌侵权内容所侵犯的著作权权属证明； （二）明确的身份证明、住址、联系方式； （三）涉嫌侵权内容在信息网络上的位置； （四）侵犯著作权的相关证据； （五）通知内容的真实性声明。"},{"i":9,"n":"第九条","txt":"互联网内容提供者的反通知应当包含以下内容： （一）明确的身份证明、住址、联系方式； （二）被移除内容的合法性证明； （三）被移除内容在互联网上的位置； （四）反通知内容的真实性声明。"},{"i":10,"n":"第十条","txt":"著作权人的通知和互联网内容提供者的反通知应当采取书面形式。 著作权人的通知和互联网内容提供者的反通知不具备本办法第八条、第九条所规定内容的，视为未发出。"},{"i":11,"n":"第十一条","txt":"互联网信息服务提供者明知互联网内容提供者通过互联网实施侵犯他人著作权的行为，或者虽不明知，但接到著作权人通知后未采取措施移除相关内容，同时损害社会公共利益的，著作权行政管理部门可以根据《中华人民共和国著作权法》第四十七条的规定责令停止侵权行为，并给予下列行政处罚： （一）没收违法所得； （二）处以非法经营额3倍以下的罚款；非法经营额难以计算的，可以处10万元以下的罚款。"},{"i":12,"n":"第十二条","txt":"没有证据表明互联网信息服务提供者明知侵权事实存在的，或者互联网信息服务提供者接到著作权人通知后，采取措施移除相关内容的，不承担行政法律责任。"},{"i":13,"n":"第十三条","txt":"著作权行政管理部门在查处侵犯互联网信息服务活动中的信息网络传播权案件时，可以按照《著作权行政处罚实施办法》第十二条规定要求著作权人提交必备材料，以及向互联网信息服务提供者发出的通知和该互联网信息服务提供者未采取措施移除相关内容的证明。"},{"i":14,"n":"第十四条","txt":"互联网信息服务提供者有本办法第十一条规定的情形，且经著作权行政管理部门依法认定专门从事盗版活动，或有其他严重情节的，国务院信息产业主管部门或者省、自治区、直辖市电信管理机构依据相关法律、行政法规的规定处理；互联网接入服务提供者应当依据国务院信息产业主管部门或者省、自治区、直辖市电信管理机构的通知，配合实施相应的处理措施。"},{"i":15,"n":"第十五条","txt":"互联网信息服务提供者未履行本办法第六条规定的义务，由国务院信息产业主管部门或者省、自治区、直辖市电信管理机构予以警告，可以并处三万元以下罚款。"},{"i":16,"n":"第十六条","txt":"著作权行政管理部门在查处侵犯互联网信息服务活动中的信息网络传播权案件过程中，发现互联网信息服务提供者的行为涉嫌构成犯罪的，应当依照国务院《行政执法机关移送涉嫌犯罪案件的规定》将案件移送司法部门，依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"表演者、录音录像制作者等与著作权有关的权利人通过互联网向公众传播其表演或者录音录像制品的权利的行政保护适用本办法。"},{"i":18,"n":"第十八条","txt":"本办法由国家版权局和信息产业部负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自2005年5月30日起施行。"}],"renleiyichuanziyuanguanlitiaolishishixize":[{"i":1,"n":"第一条","txt":"为有效保护和合理利用我国人类遗传资源，维护公众健康、国家安全和社会公共利益，根据《中华人民共和国生物安全法》《中华人民共和国人类遗传资源管理条例》（以下称《条例》）等有关法律、行政法规，制定本实施细则。"},{"i":2,"n":"第二条","txt":"采集、保藏、利用、对外提供我国人类遗传资源，应当遵守本实施细则。 《条例》第二条所称人类遗传资源信息包括利用人类遗传资源材料产生的人类基因、基因组数据等信息资料。 前款所称人类遗传资源信息不包括临床数据、影像数据、蛋白质数据和代谢数据。"},{"i":3,"n":"第三条","txt":"科学技术部（以下称科技部）负责全国人类遗传资源调查、行政许可、监督检查、行政处罚等管理工作。 科技部根据需要依法委托相关组织，开展人类遗传资源行政许可申请材料的形式审查、技术评审，以及人类遗传资源备案、事先报告、监督检查、行政处罚等工作。"},{"i":4,"n":"第四条","txt":"省、自治区、直辖市科学技术厅（委、局）、新疆生产建设兵团科学技术局（以下称省级科技行政部门）负责本区域下列人类遗传资源管理工作： （一）人类遗传资源监督检查与日常管理； （二）职权范围内的人类遗传资源违法案件调查处理； （三）根据科技部委托，开展本区域人类遗传资源调查、人类遗传资源行政许可、人类遗传资源违法案件调查处理等工作。"},{"i":5,"n":"第五条","txt":"科技部和省级科技行政部门应当加强人类遗传资源监管力量，配备行政执法人员，依职权对人类遗传资源活动开展监督检查等工作，依法履行人类遗传资源监督管理职责。"},{"i":6,"n":"第六条","txt":"科技部聘请生命科学与技术、医药、卫生、伦理、法律、信息安全等方面的专家组成人类遗传资源管理专家咨询委员会，为全国人类遗传资源管理工作提供决策咨询和技术支撑。"},{"i":7,"n":"第七条","txt":"科技部支持合理利用人类遗传资源开展科学研究、发展生物医药产业、提高诊疗技术，加强人类遗传资源管理与监督，优化审批服务，提高审批效率，推进审批规范化和信息公开，提升管理和服务水平。"},{"i":8,"n":"第八条","txt":"采集、保藏、利用、对外提供我国人类遗传资源，应当符合伦理原则，通过已在有关管理部门备案的伦理（审查）委员会的伦理审查。开展伦理审查应当遵守法律、行政法规和国家有关规定。"},{"i":9,"n":"第九条","txt":"采集、保藏、利用、对外提供我国人类遗传资源，应当尊重和保障人类遗传资源提供者的隐私权和个人信息等权益，按规定获取书面知情同意，确保人类遗传资源提供者的合法权益不受侵害。"},{"i":10,"n":"第十条","txt":"采集、保藏、利用、对外提供我国人类遗传资源，应当遵守科技活动的相关要求及技术规范，包括但不限于标准、规范、规程等。"},{"i":11,"n":"第十一条","txt":"在我国境内采集、保藏我国人类遗传资源或者向境外提供我国人类遗传资源，必须由我国科研机构、高等学校、医疗机构或者企业（以下称中方单位）开展。设在港澳的内资实控机构视为中方单位。 境外组织及境外组织、个人设立或者实际控制的机构（以下称外方单位）以及境外个人不得在我国境内采集、保藏我国人类遗传资源，不得向境外提供我国人类遗传资源。"},{"i":12,"n":"第十二条","txt":"本实施细则第十一条所称境外组织、个人设立或者实际控制的机构，包括下列情形： （一）境外组织、个人持有或者间接持有机构百分之五十以上的股份、股权、表决权、财产份额或者其他类似权益； （二）境外组织、个人持有或者间接持有机构的股份、股权、表决权、财产份额或者其他类似权益不足百分之五十，但其所享有的表决权或者其他权益足以对机构的决策、管理等行为进行支配或者施加重大影响； （三）境外组织、个人通过投资关系、协议或者其他安排，足以对机构的决策、管理等行为进行支配或者施加重大影响； （四）法律、行政法规、规章规定的其他情形。"},{"i":13,"n":"第十三条","txt":"采集、保藏、利用、对外提供我国人类遗传资源的单位应当加强管理制度建设，对涉及人类遗传资源开展科学研究的目的和研究方案等事项进行审查，确保人类遗传资源合法使用。"},{"i":14,"n":"第十四条","txt":"利用我国人类遗传资源开展国际科学研究合作，应当保证中方单位及其研究人员全过程、实质性地参与研究，依法分享相关权益。国际科学研究合作过程中，利用我国人类遗传资源产生的所有记录以及数据信息等应当完全向中方单位开放，并向中方单位提供备份。"},{"i":15,"n":"第十五条","txt":"科技部加强人类遗传资源管理信息化建设，建立公开统一的人类遗传资源行政许可、备案与安全审查工作信息系统平台，为申请人通过互联网办理行政许可、备案等事项提供便利，推进实时动态管理，实现人类遗传资源管理信息可追溯、可查询。"},{"i":16,"n":"第十六条","txt":"科技部会同国务院有关部门及省级科技行政部门推动我国科研机构、高等学校、医疗机构和企业依法依规开展人类遗传资源保藏工作，推进标准化、规范化的人类遗传资源保藏基础平台和大数据建设，并依照国家有关规定向有关科研机构、高等学校、医疗机构和企业开放。"},{"i":17,"n":"第十七条","txt":"针对公共卫生事件等突发事件，科技部建立快速审批机制，对突发事件应急处置中涉及的人类遗传资源行政许可申请，应当加快办理。 对实施快速审批的人类遗传资源行政许可申请，科技部按照统一指挥、高效快速、科学审批的原则，加快组织开展行政许可申请的受理、评审、审查等工作。快速审批的情形、程序、时限、要求等事项由科技部另行规定。"},{"i":18,"n":"第十八条","txt":"科技部制定并及时发布采集、保藏、利用、对外提供我国人类遗传资源行政许可、备案等服务指南和示范文本，为申请人办理人类遗传资源行政许可、备案等事项提供便捷和专业的指导和服务。"},{"i":19,"n":"第十九条","txt":"科技部定期对从事人类遗传资源采集、保藏、利用、对外提供等活动的科研人员和相关部门管理人员进行培训，增强法律意识和责任意识，提升管理服务能力。"},{"i":20,"n":"第二十条","txt":"科技部和省级科技行政部门应当建立并不断完善廉政风险防控措施，健全监督制约机制，加强对本机关人类遗传资源管理重要环节和关键岗位的监督。"},{"i":21,"n":"第二十一条","txt":"科技部负责组织开展全国人类遗传资源调查工作。省级科技行政部门受科技部委托，负责开展本区域人类遗传资源调查工作。"},{"i":22,"n":"第二十二条","txt":"全国人类遗传资源调查每五年开展一次，必要时可以根据实际需要开展。"},{"i":23,"n":"第二十三条","txt":"科技部组织相关领域专家制定全国人类遗传资源调查工作方案。省级科技行政部门完成本区域人类遗传资源调查工作后，应当将取得的调查数据、信息及时汇总并报送科技部。"},{"i":24,"n":"第二十四条","txt":"科技部在全国人类遗传资源调查等工作基础上，组织开展重要遗传家系和特定地区人类遗传资源研究，逐步建立我国重要遗传家系和特定地区人类遗传资源清单目录，并适时修订完善。"},{"i":25,"n":"第二十五条","txt":"科技部负责重要遗传家系和特定地区人类遗传资源登记工作，制定申报登记管理办法，建立申报登记管理信息服务平台。"},{"i":26,"n":"第二十六条","txt":"我国科研机构、高等学校、医疗机构、企业发现重要遗传家系和特定地区人类遗传资源，应当及时通过申报登记管理信息服务平台进行申报。"},{"i":27,"n":"第二十七条","txt":"人类遗传资源采集行政许可适用于拟在我国境内开展的下列活动： （一）重要遗传家系人类遗传资源采集活动。重要遗传家系是指患有遗传性疾病、具有遗传性特殊体质或者生理特征的有血缘关系的群体，且该群体中患有遗传性疾病、具有遗传性特殊体质或者生理特征的成员涉及三代或者三代以上，高血压、糖尿病、红绿色盲、血友病等常见疾病不在此列。首次发现的重要遗传家系应当按照本实施细则第二十六条规定及时进行申报。 （二）特定地区人类遗传资源采集活动。特定地区人类遗传资源是指在隔离或者特殊环境下长期生活，并具有特殊体质特征或者在生理特征方面有适应性性状发生的人类遗传资源。特定地区不以是否为少数民族聚居区为划分依据。 （三）用于大规模人群研究且人数大于3000例的人类遗传资源采集活动。大规模人群研究包括但不限于队列研究、横断面研究、临床研究、体质学研究等。为取得相关药品和医疗器械在我国上市许可的临床试验涉及的人类遗传资"},{"i":28,"n":"第二十八条","txt":"人类遗传资源保藏行政许可适用于在我国境内开展人类遗传资源保藏、为科学研究提供基础平台的活动。 人类遗传资源保藏活动是指将有合法来源的人类遗传资源保存在适宜环境条件下，保证其质量和安全，用于未来科学研究的行为，不包括以教学为目的、在实验室检测后按照法律法规要求或者临床研究方案约定的临时存储行为。"},{"i":29,"n":"第二十九条","txt":"应当申请行政许可的人类遗传资源保藏活动同时涉及人类遗传资源采集的，申请人仅需要申请人类遗传资源保藏行政许可，无需另行申请人类遗传资源采集行政许可。"},{"i":30,"n":"第三十条","txt":"人类遗传资源保藏单位应当依据《条例》第十五条规定，于每年1月31日前向科技部提交上一年度本单位保藏人类遗传资源情况年度报告。年度报告应当载明下列内容： （一）保藏的人类遗传资源情况； （二）人类遗传资源来源信息和使用信息； （三）人类遗传资源保藏相关管理制度的执行情况； （四）本单位用于保藏人类遗传资源的场所、设施、设备的维护和变动情况； （五）本单位负责保藏工作的主要管理人员变动情况。 人类遗传资源保藏单位应当加强管理，确保保藏的人类遗传资源来源合法。科技部组织各省级科技行政部门每年对本区域人类遗传资源保藏单位的保藏活动进行抽查。"},{"i":31,"n":"第三十一条","txt":"申请人类遗传资源国际科学研究合作行政许可，应当通过合作双方各自所在国（地区）的伦理审查。外方单位确无法提供所在国（地区）伦理审查证明材料的，可以提交外方单位认可中方单位伦理审查意见的证明材料。"},{"i":32,"n":"第三十二条","txt":"为取得相关药品和医疗器械在我国上市许可，在临床医疗卫生机构利用我国人类遗传资源开展国际合作临床试验、不涉及人类遗传资源材料出境的，不需要批准，但应当符合下列情况之一，并在开展临床试验前将拟使用的人类遗传资源种类、数量及其用途向科技部备案： （一）涉及的人类遗传资源采集、检测、分析和剩余人类遗传资源材料处理等在临床医疗卫生机构内进行； （二）涉及的人类遗传资源在临床医疗卫生机构内采集，并由相关药品和医疗器械上市许可临床试验方案指定的境内单位进行检测、分析和剩余样本处理。 前款所称临床医疗卫生机构是指在我国相关部门备案，依法开展临床试验的医疗机构、疾病预防控制机构等。 为取得相关药品和医疗器械在我国上市许可的临床试验涉及的探索性研究部分，应当申请人类遗传资源国际科学研究合作行政许可。"},{"i":33,"n":"第三十三条","txt":"国际科学研究合作行政许可、国际合作临床试验备案应当由中方单位和外方单位共同申请。合作各方应当对申请材料信息的真实性、准确性、完整性作出承诺。 拟开展的人类遗传资源国际科学研究合作、国际合作临床试验涉及多中心临床研究的，不得拆分后申请行政许可或者备案。"},{"i":34,"n":"第三十四条","txt":"开展多中心临床研究的，组长单位通过伦理审查后即可由申办方或者组长单位申请行政许可或者备案。 申办方或者组长单位取得行政许可或者完成备案后，参与临床研究的医疗卫生机构将本单位伦理审查批件或者认可组长单位所提供伦理审查批件的证明材料以及本单位出具的承诺书提交科技部，即可开展国际合作临床研究。"},{"i":35,"n":"第三十五条","txt":"取得国际科学研究合作行政许可或者完成国际合作临床试验备案的合作双方，应当在行政许可或者备案有效期限届满后六个月内，共同向科技部提交合作研究情况报告。合作研究情况报告应当载明下列内容： （一）研究目的、内容等事项变化情况； （二）研究方案执行情况； （三）研究内容完成情况； （四）我国人类遗传资源使用、处置情况； （五）研究过程中的所有记录以及数据信息的记录、储存、使用等情况； （六）中方单位及其研究人员全过程、实质性参与研究情况以及外方单位参与研究情况； （七）研究成果产出、归属与权益分配情况； （八）研究涉及的伦理审查情况。"},{"i":36,"n":"第三十六条","txt":"将人类遗传资源信息向境外组织、个人及其设立或者实际控制的机构提供或者开放使用的，中方信息所有者应当向科技部事先报告并提交信息备份。向科技部事先报告应当报送下列事项信息： （一）向境外组织、个人及其设立或者实际控制的机构提供或者开放使用我国人类遗传资源信息的目的、用途； （二）向境外组织、个人及其设立或者实际控制的机构提供或者开放使用我国人类遗传资源信息及信息备份情况； （三）接收人类遗传资源信息的境外组织、个人及其设立或者实际控制的机构的基本情况； （四）向境外组织、个人及其设立或者实际控制的机构提供或者开放使用对我国人类遗传资源保护的潜在风险评估情况。 已取得行政许可的国际科学研究合作或者已完成备案的国际合作临床试验实施过程中，中方单位向外方单位提供合作产生的人类遗传资源信息的，如国际合作协议中已约定由合作双方使用，不需要单独事先报告和提交信息备份。"},{"i":37,"n":"第三十七条","txt":"将人类遗传资源信息向境外组织、个人及其设立或者实际控制的机构提供或者开放使用，可能影响我国公众健康、国家安全和社会公共利益的，应当通过科技部组织的安全审查。 应当进行安全审查的情形包括： （一）重要遗传家系的人类遗传资源信息； （二）特定地区的人类遗传资源信息； （三）人数大于500例的外显子组测序、基因组测序信息资源； （四）可能影响我国公众健康、国家安全和社会公共利益的其他情形。"},{"i":38,"n":"第三十八条","txt":"科技部会同相关部门制定安全审查规则，组织相关领域专家进行安全评估，并根据安全评估意见作出审查决定。 人类遗传资源出口过程中如相关物项涉及出口管制范围，须遵守国家出口管制法律法规。"},{"i":39,"n":"第三十九条","txt":"申请人的申请材料齐全、形式符合规定的，科技部应当受理并出具加盖专用印章和注明日期的纸质或者电子凭证。 申请材料不齐全或者不符合法定形式的，科技部应当在收到正式申请材料之日起五个工作日内一次性告知申请人需要补正的全部内容。"},{"i":40,"n":"第四十条","txt":"科技部根据技术评审和安全审查工作需要，组建专家库并建立专家管理制度。 科技部按照随机抽取方式从专家库中选取评审专家，对人类遗传资源行政许可申请事项进行技术评审，对应当进行安全审查的人类遗传资源信息对外提供或者开放使用事项进行安全评估。技术评审意见、安全评估意见作为作出行政许可决定或者安全审查决定的参考依据。 专家参与技术评审和安全审查一般采用网络方式，必要时可以采用会议、现场勘查等方式。"},{"i":41,"n":"第四十一条","txt":"科技部应当自受理之日起二十个工作日内，对人类遗传资源行政许可申请作出行政许可决定。二十个工作日内不能作出行政许可决定的，经科技部负责人批准，可以延长十个工作日，并将延长期限的理由告知申请人。"},{"i":42,"n":"第四十二条","txt":"科技部作出行政许可决定，依法需要听证、检验、检测、检疫、鉴定、技术评审的，所需时间不计算在本实施细则第四十一条规定的期限内，但应当将所需时间书面告知申请人。"},{"i":43,"n":"第四十三条","txt":"科技部作出行政许可决定后，应当将行政许可决定书面告知申请人，并抄送申请人所在地的省级科技行政部门。 依法作出准予行政许可决定的，应当在科技部网站予以公开。依法作出不予行政许可决定的，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":44,"n":"第四十四条","txt":"取得人类遗传资源采集行政许可后，采集活动参与单位、采集目的、采集方案或者采集内容等重大事项发生变更的，被许可人应当向科技部提出变更申请。"},{"i":45,"n":"第四十五条","txt":"取得人类遗传资源保藏行政许可后，保藏目的、保藏方案或者保藏内容等重大事项发生变更的，被许可人应当向科技部提出变更申请。"},{"i":46,"n":"第四十六条","txt":"取得人类遗传资源国际科学研究合作行政许可后，开展国际科学研究合作过程中，研究目的、研究内容发生变更，研究方案涉及的人类遗传资源种类、数量、用途发生变更，或者申办方、组长单位、合同研究组织、第三方实验室等其他重大事项发生变更的，被许可人应当向科技部提出变更申请。"},{"i":47,"n":"第四十七条","txt":"取得人类遗传资源国际科学研究合作行政许可后，出现下列情形的，被许可人不需要提出变更申请，但应当向科技部提交事项变更的书面说明及相应材料： 研究内容或者研究方案不变，仅涉及总量累计不超过获批数量10%变更的； 本实施细则第四十六条所列合作单位以外的参与单位发生变更的； 合作方法人单位名称发生变更的； 研究内容或者研究方案发生变更，但不涉及人类遗传资源种类、数量、用途的变化或者变更后内容不超出已批准范围的。"},{"i":48,"n":"第四十八条","txt":"被许可人对本实施细则第四十四条至第四十六条所列事项提出变更申请的，科技部应当审查并作出是否准予变更的决定。符合法定条件、标准的，科技部应当予以变更。 变更申请的受理、审查、办理期限、决定、告知等程序参照本实施细则第三十九条至第四十三条有关行政许可申请的规定执行。"},{"i":49,"n":"第四十九条","txt":"行政许可决定作出前，申请人书面撤回申请的，科技部终止对行政许可申请的审查。"},{"i":50,"n":"第五十条","txt":"有下列情形之一的，科技部根据利害关系人请求或者依据职权，可以撤销人类遗传资源行政许可： （一）滥用职权、玩忽职守作出准予行政许可决定的; （二）超越法定职权作出准予行政许可决定的; （三）违反法定程序作出准予行政许可决定的; （四）对不具备申请资格或者不符合法定条件的申请人准予行政许可的; （五）依法可以撤销行政许可的其他情形。 被许可人以欺骗、贿赂等不正当手段取得行政许可的，科技部应当予以撤销。 依照前两款的规定撤销行政许可，可能对公共利益造成重大损害的，不予撤销。"},{"i":51,"n":"第五十一条","txt":"申请国际合作临床试验备案的，应当事先取得药品监督管理部门临床试验批件、通知书或者备案登记材料。"},{"i":52,"n":"第五十二条","txt":"申请国际合作临床试验备案，应当提交下列材料： （一）合作各方基本情况； （二）研究涉及使用的人类遗传资源种类、数量和用途； （三）研究方案； （四）组长单位伦理审查批件； （五）其他证明材料。"},{"i":53,"n":"第五十三条","txt":"国际合作临床试验完成备案后，涉及的人类遗传资源种类、数量、用途发生变更，或者合作方、研究方案、研究内容、研究目的等重大事项发生变更的，备案人应当及时办理备案变更。 研究方案或者研究内容变更不涉及人类遗传资源种类、数量、用途变化的，不需要办理备案变更，但应当在变更活动开始前向科技部提交事项变更的书面说明及相应材料。"},{"i":54,"n":"第五十四条","txt":"向境外组织、个人及其设立或者实际控制的机构提供或者开放使用人类遗传资源信息向科技部事先报告后，用途、接收方等事项发生变更的，应当在变更事项实施前向科技部提交事项变更报告。"},{"i":55,"n":"第五十五条","txt":"被许可人需要延续行政许可有效期的，应当在该行政许可有效期限届满三十个工作日前向科技部提出申请。科技部应当根据被许可人的申请，在该行政许可有效期限届满前作出是否准予延续的决定；逾期未作出决定的，视为准予延续。 备案人需要延续备案有效期的，应当在该备案有效期限届满三十个工作日前向科技部提出申请。科技部应当在该备案有效期限届满前完成延续备案；逾期未完成的，视为已完成延续备案。"},{"i":56,"n":"第五十六条","txt":"科技部负责全国人类遗传资源监督检查，各省级科技行政部门负责本区域人类遗传资源监督检查。监督检查事项主要包括： （一）人类遗传资源采集、保藏、利用、对外提供有关单位落实主体责任，建立、完善和执行有关规章制度的情况； （二）获批人类遗传资源项目的有关单位采集、保藏、利用人类遗传资源的情况，材料或者信息出境、对外提供、开放使用以及出境后使用情况； （三）利用人类遗传资源的剩余材料处置、知识产权及利益分享等情况； （四）人类遗传资源备案事项的真实性等情况； （五）科技部或者省级科技行政部门认为需要监督检查的其他事项。"},{"i":57,"n":"第五十七条","txt":"科技部和省级科技行政部门应当编制年度监督检查计划，实施人类遗传资源风险管理。 年度监督检查计划应当包括检查事项、检查方式、检查频次以及抽查项目种类、抽查比例等内容。"},{"i":58,"n":"第五十八条","txt":"对近三年内因人类遗传资源违法行为被实施过行政处罚、存在人类遗传资源管理风险未及时改正，以及被记入相关失信惩戒名单的单位，科技部和省级科技行政部门应当加大监督检查频次，纳入年度日常监督检查计划并开展监督检查。对管理体系和管理规范明显改进、未再发生违法行为的单位，可以适时减少监督检查频次。"},{"i":59,"n":"第五十九条","txt":"对本实施细则第五十八条规定以外的其他单位，科技部和省级科技行政部门可以在该单位人类遗传资源活动范围内随机确定监督检查事项，随机选派监督检查人员，实施监督检查。"},{"i":60,"n":"第六十条","txt":"遇有严重违法行为或者临时性、突发性任务以及通过投诉举报、转办交办、数据监测等发现的问题，科技部和省级科技行政部门可以部署开展专项监督检查。"},{"i":61,"n":"第六十一条","txt":"科技部和省级科技行政部门应当及时记录、汇总人类遗传资源活动日常监督检查信息，完善日常监督检查措施。"},{"i":62,"n":"第六十二条","txt":"发现被监督检查对象可能存在违反《条例》有关规定的风险时，科技部或者省级科技行政部门可以对其法定代表人、主要负责人等进行行政约谈。"},{"i":63,"n":"第六十三条","txt":"发现被监督检查对象可能存在违反《条例》规定的行为，科技部或者省级科技行政部门应当进行调查，必要时可以采取下列措施： （一）依法采取记录、复制、拍照、录像等措施； （二）依法采取查封、扣押等行政强制措施； （三）依法对相关物品进行检测、检验、检疫或者鉴定。"},{"i":64,"n":"第六十四条","txt":"科技部或者省级科技行政部门实施行政强制措施应当依照《中华人民共和国行政强制法》规定的程序进行。"},{"i":65,"n":"第六十五条","txt":"科技部和省级科技行政部门采取或者解除行政强制措施，应当经本机关负责人批准。 依法实施查封、扣押强制措施的，应当制作并当场向当事人交付查封、扣押决定书和清单。情况紧急，不及时查封、扣押可能影响案件查处，或者存在可能导致人类遗传资源损毁灭失等隐患，可以先行实施查封、扣押，并在二十四小时内补办查封、扣押决定书，送达当事人。"},{"i":66,"n":"第六十六条","txt":"科技部和省级科技行政部门应当规范行使人类遗传资源行政处罚裁量权，综合考虑违法行为的事实、性质、情节以及社会危害程度，在《条例》规定范围内合理确定行政处罚的种类和幅度，确保过罚相当，防止畸轻畸重。 人类遗传资源行政处罚裁量基准由科技部另行制定并向社会公布。"},{"i":67,"n":"第六十七条","txt":"拟给予行政处罚的案件，科技部和省级科技行政部门在作出行政处罚决定之前，应当书面告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有陈述、申辩的权利。拟作出的行政处罚属于听证范围的，还应当告知当事人有要求听证的权利。 当事人行使陈述、申辩权或者要求听证的，应当自告知书送达之日起五个工作日内书面提出，逾期未提出的，视为放弃上述权利。 科技部和省级科技行政部门不得因当事人陈述、申辩或者听证而给予更重的处罚。"},{"i":68,"n":"第六十八条","txt":"科技部或者省级科技行政部门拟作出下列行政处罚决定，当事人要求听证的，应当组织听证： （一）对法人、其他组织处以一百万元以上罚款或者对公民处以十万元以上罚款的； （二）没收法人、其他组织违法所得三百万元以上或者没收公民违法所得三十万元以上的； （三）禁止一年以上从事采集、保藏、利用、对外提供我国人类遗传资源活动的； （四）二年以上不受理人类遗传资源行政许可申请的； （五）撤销已取得的人类遗传资源行政许可的； （六）法律、行政法规规定应当组织听证的其他情形。"},{"i":69,"n":"第六十九条","txt":"科技部或者省级科技行政部门作出人类遗传资源行政处罚决定前，本部门案件办理机构应当将拟作出的行政处罚决定及案件材料送本部门负责法制审核的工作机构进行法制审核。未经法制审核或者审核未通过的，不得作出决定。 拟作出的行政处罚决定仅涉及警告的，不需要进行法制审核。"},{"i":70,"n":"第七十条","txt":"行政处罚决定书作出后，科技部或者省级科技行政部门应当在七个工作日内依照有关法律规定，将行政处罚决定书送达当事人或者其他的法定受送达人。"},{"i":71,"n":"第七十一条","txt":"行政处罚决定应当自立案之日起九十日内作出。案情复杂，不能在九十日内作出行政处罚决定的，经本机关负责人批准，可以延长九十日。案情特别复杂，经延期仍不能作出行政处罚决定的，经本机关负责人集体讨论决定是否继续延期。决定延期的，应当同时确定延长的合理期限，但最长不得超过六十日。 案件办理过程中，听证、公告、检测、检验、检疫、鉴定、审计、中止等时间，不计入本条第一款所指的案件办理期限。"},{"i":72,"n":"第七十二条","txt":"《条例》第三十六条、第三十九条、第四十一条、第四十二条、第四十三条规定的违法所得，以实施违法行为所获得的全部收入扣除适当的合理支出计算；难以计算的，以违法行为涉及的人类遗传资源价值计算或者为人类遗传资源投入的资金数额作为违法所得。"},{"i":73,"n":"第七十三条","txt":"在人类遗传资源监督检查或者违法案件调查处理中，发现相关公民、法人或者其他组织不具备人类遗传资源存储条件的，科技部或者省级科技行政部门应当组织将其存储的人类遗传资源转移至具备存储条件的单位临时存储。"},{"i":74,"n":"第七十四条","txt":"省级科技行政部门依法作出人类遗传资源行政处罚的，应当自行政处罚决定作出之日起十五个工作日内将案件处理情况及行政处罚决定书副本报送科技部。"},{"i":75,"n":"第七十五条","txt":"科技部有权对省级科技行政部门实施的人类遗传资源行政处罚进行监督，依法对有关违法或者不当行为责令改正。"},{"i":76,"n":"第七十六条","txt":"本实施细则中涉及期限的规定，注明为工作日的，不包含法定节假日；未注明为工作日的，为自然日。"},{"i":77,"n":"第七十七条","txt":"本实施细则所称“以上”“不超过”均包含本数，“大于”“不足”不包含本数。"},{"i":78,"n":"第七十八条","txt":"本实施细则自2023年7月1日施行。"}],"yisilanjiaochaojinshiwuguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了保障公民宗教信仰自由，坚持我国宗教中国化方向，规范伊斯兰教朝觐事务管理，维护朝觐活动正常秩序，根据《中华人民共和国出境入境管理法》《中华人民共和国国境卫生检疫法》《宗教事务条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"信仰伊斯兰教的中国公民前往沙特阿拉伯麦加朝觐，由中国伊斯兰教协会负责组织。其他任何组织或者个人不得组织朝觐活动。"},{"i":3,"n":"第三条","txt":"国家宗教事务局负责归口管理全国伊斯兰教朝觐事务。地方各级人民政府宗教事务部门负责归口管理本地伊斯兰教朝觐事务。"},{"i":4,"n":"第四条","txt":"人民政府外事、公安、移民管理、卫生健康、文化旅游、海关、市场监管、民航等有关部门在各自职责范围内负责伊斯兰教朝觐事务管理工作。"},{"i":5,"n":"第五条","txt":"信仰伊斯兰教的中国公民的朝觐活动，应当有组织、有计划、有秩序和依法进行。"},{"i":6,"n":"第六条","txt":"地方各级人民政府宗教事务部门在当地人民政府领导下，牵头协调开展非法朝觐活动综合治理工作，做好政策法规宣传和教育引导，依法制止非法朝觐活动。 人民政府公安、文化旅游、市场监管等部门应当对有关中介机构、旅行社及相关企业进行监督管理，依法制止利用商务、旅游、探亲等进行的非法朝觐活动，依法查处非法朝觐活动组织者。"},{"i":7,"n":"第七条","txt":"中国公民每年朝觐数额，根据国际通行做法，结合我国经济社会发展状况确定。"},{"i":8,"n":"第八条","txt":"朝觐名额分配和朝觐人员确定应当遵循公开、公平、公正原则。 国家工作人员和伊斯兰教协会人员等不得利用职权或者职务上的影响干涉朝觐报名排队和朝觐人员确定。"},{"i":9,"n":"第九条","txt":"省级人民政府宗教事务部门应当综合考虑本地经济发展水平、伊斯兰教协会组织能力、群众生活条件及朝觐需求等因素，每年向国家宗教事务局申报拟参加朝觐名额。"},{"i":10,"n":"第十条","txt":"国家宗教事务局征求中国伊斯兰教协会意见后，确定年度全国朝觐总名额及各省、自治区、直辖市朝觐名额。"},{"i":11,"n":"第十一条","txt":"地方各级人民政府宗教事务部门应当将本地全部朝觐名额逐级进行分配。"},{"i":12,"n":"第十二条","txt":"公民申请朝觐，应当具备以下基本条件： （一）爱国守法，品行端正； （二）未参加过朝觐； （三）身体健康，心智健全，无不适宜乘坐飞机、汽车长途旅行的病症，能够独立完成朝觐期间各项宗教活动； （四）有能力支付朝觐相关费用，并保证不因朝觐费用支出而影响家庭正常生产生活； （五）不具有《中华人民共和国出境入境管理法》第十二条规定不准出境的情形。"},{"i":13,"n":"第十三条","txt":"公民申请朝觐，在户籍所在地的朝觐报名网站上报名；户籍所在地尚未建立朝觐报名网站的，到户籍所在地县级人民政府宗教事务部门报名。 报名人员符合朝觐条件的,按照报名时间先后顺序排队。"},{"i":14,"n":"第十四条","txt":"县级人民政府宗教事务部门按照分配的名额和报名人员排队顺序，确定拟朝觐人员初选名单，并逐级报省级人民政府宗教事务部门备案。 每年朝觐人数在100人以下的省、自治区、直辖市，可以由省级人民政府宗教事务部门征求报名人员所在地设区的市级、县级人民政府宗教事务部门意见后，确定拟朝觐人员初选名单。 人民政府宗教事务部门确定拟朝觐人员初选名单后，应当将名单进行公示，公示期为5个工作日。公示期间被发现不符合参加朝觐条件的，不能取得朝觐名额。"},{"i":15,"n":"第十五条","txt":"取得朝觐名额的人员应当提交本人书面保证书，声明朝觐期间如因自身原因导致不良后果，本人自愿承担相关责任及费用。其中，年龄超过70周岁的人员，该保证书同时需要其直系亲属签字。"},{"i":16,"n":"第十六条","txt":"人民政府宗教事务部门和伊斯兰教协会应当提示取得朝觐名额的人员投保人身意外伤害保险。"},{"i":17,"n":"第十七条","txt":"伊斯兰教协会和伊斯兰教教职人员应当向信仰伊斯兰教的公民宣传国家有关政策法规和正确的朝觐知识，引导其理性对待朝觐，不参加非法朝觐，不攀比朝觐、负债朝觐、重病朝觐。"},{"i":18,"n":"第十八条","txt":"取得朝觐名额的人员应当交纳朝觐费用。朝觐费用包括为境内外组织服务机构收取的代收代缴性费用和伊斯兰教协会收取的综合服务性费用。"},{"i":19,"n":"第十九条","txt":"中国伊斯兰教协会根据与境内外组织服务机构签署的合同等，确定该会年度代收代缴性费用项目和标准；省、自治区、直辖市伊斯兰教协会根据朝觐人员境内城际交通、食宿、置装等需要，确定本地其他代收代缴性费用项目和标准。综合服务性费用由中国伊斯兰教协会按照非营利原则统一确定数额。 除前款规定外，任何组织或者个人不得借朝觐名义收取任何费用。"},{"i":20,"n":"第二十条","txt":"朝觐费用由取得朝觐名额人员所在地县（市、区、旗）伊斯兰教协会收取，并逐级上交至中国伊斯兰教协会。 县（市、区、旗）未设立伊斯兰教协会的，由所在地县级人民政府宗教事务部门代为收取。 每年朝觐人数在100人以下的省、自治区、直辖市，也可由省、自治区、直辖市伊斯兰教协会收取或者省级人民政府宗教事务部门代为收取。"},{"i":21,"n":"第二十一条","txt":"代收代缴性费用应当根据合同等收取，按实际发生情况，多退少补。综合服务性费用为一次性收取，透支不补。"},{"i":22,"n":"第二十二条","txt":"朝觐费用收取与使用应当遵循据实核算、公开透明、专款专用原则。 伊斯兰教协会应当按照国家有关财务、会计制度，制定并落实朝觐经费管理制度，按年度单独核算收支。 人民政府有关部门可以组织对年度朝觐费用收支情况进行专项检查和审计。"},{"i":23,"n":"第二十三条","txt":"取得朝觐名额人员应当在所在地海关国际旅行卫生保健中心或者省级人民政府卫生健康行政部门指定的医疗机构接受健康体检和预防接种，所需费用由本人承担并自行交纳。 健康体检和预防接种工作应当严格执行标准，人民政府宗教事务部门应当配合做好相关组织实施工作。 体检不合格的，不得参加朝觐。负责收取朝觐费用的伊斯兰教协会或者代为收取朝觐费用的人民政府宗教事务部门应当在15个工作日内退还朝觐费用。"},{"i":24,"n":"第二十四条","txt":"人民政府宗教事务部门应当组织对朝觐人员开展政策法规、爱国主义、民族团结、外事纪律、安全防范、卫生防疫、道德礼仪、海关及出入境规定、领事保护和协助常识、归国后注意事项等方面的教育培训。 伊斯兰教协会应当对朝觐人员开展宗教知识、中国伊斯兰教传统等方面的教育培训。"},{"i":25,"n":"第二十五条","txt":"中国伊斯兰教协会组织成立中国朝觐工作总团（以下简称总团）。 每年朝觐人数超过100人的省、自治区、直辖市伊斯兰教协会组织成立地方朝觐工作省区团（以下简称省区团）。省区团可以根据需要下设分团。 每年朝觐人数在100人以下的省、自治区、直辖市，统一由中国伊斯兰教协会组织，成立地方朝觐工作综合团（以下简称综合团）。"},{"i":26,"n":"第二十六条","txt":"省区团、综合团应当配备带队人员，带队人员与朝觐人员的比例一般为1：45。带队人员从地方人民政府宗教事务部门、伊斯兰教协会以及伊斯兰教经学院等选派。省级人民政府宗教事务部门应当将带队人员情况报国家宗教事务局备案。"},{"i":27,"n":"第二十七条","txt":"省区团、综合团应当配备教务人员，教务人员与朝觐人员的比例不高于1：200。教务人员由省、自治区、直辖市伊斯兰教协会从本地伊斯兰教教职人员中推荐。省级人民政府宗教事务部门应当将教务人员情况报国家宗教事务局备案。"},{"i":28,"n":"第二十八条","txt":"省区团、综合团应当配备医务人员，医务人员与朝觐人员的比例一般为1：200。医务人员由省级人民政府卫生健康行政部门会同同级人民政府宗教事务部门从二级甲等以上医疗机构选派。省级人民政府宗教事务部门、卫生健康行政部门应当将选派医务人员情况报国家宗教事务局和国家卫生健康委员会备案。"},{"i":29,"n":"第二十九条","txt":"带队人员、教务人员、医务人员等朝觐工作人员应当参加国家宗教事务局或者省级人民政府宗教事务部门组织的教育培训。教务人员还应当参加中国伊斯兰教协会组织的培训，医务人员还应当参加由国家宗教事务局会同国家卫生健康委员会组织的培训。"},{"i":30,"n":"第三十条","txt":"朝觐工作人员应当按照职责做好相应工作，遵守外事纪律和有关规定。 中国伊斯兰教协会和省、自治区、直辖市伊斯兰教协会应当建立并完善朝觐人员和朝觐工作人员数据库。 总团、省区团、综合团应当对朝觐工作人员的工作进行考核鉴定。"},{"i":31,"n":"第三十一条","txt":"中国伊斯兰教协会负责办理朝觐人员的朝觐签证，统筹协调朝觐飞机航班。"},{"i":32,"n":"第三十二条","txt":"省、自治区、直辖市伊斯兰教协会负责组织本地朝觐人员集体乘坐交通工具，配合边检、海关、机场、航空公司做好出入境监管和安全检查。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市伊斯兰教协会在省级人民政府宗教事务部门、公安部门等指导下，负责组织在境内统一接送朝觐人员，维护社会正常秩序。"},{"i":34,"n":"第三十四条","txt":"朝觐境外组织工作实行总团统一领导下的省区团、综合团和分团分级负责制，团长为第一责任人。"},{"i":35,"n":"第三十五条","txt":"总团应当履行以下职责： （一）建立健全境外朝觐组织工作制度； （二）组织开展对朝觐人员的爱国主义和安全教育，加强对朝觐人员的管理，抵御宗教极端思想渗透，防范发生危害国家安全的行为，主动排查安全隐患，落实安全责任，预防和处置突发事件； （三）组织安排朝觐人员境外餐饮、住宿、交通、参观、教务等活动； （四）组织开展对朝觐人员的卫生健康教育，改善医疗服务条件，落实疫情防控措施，做好诊疗救治工作； （五）及时将朝觐人员和朝觐地突发的传染病疫情通报中国海关； （六）统一负责对外联络、宣传，开展对外交往； （七）做好其他需要办理或者协调的事项。 总团应当接受国家宗教事务局、中国驻沙特阿拉伯使领馆的指导监督和中国伊斯兰教协会的管理。"},{"i":36,"n":"第三十六条","txt":"省区团、综合团和分团应当按照总团的安排和部署，做好本团朝觐组织工作，并加强互助合作。"},{"i":37,"n":"第三十七条","txt":"朝觐人员应当遵守中国法律以及有关国家法律，遵守朝觐工作管理规章制度，反对宗教极端思想，展现良好形象。"},{"i":38,"n":"第三十八条","txt":"中国伊斯兰教协会应当制定并落实朝觐人员境外住房租赁及分配办法，确保程序合规、工作透明、价格合理、分配公平。"},{"i":39,"n":"第三十九条","txt":"国家工作人员和伊斯兰教协会人员等在朝觐事务管理中，滥用职权、玩忽职守、徇私舞弊，应当给予处分的，依法依规给予处分；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"擅自组织公民朝觐或者为非法朝觐活动提供条件的，依照有关法律和《宗教事务条例》进行处罚；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"人民政府有关部门、中国伊斯兰教协会以及地方伊斯兰教协会应当结合实际制定具体实施办法。"},{"i":42,"n":"第四十二条","txt":"本办法自2020年12月1日起施行。"}],"yisilanjiaochaojinshiwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了保障公民宗教信仰自由，坚持我国宗教中国化方向，规范伊斯兰教朝觐事务管理，维护朝觐活动正常秩序，根据《中华人民共和国出境入境管理法》《中华人民共和国国境卫生检疫法》《宗教事务条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"信仰伊斯兰教的中国公民前往沙特阿拉伯麦加朝觐，由中国伊斯兰教协会负责组织。其他任何组织或者个人不得组织朝觐活动。"},{"i":3,"n":"第三条","txt":"国家宗教事务局负责归口管理全国伊斯兰教朝觐事务。地方各级人民政府宗教事务部门负责归口管理本地伊斯兰教朝觐事务。"},{"i":4,"n":"第四条","txt":"人民政府外事、公安、移民管理、卫生健康、文化旅游、海关、市场监管、民航等有关部门在各自职责范围内负责伊斯兰教朝觐事务管理工作。"},{"i":5,"n":"第五条","txt":"信仰伊斯兰教的中国公民的朝觐活动，应当有组织、有计划、有秩序和依法进行。"},{"i":6,"n":"第六条","txt":"地方各级人民政府宗教事务部门在当地人民政府领导下，牵头协调开展非法朝觐活动综合治理工作，做好政策法规宣传和教育引导，依法制止非法朝觐活动。 人民政府公安、文化旅游、市场监管等部门应当对有关中介机构、旅行社及相关企业进行监督管理，依法制止利用商务、旅游、探亲等进行的非法朝觐活动，依法查处非法朝觐活动组织者。"},{"i":7,"n":"第七条","txt":"中国公民每年朝觐数额，根据国际通行做法，结合我国经济社会发展状况确定。"},{"i":8,"n":"第八条","txt":"朝觐名额分配和朝觐人员确定应当遵循公开、公平、公正原则。 国家工作人员和伊斯兰教协会人员等不得利用职权或者职务上的影响干涉朝觐报名排队和朝觐人员确定。"},{"i":9,"n":"第九条","txt":"省级人民政府宗教事务部门应当综合考虑本地经济发展水平、伊斯兰教协会组织能力、群众生活条件及朝觐需求等因素，每年向国家宗教事务局申报拟参加朝觐名额。"},{"i":10,"n":"第十条","txt":"国家宗教事务局征求中国伊斯兰教协会意见后，确定年度全国朝觐总名额及各省、自治区、直辖市朝觐名额。"},{"i":11,"n":"第十一条","txt":"地方各级人民政府宗教事务部门应当将本地全部朝觐名额逐级进行分配。"},{"i":12,"n":"第十二条","txt":"公民申请朝觐，应当具备以下基本条件： （一）爱国守法，品行端正； （二）未参加过朝觐； （三）身体健康，心智健全，无不适宜乘坐飞机、汽车长途旅行的病症，能够独立完成朝觐期间各项宗教活动； （四）有能力支付朝觐相关费用，并保证不因朝觐费用支出而影响家庭正常生产生活； （五）不具有《中华人民共和国出境入境管理法》第十二条规定不准出境的情形。"},{"i":13,"n":"第十三条","txt":"公民申请朝觐，在户籍所在地的朝觐报名网站上报名；户籍所在地尚未建立朝觐报名网站的，到户籍所在地县级人民政府宗教事务部门报名。 报名人员符合朝觐条件的，按照报名时间先后顺序排队。"},{"i":14,"n":"第十四条","txt":"县级人民政府宗教事务部门按照分配的名额和报名人员排队顺序，确定拟朝觐人员初选名单，并逐级报省级人民政府宗教事务部门备案。 每年朝觐人数在100人以下的省、自治区、直辖市，可以由省级人民政府宗教事务部门征求报名人员所在地设区的市级、县级人民政府宗教事务部门意见后，确定拟朝觐人员初选名单。 人民政府宗教事务部门确定拟朝觐人员初选名单后，应当将名单进行公示，公示期为5个工作日。公示期间被发现不符合参加朝觐条件的，不能取得朝觐名额。"},{"i":15,"n":"第十五条","txt":"取得朝觐名额的人员应当提交本人书面保证书，声明朝觐期间如因自身原因导致不良后果，本人自愿承担相关责任及费用。其中，年龄超过70周岁的人员，该保证书同时需要其直系亲属签字。"},{"i":16,"n":"第十六条","txt":"人民政府宗教事务部门和伊斯兰教协会应当提示取得朝觐名额的人员投保人身意外伤害保险。"},{"i":17,"n":"第十七条","txt":"伊斯兰教协会和伊斯兰教教职人员应当向信仰伊斯兰教的公民宣传国家有关政策法规和正确的朝觐知识，引导其理性对待朝觐，不参加非法朝觐，不攀比朝觐、负债朝觐、重病朝觐。"},{"i":18,"n":"第十八条","txt":"取得朝觐名额的人员应当交纳朝觐费用。朝觐费用包括为境内外组织服务机构收取的代收代缴性费用和伊斯兰教协会收取的综合服务性费用。"},{"i":19,"n":"第十九条","txt":"中国伊斯兰教协会根据与境内外组织服务机构签署的合同等，确定该会年度代收代缴性费用项目和标准；省、自治区、直辖市伊斯兰教协会根据朝觐人员境内城际交通、食宿、置装等需要，确定本地其他代收代缴性费用项目和标准。综合服务性费用由中国伊斯兰教协会按照非营利原则统一确定数额。 除前款规定外，任何组织或者个人不得借朝觐名义收取任何费用。"},{"i":20,"n":"第二十条","txt":"朝觐费用由取得朝觐名额人员所在地县（市、区、旗）伊斯兰教协会收取，并逐级上交至中国伊斯兰教协会。 县（市、区、旗）未设立伊斯兰教协会的，由所在地县级人民政府宗教事务部门代为收取。 每年朝觐人数在100人以下的省、自治区、直辖市，也可由省、自治区、直辖市伊斯兰教协会收取或者省级人民政府宗教事务部门代为收取。"},{"i":21,"n":"第二十一条","txt":"代收代缴性费用应当根据合同等收取，按实际发生情况，多退少补。综合服务性费用为一次性收取，透支不补。"},{"i":22,"n":"第二十二条","txt":"朝觐费用收取与使用应当遵循据实核算、公开透明、专款专用原则。 伊斯兰教协会应当按照国家有关财务、会计制度，制定并落实朝觐经费管理制度，按年度单独核算收支。 人民政府有关部门可以组织对年度朝觐费用收支情况进行专项检查和审计。"},{"i":23,"n":"第二十三条","txt":"取得朝觐名额人员应当在所在地海关国际旅行卫生保健中心或者省级人民政府卫生健康行政部门指定的医疗机构接受健康体检和预防接种，所需费用由本人承担并自行交纳。 健康体检和预防接种工作应当严格执行标准，人民政府宗教事务部门应当配合做好相关组织实施工作。 体检不合格的，不得参加朝觐。负责收取朝觐费用的伊斯兰教协会或者代为收取朝觐费用的人民政府宗教事务部门应当在15个工作日内退还朝觐费用。"},{"i":24,"n":"第二十四条","txt":"人民政府宗教事务部门应当组织对朝觐人员开展政策法规、爱国主义、民族团结、外事纪律、安全防范、卫生防疫、道德礼仪、海关及出入境规定、领事保护和协助常识、归国后注意事项等方面的教育培训。 伊斯兰教协会应当对朝觐人员开展宗教知识、中国伊斯兰教传统等方面的教育培训。"},{"i":25,"n":"第二十五条","txt":"中国伊斯兰教协会组织成立中国朝觐工作总团（以下简称总团）。 每年朝觐人数超过100人的省、自治区、直辖市伊斯兰教协会组织成立地方朝觐工作省区团（以下简称省区团）。省区团可以根据需要下设分团。 每年朝觐人数在100人以下的省、自治区、直辖市，统一由中国伊斯兰教协会组织，成立地方朝觐工作综合团（以下简称综合团）。"},{"i":26,"n":"第二十六条","txt":"省区团、综合团应当配备带队人员，带队人员与朝觐人员的比例一般为1：45。带队人员从地方人民政府宗教事务部门、伊斯兰教协会以及伊斯兰教经学院等选派。省级人民政府宗教事务部门应当将带队人员情况报国家宗教事务局备案。"},{"i":27,"n":"第二十七条","txt":"省区团、综合团应当配备教务人员，教务人员与朝觐人员的比例不高于1：200。教务人员由省、自治区、直辖市伊斯兰教协会从本地伊斯兰教教职人员中推荐。省级人民政府宗教事务部门应当将教务人员情况报国家宗教事务局备案。"},{"i":28,"n":"第二十八条","txt":"省区团、综合团应当配备医务人员，医务人员与朝觐人员的比例一般为1：200。医务人员由省级人民政府卫生健康行政部门会同同级人民政府宗教事务部门从二级甲等以上医疗机构选派。省级人民政府宗教事务部门、卫生健康行政部门应当将选派医务人员情况报国家宗教事务局和国家卫生健康委员会备案。"},{"i":29,"n":"第二十九条","txt":"带队人员、教务人员、医务人员等朝觐工作人员应当参加国家宗教事务局或者省级人民政府宗教事务部门组织的教育培训。教务人员还应当参加中国伊斯兰教协会组织的培训，医务人员还应当参加由国家宗教事务局会同国家卫生健康委员会组织的培训。"},{"i":30,"n":"第三十条","txt":"朝觐工作人员应当按照职责做好相应工作，遵守外事纪律和有关规定。 中国伊斯兰教协会和省、自治区、直辖市伊斯兰教协会应当建立并完善朝觐人员和朝觐工作人员数据库。 总团、省区团、综合团应当对朝觐工作人员的工作进行考核鉴定。"},{"i":31,"n":"第三十一条","txt":"中国伊斯兰教协会负责办理朝觐人员的朝觐签证，统筹协调朝觐飞机航班。"},{"i":32,"n":"第三十二条","txt":"省、自治区、直辖市伊斯兰教协会负责组织本地朝觐人员集体乘坐交通工具，配合边检、海关、机场、航空公司做好出入境监管和安全检查。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市伊斯兰教协会在省级人民政府宗教事务部门、公安部门等指导下，负责组织在境内统一接送朝觐人员，维护社会正常秩序。"},{"i":34,"n":"第三十四条","txt":"朝觐境外组织工作实行总团统一领导下的省区团、综合团和分团分级负责制，团长为第一责任人。"},{"i":35,"n":"第三十五条","txt":"总团应当履行以下职责： （一）建立健全境外朝觐组织工作制度； （二）组织开展对朝觐人员的爱国主义和安全教育，加强对朝觐人员的管理，抵御宗教极端思想渗透，防范发生危害国家安全的行为，主动排查安全隐患，落实安全责任，预防和处置突发事件； （三）组织安排朝觐人员境外餐饮、住宿、交通、参观、教务等活动； （四）组织开展对朝觐人员的卫生健康教育，改善医疗服务条件，落实疫情防控措施，做好诊疗救治工作； （五）及时将朝觐人员和朝觐地突发的传染病疫情通报中国海关； （六）统一负责对外联络、宣传，开展对外交往； （七）做好其他需要办理或者协调的事项。 总团应当接受国家宗教事务局、中国驻沙特阿拉伯使领馆的指导监督和中国伊斯兰教协会的管理。"},{"i":36,"n":"第三十六条","txt":"省区团、综合团和分团应当按照总团的安排和部署，做好本团朝觐组织工作，并加强互助合作。"},{"i":37,"n":"第三十七条","txt":"朝觐人员应当遵守中国法律以及有关国家法律，遵守朝觐工作管理规章制度，反对宗教极端思想，展现良好形象。"},{"i":38,"n":"第三十八条","txt":"中国伊斯兰教协会应当制定并落实朝觐人员境外住房租赁及分配办法，确保程序合规、工作透明、价格合理、分配公平。"},{"i":39,"n":"第三十九条","txt":"国家工作人员和伊斯兰教协会人员等在朝觐事务管理中，滥用职权、玩忽职守、徇私舞弊，应当给予处分的，依法依规给予处分；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"擅自组织公民朝觐或者为非法朝觐活动提供条件的，依照有关法律和《宗教事务条例》进行处罚；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"人民政府有关部门、中国伊斯兰教协会以及地方伊斯兰教协会应当结合实际制定具体实施办法。"},{"i":42,"n":"第四十二条","txt":"本办法自2020年12月1日起施行。"}],"youfuyiyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强优抚医院管理，服务国防和军队建设，推动让退役军人成为全社会尊重的人，让军人成为全社会尊崇的职业，根据《中华人民共和国退役军人保障法》、《中华人民共和国基本医疗卫生与健康促进法》、《军人抚恤优待条例》、《医疗机构管理条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"优抚医院是国家为残疾退役军人和在服役期间患严重慢性病、精神疾病的退役军人等优抚对象提供医疗和供养服务的优抚事业单位，是担负特殊任务的医疗机构，主要包括综合医院、康复医院、精神病医院等，名称统一为“荣军优抚医院”。 优抚医院坚持全心全意为优抚对象服务的办院宗旨，坚持优抚属性，遵循医疗机构建设和管理规律。"},{"i":3,"n":"第三条","txt":"国务院退役军人工作主管部门负责全国优抚医院工作。县级以上地方人民政府退役军人工作主管部门负责本行政区域内优抚医院工作。 退役军人工作主管部门应当会同卫生健康主管部门加强对优抚医院的指导，为优抚医院医务人员的培训进修等创造条件，支持有条件的优抚医院在医疗、科研、教学等方面全面发展。"},{"i":4,"n":"第四条","txt":"国家兴办优抚医院，所需经费按照事权划分列入各级预算。"},{"i":5,"n":"第五条","txt":"设置优抚医院，应当符合国家有关规定和优抚医院布局规划。 卫生健康主管部门应当会同退役军人工作主管部门，将优抚医院设置纳入当地医疗机构设置规划统筹考虑。 省级人民政府退役军人工作主管部门应当会同省级人民政府卫生健康主管部门根据优抚对象数量和医疗供养需求情况，适应伤病残退役军人移交安置工作和服务备战打仗需要，制定本行政区域内优抚医院布局和发展规划，并报国务院退役军人工作主管部门和国务院卫生健康主管部门备案。 优抚医院布局和发展规划应当纳入当地经济和社会发展总体规划和卫生健康、医疗保障事业发展规划，建设水平应当与当地经济和社会发展、卫生健康事业发展相适应。"},{"i":6,"n":"第六条","txt":"因符合条件优抚对象数量较少等情形未建设优抚医院的地方，可以采取购买服务等方式，协调当地其他医疗机构为优抚对象提供医疗服务。 优抚医院应当依法履行相关职责，符合条件的按程序纳入基本医疗保险定点医疗机构、工伤保险协议医疗机构、工伤康复协议机构管理范围。"},{"i":7,"n":"第七条","txt":"优抚医院在建设、用地、水电、燃气、供暖、电信等方面依法享受国家有关优惠政策。 鼓励公民、法人和其他组织对优抚医院提供捐助和服务。 优抚医院各项经费应当按照批复的预算执行，接受财政、审计部门和社会的监督。"},{"i":8,"n":"第八条","txt":"对在优抚医院工作中成绩显著的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":9,"n":"第九条","txt":"优抚医院根据主管部门下达的任务，收治下列优抚对象： （一）需要常年医疗或者独身一人不便分散供养的一级至四级残疾退役军人； （二）在服役期间患严重慢性病的残疾退役军人和带病回乡退役军人； （三）在服役期间患精神疾病，需要住院治疗的退役军人； （四）短期疗养的优抚对象； （五）主管部门安排收治的其他人员。 优抚医院应当在完成主管部门下达的收治任务的基础上，为其他优抚对象提供优先或者优惠服务。"},{"i":10,"n":"第十条","txt":"优抚医院应当为在院优抚对象提供良好的医疗服务和生活保障，主要包括： （一）健康检查； （二）疾病诊断、治疗和护理； （三）康复训练； （四）健康指导； （五）辅助器具安装； （六）精神慰藉； （七）生活必需品供给； （八）生活照料； （九）文体活动。"},{"i":11,"n":"第十一条","txt":"优抚医院应当加强对在院优抚对象的思想政治工作，发挥优抚对象在光荣传统教育中的重要作用。"},{"i":12,"n":"第十二条","txt":"优抚医院针对在院残疾退役军人的残情特点，实施科学有效的医学治疗，探索常见后遗症、并发症的防治方法，促进生理机能恢复，提高残疾退役军人生活质量。"},{"i":13,"n":"第十三条","txt":"优抚医院应当采取积极措施，控制在院慢性病患者病情，减轻其痛苦，降低慢性疾病对患者造成的生理和心理影响。"},{"i":14,"n":"第十四条","txt":"优抚医院对在院精神疾病患者进行综合治疗，促进患者精神康复。 对精神病患者实行分级管理，预防发生自杀、自伤、伤人、出走等行为。"},{"i":15,"n":"第十五条","txt":"优抚医院应当规范入院、出院程序。 属于第九条规定收治范围的优抚对象，可以由本人（精神病患者由其利害关系人）提出申请，或者由村（社区）退役军人服务站代为提出申请，经县级人民政府退役军人工作主管部门审核，由优抚医院根据主管部门下达的任务和计划安排入院。省级人民政府退役军人工作主管部门可以指定优抚医院收治符合条件的优抚对象。 在院优抚对象基本治愈或者病情稳定，符合出院条件的，由优抚医院办理出院手续。 在院优抚对象病故的，优抚医院应当及时报告主管部门，并协助优抚对象常住户口所在地退役军人工作主管部门妥善办理丧葬事宜。"},{"i":16,"n":"第十六条","txt":"优抚医院应当按照国家有关规定建立健全病历管理制度，设置病案管理部门或者配备专兼职人员，负责病历和病案管理工作。"},{"i":17,"n":"第十七条","txt":"退役军人工作主管部门应当定期组织优抚医院开展巡回医疗活动，积极为院外优抚对象提供医疗服务。"},{"i":18,"n":"第十八条","txt":"优抚医院应当在做好优抚对象服务工作的基础上，积极履行医疗机构职责，发挥自身医疗专业特长，为社会提供优质医疗服务。 优抚医院应当通过社会服务提升业务能力，改善医疗条件，不断提高医疗和供养水平。"},{"i":19,"n":"第十九条","txt":"优抚医院在设置审批、登记管理、命名、执业和监督等方面应当符合国家有关医疗机构管理的法律法规和相关规定，执行卫生健康主管部门有关医疗机构的相关标准。"},{"i":20,"n":"第二十条","txt":"优抚医院实行党委领导下的院长负责制，科室实行主任（科长）负责制。"},{"i":21,"n":"第二十一条","txt":"优抚医院应当加强党的建设，充分发挥基层党组织战斗堡垒作用和党员先锋模范作用，促进思想政治和医德医风建设。"},{"i":22,"n":"第二十二条","txt":"优抚医院实行国家规定的工资制度，合理确定医务人员薪酬水平，完善内部分配和激励机制，促进医务人员队伍建设。"},{"i":23,"n":"第二十三条","txt":"优抚医院建立职工代表大会制度，保障职工参与医院的民主决策、民主管理和民主监督。"},{"i":24,"n":"第二十四条","txt":"优抚医院应当树立现代管理理念，推进现代化、标准化、信息化建设；强化重点专科建设，发挥专业技术优势；建立完整的医护管理、感染控制、药品使用、医疗事故预防和安全、消防等规章制度，提高医院管理水平。"},{"i":25,"n":"第二十五条","txt":"优抚医院实行岗位责任制，设立专业技术类、管理类、工勤技能类等岗位并明确相关职责；实行24小时值班制度，按照医院分级护理等有关要求为收治对象提供护理服务。"},{"i":26,"n":"第二十六条","txt":"优抚医院应当完善人才培养和引进机制，积极培养和引进学科带头人，同等条件下优先聘用曾从事医务工作的退役军人，建立一支适应现代化医院发展要求的技术和管理人才队伍。"},{"i":27,"n":"第二十七条","txt":"优抚医院应当加强与军队医院、其他社会医院、医学院校的合作与交流，开展共建活动，在人才、技术等领域实现资源共享和互补。"},{"i":28,"n":"第二十八条","txt":"优抚医院应当加强医院文化建设，积极宣传优抚对象的光荣事迹，形成有拥军特色的医院文化。"},{"i":29,"n":"第二十九条","txt":"优抚医院的土地、房屋、设施、设备和其他财产归优抚医院管理和使用，任何单位和个人不得侵占。 侵占、破坏优抚医院财产的，由当地人民政府退役军人工作主管部门责令限期改正；造成损失的，依法承担赔偿责任。"},{"i":30,"n":"第三十条","txt":"优抚对象应当遵守优抚医院各项规章制度，尊重医护人员工作，自觉配合医护人员的管理。对违反相关规定的，由优抚医院或者主管部门进行批评教育，情节严重的，依法追究相应责任。"},{"i":31,"n":"第三十一条","txt":"优抚医院违反本办法规定，提供的医疗和供养服务不符合要求的，由优抚医院主管部门责令改正；逾期不改正的，对直接负责的责任人和其他主管人员依法给予处分；造成损失的，依法承担责任。 优抚医院造成收治对象人身损害或发生医疗事故、医疗纠纷的，应当依法处置。 优抚医院违反国家有关医疗机构管理的法律法规和相关规定的，由县级以上地方人民政府卫生健康主管部门依法依规处理。"},{"i":32,"n":"第三十二条","txt":"承担优抚对象收治供养任务的其他医疗机构对优抚对象的诊疗服务工作，可以参照本办法有关规定执行。"},{"i":33,"n":"第三十三条","txt":"本办法自2022年8月1日起施行。"}],"shangcanfuxuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范和加强退役军人事务部门管理的伤残抚恤工作，根据《军人抚恤优待条例》等法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于符合下列情况的中国公民： （一）在服役期间因战因公致残退出现役的军人，在服役期间因病评定了残疾等级退出现役的残疾军人； （二）因战因公负伤时为行政编制的人民警察； （三）因参战、参加军事演习、军事训练和执行军事勤务致残的预备役人员、民兵、民工以及其他人员； （四）为维护社会治安同违法犯罪分子进行斗争致残的人员； （五）为抢救和保护国家财产、人民生命财产致残的人员； （六）法律、行政法规规定应当由退役军人事务部门负责伤残抚恤的其他人员。 前款所列第（三）、第（四）、第（五）项人员根据《工伤保险条例》应当认定视同工伤的，不再办理因战、因公伤残抚恤。"},{"i":3,"n":"第三条","txt":"本办法第二条所列人员符合《军人抚恤优待条例》及有关政策中因战因公致残规定的，可以认定因战因公致残；个人对导致伤残的事件和行为负有过错责任的，以及其他不符合因战因公致残情形的，不得认定为因战因公致残。"},{"i":4,"n":"第四条","txt":"伤残抚恤工作应当遵循公开、公平、公正的原则。县级人民政府退役军人事务部门应当公布有关评残程序和抚恤金标准。"},{"i":5,"n":"第五条","txt":"评定残疾等级包括新办评定残疾等级、补办评定残疾等级、调整残疾等级。 新办评定残疾等级是指对本办法第二条第一款第（一）项以外的人员认定因战因公残疾性质，评定残疾等级。补办评定残疾等级是指对现役军人因战因公致残未能及时评定残疾等级，在退出现役后依据《军人抚恤优待条例》的规定，认定因战因公残疾性质、评定残疾等级。调整残疾等级是指对已经评定残疾等级，因原致残部位残疾情况变化与原评定的残疾等级明显不符的人员调整残疾等级级别，对达不到最低评残标准的可以取消其残疾等级。 属于新办评定残疾等级的，申请人应当在因战因公负伤或者被诊断、鉴定为职业病3年内提出申请；属于调整残疾等级的，应当在上一次评定残疾等级1年后提出申请。"},{"i":6,"n":"第六条","txt":"申请人（精神病患者由其利害关系人帮助申请，下同）申请评定残疾等级，应当向所在单位提出书面申请。申请人所在单位应及时审查评定残疾等级申请，出具书面意见并加盖单位公章，连同相关材料一并报送户籍地县级人民政府退役军人事务部门审查。 没有工作单位的或者以原致残部位申请评定残疾等级的，可以直接向户籍地县级人民政府退役军人事务部门提出申请。"},{"i":7,"n":"第七条","txt":"申请人申请评定残疾等级，应当提供以下真实确切材料：书面申请，身份证或者居民户口簿复印件，退役军人证（退役军人登记表）、人民警察证等证件复印件，本人近期二寸免冠彩色照片。 申请新办评定残疾等级，应当提交致残经过证明和医疗诊断证明。致残经过证明应包括相关职能部门提供的执行公务证明，交通事故责任认定书、调解协议书、民事判决书、医疗事故鉴定书等证明材料；抢救和保护国家财产、人民生命财产致残或者为维护社会治安同犯罪分子斗争致残证明；统一组织参战、参加军事演习、军事训练和执行军事勤务的证明材料。医疗诊断证明应包括加盖出具单位相关印章的门诊病历原件、住院病历复印件及相关检查报告。 申请补办评定残疾等级，应当提交因战因公致残档案记载或者原始医疗证明。档案记载是指本人档案中所在部队作出的涉及本人负伤原始情况、治疗情况及善后处理情况等确切书面记载。职业病致残需提供有直接从事该职业病相关工作经历的记载。医疗"},{"i":8,"n":"第八条","txt":"县级人民政府退役军人事务部门对报送的有关材料进行核对，对材料不全或者材料不符合法定形式的应当告知申请人补充材料。 县级人民政府退役军人事务部门经审查认为申请人符合因战因公负伤条件的，在报经设区的市级人民政府以上退役军人事务部门审核同意后，应当填写《残疾等级评定审批表》，并在受理之日起20个工作日内，签发《受理通知书》，通知本人到设区的市级人民政府以上退役军人事务部门指定的医疗卫生机构，对属于因战因公导致的残疾情况进行鉴定，由医疗卫生专家小组根据《军人残疾等级评定标准》，出具残疾等级医学鉴定意见。职业病的残疾情况鉴定由省级人民政府退役军人事务部门指定的承担职业病诊断的医疗卫生机构作出；精神病的残疾情况鉴定由省级人民政府退役军人事务部门指定的二级以上精神病专科医院作出。 县级人民政府退役军人事务部门依据医疗卫生专家小组出具的残疾等级医学鉴定意见对申请人拟定残疾等级，在《残疾等级评定审批表》"},{"i":9,"n":"第九条","txt":"设区的市级人民政府退役军人事务部门对报送的材料审查后，在《残疾等级评定审批表》上签署意见，并加盖印章。 对符合条件的，于收到材料之日起20个工作日内，将上述材料报送省级人民政府退役军人事务部门。对不符合条件的，属于本办法第二条第一款第（一）项人员，根据《军人抚恤优待条例》相关规定上报省级人民政府退役军人事务部门；属于本办法第二条第一款第（一）项以外的人员，填写《残疾等级评定结果告知书》，连同申请人提供的材料，逐级退还申请人或者其所在单位。"},{"i":10,"n":"第十条","txt":"省级人民政府退役军人事务部门对报送的材料初审后，认为符合条件的，逐级通知县级人民政府退役军人事务部门对申请人的评残情况进行公示。公示内容应当包括致残的时间、地点、原因、残疾情况（涉及隐私或者不宜公开的不公示）、拟定的残疾等级以及县级退役军人事务部门联系方式。公示应当在申请人工作单位所在地或者居住地进行，时间不少于7个工作日。县级人民政府退役军人事务部门应当对公示中反馈的意见进行核实并签署意见，逐级上报省级人民政府退役军人事务部门，对调整等级的应当将本人持有的伤残人员证一并上报。 省级人民政府退役军人事务部门应当对公示的意见进行审核，在《残疾等级评定审批表》上签署审批意见，加盖印章。对符合条件的，办理伤残人员证（调整等级的，在证件变更栏处填写新等级），于公示结束之日起60个工作日内逐级发给申请人或者其所在单位。对不符合条件的，填写《残疾等级评定结果告知书》，连同申请人提供的材料，于收到材"},{"i":11,"n":"第十一条","txt":"申请人或者退役军人事务部门对医疗卫生专家小组作出的残疾等级医学鉴定意见有异议的，可以到省级人民政府退役军人事务部门指定的医疗卫生机构重新进行鉴定。 省级人民政府退役军人事务部门可以成立医疗卫生专家小组，对残疾情况与应当评定的残疾等级提出评定意见。"},{"i":12,"n":"第十二条","txt":"伤残人员以军人、人民警察或者其他人员不同身份多次致残的，退役军人事务部门按上述顺序只发给一种证件，并在伤残证件变更栏上注明再次致残的时间和性质，以及合并评残后的等级和性质。 致残部位不能合并评残的，可以先对各部位分别评残。等级不同的，以重者定级；两项（含）以上等级相同的，只能晋升一级。 多次致残的伤残性质不同的，以等级重者定性。等级相同的，按因战、因公、因病的顺序定性。"},{"i":13,"n":"第十三条","txt":"伤残证件的发放种类： （一）退役军人在服役期间因战因公因病致残的，发给《中华人民共和国残疾军人证》； （二）人民警察因战因公致残的，发给《中华人民共和国伤残人民警察证》； （三）退出国家综合性消防救援队伍的人员在职期间因战因公因病致残的，发给《中华人民共和国残疾消防救援人员证》； （四）因参战、参加军事演习、军事训练和执行军事勤务致残的预备役人员、民兵、民工以及其他人员，发给《中华人民共和国伤残预备役人员、伤残民兵民工证》； （五）其他人员因公致残的，发给《中华人民共和国因公伤残人员证》。"},{"i":14,"n":"第十四条","txt":"伤残证件由国务院退役军人事务部门统一制作。证件的有效期：15周岁以下为5年，16－25周岁为10年，26－45周岁为20年，46周岁以上为长期。"},{"i":15,"n":"第十五条","txt":"伤残证件有效期满或者损毁、遗失的，证件持有人应当到县级人民政府退役军人事务部门申请换发证件或者补发证件。伤残证件遗失的须本人登报声明作废。 县级人民政府退役军人事务部门经审查认为符合条件的，填写《伤残人员换证补证审批表》，连同照片逐级上报省级人民政府退役军人事务部门。省级人民政府退役军人事务部门将新办理的伤残证件逐级通过县级人民政府退役军人事务部门发给申请人。各级退役军人事务部门应当在20个工作日内完成本级需要办理的事项。"},{"i":16,"n":"第十六条","txt":"伤残人员前往我国香港特别行政区、澳门特别行政区、台湾地区定居或者其他国家和地区定居前，应当向户籍地（或者原户籍地）县级人民政府退役军人事务部门提出申请，由户籍地（或者原户籍地）县级人民政府退役军人事务部门在变更栏内注明变更内容。对需要换发新证的，\"身份证号\"处填写定居地的居住证件号码。\"户籍地\"为国内抚恤关系所在地。"},{"i":17,"n":"第十七条","txt":"伤残人员死亡的，其家属或者利害关系人应及时告知伤残人员户籍地县级人民政府退役军人事务部门，县级人民政府退役军人事务部门应当注销其伤残证件，并逐级上报省级人民政府退役军人事务部门备案。"},{"i":18,"n":"第十八条","txt":"退役军人事务部门对申报和审批的各种材料、伤残证件应当有登记手续。送达的材料或者证件，均须挂号邮寄或者由申请人签收。"},{"i":19,"n":"第十九条","txt":"县级人民政府退役军人事务部门应当建立伤残人员资料档案，一人一档，长期保存。"},{"i":20,"n":"第二十条","txt":"残疾军人退役或者向政府移交，必须自军队办理了退役手续或者移交手续后60日内，向户籍迁入地的县级人民政府退役军人事务部门申请转入抚恤关系。退役军人事务部门必须进行审查、登记、备案。审查的材料有：《户口登记簿》、《残疾军人证》、军队相关部门监制的《军人残疾等级评定表》、《换领<中华人民共和国残疾军人证>申报审批表》、退役证件或者移交政府安置的相关证明。 县级人民政府退役军人事务部门应当对残疾军人残疾情况及有关材料进行审查，必要时可以复查鉴定残疾情况。认为符合条件的，将《残疾军人证》及有关材料逐级报送省级人民政府退役军人事务部门。省级人民政府退役军人事务部门审查无误的，在《残疾军人证》变更栏内填写新的户籍地、重新编号，并加盖印章，将《残疾军人证》逐级通过县级人民政府退役军人事务部门发还申请人。各级退役军人事务部门应当在20个工作日内完成本级需要办理的事项。如复查、鉴定残疾情况的可以适当延长工"},{"i":21,"n":"第二十一条","txt":"伤残人员跨省迁移户籍时，应同步转移伤残抚恤关系，迁出地的县级人民政府退役军人事务部门根据伤残人员申请及其伤残证件和迁入地户口簿，将伤残档案、迁入地户口簿复印件以及《伤残人员关系转移证明》，发送迁入地县级人民政府退役军人事务部门，并同时将此信息逐级上报本省级人民政府退役军人事务部门。 迁入地县级人民政府退役军人事务部门在收到上述材料和申请人提供的伤残证件后，逐级上报省级人民政府退役军人事务部门。省级人民政府退役军人事务部门在向迁出地省级人民政府退役军人事务部门核实无误后，在伤残证件变更栏内填写新的户籍地、重新编号，并加盖印章，逐级通过县级人民政府退役军人事务部门发还申请人。各级退役军人事务部门应当在20个工作日内完成本级需要办理的事项。 迁出地退役军人事务部门邮寄伤残档案时，应当将伤残证件及其军队或者地方相关的评残审批表或者换证表复印备查。"},{"i":22,"n":"第二十二条","txt":"伤残人员本省、自治区、直辖市范围内迁移的有关手续，由省、自治区、直辖市人民政府退役军人事务部门规定。"},{"i":23,"n":"第二十三条","txt":"伤残人员从被批准残疾等级评定后的下一个月起，由户籍地县级人民政府退役军人事务部门按照规定予以抚恤。伤残人员抚恤关系转移的，其当年的抚恤金由部队或者迁出地的退役军人事务部门负责发给，从下一年起由迁入地退役军人事务部门按当地标准发给。由于申请人原因造成抚恤金断发的，不再补发。"},{"i":24,"n":"第二十四条","txt":"在境内异地（指非户籍地）居住的伤残人员或者前往我国香港特别行政区、澳门特别行政区、台湾地区定居或者其他国家和地区定居的伤残人员，经向其户籍地（或者原户籍地）县级人民政府退役军人事务部门申请并办理相关手续后，其伤残抚恤金可以委托他人代领，也可以委托其户籍地（或者原户籍地）县级人民政府退役军人事务部门存入其指定的金融机构账户，所需费用由本人负担。"},{"i":25,"n":"第二十五条","txt":"伤残人员本人（或者其家属）每年应当与其户籍地（或者原户籍地）的县级人民政府退役军人事务部门联系一次，通过见面、人脸识别等方式确认伤残人员领取待遇资格。当年未联系和确认的，县级人民政府退役军人事务部门应当经过公告或者通知本人或者其家属及时联系、确认；经过公告或者通知本人或者其家属后60日内仍未联系、确认的，从下一个月起停发伤残抚恤金和相关待遇。 伤残人员（或者其家属）与其户籍地（或者原户籍地）退役军人事务部门重新确认伤残人员领取待遇资格后，从下一个月起恢复发放伤残抚恤金和享受相关待遇，停发的抚恤金不予补发。"},{"i":26,"n":"第二十六条","txt":"伤残人员变更国籍、被取消残疾等级或者死亡的，从变更国籍、被取消残疾等级或者死亡后的下一个月起停发伤残抚恤金和相关待遇，其伤残人员证件自然失效。"},{"i":27,"n":"第二十七条","txt":"有下列行为之一的，由县级人民政府退役军人事务部门给予警告，停止其享受的抚恤、优待，追回非法所得；构成犯罪的，依法追究刑事责任： （一）伪造残情的； （二）冒领抚恤金的； （三）骗取医药费等费用的； （四）出具假证明，伪造证件、印章骗取抚恤金和相关待遇的。"},{"i":28,"n":"第二十八条","txt":"县级人民政府退役军人事务部门依据人民法院生效的法律文书、公安机关发布的通缉令或者国家有关规定，对具有中止抚恤、优待情形的伤残人员，决定中止抚恤、优待，并通知本人或者其家属、利害关系人。"},{"i":29,"n":"第二十九条","txt":"中止抚恤的伤残人员在刑满释放并恢复政治权利、取消通缉或者符合国家有关规定后，经本人（精神病患者由其利害关系人）申请，并经县级退役军人事务部门审查符合条件的，从审核确认的下一个月起恢复抚恤和相关待遇，原停发的抚恤金不予补发。办理恢复抚恤手续应当提供下列材料：本人申请、户口登记簿、司法机关的相关证明。需要重新办证的，按照证件丢失规定办理。"},{"i":30,"n":"第三十条","txt":"本办法适用于中国人民武装警察部队。"},{"i":31,"n":"第三十一条","txt":"因战因公致残的深化国防和军队改革期间部队现役干部转改的文职人员，因参加军事训练、非战争军事行动和作战支援保障任务致残的其他文职人员，因战因公致残消防救援人员、因病致残评定了残疾等级的消防救援人员，退出军队或国家综合性消防救援队伍后的伤残抚恤管理参照退出现役的残疾军人有关规定执行。"},{"i":32,"n":"第三十二条","txt":"未列入行政编制的人民警察，参照本办法评定伤残等级，其伤残抚恤金由所在单位按规定发放。"},{"i":33,"n":"第三十三条","txt":"省级人民政府退役军人事务部门可以根据本地实际情况，制定具体工作细则。"},{"i":34,"n":"第三十四条","txt":"本办法自2007年8月1日起施行。 附件：1.受理通知书 2.残疾等级评定审批表 3.残疾等级评定结果告知书 4.伤残人员换证补证审批表 5.伤残人员关系转移证明 6.评定残疾情况公示书"}],"tiyugongzuozhongguojiamimijiqimijijutifanweideguid0247c0":[{"i":1,"n":"第一条","txt":"体育工作中，一旦泄露会造成下列后果之一的，属国家秘密的具体范围： (一)妨害体育工作重大决策贯彻落实的； (二)对我国举办或参与国际体育活动所采取的安全防范措施构成威胁的；J (三)妨害优秀运动队或优秀运动员在重大比赛中发挥优异水平的； (四)对我与港、澳、、台之间以及对外体育交流中带来不良影响的； (五)危及体育交流中的秘密情报及其来源安全的； (六)使体育对外经营谈判中经济利益受到损害的； (七)给重点部位、重要人士的安全带来危害的； (八)给体育信息系统的安全、可靠带来威胁的。"},{"i":2,"n":"第二条","txt":"体育工作中国家秘密的密级具体范围如下： (一)绝密级事项 1、我国举办将国际体育活动中反恐怖、破坏事件的部署及安全防范措施， 2、体育活动中涉及国家安全或重大利益的秘密情报及其来源。 (二)机密级事项 1、体育工作中不宜公布的涉及重大政治、政策问题的事项； 2、我国优秀运动队独有的或处于世界尖端水平的训练方法和手段； 3、用于提高运动员身体机能的独有的中草药配方、传统处方和技术措施； 4、体育团、队出国访问的安全保卫方案； 5、体育外事活动中内定的政策、策略； 6、与港、澳、台地区开展体育交流的内部政策、策略以及涉及重要人士安全的事项； 7、计算机信息系统的保密措施。 (三)秘密级事项 1、党和国家领导人、外国政府要员观看体育比赛的安全保卫方案； 2、易燃、易爆体育器材仓库的安全保卫措施； 3、优秀运动队的训练计划以及参加重大国际比赛阵容设计和技术、战术方案； 4、我国特有的体育科研成"},{"i":3,"n":"第三条","txt":"本规定自1990年5月26日起生效，国家体委1987年制定的《体育工作保密暂行规定》中有关保密范围和密级划分规定同时废止。"}],"zuopinziyuandengjishixingbanfa":[{"i":1,"n":"第一条","txt":"为维护作者或其他著作权人和作品使用者的合法权益，有助于解决因著作权归属造成的著作权纠纷，并为解决著作权纠纷提供初步证据，特制定本办法。"},{"i":2,"n":"第二条","txt":"作品实行自愿登记。作品不论是否登记，作者或其他著作权人依法取得的著作权不受影响。"},{"i":3,"n":"第三条","txt":"各省、自治区、直辖市版权局负责本辖区的作者或其他著作权人的作品登记工作。国家版权局负责外国以及台湾、香港和澳门地区的作者或其他著作权人的作品登记工作。"},{"i":4,"n":"第四条","txt":"作品登记申请者应当是作者、其他享有著作权的公民、法人或者非法人单位和专有权所有人及其代理人。"},{"i":5,"n":"第五条","txt":"属于下列情况之一的作品，作品登记机关不予登记： 1.不受著作权法保护的作品； 2.超过著作权保护期的作品； 3.依法禁止出版、传播的作品。"},{"i":6,"n":"第六条","txt":"有下列情况的，作品登记机关应撤销其登记： 1.登记后发现有本办法第五条所规定的情况的； 2.登记后发现与事实不相符的； 3.申请人申请撤销原作品登记的； 4.登记后发现是重复登记的。"},{"i":7,"n":"第七条","txt":"作者或其他享有著作权的公民的所属辖区，原则上以其身份证上住址所在地的所属辖区为准。合作作者及有多个著作权人情况的，以受托登记者所属辖区为准。法人或者非法人单位所属辖区以其营业场所所在地所属辖区为准。"},{"i":8,"n":"第八条","txt":"作者或其他著作权人申请作品登记应出示身份证明和提供表明作品权利归属的证明(如：封面及版权页的复印件、部分手稿的复印件及照片、样本等)，填写作品登记表，并交纳登记费。其他著作权人申请作品登记还应出示表明著作权人身份的证明(如继承人应出示继承人身份证明；委托作品的委托人应出示委托合同)。专有权所有人应出示证明其享有专有权的合同。"},{"i":9,"n":"第九条","txt":"登记作品经作品登记机关核查后，由作品登记机关发给作品登记证。作品登记证按本办法所附样本由登记机关制作。登记机关的核查期限为一个月，该期限自登记机关收到申请人提交的所有申请登记的材料之日起计算。"},{"i":10,"n":"第十条","txt":"作品登记表和作品登记证应载有作品登记号。作品登记号格式为作登字：（地区编号)—(年代)-(作品分类号)—(顺序号)号。国家版权局负责登记的作品登记号不含地区编号。"},{"i":11,"n":"第十一条","txt":"各省、自治区、直辖市版权局应每月将本地区作品登记情况报国家版权局。"},{"i":12,"n":"第十二条","txt":"作品登记应实行计算机数据库管理．并对公众开放。查阅作品应填写查阅登记表，交纳查阅费。"},{"i":13,"n":"第十三条","txt":"有关作品登记和查阅的费用标准另行制定。"},{"i":14,"n":"第十四条","txt":"录音、录像制品的登记参照本办法执行。"},{"i":15,"n":"第十五条","txt":"计算机软件登记按《计算机软件著作权登记办法》执行。"},{"i":16,"n":"第十六条","txt":"本办法由国家版权局负责解释。"},{"i":17,"n":"第十七条","txt":"本办法自1995年1月1日起生效。"}],"shiyongwenzizuopinzhifubaochoubanfa":[{"i":1,"n":"第一条","txt":"为保护文字作品著作权人的著作权，规范使用文字作品的行为，促进文字作品的创作与传播，根据《中华人民共和国著作权法》及相关行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"除法律、行政法规另有规定外，使用文字作品支付报酬由当事人约定；当事人没有约定或者约定不明的，适用本办法。"},{"i":3,"n":"第三条","txt":"以纸介质出版方式使用文字作品支付报酬可以选择版税、基本稿酬加印数稿酬或者一次性付酬等方式。 版税，是指使用者以图书定价×实际销售数或者印数×版税率的方式向著作权人支付的报酬。 基本稿酬，是指使用者按作品的字数，以千字为单位向著作权人支付的报酬。 印数稿酬，是指使用者根据图书的印数，以千册为单位按基本稿酬的一定比例向著作权人支付的报酬。 一次性付酬，是指使用者根据作品的质量、篇幅、作者的知名度、影响力以及使用方式、使用范围和授权期限等因素，一次性向著作权人支付的报酬。"},{"i":4,"n":"第四条","txt":"版税率标准和计算方法： （一）原创作品：3%—10% （二）演绎作品：1%—7% 采用版税方式支付报酬的，著作权人可以与使用者在合同中约定，在交付作品时或者签订合同时由使用者向著作权人预付首次实际印数或者最低保底发行数的版税。 首次出版发行数不足千册的，按千册支付版税，但在下次结算版税时对已经支付版税部分不再重复支付。"},{"i":5,"n":"第五条","txt":"基本稿酬标准和计算方法： （一）原创作品：每千字80—300元，注释部分参照该标准执行｡ （二）演绎作品： 1.改编：每千字20—100元 2.汇编：每千字10—20元 3.翻译：每千字50—200元 支付基本稿酬以千字为单位，不足千字部分按千字计算。 支付报酬的字数按实有正文计算，即以排印的版面每行字数乘以全部实有的行数计算。占行题目或者末尾排不足一行的，按一行计算。 诗词每十行按一千字计算，作品不足十行的按十行计算。 辞书类作品按双栏排版的版面折合的字数计算。"},{"i":6,"n":"第六条","txt":"印数稿酬标准和计算方法： 每印一千册，按基本稿酬的1%支付。不足一千册的，按一千册计算。 作品重印时只支付印数稿酬，不再支付基本稿酬。 采用基本稿酬加印数稿酬的付酬方式的，著作权人可以与使用者在合同中约定，在交付作品时由使用者支付基本稿酬的30%—50%。除非合同另有约定，作品一经使用，使用者应当在6个月内付清全部报酬。作品重印的，应在重印后6个月内付清印数稿酬。"},{"i":7,"n":"第七条","txt":"一次性付酬的，可以参照本办法第五条规定的基本稿酬标准及其计算方法。"},{"i":8,"n":"第八条","txt":"使用演绎作品，除合同另有约定或者原作品已进入公有领域外，使用者还应当取得原作品著作权人的许可并支付报酬。"},{"i":9,"n":"第九条","txt":"使用者未与著作权人签订书面合同，或者签订了书面合同但未约定付酬方式和标准，与著作权人发生争议的，应当按本办法第四条、第五条规定的付酬标准的上限分别计算报酬，以较高者向著作权人支付，并不得以出版物抵作报酬。"},{"i":10,"n":"第十条","txt":"著作权人许可使用者通过转授权方式在境外出版作品，但对支付报酬没有约定或约定不明的，使用者应当将所得报酬扣除合理成本后的70%支付给著作权人。"},{"i":11,"n":"第十一条","txt":"报刊刊载作品只适用一次性付酬方式。"},{"i":12,"n":"第十二条","txt":"报刊刊载未发表的作品，除合同另有约定外，应当自刊载后1个月内按每千字不低于100元的标准向著作权人支付报酬。 报刊刊载未发表的作品，不足五百字的按千字作半计算；超过五百字不足千字的按千字计算。"},{"i":13,"n":"第十三条","txt":"报刊依照《中华人民共和国著作权法》的相关规定转载、摘编其他报刊已发表的作品，应当自报刊出版之日起2个月内，按每千字100元的付酬标准向著作权人支付报酬，不足五百字的按千字作半计算，超过五百字不足千字的按千字计算。 报刊出版者未按前款规定向著作权人支付报酬的，应当将报酬连同邮资以及转载、摘编作品的有关情况送交中国文字著作权协会代为收转。中国文字著作权协会收到相关报酬后，应当按相关规定及时向著作权人转付，并编制报酬收转记录。 报刊出版者按前款规定将相关报酬转交给中国文字著作权协会后，对著作权人不再承担支付报酬的义务。"},{"i":14,"n":"第十四条","txt":"以纸介质出版方式之外的其他方式使用文字作品，除合同另有约定外，使用者应当参照本办法规定的付酬标准和付酬方式付酬。 在数字或者网络环境下使用文字作品，除合同另有约定外，使用者可以参照本办法规定的付酬标准和付酬方式付酬。"},{"i":15,"n":"第十五条","txt":"教科书法定许可使用文字作品适用《教科书法定许可使用作品支付报酬办法》。"},{"i":16,"n":"第十六条","txt":"本办法由国家版权局会同国家发展和改革委员会负责解释。"},{"i":17,"n":"第十七条","txt":"本办法自2014年11月1日起施行。国家版权局1999年4月5日发布的《出版文字作品报酬规定》同时废止。"}],"baomishixiangfanweizhidingxiudingheshiyongbanfa":[{"i":1,"n":"第一条","txt":"为规范国家秘密及其密级的具体范围（以下简称保密事项范围）的制定、修订和使用工作，根据《中华人民共和国保守国家秘密法》（以下简称保密法）及其实施条例，制定本办法。"},{"i":2,"n":"第二条","txt":"保密事项范围由国家保密行政管理部门分别会同外交、公安、国家安全和其他中央有关机关制定、修订。"},{"i":3,"n":"第三条","txt":"制定、修订保密事项范围应当从维护国家安全和利益出发，适应经济社会发展要求，以保密法确定的国家秘密基本范围为遵循，区分不同行业、领域，科学准确划定。"},{"i":4,"n":"第四条","txt":"国家机关和涉及国家秘密的单位（以下简称机关、单位）应当严格依据保密事项范围，规范准确定密，不得比照类推、擅自扩大或者缩小国家秘密事项范围。"},{"i":5,"n":"第五条","txt":"国家保密行政管理部门负责对保密事项范围制定、修订和使用工作进行指导监督。中央有关机关负责组织制定、修订本行业、本领域保密事项范围，并对使用工作进行指导监督。地方各级保密行政管理部门负责对本行政区域内机关、单位使用保密事项范围工作进行指导监督。"},{"i":6,"n":"第六条","txt":"保密事项范围名称为“××工作国家秘密范围的规定”，包括正文和目录。"},{"i":7,"n":"第七条","txt":"正文应当以条款形式规定保密事项范围的制定依据，本行业、本领域国家秘密的基本范围，与其他保密事项范围的关系，解释机关和施行日期等内容。"},{"i":8,"n":"第八条","txt":"目录作为规定的附件，名称为“××工作国家秘密目录”，应当以表格形式列明国家秘密具体事项及其密级、保密期限（解密时间或者解密条件）、产生层级、知悉范围等内容。"},{"i":9,"n":"第九条","txt":"目录规定的国家秘密事项的密级应当为确定的密级。除解密时间和解密条件外，目录规定的保密期限应当为最长保密期限。国家秘密事项的产生层级能够明确的，知悉范围能够限定到机关、单位或者具体岗位的，目录应当作出列举。 对专业性强、弹性较大的条目或者名词，目录应当以备注形式作出说明。"},{"i":10,"n":"第十条","txt":"保密事项范围内容属于国家秘密的，应当根据保密法有关规定确定密级和保密期限。 未经保密事项范围制定机关同意，机关、单位不得擅自公开或者对外提供保密事项范围。"},{"i":11,"n":"第十一条","txt":"有下列情形的，中央有关机关应当与国家保密行政管理部门会商，组织制定或者修订保密事项范围： （一）主管行业、领域经常产生国家秘密、尚未制定保密事项范围的； （二）保密事项范围内容已不适应实际工作需要的； （三）保密事项范围内容与法律法规规定不相符合的； （四）因机构改革或者调整，影响保密事项范围适用的； （五）其他应当制定或者修订的情形。 其他机关、单位认为有上述情形，需要制定、修订保密事项范围的，可以向国家保密行政管理部门或者中央有关机关提出建议。"},{"i":12,"n":"第十二条","txt":"保密事项范围由主管相关行业、领域工作的中央有关机关负责起草；涉及多个部门或者行业、领域的，由承担主要职能的中央有关机关牵头负责起草；不得委托社会中介机构及其他社会组织或者个人起草。 国家保密行政管理部门、中央有关机关应当定期对起草工作进行研究会商。"},{"i":13,"n":"第十三条","txt":"中央有关机关起草保密事项范围，应当进行调查研究，总结梳理本行业、本领域国家秘密事项，广泛征求有关机关、单位和相关领域专家意见。"},{"i":14,"n":"第十四条","txt":"中央有关机关完成起草工作后，应当将保密事项范围送审稿送国家保密行政管理部门审核，同时提交下列材料： （一）保密事项范围送审稿的说明； （二）有关机关、单位或者相关领域专家的意见； （三）其他有关材料，主要包括所在行业、领域国家秘密事项总结梳理情况等。"},{"i":15,"n":"第十五条","txt":"国家保密行政管理部门对保密事项范围送审稿应当从以下方面进行审核： （一）形式是否符合本办法规定； （二）所列事项是否符合保密法关于国家秘密的规定； （三）所列事项是否涵盖所在行业、领域国家秘密； （四）所列事项是否属于法律法规要求公开或者其他不得确定为国家秘密的事项； （五）所列事项表述是否准确、规范并具有可操作性； （六）是否与其他保密事项范围协调、衔接； （七）其他需要审核的内容。 国家保密行政管理部门可以组织有关专家对保密事项范围送审稿进行评议，听取意见。"},{"i":16,"n":"第十六条","txt":"国家保密行政管理部门审核认为保密事项范围送审稿需要作出修改的，应当与中央有关机关会商议定；需要进一步征求意见的，应当征求有关机关、单位意见；无需修改的，应当会同中央有关机关形成保密事项范围草案和草案说明，并启动会签程序。"},{"i":17,"n":"第十七条","txt":"保密事项范围应当由国家保密行政管理部门、中央有关机关主要负责人共同签署批准。"},{"i":18,"n":"第十八条","txt":"保密事项范围使用中央有关机关的发文字号印发。印发时，应当严格控制发放范围，并注明能否转发以及转发范围。"},{"i":19,"n":"第十九条","txt":"机关、单位定密应当符合保密事项范围目录的规定。"},{"i":20,"n":"第二十条","txt":"机关、单位依据保密事项范围目录定密，应当遵循下列要求： （一）密级应当严格按照目录的规定确定，不得高于或者低于规定的密级； （二）保密期限应当在目录规定的最长保密期限内合理确定，不得超出最长保密期限；目录明确规定解密条件或解密时间的，从其规定； （三）知悉范围应当依据目录的规定，根据工作需要限定到具体人员；不能限定到具体人员的，应当限定到具体单位、部门或者岗位。"},{"i":21,"n":"第二十一条","txt":"机关、单位可以依据本行业、本领域和相关行业、领域保密事项范围目录，整理制定国家秘密事项一览表（细目），详细列举本机关、本单位产生的国家秘密事项的具体内容、密级、保密期限（解密条件或者解密时间）、产生部门或者岗位、知悉人员以及载体形式等。 国家秘密事项一览表（细目），应当经本机关、本单位审定后实施，并报同级保密行政管理部门备案。"},{"i":22,"n":"第二十二条","txt":"机关、单位对符合保密法规定，但保密事项范围正文和目录没有规定的不明确事项，应当按照保密法实施条例第十九条的规定办理。"},{"i":23,"n":"第二十三条","txt":"保密行政管理部门进行密级鉴定，需要适用保密事项范围的，应当以保密事项范围的目录作为依据；直接适用正文的，应当征求制定保密事项范围的中央有关机关意见。"},{"i":24,"n":"第二十四条","txt":"中央有关机关应当加强对本行业、本领域保密事项范围使用的教育培训，确保所在行业、领域准确理解保密事项范围的内容、使用要求。 机关、单位应当将保密事项范围的学习、使用纳入定密培训内容，确保定密责任人和承办人熟悉并准确掌握相关保密事项范围内容，严格依据保密事项范围定密。"},{"i":25,"n":"第二十五条","txt":"保密行政管理部门应当加强对机关、单位使用保密事项范围情况的监督检查，发现保密事项范围使用不当的，应当及时通知机关、单位予以纠正。"},{"i":26,"n":"第二十六条","txt":"有下列情形的，中央有关机关应当会同国家保密行政管理部门对保密事项范围作出书面解释： （一）目录内容需要明确具体含义的； （二）有关事项在目录中没有规定但符合正文规定情形，需要明确适用条件、适用范围的； （三）不同保密事项范围对同类事项规定不一致的； （四）其他需要作出解释的情形。 保密事项范围的解释和保密事项范围具有同等效力。"},{"i":27,"n":"第二十七条","txt":"机关、单位认为保密事项范围存在本办法第二十六条规定情形的，可以建议保密事项范围制定机关作出解释。"},{"i":28,"n":"第二十八条","txt":"保密事项范围的解释参照制定、修订程序作出。除涉及特殊国家秘密事项、需控制知悉范围的，应当按照保密事项范围印发范围发放。"},{"i":29,"n":"第二十九条","txt":"国家保密行政管理部门、中央有关机关应当每五年对保密事项范围及其解释进行一次清理，也可以根据工作需要适时组织清理，并作出继续有效、进行修订、宣布废止等处理；对属于国家秘密的保密事项范围及其解释，应当同时作出是否解密的决定。"},{"i":30,"n":"第三十条","txt":"保密事项范围部分内容宣布废止、失效或者由其他保密事项范围替代的，不影响该保密事项范围其他部分的效力。"},{"i":31,"n":"第三十一条","txt":"本办法施行前制定实施的保密事项范围，没有目录的应当即行清理，清理之前的继续有效，有关事项的保密期限和知悉范围按照保密法有关规定确定。"},{"i":32,"n":"第三十二条","txt":"本办法由国家保密局负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2017年4月1日起施行。"}],"baoxiangongsichangfunengliguanliguiding":[{"i":1,"n":"第一条","txt":"为加强保险公司偿付能力监管，有效防控保险市场风险，维护保单持有人利益，根据《中华人民共和国保险法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称保险公司，是指依法在中国境内设立的经营商业保险业务的保险公司和外国保险公司分公司。"},{"i":3,"n":"第三条","txt":"本规定所称偿付能力，是保险公司对保单持有人履行赔付义务的能力。"},{"i":4,"n":"第四条","txt":"保险公司应当建立健全偿付能力管理体系，有效识别管理各类风险，不断提升偿付能力风险管理水平，及时监测偿付能力状况，编报偿付能力报告，披露偿付能力相关信息，做好资本规划，确保偿付能力达标。"},{"i":5,"n":"第五条","txt":"中国银保监会以风险为导向，制定定量资本要求、定性监管要求、市场约束机制相结合的偿付能力监管具体规则，对保险公司偿付能力充足率状况、综合风险、风险管理能力进行全面评价和监督检查，并依法采取监管措施。"},{"i":6,"n":"第六条","txt":"偿付能力监管指标包括： （一）核心偿付能力充足率，即核心资本与最低资本的比值，衡量保险公司高质量资本的充足状况； （二）综合偿付能力充足率，即实际资本与最低资本的比值，衡量保险公司资本的总体充足状况； （三）风险综合评级，即对保险公司偿付能力综合风险的评价，衡量保险公司总体偿付能力风险的大小。 核心资本，是指保险公司在持续经营和破产清算状态下均可以吸收损失的资本。 实际资本，是指保险公司在持续经营或破产清算状态下可以吸收损失的财务资源。 最低资本，是指基于审慎监管目的，为使保险公司具有适当的财务资源应对各类可量化为资本要求的风险对偿付能力的不利影响，所要求保险公司应当具有的资本数额。 核心资本、实际资本、最低资本的计量标准等监管具体规则由中国银保监会另行规定。"},{"i":7,"n":"第七条","txt":"保险公司逆周期附加资本、系统重要性保险机构附加资本的计提另行规定。"},{"i":8,"n":"第八条","txt":"保险公司同时符合以下三项监管要求的，为偿付能力达标公司： （一）核心偿付能力充足率不低于50%； （二）综合偿付能力充足率不低于100%； （三）风险综合评级在B类及以上。 不符合上述任意一项要求的，为偿付能力不达标公司。"},{"i":9,"n":"第九条","txt":"保险公司董事会和高级管理层对本公司的偿付能力管理工作负责；总公司不在中国境内的外国保险公司分公司的高级管理层对本公司的偿付能力管理工作负责。"},{"i":10,"n":"第十条","txt":"保险公司应当建立健全偿付能力风险管理的组织架构，明确董事会及其相关专业委员会、高级管理层和相关部门的职责与权限，并指定一名高级管理人员作为首席风险官负责偿付能力风险管理工作。 保险公司应当通过聘用协议、书面承诺等方式，明确对于造成公司偿付能力风险和损失的董事和高级管理人员，公司有权追回已发的薪酬。 未设置董事会及相关专业委员会的外国保险公司分公司，由高级管理层履行偿付能力风险管理的相关职责。"},{"i":11,"n":"第十一条","txt":"保险公司应当建立完备的偿付能力风险管理制度和机制，加强对保险风险、市场风险、信用风险、操作风险、战略风险、声誉风险和流动性风险等固有风险的管理，以有效降低公司的控制风险。 固有风险，是指在现有的正常的保险行业物质技术条件和生产组织方式下，保险公司在经营和管理活动中必然存在的客观的偿付能力相关风险。 控制风险，是指因保险公司内部管理和控制不完善或无效，导致固有风险未被及时识别和控制的偿付能力相关风险。"},{"i":12,"n":"第十二条","txt":"保险公司应当按照保险公司偿付能力监管具体规则，定期评估公司的偿付能力充足状况，计算核心偿付能力充足率和综合偿付能力充足率，按规定要求报送偿付能力报告，并对其真实性、完整性和合规性负责。"},{"i":13,"n":"第十三条","txt":"保险公司应当按照中国银保监会的规定开展偿付能力压力测试，对未来一定时间内不同情景下的偿付能力状况及趋势进行预测和预警，并采取相应的预防措施。"},{"i":14,"n":"第十四条","txt":"保险公司应当建立偿付能力数据管理制度，明确职责分工，完善管理机制，强化数据管控，确保各项偿付能力数据真实、准确、完整。"},{"i":15,"n":"第十五条","txt":"保险公司应当按年度滚动编制公司三年资本规划，经公司董事会批准后，报送中国银保监会及其派出机构。保险公司应建立发展战略、经营规划、机构设立、产品设计、资金运用与资本规划联动的管理决策机制，通过优化业务结构、资产结构，提升内生资本的能力，运用适当的外部资本工具补充资本，保持偿付能力充足。"},{"i":16,"n":"第十六条","txt":"保险公司应当按照中国银保监会制定的保险公司偿付能力监管具体规则，每季度公开披露偿付能力季度报告摘要，并在日常经营的有关环节，向保险消费者、股东、潜在投资者、债权人等利益相关方披露和说明其偿付能力信息。 上市保险公司应当同时遵守证券监督管理机构相关信息披露规定。"},{"i":17,"n":"第十七条","txt":"中国银保监会定期发布以下偿付能力信息： （一）保险业偿付能力总体状况； （二）偿付能力监管工作情况； （三）中国银保监会认为需要发布的其他偿付能力信息。"},{"i":18,"n":"第十八条","txt":"保险公司聘请的会计师事务所应当按照法律法规的要求，独立、客观地对保险公司偿付能力报告发表审计意见。 精算咨询机构、信用评级机构、资产评估机构、律师事务所等中介机构在保险业开展业务，应当按照法律法规和执业准则要求，发表意见或出具报告。"},{"i":19,"n":"第十九条","txt":"保险消费者、新闻媒体、行业分析师、研究机构等可以就发现的保险公司存在未遵守偿付能力监管规定的行为，向中国银保监会反映和报告。"},{"i":20,"n":"第二十条","txt":"中国银保监会及其派出机构通过偿付能力风险管理能力评估、风险综合评级等监管工具，分析和评估保险公司的风险状况。"},{"i":21,"n":"第二十一条","txt":"中国银保监会及其派出机构定期对保险公司偿付能力风险管理能力进行监管评估，识别保险公司的控制风险。 保险公司根据评估结果计量控制风险的资本要求，并将其计入公司的最低资本。"},{"i":22,"n":"第二十二条","txt":"中国银保监会及其派出机构通过评估保险公司操作风险、战略风险、声誉风险和流动性风险，结合其核心偿付能力充足率和综合偿付能力充足率，对保险公司总体风险进行评价，确定其风险综合评级，分为A类、B类、C类和D类，并采取差别化监管措施。 风险综合评级具体评价标准和程序由中国银保监会另行规定。中国银保监会可以根据保险业发展情况和监管需要，细化风险综合评级的类别。"},{"i":23,"n":"第二十三条","txt":"中国银保监会及其派出机构建立以下偿付能力数据核查机制，包括： （一）每季度对保险公司报送的季度偿付能力报告的真实性、完整性和合规性进行核查； （二）每季度对保险公司公开披露的偿付能力季度报告摘要的真实性、完整性和合规性进行核查； （三）对保险公司报送的其他偿付能力信息和数据进行核查。 核心偿付能力充足率低于60%或综合偿付能力充足率低于120%的保险公司为重点核查对象。"},{"i":24,"n":"第二十四条","txt":"中国银保监会及其派出机构对保险公司偿付能力管理实施现场检查，包括： （一）偿付能力管理的合规性和有效性； （二）偿付能力报告的真实性、完整性和合规性； （三）风险综合评级数据的真实性、完整性和合规性； （四）偿付能力信息公开披露的真实性、完整性和合规性； （五）对中国银保监会及其派出机构监管措施的落实情况； （六）中国银保监会及其派出机构认为需要检查的其他方面。"},{"i":25,"n":"第二十五条","txt":"中国银保监会及其派出机构将根据保险公司的风险成因和风险程度，依法采取针对性的监管措施，以督促保险公司恢复偿付能力或在难以持续经营的状态下维护保单持有人的利益。"},{"i":26,"n":"第二十六条","txt":"对于核心偿付能力充足率低于50%或综合偿付能力充足率低于100%的保险公司，中国银保监会应当采取以下第（一）项至第（四）项的全部措施： （一）监管谈话； （二）要求保险公司提交预防偿付能力充足率恶化或完善风险管理的计划； （三）限制董事、监事、高级管理人员的薪酬水平； （四）限制向股东分红。 中国银保监会还可以根据其偿付能力充足率下降的具体原因，采取以下第（五）项至第（十二）项的措施： （五）责令增加资本金； （六）责令停止部分或全部新业务； （七）责令调整业务结构，限制增设分支机构，限制商业性广告； （八）限制业务范围、责令转让保险业务或责令办理分出业务； （九）责令调整资产结构，限制投资形式或比例； （十）对风险和损失负有责任的董事和高级管理人员，责令保险公司根据聘用协议、书面承诺等追回其薪酬； （十一）依法责令调整公司负责人及有关管理人员； （十二）中国银保监会依法根据保险公司的"},{"i":27,"n":"第二十七条","txt":"对于核心偿付能力充足率和综合偿付能力充足率达标，但操作风险、战略风险、声誉风险、流动性风险中某一类或某几类风险较大或严重的C类和D类保险公司，中国银保监会及其派出机构应根据风险成因和风险程度，采取针对性的监管措施。"},{"i":28,"n":"第二十八条","txt":"保险公司未按规定报送偿付能力报告或公开披露偿付能力信息的，以及报送和披露虚假偿付能力信息的，中国银保监会及其派出机构依据《中华人民共和国保险法》等进行处罚。"},{"i":29,"n":"第二十九条","txt":"保险公司聘请的会计师事务所的审计质量存在问题的，中国银保监会及其派出机构视具体情况采取责令保险公司更换会计师事务所、行业通报、向社会公众公布、不接受审计报告等措施，并移交注册会计师行业行政主管部门处理。"},{"i":30,"n":"第三十条","txt":"精算咨询机构、信用评级机构、资产评估机构、律师事务所等中介机构在保险业开展业务时，存在重大疏漏或出具的意见、报告存在严重质量问题的，中国银保监会及其派出机构视具体情况采取责令保险公司更换中介机构、不接受报告、移交相关部门处理等措施。"},{"i":31,"n":"第三十一条","txt":"保险集团、自保公司、相互保险组织适用本规定。相关法律法规另有规定的，从其规定。"},{"i":32,"n":"第三十二条","txt":"外国保险公司分公司，如在中国境内有多家分公司，应当指定其中一家分公司合并评估所有在华分公司的偿付能力，并履行本规定的偿付能力管理职责，承担偿付能力管理责任。"},{"i":33,"n":"第三十三条","txt":"本规定由中国银保监会负责解释和修订。"},{"i":34,"n":"第三十四条","txt":"本规定自2021年3月1日起施行。《保险公司偿付能力管理规定》（中国保险监督管理委员会令2008年第1号）同时废止。"}],"guangrongyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强光荣院管理，做好抚恤优待对象集中供养等工作，更好服务国防和军队建设，让退役军人成为全社会尊重的人，让军人成为全社会尊崇的职业，根据《军人抚恤优待条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"光荣院是国家集中供养孤老和生活不能自理的抚恤优待对象，并对其实行特殊保障的优抚事业单位。"},{"i":3,"n":"第三条","txt":"国务院退役军人事务部门负责指导全国光荣院的管理工作。县级以上地方人民政府退役军人事务部门是光荣院的主管部门（以下简称光荣院主管部门），对光荣院集中供养等工作进行管理、监督和检查。"},{"i":4,"n":"第四条","txt":"国家兴办光荣院，所需经费列入同级地方政府预算。光荣院的建设服务水平应当与当地经济和社会发展相适应，满足集中供养和服务需求。 国家鼓励公民、法人和其他组织对光荣院提供社会捐助和服务。 光荣院各项经费应当按照批复的预算执行，接受财政、审计部门和社会的监督。"},{"i":5,"n":"第五条","txt":"光荣院在建设、用地、水电、燃气、供暖、电信、农副业生产等方面享受国家有关社会福利机构的优惠政策。"},{"i":6,"n":"第六条","txt":"对在光荣院建设和管理工作中成绩显著的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":7,"n":"第七条","txt":"老年、残疾或者未满16周岁的烈士遗属、因公牺牲军人遗属、病故军人遗属和进入老年的残疾军人、复员军人、退伍军人，无法定赡养人、扶养人、抚养人或者法定赡养人、扶养人、抚养人无赡养、扶养、抚养能力且享受国家定期抚恤补助待遇的为集中供养对象，可以申请享受光荣院集中供养待遇。 光荣院在保障好集中供养对象的前提下，可利用空余床位为其他老年且无法定赡养人、扶养人或者法定赡养人、扶养人无赡养、扶养能力的抚恤优待对象提供优惠服务。 有条件的光荣院在满足上述对象集中供养、优惠服务的需求外，可面向其他抚恤优待对象开展优待服务。"},{"i":8,"n":"第八条","txt":"申请享受光荣院集中供养、优惠服务，应当由本人向户籍地村（社区）退役军人服务站提出申请，或者由其居民委员会（村民委员会）向乡镇（街道）退役军人服务站代为提出申请。 退役军人服务站应当在10个工作日内将申请材料报光荣院，光荣院初审后及时报其主管部门审核批准。 光荣院根据其主管部门下达的计划和任务安排集中供养、优惠服务对象入院，并根据实际情况接收优待服务对象。"},{"i":9,"n":"第九条","txt":"服务对象个人随身携带的款物和贵重物品委托光荣院保管的，应当签订财物保管协议。"},{"i":10,"n":"第十条","txt":"光荣院应当坚持入院自愿、出院自由的原则，规范入院、出院手续，建立服务对象的个人档案。 集中供养、优惠服务对象不再符合本办法第七条规定条件的，光荣院应当向其主管部门报告，由其主管部门核准后不再享受集中供养、优惠服务待遇。 集中供养、优惠服务对象死亡的，光荣院应当为其办理丧葬事宜，并向光荣院主管部门报告，其遗产按照《中华人民共和国继承法》的有关规定处理。 光荣院主管部门应当定期核准集中供养、优惠服务对象人数，通报同级人民政府财政部门，并报上一级人民政府退役军人事务部门，由省级人民政府退役军人事务部门汇总后报国务院退役军人事务部门。"},{"i":11,"n":"第十一条","txt":"光荣院应当为服务对象提供下列供养服务： （一）提供饮食； （二）提供生活必需品； （三）提供住房； （四）提供医疗、康复、护理、保健服务； （五）提供学习娱乐、精神关怀服务； （六）提供清洁卫生、安全保卫服务； （七）提供心理抚慰等社会工作服务； （八）其他服务。 集中供养对象未满16周岁或者已满16周岁仍在接受义务教育的，光荣院应当保障其接受义务教育所需费用。"},{"i":12,"n":"第十二条","txt":"光荣院提供的饮食应当符合食品安全要求，并根据服务对象的需要适当调整。 光荣院应当为服务对象提供必备的服装、被褥、生活用具和适合老年人、残疾人居住需求的生活设施，并为其提供适当的出行条件。 光荣院应当保持服务对象住房整洁，帮助其搞好个人卫生，并提供必要的照料，保证其在院期间的人身安全。"},{"i":13,"n":"第十三条","txt":"集中供养对象按照《优抚对象医疗保障办法》的规定享受医疗待遇。 光荣院应当与当地医疗机构建立协作关系，保证患病的服务对象得到及时治疗，并积极推进医养结合的服务模式。 光荣院应当建立服务对象个人医疗和健康档案，为服务对象提供定期体检服务和健康教育服务，帮助服务对象制定医疗康复计划。"},{"i":14,"n":"第十四条","txt":"光荣院实行24小时值班制度，对生活不能自理的服务对象实行全日制护理，并配置配备拐杖、轮椅或者其它辅助器具。"},{"i":15,"n":"第十五条","txt":"光荣院应当为服务对象创造良好的生活环境，安排好物质文化生活，组织学习教育，开展有益于身心健康的文体休闲活动。 对有能力并自愿参加劳动和公益活动的服务对象，光荣院可以安排其从事力所能及的劳动和公益活动，丰富日常生活。"},{"i":16,"n":"第十六条","txt":"光荣院应当关爱服务对象，为其组织必要的心理咨询和社会交往活动，使服务对象得到精神慰藉。"},{"i":17,"n":"第十七条","txt":"光荣院应当重点服务保障好集中供养对象，并结合实际视情免除相关费用。 光荣院应当为优惠服务对象提供优惠服务，适当减免相关费用。 光荣院面向其他抚恤优待对象开展优待服务，按规定收取护理费、床位费、伙食费、医疗费等相关费用。 优惠及优待服务对象的具体范围，收费及减免的具体项目、标准等，由省级人民政府退役军人事务部门商财政、民政等有关部门统筹考虑本地财力状况规定，并加大对荣获个人二等功以上奖励的退役军人和荣获个人二等功以上奖励现役军人父母的优惠力度。"},{"i":18,"n":"第十八条","txt":"光荣院集中供养和优惠、优待服务标准由省级人民政府退役军人事务部门商财政等有关部门制定，经省级人民政府批准后公布执行，并根据当地经济社会发展水平适时调整。"},{"i":19,"n":"第十九条","txt":"光荣院实行院长负责制，院长由光荣院主管部门任命，也可以向社会公开招聘。 光荣院工作人员应当经过光荣院主管部门培训考核，专业岗位工作人员应当具备相应的水平和能力。 光荣院应当按集中供养对象人数的25%配备工作人员，其中管理人员占工作人员总数的比例不超过20%。"},{"i":20,"n":"第二十条","txt":"光荣院应当设立院务管理委员会。院务管理委员会的成员由光荣院全体人员推选产生，院务管理委员会可以下设专门委员会。 院务管理委员会应当定期召开会议，参与光荣院工作的管理和监督。"},{"i":21,"n":"第二十一条","txt":"光荣院应当定期公布国家对抚恤优待对象的抚恤补助政策和标准，公开院内工作流程、经费开支等情况，明示服务宗旨和项目，并接受服务对象的监督。"},{"i":22,"n":"第二十二条","txt":"光荣院应当按照国家有关规定，建立健全安全、消防、卫生、财务、档案管理等制度。"},{"i":23,"n":"第二十三条","txt":"有条件的光荣院可以开展以改善服务对象生活条件为目的的农副业生产。服务对象自愿参加光荣院组织开展的农副业生产活动，光荣院应当给予报酬。"},{"i":24,"n":"第二十四条","txt":"光荣院应当建立荣誉室或者陈列室，收集、编撰、陈列、展示有关烈士、因战因公牺牲军人和服务对象的光荣事迹，与驻地国家机关、人民团体、社会组织、企业事业单位、学校、部队、社区等开展精神文明共建活动，充分发挥其爱国主义教育和革命传统教育作用。"},{"i":25,"n":"第二十五条","txt":"各地应当优先利用现有光荣院及各类养老机构中设立的光荣楼（层、间）等资源，为符合条件的抚恤优待对象提供集中供养等服务。集中供养需求大的地方，可以根据本地实际情况兴建、改扩建光荣院，每所光荣院床位数应当不低于50张，床位利用率应当达到80%以上。"},{"i":26,"n":"第二十六条","txt":"光荣院的各类建筑应当根据老年人、残疾人和未成年人生活、安全需要进行设计，符合无障碍标准建筑设计规范的要求。"},{"i":27,"n":"第二十七条","txt":"服务对象居住用房每间应当不小于15平方米，配置卫生间和洗澡间。 光荣院应当具备开展日常工作和服务所必需的办公室、值班室、厨房、餐厅、储藏室、活动室等辅助用房。有条件的地区还可以建设用于康复保健、文体娱乐等方面的功能室和室外活动场所。"},{"i":28,"n":"第二十八条","txt":"光荣院应当配置应急呼叫设备，并根据当地气候条件和服务对象的实际需要配置取暖、降温设备。 光荣院应当维护好照明、通讯、消防、报警、取暖、降温、排污和水电供应等设施和生活设备，保证其正常运转。"},{"i":29,"n":"第二十九条","txt":"光荣院应当设立医疗室，并视条件配备常用和急救所需的医疗器械、设备及药品。"},{"i":30,"n":"第三十条","txt":"光荣院应做好室外绿化、环境美化工作，为服务对象提供安静、整洁、优美的生活环境。"},{"i":31,"n":"第三十一条","txt":"光荣院的土地、房屋、设施、设备和其他财产依法归光荣院管理和使用，任何单位和个人不得侵占。 侵占、破坏光荣院财物的，由当地人民政府退役军人事务部门责令限期改正，并恢复原状；造成损失的，依法承担赔偿责任。"},{"i":32,"n":"第三十二条","txt":"服务对象应当珍惜荣誉，遵守光荣院的各项规定，自觉配合工作人员的管理。对违反相关规定的，由光荣院和光荣院主管部门进行批评教育，情节严重的，依法追究相应责任。 服务对象因违法犯罪被判处有期徒刑、剥夺政治权利的，中止其集中供养和优惠、优待服务资格；被判处死刑、无期徒刑的，取消其集中供养和优惠、优待服务资格。"},{"i":33,"n":"第三十三条","txt":"光荣院违反本办法的规定，提供的集中供养和优惠、优待服务不符合要求，由光荣院主管部门责令改正；逾期不改正的，对直接负责的责任人和其他主管人员依法给予处分，造成损失的，依法承担赔偿责任。 光荣院造成服务对象人身伤害事故的，应当依法承担赔偿责任。"},{"i":34,"n":"第三十四条","txt":"光荣院主管部门及其工作人员有下列行为之一的，由上级人民政府退役军人事务部门对其直接负责的责任人和其他主管人员进行批评教育，限期改正；情节严重的，依法给予处分；构成犯罪的，依法追究刑事责任： （一）违反规定审批光荣院集中供养、优惠服务待遇的； （二）贪污、挪用、截留、私分光荣院款物的； （三）光荣院建设和管理中有滥用职权、玩忽职守、徇私舞弊行为的； （四）其他违反相关法律法规行为的。"},{"i":35,"n":"第三十五条","txt":"各级民政部门主管的各类福利机构中设立的光荣间、光荣楼可以参照本办法的规定执行。"},{"i":36,"n":"第三十六条","txt":"符合儿童福利机构收留抚养条件的，按相关规定执行。"},{"i":37,"n":"第三十七条","txt":"本办法自2020年6月1日起施行。"}],"quanguominzutuanjiejinbujiaoyujidipingshenmingming21fc97":[{"i":1,"n":"第一条","txt":"为了规范全国民族团结进步教育基地评审命名工作，促进民族团结进步事业发展，根据有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"全国民族团结进步教育基地是国家民委评审命名，具备宣传教育功能，在促进民族团结、密切民族关系、维护国家统一等方面具有重要影响的文物博物类、革命纪念类、旅游文教类等场所。"},{"i":3,"n":"第三条","txt":"全国民族团结进步教育基地评审命名工作坚持实事求是、公开公正、竞争择优、面向基层的原则。"},{"i":4,"n":"第四条","txt":"全国民族团结进步教育基地一般每3年命名一批。"},{"i":5,"n":"第五条","txt":"全国民族团结进步教育基地应当具备下列基本条件： （一）能体现不同历史时期我国各族人民之间的亲密关系，有助于宣传党和国家的民族理论政策、法律法规和民族知识，有利于维护民族团结和祖国统一，促进各民族共同团结奋斗、共同繁荣发展； （二）具备开展民族团结进步宣传教育活动的实物、资料、场地或配套设施； （三）有相应的工作机构和专（兼）职工作人员，有必要的经费保障，能够保证民族团结进步宣传教育活动的正常开展； （四）有健全的规章制度和完整的工作档案，无违法违纪行为。"},{"i":6,"n":"第六条","txt":"符合全国民族团结进步教育基地条件的场所，逐级向所在省、自治区、直辖市民族工作部门申报，由省、自治区、直辖市民族工作部门审核公示后，经省、自治区、直辖市人民政府同意，报国家民委。 中央国家机关所属场所由主管部门审核后向国家民委推荐。 人民解放军和武警部队申报场所由中国人民解放军总政治部统一审核后向国家民委推荐。"},{"i":7,"n":"第七条","txt":"国家民委监督检查司负责组织对推荐对象的评审，并将通过评审的场所名单向社会公示，公示期不少于10个工作日。"},{"i":8,"n":"第八条","txt":"公示期满后，监督检查司负责将拟命名为全国民族团结进步教育基地的场所名单及相关材料报国家民委委务会议审议。"},{"i":9,"n":"第九条","txt":"国家民委发布决定，命名全国民族团结进步教育基地，颁发牌匾，给予一次性经费补助，用于开展民族团结进步宣传教育活动。"},{"i":10,"n":"第十条","txt":"已命名的全国民族团结进步教育基地，不能履行民族团结进步宣传教育职能或者不再具备本办法规定条件的，国家民委责令其限期整改或者予以撤销命名。 按照国家民委关于涉及民族方面突发事件分级标准，对发生因处置不当造成涉及民族方面重大或者特别重大事件的教育基地，国家民委予以撤销命名。"},{"i":11,"n":"第十一条","txt":"全国民族团结进步教育基地应当制定基地中长期发展规划，建立完整的档案制度，有计划地对专（兼）职工作人员进行相关职业技能培训。"},{"i":12,"n":"第十二条","txt":"全国民族团结进步教育基地应当充实宣传教育材料，充分利用现代科技、丰富宣传教育手段、增强宣传教育效果，深入开展民族团结进步宣传教育。"},{"i":13,"n":"第十三条","txt":"全国民族团结进步教育基地应当对大、中、小学校集体、现役军人、老年人和残疾人等给予免票参观等优惠待遇。有条件的教育基地，应当逐步在重大节庆日、纪念日免费向社会开放。"},{"i":14,"n":"第十四条","txt":"地方各级人民政府民族工作部门负责教育基地的考核、推荐，支持教育基地的建设和发展，推动教育基地之间的交流合作，指导教育基地开展宣传教育活动，提高宣传教育的影响力。 地方各级人民政府及其相关部门应当根据实际情况对教育基地予以适当经费补助或者采取其他方式予以扶持。"},{"i":15,"n":"第十五条","txt":"本办法自颁布之日起施行。"}],"quanguohuanbaoxitongliuxiangjinling":[],"guanyuzhongyangdangzhengjiguangongzuorenyuanzaiguo55e3a0":[],"guanyuyinfajiaqiangdianwangdiaofenggongzuoruogangufce93b":[{"i":1,"n":"第一条","txt":"为适应电网用电负荷的变化及电力负荷的峰谷差不断增大的需要，保证电网安全稳定运行和供电质量，合理利用资源和能源，特制定本规定。"},{"i":2,"n":"第二条","txt":"调峰工作是电力生产最基本的工作之一，对保证全网发电设备安全运行、电网正常稳定运行和用户用电质量有重要作用。各电网应高度重视电网调峰工作并根据电网具体情况采取切实有效的行政、经济、技术等方面措施加强调峰工作。"},{"i":3,"n":"第三条","txt":"本规定适用于各跨省电网、供电局及并网运行的全部发电厂(包括集资、合资、地方和企业自备发电厂)。电力行业的规划、设计、基建、调度等部门均应遵守本规定。"},{"i":4,"n":"第四条","txt":"所有并网的发电厂都有责任、有义务参加电网调峰。电网应在保证安全的前提下，根据经济调度的原则实行全网统一调度。"},{"i":5,"n":"第五条","txt":"当电网情况发生变化时，电网调度部门应及时修改发用电计划以保证电网运行的经济合理性，下级调度部门要严格按照修改后的计划运行。"},{"i":6,"n":"第六条","txt":"各电管局、电力局要根据本规定的要求与各电网的具体情况制定实施细则并建立相应的调峰工作责任制与奖惩办法。实施细则等应报能源部备案。"},{"i":7,"n":"第七条","txt":"各电网在制定电网发展规划、发电设备选型、审定非局属电厂(包括委托代管电厂)并网协议时，应充分考虑电网调峰工作的需要。新建火力发电厂除燃用劣质煤外，其调峰能力不应低于额定电负荷的35%-40%。在主辅设备选型时，应避免采用影响机组达到上述调峰能力的设备。如转子材料脆性转变温度高的汽轮机，调峰能力差的直流炉和三排汽20万千瓦机组等。"},{"i":8,"n":"第八条","txt":"中小型水电站应优先开发有调节性能的水库，梯级连续开发应先建上游龙头水库。"},{"i":9,"n":"第九条","txt":"各电网可选择煤质较好、较稳定的地区有计划地建设或改造一些重点调峰厂，配以调峰性能较强的主辅设备及必要的混煤、配煤设施。由于电网稳定性或地区负荷等电网结构原因影响机组调峰能力发挥的地区，应在进行技术经济比较后安排电网建设或改造项目予以解决。"},{"i":10,"n":"第十条","txt":"在调峰矛盾比较突出的地区，在经过技术经济论证后应建设一些调峰能力强的发电工程，如抽水蓄能电站，燃气、蒸汽联合循环电站等。"},{"i":11,"n":"第十一条","txt":"本规定解释权属能源部。"},{"i":12,"n":"第十二条","txt":"按照年度和月度电力生产计划，根据电网调峰基本原则、经济调度原则和省网间互供电协议，由网、省局制定每日送、受电计划。"},{"i":13,"n":"第十三条","txt":"省网间交换的电力、电量应按每日送、受电计划进行统计和考核。"},{"i":14,"n":"第十四条","txt":"省网联络线交换电力、电量的考核与结算应与电网频率挂钩。频率低于规定值时，超受或少送电量者要扣减相应售电量，少受或多送者要追加相应售电量作为奖励且联络线电量按实际结算。频率高于规定值时，多送或少受电量者扣减相应售电量且联络线电量按计划结算，多受或少送电量者追加售电量。"},{"i":15,"n":"第十五条","txt":"省网间互供电价，应实行高峰低谷电价和丰、枯季节差价。各局可根据现行互供电价作价原则和多种电价实施办法规定提出方案，报部审批后执行。"},{"i":16,"n":"第十六条","txt":"跨省电网必须配备网间联络线计量自动化装置，并要保证其准确性。"},{"i":17,"n":"第十七条","txt":"各电管局、电力局应对所有并网运行的发电设备定期核定其调峰能力，明确最高、最低出力和负荷变化率，以及主要调峰运行方式，作为电网调度和考核的依据。"},{"i":18,"n":"第十八条","txt":"核定机组调峰能力应做到：设备制造或电厂设计已规定调峰能力的机组应达到设计调峰能力。 中低压凝汽机组原则上应具备两班制或停炉不停机进行调峰的能力。按基本负荷设计的10万千瓦以上的机组在近期应达到以下调峰能力。"},{"i":19,"n":"第十九条","txt":"各电管局、电力局应根据电网设备的具体情况与峰谷差的要求，有计划地安排提高水、火电设备调峰能力的技术改造与科学试验。"},{"i":20,"n":"第二十条","txt":"各电管局、电力局和发电厂应高度重视调峰运行机组的安全性，制订必要的调峰机组安全技术措施，并对设备进行必要完善和改造，加强运行管理和培训工作。"},{"i":21,"n":"第二十一条","txt":"各电网应结合推行内部经济责任制，采用追加和扣减上网电量、峰谷电价和分时考核电量等办法对发电厂调峰工作进行考核和奖惩。"},{"i":22,"n":"第二十二条","txt":"各电管局、电力局应根据具体情况制定火电机组参与调峰后发电量指标、煤耗指标、燃油指标、检修间隔、检修费用、临检次数及各项安全指标等项内容的内部补偿政策，并根据设备实际调峰情况予以补偿。"},{"i":23,"n":"第二十三条","txt":"在丰水期，应尽可能减少水电厂弃水调峰损失，火电厂应采取特殊措施扩大调峰能力。应采用丰枯电价鼓励火电调峰，多发水电。要制定相应措施将多发水电的收益对火电厂进行适当的补偿。"},{"i":24,"n":"第二十四条","txt":"各电管局、电力局应采取切实有效的办法加强对并网运行非局属电厂的调峰管理，同时注意保证非局属电厂的合理经济权益。 非局属电厂在初步设计与设备选型时应征得所在局的同意。对调峰能力低于电网平均峰谷差的发电设备并网运行应向电网交纳相应的调峰补偿费用。 非局属发电厂并网前应签订包含调峰内容的并网协议，并按并网协议进行调峰考核，并可采用追加扣减上网电量的办法对非局属电厂调峰情况进行考核和奖惩。对并网运行的非局属火电厂可采用峰谷分时调峰电价，以正常核定的上网电价为基础，按具体情况上浮或下浮，峰谷电价比值可为2-3倍。对并网运行的非局属水电厂可采取丰水的弃水期、枯水期不同季节的分时调峰电价。丰水的弃水期上网电价可比正常上网电价低30%至50%，枯水期上网电价可比正常上网电价高30%至50%。 峰谷和丰枯浮动电价应按规定的审批程序办理。"},{"i":25,"n":"第二十五条","txt":"梯级水电厂应实行统一调度，实行梯级优化调度和经济运行。"},{"i":26,"n":"第二十六条","txt":"各电管局、电力局应结合实际情况逐步推行高峰低谷用电价格。在水电比重大的电网，对用户试行丰枯季节差价。用经济与行政相结合的办法，促进用户削峰、填谷，共同做好电网调荷节电工作。"},{"i":27,"n":"第二十七条","txt":"各电管局、电力局应根据情况制订适当办法，开放低谷用电，对有条件的用户鼓励其低谷用电。"},{"i":28,"n":"第二十八条","txt":"各省局要核定各供电局的用电负荷率等指标，以加强供电局的用电管理。在采用内部电价对购网电量进行结算时，应实行峰谷差价。"},{"i":29,"n":"第二十九条","txt":"各供电局购网电量计量点和大用户应装设分时电度表，并保证其准确性。"}],"guanyuyinfajiaqiangdianwangdiaoduguanligongzuoderuefaf7d":[],"guanyushoulixianggangaomentebiexingzhengqutuijiang046e05":[{"i":1,"n":"第一条","txt":"为了做好香港、澳门特别行政区（以下称“特别行政区”）推荐国家科学技术奖的受理工作，根据《国家科学技术奖励条例》的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于受理特别行政区政府推荐国家科学技术奖的活动。"},{"i":3,"n":"第三条","txt":"特别行政区政府推荐的国家最高科学技术奖、国家自然科学奖、国家技术发明奖、国家科学技术进步奖的候选人，应当是在科学发现、技术发明和促进科学技术进步等方面做出创造性突出贡献，符合《国家科学技术奖励条例》及其实施细则所规定条件的特别行政区居民（包括永久性居民和已在特别行政区取得居留权、但尚未取得永久居留权的人士）中的中国公民，或者在特别行政区内从事科学研究、技术开发的其他中国籍人士。 特别行政区政府推荐的中华人民共和国国际科学技术合作奖的候选人，应当是在特别行政区工作或者为特别行政区科学技术事业做出重要贡献的外国人或者外国组织。"},{"i":4,"n":"第四条","txt":"特别行政区政府推荐的国家科学技术奖候选人（项目），其主要科学研究、技术开发活动应当是在特别行政区进行和完成；与特别行政区以外的学者合作进行科学研究、技术开发工作的，该候选人必须是该项工作的主要完成人。 前款规定的科学研究、技术开发工作主要在特别行政区以外的国内其他地区进行和完成的，按照《国家科学技术奖励条例》及其实施细则的规定，通过相应渠道推荐。"},{"i":5,"n":"第五条","txt":"特别行政区政府可指定机构负责推荐国家科学技术奖的日常事务（以下称“日常事务机构”）。所指定的机构报国务院科学技术行政部门备案。"},{"i":6,"n":"第六条","txt":"特别行政区政府推荐国家科学技术奖候选人，应当征得被推荐人的同意，并填写由国家科学技术奖励工作办公室制作的统一格式的推荐书，提供必要的证明和客观的评价材料。推荐书和有关材料应当完整、真实、可靠。"},{"i":7,"n":"第七条","txt":"国家科学技术奖励实行限额推荐制度。国家科学技术奖励工作办公室每年向特别行政区政府通报当年国家科学技术奖推荐限额。"},{"i":8,"n":"第八条","txt":"凡存在知识产权以及有关完成单位、完成人员等方面争议的，在争议未解决之前，不得推荐参加国家科学技术奖评审。"},{"i":9,"n":"第九条","txt":"国家法律、法规或者特别行政区规定必须取得相关许可证，且直接关系到人身和社会安全、公共利益的项目，如动植物新品种、食品、药品、基因工程技术和产品等，在未获得许可证之前，不得推荐参加国家科学技术奖评审。"},{"i":10,"n":"第十条","txt":"特别行政区的法定高等学校，由特别行政区政府认定具备相应资格的机构以及人士，可按照特别行政区政府关于国家科学技术奖候选人推荐办法，向日常事务机构推荐。 日常事务机构负责组织由特别行政区政府认定资格的同行专家，对有关人士和机构提出的国家科学技术奖候选人和项目进行客观、公正的评价，并根据评价意见向特别行政区政府提出国家科学技术奖的推荐人选、项目及相关的奖励种类建议。 特别行政区政府根据同行专家的评价意见和日常事务机构的建议做出决定，在规定的时间内向国家科学技术奖励工作办公室进行推荐。"},{"i":11,"n":"第十一条","txt":"特别行政区内的国家最高科学技术奖获奖人每年可推荐1名（项）所熟悉专业的国家科学技术奖；中国科学院院士、中国工程院院士每年度可5人以上共同推荐1名（项）所熟悉专业的国家科学技术奖。 本项推荐由日常事务机构汇总，统一报送国家科学技术奖励办公室，不受当年推荐指标限制。"},{"i":12,"n":"第十二条","txt":"国家科学技术奖励工作办公室负责对推荐材料进行形式审查。对不符合规定的推荐材料，要求推荐机构和人员在规定的时间内补正；逾期不补正或者经补正仍不符合要求的，不提交评审。"},{"i":13,"n":"第十三条","txt":"同一项目的技术内容不得在同一年度重复参加国家自然科学奖、国家技术发明奖和国家科学技术进步奖的评审。"},{"i":14,"n":"第十四条","txt":"经评定未授予国家科学技术奖的候选人，如果其完成的项目或者工作在此后的研究开发活动中获得新的实质性进展，并符合相关规定条件的，可以按照规定的程序重新推荐。"},{"i":15,"n":"第十五条","txt":"国家科学技术奖特别行政区候选人的具体推荐办法，由特别行政区政府制定，并报国务院科学技术行政部门备案。"},{"i":16,"n":"第十六条","txt":"本规定自2003年2月1日起施行。"}],"guanyuzaiwaijiaohuodongzhongzouchangguogedeguiding":[{"i":1,"n":"第一条","txt":"为规范外交活动中奏唱中国国歌的场合和礼仪，根据《中华人民共和国国歌法》第四条第七项、第九条第一款，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外交活动，主要指中华人民共和国国家领导人、外交部长及外交部、驻外外交机构和其他受权执行相关任务的国家机关及其人员，代表中华人民共和国进行对外交往的活动。 本规定所称驻外外交机构，是指中华人民共和国驻外国的使馆、领馆以及常驻联合国等政府间国际组织的代表团等代表机构。"},{"i":3,"n":"第三条","txt":"外交活动中奏唱中国国歌，应当符合惯例、平衡、对等、礼让原则。"},{"i":4,"n":"第四条","txt":"在中华人民共和国举行以下外交活动，奏唱中国国歌： （一）国家主席、国务院总理、国家副主席分别为来华进行国事、正式访问的外国国家元首、政府首脑和国家副元首举行欢迎仪式； （二）外国国家元首、政府首脑等向人民英雄纪念碑献花圈； （三）建交（复交）、授勋仪式等重大外交庆典活动； （四）中华人民共和国国家领导人、外交部长及其他受权执行相关任务的高级别官员代表中华人民共和国主持国际会议和多边外交活动，视活动要求根据第三条安排； （五）其他应当奏唱国歌的外交场合。"},{"i":5,"n":"第五条","txt":"在中华人民共和国外举行以下外交活动，根据东道主规定和习惯做法，奏唱中国国歌： （一）在双边场合，如奏唱对方国歌，亦应当奏唱中国国歌，顺序尊重东道主惯例； （二）由中方主办的外交活动，参照第四条第三项、第四项奏唱中国国歌。"},{"i":6,"n":"第六条","txt":"驻外外交机构举行升国旗仪式时，奏唱中国国歌。举行开馆仪式、国庆招待会、庆祝建交等活动，奏唱中国国歌。驻在国有特殊规定和习惯做法的除外。"},{"i":7,"n":"第七条","txt":"双边外交活动中奏唱中国国歌和外国国歌，中方主办活动，一般先奏唱外国国歌；外方主办活动，一般先奏唱中国国歌。有特殊规定的除外。"},{"i":8,"n":"第八条","txt":"外交部及驻外外交机构应当向有关国家外交部门和有关国际组织提供中国国歌标准演奏曲谱和国歌官方录音版本。"},{"i":9,"n":"第九条","txt":"除有关国家国歌或国际组织会歌外，中国国歌不得与其他歌曲紧接奏唱。"},{"i":10,"n":"第十条","txt":"外交活动中奏唱中国国歌时，在场人员应当肃立，举止庄重，不得有不尊重国歌的行为。"},{"i":11,"n":"第十一条","txt":"其他部门和地方主办的外交活动中奏唱中国国歌，参照本规定执行。"},{"i":12,"n":"第十二条","txt":"本规定由外交部负责解释。"},{"i":13,"n":"第十三条","txt":"本规定自公布之日起施行。"}],"guanyuwoguotiyuyundongxiangmutongjishijieguanjunao070784":[{"i":1,"n":"第一条","txt":"为了使我国统计世界冠军的工作更加规范化、科学化，特制订本办法。"},{"i":2,"n":"第二条","txt":"体育运动竞赛以获得世界冠军、奥运会冠军(金牌)为最高名次。"},{"i":3,"n":"第三条","txt":"我国体育运动项目统计为世界冠军的必须符合以下三条： 一、确认世界冠军的项目必须是成立了全国单项运动协会并加入了该项目国际联合会的项目。 二、世界冠军必须是在单项国际联合会正式批准举办的世界锦标赛、世界杯赛或世界杯系列赛总决赛中获得(各项目确认世界冠军的大赛名称附后)，必须是上场正式比赛的运动员，并有大会授予的金牌或证书。 三、在夏季或冬季奥林匹克运动会上获得比赛项目的冠军。"},{"i":4,"n":"第四条","txt":"除上述三条规定以外，对于我国一些高水平的、在国际上有一定影响的项目，也可以确定一至二个最高水平的国际性大赛做为统计世界冠军的比赛。"},{"i":5,"n":"第五条","txt":"凡属要列入统计世界冠军、奥运会冠军(金牌)的项目，均要按申报程序报国家体委综合司审核，并上报国家体委批准。"},{"i":6,"n":"第六条","txt":"符合本规定第三条的项目要建立报告制度。 凡获得世界冠军、奥运会冠军(金牌)的项目要在大赛结束一个月内(12月比赛的现象要在比赛之后立即)向国家体委综合司报告成绩。报告的方法是，由该项目所属的业务部门填写成绩报告表(见附件2)，并将成绩册或复印件附后报综合司。 国家体委综合司每半年和年底汇总统计后上报委领导。"},{"i":7,"n":"第七条","txt":"每年12月底及奥运会年由国家体委综合司通过新华社、中国体育报向全国公布我国取得世界冠军、奥运会冠军(金牌)的数字。"},{"i":8,"n":"第八条","txt":"本办法由国家体委综合司负责解释。"}],"guanyushouyutiyugongzuogongxianzhangdeguiding":[],"guanyubanfameitanqiyezonggongchengshizerenzhideton3c9e5c":[],"guanjianxinxijichusheshishangyongmimashiyongguanli0f441b":[{"i":1,"n":"第一条","txt":"为规范关键信息基础设施商用密码使用，保护关键信息基础设施安全，根据《中华人民共和国密码法》、《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》、《商用密码管理条例》和《关键信息基础设施安全保护条例》、《网络数据安全管理条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"依据《中华人民共和国网络安全法》、《关键信息基础设施安全保护条例》等法律、行政法规和国家有关规定认定的关键信息基础设施的商用密码使用管理，适用本规定。"},{"i":3,"n":"第三条","txt":"国家密码管理部门会同国家网信部门、国务院公安部门负责规划、指导和监督全国的关键信息基础设施商用密码使用管理工作，建立关键信息基础设施商用密码使用管理信息共享机制。 县级以上地方各级密码管理部门会同网信部门、公安机关负责指导和监督本行政区域的关键信息基础设施商用密码使用管理工作。"},{"i":4,"n":"第四条","txt":"关键信息基础设施保护工作部门（以下简称保护工作部门）在职责范围内负责监督管理本行业、本领域关键信息基础设施商用密码使用工作，单独编制本行业、本领域商用密码使用规划或者纳入本行业、本领域的关键信息基础设施安全规划并组织实施，指导本行业、本领域关键信息基础设施运营者（以下简称运营者）开展商用密码相关制度、人员、经费等保障工作。 保护工作部门应当于每年3月31日前向国家密码管理部门、国家网信部门、国务院公安部门报告上一年度本行业、本领域关键信息基础设施商用密码使用管理情况。 关键信息基础设施发生涉及商用密码的重大网络安全事件或者发现涉及商用密码的重大网络安全威胁时，保护工作部门应当及时向国家密码管理部门、国家网信部门、国务院公安部门报告，指导运营者开展应急处置，必要时开展商用密码应用安全性评估。"},{"i":5,"n":"第五条","txt":"运营者应当按照相关法律、行政法规和国家有关规定，遵循国家商用密码管理、网络安全等级保护、关键信息基础设施安全保护等制度要求，使用商用密码保护关键信息基础设施，同步规划、同步建设、同步运行商用密码保障系统，并定期开展商用密码应用安全性评估。 运营者应当于每年1月31日前向所属的保护工作部门报告上一年度关键信息基础设施商用密码使用以及商用密码应用安全性评估开展情况。"},{"i":6,"n":"第六条","txt":"运营者应当加强关键信息基础设施商用密码使用制度保障，建立商用密码使用、应急处置、重大事件报告等关键信息基础设施商用密码使用管理制度。 运营者的主要负责人对关键信息基础设施商用密码使用管理负总责，负责关键信息基础设施商用密码使用和涉及商用密码的重大网络安全事件处置工作。"},{"i":7,"n":"第七条","txt":"运营者应当加强关键信息基础设施商用密码使用人员保障，配备取得密码相关专业学历或者密码相关国家职业技能等级认定证书的专业人员分别承担密钥管理员、密码操作员等职责，配备具有安全审计专业能力的人员承担密码安全审计员职责。 运营者应当对密码相关专业人员进行安全背景审查，并定期组织其参加密码相关业务技能培训，提高密码相关专业人员的商用密码使用能力。"},{"i":8,"n":"第八条","txt":"运营者应当加强关键信息基础设施商用密码使用和应用安全性评估经费保障，将商用密码使用和应用安全性评估经费纳入网络安全和信息化经费安排。"},{"i":9,"n":"第九条","txt":"关键信息基础设施使用的商用密码产品、服务应当经检测认证合格，使用的密码算法、密码协议、密钥管理机制等商用密码技术应当通过国家密码管理部门审查鉴定。 运营者采购涉及商用密码的网络产品和服务，影响或者可能影响国家安全的，应当按照《网络安全审查办法》进行网络安全审查。"},{"i":10,"n":"第十条","txt":"关键信息基础设施应当按照国家数据安全保护、个人信息保护有关要求，使用商用密码对其存储、使用、传输的核心数据、重要数据和个人信息进行保护。"},{"i":11,"n":"第十一条","txt":"关键信息基础设施规划阶段，其运营者应当依照相关法律、行政法规和标准规范，根据商用密码应用需求，制定商用密码应用方案，规划商用密码保障系统并纳入关键信息基础设施安全规划统筹部署。 运营者应当自行或者委托商用密码检测机构对商用密码应用方案进行商用密码应用安全性评估。商用密码应用方案未通过商用密码应用安全性评估的，不得作为商用密码保障系统的建设依据。"},{"i":12,"n":"第十二条","txt":"关键信息基础设施建设阶段，其运营者应当按照通过商用密码应用安全性评估的商用密码应用方案组织实施，落实商用密码安全防护措施，建设商用密码保障系统。建设过程中需要调整商用密码应用方案的，应当重新开展商用密码应用安全性评估，评估通过后方可按照调整后的商用密码应用方案继续建设。 关键信息基础设施运行前，其运营者应当自行或者委托商用密码检测机构开展商用密码应用安全性评估。关键信息基础设施未通过商用密码应用安全性评估的，运营者应当进行改造，改造期间不得投入运行。"},{"i":13,"n":"第十三条","txt":"关键信息基础设施建成运行后，其运营者应当自行或者委托商用密码检测机构每年至少开展一次商用密码应用安全性评估，确保关键信息基础设施商用密码的正确使用和商用密码保障系统的有效运行。关键信息基础设施未通过商用密码应用安全性评估的，运营者应当进行改造，并在改造期间采取必要措施保证关键信息基础设施运行安全。"},{"i":14,"n":"第十四条","txt":"本规定施行前正在建设的关键信息基础设施，其运营者应当加强商用密码应用方案编制论证，建设完善商用密码保障系统，并按照本规定第十二条开展商用密码应用安全性评估。 本规定施行前已经投入运行的关键信息基础设施，其运营者应当按照本规定第十三条开展商用密码应用安全性评估。"},{"i":15,"n":"第十五条","txt":"开展关键信息基础设施商用密码应用安全性评估，应当符合《商用密码应用安全性评估管理办法》有关规定。 关键信息基础设施商用密码应用安全性评估应当与关键信息基础设施安全检测评估、网络安全等级测评加强衔接，避免重复评估、测评。"},{"i":16,"n":"第十六条","txt":"国家密码管理部门负责建设和管理国家关键信息基础设施商用密码运行安全管理基础设施，统筹保护工作部门建设本行业、本领域关键信息基础设施商用密码运行安全管理基础设施，会同国家网信部门、国务院公安部门分析研判关键信息基础设施商用密码运行安全态势，协同应对处置重大商用密码运行安全威胁。"},{"i":17,"n":"第十七条","txt":"密码管理部门应当定期组织开展关键信息基础设施商用密码使用情况监督检查。保护工作部门应当定期对本行业、本领域关键信息基础设施商用密码使用情况进行检查并提出改进措施，必要时可以自行或者委托商用密码检测机构等专业机构进行商用密码应用安全性评估。 运营者对密码管理部门和保护工作部门开展的关键信息基础设施商用密码使用情况监督检查应当予以配合，根据监督检查意见及时进行整改并向保护工作部门报告整改情况，保护工作部门应当将整改情况向国家密码管理部门报告。 开展关键信息基础设施商用密码使用情况监督检查应当加强协同配合、信息沟通，避免不必要的检查和交叉重复检查。监督检查不得收取费用，不得要求被监督检查单位购买、使用指定单位或者指定品牌的商用密码产品、服务。"},{"i":18,"n":"第十八条","txt":"密码管理部门、有关部门、商用密码检测机构及其工作人员对其在履行职责中知悉的国家秘密、商业秘密和个人隐私承担保密义务，不得泄露或者非法向他人提供。"},{"i":19,"n":"第十九条","txt":"运营者违反《中华人民共和国密码法》、《中华人民共和国网络安全法》、《商用密码管理条例》、《关键信息基础设施安全保护条例》和本规定有关条款，有下列情形之一的，由密码管理部门责令改正，给予警告；拒不改正或者有其他严重情节的，处10万元以上100万元以下罚款，对直接负责的主管人员处1万元以上10万元以下罚款： （一）未按照要求使用商用密码保护关键信息基础设施，同步规划、同步建设、同步运行商用密码保障系统的； （二）关键信息基础设施使用的商用密码产品、服务未经检测认证合格的； （三）关键信息基础设施使用的密码算法、密码协议、密钥管理机制等商用密码技术未通过国家密码管理部门审查鉴定的； （四）关键信息基础设施规划阶段，未制定商用密码应用方案，或者未对商用密码应用方案进行商用密码应用安全性评估的； （五）关键信息基础设施建设阶段，未按照通过商用密码应用安全性评估的商用密码应用方案建设商用密码保障系"},{"i":20,"n":"第二十条","txt":"运营者违反《中华人民共和国密码法》、《中华人民共和国网络安全法》、《商用密码管理条例》、《关键信息基础设施安全保护条例》和本规定第九条，使用未经安全审查或者安全审查未通过的涉及商用密码的网络产品或者服务的，由有关主管部门责令停止使用，处采购金额1倍以上10倍以下罚款；对直接负责的主管人员和其他直接责任人员处1万元以上10万元以下罚款。"},{"i":21,"n":"第二十一条","txt":"运营者违反《中华人民共和国密码法》、《中华人民共和国网络安全法》、《商用密码管理条例》、《关键信息基础设施安全保护条例》和本规定第十七条，无正当理由拒不接受、不配合或者干预、阻挠密码管理部门、有关部门的商用密码监督管理的，由密码管理部门、有关部门责令改正，给予警告；拒不改正或者有其他严重情节的，处5万元以上50万元以下罚款，对直接负责的主管人员和其他直接责任人员处1万元以上10万元以下罚款；情节特别严重的，责令停业整顿。"},{"i":22,"n":"第二十二条","txt":"运营者违反本规定，有下列情形之一的，由密码管理部门、有关部门依据职责责令改正： （一）未按照要求报告上一年度关键信息基础设施商用密码使用以及商用密码应用安全性评估开展情况的； （二）未建立关键信息基础设施商用密码使用管理制度的； （三）未按照要求配备密钥管理员、密码操作员、密码安全审计员的； （四）未保障关键信息基础设施商用密码使用和应用安全性评估经费的。"},{"i":23,"n":"第二十三条","txt":"从事关键信息基础设施商用密码使用监督管理工作的人员滥用职权、玩忽职守、徇私舞弊，或者泄露、非法向他人提供在履行职责中知悉的商业秘密、个人隐私、举报人信息的，依法给予处分。"},{"i":24,"n":"第二十四条","txt":"属于国家政务信息系统的关键信息基础设施的商用密码使用管理，除应当遵守本规定以外，还应当按照《国家政务信息化项目建设管理办法》（国办发〔2019〕57号）等有关规定要求执行。"},{"i":25,"n":"第二十五条","txt":"本规定自2025年8月1日起施行。"}],"junduilixiutuixiuganbufuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了做好军队离休退休干部服务管理工作，根据《中华人民共和国退役军人保障法》和国家有关规定，制定本办法。 本办法所称军队离休退休干部，是指移交政府安置的由退役军人事务部门服务管理的中国人民解放军和中国人民武装警察部队离休退休干部（以下简称军休干部）。"},{"i":2,"n":"第二条","txt":"军休干部服务管理应当从维护军休干部的合法权益出发，贯彻执行国家关于军休干部的法律法规和政策，完善军休干部服务保障和教育管理机制，落实军休干部政治待遇和生活待遇。 军休干部服务管理坚持政治关心、生活照顾、服务优先、依法管理的原则。"},{"i":3,"n":"第三条","txt":"军休干部服务管理工作坚持党的领导，由退役军人事务部门主管，军休服务管理机构（以下简称军休机构）具体组织实施。 退役军人事务部门应当依法负责军休干部服务管理工作，及时研究解决存在的问题，监督检查军休服务管理相关法律法规和政策措施落实情况。 军休机构是服务和管理军休干部的专设机构，包括军休服务管理中心、军休所、军休服务站等，承担军休干部服务管理具体工作。"},{"i":4,"n":"第四条","txt":"军休干部服务管理应当与经济发展相协调，与社会进步相适应，实行国家保障与社会化服务相结合。"},{"i":5,"n":"第五条","txt":"对在军休干部服务管理中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":6,"n":"第六条","txt":"退役军人事务部门、军休机构应当加强军休干部思想政治工作，引导军休干部继续发扬人民军队优良传统，模范遵守宪法和法律法规，永葆政治本色。"},{"i":7,"n":"第七条","txt":"退役军人事务部门、军休机构应当按照规定落实军休干部政治待遇，组织军休干部阅读有关文件、听取党和政府重要会议精神传达等。 退役军人事务部门应当主动协调当地离退休干部管理部门，将军休干部纳入本级老干部工作体系。"},{"i":8,"n":"第八条","txt":"退役军人事务部门在国家、地方和军队举行重大庆典和重大政治活动时，应当按照要求组织军休干部参加。"},{"i":9,"n":"第九条","txt":"退役军人事务部门应当协调当地人民政府和军队有关负责人，在八一建军节、春节等重大节日走访慰问军休干部。"},{"i":10,"n":"第十条","txt":"退役军人事务部门应当按规定落实军休干部荣誉疗养制度，对服役期间或移交安置后作出突出贡献的军休干部，分层级、分批次组织疗养。"},{"i":11,"n":"第十一条","txt":"军休机构应当做好以下服务保障工作： （一）举行新接收军休干部迎接仪式。 （二）按时发放军休干部离退休费和津贴补贴，帮助符合条件的军休干部落实优抚待遇。 （三）协调做好军休干部的医疗保障工作，落实体检制度，建立健康档案，开展医疗保健知识普及活动，引导军休干部科学保健、健康养生。 （四）培育军休干部文化队伍，开展军休文化体育活动，引导和鼓励军休干部参与社会文化活动。 （五）开展经常性走访探望，定期了解军休干部情况和需求，提供必要的关心照顾。 （六）协助办理军休干部去世后的丧葬事宜，按照政策规定落实遗属待遇。"},{"i":12,"n":"第十二条","txt":"退役军人事务部门、军休机构应当依法依规加强对军休干部参加社会组织、出国（境）、著作出书、发表言论等事项的管理，督促军休干部遵纪守法和遵守军休机构各项规章制度。"},{"i":13,"n":"第十三条","txt":"退役军人事务部门、军休机构应当鼓励支持军休干部保持和发扬优良传统，发挥自身优势，继续贡献力量。"},{"i":14,"n":"第十四条","txt":"军休机构应当建立健全工作制度，为军休干部老有所养、老有所医、老有所教、老有所学、老有所为、老有所乐创造条件。"},{"i":15,"n":"第十五条","txt":"军休机构应当建立值班制度，并采取定期联系、定人包户等方式，为军休干部提供及时、方便的日常服务保障。"},{"i":16,"n":"第十六条","txt":"军休机构应当坚持共性服务和个性化服务相结合，为军休干部提供细致周到的服务。对失能、失智、重病、高龄、独居、空巢等军休干部，应当重点照顾并提供必要帮助。"},{"i":17,"n":"第十七条","txt":"军休机构应当按照退役军人事务部门制定的规范标准，推进服务管理工作标准化建设，确保规范运行。"},{"i":18,"n":"第十八条","txt":"军休机构应当推进社会化服务，根据需要引进医疗、养老、志愿服务等方面力量，为军休干部提供多元服务。"},{"i":19,"n":"第十九条","txt":"退役军人事务部门、军休机构应当加强信息化建设，充分运用信息化技术，发挥军休安置服务管理信息系统、网络\"军休所\"等信息化平台作用，提高工作效率，实现精准服务。"},{"i":20,"n":"第二十条","txt":"退役军人事务部门、军休机构应当推进军休老年大学建设，线上线下融合，扩大教学供给，提高办学水平，不断满足军休干部终身学习需求。"},{"i":21,"n":"第二十一条","txt":"退役军人事务部门应当健全军休机构服务网格，加强军休干部服务保障。"},{"i":22,"n":"第二十二条","txt":"军休干部管理委员会是在军休机构内军休干部自我教育、自我管理、自我服务的群众性组织。 军休机构内设有军休干部管理委员会的，军休机构党组织应当加强对军休干部管理委员会的领导，按照有关规定组织开展活动，发挥军休干部管理委员会的作用，定期听取军休干部管理委员会工作情况报告，研究解决其反映的问题。"},{"i":23,"n":"第二十三条","txt":"退役军人事务部门根据安置管理工作实际，按照统筹规划、合理布局、精干高效、便于服务的原则设置、调整军休机构。"},{"i":24,"n":"第二十四条","txt":"军休机构实行法定代表人负责制，对重大问题实行科学决策、民主决策。 军休机构应当依法依规落实政策公开、财务公开、服务公开，接受军休干部和工作人员监督。"},{"i":25,"n":"第二十五条","txt":"军休机构应当加强党组织建设，改进和创新军休干部党组织工作，落实党的组织生活制度，增强党组织的政治功能和组织力，使之成为组织、凝聚、教育军休干部和工作人员的坚强堡垒。 加强军休干部中的流动党员管理，将流动党员就近安排在暂住地军休机构党组织参加组织生活。"},{"i":26,"n":"第二十六条","txt":"军休机构应当加强基础设施建设，设置会议室、活动室、阅览室、荣誉室等场所，根据军休干部特点和需求，因地制宜开展适老化改造，具备条件的可引进或设立养老、医疗、助餐等功能设施，建立必要的室外文化体育活动场地，创造良好休养环境。"},{"i":27,"n":"第二十七条","txt":"军休机构应当按规定用好军休经费，加强军休经费和国有资产管理，提高使用效益，接受有关部门的审计监督。"},{"i":28,"n":"第二十八条","txt":"军休机构应当加强军休干部档案管理。"},{"i":29,"n":"第二十九条","txt":"军休机构应当加强安全管理，制定并落实卫生、灾害等突发事件应急预案，增强风险防控和应急处置能力，及时消除安全隐患，防止安全责任事故发生。"},{"i":30,"n":"第三十条","txt":"退役军人事务部门应当加强军休服务管理工作人员队伍建设，在编制员额内配齐配强工作力量，优化队伍结构。"},{"i":31,"n":"第三十一条","txt":"军休机构在编制员额内新聘用工作人员，除国家政策性安置、按照人事管理权限由上级任命、涉密岗位等人员外，应当面向社会公开招聘，同等条件下优先聘用退役军人、军人家属。"},{"i":32,"n":"第三十二条","txt":"退役军人事务部门可以通过引进专业化服务等渠道充实工作力量。"},{"i":33,"n":"第三十三条","txt":"服务管理工作人员应当强化能力素质和作风纪律，树牢全心全意为军休干部服务的意识。"},{"i":34,"n":"第三十四条","txt":"退役军人事务部门、军休机构应当定期开展教育培训、岗位练兵、业务竞赛等活动，提高工作人员思想政治素质、政策理论水平和服务管理能力。"},{"i":35,"n":"第三十五条","txt":"退役军人事务部门应当建立以军休干部满意度为主要内容的服务管理工作监督考评体系，定期对军休机构及其负责人进行测评。 退役军人事务部门、军休机构应当建立工作人员绩效考核、岗位交流制度。对军休政策落实不到位、工作推进不力的人员，按照有关规定进行处理。"},{"i":36,"n":"第三十六条","txt":"中国人民解放军和中国人民武装警察部队移交政府安置的退休军（警）士的服务管理参照本办法执行。"},{"i":37,"n":"第三十七条","txt":"本办法自2022年1月1日起施行。"}],"nongyejixiezhiliangdiaochabanfa":[{"i":1,"n":"第一条","txt":"为了规范农业机械质量调查工作，加强农业机械产品质量监督管理，维护农业机械使用者和生产者、销售者的合法权益，依据《中华人民共和国农业机械化促进法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农业机械质量调查（以下简称质量调查），是指省级以上人民政府农业机械化行政主管部门组织对在用特定种类农业机械产品的适用性、安全性、可靠性和售后服务状况进行调查监督的活动。"},{"i":3,"n":"第三条","txt":"农业部主管全国质量调查工作，统一质量调查规范，协调跨省的质量调查，制定并组织实施全国质量调查计划，公布调查结果。 省级人民政府农业机械化行政主管部门负责本行政区域内的质量调查工作，制定并组织实施本行政区域的质量调查计划，公布调查结果。"},{"i":4,"n":"第四条","txt":"质量调查的具体工作由省级以上农业机械试验鉴定机构承担，农业机械化技术推广、安全监理等机构配合。调查涉及地区的农业、农业机械化行政主管部门应当予以支持协助。"},{"i":5,"n":"第五条","txt":"质量调查坚持科学、公正、公开的原则，接受农业机械使用者、生产者、销售者和社会的监督。"},{"i":6,"n":"第六条","txt":"质量调查不向调查涉及的单位和个人收取任何费用。"},{"i":7,"n":"第七条","txt":"县级以上人民政府农业机械化行政主管部门应当明确农机质量投诉机构，负责受理投诉，统计、分析、报送投诉信息，为制定质量调查计划提供依据。 农机质量投诉机构的地址和联系电话应当向社会公布。"},{"i":8,"n":"第八条","txt":"农业机械试验鉴定机构应当加强质量信息收集和调查研究工作，并提出质量调查建议。"},{"i":9,"n":"第九条","txt":"质量调查计划应当根据农业机械使用者的投诉情况和农业生产的实际需要制定，并及时公布。 省级质量调查计划在公布前应当报农业部备案。"},{"i":10,"n":"第十条","txt":"质量调查计划应当明确质量调查的名称、目的、内容、范围、对象、时间、方法、实施单位等事项。"},{"i":11,"n":"第十一条","txt":"列入质量调查计划的农业机械产品，应当具备下列条件之一： （一）属于国家财政补贴、优惠信贷、政府采购等政策支持范围的； （二）对人体健康、人身和财产安全、资源节约、环境保护有重大影响的； （三）出现集中质量投诉或者重大质量事故的。"},{"i":12,"n":"第十二条","txt":"质量调查内容包括： （一）安全性调查：对农业机械影响人体健康、人身和财产安全、环境保护的程度进行调查； （二）可靠性调查：对农业机械故障情况进行调查； （三）适用性调查：对农业机械在不同地域、不同作物及品种或者不同耕作制度的作业效果进行调查； （四）售后服务状况调查：对企业质量承诺和售后服务承诺兑现情况进行调查。"},{"i":13,"n":"第十三条","txt":"承担质量调查任务的省级以上农业机械试验鉴定机构（以下称调查承担单位）接受任务后，应当制定实施方案，报下达任务的省级以上人民政府农业机械化行政主管部门（以下称任务下达部门）批准。 实施方案应当包括质量调查的具体内容、程序、样本数量和分布、技术路线、调查方法和依据标准、调查表格和填写说明、数据统计处理方法、工作分工、参加人员等。"},{"i":14,"n":"第十四条","txt":"任务下达部门批准实施方案后，应当向调查承担单位下达质量调查任务书。"},{"i":15,"n":"第十五条","txt":"调查承担单位应当对调查人员进行培训，发放当次质量调查证件。"},{"i":16,"n":"第十六条","txt":"进行质量调查时，调查人员应当向被调查方出示质量调查任务书和质量调查证件。 质量调查采取问询查证、发放问卷、现场跟踪、召开座谈会等方式进行。必要时依据国家标准、行业标准、企业标准或者企业质量承诺进行试验检测。"},{"i":17,"n":"第十七条","txt":"被调查方应当配合质量调查工作，按照调查要求及时提供有关资料和信息，并对其真实性负责。"},{"i":18,"n":"第十八条","txt":"质量调查结束后，调查承担单位应当按照实施方案要求汇总、处理和分析调查信息，形成调查报告，报送任务下达部门。"},{"i":19,"n":"第十九条","txt":"调查承担单位和调查人员对调查结果负责，对调查中涉及的商业秘密应当依法保密，不得利用质量调查进行有偿活动。"},{"i":20,"n":"第二十条","txt":"任务下达部门收到调查报告后，应当对调查内容、程序、方法是否符合实施方案的规定进行审查。 审查工作应当在收到调查报告之日起20个工作日内完成。审查通过的，任务下达部门应当及时公布质量调查结果。 省级质量调查结果应当在公布前报农业部备案。"},{"i":21,"n":"第二十一条","txt":"调查承担单位应当在质量调查结果公布后20个工作日内组织召开质量分析会，向有关企业通报调查中发现的问题，提出改进建议。 对质量调查中发现的产品质量或售后服务问题严重的生产或者销售企业，由任务下达部门责令整改。"},{"i":22,"n":"第二十二条","txt":"企业对整改通知有异议的，应当在收到通知后15个工作日内书面提出；逾期未提出的，视为无异议。 整改通知下达部门应当在收到企业书面异议之日起15个工作日内予以答复。"},{"i":23,"n":"第二十三条","txt":"企业对整改通知无异议的，或者有异议而未被采纳的，应当按照通知要求报告整改情况，由整改通知下达部门组织确认。"},{"i":24,"n":"第二十四条","txt":"调查承担单位和人员有下列情形之一的，责令改正，对单位负责人和其他直接责任人员，依法给予处分；情节严重的，取消调查承担单位或者个人的质量调查资格： （一）不按规定进行调查、伪造调查结果、瞒报或者出具虚假证明的； （二）利用质量调查从事有偿活动的； （三）擅自透露质量调查相关信息造成不良后果的； （四）有其他徇私舞弊、滥用职权、玩忽职守行为的。 调查承担单位和个人利用质量调查获取违法所得的，予以追缴。"},{"i":25,"n":"第二十五条","txt":"被调查的企业和个人虚报、瞒报、伪造、篡改有关资料，或者拒不配合调查工作的，由所在地农业机械化行政主管部门责令改正；情节严重的，对所涉及产品由省级以上人民政府农业机械化行政主管部门注销农业机械推广鉴定证书、取消列入国家支持推广的农业机械产品目录资格。"},{"i":26,"n":"第二十六条","txt":"企业收到整改通知后拒不整改或者逾期达不到整改要求的，整改通知下达部门应当注销该产品的农业机械推广鉴定证书、取消列入国家支持推广的农业机械产品目录的资格；属于实施生产许可证或强制性认证的产品，还应当向有关主管部门通报情况。"},{"i":27,"n":"第二十七条","txt":"本办法自2006年11月1日起施行。"}],"nongcuntudichengbaozhongcaiweiyuanhuishifanzhangcha3da3b":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国农村土地承包经营纠纷调解仲裁法》，制定本章程。"},{"i":2,"n":"第二条","txt":"____市/县/区农村土地承包仲裁委员会（以下简称本仲裁委员会）在____市/县/区人民政府指导下依法组织设立，并报____省（自治区、直辖市）人民政府农业、林业行政主管部门备案。"},{"i":3,"n":"第三条","txt":"本仲裁委员会的职责： （一）聘任、解聘仲裁员； （二）培训、管理仲裁员； （三）受理仲裁申请； （四）指导、监督仲裁活动； （五）法律法规规定的其他职责。"},{"i":4,"n":"第四条","txt":"本仲裁委员会的日常工作由____市/县/区____【注：农村土地承包管理部门】承担，主要包括以下内容： （一）登记、审查仲裁申请； （二）监督管理仲裁程序； （三）编制仲裁员名册； （四）组织仲裁员培训； （五）管理仲裁文书和仲裁档案； （六）管理仲裁工作经费； （七）仲裁委员会交办的其他事项。 本仲裁委员会办公地点设在_______。"},{"i":5,"n":"第五条","txt":"本仲裁委员会由_____市/县/区人民政府及____【注：有关部门】代表、____【注：有关人民团体】代表、农村集体经济组织代表、农民代表和____【注：法律、经济等相关专业】人员兼任组成，成员人数为____人【注：总数为单数，其中农民代表和法律、经济等相关专业人员不少于二分之一】。 本仲裁委员会设主任一人、副主任____【注：一至二】人，委员____人。"},{"i":6,"n":"第六条","txt":"本仲裁委员会组成人员的任期为____【注：三至五】年。 仲裁委员会换届，应当在任期届满前一个月内完成；有特殊情况不能如期换届的，应当在任期届满后两个月内完成。"},{"i":7,"n":"第七条","txt":"本仲裁委员会组成人员任期内因故更换的，由仲裁委员会组织重新确定人选。主任、副主任更换的，由本仲裁委员会全体会议选举决定。"},{"i":8,"n":"第八条","txt":"本仲裁委员会每年召开____【注：不少于一】次全体会议。根据主任、副主任或者三分之二以上组成人员提议，可以召开临时全体会议。全体会议由主任或者主任委托的副主任主持。 全体会议须有三分之二以上的成员出席方能举行，会议决议须经出席会议成员三分之二以上通过。 修改章程须经全体成员的三分之二以上通过。"},{"i":9,"n":"第九条","txt":"全体会议主要负责议决以下事项： （一）制定和修改仲裁委员会的章程、议事规则和规章制度； （二）选举仲裁委员会主任、副主任； （三）决定仲裁员的聘任、解聘和除名； （四）仲裁委员会主任担任仲裁员的，决定主任的回避； （五）审议仲裁委员会工作计划和年度工作报告； （六）研究农村土地承包经营纠纷仲裁的重大事项； （七）其他重要事项。"},{"i":10,"n":"第十条","txt":"本仲裁委员会从公道正派，并符合下列条件之一的人员中选聘仲裁员，颁发聘书： （一）从事农村土地承包管理工作满五年； （二）从事法律工作或者人民调解工作满五年； （三）在当地威信较高，熟悉农村土地承包法律以及国家政策的居民。"},{"i":11,"n":"第十一条","txt":"本仲裁委员会定期组织仲裁员进行农村土地承包法律以及国家政策的培训。"},{"i":12,"n":"第十二条","txt":"仲裁员聘期____【注：一般为三】年，期满可以继续聘任。"},{"i":13,"n":"第十三条","txt":"本仲裁委员会建立仲裁员考核制度，考核结果作为续聘或者解聘仲裁员的依据。"},{"i":14,"n":"第十四条","txt":"本仲裁委员会的组成人员、仲裁员应当依法履行职责，遵纪守法，不得索贿受贿、徇私舞弊、枉法裁决，不得侵害当事人的合法权益。"},{"i":15,"n":"第十五条","txt":"本仲裁委员会有权要求被选定或者被指定组成仲裁庭的仲裁员主动报告是否有回避情形。"},{"i":16,"n":"第十六条","txt":"本仲裁委员会组成人员、仲裁员、记录人员、翻译人员等有保密义务，不得擅自对外界透露案件实体和仲裁程序进行的情况。"},{"i":17,"n":"第十七条","txt":"仲裁员辞聘，应当提前三个月向本仲裁委员会提交辞呈。组成仲裁庭的仲裁员，在仲裁程序结束前不得辞聘。"},{"i":18,"n":"第十八条","txt":"本仲裁委员会对有下列情形之一的仲裁员，予以解聘： （一）故意隐瞒应当回避事实的； （二）无正当理由故意不到庭审理案件的； （三）连续两年考核不合格的； （四）其他不宜继续担任仲裁员的。"},{"i":19,"n":"第十九条","txt":"本仲裁委员会对有索贿受贿、徇私舞弊、枉法裁决以及接受当事人请客送礼等违法违纪行为的仲裁员，予以除名，且不再聘为仲裁员。"},{"i":20,"n":"第二十条","txt":"本仲裁委员会不向当事人收取仲裁费用，工作经费依法纳入财政预算。"},{"i":21,"n":"第二十一条","txt":"本章程经本仲裁委员会____年____月____日全体会议讨论通过，自____年____月____日起生效。"}],"nongcuntudichengbaojingyingjiufenzhongcaiguize-2":[{"i":1,"n":"第一条","txt":"为规范农村土地承包经营纠纷仲裁活动，根据《中华人民共和国农村土地承包经营纠纷调解仲裁法》，制定本规则。"},{"i":2,"n":"第二条","txt":"农村土地承包经营纠纷仲裁适用本规则。"},{"i":3,"n":"第三条","txt":"下列农村土地承包经营纠纷，当事人可以向农村土地承包仲裁委员会（以下简称仲裁委员会）申请仲裁： （一）因订立、履行、变更、解除和终止农村土地承包合同发生的纠纷； （二）因农村土地承包经营权转包、出租、互换、转让、入股等流转发生的纠纷； （三）因收回、调整承包地发生的纠纷； （四）因确认农村土地承包经营权发生的纠纷； （五）因侵害农村土地承包经营权发生的纠纷； （六）法律、法规规定的其他农村土地承包经营纠纷。 因征收集体所有的土地及其补偿发生的纠纷，不属于仲裁委员会的受理范围，可以通过行政复议或者诉讼等方式解决。"},{"i":4,"n":"第四条","txt":"仲裁委员会依法设立，其日常工作由当地农村土地承包管理部门承担。"},{"i":5,"n":"第五条","txt":"农村土地承包经营纠纷仲裁，应当公开、公平、公正，便民高效，注重调解，尊重事实，符合法律，遵守社会公德。"},{"i":6,"n":"第六条","txt":"农村土地承包经营纠纷仲裁的申请人、被申请人为仲裁当事人。"},{"i":7,"n":"第七条","txt":"家庭承包的，可以由农户代表人参加仲裁。农户代表人由农户成员共同推选；不能共同推选的，按下列方式确定： （一）土地承包经营权证或者林权证等证书上记载的人； （二）未取得土地承包经营权证或者林权证等证书的，为在承包合同上签字的人。"},{"i":8,"n":"第八条","txt":"当事人一方为五户（人）以上的，可以推选三至五名代表人参加仲裁。"},{"i":9,"n":"第九条","txt":"与案件处理结果有利害关系的，可以申请作为第三人参加仲裁，或者由仲裁委员会通知其参加仲裁。"},{"i":10,"n":"第十条","txt":"当事人、第三人可以委托代理人参加仲裁。 当事人或者第三人为无民事行为能力人或者限制民事行为能力人的，由其法定代理人参加仲裁。"},{"i":11,"n":"第十一条","txt":"当事人申请农村土地承包经营纠纷仲裁的时效期间为二年，自当事人知道或者应当知道其权利被侵害之日起计算。 仲裁时效因申请调解、申请仲裁、当事人一方提出要求或者同意履行义务而中断。从中断时起，仲裁时效重新计算。 在仲裁时效期间的最后六个月内，因不可抗力或者其他事由，当事人不能申请仲裁的，仲裁时效中止。从中止时效的原因消除之日起，仲裁时效期间继续计算。 侵害农村土地承包经营权行为持续发生的，仲裁时效从侵权行为终了时计算。"},{"i":12,"n":"第十二条","txt":"申请农村土地承包经营纠纷仲裁，应当符合下列条件： （一）申请人与纠纷有直接的利害关系； （二）有明确的被申请人； （三）有具体的仲裁请求和事实、理由； （四）属于仲裁委员会的受理范围。"},{"i":13,"n":"第十三条","txt":"当事人申请仲裁，应当向纠纷涉及土地所在地的仲裁委员会递交仲裁申请书。申请书可以邮寄或者委托他人代交。 书面申请有困难的，可以口头申请，由仲裁委员会记入笔录，经申请人核实后由其签名、盖章或者按指印。 仲裁委员会收到仲裁申请材料，应当出具回执。回执应当载明接收材料的名称和份数、接收日期等，并加盖仲裁委员会印章。"},{"i":14,"n":"第十四条","txt":"仲裁申请书应当载明下列内容： （一）申请人和被申请人的姓名、年龄、住所、邮政编码、电话或者其他通讯方式；法人或者其他组织应当写明名称、地址和法定代表人或者主要负责人的姓名、职务、通讯方式； （二）申请人的仲裁请求； （三）仲裁请求所依据的事实和理由； （四）证据和证据来源、证人姓名和联系方式。"},{"i":15,"n":"第十五条","txt":"仲裁委员会应当对仲裁申请进行审查，符合申请条件的，应当受理。 有下列情形之一的，不予受理；已受理的，终止仲裁程序： （一）不符合申请条件； （二）人民法院已受理该纠纷； （三）法律规定该纠纷应当由其他机构受理； （四）对该纠纷已有生效的判决、裁定、仲裁裁决、行政处理决定等。"},{"i":16,"n":"第十六条","txt":"仲裁委员会决定受理仲裁申请的，应当自收到仲裁申请之日起五个工作日内，将受理通知书、仲裁规则、仲裁员名册送达申请人，将受理通知书、仲裁申请书副本、仲裁规则、仲裁员名册送达被申请人。 决定不予受理或者终止仲裁程序的，应当自收到仲裁申请或者发现终止仲裁程序情形之日起五个工作日内书面通知申请人，并说明理由。 需要通知第三人参加仲裁的，仲裁委员会应当通知第三人，并告知其权利义务。"},{"i":17,"n":"第十七条","txt":"被申请人应当自收到仲裁申请书副本之日起十日内向仲裁委员会提交答辩书。 仲裁委员会应当自收到答辩书之日起五个工作日内将答辩书副本送达申请人。 被申请人未答辩的，不影响仲裁程序的进行。"},{"i":18,"n":"第十八条","txt":"答辩书应当载明下列内容： （一）答辩人姓名、年龄、住所、邮政编码、电话或者其他通讯方式；法人或者其他组织应当写明名称、地址和法定代表人或者主要负责人的姓名、职务、通讯方式； （二）对申请人仲裁申请的答辩及所依据的事实和理由； （三）证据和证据来源，证人姓名和联系方式。 书面答辩确有困难的，可以口头答辩，由仲裁委员会记入笔录，经被申请人核实后由其签名、盖章或者按指印。"},{"i":19,"n":"第十九条","txt":"当事人提交仲裁申请书、答辩书、有关证据材料及其他书面文件，应当一式三份。"},{"i":20,"n":"第二十条","txt":"因一方当事人的行为或者其他原因可能使裁决不能执行或者难以执行，另一方当事人申请财产保全的，仲裁委员会应当将当事人的申请提交被申请人住所地或者财产所在地的基层人民法院，并告知申请人因申请错误造成被申请人财产损失的，应当承担相应的赔偿责任。"},{"i":21,"n":"第二十一条","txt":"仲裁庭由三名仲裁员组成。 事实清楚、权利义务关系明确、争议不大的农村土地承包经营纠纷，经双方当事人同意，可以由一名仲裁员仲裁。"},{"i":22,"n":"第二十二条","txt":"双方当事人自收到受理通知书之日起五个工作日内，从仲裁员名册中选定仲裁员。首席仲裁员由双方当事人共同选定，其他二名仲裁员由双方当事人各自选定；当事人不能选定的，由仲裁委员会主任指定。 独任仲裁员由双方当事人共同选定；当事人不能选定的，由仲裁委员会主任指定。 仲裁委员会应当自仲裁庭组成之日起二个工作日内将仲裁庭组成情况通知当事人。"},{"i":23,"n":"第二十三条","txt":"仲裁庭组成后，首席仲裁员应当召集其他仲裁员审阅案件材料，了解纠纷的事实和情节，研究双方当事人的请求和理由，查核证据，整理争议焦点。 仲裁庭认为确有必要的，可以要求当事人在一定期限内补充证据，也可以自行调查取证。自行调查取证的，调查人员不得少于二人。"},{"i":24,"n":"第二十四条","txt":"仲裁员有下列情形之一的，应当回避： （一）是本案当事人或者当事人、代理人的近亲属； （二）与本案有利害关系； （三）与本案当事人、代理人有其他关系，可能影响公正仲裁； （四）私自会见当事人、代理人，或者接受当事人、代理人请客送礼。"},{"i":25,"n":"第二十五条","txt":"仲裁员有回避情形的，应当以口头或者书面方式及时向仲裁委员会提出。 当事人认为仲裁员有回避情形的，有权以口头或者书面方式向仲裁委员会申请其回避。 当事人提出回避申请，应当在首次开庭前提出，并说明理由；在首次开庭后知道回避事由的，可以在最后一次开庭终结前提出。"},{"i":26,"n":"第二十六条","txt":"仲裁委员会应当自收到回避申请或者发现仲裁员有回避情形之日起二个工作日内作出决定，以口头或者书面方式通知当事人，并说明理由。 仲裁员是否回避，由仲裁委员会主任决定；仲裁委员会主任担任仲裁员时，由仲裁委员会集体决定主任的回避。"},{"i":27,"n":"第二十七条","txt":"仲裁员有下列情形之一的，应当按照本规则第二十二条规定重新选定或者指定仲裁员： （一）被决定回避的； （二）在法律上或者事实上不能履行职责的； （三）因被除名或者解聘丧失仲裁员资格的； （四）因个人原因退出或者不能从事仲裁工作的； （五）因徇私舞弊、失职渎职被仲裁委员会决定更换的。 重新选定或者指定仲裁员后，仲裁程序继续进行。当事人请求仲裁程序重新进行的，由仲裁庭决定。"},{"i":28,"n":"第二十八条","txt":"仲裁庭应当向当事人提供必要的法律政策解释，帮助当事人自行和解。 达成和解协议的，当事人可以请求仲裁庭根据和解协议制作裁决书；当事人要求撤回仲裁申请的，仲裁庭应当终止仲裁程序。"},{"i":29,"n":"第二十九条","txt":"仲裁庭应当在双方当事人自愿的基础上进行调解。调解达成协议的，仲裁庭应当制作调解书。 调解书应当载明双方当事人基本情况、纠纷事由、仲裁请求和协议结果，由仲裁员签名，并加盖仲裁委员会印章，送达双方当事人。 调解书经双方当事人签收即发生法律效力。"},{"i":30,"n":"第三十条","txt":"调解不成或者当事人在调解书签收前反悔的，仲裁庭应当及时作出裁决。 当事人在调解过程中的陈述、意见、观点或者建议，仲裁庭不得作为裁决的证据或依据。"},{"i":31,"n":"第三十一条","txt":"仲裁庭作出裁决前，申请人放弃仲裁请求并撤回仲裁申请，且被申请人没有就申请人的仲裁请求提出反请求的，仲裁庭应当终止仲裁程序。 申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭的，可以视为撤回仲裁申请。"},{"i":32,"n":"第三十二条","txt":"被申请人就申请人的仲裁请求提出反请求的，应当说明反请求事项及其所依据的事实和理由，并附具有关证明材料。 被申请人在仲裁庭组成前提出反请求的，由仲裁委员会决定是否受理；在仲裁庭组成后提出反请求的，由仲裁庭决定是否受理。 仲裁委员会或者仲裁庭决定受理反请求的，应当自收到反请求之日起五个工作日内将反请求申请书副本送达申请人。申请人应当在收到反请求申请书副本后十个工作日内提交反请求答辩书，不答辩的不影响仲裁程序的进行。仲裁庭应当将被申请人的反请求与申请人的请求合并审理。 仲裁委员会或者仲裁庭决定不予受理反请求的，应当书面通知被申请人，并说明理由。"},{"i":33,"n":"第三十三条","txt":"仲裁庭组成前申请人变更仲裁请求或者被申请人变更反请求的，由仲裁委员会作出是否准许的决定；仲裁庭组成后变更请求或者反请求的，由仲裁庭作出是否准许的决定。"},{"i":34,"n":"第三十四条","txt":"农村土地承包经营纠纷仲裁应当开庭进行。开庭应当公开，但涉及国家秘密、商业秘密和个人隐私以及当事人约定不公开的除外。 开庭可以在纠纷涉及的土地所在地的乡（镇）或者村进行，也可以在仲裁委员会所在地进行。当事人双方要求在乡（镇）或者村开庭的，应当在该乡（镇）或者村开庭。"},{"i":35,"n":"第三十五条","txt":"仲裁庭应当在开庭五个工作日前将开庭时间、地点通知当事人、第三人和其他仲裁参与人。 当事人请求变更开庭时间和地点的，应当在开庭三个工作日前向仲裁庭提出，并说明理由。仲裁庭决定变更的，通知双方当事人、第三人和其他仲裁参与人；决定不变更的，通知提出变更请求的当事人。"},{"i":36,"n":"第三十六条","txt":"公开开庭的，应当将开庭时间、地点等信息予以公告。 申请旁听的公民，经仲裁庭审查后可以旁听。"},{"i":37,"n":"第三十七条","txt":"被申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭的，仲裁庭可以缺席裁决。 被申请人提出反请求，申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭的，仲裁庭可以就反请求缺席裁决。"},{"i":38,"n":"第三十八条","txt":"开庭前，仲裁庭应当查明当事人、第三人、代理人和其他仲裁参与人是否到庭，并逐一核对身份。 开庭由首席仲裁员或者独任仲裁员宣布。首席仲裁员或者独任仲裁员应当宣布案由，宣读仲裁庭组成人员名单、仲裁庭纪律、当事人权利和义务，询问当事人是否申请仲裁员回避。"},{"i":39,"n":"第三十九条","txt":"仲裁庭应当保障双方当事人平等陈述的机会，组织当事人、第三人、代理人陈述事实、意见、理由。"},{"i":40,"n":"第四十条","txt":"当事人、第三人应当提供证据，对其主张加以证明。 与纠纷有关的证据由作为当事人一方的发包方等掌握管理的，该当事人应当在仲裁庭指定的期限内提供，逾期不提供的，应当承担不利后果。"},{"i":41,"n":"第四十一条","txt":"仲裁庭自行调查收集的证据，应当在开庭时向双方当事人出示。"},{"i":42,"n":"第四十二条","txt":"仲裁庭对专门性问题认为需要鉴定的，可以交由当事人约定的鉴定机构鉴定；当事人没有约定的，由仲裁庭指定的鉴定机构鉴定。"},{"i":43,"n":"第四十三条","txt":"当事人申请证据保全，应当向仲裁委员会书面提出。仲裁委员会应当自收到申请之日起二个工作日内，将申请提交证据所在地的基层人民法院。"},{"i":44,"n":"第四十四条","txt":"当事人、第三人申请证人出庭作证的，仲裁庭应当准许，并告知证人的权利义务。 证人不得旁听案件审理。"},{"i":45,"n":"第四十五条","txt":"证据应当在开庭时出示，但涉及国家秘密、商业秘密和个人隐私的证据不得在公开开庭时出示。 仲裁庭应当组织当事人、第三人交换证据，相互质证。 经仲裁庭许可，当事人、第三人可以向证人询问，证人应当据实回答。 根据当事人的请求或者仲裁庭的要求，鉴定机构应当派鉴定人参加开庭。经仲裁庭许可，当事人可以向鉴定人提问。"},{"i":46,"n":"第四十六条","txt":"仲裁庭应当保障双方当事人平等行使辩论权，并对争议焦点组织辩论。 辩论终结时，首席仲裁员或者独任仲裁员应当征询双方当事人、第三人的最后意见。"},{"i":47,"n":"第四十七条","txt":"对权利义务关系明确的纠纷，当事人可以向仲裁庭书面提出先行裁定申请，请求维持现状、恢复农业生产以及停止取土、占地等破坏性行为。仲裁庭应当自收到先行裁定申请之日起二个工作日内作出决定。 仲裁庭作出先行裁定的，应当制作先行裁定书，并告知先行裁定申请人可以向人民法院申请执行，但应当提供相应的担保。 先行裁定书应当载明先行裁定申请的内容、依据事实和理由、裁定结果和日期，由仲裁员签名，加盖仲裁委员会印章。"},{"i":48,"n":"第四十八条","txt":"仲裁庭应当将开庭情况记入笔录。笔录由仲裁员、记录人员、当事人、第三人和其他仲裁参与人签名、盖章或者按指印。 当事人、第三人和其他仲裁参与人认为对自己的陈述记录有遗漏或者差错的，有权申请补正。仲裁庭不予补正的，应当向申请人说明情况，并记录该申请。"},{"i":49,"n":"第四十九条","txt":"发生下列情形之一的，仲裁程序中止： （一）一方当事人死亡，需要等待继承人表明是否参加仲裁的； （二）一方当事人丧失行为能力，尚未确定法定代理人的； （三）作为一方当事人的法人或者其他组织终止，尚未确定权利义务承受人的； （四）一方当事人因不可抗拒的事由，不能参加仲裁的； （五）本案必须以另一案的审理结果为依据，而另一案尚未审结的； （六）其他应当中止仲裁程序的情形。 在仲裁庭组成前发生仲裁中止事由的，由仲裁委员会决定是否中止仲裁；仲裁庭组成后发生仲裁中止事由的，由仲裁庭决定是否中止仲裁。决定仲裁程序中止的，应当书面通知当事人。 仲裁程序中止的原因消除后，仲裁委员会或者仲裁庭应当在三个工作日内作出恢复仲裁程序的决定，并通知当事人和第三人。"},{"i":50,"n":"第五十条","txt":"发生下列情形之一的，仲裁程序终结： （一）申请人死亡或者终止，没有继承人及权利义务承受人，或者继承人、权利义务承受人放弃权利的； （二）被申请人死亡或者终止，没有可供执行的财产，也没有应当承担义务的人的； （三）其他应当终结仲裁程序的。 终结仲裁程序的，仲裁委员会应当自发现终结仲裁程序情形之日起五个工作日内书面通知当事人、第三人，并说明理由。"},{"i":51,"n":"第五十一条","txt":"仲裁庭应当根据认定的事实和法律以及国家政策作出裁决，并制作裁决书。 首席仲裁员组织仲裁庭对案件进行评议，裁决依多数仲裁员意见作出。少数仲裁员的不同意见可以记入笔录。 仲裁庭不能形成多数意见时，应当按照首席仲裁员的意见作出裁决。"},{"i":52,"n":"第五十二条","txt":"裁决书应当写明仲裁请求、争议事实、裁决理由和依据、裁决结果、裁决日期，以及当事人不服仲裁裁决的起诉权利和期限。 裁决书由仲裁员签名，加盖仲裁委员会印章。"},{"i":53,"n":"第五十三条","txt":"对裁决书中的文字、计算错误，或者裁决书中有遗漏的事项，仲裁庭应当及时补正。补正构成裁决书的一部分。"},{"i":54,"n":"第五十四条","txt":"仲裁庭应当自受理仲裁申请之日起六十日内作出仲裁裁决。受理日期以受理通知书上记载的日期为准。 案情复杂需要延长的，经仲裁委员会主任批准可以延长，但延长期限不得超过三十日。 延长期限的，应当自作出延期决定之日起三个工作日内书面通知当事人、第三人。 期限不包括仲裁程序中止、鉴定、当事人在庭外自行和解、补充申请材料和补正裁决的时间。"},{"i":55,"n":"第五十五条","txt":"仲裁委员会应当在裁决作出之日起三个工作日内将裁决书送达当事人、第三人。 直接送达的，应当告知当事人、第三人下列事项： （一）不服仲裁裁决的，可以在收到裁决书之日起三十日内向人民法院起诉，逾期不起诉的，裁决书即发生法律效力； （二）一方当事人不履行生效的裁决书所确定义务的，另一方当事人可以向被申请人住所地或者财产所在地的基层人民法院申请执行。"},{"i":56,"n":"第五十六条","txt":"仲裁文书应当直接送达当事人或者其代理人。受送达人是自然人，但本人不在场的，由其同住成年家属签收；受送达人是法人或者其他组织的，应当由法人的法定代表人、其他组织的主要负责人或者该法人、组织负责收件的人签收。 仲裁文书送达后，由受送达人在送达回证上签名、盖章或者按指印，受送达人在送达回证上的签收日期为送达日期。 受送达人或者其同住成年家属拒绝接收仲裁文书的，可以留置送达。送达人应当邀请有关基层组织或者受送达人所在单位的代表到场，说明情况，在送达回证上记明拒收理由和日期，由送达人、见证人签名、盖章或者按指印，将仲裁文书留在受送达人的住所，即视为已经送达。 直接送达有困难的，可以邮寄送达。邮寄送达的，以当事人签收日期为送达日期。 当事人下落不明，或者以前款规定的送达方式无法送达的，可以公告送达，自发出公告之日起，经过六十日，即视为已经送达。"},{"i":57,"n":"第五十七条","txt":"独任仲裁可以适用简易程序。简易程序的仲裁规则由仲裁委员会依照本规则制定。"},{"i":58,"n":"第五十八条","txt":"期间包括法定期间和仲裁庭指定的期间。 期间以日、月、年计算，期间开始日不计算在期间内。 期间最后一日是法定节假日的，以法定节假日后的第一个工作日为期间的最后一日。"},{"i":59,"n":"第五十九条","txt":"对不通晓当地通用语言文字的当事人、第三人，仲裁委员会应当为其提供翻译。"},{"i":60,"n":"第六十条","txt":"仲裁文书格式由农业部、国家林业局共同制定。"},{"i":61,"n":"第六十一条","txt":"农村土地承包经营纠纷仲裁不得向当事人收取费用，仲裁工作经费依法纳入财政预算予以保障。 当事人委托代理人、申请鉴定等发生的费用由当事人负担。"},{"i":62,"n":"第六十二条","txt":"本规则自2010年1月1日起施行。"}],"huaxuepinshoucijinkoujiyouduhuaxuepinjinchukouhuancae54a":[{"i":1,"n":"第一条","txt":"为了保护人体健康和生态环境，加强化学品首次进口和有毒化学品进出口的环境管理，执行《关于化学品国际贸易资料交流的伦敦准则》(1989年修正本)(以下简称《伦敦准则》)，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国管辖领域内从事化学品进出口活动必须遵守本规定。"},{"i":3,"n":"第三条","txt":"本规定适用于化学品的首次进口和列入《中国禁止或严格限制的有毒化学品名录》(以下简称《名录》)的化学品进出口的环境管理。 食品添加剂、医药、兽药、化妆品和放射性物质不适用本规定。"},{"i":4,"n":"第四条","txt":"本规定中下列用语的含义是： (一)“化学品”是指人工制造的或者是从自然界取得的化学物质，包括化学物质本身、化学混合物或者化学配制物中的一部分，以及作为工业化学品和农药使用的物质。 (二)“禁止的化学品”是指因损害健康和环境而被完全禁止使用的化学品。 (三)“严格限制的化学品”是指因损害健康和环境而被禁止使用，但经授权在一些特殊情况下仍可使用的化学品。 (四)“有毒化学品”是指进入环境后通过环境蓄积、生物累积、生物转化或化学反应等方式损害健康和环境，或者通过接触对人体具有严重危害和具有潜在危险的化学品。 (五)“化学品首次进口”是指外商或其代理人向中国出口其未曾在中国登记过的化学品，即使同种化学品已有其他外商或其代理人在中国进行了登记，仍被视为化学品首次进口。 (六)“事先知情同意”是指为保护人类健康和环境目的而被禁止或严格限制的化学品的国际运输，必须在进口国指定的国家主管部门同意的情况"},{"i":5,"n":"第五条","txt":"国家环境保护局对化学品首次进口和有毒化学品进出口实施统一的环境监督管理，负责全面执行《伦敦准则》的事先知情同意程序，发布中国禁止或严格限制的有毒化学品名录，实施化学品首次进口和列入《名录》内的有毒化学品进出口的环境管理登记和审批，签发《化学品进(出)口环境管理登记证》和《有毒化学品进(出)口环境管理放行通知单》，发布首次进口化学品登记公告。"},{"i":6,"n":"第六条","txt":"中华人民共和国海关对列入《名录》的有毒化学品的进出口凭国家环境保护局签发的《有毒化学品进(出)口环境管理放行通知单》(见附件)验放。 对外贸易经济合作部根据其职责协同国家环境保护局对化学品首次进口和有毒化学品进出口环境管理登记申请资料的有关内容进行审查和对外公布《中国禁止或严格限制的有毒化学品名录》。"},{"i":7,"n":"第七条","txt":"国家环境保护局设立国家有毒化学品评审委员会，负责对申请进出口环境管理登记的化学品的综合评审工作，对实施本规定所涉及的技术事务向国家环境保护局提供咨询意见。国家有毒化学品评审委员会由环境、卫生、农业、化工、外贸、商检、海关及其它有关方面的管理人员和技术专家组成，每届任期三年。"},{"i":8,"n":"第八条","txt":"地方各级环境保护行政主管部门依据本规定对本辖区的化学品首次进口及有毒化学品进出口进行环境监督管理。"},{"i":9,"n":"第九条","txt":"每次外商及其代理人向中国出口和国内从国外进口列入《名录》中的工业化学品或农药之前，均需向国家环境保护局提出有毒化学品进口环境管理登记申请。对准予进口的发给《化学品进(出)口环境管理登记证》和《有毒化学品进(出)口环境管理放行通知单》(以下简称《通知单》)。《通知单》实行一批一证制，每份(通知单)在有效时间内只能报关使用一次(见附件一)。"},{"i":10,"n":"第十条","txt":"申请出口列入《名录》的化学品，必须向国家环境保护局提出有毒化学品出口环境管理登记申请。 国家环境保护局受理申请后，应通知进口国主管部门，在收到进口国主管部门同意进口的通知后，发给申请人准许有毒化学品出口的《化学品进(出)口环境管理登记证》。对进口国主管部门不同意进口的化学品，不予登记，不准出口，并通知申请人。"},{"i":11,"n":"第十一条","txt":"国家环境保护局签发的《化学品进(出)口环境管理登记证》须加盖中华人民共和国国家环境保护局化学品进出口环境管理登记审批章。国内外为进口或出口列入《名录》的有毒化学品而申请的《化学品进(出)口环境管理登记证》为绿色证，外商或其代理人为首次向中国出口化学品而申请的《化学品进(出)口环境管理登记证》为粉色证，临时登记证为白色证。"},{"i":12,"n":"第十二条","txt":"《有毒化学品进(出)口环境管理放行通知单》第一联由国家环境保护局留存，第二联(正本)交申请人用以报关，第三联发送中华人民共和国国家进出口商品检验局。"},{"i":13,"n":"第十三条","txt":"申请化学品进出口环境管理登记的审查期限从收到符合登记资料要求的申请之日起计算，对化学品首次进口登记申请的审查期不超过一百八十天，对列入《名录》的有毒化学品进出口登记申请的审查期不超过三十天。"},{"i":14,"n":"第十四条","txt":"国家环境保护局审批化学品进出口环境管理登记申请时，有权向申请人提出质询和要求补充有关资料。国家环境保护局应当为申请提交的资料和样品保守技术秘密。"},{"i":15,"n":"第十五条","txt":"化学品首次进口环境管理登记申请表和有毒化学品环境管理登记申请表、化学品进出口环境管理登记证和临时登记证、有毒化学品进出口环境管理放行通知单，由国家环境保护局统一监制。"},{"i":16,"n":"第十六条","txt":"进出口化学品的分类、包装、标签和运输，按照国际或国内有关危险货物运输规则的规定执行。"},{"i":17,"n":"第十七条","txt":"在装卸、贮存和运输化学品过程中，必须采取有效的预防和应急措施，防止污染环境。"},{"i":18,"n":"第十八条","txt":"因包装损坏或者不符合要求而造成或者可能造成口岸污染的，口岸主管部门应立即采取措施，防止和消除污染，并及时通知当地环境保护行政主管部门，进行调查处理。防止和消除其污染的费用由有关责任人承担。"},{"i":19,"n":"第十九条","txt":"违反本规定，未进行化学品进出口环境管理登记而进出口化学品的，由海关根据海关行政处罚实施细则有关规定处以罚款，并责令当事人补办登记手续；对经补办登记申请但未获准登记的，责令退回货物。"},{"i":20,"n":"第二十条","txt":"进出口化学品造成中国口岸污染的，由当地环境保护行政主管部门予以处罚。"},{"i":21,"n":"第二十一条","txt":"违反国家外贸管制规定而进出口化学品的，由外贸行政主管部门依照有关规定予以处罚。"},{"i":22,"n":"第二十二条","txt":"因实验需要，首次进口且年进口量不足50公斤的化学品免于登记(《中国禁止或严格限制的有毒化学品名录》中的化学品除外)。"},{"i":23,"n":"第二十三条","txt":"化学品进出口环境管理登记收费办法另行制定。"},{"i":24,"n":"第二十四条","txt":"本规定由国家环境保护局负责解释。"},{"i":25,"n":"第二十五条","txt":"本规定自1994年5月1日起施行。 　　（说明：文中提及的《中国禁止或严格限制的有毒化学品名录》（第一批）和《有毒化学品进（出）口环境管理放行通知单》是同一文件的另外两个附件，不是本规章的附件，且已由其他规范性文件修正，不附。）"}],"yiliaobaozhangjijinshiyongjianduguanlijubaochuliza7f6f61":[{"i":1,"n":"第一条","txt":"为规范医疗保障基金使用监督管理举报处理工作，确保及时、有效处理举报，切实维护医疗保障基金安全，保护自然人、法人或者其他组织合法权益，根据《中华人民共和国社会保险法》《医疗保障基金使用监督管理条例》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"违法违规使用基本医疗保险（含生育保险）基金、医疗救助基金等医疗保障基金的举报处理，适用本办法。 本办法所称举报，是指自然人、法人或者其他组织（以下简称举报人）向医疗保障行政部门反映被举报人涉嫌违反医疗保障基金使用监督管理法律、法规、规章的行为。"},{"i":3,"n":"第三条","txt":"国务院医疗保障行政部门主管全国举报处理工作，指导地方医疗保障行政部门举报处理工作。各级医疗保障行政部门建立健全举报处理工作机制。 县级以上医疗保障行政部门负责本行政区域内的举报处理工作。法律、行政法规、部门规章另有规定的，依照其规定。"},{"i":4,"n":"第四条","txt":"医疗保障行政部门处理举报，应当遵循统一领导、属地管理、分级负责、公正高效的原则，做到适用依据正确、程序合法。"},{"i":5,"n":"第五条","txt":"鼓励社会公众和新闻媒体对涉嫌违反医疗保障基金使用监督管理的违法违规行为依法进行社会监督和舆论监督。"},{"i":6,"n":"第六条","txt":"向医疗保障行政部门提出举报的，应当通过医疗保障行政部门公布的接收举报的互联网、电话、传真、邮寄地址等渠道进行。医疗保障经办机构等部门接收的举报线索，依法应当由医疗保障行政部门处理的，移交医疗保障行政部门处理。 各级医疗保障行政部门应当畅通举报渠道，加强举报渠道专业化、一体化建设。"},{"i":7,"n":"第七条","txt":"举报人应当提供涉嫌违反医疗保障基金使用监督管理法律、法规、规章的具体线索。举报人采取非书面方式进行举报的，医疗保障行政部门工作人员应当记录。"},{"i":8,"n":"第八条","txt":"举报人可以实名举报或者匿名举报。举报人实名举报的，举报时应提供本人真实身份信息和真实有效的联系方式。鼓励举报人实名举报，医疗保障行政部门按本办法要求，履行相关告知程序，对实名举报人的信息予以严格保密。 医疗保障行政部门对接收的举报进行登记。"},{"i":9,"n":"第九条","txt":"举报由被举报行为发生地的县级以上医疗保障行政部门处理。法律、行政法规、部门规章另有规定的，依照其规定。 接到举报的医疗保障行政部门不具备处理权限的，应当告知举报人直接向有处理权限的医疗保障等行政部门提出。 下级医疗保障行政部门认为需要由上级医疗保障行政部门处理的举报，可以报请上级医疗保障行政部门决定；上级医疗保障行政部门认为有必要的，可以处理下级医疗保障行政部门接收的举报。"},{"i":10,"n":"第十条","txt":"两个以上医疗保障行政部门因处理权限发生争议的，应当自发生争议之日起7个工作日内协商解决；协商不成的，报请共同的上一级医疗保障行政部门指定处理部门。"},{"i":11,"n":"第十一条","txt":"县级以上医疗保障行政部门统一接收举报的工作机构，应当及时将举报分送有处理权限的下级医疗保障行政部门或者同级医疗保障行政部门相关机构处理。 同级医疗保障行政部门相关机构收到分送的举报，应当按照本办法有关规定及时处理。不具备处理权限的，应当及时反馈统一接收举报的工作机构，不得自行移送。"},{"i":12,"n":"第十二条","txt":"医疗保障行政部门应当按照医疗保障行政处罚等有关规定处理举报。 举报人实名举报的，有处理权限的医疗保障行政部门应当自作出是否立案决定之日起5个工作日内告知举报人。"},{"i":13,"n":"第十三条","txt":"法律、法规、规章规定医疗保障行政部门应当将举报处理结果告知举报人的，医疗保障行政部门应当予以告知。"},{"i":14,"n":"第十四条","txt":"对于已经立案的举报事项，医疗保障行政部门作出处理决定前，举报人主动撤回举报的，不影响医疗保障行政部门的调查处理；医疗保障行政部门不再将处理结果告知举报人。"},{"i":15,"n":"第十五条","txt":"被举报人应当依法配合医疗保障行政部门调查。"},{"i":16,"n":"第十六条","txt":"医疗保障行政部门应当对举报人的信息予以保密，不得将举报人个人信息、举报办理情况等泄露给被举报人或者与办理举报工作无关的人员。 对举报处理工作中获悉的国家秘密以及公开后可能危及国家安全、公共安全、经济安全、社会稳定的信息，医疗保障行政部门应当严格保密。 涉及商业秘密、个人隐私等信息，依照《中华人民共和国政府信息公开条例》等有关规定执行。"},{"i":17,"n":"第十七条","txt":"医疗保障行政部门应当加强对本行政区域举报信息的统计、分析、应用，定期公布举报统计分析报告。"},{"i":18,"n":"第十八条","txt":"举报人应当对举报内容及其所提供材料的真实性负责。捏造、歪曲事实，诬告陷害他人的，依法承担相关法律责任。"},{"i":19,"n":"第十九条","txt":"国务院医疗保障行政部门建立举报处理工作年度报告制度，各省级医疗保障行政部门应当于每年4月30日前，向国务院医疗保障行政部门报告上一年度举报处理工作情况。如遇重大事项，各省级医疗保障行政部门应当按规定及时向国务院医疗保障行政部门报告。"},{"i":20,"n":"第二十条","txt":"医疗保障行政部门对经查实且具有重大社会影响的典型案例，应当向社会公布；但涉及国家秘密、工作秘密、商业秘密和个人隐私的，依照《中华人民共和国政府信息公开条例》等有关规定执行。"},{"i":21,"n":"第二十一条","txt":"经查实符合举报奖励条件的举报，医疗保障行政部门应当按规定予以奖励。"},{"i":22,"n":"第二十二条","txt":"医疗保障行政部门应当在办结后5个工作日内，依据相关档案管理规定，对举报处理过程中涉及的相关资料立卷归档，留档备查。"},{"i":23,"n":"第二十三条","txt":"各级医疗保障行政部门应当配备专业人员，提供必要的办公场所、办公设备等，保障举报接收、处理工作顺利进行。"},{"i":24,"n":"第二十四条","txt":"违法违规使用居民大病保险、职工大额医疗费用补助、公务员医疗补助等医疗保障资金的举报处理，参照本办法执行。"},{"i":25,"n":"第二十五条","txt":"以举报形式进行咨询、政府信息公开申请、行政复议申请、信访等活动的，不适用本办法，医疗保障行政部门可以告知通过相应途径提出。"},{"i":26,"n":"第二十六条","txt":"本办法自2022年3月1日起施行。"}],"yiliaobaozhangjijinfeixingjianchaguanlizanxingbanfe9e329":[{"i":1,"n":"第一条","txt":"为了加强医疗保障基金监督检查，规范飞行检查工作，根据《中华人民共和国社会保险法》《医疗保障基金使用监督管理条例》等有关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称医疗保障基金飞行检查（以下简称飞行检查），是指国家和省级医疗保障行政部门组织实施的，对定点医药机构、医保经办机构、承办医保业务的其他机构等被检查对象不预先告知的现场监督检查。"},{"i":3,"n":"第三条","txt":"飞行检查应当遵循实事求是、公正文明、程序合法的原则。"},{"i":4,"n":"第四条","txt":"国家医疗保障行政部门负责组织实施全国范围内的飞行检查。 省级医疗保障行政部门负责组织实施本行政区域内的飞行检查。省级医疗保障行政部门开展的省际联合、交叉飞行检查，应当在启动前向国家医疗保障行政部门备案。"},{"i":5,"n":"第五条","txt":"医疗保障行政部门建立与财政、卫生健康、市场监管、中医药等相关部门沟通机制，加强协调配合，必要时可以联合相关部门开展飞行检查。 医疗保障行政部门可以聘请符合条件的信息技术服务机构、会计师事务所、商业保险机构等第三方机构和专业人员协助开展飞行检查。"},{"i":6,"n":"第六条","txt":"医疗保障行政部门建立被检查对象库和检查人员库、专家库，并实行动态管理。"},{"i":7,"n":"第七条","txt":"医疗保障行政部门应当加强飞行检查能力建设，按照国家有关规定，配置飞行检查必要的检查设备、执法取证装备，提高飞行检查质量和效率。"},{"i":8,"n":"第八条","txt":"医疗保障行政部门应当主动接受社会各界对飞行检查工作的监督。"},{"i":9,"n":"第九条","txt":"参加飞行检查的人员应当遵守法律法规，严格执行保密、回避、廉洁等规定。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，医疗保障行政部门可以启动飞行检查： （一）年度工作计划安排的； （二）举报线索反映医疗保障基金可能存在重大安全风险的； （三）医疗保障智能监控或者大数据筛查提示医疗保障基金可能存在重大安全风险的； （四）新闻媒体曝光，造成重大社会影响的； （五）其他需要开展飞行检查的情形。"},{"i":11,"n":"第十一条","txt":"医疗保障行政部门原则上采取“双随机、一公开”的方式组织开展年度工作计划安排的飞行检查。 有本办法第十条第二项至第五项规定的情形，可直接开展检查工作。"},{"i":12,"n":"第十二条","txt":"组织飞行检查的医疗保障行政部门应当统筹安排，做好业务指导和工作保障，派出飞行检查组开展现场检查。 飞行检查组应当由医疗保障行政执法人员和熟悉医保、医疗、医药、财务、信息等相关专业的其他人员组成。"},{"i":13,"n":"第十三条","txt":"被检地医疗保障行政部门应当配合做好飞行检查有关工作，及时提供真实、完整、准确的政策文件、数据信息等有关材料，根据检查需要，可派行政执法、医保稽核人员配合现场检查工作。"},{"i":14,"n":"第十四条","txt":"飞行检查组应当制定飞行检查的具体实施方案，明确检查时间、方式、程序、重点、标准以及被检查对象确定方法等，主动研判风险，视情提出防控预案。 具体实施方案报经组织飞行检查的医疗保障行政部门同意后执行。"},{"i":15,"n":"第十五条","txt":"飞行检查组到达检查现场后，应当向被检查对象出示执法证件及相关工作证件并送达检查通知书，告知其享有的权利和应尽的义务。"},{"i":16,"n":"第十六条","txt":"被检查对象应当配合飞行检查工作，明确现场负责人，及时提供真实、有效、完整的文件、记录、票据、凭证、数据、病历等相关材料，如实回答飞行检查组的询问，并对疑点数据和有关问题作出解释说明、提供证明材料。 必要时，飞行检查组可以询问与检查事项有关的其他单位和个人，要求其对与检查事项有关的问题作出说明、提供有关证明材料。有关单位和个人应当配合。"},{"i":17,"n":"第十七条","txt":"现场检查应当至少有2名持有执法证件的检查人员参加。现场检查应当做好文字或者音像记录，记录应当及时、准确、完整、有效，客观真实反映现场检查情况。 现场检查应当制作现场笔录，由当事人或者有关人员以逐页签字或者盖章等方式确认。对有关人员进行询问的，检查人员应当制作询问笔录，并经询问对象逐页签字或者捺印确认。"},{"i":18,"n":"第十八条","txt":"现场检查作出检查结论前，飞行检查组应当向被检查对象反馈检查的有关情况。被检查对象有异议的，可以陈述和申辩，补充相关材料。飞行检查组应当如实记录、认真审核、充分研判、集体决策，妥善进行争议问题处理。"},{"i":19,"n":"第十九条","txt":"飞行检查组对被检查对象不配合检查、未如实提供相关材料和信息、无正当理由拒不认可检查结论的，应当如实记录，并及时移交被检地医疗保障行政部门或者其他主管部门依法依规进行处置。"},{"i":20,"n":"第二十条","txt":"现场检查需增加检查力量、延长检查时间的，或者因特殊情况需中止、取消检查的，飞行检查组应当报组织飞行检查的医疗保障行政部门批准。"},{"i":21,"n":"第二十一条","txt":"现场检查结束，飞行检查组应当与被检地医疗保障行政部门就检查发现问题的事实是否清楚、证据是否充分、定性和定量是否准确等事项进行充分沟通，并以相关法律法规以及国家和被检查对象所在统筹地区的医疗保障政策作为认定违法违规问题的依据。 飞行检查中的重大问题，飞行检查组应当及时向组织飞行检查的医疗保障行政部门报告。"},{"i":22,"n":"第二十二条","txt":"飞行检查组应当在飞行检查结束时形成书面飞行检查报告，报组织飞行检查的医疗保障行政部门，并向被检地医疗保障行政部门移交飞行检查相关材料。"},{"i":23,"n":"第二十三条","txt":"被检地医疗保障行政部门应当在收到移交材料的30个工作日内，将处理进度和整改方案上报组织飞行检查的医疗保障行政部门，并在处理完结后5个工作日内报送书面报告。 被检地医疗保障行政部门的处理结果与移交的检查结果存在较大差异的，应当作出书面解释。"},{"i":24,"n":"第二十四条","txt":"被检地医疗保障行政部门应当要求被检查对象及时整改检查发现的问题，依法依规对反馈意见中涉嫌违法违规的情形进行处理： （一）对确有应受行政处罚的违法行为，依法作出行政处罚； （二）对违反医保服务协议的，交由医保经办机构按照协议约定进行处理； （三）对涉嫌违纪、职务违法、职务犯罪的问题线索，按规定移送纪检监察机关； （四）对涉嫌违反相关法律、法规、规章，应当由其他部门处理的，移送相应部门处理； （五）其他需要进行处理的情形，按规定处理。"},{"i":25,"n":"第二十五条","txt":"组织飞行检查的医疗保障行政部门应当将飞行检查结果纳入对被检地医疗保障行政部门工作的综合评价体系，并对飞行检查结果处理情况进行督导，适时组织力量开展飞行检查“回头看”。"},{"i":26,"n":"第二十六条","txt":"针对飞行检查中发现的区域性、普遍性或者长期存在、比较突出的问题，组织飞行检查的医疗保障行政部门可以约谈被检查对象和相关医疗保障部门负责人。 被约谈对象应当在15个工作日内提出整改措施，上报整改情况。其中，对于区域性、普遍性的问题，被检查对象所在地医疗保障部门应组织辖区内定点医药机构开展自查自纠。"},{"i":27,"n":"第二十七条","txt":"参加飞行检查的人员有下列情形之一的，应当按照管理权限，由相关部门依法依纪给予处分。涉嫌犯罪的，依法移交司法机关处理： （一）违反中央八项规定及其实施细则精神的； （二）泄露飞行检查相关情况、举报人信息和被检查对象信息、商业秘密的； （三）将检查获取、知悉的材料和相关信息用于监督管理以外的其他目的的； （四）与被检查对象或者有关人员有亲属、经济利益和其他利害关系，不执行回避要求的； （五）有其他违法违规和违纪行为的。 因参加飞行检查人员的不规范行为，造成不良影响的，组织飞行检查的医疗保障行政部门应当在一定范围内予以通报。"},{"i":28,"n":"第二十八条","txt":"组织飞行检查的医疗保障行政部门必要时可以将飞行检查相关结果向同级财政、卫生健康、市场监管、中医药等相关部门通报。"},{"i":29,"n":"第二十九条","txt":"组织飞行检查的医疗保障行政部门应当及时将典型案例向社会公告。"},{"i":30,"n":"第三十条","txt":"本办法中，被检地医疗保障行政部门指组织飞行检查的医疗保障行政部门的下一级医疗保障行政部门。"},{"i":31,"n":"第三十一条","txt":"本办法由国家医疗保障局负责解释。地市级及以下医疗保障行政部门可以参照本办法组织开展检查。"},{"i":32,"n":"第三十二条","txt":"本办法自2023年5月1日起实施。"}],"yiliaobaozhangxingzhengchufachengxuzanxingguiding":[{"i":1,"n":"第一条","txt":"为了规范医疗保障领域行政处罚程序，确保医疗保障行政部门依法实施行政处罚，维护医疗保障基金安全，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》《中华人民共和国行政强制法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"医疗保障领域行政处罚，适用本规定。"},{"i":3,"n":"第三条","txt":"医疗保障行政部门实施行政处罚遵循公正、公开的原则。坚持以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当。坚持处罚与教育相结合，做到事实清楚、证据确凿、依据正确、程序合法、处罚适当。"},{"i":4,"n":"第四条","txt":"医疗保障行政部门应当全面落实行政执法公示制度、执法全过程记录制度、重大执法决定法制审核制度。"},{"i":5,"n":"第五条","txt":"执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，应当回避。 当事人认为执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，有权申请回避。 当事人提出回避申请的，医疗保障行政部门应当依法审查。医疗保障行政部门主要负责人的回避，由医疗保障行政部门负责人集体讨论决定；医疗保障行政部门其他负责人的回避，由医疗保障行政部门主要负责人决定；其他有关人员的回避，由医疗保障行政部门负责人决定。决定作出前，不停止调查。"},{"i":6,"n":"第六条","txt":"违法行为在二年内未被发现的，不再给予行政处罚；涉及公民生命健康安全且有危害后果的，上述期限延长至五年。 前款规定的期限，从违法行为发生之日起计算；违法行为有连续或者继续状态的，从行为终了之日起计算。"},{"i":7,"n":"第七条","txt":"上级医疗保障行政部门对下级医疗保障行政部门实施的行政处罚，应当加强监督。 医疗保障行政部门法制机构对本部门实施的行政处罚，应当加强监督。"},{"i":8,"n":"第八条","txt":"各级医疗保障行政部门可以依法委托符合法定条件的组织开展行政执法工作。行政强制措施权不得委托。 受委托组织在委托范围内，以委托行政机关的名义实施行政处罚，不得再委托其他组织或者个人实施行政处罚。 委托书应当载明委托的具体事项、权限、期限等内容。委托行政机关和受委托组织应当将委托书向社会公布。 委托行政机关对受委托组织实施行政处罚的行为应当负责监督，并对该行为的后果承担法律责任。"},{"i":9,"n":"第九条","txt":"医疗保障领域行政处罚由违法行为发生地的县级以上医疗保障行政部门管辖。法律、行政法规、部门规章另有规定的，从其规定。 医疗保障异地就医的违法行为，由就医地医疗保障行政部门调查处理。仅参保人员违法的，由参保地医疗保障行政部门调查处理。"},{"i":10,"n":"第十条","txt":"两个以上医疗保障行政部门因管辖权发生争议的，应当自发生争议之日起七个工作日内协商解决；协商不成的，报请共同的上一级医疗保障行政部门指定管辖；也可以直接由共同的上一级医疗保障行政部门指定管辖。"},{"i":11,"n":"第十一条","txt":"上级医疗保障行政部门认为有必要时，可以直接管辖下级医疗保障行政部门管辖的案件，也可以将本部门管辖的案件交由下级医疗保障行政部门管辖。法律、法规、规章明确规定案件应当由上级医疗保障行政部门管辖的，上级医疗保障部门不得将案件交由下级医疗保障行政部门管辖。"},{"i":12,"n":"第十二条","txt":"医疗保障行政部门发现所查处的案件属于其他医疗保障行政部门或其他行政管理部门管辖的，应当依法移送。 受移送的医疗保障行政部门对管辖权有异议的，应当报请共同的上一级医疗保障行政部门指定管辖，不得再自行移送。"},{"i":13,"n":"第十三条","txt":"医疗保障行政部门实施行政处罚时，应当责令当事人改正或者限期改正违法行为。"},{"i":14,"n":"第十四条","txt":"医疗保障行政部门对依据监督检查职权或者通过投诉、举报、其他部门移送、上级交办等途径发现的违法行为线索，应当自发现线索或者收到材料之日起十五个工作日内予以核查，并决定是否立案；特殊情况下，经医疗保障行政部门主要负责人批准后，可以延长十五个工作日。"},{"i":15,"n":"第十五条","txt":"立案应当符合下列标准： （一）有明确的违法嫌疑人； （二）经核查认为存在涉嫌违反医疗保障监督管理法律、法规、规章规定，应当给予行政处罚的行为； （三）属于本部门管辖。 符合立案标准的，应当及时立案。"},{"i":16,"n":"第十六条","txt":"行政处罚应当由具有医疗保障行政执法资格的执法人员实施，执法人员不得少于两人。 执法人员应当文明执法，尊重和保护当事人合法权益。"},{"i":17,"n":"第十七条","txt":"除依据《行政处罚法》第五十一条规定的可以当场作出的行政处罚外，医疗保障行政部门发现公民、法人或者其他组织有依法应当给予行政处罚的行为的，必须全面、客观、公正地调查，收集有关证据；必要时，依照法律、法规的规定，可以进行检查。 医疗保障行政部门及参与案件办理的有关单位和人员对调查或者检查过程中知悉的国家秘密、商业秘密和个人隐私应当依法保密。不得将调查或者检查过程中获取、知悉的被调查或者被检查对象的资料或者相关信息用于医疗保障基金使用监管管理以外的其他目的，不得泄露、篡改、毁损、非法向他人提供当事人的个人信息和商业秘密。"},{"i":18,"n":"第十八条","txt":"医疗保障行政部门开展行政执法，可以采取下列措施： （一）进入被调查对象有关的场所进行检查，询问与调查事项有关的单位和个人，要求其对有关问题作出解释说明、提供有关材料； （二）采取记录、录音、录像、照相或者复制等方式收集有关情况和资料； （三）从相关信息系统中调取数据，要求被检查对象对疑点数据作出解释和说明； （四）对可能被转移、隐匿或者灭失的资料等予以封存； （五）聘请符合条件的会计师事务所等第三方机构和专业人员协助开展检查； （六）法律、法规规定的其他措施。"},{"i":19,"n":"第十九条","txt":"办案人员应当依法收集证据。证据包括： （一）书证； （二）物证； （三）视听资料； （四）电子数据； （五）证人证言； （六）当事人的陈述； （七）鉴定意见； （八）勘验笔录、现场笔录。 立案前核查或者监督检查过程中依法取得的证据材料，可以作为案件的证据使用。 对于移送的案件，移送机关依职权调查收集的证据材料，可以作为案件的证据使用。 证据经查证属实，作为认定案件事实的根据。"},{"i":20,"n":"第二十条","txt":"办案人员在进入现场检查时，应当通知当事人或者有关人员到场，并按照有关规定采取拍照、录音、录像等方式记录现场情况。现场检查应当制作现场笔录，并由当事人或者有关人员以逐页签名或盖章等方式确认。 无法通知当事人或者有关人员到场，当事人或者有关人员拒绝接受调查及签名、盖章或者拒绝以其他方式确认的，办案人员应当在笔录或者其他材料上注明情况。"},{"i":21,"n":"第二十一条","txt":"收集、调取的书证、物证应当是原件、原物。调取原件、原物有困难的，可以提取复制件、影印件或者抄录件，也可以拍摄或者制作足以反映原件、原物外形或者内容的照片、录像。复制件、影印件、抄录件和照片、录像由证据提供人核对无误后注明与原件、原物一致，并注明取证日期、证据出处，同时由证据提供人签名或者盖章。"},{"i":22,"n":"第二十二条","txt":"收集、调取的视听资料应当是有关资料的原始载体。调取视听资料原始载体有困难的，可以提取复制件，并注明制作方法、制作时间、制作人等。声音资料应当附有该声音内容的文字记录。视听资料制作记录、声音文字记录同时由证据提供人核对无误后签名或者盖章。"},{"i":23,"n":"第二十三条","txt":"医疗保障行政部门可以利用网络信息系统或者设备收集、固定违法行为证据。用来收集、固定违法行为证据的网络信息系统或者设备应当符合相关规定，保证所收集、固定电子数据的真实性、完整性。 医疗保障行政部门可以指派或者聘请具有专门知识的人员，辅助办案人员对案件关联的电子数据进行调取。 收集、调取的电子数据应当是有关数据的原始载体。收集电子数据原始载体有困难的，可以采用拷贝复制、委托分析、书式固定、拍照录像等方式取证，并注明制作方法、制作时间、制作人等。 医疗保障行政部门利用电子技术监控设备收集、固定违法事实的，证据记录内容应符合法律、法规的规定。"},{"i":24,"n":"第二十四条","txt":"办案人员可以询问当事人及其他有关单位和个人。询问应当个别进行。询问应当制作笔录，笔录应当交被询问人核对；对阅读有困难的，应当向其宣读。笔录如有差错、遗漏，应当允许其更正或者补充。涂改部分应当由被询问人签名、盖章或者以其他方式确认。经核对无误后，由被询问人在笔录上逐页签名、盖章或者以其他方式确认。办案人员应当在笔录上签名。"},{"i":25,"n":"第二十五条","txt":"为查明案情，需要对案件相关医疗文书、医疗证明等内容进行评审的，医疗保障行政部门可以组织有关专家进行评审。"},{"i":26,"n":"第二十六条","txt":"医疗保障行政部门在收集证据时，在证据可能灭失或者以后难以取得的情况下，经医疗保障行政部门负责人批准，可以先行登记保存，并应当在七个工作日内及时作出处理决定。 情况紧急，需要当场采取先行登记保存措施的，执法人员应当在二十四小时内向医疗保障行政部门负责人报告，并补办批准手续。医疗保障行政部门负责人认为不应当采取先行登记保存措施的，应当立即解除。"},{"i":27,"n":"第二十七条","txt":"先行登记保存有关证据，应当当场清点，开具清单，由当事人和办案人员签名或者盖章。清单交当事人一份，并当场交付先行登记保存证据通知书。 先行登记保存期间，当事人或者有关人员不得损毁、销毁或者转移证据。"},{"i":28,"n":"第二十八条","txt":"对于先行登记保存的证据，医疗保障行政部门可以根据案件需要采取以下处理措施： （一）根据情况及时采取记录、复制、拍照、录像等证据保全措施； （二）可依法采取封存措施的，决定予以封存； （三）违法事实不成立，或者违法事实成立但不予行政处罚的，决定解除先行登记保存措施。 逾期未采取相关措施的，先行登记保存措施自动解除。"},{"i":29,"n":"第二十九条","txt":"医疗保障行政部门对可能被转移、隐匿或者灭失的资料，无法以先行登记保存措施加以证据保全，采取封存措施；采取或者解除封存措施的，应当经医疗保障行政部门负责人批准。 情况紧急，需要当场采取封存等行政强制措施的，执法人员应当在二十四小时内向医疗保障行政部门负责人报告，并补办批准手续。医疗保障行政部门负责人认为不应当采取行政强制措施的，应当立即解除。"},{"i":30,"n":"第三十条","txt":"医疗保障行政部门实施封存等行政强制措施应当依照《中华人民共和国行政强制法》规定的程序进行，并当场交付实施行政强制措施决定书和清单。"},{"i":31,"n":"第三十一条","txt":"封存的期限不得超过三十日；情况复杂的，经医疗保障行政部门负责人批准，可以延长，但是延长期限不得超过三十日。延长封存的决定应当及时书面告知当事人，并说明理由。"},{"i":32,"n":"第三十二条","txt":"封存的资料应妥善保管，防止丢失、损毁、篡改和非法借阅；医疗保障行政部门可以委托第三人保管，第三人不得损毁、篡改或者擅自转移、处置。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一的，医疗保障行政部门应当及时作出解除封存决定： （一）当事人没有违法行为； （二）封存的资料与违法行为无关； （三）对违法行为已经作出处理决定，不再需要封存； （四）封存期限已经届满； （五）其他不再需要采取封存措施的情形。 解除封存应当立即退还资料，并由办案人员和当事人在资料清单上签名或者盖章。"},{"i":34,"n":"第三十四条","txt":"医疗保障行政部门在案件办理过程中需要其他行政区域医疗保障行政部门协助调查取证的，应当出具书面协助调查函。被请求协助的医疗保障行政部门在接到协助调查函之日起十五日内完成相关协查工作。需要延期完成或者无法协助的，应当在期限届满前告知提出协查请求的医疗保障行政部门。"},{"i":35,"n":"第三十五条","txt":"医疗保障行政部门应当依法以文字、音像等形式，对行政处罚的立案、调查取证、审核决定、送达执行等进行全过程记录，归档保存。"},{"i":36,"n":"第三十六条","txt":"案件调查终结，办案机构应当撰写案件调查终结报告，案件调查终结报告包括以下内容： （一）当事人的基本情况； （二）案件来源、调查经过及采取行政强制措施的情况； （三）调查认定的事实及主要证据； （四）违法行为性质； （五）处理意见及依据； （六）其他需要说明的事项。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一，在医疗保障行政部门负责人作出决定之前，应当进行法制审核，未经法制审核或者审核未通过的，不得作出决定： （一）责令追回医保基金或者罚款数额较大的； （二）责令解除医保服务协议等直接关系到当事人或第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）涉及重大公共利益的； （五）法律、法规规定的其他需要审核的重大行政执法情形。 法制审核由医疗保障行政部门法制机构负责实施，同一案件的办案人员不得作为审核人员。"},{"i":38,"n":"第三十八条","txt":"法制审核的主要内容包括： （一）行政执法主体是否合法，行政执法人员是否具备执法资格； （二）是否具有管辖权； （三）案件事实是否清楚、证据是否充分； （四）定性是否准确； （五）适用依据是否正确； （六）程序是否合法； （七）处理是否适当； （八）行政执法文书是否完备、规范； （九）违法行为是否涉嫌犯罪、需要移送司法机关； （十）其他需要合法性审核的内容。"},{"i":39,"n":"第三十九条","txt":"法制机构经对案件进行审核，区别不同情况提出书面意见和建议： （一）事实清楚、证据确凿充分、定性准确、适用法律正确、处罚适当、程序合法的，提出同意的意见； （二）主要事实不清、证据不足的，提出继续调查或不予作出行政执法决定的意见； （三）定性不准、适用法律不准确和执行裁量基准不当的，提出变更意见； （四）超越执法权限或程序不合法的，提出纠正意见； （五）认为有必要提出的其他意见和建议。 行政执法机构或办案人员应根据法制机构提出的上述第二项至第四项意见作出相应处理后再次进行法制审核。"},{"i":40,"n":"第四十条","txt":"法制机构收到相关资料后，于十个工作日内审核完毕。因特殊情况需要延长的，经法制机构负责人批准后可延长十个工作日，但不得超过法定时限要求。 行政执法机构或办案人员与法制机构对审核意见不一致时，法制机构可以组织有关专家、法律顾问或者委托第三方专业机构论证，将论证意见等相关材料提交医疗保障行政部门负责人，由医疗保障行政部门负责人组织集体讨论决定。"},{"i":41,"n":"第四十一条","txt":"根据调查情况，拟给予行政处罚的案件，医疗保障行政部门在作出行政处罚决定之前应当书面告知当事人拟作出行政处罚决定的事实、理由及依据，并告知当事人依法享有陈述权、申辩权。 医疗保障行政部门应当充分听取当事人陈述、申辩意见，对当事人提出的事实、理由和证据进行复核。 拟作出的行政处罚属于听证范围的，应当告知当事人有要求举行听证的权利，当事人要求听证的，医疗保障行政部门应当依法组织听证。 当事人提出的事实、理由或者证据成立的，医疗保障行政部门应当予以采纳，不得因当事人陈述、申辩或者申请听证而加重行政处罚。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，经医疗保障行政部门负责人批准，中止案件调查，并制作案件中止调查决定书： （一）行政处罚决定必须以相关案件的裁判结果或者其他行政决定为依据，而相关案件尚未审结或者其他行政决定尚未作出； （二）涉及法律适用等问题，需要送请有权机关作出解释或者确认； （三）因不可抗力致使案件暂时无法调查； （四）因当事人下落不明致使案件暂时无法调查； （五）其他应当中止调查的情形。 中止调查的原因消除后，应当立即恢复案件调查。"},{"i":43,"n":"第四十三条","txt":"医疗保障行政部门负责人经对案件调查终结报告、法制审核意见、当事人陈述和申辩意见或者听证报告等进行审查，根据不同情况，分别作出以下决定： （一）确有依法应当给予行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）确有违法行为，但有依法不予行政处罚情形的，不予行政处罚； （三）违法事实不能成立的，不得给予行政处罚； （四）依法应移送其他行政管理部门或者医疗保障经办机构处理的，作出移送决定； （五）违法行为涉嫌犯罪的，移送司法机关。"},{"i":44,"n":"第四十四条","txt":"对下列情节复杂或者重大违法行为给予行政处罚的案件，应当由医疗保障行政部门负责人集体讨论决定： （一）涉及重大安全问题或者有重大社会影响的案件； （二）调查处理意见与法制审核意见存在重大分歧的案件； （三）医疗保障行政部门负责人认为应当提交集体讨论的其他案件。 集体讨论应当形成讨论记录，集体讨论中有不同意见的,应当如实记录。讨论记录经参加讨论人员确认签字，存入案卷。"},{"i":45,"n":"第四十五条","txt":"适用普通程序办理的案件应当自立案之日起九十日内作出处理决定。 因案情复杂或者其他原因，不能在规定期限内作出处理决定的，经医疗保障行政部门负责人批准，可以延长三十日。 案情特别复杂或者有其他特殊情况，经延期仍不能作出处理决定的，应当由医疗保障行政部门负责人集体讨论决定是否继续延期，决定继续延期的，应当同时确定延长的合理期限，但最长不得超过六十日。 案件处理过程中，检测检验、鉴定、听证、公告和专家评审时间不计入前款所指的案件办理期限。"},{"i":46,"n":"第四十六条","txt":"医疗保障行政部门作出的行政处罚决定应当按照政府信息公开及行政执法公示制度等有关规定予以公开。公开的行政处罚决定被依法变更、撤销、确认违法或者确认无效的，医疗保障行政部门应在三日内变更行政处罚决定相关信息并说明理由。"},{"i":47,"n":"第四十七条","txt":"具有下列情形之一的，经医疗保障行政部门负责人批准，终止案件调查： （一）涉嫌违法的公民死亡（或者下落不明长期无法调查的）或者法人、其他组织终止，并且无权利义务承受人等原因，致使案件调查无法继续进行的； （二）移送司法机关追究刑事责任的； （三）其他依法应当终止调查的。 对于终止调查的案件，已经采取强制措施的应当同时解除。"},{"i":48,"n":"第四十八条","txt":"违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的行政处罚的，可以当场作出行政处罚决定。"},{"i":49,"n":"第四十九条","txt":"适用简易程序当场查处违法行为，办案人员应当向当事人出示执法证件，填写预定格式、编有号码的行政处罚决定书，并当场交付当事人。当事人拒绝签收的，应当在行政处罚决定书上注明。"},{"i":50,"n":"第五十条","txt":"办案人员在行政处罚决定作出前，应当告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人有权进行陈述和申辩。当事人进行陈述和申辩的，办案人员应当记入笔录。"},{"i":51,"n":"第五十一条","txt":"适用简易程序当场作出行政处罚决定的，办案人员应当在作出行政处罚决定之日起七个工作日内将处罚决定及相关材料报所属医疗保障行政部门备案。"},{"i":52,"n":"第五十二条","txt":"依照本法规定当场作出行政处罚决定，有下列情形之一的，办案人员可以当场收缴罚款： （一）依法给予一百元以下的罚款的； （二）不当场收缴事后难以执行的。 办案人员当场收缴罚款的，必须向当事人出具国务院财政部门或者省、自治区、直辖市人民政府财政部门统一制发的专用票据；不出具财政部门统一制发的专用票据的，当事人有权拒绝缴纳罚款。 办案人员当场收缴的罚款，应当自收缴罚款之日起二个工作日内，交至医疗保障行政部门；医疗保障行政部门应当在二个工作日内将罚款缴付指定的银行。"},{"i":53,"n":"第五十三条","txt":"退回的基金退回原医疗保障基金财政专户；罚款、没收的违法所得依法上缴国库。 行政处罚决定依法作出后，当事人应当在行政处罚决定规定的期限内予以履行。 当事人对行政处罚决定不服申请行政复议或者提起行政诉讼的，行政处罚决定不停止执行。法律另有规定的除外。"},{"i":54,"n":"第五十四条","txt":"当事人确有经济困难，需要暂缓或者分期缴纳罚款的，应当提出申请。经医疗保障行政部门负责人批准，同意当事人暂缓或者分期缴纳罚款的，医疗保障行政部门应当书面告知当事人暂缓或者分期的期限以及罚款金额。"},{"i":55,"n":"第五十五条","txt":"当事人逾期不履行行政处罚决定的，作出行政处罚决定的医疗保障行政部门可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款，加处罚款的数额不得超出罚款的数额； （二）依照《中华人民共和国行政强制法》的规定申请人民法院强制执行。 医疗保障行政部门批准暂缓、分期缴纳罚款的，申请人民法院强制执行的期限，自暂缓或者分期缴纳罚款期限结束之日起计算。"},{"i":56,"n":"第五十六条","txt":"有下列情形之一的，医疗保障行政部门可以结案： （一）行政处罚决定执行完毕的； （二）医疗保障行政部门依法申请人民法院强制执行行政处罚决定，人民法院依法受理的； （三）不予行政处罚等无须执行的； （四）医疗保障行政部门认为可以结案的其他情形。 办案人员应当填写行政处罚结案报告，经医疗保障行政部门负责人批准后，予以结案。"},{"i":57,"n":"第五十七条","txt":"医疗保障行政部门应当按照下列要求及时将案件材料立卷归档： （一）一案一卷； （二）文书齐全，手续完备； （三）案卷应当按顺序装订。"},{"i":58,"n":"第五十八条","txt":"期间以时、日、月计算，期间开始的时或者日不计算在内。期间不包括在途时间。期间届满的最后一日为法定节假日的，以法定节假日后的第一日为期间届满的日期。"},{"i":59,"n":"第五十九条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，医疗保障行政部门应当在七个工作日内依照《中华人民共和国民事诉讼法》的有关规定，将行政处罚决定书送达当事人。 当事人同意并签订确认书的，医疗保障行政部门可以采用传真、电子邮件等方式，将行政处罚决定书等送达当事人。"},{"i":60,"n":"第六十条","txt":"本规定中的“以上”“以下”“内”均包括本数。"},{"i":61,"n":"第六十一条","txt":"外国人、无国籍人、外国组织在中华人民共和国领域内有医疗保障违法行为，应当给予行政处罚的，适用本规定，法律、法规另有规定的除外。"},{"i":62,"n":"第六十二条","txt":"本规定自2021年7月15日起施行。"}],"yiliaoqixieshengchanqiyezhiliangtixikaohebanfa":[{"i":1,"n":"第一条","txt":"为加强医疗器械管理，强化企业质量控制，保证病患者的人身安全，根据《医疗器械监督管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于申请第二类、第三类医疗器械准产注册企业的审查及对企业的定期审查。 下列情况可视同已通过企业质量体系考核： （一）企业获得国务院药品监督管理部门认可的质量认证机构颁发的ＧＢ／Ｔ１９００１和ＹＹ／Ｔ０２８７（或ＧＢ／Ｔ１９００２和ＹＹ／Ｔ０２８８）标准的质量体系认证证书，证书在有效期内的。 （二）已实施工业产品生产许可证的产品，其证书在有效期内的。 （三）已实施产品安全认证，企业持有的产品安全认证证书在有效期内的。"},{"i":3,"n":"第三条","txt":"申请第二、三类医疗器械生产企业质量体系考核，均由所在地省、自治区、直辖市药品监督管理部门受理并组织考核。 国家规定的部分三类医疗器械，由所在地省、自治区、直辖市药品监督管理部门受理后，报国家药品监督管理局，由国家药品监督管理局组织考核。 部分三类医疗器械目录由国家药品监督管理局确定并公布。 质量体系的考核，可委托下一级药品监督管理部门或具有相应资格的第三方机构进行。质量体系考核结果由委托方负责。"},{"i":4,"n":"第四条","txt":"企业在申请产品准产注册前，应填写《医疗器械生产企业质量体系考核申请书》（见附件１），向省级以上药品监督管理部门提出企业质量体系考核申请。 国家规定的部分三类医疗器械的质量体系考核，企业提出质量体系考核申请的同时，向国家药品监督管理局提交被考核产品的《质量保证手册》和《程序文件》。 其它产品的质量体系考核，企业提出质量体系考核申请前，应按《质量体系考核企业自查表》（见附件１的附表）进行自查，填写自查表。自查表填写内容应如实、准确，以备现场考核时查验。"},{"i":5,"n":"第五条","txt":"对二类医疗器械，省、自治区、直辖市药品监督管理部门应对企业填写的《质量体系考核企业自查表》和提供的相关资料进行审核，经审核后签署意见，必要时可对申请企业进行现场查验。 对三类医疗器械，按本办法第三条执行后，质量体系考核申请和考核报告（见附件１、２）应在国家药品监督管理局备案正本（原件）一份。"},{"i":6,"n":"第六条","txt":"考核人员至少应有一人经贯彻ＧＢ／Ｔ１９００１和ＹＹ／Ｔ０２８７标准的培训，并取得内审员或外审员的资格；考核人员至少由二人组成；确定的考核人员与被考核的企业应无经济利益联系。"},{"i":7,"n":"第七条","txt":"质量体系现场考核，参照质量体系认证审核的方法；依据附件１自查表确定的内容进行考核，重点考核项目及判定规则为： 考核结论判定为“通过考核”的，对质量体系的评价和存在不合格项要如实陈述，对不合格项给出整改期限。不能如期完成整改的应作为“整改后复核”处理。"},{"i":8,"n":"第八条","txt":"考核结论为“整改后复核”的，以“考核报告”的签署日起，企业必须在半年内完成整改并申请复核，逾期将取消申请准产注册资格。"},{"i":9,"n":"第九条","txt":"企业产品质量体系考核以“考核报告”通过的签署日为准，其有效期为四年；在有效期内企业申请同类产品准产注册，不再进行考核（药品监督管理部门另有规定的除外）。 企业应定期进行质量体系自查，自查结果应按《质量体系考核企业自查表》的规定进行记录、归档。 省、自治区、直辖市药品监督管理部门定期对企业进行体系审查。"},{"i":10,"n":"第十条","txt":"企业通过质量体系考核后，不按规定进行自查、不按质量体系要求组织生产的，经核实，由所在地省、自治区、直辖市药品监督管理部门予以警告，并限期整改。"},{"i":11,"n":"第十一条","txt":"本办法由国家药品监督管理局负责解释。"},{"i":12,"n":"第十二条","txt":"本办法自２０００年７月１日起施行。 附表："}],"yiliaojigouyiliaobaozhangdingdianguanlizanxingbanf3b9373":[{"i":1,"n":"第一条","txt":"为加强和规范医疗机构医疗保障定点管理，提高医疗保障基金使用效率，更好地保障广大参保人员权益，根据《中华人民共和国社会保险法》《中华人民共和国基本医疗卫生与健康促进法》及《医疗机构管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"医疗机构医疗保障定点管理应坚持以人民健康为中心，遵循保障基本、公平公正、权责明晰、动态平衡的原则，加强医保精细化管理，促进医疗机构供给侧改革，为参保人员提供适宜的医疗服务。"},{"i":3,"n":"第三条","txt":"医疗保障行政部门负责制定医疗机构定点管理政策，在定点申请、专业评估、协商谈判、协议订立、协议履行、协议解除等环节对医疗保障经办机构（以下简称“经办机构”）、定点医疗机构进行监督。经办机构负责确定定点医疗机构，并与定点医疗机构签订医疗保障服务协议（以下简称“医保协议”），提供经办服务，开展医保协议管理、考核等。定点医疗机构应当遵守医疗保障法律、法规、规章及有关政策，按照规定向参保人员提供医疗服务。"},{"i":4,"n":"第四条","txt":"统筹地区医疗保障行政部门根据公众健康需求、管理服务需要、医保基金收支、区域卫生规划、医疗机构设置规划等确定本统筹地区定点医疗服务的资源配置。"},{"i":5,"n":"第五条","txt":"以下取得医疗机构执业许可证或中医诊所备案证的医疗机构，以及经军队主管部门批准有为民服务资质的军队医疗机构可申请医保定点： （一）综合医院、中医医院、中西医结合医院、民族医医院、专科医院、康复医院； （二）专科疾病防治院（所、站）、妇幼保健院； （三）社区卫生服务中心（站）、中心卫生院、乡镇卫生院、街道卫生院、门诊部、诊所、卫生所（站）、村卫生室（所）； （四）独立设置的急救中心； （五）安宁疗护中心、血液透析中心、护理院； （六）养老机构内设的医疗机构。 互联网医院可依托其实体医疗机构申请签订补充协议，其提供的医疗服务所产生的符合医保支付范围的相关费用，由统筹地区经办机构与其所依托的实体医疗机构按规定进行结算。"},{"i":6,"n":"第六条","txt":"申请医保定点的医疗机构应当同时具备以下基本条件： （一）正式运营至少3个月； （二）至少有1名取得医师执业证书、乡村医生执业证书或中医（专长）医师资格证书且第一注册地在该医疗机构的医师； （三）主要负责人负责医保工作，配备专（兼）职医保管理人员；100张床位以上的医疗机构应设内部医保管理部门，安排专职工作人员； （四）具有符合医保协议管理要求的医保管理制度、财务制度、统计信息管理制度、医疗质量安全核心制度等； （五）具有符合医保协议管理要求的医院信息系统技术和接口标准，实现与医保信息系统有效对接，按要求向医保信息系统传送全部就诊人员相关信息，为参保人员提供直接联网结算。设立医保药品、诊疗项目、医疗服务设施、医用耗材、疾病病种等基础数据库，按规定使用国家统一的医保编码； （六）符合法律法规和省级及以上医疗保障行政部门规定的其他条件。"},{"i":7,"n":"第七条","txt":"医疗机构向统筹地区经办机构提出医保定点申请，至少提供以下材料： （一）定点医疗机构申请表； （二）医疗机构执业许可证或中医诊所备案证或军队医疗机构为民服务许可证照复印件； （三）与医保政策对应的内部管理制度和财务制度文本； （四）与医保有关的医疗机构信息系统相关材料； （五）纳入定点后使用医疗保障基金的预测性分析报告； （六）省级医疗保障行政部门按相关规定要求提供的其他材料。"},{"i":8,"n":"第八条","txt":"医疗机构提出定点申请，统筹地区经办机构应即时受理。对申请材料内容不全的，经办机构自收到材料之日起5个工作日内一次性告知医疗机构补充。"},{"i":9,"n":"第九条","txt":"统筹地区经办机构应组织评估小组或委托第三方机构，以书面、现场等形式开展评估。评估小组成员由医疗保障、医药卫生、财务管理、信息技术等专业人员构成。自受理申请材料之日起，评估时间不超过3个月，医疗机构补充材料时间不计入评估期限。评估内容包括： （一）核查医疗机构执业许可证或中医诊所备案证或军队医疗机构为民服务许可证； （二）核查医师、护士、药学及医技等专业技术人员执业信息和医师第一注册地信息； （三）核查与服务功能相适应的诊断、治疗、手术、住院、药品贮存及发放、检查检验放射等基础设施和仪器设备； （四）核查与医保政策对应的内部管理制度和财务制度，卫生健康部门医疗机构评审的结果； （五）核查与医保有关的医疗机构信息系统是否具备开展直接联网结算的条件。 评估结果分为合格和不合格。统筹地区经办机构应将评估结果报同级医疗保障行政部门备案。对于评估合格的，应将其纳入拟签订协议医疗机构名单，并向社会公"},{"i":10,"n":"第十条","txt":"统筹地区经办机构与评估合格的医疗机构协商谈判，达成一致的，双方自愿签订医保协议。原则上，由地市级及以上的统筹地区经办机构与医疗机构签订医保协议并向同级医疗保障行政部门备案。医保协议应明确双方权利、义务和责任。签订医保协议的双方应当严格执行协议约定。协议期限一般为1年。"},{"i":11,"n":"第十一条","txt":"统筹地区经办机构应向社会公布签订医保协议的定点医疗机构信息，包括名称、地址等，供参保人员选择。"},{"i":12,"n":"第十二条","txt":"医疗机构有下列情形之一的，不予受理定点申请： （一）以医疗美容、辅助生殖、生活照护、种植牙等非基本医疗服务为主要执业范围的； （二）基本医疗服务未执行医疗保障行政部门制定的医药价格政策的； （三）未依法履行行政处罚责任的； （四）以弄虚作假等不正当手段申请定点，自发现之日起未满3年的； （五）因违法违规被解除医保协议未满3年或已满3年但未完全履行行政处罚法律责任的； （六）因严重违反医保协议约定而被解除协议未满1年或已满1年但未完全履行违约责任的； （七）法定代表人、主要负责人或实际控制人曾因严重违法违规导致原定点医疗机构被解除医保协议，未满5年的； （八）法定代表人、主要负责人或实际控制人被列入失信人名单的； （九）法律法规规定的其他不予受理的情形。"},{"i":13,"n":"第十三条","txt":"定点医疗机构具有依法依规为参保人员提供医疗服务后获得医保结算费用，对经办机构履约情况进行监督，对完善医保政策提出意见建议等权利。"},{"i":14,"n":"第十四条","txt":"定点医疗机构应当严格执行医保协议，合理诊疗、合理收费，严格执行医保药品、医用耗材和医疗服务项目等目录，优先配备使用医保目录药品，控制患者自费比例，提高医疗保障基金使用效率。定点医疗机构不得为非定点医疗机构提供医保结算。 经办机构不予支付的费用、定点医疗机构按医保协议约定被扣除的质量保证金及其支付的违约金等，定点医疗机构不得作为医保欠费处理。"},{"i":15,"n":"第十五条","txt":"定点医疗机构及其工作人员应当执行实名就医和购药管理规定，核验参保人员有效身份凭证，按照诊疗规范提供合理、必要的医药服务，向参保人员如实出具费用单据和相关资料，不得分解住院、挂床住院，不得违反诊疗规范过度诊疗、过度检查、分解处方、超量开药、重复开药，不得重复收费、超标准收费、分解项目收费，不得串换药品、医用耗材、诊疗项目和服务设施，不得诱导、协助他人冒名或者虚假就医、购药。 定点医疗机构应当确保医疗保障基金支付的费用符合规定的支付范围；除急诊、抢救等特殊情形外，提供医疗保障基金支付范围以外的医药服务的，应当经参保人员或者其近亲属、监护人同意。"},{"i":16,"n":"第十六条","txt":"定点医疗机构应当制定相应的内部管理措施，严格掌握出入院指征。按照协议执行医保总额预算指标，执行按项目、按病种、按疾病诊断相关分组、按床日、按人头等支付方式。不得以医保支付政策为由拒收患者。"},{"i":17,"n":"第十七条","txt":"定点医疗机构按有关规定执行集中采购政策，优先使用集中采购中选的药品和耗材。医保支付的药品、耗材应当按规定在医疗保障行政部门规定的平台上采购，并真实记录“进、销、存”等情况。"},{"i":18,"n":"第十八条","txt":"定点医疗机构应当严格执行医疗保障行政部门制定的医药价格政策。"},{"i":19,"n":"第十九条","txt":"定点医疗机构应当参加由医疗保障行政部门或经办机构组织的宣传和培训。 定点医疗机构应当组织开展医疗保障基金相关制度、政策的培训，定期检查本单位医疗保障基金使用情况，及时纠正医疗保障基金使用不规范的行为。"},{"i":20,"n":"第二十条","txt":"定点医疗机构在显著位置悬挂统一样式的定点医疗机构标识。"},{"i":21,"n":"第二十一条","txt":"定点医疗机构应按要求及时向统筹地区经办机构报送医疗保障基金结算清单等信息，包括疾病诊断及手术操作，药品、医用耗材、医疗服务项目费用结算明细，医师、护士等信息，并对其真实性负责。定点医疗机构应当按要求如实向统筹地区经办机构报送药品、耗材的采购价格和数量。 定点医疗机构应向医疗保障部门报告医疗保障基金使用监督管理及协议管理所需信息，向社会公开医药费用、费用结构等信息。"},{"i":22,"n":"第二十二条","txt":"定点医疗机构应当配合经办机构开展医保费用审核、稽核检查、绩效考核等工作，接受医疗保障行政部门的监督检查，并按规定提供相关材料。"},{"i":23,"n":"第二十三条","txt":"定点医疗机构应当优化医保结算流程，为参保人员提供便捷的医疗服务，按规定进行医保费用直接结算，提供费用结算单据和相关资料。为符合规定的参保人员提供转诊转院服务。参保人员根据有关规定可以在定点医疗机构购药或凭处方到定点零售药店购药。"},{"i":24,"n":"第二十四条","txt":"定点医疗机构应当做好与医保有关的信息系统安全保障工作，遵守数据安全有关制度，保护参保人员隐私。定点医疗机构重新安装信息系统时，应当保持信息系统技术接口标准与医保信息系统有效对接，并按规定及时全面准确向医保信息系统传送医保结算和审核所需的有关数据。"},{"i":25,"n":"第二十五条","txt":"经办机构有权掌握定点医疗机构运行管理情况，从定点医疗机构获得医保费用稽查审核、绩效考核和财务记账等所需要的信息数据等资料。定点医疗机构实行属地管理，经办机构对属地定点医疗机构为本地和异地参保人员提供的医疗服务承担管理服务职责。"},{"i":26,"n":"第二十六条","txt":"经办机构应当完善定点申请、组织评估和协议签订、协议履行、协议变更和解除等管理流程，制定经办规程，为定点医疗机构和参保人员提供优质高效的经办服务。"},{"i":27,"n":"第二十七条","txt":"经办机构应做好对定点医疗机构医保政策、管理制度、支付政策、操作流程的宣传培训，提供医疗保障咨询、查询服务。"},{"i":28,"n":"第二十八条","txt":"经办机构应当落实医保支付政策，加强医疗保障基金管理。"},{"i":29,"n":"第二十九条","txt":"经办机构应当建立完善的内部控制制度，明确对定点医疗机构申报费用的审核、结算、拨付、稽核等岗位责任及风险防控机制。完善重大医保费用支出集体决策制度。"},{"i":30,"n":"第三十条","txt":"经办机构应当加强医疗保障基金支出管理，通过智能审核、实时监控、现场检查等方式及时审核医疗费用。对定点医疗机构进行定期和不定期稽查审核。按协议约定及时足额向定点医疗机构拨付医保费用，原则上应当在定点医疗机构申报后30个工作日内拨付符合规定的医保费用。"},{"i":31,"n":"第三十一条","txt":"有条件的统筹地区经办机构可以按国家规定向定点医疗机构预付一部分医保资金，缓解其资金运行压力。在突发疫情等紧急情况时，可以按国家规定预拨专项资金。"},{"i":32,"n":"第三十二条","txt":"定点医疗机构违规申报费用，经审查核实的，经办机构不予支付。"},{"i":33,"n":"第三十三条","txt":"经办机构应当依法依规支付参保人员在定点医疗机构发生的医疗费用，为参保人员提供医保政策咨询。除急诊和抢救外，参保人员在非定点医疗机构就医发生的费用医疗保障基金不予支付。"},{"i":34,"n":"第三十四条","txt":"经办机构向社会公开医保信息系统数据集和接口标准。定点医疗机构自主选择与医保对接的有关信息系统的运行和维护供应商。经办机构不得以任何名义收取任何费用及指定供应商。"},{"i":35,"n":"第三十五条","txt":"经办机构应遵守数据安全有关制度，保护参保人员隐私，确保医疗保障基金安全。"},{"i":36,"n":"第三十六条","txt":"经办机构或其委托符合规定的第三方机构，对定点医疗机构开展绩效考核，建立动态管理机制。考核结果与年终清算、质量保证金退还、协议续签等挂钩。绩效考核办法由国家医疗保障部门制定，省级医疗保障部门可制定具体考核细则，经办机构负责组织实施。"},{"i":37,"n":"第三十七条","txt":"对于定点医疗机构结算周期内未超过总额控制指标的医疗费用，经办机构应根据协议按时足额拨付。对定点医疗机构因参保人员就医数量大幅增加等形成的合理超支给予适当补偿。"},{"i":38,"n":"第三十八条","txt":"经办机构发现定点医疗机构存在违反协议约定情形的，可按协议约定相应采取以下处理方式： （一）约谈医疗机构法定代表人、主要负责人或实际控制人； （二）暂停或不予拨付费用； （三）不予支付或追回已支付的医保费用； （四）要求定点医疗机构按照协议约定支付违约金； （五）中止相关责任人员或者所在部门涉及医疗保障基金使用的医疗服务； （六）中止或解除医保协议。"},{"i":39,"n":"第三十九条","txt":"经办机构违反医保协议的，定点医疗机构有权要求纠正或者提请医疗保障行政部门协调处理、督促整改，也可以依法申请行政复议或者提起行政诉讼。 医疗保障行政部门发现经办机构存在违反医保协议的，可视情节相应采取以下处理方式：约谈主要负责人、限期整改、通报批评，对相关责任人员依法依规给予处分。 医疗保障行政部门发现经办机构违反相关法律法规和规章的，依法依规进行处理。"},{"i":40,"n":"第四十条","txt":"定点医疗机构的名称、法定代表人、主要负责人或实际控制人、注册地址、银行账户、诊疗科目、机构规模、机构性质、等级和类别等重大信息变更时，应自有关部门批准之日起30个工作日内向统筹地区经办机构提出变更申请。其他一般信息变更应及时书面告知。"},{"i":41,"n":"第四十一条","txt":"续签应由定点医疗机构于医保协议期满前3个月向经办机构提出申请或由经办机构统一组织。统筹地区经办机构与定点医疗机构就医保协议续签事宜进行协商谈判，双方根据医保协议履行情况和绩效考核情况等决定是否续签。协商一致的，可续签医保协议；未达成一致的，医保协议到期后自动终止。 对于绩效考核结果好的定点医疗机构可以采取固定医保协议和年度医保协议相结合的方式，固定医保协议相对不变，年度医保协议每年根据具体情况调整，简化签约手续。"},{"i":42,"n":"第四十二条","txt":"医保协议中止是指经办机构与定点医疗机构暂停履行医保协议约定，中止期间发生的医保费用不予结算。中止期结束，未超过医保协议有效期的，医保协议可继续履行；超过医保协议有效期的，医保协议终止。 定点医疗机构可提出中止医保协议申请，经经办机构同意，可以中止医保协议但中止时间原则上不得超过180日，定点医疗机构在医保协议中止超过180日仍未提出继续履行医保协议申请的，原则上医保协议自动终止。定点医疗机构有下列情形之一的，经办机构应中止医保协议： （一）根据日常检查和绩效考核，发现对医疗保障基金安全和参保人员权益可能造成重大风险的； （二）未按规定向经办机构及医疗保障行政部门提供有关数据或提供数据不真实的； （三）根据医保协议约定应当中止医保协议的； （四）法律法规和规章规定的应当中止的其他情形。"},{"i":43,"n":"第四十三条","txt":"医保协议解除是指经办机构与定点医疗机构之间的医保协议解除，协议关系不再存续，协议解除后产生的医药费用，医疗保障基金不再结算。定点医疗机构有以下情形之一的，经办机构应解除医保协议，并向社会公布解除医保协议的医疗机构名单： （一）医保协议有效期内累计2次及以上被中止医保协议或中止医保协议期间未按要求整改或整改不到位的； （二）以弄虚作假等不正当手段申请取得定点的； （三）经医疗保障部门和其他有关部门查实有欺诈骗保行为的； （四）为非定点医疗机构或处于中止医保协议期间的医疗机构提供医保费用结算的； （五）拒绝、阻挠或不配合医疗保障部门开展智能审核、绩效考核、监督检查等，情节恶劣的； （六）被发现重大信息发生变更但未办理重大信息变更的； （七）定点医疗机构停业或歇业后未按规定向经办机构报告的； （八）医疗保障行政部门或其他有关部门在行政执法中，发现定点医疗机构存在重大违法违规行为且可能造成医疗"},{"i":44,"n":"第四十四条","txt":"定点医疗机构请求中止、解除医保协议或不再续签医保协议的，应提前3个月向经办机构提出申请。公立医疗机构不得主动提出中止或解除医保协议。 医疗机构所在地的地市级及以上统筹地区经办机构与定点医疗机构中止或解除医保协议，该医疗机构在其他统筹区的医保协议也同时中止或解除。"},{"i":45,"n":"第四十五条","txt":"定点医疗机构的部分人员或科室有违反协议管理要求的，可对该人员或科室中止或终止医保结算。"},{"i":46,"n":"第四十六条","txt":"医疗机构与统筹地区经办机构就医保协议签订、履行、变更和解除发生争议的，可以自行协商解决或者请求同级医疗保障行政部门协调处理，也可以依法提起行政复议或行政诉讼。"},{"i":47,"n":"第四十七条","txt":"医疗保障行政部门对定点申请、申请受理、专业评估、协议订立、协议履行和解除等进行监督，对经办机构的内部控制制度建设、医保费用的审核和拨付等进行指导和监督。 医疗保障行政部门依法依规通过实地检查、抽查、智能监控、大数据分析等方式对定点医疗机构的协议履行情况、医疗保障基金使用情况、医疗服务行为、购买涉及医疗保障基金使用的第三方服务等进行监督。"},{"i":48,"n":"第四十八条","txt":"医疗保障行政部门和经办机构应拓宽监督途径、创新监督方式，通过满意度调查、第三方评价、聘请社会监督员等方式对定点医疗机构进行社会监督，畅通举报投诉渠道，及时发现问题并进行处理。"},{"i":49,"n":"第四十九条","txt":"经办机构发现违约行为，应当及时按照协议处理。 经办机构作出中止相关责任人员或者所在部门涉及医疗保障基金使用的医药服务、中止和解除医保协议等处理时，要及时报告同级医疗保障行政部门。 医疗保障行政部门发现定点医疗机构存在违约情形的，应当及时责令经办机构按照医保协议处理，经办机构应当及时按照医保协议处理。 医疗保障行政部门依法查处违法违规行为时，认为经办机构移交相关违法线索事实不清的，可组织补充调查或要求经办机构补充材料。"},{"i":50,"n":"第五十条","txt":"职工基本医疗保险、城乡居民基本医疗保险、生育保险、医疗救助、居民大病保险等医疗保障定点管理工作按照本办法执行。"},{"i":51,"n":"第五十一条","txt":"本办法中的经办机构是具有法定授权，实施医疗保障管理服务的职能机构，是医疗保障经办的主体。 定点医疗机构是指自愿与统筹地区经办机构签订医保协议，为参保人员提供医疗服务的医疗机构。 医保协议是指由经办机构与医疗机构经协商谈判而签订的，用于规范医疗服务行为以及明确双方权利、义务及责任等内容的协议。"},{"i":52,"n":"第五十二条","txt":"国务院医疗保障行政部门制作并定期修订医保协议范本，国家医疗保障经办机构制定经办规程并指导各地加强和完善医保协议管理。地市级及以上的医疗保障行政部门及经办机构在此基础上，可根据实际情况分别细化制定本地区的医保协议范本及经办规程。医保协议内容应与法律、法规、规章和医疗保障政策调整变化相一致，医疗保障行政部门调整医保协议内容时，应征求相关定点医疗机构意见。"},{"i":53,"n":"第五十三条","txt":"本办法由国务院医疗保障行政部门负责解释，自2021年2月1日起施行。"}],"shangyongmimayingyonganquanxingpingguguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范商用密码应用安全性评估工作，保障网络与信息安全，维护国家安全和社会公共利益，保护公民、法人和其他组织的合法权益，根据《中华人民共和国密码法》、《商用密码管理条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称商用密码应用安全性评估，是指按照有关法律法规和标准规范，对网络与信息系统使用商用密码技术、产品和服务的合规性、正确性、有效性进行检测分析和评估验证的活动。"},{"i":3,"n":"第三条","txt":"国家密码管理局负责管理全国的商用密码应用安全性评估工作。县级以上地方各级密码管理部门负责管理本行政区域的商用密码应用安全性评估工作。 国家机关和涉及商用密码工作的单位在其职责范围内负责指导、监督本机关、本单位或者本系统的商用密码应用安全性评估工作。"},{"i":4,"n":"第四条","txt":"从事商用密码应用安全性评估活动，向社会出具具有证明作用的商用密码应用安全性评估数据、结果的机构，应当经国家密码管理局认定，依法取得商用密码检测机构资质。"},{"i":5,"n":"第五条","txt":"国家密码管理局支持商用密码应用安全性评估技术、标准、工具创新，完善商用密码应用安全性评估标准体系，鼓励设立商用密码应用安全性评估行业组织，加强行业自律，维护行业秩序。"},{"i":6,"n":"第六条","txt":"法律、行政法规和国家有关规定要求使用商用密码进行保护的网络与信息系统（以下简称重要网络与信息系统），其运营者应当使用商用密码进行保护，制定商用密码应用方案，配备必要的资金和专业人员，同步规划、同步建设、同步运行商用密码保障系统，并定期开展商用密码应用安全性评估。"},{"i":7,"n":"第七条","txt":"重要网络与信息系统规划阶段，其运营者应当依照相关法律法规和标准规范，根据商用密码应用需求，制定商用密码应用方案，规划商用密码保障系统。 重要网络与信息系统的运营者应当自行或者委托商用密码检测机构对商用密码应用方案进行商用密码应用安全性评估。商用密码应用方案未通过商用密码应用安全性评估的，不得作为商用密码保障系统的建设依据。"},{"i":8,"n":"第八条","txt":"重要网络与信息系统建设阶段，其运营者应当按照通过商用密码应用安全性评估的商用密码应用方案组织实施，落实商用密码安全防护措施，建设商用密码保障系统。 重要网络与信息系统运行前，其运营者应当自行或者委托商用密码检测机构开展商用密码应用安全性评估。网络与信息系统未通过商用密码应用安全性评估的，运营者应当进行改造，改造期间不得投入运行。"},{"i":9,"n":"第九条","txt":"重要网络与信息系统建成运行后，其运营者应当自行或者委托商用密码检测机构每年至少开展一次商用密码应用安全性评估，确保商用密码保障系统正确有效运行。未通过商用密码应用安全性评估的，运营者应当进行改造，并在改造期间采取必要措施保证网络与信息系统运行安全。"},{"i":10,"n":"第十条","txt":"对商用密码应用方案开展商用密码应用安全性评估，应当包括以下内容： （一）考量商用密码应用需求的全面性、合理性和针对性，对照相关标准规范选取适用指标的准确性，以及不适用指标论证的充分性； （二）分析商用密码应用流程和机制是否具备可实施性、商用密码保护措施是否达到相应的商用密码应用要求、相关描述是否详尽； （三）论证商用密码技术、产品和服务选用的合规性，密钥管理的安全性，以及使用商用密码解决安全风险的科学性； （四）编制形成商用密码应用安全性评估报告。"},{"i":11,"n":"第十一条","txt":"对建设完成的网络与信息系统开展商用密码应用安全性评估，应当包括以下内容： （一）对照商用密码应用方案，了解网络与信息系统基本情况，准确划定评估范围； （二）确定评估指标及评估对象，论证编制商用密码应用安全性评估实施方案； （三）依据商用密码应用安全性评估实施方案，开展现场评估，做好数据采集和信息汇总，研判商用密码保障系统配置及运行情况； （四）根据客观凭据逐项对评估指标进行判定，编制形成商用密码应用安全性评估报告。"},{"i":12,"n":"第十二条","txt":"运营者开展商用密码应用安全性评估活动，应当遵守法律法规、标准规范要求，遵循客观实际、科学公正、诚实信用原则。委托商用密码检测机构开展商用密码应用安全性评估的，不得对评估结果施加不当影响，并应当提供以下支持： （一）对网络与信息系统的重要数据进行备份； （二）提供完整有效的网络与信息系统设备清单和网络拓扑； （三）提供详细的网络与信息系统商用密码应用方案、密码相关管理制度和密码配置、运行、维护记录； （四）提供商用密码产品管理入口、网络交换设备接入端口等相关信息、数据接入分析条件，并配合进行数据采集； （五）安排网络与信息系统相关网络管理员、系统管理员、密钥管理员、密码安全审计员、密码操作员等做好配合； （六）其他需要配合的事项。"},{"i":13,"n":"第十三条","txt":"自行开展商用密码应用安全性评估的网络与信息系统，其运营者应当符合以下要求： （一）具有与开展商用密码应用安全性评估活动相适应的设备设施； （二）具有与开展商用密码应用安全性评估活动相适应的项目管理、质量管理、人员管理、档案管理、安全保密管理等规章制度； （三）具有与开展商用密码应用安全性评估活动相适应的专业人员； （四）具有与开展商用密码应用安全性评估活动相适应的专业能力。 自行开展商用密码应用安全性评估形成的商用密码应用安全性评估报告，应当符合相关国家标准、行业标准和有关规定的要求，由本单位密码或者网络安全负责人签字确认并加盖本单位公章。 运营者应当对商用密码应用安全性评估原始记录和商用密码应用安全性评估报告归档留存，保证其具有可追溯性。商用密码应用安全性评估原始记录和商用密码应用安全性评估报告的保存期限不得少于6年。"},{"i":14,"n":"第十四条","txt":"重要网络与信息系统的运营者应当在商用密码应用安全性评估报告形成后30日内，将评估报告和相关工作情况按照国家有关规定报送国家密码管理局或者网络与信息系统所在地省、自治区、直辖市密码管理部门备案。 国家密码管理局或者省、自治区、直辖市密码管理部门对商用密码应用安全性评估结果备案材料进行形式审查。形式审查未通过的，相关运营者应当重新提交备案材料。 国家密码管理局可以对商用密码应用安全性评估结果进行抽样检查。抽样检查不合格的，相关运营者应当重新开展商用密码应用安全性评估。 省、自治区、直辖市密码管理部门应当按季度向国家密码管理局报送本地区商用密码应用安全性评估工作开展情况。"},{"i":15,"n":"第十五条","txt":"运营者发现密码相关重大安全事件、重大密码安全隐患或者特殊紧急情况的，应当及时向国家密码管理局或者网络与信息系统所在地省、自治区、直辖市密码管理部门报告，并启动应急处置方案，必要时开展商用密码应用安全性评估。"},{"i":16,"n":"第十六条","txt":"县级以上地方各级密码管理部门、国家机关和涉及商用密码工作的单位可以根据工作需要，对本地区、本机关、本单位或者本系统的重要网络与信息系统商用密码应用安全性评估情况开展专项检查。"},{"i":17,"n":"第十七条","txt":"重要网络与信息系统的运营者违反《中华人民共和国密码法》、《商用密码管理条例》和本办法规定，有下列情形之一的，由密码管理部门责令改正，给予警告；拒不改正或者有其他严重情节的，处10万元以上100万元以下罚款，对直接负责的主管人员处1万元以上10万元以下罚款： （一）重要网络与信息系统规划阶段，未对商用密码应用方案进行商用密码应用安全性评估的； （二）重要网络与信息系统建设阶段，未按照通过商用密码应用安全性评估的商用密码应用方案建设商用密码保障系统的； （三）重要网络与信息系统运行前，未开展商用密码应用安全性评估的； （四）重要网络与信息系统运行前，未通过商用密码应用安全性评估且未进行改造的； （五）重要网络与信息系统建成运行后，未定期开展商用密码应用安全性评估的； （六）重要网络与信息系统建成运行后，未通过定期开展的商用密码应用安全性评估且未进行改造的； （七）违反法律法规、标准规范要求"},{"i":18,"n":"第十八条","txt":"重要网络与信息系统的运营者违反本办法规定，有下列情形之一的，由密码管理部门责令改正；逾期未改正或者改正后仍不符合要求的，处1万元以上10万元以下罚款，对直接负责的主管人员处5000元以上5万元以下罚款： （一）对商用密码应用安全性评估结果施加不当影响的； （二）未为商用密码应用安全性评估活动提供必要支持的； （三）未按照要求进行商用密码应用安全性评估结果备案的。"},{"i":19,"n":"第十九条","txt":"从事商用密码应用安全性评估监督管理工作的人员滥用职权、玩忽职守、徇私舞弊，或者泄露、非法向他人提供在履行职责中知悉的商业秘密、个人隐私、举报人信息的，依法给予处分。"},{"i":20,"n":"第二十条","txt":"本办法施行前正在建设的重要网络与信息系统，其运营者应当加强商用密码应用方案编制论证，建设完善商用密码保障系统，并按照本办法第八条规定开展商用密码应用安全性评估。 本办法施行前已经投入运行的重要网络与信息系统，其运营者应当按照本办法第九条规定开展商用密码应用安全性评估。"},{"i":21,"n":"第二十一条","txt":"本办法自2023年11月1日起施行。"}],"shangyongmimajiancejigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强商用密码检测机构管理，规范商用密码检测活动，根据《中华人民共和国密码法》、《商用密码管理条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"商用密码检测机构的资质认定和监督管理适用本办法。"},{"i":3,"n":"第三条","txt":"从事商用密码产品检测、网络与信息系统商用密码应用安全性评估等商用密码检测活动，向社会出具具有证明作用的数据、结果的机构，应当经国家密码管理局认定，依法取得商用密码检测机构资质。"},{"i":4,"n":"第四条","txt":"国家密码管理局负责全国商用密码检测机构的资质认定和监督管理。县级以上地方各级密码管理部门负责本行政区域内商用密码检测机构的监督管理。"},{"i":5,"n":"第五条","txt":"商用密码检测机构应当在资质认定业务范围内从事商用密码检测活动。国家密码管理局制定并公布商用密码检测机构资质认定基本规范和商用密码检测机构资质认定业务范围。"},{"i":6,"n":"第六条","txt":"取得商用密码检测机构资质，应当符合下列条件： （一）具有法人资格； （二）具有与从事商用密码检测活动相适应的资金； （三）成立2年以上，从事网络安全检测评估领域相关工作1年以上，无重大违法或者不良信用记录； （四）具有与从事商用密码检测活动相适应的场所； （五）具有与从事商用密码检测活动相适应的设备设施； （六）具有保证商用密码检测活动独立、公正、科学、诚信的管理体系； （七）具有与从事商用密码检测活动相适应的专业人员； （八）具有与从事商用密码检测活动相适应的专业能力。 外商投资企业法人申请商用密码检测机构资质，除符合上述条件外，还应当符合我国外商投资有关法律法规的规定。"},{"i":7,"n":"第七条","txt":"申请商用密码检测机构资质，应当向国家密码管理局提出书面申请，向国家密码管理局委托进行受理的省、自治区、直辖市密码管理部门提交《商用密码检测机构资质申请表》及以下材料，并对其真实性负责： （一）法人资格证书； （二）资本结构和股权情况； （三）无重大违法或者不良信用记录、不从事可能影响商用密码检测公平公正性活动的承诺； （四）工作场所等固定资产产权证书或者租赁合同； （五）工作环境和设备设施配置情况； （六）项目管理、质量管理、人员管理、档案管理、安全保密管理等管理体系建立情况； （七）法定代表人、最高管理者、技术负责人、质量负责人、授权签字人以及专业人员情况； （八）申请人认为需要补充的其他材料。 受国家密码管理局委托进行受理的省、自治区、直辖市密码管理部门自收到申请材料之日起5个工作日内，对申请材料进行形式审查，根据下列情况分别作出处理：申请材料内容齐全、符合规定形式的，应当受理行政"},{"i":8,"n":"第八条","txt":"国家密码管理局应当自行政许可申请受理之日起20个工作日内，依据商用密码检测机构资质认定基本规范的要求，对申请进行审查，并依法作出是否准予许可的书面决定。 需要对申请人进行技术评审的，技术评审所需时间不计算在本条规定的期限内。国家密码管理局应当将所需时间书面告知申请人。"},{"i":9,"n":"第九条","txt":"国家密码管理局根据技术评审需要和专业要求，可以委托专业技术评价机构实施技术评审。 技术评审包括专业人员能力考核，场所、设备设施、管理体系建设实地查勘，检测能力考核等。 专业技术评价机构应当严格按照商用密码检测机构资质认定基本规范开展技术评审活动，对技术评审结论的真实性、符合性负责，并承担相应法律责任。国家密码管理局应当对技术评审活动进行监督，建立责任追究机制。"},{"i":10,"n":"第十条","txt":"申请人有下列情形之一的，国家密码管理局应当终止审查： （一）隐瞒有关情况或者提供虚假材料的； （二）采取贿赂、请托等不正当手段，影响审查工作公平公正进行的； （三）无正当理由拒绝接受审查的； （四）违反商用密码检测机构从业要求的。"},{"i":11,"n":"第十一条","txt":"准予许可的，国家密码管理局向申请人颁发《商用密码检测机构资质证书》，并公布取得资质证书的商用密码检测机构名录。 有下列情形之一的，国家密码管理局应当出具不予行政许可决定书，说明理由并告知申请人相关权利： （一）终止审查的； （二）审查不合格的； （三）法律法规规定的不予许可的其他情形。"},{"i":12,"n":"第十二条","txt":"《商用密码检测机构资质证书》有效期5年，内容包括：获证机构名称、统一社会信用代码、注册地址、证书编号、有效期限、资质认定业务范围、发证机关和发证日期。 《商用密码检测机构资质证书》有效期届满需要延续的，应当在有效期届满3个月前向国家密码管理局提出书面申请。国家密码管理局根据申请人的实际情况，采取书面或者现场形式开展审查，在《商用密码检测机构资质证书》有效期届满前作出是否准予延续的决定。 禁止转让、出租、出借、伪造、变造、冒用、租借《商用密码检测机构资质证书》。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的，商用密码检测机构应当自变更之日起30日内向国家密码管理局申请办理变更手续： （一）机构名称、注册地址、法人性质发生变更的； （二）法定代表人、最高管理者、技术负责人、质量负责人、授权签字人发生变更的； （三）资质认定业务范围发生变更的； （四）依法需要办理变更的其他事项。 商用密码检测机构发生变更的事项影响其符合资质认定条件和要求的，国家密码管理局根据申请人的实际情况，采取书面或者现场形式开展审查。需要进行技术评审的，依照本办法第九条规定对其开展技术评审。"},{"i":14,"n":"第十四条","txt":"商用密码检测机构有下列情形之一的，国家密码管理局应当依法注销其商用密码检测机构资质： （一）《商用密码检测机构资质证书》有效期届满，未申请延续或者依法不予延续批准的； （二）申请注销商用密码检测机构资质的； （三）被依法撤销、吊销商用密码检测机构资质的； （四）依法终止的； （五）因法人性质变更、改制、分立或者合并等原因发生变化，或者发生其他影响其符合资质认定条件和要求的变更事项，经审查发现不符合资质认定条件和要求的； （六）资质认定业务范围被全部取消的； （七）法律法规规定的应当注销商用密码检测机构资质的其他情形。"},{"i":15,"n":"第十五条","txt":"商用密码检测机构及相关从业人员应当按照法律、行政法规和商用密码检测技术规范、规则，在批准范围内独立、公正、科学、诚信地开展商用密码检测，对出具的检测数据、结果负责，尊重知识产权，恪守职业道德，承担社会责任，保守在工作中知悉的国家秘密、商业秘密和个人隐私。"},{"i":16,"n":"第十六条","txt":"商用密码检测机构应当保证其基本条件和技术能力能够持续符合资质认定条件和要求，并确保管理体系有效运行。"},{"i":17,"n":"第十七条","txt":"商用密码检测机构应当遵守以下从业要求： （一）加强对本机构人员的监督管理，经常性组织开展安全保密教育和业务培训；本机构从事检测活动的专业人员每年接受商用密码教育培训的时长不得少于40学时，相关情况应当记录留存； （二）本机构及关联方不得从事商用密码产品生产、销售（检测工具除外），信息系统或者商用密码保障系统集成、运营，电子认证服务，电子政务电子认证服务，或者其他可能影响商用密码检测公平公正性的活动； （三）不得同时聘用正在其他商用密码检测机构从业的人员，或者存在其他恶意竞争、扰乱市场秩序的情形； （四）不得以单独出租设备设施或者委派人员等方式承担业务，所承担的业务不得分包、转包； （五）不得以任何方式推荐或者限定被检测单位购买使用特定主体生产或者提供的商用密码产品或者服务； （六）独立于出具的检测数据、结果、报告所涉及的利益相关各方，不受任何可能干扰技术判断因素的影响； （七）使用符合"},{"i":18,"n":"第十八条","txt":"商用密码检测机构出具的检测报告，应当符合相关国家标准、行业标准和有关规定的要求，保证内容真实、客观、准确、完整。商用密码检测机构对其出具的检测报告负责，并承担相应的法律责任。 商用密码检测机构应当指定授权签字人在其业务能力范围内签字确认本机构出具的检测报告，并加盖机构公章或者专用章。授权签字人应当系统掌握商用密码管理政策和专业知识，具备密码或者网络安全领域高级技术职称或者同等专业水平。"},{"i":19,"n":"第十九条","txt":"商用密码检测机构应当对检测原始记录和检测报告归档留存，保证其具有可追溯性。检测原始记录和检测报告的保存期限不得少于6年。 从事商用密码产品检测的商用密码检测机构应当按照相关标准规范的要求，对检测样品和相关数据信息进行妥善管理。商用密码检测机构资质被注销的，应当对检测样品和相关数据信息进行妥善处理。"},{"i":20,"n":"第二十条","txt":"商用密码检测机构应当于每年1月15日前通过所在地省、自治区、直辖市密码管理部门向国家密码管理局报送上一年度工作报告以及相关统计数据，包括持续符合资质认定条件和要求、遵守从业规范、开展检测活动、实施标准等情况。"},{"i":21,"n":"第二十一条","txt":"商用密码检测机构不得有以下出具虚假或者失实检测数据、结果、报告的行为： （一）未经检测，直接出具检测数据、结果、报告的； （二）篡改、编造原始数据、记录，出具检测数据、结果、报告的； （三）伪造检测报告和原始记录签名，或者非授权签字人签发检测报告的； （四）漏检关键项目、干扰检测过程或者改动关键项目的检测方法，造成检测数据、结果、报告失实的； （五）其他出具虚假或者失实检测数据、结果、报告的行为。"},{"i":22,"n":"第二十二条","txt":"密码管理部门对商用密码检测机构依法开展监督检查，可以行使下列职权： （一）进入检测活动场所实施现场检查； （二）向商用密码检测机构、委托人等有关单位及人员调查、了解有关情况或者验证相关检测活动； （三）查阅、复制有关合同、票据、账簿以及检测活动中形成的检测数据、结果、报告等有关材料。 国家密码管理局根据工作需要，可以行使下列职权： （一）组织商用密码检测机构检测能力验证； （二）对商用密码检测机构出具的检测数据、结果、报告等有关材料进行抽样检查。 密码管理部门和有关部门及其工作人员不得要求商用密码科研、生产、销售、服务、进出口等单位和商用密码检测、认证机构向其披露源代码等密码相关专有信息，并对其在履行职责中知悉的商业秘密和个人隐私严格保密，不得泄露或者非法向他人提供。"},{"i":23,"n":"第二十三条","txt":"商用密码检测机构应当积极配合密码管理部门的监督检查，按照要求参加检测能力验证和抽样检查，并如实提供相关材料和信息。检测能力验证或者抽样检查结果不合格的，应当开展为期不少于6个月的整改，整改期间不得开展相应业务范围的商用密码检测活动。商用密码检测机构整改结束后，应当经国家密码管理局组织验收合格，方可恢复开展相应业务范围的商用密码检测活动；经整改仍不能满足相应业务范围的资质认定条件和要求的，取消其相应业务范围的资质认定，直至注销其商用密码检测机构资质。"},{"i":24,"n":"第二十四条","txt":"以欺骗、贿赂等不正当手段取得商用密码检测机构资质的，国家密码管理局应当依法撤销商用密码检测机构资质。该机构在3年内不得再次申请商用密码检测机构资质。 申请商用密码检测机构资质时隐瞒有关情况或者提供虚假材料的，国家密码管理局不予受理或者不予许可。该机构在1年内不得再次申请商用密码检测机构资质。"},{"i":25,"n":"第二十五条","txt":"商用密码检测机构违反《中华人民共和国密码法》、《商用密码管理条例》和本办法规定，有下列情形之一的，由密码管理部门责令改正或者停止违法行为，给予警告，没收违法所得；违法所得30万元以上的，可以并处违法所得1倍以上3倍以下罚款；没有违法所得或者违法所得不足30万元的，可以并处10万元以上30万元以下罚款；情节严重的，由国家密码管理局吊销其商用密码检测机构资质： （一）超出批准范围开展商用密码检测的； （二）转让、出租、出借、伪造、变造、冒用、租借《商用密码检测机构资质证书》的； （三）本机构及关联方从事商用密码产品生产、销售（检测工具除外），信息系统或者商用密码保障系统集成、运营，电子认证服务，电子政务电子认证服务，或者其他可能影响商用密码检测公平公正性的活动的； （四）同时聘用正在其他商用密码检测机构从业的人员或者存在其他恶意竞争、扰乱市场秩序情形的； （五）以单独出租设备设施或者委派人"},{"i":26,"n":"第二十六条","txt":"商用密码检测机构违反本办法规定，有下列情形之一的，由密码管理部门责令改正；逾期未改正或者改正后仍不符合要求的，处1万元以上10万元以下罚款： （一）未按照要求申请办理变更手续的； （二）未按照要求开展安全保密教育和业务培训的； （三）使用不符合国家密码管理要求的设备设施的； （四）出具未经授权签字人签字确认的检测报告，授权签字人超出其业务能力范围签发检测报告，或者未在检测报告上加盖机构公章或者专用章的； （五）未按照要求保存检测原始记录和检测报告，或者未按照要求妥善管理检测样品和相关数据信息的。"},{"i":27,"n":"第二十七条","txt":"县级以上地方各级密码管理部门应当依法公开监督检查结果，将商用密码检测机构受到的行政处罚等信息纳入国家企业信用信息公示系统等平台，并定期将年度商用密码检测机构监督检查结果等信息逐级报至国家密码管理局。"},{"i":28,"n":"第二十八条","txt":"从事商用密码检测机构监督管理工作的人员滥用职权、玩忽职守、徇私舞弊，或者泄露、非法向他人提供在履行职责中知悉的商业秘密、个人隐私、举报人信息的，依法给予处分。"},{"i":29,"n":"第二十九条","txt":"本办法自2023年11月1日起施行。"}],"guojiayuanzinengjigoushangwubuwaijiaobuhaiguanzong2a94f0":[],"guojiaguojifazhanhezuoshuxingzhengchufashishibanfa":[{"i":1,"n":"第一条","txt":"为规范国家国际发展合作署（以下简称国际发展合作署）行政处罚的实施，保障行政处罚的合法性和有效性，保护公民、法人和其他组织的合法权益，维护公共利益，根据《中华人民共和国行政处罚法》，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织违反行政管理秩序的行为，依据法律、行政法规或者部门规章规定，应当由国际发展合作署给予行政处罚的，适用本办法。"},{"i":3,"n":"第三条","txt":"行政处罚由国际发展合作署在法定职权范围内实施，国际发展合作署内设机构不得以自身名义实施行政处罚。 没有法律、行政法规或者部门规章的规定，国际发展合作署不得委托其他组织实施行政处罚。"},{"i":4,"n":"第四条","txt":"国际发展合作署实施行政处罚，依法实行回避制度。执法人员与当事人有直接利害关系，可能影响公正执法的，应当回避。"},{"i":5,"n":"第五条","txt":"国际发展合作署对行政处罚实行案件调查与案件审理分离的制度。"},{"i":6,"n":"第六条","txt":"国际发展合作署设立行政处罚委员会，作为国际发展合作署行政处罚案件的审理机构。 行政处罚委员会通过召开审理会的方式审理行政处罚案件。"},{"i":7,"n":"第七条","txt":"国际发展合作署法制机构（以下简称法制机构）是国际发展合作署行政处罚委员会的办事机构，负责组织行政处罚委员会的审理会，听取当事人陈述、申辩，制作相关法律文书，承担行政处罚委员会的日常工作。"},{"i":8,"n":"第八条","txt":"国际发展合作署行政处罚案件的调查机关是案件所涉及的业务部门。必要时，该业务部门可以会同其他相关部门共同调查案件。"},{"i":9,"n":"第九条","txt":"国际发展合作署业务部门发现公民、法人或者其他组织有违反行政管理秩序的行为时，应当及时展开调查工作。"},{"i":10,"n":"第十条","txt":"调查机关应当全面、客观、公正进行调查，收集有关证据。必要时，依照法律法规的规定，可以进行检查。"},{"i":11,"n":"第十一条","txt":"行政处罚案件调查终结后，拟作出行政处罚的，调查机关应当制作《案件调查终结报告》及证据目录，连同证据材料一并移交行政处罚委员会。 《案件调查终结报告》应当写明案件的事实情况、调查过程、相关证据及违反的法律规定，并对案件处理及依据提出初步意见。"},{"i":12,"n":"第十二条","txt":"《案件调查终结报告》及证据等材料移交行政处罚委员会后，由法制机构进行初步审查。 初次从事行政处罚审查的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":13,"n":"第十三条","txt":"法制机构认为案件中事实不清的，可以要求调查机关作出解释、说明。必要时，法制机构可以直接向有关单位及人员调查、了解情况。"},{"i":14,"n":"第十四条","txt":"法制机构经审查，认为案件事实不清、证据不足的可以退回调查机关补充调查。"},{"i":15,"n":"第十五条","txt":"法制机构经审查，认为案件主要事实清楚、证据充分的，应当制作《案件审查报告》。 《案件审查报告》应当包括案件基本情况、违法事实、拟作出的行政处罚决定及依据。"},{"i":16,"n":"第十六条","txt":"法制机构应当及时将《案件调查终结报告》《案件审查报告》等材料提交行政处罚委员会，由行政处罚委员会召开审理会对案件进行审理。"},{"i":17,"n":"第十七条","txt":"行政处罚委员会对下列案件内容进行审理： （一）违法事实是否清楚； （二）证据是否确凿； （三）是否符合法定程序； （四）当事人陈述和申辩的理由是否成立； （五）应当适用的法律规定； （六）处罚种类和幅度。"},{"i":18,"n":"第十八条","txt":"行政处罚委员会应当召开审理会，经集体讨论、充分协商，根据案件不同情况，分别提出如下处理意见： （一）违法事实不成立的，不得给予行政处罚； （二）违法行为轻微、依法可以不予处罚的，不予行政处罚； （三）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，确定拟作出的行政处罚种类及幅度； （四）涉嫌构成犯罪的，依法移送司法机关。"},{"i":19,"n":"第十九条","txt":"法制机构应当按照行政处罚委员会审理会的处理意见制作行政处罚告知书，告知当事人拟作出行政处罚决定的事实、理由及依据，保障当事人的陈述权、申辩权。"},{"i":20,"n":"第二十条","txt":"当事人要求陈述、申辩的，应当在收到行政处罚告知书后七日内提出。法制机构经审查认为当事人的陈述、申辩意见可能影响行政处罚决定的，行政处罚委员会应当召开审理会对案件进行复审。"},{"i":21,"n":"第二十一条","txt":"法制机构应当按照行政处罚委员会审理会的处理意见制作行政处罚决定书。行政处罚决定书的内容应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）违反法律、法规或者部门规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）不服行政处罚决定，申请行政复议或者提起行政诉讼的途径和期限； （六）机关名称和作出决定的日期。"},{"i":22,"n":"第二十二条","txt":"行政处罚告知书和行政处罚决定书作出后，由法制机构在七日内依照民事诉讼法的有关规定送达当事人。"},{"i":23,"n":"第二十三条","txt":"当事人应当在行政处罚决定书确定的期限内履行行政处罚决定。逾期不履行行政处罚决定的，国际发展合作署可采取《中华人民共和国行政处罚法》规定的下列措施，予以执行： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款； （二）申请人民法院强制执行。"},{"i":24,"n":"第二十四条","txt":"除涉及国家秘密、商业秘密和个人隐私的内容以及法律法规禁止公开的信息外，行政处罚决定书在国际发展合作署网站上公布，备公众查询。"},{"i":25,"n":"第二十五条","txt":"本办法由国际发展合作署负责解释，自2020年5月1日起施行。"}],"guojiaguojifazhanhezuoshuxingzhengfuyishishibanfa":[{"i":1,"n":"第一条","txt":"为防止、纠正违法或者不当的具体行政行为，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政复议法》及其实施条例，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为国家国际发展合作署（以下简称国际发展合作署）的具体行政行为侵犯其合法权益，向国际发展合作署提出行政复议申请，国际发展合作署受理行政复议申请、作出行政复议决定，适用本办法。"},{"i":3,"n":"第三条","txt":"申请人对国际发展合作署的具体行政行为不服的，可以向国际发展合作署申请行政复议。"},{"i":4,"n":"第四条","txt":"申请人申请行政复议，应当提交书面行政复议申请书正本一份，并按照被申请人数目提交副本。复议申请书应当载明下列事项： （一）申请人的基本情况，包括：公民的姓名、性别、年龄、身份证号码、工作单位、住所、邮政编码、送达地址、联系方式；法人或者其他组织的名称、住所、邮政编码、统一社会信用代码和法定代表人或者主要负责人的姓名、职务； （二）被申请人的名称、地址； （三）行政复议具体要求、主要事实和理由（包括知道具体行政行为的时间）； （四）申请人的签名或者盖章； （五）申请行政复议的日期。 申请人为自然人的，应当提交居民身份证或者其他有效证件复印件；申请人为法人或者其他组织的，应当提交营业执照或者其他有效证件复印件、法定代表人或者主要负责人居民身份证或者其他有效证件复印件。 申请人委托代理人代为申请的，还应当提交授权委托书和代理人的居民身份证或者其他有效证件复印件。 行政复议申请书应当附具必要的证"},{"i":5,"n":"第五条","txt":"同申请行政复议的具体行政行为有利害关系的其他公民、法人或者其他组织要求作为第三人参加行政复议，应当以书面形式提出申请，经国际发展合作署审查同意，可以作为第三人参加行政复议。 行政复议期间，国际发展合作署法制机构（以下简称法制机构）认为申请人以外的公民、法人或者其他组织与被审查的具体行政行为有利害关系的，可以通知其作为第三人参加行政复议。"},{"i":6,"n":"第六条","txt":"申请人向国际发展合作署申请行政复议的，向法制机构办理申请手续。法制机构应当在申请书上注明收到日期，并由递交人签字确认。"},{"i":7,"n":"第七条","txt":"法制机构收到行政复议申请后，应当在五日内进行审查，并依法作出是否受理的决定。 行政复议申请符合《中华人民共和国行政复议法》及其实施条例规定，但不属于国际发展合作署受理范围的，告知申请人向有关行政复议机关提出。"},{"i":8,"n":"第八条","txt":"行政复议申请有下列情形之一的，不予受理： （一）申请复议的事项不属于《中华人民共和国行政复议法》第六条规定的复议范围的； （二）申请人不具备复议申请主体资格的； （三）申请人错列被申请人且拒绝变更的； （四）申请复议超过了法定的申请期限且无正当理由的； （五）申请人提起行政诉讼，法院已经受理或者尚未决定是否受理，又申请行政复议的； （六）申请人向其他有管辖权的行政机关申请复议，该复议机关已经依法受理的； （七）申请人撤回复议申请，无正当理由再行申请复议的； （八）行政复议申请不具备其他法定要件的。 法制机构应当制作不予受理行政复议申请决定书，以书面形式告知申请人。"},{"i":9,"n":"第九条","txt":"除依法决定不予受理或者告知申请人应当向其他复议机关申请复议的外，行政复议申请自法制机构收到之日起即为受理。 法制机构应当自行政复议申请受理之日起七日内，将行政复议申请书副本发送署内承办具体行政行为的业务部门。"},{"i":10,"n":"第十条","txt":"业务部门应当自收到申请书副本之日起十日内提出书面答复，并提交当初作出具体行政行为的证据、依据和其他有关材料。书面答复应当载明以下内容： （一）作出具体行政行为的事实依据和有关证据材料； （二）作出具体行政行为所依据的法律、法规、规章和规范性文件的具体条款及其内容； （三）作出答复的时间、联系人。 在行政复议过程中，业务部门不得自行向申请人和其他有关组织或者个人收集证据。"},{"i":11,"n":"第十一条","txt":"行政复议原则上采取书面审查的办法，如案情复杂、书面审查无法查明案情，也可以采取听取当事人意见、实地调查，或邀请专门机构进行检验、鉴定等方式。 法制机构在办理行政复议事项过程中可以向业务部门调取、查阅、复制相关证据材料，业务部门应予配合。"},{"i":12,"n":"第十二条","txt":"对重大、复杂的案件，法制机构可以组织法律顾问、专家进行研究论证；申请人提出要求或者法制机构认为必要时，可以采取听证方式审理。"},{"i":13,"n":"第十三条","txt":"申请人在申请行政复议时，依法一并提出审查作出具体行政行为所依据的规范性文件，法制机构一并受理。有权处理的，应当在三十日内依法处理；无权处理的，应当在七日内按照法定程序转送有权处理的国家机关依法处理。处理期间，中止对具体行政行为的审查。"},{"i":14,"n":"第十四条","txt":"法制机构对具体行政行为进行审查，提出意见，经国际发展合作署署务会议审定后，作出以下行政复议决定： （一）具体行政行为认定事实清楚、证据确凿、适用依据正确、程序合法、内容适当的，决定维持； （二）申请人要求被申请人履行未履行的法定职责的，决定被申请人在一定期限内履行； （三）具体行政行为有下列情形之一的，决定撤销、变更具体行政行为或者确认具体行政行为违法： 1.主要事实不清、证据不足的； 2.适用依据错误的； 3.违反法定程序的； 4.超越或者滥用职权的； 5.具体行政行为明显不当的。"},{"i":15,"n":"第十五条","txt":"申请人在申请行政复议时一并提出行政赔偿请求的，应当按照《中华人民共和国国家赔偿法》第十二条规定写明具体的赔偿请求、事实根据和理由。国际发展合作署对依法应当给予赔偿的，在决定撤销、变更具体行政行为或者确认具体行政行为违法时，应当同时决定依法给予赔偿。"},{"i":16,"n":"第十六条","txt":"本办法由国际发展合作署负责解释，自2020年5月1日起施行。"}],"guojiamimaguanlijuguizhangzhidingchengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范国家密码管理局规章制定工作,根据《中华人民共和国立法法》、《中华人民共和国密码法》和《规章制定程序条例》,制定本规定。"},{"i":2,"n":"第二条","txt":"国家密码管理局根据法律和国务院的行政法规、决定、命令,在本部门的权限范围内制定公布面向社会履行密码行政管理职能,对密码管理部门和行政相对人具有普遍约束力的规章。 规章的立项、起草、审查、决定、公布、解释,适用本规定。"},{"i":3,"n":"第三条","txt":"制定规章,应当坚持中国共产党对密码工作的领导,贯彻落实党的路线方针政策和决策部署,遵循立法法确定的立法原则,符合宪法、法律、行政法规和其他上位法的规定。 制定规章涉及重大事项的,应当事先报中央密码工作领导小组同意。重要规章公布前,应当报中央密码工作领导小组批准。"},{"i":4,"n":"第四条","txt":"制定规章,应当体现职权与责任相统一的原则,切实保障行政相对人的合法权益。 没有法律或者国务院的行政法规、决定、命令的依据,规章不得设定减损行政相对人权利或者增加其义务的规范,不得增加密码管理部门的权力或者减少密码管理部门的法定职责。 规章不得溯及既往,但是为了更好地保护行政相对人权益而作出的特别规定除外。"},{"i":5,"n":"第五条","txt":"规章的名称一般称“规定”、“办法”,但不得称“条例”。"},{"i":6,"n":"第六条","txt":"规章应当根据需要,明确制定目的、依据、适用范围、主体、权利义务、具体规范、操作程序、法律责任、施行日期等。 规章用语应当准确、简洁,避免产生歧义；条文内容应当明确、具体,具有可操作性。 法律、行政法规已经明确规定的内容,规章原则上不作重复规定。 除内容复杂的外,规章一般不分章、节。"},{"i":7,"n":"第七条","txt":"国家密码管理局内设机构或者省、自治区、直辖市密码管理部门认为需要制定规章的,应当于每年11月30日前向国家密码管理局提出下一年度的规章立项申请。 规章立项申请应当列明规章名称、立项必要性和可行性、所要解决的主要问题、拟确立的主要制度、起草单位、进度安排和完成时间等内容。 国家密码管理局可以向社会公开征集规章制定项目建议。"},{"i":8,"n":"第八条","txt":"国家密码管理局政策法规机构（以下简称政策法规机构）应当对规章立项申请和制定项目建议进行评估论证,拟订年度规章制定工作计划,报局务会议批准后向社会公布。 年度规章制定工作计划需要调整的,应当经局务会议批准。"},{"i":9,"n":"第九条","txt":"规章由国家密码管理局业务主管机构负责起草；涉及多个机构职责的,由一个机构牵头起草,相关机构配合。重要的或者综合性的规章,可以由政策法规机构起草或者组织起草。 起草专业性较强的规章,可以吸收相关领域的专家、局法律顾问、公职律师参与,或者委托有关专家、教学科研单位、社会组织起草。"},{"i":10,"n":"第十条","txt":"起草规章,应当深入调查研究,广泛听取国务院有关部门、地方密码管理部门、组织和公民的意见。听取意见可以采取书面征求意见、座谈会、论证会、听证会等多种形式。 除依法需要保密的外,起草单位应当将规章征求意见稿及其说明等在中国政府法制信息网、国家密码管理局门户网站上向社会公布,征求意见,征求意见期限一般不少于30日。 起草规章涉及重大利益调整的,起草单位应当按照规定进行论证咨询。依法需要进行听证的,起草单位应当按照规定举行听证会听取意见。 起草单位与国务院有关部门有不同意见的,应当充分协商；经过充分协商不能取得一致意见的,起草单位应当在报送规章草案送审稿（以下简称规章送审稿）时说明情况和理由。"},{"i":11,"n":"第十一条","txt":"起草单位形成规章送审稿后,应当将规章送审稿及其说明和其他有关材料按照规定报送政策法规机构审查。 规章送审稿的说明应当对制定规章的必要性、起草过程、规定的主要措施、有关方面的意见及其协调处理情况等作出说明。 有关材料主要包括所规范领域的实际情况和相关数据、实践中存在的主要问题、汇总的意见、听证会笔录、调研报告、国内外有关立法资料等。"},{"i":12,"n":"第十二条","txt":"政策法规机构应当从以下方面对规章送审稿进行审查： （一）是否符合本规定第三条至第六条的规定； （二）是否与有关规章协调、衔接； （三）是否正确处理国务院有关部门、地方密码管理部门、组织和公民对规章送审稿主要问题的意见； （四）是否符合立法技术要求； （五）需要审查的其他内容。"},{"i":13,"n":"第十三条","txt":"规章送审稿有下列情形之一的,政策法规机构可以缓办或者退回起草单位： （一）制定规章的基本条件尚不成熟或者发生重大变化的； （二）国务院有关部门对规章送审稿规定的主要制度存在较大争议,起草单位未与国务院有关部门充分协商的； （三）未按照本规定有关规定公开征求意见的； （四）报送送审稿不符合本规定第十一条规定的。"},{"i":14,"n":"第十四条","txt":"政策法规机构应当按照规定对规章送审稿涉及的主要问题进行深入调查研究,并将规章送审稿或者规章送审稿涉及的主要问题发送国务院有关部门、地方密码管理部门、组织和专家征求意见。 政策法规机构可以将规章送审稿或者修改稿及其说明等向社会公布,征求意见,征求意见期限一般不少于30日。"},{"i":15,"n":"第十五条","txt":"规章送审稿涉及重大利益调整的,政策法规机构应当按照规定进行论证咨询。规章送审稿在起草过程中应当进行而未进行听证的,政策法规机构报局领导批准后,按照规定举行听证会。 国务院有关部门对规章送审稿涉及的主要措施、管理体制、权限分工等问题有不同意见的,政策法规机构应当进行协调,力求达成一致意见。对有较大争议的重要立法事项,政策法规机构可以委托有关专家、教学科研单位、社会组织进行评估。经过充分协调不能达成一致意见的,政策法规机构应当提出倾向性意见报局领导协调或者报局务会议决定。"},{"i":16,"n":"第十六条","txt":"政策法规机构应当认真研究各方面意见,与起草单位协商后,对规章送审稿进行修改,形成规章草案和对草案的说明,报局务会议审议。"},{"i":17,"n":"第十七条","txt":"规章草案经局务会议审议通过后,政策法规机构应当根据局务会议审议意见进行修改,形成草案修改稿,报请局长签署国家密码管理局令予以公布。 国家密码管理局与国务院有关部门联合制定的规章,应当经局务会议审议通过,由局长和联合制定部门的行政首长共同署名,以联合命令形式公布,使用主办机关的命令序号。"},{"i":18,"n":"第十八条","txt":"规章签署公布后,及时在国务院公报、中国政府法制信息网和国家密码管理局门户网站上刊载。"},{"i":19,"n":"第十九条","txt":"规章应当自公布之日起30日后施行；但是,涉及国家安全以及公布后不立即施行将有碍施行的,可以自公布之日起施行。"},{"i":20,"n":"第二十条","txt":"规章由国家密码管理局负责解释。规章的解释同规章具有同等效力。"},{"i":21,"n":"第二十一条","txt":"规章应当自公布之日起30日内,由政策法规机构按照规定报国务院备案。"},{"i":22,"n":"第二十二条","txt":"规章的修改、废止程序适用本规定的有关规定。规章修改、废止后,应当及时公布。 国家密码管理局应当及时组织开展规章清理工作,并根据清理情况及时修改或者废止相关规章。 国家密码管理局可以组织开展规章立法后评估,并把评估结果作为修改、废止规章的重要参考。"},{"i":23,"n":"第二十三条","txt":"国家密码管理局负责起草法律、行政法规草案的,参照本规定执行。"},{"i":24,"n":"第二十四条","txt":"本规定自2022年2月1日起施行。"}],"guojiaminweizhidingguizhangheguifanxingwenjiandegu827360":[{"i":1,"n":"第一条","txt":"为了规范国家民委规章和规范性文件制定程序，推进依法行政，根据《中华人民共和国立法法》、《规章制定程序条例》、《法规规章备案条例》等有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称规章，是指国家民委根据法律和国务院的行政法规、决定、命令，以委令形式公布的，涉及行政相对人权利义务，具有普遍约束力的规定、办法和实施细则等。 本规定所称规范性文件，是指国家民委为执行法律、行政法规、规章和国务院文件的有关规定，依据法定职权制定公布的决定、规定、公告、通告、通知和办法等。规范性文件应符合以下要件： （一）涉及行政相对人权利义务的外部行政事项； （二）具有规范性和普遍约束力； （三）调整对象为不特定的行政相对人或事项； （四）针对未来事项且需要通过具体行为执行或落实，在一定期限内能够反复适用。"},{"i":3,"n":"第三条","txt":"国家民委单独或与国务院有关部门联合制定的规章和规范性文件，适用本规定。 国家民委制定的不涉及行政相对人权利义务的请示、报告、通报、内部工作制度、人事任免决定等文件，以及项目批复等对外部具体事项作出的行政决定，不适用本规定。"},{"i":4,"n":"第四条","txt":"政策法规司负责归口管理和协调规章的立项、审查、公布、备案工作和规范性文件的合法性审查工作。其他各有关部门按照职责具体承担相应的立项申请、起草、清理和解释等工作。"},{"i":5,"n":"第五条","txt":"各部门认为需要制定或修订规章的，应于每年11月30日前向政策法规司提出下一年度立项申请。 政策法规司应对立项申请进行汇总研究，拟订国家民委年度规章制定工作计划，报委务会议审批后，以办公厅文件形式印发各部门执行。"},{"i":6,"n":"第六条","txt":"规章的名称一般称“规定”、“办法”，不得称“条例”。 规章应当结构严谨、用词准确规范、具有可操作性，不得与法律、行政法规相抵触。 规章根据内容需要，可以分为章、节、条、款、项、目。"},{"i":7,"n":"第七条","txt":"起草规章，应在深入调查研究的基础上，采取座谈会、论证会、听证会等形式或通过国家民委政府网站和有关媒体，广泛听取有关单位、组织、专家和其他有关人员的意见。 对各方面提出的修改意见，起草部门应提出采纳或者不采纳的意见及其理由，并以适当方式进行反馈。"},{"i":8,"n":"第八条","txt":"起草规范性文件，应符合《国家行政机关公文处理办法》和《国家民委机关公文处理细则》的相关规定。"},{"i":9,"n":"第九条","txt":"规章起草部门根据有关方面的修改意见研究、完善并形成规章送审稿提交政策法规司审查。 提交规章送审稿时，应同时提交制定规章的必要性、主要依据、起草过程、征求意见情况及协调情况、与现行的相关规章和文件相衔接情况等说明。"},{"i":10,"n":"第十条","txt":"政策法规司应从以下方面对规章送审稿进行审查： （一）是否符合法定权限和程序； （二）是否与有关法律、行政法规相协调、衔接； （三）是否妥善协调和处理有关方面的意见； （四）是否符合立法技术要求； （五）其他需要审查的内容。"},{"i":11,"n":"第十一条","txt":"经政策法规司审查后，起草部门形成规章草案和对草案的说明，提交委务会议审议。 规章草案经委务会议审议通过后，由国家民委主任签署命令予以公布。"},{"i":12,"n":"第十二条","txt":"国家民委与国务院其他部门联合制定的规章由国家民委主任和联合制定部门的主要负责同志共同签署命令予以公布。"},{"i":13,"n":"第十三条","txt":"各部门起草的规范性文件，在送办公厅核稿前，应先送政策法规司进行合法性审查。签发人和办公厅做出实质性修改的，起草部门应再次送政策法规司复核。未经政策法规司合法性审查的规范性文件，办公厅不予核稿。 政策法规司主要从以下方面进行审查： （一）是否有与法律、行政法规相抵触的内容； （二）制定过程是否符合规定的程序； （三）其他应当审查的内容。"},{"i":14,"n":"第十四条","txt":"规章的公布由政策法规司负责；规范性文件的公布由起草部门负责。"},{"i":15,"n":"第十五条","txt":"规章公布后30日内，由政策法规司按照有关程序和要求报国务院法制办备案。 起草部门应于每年1月30日前，将上一年度发布的规范性文件提交政策法规司备案。"},{"i":16,"n":"第十六条","txt":"国家民委定期开展规章、规范性文件清理工作。清理工作由政策法规司牵头组织，各部门具体负责由本部门起草的规章和规范性文件的清理工作。 规章清理原则上每5年开展一次，规范性文件清理每2年开展一次。日常清理由各起草部门根据工作需要进行。"},{"i":17,"n":"第十七条","txt":"规章、规范性文件有下列情形之一的，应进行修改： （一）根据工作需要，有必要增减内容的； （二）因法律、行政法规的制定、修正或者废止，规章、规范性文件的个别条款与之相抵触的； （三）规定的主管机关或者执行机关发生变更的； （四）其他需要修改的情形。 修改规章或规范性文件的程序及公布方式，参照前述有关规定执行。"},{"i":18,"n":"第十八条","txt":"规章、规范性文件有下列情形之一的，应予废止或宣布失效： （一）因有关法律、行政法规、规章废止或者修改，失去依据的； （二）规定的事项已执行完毕或者因实际情况变化，没有必要继续执行的； （三）对同一事项已作出新规定的； （四）其他应予废止或宣布失效的情形。 废止或宣布失效规章应以国家民委令的形式公布；废止或宣布失效规范性文件，应以国家民委公告的形式公布。"},{"i":19,"n":"第十九条","txt":"规章有下列情形之一的，由起草部门商政策法规司提出意见，报请委领导批准后进行解释： （一）规章的规定需要进一步明确具体含义的； （二）规章制定后出现新的情况，需要明确适用依据的。"},{"i":20,"n":"第二十条","txt":"政策法规司牵头负责国家民委规章、规范性文件的编纂、汇编工作。需用多种文字编辑出版的规章、规范性文件汇编，依照《法规汇编编辑出版管理规定》的有关规定执行。"},{"i":21,"n":"第二十一条","txt":"本规定自2011年9月1日起施行，国家民委2000年2月25日公布的《国家民委关于起草和制定法规的程序规定》同时废止。"}],"guojiaminweikeyanxiangmuguanlibanfa":[{"i":1,"n":"第一条","txt":"为进一步加强国家民委科研项目管理工作的科学化和规范化，依据国家有关规定制定本办法。"},{"i":2,"n":"第二条","txt":"国家民委科研项目坚持全面开放原则，公平竞争，择优立项。"},{"i":3,"n":"第三条","txt":"国家民委科研项目分为招标项目、委托项目和后期资助项目等类别。"},{"i":4,"n":"第四条","txt":"国家民委成立科研项目管理办公室，负责科研项目的统一管理。国家民委科研项目管理办公室（以下简称管理办公室）由国家民委民族理论政策研究室和教育科技司组成，民族理论政策研究室负责民族研究项目管理，教育科技司负责其他项目管理，对外统一使用国家民委科研项目管理办公室名称。 国家民委机关各部门因工作需要设立科研项目的,应当委托管理办公室办理相关事宜。"},{"i":5,"n":"第五条","txt":"国家民委科研项目管理工作应当遵循公开、公平、公正的原则。"},{"i":6,"n":"第六条","txt":"国家民委鼓励合作攻关重大基础研究项目和应用研究项目，支持对民族工作决策具有重要参考价值的其他现实问题研究项目。"},{"i":7,"n":"第七条","txt":"国家民委科研项目采取招标和委托相结合的方式，实行项目主持人负责制。"},{"i":8,"n":"第八条","txt":"管理办公室于每年12月底前在国家民委网站发布下年度的《国家民委课题指南》，在规定期限内受理项目申报。"},{"i":9,"n":"第九条","txt":"申报国家民委科研项目的主持人应符合以下条件： （一）遵守中华人民共和国宪法和法律有关规定； （二）一般应为高校、科研院所等有关单位的正式在职职工，聘用职工应与单位签有正式协议； （三）年龄一般不超过65周岁，鼓励和扶持青年学者（40周岁以下）申报； （四）申报自筹经费项目，须有出资单位或个人的经费有效资助证明。"},{"i":10,"n":"第十条","txt":"申报国家民委科研项目应填写《国家民委课题申请表》并提供相关材料，经项目主持人所在单位审查并签署意见后，报送管理办公室。"},{"i":11,"n":"第十一条","txt":"具有下列情况之一者，取消申报资格： （一）申报材料中有虚假内容的； （二）项目申请人严重违反学术道德的； （三）项目主持人承担国家民委科研项目，尚未结项的。"},{"i":12,"n":"第十二条","txt":"管理办公室负责组织国家民委科研项目的立项评审。 （一）初核。管理办公室按照本办法第九至十一条的要求对课题申报材料进行审核。 （二）初审。管理办公室组织成立专家组，对通过初核的申报材料实行活页匿名评审。根据申报实际选出一定数量的申报材料进入复审。 （三）复审。管理办公室组织专家组对进入复审的申报材料进行审核，复审采取分组投票方式进行。 （四）终审。管理办公室将复审结果报终审专家评审，确定拟立项项目名单。 （五）公示。管理办公室将终审专家确定的拟立项项目名单在国家民委网站进行公示，公示时间不少于5个工作日。 （六）立项。通过公示的拟立项项目，由管理办公室及时发布立项公告。"},{"i":13,"n":"第十三条","txt":"立项评审应主要从以下几方面进行评价判断： （一）项目设计的科学性、合理性； （二）研究内容的创新性及技术路线的可行性； （三）项目主持人的科研能力及项目组成人员结构的合理性； （四）具备相关科研条件和研究基础； （五）项目研究经费预算的合理性。"},{"i":14,"n":"第十四条","txt":"参与评审的相关人员应当严格遵守评审纪律，如有不当行为，将依照有关规定予以严肃处理。"},{"i":15,"n":"第十五条","txt":"经批准立项的，由管理办公室向项目主持人发出《国家民委科研项目立项通知书》。 立项时间以立项通知书发出之日为准。"},{"i":16,"n":"第十六条","txt":"项目主持人接到项目立项通知书后应在规定期限内填写《回执》并签字后寄回管理办公室。逾期未签者视为自动放弃。"},{"i":17,"n":"第十七条","txt":"自然科学类的国家民委科研项目的研究时限一般为2年，最长不超过3年。社会科学类的一般为1年半，最长不超过2年。国家民委科研项目的研究时限均以立项通知书为准。"},{"i":18,"n":"第十八条","txt":"管理办公室对项目进行全程跟踪管理，对开题和课题进展情况实施抽查。 项目主持人所在单位科研管理部门要履行职责，对项目实施过程进行管理。"},{"i":19,"n":"第十九条","txt":"凡有下列情形之一者，须由项目主持人提交书面申请，并经所在单位同意，报管理办公室审批： （一）变更项目主持人； （二）变更项目名称； （三）变更项目最终成果形式； （四）变更项目研究内容； （五）变更项目管理单位； （六）申请项目延期； （七）申请撤销项目。"},{"i":20,"n":"第二十条","txt":"管理办公室组织有关专家对项目最终研究成果进行鉴定，通过鉴定后方可结项。 （一）项目研究工作完成后，项目主持人填报《结项申请表》并提供相关材料，经所在单位科研和财务部门审核合格后，报送管理办公室； （二）管理办公室对《结项申请表》及相关材料进行审查，审查合格后送专家组进行鉴定； （三）专家组应对项目成果提出是否通过及相应评级的鉴定意见； （四）管理办公室汇总专家鉴定意见，提出能否结项及相应评级的意见； （五）管理办公室将鉴定结果在国家民委网站上公示，并通知项目主持人及其所在单位。"},{"i":21,"n":"第二十一条","txt":"成果鉴定未能通过的，允许项目组在半年内对成果进行修改，并重新申请鉴定。重新鉴定仍不能通过的，按撤项处理，且2年内不得申请国家民委科研项目。"},{"i":22,"n":"第二十二条","txt":"最终成果鉴定通过后，由管理办公室负责办理验收结项事宜，发给《国家民委科研项目结项证书》。"},{"i":23,"n":"第二十三条","txt":"凡有下列情形之一者，撤销项目并公示： （一）无特殊情况逾期不提交研究成果的； （二）专家鉴定不合格并在延长期限（最长半年）结束后第二次鉴定仍不合格的； （三）剽窃他人成果的； （四）擅自变更计划任务的； （五）不提交经费使用决算表，或经费使用情况严重违反财务纪律的； （六）其他违反本办法规定的。"},{"i":24,"n":"第二十四条","txt":"国家民委单独设立科研项目专项经费，年度规模根据实际情况确定。 管理办公室负责对项目经费的使用情况进行监督、检查和指导。 项目主持人所在单位按财务制度要求对项目资助经费实施具体管理；项目经费不分拨给项目研究成员个人。 相关财务部门应妥善保存项目资助经费账单，并有义务接受有关部门的监督、检查和审计。"},{"i":25,"n":"第二十五条","txt":"管理办公室根据核准项目，将项目经费拨到项目主持人所在单位的银行账户，由所在单位统一管理。 项目资助经费一次核定，一般分两期拨付，包干使用，超支不补。首期拨付资助经费的80%，在规定期限内经鉴定合格的再拨付20%。鉴定为不合格的，不再拨付尾款。"},{"i":26,"n":"第二十六条","txt":"具体经费使用办法、项目资金开支范围参照《国家社会科学基金项目资金管理办法》执行。"},{"i":27,"n":"第二十七条","txt":"项目主持人所在单位的科研管理部门，按国家有关规定提取管理费，用于项目日常管理、检查和专家咨询、评审等专用支出。管理费不超过项目经费的5%。"},{"i":28,"n":"第二十八条","txt":"项目主持人在本单位科研和财务管理部门的指导下，按计划自主支配项目经费，严禁挪用。 依据相关财务规定严格使用经费，在提交《结题申请表》时，应同时提交资助经费决算表。"},{"i":29,"n":"第二十九条","txt":"项目成果通过验收后，资助经费有结余的，由项目主持人所在单位继续用于开展研究工作，项目主持人有优先使用权。 若项目研究成果通过审核验收2年后结余资金仍有剩余的，应当按国家有关规定收回。"},{"i":30,"n":"第三十条","txt":"对因故不能结项而导致撤项的，剩余经费应按原渠道返回管理办公室。对无故不完成研究任务而导致撤项的，管理办公室将追回全部已拨经费。"},{"i":31,"n":"第三十一条","txt":"项目成果通过鉴定，且不涉及国家秘密的，可公开出版或发表。未通过鉴定的，不能出版或发表。民族研究项目成果未经管理办公室同意，不得公开。"},{"i":32,"n":"第三十二条","txt":"根据需要，可择优资助部分科研项目成果出版。"},{"i":33,"n":"第三十三条","txt":"管理办公室可推荐符合要求的项目成果直接进入国家民委优秀科研成果的评奖程序。项目负责人提出申请的，可推荐参加国内外各类评奖活动。"},{"i":34,"n":"第三十四条","txt":"管理办公室可通过要报、内参等形式上报，加强对优秀成果的宣传、推广和应用转化。"},{"i":35,"n":"第三十五条","txt":"如无特殊约定，项目成果的著作权属作者本人，成果完成1年内国家民委有权优先使用。成果正式出版或向有关部门报送时，需在醒目位置标明“国家民委科研项目”相关字样。"},{"i":36,"n":"第三十六条","txt":"科研项目涉及国家秘密的，有关单位和人员应切实做好保密工作。"},{"i":37,"n":"第三十七条","txt":"本办法自公布之日起施行。"},{"i":38,"n":"第三十八条","txt":"本办法由国家民委科研项目管理办公室负责解释。"}],"guojiahuanjingbaohujuhuanjingbaohukexuejishuyanjiue4e208":[{"i":1,"n":"第一条","txt":"为加强对环境保护科学技术研究成果（以下简称环保科技成果）的管理，促进环境保护科学技术进步，特制定本办法。"},{"i":2,"n":"第二条","txt":"环保科技成果管理的主要任务，是做好环保科技成果的鉴定、建档、登记、奖励、保密和推广应用等工作。"},{"i":3,"n":"第三条","txt":"本办法所指环保科技成果包括： （一）为阐明环境污染、生态破坏及其效应的机理、规律、特征而取得的具有一定学术价值的应用理论研究成果； （二）为解决某一环境问题而取得的具有创造性、先进性和实用性的应用技术成果； （三）对引进的环境保护科学技术进行消化、吸收、创新而取得的具有新颖性、先进性和实用价值的技术成果； （四）应用推广已有科技成果过程中取得的新的环保科技成果； （五）为环境决策和环境管理提供科学依据，促进环境、经济与社会协调发展而取得的软科学研究成果。"},{"i":4,"n":"第四条","txt":"国家环境保护局负责管理全国的重大环保科技成果。 各省、自治区、直辖市环境保护行政主管部门负责管理本地区的环保科技成果；国务院有关部委环境保护机构负责管理本部门的环保科技成果。 各基层单位负责管理本单位的科技成果。"},{"i":5,"n":"第五条","txt":"环保科技成果的鉴定必须按照国家科学技术委员会关于科学技术成果鉴定的规定执行。"},{"i":6,"n":"第六条","txt":"环保科技成果通过鉴定后，应按档案管理的有关规定及时建档。"},{"i":7,"n":"第七条","txt":"达到国家先进水平、技术难度较大、具有推广应用价值的重大环保科技成果，应报送国家环境保护局登记，并附送下列材料一套： （一）科学技术研究成果报告表； （二）技术鉴定证书或视同鉴定证书； （三）主要技术报告。 报送国家环境保护局登记的环保科技成果，应经省、自治区、直辖市环境保护行政主管部门或国务院有关部委环境保护机构审查、推荐。国家环境保护局直属单位的环保科技成果，直接报送。两个以上单位合作完成的环保科技成果，由项目主要完成单位会同主要协作单位按上述规定报送。"},{"i":8,"n":"第八条","txt":"国家环境保护局对符合条件的环保科技成果，按报送日期先后顺序登记，并在国家环境保护局《环境保护科学技术研究成果公报》上公布。 任何单位、个人对《环境保护科学技术研究成果公报》中的环保科技成果有异议的，自成果公布之日起两个月内，可向国家环境保护局提出。提出异议必须采用书面形式，并写清异议者的真实姓名、工作单位和联系地址。国家环境保护局接到异议书后，送成果推荐部门调查核实；成果推荐部门应及时对有异议的成果提出处理意见，报国家环境保护局核定。 对无异议的环保科技成果，由国家环境保护局发给环保科技成果证书。"},{"i":9,"n":"第九条","txt":"对环保科技成果的奖励，按照国家有关科技奖励条例和《国家环境保护局环境保护科学技术进步奖励办法》执行。"},{"i":10,"n":"第十条","txt":"环保科技成果的保密必须按照国务院批准的《科学技术保密条例》以及国家环境保护局和国家保密局的有关规定执行。"},{"i":11,"n":"第十一条","txt":"各级环保科技成果管理部门应与科技情报、科技服务、科技开发和科技宣传等机构配合，交流环保科技成果信息；对技术先进，工艺成熟，环境效益、经济效益和社会效益较好的环保科技成果，应编制推广计划，安排落实。"},{"i":12,"n":"第十二条","txt":"本办法自发布之日起施行。"}],"guojiakexuejishujianglitiaolishishixize":[{"i":1,"n":"第一条","txt":"为了做好国家科学技术奖励工作，保证国家科学技术奖质量，根据《国家科学技术奖励条例》（以下简称《奖励条例》），制定本细则。"},{"i":2,"n":"第二条","txt":"本细则适用于国家最高科学技术奖、国家自然科学奖、国家技术发明奖、国家科学技术进步奖和中华人民共和国国际科学技术合作奖（以下简称国际科技合作奖）的提名、评审、授予等各项活动。"},{"i":3,"n":"第三条","txt":"国家科学技术奖励工作坚持党中央集中统一领导，遵循党和国家功勋荣誉表彰奖励工作的基本原则，坚持公开、公平、公正，实行科学的评审制度，不受任何组织或者个人的干涉，接受纪检监察监督和社会监督。 国家科学技术奖励工作重大事项按照有关规定报党中央。"},{"i":4,"n":"第四条","txt":"国家科学技术奖坚持国家战略导向，面向世界科技前沿、面向经济主战场、面向国家重大需求、面向人民生命健康，与国家重大战略需要和中长期科技发展规划紧密结合，推动科技创新和产业创新深度融合，重点奖励在基础研究和应用基础研究、关键核心技术攻关、助力发展新质生产力等方面做出创造性贡献的科学家和一线科技人员，激励引导广大科技工作者锚定科技强国建设目标，加快实现高水平科技自立自强。"},{"i":5,"n":"第五条","txt":"国家科学技术奖授予在科学发现、技术发明和促进科学技术进步等方面做出创造性突出贡献的个人、组织。同一项目授奖的个人、组织按照贡献大小排序。 在科学研究、技术开发项目中仅从事组织领导、行政管理或者辅助服务的人员，不得作为国家科学技术奖的候选者。"},{"i":6,"n":"第六条","txt":"国家科学技术奖是国家授予个人或者组织的荣誉，授奖证书不作为确定科学技术成果权属的直接依据。"},{"i":7,"n":"第七条","txt":"科技部负责国家科学技术奖的相关办法制定和评审活动的组织工作。国家科学技术奖励工作办公室（以下简称奖励办公室）负责相关日常工作。 科技部会同有关部门对国家科学技术奖励工作开展绩效评价。"},{"i":8,"n":"第八条","txt":"国家科学技术奖励委员会（以下简称奖励委员会）聘请有关方面的专家、学者等组成评审委员会和监督委员会，负责国家科学技术奖的评审和监督工作。 奖励委员会的组成人员人选由科技部提出，报党中央、国务院批准。"},{"i":9,"n":"第九条","txt":"国家科学技术奖每两年评审一次。 国家最高科学技术奖每次授予人数不超过2名。 国家自然科学奖、国家技术发明奖、国家科学技术进步奖每次授予项目总数不超过300项。其中，每个奖种的特等奖项目不超过3项，一等奖项目不超过该奖种奖励项目总数的15%。 国际科技合作奖每次授予数额不超过10个。"},{"i":10,"n":"第十条","txt":"建立健全国家科学技术奖励工作保密管理制度。对涉及国家安全的项目，按照国家保密法律法规和科学技术保密规定，采取严格的保密措施，加强全过程保密管理。"},{"i":11,"n":"第十一条","txt":"《奖励条例》第八条第一款第一项所称“在当代科学技术前沿取得重大突破或者在科学技术发展中有卓越建树”，是指候选者在基础研究、应用基础研究中取得系列或者特别重大发现，丰富和拓展了学科的理论，引领了本学科或者相关学科领域的突破性发展，为国内外同行所公认，对服务国家战略、科学技术发展和社会进步做出了特别重大的贡献。"},{"i":12,"n":"第十二条","txt":"《奖励条例》第八条第一款第二项所称“在科学技术创新、科学技术成果转化和高技术产业化中，创造巨大经济效益、社会效益、生态环境效益或者对维护国家安全做出巨大贡献”，是指候选者在科学技术活动中，特别是面向国家重大需求的重点领域，取得系列或者特别重大技术突破，引领了相关行业领域的重大科技进步和产业变革，为促进经济社会发展、保障人民生命健康、保护生态环境、维护国家安全等做出了特别重大的贡献。"},{"i":13,"n":"第十三条","txt":"国家最高科学技术奖的候选者应当热爱祖国，模范践行科学家精神，并仍活跃在当代科学技术前沿，从事科学研究或者技术开发工作。"},{"i":14,"n":"第十四条","txt":"《奖励条例》第九条第二款第一项所称“前人尚未发现或者尚未阐明”，是指该项自然科学发现为国内外首次提出，或者其科学理论在国内外首次阐明，且主要论著为国内外首次发表。"},{"i":15,"n":"第十五条","txt":"《奖励条例》第九条第二款第二项所称“具有重大科学价值”，是指： （一）在科学理论、学说上有创见，或者在研究方法、手段上有创新； （二）对于推动学科发展有重大意义，或者对于经济建设和社会发展具有重要影响。"},{"i":16,"n":"第十六条","txt":"《奖励条例》第九条第二款第三项所称“得到国内外自然科学界公认”，是指主要论著已在国内外公开发行的学术刊物上发表或者作为学术专著出版三年以上，其重要科学结论已为国内外同行在重要学术会议、公开发行的重要学术刊物以及学术专著所正面引用或者应用。逐步提高主要论著在国内学术刊物上发表的比例。"},{"i":17,"n":"第十七条","txt":"国家自然科学奖的候选者应当是相关科学技术论著的主要作者，并具备下列条件之一： （一）提出总体学术思想、研究方案； （二）发现重要科学现象、特性和规律，并阐明科学理论和学说； （三）提出研究方法和手段，解决关键性学术疑难问题或者实验技术难点，以及对重要基础数据的系统收集和综合分析等。"},{"i":18,"n":"第十八条","txt":"国家自然科学奖一等奖、二等奖单项授奖人数不超过5人；特等奖单项授奖人数经国家自然科学奖评审委员会评审后，由奖励委员会确定。"},{"i":19,"n":"第十九条","txt":"国家自然科学奖授奖等级根据候选者所做出的科学发现进行综合评定，评定标准如下： （一）在科学上取得重大原创性突破，发现的自然现象、揭示的科学规律、提出的学术理论或者研究方法为国内外学术界所公认，引领本学科或者相关学科的发展，或者为关键核心技术突破提供重要理论支撑，对经济社会发展有重大影响的，可以评为一等奖。 （二）在科学上取得重要原创性突破，发现的自然现象、揭示的科学规律、提出的学术理论或者研究方法为国内外学术界所公认，推动本学科或者相关学科的发展，或者为相关技术突破提供理论支撑，对经济社会发展有重要影响的，可以评为二等奖。 前瞻性、引领性特别突出，取得特别重大科学突破，具有特别重大科学价值，产生特别重大影响的科学发现，可以评为特等奖。"},{"i":20,"n":"第二十条","txt":"《奖励条例》第十条第二款第一项所称“前人尚未发明或者尚未公开”，是指该项技术发明为国内外首创，或者虽然国内外已有但主要技术内容尚未在国内外各种公开出版物、媒体及其他公共渠道发表或者公开，也未曾公开使用过。"},{"i":21,"n":"第二十一条","txt":"《奖励条例》第十条第二款第二项所称“具有先进性、创造性、实用性”，是指该项技术发明与国内外已有同类技术相比较，其主要性能（性状）、技术经济指标、科学技术水平及其促进科学技术进步的作用和意义等方面综合优于同类技术，技术思路、技术原理或者技术方法有创新，技术上有突出的实质性特点和显著的进步，且在制造、使用后产生明显的积极效果。"},{"i":22,"n":"第二十二条","txt":"《奖励条例》第十条第二款第三项所称“经实施，创造显著经济效益、社会效益、生态环境效益或者对维护国家安全做出显著贡献，且具有良好的应用前景”，是指该项技术发明成熟，并实施应用三年以上，取得显著的应用效果，且未来具有广泛应用的潜力或者可持续发展的良好预期。"},{"i":23,"n":"第二十三条","txt":"国家技术发明奖的候选者应当是该项技术发明的全部或者部分创造性技术内容的独立完成人。 国家技术发明奖一等奖、二等奖单项授奖人数不超过6人；特等奖单项授奖人数经国家技术发明奖评审委员会评审后，由奖励委员会确定。"},{"i":24,"n":"第二十四条","txt":"国家技术发明奖授奖等级根据候选者所做出的技术发明进行综合评定，评定标准如下： （一）属国内外首创的重大技术发明，关键技术上有重大的创新，技术经济指标达到国际同类技术的领先水平，推动相关领域的技术进步，产生重大经济效益、社会效益、生态环境效益或者对维护国家安全做出重大贡献，且具有广阔的应用前景，可以评为一等奖。 （二）属国内外首创的重要技术发明，主要技术上有较大的创新，技术经济指标达到国际同类技术的先进水平，对本领域的技术进步有推动作用，产生显著经济效益、社会效益、生态环境效益或者对维护国家安全做出显著贡献，且具有良好的应用前景，可以评为二等奖。 原始性、颠覆性创新特别突出，主要技术经济指标显著优于国际同类技术或者产品，创造特别重大经济效益、社会效益、生态环境效益或者对维护国家安全做出特别重大贡献，对抢占科技和产业发展制高点具有特别重大意义的技术发明，可以评为特等奖。"},{"i":25,"n":"第二十五条","txt":"国家技术发明奖的授奖范围不包括仅依赖个人经验和技能、技巧且不可重复实现的技术。"},{"i":26,"n":"第二十六条","txt":"《奖励条例》第十一条第一款所称“完成和应用推广创新性科学技术成果”包括下列类别： （一）技术开发类，即面向经济主战场和国家重大需求，完成具有重大市场实用价值或者满足国家重大需求的产品、技术、工艺、材料、设计和生物品种及其应用推广； （二）社会公益类，即在保障人民生命健康、保护生态环境、自然资源调查和合理利用、自然灾害监测预报和防治等社会公益性科学技术事业和在标准、计量、科技信息、科学数据、科技档案、科学技术普及等科学技术基础性工作中取得的科学技术成果及其应用推广； （三）国家安全类，即在国家安全相关活动中产生，并在一定时期内仅用于国家安全目的，对推进国防和军队现代化建设、增强国防实力和维护国家安全具有重要意义的科学技术成果； （四）重大工程类，即重大综合性基本建设工程、科学技术工程、国防工程等。 国家科学技术进步奖重大工程类仅授予组织。在完成重大工程中做出科学发现、技术发明的个人，符合"},{"i":27,"n":"第二十七条","txt":"《奖励条例》第十一条第二款第一项所称“技术创新性突出，技术经济指标先进”，是指在技术上有重要的创新，特别是在高新技术领域进行自主创新，形成了产业的主导技术和标志性产品，或者推动传统产业改造升级，提高科技含量和产品附加值；技术难度大，解决了行业发展中的热点、难点和关键问题；总体技术水平和技术经济指标达到了行业的领先水平。"},{"i":28,"n":"第二十八条","txt":"《奖励条例》第十一条第二款第二项所称“经应用推广”，是指相关科学技术成果经过三年以上较大规模的实施应用。"},{"i":29,"n":"第二十九条","txt":"《奖励条例》第十一条第二款第三项所称“在推动行业科学技术进步等方面有重大贡献”，是指项目转化程度高，具有较强的示范、带动和扩散能力，促进了产业结构的调整、优化、升级，对提升行业科技发展水平具有重要作用。"},{"i":30,"n":"第三十条","txt":"国家科学技术进步奖候选人应当具备下列条件之一： （一）在设计项目的总体技术方案中做出创造性的重要贡献； （二）在关键技术和疑难问题的解决中做出重大技术创新； （三）在成果转化和推广应用过程中做出创造性的重要贡献； （四）在高技术产业化方面做出重要贡献； （五）在科学技术普及方面做出突出贡献。"},{"i":31,"n":"第三十一条","txt":"国家科学技术进步奖候选组织应当是在项目研究、开发、应用和推广过程中提供技术、设备和人员等条件，对项目完成起到组织、管理和协调作用的主要完成单位。 各级党政机关一般不得作为国家科学技术进步奖的候选组织。"},{"i":32,"n":"第三十二条","txt":"国家科学技术进步奖一等奖单项授奖人数不超过15人，授奖组织不超过10个；二等奖单项授奖人数不超过10人，授奖组织不超过7个；特等奖单项授奖人数不超过50人，授奖组织不超过30个。"},{"i":33,"n":"第三十三条","txt":"国家科学技术进步奖授奖等级根据候选者所完成的项目进行综合评定，评定标准如下： （一）技术开发类 在关键核心技术或者系统集成上有重大创新，技术难度大，总体技术水平和主要技术指标达到国际同类技术或者产品先进水平，市场竞争力强，成果转化程度高，创造重大经济效益，对行业科技进步和产业结构优化升级有重大作用，为服务经济主战场和国家重大需求做出重大贡献的，可以评为一等奖； 在关键核心技术或者系统集成上有较大创新，技术难度较大，总体技术水平和主要技术指标达到国际同类技术或者产品水平并在国内处于领先水平，市场竞争力较强，成果转化程度较高，创造显著经济效益，对行业科技进步和产业结构调整优化有较大作用，为服务经济主战场和国家重大需求做出较大贡献的，可以评为二等奖。 （二）社会公益类 在关键核心技术或者系统集成上有重大创新，技术难度大，总体技术水平和主要技术经济指标达到国际同类技术或者产品先进水平，在行业得"},{"i":34,"n":"第三十四条","txt":"《奖励条例》第十三条所称“外国人或者外国组织”，是指在双边或者多边国际科技合作中对中国科学技术事业做出重要贡献的外国科学家、工程技术人员、科技管理人员或者从事科学技术研究、开发、管理等活动的外国组织、国际组织。"},{"i":35,"n":"第三十五条","txt":"国际科技合作奖的候选者应当对华友好，并具备下列条件之一： （一）在与中国的公民或者组织进行合作研究、开发等方面取得重大科技成果，对中国经济与社会发展有重要推动作用，并取得显著的经济效益或者社会效益； （二）在向中国的公民或者组织传授先进科学技术、提出重要科技发展建议与对策、培养科技人才或者管理人才等方面做出重要贡献，推进中国科学技术事业的发展，并取得显著的社会效益或者经济效益； （三）在积极宣传中国的科技政策与科技成就、促进中国与其他国家或者国际组织的科技交流与合作、提升中国在科学技术领域的国际影响力等方面做出重要贡献，并对中国的科学技术发展有重要推动作用。"},{"i":36,"n":"第三十六条","txt":"奖励委员会的主要职责是： （一）作出各奖种获奖者和奖励等级的决议； （二）聘请有关专家、学者等组成国家科学技术奖评审委员会和监督委员会； （三）审议国家科学技术奖励工作安排； （四）为完善国家科学技术奖励制度提供政策性意见和建议； （五）研究解决国家科学技术奖励工作中的其他重大问题。"},{"i":37,"n":"第三十七条","txt":"奖励委员会设委员20至25人，其中主任委员1人，副主任委员1至2人，秘书长1人。主任委员由科技部部长担任。委员由科技、教育、经济等领域的著名专家、学者和相关部门负责人组成。 奖励委员会每届任期5年。"},{"i":38,"n":"第三十八条","txt":"奖励委员会下设国家最高科学技术奖、国家自然科学奖、国家技术发明奖、国家科学技术进步奖、国际科技合作奖五个奖种评审委员会。评审委员会主要职责包括： （一）负责国家科学技术奖相应奖种的评审工作； （二）向奖励委员会提出相应奖种获奖者和奖励等级的建议； （三）对国家科学技术奖评审工作有关问题进行处理； （四）对完善国家科学技术奖励工作提供咨询意见。"},{"i":39,"n":"第三十九条","txt":"各奖种评审委员会委员（以下简称评审委员）一般不少于25人，分别设主任委员1人，副主任委员2人，秘书长1人。主任委员一般由奖励委员会委员担任，秘书长由奖励办公室主任担任。委员人选由奖励办公室提出，经科技部审核后，报奖励委员会批准。 评审委员会应结构合理，保持稳定性、连续性和权威性。评审委员连续聘任一般不得超过3次。"},{"i":40,"n":"第四十条","txt":"评审委员由于客观原因不能履行职责，可能影响评审工作正常开展时，或者根据评审工作实际情况需要调整、增补的，由奖励办公室提出调整、增补人选建议，经相应奖种评审委员会主任委员同意后，报奖励委员会主任委员批准。评审委员调整、增补的情况应当适时向奖励委员会报告。"},{"i":41,"n":"第四十一条","txt":"国家技术发明奖、国家科学技术进步奖评审委员会内设专用项目小组，负责涉及国家安全的保密项目的评审，并将评审结果向评审委员会报告。"},{"i":42,"n":"第四十二条","txt":"根据国家战略导向以及学科专业布局，结合评审工作需要，评审委员会下设若干评审组。评审组主要职责包括： （一）负责初评工作； （二）向评审委员会提出初评建议； （三）对相关异议进行审议； （四）对相关项目和人选进行实地考察。"},{"i":43,"n":"第四十三条","txt":"各评审组设组长1人，副组长1至3人，专家人数根据评审工作需要确定。组长一般由相应奖种评审委员担任。"},{"i":44,"n":"第四十四条","txt":"科技部建立国家科学技术奖评审专家库，由奖励办公室负责管理与维护。 参与初评的评审专家从评审专家库中按规则抽取产生。 评审专家名单应当按要求严格保密。"},{"i":45,"n":"第四十五条","txt":"科技部可以委托相关部门协助负责涉及国家安全的国家技术发明奖和国家科学技术进步奖评审组的相关日常工作。 受委托的相关部门应当建立规范的制度机制，严格加强评审保密管理。"},{"i":46,"n":"第四十六条","txt":"评审委员、评审专家应当认真履行评审职责，严格遵守评审工作纪律，坚决抵制可能影响国家科学技术奖评审公平、公正的行为和活动。"},{"i":47,"n":"第四十七条","txt":"评审委员、评审专家和相关的工作人员应当严格遵守评审保密要求，对评审内容及评审情况等严格保守秘密。"},{"i":48,"n":"第四十八条","txt":"科技部建立评审信誉管理机制。奖励办公室对参加评审活动的专家履行职责情况进行评价，评价情况作为后续选聘的重要依据。"},{"i":49,"n":"第四十九条","txt":"国家科学技术奖提名工作应当坚持国家战略导向，以学术水平为重要标准，弘扬良好作风学风，重在提名服务国家战略需求的重大科学技术成果和真正做出创造性贡献的科技人员。"},{"i":50,"n":"第五十条","txt":"国家科学技术奖实行限额提名制度。提名单位、提名专家资格条件和限额提名要求，由科技部制定提名办法予以规定。"},{"i":51,"n":"第五十一条","txt":"提名单位应当建立规范的遴选机制，在本部门、本地区、本行业范围内择优提名。 提名专家应当在本人熟悉的学科领域内提名。"},{"i":52,"n":"第五十二条","txt":"涉及国家安全的保密项目仅由中央和国家机关有关部门、中央军事委员会科学技术部门或者地方政府提名。"},{"i":53,"n":"第五十三条","txt":"提名者应当对提名材料的真实性和准确性负责，对候选者政治、品行、作风、廉洁等情况进行审核，并履行在答辩、异议和信访处理等工作中的责任。"},{"i":54,"n":"第五十四条","txt":"提名者和候选者所在单位应当按照要求对拟提名的国家最高科学技术奖候选者、国家自然科学奖、国家技术发明奖和国家科学技术进步奖候选者及其候选项目进行公示。涉及国家安全的保密项目在适当范围内公示。公示无异议或者异议在提名前处理完毕且不影响提名的，方可提名。"},{"i":55,"n":"第五十五条","txt":"提名者认为有关专家参加评审可能影响评审公正性的，可以申请其回避，并在提名时书面提出回避理由及相关证明材料。每项提名所提出的回避专家不超过3人。"},{"i":56,"n":"第五十六条","txt":"候选者应当遵纪守法，具有良好的科学道德和行为品德。有下列情形之一的，不得被提名国家科学技术奖： （一）在科学技术活动中，危害国家安全、损害社会公共利益、危害人体健康、违反伦理道德的； （二）有科研不端行为，按照国家有关规定被禁止参与国家科学技术奖励活动的； （三）被依法列为严重失信主体联合惩戒对象且处于惩戒期的； （四）受到党纪处分或者政务处分并处于影响期的； （五）其他依法被禁止参与国家科学技术奖励活动或者有科技部规定的其他情形的。 从严重失信主体名单移出、处分解除或者处罚执行完毕，按规定恢复参与国家科学技术奖励活动资格的，被提名时应当按要求提交有关情况说明。"},{"i":57,"n":"第五十七条","txt":"成果的知识产权或者完成单位、完成人员等方面存在直接影响国家科学技术奖评审的未解决争议并且相关争议正处于诉讼、仲裁或者行政裁决、行政复议程序中的，不得提名国家科学技术奖。"},{"i":58,"n":"第五十八条","txt":"依法应当取得有关行政许可方可实施应用的技术或者成果，如食品、药品、医疗器械、基因工程技术和产品、肥料、压力容器、通信设备等，在未取得许可之前，不得提名国家技术发明奖和国家科学技术进步奖。"},{"i":59,"n":"第五十九条","txt":"同一候选人或者同一科学技术内容同一年度只能被提名1项国家自然科学奖、国家技术发明奖或者国家科学技术进步奖。"},{"i":60,"n":"第六十条","txt":"已获得国家自然科学奖、国家技术发明奖或者国家科学技术进步奖的科学技术内容，不得重复提名。"},{"i":61,"n":"第六十一条","txt":"我国公民或者组织在国外以及我国公民在中国的外资机构，单独或者合作完成重大科学技术成果，符合《奖励条例》和本细则规定的条件，且成果的主要学术思想、技术路线和研究工作由我国公民或者组织提出和完成，并享有有关的知识产权，可以提名为国家科学技术奖候选者。"},{"i":62,"n":"第六十二条","txt":"外国人受聘于中国的法人机构，与中方合作完成重大科学技术成果，符合《奖励条例》和本细则规定的条件，且成果的知识产权属中方所有或者与中方共有，可以提名为国家自然科学奖、国家技术发明奖和国家科学技术进步奖的候选者。"},{"i":63,"n":"第六十三条","txt":"对科学技术进步、经济建设、社会发展和国家安全具有特别意义或者重大影响的科学技术成果，可以适时提名国家科学技术奖。"},{"i":64,"n":"第六十四条","txt":"奖励办公室负责对提名材料进行形式审查。形式审查合格的予以受理，不合格的不予受理。"},{"i":65,"n":"第六十五条","txt":"奖励办公室应当对受理的国家自然科学奖、国家技术发明奖、国家科学技术进步奖候选者及其候选项目进行公示。涉及国家安全的保密项目，按照相关保密规定，在适当范围内公示。"},{"i":66,"n":"第六十六条","txt":"受理的候选者及其候选项目如被发现存在本细则规定不得提名情形的，不提交评审。"},{"i":67,"n":"第六十七条","txt":"国家自然科学奖、国家技术发明奖和国家科学技术进步奖的评审工作实行异议制度。 任何单位或者个人对候选者及其候选项目及提名材料真实性等持有异议的，应当在公示期间向奖励办公室提出，逾期不予受理。"},{"i":68,"n":"第六十八条","txt":"异议者应当提交书面异议材料，并提供必要的证据材料。 提倡实名提出异议。个人实名提出异议的，应当提供有效联系方式；以单位名义提出异议的，应当加盖本单位公章。 异议者应当对异议材料内容的真实性负责。诬告陷害的，依法严肃处理。"},{"i":69,"n":"第六十九条","txt":"异议者不得擅自将异议材料直接提交评审组织或者评审专家；评审专家收到异议材料的，应当及时转交奖励办公室，不得提交评审组织讨论或者以任何方式转发、传播。"},{"i":70,"n":"第七十条","txt":"奖励办公室在接到异议材料后应当进行审查，对符合规定并能提供充分证据的异议，予以受理。"},{"i":71,"n":"第七十一条","txt":"为维护异议者的合法权益，奖励办公室、提名者，以及其他参与异议调查、处理的有关人员应当对异议者的身份予以保密；如需要公开的，应当事前征得异议者的同意。"},{"i":72,"n":"第七十二条","txt":"涉及候选项目的创新性、先进性、实用性、候选者排序及提名材料真实性等内容的学术类异议，由提名者配合奖励办公室进行调查核实，由奖励办公室组织审核处理。必要时，奖励办公室可以组织有关专家进行调查，提出处理建议。 涉及候选者的纪律类异议，由奖励办公室转交有关方面调查处理，并向监督委员会报告有关情况。 涉及国家安全的保密项目的异议，由有关部门处理，并将处理结果报奖励办公室。"},{"i":73,"n":"第七十三条","txt":"异议处理过程中，涉及异议的任何一方应当积极配合，不得推诿、延误和弄虚作假。候选者在规定时间内未按要求提供相关证明材料的，视为承认异议内容；异议者在规定时间内未按要求提供相关证明材料的，视为放弃异议。"},{"i":74,"n":"第七十四条","txt":"异议项目在规定时间内处理完毕且相关材料报送齐全的，可以提交本次评审。 提名者在规定时间内未按要求提交调查核实报告和提名者意见的，异议项目不提交本次评审，提名者应向奖励办公室说明原因并申请延期处理或者撤回提名。提名者既未按规定时间报送异议处理材料，也未提出延期申请或者撤回提名的，视为放弃提名，异议项目终止评审。 延期处理的异议项目经批准后，在下一次评审的相同节点前完成调查、核实且相关材料报送齐全的，可以提交后续评审程序；仍未能报送齐全相关材料的，终止评审。 终止评审的异议项目如再次以相同科学技术内容提名国家科学技术奖，应当同时提交异议处理材料。"},{"i":75,"n":"第七十五条","txt":"奖励办公室应当及时向监督委员会报告异议处理情况，将相关材料提交评审组织审议，并将审议结果通知异议者和提名者。 异议项目未通过评审的，异议处理程序自行终止，异议反映的相关问题按规定转有关方面处理。"},{"i":76,"n":"第七十六条","txt":"对受理的候选者及其候选项目，由奖励办公室提交相应评审组进行初评。 根据评审工作需要，在评审组初评前可以从评审专家库中按规则抽取专家进行通讯评审。"},{"i":77,"n":"第七十七条","txt":"通讯评审和评审组初评可以采取定量和定性评价相结合的方式进行。奖励办公室负责分类制订各奖种评价指标体系。"},{"i":78,"n":"第七十八条","txt":"奖励办公室应当公示通过初评的国家自然科学奖、国家技术发明奖、国家科学技术进步奖项目。涉及国家安全的保密项目，按照相关保密规定，在适当范围内公示。"},{"i":79,"n":"第七十九条","txt":"对通过初评的国家最高科学技术奖、国际科技合作奖候选者，及通过初评且没有异议或者虽有异议但已在规定时间内处理完毕的国家自然科学奖、国家技术发明奖、国家科学技术进步奖候选项目，提交相应奖种评审委员会进行评审。"},{"i":80,"n":"第八十条","txt":"奖励委员会对评审委员会的评审结果进行审定，作出各奖种获奖者和奖励等级的决议。"},{"i":81,"n":"第八十一条","txt":"国家科学技术奖的评审表决规则如下： （一）奖励委员会以会议方式进行审定。其中，对国家最高科学技术奖以及国家自然科学奖、国家技术发明奖和国家科学技术进步奖的特等奖、一等奖，以记名限额投票方式进行表决。 （二）评审委员会及评审组以会议方式进行评审，以记名限额投票方式进行表决。 （三）奖励委员会及评审委员会、评审组的表决应当有三分之二以上委员（专家）参加，表决结果有效。 （四）国家最高科学技术奖、国际科技合作奖，在奖励委员会、评审委员会表决时应当由到会委员的三分之二以上通过，在评审组表决时应当由到会专家的二分之一以上多数（不含二分之一）通过。 （五）国家自然科学奖、国家技术发明奖和国家科学技术进步奖的特等奖、一等奖应当由到会委员（专家）的三分之二以上通过，二等奖应当由到会委员（专家）的二分之一以上多数（不含二分之一）通过。"},{"i":82,"n":"第八十二条","txt":"国家科学技术奖评审实行回避制度，与被评审的候选者或者候选项目有重大利害关系的评审委员、评审专家应当回避。"},{"i":83,"n":"第八十三条","txt":"根据评审工作需要，奖励办公室可以组织专家对候选者及其候选项目进行实地考察，或者以适当方式征询有关部门、组织机构和海外同行专家等方面意见。考察情况和有关方面意见提交评审组织参考。"},{"i":84,"n":"第八十四条","txt":"国际科技合作奖的评审结果应当征询我国有关驻外使、领馆或者派出机构的意见。"},{"i":85,"n":"第八十五条","txt":"科技部对奖励委员会作出的各奖种获奖者和奖励等级的决议进行审核，报党中央、国务院批准。"},{"i":86,"n":"第八十六条","txt":"国家最高科学技术奖报请国家主席签署并颁发奖章、证书和奖金。 国家最高科学技术奖奖金数额为800万元，全部属获奖者个人所得。"},{"i":87,"n":"第八十七条","txt":"国家自然科学奖、国家技术发明奖、国家科学技术进步奖颁发证书和奖金。 国家自然科学奖、国家技术发明奖、国家科学技术进步奖奖金数额由科技部会同财政部另行公布。"},{"i":88,"n":"第八十八条","txt":"国际科技合作奖颁发奖章和证书。"},{"i":89,"n":"第八十九条","txt":"奖励委员会设立的监督委员会负责对国家科学技术奖的提名、评审和异议处理工作全程进行监督。 监督委员会委员人选由奖励办公室提出，经科技部审核后，报奖励委员会批准。"},{"i":90,"n":"第九十条","txt":"奖励办公室应当定期向监督委员会报告有关国家科学技术奖的提名、评审和异议处理的工作情况。必要时，监督委员会可以要求进行专题汇报。 监督委员会根据相关规则，通过现场监督、审议工作报告，以及经奖励委员会授权对重大问题组织专项调查等方式，履行监督职责。对在评审活动中违反《奖励条例》及本细则有关规定的个人、组织，可以建议有关方面给予处理。"},{"i":91,"n":"第九十一条","txt":"任何单位和个人发现国家科学技术奖的提名、评审和异议处理工作中存在问题的，可以向监督委员会进行举报和投诉。有关方面收到举报或者投诉材料的，应当及时转交监督委员会。监督委员会提出处理建议，提交评审组织审议。"},{"i":92,"n":"第九十二条","txt":"国家科学技术奖励工作实行科研诚信审核制度。科技部建立提名者和评审委员、评审专家、候选者的科研诚信严重失信行为数据库。奖励办公室在提名、评审等活动中对相关个人、组织的诚信情况进行审核。对惩戒期内的个人、组织，按程序取消其参与国家科学技术奖励活动的资格。"},{"i":93,"n":"第九十三条","txt":"禁止任何单位和个人进行可能影响国家科学技术奖提名和评审公平、公正的活动。对违规单位和个人，由科技部按照有关规定予以处理；相关候选者有责任的，取消其参评资格。"},{"i":94,"n":"第九十四条","txt":"对通过剽窃、侵占他人的发现、发明或者其他科学技术成果，或者以其他不正当手段骗取国家科学技术奖的个人、组织，尚未授奖的，由监督委员会提出建议，奖励办公室按程序报奖励委员会批准，取消其参评资格；已经授奖的，经奖励委员会审核，由科技部报党中央、国务院批准后撤销奖励，追回奖章、证书和奖金。按规定记入科研诚信严重失信行为数据库，由相关责任人所在单位或者主管部门依法给予处分。"},{"i":95,"n":"第九十五条","txt":"提名者提供虚假数据、材料，协助他人骗取国家科学技术奖的，由科技部予以通报批评；情节严重的，暂停或者取消其提名资格，按规定记入科研诚信严重失信行为数据库，并由相关责任人所在单位或者主管部门依法给予处分。"},{"i":96,"n":"第九十六条","txt":"参与国家科学技术奖评审工作的评审委员、评审专家违反评审工作纪律的，由科技部取消其评审委员、评审专家资格，按规定记入科研诚信严重失信行为数据库，并由其所在单位或者主管部门依法给予处分。"},{"i":97,"n":"第九十七条","txt":"参与国家科学技术奖评审组织工作的人员在评审活动中存在滥用职权、玩忽职守、徇私舞弊等违法违规违纪行为的，由科技部或者相关主管部门依法给予处分；涉嫌犯罪的，依法移送司法机关处理。"},{"i":98,"n":"第九十八条","txt":"参与国家科学技术奖励活动的单位和个人应当严格遵守保密要求。对违反保密规定的，由有关部门依法予以处理。"},{"i":99,"n":"第九十九条","txt":"对国家科学技术奖获奖者及其项目的宣传应当真实、客观、准确，不得以虚假、夸大、模糊宣传误导公众。获奖成果的应用不得损害国家利益、社会安全和人民健康。禁止使用国家科学技术奖名义牟取不正当利益。 对违反前款规定产生严重后果的，由有关部门依法给予处理。"},{"i":100,"n":"第一百条","txt":"国家科学技术奖的提名、评审、授予的经费管理，按照国家有关规定执行。"},{"i":101,"n":"第一百零一条","txt":"本细则由科技部负责解释。"},{"i":102,"n":"第一百零二条","txt":"本细则自2025年6月27日起施行，2008年公布的《国家科学技术奖励条例实施细则》（科学技术部令第13号）同时废止。"}],"guojiakejijihuashishizhongkeyanbuduanxingweichulibe52d09":[{"i":1,"n":"第一条","txt":"为了加强国家科技计划实施中的科研诚信建设，根据《中华人民共和国科学技术进步法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"对科学技术部归口管理的国家科技计划项目的申请者、推荐者、承担者在科技计划项目申请、评估评审、检查、项目执行、验收等过程中发生的科研不端行为（以下称科研不端行为）的查处，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称的科研不端行为，是指违反科学共同体公认的科研行为准则的行为，包括： （一）在有关人员职称、简历以及研究基础等方面提供虚假信息； （二）抄袭、剽窃他人科研成果； （三）捏造或篡改科研数据； （四）在涉及人体的研究中，违反知情同意、保护隐私等规定； （五）违反实验动物保护规范； （六）其他科研不端行为。"},{"i":4,"n":"第四条","txt":"科学技术部、行业科技主管部门和省级科技行政部门（以下简称项目主持机关）、国家科技计划项目承担单位（以下称项目承担单位）是科研不端行为的调查机构，根据其职责和权限对科研不端行为进行查处。"},{"i":5,"n":"第五条","txt":"调查和处理科研不端行为应遵循合法、客观、公正的原则。 在调查和处理科研不端行为中，要正确把握科研不端行为与正当学术争论的界限。"},{"i":6,"n":"第六条","txt":"任何单位和个人都可以向科学技术部、项目主持机关、项目承担单位举报在国家科技计划项目实施过程中发生的科研不端行为。 鼓励举报人以实名举报。"},{"i":7,"n":"第七条","txt":"科学技术部负责查处影响重大的科研不端行为。必要时，科学技术部会同其他部门联合进行查处。 科学技术部成立科研诚信建设办公室（以下称办公室），负责科研诚信建设的日常工作。其主要职责是： （一）接受、转送对科研不端行为的举报； （二）协调项目主持机关和项目承担单位的调查处理工作； （三）向被处理人或实名举报人送达科学技术部的查处决定； （四）推动项目主持机关、项目承担单位的科研诚信建设； （五）研究提出加强科研诚信建设的建议； （六）科技部交办的其他事项。"},{"i":8,"n":"第八条","txt":"项目主持机关负责对其推荐、主持、受委托管理的科技计划项目实施中发生的科研不端行为进行调查和处理。 项目主持机关应当建立健全科研诚信建设工作体系。"},{"i":9,"n":"第九条","txt":"项目承担单位负责对本单位承担的国家科技计划项目实施中发生的科研不端行为进行调查和处理。 承担国家科技计划项目的科研机构、高等学校应当建立科研诚信管理机构，建立健全调查处理科研不端行为的制度。科研机构、高等学校的科研诚信制度建设，作为国家科技计划项目立项的条件之一。"},{"i":10,"n":"第十条","txt":"国家科技计划项目承担者在申请项目时应当签署科研诚信承诺书。"},{"i":11,"n":"第十一条","txt":"项目承担单位应当根据其权限和科研不端行为的情节轻重，对科研不端行为人做出如下处罚： （一）警告； （二）通报批评； （三）责令其接受项目承担单位的定期审查； （四）禁止其一定期限内参与项目承担单位承担或组织的科研活动； （五）记过； （六）降职； （七）解职； （八）解聘、辞退或开除等。"},{"i":12,"n":"第十二条","txt":"项目主持机关应当根据其权限和科研不端行为的情节轻重，对科研不端行为人做出如下处罚： （一）警告； （二）在一定范围内通报批评； （三）记过； （四）禁止其在一定期限内参加项目主持机关主持的国家科技计划项目； （五）解聘、开除等。"},{"i":13,"n":"第十三条","txt":"科学技术部应当根据其权限和科研不端行为的情节轻重，对科研不端行为人做出如下处罚： （一）警告； （二）在一定范围内通报批评； （三）中止项目，并责令限期改正； （四）终止项目，收缴剩余项目经费，追缴已拨付项目经费； （五）在一定期限内，不接受其国家科技计划项目的申请。"},{"i":14,"n":"第十四条","txt":"项目主持机关对举报的科研不端行为不开展调查、无故拖延调查的，科学技术部可以停止该机关在一定期限内主持、管理相关项目的资格。"},{"i":15,"n":"第十五条","txt":"被调查人有下列情形之一的，从轻处罚： （一）主动承认错误并积极配合调查的； （二）经批评教育确有悔改表现的； （三）主动消除或者减轻科研不端行为不良影响的； （四）其他应从轻处罚的情形。"},{"i":16,"n":"第十六条","txt":"被调查人有下列情形之一的，从重处罚： （一）藏匿、伪造、销毁证据的； （二）干扰、妨碍调查工作的； （三）打击、报复举报人的； （四）同时涉及多种科研不端行为的。"},{"i":17,"n":"第十七条","txt":"举报人捏造事实、故意陷害他人的，一经查实，在一定期限内，不接受其国家科技计划项目的申请。"},{"i":18,"n":"第十八条","txt":"科研不端行为涉嫌违纪、违法的，移交有关机关处理。"},{"i":19,"n":"第十九条","txt":"调查机构接到举报后，应进行登记。 被举报的行为属于本办法规定的科研不端行为，且事实基本清楚，并属于本机构职责范围的，应予以受理；不属于本机构职责范围的，转送有关机构处理。 不符合受理条件不予受理的，应当书面通知实名举报人。"},{"i":20,"n":"第二十条","txt":"调查机构应当成立专家组进行调查。专家组包括相关领域的技术专家、法律专家、道德伦理专家。项目承担单位为调查机构的，可由其科研诚信管理机构进行调查。 专家组成员或调查人员与举报人、被举报人有利害关系的，应当回避。"},{"i":21,"n":"第二十一条","txt":"在有关举报未被查实前，调查机构和参与调查的人员不得公开有关情况；确需公开的，应当严格限定公开范围。"},{"i":22,"n":"第二十二条","txt":"被调查人、有关单位及个人有义务协助提供必要证据，说明事实真相。"},{"i":23,"n":"第二十三条","txt":"调查工作应当按照下列程序进行： （一）核实、审阅原始记录，多方面听取有关人员的意见； （二）要求被调查人提供有关资料，说明事实情况； （三）形成初步调查意见，并听取被调查人的陈述和申辩； （四）形成调查报告。"},{"i":24,"n":"第二十四条","txt":"科研不端行为影响重大或争议较大的，可以举行听证会。需经过科学试验予以验证的，应当进行科学试验。 听证会和科学试验由调查机构组织。"},{"i":25,"n":"第二十五条","txt":"专家组完成调查工作后，向调查机构提交调查报告。 调查报告应当包括调查对象、调查内容、调查过程、主要事实与证据、处理意见。"},{"i":26,"n":"第二十六条","txt":"调查机构根据专家组的调查报告，做出处理决定。"},{"i":27,"n":"第二十七条","txt":"调查机构应在做出处理决定后10日内将处理决定送被处理人、实名举报人。"},{"i":28,"n":"第二十八条","txt":"项目主持机关、项目承担单位为调查机构的，应当在做出处理决定后10日内将处理决定送科学技术部科研诚信建设办公室备案。 科学技术部将处理决定纳入国家科技计划信用信息管理体系，作为科技计划实施和管理的参考。"},{"i":29,"n":"第二十九条","txt":"被处理人或实名举报人对调查机构的处理决定不服的，可以在收到处理决定后30日内向调查机构或其上级主管部门提出申诉。 科学技术部和国务院其他部门为调查机构的，申诉应向调查机构提出。"},{"i":30,"n":"第三十条","txt":"收到申诉的机构经审查，认为原处理决定认定事实不清，或适用法律、法规和有关规定不正确的，应当进行复查。 复查机构应另行组成专家组进行调查。复查程序按照本办法规定的调查程序进行。 收到申诉的机构决定不予复查的，应书面通知申诉人。"},{"i":31,"n":"第三十一条","txt":"申诉人对复查决定仍然不服，以同一事实和理由提出申诉的，不予受理。"},{"i":32,"n":"第三十二条","txt":"被处理人对有关行政机关的处罚决定不服的，可以依照《中华人民共和国行政复议法》的规定，申请复议。 属于人事和劳动争议的，依照有关规定处理。"},{"i":33,"n":"第三十三条","txt":"在国家科技奖励推荐、评审过程中发生的科研不端行为，参照本规定执行。"},{"i":34,"n":"第三十四条","txt":"本办法自2007年1月1日起施行。"}],"guojiakejijihuaguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为了规范国家科技计划管理，明确设立国家科技计划的基本程序和要求，强化国家科技计划管理的责任机制，建立国家科技计划管理的基本制度，根据《中华人民共和国科学技术进步法》的有关要求，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的国家科技计划是指：根据国家科技发展规划和战略安排的，以中央财政支持或以宏观政策调控、引导，由政府行政部门组织和实施的科学研究与试验发展活动及相关的其它科学技术活动。国家科技计划是国家解决社会和经济发展中涉及的重大科技问题、实现科技资源合理配置的重要手段。"},{"i":3,"n":"第三条","txt":"国家科技计划管理应遵循以下基本原则： （一）制定、实施和管理国家科技计划必须依法进行； （二）国家科技计划设立和项目选择必须保证国家目标的实现； （三）简化管理程序，加强国家科技计划管理的政策、制度和规律研究，提高国家科技计划管理的效率； （四）建立国家科技计划的管理公开制度，促进公众对国家科技计划管理的了解和参与，提高管理决策的公开性和公正性。"},{"i":4,"n":"第四条","txt":"本规定适用于： （一）涉及国家科技计划体系中以中央财政投入为主的国家高技术研究发展计划（863计划）、科技攻关计划、基础研究计划、研究开发能力条件建设计划、科技产业化环境建设计划等； （二）根据国民经济和社会发展需要而新设立的国家科技计划。"},{"i":5,"n":"第五条","txt":"科技部根据国家科技发展战略、科技发展规划，结合国民经济和社会发展以及国家安全等对科技的现实需求，适时向国务院提出需由中央财政新增经费支持而设立的国家科技计划的建议。"},{"i":6,"n":"第六条","txt":"科技部应当在组织国务院有关部门、地方科技行政管理部门和科技界、经济界权威专家对国家科技计划建议讨论和咨询后，起草设立国家科技计划的建议报告草案。 国家科技计划的建议报告草案应当符合以下基本要求： （一）拟设立的国家科技计划目标、任务和重点必须与国民经济和社会发展的总体部署和安排相协调，并符合国家产业政策、科技政策的要求； （二）应对国家科技计划的宗旨、目标、任务、范围、内容、管理和运行等明确地予以界定，并说明该计划同现有的其他国家科技计划的关系； （三）应提供该计划的资金预算，包括所需要的资金规模和资金来源，并说明该计划的实施期限（周期）； （四）应提供该计划相关领域的技术发展趋势分析和有关背景资料。"},{"i":7,"n":"第七条","txt":"科技部应将建议报告草案提交由科技、经济和管理专家参加的、独立于行政管理部门的高层咨询委员会咨询，经高层咨询委员会对建议报告草案咨询审议并通过后，由科技部按程序报送国务院批准。 高层咨询委员会的专家由科技部聘任。"},{"i":8,"n":"第八条","txt":"国家科技计划在计划周期内应具有相对的稳定性，其宗旨、目标任务的重大调整及撤销或更名，应经科技部审议后报国务院批准。"},{"i":9,"n":"第九条","txt":"利用现有中央财政经费而新设立的国家科技计划由科技部部务会讨论通过后即可实施。"},{"i":10,"n":"第十条","txt":"本规定第四条（一）所列的现有各类国家科技计划的调整和变化不适用于本章规定。"},{"i":11,"n":"第十一条","txt":"各类国家科技计划启动实施前，应当制定具体的管理办法，并可根据管理的需要，制定有关实施细则。各类国家科技计划的管理办法在计划实施期内可以通过制定有关补充规定的方式予以修订。"},{"i":12,"n":"第十二条","txt":"各类国家科技计划的管理办法由科技部专项计划部门组织起草。起草单位应将草案及其说明、各方面对草案的不同意见和其他有关资料报送科技部综合计划部门。"},{"i":13,"n":"第十三条","txt":"科技部综合计划部门负责对各类国家科技计划的管理办法草案进行审查，起草审查报告，并按科技部规定的有关程序办理。 审查报告应当包括以下内容： （一）对草案的审查结果和对草案主要问题的说明； （二）征求意见的范围及有关方面对草案的不同意见； （三）对不同意见的处理建议和对草案的修改意见。"},{"i":14,"n":"第十四条","txt":"各类国家科技计划管理办法由科技部部长签发，在指定报刊上刊登予以公布。"},{"i":15,"n":"第十五条","txt":"各类国家科技计划管理办法的实施细则和补充规定应依照本规定第十二条至第十四条的规定程序执行。"},{"i":16,"n":"第十六条","txt":"根据科技政策和有关法律法规，针对计划管理工作的实际需求，各类国家科技计划管理办法可以就下列事项做出具体规定： （一）计划的目标、宗旨、性质、范围、周期等； （二）计划的组织管理。主要涉及管理模式、组织结构、责任主体及其相应的责任、权利和义务； （三）计划实施的基本程序和相应的管理要求； （四）计划经费管理的有关事项，主要包括经费渠道、预算编制和经费下达的程序以及经费使用、监督和检查； （五）计划的有效期。"},{"i":17,"n":"第十七条","txt":"国家科技计划管理和实施的责任主体分为以下三类： （一）主管国家科技计划的科技行政管理部门； （二）经科技行政管理部门授权或委托，行使部分计划管理权并负责项目组织实施管理的机构； （三）国家科技计划项目承担者。"},{"i":18,"n":"第十八条","txt":"科技部在国家科技计划管理中的主要职能是： （一）确定计划项目并优选项目承担者； （二）确定计划项目经费额度，并根据合同或任务书确定的额度和时限下达经费； （三）对项目的计划进度进行监督检查和验收。对于不能恰当履行合同义务的项目承担者，应通报批评，并视具体情况中止或取消合同； （四）制定特定条件下的快速决策程序或紧急处置程序，处理国务院交办的紧急任务或其他重要事项。"},{"i":19,"n":"第十九条","txt":"根据国家科技计划管理的需要，科技部可选择符合一定条件的部门、机构行使部分计划管理职能，通过签定合同、协议等方式建立正式的授权或委托关系，并明确相应的职责和权限。 被授权或委托负责项目组织实施管理的机构必须做到： （一）只能在被授权或委托的范围内行使职权，不得越权管理； （二）接受科技部的监督和检查； （三）在行使国家科技计划管理职权的同时，不得利用被授权或委托的管理职能从事营利性活动。"},{"i":20,"n":"第二十条","txt":"国家科技计划项目的承担者具有以下责任和义务： （一）严格履行国家科技计划项目合同或任务书，遵守国家科技计划管理的有关规定，完成项目计划任务。对于违约或违反管理规定的单位和个人，应承担相应的责任并根据有关规定接受处罚； （二）按要求向国家科技行政管理部门提供各种报告，接受科技部及其授权或委托机构的监督和评估； （三）客观、及时向有关上级部门反映国家科技计划管理中的各类问题。"},{"i":21,"n":"第二十一条","txt":"国家科技计划管理应在严格执行《科学技术保密规定》等科技保密法规的基础上，建立管理公开制度。国家科技计划管理公开制度的基本内容包括公告、共享、查询三个方面。 （一）公告：科技部应通过一定的程序向公众告知国家科技计划的有关信息。在管理公开制度中，除了涉及国家机密和计划制定时确定的保密内容外，应对公告的信息内容、方式、范围、信息更新时间及争议期的设定等事项做出具体规定； （二）共享：科技部应建立计划的数据库和档案系统，并按一定的标准制定关于数据和档案的保存、使用和共享的规定，包括数据和档案的基本框架、内容、保存的方式和年限、共享的条件、申请使用的要求等； （三）查询：国家科技计划管理涉及的项目承担者有权通过相应的程序，查询有关信息。专项计划管理部门应根据国家科技计划的特点，制定信息查询的内容、申请查询的程序及回复查询要求的时限等有关规定。"},{"i":22,"n":"第二十二条","txt":"国家科技计划必须建立报告制度，明确规定报告的内容、要求和报告期。国家科技计划管理的基本报告类型如下： （一）进度报告：国家科技计划项目承担者、被授权或委托负责项目组织实施管理机构有责任定期按要求向科技部专项、综合计划部门报告计划项目执行情况； （二）统计调查报告：国家科技计划项目承担者需如实填报由科技部制发的统计调查表； （三）调整报告：国家科技计划项目承担者要求调整合同目标、变更项目主持人及延期验收等，需及时向科技部专项计划部门报告；科技部专项计划部门应对其调整要求明确签署意见； （四）重要事件报告：如果计划项目取得重大进展、突破，或发生可能影响合同按期完成的重大事件或难以协调的问题，项目承担者及被授权或委托负责项目组织实施管理机构有责任向科技部专项计划部门及时报告； （五）财务报告：项目承担者有责任定期向科技部专项、综合计划部门报告经费到位及使用情况，按要求提交项目年度财务决算；"},{"i":23,"n":"第二十三条","txt":"国家科技计划管理实行回避制度，具体回避内容如下： （一）国家科技计划管理者的回避。在立项、经费分配、项目验收、争议处理等环节，对于涉及科技行政管理部门、管理人员以及授权或委托机构自身利益的事项，当事者有责任主动提出声明，并实行回避； （二）选择咨询专家的回避。以下人员不宜选择为咨询专家：与咨询对象有利益关系的人、咨询对象因正当理由而事先正式申请希望回避的人； （三）选择中介机构的回避。委托中介机构进行招标投标、评估等任务时，若中介机构与国家科技计划管理和实施有关责任主体之间存在某种形式的经济利益关系，应实行回避。"},{"i":24,"n":"第二十四条","txt":"科技部可根据计划管理的需要建立内部监督和外部评估制度，明确规定执行监督与评估的时间、程序、方式以及各方面的责任，并在项目合同及任务书中具体约定。除特殊情况，任何人不得在监督与评估制度的规定之外随意执行监督、评估行为。"},{"i":25,"n":"第二十五条","txt":"本规定发布之前已制定的各类国家科技计划管理办法如与本规定不相符的，应当按本规定重新制定或修订。"},{"i":26,"n":"第二十六条","txt":"本规定自发布之日起施行。"}],"guojiakejijihuaxiangmuguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范国家科技计划项目管理，提高科技计划项目管理的效率，保证科技计划项目管理的公开、公正和科学，制定本办法。"},{"i":2,"n":"第二条","txt":"国家科技计划项目（以下称项目）是指在国家科技计划中实施安排，由单位或个人承担，并在一定时间周期内进行的科学技术研究开发活动。"},{"i":3,"n":"第三条","txt":"国家科技计划项目管理实行依法管理、规范权限、明确职责、管理公开、精简高效的原则，并严格按《国家科技计划管理暂行规定》和相关各类国家科技计划管理办法中的有关规定组织实施。"},{"i":4,"n":"第四条","txt":"本办法主要适用于以中央财政投入为主的各类国家科技计划的项目立项、实施管理、项目验收和专家咨询等项目管理工作。"},{"i":5,"n":"第五条","txt":"项目立项一般应包括申请、审批、签约三个基本程序。"},{"i":6,"n":"第六条","txt":"科技部专项计划部门在启动项目申请工作前，应根据科技发展规划和战略，发布项目指南或优先领域，并依据计划的性质、宗旨和功能定位，明确申请项目的选择范围、领域、性质、规模、目标方向等，确定项目申报的时间、渠道、方式。"},{"i":7,"n":"第七条","txt":"项目指南和优先领域已明确项目目标和任务，并符合招标投标条件的，应当依据《科技项目招标投标暂行管理办法》中的相关规定执行。"},{"i":8,"n":"第八条","txt":"申请项目的申请者（包括单位或个人）应当符合以下基本条件： （一）符合该计划对申请者的主体资格（包括法人性质、经济性质、国籍）等方面要求； （二）在相关研究领域和专业应具有一定的学术地位和技术优势； （三）具有为完成项目必备的人才条件和技术装备； （四）具有与项目相关的研究经历和研究积累； （五）具有完成项目所需的组织管理和协调能力； （六）具有完成项目的良好信誉度。"},{"i":9,"n":"第九条","txt":"申请项目应符合国家科技、经济和社会发展战略，符合国家产业政策和科技政策，符合国家科技发展规划、计划的总体部署和安排。"},{"i":10,"n":"第十条","txt":"申请项目应提供以下三部分材料： （一）项目申请表（由科技部统一印制）； （二）项目建议书（由申请者按照科技部要求的内容框架编写）； （三）项目建议书的附件（与项目建议书内容有关的证明材料、专家评议意见、相关单位的项目推荐意见）。"},{"i":11,"n":"第十一条","txt":"项目建议书的内容和框架一般应包括： （一）立项的背景和意义； （二）国内外研究现状和发展趋势； （三）现有研究基础、特色和优势； （四）应用或产业化前景、科技发展或市场需求； （五）研究内容与预期目标； （六）研究方案、技术路线、组织方式与课题分解； （七）年度计划内容； （八）主要研究人员和单位简况及具备的条件； （九）经费预算； （十）有关上级单位或评估机构的意见。 除满足上述条件外，不同类型项目的建议书可有所侧重，或根据需要增加新的内容。"},{"i":12,"n":"第十二条","txt":"项目申请，必须严格按各类国家科技计划管理办法规定的渠道、方式、时间执行。申请渠道可按行政隶属关系逐级汇总、审核；或由申请者经有关行业和地方科技行政管理部门推荐后直接申报，最终由科技部专项计划部门受理。"},{"i":13,"n":"第十三条","txt":"经科技部专项计划部门或由其委托的有关机构对项目建议书进行讨论、咨询和审查后，符合条件并通过审查的项目，可以进入可行性论证或评估。"},{"i":14,"n":"第十四条","txt":"科技部专项计划部门负责组织或委托有关机构进行项目可行性报告的论证或评估工作。"},{"i":15,"n":"第十五条","txt":"可行性报告内容和框架一般应包括： （一）项目的背景和意义； （二）国内外研究开发现状和发展趋势（包括知识产权状况）； （三）拟承担单位的技术优势和条件； （四）项目目标、研究内容和关键技术； （五）技术路线方案、课题分解； （六）经费的预算； （七）年度进度和目标； （八）预期成果； （九）项目负责人的技术水平和组织管理能力介绍； （十）有关上级单位的意见。"},{"i":16,"n":"第十六条","txt":"可行性论证或评估报告应对项目给出可行、不可行或需作复议的明确结论意见，并交科技部专项计划部门负责审核。对论证结论“需作复议”的项目，申请者应对有关内容进行必要的修改，然后将修改完善后的论证报告送科技部专项计划部门进行复审。"},{"i":17,"n":"第十七条","txt":"对通过可行性论证审核的项目，科技部将以部发文的形式给予批复，并根据管理公开制度在相关范围或媒体向社会公众发布列入计划项目公告。"},{"i":18,"n":"第十八条","txt":"对符合评估条件的项目，应当依据《科技评估管理暂行办法》中的相关规定执行。"},{"i":19,"n":"第十九条","txt":"列入国家科技计划的项目，科技部专项计划部门应根据不同计划的性质，通过合同或计划任务书形式，确定项目各方的权利和义务。"},{"i":20,"n":"第二十条","txt":"列入国家科技计划的项目实行统一编号，有关标准由科技部另行制定。"},{"i":21,"n":"第二十一条","txt":"项目的合同或计划任务书的文本由科技部专项计划部门依据有关法律法规统一设计和印制，由项目承担者依据批准的项目可行性研究报告填写合同或计划任务书。经签约各方共同审核后，方可履行签订手续。"},{"i":22,"n":"第二十二条","txt":"合同或计划任务书应包括以下内容： （一）项目编号、项目名称和项目密级； （二）合同甲方或计划任务下达部门； （三）合同乙方或计划任务承担单位（人）和任务责任人； （四）立项背景与意义； （五）主要任务、关键技术； （六）验收考核指标； （七）实施方案、技术路线与年度计划进度； （八）经费预算和用途； （九）承担单位的保障条件与经费配套； （十）科技成果及其知识产权的归属和管理； （十一）涉密项目的科技保密义务； （十二）争议解决方法。"},{"i":23,"n":"第二十三条","txt":"根据国家科技计划的不同性质和目标，合同或计划任务书可增加有关科技行政管理部门作为第三方，第三方有保证任务完成的责任和监督项目实施的权力。"},{"i":24,"n":"第二十四条","txt":"对于执行结果可测的项目，合同中的研究和考核指标，必须量化；对于执行结果不可测项目，合同中的研究和考核指标，必须有准确含义的定性说明。"},{"i":25,"n":"第二十五条","txt":"对项目执行中的有关国拨经费、条件保障和经费配套条款，必须明确签约各方的责任，并明确出现一方违约时，其他方应有的权力。"},{"i":26,"n":"第二十六条","txt":"合同或计划任务书由科技部专项计划部门核准后方能生效。"},{"i":27,"n":"第二十七条","txt":"对国务院交办或科技部决定所需紧急立项任务，可按各类国家科技计划管理办法所规定的紧急立项程序条款进行立项。"},{"i":28,"n":"第二十八条","txt":"国家科技计划一般按项目、课题两级管理，不设课题的可按项目进行管理。"},{"i":29,"n":"第二十九条","txt":"科技部专项计划部门和授权或委托的项目组织实施管理机构负责项目的实施和管理。"},{"i":30,"n":"第三十条","txt":"科技部专项计划部门在项目管理中的基本职责是： （一）确定项目组织实施的管理机构和管理模式； （二）审聘项目专家咨询委员会； （三）审查项目年度执行报告、项目完成后的总结报告和项目经费的预、决算； （四）组织或委托其他组织或机构进行项目的中期检查或评估； （五）组织协调并处理项目执行中需要协调、处理的问题。"},{"i":31,"n":"第三十一条","txt":"受科技部专项计划部门授权或委托，项目组织实施管理机构对项目目标的实现、项目任务的完成、关键技术的突破及涉密项目的科技保密等，承担组织实施的责任。 项目组织实施管理机构的基本职责是： （一）匹配项目约定支付的科技经费； （二）定期报告项目年度执行情况和年度经费决算，协同科技部专项计划部门进行项目执行情况的检查或评估，协调项目的实施，进行技术保密的实施管理； （三）实施项目的统计调查，督促项目科技成果完成单位办理科技成果登记手续； （四）向科技部专项计划部门报告项目实施中难以协调的问题。"},{"i":32,"n":"第三十二条","txt":"项目承担者的基本职责是： （一）严格执行合同或计划任务书，完成项目目标任务； （二）真实报告项目年度完成情况和经费年度决算； （三）接受科技部专项计划部门和项目组织实施管理机构对项目执行情况的监督检查； （四）接受并配合科技部委托的有关中介机构所进行的中期评估或验收评估，准确提供相关数据和资料； （五）及时报告项目执行中出现的重大事项； （六）填报由科技部制发的科技计划统计调查表和科技成果登记表； （七）报告项目执行中知识产权管理情况和提出知识产权保护的建议。"},{"i":33,"n":"第三十三条","txt":"项目实施中必须建立年度执行情况报告制度，如遇目标调整、内容更改、项目负责人变更、关键技术方案的变更、不可抗拒的因素等对项目执行产生重大影响的情况必须及时报告。 项目承担者必须在每年1月中旬提交项目上年度执行情况，经项目组织实施管理机构审核汇总后，于2月中旬报科技部综合计划部门和专项计划部门。"},{"i":34,"n":"第三十四条","txt":"项目实施时限一般为三年，并可以逐年滚动立项，超过三年的项目，应进行中期检查或中期评估。项目执行中因人为因素致使项目难以实施或在预定时间内不能完成合同，科技部专项计划部门可以采取警告、通报批评，并视情况直至取消合同任务的处罚。"},{"i":35,"n":"第三十五条","txt":"各类国家科技计划必须建立相互兼容的数据库，实现信息、数据资源共享。统计、调查和成果登记的科技指标应有一致的概念和内涵，指标及数据具有可比性。"},{"i":36,"n":"第三十六条","txt":"各类国家科技计划可根据计划自身的特点，制定专门的验收管理办法。"},{"i":37,"n":"第三十七条","txt":"项目验收的组织工作，由科技部专项计划部门委托项目组织实施管理机构组织进行。 对跨行业（部门）、跨省市的重大项目验收，应由科技部专项计划部门负责主持。"},{"i":38,"n":"第三十八条","txt":"项目验收以批准的项目可行性报告、合同文本或计划任务书约定的内容和确定的考核目标为基本依据，对项目产生的科技成果水平、应用效果和对经济社会的影响、实施的技术路线、攻克关键技术的方案和效果、知识产权的形成和管理、项目实施的组织管理经验和教训、科技人才的培养和队伍的成长、经费使用的合理性等应作出客观的、实事求是的评价。"},{"i":39,"n":"第三十九条","txt":"项目验收程序，一般应符合下列要求： （一）项目验收工作需在合同完成后半年内完成； （二）项目的承担者，在完成技术、研发总结基础上，向项目组织实施管理机构提出验收申请并提交有关验收资料及数据； （三）项目组织实施管理机构审查全部验收资料及有关证明，合格的向科技部专项计划部门提出项目验收申请报告； （四）科技部专项计划部门批复验收申请，并委托项目组织实施管理机构组织验收，验收一般应委托有关社会中介服务机构对研究开发成果完成客观评价或鉴定后进行； （五）科技部专项计划部门负责批准项目的验收结果。"},{"i":40,"n":"第四十条","txt":"项目承担者申请验收时应提供以下验收文件、资料，以及一定形式的成果（样机、样品等），供验收组织或评估机构审查： （一）项目合同书或项目计划任务书； （二）科技部专项计划部门对项目的批件或有关批复文件； （三）项目验收申请表； （四）科技成果鉴定报告； （五）项目研发工作总结报告； （六）项目研发技术报告； （七）项目所获成果、专利一览表（含成果登记号、专利申请号、专利号等）； （八）研制样机、样品的图片及数据； （九）有关产品测试报告或检测报告及用户使用报告； （十）建设的中试线、试验基地、示范点一览表、图片及数据； （十一）购置的仪器、设备等固定资产清单； （十二）项目经费的决算表； （十三）项目验收信息汇总表。"},{"i":41,"n":"第四十一条","txt":"项目组织实施管理机构在组织项目验收时，可临时组织项目验收小组，有关专家成员由项目组织实施管理机构提出并经科技部专项计划部门批准后聘任。项目验收小组应由熟悉了解专业技术、经济和企业管理等方面专家组成，专家人数一般不少于11人。 验收小组的全体成员应认真阅读项目验收全部资料，必要时，应进行现场实地考察，收集听取相关方面的意见，核实或复测相关数据，独立、负责任地提出验收意见和验收结论。"},{"i":42,"n":"第四十二条","txt":"参与项目验收工作的评估机构，应遵照《科技评估管理暂行办法》有关规定执行。"},{"i":43,"n":"第四十三条","txt":"项目验收方式和验收活动安排，应在验收工作开始前15日由组织验收部门通知被验收者。被验收者应对验收报告、资料、数据及结论的真实性、可靠性负责。验收小组/评估机构，应对验收结论或评价的准确性负责，应维护验收项目的知识产权和保守其技术秘密。"},{"i":44,"n":"第四十四条","txt":"项目组织实施管理机构根据验收小组/评估机构的验收意见，提出“通过验收”或“需要复议”或“不通过验收”的结论建议，由科技部专项计划部门审定后以文件正式下达。 被验收项目存在下列情况之一者，不能通过验收： （一）完成合同或计划任务书任务不到85%； （二）预定成果未能实现或成果已无科学或实用价值； （三）提供的验收文件、资料、数据不真实； （四）擅自修改对合同或计划任务书考核目标、内容、技术路线； （五）超过合同或计划任务书规定期限半年以上未完成任务，事先未作说明。"},{"i":45,"n":"第四十五条","txt":"需要复议的验收项目，应在接到通知30日内提出复议申请。 未通过验收的项目，承担者接到通知半年之内，经整改完善有关项目计划及文件资料后，可再次提出验收申请。如再次未通过验收，项目承担者三年内不得再承担国家科技计划项目。"},{"i":46,"n":"第四十六条","txt":"除科技部事先合同约定科技成果归国家所有外，项目所产生科技成果的知识产权归科技成果完成者所有，具体办法另行规定。"},{"i":47,"n":"第四十七条","txt":"项目产生科技成果后，应当按照科学技术保密、科技成果登记、知识产权保护、技术合同认定登记、科学技术奖励等有关规定和办法执行。"},{"i":48,"n":"第四十八条","txt":"充分发挥专家咨询参谋作用，提高项目管理工作的科学性、公正性及社会参与程度，项目管理应当引入专家咨询机制。"},{"i":49,"n":"第四十九条","txt":"国家科技计划在项目的可行性论证、立项审查、招标投标、评估、中期检查、项目验收等环节可以组织专家咨询活动。专家咨询意见应作为科技管理与决策的参考依据。"},{"i":50,"n":"第五十条","txt":"科技部专项计划部门应根据各类国家科技计划特点确定咨询专家条件、构成，咨询专家应具备的基本条件是： （一）具有良好的科学道德和职业道德，能够客观、公正、实事求是地提出咨询意见； （二）熟悉咨询项目所在领域或行业的科技经济发展状况，了解科技活动的特点与规律，在本领域或行业内具有较高的权威性。 咨询专家的群体组成应具有代表性和互补性。人数、年龄和知识构成应具有相对合理性。专家群体应熟悉相关领域或行业的发展状况，掌握技术、经济、市场、产业政策等方面情况，并具有一定综合分析判断能力。"},{"i":51,"n":"第五十一条","txt":"以下人员不宜作为咨询专家选聘： （一）与咨询对象有利益关系的人员； （二）咨询对象因正当理由而事先正式书面申请希望回避的人员； （三）在以往咨询活动中有不良记录的人员。"},{"i":52,"n":"第五十二条","txt":"科技部专项计划部门、项目组织实施管理机构应在聘请专家时向专家阐明咨询的目的、咨询的工作原则、咨询专家的职责与权利，明确咨询的任务与要求。专家同意后，方可聘为咨询专家，正式参与咨询活动。"},{"i":53,"n":"第五十三条","txt":"科技部专项计划部门、项目组织实施管理机构应向咨询专家提供与咨询工作相关的资料、信息和数据，提供必要的工作条件和费用，对有关咨询内容和项目背景作必要的介绍与说明，还应当对咨询专家的具体意见负有保密责任。"},{"i":54,"n":"第五十四条","txt":"科技部专项计划部门、项目组织实施管理机构不得向咨询专家施加倾向性影响，不得故意引导专家的咨询意见。不得伪造、修改咨询专家意见。不得向咨询对象及与计划管理决策无关的任何单位或个人扩散咨询专家和咨询意见。采用咨询专家意见后的决策行为，其责任由决策者承担。"},{"i":55,"n":"第五十五条","txt":"咨询专家在为项目进行咨询的过程中，必须遵守以下规范： （一）应坚持实事求是的原则，独立、客观、公正地提供个人负责任的意见，不受任何影响公正性因素的干扰，应按照管理者的要求按时按质地完成咨询任务； （二）应维护咨询对象的知识产权和技术秘密，应妥善保存咨询材料并在咨询活动结束后按要求将其全部退还管理者，不得复制与咨询有关的材料，不得向管理者以外的单位或个人扩散咨询有关情况； （三）当咨询事项与专家有利益关系时，必须主动向管理者申明并回避； （四）在咨询期间，未经组织者允许，咨询专家个人不得就咨询事项与咨询对象及相关人员进行接触。更不得以各种方式收取咨询对象的报酬和费用。"},{"i":56,"n":"第五十六条","txt":"在咨询活动中若咨询专家存在违规行为，科技部专项计划部门可视情节轻重，采取记录其信誉度、专家意见无效直至公开取消专家咨询资格等方式处理；触犯法律的，由司法部门依法追究法律责任。"},{"i":57,"n":"第五十七条","txt":"科技部专项计划部门应对专家咨询活动的重要内容进行记录存档，其主要内容包括咨询任务、内容、方式、程序、咨询专家意见使用方法和规则、咨询专家名单、咨询专家个人意见、综合分析结论、组织咨询活动的机构和人员、以及其他需要特别说明的事项等。"},{"i":58,"n":"第五十八条","txt":"必要时，科技部有关专项计划、综合计划部门可根据实际需要建立咨询专家动态数据库。根据咨询任务的需要，聘任若干较为稳定的咨询专家群体参与项目管理全过程的活动，以增强咨询专家的责任和提高咨询工作质量。"},{"i":59,"n":"第五十九条","txt":"科技部专项计划部门可依据本办法，结合计划管理的实际需要对各类国家科技计划项目管理的基本程序做必要的补充，并报科技部综合计划部门备案。"},{"i":60,"n":"第六十条","txt":"本办法自发布之日起施行。"}],"guojiakejijihuaxiangmupinggupingshenxingweizhunzey6c62b0":[{"i":1,"n":"第一条","txt":"为加强对国家科技计划项目（含课题，下同）评估评审活动的监督检查，规范项目评估评审过程中有关单位和个人的行为，保证项目评估评审工作廉洁高效依法进行，特制定本办法。"},{"i":2,"n":"第二条","txt":"项目评估，是指科技部各专项科技计划主管部门按照公开、公平和竞争的原则，择优遴选具有科技评估能力的评估机构，按照规定的程序、办法和标准，对项目进行的专业化咨询和评判活动。 项目评审，是指科技部各专项科技计划主管部门组织或者委托有关单位组织科技、经济、管理等方面的专家，按照规定的程序、办法和标准，对项目进行的咨询和评判活动。"},{"i":3,"n":"第三条","txt":"本办法适用于在项目立项（含项目招标）、项目检查、项目验收等过程中组织或参与评估、评审活动的单位和个人，包括项目评估评审活动的组织者、承担者，项目评估人员和评审专家以及项目推荐者和项目申请者（含投标人和项目责任人，下同）。"},{"i":4,"n":"第四条","txt":"科技部负责国家科技计划项目评估评审活动的督查工作。"},{"i":5,"n":"第五条","txt":"项目评估或评审活动要按照国家有关法律、法规、规章和政策的要求，坚持独立、客观、公正的原则，并自觉接受有关方面的监督。 评估机构的项目评估报告或者评审专家的项目评审意见是科技部管理决策的重要参考依据。"},{"i":6,"n":"第六条","txt":"项目评估评审组织者，即科技部各专项科技计划主管部门及其相关人员、受委托组织项目评估评审活动的科技部直属事业单位和有关单位及其相关人员，应当严格执行项目立项、检查、验收中评估评审的各项规则、程序和办法，正确履行对项目评估评审的管理、指导和监督职能，忠于职守、依法行政、廉洁自律。 项目评估评审组织者对于评估评审意见的采纳情况，必须在报批时予以说明。项目评估评审组织者在组织评估评审活动中应当遵守下列规定： （一）不得直接从事、参与或干预项目评估评审活动，不得向评估机构、评估人员或者评审专家施加倾向性影响； （二）不得利用组织项目评估评审活动之便谋取不正当利益； （三）不得委托不具备规定条件的评估机构或者聘请不具备规定条件的评审专家承担项目评估评审活动； （四）不得聘请按规定应当回避或者在以往评估评审工作中有不良记录的评估机构或者评审专家； （五）不得违反保密规定，擅自泄露评估评审资料、评估人"},{"i":7,"n":"第七条","txt":"项目评估评审活动承担者，即受委托承担评估评审活动的科技评估机构、评审组织及相关人员，应当严格遵守项目评估评审有关规则、程序和办法，在受委托的范围内开展项目评估评审活动。 项目评估评审活动承担者应当遵守下列规定： （一）不得利用承担项目评估评审活动之便谋取不正当利益； （二）不得违反项目评估评审工作方案和预算的规定； （三）不得在规定程序以外向评审专家施加倾向性影响，损害国家利益或者其他项目申请者合法权益； （四）不得为评估评审对象编写立项可行性报告，或者检查、验收工作中要求提供的材料； （五）不得违反保密规定，擅自泄露评估评审资料、评估人员或者评审专家名单、项目评估报告、评审专家意见或者其他应当保密的评估评审情况； （六）不得索取或者接受评估评审对象以及相关人员的礼品、礼金、有价证券、支付凭证、可能影响公正性的宴请或其他好处。"},{"i":8,"n":"第八条","txt":"项目评估人员和评审专家应当以科学的态度和方法，严格依照项目评估评审工作的有关规定、程序和办法，实事求是，独立、客观、公正地对项目作出评价或者提出意见。 项目评估人员或评审专家在项目评估评审活动中应当遵守下列规定： （一）发现与项目或项目申请者存在利益关系或其他可能影响公正性的关系的，应当主动向项目评估评审组织者申明并回避； （二）不得利用评估人员或评审专家的特殊身份和影响力，或者与评估评审对象及相关人员串通，为有利益关系者获得项目立项或者通过检查、验收提供便利； （三）不得压制不同学术观点和其他专家意见； （四）不得为得出主观期望的结论，投机取巧、断章取义、片面作出与客观事实不符的评价； （五）不得擅自披露、使用或许可使用被评估评审对象的商业秘密； （六）严格遵守保密规定。未经允许，不得单独与评估评审对象及相关人员接触、不得复制保留或者向他人扩散评估评审资料，泄露保密信息； （七）不得"},{"i":9,"n":"第九条","txt":"项目推荐者，即各级科技行政管理部门、有关单位及相关人员，应当对推荐申请立项或者检查、验收的项目进行必要的考察、论证，如实反映所推荐项目和项目申请者情况，以及与项目申请者的关系、对项目申请者的了解程度。 项目推荐者应当遵守下列规定： （一）不得歧视潜在项目申请者，故意不推荐符合申请条件的项目； （二）不得与项目申请者串通，在项目立项申请材料或者检查、验收申请材料中弄虚作假； （三）不得为项目申请者拉关系，干扰项目评估评审工作； （四）不得索取或者接受项目申请者以及相关人员的礼品，礼金、有价证券、支付凭证、可能影响公正性的宴请或其他好处。"},{"i":10,"n":"第十条","txt":"项目申请者在项目的立项、检查、验收过程中，有义务接受并配合评估机构的评估或者科技计划管理部门组织的评审，按要求提供与项目有关的全部资料和信息，确保所提供资料和信息真实、有效。 项目申请者应当遵守下列规定： （一）不得弄虚作假，故意在项目评估评审活动中提供虚假资料、信息； （二）对同一项目（包括研究内容相同或者相近的项目）不得重复申请立项； （三）不得相互串通或者与科技计划项目管理人员、评估人员、评审专家串通，以不正当手段获取有关项目的评估评审信息； （四）不得向项目评估评审组织者、项目评估评审活动承担者、项目推荐者、项目评估人员和评审专家馈赠或者许诺馈赠钱物或给予其他好处； （五）不得编造谎言、捏造事实诋毁、侮辱、陷害科技计划项目管理者、项目评估评审活动承担者、项目评估人员、评审专家和其他项目申请者； （六）不得进行其他妨碍项目评估评审活动独立、客观、公正开展的行为。"},{"i":11,"n":"第十一条","txt":"科技部法制工作机构、综合计划管理机构、科技经费管理机构和驻科技部监察机构依照本办法的规定，具体负责对项目评估评审活动进行监督检查。"},{"i":12,"n":"第十二条","txt":"评估评审活动的督查工作可以采取经常性督查和专项性督查的形式。经常性督查是指对项目评估评审活动进行全过程的监督检查；专项性督查是指对项目评估评审某个环节或某类项目进行监督检查。对于重大项目的评估评审活动应当采取专项性督查方式进行重点督查。"},{"i":13,"n":"第十三条","txt":"评估评审活动的督查工作，可以采取下列方式： （一）听取评估评审活动的各方当事人的汇报； （二）查阅与评估评审有关的文件、合同、材料等； （三）参加与评估评审事项有关的会议； （四）向有关单位和个人调查核实； （五）其他适当方式。"},{"i":14,"n":"第十四条","txt":"科技部各专项科技计划主管部门及其相关人员有下列行为之一的，可视问题严重程度，对主要负责人或直接责任人给予纪律处分；构成犯罪的，依法移送司法机关追究刑事责任。 （一）对评估评审的重大情况隐匿不报，严重失职的； （二）与评估评审活动的承担者、申请者、推荐者或评估人员、评审专家串通、编造虚假报告的； （三）干预正常的评估评审活动，造成不良后果的； （四）索取或收受贿赂的； （五）其他玩忽职守，徇私舞弊以及妨碍项目评估评审活动正常进行的； （六）违反本办法第六条规定之一的。"},{"i":15,"n":"第十五条","txt":"受委托组织项目评估评审活动者或者评估评审活动承担者有下列情况之一的，科技部可以分别情况责令改正，给予警告、通报批评或者终止评估或评审委托；非法收受财物的，按国家有关规定没收所收受的财物；构成违纪的，建议有关部门给予纪律处分；构成犯罪的，依法移送司法机关追究刑事责任。 （一）弄虚作假，与项目执行单位串通编造虚假报告，或者对重大问题隐匿不报的； （二）徇私舞弊、滥用职权或者玩忽职守的； （三）违反本办法第六条、第七条规定之一的。"},{"i":16,"n":"第十六条","txt":"项目评估人员和评审专家有下列情况之一的，科技部可以分别情况责令改正，记录不良信用、给予警告、通报批评、宣布评估评审意见无效直至取消其参加评估评审活动的资格；构成违纪的，建议有关部门给予纪律处分；构成犯罪的，依法移送司法机关追究刑事责任。 （一）弄虚作假，致使相关项目通过评估评审的； （二）徇私舞弊，违背科学道德、有失公允的； （三）违反本办法第八条规定之一的。"},{"i":17,"n":"第十七条","txt":"项目推荐者和项目申请者有下列情况之一的，科技部可以分别情况责令改正，给予警告、通报批评、取消项目立项资格、终止项目合同，追回已拨经费、直至一定时限内取消相关人员或者单位推荐项目或者承担国家科技计划项目的资格；构成违纪的，建议有关部门给予纪律处分；构成犯罪的，依法移送司法机关追究刑事责任。 （一）弄虚作假，骗取项目立项的； （二）玩忽职守，徇私舞弊以及妨碍项目评估评审活动正常进行的； （三）违反本办法第九条、第十条规定之一的。"},{"i":18,"n":"第十八条","txt":"任何单位和个人发现国家科技计划项目评估评审活动存在问题的，可以向科技部进行举报和投诉。驻科技部监察局以及其他相关机构应当依照本办法的有关规定作出处理。 （一）对署名举报的，应当对举报人及举报内容保密。在对反映的问题调查核实、做出处理后，将核实、处理结果告知举报人并听取意见。 对捏造事实，进行诬告陷害的，要依据有关规定严肃处理。 （二）对匿名举报的材料，有具体事实的，应当进行初步核实，并确定处理办法。对重要问题的处理结果，要在适当范围内通报；没有具体事实的，可登记留存。 （三）对投诉人的投诉，应当严格按照信访工作的有关规定及时办理。"},{"i":19,"n":"第十九条","txt":"本办法自2003年3月1日起施行。"},{"i":20,"n":"第二十条","txt":"国家科学技术奖评审工作参照本办法执行。 地方各级科技行政主管部门可参照本办法，结合本地实际情况制定相应规定。"}],"guojiamimidingmiguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为加强国家秘密定密管理，规范定密行为，根据《中华人民共和国保守国家秘密法》（以下简称保密法）及其实施条例，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称定密，是指国家机关和涉及国家秘密的单位（以下简称机关、单位）依法确定、变更和解除国家秘密的活动。"},{"i":3,"n":"第三条","txt":"机关、单位定密以及定密责任人的确定、定密授权和定密监督等工作，适用本规定。"},{"i":4,"n":"第四条","txt":"机关、单位定密应当坚持最小化、精准化原则，做到权责明确、依据充分、程序规范、及时准确，既确保国家秘密安全，又便利信息资源合理利用。"},{"i":5,"n":"第五条","txt":"机关、单位应当依法开展定密工作，建立健全相关管理制度，定期组织培训和检查，接受保密行政管理部门和上级机关、单位或者业务主管部门的指导和监督。"},{"i":6,"n":"第六条","txt":"中央国家机关、省级机关以及设区的市、自治州一级的机关（以下简称授权机关）可以根据工作需要或者机关、单位申请作出定密授权。 保密行政管理部门应当将授权机关名单在有关范围内公布。"},{"i":7,"n":"第七条","txt":"中央国家机关可以在主管业务工作范围内作出授予绝密级、机密级和秘密级国家秘密定密权的决定。省级机关可以在主管业务工作范围内或者本行政区域内作出授予绝密级、机密级和秘密级国家秘密定密权的决定。设区的市、自治州一级的机关可以在主管业务工作范围内或者本行政区域内作出授予机密级和秘密级国家秘密定密权的决定。 定密授权不得超出授权机关的定密权限。被授权机关、单位不得再行授权。"},{"i":8,"n":"第八条","txt":"授权机关根据工作需要，可以对承担本机关定密权限内的涉密科研、生产或者其他涉密任务的机关、单位，就具体事项作出定密授权。"},{"i":9,"n":"第九条","txt":"没有定密权但经常产生国家秘密事项的机关、单位，或者虽有定密权但经常产生超出其定密权限的国家秘密事项的机关、单位，可以向授权机关申请定密授权。 机关、单位申请定密授权，应当向其上级业务主管部门提出；没有上级业务主管部门的，应当向其上级机关提出。 机关、单位申请定密授权，应当书面说明拟申请的定密权限、事项范围、授权期限以及申请依据和理由。"},{"i":10,"n":"第十条","txt":"授权机关收到定密授权申请后，应当依照保密法律法规和国家秘密及其密级的具体范围（以下简称保密事项范围）进行审查。对符合授权条件的，应当作出定密授权决定；对不符合授权条件的，应当作出不予授权的决定。 定密授权决定应当以书面形式作出，明确被授权机关、单位的名称和具体定密权限、事项范围、授权期限。"},{"i":11,"n":"第十一条","txt":"授权机关应当对被授权机关、单位行使所授定密权情况进行监督，对发现的问题及时纠正。 保密行政管理部门发现定密授权不当或者被授权机关、单位对所授定密权行使不当的，应当通知有关机关、单位纠正。"},{"i":12,"n":"第十二条","txt":"被授权机关、单位不再经常产生授权范围内的国家秘密事项，或者因保密事项范围调整授权事项不再作为国家秘密的，授权机关应当及时撤销定密授权。 因保密事项范围调整授权事项密级发生变化的，授权机关应当重新作出定密授权。"},{"i":13,"n":"第十三条","txt":"中央国家机关、省级机关作出的授权决定和撤销授权决定，报国家保密行政管理部门备案。设区的市、自治州一级的机关作出的授权决定和撤销授权决定，报省、自治区、直辖市保密行政管理部门备案。 机关、单位收到定密授权决定或者撤销定密授权决定后，应当报同级保密行政管理部门备案。"},{"i":14,"n":"第十四条","txt":"机关、单位负责人为本机关、本单位的定密责任人，对定密工作负总责。 根据工作需要，机关、单位负责人可以指定本机关、本单位其他负责人、内设机构负责人或者其他工作人员为定密责任人，并明确相应的定密权限。 机关、单位指定的定密责任人应当熟悉涉密业务工作，符合在涉密岗位工作的基本条件。"},{"i":15,"n":"第十五条","txt":"机关、单位应当在本机关、本单位内部公布定密责任人名单及其定密权限，并报同级保密行政管理部门备案。"},{"i":16,"n":"第十六条","txt":"机关、单位定密责任人和承办人应当接受定密培训，熟悉定密职责和保密事项范围，掌握定密程序和方法。"},{"i":17,"n":"第十七条","txt":"机关、单位负责人发现其指定的定密责任人未依法履行定密职责的，应当及时纠正；有下列情形之一的，应当作出调整： （一）定密不当，情节严重的； （二）因离岗离职无法继续履行定密职责的； （三）保密行政管理部门建议调整的； （四）因其他原因不宜从事定密工作的。"},{"i":18,"n":"第十八条","txt":"机关、单位确定国家秘密应当依据保密事项范围进行。保密事项范围没有明确规定但属于保密法第九条、第十条规定情形的，应当确定为国家秘密。"},{"i":19,"n":"第十九条","txt":"下列事项不得确定为国家秘密： （一）需要社会公众广泛知晓或者参与的； （二）属于工作秘密、商业秘密、个人隐私的； （三）已经依法公开或者无法控制知悉范围的； （四）法律、法规或者国家有关规定要求公开的。"},{"i":20,"n":"第二十条","txt":"机关、单位对所产生的国家秘密事项有定密权的，应当依法确定密级、保密期限和知悉范围。没有定密权的，应当先行采取保密措施，并立即报请有定密权的上级机关、单位确定；没有上级机关、单位的，应当立即提请有相应定密权限的业务主管部门或者保密行政管理部门确定。 机关、单位执行上级机关、单位或者办理其他机关、单位已定密事项所产生的国家秘密事项，根据所执行或者办理的国家秘密事项确定密级、保密期限和知悉范围。"},{"i":21,"n":"第二十一条","txt":"机关、单位确定国家秘密，应当依照法定程序进行并作出书面记录，注明承办人、定密责任人和定密依据。"},{"i":22,"n":"第二十二条","txt":"国家秘密具体的保密期限一般应当以日、月或者年计；不能确定具体的保密期限的，应当确定解密时间或者解密条件。国家秘密的解密条件应当明确、具体、合法。 除保密事项范围有明确规定外，国家秘密的保密期限不得确定为长期。"},{"i":23,"n":"第二十三条","txt":"国家秘密的知悉范围应当在国家秘密载体上标明。不能标明的，应当书面通知知悉范围内的机关、单位或者人员。"},{"i":24,"n":"第二十四条","txt":"国家秘密一经确定，应当同时在国家秘密载体上作出国家秘密标志。国家秘密标志形式为“密级★保密期限”、“密级★解密时间”或者“密级★解密条件”。 在纸介质和电子文件国家秘密载体上作出国家秘密标志的，应当符合有关国家标准。没有国家标准的，应当标注在封面左上角或者标题下方的显著位置。光介质、电磁介质等国家秘密载体和属于国家秘密的设备、产品的国家秘密标志，应当标注在壳体及封面、外包装的显著位置。 国家秘密标志应当与载体不可分离，明显并易于识别。 无法作出或者不宜作出国家秘密标志的，确定该国家秘密的机关、单位应当书面通知知悉范围内的机关、单位或者人员。凡未标明保密期限或者解密条件，且未作书面通知的国家秘密事项，其保密期限按照绝密级事项三十年、机密级事项二十年、秘密级事项十年执行。"},{"i":25,"n":"第二十五条","txt":"两个以上机关、单位共同产生的国家秘密事项，由主办该事项的机关、单位征求协办机关、单位意见后确定。 临时性工作机构的定密工作，由承担该机构日常工作的机关、单位负责。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，机关、单位应当对所确定国家秘密事项的密级、保密期限或者知悉范围及时作出变更： （一）定密时所依据的法律法规或者保密事项范围发生变化的； （二）泄露后对国家安全和利益的损害程度发生明显变化的。 必要时，上级机关、单位或者业务主管部门可以直接变更下级机关、单位确定的国家秘密事项的密级、保密期限或者知悉范围。"},{"i":27,"n":"第二十七条","txt":"机关、单位认为需要延长所确定国家秘密事项保密期限的，应当在保密期限届满前作出决定；延长保密期限使累计保密期限超过保密事项范围规定的，应当报规定该保密事项范围的中央有关机关批准，中央有关机关应当在接到报告后三十日内作出决定。"},{"i":28,"n":"第二十八条","txt":"国家秘密知悉范围内的机关、单位，其有关工作人员不在知悉范围内，但因工作需要知悉国家秘密的，应当经机关、单位负责人批准。 国家秘密知悉范围以外的机关、单位及其人员，因工作需要知悉国家秘密的，应当经原定密机关、单位同意。 原定密机关、单位对扩大知悉范围有明确规定的，应当遵守其规定。 扩大国家秘密知悉范围应当作出详细记录。"},{"i":29,"n":"第二十九条","txt":"国家秘密变更按照国家秘密确定程序进行并作出书面记录。 国家秘密变更后，原定密机关、单位应当及时在原国家秘密标志附近重新作出国家秘密标志。"},{"i":30,"n":"第三十条","txt":"机关、单位变更国家秘密的密级、保密期限或者知悉范围的，应当书面通知知悉范围内的机关、单位或者人员。有关机关、单位或者人员接到通知后，应当在国家秘密标志附近标明变更后的密级、保密期限和知悉范围。 延长保密期限的书面通知，应当于原定保密期限届满前送达知悉范围内的机关、单位或者人员。"},{"i":31,"n":"第三十一条","txt":"机关、单位应当每年对所确定的国家秘密进行审核，有下列情形之一的，及时解密： （一）保密法律法规或者保密事项范围调整后，不再属于国家秘密的； （二）公开后不会损害国家安全和利益，不需要继续保密的。 机关、单位经解密审核，对本机关、本单位或者下级机关、单位尚在保密期限内的国家秘密事项决定公开的，正式公布即视为解密。"},{"i":32,"n":"第三十二条","txt":"国家秘密的具体保密期限已满、解密时间已到或者符合解密条件的，自行解密。"},{"i":33,"n":"第三十三条","txt":"保密事项范围明确规定保密期限为长期的国家秘密事项，机关、单位不得擅自解密；确需解密的，应当报规定该保密事项范围的中央有关机关批准，中央有关机关应当在接到报告后三十日内作出决定。"},{"i":34,"n":"第三十四条","txt":"除自行解密的外，国家秘密解除应当按照国家秘密确定程序进行并作出书面记录。 国家秘密解除后，有关机关、单位或者人员应当及时在原国家秘密标志附近作出解密标志。"},{"i":35,"n":"第三十五条","txt":"除自行解密和正式公布的外，机关、单位解除国家秘密，应当书面通知知悉范围内的机关、单位或者人员。"},{"i":36,"n":"第三十六条","txt":"机关、单位对所产生的国家秘密事项，解密之后需要公开的，应当依照信息公开程序进行保密审查。 机关、单位对已解密的不属于本机关、本单位产生的国家秘密事项，需要公开的，应当经原定密机关、单位同意。 机关、单位公开已解密的文件资料，不得保留国家秘密标志。对国家秘密标志以及属于敏感信息的内容，应当作删除、遮盖等处理。"},{"i":37,"n":"第三十七条","txt":"机关、单位对拟移交各级国家档案馆的尚在保密期限内的国家秘密档案，应当进行解密审核，对本机关、本单位产生的符合解密条件的档案，应当予以解密。 已依法移交各级国家档案馆的属于国家秘密的档案，其解密办法由国家保密行政管理部门会同国家档案行政管理部门另行制定。"},{"i":38,"n":"第三十八条","txt":"机关、单位应当定期对本机关、本单位定密以及定密责任人履行职责、定密授权等定密制度落实情况进行检查，对发现的问题及时纠正。"},{"i":39,"n":"第三十九条","txt":"机关、单位应当向同级保密行政管理部门报告本机关、本单位年度国家秘密事项统计情况。 下一级保密行政管理部门应当向上一级保密行政管理部门报告本行政区域年度定密工作情况。"},{"i":40,"n":"第四十条","txt":"中央国家机关应当依法对本系统、本行业的定密工作进行指导和监督。 上级机关、单位或者业务主管部门发现下级机关、单位定密不当的，应当及时通知其纠正，也可以直接作出确定、变更或者解除的决定。"},{"i":41,"n":"第四十一条","txt":"保密行政管理部门应当依法对机关、单位定密工作进行指导、监督和检查，对发现的问题及时纠正或者责令整改。"},{"i":42,"n":"第四十二条","txt":"定密责任人和承办人违反本规定，有下列行为之一的，机关、单位应当及时纠正并进行批评教育；造成严重后果的，依纪依法给予处分： （一）应当确定国家秘密而未确定的； （二）不应当确定国家秘密而确定的； （三）超出定密权限定密的； （四）未按照法定程序定密的； （五）未按规定标注国家秘密标志的； （六）未按规定变更国家秘密的密级、保密期限、知悉范围的； （七）未按要求开展解密审核的； （八）不应当解除国家秘密而解除的； （九）应当解除国家秘密而未解除的； （十）违反本规定的其他行为。"},{"i":43,"n":"第四十三条","txt":"机关、单位未依法履行定密管理职责，导致定密工作不能正常进行的，应当给予通报批评；造成严重后果的，应当依法追究直接负责的主管人员和其他直接责任人员的责任。"},{"i":44,"n":"第四十四条","txt":"本规定下列用语的含义： （一）“中央国家机关”包括中国共产党中央机关及部门、各民主党派中央机关、全国人大机关、全国政协机关、最高人民法院、最高人民检察院，国务院及其组成部门、直属特设机构、直属机构、办事机构、直属事业单位、部委管理国家局，以及中央机构编制管理部门直接管理机构编制的群众团体机关； （二）“省级机关”包括省（自治区、直辖市）党委、人大、政府、政协机关，以及人民法院、人民检察院； （三）“设区的市和自治州一级的机关”包括地（市、州、盟、区）党委、人大、政府、政协机关，以及人民法院、人民检察院，省（自治区、直辖市）直属机关和人民团体，中央国家机关设在省（自治区、直辖市）的直属机构，省（自治区、直辖市）在地区、盟设立的派出机构； （四）第九条所指“经常”，是指近三年来年均产生六件以上国家秘密事项的情形。"},{"i":45,"n":"第四十五条","txt":"各地区各部门可以依据本规定，制定本地区本部门国家秘密定密管理的具体办法。"},{"i":46,"n":"第四十六条","txt":"公安、国家安全机关定密授权和定密责任人确定的具体办法，由国家保密行政管理部门会同国务院公安、国家安全部门另行制定。"},{"i":47,"n":"第四十七条","txt":"本规定自公布之日起施行。1990年9月19日国家保密局令第2号发布的《国家秘密保密期限的规定》和1990年10月6日国家保密局、国家技术监督局令第3号发布的《国家秘密文件、资料和其他物品标志的规定》同时废止。"}],"guojiamimidingmiguanliguiding":[{"i":1,"n":"第一条","txt":"为规范国家秘密定密管理，根据《中华人民共和国保守国家秘密法》（以下简称保密法）及其实施条例，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称定密，是指国家机关和涉及国家秘密的单位（以下简称机关、单位）依法确定、变更和解除国家秘密的活动。 定密包括原始定密和派生定密。机关、单位在定密权限内，对其所产生的属于国家秘密及其密级的具体范围（以下简称保密事项范围）规定的国家秘密，依法确定、变更和解除的活动为原始定密。机关、单位对执行或者办理已定密事项所产生的国家秘密，依法确定、变更和解除的活动为派生定密。"},{"i":3,"n":"第三条","txt":"机关、单位国家秘密确定、变更和解除以及定密责任人的管理、定密授权和定密监督等工作，适用本规定。"},{"i":4,"n":"第四条","txt":"机关、单位定密应当坚持最小化、精准化原则，做到权责明确、依据充分、程序规范、及时准确，既确保国家秘密安全，又便利信息资源合理利用。"},{"i":5,"n":"第五条","txt":"机关、单位应当依法开展定密工作，建立健全相关管理制度，定期组织培训和检查，接受保密行政管理部门和业务主管部门或者上级机关、单位的指导和监督。"},{"i":6,"n":"第六条","txt":"保密事项范围是国家秘密确定、变更和解除的依据。 保密事项范围由国家保密行政管理部门单独或者会同有关中央和国家机关规定。国家保密行政管理部门会同有关中央和国家机关规定的，由部门主要负责人共同签署批准。 军事方面的保密事项范围，由中央军事委员会规定。"},{"i":7,"n":"第七条","txt":"保密事项范围包括正文和目录。正文规定本行业、本领域国家秘密的基本范围，目录规定国家秘密具体事项的名称、密级、保密期限、知悉范围和产生层级。"},{"i":8,"n":"第八条","txt":"保密事项范围的确定应当遵循必要、合理原则，科学论证评估，并根据情况变化及时修订。制定、修订保密事项范围应当充分听取有关机关、单位和相关行业、领域专家的意见。 保密事项范围应当在有关范围内公布。保密事项范围内容属于国家秘密的，应当依法确定密级和保密期限。"},{"i":9,"n":"第九条","txt":"国家保密行政管理部门负责对保密事项范围制定、修订和使用工作进行指导监督。中央和国家机关负责组织制定、修订本行业、本领域保密事项范围并组织教育培训，对保密事项范围的使用进行指导监督。地方各级保密行政管理部门负责对本行政区域内机关、单位使用保密事项范围工作进行指导监督。"},{"i":10,"n":"第十条","txt":"有定密权的机关、单位应当依据本行业、本领域和相关行业、领域保密事项范围目录，制定、修订国家秘密事项一览表，明确本机关、本单位产生的国家秘密事项的具体内容、密级、保密期限、知悉范围、产生部门或者岗位、制定依据等。 国家秘密事项一览表，应当经本机关、本单位负责人审定后实施，并报同级保密行政管理部门备案。"},{"i":11,"n":"第十一条","txt":"机关、单位原始定密应当遵守定密权限。中央和国家机关、省级机关可以确定绝密级、机密级和秘密级国家秘密；设区的市级机关可以确定机密级和秘密级国家秘密。 机关、单位产生保密事项范围明确规定的国家秘密事项，但该机关、单位没有定密权或者定密权限低于该国家秘密事项的密级的，应当先行采取保密措施，并立即报请有相应定密权限的上级机关、单位确定；没有上级机关、单位的，应当立即提请有相应定密权限的业务主管部门或者保密行政管理部门确定。 机关、单位开展派生定密，不受定密权限限制。"},{"i":12,"n":"第十二条","txt":"中央和国家机关、省级机关以及设区的市级机关（以下统称授权机关）可以根据保密工作需要或者有关机关、单位申请，在国家保密行政管理部门规定的定密权限、授权范围内，作出定密授权。 保密行政管理部门应当将授权机关名单在有关范围内公布，并根据情况变化及时调整。"},{"i":13,"n":"第十三条","txt":"中央和国家机关、省级机关可以在工作职责范围内作出授予绝密级、机密级和秘密级国家秘密定密权的决定。设区的市级机关可以在工作职责范围内作出授予机密级和秘密级国家秘密定密权的决定。 定密授权不得超出授权机关的定密权限。被授权机关、单位不得再行授权。"},{"i":14,"n":"第十四条","txt":"授权机关根据工作需要，可以对经常产生本行业、本领域保密事项范围规定事项但无相应定密权限的机关、单位作出定密授权；也可以对承担本机关涉密业务的机关、单位，就具体事项作出定密授权。"},{"i":15,"n":"第十五条","txt":"没有定密权但经常产生国家秘密事项的机关、单位，或者虽有定密权但经常产生超出其定密权限的国家秘密事项的机关、单位，可以向授权机关申请定密授权。 机关、单位申请定密授权，应当向有相应定密权限的业务主管部门或者上级机关提出。无法按照上述规定申请授权的，可以向国家保密行政管理部门或者省、自治区、直辖市保密行政管理部门提出。 机关、单位申请定密授权，应当书面说明拟申请的定密权限、事项范围、授权期限以及申请依据和理由。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，国家保密行政管理部门或者省、自治区、直辖市保密行政管理部门可以根据工作需要或者有关机关、单位申请，作出授予定密权的决定： （一）申请定密授权的机关、单位没有上级机关或者业务主管部门不明确的； （二）定密授权申请涉及多个行业、领域国家秘密事项的； （三）保密行政管理部门认为需要授予定密权的其他情形。 中央单位应当向国家保密行政管理部门申请定密授权，其他单位应当向省、自治区、直辖市保密行政管理部门申请定密授权。"},{"i":17,"n":"第十七条","txt":"授权机关依照本行业、本领域保密事项范围作出定密授权。根据工作需要，上级机关可以对下级机关、单位的组织、纪检监察、财务、审计、保密、档案、信访等事项作出定密授权。"},{"i":18,"n":"第十八条","txt":"授权机关收到定密授权申请后，应当依据保密法律法规和保密事项范围对是否符合授权条件进行审查，在30日内作出定密授权或者不予授权的决定。 定密授权决定应当以书面形式作出，明确被授权机关、单位的名称和具体定密权限、事项范围、授权期限，授权期限一般不超过5年。"},{"i":19,"n":"第十九条","txt":"授权机关应当对被授权机关、单位行使定密权情况进行监督，对发现的问题及时纠正。 被授权机关、单位应当规范行使定密权，主动向授权机关报告定密权行使情况，接受授权机关指导、监督。 保密行政管理部门发现定密授权不当或者被授权机关、单位对定密权行使不当的，应当通知有关机关、单位纠正。"},{"i":20,"n":"第二十条","txt":"被授权机关、单位不再经常产生授权范围内的国家秘密事项，或者因保密事项范围调整授权事项不再作为国家秘密的，授权机关应当及时撤销定密授权。 因保密事项范围调整授权事项密级发生变化的，授权机关应当重新作出定密授权。"},{"i":21,"n":"第二十一条","txt":"中央和国家机关、省级机关和省、自治区、直辖市保密行政管理部门作出的授权决定和撤销授权决定，应当报国家保密行政管理部门备案。设区的市级机关作出的授权决定和撤销授权决定，应当报省、自治区、直辖市保密行政管理部门备案。 机关、单位收到定密授权决定或者撤销定密授权决定后，应当报同级保密行政管理部门备案。"},{"i":22,"n":"第二十二条","txt":"机关、单位主要负责人为本机关、本单位的法定定密责任人，对定密工作负总责。 根据工作需要，机关、单位法定定密责任人可以明确本机关、本单位其他负责人、内设机构负责人或者其他人员为指定定密责任人，并明确相应的定密权限，负责其职责范围内定密工作。指定定密责任人不得再确定其他人员为定密责任人。 机关、单位定密责任人应当熟悉涉密业务工作，符合在涉密岗位工作的基本条件。"},{"i":23,"n":"第二十三条","txt":"机关、单位应当在本机关、本单位内部公布定密责任人名单及其定密权限，并报同级保密行政管理部门备案。"},{"i":24,"n":"第二十四条","txt":"定密责任人在职责范围内承担国家秘密确定、变更和解除工作，指导、监督职责范围内的定密工作。主要包括： （一）对承办人拟定的国家秘密的密级、保密期限和知悉范围进行审核批准； （二）对本机关、本单位确定的尚在保密期限内的国家秘密进行审核，作出是否变更或者解除的决定； （三）参与制定修订本机关、本单位国家秘密事项一览表； （四）对不明确事项先行拟定密级、保密期限和知悉范围，采取相应的保密措施，并按照规定的程序报相应的保密行政管理部门确定； （五）研究办理有关机关、单位提出的定密异议； （六）对拟公开的已解密事项提出保密审查意见； （七）对保密事项范围的制定、修订，以及加强和改进定密工作，提出意见建议。"},{"i":25,"n":"第二十五条","txt":"机关、单位定密责任人和承办人应当接受定密培训，熟悉定密职责和有关保密事项范围，掌握定密程序和方法。"},{"i":26,"n":"第二十六条","txt":"机关、单位法定定密责任人发现指定定密责任人未依法履行定密职责的，应当及时纠正；有下列情形之一的，应当作出调整： （一）不符合本规定第二十五条定密责任人岗位要求，无法履行定密职责的； （二）定密不当，情节严重的； （三）因离岗离职无法继续履行定密职责的； （四）保密行政管理部门建议调整的； （五）因其他原因不宜从事定密工作的。"},{"i":27,"n":"第二十七条","txt":"机关、单位原始定密应当按照定密权限，依据保密事项范围确定密级、保密期限和知悉范围： （一）密级应当按照目录的规定确定，不得高于或者低于规定的密级； （二）保密期限应当在目录规定的最长保密期限内合理确定，不得超出最长保密期限。明确为长期的，不得擅自变更。规定解密条件或者解密时间的，从其规定； （三）知悉范围应当依据目录的规定，根据工作需要限定到具体人员。不能限定到具体人员的，应当限定到具体单位、部门或者岗位； （四）产生层级应当符合目录的规定，不符合目录规定，确需定密的，报上级机关、单位确定。"},{"i":28,"n":"第二十八条","txt":"机关、单位派生定密应当依据所执行或者办理的已定密事项确定密级、保密期限和知悉范围。"},{"i":29,"n":"第二十九条","txt":"下列事项不得确定为国家秘密： （一）需要社会公众广泛知晓或者参与的； （二）属于工作秘密、商业秘密、个人隐私的； （三）已经依法公开或者无法控制知悉范围的； （四）法律、法规或者国家有关规定要求公开的。 机关、单位因执行或者办理已定密事项而产生的事项，不涉及对已定密事项内容进行概括总结、编辑整合、具体细化的，不应当派生定密。"},{"i":30,"n":"第三十条","txt":"机关、单位确定国家秘密，应当由承办人拟定密级、保密期限和知悉范围，经定密责任人审核批准，并作出书面记录，注明承办人、定密责任人和定密依据。"},{"i":31,"n":"第三十一条","txt":"机关、单位对具备国家秘密本质属性，可以与非国家秘密明确区分的关键内容，可以标注密点。对涉密科研项目、涉密工程、涉密政府采购等可以明确密点的，应当确定密点并作出标注；不能明确标注的，可以以附件、附注等形式作出说明。 同一事项涉及多个密点，且密级和保密期限不同的，应当分别进行标注，并按照涉及密点的最高密级和最长保密期限确定该事项的密级和保密期限。 国家保密行政管理部门制定密点标注的具体规定和标准。"},{"i":32,"n":"第三十二条","txt":"国家秘密具体保密期限一般应当以日、月或者年计；不能确定具体保密期限的，应当确定解密时间或者解密条件。国家秘密的解密条件应当明确、具体、合理。 除保密事项范围有明确规定外，国家秘密的保密期限不得确定为长期。"},{"i":33,"n":"第三十三条","txt":"国家秘密的知悉范围应当在国家秘密载体上标明。不能标明的，应当书面通知知悉范围内的机关、单位或者人员。"},{"i":34,"n":"第三十四条","txt":"国家秘密一经确定，应当在国家秘密载体上规范作出国家秘密标志。国家秘密标志形式为“密级★保密期限”、“密级★解密时间”或者“密级★解密条件”。 在纸介质和电子文件国家秘密载体上作出国家秘密标志的，应当符合有关国家标准。没有国家标准的，应当标注在封面左上角或者标题下方的显著位置。光介质、电磁介质等国家秘密载体和属于国家秘密的设备、产品的国家秘密标志，应当标注在壳体及封面、外包装的显著位置。 国家秘密标志应当与载体不可分离，明显并易于识别。 无法作出或者不宜作出国家秘密标志的，确定该国家秘密的机关、单位应当书面通知知悉范围内的机关、单位或者人员。"},{"i":35,"n":"第三十五条","txt":"机关、单位对汇聚、关联后符合保密事项范围有关规定的数据，应当依法加强安全管理，防范数据泄露。汇聚、关联后的数据达到一定精度或者规模，符合保密法第十三条和第十四条规定，但保密事项范围没有相关规定的，应当先行采取保密措施，并报主管该行业、领域的有关中央和国家机关确定。 中央和国家机关应当加强对本行业、本领域数据汇聚、关联定密工作的指导。"},{"i":36,"n":"第三十六条","txt":"两个以上机关、单位共同产生的国家秘密事项，由主办机关、单位征求协办机关、单位意见后确定。 临时性工作机构的定密工作，由承担该机构日常工作的机关、单位负责。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一的，机关、单位应当对所确定国家秘密的密级、保密期限或者知悉范围及时作出变更： （一）定密时所依据的法律法规或者保密事项范围发生变化的； （二）泄露后对国家安全和利益的损害程度发生明显变化的； （三）派生定密所执行或者办理的已定密事项已经变更的。 必要时，上级机关、单位或者业务主管部门可以直接变更下级机关、单位确定的国家秘密事项的密级、保密期限或者知悉范围。 派生定密的机关、单位对已定密事项是否变更不明确的，可以向原定密机关、单位请示或者函询，原定密机关、单位应当及时予以答复。"},{"i":38,"n":"第三十八条","txt":"机关、单位认为需要延长所确定国家秘密保密期限的，应当在保密期限届满前作出决定；延长保密期限使累计保密期限超过保密事项范围规定的，应当报制定该保密事项范围的中央和国家机关批准，中央和国家机关应当在接到报告后30日内作出决定。"},{"i":39,"n":"第三十九条","txt":"国家秘密知悉范围内的机关、单位，其有关工作人员不在知悉范围内，但因工作需要知悉国家秘密的，应当经本机关、本单位主要负责人或者其指定的人员批准。 国家秘密知悉范围以外的机关、单位及其人员，因工作需要知悉国家秘密的，应当经原定密机关、单位同意。 原定密机关、单位对扩大知悉范围有明确规定的，应当遵守其规定。 扩大国家秘密知悉范围应当作出详细记录。"},{"i":40,"n":"第四十条","txt":"国家秘密变更按照国家秘密确定程序进行并作出书面记录。 国家秘密变更后，应当及时在原国家秘密标志附近重新作出国家秘密标志。"},{"i":41,"n":"第四十一条","txt":"机关、单位变更国家秘密的密级、保密期限或者知悉范围的，应当书面通知知悉范围内的机关、单位或者人员。有关机关、单位或者人员接到通知后，应当在国家秘密标志附近标明变更后的密级、保密期限和知悉范围。 延长保密期限的通知，应当于原定保密期限届满前送达知悉范围内的机关、单位或者人员。"},{"i":42,"n":"第四十二条","txt":"机关、单位应当每年审核所确定的国家秘密，在保密期限内有下列情形之一的，应当及时解密： （一）法律法规或者保密事项范围调整后，不再属于国家秘密的； （二）公开后不会损害国家安全和利益，不需要继续保密的； （三）根据现行法律法规和国家有关规定，应当予以公开或者需要社会公众广泛知晓的； （四）派生定密所执行或者办理的已定密事项已经解密的。 派生定密的机关、单位对已定密事项是否解密不明确的，可以向原定密机关、单位请示或者函询，原定密机关、单位应当及时予以答复。"},{"i":43,"n":"第四十三条","txt":"明确标注具体保密期限的国家秘密事项，保密期限已满，经原定密机关、单位审核未延长保密期限的，自行解密。解密时间已到或者符合解密条件的，自行解密。 凡未明确标注具体保密期限、解密时间或者解密条件，且未就保密期限作出书面通知的国家秘密事项，其保密期限按照绝密级事项30年、机密级事项20年、秘密级事项10年执行。国家另有规定的，从其规定。 保密事项范围明确规定保密期限为长期的国家秘密事项，机关、单位不得擅自解密；确需解密的，应当报制定该保密事项范围的中央和国家机关批准，中央和国家机关应当在接到报告后30日内作出决定。"},{"i":44,"n":"第四十四条","txt":"国家秘密解除应当按照有关规定履行解密程序并作出书面记录。 国家秘密解除后，应当及时在原国家秘密标志附近作出解密标志；无法或者不宜作出解密标志的，应当以其他方式作出说明。"},{"i":45,"n":"第四十五条","txt":"除正式公布的外，机关、单位解除国家秘密，应当书面通知知悉范围内的机关、单位或者人员。解密通知可以单独发布或者以目录形式集中发布。"},{"i":46,"n":"第四十六条","txt":"机关、单位对所产生的国家秘密事项，解密后需要公开的，应当进行保密审查。 机关、单位对已解密的不属于本机关、本单位产生的国家秘密事项，需要公开的，应当经原定密机关、单位同意。 机关、单位公开已解密的文件资料，不得保留国家秘密标志。对国家秘密标志以及属于其他不宜公开的敏感信息，应当作删除、遮盖等处理。"},{"i":47,"n":"第四十七条","txt":"机关、单位对拟移交各级国家档案馆的尚在保密期限内的国家秘密档案，应当进行解密审核，对本机关、本单位产生的符合解密条件的档案，应当予以解密。 已依法移交各级国家档案馆的属于国家秘密的档案，其解密办法由国家保密行政管理部门会同国家档案主管部门另行制定。"},{"i":48,"n":"第四十八条","txt":"机关、单位应当定期对本机关、本单位定密以及定密责任人履行职责、定密授权等定密制度落实情况进行检查，对发现的问题及时纠正。"},{"i":49,"n":"第四十九条","txt":"具有系统管理或者指导职能的中央和国家机关应当在其职权范围内对本系统、本行业的定密工作进行管理或者指导，监督执行定密规定。 上级机关、单位或者业务主管部门发现下级机关、单位定密不当的，应当及时通知其纠正，也可以直接作出确定、变更或者解除的决定。"},{"i":50,"n":"第五十条","txt":"机关、单位应当向同级保密行政管理部门报告本机关、本单位年度国家秘密确定、变更和解除等情况。下一级保密行政管理部门应当向上一级保密行政管理部门报告本行政区域年度定密工作情况。 保密行政管理部门应当依法对机关、单位定密工作进行指导、监督和检查，对发现的问题及时通知纠正或者责令整改。"},{"i":51,"n":"第五十一条","txt":"定密责任人和承办人违反本规定，有下列行为之一的，机关、单位应当及时纠正并进行批评教育；造成严重后果的，依纪依法给予处分并予以通报： （一）应当确定国家秘密而未确定的； （二）不应当确定国家秘密而确定的； （三）超出定密权限定密的； （四）未按照法定程序定密的； （五）未按照规定标注国家秘密标志的； （六）未按照规定变更国家秘密的密级、保密期限、知悉范围的； （七）未履行解密审核责任的； （八）不应当解除国家秘密而解除的； （九）应当解除国家秘密而未解除的； （十）违反本规定的其他行为。"},{"i":52,"n":"第五十二条","txt":"机关、单位未依法履行定密管理职责，导致定密工作不能正常进行的，应当给予通报批评；造成严重后果的，应当依法追究直接负责的主管人员和其他直接责任人员的责任。"},{"i":53,"n":"第五十三条","txt":"本规定第十四条、第十五条所指“经常”，是指近3年来年均原始产生6件以上国家秘密事项的情形。"},{"i":54,"n":"第五十四条","txt":"各地区各部门可以依据本规定，制定本地区本部门国家秘密定密管理的具体办法。"},{"i":55,"n":"第五十五条","txt":"公安、国家安全机关定密授权和定密责任人确定的具体办法，由国家保密行政管理部门会同国务院公安、国家安全部门另行制定。"},{"i":56,"n":"第五十六条","txt":"本规定自2025年5月1日起施行。2014年3月9日国家保密局令第1号发布的《国家秘密定密管理暂行规定》、2017年3月9日国家保密局令第1号发布的《保密事项范围制定、修订和使用办法》同时废止。"}],"guojiamimizaitiyinzhizizhiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了加强国家秘密载体印制资质管理，确保国家秘密安全，根据《中华人民共和国保守国家秘密法》、《中华人民共和国行政许可法》、《中华人民共和国行政处罚法》、《中华人民共和国保守国家秘密法实施条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称国家秘密载体印制（以下简称涉密印制），是指以印刷、复制等方式制作国家秘密载体的行为。 涉密印制资质是指保密行政管理部门许可企业事业单位从事国家秘密载体印制业务的法定资格。"},{"i":3,"n":"第三条","txt":"涉密印制资质的申请、受理、审查、决定、使用和监督管理，适用本办法。"},{"i":4,"n":"第四条","txt":"从事涉密印制业务的企业事业单位应当依照本办法，取得涉密印制资质。 国家机关和涉及国家秘密的单位（以下简称机关、单位）应当选择具有涉密印制资质的单位（以下简称资质单位）承接涉密印制业务。"},{"i":5,"n":"第五条","txt":"涉密印制资质管理应当遵循依法管理、安全保密、科学发展、公平公正的原则。"},{"i":6,"n":"第六条","txt":"国家保密行政管理部门主管全国涉密印制资质管理工作，省级保密行政管理部门主管本行政区域内涉密印制资质管理工作。 省级以上保密行政管理部门根据工作需要，可以委托下一级保密行政管理部门开展审查工作，或者组织机构协助开展工作。"},{"i":7,"n":"第七条","txt":"省级以上保密行政管理部门应当指定专门机构承担保密资质管理日常工作。"},{"i":8,"n":"第八条","txt":"省级以上保密行政管理部门建立保密资质审查专家库，组织开展入库审查、培训考核等工作。"},{"i":9,"n":"第九条","txt":"实施涉密印制资质许可不收取任何费用，所需经费纳入同级财政预算。"},{"i":10,"n":"第十条","txt":"涉密印制资质分为甲级和乙级两个等级。 甲级资质单位可以从事绝密级、机密级、秘密级涉密印制业务；乙级资质单位可以从事机密级、秘密级涉密印制业务。"},{"i":11,"n":"第十一条","txt":"涉密印制资质包括涉密文件资料、国家统一考试试卷、涉密防伪票据证书、涉密光电磁介质、涉密档案数字化加工，以及国家保密行政管理部门许可的其他涉密印制业务。 资质单位应当在保密行政管理部门许可的业务种类范围内承接涉密印制业务。"},{"i":12,"n":"第十二条","txt":"申请单位应当具备以下基本条件： （一）在中华人民共和国境内注册的法人，从事印制业务三年以上，甲级资质申请单位还应当具备相应乙级资质三年以上； （二）无犯罪记录且近三年内未被吊销保密资质（资格），法定代表人、主要负责人、实际控制人未被列入失信人员名单； （三）法定代表人、主要负责人、实际控制人、董（监）事会人员、高级管理人员以及从事涉密印制业务人员具有中华人民共和国国籍，无境外永久居留权或者长期居留许可，与境外人员无婚姻关系，国家另有规定的除外； （四）具有从事涉密印制业务的专业能力； （五）法律、行政法规和国家保密行政管理部门规定的其他条件。"},{"i":13,"n":"第十三条","txt":"申请单位应当具备以下保密条件： （一）有专门机构或者人员负责保密工作； （二）保密制度完善； （三）从事涉密印制业务的人员经过保密教育培训，具备必要的保密知识和技能； （四）用于涉密印制业务的场所、设施、设备符合国家保密规定和标准； （五）有专门的保密工作经费； （六）法律、行政法规和国家保密行政管理部门规定的其他保密条件。"},{"i":14,"n":"第十四条","txt":"申请涉密文件资料、涉密光电磁介质、涉密档案数字化加工资质的单位不得有外国投资者投资。在新三板挂牌的企业申请资质以及资质有效期内的，还应当符合以下条件： （一）参与挂牌交易的股份比例不高于总股本的30%； （二）实际控制人在申请期间及资质有效期内保持控制地位不变。"},{"i":15,"n":"第十五条","txt":"申请国家统一考试试卷、涉密防伪票据证书资质的单位不得由外国投资者控股。"},{"i":16,"n":"第十六条","txt":"申请单位应当建立完善的内部管理和信息披露制度，未经国务院有关主管部门或者省级人民政府有关主管部门批准，外国投资者不得接触、知悉国家秘密信息。"},{"i":17,"n":"第十七条","txt":"申请单位申请不同等级和业务种类的涉密印制资质，应当符合涉密印制资质具体条件的要求。"},{"i":18,"n":"第十八条","txt":"申请甲级资质的，应当向国家保密行政管理部门提出申请；申请乙级资质的，应当向注册地的省级保密行政管理部门提出申请。申请单位应当提交以下材料： （一）《国家秘密载体印制资质申请书》（以下简称申请书）； （二）企业营业执照或者事业单位法人证书； （三）在登记机关备案的章程； （四）从事印刷、复制等经营活动的许可证明； （五）法定代表人、主要负责人、实际控制人、董（监）事会人员、高级管理人员以及从事涉密印制业务的其他人员情况； （六）资本结构和股权情况； （七）上一年度企业年度报告； （八）生产经营和办公场所的产权证书或者租赁合同； （九）近三年印制业务合同清单； （十）涉密印制业务设备、场所和保密设施、设备情况； （十一）基本管理制度、保密制度以及保密体系运行情况。 申请书及相关材料不得涉及国家秘密，申请单位应当对申请材料的真实性和完整性负责。"},{"i":19,"n":"第十九条","txt":"保密行政管理部门收到申请材料后，应当在五日内完成审查。申请材料齐全且符合法定形式的，应当受理并发出受理通知书；申请材料不齐全或者不符合法定形式的，应当一次告知申请单位十五日内补正材料；逾期未告知申请单位补正的，自收到申请材料之日起即为受理。申请单位十五日内不予补正的，视为放弃本次行政许可申请。"},{"i":20,"n":"第二十条","txt":"资质审查分为书面审查、现场审查。确有需要的，可以组织专家开展评审。"},{"i":21,"n":"第二十一条","txt":"对作出受理决定的，保密行政管理部门应当对提交的申请材料进行书面审查。"},{"i":22,"n":"第二十二条","txt":"对书面审查合格的单位，保密行政管理部门应当指派两名以上工作人员，并可以结合工作实际指派一名以上审查专家，依据涉密印制资质审查细则和评分标准，对保密制度、保密工作机构、保密监督管理、涉密人员管理、保密技术防护以及从事涉密印制业务的专业能力等情况进行现场审查。 涉密印制资质审查细则和评分标准由国家保密行政管理部门另行规定。"},{"i":23,"n":"第二十三条","txt":"现场审查应当按照以下程序进行： （一）提前五日以传真、电子邮件等形式书面通知申请单位现场审查时间； （二）听取申请单位情况汇报和对有关事项的说明； （三）审查有关材料； （四）与主要负责人、保密工作负责人及有关人员谈话了解情况； （五）组织涉密人员进行保密知识测试； （六）对涉密场所、涉密设备等进行实地查看； （七）汇总现场审查情况，形成现场审查报告； （八）通报审查情况，申请单位法定代表人或者主要负责人在现场审查报告上签字确认。"},{"i":24,"n":"第二十四条","txt":"申请单位具有下列情形之一的，保密行政管理部门应当终止审查： （一）隐瞒有关情况或者提供虚假材料的； （二）采取贿赂、请托等不正当手段，影响审查工作公平公正进行的； （三）无正当理由拒绝按通知时间接受现场审查的； （四）现场审查中发现不符合评分标准基本项的； （五）其他违反保密法律法规的行为。"},{"i":25,"n":"第二十五条","txt":"申请单位书面审查、现场审查合格的，保密行政管理部门应当准予行政许可。 申请单位具有下列情形之一的，保密行政管理部门应当作出不予行政许可的书面决定，说明理由并告知申请单位相关权利。 （一）书面审查不合格的； （二）现场审查不合格的； （三）终止审查的； （四）法律、行政法规规定的不予行政许可的其他情形。"},{"i":26,"n":"第二十六条","txt":"保密行政管理部门应当自受理申请之日起二十日内，对申请单位作出准予行政许可或者不予行政许可的决定。二十日内不能作出决定的，经本行政机关负责人批准，可以延长十日，并应当将延长期限的理由告知申请单位。 保密行政管理部门组织开展专家评审、鉴定所需时间不计入行政许可期限。"},{"i":27,"n":"第二十七条","txt":"保密行政管理部门作出准予行政许可的决定的，自作出决定之日起十日内向申请单位颁发《国家秘密载体印制资质证书》（以下简称《资质证书》）。"},{"i":28,"n":"第二十八条","txt":"《资质证书》有效期为五年，分为正本和副本，正本和副本具有同等法律效力。样式由国家保密行政管理部门统一制作，主要包括以下内容： （一）单位名称； （二）法定代表人； （三）注册地址； （四）证书编号； （五）资质等级； （六）业务种类； （七）发证机关； （八）有效期和发证日期。"},{"i":29,"n":"第二十九条","txt":"《资质证书》有效期满，需要继续从事涉密印制业务的，应当在有效期届满三个月前向保密行政管理部门提出延续申请，保密行政管理部门应当按照本办法有关规定开展审查，申请单位未按规定期限提出延续申请的，视为重新申请。 有效期届满且未准予延续前，不得签订新的涉密印制业务合同。对于已经签订合同但未完成的涉密业务，在确保安全保密的条件下可以继续完成。"},{"i":30,"n":"第三十条","txt":"省级保密行政管理部门应当将许可的乙级资质单位报国家保密行政管理部门备案。 准予行政许可和注销、吊销、撤销以及暂停资质的决定，由作出决定的保密行政管理部门在一定范围内予以发布。"},{"i":31,"n":"第三十一条","txt":"省级以上保密行政管理部门应当加强对下一级保密行政管理部门以及协助开展审查工作的专门机构的监督检查，及时纠正资质管理中的违法违规行为。"},{"i":32,"n":"第三十二条","txt":"保密行政管理部门应当开展“双随机”抽查、飞行检查等形式的保密检查，对资质单位从事涉密印制业务和保密管理情况进行监督。"},{"i":33,"n":"第三十三条","txt":"机关、单位委托资质单位印制国家秘密载体，应当查验其《资质证书》，出具委托证明，签订保密协议，提出保密要求，督促落实保密措施。 资质单位应当查验、收取委托方的委托证明，并进行登记。没有委托证明的，资质单位不得承接。"},{"i":34,"n":"第三十四条","txt":"资质单位与其他单位合作开展涉密印制业务的，合作单位应当具有相应的涉密印制资质且取得委托方书面同意。 资质单位不得将涉密印制业务分包或者转包给无相应涉密资质的单位。"},{"i":35,"n":"第三十五条","txt":"乙级资质单位拟在注册地的省级行政区域外承接涉密印制业务的，应当向业务所在地的省级保密行政管理部门备案，接受保密监督管理。"},{"i":36,"n":"第三十六条","txt":"资质单位实行年度自检制度，应当于每年3月31日前向作出准予行政许可决定的保密行政管理部门报送上一年度自检报告。"},{"i":37,"n":"第三十七条","txt":"资质单位下列事项发生变更的，应当在变更前向保密行政管理部门书面报告： （一）注册资本或者股权结构； （二）控股股东或者实际控制人； （三）单位性质或者隶属关系； （四）用于涉密印制业务的场所。 保密行政管理部门应当对资质单位变更事项进行书面审查。通过审查的，资质单位应当按照审定事项实施变更，并在变更完成后十日内提交情况报告。 对影响或者可能影响国家安全的外商投资，应当按照外商投资安全审查制度进行安全审查。 资质单位发生控股股东或者实际控制人、单位性质或者隶属关系、用于涉密印制业务的场所等事项变更的，保密行政管理部门应当组织现场审查。"},{"i":38,"n":"第三十八条","txt":"资质单位下列事项发生变更的，应当在变更后十日内向保密行政管理部门书面报告： （一）单位名称； （二）注册地址或者经营地址； （三）经营范围； （四）法定代表人、董（监）事会人员或者高级管理人员。 资质单位变更完成需换发《资质证书》的，由保密行政管理部门审核后重新颁发。"},{"i":39,"n":"第三十九条","txt":"保密行政管理部门在现场审查、保密检查过程中，发现申请单位或者资质单位存在涉嫌泄露国家秘密的案件线索，应当根据工作需要，按照泄密案件管辖权限，经保密行政管理部门负责人批准，由具备执法资格的人员对有关设施、设备、载体等采取登记保存措施，依法开展调查工作。 保密行政管理部门调查结束后，认定申请单位或者资质单位存在违反保密法律法规事实的，违法行为发生地的保密行政管理部门应当按照本办法作出处理，并将违法事实、处理结果抄告受理申请或者准予行政许可的保密行政管理部门。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，作出准予行政许可决定的保密行政管理部门或者其上级保密行政管理部门，依据职权可以撤销行政许可： （一）保密行政管理部门滥用职权、玩忽职守作出准予行政许可决定的； （二）超越法定职权作出准予行政许可决定的； （三）违反法定程序作出准予行政许可决定的； （四）对不具备申请资格或者不符合法定条件的申请单位准予行政许可的； （五）依法可以撤销行政许可的其他情形。 资质单位采取欺骗、贿赂等不正当手段取得资质的，保密行政管理部门应当撤销其资质，停止其涉密业务。自撤销之日起，三年内不得再次申请。"},{"i":41,"n":"第四十一条","txt":"资质单位具有下列情形之一的，作出准予行政许可决定的保密行政管理部门应当注销其资质： （一）《资质证书》有效期届满未延续的； （二）法人资格依法终止的； （三）主动申请注销资质的； （四）行政许可依法被撤销、撤回，或者行政许可证件依法被吊销的； （五）因不可抗力导致行政许可事项无法实施的； （六）法律、行政法规规定的应当注销资质的其他情形。"},{"i":42,"n":"第四十二条","txt":"申请单位或者资质单位对保密行政管理部门作出的决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":43,"n":"第四十三条","txt":"资质单位违反本办法的，依照本办法有关规定处理；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"资质单位具有下列情形之一的，保密行政管理部门应当责令其在二十日内完成整改，逾期不改或者整改后仍不符合要求的，给予六个月以上十二个月以下暂停资质的处罚： （一）未经委托方书面同意，擅自与其他涉密印制资质单位合作开展涉密印制业务的； （二）超出行政许可的业务种类范围承接涉密印制业务的； （三）发生需要报告的事项，未及时报告的； （四）未按本办法提交年度自检报告的； （五）不符合其他保密管理规定，存在泄密隐患的。"},{"i":45,"n":"第四十五条","txt":"资质单位不再符合申请条件，或者具有下列情形之一的，保密行政管理部门应当吊销其资质，停止其涉密业务： （一）涂改、出卖、出租、出借《资质证书》，或者以其他方式伪造、非法转让《资质证书》的； （二）将涉密印制业务分包或者转包给无相应涉密资质单位的； （三）发现国家秘密已经泄露或者可能泄露，未按法定时限报告的； （四）拒绝接受保密检查的； （五）资质暂停期间，承接新的涉密印制业务的； （六）资质暂停期满，仍不符合保密管理规定的； （七）发生泄密案件的； （八）其他违反保密法律法规的行为。"},{"i":46,"n":"第四十六条","txt":"申请单位隐瞒有关情况或者提供虚假材料的，保密行政管理部门应当作出不予受理或者不予行政许可的决定。自不予受理或者不予许可之日起，一年内不得再次申请。"},{"i":47,"n":"第四十七条","txt":"未经保密行政管理部门许可的单位从事涉密印制业务的，由保密行政管理部门责令停止违法行为，非法获取、持有的国家秘密载体，应当予以收缴；有违法所得的，由市场监督管理部门没收违法所得；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"机关、单位委托未经保密行政管理部门许可的单位从事涉密印制业务的，应当由有关机关、单位对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"保密行政管理部门及其工作人员未依法履行职责，或者滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予政务处分；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"机关、单位内部非经营性印刷厂、文印中心（室），承担本机关、单位涉密印制业务的，可不申请涉密印制资质，由本机关、单位按照保密要害部门部位进行管理，接受同级保密行政管理部门监督指导。"},{"i":51,"n":"第五十一条","txt":"申请单位资本结构包含香港特别行政区、澳门特别行政区、台湾地区投资者以及定居在国外中国公民投资者的，参照本办法管理。国家另有规定的，从其规定。"},{"i":52,"n":"第五十二条","txt":"本办法规定的实施行政许可的期限以工作日计算，不含法定节假日。"},{"i":53,"n":"第五十三条","txt":"本办法由国家保密局负责解释。"},{"i":54,"n":"第五十四条","txt":"本办法自2021年3月1日起施行。国家保密局、国家工商行政管理总局、国家新闻出版总署发布的《国家秘密载体印制资质管理办法》（国保发〔2012〕7号，国保发〔2019〕13号修订）同时废止。 附件：国家秘密载体印制资质具体条件 国家秘密载体印制资质具体条件 一、涉密文件资料 （一）甲级资质 1. 取得《印刷经营许可证》。 2. 上一个会计年度净资产不少于5000万元人民币。 3. 在本单位依法缴纳社保一年以上的人员不少于50名。 4. 具有自有产权或者租赁期3年（含）以上的固定生产经营场所，建筑面积不少于1000平方米。 5. 具备独立的保密室和涉密印制业务所必需的印制车间、成品库、废品库等功能场所，实行封闭式管理，周边环境安全可控。 （二）乙级资质 1. 取得《印刷经营许可证》。 2. 上一个会计年度净资产不少于500万元人民币。 3. 在本单位依法缴纳社保一年以上的人员不少于20名。"}],"guojiamimizaitiyinzhizizhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强国家秘密载体印制资质管理，确保国家秘密安全，根据《中华人民共和国保守国家秘密法》、《中华人民共和国行政许可法》、《中华人民共和国行政处罚法》、《中华人民共和国保守国家秘密法实施条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称国家秘密载体印制（以下简称涉密印制），是指以印刷、复制等方式制作国家秘密载体的行为。 涉密印制资质是指保密行政管理部门许可企业事业单位从事国家秘密载体印制业务的法定资格。"},{"i":3,"n":"第三条","txt":"涉密印制资质的申请、受理、审查、决定、使用和监督管理，适用本办法。"},{"i":4,"n":"第四条","txt":"从事涉密印制业务的企业事业单位应当依照本办法，取得涉密印制资质。 国家机关和涉及国家秘密的单位（以下简称机关、单位）应当选择具有涉密印制资质的单位（以下简称资质单位）承接涉密印制业务。"},{"i":5,"n":"第五条","txt":"涉密印制资质管理应当遵循依法管理、安全保密、科学发展、公平公正的原则。"},{"i":6,"n":"第六条","txt":"国家保密行政管理部门主管全国涉密印制资质管理工作，省级保密行政管理部门主管本行政区域内涉密印制资质管理工作。 省级以上保密行政管理部门根据工作需要，可以委托下一级保密行政管理部门开展审查工作，或者组织机构协助开展工作。"},{"i":7,"n":"第七条","txt":"省级以上保密行政管理部门应当指定专门机构承担保密资质管理日常工作。"},{"i":8,"n":"第八条","txt":"省级以上保密行政管理部门建立保密资质审查专家库，组织开展入库审查、培训考核等工作。"},{"i":9,"n":"第九条","txt":"实施涉密印制资质许可不收取任何费用，所需经费纳入同级财政预算。"},{"i":10,"n":"第十条","txt":"涉密印制资质分为甲级和乙级两个等级。 甲级资质单位可以从事绝密级、机密级、秘密级涉密印制业务；乙级资质单位可以从事机密级、秘密级涉密印制业务。"},{"i":11,"n":"第十一条","txt":"涉密印制资质包括涉密文件资料、国家统一考试试卷、涉密防伪票据证书、涉密光电磁介质、涉密档案数字化加工，以及国家保密行政管理部门许可的其他涉密印制业务。 资质单位应当在保密行政管理部门许可的业务种类范围内承接涉密印制业务。"},{"i":12,"n":"第十二条","txt":"申请单位应当具备以下基本条件： （一）在中华人民共和国境内注册的法人，从事印制业务三年以上，甲级资质申请单位还应当具备相应乙级资质三年以上； （二）无犯罪记录且近三年内未被吊销保密资质（资格），法定代表人、主要负责人、实际控制人未被列入失信人员名单； （三）法定代表人、主要负责人、实际控制人、董（监）事会人员、高级管理人员以及从事涉密印制业务人员具有中华人民共和国国籍，无境外永久居留权或者长期居留许可，与境外人员无婚姻关系，国家另有规定的除外； （四）具有从事涉密印制业务的专业能力； （五）法律、行政法规和国家保密行政管理部门规定的其他条件。"},{"i":13,"n":"第十三条","txt":"申请单位应当具备以下保密条件： （一）有专门机构或者人员负责保密工作； （二）保密制度完善； （三）从事涉密印制业务的人员经过保密教育培训，具备必要的保密知识和技能； （四）用于涉密印制业务的场所、设施、设备符合国家保密规定和标准； （五）有专门的保密工作经费； （六）法律、行政法规和国家保密行政管理部门规定的其他保密条件。"},{"i":14,"n":"第十四条","txt":"申请涉密文件资料、涉密光电磁介质、涉密档案数字化加工资质的单位不得有外国投资者投资。在新三板挂牌的企业申请资质以及资质有效期内的，还应当符合以下条件： （一）参与挂牌交易的股份比例不高于总股本的30%； （二）实际控制人在申请期间及资质有效期内保持控制地位不变。"},{"i":15,"n":"第十五条","txt":"申请国家统一考试试卷、涉密防伪票据证书资质的单位不得由外国投资者控股。"},{"i":16,"n":"第十六条","txt":"申请单位应当建立完善的内部管理和信息披露制度，未经国务院有关主管部门或者省级人民政府有关主管部门批准，外国投资者不得接触、知悉国家秘密信息。"},{"i":17,"n":"第十七条","txt":"申请单位申请不同等级和业务种类的涉密印制资质，应当符合涉密印制资质具体条件的要求。"},{"i":18,"n":"第十八条","txt":"申请甲级资质的，应当向国家保密行政管理部门提出申请；申请乙级资质的，应当向注册地的省级保密行政管理部门提出申请。申请单位应当提交以下材料： （一）《国家秘密载体印制资质申请书》（以下简称申请书）； （二）企业营业执照或者事业单位法人证书； （三）在登记机关备案的章程； （四）从事印刷、复制等经营活动的许可证明； （五）法定代表人、主要负责人、实际控制人、董（监）事会人员、高级管理人员以及从事涉密印制业务的其他人员情况； （六）资本结构和股权情况； （七）上一年度企业年度报告； （八）生产经营和办公场所的产权证书或者租赁合同； （九）近三年印制业务合同清单； （十）涉密印制业务设备、场所和保密设施、设备情况； （十一）基本管理制度、保密制度以及保密体系运行情况。 申请书及相关材料不得涉及国家秘密，申请单位应当对申请材料的真实性和完整性负责。"},{"i":19,"n":"第十九条","txt":"保密行政管理部门收到申请材料后，应当在五日内完成审查。申请材料齐全且符合法定形式的，应当受理并发出受理通知书；申请材料不齐全或者不符合法定形式的，应当一次告知申请单位十五日内补正材料；逾期未告知申请单位补正的，自收到申请材料之日起即为受理。申请单位十五日内不予补正的，视为放弃本次行政许可申请。"},{"i":20,"n":"第二十条","txt":"资质审查分为书面审查、现场审查。确有需要的，可以组织专家开展评审。"},{"i":21,"n":"第二十一条","txt":"对作出受理决定的，保密行政管理部门应当对提交的申请材料进行书面审查。"},{"i":22,"n":"第二十二条","txt":"对书面审查合格的单位，保密行政管理部门应当指派两名以上工作人员，并可以结合工作实际指派一名以上审查专家，依据涉密印制资质审查细则和评分标准，对保密制度、保密工作机构、保密监督管理、涉密人员管理、保密技术防护以及从事涉密印制业务的专业能力等情况进行现场审查。 涉密印制资质审查细则和评分标准由国家保密行政管理部门另行规定。"},{"i":23,"n":"第二十三条","txt":"现场审查应当按照以下程序进行： （一）提前五日以传真、电子邮件等形式书面通知申请单位现场审查时间； （二）听取申请单位情况汇报和对有关事项的说明； （三）审查有关材料； （四）与主要负责人、保密工作负责人及有关人员谈话了解情况； （五）组织涉密人员进行保密知识测试； （六）对涉密场所、涉密设备等进行实地查看； （七）汇总现场审查情况，形成现场审查报告； （八）通报审查情况，申请单位法定代表人或者主要负责人在现场审查报告上签字确认。"},{"i":24,"n":"第二十四条","txt":"申请单位具有下列情形之一的，保密行政管理部门应当终止审查： （一）隐瞒有关情况或者提供虚假材料的； （二）采取贿赂、请托等不正当手段，影响审查工作公平公正进行的； （三）无正当理由拒绝按通知时间接受现场审查的； （四）现场审查中发现不符合评分标准基本项的； （五）其他违反保密法律法规的行为。"},{"i":25,"n":"第二十五条","txt":"申请单位书面审查、现场审查合格的，保密行政管理部门应当准予行政许可。 申请单位具有下列情形之一的，保密行政管理部门应当作出不予行政许可的书面决定，说明理由并告知申请单位相关权利。 （一）书面审查不合格的； （二）现场审查不合格的； （三）终止审查的； （四）法律、行政法规规定的不予行政许可的其他情形。"},{"i":26,"n":"第二十六条","txt":"保密行政管理部门应当自受理申请之日起二十日内，对申请单位作出准予行政许可或者不予行政许可的决定。二十日内不能作出决定的，经本行政机关负责人批准，可以延长十日，并应当将延长期限的理由告知申请单位。 保密行政管理部门组织开展专家评审、鉴定所需时间不计入行政许可期限。"},{"i":27,"n":"第二十七条","txt":"保密行政管理部门作出准予行政许可的决定的，自作出决定之日起十日内向申请单位颁发《国家秘密载体印制资质证书》（以下简称《资质证书》）。"},{"i":28,"n":"第二十八条","txt":"《资质证书》有效期为五年，分为正本和副本，正本和副本具有同等法律效力。样式由国家保密行政管理部门统一制作，主要包括以下内容： （一）单位名称； （二）法定代表人； （三）注册地址； （四）证书编号； （五）资质等级； （六）业务种类； （七）发证机关； （八）有效期和发证日期。"},{"i":29,"n":"第二十九条","txt":"《资质证书》有效期满，需要继续从事涉密印制业务的，应当在有效期届满三个月前向保密行政管理部门提出延续申请，保密行政管理部门应当按照本办法有关规定开展审查，申请单位未按规定期限提出延续申请的，视为重新申请。 有效期届满且未准予延续前，不得签订新的涉密印制业务合同。对于已经签订合同但未完成的涉密业务，在确保安全保密的条件下可以继续完成。"},{"i":30,"n":"第三十条","txt":"省级保密行政管理部门应当将许可的乙级资质单位报国家保密行政管理部门备案。 准予行政许可和注销、吊销、撤销以及暂停资质的决定，由作出决定的保密行政管理部门在一定范围内予以发布。"},{"i":31,"n":"第三十一条","txt":"省级以上保密行政管理部门应当加强对下一级保密行政管理部门以及协助开展审查工作的专门机构的监督检查，及时纠正资质管理中的违法违规行为。"},{"i":32,"n":"第三十二条","txt":"保密行政管理部门应当开展“双随机”抽查、飞行检查等形式的保密检查，对资质单位从事涉密印制业务和保密管理情况进行监督。"},{"i":33,"n":"第三十三条","txt":"机关、单位委托资质单位印制国家秘密载体，应当查验其《资质证书》，出具委托证明，签订保密协议，提出保密要求，督促落实保密措施。 资质单位应当查验、收取委托方的委托证明，并进行登记。没有委托证明的，资质单位不得承接。"},{"i":34,"n":"第三十四条","txt":"资质单位与其他单位合作开展涉密印制业务的，合作单位应当具有相应的涉密印制资质且取得委托方书面同意。 资质单位不得将涉密印制业务分包或者转包给无相应涉密资质的单位。"},{"i":35,"n":"第三十五条","txt":"乙级资质单位拟在注册地的省级行政区域外承接涉密印制业务的，应当向业务所在地的省级保密行政管理部门备案，接受保密监督管理。"},{"i":36,"n":"第三十六条","txt":"资质单位实行年度自检制度，应当于每年3月31日前向作出准予行政许可决定的保密行政管理部门报送上一年度自检报告。"},{"i":37,"n":"第三十七条","txt":"资质单位下列事项发生变更的，应当在变更前向保密行政管理部门书面报告： （一）注册资本或者股权结构； （二）控股股东或者实际控制人； （三）单位性质或者隶属关系； （四）用于涉密印制业务的场所。 保密行政管理部门应当对资质单位变更事项进行书面审查。通过审查的，资质单位应当按照审定事项实施变更，并在变更完成后十日内提交情况报告。 对影响或者可能影响国家安全的外商投资，应当按照外商投资安全审查制度进行安全审查。 资质单位发生控股股东或者实际控制人、单位性质或者隶属关系、用于涉密印制业务的场所等事项变更的，保密行政管理部门应当组织现场审查。"},{"i":38,"n":"第三十八条","txt":"资质单位下列事项发生变更的，应当在变更后十日内向保密行政管理部门书面报告： （一）单位名称； （二）注册地址或者经营地址； （三）经营范围； （四）法定代表人、董（监）事会人员或者高级管理人员。 资质单位变更完成需换发《资质证书》的，由保密行政管理部门审核后重新颁发。"},{"i":39,"n":"第三十九条","txt":"保密行政管理部门在现场审查、保密检查过程中，发现申请单位或者资质单位存在涉嫌泄露国家秘密的案件线索，应当根据工作需要，按照泄密案件管辖权限，经保密行政管理部门负责人批准，由具备执法资格的人员对有关设施、设备、载体等采取登记保存措施，依法开展调查工作。 保密行政管理部门调查结束后，认定申请单位或者资质单位存在违反保密法律法规事实的，违法行为发生地的保密行政管理部门应当按照本办法作出处理，并将违法事实、处理结果抄告受理申请或者准予行政许可的保密行政管理部门。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，作出准予行政许可决定的保密行政管理部门或者其上级保密行政管理部门，依据职权可以撤销行政许可： （一）保密行政管理部门滥用职权、玩忽职守作出准予行政许可决定的； （二）超越法定职权作出准予行政许可决定的； （三）违反法定程序作出准予行政许可决定的； （四）对不具备申请资格或者不符合法定条件的申请单位准予行政许可的； （五）依法可以撤销行政许可的其他情形。 资质单位采取欺骗、贿赂等不正当手段取得资质的，保密行政管理部门应当撤销其资质，停止其涉密业务。自撤销之日起，三年内不得再次申请。"},{"i":41,"n":"第四十一条","txt":"资质单位具有下列情形之一的，作出准予行政许可决定的保密行政管理部门应当注销其资质： （一）《资质证书》有效期届满未延续的； （二）法人资格依法终止的； （三）主动申请注销资质的； （四）行政许可依法被撤销、撤回，或者行政许可证件依法被吊销的； （五）因不可抗力导致行政许可事项无法实施的； （六）法律、行政法规规定的应当注销资质的其他情形。"},{"i":42,"n":"第四十二条","txt":"申请单位或者资质单位对保密行政管理部门作出的决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":43,"n":"第四十三条","txt":"资质单位违反本办法的，依照本办法有关规定处理；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"资质单位具有下列情形之一的，保密行政管理部门应当责令其在二十日内完成整改，逾期不改或者整改后仍不符合要求的，给予六个月以上十二个月以下暂停资质的处罚： （一）未经委托方书面同意，擅自与其他涉密印制资质单位合作开展涉密印制业务的； （二）超出行政许可的业务种类范围承接涉密印制业务的； （三）发生需要报告的事项，未及时报告的； （四）未按本办法提交年度自检报告的； （五）不符合其他保密管理规定，存在泄密隐患的。"},{"i":45,"n":"第四十五条","txt":"资质单位不再符合申请条件，或者具有下列情形之一的，保密行政管理部门应当吊销其资质，停止其涉密业务： （一）涂改、出卖、出租、出借《资质证书》，或者以其他方式伪造、非法转让《资质证书》的； （二）将涉密印制业务分包或者转包给无相应涉密资质单位的； （三）发现国家秘密已经泄露或者可能泄露，未按法定时限报告的； （四）拒绝接受保密检查的； （五）资质暂停期间，承接新的涉密印制业务的； （六）资质暂停期满，仍不符合保密管理规定的； （七）发生泄密案件的； （八）其他违反保密法律法规的行为。"},{"i":46,"n":"第四十六条","txt":"申请单位隐瞒有关情况或者提供虚假材料的，保密行政管理部门应当作出不予受理或者不予行政许可的决定。自不予受理或者不予许可之日起，一年内不得再次申请。"},{"i":47,"n":"第四十七条","txt":"未经保密行政管理部门许可的单位从事涉密印制业务的，由保密行政管理部门责令停止违法行为，非法获取、持有的国家秘密载体，应当予以收缴；有违法所得的，由市场监督管理部门没收违法所得；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"机关、单位委托未经保密行政管理部门许可的单位从事涉密印制业务的，应当由有关机关、单位对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"保密行政管理部门及其工作人员未依法履行职责，或者滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予政务处分；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"机关、单位内部非经营性印刷厂、文印中心（室），承担本机关、单位涉密印制业务的，可不申请涉密印制资质，由本机关、单位按照保密要害部门部位进行管理，接受同级保密行政管理部门监督指导。"},{"i":51,"n":"第五十一条","txt":"申请单位资本结构包含香港特别行政区、澳门特别行政区、台湾地区投资者以及定居在国外中国公民投资者的，参照本办法管理。国家另有规定的，从其规定。"},{"i":52,"n":"第五十二条","txt":"本办法规定的实施行政许可的期限以工作日计算，不含法定节假日。"},{"i":53,"n":"第五十三条","txt":"本办法由国家保密局负责解释。"},{"i":54,"n":"第五十四条","txt":"本办法自2021年3月1日起施行。国家保密局、国家工商行政管理总局、国家新闻出版总署发布的《国家秘密载体印制资质管理办法》（国保发〔2012〕7号，国保发〔2019〕13号修订）同时废止。 附 件 国家秘密载体印制资质具体条件 一、 涉密文件资料 （一）甲级资质 1. 取得《印刷经营许可证》。 2. 上一个会计年度净资产不少于5000万元人民币。 3. 在本单位依法缴纳社保一年以上的人员不少于50名。 4. 具有自有产权或者租赁期3年（含）以上的固定生产经营场所，建筑面积不少于1000平方米。 5. 具备独立的保密室和涉密印制业务所必需的印制车间、成品库、废品库等功能场所，实行封闭式管理，周边环境安全可控。 （二）乙级资质 1. 取得《印刷经营许可证》。 2. 上一个会计年度净资产不少于500万元人民币。 3. 在本单位依法缴纳社保一年以上的人员不少于20名。 4. 具有自有产权或者租"}],"guojiamimijiandinggongzuoguiding":[{"i":1,"n":"第一条","txt":"为了规范国家秘密鉴定工作，根据《中华人民共和国保守国家秘密法》及其实施条例，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称国家秘密鉴定，是指保密行政管理部门对涉嫌泄露国家秘密案件中有关事项是否属于国家秘密以及属于何种密级进行鉴别和认定的活动。"},{"i":3,"n":"第三条","txt":"国家秘密鉴定的申请、受理、办理、复核、监督等，适用本规定。"},{"i":4,"n":"第四条","txt":"国家秘密鉴定应当遵循依法、客观、公正的原则，做到事实清楚、依据充分、程序规范、结论准确。"},{"i":5,"n":"第五条","txt":"办理涉嫌泄露国家秘密案件的纪检监察、侦查、公诉、审判机关（以下统称办案机关）可以申请国家秘密鉴定。 国家保密行政管理部门、省（自治区、直辖市）保密行政管理部门负责国家秘密鉴定。"},{"i":6,"n":"第六条","txt":"国家秘密鉴定应当以保密法律法规、保密事项范围和国家秘密确定、变更、解除文件为依据。"},{"i":7,"n":"第七条","txt":"下列事项不得鉴定为国家秘密： （一）需要公众广泛知晓或者参与的； （二）属于工作秘密、商业秘密、个人隐私的； （三）已经依法公开或者泄露前已经无法控制知悉范围的； （四）法律、法规或者国家有关规定要求公开的； （五）其他泄露后对国家安全和利益不会造成损害的。"},{"i":8,"n":"第八条","txt":"中央一级办案机关申请国家秘密鉴定的，应当向国家保密行政管理部门提出。省级及以下办案机关申请国家秘密鉴定的，应当向所在地省（自治区、直辖市）保密行政管理部门提出。 国家保密行政管理部门可以根据工作需要，对省（自治区、直辖市）保密行政管理部门负责鉴定的重大、疑难、复杂事项直接进行鉴定。"},{"i":9,"n":"第九条","txt":"办案机关申请国家秘密鉴定，应当提交下列材料： （一）申请国家秘密鉴定的公文； （二）需要进行国家秘密鉴定的事项（以下简称鉴定事项）及鉴定事项清单； （三）进行国家秘密鉴定需要掌握的有关情况说明，包括案件基本情况、鉴定事项来源、泄露对象和时间、回避建议等。"},{"i":10,"n":"第十条","txt":"申请国家秘密鉴定的公文应当以办案机关名义作出，说明认为相关事项涉嫌属于国家秘密的理由或者依据。 鉴定事项属于咨询意见、聊天记录、讯（询）问笔录、视听资料、电子数据、物品等的，办案机关应当进行筛查和梳理，明确其中涉嫌属于国家秘密、需要申请鉴定的具体内容。 鉴定事项不属于中文的，办案机关应当同时提供中文译本。保密行政管理部门就办案机关提供的中文译本进行鉴定。"},{"i":11,"n":"第十一条","txt":"国家秘密鉴定申请有下列情形之一的，保密行政管理部门不予受理： （一）申请机关和申请方式不符合本规定第五条、第八条要求的； （二）办案机关已就同一鉴定事项申请国家秘密鉴定的； （三）鉴定事项内容明显属于捏造的，或者无法核实真伪、来源的； （四）未按本规定第九条、第十条提供材料，或者修改、补充后仍不符合要求的； （五）其他不符合法律、法规、规章规定的情形。"},{"i":12,"n":"第十二条","txt":"保密行政管理部门应当自收到申请国家秘密鉴定的公文之日起5日内，对相关材料进行审查，作出是否受理的决定，并告知办案机关。 经审查认为办案机关提交的材料存在瑕疵、不完整或者不能满足鉴定需要的，应当通知办案机关予以修改或者补充。审查受理时间自相关材料修改完成或者补齐之日起计算。 经审查决定不予受理的，应当说明理由并退还相关材料。"},{"i":13,"n":"第十三条","txt":"办案机关不服不予受理决定的，可以在接到通知之日起10日内，向作出不予受理决定的保密行政管理部门提出书面异议，并按照本规定第九条、第十条规定提供相关材料。 保密行政管理部门应当在10日内，对相关材料进行审查，对符合受理条件的，作出受理决定；对不应受理的，书面告知提出异议的机关并退还相关材料。 省级及以下办案机关提出异议后，对省（自治区、直辖市）保密行政管理部门再次作出的不予受理决定仍有异议的，可以向国家保密行政管理部门提出书面异议。国家保密行政管理部门经审查认为确实不应受理的，书面告知提出异议的机关并退还相关材料；对符合受理条件的，应当要求作出不予受理决定的保密行政管理部门受理鉴定申请。"},{"i":14,"n":"第十四条","txt":"受理鉴定申请后，保密行政管理部门应当就下列情况向鉴定事项产生单位征求鉴定意见： （一）鉴定事项是否由其产生，内容是否真实； （二）鉴定事项是否已经按照法定程序确定、变更、解除国家秘密，及其时间、理由和依据； （三）鉴定事项是否应当属于国家秘密及何种密级，是否应当变更或者解除国家秘密，及其理由和依据。"},{"i":15,"n":"第十五条","txt":"存在鉴定事项产生单位不明确，涉及多个机关、单位以及行业、领域，或者有关单位鉴定意见不明确、理由和依据不充分等情形的，保密行政管理部门可以向有关业务主管部门或者相关机关、单位征求鉴定意见。 鉴定事项属于执行、办理已经确定的国家秘密事项的，受理鉴定的保密行政管理部门可以根据工作需要，向原定密单位或者有关业务主管部门征求鉴定意见。"},{"i":16,"n":"第十六条","txt":"国家保密行政管理部门受理鉴定后，对属于地方各级机关、单位产生的鉴定事项，可以征求鉴定事项产生地省（自治区、直辖市）保密行政管理部门鉴定意见。 省（自治区、直辖市）保密行政管理部门受理鉴定后，对属于中央和国家机关产生的鉴定事项，应当直接征求该中央和国家机关鉴定意见；对属于其他地方机关、单位产生的鉴定事项，应当征求相关省（自治区、直辖市）保密行政管理部门鉴定意见。"},{"i":17,"n":"第十七条","txt":"保密行政管理部门征求机关、单位鉴定意见的，机关、单位应当予以配合，按照要求及时提出鉴定意见或者提供相关材料。"},{"i":18,"n":"第十八条","txt":"鉴定事项重大、疑难、复杂或者专业性强、涉及专门技术等问题的，保密行政管理部门可以向相关领域专家进行咨询，为作出国家秘密鉴定结论提供参考。"},{"i":19,"n":"第十九条","txt":"对拟鉴定为国家秘密的事项，保密行政管理部门可以根据工作需要，组织有关机关、单位或者专家对其泄露后已经或者可能造成的危害进行评估。"},{"i":20,"n":"第二十条","txt":"国家秘密鉴定结论应当按照保密法律法规和保密事项范围等鉴定依据，在分析研判有关意见基础上，报保密行政管理部门负责人审批后作出。"},{"i":21,"n":"第二十一条","txt":"省（自治区、直辖市）保密行政管理部门对中央和国家机关、其他省（自治区、直辖市）保密行政管理部门答复的鉴定意见有异议的，或者认为本地区产生的绝密级事项鉴定依据不明确、有争议的，报国家保密行政管理部门审核后，作出鉴定结论。"},{"i":22,"n":"第二十二条","txt":"保密行政管理部门作出鉴定结论应当出具国家秘密鉴定书。国家秘密鉴定书应当包括以下内容： （一）鉴定事项名称或者内容； （二）鉴定依据和鉴定结论； （三）其他需要说明的情况； （四）鉴定机关名称和鉴定日期。 国家秘密鉴定书应当加盖保密行政管理部门印章。"},{"i":23,"n":"第二十三条","txt":"保密行政管理部门应当在受理国家秘密鉴定申请后30日内作出鉴定结论并出具国家秘密鉴定书。因鉴定事项疑难、复杂等不能按期出具国家秘密鉴定书的，经保密行政管理部门负责人批准，可以适当延长工作时限，延长时限最长不超过30日。 保密行政管理部门征求有关机关、单位鉴定意见，进行专家咨询时，应当明确答复期限，一般不超过15日；对鉴定事项数量较多、疑难、复杂等情况的，经双方协商，可以延长15日。 机关、单位提出鉴定意见，专家咨询等时间不计入保密行政管理部门国家秘密鉴定办理期限。"},{"i":24,"n":"第二十四条","txt":"办案机关有明确理由或者证据证明保密行政管理部门作出的鉴定结论可能错误的，可以向国家保密行政管理部门申请复核。"},{"i":25,"n":"第二十五条","txt":"办案机关申请复核的，应当提交申请复核的公文，说明申请复核的内容和理由，按照本规定第九条、第十条要求提供相关材料，并附需要进行复核的国家秘密鉴定书。"},{"i":26,"n":"第二十六条","txt":"国家保密行政管理部门受理复核申请后，应当向作出鉴定结论的保密行政管理部门调阅鉴定档案、了解有关情况，对其鉴定程序是否规范、依据是否明确、理由是否充分、结论是否准确等进行审核，并根据需要征求有关机关、单位鉴定意见，进行专家咨询或者组织开展危害评估。"},{"i":27,"n":"第二十七条","txt":"国家秘密鉴定复核结论应当按照保密法律法规和保密事项范围等鉴定依据，在分析研判原鉴定情况以及有关意见基础上，报国家保密行政管理部门主要负责人审批后作出。 国家保密行政管理部门的复核结论为最终结论。"},{"i":28,"n":"第二十八条","txt":"国家保密行政管理部门作出复核结论应当出具国家秘密鉴定复核决定书。 国家秘密鉴定复核决定书维持原国家秘密鉴定结论的，应当说明依据或者理由；改变原国家秘密鉴定结论的，应当作出最终的鉴定结论并说明依据或者理由。 国家秘密鉴定复核决定书应当以国家保密行政管理部门名义作出，并加盖印章，抄送作出原国家秘密鉴定结论的省（自治区、直辖市）保密行政管理部门。"},{"i":29,"n":"第二十九条","txt":"国家保密行政管理部门应当在受理国家秘密鉴定复核申请后60日内作出复核结论并出具复核决定书。因鉴定事项疑难、复杂等不能按期出具国家秘密鉴定复核决定书的，经国家保密行政管理部门主要负责人批准，可以适当延长工作时限，延长时限最长不超过30日。 征求机关、单位鉴定意见，专家咨询时限按照本规定第二十三条第二、三款办理。"},{"i":30,"n":"第三十条","txt":"国家秘密鉴定工作人员与案件有利害关系或者其他关系可能影响公正鉴定的，应当自行回避；办案机关发现上述情形的，有权申请其回避。国家秘密鉴定工作人员的回避，由其所属保密行政管理部门决定。 机关、单位配合开展国家秘密鉴定工作的人员以及有关专家与案件有利害关系或者其他关系可能影响公正鉴定的，应当回避。"},{"i":31,"n":"第三十一条","txt":"保密行政管理部门向机关、单位征求鉴定意见以及组织专家咨询时，应当对鉴定事项作以下处理： （一）对涉及不同机关、单位或者行业、领域的内容进行拆分，不向机关、单位或者专家提供与其无关、不应由其知悉的内容； （二）对涉嫌违法犯罪的责任单位或者责任人姓名等作遮盖、删除处理，不向机关、单位或者专家透露案情以及案件办理情况。"},{"i":32,"n":"第三十二条","txt":"保密行政管理部门及其工作人员，配合开展国家秘密鉴定工作的机关、单位及其工作人员，以及有关专家，应当对国家秘密鉴定工作以及工作中知悉的国家秘密、工作秘密、商业秘密、个人隐私予以保密。 保密行政管理部门在征求鉴定意见、组织专家咨询等过程中，应当向有关机关、单位或者专家明确保密要求，必要时组织签订书面保密承诺。"},{"i":33,"n":"第三十三条","txt":"国家秘密鉴定结论与机关、单位定密情况不一致的，保密行政管理部门应当通知机关、单位予以变更或者纠正；对机关、单位未依法履行定密管理职责、情节严重的，予以通报。"},{"i":34,"n":"第三十四条","txt":"省（自治区、直辖市）保密行政管理部门应当将年度国家秘密鉴定工作情况和作出的国家秘密鉴定结论报国家保密行政管理部门。"},{"i":35,"n":"第三十五条","txt":"保密行政管理部门依法办理国家秘密鉴定，不受其他机关、单位，社会团体和个人干涉。 保密行政管理部门未依法履行职责，或者滥用职权、玩忽职守、徇私舞弊的，对负有责任的领导人员和直接责任人员依法进行处理；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"在国家秘密鉴定工作中，负有配合鉴定义务的机关、单位及其工作人员拒不配合，弄虚作假，故意出具错误鉴定意见，造成严重后果的，对直接负责的主管人员和其他直接责任人员依法进行处理；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"保密行政管理部门办理涉嫌泄露国家秘密案件时，可以根据工作需要，按照本规定直接进行国家秘密鉴定。 鉴定事项产生单位属于军队或者鉴定事项涉嫌属于军事秘密的，由军队相关军级以上单位保密工作机构进行国家秘密鉴定或者协助提出鉴定意见。"},{"i":38,"n":"第三十八条","txt":"执行本规定所需要的文书式样，由国家保密行政管理部门统一制定。工作中需要的其他文书，国家保密行政管理部门没有制定式样的，省（自治区、直辖市）保密行政管理部门可以自行制定式样。"},{"i":39,"n":"第三十九条","txt":"本规定由国家保密局负责解释。"},{"i":40,"n":"第四十条","txt":"本规定自2021年9月1日起施行。2013年7月15日国家保密局发布的《密级鉴定工作规定》（国保发〔2013〕5号）同时废止。"}],"guofangkexuejishujianglibanfa":[{"i":1,"n":"第一条","txt":"为了奖励在推动国防科学技术进步中做出突出贡献的单位和个人，鼓励自主创新，促进国防现代化建设和国民经济的发展，根据《国家科学技术奖励条例》及其实施细则，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国工业和信息化部（以下简称工业和信息化部）设立下列国防科学技术奖： （一）国防技术发明奖； （二）国防科学技术进步奖； （三）国防科技工业杰出人才奖。"},{"i":3,"n":"第三条","txt":"国防科学技术奖励工作贯彻“尊重劳动、尊重知识、尊重人才、尊重创造”的方针，坚持精神奖励与物质奖励相结合的原则。"},{"i":4,"n":"第四条","txt":"为了维护国防科学技术奖的严肃性，国防科学技术奖的评审、授予，不受任何组织和个人的非法干涉。"},{"i":5,"n":"第五条","txt":"国防科学技术奖的评审和管理工作要严格保守国家秘密，尊重和保护知识产权。"},{"i":6,"n":"第六条","txt":"国防技术发明奖授予在国防建设和因保密不能公开的军民结合技术开发中运用科学技术知识做出产品、工艺、材料及其系统等技术发明成果的单位和个人。 前款所称技术发明成果应当具备下列条件： （一）前人尚未发明或者尚未公开； （二）具有先进性和创造性； （三）经实施，创造显著的军事效益、社会效益或者经济效益。"},{"i":7,"n":"第七条","txt":"国防科学技术进步奖授予在完成下列创新科技成果中做出突出贡献的单位和个人： （一）在武器装备及其配套产品的科研、生产、试验及相关工作中取得的科技成果； （二）在军民结合高技术产业的型号工程及技术、产品开发和成果转化中取得的因保密不能公开的科技成果； （三）在国防基础性技术研究中取得的科技成果； （四）在为决策科学化和管理现代化而进行的国防科技工业软科学研究中取得的科技成果。"},{"i":8,"n":"第八条","txt":"国防科技工业杰出人才奖授予在国防科学技术研究和技术开发中做出杰出贡献的下列科学技术工作者： （一）在当代国防科学技术前沿取得重大突破或者在国防科学技术发展中有卓越建树的； （二）在国防科学技术研究、型号研制和军民结合高技术产业化等领域及重大工程建设项目中，取得重大创新性成果，创造显著军事效益、社会效益或者经济效益的。 国防科技工业杰出人才奖的推荐、评审、授予等具体办法另行制定。"},{"i":9,"n":"第九条","txt":"国防技术发明奖和国防科学技术进步奖分为特等奖、一等奖、二等奖、三等奖4个等级。"},{"i":10,"n":"第十条","txt":"国防技术发明奖和国防科学技术进步奖实行限额申报、限额授奖，每年评审一次。"},{"i":11,"n":"第十一条","txt":"工业和信息化部设立国防科学技术奖励委员会（以下简称奖励委员会），负责国防科学技术奖的管理。 国防科学技术奖评审的组织工作，委托国家国防科技工业局（以下简称国防科工局）负责。"},{"i":12,"n":"第十二条","txt":"奖励委员会的主要职责： （一）审定国防科学技术奖励项目评审结果； （二）监督国防科学技术奖励项目的申报、评审和异议处理工作； （三）对国防科学技术奖励工作提供政策性意见和建议。"},{"i":13,"n":"第十三条","txt":"奖励委员会由19-23人组成。主任由工业和信息化部部级领导担任。成员分别由国防科技领域的专家和有关行政主管部门的负责同志组成。组成人选由工业和信息化部相关司局提出，征求 国防科工局意见后，由工业和信息化部批准。 奖励委员会实行聘任制，每届任期三年。"},{"i":14,"n":"第十四条","txt":"奖励委员会下设评审委员会，主要职责： （一）对各专业评审委员会初评通过的国防科学技术奖项目进行评审； （二）向奖励委员会报告国防科学技术奖励项目的评审结果； （三）向奖励委员会报告国防科学技术奖励项目的申报、评审和异议处理情况； （四）协调处理重大异议及评审工作中出现的其他问题。"},{"i":15,"n":"第十五条","txt":"评审委员会由25-29人组成。主任由国防科工局负责同志担任，委员分别由各专业评审委员会主任、本专业专家，以及行政主管部门负责同志组成。评审委员会成员由国防科工局批准。"},{"i":16,"n":"第十六条","txt":"根据工作需要，评审委员会可设若干专业评审委员会，负责相应专业的国防科学技术奖励项目的初评；各专业评审委员会成员由国防科工局批准。"},{"i":17,"n":"第十七条","txt":"奖励委员会的日常工作由工业和信息化部相关司局承担，评审委员会、专业评审委员会的日常工作由国防科工局负责。"},{"i":18,"n":"第十八条","txt":"国防技术发明奖和国防科学技术进步奖的项目不得重复申报。已申报国家级或其他省部级科技奖励的项目，不得再申报国防技术发明奖或国防科学技术进步奖。同一技术内容不能同时申报国防技术发明奖和国防科学技术进步奖。 在技术上又取得重大进步或新的突破的，可就其进步或突破的部分申报国防技术发明奖或国防科学技术进步奖。"},{"i":19,"n":"第十九条","txt":"申报国防技术发明奖和国防科学技术进步奖项目必须按规定格式填写相应的《国防科学技术奖申报书》，并提供所要求的附件材料及相应的电子文档。提供的有关材料必须真实、可靠。"},{"i":20,"n":"第二十条","txt":"申报国防技术发明奖和国防科学技术进步奖的材料应按下列渠道报送： （一）军工集团公司负责对其所属单位申报项目材料进行审查后，统一报送国防科工局。 （二）各省、自治区、直辖市国防科学技术工业行政主管部门，负责对本地区承担军工任务的地方单位申报项目材料审查后，统一报送国防科工局。 （三）工业和信息化部所属单位和国防科工局所属单位对申报项目材料审查后，直接报送国防科工局； （四）其他企事业单位申报项目材料，由其主管部门（单位）审查后报送国防科工局。"},{"i":21,"n":"第二十一条","txt":"国防技术发明奖和国防科学技术进步奖的奖励等级按下列指标进行综合评定： （一）自主创新程度； （二）难易程度、复杂程度； （三）先进程度； （四）成熟性、完备性； （五）综合效益（军事效益、社会效益、经济效益）； （六）应用情况与效果、科学技术价值。"},{"i":22,"n":"第二十二条","txt":"申报国防技术发明奖和国防科学技术进步奖的项目，由国防科工局进行形式审查后，按所属专业划分到相应的专业评审委员会进行初评。"},{"i":23,"n":"第二十三条","txt":"专业评审委员会的初评结果应在适当范围内公布。自公布之日起50日内为异议期。自公布之日起70日内异议处理完毕的，继续参加本年度评审；自公布之日起一年内异议处理完毕的， 提交下一年度评审；自公布之日起一年后异议处理完毕的，可以重新申报。"},{"i":24,"n":"第二十四条","txt":"经过异议程序后，各专业评审委员会的初评结果，提交评审委员会进行评审。"},{"i":25,"n":"第二十五条","txt":"评审委员会对初评通过的奖励项目进行评审后，将评审结果，以及奖励项目和奖励等级的建议提交奖励委员会审定，并向奖励委员会报告申报、评审和异议处理工作情况。"},{"i":26,"n":"第二十六条","txt":"奖励委员会对评审结果，以及获奖人选和奖励等级的建议进行审定。符合授奖条件的项目，由工业和信息化部批准授奖，向获奖人员和单位颁发奖励证书，并按有关规定颁发奖金。"},{"i":27,"n":"第二十七条","txt":"国防技术发明奖和国防科学技术进步奖采取评委集体讨论、投票的方法进行评审。特等奖和一等奖项目，应有投票人数三分之二及以上的票数通过，二等奖和三等奖项目，应有投票人数五分之三及以上的票数通过。 奖励委员会、评审委员会和专业评审委员会的评审表决应当有三分之二以上多数（含三分之二）委员参加，表决结果方有效。"},{"i":28,"n":"第二十八条","txt":"国防技术发明奖和国防科学技术进步奖的评审实行回避制度。被评项目的完成人或来自项目完成单位的人员是评委的，在该项目讨论和投票时均应回避。"},{"i":29,"n":"第二十九条","txt":"获奖人员的情况及主要贡献，应记入本人档案，作为综合考核、评价科技人员的依据之一。"},{"i":30,"n":"第三十条","txt":"奖金应按完成单位、完成人的贡献大小进行合理分配，不得挪作它用。"},{"i":31,"n":"第三十一条","txt":"国防科学技术奖的奖金数额由国防科工局商请财政部规定。国防科学技术奖的奖励经费由中央财政列支。"},{"i":32,"n":"第三十二条","txt":"在异议期内，任何单位和个人都有权对公布国防技术发明奖和国防科学技术进步奖项目的内容真实性、成果权属、获奖资格、完成单位和完成人及其排序等问题提出异议。"},{"i":33,"n":"第三十三条","txt":"对公布国防技术发明奖和国防科学技术进步奖项目提出异议的，要填写异议书，并提供必要的证明材料。有下列情况之一的不予受理： （一）匿名的异议； （二）无正当理由超过异议期提出的异议； （三）关于奖励等级的异议。"},{"i":34,"n":"第三十四条","txt":"申报单位内部提出的异议，由申报单位负责处理；军工集团公司所属单位间的异议由军工集团公司负责处理；各军工集团公司之间的异议，以及其他的单位和个人提出的异议，由国防 必要时，国防科工局可以组织评审委员和专家对重大异议进行调查，提出处理意见。"},{"i":35,"n":"第三十五条","txt":"对于剽窃、侵占他人科技成果的，或者以其他不正当手段骗取国防科学技术奖的，经工业和信息化部批准后，撤销其奖励，追回奖励证书和奖金，并建议其主管部门或单位依法给予处分。"},{"i":36,"n":"第三十六条","txt":"参与国防科学技术奖评审活动和有关工作的人员在评审活动中弄虚作假、徇私舞弊的，建议有关部门或单位依法给予处分。"},{"i":37,"n":"第三十七条","txt":"本办法的实施细则由国防科工局负责制定。"},{"i":38,"n":"第三十八条","txt":"本办法自2010年7月1日起施行。 2006年12月27日发布的《国防科学技术奖励办法》（国防科学技术工业委员会令第19号）同时废止。"}],"guofangkexuejishugongyeweiyuanhuitingzhengguize-2":[{"i":1,"n":"第一条","txt":"为了规范听证行为，维护公民、法人和其他组织的合法权益，促进依法行政，根据有关法律、行政法规，制定本规则。"},{"i":2,"n":"第二条","txt":"国防科学技术工业委员会（以下简称国防科工委）根据当事人的申请组织的听证和依据职权主动组织的听证适用本规则。 本规则所称当事人，包括行政处罚当事人、行政许可申请人和行政许可利害关系人。"},{"i":3,"n":"第三条","txt":"听证应当遵循公平、公正、便民和效率的原则。除涉及国家秘密、商业秘密或者个人隐私外，听证应当公开举行。"},{"i":4,"n":"第四条","txt":"依据当事人申请组织的听证，由法制工作机构负责实施；依据职权主动组织的听证，由听证事项承办部门负责实施。"},{"i":5,"n":"第五条","txt":"听证不得向当事人收取或者变相收取任何费用。"},{"i":6,"n":"第六条","txt":"听证人员包括听证主持人、听证员和记录员。 听证主持人由听证组织部门的有关负责人担任并报委领导批准，负责主持听证会。 听证员、记录员由听证组织部门指定，协助听证主持人工作。 行政处罚或者行政许可听证事项的具体承办人员，不得作为听证主持人、听证员和记录员。"},{"i":7,"n":"第七条","txt":"听证由一名听证主持人、两名听证员组织，也可视具体情况由一名听证主持人组织。"},{"i":8,"n":"第八条","txt":"听证人员应当公正地履行职责，保证听证参加人行使陈述、申辩、质证等权利，对听证中知悉的国家秘密、商业秘密和个人隐私负有保密的义务。"},{"i":9,"n":"第九条","txt":"当事人认为听证人员与听证事项有利害关系可能影响公正的，有权申请回避，并说明理由。 听证主持人的回避由委领导决定；听证员和记录员的回避由听证组织部门决定。"},{"i":10,"n":"第十条","txt":"听证参加人包括行政处罚或者行政许可事项的具体承办人、当事人、听证会代表、鉴定人、证人、翻译人员等。 听证参加人应当按时参加听证会，服从听证主持人指挥，遵守听证会纪律。"},{"i":11,"n":"第十一条","txt":"当事人可以委托一至二名代理人参加听证，收集、提供相关材料和证据，进行质证和申辩。"},{"i":12,"n":"第十二条","txt":"当事人在听证中享有以下权利： （一）知悉作出行政处罚或行政许可的事实、证据和法律依据； （二）申请听证人员的回避； （三）陈述主张和理由，提出证据； （四）进行质证和申辩； （五）依法享有的其他权利。 听证会代表在听证中享有以下权利： （一）知悉听证事项的情况； （二）对听证内容发表意见； （三）进行质询。"},{"i":13,"n":"第十三条","txt":"行政处罚或行政许可事项承办部门在作出行政决定前，有下列情形之一的，应当书面告知当事人有申请举行听证的权利： （一）作出责令停产停业、吊销许可证或者执照、3万元以上(不含3万元)罚款等行政处罚决定的； （二）行政许可直接涉及申请人与他人之间重大利益关系的； （三）法律、行政法规或者规章规定的其他情形。"},{"i":14,"n":"第十四条","txt":"行政许可事项当事人应当自收到书面告知之日起5日内，行政处罚事项当事人应当自收到书面告知之日起3日内，向国防科工委法制工作机构提出书面听证申请。 逾期未提出的，视为放弃听证。"},{"i":15,"n":"第十五条","txt":"听证申请应当包括以下内容： （一）申请人的名称，住所，联系方式； （二）申请听证的具体事项； （三）申请听证的依据、理由及其他证明材料。"},{"i":16,"n":"第十六条","txt":"法制工作机构收到听证书面申请后，应当对申请材料进行审查，并根据下列情况作出处理： （一）申请人不具备法定条件或者超过法定期限提出申请的，应当告知申请人不予受理，并书面说明理由； （二）申请材料不齐全的，应当一次告知申请人补正全部材料； （三）申请人符合法定条件，申请材料齐全、申请事项符合听证条件的，受理听证申请。"},{"i":17,"n":"第十七条","txt":"法制工作机构受理听证申请，应当制作听证通知书，并于举行听证7日前送达申请人和行政处罚或者行政许可事项承办部门。 听证通知书应当载明下列事项： （一）听证的事由、依据； （二）听证的时间、地点； （三）听证人员的姓名、职务； （四）当事人的权利和义务； （五）其他注意事项。 听证事项涉及其他公民、法人或者其他组织重大利益关系的，应当通知其参加听证。"},{"i":18,"n":"第十八条","txt":"当事人收到听证通知书后，无正当理由不参加听证的，或者未经听证主持人允许中途退出的，视为放弃听证。放弃听证的，记入听证笔录。"},{"i":19,"n":"第十九条","txt":"听证会开始前，记录员应当查明听证参加人的身份和到场情况，宣布听证纪律和听证会场有关注意事项。"},{"i":20,"n":"第二十条","txt":"听证会按下列程序进行： （一）听证主持人宣布听证开始，宣布听证事由和听证人员名单； （二）告知听证参加人的权利和义务，询问当事人是否申请回避； （三）行政处罚或者行政许可事项承办部门陈述意见； （四）当事人进行质证、申辩； （五）听证主持人、听证员对听证参加人进行询问； （六）听证各方最后陈述； （七）听证主持人宣布听证会结束。"},{"i":21,"n":"第二十一条","txt":"记录员应当制作听证笔录。听证笔录应当载明下列事项： （一）听证时间、地点、事由； （二）听证人员的姓名、职务； （三）听证参加人的基本情况； （四）行政处罚或者行政许可事项承办部门的意见； （五）当事人辩论、申辩情况； （六）其他需要记载的事项。 听证笔录经听证参加人确认无误或者补正后当场签字或者盖章；拒绝签字或者盖章的，记录员应当记明情况附卷。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，可以延期举行听证： （一）因不可抗力的事由致使听证无法按期举行的； （二）当事人有正当理由申请延期的； （三）其他可以延期的情形。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，应当中止听证： （一）听证主持人认为听证过程中提出新的事实、理由和依据有待调查核实的； （二）申请听证的公民死亡、法人或者其他组织终止，尚未确定权利、义务承受人的； （三）其他应当中止听证的情形。"},{"i":24,"n":"第二十四条","txt":"延期听证和中止听证的，法制工作机构应当书面通知听证参加人。延期和中止听证的情形消失后，法制工作机构应当恢复听证，并书面通知听证参加人。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，应当终止听证： （一）申请听证的公民死亡，没有继承人，或者继承人放弃听证权利的； （二）申请听证的法人或者其他组织终止，承受其权利的法人或者组织放弃听证权利的； （三）申请人在听证过程中声明退出的； （四）其他应当终止听证的情形。"},{"i":26,"n":"第二十六条","txt":"听证会结束后，法制工作机构应当根据听证笔录，提出听证建议。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，承办部门应当报委领导批准后组织听证： （一）起草、修订的法律、行政法规和规章直接涉及公民、法人或者其他组织的切身利益，有关机关、组织或者公民对其有重大分歧意见的； （二）法律、行政法规和规章规定实施行政许可应当听证的事项，或者行政机关认为需要听证的其他涉及公共利益的重大行政许可事项； （三）作出涉及重大公共利益的行政决策前，认为需要听证的； （四）国防科工委认为需要听证的其他事项。"},{"i":28,"n":"第二十八条","txt":"承办部门应当在举行听证会30日前，向社会公告听证会的时间、地点、内容和申请参加的条件。"},{"i":29,"n":"第二十九条","txt":"符合规定条件的公民、法人和其他组织，可以申请参加听证会，也可以推选代表参加听证会。 承办部门根据听证事项情况及公民、法人和其他组织的申请情况，指定听证会代表；指定的听证会代表应当具有广泛性、代表性。"},{"i":30,"n":"第三十条","txt":"承办部门应当在举行听证会10日前将听证会材料送达听证会代表。"},{"i":31,"n":"第三十一条","txt":"听证会代表应当亲自参加听证，并有权对听证事项的必要性、可行性以及具体内容发表意见和质询，查阅听证纪要。 听证会代表应当忠于事实，实事求是地反映所代表的公民、法人和其他组织的意见，遵守听证纪律，保守国家秘密。"},{"i":32,"n":"第三十二条","txt":"听证会按照以下程序进行： （一）听证主持人宣布听证会开始； （二）承办部门对听证事项进行说明； （三）听证会代表提问和发表意见； （四）听证主持人询问； （五）听证主持人宣布听证会结束。"},{"i":33,"n":"第三十三条","txt":"承办部门应当制作听证会记录，如实记录各方的主要观点和理由。"},{"i":34,"n":"第三十四条","txt":"听证会结束后，承办部门应当根据听证会记录制作听证纪要，听证纪要应包括听证会的基本情况、听证会代表的意见及采纳情况。 依据听证作出行政许可决定、行政决策应当附具相关听证纪要。"},{"i":35,"n":"第三十五条","txt":"当事人扰乱听证秩序或者有其他妨碍听证正常进行行为的，由主持人给予警告；情节严重的，责令其退离听证会场。"},{"i":36,"n":"第三十六条","txt":"行政处罚和行政许可事项承办部门及其工作人员违反本规则规定，应当履行听证告知义务而不履行的，由有关部门责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员给予行政处分。"},{"i":37,"n":"第三十七条","txt":"当事人依法要求举行听证或者法律、行政法规和规章规定应当举行听证的，而法制工作机构或者承办部门违反本规则未依法组织听证的，由有关部门责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员给予行政处分。"},{"i":38,"n":"第三十八条","txt":"听证工作人员违反本规则规定，在听证活动中履行职责不当、妨碍听证参加人行使陈述、申辩、质证等权利的，由有关部门批评教育；情节严重的，依法给予行政处分。"},{"i":39,"n":"第三十九条","txt":"本规则所称3日、5日、7日为工作日。"},{"i":40,"n":"第四十条","txt":"本规则自2007年3月1日起施行。"}],"guofangkexuejishugongyeweiyuanhuixingzhengchufashi6fc158":[{"i":1,"n":"第一条","txt":"为了规范行政处罚行为，保障行政处罚的合法性，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》等有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国防科学技术工业委员会（以下简称国防科工委）依据法律、行政法规或者规章，对公民、法人和其他组织违反国防科技工业行政管理秩序的行为实施行政处罚，适用本办法。"},{"i":3,"n":"第三条","txt":"实施行政处罚应当遵循合法、公正、公开原则。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织对国防科工委作出的行政处罚，享有陈述权、申辩权；对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。 公民、法人或者其他组织因国防科工委违法作出行政处罚受到损害的，有权依法提出赔偿要求。"},{"i":5,"n":"第五条","txt":"国防科工委在法定职权范围内实施行政处罚。 国防科工委依照法律、行政法规或者规章的规定，可以在其法定权限内委托符合《中华人民共和国行政处罚法》第十八条、第十九条规定条件的组织实施行政处罚。 国防科工委相关业务部门、直属单位和受委托的组织不得以自己的名义实施行政处罚。"},{"i":6,"n":"第六条","txt":"国防科工委相关业务部门对涉嫌违反国防科技工业行政管理秩序的行为，经初步审查认为应当依法作出行政处罚的，报委领导批准立案并确定承办部门。"},{"i":7,"n":"第七条","txt":"承办部门应当指派案件承办人员组成案件调查组调查违法行为，收集有关证据。 案件承办人员与当事人有直接利害关系的，应当回避。"},{"i":8,"n":"第八条","txt":"案件承办人员进行调查时，不得少于两人，并应当向当事人或者有关人员出示有效证件。当事人或者有关人员应当协助调查，不得阻挠或者拒绝。 对在调查中知悉的国家秘密、商业秘密和个人隐私，案件承办人员负有保密义务。"},{"i":9,"n":"第九条","txt":"案件承办人员对当事人及其他有关人员进行询问或者调查应当制作笔录。 笔录应当记载时间、地点、询问情况，由被询问人和案件承办人员签字或者盖章；被询问人要求补正的，应当允许。 被询问人拒绝签字或者盖章的，案件承办人员应当在笔录中予以说明。"},{"i":10,"n":"第十条","txt":"案件承办人员在调查中可以要求当事人及其他有关人员提供相关证明材料，材料提供人应当在有关材料上签名或者盖章。材料提供人拒绝签名或者盖章的，案件承办人应当在材料上予以注明。"},{"i":11,"n":"第十一条","txt":"调查终结，承办部门应当作出案件调查报告。 调查报告应当包括下列内容： （一）当事人的基本情况； （二）经调查核实的事实、证据； （三）拟作出行政处罚、不予行政处罚的建议及其法律依据。"},{"i":12,"n":"第十二条","txt":"拟作出行政处罚的，承办部门应当将调查报告及相关材料移送法制工作机构进行审查。 不予行政处罚的，由承办部门报委领导批准撤销案件。"},{"i":13,"n":"第十三条","txt":"法制工作机构应当对承办部门移交的调查报告及相关材料进行审查。审查内容包括： （一）是否在法定职权管辖范围； （二）违法事实是否清楚，证据是否确凿充分，调查取证程序是否合法； （三）确定违法行为性质是否准确； （四）适用法律、行政法规或者规章是否正确； （五）处罚种类、幅度是否适当； （六）其他依法应当审查的内容。"},{"i":14,"n":"第十四条","txt":"法制工作机构在审查过程中可以要求承办部门对案件有关情况作出解释、说明。必要时，法制工作机构可以直接向有关单位及人员调查、了解情况。"},{"i":15,"n":"第十五条","txt":"法制工作机构根据下列情况作出审查意见： （一）违法事实清楚，证据充分，定性准确，适用法律、行政法规或者规章正确，程序合法，处罚种类、幅度适当的，签署同意意见； （二）违法事实清楚，证据充分，程序合法，但确定违法行为性质不准确或者适用法律、行政法规、规章错误的，提出纠正意见，退回承办部门； （三）违法事实不清，证据不足，程序不合法的，提出纠正意见，退回承办部门，重新进行调查取证。"},{"i":16,"n":"第十六条","txt":"对法制工作机构审查通过的案件，承办部门应当书面告知当事人拟作出行政处罚决定的事实、理由和法律依据，以及当事人依法享有的权利。 当事人要求陈述和申辩的，承办部门应当充分听取当事人意见，对有关情况进行复核，不得因当事人的申辩而加重处罚。"},{"i":17,"n":"第十七条","txt":"对拟作出3万元以上(不含3万元)罚款、责令停产停业、吊销许可证或者执照等行政处罚的，承办部门应当告知当事人享有听证的权利。当事人要求听证的，应当在收到告知后3个工作日内提出申请。 行政处罚的听证由法制工作机构组织。"},{"i":18,"n":"第十八条","txt":"拟作出3万元以上罚款、责令停产停业、吊销许可证或者执照等行政处罚的，承办部门应当将起草的行政处罚决定书、调查报告及其他相关材料报委主任办公会议审查决定。 拟作出警告、3万元以下罚款等其他行政处罚的，承办部门应当将起草的行政处罚决定书、调查报告及其他相关材料报委领导审查决定。"},{"i":19,"n":"第十九条","txt":"国防科工委决定依法作出行政处罚的，法制工作机构应当制作正式的行政处罚决定书，由承办部门负责送达当事人。"},{"i":20,"n":"第二十条","txt":"行政处罚决定作出后，国防科工委相关业务部门应当依照《中华人民共和国行政处罚法》的相关规定执行。 行政处罚决定执行完毕后，法制工作机构和承办部门应当及时将案件材料立卷归档。"},{"i":21,"n":"第二十一条","txt":"案件承办人员因履行职责不当，给公民人身或财产造成损害、给法人或者其它组织造成损失的，由有关部门批评教育；情节严重的，给予行政处分。"},{"i":22,"n":"第二十二条","txt":"国防科工委工作人员玩忽职守，对应当予以制止和处罚的违法行为不予制止、处罚，致使公民、法人或者其他组织的合法权益、公共利益和社会秩序遭受损害的，对直接负责的主管人员和其他责任人员依法给予行政处分。"},{"i":23,"n":"第二十三条","txt":"国防科工委工作人员在行政处罚过程中利用职务上的便利，索取或者收受他人财物、收缴罚款据为己有的，由有关部门批评教育；情节严重的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"本办法自2007年3月1日起施行。"}],"guofangkegongweixingzhengshenpiguanlizanxingbanfa-2":[{"i":1,"n":"第一条","txt":"为了规范行政审批行为，提高行政效能，促进依法行政，保护公民、法人和其他组织的合法权益，根据国家有关法律法规以及国务院行政审批制度改革工作有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国防科学技术工业委员会(以下简称国防科工委)根据公民、法人或者其他组织依法提出的申请，经依法审查，准予其从事特定活动、认可其资格资质等行政审批的设定和实施，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"行政审批的设定和实施应当遵循合法合理、公正公开、精简高效、责权一致的原则。"},{"i":4,"n":"第四条","txt":"行政审批的设定和实施必须加强事先调查研究、过程监督检查和事后评估评价，坚持做到充分论证、严格把关、依法审批、科学决策。"},{"i":5,"n":"第五条","txt":"行政审批项目的设定，应当以法律、行政法规、国务院有普遍约束力的决定为依据，并通过国防科工委规章或规范性文件对行政审批对象、条件、程序、期限以及监督方式等加以具体明确。"},{"i":6,"n":"第六条","txt":"拟设定的行政审批项目，由具有相关职能的司局研究提出，具体内容应当包括行政审批项目名称、设定依据、审批程序等。对无法律、行政法规、国务院有普遍约束力的决定作为依据，但确需设定的行政审批项目，具有相关职能的司局应当在提出设定行政审批项目的同时，提出立法建议和行政法规(或者国务院文件)草案。"},{"i":7,"n":"第七条","txt":"拟设定的行政审批项目提出后，国防科工委法制工作机构应当对其合法性进行审核，并会同办公厅以及监察、人事等机构对该行政审批项目是否符合合理、效能、责任、监督原则进行审核、评估。经审核通过后，报国防科工委主任办公会议审议决定。"},{"i":8,"n":"第八条","txt":"拟取消的行政审批项目，由具有相关职能的司局研究提出，同时应说明理由并制定相应的后续监管措施，经国防科工委法制工作机构审核后，报国防科工委主任办公会议审议决定。"},{"i":9,"n":"第九条","txt":"除涉及国家秘密外，行政审批的项目名称、依据及其条件、程序、期限、费用以及需要提交的全部材料、申请书示范文本应当予以公示。"},{"i":10,"n":"第十条","txt":"行政审批申请应当以书面形式提出。申请人可以通过送交、邮寄、数据电文等方式提出行政审批申请。但涉及国家秘密的，按国家有关规定办理。"},{"i":11,"n":"第十一条","txt":"申请事项属于国防科工委职责和行政审批范围，申请材料齐全、符合法定形式和法定程序的，国防科工委行政审批承办司局(以下简称承办司局)应当予以受理，并告知申请人。 申请事项不属于国防科工委职责和行政审批范围，或者不符合法定程序的，承办司局应当作出不予受理的决定，并告知申请人。 申请材料不齐全或者不符合法定形式的，承办司局应当告知申请人在合理期限内予以补正。申请人未补正或未按期补正的，视为撤消申请。"},{"i":12,"n":"第十二条","txt":"依照有关规定需要经过初审的行政审批项目，初审机构(单位)应在该项行政审批项目规定的期限内进行审查，并将初审意见和申请材料报送国防科工委。承办司局不得要求申请人重复提供申请材料。"},{"i":13,"n":"第十三条","txt":"行政审批申请受理后，承办司局应当依据法定条件和程序进行实质审查。对行政审批申请进行实质审查时，应当充分听取各方面的意见。"},{"i":14,"n":"第十四条","txt":"涉及两个以上司局的行政审批，应当确定一个司局牵头，并由其负责征求其他有关司局意见后统一办理。 涉及国务院其他部门职能的，承办司局应当按照有关规定和法定程序征求相关部门的意见。"},{"i":15,"n":"第十五条","txt":"行政审批项目有明确办理时限规定的，承办司局应严格从其规定。行政审批项目未规定办理时限的，承办司局应当自受理申请之日起30日内进行实质审查，并依程序做出决定；30日内不能作出决定的，经主管委领导批准可以延长，但承办司局应当将延长审查时限及理由告知申请人。"},{"i":16,"n":"第十六条","txt":"依法不予批准的行政审批申请，承办司局应在本办法第十五条规定的时限内通知申请人，并说明理由。"},{"i":17,"n":"第十七条","txt":"承办司局对其所负责的行政审批项目应当建立完备的案卷登记档案，并妥善保管。凡不涉及国家秘密、企业商业秘密的案卷登记材料，申请人及其他相关人员可以查阅。"},{"i":18,"n":"第十八条","txt":"除涉及国家秘密外，承办司局在作出行政审批决定后，应当公布行政审批结果。"},{"i":19,"n":"第十九条","txt":"建立行政审批执法检查制度，对申请人从事行政审批项目活动进行监督检查，对已取消行政审批项目的后续监管措施进行监督检查。"},{"i":20,"n":"第二十条","txt":"公民、法人或者其他组织认为国防科工委的行政审批行为侵犯其合法权益的，可以依法申请行政复议或者提起行政诉讼。"},{"i":21,"n":"第二十一条","txt":"不需要继续保留的行政审批项目，应当按照本办法第八条规定的程序予以取消；对程序不规范、条件不明确、效率不高的行政审批项目，应当及时改进完善。"},{"i":22,"n":"第二十二条","txt":"行政审批项目依法委托给其他有关组织实施的，承办司局应当对其审批行为进行监督，并对其审批行为的后果承担责任。"},{"i":23,"n":"第二十三条","txt":"建立行政审批责任追究制度。国防科工委监察机构负责对行政审批工作人员履行职责情况进行监督，对违反本办法规定的，按照《国防科工委行政审批责任追究暂行办法》追究其责任。"},{"i":24,"n":"第二十四条","txt":"本办法关于行政审批期限的规定，是指工作日，不含法定节假日。"},{"i":25,"n":"第二十五条","txt":"本办法由国防科工委负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2003年9月1日起施行。"}],"guofangkejigongyejunyonghesheshianquanjianduguanlidd5910":[{"i":1,"n":"第一条","txt":"为实施国防科技工业军用核设施（以下简称军用核设施）的安全监督管理，保证军用核设施的安全，保障设施工作人员和公众的健康，保护环境，促进国防核科学技术工业的顺利发展，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于下列军用核设施的安全监督管理： （一）核材料的生产、加工、贮存及乏燃料后处理设施； （二）核动力装置； （三）各种陆基反应堆，包括生产堆、研究堆、试验堆、临界装置等； （四）放射性废物管理设施； （五）其他需要监督管理的军用核设施。 交付军队使用的核设施除外。"},{"i":3,"n":"第三条","txt":"军用核设施的选址、设计、建造、运行和退役必须贯彻“安全第一”的方针，并应当实现下列安全目标： （一）建立和保持有效的防御措施，保护工作人员、公众及环境免遭辐射危害； （二）确保在设施运行状态下工作人员和公众所受到的辐射照射低于国家规定限值，并保持在可合理达到的尽量低水平，保证减轻事故引起的辐射照射； （三）采取一切合理可行的措施预防事故的发生，缓解事故的后果。确保设施设计中考虑的所有事故的辐射后果是可以接受的，并保证那些可能导致严重辐射后果的事故发生的可能性足够低。"},{"i":4,"n":"第四条","txt":"国防科学技术工业委员会（以下简称国防科工委）对军用核设施实行统一的安全监督管理。其主要职责是： （一）组织起草、制定有关的安全法律、规章及安全标准； （二）负责组织安全审评，批准颁发或吊销有关安全许可证件； （三）负责实施安全监督检查； （四）监督、协调核事故应急计划的制定和实施； （五）负责安全执法和事故、事件的调查与处理； （六）会同有关部门调解安全纠纷； （七）组织有关的安全研究及运行经验反馈。"},{"i":5,"n":"第五条","txt":"国防科工委根据军用核设施安全监督管理的需要设立相应的独立行使安全监督管理职权的机构，配备必要的合适人员，并组成军用核设施安全专家委员会。 安全专家委员会为军用核设施安全政策与法规、规章的制定、许可证的颁发、安全研究规划的确定等重大事项的决策提供咨询。"},{"i":6,"n":"第六条","txt":"营运单位负责对所申请的军用核设施的安全承担全面的责任。其主要职责是： （一）遵守国家有关法律、法规及规章，并制定相应的措施； （二）确保设施的选址、设计、建造、调试、运行和退役符合国家有关法律、法规、规章及标准的要求，足以保证安全； （三）提供保证设施安全所需要的资源，配备足够的合格工作人员，并对它们进行充分的培训和定期再培训； （四）接受国防科工委的安全监督管理； （五）及时、如实地报告设施的安全状况，并提供有关资料。"},{"i":7,"n":"第七条","txt":"对军用核设施所实施的安全监督管理不减轻也不转移营运单位对所申请的设施应承担的全面安全责任。 营运单位应负的安全责任也不因设计者、供货商、建造者等各自的活动和责任而发生任何改变。"},{"i":8,"n":"第八条","txt":"对军用核设施实行安全许可制度。安全许可证件包括： （一）军用核设施厂址选择审查意见书； （二）军用核设施建造许可证； （三）军用核设施装（投）料调试批准书； （四）军用核设施运行许可证； （五）军用核设施退役批准书； （六）军用核设施安全关键岗位操纵（作）员执照； （七）其他需要的批准文件。 有关军用核设施的各种活动必须遵循相应安全许可证件所规定的条件。"},{"i":9,"n":"第九条","txt":"军用核设施的厂址，需经国防科工委根据《可行性研究报告》中的厂址选择部分组织安全审评并出具《厂址选择审查意见书》，从安全方面确认所选厂址的适宜性后，方可予以批准。"},{"i":10,"n":"第十条","txt":"军用核设施开始建造（包括改建、扩建）前，其营运单位必须向国防科工委提交军用核设施建造申请书、初步安全分析报告及其他有关资料，经审核批准，获得《军用核设施建造许可证》后，方可动工建造。"},{"i":11,"n":"第十一条","txt":"军用核设施开始启动、运行前，其营运单位必须向国防科工委提交军用核设施启动、运行申请书、最终安全分析报告以及其他有关资料，经审核批准，获得《军用核设施装（投）料调试批准书》后，方可开始装载或投放燃料进行启动调试，在获得《军用核设施运行许可证》后，方可正式运行。"},{"i":12,"n":"第十二条","txt":"军用核设施开始退役前，其营运单位必须向国防科工委提交军用核设施退役申请书、退役安全分析报告以及其他有关资料，经审核批准，获《军用核设施退役批准书》后，方可开始退役活动。 军用核设施退役的最终状态必须经国防科工委会同有关部门验收，确认符合有关安全要求后，营运单位的责任方可终止。"},{"i":13,"n":"第十三条","txt":"本规定发布前已在建、在役或退役中的军用核设施，其营运单位应当在规定的期限内向国防科工委补交相应的申请书，提交有关安全分析报告及资料，以获得必需的安全许可证件。"},{"i":14,"n":"第十四条","txt":"获得并持有军用核设施安全关键岗位操纵（作）员执照的人员方可在相应安全关键岗位进行操作；具有大专以上文化水平、担任安全关键岗位操纵（作）员两年以上、成绩优秀者，方可指导他人在相应安全关键岗位进行操作。"},{"i":15,"n":"第十五条","txt":"军用核设施安全许可证件的颁发以安全审评为基础。国防科工委确认营运单位的申请符合国家有关法律、法规及规章的规定，并满足有关安全要求时，方可颁发相应的安全许可证件。"},{"i":16,"n":"第十六条","txt":"安全许可证件期满后终止；安全许可证件的变更、延期或更换，必须向国防科工委提出申请，经审查批准后方为有效。 未经国防科工委批准，任何法人或个人均不得转让按照本规定所获得的任何安全许可证件。"},{"i":17,"n":"第十七条","txt":"军用核设施安全监督检查的依据是： （一）国家的有关法律、法规及规章； （二）有关的国家标准、国家军用标准及核行业标准； （三）安全许可证件所规定的条件； （四）其他具有约束力的文件。"},{"i":18,"n":"第十八条","txt":"军用核设施安全监督检查的任务包括： （一）审核申请者所提交的安全文件与资料是否符合实际； （二）监督检查设施的选址、设计、建造、调试、运行和退役是否符合有关法律、法规、规章及标准和相应安全许可证件所规定的条件，是否满足预定的技术要求； （三）监督检查安全有关活动是否按审评认可的设计、程序和质量保证大纲进行； （四）考察营运单位是否具备确保设施安全运行及执行应急计划的能力与措施； （五）评估营运单位的安全文化素养； （六）其他必需的监督检查任务。"},{"i":19,"n":"第十九条","txt":"对军用核设施安全监督检查可以采取查阅有关文件与记录、现场见证、座谈访问、验证性检验和测量等方式。"},{"i":20,"n":"第二十条","txt":"国防科工委根据需要组织合适的人员（必要时邀请专家）执行指定的监督检查任务。 监督检查人员执行任务时，凭其有效证件有权进入设施内及与监督检查任务有关的建造、运行或退役现场，调查、收集有关安全的资料。"},{"i":21,"n":"第二十一条","txt":"从事军用核设施安全监督检查的人员必须客观、公正地履行监督检查职能，遵守监督检查纪律，保守国家秘密，不得介入与被监督检查设施有关的商业性质的活动和其他不利于监督检查任务有效完成的活动。"},{"i":22,"n":"第二十二条","txt":"营运单位应按规定向国防科工委提交其安全有关活动的进度及有关文件与资料，并为监督检查提供必要的条件，保证监督检查任务有计划地实施。"},{"i":23,"n":"第二十三条","txt":"国防科工委确认必要时，有权采取强制性行动，命令营运单位采取安全措施或停止危及安全的活动。"},{"i":24,"n":"第二十四条","txt":"营运单位有权拒绝有害于安全的监督检查要求，但必须执行国防科工委的强制性命令。"},{"i":25,"n":"第二十五条","txt":"对保证军用核设施安全作出显著成绩的单位和个人，国防科工委应给予表彰。"},{"i":26,"n":"第二十六条","txt":"凡违反本规定，有下列行为之一的，国防科工委可视情节轻重，给予警告、罚款、停工或停运整顿或吊销安全许可证件的处罚： （一）未经许可或违章从事军用核设施建造、运行、退役或擅自变更、转让安全许可证件的； （二）隐瞒、谎报有关资料或事实的； （三）无故拒绝或阻挠安全监督检查的； （四）无执照或违章在安全关键岗位操作的； （五）拒不执行强制性命令的。 不服从管理、违章或强迫他人违章作业，造成严重后果构成犯罪的，由司法机关依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"军用核设施的安全监督检查人员，玩忽职守、徇私舞弊、滥用职权的，视情节轻重给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"当事人对行政处罚不服的，可在接到处罚通知之日起六十日内向国防科工委申请行政复议，但对于吊销安全许可证件的处罚必须立即执行。"},{"i":29,"n":"第二十九条","txt":"军用核设施安全监督管理中涉及的保密事项按国家保密法规及有关规定处理。"},{"i":30,"n":"第三十条","txt":"申请军用核设施安全许可证件的营运单位应缴纳所需的安全审评费用，具体收费办法另行制定。"},{"i":31,"n":"第三十一条","txt":"本规定由国防科工委负责解释，并制定实施细则。"},{"i":32,"n":"第三十二条","txt":"本规定自发布之日起施行。"}],"guofangkejigongyejiliangjianduguanlizanxingguiding-2":[{"i":1,"n":"第一条","txt":"为加强国防科技工业计量工作的监督管理，保证国防科技工业产品的量值准确一致，测量数据可靠，根据《中华人民共和国计量法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称国防科技工业计量，是指国防科技工业科研（含设计、试验等，下同）、生产、服务中实现产品量值准确一致、测量数据可靠的全部活动。"},{"i":3,"n":"第三条","txt":"国防科学技术工业委员会（以下简称国防科工委）统一监督管理国防科技工业计量工作。国防科技工业计量在业务上接受国务院计量行政部门的指导。"},{"i":4,"n":"第四条","txt":"国防科技工业面向社会的科研、生产、服务中的计量活动接受政府计量行政部门的监督；国防科技工业面向社会出具公正数据的产品质量检验机构，应当按国家有关规定进行计量认证。"},{"i":5,"n":"第五条","txt":"国防科技工业计量实行国家法定计量单位。对军品科研、生产中特殊需要保留的非法定计量单位，由使用单位提出，经国防科工委批准，报国务院计量行政部门备案。"},{"i":6,"n":"第六条","txt":"国防科技工业计量坚持面向科研、面向生产、面向使用；坚持军用与民用相结合、计量与测试相结合、服务与监督相结合、内部与外部相结合，为国防现代化建设和国民经济建设服务。"},{"i":7,"n":"第七条","txt":"国防科工委计量管理机构是国防科技工业计量监督管理的职能部门，其职责是： （一）贯彻执行国家计量法律、法规，拟定国防科技工业计量工作方针、政策及规章； （二）编制并组织实施国防科技工业计量工作规划、计划； （三）组织建立与调整国防科技工业计量技术机构； （四）组织研究、建立与保持国防科技工业需要的最高计量标准器具、校准装置和测试系统；组织国防最高计量标准以外的计量标准器具、校准装置、测试系统考核和计量人员考核； （五）组织实施从事国防科技工业计量检定、校准、测试的校准实验室和测试实验室认可； （六）组织国防科技工业计量工作的监督检查； （七）组织国防科技工业计量检定规程和校准规范的制定和贯彻实施； （八）组织国防科技工业系统的国际计量技术合作与交流； （九）指导有关部门（单位）开展国防科技工业计量工作。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市人民政府国防科技工业行政主管部门，依据其职能和国防科工委计量管理机构的授权，对本地区的国防科技工业计量工作实施监督管理，其职责是： （一）贯彻执行国家计量法律、法规和国防科技工业计量工作的方针、政策及规章； （二）监督检查和协调本地区的国防科技工业计量工作； （三）负责本地区军工企业事业单位最高计量标准器具和计量人员的考核工作； （四）承办国防科工委计量管理机构交办其他计量工作。"},{"i":9,"n":"第九条","txt":"军工集团公司计量管理机构，依据本规定对本集团的计量工作实施监督管理，组织本集团计量业务技术活动，承办国防科工委计量管理机构交办的其他计量工作。"},{"i":10,"n":"第十条","txt":"军工企业事业单位（含委属各高校），依法对本单位的计量工作实施自主管理，保证产品的测量质量，接受国防科技工业计量管理机构的监督检查。"},{"i":11,"n":"第十一条","txt":"其他承担国防科技工业产品科研、生产任务的部门（单位），应当按本规定的要求，对本部门（单位）的计量工作实施监督管理。"},{"i":12,"n":"第十二条","txt":"国防科工委批准设置的计量测试研究中心、专业计量站，接受国防科工委计量管理机构的监督检查。其职责是： （一）研究、建立国防科技工业需要的最高计量标准器具、校准装置和测试系统，并保持其服务能力； （二）承担国防科技工业的量值传递和量值溯源工作，根据委托承担因计量器具准确度引起纠纷的仲裁检定； （三）根据委托承担国防科技工业计量人员、计量标准器具、校准装置和测试系统的技术考核； （四）跟踪国内外计量测试新技术，研究新的测量理论与方法； （五）研究产品科研、生产、使用中的关键计量测试技术，专用测试设备及其校准手段和方法； （六）承担型号试验中使用的计量器具和专用测试设备的计量检查与保障工作； （七）承办国防科工委计量管理机构交办的其他任务。"},{"i":13,"n":"第十三条","txt":"国防科工委批准设置的区域校准实验室，在业务上接受计量测试研究中心、专业计量站的指导。其职责是： （一）研究、建立计量标准器具、校准装置和测试系统，并保持其服务能力； （二）承担军工企业事业单位的最高计量标准器具和其委托的工作计量器具的强制检定与校准工作，承担产品质量保证中的测试任务； （三）根据委托承担企业事业单位的计量人员、计量标准器具、校准装置和测试系统的技术考核。"},{"i":14,"n":"第十四条","txt":"军工企业事业单位，根据所承担科研、生产和服务任务设置的计量技术机构，在业务上接受国防科技工业计量测试研究中心、专业计量站和区域校准实验室的指导。其职责是： （一）贯彻执行国防科技工业计量工作的方针、政策及规章，提高设计、工艺及管理人员的计量意识； （二）负责本单位强制检定和其他检定、校准、测试工作； （三）确保在用计量器具及专用测试设备的量值准确和测量数据可靠。"},{"i":15,"n":"第十五条","txt":"国防科工委根据国防科技工业布局和任务的需要，对批准设置的计量技术机构，实行动态管理。"},{"i":16,"n":"第十六条","txt":"国防最高计量标准器具，须经国防科工委计量管理机构审查，由国务院计量行政部门组织考核合格后使用。"},{"i":17,"n":"第十七条","txt":"国防科技工业的区域校准实验室建立的最高计量标准器具，以及国防科技工业的计量测试研究中心、专业计量站和区域校准实验室建立的校准装置、测试系统，由国防科工委计量管理机构组织考核合格后使用，并向国务院计量行政部门备案。"},{"i":18,"n":"第十八条","txt":"军工企业事业单位建立的最高计量标准器具，由国防科工委计量管理机构授权省、自治区、直辖市人民政府国防科技工业行政主管部门组织考核合格后使用，并向所在省、自治区、直辖市计量行政部门备案。"},{"i":19,"n":"第十九条","txt":"国防科技工业用于量值传递的有证标准物质，作为计量标准器具按有关规定进行管理。"},{"i":20,"n":"第二十条","txt":"国防科技工业建立的计量标准器具、校准装置、测试系统，以及用于产品性能评定、定型鉴定和保证安全的工作计量器具，必须按规定实行计量检定。其他用于产品科研、生产、服务的工作计量器具和专用测试设备，应按规定实行校准。经检定或经校准不满足预期使用要求的，不得使用。"},{"i":21,"n":"第二十一条","txt":"计量检定按照国家计量检定系统表和计量检定规程进行。国家未制定计量检定系统表和计量检定规程的，按照国防科工委制定的国防科技工业计量器具等级图和计量检定规程进行。 国家计量检定规程不能满足国防科技工业的特殊使用要求的，计量检定按照国防科工委制定的计量检定规程进行。 国防科工委制定的国防科技工业计量器具等级图和计量检定规程报国务院计量行政部门备案。"},{"i":22,"n":"第二十二条","txt":"计量器具的校准按照校准技术规范进行。校准技术规范可由国防科工委、有关部门、军工集团公司或军工企业事业单位根据需要制定，经组织技术评审后发布实施。"},{"i":23,"n":"第二十三条","txt":"国防科技工业计量技术机构的计量检定、校准人员，必须经国防科工委计量管理机构或其授权的机构考核合格后，持证上岗。"},{"i":24,"n":"第二十四条","txt":"武器装备重点型号设置的型号计量师系统（或型号计量工作系统），负责重点型号的计量保证工作。其职责是： （一）提出型号研制过程中总体或分系统对计量测试工作的要求； （二）根据型号总体或分系统的技术指标，提出计量测试的技术指标要求； （三）提出型号总体或分系统研制过程中需要研制的计量标准器具、校准装置和专用测试设备的研究课题，并组织落实承担单位及有关保障条件； （四）组织协调型号总体或分系统研制过程中的计量保障工作。"},{"i":25,"n":"第二十五条","txt":"型号研制单位的计量机构，根据型号计量师提出的计量测试技术指标，制定可行性论证方案，并组织实施。 型号试验单位的计量机构，根据型号计量师提出的计量测试工作要求，负责组织实施。"},{"i":26,"n":"第二十六条","txt":"型号设计定型前，研制单位的计量机构应对定型组织批准的专用测试设备的计量控制状况和计量技术文件（包括计量检定规程、校准技术规范）的有效性进行审查。"},{"i":27,"n":"第二十七条","txt":"型号试验时，计量工作应列入型号的试验大纲或试验计划；计量器具和专用测试设备进入试验基地（靶场），必须进行计量检查。"},{"i":28,"n":"第二十八条","txt":"生产单位必须按照产品的技术指标和工艺规范的要求，配备满足生产要求的计量器具和检测手段。"},{"i":29,"n":"第二十九条","txt":"生产单位向使用单位交付型号产品时，按合同向使用单位交付的专用测试设备及其技术资料，应符合相应的计量规定。"},{"i":30,"n":"第三十条","txt":"产品的质量评定、成果鉴定，必须经产品的研制和生产单位的计量机构进行计量审查，并对其测量方法的正确性和测量数据的可靠性签署意见。"},{"i":31,"n":"第三十一条","txt":"产品的设计定型和生产定型，凡涉及产品技术指标量值的准确度及可信性，必须经技术能力满足要求的计量机构签署意见。"},{"i":32,"n":"第三十二条","txt":"用于产品设计定型、生产定型、质量评定和成果鉴定的计量器具和专用测试设备，必须经过检定或校准，并在检定或校准证书注明的有效期内使用。"},{"i":33,"n":"第三十三条","txt":"军工企业事业单位引进技术和仪器设备时，应同时引进必要的计量保证手段和技术资料；有关计量机构应当对引进技术和仪器设备的计量保证条件进行审查。"},{"i":34,"n":"第三十四条","txt":"军工企业事业单位承担的重点工程项目，应参照武器装备型号计量师制度，设置工程项目计量师，确保测量数据准确，质量可靠。"},{"i":35,"n":"第三十五条","txt":"军工企业事业单位在型号和重点工程项目可行性论证时，相应的计量机构应对其技术指标的计量保证手段进行审查；当不具备计量保证手段时，负责可行性论证的单位应采取有效措施予以保证。"},{"i":36,"n":"第三十六条","txt":"国防科工委计量管理机构组织建立国防科技工业计量工作监督机制，对国防科技工业科研、生产、服务全过程的计量工作，按领域、分层次实施监督。"},{"i":37,"n":"第三十七条","txt":"国防科工委计量管理机构统一组织建立国防科技工业计量监督员队伍，依法对国防科技工业计量工作实施监督。其主要任务是： （一）监督检查国防科技工业计量法律、法规及规章制度的执行情况； （二）监督检查国防科技工业计量和测试人员资格的有效性； （三）监督检查国防科技工业计量标准器具、校准装置和测试系统的考核情况及测量设备的控制状况； （四）监督检查国防科技工业计量技术机构和测试实验室的能力保持状况和资格的有效性。"},{"i":38,"n":"第三十八条","txt":"承担国防科技工业计量监督任务的人员，必须经国防科工委计量管理机构考核合格，取得资格。"},{"i":39,"n":"第三十九条","txt":"国防科技工业计量工作的监督检查情况，依据监督检查的对象和内容，由国防科工委计量管理机构或授权省、自治区、直辖市人民政府国防科技工业行政主管部门发布通报。"},{"i":40,"n":"第四十条","txt":"违反本规定的，由国防科工委计量管理机构按照有关规定进行处理。"},{"i":41,"n":"第四十一条","txt":"国防科技工业系统开展计量检定、校准，计量人员和计量标准考核，校准实验室和测试实验室认可工作，参照有关规定收取费用。"},{"i":42,"n":"第四十二条","txt":"省、自治区、直辖市人民政府国防科技工业行政主管部门、军工集团公司，其他承担国防科技工业科研、生产任务的部门，可以根据本规定制定具体实施办法，并报国防科工委备案。"},{"i":43,"n":"第四十三条","txt":"本规定由国防科工委负责解释。"},{"i":44,"n":"第四十四条","txt":"本规定自发布之日起施行。"}],"guofangkeyanshengchananquanshigubaogaohediaochachu732428-2":[{"i":1,"n":"第一条","txt":"为了规范国防科研生产安全事故报告和调查处理工作，落实生产安全事故责任追究制度，防止和减少国防科研生产安全事故，根据《中华人民共和国安全生产法》、《中华人民共和国保守国家秘密法》等法律，制定本办法。"},{"i":2,"n":"第二条","txt":"国防科研生产安全事故报告和调查处理，适用本办法。 本办法所称国防科研生产安全事故（以下简称事故），是指取得武器装备科研生产许可的单位在武器装备科研、生产、试验、储存、销毁等活动中发生的造成人身伤亡或者直接经济损失的事故。"},{"i":3,"n":"第三条","txt":"根据事故造成的人员伤亡或者直接经济损失，事故分为四个等级： （一）特别重大事故，是指造成30人以上死亡，或者100人以上重伤（包括急性工业中毒，下同），或者1亿元以上直接经济损失的事故； （二）重大事故，是指造成10人以上30人以下死亡，或者50人以上100人以下重伤，或者5000万元以上1亿元以下直接经济损失的事故； （三）较大事故，是指造成3人以上10人以下死亡，或者10人以上50人以下重伤，或者1000万元以上5000万元以下直接经济损失的事故； （四）一般事故，是指造成3人以下死亡，或者10人以下重伤，或者直接经济损失1000万元以下的事故。"},{"i":4,"n":"第四条","txt":"事故报告应当及时、准确、完整，任何单位和个人对事故不得迟报、漏报、谎报或者瞒报。 事故调查处理应当坚持实事求是、尊重科学的原则，及时、准确地查清事故经过、事故原因和事故损失，查明事故性质，认定事故责任，总结事故教训，提出整改措施，并对事故责任者依法追究责任。"},{"i":5,"n":"第五条","txt":"国家国防科技工业局（以下简称国防科工局）负责全国事故统计、事故报告和调查处理工作；省级国防科技工业管理部门根据本办法的规定，负责本行政区域内的事故报告和调查处理工作，并向国防科工局报告事故调查处理情况。"},{"i":6,"n":"第六条","txt":"事故报告和调查处理、应急工作及其信息发布，应当遵守国家法律、行政法规有关保密的规定。 未经国防科工局批准，任何单位和个人不得对外发布有关涉密信息。"},{"i":7,"n":"第七条","txt":"事故发生后，事故现场有关人员应当立即向本单位负责人报告；单位负责人接到报告后，应当于1小时内向事故发生地省级国防科技工业管理部门报告。中央所属军工企事业单位还应当逐级向所属军工集团公司报告。 发生燃烧爆炸和有毒有害物质泄漏事故及其他需要社会救援的事故的，应当立即报告当地人民政府及有关应急救援组织。"},{"i":8,"n":"第八条","txt":"省级国防科技工业管理部门和军工集团公司接到事故报告后，应当依照下列时限向国防科工局报告： （一）特别重大事故、重大事故立即报告； （二）较大事故2小时内报告； （三）一般事故12小时内报告。 省级国防科技工业管理部门接到事故报告后，应当通报省级公安机关、安全生产监督管理部门。 国防科工局接到较大以上事故报告后，应当根据事故等级，按照本条第一款第一项、第二项规定的时限向工业和信息化部、国家安全生产监督管理总局报告。"},{"i":9,"n":"第九条","txt":"报告事故应当包括下列内容： （一）事故发生单位概况； （二）事故发生的时间、地点以及事故现场情况； （三）事故的简要经过； （四）事故已经或者可能造成的伤亡人数（包括下落不明的人数）和初步估计的直接经济损失； （五）已经采取的措施； （六）其他应当报告的情况。"},{"i":10,"n":"第十条","txt":"事故报告后30日内（火灾事故自发生之日起7日内）伤亡人数出现变化的，应当及时补报。"},{"i":11,"n":"第十一条","txt":"事故发生单位接到事故报告后，应当立即启动事故应急预案，采取有效措施组织抢救，防止事故扩大，减少人员伤亡和财产损失。 事故现场存在发生爆炸、急性中毒等次生事故危险的，现场应急抢险救援工作应当在事故应急指挥部的统一指挥和安全技术专家的指导下进行。"},{"i":12,"n":"第十二条","txt":"接到事故报告后，省级国防科技工业管理部门、军工集团公司应当立即派员赶赴现场，开展相关工作；属于重大以上事故的，国防科工局应当派员赶赴现场，开展有关工作。"},{"i":13,"n":"第十三条","txt":"事故发生后，事故单位和有关人员应当妥善保护事故现场以及相关证据，任何单位和个人不得破坏事故现场、毁灭相关证据。 因抢救人员、防止事故扩大以及疏通交通等原因，需要移动事故现场物件的，应当做出标志，绘制现场简图并做出书面记录或者影像记录，妥善保存现场重要痕迹、物证。"},{"i":14,"n":"第十四条","txt":"国防科工局、省级国防科技工业管理部门和军工集团公司应当建立安全生产值班制度，公布值班电话，受理事故报告和举报。"},{"i":15,"n":"第十五条","txt":"发生特别重大事故，国防科工局应当配合国务院或者国务院授权的部门组织调查；重大事故由国防科工局组织调查；较大事故、一般事故由省级国防科技工业管理部门组织调查。 事故发生单位所属的军工集团公司应当参加相关部门组织的事故调查工作。 造成3人以下重伤或者直接经济损失300万元以下的事故，负责事故调查的部门可以委托事故发生单位的上级单位组织调查。"},{"i":16,"n":"第十六条","txt":"自事故发生之日起30日内（火灾事故自发生之日起7日内），因事故伤亡人数变化导致事故等级发生变化的，根据变化后的事故等级可以由相应部门对事故调查情况进行复核，必要时应当另行组织调查。"},{"i":17,"n":"第十七条","txt":"负责事故调查的部门应当遵循精简、效能、保密的原则组成调查组，开展调查工作。 负责事故调查的部门可以根据事故的具体情况，邀请有关安全生产监督管理部门、监察机关、公安机关、检察机关、工会派人参与事故调查，事故发生单位的上级单位应当派人参加。 事故调查组可以聘请有关专家参与调查。"},{"i":18,"n":"第十八条","txt":"负责事故调查的部门指定事故调查组组长，由其主持事故调查组的工作。调查组成员应当具有事故调查所需要的知识和专长，并与所调查的事故没有直接利害关系。"},{"i":19,"n":"第十九条","txt":"事故调查组履行下列职责： （一）查明事故发生经过、原因、伤亡情况及直接经济损失； （二）认定事故的性质和事故责任； （三）提出对事故责任者的处理建议； （四）总结事故教训，提出防范和整改措施； （五）提交事故调查报告。"},{"i":20,"n":"第二十条","txt":"事故调查组有权向有关单位和个人了解与事故有关的情况，并要求其提供相关文件、资料，有关单位和个人不得拒绝。 事故发生单位的负责人和有关人员在事故调查期间不得擅离职守，并应当随时接受事故调查组的询问，如实提供有关情况。 事故调查中发现涉嫌犯罪的，事故调查组应当及时将有关材料或者其复印件移交司法机关处理。"},{"i":21,"n":"第二十一条","txt":"事故调查中需要进行技术鉴定的，事故调查组可以委托具有国家规定资质的单位进行技术鉴定，也可以直接组织专家进行技术鉴定。 技术鉴定所需时间不计入事故调查期限。"},{"i":22,"n":"第二十二条","txt":"事故调查组成员在事故调查工作中应当诚信公正、恪尽职守，遵守事故调查组的纪律，保守事故调查秘密。 事故调查组成员不得擅自发布有关事故的信息。"},{"i":23,"n":"第二十三条","txt":"事故调查组应当自事故发生之日起60日内提交事故调查报告；特殊情况下，经负责事故调查的部门批准，提交事故调查报告的期限可以适当延长，延长期限不得超过60日。"},{"i":24,"n":"第二十四条","txt":"事故调查报告应当包括下列内容： （一）事故发生单位概况； （二）事故发生经过和事故救援情况； （三）事故造成的人员伤亡和直接经济损失； （四）事故发生的原因和事故性质； （五）事故责任的认定以及对事故责任者的处理建议； （六）事故防范和整改措施。 事故调查报告应当附有关证据材料。事故调查组成员应当在事故调查报告上签名。事故报告涉及国家秘密的，应确定密级并按照保密规定管理。"},{"i":25,"n":"第二十五条","txt":"事故调查结束后，负责事故调查的部门应当收回事故调查资料，归档保存。"},{"i":26,"n":"第二十六条","txt":"重大事故、较大事故、一般事故，负责组织事故调查的部门应当自收到事故调查报告之日起15日内做出批复；特殊情况下，批复时间可以适当延长，延长时间最长不超过30日。批复中应当明确对事故发生单位和有关人员的处理意见。 有关部门和单位应当按照批复，依照法律、行政法规的规定和干部管理权限，对事故发生单位和相关责任人员进行处理。 负有事故责任的人员构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"事故发生单位应当及时落实防范和整改措施，防止事故再次发生。 国防科技工业管理部门和事故发生单位的上级单位应当对事故发生单位落实防范和整改措施的情况进行监督检查。"},{"i":28,"n":"第二十八条","txt":"事故调查处理结果，由负责事故调查的部门在相关范围内通报。事故通报涉及国家秘密的，应当注明密级，并严格控制知悉范围。"},{"i":29,"n":"第二十九条","txt":"省级国防科技工业管理部门负责组织调查的事故，应当自结案之日起15日内将经批复的事故调查报告报送国防科工局备案，并同时通报地方人民政府安全生产监督管理等有关部门。"},{"i":30,"n":"第三十条","txt":"事故发生单位主要负责人、直接负责的主管人员和其他直接责任人员有下列行为之一，构成违反治安管理行为的，由公安机关依法给予处罚；构成犯罪的，依法追究刑事责任；属于国家工作人员的，还应当依法给予处分。 （一）谎报或者瞒报事故的； （二）伪造或者故意破坏事故现场的； （三）转移、隐匿资金、财产，或者销毁有关证据、资料的； （四）拒绝接受调查或者拒绝提供有关情况和资料的； （五）在事故调查中作伪证或者指使他人作伪证的； （六）事故发生后逃匿的。"},{"i":31,"n":"第三十一条","txt":"事故发生单位主要负责人未依法履行安全生产管理职责，导致事故发生的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"发生较大以上事故单位管理混乱，不具备法律规定的安全生产条件，经整顿仍不能满足安全生产条件的，由发证机关依法暂扣或者吊销其有关证照；事故发生单位主要负责人受到刑事处罚或者撤职处分的，自刑罚执行完毕或者受处分之日起，5年内不得担任军工企事业单位的主要负责人。"},{"i":33,"n":"第三十三条","txt":"负有安全生产管理职责的部门或者单位有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。 （一）不立即组织应急救援的； （二）故意漏报、迟报或者谎报、瞒报事故的； （三）阻碍、干涉事故调查工作的； （四）在事故调查中作伪证或者指使他人作伪证的。"},{"i":34,"n":"第三十四条","txt":"参与事故调查的人员在事故调查中有下列行为之一的，依法给予处分；构成犯罪的，依法追究刑事责任。 （一）对事故调查工作不负责任，致使事故调查工作有重大疏漏的； （二）包庇、袒护负有事故责任的人员或者借机打击报复的。"},{"i":35,"n":"第三十五条","txt":"参与事故报告和调查处理的人员，违反有关保密规定的，按照有关法律、行政法规进行处理。"},{"i":36,"n":"第三十六条","txt":"核事故、军队组织的国防科研试验活动中发生的事故和海事事故引起的事故的报告和调查处理，不适用本办法。"},{"i":37,"n":"第三十七条","txt":"工业和信息化部所属高校发生生产安全事故的，应当立即向工业和信息化部报告。"},{"i":38,"n":"第三十八条","txt":"本办法所称的“以上”包括本数，所称的“以下”不包括本数。"},{"i":39,"n":"第三十九条","txt":"本办法自2011年6月1日起施行。"}],"dizhenxingzhengfuyiguiding":[{"i":1,"n":"第一条","txt":"为了加强地震行政行为的监督，防止和纠正违法的或者不当的具体地震行政行为，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政复议法》（以下简称《行政复议法》），制定本规定。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织向地震工作部门或者机构（以下统称地震行政机关）提出地震行政复议申请，地震行政机关受理地震行政复议申请、作出地震行政复议决定，适用本规定。"},{"i":3,"n":"第三条","txt":"履行地震行政复议职责的地震行政机关是地震行政复议机关。地震行政复议机关负责法制工作的机构具体办理地震行政复议事项，履行下列职责： （一）受理地震行政复议申请； （二）向有关组织和人员调查取证，查阅有关文件和资料； （三）审查申请地震行政复议的具体行政行为是否合法与适当，拟订地震行政复议决定； （四）对地震行政机关违反本规定的行为依照规定的权限和程序提出处理建议； （五）办理因不服地震行政复议决定提起行政诉讼的应诉事项； （六）法律、法规规定的其他职责。"},{"i":4,"n":"第四条","txt":"地震行政复议应当遵循合法、公正、公开、及时、便民的原则，坚持有错必纠，保障法律、法规的正确实施。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织有下列情形之一的，可以依照本规定申请地震行政复议： （一）对地震行政机关作出的赔偿损失、责令改正、恢复原状等行政决定不服的； （二）对地震行政机关作出的警告、罚款等行政处罚决定不服的； （三）对地震行政机关作出的有关许可证、资格证、资质证等证书变更、中止、撤销等决定不服的； （四）认为符合法定条件，申请地震行政机关颁发许可证、资格证、资质证等证书，或者申请地震行政机关审批、登记等事项，地震行政机关没有依法办理的； （五）认为地震行政机关的其他具体行政行为侵犯其合法权益的。"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织认为地震行政机关的具体行政行为侵犯其合法权益的，可以自知道该具体行政行为之日起60日内提出地震行政复议申请；法律规定的申请期限超过60日的除外。 因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。"},{"i":7,"n":"第七条","txt":"申请人申请地震行政复议，可以书面申请，也可以口头申请。口头申请的，应当当场记录。"},{"i":8,"n":"第八条","txt":"地震行政复议申请应当载明下列内容： （一）申请人的姓名、年龄、职业、住址等（法人或者其他组织的名称、地址、法定代表人的姓名）； （二）被申请人的名称、地址； （三）地震行政复议机关名称； （四）地震行政复议请求； （五）申请地震行政复议的主要事实、理由； （六）提出申请的时间。"},{"i":9,"n":"第九条","txt":"对县级以上地方各级地震行政机关的具体行政行为不服的，由申请人选择，可以向该部门的本级人民政府申请地震行政复议，也可以向上一级地震行政机关申请地震行政复议。"},{"i":10,"n":"第十条","txt":"对国务院地震工作主管部门的具体行政行为不服的，向国务院地震工作主管部门申请地震行政复议。"},{"i":11,"n":"第十一条","txt":"对县级以上地方各级地震行政机关与其他行政机关以共同的名义作出的具体行政行为不服的，向其共同上一级行政机关申请行政复议。"},{"i":12,"n":"第十二条","txt":"地震行政复议机关收到地震行政复议申请后，应当在5日内进行审查，对不符合本规定的地震行政复议申请，决定不予受理，并书面告知申请人；对不属于地震行政复议机关受理的行政复议申请，应当告知申请人向有关行政复议机关提出。 除前款规定外，地震行政复议申请自地震行政复议机关负责法制工作的机构收到之日起即为受理。"},{"i":13,"n":"第十三条","txt":"公民、法人或者其他组织依法提出地震行政复议申请，地震行政复议机关无正当理由不予受理的，上级地震行政机关应当责令其受理；必要时，上级地震行政机关可以直接受理。"},{"i":14,"n":"第十四条","txt":"《行政复议法》第二十一条规定可以停止执行的情况外，地震行政复议期间具体地震行政行为不停止执行。"},{"i":15,"n":"第十五条","txt":"地震行政复议原则上采取书面审查的办法，但是申请人提出要求或者地震行政复议机关负责法制工作的机构认为有必要时，可以向有关组织和人员调查情况，听取申请人、被申请人和第三人的意见。"},{"i":16,"n":"第十六条","txt":"地震行政复议机关负责法制工作的机构应当自地震行政复议申请受理之日起7日内，将地震行政复议申请书副本或者地震行政复议申请笔录复印件发送被申请人。被申请人应当自收到申请书副本或者申请笔录复印件之日起10日内，提出书面答复，并提交当初作出具体行政行为的证据、依据和其他有关材料。 申请人、第三人可以查阅被申请人提出的书面答复、作出具体行政行为的证据、依据和其他有关材料，除涉及国家秘密、商业秘密或者个人隐私外，地震行政复议机关不得拒绝。"},{"i":17,"n":"第十七条","txt":"在地震行政复议过程中，被申请人不得自行向申请人和其他有关组织或者个人收集证据。"},{"i":18,"n":"第十八条","txt":"地震行政复议决定作出前，申请人要求撤回地震行政复议申请的，经说明理由，可以撤回；撤回地震行政复议申请的，地震行政复议终止。"},{"i":19,"n":"第十九条","txt":"地震行政复议机关负责法制工作的机构应当对被申请人作出的具体行政行为进行审查，提出意见，经地震行政复议机关负责人同意或者集体讨论通过后，按照《行政复议法》第二十八条规定作出地震行政复议决定。"},{"i":20,"n":"第二十条","txt":"地震行政复议机关作出复议决定，应当制作地震行政复议决定书。 地震行政复议决定书应当载明如下事项： （一）申请人的姓名、年龄、职业、住址（法人或者其他组织的名称、地址、法定代表人姓名）； （二）被申请人的名称、地址、法定代表人的姓名、职务； （三）申请地震行政复议的主要请求和理由； （四）地震行政复议机关认定的事实、理由，适用的法律、法规、规章和具有普遍约束力的决定、命令； （五）地震行政复议结论； （六）不服地震行政复议决定向人民法院起诉的期限； （七）作出地震行政复议决定的时间。 地震行政复议决定书由地震行政复议机关法定代表人署名，加盖地震行政复议机关印章。 地震行政复议决定书一经送达，即发生法律效力。"},{"i":21,"n":"第二十一条","txt":"地震行政复议机关应当自受理申请之日起60日内作出地震行政复议决定。《行政复议法》第三十一条规定的特殊情况除外。"},{"i":22,"n":"第二十二条","txt":"被申请人应当履行地震行政复议决定。被申请人不履行或者无正当理由拖延履行地震行政复议决定的，地震行政复议机关应当责令其限期履行。"},{"i":23,"n":"第二十三条","txt":"申请人逾期不起诉又不履行地震行政复议的，按照下列规定分别处理： （一）维持具体地震行政行为的地震复议决定，由作出具体地震行政行为的机关依法强制执行，或者申请人民法院强制执行； （二）变更具体地震行政行为的地震复议决定，由地震行政复议机关依法强制执行，或者申请人民法院强制执行。"},{"i":24,"n":"第二十四条","txt":"地震行政复议机关应当于地震行政复议案件结案后30日内向上一级地震行政机关备案。"},{"i":25,"n":"第二十五条","txt":"地震行政复议机关违反本规定, 无正当理由不予受理依法提出的地震行政复议申请或者不按照规定转送地震行政复议申请的，或者在法定期限内不作出地震复议决定的，对直接负责的主管人员和其他直接责任人员依法给予警告、记过、记大过的行政处分；经责令受理仍不受理或者不按照规定转送地震行政复议申请，造成严重后果的，依法给予降级、撤职、开除的行政处分。"},{"i":26,"n":"第二十六条","txt":"地震行政复议机关工作人员在地震行政复议活动中，徇私舞弊或者有其他渎职、失职行为的，依法给予警告、记过、记大过的行政处分；情节严重的，依法给予降级、撤职、开除的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"地震行政复议被申请人违反本规定，不提出书面答复或者不提交作出具体行政行为的证据、依据和其他有关材料，或者阻挠、变相阻挠公民、法人或者其他组织依法申请地震行政复议的，对直接负责的主管人员和其他直接责任人员依法给予警告、记过、记大过的行政处分；进行报复陷害的，依法给予降级、撤职、开除的行政处分；构成犯罪的,依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"地震行政复议被申请人不履行或者无正当理由拖延履行地震行政复议决定的，对直接负责的主管人员和其他直接责任人员依法给予警告、记过、记大过的行政处分；经责令履行仍拒不履行的，依法给予降级、撤职、开除的行政处分。"},{"i":29,"n":"第二十九条","txt":"地震行政复议机关负责法制工作的机构发现有无正当理由不予受理地震行政复议申请、不按照规定期限作出地震行政复议决定、徇私舞弊、对申请人打击报复或者不履行地震行政复议决定等情形的，应当向有关行政机关提出建议，有关行政机关应当依照本规定和有关法律、法规作出处理。"},{"i":30,"n":"第三十条","txt":"地震行政复议机关受理地震行政复议申请，不得向申请人收取任何费用。地震行政复议活动所需经费，列入本机关的行政经费，由本级财政予以保障。"},{"i":31,"n":"第三十一条","txt":"地震行政复议期间的计算和地震行政复议文书的送达，依照《中华人民共和国民事诉讼法》关于期间、送达的规定执行。"},{"i":32,"n":"第三十二条","txt":"本规定由国务院地震工作主管部门负责解释。"},{"i":33,"n":"第三十三条","txt":"本规定自1999年10月1日起施行。 附：《中华人民共和国行政复议法》有关条文"},{"i":34,"n":"第二十一条","txt":"行政复议期间具体行政行为不停止执行；但是，有下列情形之一的，可以停止执行: (一)被申请人认为需要停止执行的； (二)行政复议机关认为需要停止执行的； (三)申请人申请停止执行，行政复议机关认为其要求合理，决定停止执行的； (四)法律规定停止执行的。"},{"i":35,"n":"第二十三条","txt":"行政复议机关负责法制工作的机构应当自行政复议申请受理之日起7日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到申请书副本或者申请笔录复印件之日起10日内，提出书面答复，并提交当初作出具体行政行为的证据、依据和其他有关材料。 申请人、第三人可以查阅被申请人提出的书面答复、作出具体行政行为的证据、依据和其他有关材料，除涉及国家秘密、商业秘密或者个人隐私外，行政复议机关不得拒绝。"},{"i":36,"n":"第二十八条","txt":"行政复议机关负责法制工作的机构应当对被申请人作出的具体行政行为进行审查，提出意见，经行政复议机关的负责人同意或者集体讨论通过后，按照下列规定作出行政复议决定： (一)具体行政行为认定事实清楚，证据确凿，适用依据正确，程序合法，内容适当的，决定维持； (二)被申请人不履行法定职责的，决定其在一定期限内履行； (三)具体行政行为有下列情形之一的，决定撤销、变更或者确认该具体行政行为违法；决定撤销或者确认该具体行政行为违法的，可以责令被申请人在一定期限内重新作出具体行政行为： 1.主要事实不清、证据不足的； 2.适用依据错误的； 3.违反法定程序的； 4.超越或者滥用职权的； 5.具体行政行为明显不当的。 (四)被申请人不按照本法第二十三条规定提出书面答复、提交当初作出具体行政行为的证据、依据和其他有关材料的，视为该具体行政行为没有证据、依据，决定撤销该具体行政行为。 行政复议机关责令被申请"},{"i":37,"n":"第三十一条","txt":"行政复议机关应当自受理申请之日起60日内作出行政复议决定；但法律规定的行政复议期限少于60日的除外。情况复杂，不能在规定期限内作出行政复议决定的，经行政复议机关的负责人批准，可以适当延长，并告知申请人和被申请人；但是延长期限最多不超过30日。 行政复议机关作出行政复议决定，应当制作行政复议决定书，并加盖印章。 行政复议决定书一经送达，即发生法律效力。"}],"dizhenxingzhengzhifaguiding":[{"i":1,"n":"第一条","txt":"为了加强地震行政执法工作，规范地震行政执法行为，保障公民、法人和其他组织的合法权益，根据国家有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"地震行政执法，是指国务院地震工作主管部门和县级以上地方人民政府负责管理地震工作的部门或者机构（以下统称地震行政执法机关），以及受委托进行地震行政执法的机构或者组织依据防震减灾法律、法规和规章的规定，按照法定权限和程序实施的具体行政行为。"},{"i":3,"n":"第三条","txt":"地震行政执法机关和受委托进行地震行政执法的机构或者组织及其执法工作人员进行地震行政执法活动，必须遵守本规定。"},{"i":4,"n":"第四条","txt":"地震行政执法必须遵循合法、公正、公开、及时的原则。"},{"i":5,"n":"第五条","txt":"地震行政执法机关及其执法工作人员依法进行地震行政执法活动，受国家法律保护。"},{"i":6,"n":"第六条","txt":"各级地震行政执法机关应当接受同级人民政府和上级地震行政执法机关的行政监督。"},{"i":7,"n":"第七条","txt":"各级地震行政执法机关是地震行政执法的主体，履行下列职责： (一)宣传、普及、贯彻、执行防震减灾法律、法规和规章； (二)制定地震行政执法的制度并组织实施； (三)向立法机关提出完善相关法律、法规的意见和建议； (四)组织地震行政执法的培训和考核； (五)监督下级地震行政执法机关的行政执法工作； (六)法律、法规和规章赋予的其他职责。"},{"i":8,"n":"第八条","txt":"地震行政执法机关根据需要在其权限内可以委托有关组织或者机构进行地震行政执法。 未设立地震工作机构的市、县的地震行政执法工作，由其上一级地震行政执法机关负责，或者委托有关组织或者机构负责。 委托机关负责监督受委托的组织或者机构实施的地震行政执法行为，并对行为后果负责；受委托组织在委托范围内，以委托机关名义进行地震行政执法活动。"},{"i":9,"n":"第九条","txt":"具备地震行政执法资格，依法履行地震行政执法职责的人员是地震行政执法人员。 地震行政执法人员应当具备下列条件： (一)坚持四项基本原则，遵纪守法； (二)具有良好的职业道德； (三)熟悉防震减灾业务工作； (四)熟悉防震减灾法律、法规、规章以及有关的法律知识。"},{"i":10,"n":"第十条","txt":"地震行政执法实行地域管辖。 国务院地震行政执法机关负责管理、指导和监督全国的地震行政执法。 县级以上地方各级地震行政执法机关负责管理本行政区域内的地震行政执法。 受委托的组织或者机构，在其委托的范围内进行地震行政执法。"},{"i":11,"n":"第十一条","txt":"地震行政执法机关之间因执法管辖权发生争议时，争议双方应当协商；协商不成的，案件由其共同上一级地震行政执法机关指定管辖。"},{"i":12,"n":"第十二条","txt":"地震行政执法机关发现查处的案件不属于自己管辖时，应当将案件移送到有管辖权的地震行政执法机关，受送机关不得再自行移送或者拒绝。"},{"i":13,"n":"第十三条","txt":"地震行政执法机关在查处案件时，如发现违法行为已经构成犯罪的，应当及时将案件移送给司法机关处理。"},{"i":14,"n":"第十四条","txt":"地震行政执法内容包括： (一)地震行政检查； (二)地震行政许可； (三)地震行政确认； (四)地震行政处罚； (五)地震行政奖励； (六)法律、法规和规章规定的其他地震行政执法行为。"},{"i":15,"n":"第十五条","txt":"地震行政检查，是指地震行政执法机关对公民、法人或者其他组织是否遵守防震减灾法律、法规和规章，是否执行地震行政决定、命令等情况进行检查的具体行政行为。"},{"i":16,"n":"第十六条","txt":"地震行政许可，是指地震行政执法机关依法对公民、法人或者其他组织提出的申请，通过颁发证明或者批准、登记、认可等方式，允许其行使某项权利，从事某项活动的具体行政行为。"},{"i":17,"n":"第十七条","txt":"地震行政确认，是指地震行政执法机关依法对公民、法人或者其他组织在防震减灾活动中的法律地位和权利、义务进行甄别，给予确定或者否定并宣告的具体行政行为。"},{"i":18,"n":"第十八条","txt":"地震行政处罚，是指地震行政执法机关依法对违反防震减灾法律、法规和规章规定的公民、法人或者其他组织给予制裁的具体行政行为。"},{"i":19,"n":"第十九条","txt":"地震行政奖励，是指地震行政执法机关对在贯彻执行防震减灾法律、法规和规章，为减轻地震灾害损失作出突出贡献的公民、法人或者其他组织给予奖励的具体行政行为。"},{"i":20,"n":"第二十条","txt":"地震行政执法人员进行地震行政检查、处罚等执法活动，应当出示表明其身份的执法证件。不按规定表明身份的，当事人有权拒绝。"},{"i":21,"n":"第二十一条","txt":"地震行政执法机关实施地震行政检查，必须告知被检查者检查的目的、内容、要求和方法等事项。 进行现场检查时应当制作笔录，并由被检查者阅核、签字；被检查者拒绝签字的，应当由2名以上现场检查人员签字并注明情况。 地震行政检查应当按照法定时间进行。 在检查中需要采取强制措施的，应当事先向被检查者说明理由。 检查结束后，应当对检查情况进行总结，并制作检查报告。"},{"i":22,"n":"第二十二条","txt":"地震行政许可的一般程序是：申请的提出、申请的受理、申请的审核、许可证的颁发。 地震行政执法机关应当对公民、法人或者其他组织提出的申请，依法进行审核，对不符合法定条件的申请应当给予驳回。 地震行政执法机关颁发的许可证应当载明许可的内容、期限、许可证件编号，并加盖颁发机关印章。"},{"i":23,"n":"第二十三条","txt":"地震行政确认的一般程序是：确认事项的提出、检查鉴定、确定鉴定结果和确认结果公告。 地震行政确认必须遵循国家有关法律、法规和技术规范。"},{"i":24,"n":"第二十四条","txt":"地震行政奖励的一般程序是：奖励的提出、审批、公布、授奖和存档。"},{"i":25,"n":"第二十五条","txt":"地震行政处罚的一般程序是：受理立案、调查取证、决定、执行和结案。"},{"i":26,"n":"第二十六条","txt":"地震行政执法机关对下列案件应当及时受理： (一)监督检查中发现的； (二)举报的； (三)移送的； (四)下级地震行政执法机关报请的； (五)上级地震行政执法机关指定办理的； (六)其他需要受理的案件。"},{"i":27,"n":"第二十七条","txt":"地震行政执法机关受理的案件符合下列条件的，应当予以立案： (一)有违法人和违法后果； (二)有事实依据； (三)属于地震行政处罚的范围； (四)属于本机关管辖。"},{"i":28,"n":"第二十八条","txt":"确定立案办理的案件，应当填写立案审批表，由地震行政执法机关负责人批准立案，确定立案日期和两名以上地震行政执法人员为案件承办人。"},{"i":29,"n":"第二十九条","txt":"对于立案办理的案件，地震行政执法机关应当调查取证，查明违法事实。"},{"i":30,"n":"第三十条","txt":"地震行政执法机关在作出行政处罚决定之前，应当及时告知当事人行政处罚认定的事实、理由、依据，以及当事人依法享有的权利。"},{"i":31,"n":"第三十一条","txt":"地震行政执法机关在进行地震行政处罚时，必须听取当事人的陈述和申辩，并进行复核，当事人提出的事实、理由或者依据成立的，应当予以采纳。地震行政执法机关不得因当事人申辩而加重处罚。"},{"i":32,"n":"第三十二条","txt":"对违法事实确凿，情节较轻，拟作出以下处罚决定的违法行为，地震行政执法机关可以作出现场处罚： (一)予以警告的处罚； (二)对公民处以五十元以下罚款的处罚； (三)对法人或者其他组织处以一千元以下罚款的处罚； (四)法律、法规规定的其他可以适用现场的处罚。 地震行政执法人员作出现场处罚时，应当填写预定格式的现场处罚决定书。"},{"i":33,"n":"第三十三条","txt":"除适用现场处罚的案件外，承办人员在案件调查终结后，应当对违法行为的事实、性质和社会危害程度进行合议并作好记录，合议应当根据认定的违法事实，依据防震减灾法律、法规和规章的规定，分别提出以下处理意见： (一)确定应当受到处罚的，依法提出予以地震行政处罚； (二)违法行为较轻，依法提出免于地震行政处罚； (三)违法行为不能成立的，依法撤销案件； (四)违法行为已构成犯罪的，将案件移送司法机关处理。"},{"i":34,"n":"第三十四条","txt":"依据防震减灾法律、法规和规章的规定应当给予行政处罚的，案件承办人员应当制作地震行政处罚意见书，报地震行政执法机关负责人审批。 地震行政执法机关负责人应当根据案件情节轻重依法提出行政处罚决定。对情节复杂或者重大违法行为给予较重的行政处罚，由地震行政执法机关负责人组织集体讨论决定。"},{"i":35,"n":"第三十五条","txt":"地震行政执法机关在作出地震行政处罚时，应当制作地震行政处罚决定书，决定书应载明下列事项，并加盖本机关的印章： (一)当事人的姓名或者名称、地址； (二)执法机关认定的违法事实； (三)适用的法律、法规、规章； (四)处理结论； (五)处理决定的履行方式和期限； (六)当事人申请行政复议或者提起行政诉讼的权利、期限及受理机关的名称； (七)作出处理决定的行政机关名称、法定代表人姓名以及作出决定的日期。 涉及罚款的还应当载明收缴罚款的金融机构名称、地址以及不按规定期限缴纳罚款的法律后果。"},{"i":36,"n":"第三十六条","txt":"行政处罚决定书应当在宣告后当场交付当事人，或者在7日内将行政处罚决定书送达当事人。受送达人在送达回证上签名，并注明签收日期。 受送达人不在的，由其指定的代收人、同住的成年家属或者所在单位代为签收。 受送达人拒绝接受处罚决定书，则应当邀请有关基层组织或者其他人到场见证，在送达回证上注明拒收事由、日期、送达人、见证人签名或者盖章，并将送达书留在受送达人住处或者单位收发部门。 不能直接送达的，可邮寄送达、公告送达、委托代为送达。 行政处罚决定书自送达当事人之日起生效。"},{"i":37,"n":"第三十七条","txt":"地震行政执法机关在作出较大数额的罚款、中止许可证等较重处罚决定前，应当告知当事人有要求举行听证的权利；当事人要求组织听证的，地震行政执法机关应当组织听证。 前款所称较大数额罚款的标准依照本省、自治区、直辖市人民政府的有关规定执行。 听证费用由听证机关承担。"},{"i":38,"n":"第三十八条","txt":"地震行政执法机关告知当事人听证的权利时，应当制作听证告知书。听证告知书应当载明以下事项： (一)当事人的姓名或者名称、地址 (二)当事人的违法行为、行政处罚的理由、依据和拟作出的行政处罚意见； (三)告知当事人有要求听证的权利； (四)告知当事人提出听证要求的期限和受理听证申请的组织或者机构。 听证告知书必须盖有地震行政执法机关的印章。"},{"i":39,"n":"第三十九条","txt":"当事人提出听证申请时，应当提交听证申请书。听证申请书应当载明以下事项： (一)申请人的基本情况； (二)请求听证的目的； (三)申辩理由及其依据； (四)申请递交的地震行政执法机关的名称； (五)提交申请书的日期。 申请人应当在申请书上签名或者盖章。"},{"i":40,"n":"第四十条","txt":"地震行政执法机关在收到听证申请后，应当组织案件调查人员进行研究，并依法作出是否受理的决定；对依法不予受理的听证申请，应当告知当事人。 对依法予以受理的听证申请，应当制作听证受理书，载明以下事项： (一)听证申请人的姓名或者名称、地址； (二)案件基本情况； (三)申请人申请听证的理由； (四)听证受理决定。"},{"i":41,"n":"第四十一条","txt":"听证由拟作出行政处罚的地震行政执法机关组织，听证的具体工作由其法制工作机构负责。"},{"i":42,"n":"第四十二条","txt":"举行听证的地震行政执法机关，应当在举行听证7日前，将听证通知书送达当事人。 听证通知书应当载明以下事项： (一)当事人的姓名或者名称、地址； (二)举行听证的时间、地点和方式； (三)听证人员名单； (四)告知当事人有权申请回避； (五)告知当事人准备证据，通知证人等事项。 听证通知书应当加盖地震行政执法机关的印章。"},{"i":43,"n":"第四十三条","txt":"听证会按照下列程序进行： (一)听证员检查听证参加人员是否到场，宣布听证纪律； (二)听证主持人宣布案由，主持人、听证员和书记员名单，告知当事人有关的权利和义务，询问当事人是否提出回避申请； (三)案件调查人员陈述当事人的违法事实、证据、处罚依据和处罚建议； (四)当事人进行陈述和申辩，并出示相关证据； (五)当事人及其代理人和案件调查人员进行质证和辩论； (六)当事人及其代理人作最后陈述； (七)听证主持人宣布听证结束。"},{"i":44,"n":"第四十四条","txt":"听证举行后，地震行政执法机关应当根据听证情况进行复核。违法事实清楚的，依法作出行政处罚决定；违法事实与原来认定有出入的，应当调查核实，查清事实后，作出处理决定。"},{"i":45,"n":"第四十五条","txt":"地震行政处罚依法作出后，当事人应当在处罚决定的期限内予以履行。"},{"i":46,"n":"第四十六条","txt":"除法律规定的情况外，地震行政执法机关及其工作人员不得擅自收缴罚款。 依法可以当场收缴罚款的，地震行政执法机关及其工作人员必须向当事人出具省、自治区、直辖市财政部门统一制发的罚款收据。"},{"i":47,"n":"第四十七条","txt":"当事人逾期不履行行政处罚决定的，作出行政处罚的地震行政执法机关可以采取下列措施： (一)到期不缴纳罚款的，每日按罚款数额的3%加处罚款； (二)申请人民法院强制执行。 强制执行费用由被处罚人承担。"},{"i":48,"n":"第四十八条","txt":"地震行政处罚决定执行后，承办人员应当制作结案报告，将有关材料进行整理装订，并由承办人员签名或盖章后，归档保存。"},{"i":49,"n":"第四十九条","txt":"地震行政执法机关应当将作出较大数额罚款、中止许可证等行政处罚案件在结案后30日内报上一级地震行政执法机关备案。"},{"i":50,"n":"第五十条","txt":"地震行政执法机关对符合下列情况之一的个人或者单位，应当根据国家有关规定给予表彰和奖励： (一)在宣传、贯彻防震减灾法律、法规和规章工作中成绩显著的； (二)制止和纠正违反防震减灾法律、法规和规章的行为，产生良好社会影响的； (三)在执法工作中避免或者挽回重大损失的； (四)在地震行政监督工作中作出显著成绩的； (五)其他需要奖励的。"},{"i":51,"n":"第五十一条","txt":"地震行政执法机关有下列行为之一的，由其上级地震行政执法机关或者同级人民政府通报批评，可以对直接负责的主管人员和其他责任人员依法给予行政处分： (一)作出具体行政行为违法或者不适当，给公民、法人或者其他组织的合法权益或者国家利益造成严重损失的； (二)拒不履行法定职责或者超越职权，造成不良后果的； (三)以行政执法权为本单位谋取私利的； (四)不按本规定的期限处理违法行为的； (五)应当给予行政处分的其他违法行为。"},{"i":52,"n":"第五十二条","txt":"地震行政执法机关的执法工作人员在地震行政执法活动中有下列违法行为之一的，由其所在单位依法给予行政处分；构成犯罪的，移送司法机关依法追究刑事责任： (一)滥用职权、滥施处罚造成不良后果的； (二)适用法律、法规、规章错误，或者违反法定程序，造成不良后果的； (三)对举报行政执法中违法问题的举报人，或者对申请行政复议、提起行政诉讼的单位或者个人打击报复的； (四)在行政执法工作中徇私枉法、索贿受贿，或者采取其他手段侵犯公民、法人或者其他组织的合法权益的； (五)在行政执法工作中泄露国家机密或者其他应当保密的商业、技术秘密或者个人隐私的； (六)推诿不履行法定职责的； (七)应当给予行政处分的其他行为。"},{"i":53,"n":"第五十三条","txt":"地震行政执法机关不依法追究执法人员违法行为责任的，受具体行政行为侵害的公民、法人或者其他组织，有权向上级地震行政执法机关或者同级人民政府举报。"},{"i":54,"n":"第五十四条","txt":"本规定由国务院地震工作主管部门负责解释。"},{"i":55,"n":"第五十五条","txt":"本规定自发布之日起施行。"}],"dizhenxingzhengfazhijianduguiding":[{"i":1,"n":"第一条","txt":"为了推进依法行政，加强地震行政法制监督，根据国家有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称地震行政法制监督，是指上级地震工作部门或者机构（以下统称地震行政机关）对下级地震行政机关、各级地震行政机关对所属工作机构及其委托的执法机构行政行为进行的督促、检查与纠正活动。"},{"i":3,"n":"第三条","txt":"地震行政法制监督，应当遵循合法、公正、公开、及时、有效的原则，保障法律、法规的正确实施。"},{"i":4,"n":"第四条","txt":"各级地震行政机关的法制工作机构是地震行政法制监督的执行机构。 国务院地震行政机关的法制工作机构负责本部门和全国地震行政法制监督工作的组织与实施。 省、市（地）、县（市）地震行政机关的法制工作机构负责本部门和辖区内地震行政法制监督工作的组织与实施。"},{"i":5,"n":"第五条","txt":"地震行政机关的法制工作机构履行下列职责： （一）制定行政法制监督工作计划和实施办法； （二）负责地震行政执法检查的组织工作，并配合有关监督部门进行执法检查工作； （三）受理规范性文件的备案； （四）受理行政复议和承担本部门行政诉讼案件的应诉工作； （五）协调行政执法争议； （六）审查具体行政行为； （七）调查违法行政行为案件； （八）管理、培训行政执法人员和行政监督人员； （九）建立健全行政法制监督档案； （十）法律法规规定的其他行政法制监督任务。"},{"i":6,"n":"第六条","txt":"地震行政法制监督的主要内容： （一）实施法律、法规和规章的情况； （二）法定职责的履行情况； （三）规范性文件的合法性； （四）行政执法主体和执法程序的合法性； （五）具体行政行为的合法性、适当性； （六）行政执法中违法行政行为或者失职行为的查处情况； （七）其他法律法规规定的法制监督事项。"},{"i":7,"n":"第七条","txt":"地震行政法制监督通过下列制度或者方式实施： （一）地方性法规、规章及政府规范性文件报告制度。省级地震行政机关应当在防震减灾地方性法规、规章和政府规范性文件发布后30日内，将法规、规章和政府规范性文件文本一式三份报送国务院地震行政机关。 有立法权的市的地震行政机关应当在本市地方性法规、政府规章和规范性文件发布后30日内，将法规、规章和政府规范性文件文本一式三份报上级地震行政机关，同时报送国务院地震行政机关。 （二）地震行政机关规范性文件备案制度。地方各级地震行政机关制定的规范性文件，应当于发布后30日内，将文本一式三份报送上级地震行政机关备案。 （三）地震行政机关规范性文件起草审核制度。各级地震行政机关所属工作部门起草的规范性文件，应当经本级法制工作机构审查、会签后，提请本级行政负责人签发。 （四）实施法律、法规、规章情况的报告制度。地方各级地震行政机关，应当在防震减灾法律、法规、规章正"},{"i":8,"n":"第八条","txt":"地震行政法制监督中发现的问题，按下列规定处理： （一）规范性文件设定的内容违法或者不当的，上级地震行政机关应当责令限期改正；逾期不改的，上级地震行政机关予以撤销。 （二）作出的具体行政行为不合法、不适当的，上级地震行政机关应当责令限期改正；逾期不改的，上级地震行政机关予以变更或者撤销。 （三）不履行法定职责的，上级地震行政机关或者本级法制工作机构应当督促其履行，仍不履行的，上级或者本级地震行政机关应当依法追究有关行政负责人和其他直接责任人的行政责任。 （四）对国家权力机关、人民政府交办的地震行政违法案件和群众举报或者通过其他途径获知的行政违法行为，地震行政机关应当认真审查，属于自己管辖的，应当及时立案；属于上级地震行政机关管辖的，应当及时移送；属于下级地震行政机关管辖的，应当及时督促其依法查处。负责办案的地震行政机关应当在案件处理后30日内将处理情况报告督办机关。 （五）公民、法人或者"},{"i":9,"n":"第九条","txt":"地震行政机关的法制工作机构在履行行政法制监督职责时，有权查询、调阅有关执法案卷和其他相关材料，有关地震行政机关及其工作人员，必须予以配合和协助。"},{"i":10,"n":"第十条","txt":"国务院地震行政机关负责统一制发地震行政法制监督证。地方各级地震行政机关负责将本辖区地震行政法制监督证持证人员情况向本级人民政府的法制工作部门备案。"},{"i":11,"n":"第十一条","txt":"地震行政法制监督人员的主要职责是： （一）检查行政执法人员持证执法情况； （二）维护合法的行政执法活动； （三）制止、纠正行政执法人员正在实施的违法执法行为，保护公民、法人和其他组织的合法权益； （四）对行政执法中的违法行为进行调查； （五）督促行政执法人员履行法定职责； （六）对解决行政执法中带有普遍性的问题提出建议。"},{"i":12,"n":"第十二条","txt":"在地震行政法制监督工作中成绩显著的，由本级地震行政机关或者上级地震行政机关给予表彰或者奖励。"},{"i":13,"n":"第十三条","txt":"在地震行政法制监督中违反本规定，造成不良后果或者影响，情节较轻的，由上级地震行政机关责令限期改正；情节严重的，依法追究单位主管人员和直接责任人员的行政责任。"},{"i":14,"n":"第十四条","txt":"本规定所称规范性文件，是指各级地震行政机关为贯彻实施法律、法规和规章，依职责权限制定的，在一定范围内适用，并具有普遍约束力的文件的总称。"},{"i":15,"n":"第十五条","txt":"本规定由中国地震局负责解释。"},{"i":16,"n":"第十六条","txt":"本规定自2000年3月1日起施行。"}],"dizhenxingzhengguizhangzhidingchengxuguiding":[{"i":1,"n":"第一条","txt":"为了保证制定地震行政规章科学化、规范化，提高质量，根据有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称规章，是指由中国地震局或者中国地震局会同国务院有关部门，根据有关法律、法规，在职权范围内制定的，调整防震减灾活动的社会关系，具有普遍约束力的行为规范的总和。 规章由中国地震局局长签署中国地震局令发布。 以中国地震局令以外形式发布的其他规范性文件、政策性文件、内部工作规则和不具有普遍约束力的文件不属于地震行政规章。"},{"i":3,"n":"第三条","txt":"地震行政规章按内容不同，称为“规定”、“办法”或者“实施细则”。 对某一方面的行政管理关系作比较全面、系统的规范，称“规定”。 对某一项行政管理关系作比较具体的规范，称“办法”。 对国务院行政法规所作的具体实施规范，称为“实施细则”。"},{"i":4,"n":"第四条","txt":"地震行政规章的起草、审议、发布、修改、废止和解释，应当依照本规定。"},{"i":5,"n":"第五条","txt":"中国地震局法规司负责管理地震行政规章制定的组织、协调等工作。"},{"i":6,"n":"第六条","txt":"中国地震局法规司根据国家防震减灾事业发展和管理工作的需要，在广泛调研论证的基础上拟订规章制定规划，报局务会议审定实施。 中国地震局法规司，根据规章制定规划，结合全局工作部署，拟订规章制定计划，报局长办公会议审定实施。 规章制定规划的年限一般为五年，规章制定计划的年限一般为一年。"},{"i":7,"n":"第七条","txt":"规章制定规划、计划的制定和实施，应当与防震减灾法律体系建设相一致，保证立法工作的严肃性、连续性。"},{"i":8,"n":"第八条","txt":"规章制定规划、计划的调整，应当由法规司提出，报局长办公会议审定。"},{"i":9,"n":"第九条","txt":"法规司负责规章制定规划、计划实施的组织和监督执行工作。"},{"i":10,"n":"第十条","txt":"已列入年度计划的规章由业务主管司(室)负责起草。规章内容涉及两个以上司(室)工作的，组成起草组，由主要业务司（室）负责牵头，有关司(室)参加起草工作。 法规司在规章起草中进行立法指导，重要的规章可以由法规司直接负责或者会同有关司（室）起草。"},{"i":11,"n":"第十一条","txt":"起草规章包括规章草案和起草说明。 规章草案的具体内容一般应当包括：制定的宗旨、依据、适用范围、基本原则、管理机关、实体内容、执行程序、奖惩办法和施行日期等。 起草说明的内容主要包括：制定的目的和依据、立法指导思想和原则、起草过程、需要解释的政策界限和有关问题等。"},{"i":12,"n":"第十二条","txt":"规章的内容分条文书写，冠以“第某条”字样，每条应当包含一项规则，可以分设款、项、目。款不冠数字，项冠以(一)、(二)、(三)等数字，目冠以1、2、3等数字。条、款、项、目均应当另起一行缩进二字书写。 规章内容繁杂或者条文较多的，可以分章、节。必要时，可以有目录、注释、附录、附表、索引等附加部分。"},{"i":13,"n":"第十三条","txt":"规章应当结构严谨、条理清晰、概念明确、文字简炼规范、标点正确。"},{"i":14,"n":"第十四条","txt":"起草规章，应当征求有关单位及专家的意见，对于涉及其他司室主管的业务或者与其他部门关系密切的规定，应当与有关部门协商一致。经过充分协商不能取得一致意见的，应当附有关情况的说明。"},{"i":15,"n":"第十五条","txt":"起草规章，应当注意与有关行政法规、规章的衔接和协调。对同一事项，如果作出与别的行政法规、规章不相一致的规定，应当在上报规章草案时专门提出并说明情况和理由。"},{"i":16,"n":"第十六条","txt":"起草规章，应当对现行内容相同的规章进行清理。如果现行的规章将被起草的规章所代替，必须在草案中写明予以废止。"},{"i":17,"n":"第十七条","txt":"规章草案定稿后，由起草单位领导签署送审报告，将送审稿、起草说明一并送法规司审查。 在审查中，有下列情况之一的，由起草单位予以修改： (一) 体例和结构不符合本规定第十一条、第十二条和第十三条要求的； (二) 意见分歧大，需要作较大调整的； (三) 内容与法律、行政法规相抵触的； (四) 条文内容不明确，适用性、可操作性差的。"},{"i":18,"n":"第十八条","txt":"规章草案，经法规司审查后，由法规司提出审议报告，报送主管副局长批准后，按程序提交局务会议审议。"},{"i":19,"n":"第十九条","txt":"规章草案应当经局务会议审议通过。内容简单或者专业性较强的规章，局长或者主管副局长认为必要的，也可由局长或者有关副局长传阅审批。"},{"i":20,"n":"第二十条","txt":"局务会议审议法规、规章草案时，负责起草工作部门的负责人作起草说明，法规司负责人作审查说明。 对局务会议提出重大问题或者需要作大量修改的规章草案，须经起草部门论证、修改后，再次提交局务会审定。"},{"i":21,"n":"第二十一条","txt":"规章草案经审定后，由法规司负责起草中国地震局令，统一编号，报局长签署发布。"},{"i":22,"n":"第二十二条","txt":"规章发布令应当包括发布机关、序号、规章名称、通过形式、通过日期、生效日期和签署人等项内容。"},{"i":23,"n":"第二十三条","txt":"规章明确规定自发布之日起施行的，自发布之日起发生效力。 规章有特定施行日期的，自该特定日期起发生效力。 规章有特定施行区域的，在该特定区域内具有效力。"},{"i":24,"n":"第二十四条","txt":"经中国地震局局长签署中国地震局令发布的规章，全文刊登于《国务院公报》。 在国务院公报上刊登的规章文本，为标准文本。"},{"i":25,"n":"第二十五条","txt":"规章的修改包括修订和修正。 对规章进行全面修改，应当采取修订的形式。 规章因下列情况之一需要修改的，应当采取修正的形式∶ (一) 基于政策或者事实的需要，有必要增减内容的； (二) 因有关法律、行政法规的修正或者废止而应当作相应修正的； (三) 规定的主管机关或者执行机关发生变更的； (四) 同一事项在两个以上的规章中予以规定，且不相一致的； (五) 其他需要修改的情况。 规章修改，应当遵循本规定有关规章起草和审议的程序规定。 规章的某一项规定适用其他规章规定的，其他规章修正后，适用修正后的规章。"},{"i":26,"n":"第二十六条","txt":"规章有下列情况之一的，应当予以废止： (一) 规定的事项已经执行完毕，或者因情况变更，无继续施行必要的； (二) 因有关法律、行政法规的废止或者修正，失去立法依据的； (三) 同一事项已由新规章规定，并发布施行的。"},{"i":27,"n":"第二十七条","txt":"规章的修改或者废止，应当经法规司审查，报局务会议通过后，由局长签署中国地震局令予以公布。但因第二十六条第三项原因废止的规章除外。 依前款程序废止的规章，自废止令发布之日起失效。"},{"i":28,"n":"第二十八条","txt":"规章规定有施行期限的，期满自行废止。 主管司（室）认为需要延长的，应当于期限届满3个月前报送局务会议审议。延长规章的施行期限批准后，由局长签署发布令，予以公告。"},{"i":29,"n":"第二十九条","txt":"规章自中国地震局令发布之日起30日内，由法规司负责报送国务院备案。"},{"i":30,"n":"第三十条","txt":"各省、自治区、直辖市人民政府负责管理地震工作的部门关于规章具体应用的请示，由法规司负责以书面形式进行解释。解释内容由法规司会同有关司（室）商定起草，经局长或者主管副局长审定签发后生效。 规章已有明确规定的内容，不予解释。"},{"i":31,"n":"第三十一条","txt":"国务院立法规划和计划规定由中国地震局负责的法律、行政法规草案的起草工作，由法规司负责组织。"},{"i":32,"n":"第三十二条","txt":"《地震行政法制监督规定》第十四条规定的由中国地震局制定的规范性文件，应当经法规司审查会签后，提请主管局长签发。"},{"i":33,"n":"第三十三条","txt":"防震减灾法律、行政法规和规章的汇编工作，由法规司负责。"},{"i":34,"n":"第三十四条","txt":"本规定自2000年3月1日起施行。1989年8月10日原国家地震局颁布的《关于行政法规制定的暂行办法》同时废止。"}],"chengshizhenkongzhixingxiangxiguihuabianzhishenpibdc87e8":[{"i":1,"n":"第一条","txt":"为了规范城市、镇控制性详细规划编制和审批工作，根据《中华人民共和国城乡规划法》，制定本办法。"},{"i":2,"n":"第二条","txt":"控制性详细规划的编制和审批，适用本办法。"},{"i":3,"n":"第三条","txt":"控制性详细规划是城乡规划主管部门作出规划行政许可、实施规划管理的依据。 国有土地使用权的划拨、出让应当符合控制性详细规划。"},{"i":4,"n":"第四条","txt":"控制性详细规划的编制和管理经费应当按照《城乡规划法》第六条的规定执行。"},{"i":5,"n":"第五条","txt":"任何单位和个人都应当遵守经依法批准并公布的控制性详细规划，服从规划管理，并有权就涉及其利害关系的建设活动是否符合控制性详细规划的要求向城乡规划主管部门查询。 任何单位和个人都有权向城乡规划主管部门或者其他有关部门举报或者控告违反控制性详细规划的行为。"},{"i":6,"n":"第六条","txt":"城市、县人民政府城乡规划主管部门组织编制城市、县人民政府所在地镇的控制性详细规划；其他镇的控制性详细规划由镇人民政府组织编制。"},{"i":7,"n":"第七条","txt":"城市、县人民政府城乡规划主管部门、镇人民政府（以下统称控制性详细规划组织编制机关）应当委托具备相应资质等级的规划编制单位承担控制性详细规划的具体编制工作。"},{"i":8,"n":"第八条","txt":"编制控制性详细规划，应当综合考虑当地资源条件、环境状况、历史文化遗产、公共安全以及土地权属等因素，满足城市地下空间利用的需要，妥善处理近期与长远、局部与整体、发展与保护的关系。"},{"i":9,"n":"第九条","txt":"编制控制性详细规划，应当依据经批准的城市、镇总体规划，遵守国家有关标准和技术规范，采用符合国家有关规定的基础资料。"},{"i":10,"n":"第十条","txt":"控制性详细规划应当包括下列基本内容： （一）土地使用性质及其兼容性等用地功能控制要求； （二）容积率、建筑高度、建筑密度、绿地率等用地指标； （三）基础设施、公共服务设施、公共安全设施的用地规模、范围及具体控制要求，地下管线控制要求； （四）基础设施用地的控制界线（黄线）、各类绿地范围的控制线（绿线）、历史文化街区和历史建筑的保护范围界线（紫线）、地表水体保护和控制的地域界线（蓝线）等“四线”及控制要求。"},{"i":11,"n":"第十一条","txt":"编制大城市和特大城市的控制性详细规划，可以根据本地实际情况，结合城市空间布局、规划管理要求，以及社区边界、城乡建设要求等，将建设地区划分为若干规划控制单元，组织编制单元规划。 镇控制性详细规划可以根据实际情况，适当调整或者减少控制要求和指标。规模较小的建制镇的控制性详细规划，可以与镇总体规划编制相结合，提出规划控制要求和指标。"},{"i":12,"n":"第十二条","txt":"控制性详细规划草案编制完成后，控制性详细规划组织编制机关应当依法将控制性详细规划草案予以公告，并采取论证会、听证会或者其他方式征求专家和公众的意见。 公告的时间不得少于30日。公告的时间、地点及公众提交意见的期限、方式，应当在政府信息网站以及当地主要新闻媒体上公布。"},{"i":13,"n":"第十三条","txt":"控制性详细规划组织编制机关应当制订控制性详细规划编制工作计划，分期、分批地编制控制性详细规划。 中心区、旧城改造地区、近期建设地区，以及拟进行土地储备或者土地出让的地区，应当优先编制控制性详细规划。"},{"i":14,"n":"第十四条","txt":"控制性详细规划编制成果由文本、图表、说明书以及各种必要的技术研究资料构成。文本和图表的内容应当一致，并作为规划管理的法定依据。"},{"i":15,"n":"第十五条","txt":"城市的控制性详细规划经本级人民政府批准后，报本级人民代表大会常务委员会和上一级人民政府备案。 县人民政府所在地镇的控制性详细规划，经县人民政府批准后，报本级人民代表大会常务委员会和上一级人民政府备案。其他镇的控制性详细规划由镇人民政府报上一级人民政府审批。 城市的控制性详细规划成果应当采用纸质及电子文档形式备案。"},{"i":16,"n":"第十六条","txt":"控制性详细规划组织编制机关应当组织召开由有关部门和专家参加的审查会。审查通过后，组织编制机关应当将控制性详细规划草案、审查意见、公众意见及处理结果报审批机关。"},{"i":17,"n":"第十七条","txt":"控制性详细规划应当自批准之日起20个工作日内，通过政府信息网站以及当地主要新闻媒体等便于公众知晓的方式公布。"},{"i":18,"n":"第十八条","txt":"控制性详细规划组织编制机关应当建立控制性详细规划档案管理制度，逐步建立控制性详细规划数字化信息管理平台。"},{"i":19,"n":"第十九条","txt":"控制性详细规划组织编制机关应当建立规划动态维护制度，有计划、有组织地对控制性详细规划进行评估和维护。"},{"i":20,"n":"第二十条","txt":"经批准后的控制性详细规划具有法定效力，任何单位和个人不得随意修改；确需修改的，应当按照下列程序进行： （一）控制性详细规划组织编制机关应当组织对控制性详细规划修改的必要性进行专题论证； （二）控制性详细规划组织编制机关应当采用多种方式征求规划地段内利害关系人的意见，必要时应当组织听证； （三）控制性详细规划组织编制机关提出修改控制性详细规划的建议，并向原审批机关提出专题报告，经原审批机关同意后，方可组织编制修改方案； （四）修改后应当按法定程序审查报批。报批材料中应当附具规划地段内利害关系人意见及处理结果。 控制性详细规划修改涉及城市总体规划、镇总体规划强制性内容的，应当先修改总体规划。"},{"i":21,"n":"第二十一条","txt":"各地可以根据本办法制定实施细则和编制技术规定。"},{"i":22,"n":"第二十二条","txt":"本办法自2011年1月1日起施行。"}],"chengshigongyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了促进城市公园事业高质量发展，改善城市生态和人居环境，根据《中华人民共和国建筑法》《城市绿化条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称城市公园，是指城市内具备园林景观和服务设施，具有改善生态、美化环境、休闲游憩、健身娱乐、传承文化、保护资源、科普教育和应急避难等功能，向公众开放的场所，包括利用公园绿地建设的公园和其他纳入城市公园名录的公园。"},{"i":3,"n":"第三条","txt":"本办法适用于城市公园的规划、建设、保护和管理工作。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责对全国城市公园工作进行指导监督。 省、自治区人民政府住房城乡建设主管部门负责对本行政区域内的城市公园工作进行指导监督。 直辖市、市、市辖区、县人民政府确定的城市园林绿化主管部门（以下简称城市园林绿化主管部门）按照职责负责本行政区域内城市公园的监督管理工作。"},{"i":5,"n":"第五条","txt":"城市公园是公益性城市基础设施。 城市公园规划、建设、保护和管理工作所需经费，由城市园林绿化主管部门向财政申请予以保障。"},{"i":6,"n":"第六条","txt":"城市园林绿化主管部门应当建立城市公园名录，并逐级报上一级园林绿化主管部门。城市公园名录应当包括公园名称、类别、位置、面积、管理单位、监管单位和联系方式等内容，并向社会公开。 城市园林绿化主管部门应当根据公园规模、功能、位置等对城市公园进行分类分级，在养护经费、考核检查等方面实行差异化管理。"},{"i":7,"n":"第七条","txt":"城市园林绿化主管部门应当加强信息化建设，提高城市公园管理的数字化、智能化水平。 鼓励开展城市公园事业的科学技术研究，推广应用新材料、新工艺、新技术，提升城市公园品质和功能。"},{"i":8,"n":"第八条","txt":"鼓励单位和个人通过认种认养、捐资捐物、志愿服务等形式，依法参与城市公园的规划、建设、保护和管理工作，推动城市公园共建共治共享。"},{"i":9,"n":"第九条","txt":"城市园林绿化主管部门应当依据城市绿地系统规划等相关规划，构建布局均衡、类型丰富、功能完备、品质优良的城市公园体系。 城市园林绿化主管部门应当在城市更新过程中，根据城市体检结果完善城市公园体系，及时提出优化城市公园布局、完善服务设施的方案或者计划，按照职能分工予以实施。"},{"i":10,"n":"第十条","txt":"城市园林绿化主管部门按照有关规定审查城市公园建设项目设计方案的，应当重点审查以下方面： （一）是否符合科学、生态、节俭的要求，落实人民城市、绿色低碳、安全发展等理念； （二）植物选择与配置是否科学合理，遵循自然规律和生物特性，体现植物多样性、特色性以及乡土植物选择原则； （三）绿化用地比例是否符合要求，功能布局是否合理，是否设置满足功能需要的园路、活动场地以及停车位、公厕等设施，公园主要出入口的设置是否与城市交通、游客流量等相适应； （四）是否保护城市公园内古树名木、具有文化价值的建（构）筑物和历史遗迹遗存、具有科学价值的自然遗迹； （五）是否保护自然山体、水体、地形、地貌以及湿地、生物物种等资源和风貌； （六）是否突出人文内涵和地域特色，融合历史、文化、艺术、传统工艺等； （七）是否符合法律法规和技术标准规定的其他要求。"},{"i":11,"n":"第十一条","txt":"城市公园建设项目设计应当由具有相应资质的设计单位承担。"},{"i":12,"n":"第十二条","txt":"城市公园建设项目应当按照批准的设计方案和有关规定进行建设，依法办理工程建设项目审批手续。 承担城市公园建设项目中园林绿化工程的施工企业，应当具有与所承揽的工程相匹配的园林绿化专业技术人员和技能人员，项目负责人应当具备相应的专业技术能力和现场管理工作经历。城市公园建设项目中的房屋建筑、市政公用、水利水电等专项工程，应当由具有相应资质的施工企业承担。"},{"i":13,"n":"第十三条","txt":"城市园林绿化主管部门应当根据城市防灾减灾等相关规划，协同配合有关部门利用城市公园建设应急避难场所。"},{"i":14,"n":"第十四条","txt":"城市公园应当按照无障碍设施工程建设标准，配套建设无障碍设施。既有城市公园不符合无障碍设施工程建设标准的，应当组织实施改造；不具备无障碍设施改造条件的，应当依法采取必要的替代性措施。"},{"i":15,"n":"第十五条","txt":"城市公园建设项目竣工后，建设单位应当依法组织竣工验收，经验收合格方可交付使用。 建设单位应当按照国家有关档案管理的规定，及时收集、整理建设项目各环节的文件资料，建立、健全建设项目档案，并在城市公园建设项目竣工验收后，及时移交城建档案管理机构。"},{"i":16,"n":"第十六条","txt":"建设单位或者城市公园管理单位应当在城市公园经依法批准、核准或者备案后，投入使用前，向城市园林绿化主管部门提出城市公园命名申请，并提交下列材料： （一）城市公园命名的方案及理由； （二）城市公园的位置、规模、功能、用地性质等基本情况； （三）依法应当提交的其他材料。 城市公园需要更名的，参照前款执行。"},{"i":17,"n":"第十七条","txt":"对申请材料齐全且符合下列条件的城市公园命名、更名申请，城市园林绿化主管部门应当依法予以批准，并于批准之日起15日内将城市公园名称报送同级人民政府地名行政主管部门备案： （一）含义明确、健康，不违背公序良俗； （二）使用国家通用语言文字，避免使用生僻字； （三）尊重当地历史和市民情感，注重文化内涵； （四）与公园所承担的改善生态、美化环境、休闲游憩、健身娱乐、传承文化、保护资源、科普教育和应急避难等功能相适应； （五）一般不以人名作城市公园名称，不以国家领导人的名字作城市公园名称； （六）不以外国人名、地名作城市公园名称； （七）不以企业名称或者商标名称作城市公园名称； （八）遵守法律、行政法规和国家有关规定。"},{"i":18,"n":"第十八条","txt":"城市园林绿化主管部门应当按照依法划定的城市绿线，组织城市公园管理单位设立与环境协调一致的绿线界桩和绿线公示牌，公布城市公园的位置、面积、四至边界、管理单位、监督电话等内容。"},{"i":19,"n":"第十九条","txt":"城市园林绿化主管部门应当指导、监督城市公园管理单位按照相关技术标准要求，做好城市公园植物养护管理。 任何单位和个人不得损坏城市公园内的植物或者擅自砍伐树木。确需砍伐城市公园内树木的，必须经城市园林绿化主管部门批准，并按照国家有关规定补植树木或者采取其他补救措施。"},{"i":20,"n":"第二十条","txt":"城市园林绿化主管部门应当组织对城市公园内的古树名木进行调查、鉴定、定级、登记、编号，设置标志，划定保护范围，落实养护管理责任；按照一树一档的要求建立图文档案和电子信息数据库，定期开展古树名木健康评估，组织实施抢救复壮等保护措施。 古树名木档案应当包括树木基本信息、价值意义、地理位置、生长环境、养护记录、保护现状、照片等内容。古树名木标志应当包括树木名称、学名、科属、树龄、保护级别、编号等内容。有条件的城市公园应当设置古树名木标志的电子信息码。 城市公园古树名木档案应当逐级报上一级园林绿化主管部门。"},{"i":21,"n":"第二十一条","txt":"城市公园管理单位应当制定古树名木的日常养护和保护方案，改善古树名木生长环境，落实养护责任；发现古树名木遭受损害或者长势明显衰弱的，应当及时报告城市园林绿化主管部门。"},{"i":22,"n":"第二十二条","txt":"体现一定历史时期和地域范围内代表性造园艺术和营造技艺，且具有重要的历史、文化、艺术、生态和科学价值的城市公园，应当按照有关规定认定为历史名园。 城市园林绿化主管部门应当组织编制历史名园保护方案并组织实施。历史名园保护方案包括以下内容： （一）评估历史名园保护管理和利用现状，分析其价值、特点和保护管理利用中存在的问题； （二）确定保护原则、保护范围以及保护范围内建筑格局风貌、植物景观风貌和山形水系原有格局等重点保护对象； （三）制定历史名园整体保护和重点保护对象专项保护利用措施； （四）提出传承弘扬中国园林文化的措施； （五）提出实施保障要求。 历史名园内涉及文物、历史建筑等保护的，按照有关法律、法规规定执行。"},{"i":23,"n":"第二十三条","txt":"城市公园管理单位负责公园的日常管理，做好以下工作： （一）建立健全公园管理制度，依法制定游园守则； （二）保持园容园貌整洁，保障设备设施完好； （三）做好公园绿化养护，保持树木花草繁茂； （四）保护生物多样性，防治外来物种侵害； （五）引导游客文明游园，劝阻游客不文明行为； （六）建立健全安全生产责任制，做好隐患排查治理，提高安全管理水平； （七）制定突发事件应急预案，定期开展演练，做好应急处置； （八）法律法规规定的其他工作。"},{"i":24,"n":"第二十四条","txt":"城市园林绿化主管部门应当组织开展城市公园绿地开放共享工作，指导城市公园管理单位开放城市公园中具备条件的草坪和林下空间。 城市公园管理单位应当公布草坪和林下空间的开放时间、范围等信息，完善周边环境卫生、安全监控等配套设施，并根据游客规模、植物特性和气候条件等因素对开放草坪实行轮换养护管理。"},{"i":25,"n":"第二十五条","txt":"城市公园管理单位应当结合公园实际情况，完善休憩、文化、科普、阅读、健身等配套服务设施，应用电子显示屏等设施开展宣传教育，提升城市公园服务功能。"},{"i":26,"n":"第二十六条","txt":"城市园林绿化主管部门应当规范城市公园配套服务项目经营活动，并加强监督管理。 城市公园管理单位应当按照有关规定组织开展配套服务项目经营活动，提供便民服务。城市公园内新设经营性配套服务设施的，应当符合已批准的城市公园建设项目设计方案及有关技术标准要求。 严禁在城市公园中以自建、租赁、承包、转让、出借、抵押、买断、合资、合作等形式设立私人会所。"},{"i":27,"n":"第二十七条","txt":"城市公园应当每天开放。因特殊情况需要临时关闭的，城市园林绿化主管部门、城市公园管理单位应当利用互联网、广播电视、城市公园告示牌等方式多渠道提前发布闭园信息。 实行封闭式管理的城市公园，城市公园管理单位应当将开园、闭园时间向社会公开。"},{"i":28,"n":"第二十八条","txt":"游客应当文明游园，遵守公园管理规定，爱护园内动植物和设施，保护公园环境。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，建设单位或者城市公园管理单位擅自进行城市公园命名、更名的，依据《地名管理条例》的有关规定予以处罚。"},{"i":30,"n":"第三十条","txt":"违反本办法规定，损坏城市公园内的植物或者擅自砍伐树木的，依据《城市绿化条例》等有关规定予以处罚。"},{"i":31,"n":"第三十一条","txt":"建设、设计、施工等单位在城市公园建设项目建设活动中有违反本办法规定行为的，依据《中华人民共和国建筑法》《建设工程质量管理条例》等有关法律法规规定予以处罚。"},{"i":32,"n":"第三十二条","txt":"城市园林绿化主管部门工作人员在城市公园监督管理工作中滥用职权、玩忽职守、徇私舞弊或者有其他违法行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"本办法自2024年12月1日起施行。"}],"jiyingongchenganquanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了促进我国生物技术的研究与开发，加强基因工程工作的安全管理,保障公众和基因工程工作人员的健康，防止环境污染，维护生态平衡，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称基因工程，包括利用载体系统的重组体DNA技术,以及利用物理或者化学方法把异源DNA直接导入有机体的技术。但不包括下列遗传操作： （一）细胞融合技术，原生质体融合技术； （二）传统杂交繁殖技术； （三）诱变技术,体外受精技术，细胞培养或者胚胎培养技术。"},{"i":3,"n":"第三条","txt":"本办法适用于在中华人民共和国境内进行的一切基因工程工作，包括实验研究、中间试验、工业化生产以及遗传工程体释放和遗传工程产品使用等。 从国外进口遗传工程体，在中国境内进行基因工程工作的，应当遵守本办法。"},{"i":4,"n":"第四条","txt":"国家科学技术委员会主管全国基因工程安全工作，成立全国基因工程安全委员会，负责基因工程安全监督和协调。 国务院有关行政主管部门依照有关规定，在各自的职责范围内对基因工程工作进行安全管理。"},{"i":5,"n":"第五条","txt":"基因工程工作安全管理实行安全等级控制、分类归口审批制度。"},{"i":6,"n":"第六条","txt":"按照潜在危险程度,将基因工程工作分为四个安全等级： 安全等级Ⅰ,该类基因工程工作对人类健康和生态环境尚不存在危险； 安全等级Ⅱ,该类基因工程工作对人类健康和生态环境具有低度危险； 安全等级Ⅲ,该类基因工程工作对人类健康和生态环境具有中度危险； 安全等级Ⅳ,该类基因工程工作对人类健康和生态环境具有高度危险；"},{"i":7,"n":"第七条","txt":"各类基因工程工作的安全等级的技术标准和环境标准，由国务院有关行政主管部门制定，并报全国基因工程安全委员会备案。"},{"i":8,"n":"第八条","txt":"从事基因工程工作的单位,应当进行安全性评价,评估潜在危险,确定安全等级,制定安全控制方法和措施。"},{"i":9,"n":"第九条","txt":"从事基因工程实验研究，应当对DNA供体、载体、宿主和遗传工程体进行安全性评价。安全性评价重点是目的基因、载体、宿主和遗传工程体的致病性、致癌性、抗药性、转移性和生态环境效应，以及确定生物控制和物理控制等级。"},{"i":10,"n":"第十条","txt":"从事基因工程中间试验或者工业化生产,应当根据所用遗传工程体的安全性评价,对培养、发酵、分离和纯化工艺过程的设备和设施的物理屏障进行安全鉴定，确定中间试验或者工业化生产的安全等级。"},{"i":11,"n":"第十一条","txt":"从事遗传工程体释放，应当对遗传工程体安全性、释放目的、释放地区的生态环境、释放方式、监测方法和控制措施进行评价，确定释放工作的安全等级。"},{"i":12,"n":"第十二条","txt":"遗传工程产品的使用，应当经过生物学安全检验,进行安全性评价,确定遗传工程产品对公众健康和生态环境可能产生的影响。"},{"i":13,"n":"第十三条","txt":"从事基因工程工作的单位，应当依据遗传工程产品适用性质和安全等级,分类分级进行申报，经审批同意后方能进行。"},{"i":14,"n":"第十四条","txt":"基因工程实验研究，属于安全等级Ⅰ和Ⅱ的工作，由本单位行政负责人批准;属于安全等级Ⅲ的工作，由本单位行政负责人审查,报国务院有关行政主管部门批准;属于安全等级Ⅳ的工作，经国务院有关行政主管部门审查，报全国基因工程安全委员会批准。"},{"i":15,"n":"第十五条","txt":"基因工程中间试验，属于安全等级Ⅰ的工作，由本单位行政负责人批准;属于安全等级Ⅱ的工作，报国务院有关行政主管部门批准;属于安全等级Ⅲ的工作，由国务院有关行政主管部门审批，并报全国基因工程安全委员会备案;属于安全等级Ⅳ的工作，由国务院有关行政主管部门审查，报全国基因工程安全委员会批准。"},{"i":16,"n":"第十六条","txt":"基因工程工业化生产、遗传工程体释放和遗传工程产品使用，属于安全等级Ⅰ至Ⅲ的工作，由国务院有关行政主管部门审批,并报全国基因工程安全委员会备案；属于安全等级Ⅳ的工作，由国务院有关行政主管部门审查，报全国基因工程安全委员会批准。"},{"i":17,"n":"第十七条","txt":"从事基因工程工作的单位应当履行下列申报手续： （一）项目负责人对从事的基因工程工作进行安全性评价，并填报申请书； （二）本单位学术委员会对申报资料进行技术审查； （三）上报申请书及提交有关技术资料。"},{"i":18,"n":"第十八条","txt":"凡符合下列各项条件的基因工程工作,应当予以批准，并签发证明文件： （一）不存在对申报的基因工程工作安全性评价的可靠性产生怀疑的事实； （二）保证所申报的基因工程工作按照安全等级的要求,采取与现有科学技术水平相适应的安全控制措施，判断不会对公众健康和生态环境造成严重危害； （三）项目负责人和工作人员具备从事基因工程工作所必需的专业知识和安全操作知识，能承担本办法规定的义务； （四）符合国家有关法律、法规规定。"},{"i":19,"n":"第十九条","txt":"从事基因工程工作的单位，应当根据安全等级,确定安全控制方法,制定安全操作规则。"},{"i":20,"n":"第二十条","txt":"从事基因工程工作的单位，应当根据安全等级，制定相应治理废弃物的安全措施。排放之前应当采取措施使残留遗传工程体灭活,以防止扩散和污染环境。"},{"i":21,"n":"第二十一条","txt":"从事基因工程工作的单位，应当制定预防事故的应急措施，并将其列入安全操作规则。"},{"i":22,"n":"第二十二条","txt":"遗传工程体应当贮存在特定设备内。贮放场所的物理控制应当与安全等级相适应。 安全等级Ⅳ的遗传工程体贮放场所,应当指定专人管理。 从事基因工程工作的单位应当编制遗传工程体的贮存目录清单，以备核查。"},{"i":23,"n":"第二十三条","txt":"转移或者运输的遗传工程体应当放置在与其安全等级相适应的容器内，严格遵守国家有关运输或者邮寄生物材料的规定。"},{"i":24,"n":"第二十四条","txt":"从事基因工程工作的单位和个人必须认真做好安全监督记录。安全监督记录保存期不得少于十年，以备核查。"},{"i":25,"n":"第二十五条","txt":"因基因工程工作发生损害公众健康或者环境污染事故的单位，必须及时采取措施，控制损害的扩大，并向有关主管部门报告。"},{"i":26,"n":"第二十六条","txt":"有下列情况之一的，由有关主管部门视情节轻重分别给予警告、责令停止工作、停止资助经费、没收非法所得的处罚： （一）未经审批,擅自进行基因工程工作的； （二）使用不符合规定的装置、仪器、试验室等设施的； （三）违反基因工程工作安全操作规则的； （四）违反本办法其它规定的。"},{"i":27,"n":"第二十七条","txt":"审批机关工作人员玩忽职守、徇私舞弊的，由所在单位或者其上级主管部门对直接责任人员给予行政处分。情节严重,构成犯罪的,依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"违反本办法的规定，造成下列情况之一的,负有责任的单位必须立即停止损害行为，并负责治理污染、赔偿有关损失;情节严重,构成犯罪的,依法追究直接责任人员的刑事责任: （一）严重污染环境的； （二）损害或者影响公众健康的； （三）严重破坏生态资源、影响生态平衡的。"},{"i":29,"n":"第二十九条","txt":"审批机构的工作人员和参与审査的专家负有为申报者保守技术秘密的责任。"},{"i":30,"n":"第三十条","txt":"本办法所用术语的含义是： （一）DNA,系脱氧核糖核酸的英文名词缩写,是贮存生物遗传信息的遗传物质。 （二）基因，系控制生物性状的遗传物质的功能和结构单位，是具有遗传信息的DNA片段。 （三）目的基因，系指以修饰宿主细胞遗传组成并表达其遗传效应为目的的异源DNA片段。 （四）载体，系指具有运载异源DNA进入宿主细胞和自我复制能力的DNA分子。 （五）宿主细胞，系指被导入重组DNA分子的细胞，宿主细胞又称受体细胞。 （六）重组DNA分子，系指由异源DNA与载体DNA组成的杂种DNA分子。 （七）有机体，系指能够繁殖或者能够传递遗传物质的活细胞或者生物体。 （八）重组体，系指因自然因素或者用人工方法导入异源DNA改造其遗传组成的有机体。 （九）变异体，系指因自然或者人工因素导致其遗传物质变化的有机体。 （十）重组体DNA技术，系指利用载体系统人工修饰有机体遗传组成的技术，即在体外通过酶的作"},{"i":31,"n":"第三十一条","txt":"国务院有关行政主管部门按照本办法的规定，在各自的职责范围内制定实施细则。"},{"i":32,"n":"第三十二条","txt":"本办法由国家科学技术委员会解释。"},{"i":33,"n":"第三十三条","txt":"本办法自发布之日起施行。"}],"jibenyiliaobaoxianyongyaoguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为推进健康中国建设，保障参保人员基本用药需求，提升基本医疗保险用药科学化、精细化管理水平，提高基本医疗保险基金使用效益，推进治理体系和治理能力现代化，依据《中华人民共和国社会保险法》等法律法规和《中共中央国务院关于深化医疗保障制度改革的意见》，制定本暂行办法。"},{"i":2,"n":"第二条","txt":"各级医疗保障部门对基本医疗保险用药范围的确定、调整，以及基本医疗保险用药的支付、管理和监督等，适用本办法。"},{"i":3,"n":"第三条","txt":"基本医疗保险用药范围通过制定《基本医疗保险药品目录》（以下简称《药品目录》）进行管理，符合《药品目录》的药品费用，按照国家规定由基本医疗保险基金支付。《药品目录》实行通用名管理，《药品目录》内药品的同通用名药品自动属于基本医疗保险基金支付范围。"},{"i":4,"n":"第四条","txt":"基本医疗保险用药管理坚持以人民为中心的发展思想，切实保障参保人员合理的用药需求；坚持“保基本”的功能定位，既尽力而为，又量力而行，用药保障水平与基本医疗保险基金和参保人承受能力相适应；坚持分级管理，明确各层级职责和权限；坚持专家评审，适应临床技术进步，实现科学、规范、精细、动态管理；坚持中西药并重，充分发挥中药和西药各自优势。"},{"i":5,"n":"第五条","txt":"《药品目录》由凡例、西药、中成药、协议期内谈判药品和中药饮片五部分组成。省级医疗保障行政部门按国家规定增补的药品单列。为维护临床用药安全和提高基本医疗保险基金使用效益，《药品目录》对部分药品的医保支付条件进行限定。"},{"i":6,"n":"第六条","txt":"国务院医疗保障行政部门负责建立基本医疗保险用药管理体系，制定和调整全国范围内基本医疗保险用药范围，使用和支付的原则、条件、标准及程序等，组织制定、调整和发布国家《药品目录》并编制统一的医保代码，对全国基本医疗保险用药工作进行管理和监督。国家医疗保障经办机构受国务院医疗保障行政部门委托承担国家《药品目录》调整的具体组织实施工作。 省级医疗保障行政部门负责本行政区域内的基本医疗保险用药管理,制定本地区基本医疗保险用药管理政策措施，负责《药品目录》的监督实施等工作。各省（自治区、直辖市）以国家《药品目录》为基础，按照国家规定的调整权限和程序将符合条件的民族药、医疗机构制剂、中药饮片纳入省级医保支付范围，按规定向国务院医疗保障行政部门备案后实施。 统筹地区医疗保障部门负责《药品目录》及相关政策的实施，按照医保协议对定点医药机构医保用药行为进行审核、监督和管理，按规定及时结算和支付医保费用，并承"},{"i":7,"n":"第七条","txt":"纳入国家《药品目录》的药品应当是经国家药品监管部门批准，取得药品注册证书的化学药、生物制品、中成药（民族药），以及按国家标准炮制的中药饮片，并符合临床必需、安全有效、价格合理等基本条件。支持符合条件的基本药物按规定纳入《药品目录》。"},{"i":8,"n":"第八条","txt":"以下药品不纳入《药品目录》： （一）主要起滋补作用的药品； （二）含国家珍贵、濒危野生动植物药材的药品； （三）保健药品； （四）预防性疫苗和避孕药品； （五）主要起增强性功能、治疗脱发、减肥、美容、戒烟、戒酒等作用的药品； （六）因被纳入诊疗项目等原因，无法单独收费的药品； （七）酒制剂、茶制剂，各类果味制剂（特别情况下的儿童用药除外），口腔含服剂和口服泡腾剂（特别规定情形的除外）等； （八）其他不符合基本医疗保险用药规定的药品。"},{"i":9,"n":"第九条","txt":"《药品目录》内的药品，有下列情况之一的，经专家评审后，直接调出《药品目录》： （一）被药品监管部门撤销、吊销或者注销药品批准证明文件的药品； （二）被有关部门列入负面清单的药品； （三）综合考虑临床价值、不良反应、药物经济性等因素，经评估认为风险大于收益的药品； （四）通过弄虚作假等违规手段进入《药品目录》的药品； （五）国家规定的应当直接调出的其他情形。"},{"i":10,"n":"第十条","txt":"《药品目录》内的药品，符合以下情况之一的，经专家评审等规定程序后，可以调出《药品目录》： （一）在同治疗领域中，价格或费用明显偏高且没有合理理由的药品； （二）临床价值不确切，可以被更好替代的药品； （三）其他不符合安全性、有效性、经济性等条件的药品。"},{"i":11,"n":"第十一条","txt":"国务院医疗保障行政部门建立完善动态调整机制，原则上每年调整一次。 国务院医疗保障行政部门根据医保药品保障需求、基本医疗保险基金的收支情况、承受能力、目录管理重点等因素，确定当年《药品目录》调整的范围和具体条件，研究制定调整工作方案，依法征求相关部门和有关方面的意见并向社会公布。对企业申报且符合当年《药品目录》调整条件的药品纳入该年度调整范围。"},{"i":12,"n":"第十二条","txt":"建立《药品目录》准入与医保药品支付标准（以下简称支付标准）衔接机制。除中药饮片外，原则上新纳入《药品目录》的药品同步确定支付标准。 独家药品通过准入谈判的方式确定支付标准。 非独家药品中，国家组织药品集中采购（以下简称集中采购）中选药品，按照集中采购有关规定确定支付标准；其他非独家药品根据准入竞价等方式确定支付标准。 执行政府定价的麻醉药品和第一类精神药品，支付标准按照政府定价确定。"},{"i":13,"n":"第十三条","txt":"中药饮片采用专家评审方式进行调整，其他药品的调整程序主要包括企业申报、专家评审、谈判或准入竞价、公布结果。"},{"i":14,"n":"第十四条","txt":"建立企业（药品上市许可持有人，以下统称企业）申报制度。根据当年调整的范围，符合条件的企业按规定向国家医疗保障经办机构提交必要的资料。提交资料的具体要求和办法另行制定。"},{"i":15,"n":"第十五条","txt":"国家医疗保障经办机构按规定组织医学、药学、药物经济学、医保管理等方面专家，对符合当年《药品目录》调整条件的全部药品进行评审，并提出如下药品名单： （一）建议新增纳入《药品目录》的药品。经专家评审后，符合条件的国家组织集中采购中选药品或政府定价药品，可直接纳入《药品目录》；其他药品按规定提交药物经济学等资料。 （二）原《药品目录》内建议直接调出的药品。该类药品直接从《药品目录》中调出。 （三）原《药品目录》内建议可以调出的药品。该类药品按规定提交药物经济学等资料。 （四）原《药品目录》内药品建议调整限定支付范围的。其中缩小限定支付范围或者扩大限定支付范围但对基本医疗保险基金影响较小的，可以直接调整；扩大限定支付范围且对基本医疗保险基金影响较大的，按规定提交药物经济学等资料。"},{"i":16,"n":"第十六条","txt":"国家医疗保障经办机构按规定组织药物经济学、医保管理等方面专家开展谈判或准入竞价。其中独家药品进入谈判环节，非独家药品进入企业准入竞价环节。谈判或者准入竞价成功的，纳入《药品目录》或调整限定支付范围；谈判或者准入竞价不成功的，不纳入或调出《药品目录》，或者不予调整限定支付范围。"},{"i":17,"n":"第十七条","txt":"国务院医疗保障行政部门负责确定并印发《药品目录》，公布调整结果。"},{"i":18,"n":"第十八条","txt":"原则上谈判药品协议有效期为两年。协议期内，如有谈判药品的同通用名药物（仿制药）上市，医保部门可根据仿制药价格水平调整该药品的支付标准，也可以将该通用名纳入集中采购范围。协议期满后，如谈判药品仍为独家，周边国家及地区的价格等市场环境未发生重大变化且未调整限定支付范围或虽然调整了限定支付范围但对基本医疗保险基金影响较小的，根据协议期内基本医疗保险基金实际支出（以医保部门统计为准）与谈判前企业提交的预算影响分析进行对比，按相关规则调整支付标准，并续签协议。具体规则另行制定。"},{"i":19,"n":"第十九条","txt":"对于因更名、异名等原因需要对药品的目录归属进行认定的，由国务院医疗保障行政部门按程序进行认定后发布。"},{"i":20,"n":"第二十条","txt":"国务院医疗保障行政部门负责编制国家医保药品代码，按照医保药品分类和代码规则建立药品编码数据库。原则上每季度更新一次。"},{"i":21,"n":"第二十一条","txt":"协议期内谈判药品原则上按照支付标准直接挂网采购。协议期内，谈判药品的同通用名药品在价格不高于谈判支付标准的情况下，按规定挂网采购。其他药品按照药品招采有关政策执行。"},{"i":22,"n":"第二十二条","txt":"在满足临床需要的前提下，医保定点医疗机构须优先配备和使用《药品目录》内药品。逐步建立《药品目录》与定点医疗机构药品配备联动机制，定点医疗机构根据《药品目录》调整结果及时对本医疗机构用药目录进行调整和优化。"},{"i":23,"n":"第二十三条","txt":"参保人使用《药品目录》内药品发生的费用，符合以下条件的，可由基本医疗保险基金支付： （一）以疾病诊断或治疗为目的； （二）诊断、治疗与病情相符，符合药品法定适应症及医保限定支付范围； （三）由符合规定的定点医药机构提供，急救、抢救的除外； （四）由统筹基金支付的药品费用，应当凭医生处方或住院医嘱； （五）按规定程序经过药师或执业药师的审查。"},{"i":24,"n":"第二十四条","txt":"国家《药品目录》中的西药和中成药分为“甲类药品”和“乙类药品”。“甲类药品”是临床治疗必需、使用广泛、疗效确切、同类药品中价格或治疗费用较低的药品。“乙类药品”是可供临床治疗选择使用，疗效确切、同类药品中比“甲类药品”价格或治疗费用略高的药品。协议期内谈判药品纳入“乙类药品”管理。 各省级医疗保障部门按国家规定纳入《药品目录》的民族药、医疗机构制剂纳入“乙类药品”管理。 中药饮片的“甲乙分类”由省级医疗保障行政部门确定。"},{"i":25,"n":"第二十五条","txt":"参保人使用“甲类药品”按基本医疗保险规定的支付标准及分担办法支付；使用“乙类药品”按基本医疗保险规定的支付标准，先由参保人自付一定比例后，再按基本医疗保险规定的分担办法支付。 “乙类药品”个人先行自付的比例由省级或统筹地区医疗保障行政部门确定。"},{"i":26,"n":"第二十六条","txt":"支付标准是基本医疗保险参保人员使用《药品目录》内药品时，基本医疗保险基金支付药品费用的基准。基本医疗保险基金依据药品的支付标准以及医保支付规定向定点医疗机构和定点零售药店支付药品费用。支付标准的制定和调整规则另行制定。"},{"i":27,"n":"第二十七条","txt":"综合运用协议、行政、司法等手段，加强《药品目录》及用药政策落实情况的监管，提升医保用药安全性、有效性、经济性。"},{"i":28,"n":"第二十八条","txt":"定点医药机构应健全组织机构，完善内部制度规范，建立健全药品“进、销、存”全流程记录和管理制度，提高医保用药管理能力，确保医保用药安全合理。"},{"i":29,"n":"第二十九条","txt":"将《药品目录》和相关政策落实责任纳入定点医药机构协议内容，强化用药合理性和费用审核，定期开展监督检查。将医保药品备药率、非医保药品使用率等与定点医疗机构的基金支付挂钩。加强定点医药机构落实医保用药管理政策，履行药品配备、使用、支付、管理等方面职责的监督检查。"},{"i":30,"n":"第三十条","txt":"建立目录内药品企业监督机制，引导企业遵守相关规定。将企业在药品推广使用、协议遵守、信息报送等方面的行为与《药品目录》管理挂钩。"},{"i":31,"n":"第三十一条","txt":"基本医疗保险用药管理工作主动接受纪检监察部门和社会各界监督。加强专家管理，完善专家产生、利益回避、责任追究等机制。加强内控制度建设，完善投诉举报处理、利益回避、保密等内部管理制度，落实合法性和公平竞争审查制度。"},{"i":32,"n":"第三十二条","txt":"对于调入或调出《药品目录》的药品，专家应当提交评审结论和报告。逐步建立评审报告公开机制，接受社会监督。"},{"i":33,"n":"第三十三条","txt":"凡例是对《药品目录》的编排格式、名称剂型规范、备注等内容的解释和说明。 西药部分，收载化学药品和生物制品。 中成药部分，收载中成药和民族药。 协议期内谈判药品部分，收载谈判协议有效期内的药品。 中药饮片部分，收载基本医疗保险基金予以支付的饮片，并规定不得纳入基本医疗保险基金支付的饮片。"},{"i":34,"n":"第三十四条","txt":"各省（自治区、直辖市）医疗保障部门要参照本暂行办法，在国家规定的权限内，制定本省（自治区、直辖市）调整《药品目录》的具体办法。"},{"i":35,"n":"第三十五条","txt":"发生严重危害群众健康的公共卫生事件或紧急情况时，国务院医疗保障行政部门可临时调整或授权省级医疗保障行政部门临时调整医保药品支付范围。"},{"i":36,"n":"第三十六条","txt":"原则上《药品目录》不再新增OTC药品。"},{"i":37,"n":"第三十七条","txt":"本办法由国务院医疗保障行政部门负责解释，自2020年9月1日起施行。"}],"jingwailieshijiniansheshibaohuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了传承和弘扬烈士精神，加强境外烈士纪念设施保护管理，彰显我国良好国家形象，根据《中华人民共和国英雄烈士保护法》、《烈士褒扬条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称境外烈士纪念设施，是指在中华人民共和国境外为纪念中国烈士修建的烈士陵园、纪念堂馆、纪念碑亭、纪念塔祠、纪念塑像、烈士骨灰堂、烈士墓等设施。"},{"i":3,"n":"第三条","txt":"境外烈士纪念设施保护管理领导小组统筹协调境外烈士纪念设施保护管理工作。 境外烈士纪念设施保护管理领导小组由退役军人事务部会同外交部、财政部、中央军委政治工作部等部门组成。退役军人事务部负责领导小组日常事务，驻外使领馆协助处理有关具体工作。"},{"i":4,"n":"第四条","txt":"境外烈士纪念设施保护管理应当尊重历史、结合现实，根据纪念设施现状、所在国情况以及双边关系，经与所在国政府有关部门协商，通过签署双边合作协议等方式，明确保护管理具体事项。"},{"i":5,"n":"第五条","txt":"境外烈士纪念设施保护管理工作包括下列事项： （一）调查核实烈士纪念设施，查找、收集烈士遗骸、遗物； （二）修缮保护、新建迁建烈士纪念设施； （三）负责烈士纪念设施日常维护管理； （四）搜集、整理、编纂、陈列、展示、保管烈士事迹和遗物史料； （五）组织开展烈士祭扫和宣传纪念活动； （六）其他相关事项。"},{"i":6,"n":"第六条","txt":"境外烈士纪念设施保护管理工作所需经费，由中央财政安排，列入部门预算。"},{"i":7,"n":"第七条","txt":"境外烈士纪念设施保护管理领导小组应当掌握境外烈士纪念设施基本情况并建立档案。 退役军人事务部、烈士生前所在工作单位或其主管部门应当根据历史线索和资料，调查核实境外烈士纪念设施，搜寻查找烈士遗骸，驻外使领馆提供协助。"},{"i":8,"n":"第八条","txt":"境外烈士纪念设施一般就地修缮保护。对于散落在境外的烈士墓，可以依托当地现有境外烈士纪念设施集中保护管理。"},{"i":9,"n":"第九条","txt":"具有重大历史意义、确需新建境外烈士纪念设施的，以及因修缮保护需要或者因所在国建设规划等原因确需迁建境外烈士纪念设施的，应当按照有关规定经批准后实施。"},{"i":10,"n":"第十条","txt":"境外烈士纪念设施保护管理领导小组应当与所在国政府有关部门协商划定境外烈士纪念设施保护范围，明确不得侵占保护范围内的土地和设施，不得单方面拆除、变更、迁移纪念设施，在保护范围内不得从事与纪念烈士无关的活动。"},{"i":11,"n":"第十一条","txt":"境外烈士纪念设施保护管理领导小组与所在国政府有关部门协商确定境外烈士纪念设施管理方式，驻外使领馆可以根据纪念设施现状、所在国情况提出建议。 确定由所在国政府负责管理的，境外烈士纪念设施保护管理领导小组应当协调所在国政府有关部门指定专门机构进行管理。 确定由我国政府负责管理的，由境外烈士纪念设施保护管理领导小组或授权驻外使领馆通过签署委托协议的方式，委托中资企业（机构）、所在国华侨华人友好社团等进行管理，也可以委托所在国华侨华人进行管理。"},{"i":12,"n":"第十二条","txt":"各有关部门和单位应当开展烈士史料收集整理、事迹编纂和陈列展示工作，宣传烈士英雄事迹，褒扬英烈风范，加深我国同所在国的友谊。 烈士史料等属于文物的，依照有关法律法规的规定予以保护。"},{"i":13,"n":"第十三条","txt":"在烈士纪念日、清明节或者其他重要纪念日期间，驻外使领馆应当结合所在国情况组织烈士公祭活动。 烈士公祭活动可以根据实际情况邀请所在国政府、中资企业（机构）、华侨华人和社会各界代表参加。"},{"i":14,"n":"第十四条","txt":"驻外使领馆可以结合实际，为赴所在国祭扫的烈士家属提供协助，引导赴所在国参观访问的我国代表团、旅游者及旅居所在国我国侨民、留学生前往境外烈士纪念设施瞻仰祭扫。 烈士纪念活动应当庄严、肃穆，符合我国祭扫习惯和境外烈士纪念设施所在国习俗。"},{"i":15,"n":"第十五条","txt":"驻外使领馆应当敦促境外烈士纪念设施管理机构或者人员对在境外烈士纪念设施举行的各项祭扫纪念活动进行登记。"},{"i":16,"n":"第十六条","txt":"驻外使领馆应当敦促境外烈士纪念设施管理机构或者人员做好纪念设施保护范围内的设施维护、安全保卫、绿化美化、环境卫生等工作。"},{"i":17,"n":"第十七条","txt":"侵占境外烈士纪念设施保护范围内土地、设施，破坏、污损境外烈士纪念设施，在保护范围内从事与纪念活动无关的活动的，驻外使领馆应当敦促境外烈士纪念设施管理机构或者人员及时制止。情节严重、造成损害后果的，驻外使领馆应当通过外交途径向所在国政府提出交涉，敦促其严肃处理；涉及已返回境内中国公民的，驻外使领馆应当敦促所在国相关部门将相关材料移交境外烈士纪念设施保护管理领导小组，由有关部门依法处理。"},{"i":18,"n":"第十八条","txt":"我国在境外的其他因公牺牲人员纪念设施保护管理工作，参照本办法执行。"},{"i":19,"n":"第十九条","txt":"香港特别行政区、澳门特别行政区和台湾地区烈士纪念设施的保护管理，参照国家有关规定执行。"},{"i":20,"n":"第二十条","txt":"本办法自2020年4月1日起施行。"}],"chufangyaoyufeichufangyaofenleiguanlibanfa":[{"i":1,"n":"第一条","txt":"为保障人民用药安全有效、使用方便，根据《中共中央、国务院关于卫生改革与发展的决定》，制定处方药与非处方药分类管理办法。"},{"i":2,"n":"第二条","txt":"根据药品品种、规格、适应症、剂量及给药途径不同，对药品分别按处方药与非处方药进行管理。 处方药必须凭执业医师或执业助理医师处方才可调配、购买和使用；非处方药不需要凭执业医师或执业助理医师处方即可自行判断、购买和使用。"},{"i":3,"n":"第三条","txt":"国家药品监督管理局负责处方药与非处方药分类管理办法的制定。各级药品监督管理部门负责辖区内处方药与非处方药分类管理的组织实施和监督管理。"},{"i":4,"n":"第四条","txt":"国家药品监督管理局负责非处方药目录的遴选、审批、发布和调整工作。"},{"i":5,"n":"第五条","txt":"处方药、非处方药生产企业必须具有《药品生产企业许可证》，其生产品种必须取得药品批准文号。"},{"i":6,"n":"第六条","txt":"非处方药标签和说明书除符合规定外，用语应当科学、易懂，便于消费者自行判断、选择和使用。非处方药的标签和说明书必须经国家药品监督管理局批准。"},{"i":7,"n":"第七条","txt":"非处方药的包装必须印有国家指定的非处方药专有标识，必须符合质量要求，方便储存、运输和使用。每个销售基本单元包装必须附有标签和说明书。"},{"i":8,"n":"第八条","txt":"根据药品的安全性，非处方药分为甲、乙两类。 经营处方药、非处方药的批发企业和经营处方药、甲类非处方药的零售企业必须具有《药品经营企业许可证》。 经省级药品监督管理部门或其授权的药品监督管理部门批准的其它商业企业可以零售乙类非处方药。"},{"i":9,"n":"第九条","txt":"零售乙类非处方药的商业企业必须配备专职的具有高中以上文化程度，经专业培训后，由省级药品监督管理部门或其授权的药品监督管理部门考核合格并取得上岗证的人员。"},{"i":10,"n":"第十条","txt":"医疗机构根据医疗需要可以决定或推荐使用非处方药。"},{"i":11,"n":"第十一条","txt":"消费者有权自主选购非处方药，并须按非处方药标签和说明书所示内容使用。"},{"i":12,"n":"第十二条","txt":"处方药只准在专业性医药报刊进行广告宣传，非处方药经审批可以在大众传播媒介进行广告宣传。"},{"i":13,"n":"第十三条","txt":"处方药与非处方药分类管理有关审批、流通、广告等具体办法另行制定。"},{"i":14,"n":"第十四条","txt":"本办法由国家药品监督管理局负责解释。"},{"i":15,"n":"第十五条","txt":"本办法自２０００年１月１日起施行。"}],"waishangtouzidianyingyuanzanxingguiding":[{"i":1,"n":"第二条","txt":"本规定适用于外国的公司、企业和其它经济组织或个人（以下简称合营外方）按照平等互利的原则，经中国政府批准，同中国境内的公司、企业（以下简称合营中方）设立中外合资、合作企业，新建、改造电影院，从事电影放映业务。"},{"i":2,"n":"第三条","txt":"外商不得设立独资电影院，不得组建电影院线公司。"},{"i":3,"n":"第四条","txt":"外商投资电影院应当符合以下条件： （一）符合当地文化设施的布局与规划； （二）有固定的营业（放映）场所； （三）中外合资电影院，合营中方在注册资本中的投资比例不得低于51%；对全国试点城市：北京、上海、广州、成都、西安、武汉、南京市中外合资电影院，合营外方在注册资本中的投资比例最高不得超过75%； （四）合资、合作期限不超过30年； （五）符合中国有关法律、法规及有关规定。"},{"i":4,"n":"第五条","txt":"合营中方若以国有资产（现金投资除外）参与投资，应按国有资产管理的有关规定履行相关手续。"},{"i":5,"n":"第六条","txt":"设立外商投资电影院依下列程序报批： （一）合营中方须向所在地省级商务行政部门提出申请，提交以下材料： 1．设立外商投资电影院项目申请书； 2．合营中方的法人资格证明材料、影院土地使用权的有关材料； 3．合营外方的资格证明材料； 4．工商行政部门出具的外商投资电影院名称预核准通知书； 5．可行性研究报告、合同、章程； 6．法律、法规和审批机构要求提供的其它材料。 （二）所在地省级商务行政部门在征得省级电影行政部门同意后，依照国家有关外商投资的法律、法规进行审批，报商务部、国家广播电影电视总局、文化部备案。对批准设立的外商投资企业颁发《外商投资企业批准证书》。 （三）获批准设立的外商投资电影院，应自收到《外商投资企业批准证书》之日起一个月内，持《外商投资企业批准证书》到省级工商行政部门办理注册登记手续。 （四）外商投资电影院完成建设、改造任务后，经有关部门验收合格，持《外商投资企业批准证书"},{"i":6,"n":"第七条","txt":"已设立的外商投资电影院变更股权及投资额时，应按本规定第六条的程序办理。"},{"i":7,"n":"第八条","txt":"外商投资电影院必须遵守国家有关法律、法规，依照《电影管理条例》从事经营活动，接受中国政府有关部门的监督和管理，放映的影片必须持有国家广播电影电视总局颁发的《电影片公映许可证》，不准放映走私、盗版电影，不得从事营业性的录像、VCD、DVD的放映。"},{"i":8,"n":"第九条","txt":"外商投资电影院附属从事其它娱乐服务业务要符合国家有关规定。"},{"i":9,"n":"第十条","txt":"香港特别行政区、澳门特别行政区和台湾地区的投资者在内地设立从事电影放映业务的企业参照本规定办理。"},{"i":10,"n":"第十一条","txt":"本规定及其附件自2004年1月1日起施行。本规定及附件施行之日，2000年10月25日国家广播电影电视总局、对外贸易经济合作部和文化部发布的《外商投资电影院暂行规定》同时废止。 附件： 为了促进香港、澳门与内地建立更紧密经贸关系，鼓励香港、澳门服务提供者在内地设立从事电影放映业务的企业，根据国务院批准的《内地与香港关于建立更紧密经贸关系的安排》和《内地与澳门关于建立更紧密经贸关系的安排》，现对《外商投资电影院暂行规定》中有关香港和澳门服务提供者投资电影院问题作出如下特别规定： 一、自2004年1月1日起，允许香港、澳门服务提供者在内地以合资、合作的形式建设、改造及经营电影院。允许香港、澳门服务提供者拥有多数股权，但不得超过75%。 二、香港、澳门服务提供者在内地投资电影院的其它规定，仍按《外商投资电影院暂行规定》执行。 《外商投资电影院暂行规定》的补充规定 （2005年4月8日国家广播"}],"waiguojigouzaizhongguojingneitigongjinrongxinxifuw845771":[{"i":1,"n":"第一条","txt":"为便于外国机构在中国境内依法提供金融信息服务，满足国内用户对金融信息的需求，促进金融信息服务业健康、有序发展，根据《国务院关于修改〈国务院对确需保留的行政审批项目设定行政许可的决定〉的决定》（国务院第548号令），制定本规定。"},{"i":2,"n":"第二条","txt":"外国机构在中国境内提供金融信息服务，适用本规定。 本规定所称外国机构，是指外国金融信息服务提供者。 本规定所称金融信息服务，是指向从事金融分析、金融交易、金融决策或者其他金融活动的用户提供可能影响金融市场的信息和／或者金融数据的服务。该服务不同于通讯社服务。"},{"i":3,"n":"第三条","txt":"中国依法保障外国机构在中国境内提供金融信息服务的合法权益，为其依法提供金融信息服务提供便利。 外国机构在中国境内提供金融信息服务，应当遵守中国法律、法规和规章。"},{"i":4,"n":"第四条","txt":"国务院新闻办公室为外国机构在中国境内提供金融信息服务的监督管理机关。外国机构在中国境内提供金融信息服务，必须经国务院新闻办公室批准。 未经国务院新闻办公室批准的外国机构，不得在中国境内提供金融信息服务。"},{"i":5,"n":"第五条","txt":"外国机构申请在中国境内提供金融信息服务，应当具备以下条件： （一）在所在国家（地区）有相应的合法资质； （二）在金融信息服务领域有良好信誉； （三）有确定的金融信息服务业务； （四）有良好的传播手段和技术服务； （五）中国法律、法规规定的其他条件。"},{"i":6,"n":"第六条","txt":"外国机构在中国境内提供金融信息服务，需向国务院新闻办公室申请，提交下列材料： （一）该机构主要负责人签署的书面申请； （二）该机构情况介绍； （三）该机构在所在国家（地区）设立的证明文本副本； （四）拟提供金融信息服务的产品、栏目、说明、信息来源和样品的概述； （五）传播手段及技术服务说明材料。"},{"i":7,"n":"第七条","txt":"国务院新闻办公室应当自受理申请之日起20个工作日内作出批准或者不批准决定。予以批准的，发给批准文件；不予批准的，书面通知申请人并说明理由。"},{"i":8,"n":"第八条","txt":"外国机构在中国境内提供金融信息服务，应当与用户签订书面合同。 外国机构应当在首次收到本规定第七条所述批准文件后30日内，就获得批准文件前与国内用户签订的任何合同，向国务院新闻办公室备案。获得批准的外国机构与国内用户签订、终止任何合同，应当在该合同签订、终止后30日内，向国务院新闻办公室备案。备案内容包括：合同所涉信息产品、提供方式、用户相关身份信息、合同期限等。已备案内容发生变更的，外国机构应当在变更后30日内向国务院新闻办公室变更备案。"},{"i":9,"n":"第九条","txt":"外国机构在中国境内提供金融信息服务，拟变更机构名称、产品种类或者传播手段的，应当至少提前30日向国务院新闻办公室办理变更手续。"},{"i":10,"n":"第十条","txt":"外国机构拟终止在中国境内提供金融信息服务的，应当在终止业务前书面告知国务院新闻办公室，并自终止业务之日起7日内到国务院新闻办公室办理注销手续。"},{"i":11,"n":"第十一条","txt":"外国机构在中国境内提供金融信息服务批准文件有效期为2年。批准文件到期并拟继续提供服务的，应当在批准文件到期前至少30日，持原批准文件和本规定第六条所述材料向国务院新闻办公室申请更新批准文件。国务院新闻办公室将依照本规定第七条的规定办理。"},{"i":12,"n":"第十二条","txt":"国务院新闻办公室依法保护外国机构依照本规定提交材料中包含的具有商业价值的信息，上述信息将仅用于监管。"},{"i":13,"n":"第十三条","txt":"外国机构在中国境内投资设立金融信息服务企业，应当依照中国有关法律向国务院商务主管部门提出申请，并提交下列材料： （一）国务院新闻办公室的批准文件； （二）该机构主要负责人签署的在中国境内投资设立金融信息服务企业的书面申请； （三）由各方投资者法定代表人或者其授权的代表签署的金融信息服务企业的合同、章程； （四）拟投资设立金融信息服务企业的董事会成员名单及证明文件； （五）工商行政管理部门出具的企业名称预先核准通知书； （六）中国法律、法规规定的其他文件。"},{"i":14,"n":"第十四条","txt":"国务院商务主管部门应当自受理申请之日起30个工作日内作出批准或者不批准决定。予以批准的，发给《外商投资企业批准证书》；不予批准的，书面通知申请人并说明理由。"},{"i":15,"n":"第十五条","txt":"获得批准投资设立金融信息服务企业的外国机构应当自收到《外商投资企业批准证书》之日起30日内，依法向工商行政管理部门申请设立登记。 外商投资的金融信息服务企业变更登记事项或者终止的，应当依法办理变更登记或者注销登记。"},{"i":16,"n":"第十六条","txt":"外国机构应当严格按照批准的经营范围提供金融信息服务。国务院新闻办公室对外国机构提供金融信息服务进行监督检查，外国机构应当予以配合。"},{"i":17,"n":"第十七条","txt":"外国机构在中国境内向用户提供的金融信息，不得含有下列内容： （一）违反中华人民共和国宪法基本原则的； （二）破坏中国国家统一、主权和领土完整的； （三）危害中国国家安全和损害国家利益的； （四）违反中国的民族、宗教政策，破坏民族团结，宣扬邪教的； （五）散布虚假金融信息，扰乱经济秩序，破坏经济、金融、资本市场和社会稳定的； （六）宣扬淫秽、色情、暴力、恐怖或者教唆犯罪的； （七）侮辱或者诽谤他人，侵害他人合法权益的； （八）中国法律、法规和规章禁止的其他内容。"},{"i":18,"n":"第十八条","txt":"国务院新闻办公室对外国机构在中国境内提供的金融信息进行同步审视，发现含有本规定第十七条所列内容的，予以调查、处理。外国机构应当向国务院新闻办公室无偿提供同步审视其所提供金融信息的必要条件。"},{"i":19,"n":"第十九条","txt":"在中国境内设立的外商投资金融信息服务企业应当严格按照登记注册的经营范围从事业务活动，不得开展新闻采集业务，不得从事通讯社业务。"},{"i":20,"n":"第二十条","txt":"国内金融信息用户发现外国机构提供的金融信息中含有本规定第十七条所列内容的，应当向国务院新闻办公室举报，并不得使用和传播。"},{"i":21,"n":"第二十一条","txt":"外国机构在中国境内提供金融信息服务违反本规定的，由国务院新闻办公室和有关部门责令改正，给予警告，并处罚款。违反其他法律法规的，由相关行政、司法机关依法处理。"},{"i":22,"n":"第二十二条","txt":"国内金融信息用户向社会传播外国机构提供的金融信息中含有本规定第十七条所列内容的，由国务院新闻办公室和有关部门依法处罚。"},{"i":23,"n":"第二十三条","txt":"国务院新闻办公室工作人员，因玩忽职守、滥用职权、徇私舞弊或者收受贿赂，造成严重后果并构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":24,"n":"第二十四条","txt":"香港特别行政区、澳门特别行政区、台湾地区有关机构，在内地提供金融信息服务，参照适用本规定。"},{"i":25,"n":"第二十五条","txt":"本规定自2009年6月1日起施行。本规定发布前，有关部门发布的关于金融信息服务的规定与本规定不一致的，以本规定为准。 本规定施行前已获得批准在中国境内提供金融信息服务的外国机构，拟继续在中国境内提供金融信息服务的，应当在本规定施行之日起30日内持本规定第六条所述材料向国务院新闻办公室提出申请。在国务院新闻办公室根据本规定第七条做出决定之日前，允许其继续提供该服务。"}],"anquanshengchanjiandufakuanguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为加强安全生产监督罚款管理工作，依法实施安全生产综合监督管理，根据《安全生产法》、《罚款决定与罚款收缴分离实施办法》和《财政部关于做好安全生产监督有关罚款收入管理工作的通知》等法律、法规和有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府安全生产监督管理部门（以下简称安全生产监督管理部门）对生产经营单位及其有关人员在生产经营活动中违反安全生产的法律、行政法规、部门规章、国家标准、行业标准和规程的违法行为（以下简称安全生产违法行为）依法实施罚款，适用本办法。"},{"i":3,"n":"第三条","txt":"安全生产监督罚款实行处罚决定与罚款收缴分离。 安全生产监督管理部门按照有关规定，对安全生产违法行为实施罚款，开具安全生产监督管理行政处罚决定书；被处罚人持安全生产监督管理部门开具的行政处罚决定书到指定的代收银行及其分支机构缴纳罚款。 罚款代收银行的确定以及会计科目的使用应严格按照财政部《罚款代收代缴管理办法》和其他有关规定办理。代收银行的代收手续费按照《财政部、中国人民银行关于代收罚款手续费有关问题的通知》的规定执行。"},{"i":4,"n":"第四条","txt":"罚款票据使用省、自治区、直辖市财政部门统一印制的罚款收据，并由代收银行负责管理。 安全生产监督管理部门可领取小额罚款票据，并负责管理。罚没款票据的使用，应当符合罚款票据管理暂行规定。 尚未实行银行代收的罚款，由县级以上安全生产监督管理部门统一向同级财政部门购领罚款票据，并负责本单位罚款票据的管理。"},{"i":5,"n":"第五条","txt":"安全生产监督罚款收入纳入同级财政预算，实行“收支两条线”管理。 罚款缴库时间按照当地财政部门有关规定办理。"},{"i":6,"n":"第六条","txt":"安全生产监督管理部门定期到代收银行索取缴款票据，据以登记统计，并和安全生产监督管理行政处罚决定书核对。 各地安全生产监督管理部门应于每季度终了后7日内将罚款统计表（格式附后〔略〕）逐级上报。各省级安全生产监督管理部门应于每半年（年）终了后15日内将罚款统计表报国家安全生产监督管理局。"},{"i":7,"n":"第七条","txt":"安全生产监督管理部门罚款收入的缴库情况，应接受同级财政部门的检查和监督。"},{"i":8,"n":"第八条","txt":"安全生产监督罚款应严格执行国家有关罚款收支管理的规定，对违反“收支两条线”管理的机构和个人，依照《违反行政事业性收费和罚没收入收支两条线管理规定行政处分暂行规定》追究责任。"},{"i":9,"n":"第九条","txt":"本办法自公布之日起施行。"}],"anquanshengchanlingyuweifaweijixingweizhengjichufe2c107b":[{"i":1,"n":"第一条","txt":"为了加强安全生产工作，惩处安全生产领域违法违纪行为，促进安全生产法律法规的贯彻实施，保障人民群众生命财产和公共财产安全，根据《中华人民共和国行政监察法》、《中华人民共和国安全生产法》及其他有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"国家行政机关及其公务员，企业、事业单位中由国家行政机关任命的人员有安全生产领域违法违纪行为，应当给予处分的，适用本规定。"},{"i":3,"n":"第三条","txt":"有安全生产领域违法违纪行为的国家行政机关，对其直接负责的主管人员和其他直接责任人员，以及对有安全生产领域违法违纪行为的国家行政机关公务员（以下统称有关责任人员），由监察机关或者任免机关按照管理权限，依法给予处分。 有安全生产领域违法违纪行为的企业、事业单位，对其直接负责的主管人员和其他直接责任人员，以及对有安全生产领域违法违纪行为的企业、事业单位工作人员中由国家行政机关任命的人员（以下统称有关责任人员），由监察机关或者任免机关按照管理权限，依法给予处分。"},{"i":4,"n":"第四条","txt":"国家行政机关及其公务员有下列行为之一的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）不执行国家安全生产方针政策和安全生产法律、法规、规章以及上级机关、主管部门有关安全生产的决定、命令、指示的； （二）制定或者采取与国家安全生产方针政策以及安全生产法律、法规、规章相抵触的规定或者措施，造成不良后果或者经上级机关、有关部门指出仍不改正的。"},{"i":5,"n":"第五条","txt":"国家行政机关及其公务员有下列行为之一的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）向不符合法定安全生产条件的生产经营单位或者经营者颁发有关证照的； （二）对不具备法定条件机构、人员的安全生产资质、资格予以批准认定的； （三）对经责令整改仍不具备安全生产条件的生产经营单位，不撤销原行政许可、审批或者不依法查处的； （四）违法委托单位或者个人行使有关安全生产的行政许可权或者审批权的； （五）有其他违反规定实施安全生产行政许可或者审批行为的。"},{"i":6,"n":"第六条","txt":"国家行政机关及其公务员有下列行为之一的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）批准向合法的生产经营单位或者经营者超量提供剧毒品、火工品等危险物资，造成后果的； （二）批准向非法或者不具备安全生产条件的生产经营单位或者经营者，提供剧毒品、火工品等危险物资或者其他生产经营条件的。"},{"i":7,"n":"第七条","txt":"国家行政机关公务员利用职权或者职务上的影响，违反规定为个人和亲友谋取私利，有下列行为之一的，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）干预、插手安全生产装备、设备、设施采购或者招标投标等活动的； （二）干预、插手安全生产行政许可、审批或者安全生产监督执法的； （三）干预、插手安全生产中介活动的； （四）有其他干预、插手生产经营活动危及安全生产行为的。"},{"i":8,"n":"第八条","txt":"国家行政机关及其公务员有下列行为之一的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）未按照有关规定对有关单位申报的新建、改建、扩建工程项目的安全设施，与主体工程同时设计、同时施工、同时投入生产和使用中组织审查验收的； （二）发现存在重大安全隐患，未按规定采取措施，导致生产安全事故发生的； （三）对发生的生产安全事故瞒报、谎报、拖延不报，或者组织、参与瞒报、谎报、拖延不报的； （四）生产安全事故发生后，不及时组织抢救的； （五）对生产安全事故的防范、报告、应急救援有其他失职、渎职行为的。"},{"i":9,"n":"第九条","txt":"国家行政机关及其公务员有下列行为之一的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）阻挠、干涉生产安全事故调查工作的； （二）阻挠、干涉对事故责任人员进行责任追究的； （三）不执行对事故责任人员的处理决定，或者擅自改变上级机关批复的对事故责任人员的处理意见的。"},{"i":10,"n":"第十条","txt":"国家行政机关公务员有下列行为之一的，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）本人及其配偶、子女及其配偶违反规定在煤矿等企业投资入股或者在安全生产领域经商办企业的； （二）违反规定从事安全生产中介活动或者其他营利活动的； （三）在事故调查处理时，滥用职权、玩忽职守、徇私舞弊的； （四）利用职务上的便利，索取他人财物，或者非法收受他人财物，在安全生产领域为他人谋取利益的。 对国家行政机关公务员本人违反规定投资入股煤矿的处分，法律、法规另有规定的，从其规定。"},{"i":11,"n":"第十一条","txt":"国有企业及其工作人员有下列行为之一的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级、撤职或者留用察看处分；情节严重的，给予开除处分： （一）未取得安全生产行政许可及相关证照或者不具备安全生产条件从事生产经营活动的； （二）弄虚作假，骗取安全生产相关证照的； （三）出借、出租、转让或者冒用安全生产相关证照的； （四）未按照有关规定保证安全生产所必需的资金投入，导致产生重大安全隐患的； （五）新建、改建、扩建工程项目的安全设施，不与主体工程同时设计、同时施工、同时投入生产和使用，或者未按规定审批、验收，擅自组织施工和生产的； （六）被依法责令停产停业整顿、吊销证照、关闭的生产经营单位，继续从事生产经营活动的。"},{"i":12,"n":"第十二条","txt":"国有企业及其工作人员有下列行为之一，导致生产安全事故发生的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级、撤职或者留用察看处分；情节严重的，给予开除处分： （一）对存在的重大安全隐患，未采取有效措施的； （二）违章指挥，强令工人违章冒险作业的； （三）未按规定进行安全生产教育和培训并经考核合格，允许从业人员上岗，致使违章作业的； （四）制造、销售、使用国家明令淘汰或者不符合国家标准的设施、设备、器材或者产品的； （五）超能力、超强度、超定员组织生产经营，拒不执行有关部门整改指令的； （六）拒绝执法人员进行现场检查或者在被检查时隐瞒事故隐患，不如实反映情况的； （七）有其他不履行或者不正确履行安全生产管理职责的。"},{"i":13,"n":"第十三条","txt":"国有企业及其工作人员有下列行为之一的，对有关责任人员，给予记过或者记大过处分；情节较重的，给予降级、撤职或者留用察看处分；情节严重的，给予开除处分： （一）对发生的生产安全事故瞒报、谎报或者拖延不报的； （二）组织或者参与破坏事故现场、出具伪证或者隐匿、转移、篡改、毁灭有关证据，阻挠事故调查处理的； （三）生产安全事故发生后，不及时组织抢救或者擅离职守的。 生产安全事故发生后逃匿的，给予开除处分。"},{"i":14,"n":"第十四条","txt":"国有企业及其工作人员不执行或者不正确执行对事故责任人员作出的处理决定，或者擅自改变上级机关批复的对事故责任人员的处理意见的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级、撤职或者留用察看处分；情节严重的，给予开除处分。"},{"i":15,"n":"第十五条","txt":"国有企业负责人及其配偶、子女及其配偶违反规定在煤矿等企业投资入股或者在安全生产领域经商办企业的，对由国家行政机关任命的人员，给予警告、记过或者记大过处分；情节较重的，给予降级、撤职或者留用察看处分；情节严重的，给予开除处分。"},{"i":16,"n":"第十六条","txt":"承担安全评价、培训、认证、资质验证、设计、检测、检验等工作的机构及其工作人员，出具虚假报告等与事实不符的文件、材料，造成安全生产隐患的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级、降职或者撤职处分；情节严重的，给予开除留用察看或者开除处分。"},{"i":17,"n":"第十七条","txt":"法律、法规授权的具有管理公共事务职能的组织以及国家行政机关依法委托的组织及其工勤人员以外的工作人员有安全生产领域违法违纪行为，应当给予处分的，参照本规定执行。 企业、事业单位中除由国家行政机关任命的人员外，其他人员有安全生产领域违法违纪行为，应当给予处分的，由企业、事业单位参照本规定执行。"},{"i":18,"n":"第十八条","txt":"有安全生产领域违法违纪行为，需要给予组织处理的，依照有关规定办理。"},{"i":19,"n":"第十九条","txt":"有安全生产领域违法违纪行为，涉嫌犯罪的，移送司法机关依法处理。"},{"i":20,"n":"第二十条","txt":"本规定由监察部和国家安全生产监督管理总局负责解释。"},{"i":21,"n":"第二十一条","txt":"本规定自公布之日起施行。"}],"zongjiaotuantiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范宗教团体管理，促进宗教团体健康发展，积极引导宗教与社会主义社会相适应，根据国家社会团体管理和宗教事务管理有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称宗教团体，是指信教公民自愿组成，为团结信教公民爱国爱教、促进宗教健康发展，按照其章程开展活动的非营利性社会组织。 宗教团体是中国共产党和人民政府团结、联系宗教界人士和广大信教公民的桥梁和纽带。"},{"i":3,"n":"第三条","txt":"成立宗教团体应当按照国家社会团体登记管理和宗教事务管理规定，经人民政府宗教事务部门审查同意并到人民政府民政部门登记。 未经人民政府宗教事务部门审查同意，或者未在人民政府民政部门登记，不得以宗教团体的名义开展活动。"},{"i":4,"n":"第四条","txt":"宗教团体章程应当符合国家社会团体管理和宗教事务管理有关规定。宗教团体按照章程开展活动，受法律保护。"},{"i":5,"n":"第五条","txt":"宗教团体必须坚持中国共产党的领导，遵守宪法、法律、法规、规章和政策，坚持独立自主自办的原则，坚持我国宗教中国化方向，践行社会主义核心价值观，维护国家统一、民族团结、宗教和睦与社会稳定。"},{"i":6,"n":"第六条","txt":"人民政府宗教事务部门是宗教团体的业务主管单位。宗教团体应当接受人民政府宗教事务部门的业务指导和监督管理。"},{"i":7,"n":"第七条","txt":"宗教团体应当根据国家社会团体管理和宗教事务管理有关规定以及本团体章程规定，按照民主、精干、高效的原则建立组织机构。"},{"i":8,"n":"第八条","txt":"宗教团体代表会议是宗教团体的最高权力机构。理事会（委员会）是代表会议的执行机构，对代表会议负责。 理事会（委员会）人数较多的宗教团体可以设立常务理事会（常务委员会），常务理事会（常务委员会）对理事会（委员会）负责。"},{"i":9,"n":"第九条","txt":"宗教团体代表会议、理事会（委员会）和常务理事会（常务委员会）应当按照国家社会团体管理有关规定和本团体章程定期召开会议，决定相关事项，行使职权。"},{"i":10,"n":"第十条","txt":"宗教团体的理事（委员）、常务理事（常务委员）、会长（主席、主任）、副会长（副主席、副主任）、秘书长（总干事）、副秘书长（副总干事）应当按照国家社会团体管理有关规定和本团体章程规定产生，并履行职责。"},{"i":11,"n":"第十一条","txt":"会长（主席、主任）不得兼任其他社会团体包括宗教团体的会长（主席、主任），所任会长（主席、主任）的宗教团体合署办公的除外。会长（主席、主任）应当是具有中华人民共和国国籍的内地居民，年龄一般不得超过70周岁。 会长（主席、主任）每届任期五年，一般可连选连任一届。 会长（主席、主任）一般应当在团体驻会办公，特殊情况下，会长（主席、主任）不能驻会的，应当由常务副会长（常务副主席、常务副主任）负责团体日常工作。副会长（副主席、副主任）中应当至少有一位驻会。"},{"i":12,"n":"第十二条","txt":"宗教团体法定代表人一般应当由会长（主席、主任）担任。宗教团体法定代表人不得兼任其他社会团体包括宗教团体的法定代表人。"},{"i":13,"n":"第十三条","txt":"宗教团体应当根据业务范围和实际工作需要，合理设置办事机构。"},{"i":14,"n":"第十四条","txt":"宗教团体设立分支机构、代表机构，应当符合本团体章程规定的宗旨和业务范围，并经理事会（委员会）或者常务理事会（常务委员会）讨论通过。 分支机构可以称分会、专业委员会、工作委员会等。代表机构可以称代表处、办事处、联络处。 分支机构、代表机构不具有法人资格，不得另行制定章程，其名称不得以各类法人组织的名称命名，不得冠以“中国”“中华”“全国”“国家”等字样，开展活动应当使用冠有所属宗教团体名称的规范全称。 宗教团体不得设立地域性的分支机构，不得在分支机构、代表机构下再设立分支机构、代表机构。"},{"i":15,"n":"第十五条","txt":"宗教团体应当加强领导班子建设，按照政治上可靠、作风上民主、工作上高效的标准，建设高素质领导班子。"},{"i":16,"n":"第十六条","txt":"宗教团体应当依法依章程开展工作，履行法律、法规、规章和本团体章程规定的职能。"},{"i":17,"n":"第十七条","txt":"宗教团体应当向宗教教职人员和信教公民宣传中国共产党的方针政策以及国家法律、法规、规章，教育引导宗教教职人员和信教公民拥护中国共产党的领导，拥护社会主义制度，坚持走中国特色社会主义道路，遵守法律、法规、规章和政策，正确处理国法与教规关系，增强国家意识、法治意识、公民意识。"},{"i":18,"n":"第十八条","txt":"宗教团体应当联系、服务宗教教职人员和信教公民，反映宗教界的意见和合理诉求，维护宗教教职人员和信教公民的合法权益，引导宗教教职人员和信教公民履行公民义务。"},{"i":19,"n":"第十九条","txt":"宗教团体应当根据宪法、法律、法规、规章、政策以及实际工作需要，在业务范围内制定有关宗教院校、宗教活动场所、宗教教职人员、宗教活动等方面的规章制度并督促落实。"},{"i":20,"n":"第二十条","txt":"全国性宗教团体和省、自治区、直辖市宗教团体应当履行宗教院校办学主体责任，对所举办宗教院校进行日常管理和指导监督，指导宗教院校坚持正确的办学方向，提高办学质量,完善董事会或者理事会等组织机构和议事决策制度，完善宗教院校内部管理和运行机制；支持宗教院校改善办学条件，帮助解决办学中遇到的困难和问题，保障宗教院校有稳定的办学经费。"},{"i":21,"n":"第二十一条","txt":"宗教团体应当指导宗教活动场所成立管理组织，完善内部管理制度，实行民主管理，规范宗教活动和财务管理。 宗教团体应当指导宗教活动场所协商产生宗教活动场所主要教职人选，并对担任或者离任宗教活动场所主要教职的宗教教职人员进行审核，审核同意后指导宗教活动场所向人民政府宗教事务部门备案。 宗教团体根据实际需要，依法申请设立宗教活动场所；对宗教活动场所申请法人登记，提出审核意见。"},{"i":22,"n":"第二十二条","txt":"宗教团体应当进行宗教文化、宗教典籍研究，开展宗教思想建设，深入挖掘教义教规中有利于社会和谐、时代进步、健康文明的内容，对教义教规作出符合当代中国发展进步要求、符合中华优秀传统文化的阐释。"},{"i":23,"n":"第二十三条","txt":"宗教团体应当按照全国性宗教团体制定的宗教教职人员认定办法认定宗教教职人员，并报人民政府宗教事务部门备案。 宗教团体应当加强宗教教职人员的法治教育、政治教育、文化教育、宗教教育，提高宗教教职人员的综合素质。 宗教团体应当加强教风建设，健全宗教教职人员奖惩机制和准入、退出机制，对违反法律、法规、规章和本团体规章制度的宗教教职人员，依规予以惩处。"},{"i":24,"n":"第二十四条","txt":"全国性宗教团体和省、自治区、直辖市宗教团体可以根据本宗教的需要，按照国家有关规定选派和接收宗教留学人员，规范留学人员留学渠道。 全国性宗教团体应当制定本宗教选派和接收宗教留学人员办法，并报国家宗教事务局备案。"},{"i":25,"n":"第二十五条","txt":"人民政府宗教事务部门应当履行业务主管单位的职责，根据国家有关法律、法规、规章，对宗教团体的下列事务进行指导和管理: （一）负责宗教团体设立、变更、注销登记以及章程核准前的业务审查，负责宗教团体年度工作报告的审查，会同有关机关指导宗教团体的注销登记清算事宜； （二）监督、指导宗教团体依法依章程开展活动、履行职能，对宗教团体违反法律、法规、规章、政策和本团体章程的行为，依法予以处理； （三）对宗教团体依法向人民政府宗教事务部门申请审批的事项进行审批、监督和管理； （四）监督、指导宗教团体根据宪法、法律、法规、规章、政策以及实际工作需要，建立健全规章制度，加强思想建设、组织建设、作风建设和制度建设; （五）法律、法规规定的其他需要指导和管理的事项。"},{"i":26,"n":"第二十六条","txt":"宗教团体的下列事项，应当报其业务主管单位审核同意： （一）法律、法规规定应当经业务主管单位审批的事项； （二）调整本团体会长（主席、主任）、副会长（副主席、副主任）、秘书长（总干事）和办事机构以及办事机构负责人，聘请名誉会长（主席、主任）； （三）举办重大会议、活动、培训以及开展对外交流活动； （四）开展活动拟冠以人民政府宗教事务部门作为支持单位、主办单位； （五）接受国（境）外组织或者个人捐赠宗教书刊、音像制品或者捐赠金额超过10万元； （六）其他应当报业务主管单位审核的事项。"},{"i":27,"n":"第二十七条","txt":"宗教团体的下列事项，应当事前书面报告其业务主管单位： （一）工作规划、年度工作计划、年度工作总结； （二）大额财务支出、重大资产处置、重大建设工程项目； （三）成立分支机构、代表机构、社会组织以及经济实体； （四）发生安全事故，造成人员伤亡或财产损失； （五）本团体内部或者本团体与其他方面发生矛盾、纠纷，影响本团体工作正常开展； （六）发生重大违法违规问题； （七）其他应当报告业务主管单位的事项。 特殊情况下，不能事前书面报告的，宗教团体应当在事中或者事后及时书面报告其业务主管单位。"},{"i":28,"n":"第二十八条","txt":"宗教团体应当按照国家社会团体管理有关规定和本团体章程，规范代表会议、理事会（委员会）、常务理事会（常务委员会）、会长（主席、主任）会议、会长（主席、主任）办公会议制度，完善民主决策机制。"},{"i":29,"n":"第二十九条","txt":"宗教团体应当制定工作规划和年度工作计划，明确远期目标和近期任务，并保障规划和计划得到贯彻执行。"},{"i":30,"n":"第三十条","txt":"宗教团体应当制定本团体工作人员管理制度，明确工作职责和工作纪律，规范工作人员的宗教活动、社会活动、对外交流等。 宗教团体工作人员包括会长（主席、主任）、副会长（副主席、副主任）、秘书长（总干事）、副秘书长（副总干事）、办事机构工作人员。"},{"i":31,"n":"第三十一条","txt":"宗教团体应当建立会长（主席、主任）、副会长（副主席、副主任）、秘书长（总干事）述职和民主评议制度。"},{"i":32,"n":"第三十二条","txt":"宗教团体应当建立学习制度，组织本团体工作人员学习中国共产党的重大决策部署、国家政策法规、中华优秀传统文化、宗教知识等。"},{"i":33,"n":"第三十三条","txt":"宗教团体开展互联网宗教信息服务，应当健全相关内部管理制度，遵守互联网宗教信息服务相关规定。"},{"i":34,"n":"第三十四条","txt":"宗教团体应当执行国家统一的财务、资产、会计制度，建立健全会计核算、财务报告、财务公开等制度，建立健全财务管理机构，配备必要的会计人员，加强财务管理，定期向所在地的县级以上人民政府宗教事务部门报告财务状况、收支情况和接受、使用捐赠情况等，并以适当方式向信教公民公布。"},{"i":35,"n":"第三十五条","txt":"宗教团体的法定代表人、主管财务的负责人，以及财务部门的负责人，在离任、退休、调离工作岗位时，应当接受财务审计。"},{"i":36,"n":"第三十六条","txt":"宗教团体应当依法办理税务登记、办理纳税申报，按照国家有关规定享受税收优惠。"},{"i":37,"n":"第三十七条","txt":"宗教团体存在内部治理不规范、未按章程规定履行职责等问题的，人民政府宗教事务部门应当对其会长（主席、主任）进行工作约谈；情节严重的，给予通报批评、限期整改等。"},{"i":38,"n":"第三十八条","txt":"宗教团体违反国家社会团体管理、宗教事务管理有关规定的，由人民政府宗教事务部门、民政部门等依法处理；违反其他法律、法规的，依法追究法律责任。"},{"i":39,"n":"第三十九条","txt":"本办法由国家宗教事务局负责解释。"},{"i":40,"n":"第四十条","txt":"本办法未尽事宜，按国家有关规定执行。"},{"i":41,"n":"第四十一条","txt":"本办法自2020年2月1日起实施。"}],"zongjiaojiaozhirenyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范宗教教职人员管理，保障宗教教职人员合法权益，根据《宗教事务条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称宗教教职人员，是指依法取得宗教教职人员资格、可以从事宗教教务活动的人员。"},{"i":3,"n":"第三条","txt":"宗教教职人员应当热爱祖国，拥护中国共产党的领导，拥护社会主义制度，遵守宪法、法律、法规和规章，践行社会主义核心价值观，坚持我国宗教独立自主自办原则，坚持我国宗教中国化方向，维护国家统一、民族团结、宗教和睦与社会稳定。"},{"i":4,"n":"第四条","txt":"宗教事务部门依法对宗教教职人员进行行政管理，保护宗教教职人员合法权益，指导宗教团体、宗教院校和宗教活动场所培养、管理宗教教职人员，引导宗教教职人员在促进经济社会发展中发挥积极作用。"},{"i":5,"n":"第五条","txt":"宗教教职人员依法享有下列权利： （一）主持宗教活动、举行宗教仪式； （二）从事宗教典籍整理、进行宗教教义教规和宗教文化研究； （三）从事、接受宗教教育培训； （四）参与所在的宗教团体、宗教院校、宗教活动场所的管理，按程序担任相应的职务； （五）开展公益慈善活动； （六）参加社会保障并享有相关权利； （七）法律、法规和规章规定的其他权利。"},{"i":6,"n":"第六条","txt":"宗教教职人员应当履行下列义务： （一）维护国家利益和社会公共利益，在法律、法规和规章规定的范围内开展活动； （二）接受宗教事务部门和其他有关部门的依法管理； （三）遵守宗教团体制定的规章制度，接受所在的宗教团体、宗教院校、宗教活动场所的管理； （四）服务信教公民，引导信教公民爱国守法； （五）维护宗教活动正常秩序，抵制非法宗教活动和宗教极端思想，抵御境外势力利用宗教进行的渗透； （六）维护和促进不同宗教之间、同一宗教内部以及信教公民和不信教公民之间的和睦； （七）法律、法规和规章规定的其他义务。"},{"i":7,"n":"第七条","txt":"宗教教职人员应当注重提升自身素质，提高文化、道德素养，研究教义教规中有利于社会和谐、时代进步和健康文明的内容，并融入讲经讲道中，为推进我国宗教中国化发挥作用。"},{"i":8,"n":"第八条","txt":"宗教教职人员发布互联网宗教信息，应当遵守国家互联网信息服务的有关规定。"},{"i":9,"n":"第九条","txt":"宗教教职人员收入的取得应当符合法律、法规、规章和政策以及宗教团体规章制度的规定。 宗教教职人员应当区分个人财产与宗教团体、宗教院校、宗教活动场所的财产，不得侵占、挪用、私分、损毁或者擅自处分宗教团体、宗教院校、宗教活动场所的合法财产。 宗教教职人员应当依法纳税，依法办理纳税申报。"},{"i":10,"n":"第十条","txt":"在宗教团体、宗教院校、宗教活动场所担任负责人或者从事财务相关工作的宗教教职人员应当按照国家财务、会计、资产管理有关规定，履行财务管理职责。"},{"i":11,"n":"第十一条","txt":"宗教教职人员出境开展宗教交往，应当按照国家有关规定办理手续。"},{"i":12,"n":"第十二条","txt":"宗教教职人员不得有下列行为： （一）危害国家安全、公共安全，宣扬、支持、资助宗教极端主义，破坏民族团结、分裂国家，进行恐怖活动或者参与相关活动； （二）干预行政、司法、教育等国家职能的实施； （三）受境外势力支配，擅自接受境外宗教团体或者机构委任教职，以及其他违背宗教独立自主自办原则的行为； （四）违反国家有关规定接受境内外捐赠； （五）影响公民正常生产、生活； （六）组织、主持或者参加未经批准的在宗教活动场所外举行的宗教活动； （七）利用公益慈善活动传教，在宗教院校以外的学校和其他教育机构传教，以及其他违反国家规定进行传教的行为； （八）以宗教名义进行商业宣传； （九）其他违反法律、法规和规章的行为。"},{"i":13,"n":"第十三条","txt":"取得宗教教职人员资格应当经宗教团体认定，报宗教事务部门备案。 全国性宗教团体应当制定本宗教的宗教教职人员认定办法，规定宗教教职人员的称谓、认定条件和程序等，认定条件应当包含本办法第三条规定的内容。全国性宗教团体制定的宗教教职人员认定办法应当报国家宗教事务局备案。 宗教团体应当按照全国性宗教团体制定的宗教教职人员认定办法认定宗教教职人员。"},{"i":14,"n":"第十四条","txt":"宗教团体应当自认定宗教教职人员之日起二十日内，填写宗教教职人员备案表，报宗教事务部门备案，并提交拟备案宗教教职人员的户口簿复印件和居民身份证复印件。 全国性宗教团体认定的宗教教职人员，报国家宗教事务局备案；省、自治区、直辖市宗教团体认定的宗教教职人员，报省级人民政府宗教事务部门备案；设区的市（地、州、盟）宗教团体认定的宗教教职人员，报设区的市级人民政府宗教事务部门备案；县（市、区、旗）宗教团体认定的宗教教职人员，报县级人民政府宗教事务部门备案。 宗教教职人员备案表式样由国家宗教事务局制定。"},{"i":15,"n":"第十五条","txt":"藏传佛教活佛传承继位，按照《宗教事务条例》《藏传佛教活佛转世管理办法》等有关规定办理。"},{"i":16,"n":"第十六条","txt":"天主教的主教由中国天主教主教团批准并祝圣。中国天主教爱国会和中国天主教主教团应当在主教祝圣后二十日内，填写天主教主教备案表，报国家宗教事务局备案，并提交下列材料： （一）该主教的户口簿复印件和居民身份证复印件； （二）省、自治区、直辖市天主教团体出具的民主选举该主教的情况说明； （三）中国天主教主教团批准书； （四）主持祝圣的主教签署的祝圣情况说明。 天主教主教备案表式样由国家宗教事务局制定。"},{"i":17,"n":"第十七条","txt":"宗教事务部门应当自收到宗教团体提交的备案材料之日起二十个工作日内，作出书面答复，逾期未答复的，视为已办理备案。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，不予办理宗教教职人员备案： （一）未按照全国性宗教团体制定的宗教教职人员认定办法认定的； （二）提交的备案材料不属实的。"},{"i":19,"n":"第十九条","txt":"宗教事务部门办理备案后，应当为宗教教职人员编制备案号。备案号采用十二位数字编码，依次由六位行政区划代码、一位教别号和五位流水号组成。"},{"i":20,"n":"第二十条","txt":"宗教团体应当向完成备案的宗教教职人员颁发宗教教职人员证书，不得收取费用。 宗教教职人员证书在全国范围内适用。宗教团体、宗教事务部门不得重复认定或者备案宗教教职人员。 宗教教职人员证书由全国性宗教团体印制，证书应当载明备案号和有效期等内容。宗教教职人员应当在证书有效期满前及时办理延期手续。"},{"i":21,"n":"第二十一条","txt":"宗教教职人员有下列情形之一的，宗教团体应当按照管理职责到相应的宗教事务部门办理注销备案手续，并以适当方式公告： （一）被宗教事务部门依法建议宗教团体取消宗教教职人员资格的； （二）被宗教团体依照本宗教的有关规定取消宗教教职人员资格的； （三）因自愿放弃、死亡或者其他原因丧失宗教教职人员资格的。"},{"i":22,"n":"第二十二条","txt":"本办法所称宗教活动场所主要教职，是指在宗教活动场所主持宗教教务的宗教教职人员。 全国性宗教团体应当制定本宗教的宗教活动场所主要教职任职办法，规定宗教活动场所主要教职的具体范围、任职条件和程序等，任职条件应当包含本办法第三条规定的内容。全国性宗教团体制定的宗教活动场所主要教职任职办法应当报国家宗教事务局备案。"},{"i":23,"n":"第二十三条","txt":"拟任宗教活动场所主要教职的宗教教职人员，按照全国性宗教团体制定的宗教活动场所主要教职任职办法产生后十日内，由该场所填写宗教活动场所主要教职备案表，报宗教事务部门备案，并提交下列材料： （一）拟任职人员产生情况说明； （二）拟任职人员的户口簿复印件、居民身份证复印件和宗教教职人员证书复印件。 拟任职人员离任其他宗教活动场所主要教职的，还应当提交离任场所主要教职的注销备案材料。 宗教活动场所主要教职备案表式样由国家宗教事务局制定。"},{"i":24,"n":"第二十四条","txt":"宗教事务部门应当自收到宗教活动场所提交的备案材料之日起二十个工作日内，作出书面答复，逾期未答复的，视为已完成备案程序。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，不予办理宗教活动场所主要教职备案： （一）拟任职人员未按照全国性宗教团体制定的宗教活动场所主要教职任职办法产生的； （二）拟任职人员离任其他宗教活动场所主要教职未办理注销备案手续的； （三）提交的备案材料不属实的。"},{"i":26,"n":"第二十六条","txt":"宗教活动场所主要教职备案程序完成后，该场所可以举行主要教职任职仪式，正式赋予职责。"},{"i":27,"n":"第二十七条","txt":"宗教活动场所主要教职实行任期制，任期三至五年。期满后拟继续担任主要教职的，应当按照本办法第二十三条规定办理。"},{"i":28,"n":"第二十八条","txt":"宗教教职人员离任宗教活动场所主要教职，该场所应当按照任职备案程序办理注销备案手续，并提交下列材料： （一）该场所管理组织作出宗教教职人员离任宗教活动场所主要教职决定的情况说明； （二）该场所所在地宗教团体出具的书面意见。 离任宗教活动场所主要教职的宗教教职人员同时担任该场所管理组织负责人或者财务管理机构负责人的，该场所还应当提交离任财务审查情况的报告。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，不予办理宗教活动场所主要教职注销备案： （一）该场所管理组织未按照全国性宗教团体制定的宗教活动场所主要教职任职办法规定的程序，作出宗教教职人员离任宗教活动场所主要教职决定的； （二）未经该场所所在地宗教团体同意的； （三）离任该场所主要教职的宗教教职人员同时担任该场所管理组织负责人或者财务管理机构负责人，该场所未提交离任财务审查情况报告的。"},{"i":30,"n":"第三十条","txt":"宗教教职人员一般只能担任一个宗教活动场所的主要教职。确有需要的，可以兼任一个宗教活动场所的主要教职。 兼任宗教活动场所主要教职，应当经拟兼任的宗教活动场所所在地县（市、区、旗）宗教团体同意，由该场所将兼任情况报县级人民政府宗教事务部门，县级人民政府宗教事务部门逐级报省级人民政府宗教事务部门备案。跨省、自治区、直辖市兼任的，拟兼任的宗教活动场所所在地省级人民政府宗教事务部门还应当征求该宗教教职人员现任职所在地省级人民政府宗教事务部门的意见。"},{"i":31,"n":"第三十一条","txt":"担任宗教活动场所主要教职的宗教教职人员有下列情形之一的，应当按照任职备案程序办理注销备案手续，并以适当方式公告： （一）丧失宗教教职人员资格的； （二）违反法律、法规、规章或者宗教团体规章制度被撤销宗教活动场所主要教职的； （三）超过一年未履行宗教活动场所主要教职职责或者不具备正常履行主要教职职责能力的。"},{"i":32,"n":"第三十二条","txt":"宗教事务部门应当依法履行宗教教职人员备案和宗教活动场所主要教职备案的职责，指导、监督宗教团体、宗教院校、宗教活动场所加强对宗教教职人员的管理。"},{"i":33,"n":"第三十三条","txt":"宗教事务部门应当按照寓管理于服务之中的原则，加强宗教教职人员信息化管理。 国家宗教事务局应当建立宗教教职人员数据库，地方人民政府宗教事务部门应当及时提供和更新宗教教职人员的基本信息、奖惩情况、注销备案等信息。"},{"i":34,"n":"第三十四条","txt":"宗教教职人员跨省、自治区、直辖市从事宗教教务活动的，应当经离开地和前往地的省、自治区、直辖市宗教团体同意，并报两地的省级人民政府宗教事务部门备案。其中，跨省、自治区、直辖市从事宗教教务活动一年以上的，由两地的省级人民政府宗教事务部门通过宗教教职人员数据库办理相关信息变更。对该宗教教职人员的管理职责转移至迁入地相应的宗教事务部门和宗教团体。 宗教教职人员跨县、设区的市级行政区域从事宗教教务活动的管理，由省、自治区、直辖市根据实际情况制定相关规定。"},{"i":35,"n":"第三十五条","txt":"宗教团体应当制定宗教教职人员培养规划，加强宗教教职人员的政治教育、法治教育、文化教育、宗教教育，提高宗教教职人员的综合素质和宗教教职人员队伍的整体素质。 全国性宗教团体和省、自治区、直辖市宗教团体应当制定宗教教职人员出境留学的规章制度。"},{"i":36,"n":"第三十六条","txt":"宗教团体应当规范宗教教职人员证书管理，不得违规颁发证书，不得借颁发证书牟利。"},{"i":37,"n":"第三十七条","txt":"宗教团体应当根据宪法、法律、法规、规章和政策以及实际工作需要，在业务范围内建立健全宗教教职人员管理的规章制度，制定宗教教职人员行为规范，健全宗教教职人员奖惩机制和准入、退出机制，对违反法律、法规、规章和本团体规章制度的宗教教职人员予以相应处罚。"},{"i":38,"n":"第三十八条","txt":"宗教团体应当制定宗教教职人员考核制度，对宗教教职人员进行考核，将考核结果作为任职、奖惩等的重要依据。"},{"i":39,"n":"第三十九条","txt":"宗教团体应当建立宗教教职人员档案，健全宗教团体、宗教院校、宗教活动场所的宗教教职人员信息共享机制，定期将宗教教职人员信息变更情况报送宗教事务部门。 宗教院校应当将本院校宗教教职人员有关情况及时报送设立该院校的宗教团体。 宗教活动场所应当将本场所宗教教职人员有关情况及时报送所在地宗教团体和宗教事务部门。"},{"i":40,"n":"第四十条","txt":"宗教院校应当坚持正确的办学方向，提高办学质量，培养高素质的宗教教职人员。"},{"i":41,"n":"第四十一条","txt":"宗教活动场所接收宗教教职人员应当严格把关，核查身份并登记造册。 宗教活动场所不得超出本场所容纳能力及经济能力接收宗教教职人员。"},{"i":42,"n":"第四十二条","txt":"宗教团体、宗教院校、宗教活动场所应当建立健全本团体、院校、场所宗教教职人员管理制度，加强对宗教教职人员从事宗教活动、接受境内外捐赠等的监督和管理。"},{"i":43,"n":"第四十三条","txt":"担任宗教活动场所主要教职的宗教教职人员应当履行宗教教务管理职责，接受宗教团体的教务指导，服从宗教活动场所管理组织的管理，接受所在宗教活动场所的宗教教职人员和信教公民的监督。"},{"i":44,"n":"第四十四条","txt":"宗教事务部门和宗教团体、宗教院校、宗教活动场所收到反映宗教教职人员违反法律、法规、规章或者宗教团体规章制度情况的，应当调查核实，依法依规予以处理。"},{"i":45,"n":"第四十五条","txt":"宗教教职人员认为宗教团体、宗教院校、宗教活动场所及其成员侵犯其合法权益的，可以向宗教事务部门反映。宗教事务部门应当调查核实，依法予以处理。"},{"i":46,"n":"第四十六条","txt":"公职人员在宗教教职人员管理工作中滥用职权、玩忽职守、徇私舞弊，应当给予处分的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"宗教团体、宗教院校、宗教活动场所有下列行为之一的，由宗教事务部门责令改正，拒不改正的，按照《宗教事务条例》第六十五条的规定予以处罚： （一）未建立健全宗教教职人员管理制度的； （二）未按本办法规定管理宗教教职人员的； （三）未按规定认定或者批准宗教教职人员的； （四）宗教活动场所未按规定选任宗教活动场所主要教职的； （五）宗教团体未按本办法规定办理宗教教职人员备案手续，宗教活动场所未按本办法规定办理宗教活动场所主要教职备案手续的； （六）未按规定颁发宗教教职人员证书，或者借颁发证书牟利的； （七）侵犯宗教教职人员合法权益的； （八）其他违反本办法有关规定的行为。"},{"i":48,"n":"第四十八条","txt":"宗教教职人员违反本办法有关规定的，按照《宗教事务条例》第七十三条等规定予以处罚。"},{"i":49,"n":"第四十九条","txt":"对宗教事务部门的行政行为不服的，可以依法申请行政复议；对行政复议决定不服的，可以依法提起行政诉讼。"},{"i":50,"n":"第五十条","txt":"县（市、区、旗）没有相关宗教团体的，本办法规定的相应职责由设区的市（地、州、盟）宗教团体履行。 设区的市（地、州、盟）没有相关宗教团体的，相应职责由省、自治区、直辖市宗教团体履行。 省、自治区、直辖市没有相关宗教团体的，相应职责由全国性宗教团体履行。"},{"i":51,"n":"第五十一条","txt":"本办法由国家宗教事务局负责解释。"},{"i":52,"n":"第五十二条","txt":"本办法自2021年5月1日起施行。2006年国家宗教事务局公布的《宗教教职人员备案办法》《宗教活动场所主要教职任职备案办法》同时废止。"}],"zongjiaohuodongchangsuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范宗教活动场所管理，保护正常的宗教活动，维护宗教活动场所和信教公民的合法权益，根据宪法、有关法律和《宗教事务条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称宗教活动场所，是指依照《宗教事务条例》等规定登记的寺院、宫观、清真寺、教堂（以下称寺观教堂）和其他固定宗教活动处所。"},{"i":3,"n":"第三条","txt":"宗教活动场所应当拥护中国共产党的领导，拥护社会主义制度，深入贯彻习近平新时代中国特色社会主义思想，遵守宪法、法律、法规、规章和宗教事务管理的相关规定，践行社会主义核心价值观，坚持我国宗教中国化方向，坚持独立自主自办原则，维护国家统一、民族团结、宗教和顺与社会稳定。 任何组织或者个人不得利用宗教活动场所进行危害国家安全、破坏社会秩序、损害公民身体健康、妨碍国家教育制度、违背公序良俗，以及其他损害国家利益、社会公共利益和公民合法权益等活动。 宗教活动场所不得从事非法活动或者为非法活动提供条件。"},{"i":4,"n":"第四条","txt":"宗教活动场所的合法财产、收益以及正常的宗教活动受法律保护。 任何组织或者个人不得以宗教活动场所名义或者利用宗教活动场所影响力进行商业宣传，牟取非法利益。"},{"i":5,"n":"第五条","txt":"任何组织或者个人进入宗教活动场所应当尊重该场所所属宗教的信仰和习俗。 任何组织或者个人不得在宗教活动场所内制造不同宗教之间、同一宗教内部以及信教公民与不信教公民之间的矛盾和冲突。"},{"i":6,"n":"第六条","txt":"宗教活动场所应当成立管理组织，实行民主管理。 宗教活动场所之间不得形成隶属关系。"},{"i":7,"n":"第七条","txt":"宗教事务部门应当会同有关部门依法对宗教活动场所进行监督管理，保障公民宗教信仰自由，维护宗教活动场所的合法权益，指导和督促宗教活动场所规范内部管理。"},{"i":8,"n":"第八条","txt":"设立宗教活动场所，应当具备下列条件： （一）设立宗旨不违背《宗教事务条例》第四条、第五条的规定； （二）当地一定数量的信教公民有经常进行集体宗教活动的需要； （三）有拟主持宗教活动的宗教教职人员或者符合本宗教的全国性宗教团体规章制度规定的其他人员； （四）有必要的资金，资金来源渠道合法； （五）布局合理，符合国土空间规划和生态环境保护要求。"},{"i":9,"n":"第九条","txt":"筹备设立宗教活动场所，由宗教团体向拟设立场所所在地的县级宗教事务部门提出申请。"},{"i":10,"n":"第十条","txt":"申请筹备设立宗教活动场所的宗教团体应当提出筹备组织组建方案。筹备组织应当由该宗教团体的有关人员、拟主持宗教活动的宗教教职人员或者符合本宗教的全国性宗教团体规章制度规定的其他人员、拟设立地信教公民代表等组成。"},{"i":11,"n":"第十一条","txt":"申请筹备设立宗教活动场所，应当填写《宗教活动场所筹备设立申请表》，同时提交下列材料： （一）拟设立地一定数量的信教公民有经常进行集体宗教活动需要的情况说明； （二）拟主持宗教活动的宗教教职人员或者符合本宗教的全国性宗教团体规章制度规定的其他人员的基本情况及户口簿、居民身份证和宗教教职人员证书； （三）拟成立的筹备组织成员的基本情况、户口簿和居民身份证（属宗教教职人员的，还应当提供宗教教职人员证书）； （四）资金预算及资金来源情况说明； （五）拟设立地点和拟设立场所的可行性说明，以及建筑风格样式的效果图样。"},{"i":12,"n":"第十二条","txt":"县级宗教事务部门应当自收到申请之日起三十个工作日内提出审核意见，报设区的市级宗教事务部门。 设区的市级宗教事务部门应当自收到县级宗教事务部门报送的材料之日起三十个工作日内，对申请设立其他固定宗教活动处所的，作出批准或者不予批准的决定，作出批准决定的，应当报省级宗教事务部门备案；对申请设立寺观教堂的，提出审核意见，报省级宗教事务部门审批。 省级宗教事务部门应当自收到设区的市级宗教事务部门报送的材料之日起三十个工作日内，作出批准或者不予批准的决定。 设区的市级宗教事务部门和省级宗教事务部门作出决定前，应当进行实地核查，必要时可以召开听证会。 拟设立宗教活动场所涉及不可移动文物的，应当按照文物保护法律、法规的规定办理。 在自然保护地范围内拟设立宗教活动场所的，应当按照自然保护地法律、法规的规定办理。 宗教活动场所的设立申请获得批准后，方可正式成立筹备组织，办理该宗教活动场所的筹建事项。"},{"i":13,"n":"第十三条","txt":"宗教活动场所的筹备设立事项，应当在批准的筹备设立期限内完成。筹备设立期限一般不超过五年。筹备组织应当将筹备情况及时向设立地的县级宗教事务部门报告。 设立地的县级以上地方宗教事务部门应当对筹备设立的进展情况进行监督检查。未在批准期限内完成宗教活动场所筹备设立事项的，经筹备设立批准机关批准可以适当延长，但最长不得超过两年。筹备设立事项在延长期限内仍然无法完成的，该筹备设立许可失效。提出筹备设立申请的宗教团体应当做好相关善后事宜。"},{"i":14,"n":"第十四条","txt":"宗教活动场所在登记前，应当由筹备组织负责，并在所在地宗教团体的指导下，民主协商成立该场所的管理组织。"},{"i":15,"n":"第十五条","txt":"宗教活动场所经批准筹备并建设完工后，场所管理组织应当向所在地的县级宗教事务部门（以下称登记管理机关）申请登记。 申请登记宗教活动场所，应当填写《宗教活动场所登记申请表》，同时提交下列材料： （一）民主协商成立管理组织的情况说明； （二）管理组织成员的户口簿和居民身份证； （三）主持宗教活动的宗教教职人员或者符合本宗教的全国性宗教团体规章制度规定的其他人员的户口簿、居民身份证和宗教教职人员证书； （四）人员、财务、资产、会计、档案、治安、消防、文物保护、卫生防疫等规章制度文本； （五）场所房屋等建筑物的有关材料（属建设工程的，提供工程竣工验收、消防验收材料，规划、用地核实核验材料，已经办理土地和房屋不动产登记的，提供土地房屋的不动产权证书；属租借的，提供一年期以上的使用权和房屋安全材料）； （六）合法经济来源的情况说明。"},{"i":16,"n":"第十六条","txt":"宗教活动场所不得以教会、教派、人名等冠名。"},{"i":17,"n":"第十七条","txt":"登记管理机关应当自收到申请之日起三十个工作日内对该宗教活动场所的名称、管理组织、规章制度建设等情况进行审核，对符合条件的予以登记，发给《宗教活动场所登记证》。宗教活动场所取得《宗教活动场所登记证》后方可开展宗教活动。 《宗教活动场所登记证》和有关申请表，由各省、自治区、直辖市宗教事务部门按照国家宗教事务局制定的式样印制。 《宗教活动场所登记证》不得涂改、转让、出借。证书遗失的，应当及时向登记管理机关申请补办。"},{"i":18,"n":"第十八条","txt":"宗教活动场所符合法人条件的，经所在地宗教团体同意，并报县级宗教事务部门审查同意后，可以到民政部门办理法人登记。 宗教活动场所办理法人登记的，其相关登记和管理工作应当遵守国家有关规定。"},{"i":19,"n":"第十九条","txt":"宗教活动场所变更名称、地址、负责人等登记内容的，应当到原登记管理机关办理相应的变更登记手续。 其他固定宗教活动处所需要变更为寺观教堂的，应当按照本办法第十二条规定的寺观教堂的审批程序办理，并按照前款规定办理变更登记。"},{"i":20,"n":"第二十条","txt":"宗教活动场所有下列情形之一的，应当到原登记管理机关申请注销登记： （一）被依法吊销《宗教活动场所登记证》或者民政部门颁发的《宗教活动场所法人登记证书》的； （二）无法维持正常运行的； （三）无正当理由两年以上不开展宗教活动的； （四）自行解散或者由于其他原因终止的。"},{"i":21,"n":"第二十一条","txt":"宗教活动场所申请注销登记，原登记管理机关应当指导该场所成立清算组织，完成清算工作。清算期间，不得开展清算以外的活动，清算后的剩余财产应当用于与其宗旨相符的事业。"},{"i":22,"n":"第二十二条","txt":"宗教活动场所应当自完成清算之日起十五日内，向原登记管理机关办理注销登记手续。原登记管理机关应当收回《宗教活动场所登记证》，并逐级上报省级宗教事务部门备案。"},{"i":23,"n":"第二十三条","txt":"宗教活动场所未按本办法规定申请注销登记的，在原登记管理机关告知后，十五日内仍未依法办理的，原登记管理机关应当协调所在地宗教团体成立清算组织完成清算，并依法予以注销登记。"},{"i":24,"n":"第二十四条","txt":"宗教活动场所管理组织应当经民主协商产生，由宗教教职人员、所在地信教公民代表和其他有关人员等组成。 管理组织成员应当三人以上，设负责人一名。 宗教活动场所管理组织成员的产生、惩处、调整，应当征求所在地宗教团体意见后，报登记管理机关备案。"},{"i":25,"n":"第二十五条","txt":"宗教活动场所管理组织成员每届任期不超过五年，可以连任，任期届满应当在所在地宗教团体指导下进行换届。特殊情况经所在地宗教团体同意并报登记管理机关备案，可以提前或者延后换届，但是延期换届最长不超过一年。"},{"i":26,"n":"第二十六条","txt":"宗教活动场所管理组织负责人一般不得同时担任其他宗教活动场所管理组织负责人。确有需要的，可以兼任一个宗教活动场所的管理组织负责人。 兼任宗教活动场所管理组织负责人，应当经拟兼任的宗教活动场所所在地宗教团体同意，由该场所将兼任情况报所在地县级宗教事务部门，县级宗教事务部门逐级报省级宗教事务部门备案。跨省、自治区、直辖市兼任的，拟兼任的宗教活动场所所在地省级宗教事务部门还应当征求该人选现任职所在地省级宗教事务部门的意见。"},{"i":27,"n":"第二十七条","txt":"宗教活动场所管理组织成员应当具备下列基本条件： （一）热爱祖国，拥护中国共产党的领导和社会主义制度； （二）遵守宪法、法律、法规、规章和宗教事务管理的相关规定； （三）遵守本宗教的宗教团体和该宗教活动场所制定的各项规章制度； （四）具备一定的宗教知识和组织管理能力； （五）具有完全民事行为能力； （六）作风端正，为人正派，办事公道，责任心强。 宗教活动场所管理组织成员应当是具有中国国籍的内地居民，当选时年龄一般不得超过七十周岁。 管理组织成员之间有夫妻关系、直系血亲关系、三代以内旁系血亲关系、近姻亲关系以及收养关系的，应当回避。"},{"i":28,"n":"第二十八条","txt":"宗教活动场所应当建立管理组织成员考核制度，及时调整不称职或未按规定履行职责的成员。"},{"i":29,"n":"第二十九条","txt":"宗教活动场所管理组织成员存在下列情形之一的，宗教活动场所应当及时予以撤换： （一）危害国家安全、公共安全，宣扬、支持、资助宗教极端主义，破坏民族团结、分裂国家，进行恐怖活动或者参与相关活动的； （二）干预行政、司法、教育和社会生活，违背公序良俗的； （三）破坏不同宗教之间以及本宗教内部和睦的； （四）受境外势力支配，擅自接受境外宗教团体或者机构委任教职，以及其他违背宗教的独立自主自办原则的； （五）违反国家有关规定接受境内外捐赠的； （六）参加非法宗教组织，从事非法宗教活动或者为非法宗教活动提供便利的； （七）组织、主持未经批准的在宗教活动场所外举行的宗教活动的； （八）不遵守本宗教的宗教团体制定的规章制度的； （九）不服从管理机关依法实施监督管理的； （十）其他违反法律、法规和规章的行为。 管理组织成员存在前款所列情形，但宗教活动场所未及时撤换的，宗教事务部门应当责令该宗教活动场所撤"},{"i":30,"n":"第三十条","txt":"宗教活动场所管理组织应当履行下列职责： （一）团结和教育信教公民热爱祖国，拥护中国共产党的领导，践行社会主义核心价值观，坚持我国宗教中国化方向，遵守宪法、法律、法规、规章和宗教事务管理的相关规定； （二）落实本宗教的宗教团体制定的规章制度； （三）建立健全本场所人员、财务、资产、会计、档案、治安、消防、文物保护、食品安全和卫生防疫等管理制度并组织落实； （四）组织开展宗教活动，处理日常事务，维护本场所的正常秩序； （五）管理本场所宗教教职人员和其他人员； （六）依照法律和国家有关规定管理使用本场所的财产； （七）协调本场所与社会其他方面的关系，维护本场所及其人员的合法权益； （八）法律、法规和规章规定的其他职责。"},{"i":31,"n":"第三十一条","txt":"凡涉及宗教教职人员聘任及解聘、举行大型宗教活动、成立法人组织、重大经济决策、大额支出、固定及无形资产处置、场所建设和对外交流等重大事项，宗教活动场所管理组织应当召开会议，集体讨论决定，并将会议记录及时报登记管理机关备案。 管理组织会议有三分之二以上的管理组织成员出席方可举行，其决议经管理组织全体成员三分之二以上通过方为有效。"},{"i":32,"n":"第三十二条","txt":"宗教活动场所应当建立健全人员管理制度，规范本场所人员的宗教活动、社会活动、对外交流等，加强本场所人员管理，对违规人员进行批评教育、责令改正并给予相应惩处。"},{"i":33,"n":"第三十三条","txt":"宗教活动场所接收常住或者暂住的人员应当严格把关、核查身份，并按照所在地有关规定及时申报办理户口登记或者居住登记。 宗教活动场所应当根据容纳能力及经济能力确定本场所宗教教职人员的定员数额，并报登记管理机关备案。"},{"i":34,"n":"第三十四条","txt":"宗教活动场所应当按照《宗教教职人员管理办法》相关规定，为担任或者离任本场所主要教职的宗教教职人员办理任职或者注销备案手续。"},{"i":35,"n":"第三十五条","txt":"宗教活动场所应当建立本场所常住人员档案，并将接收、变更、惩处宗教教职人员等有关情况，在三十日内报所在地宗教团体和登记管理机关备案。"},{"i":36,"n":"第三十六条","txt":"宗教活动场所应当建立学习制度，定期组织本场所人员学习中国共产党的方针政策、国家法律法规、中华优秀传统文化、宗教知识等。"},{"i":37,"n":"第三十七条","txt":"宗教活动场所应当鼓励、支持本场所人员参加宗教团体、宗教院校以及有关部门组织的教育培训。"},{"i":38,"n":"第三十八条","txt":"宗教活动场所组织、举行的宗教活动一般应当在本场所内开展，由宗教教职人员或者符合本宗教的全国性宗教团体规章制度规定的其他人员主持，按照教义教规进行。"},{"i":39,"n":"第三十九条","txt":"宗教活动场所开展宗教活动，应当遵守国家法律、法规、规章，讲经讲道内容应当适合我国国情特点和时代特征、融通中华优秀传统文化、体现社会主义核心价值观。"},{"i":40,"n":"第四十条","txt":"宗教活动场所应当在宗教活动中加强铸牢中华民族共同体意识宣传教育，加强国家通用语言文字的使用，促进民族团结进步，引导信教公民增强国家意识、公民意识、法治意识，正确区分民族风俗习惯和宗教信仰，不得利用宗教干预行政、司法、教育和社会生活。"},{"i":41,"n":"第四十一条","txt":"宗教活动场所组织、举行宗教活动，应当坚持规模适当、厉行节约、安全有序的原则，不得影响社会秩序、生产秩序和生活秩序。 寺观教堂举办大型宗教活动应当按照《宗教事务条例》等有关规定办理审批手续。"},{"i":42,"n":"第四十二条","txt":"宗教活动场所不得擅自到本场所外组织、举行宗教活动。"},{"i":43,"n":"第四十三条","txt":"宗教活动场所组织、举行以公益慈善为目的的宗教活动，应当报所在地宗教团体和登记管理机关备案后进行。"},{"i":44,"n":"第四十四条","txt":"寺观教堂开展培养宗教教职人员、学习时间在三个月以上的宗教教育培训应当按照《宗教事务条例》等有关规定办理，不得擅自变更授课教师、教学内容、招生范围、培训时间等。"},{"i":45,"n":"第四十五条","txt":"宗教活动场所应当规范设置和摆放陈列物，引导信教公民文明燃香，依法依规开展放生等活动。 宗教活动场所提供宗教服务不得收取不合理费用。"},{"i":46,"n":"第四十六条","txt":"寺观教堂编印、发送宗教内部资料性出版物和宗教用品应当符合《宗教事务条例》《印刷业管理条例》《内部资料性出版物管理办法》等有关规定。"},{"i":47,"n":"第四十七条","txt":"宗教活动场所从事互联网宗教信息服务，应当按照《互联网宗教信息服务管理办法》有关规定办理。"},{"i":48,"n":"第四十八条","txt":"宗教活动场所的建设活动应当符合国土空间规划和工程建设、生态环境保护、文物保护、消防、自然保护地等有关法律、法规。"},{"i":49,"n":"第四十九条","txt":"新建、改建、扩建、重建宗教活动场所或者宗教活动场所内建（构）筑物，按照《宗教事务条例》等有关规定经宗教事务部门批准后，还应当依法办理用地、规划、建设等手续。 宗教活动场所建设应当严格按照批准内容进行，不得未经审批建设或者擅自更改已批准规划方案、扩大建设规模、改变建筑风格。"},{"i":50,"n":"第五十条","txt":"宗教活动场所应当在建筑、雕塑、绘画、装饰等方面融汇中华文化、体现中国风格。"},{"i":51,"n":"第五十一条","txt":"宗教活动场所的建设应当坚持安全实用、俭朴适度、绿色环保的原则，防止造成资源浪费、增加群众负担、破坏生态环境。"},{"i":52,"n":"第五十二条","txt":"宗教活动场所的建设不得通过非法手段募集资金，不得向信教公民摊派，不得超出偿还能力进行借贷。"},{"i":53,"n":"第五十三条","txt":"宗教团体、寺观教堂拟在寺观教堂内修建大型露天宗教造像，应当按照《宗教事务条例》等有关规定办理。 禁止在寺观教堂外修建大型露天宗教造像。"},{"i":54,"n":"第五十四条","txt":"宗教活动场所的建设工程竣工，按照国家有关规定验收合格后，方能投入使用。 宗教活动场所使用的土地和所有的房屋等不动产，应当依法申请不动产登记。"},{"i":55,"n":"第五十五条","txt":"任何组织或者个人捐资修建宗教活动场所，均不享有该宗教活动场所的所有权、使用权，不得从该场所获得经济收益，不得干预该场所的内部事务。 禁止投资、承包经营宗教活动场所或者大型露天宗教造像。"},{"i":56,"n":"第五十六条","txt":"宗教活动场所应当建立健全安全管理制度，落实安全责任制，定期开展安全教育和安全隐患排查，确保人身安全、财产安全以及宗教活动安全。"},{"i":57,"n":"第五十七条","txt":"宗教活动场所管理组织负责本场所安全管理工作，管理组织负责人为本场所的安全工作第一责任人。"},{"i":58,"n":"第五十八条","txt":"宗教活动场所应当成立安全管理小组，具体组织实施安全工作，履行以下职责： （一）制定本场所的安全管理制度、事故处理和应急预案，明确安全责任； （二）按国家有关标准配置安全设施、器材，设置安全标志，并定期组织检验、维修，确保完好有效，检验、维修记录存档备查； （三）定期组织对本场所人员和信教公民进行安全宣传教育、安全培训和安全演练； （四）定期组织消防、食品、卫生、建筑、文物等安全检查，及时排查消除安全隐患，建立安全档案； （五）开展治安保卫工作，维护本场所的正常秩序； （六）制止非法宗教活动和邪教活动，抵制宗教极端思想，防范境外势力利用宗教进行渗透。 宗教活动场所内发生重大事故或者违犯宗教禁忌等伤害信教公民宗教感情、破坏民族团结、影响社会稳定的事件时，应当立即启动应急预案，向登记管理机关报告，并配合有关部门做好处置工作。"},{"i":59,"n":"第五十九条","txt":"寺观教堂主办大型宗教活动应当履行下列安全管理职责： （一）制定安全保障方案和突发事件应急预案并组织演练； （二）保障临时搭建的设施、建（构）筑物的安全； （三）全面排查、整治场所内外安全隐患，保证疏散通道、安全出口、疏散指示标志、应急照明和消防通道符合消防技术标准和管理规定，保持消防设施和消防器材配置齐全、完好有效； （四）配备与宗教活动安全工作需要相适应的安保人员和疏散引导员等相关工作人员； （五）开展必要的安全教育培训； （六）确保宗教活动现场安全、有序； （七）法律、法规和规章规定的其他安全职责。"},{"i":60,"n":"第六十条","txt":"宗教活动场所应当建立健全消防安全管理制度，加强明火、燃灯、焚纸、焚香等火源管理，强化用电安全，规范敷设电气线路，严格各种易燃、易爆物品的管理，禁止使用易燃可燃夹芯材料搭建临时设施、建（构）筑物。确需使用燃气的食堂、住宿等区域，应当采取安全有效防护措施。"},{"i":61,"n":"第六十一条","txt":"宗教活动场所应当建立食品安全和卫生防疫制度并落实制度规定，发生重大食品安全事件和疫情，应当及时向宗教事务管理、食品监管、卫生管理等部门或者乡级人民政府报告，并遵守相关规定。"},{"i":62,"n":"第六十二条","txt":"宗教活动场所应当加强建（构）筑物的日常维护、安全排查，及时消除安全隐患。 宗教活动场所不得擅自改变建（构）筑物的功能和用途。"},{"i":63,"n":"第六十三条","txt":"宗教活动场所应当按照文物保护法律、法规的规定，登记、管理、保护位于本场所或者由本场所管理的文物，防止文物遭到损毁或者遗失。 宗教事务部门应当协调有关部门保障宗教活动场所文物保护相关经费。"},{"i":64,"n":"第六十四条","txt":"宗教活动场所应当加强内部管理，按照有关法律、法规、规章的规定，建立健全管理制度，接受当地有关部门的指导、监督、检查。"},{"i":65,"n":"第六十五条","txt":"宗教活动场所应当设立监事（三名以上监事可以设立监事会），负责对本场所管理组织及其成员遵守法律、法规、规章和所属宗教的宗教团体、本场所制定的规章制度等情况进行监督。宗教活动场所管理组织召开会议，监事（监事会）应当列席。 监事由所在地宗教团体、信教公民代表和登记管理机关推选产生，任期与管理组织成员任期相同，期满可以连任。管理组织成员及其近亲属和财务人员不得担任监事。"},{"i":66,"n":"第六十六条","txt":"宗教事务部门应当对宗教活动场所遵守法律、法规、规章情况，建立和执行场所管理制度情况，登记项目变更情况，备案手续办理情况，以及宗教活动和涉外活动情况进行监督检查。 宗教事务部门应当指导乡级人民政府以及村民委员会、居民委员会履行宗教活动场所管理相应职责。"},{"i":67,"n":"第六十七条","txt":"全国性宗教团体应当根据宪法、法律、法规、规章和政策以及实际工作需要，在业务范围内制定本宗教的宗教活动场所规章制度，对场所管理组织成员监督及其任期、宗教教职人员、主要教职、宗教活动、财务和资产管理等作出具体规定。 宗教团体应当指导宗教活动场所建立健全并执行内部管理制度，督促内部管理存在问题的宗教活动场所进行整改。"},{"i":68,"n":"第六十八条","txt":"宗教活动场所应当接受宗教团体的教务指导以及信教公民的监督。"},{"i":69,"n":"第六十九条","txt":"宗教事务部门和宗教团体收到反映宗教活动场所违反法律、法规、规章或者宗教团体规章制度情况的，应当调查核实，依法依规予以处理。"},{"i":70,"n":"第七十条","txt":"公职人员在宗教活动场所管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":71,"n":"第七十一条","txt":"宗教活动场所违反本办法规定的，由登记管理机关或者有关部门按照《宗教事务条例》或者相关法律、法规的规定予以处罚。 擅自设立宗教活动场所的，由宗教事务部门会同有关部门按照《宗教事务条例》或者相关法律、法规的规定予以处罚。"},{"i":72,"n":"第七十二条","txt":"宗教活动场所管理组织成员违反本办法规定的，由登记管理机关责令改正；情节严重的，责令该场所予以撤换，是宗教教职人员的，按照《宗教事务条例》的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":73,"n":"第七十三条","txt":"本办法所称的所在地宗教团体是指宗教活动场所所在地的县（市、区、旗）宗教团体。 县（市、区、旗）没有相关宗教团体的，本办法规定的相应职责由设区的市（地、州、盟）宗教团体履行。 设区的市（地、州、盟）没有相关宗教团体的，相应职责由省、自治区、直辖市宗教团体履行。 省、自治区、直辖市没有相关宗教团体的，相应职责由全国性宗教团体履行。"},{"i":74,"n":"第七十四条","txt":"宗教活动场所的财务管理按照《宗教活动场所财务管理办法》规定执行。"},{"i":75,"n":"第七十五条","txt":"本办法由国家宗教事务局负责解释。"},{"i":76,"n":"第七十六条","txt":"本办法自2023年9月1日起施行。2005年国家宗教事务局公布的《宗教活动场所设立审批和登记办法》同时废止。"}],"zongjiaohuodongchangsuoshelishenpihedengjibanfa":[{"i":1,"n":"第一条","txt":"根据《宗教事务条例》的有关规定,制定本办法。"},{"i":2,"n":"第二条","txt":"宗教活动场所分为寺院、宫观、清真寺、教堂和其他固定宗教活动处所两类。两类宗教活动场所的具体区分标准，由各省、自治区、直辖市人民政府宗教事务部门根据本地实际情况制定，报国家宗教事务局备案。"},{"i":3,"n":"第三条","txt":"筹备设立宗教活动场所，一般应当由拟设立地的县（市、区、旗）宗教团体提出申请。如拟设立地的县（市、区、旗）无宗教团体的，可由拟设立地的设区的市（地、州、盟）宗教团体提出申请；拟设立地的市（地、州、盟）无宗教团体的，可由拟设立地的省、自治区、直辖市宗教团体提出申请；拟设立地的省、自治区、直辖市无宗教团体的，可由全国性宗教团体提出申请。 县级人民政府宗教事务部门是筹备设立宗教活动场所申请的受理机关。"},{"i":4,"n":"第四条","txt":"申请筹备宗教活动场所的宗教团体应当提出筹备组织组建方案，在申请获批准后，正式成立筹备组织，负责筹备事宜。筹备组织应当由本宗教团体的有关人员、拟主持宗教活动的宗教教职人员或者符合本宗教规定的其他人员、拟设立地信教公民代表等组成。"},{"i":5,"n":"第五条","txt":"申请筹备设立宗教活动场所，应当填写《宗教活动场所筹备设立申请表》，同时提交下列材料： （一）拟设立地信教公民的有关情况说明； （二）拟主持宗教活动的宗教教职人员或者符合本宗教规定的其他人员的基本情况及户籍、居民身份和教职身份证明； （三）拟成立的筹备组织成员的基本情况、户籍和居民身份证明(属宗教教职人员的，还应当提供教职身份证明)； （四）必要的资金证明； （五）拟设立地点和拟设立场所的可行性说明； （六）需要提供的其他有关材料。"},{"i":6,"n":"第六条","txt":"县级人民政府宗教事务部门在受理筹备设立宗教活动场所的申请后，对拟同意的，应当征求拟设立地乡镇人民政府、街道办事处的意见。"},{"i":7,"n":"第七条","txt":"宗教活动场所的筹备设立事项，应当在批准的筹备设立期限内完成。筹备组织应当将筹备情况及时向设立地的县级人民政府宗教事务部门报告。 设立地的县级以上地方人民政府宗教事务部门应当对筹备设立的进展情况进行监督检查。"},{"i":8,"n":"第八条","txt":"宗教活动场所在登记前，应当由筹备组织负责，民主协商成立该场所的管理组织。管理组织应当由宗教教职人员或者符合本宗教规定的主持宗教活动的其他人员和设立地信教公民代表等组成。"},{"i":9,"n":"第九条","txt":"宗教活动场所完成筹备后，由该场所管理组织负责向所在地县级人民政府宗教事务部门申请登记。 申请登记宗教活动场所，应填写《宗教活动场所登记申请表》，同时提交下列材料： （一）民主协商成立管理组织的情况说明； （二）管理组织成员的户籍和居民身份证明； （三）主持宗教活动的宗教教职人员或者符合本宗教规定的其他人员的户籍、居民身份和教职身份证明； （四）有关规章制度文本； （五）场所房屋等建筑物的有关证明（属新建的，应当提供规划、建筑、消防等部门的验收合格证明；属改扩建的，应当提供房屋所有权或者使用权证明和消防安全验收合格证明；属租借的，应当提供消防安全验收合格证明和一年期以上的使用权证明）； （六）合法的经济来源的情况说明。"},{"i":10,"n":"第十条","txt":"《宗教活动场所登记证》和有关表格，由各省、自治区、直辖市人民政府宗教事务部门按照国家宗教事务局制定的式样印制。 《宗教活动场所登记证》不得涂改、转让、出借。证书遗失的，应当及时向登记管理机关申请补办。"},{"i":11,"n":"第十一条","txt":"在《宗教事务条例》施行前，已按照《宗教活动场所管理条例》有关规定登记的宗教活动场所，不再重新进行登记。"},{"i":12,"n":"第十二条","txt":"其他固定宗教活动处所需要变更为寺院、宫观、清真寺、教堂的，须按照《宗教事务条例》第十三条规定的寺观教堂的审批程序办理，并按照《宗教事务条例》第十六条规定办理变更登记。"},{"i":13,"n":"第十三条","txt":"拟在直辖市的区（县、市）筹备设立宗教活动场所，可直接向直辖市的区（县、市）人民政府宗教事务部门提出申请。直辖市的区（县、市）人民政府宗教事务部门可以批准筹备设立其他固定宗教活动处所。 直辖市的区（县、市）人民政府宗教事务部门是当地宗教活动场所的登记管理机关。"},{"i":14,"n":"第十四条","txt":"拟筹备设立宗教活动场所的地区，如未设置设区的市级人民政府，筹备设立宗教活动场所的申请，由县级人民政府宗教事务部门审核后，直接报省级人民政府宗教事务部门审批。"},{"i":15,"n":"第十五条","txt":"本办法自公布之日起施行。1994年国务院宗教事务局颁发的《宗教活动场所登记办法》同时废止。"}],"zongjiaohuodongchangsuocaiwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范宗教活动场所的财务行为，加强宗教活动场所的财务管理，维护宗教活动场所和信教公民的合法权益，根据《中华人民共和国会计法》《宗教事务条例》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称宗教活动场所，是指按照《宗教事务条例》等规定登记的寺院、宫观、清真寺、教堂和其他固定宗教活动处所。"},{"i":3,"n":"第三条","txt":"宗教活动场所财务管理应当坚持依法依规、真实完整、安全有效的原则。"},{"i":4,"n":"第四条","txt":"宗教活动场所应当建立健全内部财务管理制度。宗教活动场所内部财务管理制度应当报为其办理宗教活动场所登记的宗教事务部门（以下称登记管理机关）备案。"},{"i":5,"n":"第五条","txt":"宗教活动场所财务管理主要包括下列任务： （一）建立、健全内部财务管理制度，对本场所的财务活动进行管理和监督； （二）进行会计核算处理，编制财务会计报告，实施财务公开，如实反映本场所财务状况； （三）合理编制预算，统筹安排、节约使用资金，保障本场所正常运转； （四）规范本场所收支管理，严格审批程序； （五）规范本场所资产管理，防止资产流失，维护合法权益。"},{"i":6,"n":"第六条","txt":"宗教活动场所的合法财产、收益受法律保护，任何组织或者个人不得侵占、哄抢、私分、损毁或者非法查封、扣押、冻结、没收、处分。"},{"i":7,"n":"第七条","txt":"宗教事务部门、财政部门依法对宗教活动场所的财务管理进行指导和监督。"},{"i":8,"n":"第八条","txt":"宗教活动场所应当建立健全财务管理机构，配备会计、出纳、资产管理等必要的财务人员。财务管理机构在本场所管理组织的领导下对本场所的财务进行统一管理。"},{"i":9,"n":"第九条","txt":"宗教活动场所财务管理机构一般由财务管理机构负责人以及财务人员等组成。会计、出纳应当具备从事会计工作所需的专业能力。 宗教活动场所财务管理机构的人员组成应当遵循不相容岗位分离原则和任职回避的有关规定。 曾因发生与会计职务有关的违法行为被依法追究刑事责任，或者处于不得从事会计工作行政处罚期间的人员，不得担任宗教活动场所的财务管理机构负责人、会计、出纳等。"},{"i":10,"n":"第十条","txt":"宗教活动场所管理组织负责人是本场所财务管理责任人，应当全面负责本场所的财务管理，支持财务管理机构、财务人员依法实施财务管理。"},{"i":11,"n":"第十一条","txt":"宗教活动场所财务管理机构负责人应当熟悉国家有关财务管理的法律法规和政策，具体负责并组织开展本场所财务管理工作。"},{"i":12,"n":"第十二条","txt":"宗教活动场所财务人员应当依法履行职责，抵制违反国家有关财务、资产、会计规定和本办法规定的行为。任何组织或者个人不得对依法履行职责的宗教活动场所财务人员进行打击报复。"},{"i":13,"n":"第十三条","txt":"宗教活动场所会计应当按照国家统一的会计制度规定的程序和要求进行会计核算处理工作，保证核算反映的会计信息合法、真实、准确、及时、完整。"},{"i":14,"n":"第十四条","txt":"宗教活动场所出纳应当依法依规履行办理本场所的现金收付、银行结算，保管库存现金、有价证券等职责。"},{"i":15,"n":"第十五条","txt":"宗教活动场所更换财务人员，应当由本场所管理组织集体研究决定，并监督其办理交接手续。"},{"i":16,"n":"第十六条","txt":"宗教活动场所应当执行国家有关民间非营利组织的会计制度，依法设置会计账簿，并保证其真实、完整。"},{"i":17,"n":"第十七条","txt":"宗教活动场所应当采用借贷记账法进行会计核算。"},{"i":18,"n":"第十八条","txt":"会计核算应当以记录经济业务活动的原始凭证为依据，做到真实、完整。 任何组织或者个人不得以任何方式授意、指使、强令宗教活动场所会计伪造、变造会计凭证、会计账簿，编制虚假财务会计报告或者隐匿、故意销毁依法应当保存的会计凭证、会计账簿、财务会计报告。"},{"i":19,"n":"第十九条","txt":"宗教活动场所应当按照国家会计档案管理制度，建立会计凭证、会计账簿、财务会计报告和其他会计资料的档案，并妥善保管。"},{"i":20,"n":"第二十条","txt":"宗教活动场所根据工作需要，可以委托经批准设立的机构代理记账。"},{"i":21,"n":"第二十一条","txt":"宗教活动场所一般应当制定本场所的年度预算，报登记管理机关备案，并以适当方式通报当地信教公民。"},{"i":22,"n":"第二十二条","txt":"宗教活动场所的年度预算由收入预算和支出预算组成。预算一般应当自求收支平衡，量入为出。"},{"i":23,"n":"第二十三条","txt":"宗教活动场所的收入包括下列类型： （一）提供宗教服务的收入和出售宗教活动场所门票的收入； （二）按照国家有关规定接受境内外组织和个人捐赠的收入； （三）经销宗教用品、宗教艺术品和宗教出版物，出租宗教活动场所资产取得的收入； （四）政府补助取得的收入； （五）其他合法收入。"},{"i":24,"n":"第二十四条","txt":"宗教活动场所各项收入应当及时入账，纳入本场所财务管理。"},{"i":25,"n":"第二十五条","txt":"宗教活动场所应当开立单位银行结算账户，并将银行账户信息报登记管理机关备案。 宗教活动场所各项收入应当存入单位银行结算账户，不得存入个人账户，不得通过个人的支付宝、微信等互联网支付方式收取。"},{"i":26,"n":"第二十六条","txt":"宗教活动场所接受境内外组织和个人的捐赠，应当遵守国家有关规定，并给捐赠人出具省级人民政府宗教事务部门统一印制编号的收据，加盖本场所印章。捐赠人匿名或者放弃收据的，宗教活动场所应当做好相关记录。接受的捐赠应当及时入账。 宗教活动场所设有捐款箱的，应当指定三人管理捐款箱。开启捐款箱应当有三人同时在场，当场清点捐款数额并登记，由三人签字后交本场所财务人员入账。 宗教活动场所发起设立的慈善组织接受慈善捐赠，应当符合《中华人民共和国慈善法》有关规定。"},{"i":27,"n":"第二十七条","txt":"宗教教职人员和其他任何人员不得将宗教活动场所的财产据为己有。 宗教教职人员接收的捐赠给宗教活动场所的钱物，应当按照本办法第二十六条的规定出具收据并及时入账。"},{"i":28,"n":"第二十八条","txt":"宗教活动场所应当对取得的政府补助收入单独核算，严格管理。"},{"i":29,"n":"第二十九条","txt":"宗教活动场所应当依法办理税务登记和纳税申报，依法纳税，按照国家有关规定享受税收优惠。"},{"i":30,"n":"第三十条","txt":"宗教活动场所的支出包括下列类型： （一）举行宗教活动发生的支出； （二）开展基本建设发生的支出； （三）宗教教职人员生活支出、工作人员报酬支出以及水费、电费等日常性支出； （四）进购宗教用品、宗教艺术品和宗教出版物的支出； （五）从事公益慈善事业和其他社会服务的支出； （六）其他合法支出。"},{"i":31,"n":"第三十一条","txt":"宗教活动场所的收入应当用于与本场所宗旨相符的活动，不得用于分配，不得用于法律法规禁止的领域、活动。"},{"i":32,"n":"第三十二条","txt":"宗教活动场所应当制定并严格执行财务支出审批制度。 宗教活动场所的支出应当经本场所财务管理机构负责人签字同意，报本场所管理组织负责人审批。 宗教活动场所的大额支出应当经本场所管理组织集体研究决定，需要听取信教公民意见的，应当征求信教公民意见。大额支出数额标准由宗教活动场所在其内部财务管理制度中规定。"},{"i":33,"n":"第三十三条","txt":"宗教活动场所取得的政府补助收入，应当专款专用，不得挪作他用。"},{"i":34,"n":"第三十四条","txt":"宗教活动场所款项的出借和借入应当经本场所管理组织集体研究决定并形成会议纪要。借贷双方应当签订合法有效的借款合同。 宗教活动场所借入款项应当保证按期偿还。 宗教活动场所出借款项数额较大的，应当要求借方提供担保或者抵押。 宗教活动场所不得参与非法民间借贷以及任何形式的非法金融活动。"},{"i":35,"n":"第三十五条","txt":"宗教活动场所应当制定资产管理制度，确保本场所的资产安全。"},{"i":36,"n":"第三十六条","txt":"宗教活动场所的资产包括流动资产、固定资产、无形资产、文物文化资产等。"},{"i":37,"n":"第三十七条","txt":"宗教活动场所应当加强对流动资产的管理，建立健全现金、银行存款、应收款项和存货等流动资产的管理制度。"},{"i":38,"n":"第三十八条","txt":"宗教活动场所应当对固定资产登记造册，设置固定资产明细账或者固定资产卡片，定期对固定资产清查盘点。 宗教活动场所固定资产的出租、转让和报废应当经本场所管理组织集体研究决定。"},{"i":39,"n":"第三十九条","txt":"宗教活动场所转让无形资产，应当经本场所管理组织集体研究决定，取得的收入计入本场所收入。"},{"i":40,"n":"第四十条","txt":"宗教活动场所使用的土地和拥有的房屋等不动产，应当依法申请不动产登记，领取不动产权证书；产权变更、转移的，应当及时办理变更、转移登记。用于宗教活动的房屋、构筑物及其附属的宗教教职人员生活用房不得转让、抵押或者作为实物投资。"},{"i":41,"n":"第四十一条","txt":"宗教活动场所管理收藏的文物应当登记入账，按照文物保护有关规定妥善保护利用。"},{"i":42,"n":"第四十二条","txt":"宗教活动场所对依法占有的属于国家、集体所有的财产以及接受政府补助形成的各类资产，应当按照法律和国家有关规定管理和使用。"},{"i":43,"n":"第四十三条","txt":"宗教事务部门和财政部门应当指导宗教活动场所建立健全内部财务管理制度，检查制度执行情况，督促存在问题的宗教活动场所进行整改，依法对违法违规行为进行处罚。 宗教事务部门、财政部门以及有关政府部门可以组织对宗教活动场所进行财务、资产检查和审计。"},{"i":44,"n":"第四十四条","txt":"宗教团体应当协助、督促宗教活动场所建立健全并执行内部财务管理制度，帮助财务管理存在问题的宗教活动场所进行整改。"},{"i":45,"n":"第四十五条","txt":"宗教活动场所应当接受宗教事务部门、财政部门以及有关政府部门对其财务管理的指导、监督、检查。"},{"i":46,"n":"第四十六条","txt":"宗教活动场所应当于每年年度终了后三个月内向登记管理机关提供上年度财务会计报告，以及接受和使用捐赠情况等。"},{"i":47,"n":"第四十七条","txt":"宗教活动场所应当定期以适当方式公布财务收支情况和接受、使用捐赠情况，接受本场所宗教教职人员、捐赠人和信教公民的监督。捐赠人和信教公民提出的合理意见和建议，场所管理组织应当采纳，并以适当方式向捐赠人和信教公民反馈。 登记为法人的宗教活动场所，场所财务管理机构及其工作应当接受本场所监事（监事会）的监督。"},{"i":48,"n":"第四十八条","txt":"宗教活动场所的财务人员有权按照《中华人民共和国会计法》以及其他有关规定行使财务监督权，对涉及财务的违法行为提出意见并向本场所登记管理机关和其他有关部门反映。"},{"i":49,"n":"第四十九条","txt":"宗教活动场所管理组织负责人和财务管理机构负责人离任时，登记管理机关应当组织对其进行财务审计。"},{"i":50,"n":"第五十条","txt":"宗教活动场所注销或者终止时，应当进行清算。 宗教活动场所清算时，应当在其登记管理机关和有关部门的监督指导下，成立清算小组，对本场所的财产、债权、债务等进行全面清理，编制财产目录和债权、债务清单，提出财产作价依据和债权、债务处理办法，做好资产的移交、接收、划转和相关工作，并妥善处理各项遗留问题。 清算期间，宗教活动场所不得开展清算以外的活动。 清算后的剩余财产应当用于与该场所宗旨相符的事业。"},{"i":51,"n":"第五十一条","txt":"宗教事务部门、财政部门的工作人员以及其他承担管理职责的公职人员在宗教活动场所财务管理工作中滥用职权、玩忽职守、徇私舞弊，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"宗教活动场所违反本办法规定的，由登记管理机关和财政部门按照《中华人民共和国会计法》以及《宗教事务条例》的有关规定予以处罚。"},{"i":53,"n":"第五十三条","txt":"宗教活动场所相关人员违反本办法规定的，由登记管理机关责令改正；情节严重的，责令该场所撤换直接负责的主管人员，是宗教教职人员的，按照《宗教事务条例》的有关规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"本办法由国家宗教事务局、财政部负责解释。"},{"i":55,"n":"第五十五条","txt":"本办法自2022年6月1日起施行。2010年1月11日国家宗教事务局公布的《宗教活动场所财务监督管理办法（试行）》同时废止。"}],"zongjiaoyuanxiaoxueweishouyubanfa":[{"i":1,"n":"第一条","txt":"为了加强宗教专门人才培养，提高宗教院校教育教学水平，依据国家有关法律法规，按照宗教与教育相分离的原则，结合宗教院校实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称宗教院校，是指依据《宗教事务条例》和《宗教院校设立办法》设立，由宗教团体举办，培养宗教教职人员和宗教方面其他专门人才的全日制高等院校。"},{"i":3,"n":"第三条","txt":"遵守宪法和法律，爱国爱教，坚持独立自主自办原则，思想品德良好，有志于宗教事业的宗教院校本科以上毕业生，可以按照本办法规定申请相应的学位。"},{"i":4,"n":"第四条","txt":"宗教院校学位分学士、硕士、博士三级。 宗教院校学位名称由宗教名称、学科名称、学位等级三部分组成。 宗教院校学位名称由各全国性宗教团体确定，报国家宗教事务局备案。"},{"i":5,"n":"第五条","txt":"申请攻读宗教院校上一级学位，一般应当先取得下一级学位。"},{"i":6,"n":"第六条","txt":"宗教院校认可普通高等学校和学术研究机构授予的学位。"},{"i":7,"n":"第七条","txt":"各全国性宗教团体的教育委员会设立宗教院校学位工作小组，负责本宗教的宗教院校学位授予工作。 宗教院校学位工作小组由宗教团体有关负责人、宗教院校中、高级职称人员及有关方面专家学者组成。学位工作小组成员名单由全国性宗教团体报国家宗教事务局备案。"},{"i":8,"n":"第八条","txt":"宗教院校学位授予工作应当坚持公正规范、公开透明原则。"},{"i":9,"n":"第九条","txt":"各全国性宗教团体应当依照本办法制定本宗教的宗教院校学位授予实施细则和学位工作小组工作规则，报国家宗教事务局备案。"},{"i":10,"n":"第十条","txt":"宗教院校本科毕业生，成绩合格，通过学士论文评审，并符合下列条件者，授予学士学位： （一）较好地掌握本宗教的基础理论和教义教规； （二）初步具有从事宗教研究工作的能力； （三）具备从事宗教教务活动的基本能力。"},{"i":11,"n":"第十一条","txt":"宗教院校学生完成硕士学位研究生学业，通过硕士学位研究生课程考试和论文答辩，并符合下列条件者，授予硕士学位： （一）系统掌握本宗教的基础理论和教义教规，在其研究领域有较深的造诣； （二）具有从事宗教研究工作的能力； （三）具备较强的从事宗教教务活动的能力。"},{"i":12,"n":"第十二条","txt":"宗教院校学生完成博士学位研究生学业，通过博士学位研究生课程考试和论文答辩，并符合下列条件者，授予博士学位： （一）系统深入掌握本宗教的基础理论和教义教规，在其研究领域有突出成果； （二）具有独立从事宗教研究工作的能力； （三）具备系统扎实的从事宗教教务活动的能力。"},{"i":13,"n":"第十三条","txt":"申请宗教院校学位，还应当具备一定的外国语或古汉语水平，具体标准由各全国性宗教团体制定。"},{"i":14,"n":"第十四条","txt":"授予学位的宗教院校，应当具有学位授予资格。 符合条件的高等宗教院校可按程序申请学位授予资格。"},{"i":15,"n":"第十五条","txt":"申请学位授予资格，由宗教院校填写宗教院校学位授予资格申请表，并提交举办该院校的宗教团体，该宗教团体审核后报本宗教的学位工作小组。全国性宗教团体举办的宗教院校申请学位授予资格，由该院校直接报本宗教的学位工作小组。 宗教院校学位工作小组按照本宗教的宗教院校学位授予实施细则和学位工作小组工作规则，对宗教院校的申请进行审查，对可授予学位的院校、可授予学位的学科及相应学位提出意见，并报全国性宗教团体教育委员会审定。全国性宗教团体教育委员会对同意授予学位资格的宗教院校，颁发宗教院校学位授予资格证书，并由全国性宗教团体报国家宗教事务局备案。"},{"i":16,"n":"第十六条","txt":"取得学位授予资格的宗教院校，依据可授予的学位，设立相应的学士学位评定委员会、硕士学位论文答辩委员会和博士学位论文答辩委员会。 宗教院校学士学位评定委员会、硕士学位论文答辩委员会和博士学位论文答辩委员会的组成人员由该宗教院校提出，经举办该宗教院校的宗教团体审核后，报本宗教的学位工作小组审定。全国性宗教团体举办的宗教院校可直接报本宗教的学位工作小组审定。 宗教院校学士学位评定委员会、硕士学位论文答辩委员会和博士学位论文答辩委员会组成人员名单确定后，由全国性宗教团体报国家宗教事务局备案。"},{"i":17,"n":"第十七条","txt":"宗教院校的学士学位评定委员会负责评定学士学位。 宗教院校的硕士学位论文答辩委员会、博士学位论文答辩委员会分别负责审查硕士、博士学位论文，组织答辩，对是否授予硕士学位或博士学位提出意见，报本宗教的学位工作小组审核，经全国性宗教团体教育委员会审定后，由全国性宗教团体报国家宗教事务局备案。"},{"i":18,"n":"第十八条","txt":"具有博士学位授予资格的宗教院校可以授予国内外知名人士名誉博士学位。授予名誉博士学位应当由宗教院校提名，并经本宗教的学位工作小组审核，报全国性宗教团体教育委员会审定，由全国性宗教团体报国家宗教事务局备案。"},{"i":19,"n":"第十九条","txt":"在宗教院校学习的境外留学生，其学位授予按照本办法的规定办理。"},{"i":20,"n":"第二十条","txt":"对已取得学位授予资格的宗教院校，宗教学位工作小组确认其不能保证所授学位的学业水平，报全国性宗教团体教育委员会审定后，可停止或撤销该院校相应的学位授予资格，并由全国性宗教团体报国家宗教事务局备案。"},{"i":21,"n":"第二十一条","txt":"对已经授予的学位，发现有严重违反本办法规定的，由授予其学士学位的评定委员会或授予其硕士、博士学位的全国性宗教团体教育委员会予以撤销。"},{"i":22,"n":"第二十二条","txt":"学士学位评定委员会成员、硕士学位论文答辩委员会成员、博士学位论文答辩委员会成员和学位工作小组成员有违反学位授予程序和规定行为的，由全国性宗教团体根据情节轻重，分别责令改正、取消委员会成员或工作小组成员资格，并宣布违规授予的学位无效。 学士学位评定委员会、硕士学位论文答辩委员会、博士学位论文答辩委员会和学位工作小组有违反学位授予程序和规定行为的，由全国性宗教团体根据情节轻重，分别责令限期改正、暂停学位授予工作、重组委员会或工作小组，并宣布违规授予的学位无效。"},{"i":23,"n":"第二十三条","txt":"宗教院校学位授予资格证书由各全国性宗教团体印制、各全国性宗教团体教育委员会颁发，在宗教界内部有效。 宗教院校学位证书由各全国性宗教团体印制、宗教院校颁发，在宗教界内部有效。"},{"i":24,"n":"第二十四条","txt":"藏传佛教院校学衔授予办法另行规定。"},{"i":25,"n":"第二十五条","txt":"本办法自2013年1月1日起施行。"}],"zongjiaoyuanxiaojiaoshizigerendinghezhichengpingsh5544e2":[{"i":1,"n":"第一条","txt":"为了加强宗教院校教师队伍建设，提高宗教院校的规范化管理水平，依据国家有关法律法规，按照宗教与教育相分离的原则，结合宗教院校实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称宗教院校，是指依据《宗教事务条例》和《宗教院校设立办法》设立，由宗教团体举办，培养宗教教职人员和宗教方面其他专门人才的全日制院校。"},{"i":3,"n":"第三条","txt":"在宗教院校专门从事教育教学工作的人员，应当具备宗教院校教师资格。 按《教师资格条例》获得普通高等学校教师资格的人员和按国家有关专业技术资格评定办法获得专业技术职称的人员，视为已具备宗教院校教师资格。"},{"i":4,"n":"第四条","txt":"宗教院校教师职称实行评审聘任制度。 宗教院校教师职称分为助教、讲师、副教授、教授。"},{"i":5,"n":"第五条","txt":"各全国性宗教团体的教育委员会设立宗教院校教师资格认定工作小组和宗教院校教师职称评审工作小组，分别负责本宗教的宗教院校教师资格认定和讲师以上职称评审工作。 宗教院校根据宗教院校教师职称评审工作小组的评审结果，负责本校讲师、副教授和教授职称的聘任工作，并负责本校助教职称的评审聘任工作。"},{"i":6,"n":"第六条","txt":"宗教院校教师资格认定工作小组由宗教团体有关负责人、宗教院校中、高级职称人员及有关方面专家学者组成，宗教院校教师职称评审工作小组由宗教团体有关负责人、宗教院校高级职称人员及有关方面专家学者组成。 宗教院校教师资格认定工作小组成员名单和职称评审工作小组成员名单由全国性宗教团体报国家宗教事务局备案。"},{"i":7,"n":"第七条","txt":"宗教院校教师资格认定和职称评审工作应当坚持公正规范、公开透明原则。"},{"i":8,"n":"第八条","txt":"各全国性宗教团体应当依照本办法制定本宗教的宗教院校教师资格认定实施细则和职称评审实施细则，以及宗教院校教师资格认定工作小组工作规则和职称评审工作小组工作规则，并报国家宗教事务局备案。"},{"i":9,"n":"第九条","txt":"国家宗教事务局和省级人民政府宗教事务部门按照各自职责对宗教院校教师资格认定和职称评审聘任工作进行监督指导。"},{"i":10,"n":"第十条","txt":"申请宗教院校教师资格，应当具备下列条件： （一）遵守宪法和法律，爱国爱教，坚持独立自主自办原则，思想品德良好，愿意从事宗教院校教育工作； （二）有本科以上学历或同等学力； （三）在宗教团体或宗教院校、宗教活动场所工作一年以上； （四）具备教育教学工作所必需的基本素质和能力； （五）熟悉国家宗教方面的法律、法规、规章和政策； （六）能用普通话进行教学与交流，少数民族地区可适当放宽； （七）身体健康，能胜任工作。"},{"i":11,"n":"第十一条","txt":"申请宗教院校教师资格，由本人向户籍地或拟任教宗教院校所在地的省、自治区、直辖市宗教团体提出申请。省、自治区、直辖市宗教团体提出审核意见后，报本宗教的宗教院校教师资格认定工作小组。 拟在全国性宗教团体举办的宗教院校任教的，可直接向全国性宗教团体提出申请。"},{"i":12,"n":"第十二条","txt":"申请宗教院校教师资格，应当填写宗教院校教师资格认定申请表，并提交下列材料： （一）户籍证明、身份证明和学历证明，宗教教职人员应同时提交宗教教职人员证书； （二）二级以上医院出具的体检合格证明； （三）毕业院校出具的毕业鉴定表，以及所在单位或户籍所在地乡（镇）人民政府、街道办事处出具的个人品行情况材料。"},{"i":13,"n":"第十三条","txt":"宗教院校教师资格认定工作小组按照本宗教的宗教院校教师资格认定实施细则和工作小组工作规则，对申请人资格进行审查。经审查符合条件的，由该工作小组组织资格考试。考试成绩合格的，由全国性宗教团体的教育委员会颁发宗教院校教师资格证书。"},{"i":14,"n":"第十四条","txt":"助教主要履行下列职责： （一）承担教学辅导工作； （二）经学校批准，承担某些课程的部分或全部教学工作； （三）参与组织和指导学生实习等方面的工作； （四）担任教学、研究等方面的其他工作。"},{"i":15,"n":"第十五条","txt":"讲师主要履行下列职责： （一）承担教学工作； （二）参与编写课程辅导材料； （三）指导学生完成毕业论文； （四）协助教授、副教授指导研究生、进修教师。"},{"i":16,"n":"第十六条","txt":"副教授主要履行下列职责： （一）承担教学工作； （二）担任研究课题负责人，负责或参加审阅学术论文； （三）主持或参与编写、审议教材和教学参考书； （四）根据需要，指导硕士研究生、进修教师，协助教授指导博士研究生。"},{"i":17,"n":"第十七条","txt":"教授主要履行下列职责： （一）承担教学工作； （二）担任研究课题负责人，负责审阅学术论文； （三）主持编写、审议教材和教学参考书； （四）根据需要，指导硕士、博士研究生和进修教师。"},{"i":18,"n":"第十八条","txt":"宗教院校教师除承担教育教学及相关研究工作外，还应当负责学生思想政治工作。"},{"i":19,"n":"第十九条","txt":"获得助教职称，应当具备下列条件： （一）获得学士学位且经过一年以上见习期试用，或本科毕业且担任教学工作二年以上，或硕士研究生毕业； （二）能胜任助教职责。"},{"i":20,"n":"第二十条","txt":"获得讲师职称，应当具备下列条件： （一）担任助教四年以上，或硕士研究生毕业且担任助教二年以上，或获得博士学位； （二）有一定的外国语或古汉语水平； （三）能胜任讲师职责。"},{"i":21,"n":"第二十一条","txt":"获得副教授职称，应当具备下列条件： （一）担任讲师五年以上，或获得博士学位且担任讲师二年以上； （二）能阅读本专业的外文或古汉语书籍； （三）发表过有一定水平的研究论文或出版过著作、教科书，或教学水平较高； （四）能胜任副教授职责。"},{"i":22,"n":"第二十二条","txt":"获得教授职称，应当具备下列条件： （一）担任副教授五年以上； （二）熟练掌握一门外国语或精通古汉语； （三）发表、出版过有创见性或较高水平的研究论文、著作、教科书，或教学成绩卓著； （四）能胜任教授职责。"},{"i":23,"n":"第二十三条","txt":"教学或研究等方面成绩突出的教师，可以破格申请宗教院校教师职称，具体办法由各全国性宗教团体制定。"},{"i":24,"n":"第二十四条","txt":"申请宗教院校教师职称，由本人向所在宗教院校提交宗教院校教师职称申请表，并提供下列材料： （一）宗教院校教师资格证书； （二）户籍证明、身份证明、学历证明、学位证明和职称证明； （三）教学或学术成果。"},{"i":25,"n":"第二十五条","txt":"助教职称的评审聘任，由宗教院校负责办理。 讲师以上职称的评审，由宗教院校提出初审意见，经该院校所在地的省、自治区、直辖市宗教团体审核并征求所在地的省级人民政府宗教事务部门意见后，报本宗教的宗教院校教师职称评审工作小组评审。 全国性宗教团体举办的宗教院校的讲师以上职称评审，由该院校直接报本宗教的宗教院校教师职称评审工作小组评审。"},{"i":26,"n":"第二十六条","txt":"宗教院校教师职称评审工作小组按照本宗教的宗教院校教师职称评审实施细则和工作小组工作规则，对申请讲师以上职称的人员进行评审，并出具评审意见。通过评审的，由全国性宗教团体的教育委员会颁发宗教院校教师职称证书，并书面通知拟聘该教师的宗教院校。"},{"i":27,"n":"第二十七条","txt":"宗教院校根据教育教学工作岗位需要和规定职数，与获得相应职称资格的宗教院校教师协商签定岗位聘任协议，明确聘任待遇、聘任期限等双方权利义务，并颁发聘任证书。"},{"i":28,"n":"第二十八条","txt":"按照本办法获得职称并受聘任教的宗教院校教师，其工资和各项待遇所需经费，由所在宗教院校和举办该宗教院校的宗教团体筹措、保障。"},{"i":29,"n":"第二十九条","txt":"各全国性宗教团体应当在宗教院校教师职称评审工作小组评审结束后三十日内，将评审情况及结果报国家宗教事务局备案。 宗教院校应当在每年第三季度将聘用教师情况报举办该宗教院校的宗教团体和相应的政府宗教事务部门备案。"},{"i":30,"n":"第三十条","txt":"宗教院校应加强对教师的管理，对教师的政治素质、道德品行、教学水平、工作绩效等进行考核。考核结果记入个人档案，作为晋级、调薪、奖惩和解聘、续聘的依据。"},{"i":31,"n":"第三十一条","txt":"已获得宗教院校教师资格，有下列情形之一的，由认定其教师资格的宗教院校教师资格认定工作小组撤销其宗教院校教师资格： （一）受到刑事处罚的； （二）违反国家宗教方面的法律、法规、规章和政策，情节严重的； （三）弄虚作假、骗取宗教院校教师资格的； （四）品行不良，造成恶劣影响的。 被撤销宗教院校教师资格的，自撤销之日起五年内不得重新申请宗教院校教师资格。"},{"i":32,"n":"第三十二条","txt":"弄虚作假获得宗教院校教师职称的，由评审其职称的宗教院校教师职称评审工作小组撤销其职称，自撤销之日起三年内不得重新申请宗教院校教师职称。"},{"i":33,"n":"第三十三条","txt":"宗教院校教师资格认定工作小组成员或职称评审工作小组成员有违反资格认定或职称评审程序和规定行为的，由全国性宗教团体根据情节轻重，分别责令改正、取消工作小组成员资格，并宣布违规认定或评审的结果无效。 宗教院校教师资格认定工作小组或职称评审工作小组有违反资格认定或职称评审程序和规定行为的，由全国性宗教团体根据情节轻重，分别责令限期改正、暂停认定或评审工作、重组工作小组，并宣布违规认定或评审的结果无效。"},{"i":34,"n":"第三十四条","txt":"宗教院校教师资格证书、宗教院校教师职称证书由各全国性宗教团体印制，在宗教界内部有效。 宗教院校教师资格认定申请表、宗教院校教师职称申请表由各全国性宗教团体制定式样。"},{"i":35,"n":"第三十五条","txt":"按照国家有关专业技术资格评定办法参加专业技术职称评审聘任的人员，其资格认定、职称聘任、待遇等按国家有关规定办理，不属本办法规范的范围。 按照国家有关专业技术资格评定办法获得专业技术职称的宗教院校教师，可按本办法申请宗教院校教师职称。"},{"i":36,"n":"第三十六条","txt":"本办法实施前已在宗教院校任教的教师，其职称评审条件可以适当放宽，具体标准由各全国性宗教团体制定。"},{"i":37,"n":"第三十七条","txt":"本办法自2013年1月1日起施行。"}],"zongjiaoyuanxiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范宗教院校管理，促进宗教院校健康发展，根据《宗教事务条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称宗教院校，是指培养宗教教职人员和宗教方面其他专门人才的全日制教育机构。按照宗教与教育相分离的原则，宗教院校不属于国民教育体系。宗教教育学历适用于宗教界内部。"},{"i":3,"n":"第三条","txt":"宗教院校由全国性宗教团体或者省、自治区、直辖市宗教团体设立。由全国性宗教团体设立的，为全国性宗教院校；由省、自治区、直辖市宗教团体设立的，为地方性宗教院校。 其他任何组织或者个人不得设立宗教院校。"},{"i":4,"n":"第四条","txt":"宗教院校是培养爱国宗教后备人才、正确阐释宗教教义、培训在职宗教教职人员的重要基地。宗教院校应当以坚持我国宗教中国化为办学方向，以社会主义核心价值观为引领，走中国特色宗教院校办学道路，按照政治上靠得住、宗教上有造诣、品德上能服众、关键时起作用的标准，培养宗教教职人员和宗教方面其他专门人才。"},{"i":5,"n":"第五条","txt":"宗教院校开展活动应当遵守法律、法规和规章。 宗教院校坚持独立自主自办的原则，不受外国势力的支配，不得与境外组织和人员合作办学。"},{"i":6,"n":"第六条","txt":"国家宗教事务局主管宗教院校工作，负责宗教院校设立审批，管理全国性宗教院校。国家宗教事务局可以委托省级人民政府宗教事务部门行使其管理全国性宗教院校的部分职责。 省级人民政府宗教事务部门管理本行政区域的地方性宗教院校。省级人民政府宗教事务部门可以委托设区的市级人民政府宗教事务部门行使其管理地方性宗教院校的部分职责。"},{"i":7,"n":"第七条","txt":"宗教院校分为高等宗教院校和中等宗教院校。"},{"i":8,"n":"第八条","txt":"设立宗教院校，应当具备下列条件： （一）有明确的培养目标、办学章程和课程设置计划； （二）有符合培养条件的生源和招生计划； （三）有必要的办学资金和合法、稳定的经费来源； （四）有教学任务和办学规模所必需的教学场所、设施设备； （五）有专职的院校负责人、合格的专职教师和内部管理组织； （六）布局合理。 同一省级行政区域内已设立宗教院校的，一般不再批准设立新的同类宗教院校。"},{"i":9,"n":"第九条","txt":"设立高等宗教院校，应当符合下列标准： （一）招生对象至少具备中等宗教院校或者普通高级中学学历，或者具有同等学力； （二）任课教师总数不少于学生总额的百分之十，其中至少百分之五十为专职教师； （三）有独立的教学场所，其建筑设施可以保证教学、研究和师生的宗教生活、日常生活、体育锻炼等方面的基本需求，并符合国家有关规划、建设、消防等方面的规定； （四）有必要的教学设备，适用图书不少于三万册； （五）有必要的办学资金。"},{"i":10,"n":"第十条","txt":"设立中等宗教院校，应当符合下列标准： （一）招生对象至少具备普通初级中学学历； （二）任课教师总数不少于学生总额的百分之八，其中至少百分之五十为专职教师； （三）有独立的教学场所，其建筑设施可以保证教学和师生的宗教生活、日常生活、体育锻炼等方面的基本需求，并符合国家有关规划、建设、消防等方面的规定； （四）有必要的教学设备，适用图书不少于二万册； （五）有必要的办学资金。"},{"i":11,"n":"第十一条","txt":"申请设立宗教院校，应当填写《宗教院校设立申请表》，并提交下列材料： （一）办学章程及培养方案； （二）符合培养条件的生源情况说明； （三）资金证明以及办学经费主要来源情况说明； （四）拟聘任教师、院校主要负责人和拟组建管理组织及成员的基本情况说明； （五）校舍等基础设施和设备情况说明。 《宗教院校设立申请表》由国家宗教事务局制定。"},{"i":12,"n":"第十二条","txt":"宗教院校的章程，应当包括以下事项： （一）明确宗教教别的院校名称、简称、外文译名等； （二）院校的办学地点、住所； （三）院校的机构性质、组织体系、发展定位、培养目标、办学宗旨、办学层次、招生范围和办学规模等； （四）院校的主要学科门类，以及设置和调整的原则、程序； （五）院校实施的全日制与非全日制、学历教育与非学历教育等不同教育形式的性质、目的和要求； （六）院校的领导体制，院校负责人的产生与任命机制，院校的决策机制、民主管理和监督机制，内设机构的组成、职责和管理体制； （七）院校经费的来源渠道、财产属性、使用原则和管理制度，接受捐赠的规则和办法； （八）章程修改的启动、审议程序，以及章程解释权的归属； （九）其他应当由章程规定的事项。"},{"i":13,"n":"第十三条","txt":"全国性宗教团体拟设立宗教院校的，向国家宗教事务局提出申请。 省、自治区、直辖市宗教团体拟设立宗教院校的，征求全国性宗教团体意见后，向所在地省级人民政府宗教事务部门提出申请。省级人民政府宗教事务部门应当自收到申请之日起三十日内提出意见，报国家宗教事务局审批。 国家宗教事务局应当自收到全国性宗教团体的申请或者省级人民政府宗教事务部门报送的材料之日起六十日内，作出批准或者不予批准的决定。不予批准的，书面说明理由。"},{"i":14,"n":"第十四条","txt":"宗教院校的变更、合并、分设和终止，应当按本办法第十三条规定的程序办理。宗教院校的变更包括更改校址、校名、隶属关系、培养目标、学制、办学规模等。"},{"i":15,"n":"第十五条","txt":"经批准设立的宗教院校，可以按照有关规定申请法人登记。"},{"i":16,"n":"第十六条","txt":"宗教院校院（校）长为院校主要负责人，全面负责院校管理工作。宗教院校可以根据需要设置副院（校）长。 宗教院校主要负责人不得兼任其他宗教院校的主要负责人。 宗教院校不得聘请外籍人员担任院校的行政职务。"},{"i":17,"n":"第十七条","txt":"宗教院校负责人应具有较高的思想政治素质和政策理论水平，拥护中国共产党的领导，拥护社会主义制度，接受政府管理，坚持我国宗教中国化办学方向；具有深厚的宗教学识和较强的行政管理能力，贯彻民主管理和集体领导制度。"},{"i":18,"n":"第十八条","txt":"宗教院校主要负责人为院校安全稳定工作第一责任人。宗教院校应当建立安全管理工作机制，负责以下安全管理工作： （一）健全院校安全预警机制，制定突发事件应急预案，完善事故预防措施； （二）防范院校内发生宣扬、支持宗教极端主义，以及利用宗教破坏国家统一、民族团结、宗教和睦与社会稳定的行为和言论； （三）落实国家有关建筑、消防、食品、卫生等安全工作的规定； （四）开展校园综合治理，维护校园安全和教学秩序； （五）开展安全宣传教育培训、消防演练等，提高教职工和学生安全意识和防护能力。"},{"i":19,"n":"第十九条","txt":"宗教院校根据办学需要设置理事会或者董事会的，应当在章程中明确其职责定位、组成和议事规则。"},{"i":20,"n":"第二十条","txt":"宗教院校根据精简高效的原则和实际需要，确定教学、研究、行政职能部门等内设机构的设置和人员配备，明确管理层级、职责权限。"},{"i":21,"n":"第二十一条","txt":"宗教院校通过教职工代表大会等组织形式，依法保障教职工参与民主管理和监督，维护教职工合法权益。 宗教院校应当为教职工中的中国共产党党员成立基层党组织、开展活动提供必要条件。"},{"i":22,"n":"第二十二条","txt":"宗教院校应当在教职工和学生中开展习近平新时代中国特色社会主义思想教育、爱国主义教育、社会主义核心价值观教育、法治教育、中华优秀传统文化教育，坚持升国旗与重要场合奏唱国歌制度，增强教职工和学生的国家意识、公民意识、法治意识。"},{"i":23,"n":"第二十三条","txt":"宗教院校不得超出法律、法规、规章和章程规定的活动范围开展传教和宗教教学活动。"},{"i":24,"n":"第二十四条","txt":"宗教院校应当依据章程和有关规定建立教职工和学生的奖惩制度。"},{"i":25,"n":"第二十五条","txt":"宗教院校应当执行国家统一的财务、资产、会计制度，建立健全会计核算、财务报告、财务公开等制度，建立健全财务管理机构，加强财务管理，定期向设立该院校的宗教团体和省级以上人民政府宗教事务部门报告财务状况、收支情况和接受、使用捐赠情况，接受其监督管理，并以适当方式向捐赠方公布。 宗教院校主要负责人、主管财务的负责人以及财务部门的负责人，在离任、退休、调离工作岗位时，应当接受财务审计。"},{"i":26,"n":"第二十六条","txt":"宗教院校应当依法办理税务登记和纳税申报，按照国家有关规定享受税收优惠。"},{"i":27,"n":"第二十七条","txt":"宗教院校学历教育分为中等专科层次宗教教育、高等专科层次宗教教育、本科层次宗教教育和研究生层次宗教教育。 中等宗教院校开展中等专科层次宗教教育，高等宗教院校开展高等专科层次、本科层次和研究生层次宗教教育。"},{"i":28,"n":"第二十八条","txt":"中等专科层次宗教教育应当培养学生掌握本宗教必备的基础理论和教义教规，具有从事宗教教务活动的基本能力。 中等专科层次宗教教育基本修业年限为二至四年。"},{"i":29,"n":"第二十九条","txt":"高等专科层次宗教教育应当培养学生较好地掌握本宗教的基础理论、教义教规和本专业必备的知识，具有从事宗教教务活动和本专业实际工作的基本能力。 高等专科层次宗教教育基本修业年限为三至五年。"},{"i":30,"n":"第三十条","txt":"本科层次宗教教育应当培养学生系统地掌握本宗教的基础理论、教义教规和本学科的基本知识，具备从事宗教教务活动、本专业实际工作和引领信教群众的基本能力，具有开展宗教研究工作、阐释教理教义教规的初步能力。 本科层次宗教教育的基本修业年限为四至六年。"},{"i":31,"n":"第三十一条","txt":"研究生层次宗教教育应当培养学生掌握本宗教坚实的基础理论、教义教规和本学科系统的专业知识，具备较强的从事宗教教务活动、本专业实际工作和引领信教群众的能力，具有开展研究、阐释教理教义教规的能力。"},{"i":32,"n":"第三十二条","txt":"宗教院校根据本宗教健康传承需要和自身教学、学术研究水平，合理设置和调整院校学科、专业。全国性宗教院校设置和调整院校学科、专业，经本宗教的全国性宗教团体教育委员会核准后，报国家宗教事务局备案。地方性宗教院校设置和调整院校学科、专业，经设立该院校的宗教团体和该宗教团体的业务主管单位审核同意后，由本宗教的全国性宗教团体的教育委员会核准，报国家宗教事务局备案。"},{"i":33,"n":"第三十三条","txt":"宗教院校根据本宗教健康传承需要、办学条件和核定的办学规模，制定招生简章。招生简章应当包含招生名额、招生对象、报考录取程序、毕业和就业信息等。招生简章于招生工作启动前三个月报设立该院校的宗教团体同意，并报该宗教团体的业务主管单位备案。"},{"i":34,"n":"第三十四条","txt":"宗教院校招收对象为宗教教职人员或者信仰宗教的公民，一般应当年满十八周岁，且具有普通初级中学以上学历。"},{"i":35,"n":"第三十五条","txt":"报考宗教院校应当经宗教团体、宗教院校或者宗教活动场所推荐，按照招生条件和报考程序进行考试，择优录取。"},{"i":36,"n":"第三十六条","txt":"宗教院校可以依法向学生收取合理的学费和其他费用，收费标准应当报物价主管部门审定。"},{"i":37,"n":"第三十七条","txt":"宗教院校应当对新入学学生资格进行审查，审查合格的，方可办理入学手续，予以注册学籍。"},{"i":38,"n":"第三十八条","txt":"宗教院校教学课程分为公共课程和专业课程。公共课程的教学计划、教材使用方案由国家宗教事务局统一制定；专业课程的教学计划、教材编写和教材使用方案，由本宗教的全国性宗教团体的教育委员会制定，并报国家宗教事务局备案。"},{"i":39,"n":"第三十九条","txt":"宗教院校公共课程包括思想政治理论和中国文化与社会等系列课程，以深入学习习近平新时代中国特色社会主义思想、持续开展社会主义核心价值观教育为目标，加强中华优秀传统文化、社会主义先进文化、思想政治理论、法律法规和国家通用语言文字教育，提升学生综合素质。公共课课时比例不得低于总学时的百分之三十。"},{"i":40,"n":"第四十条","txt":"宗教院校专业课程应当围绕坚持我国宗教中国化方向，以提升学生关于本宗教的理论素养、实践能力和思想建设水平为目标。"},{"i":41,"n":"第四十一条","txt":"宗教院校学位授予、藏传佛教院校学衔授予按照有关规定执行。"},{"i":42,"n":"第四十二条","txt":"宗教院校可以开展非学历继续教育，培训在职宗教教职人员。"},{"i":43,"n":"第四十三条","txt":"宗教院校可以根据办学实际需要，按照国家互联网信息服务管理有关规定开展互联网宗教教育培训。"},{"i":44,"n":"第四十四条","txt":"在宗教院校专门从事宗教专业教育教学工作的人员，应当具备宗教院校教师资格。宗教院校教师职称实行评审聘任制度。宗教院校教师资格申请认定和职称评审聘任按照有关规定执行。 按照《中华人民共和国教师法》《教师资格条例》获得普通高等学校教师资格的人员视为已具备宗教院校教师资格。"},{"i":45,"n":"第四十五条","txt":"宗教院校教师应当遵守宪法、法律、法规、规章和职业道德，恪守学术规范，具有良好的思想品德，为人师表，对学生进行宪法所确定的基本原则的教育、爱国主义教育、民族团结进步教育、法治教育和国家安全教育，完成院校的教学计划。"},{"i":46,"n":"第四十六条","txt":"宗教院校和设立该院校的宗教团体应当依法维护宗教院校教师的合法权益，采取措施改善其工作条件和生活条件，为其办理社会保险登记，组织、支持其参加培训。"},{"i":47,"n":"第四十七条","txt":"宗教院校应当鼓励教师按照坚持我国宗教中国化方向的要求，开展教理教义教规阐释和学术研究，进行学术交流，并提供便利条件。"},{"i":48,"n":"第四十八条","txt":"宗教院校应当对教师、管理人员的思想政治表现、师德师风、业务水平和工作实绩进行考核，考核结果作为聘任或者解聘、晋升、奖励或者处分的依据。 宗教院校应当对违反师德规范或者行为准则的教师，依法依规依纪进行处理。"},{"i":49,"n":"第四十九条","txt":"宗教院校学生在校期间依法享有使用教育教学资源、参加社会实践、志愿服务、勤工助学、文娱体育等活动的权利；对与学生权益相关事务享有知情权、参与权、表达权和监督权。"},{"i":50,"n":"第五十条","txt":"宗教院校学生应当遵守宪法、法律、法规和规章，遵守院校的规章制度，遵守学生行为规范，完成规定学业，尊敬师长。"},{"i":51,"n":"第五十一条","txt":"宗教院校应当真实记录学生考核成绩，并以适当方式记录学生学业、学术、纪律、品行等信息。考核成绩和相关信息归入学籍档案。"},{"i":52,"n":"第五十二条","txt":"宗教院校学生在规定学习年限内修完教育教学计划规定内容，成绩合格，达到毕业要求的，宗教院校应当准予毕业，并在学生离校前颁发毕业证书。 符合宗教院校学位授予条件的，学位授予单位应当依照宗教院校学位授予的有关规定颁发学位证书。"},{"i":53,"n":"第五十三条","txt":"宗教院校可以根据办学实际，按照有关规定建立健全奖学金、助学金制度，完善学生资助体系。"},{"i":54,"n":"第五十四条","txt":"宗教院校可以根据实际情况建立并施行学生转学、转专业、休学和复学制度。"},{"i":55,"n":"第五十五条","txt":"宗教院校学生可以在校内组织、参加学生团体，以适当方式参与院校管理。 学生团体应当在法律、法规、规章和院校管理制度范围内活动，接受院校的领导和管理。"},{"i":56,"n":"第五十六条","txt":"宗教院校招收国际学生，经设立该院校的宗教团体参照《学校招收和培养国际学生管理办法》有关规定审核同意后，报该团体的业务主管单位备案。"},{"i":57,"n":"第五十七条","txt":"宗教院校招收香港特别行政区、澳门特别行政区以及台湾地区学生，经设立该院校的宗教团体按照有关规定审核同意后，报该团体的业务主管单位备案。"},{"i":58,"n":"第五十八条","txt":"在宗教院校学习的国际学生以及香港特别行政区、澳门特别行政区和台湾地区学生，其学位授予按照本办法和宗教院校学位授予的有关规定办理。"},{"i":59,"n":"第五十九条","txt":"宗教院校选派教师或者学生出国出境学习、开展宗教交往，应当报设立该院校的宗教团体同意后，按照有关规定办理。"},{"i":60,"n":"第六十条","txt":"宗教院校为丰富教学内容，开展与国外宗教文化学术交流，可以按照法定程序聘用承担讲学或者教学任务的外籍专业人员。宗教院校聘用外籍专业人员应当遵循以我为主、适量聘用、保证质量、注重实效的原则。"},{"i":61,"n":"第六十一条","txt":"宗教院校申请聘用外籍专业人员，应当符合下列条件： （一）学制三年以上并已正式开办四年以上，教学评估合格； （二）有健全的规章制度，有专门的外籍专业人员管理制度； （三）有保障外籍专业人员开展工作的基本条件； （四）拟聘用人员遵守中国的法律法规规章，尊重中国宗教独立自主自办和各宗教之间相互尊重的原则； （五）拟聘用人员无不良记录，未参加过反华组织、未从事过反华活动、未发表过反华言论，不支持、宣扬和资助宗教极端主义； （六）拟聘用人员无刑事犯罪记录和吸食大麻等毒品的行为记录； （七）拟聘用人员无传染性疾病、无精神障碍史； （八）拟聘用人员无因违反法律法规和师德规范被国内外教育机构解聘及处罚、处分的经历； （九）拟聘用人员具有硕士以上学历或者同等学力，在拟聘任的学科专业领域有较高造诣； （十）拟聘用人员具有与拟聘岗位要求相一致的教学能力和水平。"},{"i":62,"n":"第六十二条","txt":"宗教院校申请聘用外籍专业人员，应当提交下列材料： （一）申请书，内容包括拟聘用人员名单、讲授课程、课时和任教期限等； （二）拟与聘用人员签订的合同文本； （三）拟聘用人员的个人简历，并附相关证书或者证明材料； （四）拟聘用人员的健康情况说明； （五）相关专业机构或者人员的推荐材料。"},{"i":63,"n":"第六十三条","txt":"全国性宗教院校申请聘用外籍专业人员，应当报全国性宗教团体审核，由全国性宗教团体向国家宗教事务局提出申请。地方性宗教院校申请聘用外籍专业人员，经设立该院校的宗教团体和省级人民政府宗教事务部门提出意见后，由省级人民政府宗教事务部门向国家宗教事务局提出申请。 国家宗教事务局应当自受理申请之日起二十日内，作出批准或者不予批准的决定。"},{"i":64,"n":"第六十四条","txt":"拟聘用外籍专业人员的宗教院校取得国家宗教事务局批准后，应当到所在地外国人工作管理部门申请外国人来华工作许可，领取《外国人工作许可通知》。 受聘的外籍专业人员持《外国人工作许可通知》及其他相关材料，向中国驻外签证机关申请办理Z字签证。入境后，还应当依法办理在华工作和居留的相关手续。"},{"i":65,"n":"第六十五条","txt":"宗教院校邀请外籍专业人员到宗教院校开办讲座，时间在两天以内且课时总量不超过六课时，按来华交流访问有关规定办理。"},{"i":66,"n":"第六十六条","txt":"宗教院校应当对拟聘用的外籍专业人员专业素质、资格资历、社会背景等严格把关；对受聘的外籍专业人员进行必要的教育培训，对其讲学内容及使用的教材进行审定，并开展教学评估工作。"},{"i":67,"n":"第六十七条","txt":"受聘的外籍专业人员应当遵守我国法律、法规和规章，尊重我国宗教独立自主自办原则，遵守所在院校规章制度，不得从事与其聘用身份不相符的活动。"},{"i":68,"n":"第六十八条","txt":"宗教院校聘用香港特别行政区、澳门特别行政区以及台湾地区专业人员讲学，参照本章上述规定执行。"},{"i":69,"n":"第六十九条","txt":"设立宗教院校的宗教团体，应当履行以下职责： （一）指导、监督宗教院校坚持正确的办学方向； （二）制定有关宗教院校管理的规章制度并督促落实； （三）指导宗教院校制定和履行章程； （四）为宗教院校正常运转筹集资金； （五）指导、监督宗教院校落实财务管理制度； （六）依据本宗教教理教义和戒律仪轨，按照宗教与社会主义社会相适应的原则，指导、监督宗教院校开展专业课教学和宗教实践活动； （七）指导、支持宗教院校提高办学质量； （八）通过设立奖学金、奖教金等形式奖励优秀学生和教师； （九）法律、法规、规章和宗教团体规章制度规定的其他需要指导和管理的事项。"},{"i":70,"n":"第七十条","txt":"全国性宗教团体除履行第六十九条规定的职责外，还应当履行以下职责： （一）依据宗教院校学位授予的有关规定，制定学位授予实施细则，成立学位授予工作小组，开展宗教院校学位授予资格认定工作； （二）依据宗教院校教师资格认定和职称评审有关规定，制定教师资格认定和职称评审实施细则，成立认定和评审工作小组，开展宗教院校教师资格认定和职称评审工作； （三）审核宗教院校学科、专业的设置和调整； （四）研究制定宗教院校专业课程的课程体系，组织编写宗教院校专业课程统编教材，组织、指导宗教院校专业课教师培训工作； （五）制定宗教院校教师师德规范或者行为准则，明确负面清单； （六）审核地方性宗教院校上报事项等； （七）法律、法规、规章和本团体规章制度规定的其他需要指导和管理的事项。"},{"i":71,"n":"第七十一条","txt":"国家宗教事务局和省级人民政府宗教事务部门应当根据国家有关法律、法规和规章，对宗教院校下列事项进行指导和管理： （一）宗教院校设立、变更、合并、分设和终止的初审或者审批以及章程核准审查； （二）对宗教院校依法向人民政府宗教事务部门申请审批的事项进行初审或者审批、监督、管理； （三）指导、监督宗教团体履行支持、指导和管理所设立宗教院校的职责； （四）组织专家或者委托第三方专业机构对宗教院校的办学水平、效益和教育质量进行评估； （五）指导宗教院校加强公共课程教学，提升教学质量； （六）指导宗教院校通过多种途径配齐配强师资力量； （七）法律、法规和规章规定的其他需要指导和管理的事项。"},{"i":72,"n":"第七十二条","txt":"国家宗教事务局和省级人民政府宗教事务部门根据实际工作需要，可以选派教育督导人员，对宗教院校下列事项开展教育督导工作： （一）宗教院校依法依规依章程开展教学、研究活动情况； （二）师生或者群众反映的教育教学热点、难点问题； （三）严重影响或者损害宗教和睦、社会稳定的突发事件； （四）严重影响或者损害师生安全和合法权益、教育教学秩序等的突发事件； （五）国家宗教事务局或者省级人民政府宗教事务部门交办的工作事项落实情况； （六）宗教院校公共课程的教学情况、教学内容和教学效果。 教育督导人员的聘任和实施教育督导时可行使的权力，参照国家教育督导有关规定执行。"},{"i":73,"n":"第七十三条","txt":"宗教院校的下列事项，应当报设立该院校的宗教团体审核后，由该宗教团体报其业务主管单位审核同意： （一）调整本院校法定代表人、主要负责人等院校领导成员及董事会、理事会成员，召开董事会或者理事会，修改院校章程或者董事会、理事会章程； （二）举办重大会议、培训、学术交流和对外交流活动； （三）开展活动冠以人民政府宗教事务部门作为支持单位、指导单位或者主办单位； （四）接受国（境）外组织或者个人捐赠宗教书刊、音像制品或者捐赠金额超过十万元； （五）其他应当由宗教团体报其业务主管单位审核同意的事项。 法律、法规规定应当报人民政府宗教事务部门审批的事项，宗教院校应当依法办理。"},{"i":74,"n":"第七十四条","txt":"宗教院校下列事项，应当及时书面报设立该院校的宗教团体，由该宗教团体书面报其业务主管单位： （一）工作规划、年度工作计划、年度工作总结、年度财务报告； （二）大额财务支出、重大资产处置、重大建设工程项目、重大活动安排； （三）发生安全事故，造成人员伤亡或者财产损失； （四）院校内部或者院校与其他方面发生矛盾、纠纷，影响本院校工作正常开展； （五）发生重大违法违规问题； （六）其他应当由宗教团体书面报其业务主管单位的事项。 特殊情况下，不能及时书面报告的，应当先口头报告。"},{"i":75,"n":"第七十五条","txt":"公职人员在宗教院校管理工作中滥用职权、玩忽职守、徇私舞弊，应当给予处分的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":76,"n":"第七十六条","txt":"擅自设立宗教院校的，按照《宗教事务条例》第六十九条规定予以处罚。"},{"i":77,"n":"第七十七条","txt":"宗教院校违反本办法规定，未依法依章程开展活动，按照《宗教事务条例》第六十五条予以处罚。"},{"i":78,"n":"第七十八条","txt":"宗教院校违反国家有关财务、会计、资产、税收管理规定的，按照《宗教事务条例》第六十七条予以处罚。"},{"i":79,"n":"第七十九条","txt":"宗教团体未履行支持、指导、管理宗教院校相关职责的，人民政府宗教事务部门应当对其主要负责人进行工作约谈；情节严重的，给予通报批评、限期整改。"},{"i":80,"n":"第八十条","txt":"对宗教事务部门的行政行为不服的，可以依法申请行政复议；对行政复议决定不服的，可以依法提起行政诉讼。"},{"i":81,"n":"第八十一条","txt":"本办法由国家宗教事务局负责解释。"},{"i":82,"n":"第八十二条","txt":"本办法未尽事宜，按国家有关规定执行。"},{"i":83,"n":"第八十三条","txt":"本办法自2021年9月1日起施行。1998年国家宗教事务局、国家外国专家局、公安部公布的《宗教院校聘用外籍专业人员办法》和2007年国家宗教事务局公布的《宗教院校设立办法》同时废止。"}],"shenjijiguanshenjitingzhengguiding":[{"i":1,"n":"第一条","txt":"为规范审计机关的审计处罚程序，保证审计质量，维护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》和《中华人民共和国审计法》及其实施条例，制定本规定。"},{"i":2,"n":"第二条","txt":"审计机关进行审计听证应当遵循公正、公平、公开的原则。"},{"i":3,"n":"第三条","txt":"审计机关对被审计单位和有关责任人员（以下统称当事人）拟作出下列审计处罚的，应当向当事人送达审计听证告知书，告知当事人有要求听证的权利，当事人要求听证的，审计机关应当举行审计听证会： （一）对被审计单位处以十万元以上或者对个人处以一万元以上罚款的； （二）对被审计单位处以没收十万元以上违法所得的； （三）法律、法规、规章规定的其他情形。"},{"i":4,"n":"第四条","txt":"审计听证告知书主要包括以下内容： （一）当事人的名称或者姓名； （二）当事人违法的事实和证据； （三）审计处罚的法律依据； （四）审计处罚建议； （五）当事人有要求审计听证的权利； （六）当事人申请审计听证的期限； （七）审计机关的名称（印章）和日期。"},{"i":5,"n":"第五条","txt":"当事人要求举行审计听证会的，应当自收到审计听证告知书之日起五个工作日内，向审计机关提出书面申请，列明听证要求，并由当事人签名或者盖章。逾期不提出书面申请的，视为放弃审计听证权利。"},{"i":6,"n":"第六条","txt":"审计机关应当在举行审计听证会七个工作日前向当事人及有关人员送达审计听证会通知书，通知当事人举行审计听证会的时间、地点，审计听证主持人、书记员姓名，并告知当事人有申请主持人、书记员回避的权利。"},{"i":7,"n":"第七条","txt":"除涉及国家秘密、商业秘密或者个人隐私依法予以保密外，审计听证会应当公开举行。"},{"i":8,"n":"第八条","txt":"审计听证会的主持人由审计机关负责人指定的非本案审计人员担任，负责审计听证会的组织、主持工作。 书记员可以由一至二人组成，由主持人指定，负责审计听证的记录工作，制作审计听证笔录。"},{"i":9,"n":"第九条","txt":"当事人认为主持人或者书记员与本案有直接利害关系的，有权申请其回避并说明理由。 当事人申请主持人回避应当在审计听证会举行之前提出；申请书记员回避可以在审计听证会举行时提出。 当事人申请回避可以以书面形式提出，也可以以口头形式提出。以口头形式提出的，由书记员记录在案。"},{"i":10,"n":"第十条","txt":"主持人的回避，由审计机关负责人决定；书记员的回避，由主持人决定。 相关回避情况应当记入审计听证笔录。"},{"i":11,"n":"第十一条","txt":"当事人可以亲自参加审计听证，也可以委托一至二人代理参加审计听证。委托他人代理参加审计听证会的，代理人应当出具当事人的授权委托书。 当事人的授权委托书应当载明代理人的代理权限。"},{"i":12,"n":"第十二条","txt":"当事人接到审计听证通知书后，本人或者其代理人不能按时参加审计听证会的，应当及时告知审计机关并说明理由。 当事人及其代理人无正当理由拒不出席听证或者未经许可中途退出听证的，视为放弃听证权利，审计机关终止听证。终止听证的情况应当记入审计听证笔录。"},{"i":13,"n":"第十三条","txt":"书记员应当将审计听证的全部活动记入审计听证笔录。审计机关认为有必要的，可以对审计听证会情况进行录音、录像。 审计听证笔录应当交听证双方确认无误后签字或者盖章。当事人或者其代理人如认为笔录有差错，可以要求补正。当事人或者其代理人拒绝签字或者盖章的，由听证主持人在笔录中注明。"},{"i":14,"n":"第十四条","txt":"审计听证会参加人和旁听人员应当遵守以下听证纪律： （一）审计听证会参加人应当在主持人的主持下发言、提问、辩论； （二）未经主持人允许，审计听证会参加人不得提前退席； （三）未经主持人允许，任何人不得录音、录像或摄影； （四）旁听人员要保持肃静，不得发言、提问或者议论。"},{"i":15,"n":"第十五条","txt":"主持人在审计听证会主持过程中，有以下权利： （一）对审计听证会参加人的不当辩论或者其他违反审计听证会纪律的行为予以制止、警告； （二）对违反审计听证会纪律的旁听人员予以制止、警告、责令退席； （三）对违反审计听证纪律的人员制止无效的，提请公安机关依法处置。"},{"i":16,"n":"第十六条","txt":"审计听证会应当按照下列程序进行： （一）主持人宣读审计听证会的纪律和应注意的事项； （二）主持人宣布审计听证会开始； （三）主持人宣布案由并宣读参加审计听证会的主持人、书记员、听证参加人的姓名、工作单位和职务； （四）主持人告知当事人或者其代理人有申请书记员回避的权利，并询问当事人或者其代理人是否申请回避； （五）本案审计人员提出当事人违法的事实、证据和审计处罚的法律依据以及审计处罚建议； （六）当事人进行陈述、申辩； （七）在主持人允许下，双方进行质证、辩论； （八）双方作最后陈述； （九）书记员将所作的笔录交听证双方当场确认并签字或者盖章； （十）主持人宣布审计听证会结束。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，可以延期举行审计听证会： （一）当事人或者其代理人有正当理由未到场的； （二）需要通知新的证人到场，或者有新的事实需要重新调查核实的； （三）主持人应当回避，需要重新确定主持人的； （四）其他需要延期的情形。"},{"i":18,"n":"第十八条","txt":"审计听证会结束后，主持人应当将审计听证笔录、案卷材料等一并报送审计机关。 审计机关根据审计听证笔录以及有关审理意见，区别以下情形作出决定： （一）确有应受审计处罚的违法行为的，根据情节轻重及具体情况，作出审计处罚； （二）违法事实不能成立的，不予审计处罚； （三）违法行为轻微，依法依规可以不予审计处罚的，不予审计处罚。 违法行为涉嫌犯罪的，审计机关应当依法依规移送监察机关或者司法机关处理。"},{"i":19,"n":"第十九条","txt":"审计机关不得因当事人要求审计听证、在审计听证中进行申辩和质证而加重处罚。"},{"i":20,"n":"第二十条","txt":"审计听证文书和有关资料应当归入相应的审计项目档案。"},{"i":21,"n":"第二十一条","txt":"审计听证文书送达适用《中华人民共和国民事诉讼法》的有关规定。"},{"i":22,"n":"第二十二条","txt":"本规定由审计署负责解释。"},{"i":23,"n":"第二十三条","txt":"本规定自发布之日起施行。审计署于2000年1月28日发布的《审计机关审计听证的规定》（2000年审计署第1号令）同时废止。"}],"shenjijiguanshenjidanganguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范审计档案管理，维护审计档案的完整与安全，保证审计档案的质量，发挥审计档案的作用，根据《中华人民共和国档案法》、《中华人民共和国审计法》和其他有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称审计档案，是指审计机关进行审计（含专项审计调查）活动中直接形成的对国家和社会具有保存价值的各种文字、图表等不同形式的历史记录。 审计档案是国家档案的组成部分。"},{"i":3,"n":"第三条","txt":"审计机关的审计档案管理工作接受同级档案行政管理部门的监督和指导；审计机关和档案行政管理部门在各自的职责范围内开展审计档案工作。"},{"i":4,"n":"第四条","txt":"审计机关审计档案应当实行集中统一管理。"},{"i":5,"n":"第五条","txt":"审计机关应当设立档案机构或者配备专职（兼职）档案人员，负责本单位的审计档案工作。"},{"i":6,"n":"第六条","txt":"审计档案案卷质量的基本要求是：审计项目文件材料应当真实、完整、有效、规范，并做到遵循文件材料的形成规律和特点，保持文件材料之间的有机联系，区别不同价值，便于保管和利用。"},{"i":7,"n":"第七条","txt":"审计文件材料应当按照结论类、证明类、立项类、备查类4个单元进行排列。"},{"i":8,"n":"第八条","txt":"审计文件材料归档范围： （一）结论类文件材料：上级机关（领导）对该审计项目形成的《审计要情》、《重要信息要目》等审计信息批示的情况说明、审计报告、审计决定书、审计移送处理书等结论类报告，及相关的审理意见书、审计业务会议记录、纪要、被审计对象对审计报告的书面意见、审计组的书面说明等。 （二）证明类文件材料：被审计单位承诺书、审计工作底稿汇总表、审计工作底稿及相应的审计取证单、审计证据等。 （三）立项类文件材料：上级审计机关或者本级政府的指令性文件、与审计事项有关的举报材料及领导批示、调查了解记录、审计实施方案及相关材料、审计通知书和授权审计通知书等。 （四）备查类文件材料：被审计单位整改情况、该审计项目审计过程中产生的信息等不属于前三类的其他文件材料。"},{"i":9,"n":"第九条","txt":"审计文件材料按审计项目立卷，不同审计项目不得合并立卷。"},{"i":10,"n":"第十条","txt":"审计文件材料归档工作实行审计组组长负责制。 审计组组长确定的立卷人应当及时收集审计项目的文件材料，在审计项目终结后按立卷方法和规则进行归类整理，经业务部门负责人审核、档案人员检查后，按照有关规定进行编目和装订，由审计业务部门向本机关档案机构或者专职（兼职）档案人员办理移交手续。"},{"i":11,"n":"第十一条","txt":"审计机关统一组织多个下级审计机关的审计组共同实施一个审计项目，由审计机关负责组织的业务部门确定文件材料归档工作。"},{"i":12,"n":"第十二条","txt":"审计复议案件的文件材料由复议机构逐案单独立卷归档。 为了便于查找和利用，档案机构（人员）应当将审计复议案件归档情况在被复议的审计项目案卷备考表中加以说明。"},{"i":13,"n":"第十三条","txt":"审计档案的保管期限应当根据审计项目涉及的金额、性质、社会影响等因素划定为永久、定期两种，定期分为30年、10年。 （一）永久保管的档案，是指特别重大的审计事项、列入审计工作报告、审计结果报告或第一次涉及的审计领域等具有突出代表意义的审计事项档案。 （二）保管30年的档案，是指重要审计事项、查考价值较大的档案。 （三）保管10年的档案，是指一般性审计事项的档案。 审计机关业务部门应当负责划定审计档案的保管期限。 执行同一审计工作方案的审计项目档案，由审计机关负责组织的业务部门确定相同保管期限。 审计档案的保管期限自归档年度开始计算。"},{"i":14,"n":"第十四条","txt":"审计文件材料的归档时间应当在该审计项目终结后的5个月内，不得迟于次年4月底。 跟踪审计项目，按年度分别立卷归档。"},{"i":15,"n":"第十五条","txt":"审计机关应当根据审计工作保密事项范围和有关主管部门保密事项范围的规定确定密级和保密期限。凡未标明保密期限的，按照绝密级30年、机密级20年、秘密级10年认定。 审计档案的密级及其保密期限，按卷内文件的最高密级及其保密期限确定，由审计业务部门按有关规定作出标识。 审计档案保密期限届满，即自行解密。因工作需要提前或者推迟解密的，由审计业务部门向本机关保密工作部门按解密程序申请办理。"},{"i":16,"n":"第十六条","txt":"审计档案应当采用“年度—组织机构—保管期限”的方法排列、编目和存放。审计案卷排列方法应当统一，前后保持一致，不可任意变动。"},{"i":17,"n":"第十七条","txt":"审计机关应当按照国家有关规定配置具有防盗、防光、防高温、防火、防潮、防尘、防鼠、防虫功能的专用、坚固的审计档案库房，配备必要的设施和设备。"},{"i":18,"n":"第十八条","txt":"审计机关应当加强审计档案信息化管理，采用计算机等现代化管理技术编制适用的检索工具和参考材料，积极开展审计档案的利用工作。"},{"i":19,"n":"第十九条","txt":"审计机关应当建立健全审计档案利用制度。借阅审计档案，仅限定在审计机关内部。审计机关以外的单位有特殊情况需要查阅、复制审计档案或者要求出具审计档案证明的，须经审计档案所属审计机关分管领导审批，重大审计事项的档案须经审计机关主要领导审批。"},{"i":20,"n":"第二十条","txt":"省级以上（含省级）审计机关应当将永久保管的、省级以下审计机关应当将永久和30年保管的审计档案在本机关保管20年后，定期向同级国家综合档案馆移交。"},{"i":21,"n":"第二十一条","txt":"审计机关应当按照有关规定成立鉴定小组，在审计机关办公厅（室）主要负责人的主持下定期对已超过保管期限的审计档案进行鉴定，准确地判定档案的存毁。"},{"i":22,"n":"第二十二条","txt":"审计机关应当对确无保存价值的审计档案进行登记造册，经分管负责人批准后销毁。销毁审计档案，应当指定两人负责监销。"},{"i":23,"n":"第二十三条","txt":"对审计机关工作人员损毁、丢失、涂改、伪造、出卖、转卖、擅自提供审计档案的，由任免机关或者监察机关依法对直接责任人员和负有责任的领导人员给予行政处分；涉嫌犯罪的，移送司法机关依法追究刑事责任。档案行政管理部门可以对相关责任单位依法给予行政处罚。"},{"i":24,"n":"第二十四条","txt":"电子审计档案的管理办法另行规定。"},{"i":25,"n":"第二十五条","txt":"审计机关和档案行政管理部门可以根据本地实际情况，在遵循本规定的基础上联合制定实施办法。"},{"i":26,"n":"第二十六条","txt":"本规定由审计署和国家档案局负责解释。"},{"i":27,"n":"第二十七条","txt":"本规定自2013年1月1日起施行。此前审计署发布的《审计机关审计档案工作准则》（2001年审计署第3号令）同时废止。"}],"shenjijiguanfengcunziliaozichanguiding":[{"i":1,"n":"第一条","txt":"为了规范审计机关封存被审计单位有关资料和违反国家规定取得的资产的行为，保障审计机关和审计人员严格依法行使审计监督职权，提高依法审计水平，维护国家利益和被审计单位的合法权益，根据审计法、审计法实施条例和其他有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"审计机关对被审计单位有关资料和违反国家规定取得的资产采取封存措施适用本规定。 审计机关在审计证据可能灭失或者以后难以取得的情况下，采取的先行登记保存措施，依照行政处罚法和有关行政法规的规定执行。"},{"i":3,"n":"第三条","txt":"审计机关采取封存措施，应当遵循合法、谨慎的原则。 审计机关应当严格依照审计法、审计法实施条例和本规定确定的条件、程序采取封存措施，不得滥用封存权。 审计机关通过制止被审计单位违法行为、及时取证或者采取先行登记保存措施可以达到审计目的的，不必采取封存措施。"},{"i":4,"n":"第四条","txt":"有下列情形之一的，审计机关可以采取封存措施： （一）被审计单位正在或者可能转移、隐匿、篡改、毁弃会计凭证、会计账簿、财务会计报告以及其他与财政收支或者财务收支有关的资料的； （二）被审计单位正在或者可能转移、隐匿违反国家规定取得的资产的。"},{"i":5,"n":"第五条","txt":"审计机关依法对被审计单位的下列资料进行封存： （一）会计凭证、会计账簿、财务会计报告等会计资料； （二）合同、文件、会议记录等与被审计单位财政收支或者财务收支有关的其他资料。 上述资料存储在磁、光、电等介质上的，审计机关可以依法封存相关存储介质。"},{"i":6,"n":"第六条","txt":"审计机关依法对被审计单位违反国家规定取得的现金、实物等资产或者有价证券、权属证明等资产凭证进行封存。"},{"i":7,"n":"第七条","txt":"审计机关采取封存措施，应当经县级以上人民政府审计机关（含县级人民政府审计机关和省级以上人民政府审计机关派出机构，下同）负责人批准，由两名审计人员实施。"},{"i":8,"n":"第八条","txt":"审计机关采取封存措施，应当向被审计单位送达封存通知书。 封存通知书包括下列内容： （一）被审计单位名称； （二）封存依据； （三）封存资料或者资产的名称、数量等； （四）封存期限； （五）被审计单位申请行政复议或者提起行政诉讼的途径和期限； （六）审计机关的名称、印章和日期。 在被审计单位正在转移、隐匿、篡改、毁弃有关资料或者正在转移、隐匿违反国家规定取得的资产等紧急情况下，审计人员报经县级以上人民政府审计机关负责人口头批准，可以采取必要措施，当场予以封存，再补送封存通知书。"},{"i":9,"n":"第九条","txt":"审计机关采取封存措施时，审计人员应当会同被审计单位相关人员对有关资料或者资产进行清点，开列封存清单。 封存清单一般登记封存资料的名称、数量，封存资产的名称、规格、型号、数量等。封存资料存储在磁、光、电等介质上的，还应当列明存储介质的名称、规格等。 封存清单一式两份，由审计人员和被审计单位相关人员核对后签名或者盖章，双方各执一份。"},{"i":10,"n":"第十条","txt":"审计机关应当对存放封存资料或者资产的文件柜、保险柜、档案室、库房等加贴封条。 封条上应当注明审计机关名称、封存日期并加盖审计机关印章。"},{"i":11,"n":"第十一条","txt":"审计机关具备保管条件的，可以自行保管封存的资料或者资产；不具备保管条件的，可以指定被审计单位对存放封存资料、资产的设备或者设施进行保管或者看管；特殊情况下，也可以委托与被审计单位无利害关系的第三人保管。 审计机关指定被审计单位保管或者看管存放封存资料、资产的设备或者设施的，应当在封存通知书中一并载明被审计单位的保管责任。"},{"i":12,"n":"第十二条","txt":"被审计单位或者受托保管的第三人应当履行保管责任，除本规定第十三条规定的情形外，不得擅自启封，不得损毁或者转移存放封存资料、资产的设备或者设施。"},{"i":13,"n":"第十三条","txt":"遇有自然灾害等突发事件，可能导致封存的资料或者资产损毁的，负有保管责任的被审计单位或者第三人，应当将封存的资料或者资产转移到安全的地方，并将情况及时报告采取封存措施的审计机关。"},{"i":14,"n":"第十四条","txt":"封存的期限一般不得超过7个工作日；有特殊情况需要延长的，经县级以上人民政府审计机关负责人批准，可以适当延长，但延长的期限不得超过7个工作日。"},{"i":15,"n":"第十五条","txt":"审计机关封存资料或者资产后，审计人员应当及时进行审查，获取审计证据，或者提请有关主管部门对被审计单位违反国家规定取得的资产进行处理。"},{"i":16,"n":"第十六条","txt":"审计机关在封存期限届满或者在封存期限内完成对有关资料或者资产处理的，审计人员应当与被审计单位相关人员共同清点封存的资料或者资产后予以退还，并在双方持有的封存清单上注明解除封存日期和退还的资料或者资产，由双方签名或者盖章。"},{"i":17,"n":"第十七条","txt":"审计机关违反规定采取封存措施，给国家利益或者被审计单位的合法权益造成重大损害的，依照有关法律法规的规定追究相关人员的责任。"},{"i":18,"n":"第十八条","txt":"被审计单位或者负有保管责任的第三人有下列行为之一的，依照有关法律法规的规定追究相关人员的责任： （一）除本规定第十三条规定的情形外，擅自启封的； （二）故意或者未尽保管责任，导致封存的资料被转移、隐匿、篡改、毁弃的； （三）故意或者未尽保管责任，导致封存的资产被转移、隐匿、损毁的。"},{"i":19,"n":"第十九条","txt":"本规定由审计署负责解释。"},{"i":20,"n":"第二十条","txt":"本规定自2011年2月1日起施行。"}],"shenjishuguanyuneibushenjigongzuodeguiding":[{"i":1,"n":"第一条","txt":"为了加强内部审计工作，建立健全内部审计制度，提升内部审计工作质量，充分发挥内部审计作用，根据《中华人民共和国审计法》《中华人民共和国审计法实施条例》以及国家其他有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"依法属于审计机关审计监督对象的单位（以下统称单位）的内部审计工作，以及审计机关对单位内部审计工作的业务指导和监督，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称内部审计，是指对本单位及所属单位财政财务收支、经济活动、内部控制、风险管理实施独立、客观的监督、评价和建议，以促进单位完善治理、实现目标的活动。"},{"i":4,"n":"第四条","txt":"单位应当依照有关法律法规、本规定和内部审计职业规范，结合本单位实际情况，建立健全内部审计制度，明确内部审计工作的领导体制、职责权限、人员配备、经费保障、审计结果运用和责任追究等。"},{"i":5,"n":"第五条","txt":"内部审计机构和内部审计人员从事内部审计工作，应当严格遵守有关法律法规、本规定和内部审计职业规范，忠于职守，做到独立、客观、公正、保密。 内部审计机构和内部审计人员不得参与可能影响独立、客观履行审计职责的工作。"},{"i":6,"n":"第六条","txt":"国家机关、事业单位、社会团体等单位的内部审计机构或者履行内部审计职责的内设机构，应当在本单位党组织、主要负责人的直接领导下开展内部审计工作，向其负责并报告工作。 国有企业内部审计机构或者履行内部审计职责的内设机构应当在企业党组织、董事会（或者主要负责人）直接领导下开展内部审计工作，向其负责并报告工作。国有企业应当按照有关规定建立总审计师制度。总审计师协助党组织、董事会（或者主要负责人）管理内部审计工作。"},{"i":7,"n":"第七条","txt":"内部审计人员应当具备从事审计工作所需要的专业能力。单位应当严格内部审计人员录用标准，支持和保障内部审计机构通过多种途径开展继续教育，提高内部审计人员的职业胜任能力。 内部审计机构负责人应当具备审计、会计、经济、法律或者管理等工作背景。"},{"i":8,"n":"第八条","txt":"内部审计机构应当根据工作需要，合理配备内部审计人员。除涉密事项外，可以根据内部审计工作需要向社会购买审计服务，并对采用的审计结果负责。"},{"i":9,"n":"第九条","txt":"单位应当保障内部审计机构和内部审计人员依法依规独立履行职责，任何单位和个人不得打击报复。"},{"i":10,"n":"第十条","txt":"内部审计机构履行内部审计职责所需经费，应当列入本单位预算。"},{"i":11,"n":"第十一条","txt":"对忠于职守、坚持原则、认真履职、成绩显著的内部审计人员，由所在单位予以表彰。"},{"i":12,"n":"第十二条","txt":"内部审计机构或者履行内部审计职责的内设机构应当按照国家有关规定和本单位的要求，履行下列职责： （一）对本单位及所属单位贯彻落实国家重大政策措施情况进行审计； （二）对本单位及所属单位发展规划、战略决策、重大措施以及年度业务计划执行情况进行审计； （三）对本单位及所属单位财政财务收支进行审计； （四）对本单位及所属单位固定资产投资项目进行审计； （五）对本单位及所属单位的自然资源资产管理和生态环境保护责任的履行情况进行审计； （六）对本单位及所属单位的境外机构、境外资产和境外经济活动进行审计； （七）对本单位及所属单位经济管理和效益情况进行审计； （八）对本单位及所属单位内部控制及风险管理情况进行审计； （九）对本单位内部管理的领导人员履行经济责任情况进行审计； （十）协助本单位主要负责人督促落实审计发现问题的整改工作； （十一）对本单位所属单位的内部审计工作进行指导、监督和管理； （十"},{"i":13,"n":"第十三条","txt":"内部审计机构或者履行内部审计职责的内设机构应有下列权限： （一）要求被审计单位按时报送发展规划、战略决策、重大措施、内部控制、风险管理、财政财务收支等有关资料（含相关电子数据，下同），以及必要的计算机技术文档； （二）参加单位有关会议，召开与审计事项有关的会议； （三）参与研究制定有关的规章制度，提出制定内部审计规章制度的建议； （四）检查有关财政财务收支、经济活动、内部控制、风险管理的资料、文件和现场勘察实物； （五）检查有关计算机系统及其电子数据和资料； （六）就审计事项中的有关问题，向有关单位和个人开展调查和询问，取得相关证明材料； （七）对正在进行的严重违法违规、严重损失浪费行为及时向单位主要负责人报告，经同意作出临时制止决定； （八）对可能转移、隐匿、篡改、毁弃会计凭证、会计账簿、会计报表以及与经济活动有关的资料，经批准，有权予以暂时封存； （九）提出纠正、处理违法违规行为的"},{"i":14,"n":"第十四条","txt":"单位党组织、董事会（或者主要负责人）应当定期听取内部审计工作汇报，加强对内部审计工作规划、年度审计计划、审计质量控制、问题整改和队伍建设等重要事项的管理。"},{"i":15,"n":"第十五条","txt":"下属单位、分支机构较多或者实行系统垂直管理的单位，其内部审计机构应当对全系统的内部审计工作进行指导和监督。系统内各单位的内部审计结果和发现的重大违纪违法问题线索，在向本单位党组织、董事会（或者主要负责人）报告的同时，应当及时向上一级单位的内部审计机构报告。 单位应当将内部审计工作计划、工作总结、审计报告、整改情况以及审计中发现的重大违纪违法问题线索等资料报送同级审计机关备案。"},{"i":16,"n":"第十六条","txt":"内部审计的实施程序，应当依照内部审计职业规范和本单位的相关规定执行。"},{"i":17,"n":"第十七条","txt":"内部审计机构或者履行内部审计职责的内设机构，对本单位内部管理的领导人员实施经济责任审计时，可以参照执行国家有关经济责任审计的规定。"},{"i":18,"n":"第十八条","txt":"单位应当建立健全审计发现问题整改机制，明确被审计单位主要负责人为整改第一责任人。对审计发现的问题和提出的建议，被审计单位应当及时整改，并将整改结果书面告知内部审计机构。"},{"i":19,"n":"第十九条","txt":"单位对内部审计发现的典型性、普遍性、倾向性问题，应当及时分析研究，制定和完善相关管理制度，建立健全内部控制措施。"},{"i":20,"n":"第二十条","txt":"内部审计机构应当加强与内部纪检监察、巡视巡察、组织人事等其他内部监督力量的协作配合，建立信息共享、结果共用、重要事项共同实施、问题整改问责共同落实等工作机制。 内部审计结果及整改情况应当作为考核、任免、奖惩干部和相关决策的重要依据。"},{"i":21,"n":"第二十一条","txt":"单位对内部审计发现的重大违纪违法问题线索，应当按照管辖权限依法依规及时移送纪检监察机关、司法机关。"},{"i":22,"n":"第二十二条","txt":"审计机关在审计中，特别是在国家机关、事业单位和国有企业三级以下单位审计中，应当有效利用内部审计力量和成果。对内部审计发现且已经纠正的问题不再在审计报告中反映。"},{"i":23,"n":"第二十三条","txt":"审计机关应当依法对内部审计工作进行业务指导和监督，明确内部职能机构和专职人员，并履行下列职责： （一）起草有关内部审计工作的法规草案； （二）制定有关内部审计工作的规章制度和规划； （三）推动单位建立健全内部审计制度； （四）指导内部审计统筹安排审计计划，突出审计重点； （五）监督内部审计职责履行情况，检查内部审计业务质量； （六）指导内部审计自律组织开展工作； （七）法律、法规规定的其他职责。"},{"i":24,"n":"第二十四条","txt":"审计机关可以通过业务培训、交流研讨等方式，加强对内部审计人员的业务指导。"},{"i":25,"n":"第二十五条","txt":"审计机关应当对单位报送的备案资料进行分析，将其作为编制年度审计项目计划的参考依据。"},{"i":26,"n":"第二十六条","txt":"审计机关可以采取日常监督、结合审计项目监督、专项检查等方式，对单位的内部审计制度建立健全情况、内部审计工作质量情况等进行指导和监督。 对内部审计制度建设和内部审计工作质量存在问题的，审计机关应当督促单位内部审计机构及时进行整改并书面报告整改情况；情节严重的，应当通报批评并视情况抄送有关主管部门。"},{"i":27,"n":"第二十七条","txt":"审计机关应当按照国家有关规定对内部审计自律组织进行政策和业务指导，推动内部审计自律组织按照法律法规和章程开展活动。必要时，可以向内部审计自律组织购买服务。"},{"i":28,"n":"第二十八条","txt":"被审计单位有下列情形之一的，由单位党组织、董事会（或者主要负责人）责令改正，并对直接负责的主管人员和其他直接责任人员进行处理： （一）拒绝接受或者不配合内部审计工作的； （二）拒绝、拖延提供与内部审计事项有关的资料，或者提供资料不真实、不完整的； （三）拒不纠正审计发现问题的； （四）整改不力、屡审屡犯的； （五）违反国家规定或者本单位内部规定的其他情形。"},{"i":29,"n":"第二十九条","txt":"内部审计机构或者履行内部审计职责的内设机构和内部审计人员有下列情形之一的，由单位对直接负责的主管人员和其他直接责任人员进行处理；涉嫌犯罪的，移送司法机关依法追究刑事责任： （一）未按有关法律法规、本规定和内部审计职业规范实施审计导致应当发现的问题未被发现并造成严重后果的； （二）隐瞒审计查出的问题或者提供虚假审计报告的； （三）泄露国家秘密或者商业秘密的； （四）利用职权谋取私利的； （五）违反国家规定或者本单位内部规定的其他情形。"},{"i":30,"n":"第三十条","txt":"内部审计人员因履行职责受到打击、报复、陷害的，单位党组织、董事会（或者主要负责人）应当及时采取保护措施，并对相关责任人员进行处理；涉嫌犯罪的，移送司法机关依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"本规定所称国有企业是指国有和国有资本占控股地位或者主导地位的企业、金融机构。"},{"i":32,"n":"第三十二条","txt":"不属于审计机关审计监督对象的单位的内部审计工作，可以参照本规定执行。"},{"i":33,"n":"第三十三条","txt":"本规定由审计署负责解释。"},{"i":34,"n":"第三十四条","txt":"本规定自2018年3月1日起施行。审计署于2003年3月4日发布的《审计署关于内部审计工作的规定》（2003年审计署第4号令）同时废止。"}],"duiwaiyuanzhubiaoshishiyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范对外援助标识（以下简称援外标识）使用，加强援外标识管理，制定本办法。"},{"i":2,"n":"第二条","txt":"援外标识是中华人民共和国政府对外提供援助的标志。"},{"i":3,"n":"第三条","txt":"本办法所称的援外标识使用人是指使用中国政府对外援助资金承担对外援助项目的公民、法人和其他组织，以及经同意可以使用援外标识的公民、法人和其他组织。"},{"i":4,"n":"第四条","txt":"国家国际发展合作署（以下简称国际发展合作署）负责管理和监督援外标识的使用。 援外执行部门依据各自职能和本办法规定负责组织援外标识使用。 驻外使领馆协助办理与援外标识有关事务，对援外标识使用情况进行监督和检查。"},{"i":5,"n":"第五条","txt":"援外标识可以根据需要与中华人民共和国国旗图案一同使用。国旗图案的印制和使用应当遵守《中华人民共和国国旗法》。"},{"i":6,"n":"第六条","txt":"在下列情形下，援外标识使用人应当使用援外标识： （一）援外成套项目的主体建筑、大型机械设备、开竣工仪式、项目组驻地和项目工地； （二）援外物资项目提供的物资及其包装； （三）对外技术援助项目组驻地； （四）援外人力资源开发合作、志愿者服务等项目的有关活动； （五）援外医疗队医疗设备和医疗活动； （六）南南合作援助基金项目合作协议约定使用的情形； （七）援外优惠贷款项目政府间协议规定使用的情形； （八）援外项目相关文件和资料，援外人员的工作服装、佩饰和交通工具； （九）经国际发展合作署同意举办的援外活动； （十）经国际发展合作署同意印制或出版的援外刊物或其他印刷品和音像制品； （十一）国际发展合作署认为应当使用援外标识的其他情形。 特殊情形下无法按照本条第一款使用援外标识的，经国际发展合作署同意，可以不使用援外标识。"},{"i":7,"n":"第七条","txt":"经国际发展合作署同意，公民、法人或其他组织可以在相关援外项目及援外活动中使用援外标识。"},{"i":8,"n":"第八条","txt":"援外标识不得用于与对外援助无关的用途。"},{"i":9,"n":"第九条","txt":"援外标识图案和制作说明由国际发展合作署另行公告。 援外标识可按比例放大或缩小，但不得更改援外标识的图案组成、文字字体、图文比例、颜色式样等。 援外标识所附媒介的底色不得影响援外标识的标准颜色式样，不得透叠其他色彩和图案。"},{"i":10,"n":"第十条","txt":"对于成套项目和技术援助项目，援外标识应当安装于醒目位置，所使用的援外标识载体应当采用耐久材料制作，并根据项目具体情况确定标识载体的制作和安装办法。援外标识载体上除标识图案外，还可以包括国旗图案、项目信息等。"},{"i":11,"n":"第十一条","txt":"对于物资项目，援外标识应当印刷、刻制或喷涂于援外物资和包装的明显位置。 对于紧急援助物资或因工艺制作条件所限，无法采用印制、刻制或喷涂方式制作标识的援外物资，可以使用援外标识即时贴。"},{"i":12,"n":"第十二条","txt":"对于除第十条、第十一条外的其他应当或可以使用援外标识的情形，根据项目具体情况确定援外标识的制作和安装办法。"},{"i":13,"n":"第十三条","txt":"国际发展合作署负责以援外标识为图案统一监制援外徽章，供援外人员履行职责时佩戴。援外徽章图案由国际发展合作署另行公告。"},{"i":14,"n":"第十四条","txt":"国际发展合作署在与受援方签署的政府间协议中应当明确援外标识使用条款。"},{"i":15,"n":"第十五条","txt":"除紧急援助项目外，援外项目可行性研究单位负责编制援外标识使用方案，并写入可行性研究成果文件。 国际发展合作署负责审批可行性研究成果文件中的援外标识使用方案。"},{"i":16,"n":"第十六条","txt":"对于无偿援助和无息贷款项目，援外执行部门根据项目具体情况，在项目采购文件中要求编制援外标识制作和安装方案，制作和安装费用纳入项目总报价。 援外执行部门应当在与援外项目实施主体签订的项目实施合同（协议）中明确援外标识使用的具体事宜和权利义务。"},{"i":17,"n":"第十七条","txt":"成套项目项目管理企业或工程总承包企业应当在进行深化设计和施工详图设计时编制援外标识制作和安装方案。 项目管理企业应当在深化设计和施工详图设计自查或审查时一并审查援外标识的制作和安装方案，监督工程总承包企业据此组织实施。 工程总承包企业应当根据施工详图设计要求制作和安装援外标识，并按照项目实施合同使用援外标识。 竣工验收单位应当将援外标识制作和安装纳入检查范围。"},{"i":18,"n":"第十八条","txt":"物资项目总承包企业负责制作和安装援外标识，并按照项目实施合同在物资生产、包装、组货、移交等阶段使用援外标识。"},{"i":19,"n":"第十九条","txt":"技术援助项目实施单位负责制作和安装援外标识，并按照项目实施合同使用援外标识。"},{"i":20,"n":"第二十条","txt":"援外人力资源开发合作项目实施单位负责制作和安装援外标识，并按规定使用援外标识。"},{"i":21,"n":"第二十一条","txt":"南南合作援助基金项目合作方应按照项目合作协议约定使用援外标识。"},{"i":22,"n":"第二十二条","txt":"援外医疗队项目实施单位负责制作和安装援外标识，并按规定使用援外标识。"},{"i":23,"n":"第二十三条","txt":"对于援外优惠贷款项目，项目实施主体应当按照国际发展合作署批准的援外标识使用方案制作和安装援外标识，并按政府间协议规定使用援外标识。"},{"i":24,"n":"第二十四条","txt":"其他类型的援外项目及使用援外标识的其他情形，援外标识使用人应当按照国际发展合作署批准的援外标识使用方案制作和安装援外标识，并按规定使用援外标识。"},{"i":25,"n":"第二十五条","txt":"援外标识使用人在使用援外标识的过程中应按照有关规定实施项目和使用标识，维护良好的国家形象和公益形象。"},{"i":26,"n":"第二十六条","txt":"援外标识使用人只能在承担的援外项目或援外活动中使用援外标识。援外项目对外移交或援外活动结束后，援外标识使用人使用援外标识的权利自然终止。"},{"i":27,"n":"第二十七条","txt":"未经国际发展合作署同意，援外标识使用人不得将使用援外标识的权利全部或部分转让或委托给其他公民、法人或其他组织行使。"},{"i":28,"n":"第二十八条","txt":"援外标识使用人违反本办法的，由国际发展合作署责令其限期改正。"},{"i":29,"n":"第二十九条","txt":"援外标识使用人有下列行为之一的，国际发展合作署给予警告，可以并处三万元人民币以下罚款，并应当依法公布处罚决定；违反相关法律、行政法规规定的，依照法律、行政法规的规定给予行政处罚；构成犯罪的，依法追究刑事责任： （一）污损或侮辱援外标识的； （二）未经同意，擅自使用或允许他人使用援外标识的； （三）将援外标识用于与对外援助无关活动的； （四）所承担的援外项目对外移交后或援外活动结束后仍使用援外标识的； （五）应当使用援外标识而未使用，责令限期改正，逾期未改正的。"},{"i":30,"n":"第三十条","txt":"本办法由国际发展合作署负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2020年1月1日起施行。商务部《对外援助标识使用管理办法（试行）》（商务部2016年第1号令）同时废止。"}],"duiwaiyuanzhuguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了加强对外援助的战略谋划和统筹协调，规范对外援助管理，提升对外援助效果，依据有关法律、行政法规制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称对外援助是指使用政府对外援助资金向受援方提供经济、技术、物资、人才、管理等支持的活动。"},{"i":3,"n":"第三条","txt":"对外援助的受援方主要包括与中华人民共和国已经建立外交关系且有接受援助需要的发展中国家，以及以发展中国家为主的国际组织。 在人道主义援助等紧急或者特殊情况下，发达国家或者与中华人民共和国无外交关系的发展中国家也可以作为受援方。"},{"i":4,"n":"第四条","txt":"对外援助致力于帮助受援方减轻与消除贫困，改善受援方民生和生态环境，促进受援方经济发展和社会进步，增强受援方自主可持续发展能力，巩固和发展与受援方的友好合作关系，促进高质量共建“一带一路”，推动构建新型国际关系，推动构建人类命运共同体。"},{"i":5,"n":"第五条","txt":"对外援助应当坚持正确义利观和真实亲诚理念，相互尊重，平等相待，合作共赢；尊重受援国主权，不干涉他国内政，不附加任何政治条件；量力而行，尽力而为，重信守诺，善始善终；因国施策，共商共建，形式多样，注重实效。"},{"i":6,"n":"第六条","txt":"国家国际发展合作署（以下简称国际发展合作署）负责拟订对外援助方针政策，推进对外援助方式改革，归口管理对外援助资金规模和使用方向，编制对外援助项目年度预决算，确定对外援助项目，监督评估对外援助项目实施情况，组织开展对外援助国际交流合作。 商务部等对外援助执行部门（以下简称援外执行部门）负责根据对外工作需要提出对外援助相关建议，承担对外援助具体执行工作，与受援方协商和办理对外援助项目实施具体事宜，负责项目组织管理，选定对外援助项目实施主体或者派出对外援助人员，管理本部门的对外援助资金。 外交部负责根据外交工作需要提出对外援助相关建议。驻外使领馆（团）统筹管理在驻在国（国际组织）的对外援助工作，协助办理对外援助有关事务，与受援方沟通援助需求并进行政策审核，负责对外援助项目实施的境外监督管理。"},{"i":7,"n":"第七条","txt":"国际发展合作署会同有关部门建立对外援助部际协调机制，统筹协调对外援助重大问题。"},{"i":8,"n":"第八条","txt":"国际发展合作署制定统一的中国政府对外援助标识，负责标识使用的监督管理。"},{"i":9,"n":"第九条","txt":"国际发展合作署会同有关部门拟订对外援助的战略方针和中长期政策规划，按照程序报批后执行。"},{"i":10,"n":"第十条","txt":"国际发展合作署会同有关部门制定分国别的对外援助政策，按照程序报批后执行。"},{"i":11,"n":"第十一条","txt":"国际发展合作署会同有关部门拟订对外援助总体方案和年度计划，按照程序报批后执行。"},{"i":12,"n":"第十二条","txt":"国际发展合作署会同有关部门研究对外援助方式的改革措施，并推动改革措施落实。"},{"i":13,"n":"第十三条","txt":"国际发展合作署牵头推进对外援助法制化建设，与援外执行部门根据职责分工制定相应的对外援助管理制度。"},{"i":14,"n":"第十四条","txt":"国际发展合作署建立对外援助项目储备制度，搜集、审核和确定具体国别的对外援助储备项目，并对储备项目实行动态管理。 对外援助储备项目是编制对外援助资金计划和预算，以及对外援助项目立项的主要依据。"},{"i":15,"n":"第十五条","txt":"国际发展合作署拟订对外提供援助的援款协议草案，与受援方进行谈判，并以中国政府名义签署协议。"},{"i":16,"n":"第十六条","txt":"对外援助资金主要包括无偿援助、无息贷款和优惠贷款三种类型。 无偿援助主要用于受援方在减贫、减灾、民生、社会福利、公共服务、人道主义等方面的援助需求。 无息贷款主要用于受援方在公共基础设施、工农业生产等方面的援助需求。 优惠贷款主要用于受援方在具有经济效益的生产型项目、资源能源开发项目、较大规模的基础设施建设项目等方面的援助需求。"},{"i":17,"n":"第十七条","txt":"国际发展合作署通过南南合作援助基金等方式创新对外援助形式。"},{"i":18,"n":"第十八条","txt":"对外援助以项目援助为主。 在人道主义援助等紧急或者特殊情况下，可以向受援方提供现汇援助。"},{"i":19,"n":"第十九条","txt":"对外援助项目主要包括以下类型： （一）成套项目，即通过组织或者指导施工、安装和试生产全过程或者其中部分阶段，向受援方提供生产生活、公共服务等成套设备和工程设施，并提供长效质量保证和配套技术服务的项目； （二）物资项目，即向受援方提供一般生产生活物资、技术性产品或者单项设备，并承担必要配套技术服务的项目； （三）技术援助项目，即综合采用选派专家、技术工人或者提供政策和技术咨询、设备等手段帮助受援方实现某一特定政策、管理或者技术目标的项目； （四）人力资源开发合作项目，即为受援方人员提供各种形式的学历学位教育、研修培训、人员交流以及高级专家服务的项目； （五）志愿服务项目，即选派志愿者到受援方从事公益性服务的项目； （六）援外医疗队项目，即选派医务服务人员，并无偿提供部分医疗设备和药品，在受援方进行定点或者巡回医疗服务的项目； （七）紧急人道主义援助项目，即在有关国家遭受人道主义灾难的情况"},{"i":20,"n":"第二十条","txt":"对外援助项目一般通过政府间援助方式实施，主要有以下方式： （一）中方负责实施； （二）中方与受援方按商定分工合作实施； （三）在落实中方外部监督的前提下由受援方自主实施； （四）中方也可以同其他国家、国际组织、非政府组织等合作实施。"},{"i":21,"n":"第二十一条","txt":"加强对外援助资金管理、援外优惠贷款管理，有关规定另行制定。"},{"i":22,"n":"第二十二条","txt":"受援方有援助需求时，应当将项目建议通过驻外使领馆（团）向中方提出，驻外使领馆（团）对受援方提出的项目建议进行国别政策审核并形成明确意见后报外交部和国际发展合作署，并抄报援外执行部门。 援外执行部门可以根据工作需要向国际发展合作署提出项目建议。"},{"i":23,"n":"第二十三条","txt":"对外援助项目在立项前应当经过可行性研究。 中方可以要求受援方提供拟立项项目的相关资料，作为进行可行性研究的前提。"},{"i":24,"n":"第二十四条","txt":"国际发展合作署组织项目前期论证，根据可行性研究结果确定项目，并按照程序批准立项。"},{"i":25,"n":"第二十五条","txt":"对外援助项目立项后，国际发展合作署一般应当与受援方商签政府间立项协议，明确协议各方的权利和义务，主要包括项目内容、资金安排、实施配套条件、相关税收减免、安全保障等。"},{"i":26,"n":"第二十六条","txt":"对外援助项目实施过程中涉及立项协议内容重大调整的，国际发展合作署按照程序报批后可以进行调整并与外方签订补充立项协议。 援外执行部门可以向国际发展合作署提出调整的建议。"},{"i":27,"n":"第二十七条","txt":"中方同其他国家、国际组织、非政府组织等合作实施的对外援助项目，国际发展合作署一般应当与合作方商签合作协议，明确各方权利义务。"},{"i":28,"n":"第二十八条","txt":"优惠贷款项下的对外援助项目，国际发展合作署应当在承办金融机构出具评审意见后按照程序批准立项，并与受援方签署优惠贷款框架协议。"},{"i":29,"n":"第二十九条","txt":"人道主义灾难发生后，国际发展合作署会同有关部门拟订紧急援助方案，并办理立项。"},{"i":30,"n":"第三十条","txt":"国际发展合作署根据现行部门分工统筹安排援外执行部门组织实施项目。 援外执行部门依据立项批准内容组织实施对外援助项目，对对外援助项目的安全、质量、进度、投资控制等负责，可以委托有关机构组织实施管理。"},{"i":31,"n":"第三十一条","txt":"国际发展合作署会同有关部门推动重大项目实施，协调解决项目实施中的问题。"},{"i":32,"n":"第三十二条","txt":"国际发展合作署和商务部按照职责分工对对外援助项目实施主体资格进行管理，制定有关管理制度。"},{"i":33,"n":"第三十三条","txt":"对外援助项目由中方负责实施的，援外执行部门依照相关法律法规选定具体项目实施主体。"},{"i":34,"n":"第三十四条","txt":"对外援助项目实施主体不得将所承担的任务转包或者违法分包。"},{"i":35,"n":"第三十五条","txt":"对于无偿援助和无息贷款项下的援助项目，援外执行部门一般应当与受援方商签对外援助项目实施协议，明确规定对外援助项目实施的具体事宜和双方权利义务。"},{"i":36,"n":"第三十六条","txt":"对于无偿援助和无息贷款项下的援助项目，援外执行部门一般应当与实施主体商签对外援助项目实施合同，明确规定对外援助项目实施的具体事宜和双方权利义务。"},{"i":37,"n":"第三十七条","txt":"因外交、国家安全或者承担的国际义务等原因，或者因不可抗力导致对外援助项目无法实施时，国际发展合作署按照程序报批后可以中断或者终止对外援助项目。 援外执行部门可以向国际发展合作署提出中断或者终止对外援助项目的建议。"},{"i":38,"n":"第三十八条","txt":"对外援助项目执行完毕后，中方一般应当与受援方办理政府间交接手续，商签政府间交接证书。"},{"i":39,"n":"第三十九条","txt":"国际发展合作署、援外执行部门会同有关部门建立对外援助出口物资口岸验放机制。 除涉及国家实施出口管制的货物、技术、服务等物项外，对外援助物资出口不纳入配额和许可证管理。"},{"i":40,"n":"第四十条","txt":"对外援助资金应当专款专用、单独核算，任何单位和个人不得挪作他用。"},{"i":41,"n":"第四十一条","txt":"对外援助人员是指政府或者对外援助项目实施主体派遣执行对外援助任务的人员。对外援助人员在外执行对外援助任务期间享有国家规定的待遇保障。对外援助人员在受援方当地执行对外援助任务期间应当遵守中国和受援方的法律法规，尊重受援方的风俗习惯。 对外援助项目实施主体应当加强对对外援助人员的管理和监督，按照有关规定保证其派遣的对外援助人员在外执行对外援助任务期间享有相应的工作和生活待遇及人身意外伤害保障。 对外援助人员在执行对外援助任务期间作出突出贡献的，国际发展合作署和援外执行部门可以依法给予表彰。在执行对外援助任务期间牺牲的，国际发展合作署和援外执行部门可以依法报请有关部门评定为烈士。"},{"i":42,"n":"第四十二条","txt":"对于对外援助项目实施主体的违法违规行为，任何单位和个人可以依法向国际发展合作署和援外执行部门投诉或者举报。"},{"i":43,"n":"第四十三条","txt":"国际发展合作署会同援外执行部门建立对外援助项目监督制度，对对外援助项目的实施情况进行监督。"},{"i":44,"n":"第四十四条","txt":"国际发展合作署会同援外执行部门建立对外援助项目评估制度，制定对外援助项目实施情况评估标准，组织开展评估。"},{"i":45,"n":"第四十五条","txt":"国际发展合作署会同援外执行部门建立对外援助项目实施主体诚信评价体系，按照职责分工对实施主体参与对外援助项目过程中的行为进行信用评价和管理。"},{"i":46,"n":"第四十六条","txt":"国际发展合作署会同援外执行部门建立对外援助项目信息报送制度。 援外执行部门向国际发展合作署报送对外援助项目组织实施情况，以及项目组织实施过程中出现的质量、安全、进度和投资控制等重大问题。 驻外使领馆（团）向国际发展合作署、外交部和援外执行部门报送对外援助项目境外监管中发现的质量、安全、进度和投资控制等重大问题。"},{"i":47,"n":"第四十七条","txt":"国际发展合作署会同援外执行部门依法建立对外援助统计制度，收集、汇总和编制对外援助统计资料。 援外执行部门、省级人民政府有关部门、有关单位应当按照对外援助统计制度，定期向国际发展合作署报送统计数据及相关信息。"},{"i":48,"n":"第四十八条","txt":"对外援助项目实施主体有下列行为之一的，国际发展合作署、援外执行部门依职权给予警告或者通报批评，可以并处人民币3万元以下罚款，并依法公开处罚决定： （一）将所承担的对外援助项目任务转包或者违法分包的； （二）未按对外援助项目实施合同履行义务或者迟延履行义务，影响项目正常实施，造成严重不良影响的； （三）挪用对外援助资金的； （四）未按规定保证外派对外援助人员工作和生活待遇，未提供人身意外伤害保障的。 对外援助项目实施主体违反相关法律、行政法规规定的，依照规定给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"国际发展合作署、援外执行部门和驻外使领馆（团）的工作人员在对外援助管理中有下列行为之一的，视情节轻重给予相应处分；构成犯罪的，依法追究刑事责任： （一）利用职务便利索取他人财物，或者非法收受他人财物为他人谋取利益的； （二）滥用职权、玩忽职守或者徇私舞弊，致使国家利益遭受损失的； （三）泄露国家秘密的。"},{"i":50,"n":"第五十条","txt":"对外军事援助，按照国家和军队有关规定执行。"},{"i":51,"n":"第五十一条","txt":"本办法自2021年10月1日起施行。商务部《对外援助管理办法（试行）》（商务部令2014年第5号）同时废止。"}],"duiwaiyuanzhuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对外援助的战略谋划和统筹协调，规范对外援助管理，提升对外援助效果，依据有关法律、行政法规制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称对外援助是指使用政府对外援助资金向受援方提供经济、技术、物资、人才、管理等支持的活动。"},{"i":3,"n":"第三条","txt":"对外援助的受援方主要包括与中华人民共和国已经建立外交关系且有接受援助需要的发展中国家，以及以发展中国家为主的国际组织。 在人道主义援助等紧急或者特殊情况下，发达国家或者与中华人民共和国无外交关系的发展中国家也可以作为受援方。"},{"i":4,"n":"第四条","txt":"对外援助致力于帮助受援方减轻与消除贫困，改善受援方民生和生态环境，促进受援方经济发展和社会进步，增强受援方自主可持续发展能力，巩固和发展与受援方的友好合作关系，促进高质量共建“一带一路”，推动构建新型国际关系，推动构建人类命运共同体。"},{"i":5,"n":"第五条","txt":"对外援助应当坚持正确义利观和真实亲诚理念，相互尊重，平等相待，合作共赢；尊重受援国主权，不干涉他国内政，不附加任何政治条件；量力而行，尽力而为，重信守诺，善始善终；因国施策，共商共建，形式多样，注重实效。"},{"i":6,"n":"第六条","txt":"国家国际发展合作署（以下简称国际发展合作署）负责拟订对外援助方针政策，推进对外援助方式改革，归口管理对外援助资金规模和使用方向，编制对外援助项目年度预决算，确定对外援助项目，监督评估对外援助项目实施情况，组织开展对外援助国际交流合作。 商务部等对外援助执行部门（以下简称援外执行部门）负责根据对外工作需要提出对外援助相关建议，承担对外援助具体执行工作，与受援方协商和办理对外援助项目实施具体事宜，负责项目组织管理，选定对外援助项目实施主体或者派出对外援助人员，管理本部门的对外援助资金。 外交部负责根据外交工作需要提出对外援助相关建议。驻外使领馆（团）统筹管理在驻在国（国际组织）的对外援助工作，协助办理对外援助有关事务，与受援方沟通援助需求并进行政策审核，负责对外援助项目实施的境外监督管理。"},{"i":7,"n":"第七条","txt":"国际发展合作署会同有关部门建立对外援助部际协调机制，统筹协调对外援助重大问题。"},{"i":8,"n":"第八条","txt":"国际发展合作署制定统一的中国政府对外援助标识，负责标识使用的监督管理。"},{"i":9,"n":"第九条","txt":"国际发展合作署会同有关部门拟订对外援助的战略方针和中长期政策规划，按照程序报批后执行。"},{"i":10,"n":"第十条","txt":"国际发展合作署会同有关部门制定分国别的对外援助政策，按照程序报批后执行。"},{"i":11,"n":"第十一条","txt":"国际发展合作署会同有关部门拟订对外援助总体方案和年度计划，按照程序报批后执行。"},{"i":12,"n":"第十二条","txt":"国际发展合作署会同有关部门研究对外援助方式的改革措施，并推动改革措施落实。"},{"i":13,"n":"第十三条","txt":"国际发展合作署牵头推进对外援助法制化建设，与援外执行部门根据职责分工制定相应的对外援助管理制度。"},{"i":14,"n":"第十四条","txt":"国际发展合作署建立对外援助项目储备制度，搜集、审核和确定具体国别的对外援助储备项目，并对储备项目实行动态管理。 对外援助储备项目是编制对外援助资金计划和预算，以及对外援助项目立项的主要依据。"},{"i":15,"n":"第十五条","txt":"国际发展合作署拟订对外提供援助的援款协议草案，与受援方进行谈判，并以中国政府名义签署协议。"},{"i":16,"n":"第十六条","txt":"对外援助资金主要包括无偿援助、无息贷款和优惠贷款三种类型。 无偿援助主要用于受援方在减贫、减灾、民生、社会福利、公共服务、人道主义等方面的援助需求。 无息贷款主要用于受援方在公共基础设施、工农业生产等方面的援助需求。 优惠贷款主要用于受援方在具有经济效益的生产型项目、资源能源开发项目、较大规模的基础设施建设项目等方面的援助需求。"},{"i":17,"n":"第十七条","txt":"国际发展合作署通过南南合作援助基金等方式创新对外援助形式。"},{"i":18,"n":"第十八条","txt":"对外援助以项目援助为主。 在人道主义援助等紧急或者特殊情况下，可以向受援方提供现汇援助。"},{"i":19,"n":"第十九条","txt":"对外援助项目主要包括以下类型： （一）成套项目，即通过组织或者指导施工、安装和试生产全过程或者其中部分阶段，向受援方提供生产生活、公共服务等成套设备和工程设施，并提供长效质量保证和配套技术服务的项目； （二）物资项目，即向受援方提供一般生产生活物资、技术性产品或者单项设备，并承担必要配套技术服务的项目； （三）技术援助项目，即综合采用选派专家、技术工人或者提供政策和技术咨询、设备等手段帮助受援方实现某一特定政策、管理或者技术目标的项目； （四）人力资源开发合作项目，即为受援方人员提供各种形式的学历学位教育、研修培训、人员交流以及高级专家服务的项目； （五）志愿服务项目，即选派志愿者到受援方从事公益性服务的项目； （六）援外医疗队项目，即选派医务服务人员，并无偿提供部分医疗设备和药品，在受援方进行定点或者巡回医疗服务的项目； （七）紧急人道主义援助项目，即在有关国家遭受人道主义灾难的情况"},{"i":20,"n":"第二十条","txt":"对外援助项目一般通过政府间援助方式实施，主要有以下方式： （一）中方负责实施； （二）中方与受援方按商定分工合作实施； （三）在落实中方外部监督的前提下由受援方自主实施； （四）中方也可以同其他国家、国际组织、非政府组织等合作实施。"},{"i":21,"n":"第二十一条","txt":"加强对外援助资金管理、援外优惠贷款管理，有关规定另行制定。"},{"i":22,"n":"第二十二条","txt":"受援方有援助需求时，应当将项目建议通过驻外使领馆（团）向中方提出，驻外使领馆（团）对受援方提出的项目建议进行国别政策审核并形成明确意见后报外交部和国际发展合作署，并抄报援外执行部门。 援外执行部门可以根据工作需要向国际发展合作署提出项目建议。"},{"i":23,"n":"第二十三条","txt":"对外援助项目在立项前应当经过可行性研究。 中方可以要求受援方提供拟立项项目的相关资料，作为进行可行性研究的前提。"},{"i":24,"n":"第二十四条","txt":"国际发展合作署组织项目前期论证，根据可行性研究结果确定项目，并按照程序批准立项。"},{"i":25,"n":"第二十五条","txt":"对外援助项目立项后，国际发展合作署一般应当与受援方商签政府间立项协议，明确协议各方的权利和义务，主要包括项目内容、资金安排、实施配套条件、相关税收减免、安全保障等。"},{"i":26,"n":"第二十六条","txt":"对外援助项目实施过程中涉及立项协议内容重大调整的，国际发展合作署按照程序报批后可以进行调整并与外方签订补充立项协议。 援外执行部门可以向国际发展合作署提出调整的建议。"},{"i":27,"n":"第二十七条","txt":"中方同其他国家、国际组织、非政府组织等合作实施的对外援助项目，国际发展合作署一般应当与合作方商签合作协议，明确各方权利义务。"},{"i":28,"n":"第二十八条","txt":"优惠贷款项下的对外援助项目，国际发展合作署应当在承办金融机构出具评审意见后按照程序批准立项，并与受援方签署优惠贷款框架协议。"},{"i":29,"n":"第二十九条","txt":"人道主义灾难发生后，国际发展合作署会同有关部门拟订紧急援助方案，并办理立项。"},{"i":30,"n":"第三十条","txt":"国际发展合作署根据现行部门分工统筹安排援外执行部门组织实施项目。 援外执行部门依据立项批准内容组织实施对外援助项目，对对外援助项目的安全、质量、进度、投资控制等负责，可以委托有关机构组织实施管理。"},{"i":31,"n":"第三十一条","txt":"国际发展合作署会同有关部门推动重大项目实施，协调解决项目实施中的问题。"},{"i":32,"n":"第三十二条","txt":"国际发展合作署和商务部按照职责分工对对外援助项目实施主体资格进行管理，制定有关管理制度。"},{"i":33,"n":"第三十三条","txt":"对外援助项目由中方负责实施的，援外执行部门依照相关法律法规选定具体项目实施主体。"},{"i":34,"n":"第三十四条","txt":"对外援助项目实施主体不得将所承担的任务转包或者违法分包。"},{"i":35,"n":"第三十五条","txt":"对于无偿援助和无息贷款项下的援助项目，援外执行部门一般应当与受援方商签对外援助项目实施协议，明确规定对外援助项目实施的具体事宜和双方权利义务。"},{"i":36,"n":"第三十六条","txt":"对于无偿援助和无息贷款项下的援助项目，援外执行部门一般应当与实施主体商签对外援助项目实施合同，明确规定对外援助项目实施的具体事宜和双方权利义务。"},{"i":37,"n":"第三十七条","txt":"因外交、国家安全或者承担的国际义务等原因，或者因不可抗力导致对外援助项目无法实施时，国际发展合作署按照程序报批后可以中断或者终止对外援助项目。 援外执行部门可以向国际发展合作署提出中断或者终止对外援助项目的建议。"},{"i":38,"n":"第三十八条","txt":"对外援助项目执行完毕后，中方一般应当与受援方办理政府间交接手续，商签政府间交接证书。"},{"i":39,"n":"第三十九条","txt":"国际发展合作署、援外执行部门会同有关部门建立对外援助出口物资口岸验放机制。 除涉及国家实施出口管制的货物、技术、服务等物项外，对外援助物资出口不纳入配额和许可证管理。"},{"i":40,"n":"第四十条","txt":"对外援助资金应当专款专用、单独核算，任何单位和个人不得挪作他用。"},{"i":41,"n":"第四十一条","txt":"对外援助人员是指政府或者对外援助项目实施主体派遣执行对外援助任务的人员。对外援助人员在外执行对外援助任务期间享有国家规定的待遇保障。对外援助人员在受援方当地执行对外援助任务期间应当遵守中国和受援方的法律法规，尊重受援方的风俗习惯。 对外援助项目实施主体应当加强对对外援助人员的管理和监督，按照有关规定保证其派遣的对外援助人员在外执行对外援助任务期间享有相应的工作和生活待遇及人身意外伤害保障。 对外援助人员在执行对外援助任务期间作出突出贡献的，国际发展合作署和援外执行部门可以依法给予表彰。在执行对外援助任务期间牺牲的，国际发展合作署和援外执行部门可以依法报请有关部门评定为烈士。"},{"i":42,"n":"第四十二条","txt":"对于对外援助项目实施主体的违法违规行为，任何单位和个人可以依法向国际发展合作署和援外执行部门投诉或者举报。"},{"i":43,"n":"第四十三条","txt":"国际发展合作署会同援外执行部门建立对外援助项目监督制度，对对外援助项目的实施情况进行监督。"},{"i":44,"n":"第四十四条","txt":"国际发展合作署会同援外执行部门建立对外援助项目评估制度，制定对外援助项目实施情况评估标准，组织开展评估。"},{"i":45,"n":"第四十五条","txt":"国际发展合作署会同援外执行部门建立对外援助项目实施主体诚信评价体系，按照职责分工对实施主体参与对外援助项目过程中的行为进行信用评价和管理。"},{"i":46,"n":"第四十六条","txt":"国际发展合作署会同援外执行部门建立对外援助项目信息报送制度。 援外执行部门向国际发展合作署报送对外援助项目组织实施情况，以及项目组织实施过程中出现的质量、安全、进度和投资控制等重大问题。 驻外使领馆（团）向国际发展合作署、外交部和援外执行部门报送对外援助项目境外监管中发现的质量、安全、进度和投资控制等重大问题。"},{"i":47,"n":"第四十七条","txt":"国际发展合作署会同援外执行部门依法建立对外援助统计制度，收集、汇总和编制对外援助统计资料。 援外执行部门、省级人民政府有关部门、有关单位应当按照对外援助统计制度，定期向国际发展合作署报送统计数据及相关信息。"},{"i":48,"n":"第四十八条","txt":"对外援助项目实施主体有下列行为之一的，国际发展合作署、援外执行部门依职权给予警告或者通报批评，可以并处人民币3万元以下罚款，并依法公开处罚决定： （一）将所承担的对外援助项目任务转包或者违法分包的； （二）未按对外援助项目实施合同履行义务或者迟延履行义务，影响项目正常实施，造成严重不良影响的； （三）挪用对外援助资金的； （四）未按规定保证外派对外援助人员工作和生活待遇，未提供人身意外伤害保障的。 对外援助项目实施主体违反相关法律、行政法规规定的，依照规定给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"国际发展合作署、援外执行部门和驻外使领馆（团）的工作人员在对外援助管理中有下列行为之一的，视情节轻重给予相应处分；构成犯罪的，依法追究刑事责任： （一）利用职务便利索取他人财物，或者非法收受他人财物为他人谋取利益的； （二）滥用职权、玩忽职守或者徇私舞弊，致使国家利益遭受损失的； （三）泄露国家秘密的。"},{"i":50,"n":"第五十条","txt":"对外军事援助，按照国家和军队有关规定执行。"},{"i":51,"n":"第五十一条","txt":"本办法自2021年10月1日起施行。商务部《对外援助管理办法（试行）》（商务部令2014年第5号）同时废止。"}],"duiwaiyuanzhuxiangmuzixunfuwudanweizigerendingbanf8d654c":[{"i":1,"n":"第一条","txt":"为规范对外援助项目咨询服务单位（以下简称援外项目咨询服务单位）资格认定，依据《行政许可法》和《国务院对确需保留的行政审批项目设定行政许可的决定》（国务院令2004年第412号），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称援外项目咨询服务单位是指经资格认定，可承担中国政府对外援助项目咨询服务任务的法人组织。 援外项目咨询服务单位包括： （一）可行性研究单位，承担援外项目可行性研究任务。具体分为： 1.工程类可行性研究单位，承担援外成套项目、以附带工程为主的技术援助项目的可行性研究任务。 2.物资类可行性研究单位，承担援外物资项目、以提供物资为主的技术援助项目的可行性研究任务。 3.服务类可行性研究单位，承担规划编制、政策咨询、教育培训、技术服务等以派遣专家为主的技术援助项目的可行性研究任务。 （二）项目咨询单位，承担援外项目预可行性研究、准备性技术研究、项目建议书编制、援外优惠贷款申请报告编制、重大战略项目融资方案编制和项目申请等立项前期咨询服务任务。 （三）评估咨询单位，承担援外项目可行性研究报告和项目建议书评估、援外优惠贷款申请报告评审、重大战略项目融资方案和项目申请报告评估、项目实施情况"},{"i":3,"n":"第三条","txt":"国家国际发展合作署（以下简称国际发展合作署）负责援外项目咨询服务单位的资格认定和资格管理。 省、自治区、直辖市人民政府及新疆生产建设兵团负责对外援助工作的具体部门（以下统称省级主管部门）协助国际发展合作署进行援外项目咨询服务单位资格认定。"},{"i":4,"n":"第四条","txt":"经资格认定的援外项目咨询服务单位可在相应的资格类别范围内承担援外项目咨询服务任务。"},{"i":5,"n":"第五条","txt":"援外项目咨询服务单位应具备以下基本资格条件： （一）系依照中国法律在中国境内设立的法人，包括企业、事业单位和社会团体； （二）所有出资人均为中国投资者； （三）具备能够从事对外援助工作的专业部门和五名以上咨询工作人员，其中主要业务负责人从事咨询业务不少于十年； （四）具备相应类别的境内（外）咨询服务业绩，具体业绩标准另行公告； （五）前两个会计年度未出现亏损； （六）前两年未受过刑事处罚、未因进行非法经营活动或违反有关援外管理规章受过行政处罚； （七）依法纳税和缴纳社会保险费； （八）具有良好的经营诚信表现。"},{"i":6,"n":"第六条","txt":"申请工程类可行性研究单位资格的，除具备第五条规定的基本资格条件外，还应具备国务院相关行业主管部门颁发的工程设计综合甲级或行业甲级资质，且符合国务院相关行业主管部门指导认定的工程咨询单位甲级资信评价标准。"},{"i":7,"n":"第七条","txt":"申请项目咨询单位资格的，除具备第五条规定的基本资格条件外，还应符合国务院相关行业主管部门指导认定的工程咨询单位甲级资信评价标准。"},{"i":8,"n":"第八条","txt":"申请评估咨询单位资格的，除具备第五条规定的基本资格条件外，还应符合国务院相关行业主管部门指导认定的工程咨询单位综合甲级资信评价标准。"},{"i":9,"n":"第九条","txt":"申请经济技术咨询单位资格的，除具备第五条规定的基本资格条件外，还应具备国务院相关主管部门颁发的工程造价咨询企业甲级资质。"},{"i":10,"n":"第十条","txt":"咨询服务单位申请援外项目咨询服务单位资格，应向国际发展合作署提交以下文件： （一）申请书； （二）单位法人及其法定代表人身份证明文件； （三）企业出资情况证明文件和出资人身份证明文件，事业单位法人登记有关证明文件，或社会团体登记有关证明文件； （四）专业技术力量情况说明，包括单位能够从事对外援助工作的专业部门及其工作人员名单，以及主要业务负责人的工作履历； （五）开展境内（外）项目咨询服务的业绩证明材料； （六）前两个年度单位会计报表； （七）本单位关于前两年未受过刑事处罚、未因进行非法经营活动或违反有关援外管理规章受过行政处罚的声明； （八）税务机关出具的前两年完税证明； （九）社会保险经办机构出具的前两年缴费证明。 除上述文件外，申请工程类可行性研究单位资格还需提交国务院相关行业主管部门颁发的工程设计综合甲级或行业甲级资质证书，以及国务院相关行业主管部门指导认定的工程咨询单位甲级资"},{"i":11,"n":"第十一条","txt":"在国务院相关主管部门和机构登记的咨询服务单位直接向国际发展合作署提交申请，其他单位向所在地省级主管部门提交申请。"},{"i":12,"n":"第十二条","txt":"向省级主管部门申请的，省级主管部门应当在收到申请文件之日起五个工作日内完成初核，将申请文件连同初核意见一并报国际发展合作署审核。"},{"i":13,"n":"第十三条","txt":"国际发展合作署应在收到完备申请文件之日起二十个工作日内或收到省级主管部门初核意见之日起十五个工作日内完成审核，作出许可与否的决定。 准予许可的，国际发展合作署颁发有效期为两年的许可文件；不予许可的，国际发展合作署应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":14,"n":"第十四条","txt":"国际发展合作署应公布经资格认定取得资格的援外项目咨询服务单位名单。"},{"i":15,"n":"第十五条","txt":"取得资格的咨询服务单位需要延续资格许可有效期的,应当在有效期届满六十日前根据第十条和第十一条向国际发展合作署或所在地省级主管部门提出申请。"},{"i":16,"n":"第十六条","txt":"省级主管部门和国际发展合作署根据第十二条和第十三条规定的期限对申请进行初核或审核，国际发展合作署在许可有效期届满前作出是否准予延期的决定。"},{"i":17,"n":"第十七条","txt":"准予延期的，国际发展合作署颁发准予延期的许可文件；不予延期的，国际发展合作署应当说明理由，并告知咨询服务单位享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":18,"n":"第十八条","txt":"援外项目咨询服务单位发生单位名称、单位类型、法定代表人、出资情况变更的，应在变更之日起一个月内向国际发展合作署备案，提供以下文件： （一）变更申请表； （二）变更登记证明文件； （三）变更后的相关证明文件。"},{"i":19,"n":"第十九条","txt":"援外项目咨询服务单位发生改制、分立或合并情形的，改制、分立或合并后新成立的单位应按照本办法规定重新申请资格认定。"},{"i":20,"n":"第二十条","txt":"国际发展合作署建立援外项目咨询服务单位诚信评价体系，对咨询服务单位遵守援外管理规章和履行咨询服务合同等情况进行评价。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，国际发展合作署可依据职权或根据利害关系人的请求，撤销援外项目咨询服务单位资格： （一）行政机关工作人员滥用职权、玩忽职守作出援外项目咨询服务单位资格许可决定的； （二）违反法定程序作出援外项目咨询服务单位资格许可决定的； （三）对不具备申请资格或不符合法定条件的申请人准予援外项目咨询服务单位资格许可的。 咨询服务单位以欺骗、贿赂等不正当手段获得资格的，国际发展合作署应撤销其资格。"},{"i":22,"n":"第二十二条","txt":"援外项目咨询服务单位因有效期届满而丧失资格，不影响已中标项目的实施。"},{"i":23,"n":"第二十三条","txt":"咨询服务单位有下列情形之一的，国际发展合作署给予警告，可以并处三万元人民币以下罚款；违反相关法律、行政法规规定的，依照相关法律、行政法规的规定给予行政处罚；构成犯罪的，依法追究刑事责任： （一）以欺骗、贿赂等不正当手段获得援外项目咨询服务单位资格的； （二）以出租、出借等方式非法转让援外项目咨询服务单位资格的； （三）隐瞒有关情况或者提供虚假材料获得援外项目咨询服务单位资格的。"},{"i":24,"n":"第二十四条","txt":"国际发展合作署和省级主管部门工作人员在援外项目咨询服务单位资格管理过程中，违反有关法律法规和本办法规定的，视情节轻重给予相应处分；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"对于暂无单位经资格认定取得援外项目咨询服务单位资格的专业领域，该专业咨询服务单位的选定按照援外项目采购规定执行。"},{"i":26,"n":"第二十六条","txt":"本办法所称“中国投资者”不包括外商投资企业。"},{"i":27,"n":"第二十七条","txt":"本办法自2020年12月1日起施行。施行之日起，《对外援助项目实施企业资格认定办法（试行）》（商务部令2015年第1号）中援外项目咨询服务单位有关规定与本办法规定不一致的，以本办法规定为准。"}],"yingjiguanlixingzhengzhifarenyuanyifalvzhiguanligu08778e":[{"i":1,"n":"第一条","txt":"为了全面贯彻落实行政执法责任制和问责制，监督和保障应急管理行政执法人员依法履职尽责，激励新时代新担当新作为，根据《中华人民共和国公务员法》《中华人民共和国安全生产法》等法律法规和有关文件规定，制定本规定。"},{"i":2,"n":"第二条","txt":"各级应急管理部门监督和保障应急管理行政执法人员依法履职尽责，适用本规定。法律、行政法规或者国务院另有规定的，从其规定。 本规定所称应急管理行政执法人员，是指应急管理部门履行行政检查、行政强制、行政处罚、行政许可等行政执法职责的人员。 应急管理系统矿山安全监察机构、地震工作机构、消防救援机构监督和保障有关行政执法人员依法履职尽责，按照本规定的相关规定执行。根据依法授权或者委托履行应急管理行政执法职责的乡镇政府、街道办事处以及开发区等组织，监督和保障有关行政执法人员依法履职尽责的，可以参照本规定执行。"},{"i":3,"n":"第三条","txt":"监督和保障应急管理行政执法人员依法履职尽责，应当坚持中国共产党的领导，遵循职权法定、权责一致、过罚相当、约束与激励并重、惩戒与教育相结合的原则，做到尽职免责、失职问责。"},{"i":4,"n":"第四条","txt":"应急管理部门应当按照本级人民政府的安排，梳理本部门行政执法依据，编制权责清单，将本部门依法承担的行政执法职责分解落实到所属执法机构和执法岗位。分解落实所属执法机构、执法岗位的执法职责，不得擅自增加或者减少本部门的行政执法权限。 应急管理部门应当制定安全生产年度监督检查计划，按照计划组织开展监督检查。同时，应急管理部门应当按照部署组织开展有关专项治理，依法组织查处违法行为和举报的事故隐患。应急管理部门应当统筹开展前述执法活动，确保对辖区内安全监管重点企业按照明确的时间周期固定开展“全覆盖”执法检查。 应急管理部门应当对照权责清单，对行政许可和其他直接影响行政相对人权利义务的重要权责事项，制定办事指南和运行流程图，并以适当形式向社会公众公开。"},{"i":5,"n":"第五条","txt":"应急管理行政执法人员根据本部门的安排或者当事人的申请，在法定权限范围内依照法定程序履行行政检查、行政强制、行政处罚、行政许可等行政执法职责，做到严格规范公正文明执法，不得玩忽职守、超越职权、滥用职权、徇私舞弊。"},{"i":6,"n":"第六条","txt":"应急管理行政执法人员因故意或者重大过失，未履行、不当履行或者违法履行有关行政执法职责，造成危害后果或者不良影响的，应当依法承担行政执法责任。"},{"i":7,"n":"第七条","txt":"应急管理行政执法人员在履职过程中，有下列情形之一的，应当依法追究有关行政执法人员的行政执法责任： （一）对符合行政处罚立案标准的案件不立案或者不及时立案的； （二）对符合法定条件的行政许可申请不予受理的，或者未依照法定条件作出准予或者不予行政许可决定的； （三）对监督检查中已经发现的违法行为和事故隐患，未依法予以处罚或者未依法采取处理措施的； （四）涂改、隐匿、伪造、偷换、故意损毁有关记录或者证据，妨碍作证，或者指使、支持、授意他人做伪证，或者以欺骗、利诱等方式调取证据的； （五）违法扩大查封、扣押范围，在查封、扣押法定期间不作出处理决定或者未依法及时解除查封、扣押，对查封、扣押场所、设施或者财物未尽到妥善保管义务，或者违法使用、损毁查封、扣押场所、设施或者财物的； （六）违法实行检查措施或者强制措施，给公民人身或者财产造成损害、给法人或者其他组织造成损失的； （七）选择性执法或者滥用"},{"i":8,"n":"第八条","txt":"应急管理行政执法人员在履职过程中，有下列情形之一的，应当从重追究其行政执法责任： （一）干扰、妨碍、抗拒对其追究行政执法责任的； （二）打击报复申诉人、控告人、检举人或者行政执法责任追究案件承办人员的； （三）一年内出现2次以上应当追究行政执法责任情形的； （四）违法或者不当执法行为造成重大经济损失或者严重社会影响的； （五）法律、法规、规章规定的其他应当从重追究行政执法责任的情形。"},{"i":9,"n":"第九条","txt":"应急管理行政执法人员在履职过程中，有下列情形之一的，可以从轻、减轻追究其行政执法责任： （一）能够主动、及时报告过错行为并采取补救措施，有效避免损失、阻止危害后果发生或者挽回、消除不良影响的； （二）在调查核实过程中，能够配合调查核实工作，如实说明本人行政执法过错情况的； （三）检举同案人或者其他人应当追究行政执法责任的问题，或者有其他立功表现，经查证属实的； （四）主动上交或者退赔违法所得的； （五）法律、法规、规章规定的其他可以从轻、减轻追究行政执法责任的情形。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，不予追究有关行政执法人员的行政执法责任： （一）因行政执法依据不明确或者对有关事实和依据的理解认识不一致，致使行政执法行为出现偏差的，但故意违法的除外； （二）因行政相对人隐瞒有关情况或者提供虚假材料导致作出错误行政执法决定，且已按照规定认真履行审查职责的； （三）依据检验、检测、鉴定、评价报告或者专家评审意见等作出行政执法决定，且已按照规定认真履行审查职责的； （四）行政相对人未依法申请行政许可或者登记备案，在其违法行为造成不良影响前，应急管理部门未接到投诉举报或者由于客观原因未能发现的，但未按照规定履行监督检查职责的除外； （五）按照批准、备案的安全生产年度监督检查计划以及有关专项执法工作方案等检查计划已经认真履行监督检查职责，或者虽尚未进行监督检查，但未超过法定或者规定时限，行政相对人违法的； （六）因出现新的证据致使原认定事实、案件性质发生变化，或者因标准缺失"},{"i":11,"n":"第十一条","txt":"在推进应急管理行政执法改革创新中因缺乏经验、先行先试出现的失误，尚无明确限制的探索性试验中的失误，为推动发展的无意过失，免予或者不予追究行政执法责任。但是，应当及时依法予以纠正。"},{"i":12,"n":"第十二条","txt":"应急管理部门对发现的行政执法过错行为线索，依照《行政机关公务员处分条例》等规定的程序予以调查和处理。"},{"i":13,"n":"第十三条","txt":"追究应急管理行政执法人员行政执法责任，应当充分听取当事执法人员的意见，全面收集相关证据材料，以法律、法规、规章等规定为依据，综合考虑行政执法过错行为的性质、情节、危害程度以及执法人员的主观过错等因素，做到事实清楚、证据确凿、定性准确、处理恰当、程序合法、手续完备。 行政执法过错行为情节轻微、危害较小，且具有法定从轻或者减轻情形的，根据不同情况，可以予以谈话提醒、批评教育、责令检查、诫勉、取消当年评优评先资格、调离执法岗位等处理，免予或者不予处分。"},{"i":14,"n":"第十四条","txt":"应急管理部门发现有关行政执法人员涉嫌违反党纪或者涉嫌职务违法、职务犯罪的，应当依照有关规定及时移送纪检监察机关处理。 纪检监察机关和其他有权单位介入调查的，应急管理部门可以按照要求对有关行政执法人员是否依法履职、是否存在行政执法过错行为等问题，组织相关专业人员进行论证并出具书面论证意见，作为有权机关、单位认定责任的参考。 对同一行政执法过错行为，纪检监察机关已经给予党纪、政务处分的，应急管理部门不再重复处理。"},{"i":15,"n":"第十五条","txt":"应急管理行政执法人员依法履行职责受法律保护。有权拒绝任何单位和个人违反法定职责、法定程序或者有碍执法公正的要求。 对地方各级党委、政府以及有关部门、单位领导干部及相关人员非法干预应急管理行政执法活动的，应急管理行政执法人员应当全面、如实记录，其所在应急管理部门应当及时向有关机关通报反映情况。"},{"i":16,"n":"第十六条","txt":"应急管理行政执法人员因依法履行职责遭受不实举报、诬告陷害以及侮辱诽谤，致使名誉受到损害的，其所在的应急管理部门应当以适当方式及时澄清事实，消除不良影响，维护应急管理行政执法人员声誉，并依法追究相关单位或者个人的责任。 应急管理行政执法人员因依法履行职责，本人或者其近亲属遭受恐吓威胁、滋事骚扰、攻击辱骂或者人身、财产受到侵害的，其所在的应急管理部门应当及时告知当地公安机关并协助依法处置。"},{"i":17,"n":"第十七条","txt":"各级应急管理部门应当为应急管理行政执法人员依法履行职责提供必要的办公用房、执法装备、后勤保障等条件，并采取措施保障其人身健康和生命安全。"},{"i":18,"n":"第十八条","txt":"各级应急管理部门应当加强对应急管理行政执法人员的专业培训，建立标准化制度化培训机制，提升应急管理行政执法人员依法履职能力。 应急管理部门应当适应综合行政执法体制改革需要，组织开展应急管理领域综合行政执法人才能力提升行动，培养应急管理行政执法骨干人才。"},{"i":19,"n":"第十九条","txt":"应急管理部门应当建立健全评议考核制度，遵循公开、公平、公正原则，将应急管理行政执法人员依法履职尽责情况纳入行政执法评议考核范围，有关考核标准、过程和结果以适当方式在一定范围内公开。强化考核结果分析运用，并将其作为干部选拔任用、评优评先的重要依据。"},{"i":20,"n":"第二十条","txt":"对坚持原则、敢抓敢管、勇于探索、担当作为，在防范化解重大安全风险、应急抢险救援等方面或者在行政执法改革创新中作出突出贡献的应急管理行政执法人员，应当按照规定给予表彰奖励。"},{"i":21,"n":"第二十一条","txt":"本规定自2022年12月1日起施行。原国家安全生产监督管理总局2009年7月25日公布、2013年8月29日第一次修正、2015年4月2日第二次修正的《安全生产监管监察职责和行政执法责任追究的规定》同时废止。"}],"jianzhushigongtezhongzuoyerenyuanguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对建筑施工特种作业人员的管理，预防和减少生产安全事故，保障人民群众生命和财产安全，根据《中华人民共和国建筑法》、《中华人民共和国安全生产法》、《中华人民共和国特种设备安全法》、《建设工程安全生产管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"建筑施工特种作业人员职业资格认定、从业及监督管理，适用本规定。 本规定所称建筑施工特种作业人员，是指在房屋建筑和市政基础设施工程（以下简称房屋市政工程）施工活动中，所从事工种危险因素较多、危险性较大，发生生产安全事故对本人、他人的人身安全，以及设备、设施、建筑和环境安全可能造成重大危害的作业人员。 建筑施工特种作业工种范围另行规定。"},{"i":3,"n":"第三条","txt":"建筑施工特种作业人员应当依法参加专门的安全作业培训并考核合格，取得建筑施工特种作业操作资格证书（以下简称资格证书），方可上岗从事相应的施工作业。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责全国建筑施工特种作业人员管理的指导监督。 县级以上地方人民政府住房城乡建设主管部门负责本行政区域内建筑施工特种作业人员从业行为的监督管理。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人民政府住房城乡建设主管部门（以下简称考核发证机关）负责建筑施工特种作业人员职业资格认定，可以依法委托设区的市级人民政府住房城乡建设主管部门实施考核相关工作。"},{"i":6,"n":"第六条","txt":"申请人可以向户籍所在地或者就业所在地的考核发证机关报名参加建筑施工特种作业人员操作资格考核。"},{"i":7,"n":"第七条","txt":"报名参加建筑施工特种作业操作资格考核的人员，应当具备下列基本条件： （一）年满18周岁； （二）初中以上学历； （三）经二级及以上医院体检合格，且无器质性心脏病、癫痫病、美尼尔氏综合症、眩晕症、癔病、震颤麻痹、精神病、吸毒史以及其他不适合从事建筑施工特种作业的疾病和生理缺陷； （四）5年内不存在因违反建筑施工安全生产管理有关规定作业，造成生产安全事故或者受到刑事处罚的情形； （五）在依法开展培训的机构完成安全作业培训，具备建筑施工特种作业相关理论知识和技术能力。 资格证书有效期内，申请人不得就同一工种重复申请。"},{"i":8,"n":"第八条","txt":"考核发证机关应当组织制定本地区考核计划，并及时上传至全国工程质量安全监管信息平台。考核计划应当明确考核时间、考核工种、考核地点等内容。 考核发证机关应当根据本地区考核经费、考核场地及设备设施等情况，合理安排考核场次和各场次考核人员数量。每年集中考核原则上不少于2次。"},{"i":9,"n":"第九条","txt":"建筑施工特种作业操作资格考核包括技术理论和操作技能两门科目。技术理论考核通过后，方可参加操作技能考核。两门科目均考核通过的，为考核合格。 考核大纲由国务院住房城乡建设主管部门制定。"},{"i":10,"n":"第十条","txt":"考核发证机关应当组织制定本地区考核管理制度、考核纪律和考核应急预案，做好考核经费、考务信息系统、考核场地及设备设施的保障措施，规范考场秩序。 考核发证机关应当加强对从事监考、实操考评、考务信息系统和考核设备设施管理等考务工作人员的管理，并定期对考核场地及设备设施进行检查维护。 参加考核的人员应当自觉遵守考核纪律，服从考务工作人员管理。存在作弊或者其他严重违反考核纪律行为的，当次全部科目考核成绩无效。"},{"i":11,"n":"第十一条","txt":"考核发证机关应当在建筑施工特种作业操作资格考核结束后10个工作日内公布考核成绩。考核成绩有效期1年。"},{"i":12,"n":"第十二条","txt":"建筑施工特种作业操作资格考核通过且符合条件的人员，可以在考核成绩有效期内通过政务服务平台向原考核发证机关申请资格证书，并提交资格证书申请表、3个月内的体检合格报告、培训机构出具的安全作业培训记录或者证书。申请人应当对所提交材料的真实性负责。 考核发证机关应当自受理申请之日起10个工作日内完成审核。对符合条件的，核发资格证书。"},{"i":13,"n":"第十三条","txt":"资格证书实行电子证照。电子证照标准由国务院住房城乡建设主管部门制定。"},{"i":14,"n":"第十四条","txt":"资格证书在全国范围内有效，有效期为3年。"},{"i":15,"n":"第十五条","txt":"考核发证机关应当通过政务服务平台公布资格证书申请条件、申请程序、考核日程、审核时限和监督电话，并办理资格证书申请受理等事项。"},{"i":16,"n":"第十六条","txt":"取得国务院有关部门认定的特种作业、特种设备作业等相关职业资格的人员，可以按照有关规定申请领取建筑施工特种作业相应工种的资格证书。"},{"i":17,"n":"第十七条","txt":"建筑施工特种作业人员需要延续资格证书有效期的，应当在资格证书有效期届满30个工作日前向原考核发证机关提出延期复核申请。 建筑施工特种作业人员在资格证书有效期内符合第七条第三项、第四项规定，并完成用人单位或者培训机构组织的安全生产教育培训的，经原考核发证机关复核通过，资格证书有效期延续3年。 建筑施工特种作业人员因违法违章行为资格证书累积记分达到12分的，不予延期。 年龄超过60周岁从事建筑施工特种作业，未按规定每年进行1次体检并提交体检报告的，不予延期。"},{"i":18,"n":"第十八条","txt":"建筑施工特种作业人员申请资格证书延期复核，应当通过政务服务平台提交延期复核申请表、3个月内的体检合格报告、用人单位或者培训机构出具的安全生产教育培训记录或者证书。"},{"i":19,"n":"第十九条","txt":"资格证书不得伪造、涂改，不得倒卖、出租、出借或者以其他形式非法转让。"},{"i":20,"n":"第二十条","txt":"建筑施工特种作业人员应当在房屋市政工程范围内或者按照有关规定，按照其资格证书载明的工种从事相应的建筑施工特种作业。"},{"i":21,"n":"第二十一条","txt":"建筑施工企业（以下简称用人单位）在其承揽的房屋市政工程中开展建筑施工特种作业，应当招用取得相应工种资格证书的建筑施工特种作业人员。"},{"i":22,"n":"第二十二条","txt":"首次取得资格证书的建筑施工特种作业人员在正式上岗前，用人单位应当安排不少于6个月的实习操作。实习期内，实习人员应当穿戴醒目实习标志，并由从事相应工种6年以上的建筑施工特种作业人员进行作业指导，不得独立作业。 用人单位应当建立本单位建筑施工特种作业人员实习管理制度，并详细记录实习作业情况。实习作业记录由相关作业人员签字确认。"},{"i":23,"n":"第二十三条","txt":"用人单位及其管理人员应当依法履行下列职责： （一）制定并实施本单位建筑施工特种作业安全生产规章制度和操作规程、安全生产教育培训计划以及有关应急预案； （二）对建筑施工特种作业人员进行安全生产教育培训，保证其具备必要的安全生产知识，熟悉有关的安全生产规章制度和操作规程； （三）向建筑施工特种作业人员提供安全防护用具和安全防护服装，并书面告知岗位操作规程、违章操作的危害； （四）施工前，向建筑施工特种作业人员详细说明有关安全施工的技术要求； （五）制止和纠正相关违章指挥、强令冒险作业、违反操作规程的行为； （六）在施工起重机械、临时用电设施、脚手架、电梯井口等危险部位，设置明显的安全警示标志； （七）根据建筑施工特种作业人员年龄、身体健康状况、作业环境等情况合理安排作业内容和时段； （八）合理安排作业时间，连续作业不得超过4小时且间隔休息时间不得少于1小时； （九）建立本单位建筑施工特种作"},{"i":24,"n":"第二十四条","txt":"用人单位应当关注建筑施工特种作业人员的身体、心理状况和行为习惯，对其定期进行健康检查，并加强心理疏导。 年龄超过60周岁从事建筑施工特种作业的人员，应当按照本规定要求每年体检1次，并将体检报告提交考核发证机关。"},{"i":25,"n":"第二十五条","txt":"建筑施工特种作业人员开展建筑施工特种作业，应当按照要求参加安全技术交底，严格执行安全施工的强制性标准和相应工种的操作规则，不得实施妨碍施工安全的行为。"},{"i":26,"n":"第二十六条","txt":"任何单位和个人不得强迫、指使、纵容建筑施工特种作业人员违反建筑施工安全生产法律法规、强制性标准、操作规则进行作业。"},{"i":27,"n":"第二十七条","txt":"建筑施工特种作业人员有权了解其作业场所和工作岗位存在的危险因素、防范措施及事故应急措施，拒绝违章指挥和强令冒险作业。"},{"i":28,"n":"第二十八条","txt":"施工过程中发生危及人身安全的紧急情况时，建筑施工特种作业人员有权停止作业或者在采取必要的应急措施后撤离危险区域。"},{"i":29,"n":"第二十九条","txt":"建筑施工特种作业人员发现事故隐患或者其他不安全因素，应当立即向施工现场安全生产管理人员或者本单位负责人报告。出现重大事故隐患或者发生生产安全事故的，有权直接向工程所在地县级以上地方人民政府住房城乡建设主管部门报告或者举报。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，考核发证机关根据利害关系人的请求或者依据职权，可以撤销资格证书： （一）行政机关工作人员滥用职权、玩忽职守发放资格证书； （二）超越法定职权发放资格证书； （三）违反法定程序发放资格证书； （四）对不具备申请资格或者不符合法定条件的申请人发放资格证书； （五）依法可以撤销的其他情形。"},{"i":31,"n":"第三十一条","txt":"建筑施工特种作业人员有下列情形之一的，考核发证机关应当依法注销资格证书： （一）未按期办理延期复核手续或者延期复核不合格； （二）死亡或者丧失行为能力； （三）资格证书被依法撤销、吊销； （四）法律、法规规定的应当注销资格证书的其他情形。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府住房城乡建设主管部门应当依照有关法律法规和本规定，对建筑施工特种作业人员持证上岗、安全生产教育培训和从业行为，以及用人单位相关责任落实情况等进行监督检查。 有关单位和个人对依法进行的监督检查应当予以协助配合，不得拒绝或者阻挠。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市人民政府住房城乡建设主管部门应当建立建筑施工特种作业人员监管信息系统，及时归集建筑施工特种作业人员信息档案，并按照有关标准规范和数据共享要求上传至全国工程质量安全监管信息平台。监管信息系统相关建设维护费用向同级财政申请予以保障。 县级以上地方人民政府住房城乡建设主管部门应当按照有关规定及时将建筑施工特种作业人员从业行为涉及的违法违章行为、生产安全事故、不适宜从事建筑施工特种作业的健康信息等录入信息档案。"},{"i":34,"n":"第三十四条","txt":"建筑施工特种作业人员违法违章行为，除依法给予行政处罚外，实行记分管理。记分周期与资格证书有效期一致。 县级以上地方人民政府住房城乡建设主管部门发现建筑施工特种作业人员违反相应工种操作规则作业的，应当予以记录并作相应记分。分数跨省累积。建筑施工特种作业人员可以按照规定通过学习相关安全生产课程进行相应减分。 操作规则由国务院住房城乡建设主管部门制定。"},{"i":35,"n":"第三十五条","txt":"用人单位使用未取得资格证书的人员从事建筑施工特种作业的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，处10万元以下罚款；逾期未改正的，责令停业整顿，处10万元以上20万元以下罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"申请人隐瞒有关情况或者提供虚假材料申请资格证书的，考核发证机关不予受理或者不予行政许可，并给予警告；申请人1年内不得再次申请资格证书。"},{"i":37,"n":"第三十七条","txt":"申请人以欺骗、贿赂、考核作弊等不正当手段取得资格证书的，考核发证机关应当予以撤销，并给予通报批评，处1万元以上3万元以下罚款；申请人3年内不得再次申请资格证书。"},{"i":38,"n":"第三十八条","txt":"建筑施工特种作业人员涂改、倒卖、出租、出借或者以其他形式非法转让资格证书的，由考核发证机关给予警告，处1万元以上3万元以下罚款。"},{"i":39,"n":"第三十九条","txt":"用人单位未按规定安排实习操作、未建立实习管理制度，或者安排建筑施工特种作业人员实习期内独立作业的，责令限期改正，由县级以上地方人民政府住房城乡建设主管部门给予警告或者通报批评，处1万元以上5万元以下罚款；造成危害后果的，处5万元以上10万元以下罚款。 建筑施工特种作业人员实习期内擅自独立作业的，责令限期改正，处1000元以上1万元以下罚款。"},{"i":40,"n":"第四十条","txt":"用人单位违反第二十三条第一项至第六项规定的，依照《中华人民共和国安全生产法》、《中华人民共和国特种设备安全法》、《建设工程安全生产管理条例》等法律法规有关规定予以处罚。 用人单位违反第二十三条第七项至第九项规定的，责令限期改正，由县级以上地方人民政府住房城乡建设主管部门给予警告或者通报批评，处1万元以上5万元以下罚款；造成危害后果的，处5万元以上10万元以下罚款；对单位直接负责的主管人员和其他直接责任人员处5000元以下罚款。"},{"i":41,"n":"第四十一条","txt":"建筑施工特种作业人员违反安全施工强制性标准或者相应工种操作规则进行作业的，或者作业前拒绝参加安全技术交底的，按照有关法律、行政法规予以处罚；法律、行政法规尚未规定的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，情节严重或者造成生产安全重大事故隐患的，处2000元以上2万元以下罚款。"},{"i":42,"n":"第四十二条","txt":"用人单位违反本规定，导致不再具备安全生产条件的，依法暂扣安全生产许可证并限期整改；情节严重的，吊销安全生产许可证。"},{"i":43,"n":"第四十三条","txt":"违反本规定，造成财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"住房城乡建设主管部门工作人员在建筑施工特种作业监督管理工作中滥用职权、玩忽职守、徇私舞弊或者有其他违法行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"本规定自2026年6月1日起施行。《住房和城乡建设部关于印发〈建筑施工特种作业人员管理规定〉的通知》（建质〔2008〕75号）同时废止。"}],"jianshegongchengkangzhenshefangyaoqiuguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对新建、扩建、改建建设工程（以下简称建设工程）抗震设防要求的管理，防御与减轻地震灾害，保护人民生命和财产安全，根据《中华人民共和国防震减灾法》和《地震安全性评价管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行建设工程抗震设防要求的确定、使用和监督管理，必须遵守本规定。 本规定所称抗震设防要求，是指建设工程抗御地震破坏的准则和在一定风险水准下抗震设计采用的地震烈度或地震动参数。"},{"i":3,"n":"第三条","txt":"国务院地震工作主管部门负责全国建设工程抗震设防要求的监督管理工作。 县级以上地方人民政府负责管理地震工作的部门或者机构，负责本行政区域内建设工程抗震设防要求的监督管理工作。"},{"i":4,"n":"第四条","txt":"建设工程必须按照抗震设防要求进行抗震设防。 应当进行地震安全性评价的建设工程，其抗震设防要求必须按照地震安全性评价结果确定；其他建设工程的抗震设防要求按照国家颁布的地震动参数区划图或者地震动参数复核、地震小区划结果确定。"},{"i":5,"n":"第五条","txt":"应当进行地震安全性评价的建设工程的建设单位，必须在项目可行性研究阶段，委托具有资质的单位进行地震安全性评价工作，并将地震安全性评价报告报送有关地震工作主管部门或者机构审定。"},{"i":6,"n":"第六条","txt":"国务院地震工作主管部门和省、自治区、直辖市人民政府负责管理地震工作的部门或者机构，应当设立地震安全性评审组织。 地震安全性评审组织应当由15名以上地震行业及有关行业的技术、管理专家组成，其中技术专家不得少于二分之一。"},{"i":7,"n":"第七条","txt":"国务院地震工作主管部门和省、自治区、直辖市人民政府负责管理地震工作的部门或者机构，应当委托本级地震安全性评审组织，对地震安全性评价报告进行评审。 地震安全性评审组织应当按照国家地震安全性评价的技术规范和其他有关技术规范，对地震安全性评价报告的基础资料、技术途径和评价结果等进行审查，形成评审意见。"},{"i":8,"n":"第八条","txt":"国务院地震工作主管部门和省、自治区、直辖市人民政府负责管理地震工作的部门或者机构，应当根据地震安全性评审组织的评审意见，结合建设工程特性和其他综合因素，确定建设工程的抗震设防要求。"},{"i":9,"n":"第九条","txt":"下列区域内建设工程的抗震设防要求不应直接采用地震动参数区划图结果，必须进行地震动参数复核： （一） 位于地震动峰值加速度区划图峰值加速度分区界线两侧各4公里区域的建设工程； （二） 位于某些地震研究程度和资料详细程度较差的边远地区的建设工程。"},{"i":10,"n":"第十条","txt":"下列地区应当根据需要和可能开展地震小区划工作： （一）地震重点监视防御区内的大中城市和地震重点监视防御城市； （二）位于地震动参数0.15g以上（含0.15g）的大中城市； （三）位于复杂工程地质条件区域内的大中城市、大型厂矿企业、长距离生命线工程和新建开发区； （四）其他需要开展地震小区划工作的地区。"},{"i":11,"n":"第十一条","txt":"地震动参数复核和地震小区划工作必须由具有相应地震安全性评价资质的单位进行。"},{"i":12,"n":"第十二条","txt":"地震动参数复核结果一般由省、自治区、直辖市人民政府负责管理地震工作的部门或者机构负责审定，结果变动显著的，报国务院地震工作主管部门审定；地震小区划结果，由国务院地震工作主管部门负责审定。 地震动参数复核和地震小区划结果的审定程序按照本规定第七条、第八条的规定执行。 省、自治区、直辖市人民政府负责管理地震工作的部门或者机构，应当将审定后的地震动参数复核结果报国务院地震工作主管部门备案。"},{"i":13,"n":"第十三条","txt":"经过地震动参数复核或者地震小区划工作的区域内不需要进行地震安全性评价的建设工程，必须按照地震动参数复核或者地震小区划结果确定的抗震设防要求进行抗震设防。"},{"i":14,"n":"第十四条","txt":"国务院地震工作主管部门和县级以上地方人民政府负责管理地震工作的部门或者机构，应当会同同级政府有关行业主管部门，加强对建设工程抗震设防要求使用的监督检查，确保建设工程按照抗震设防要求进行抗震设防。"},{"i":15,"n":"第十五条","txt":"国务院地震工作主管部门和县级以上地方人民政府负责管理地震工作的部门或者机构，应当按照地震动参数区划图规定的抗震设防要求，加强对村镇房屋建设抗震设防的指导，逐步增强村镇房屋抗御地震破坏的能力。"},{"i":16,"n":"第十六条","txt":"国务院地震工作主管部门和县级以上地方人民政府负责管理地震工作的部门或者机构，应当加强对建设工程抗震设防的宣传教育，提高社会的防震减灾意识，增强社会防御地震灾害的能力。"},{"i":17,"n":"第十七条","txt":"建设单位违反本规定第十三条的规定，由国务院地震工作主管部门或者县级以上地方人民政府负责管理地震工作的部门或者机构，责令改正，并处5000元以上30000元以下的罚款。"},{"i":18,"n":"第十八条","txt":"本规定自公布之日起施行。"}],"jianshegongchengxiaofangshejishenchayanshouguanliz31f704":[{"i":1,"n":"第一条","txt":"为了加强建设工程消防设计审查验收管理，保证建设工程消防设计、施工质量，根据《中华人民共和国建筑法》《中华人民共和国消防法》《建设工程质量管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"特殊建设工程的消防设计审查、消防验收，以及其他建设工程的消防验收备案（以下简称备案）、抽查，适用本规定。 　　本规定所称特殊建设工程，是指本规定第十四条所列的建设工程。 　　本规定所称其他建设工程，是指特殊建设工程以外的其他按照国家工程建设消防技术标准需要进行消防设计的建设工程。"},{"i":3,"n":"第三条","txt":"国务院住房和城乡建设主管部门负责指导监督全国建设工程消防设计审查验收工作。 　　县级以上地方人民政府住房和城乡建设主管部门（以下简称消防设计审查验收主管部门）依职责承担本行政区域内建设工程的消防设计审查、消防验收、备案和抽查工作。 　　跨行政区域建设工程的消防设计审查、消防验收、备案和抽查工作，由该建设工程所在行政区域消防设计审查验收主管部门共同的上一级主管部门指定负责。"},{"i":4,"n":"第四条","txt":"消防设计审查验收主管部门应当运用互联网技术等信息化手段开展消防设计审查、消防验收、备案和抽查工作，建立健全有关单位和从业人员的信用管理制度，不断提升政务服务水平。"},{"i":5,"n":"第五条","txt":"消防设计审查验收主管部门实施消防设计审查、消防验收、备案和抽查工作所需经费，按照《中华人民共和国行政许可法》等有关法律法规的规定执行。"},{"i":6,"n":"第六条","txt":"消防设计审查验收主管部门应当及时将消防验收、备案和抽查情况告知消防救援机构，并与消防救援机构共享建筑平面图、消防设施平面布置图、消防设施系统图等资料。"},{"i":7,"n":"第七条","txt":"从事建设工程消防设计审查验收的工作人员，以及建设、设计、施工、工程监理、技术服务等单位的从业人员，应当具备相应的专业技术能力，定期参加职业培训。"},{"i":8,"n":"第八条","txt":"建设单位依法对建设工程消防设计、施工质量负首要责任。设计、施工、工程监理、技术服务等单位依法对建设工程消防设计、施工质量负主体责任。建设、设计、施工、工程监理、技术服务等单位的从业人员依法对建设工程消防设计、施工质量承担相应的个人责任。"},{"i":9,"n":"第九条","txt":"建设单位应当履行下列消防设计、施工质量责任和义务： 　　（一）不得明示或者暗示设计、施工、工程监理、技术服务等单位及其从业人员违反建设工程法律法规和国家工程建设消防技术标准，降低建设工程消防设计、施工质量； 　　（二）依法申请建设工程消防设计审查、消防验收，办理备案并接受抽查； 　　（三）实行工程监理的建设工程，依法将消防施工质量委托监理； 　　（四）委托具有相应资质的设计、施工、工程监理单位； 　　（五）按照工程消防设计要求和合同约定，选用合格的消防产品和满足防火性能要求的建筑材料、建筑构配件和设备； 　　（六）组织有关单位进行建设工程竣工验收时，对建设工程是否符合消防要求进行查验； 　　（七）依法及时向档案管理机构移交建设工程消防有关档案。"},{"i":10,"n":"第十条","txt":"设计单位应当履行下列消防设计、施工质量责任和义务： 　　（一）按照建设工程法律法规和国家工程建设消防技术标准进行设计，编制符合要求的消防设计文件，不得违反国家工程建设消防技术标准强制性条文； 　　（二）在设计文件中选用的消防产品和具有防火性能要求的建筑材料、建筑构配件和设备，应当注明规格、性能等技术指标，符合国家规定的标准； 　　（三）参加建设单位组织的建设工程竣工验收，对建设工程消防设计实施情况签章确认，并对建设工程消防设计质量负责。"},{"i":11,"n":"第十一条","txt":"施工单位应当履行下列消防设计、施工质量责任和义务： 　　（一）按照建设工程法律法规、国家工程建设消防技术标准，以及经消防设计审查合格或者满足工程需要的消防设计文件组织施工，不得擅自改变消防设计进行施工，降低消防施工质量； 　　（二）按照消防设计要求、施工技术标准和合同约定检验消防产品和具有防火性能要求的建筑材料、建筑构配件和设备的质量，使用合格产品，保证消防施工质量； 　　（三）参加建设单位组织的建设工程竣工验收，对建设工程消防施工质量签章确认，并对建设工程消防施工质量负责。"},{"i":12,"n":"第十二条","txt":"工程监理单位应当履行下列消防设计、施工质量责任和义务： 　　（一）按照建设工程法律法规、国家工程建设消防技术标准，以及经消防设计审查合格或者满足工程需要的消防设计文件实施工程监理； 　　（二）在消防产品和具有防火性能要求的建筑材料、建筑构配件和设备使用、安装前，核查产品质量证明文件，不得同意使用或者安装不合格的消防产品和防火性能不符合要求的建筑材料、建筑构配件和设备； 　　（三）参加建设单位组织的建设工程竣工验收，对建设工程消防施工质量签章确认，并对建设工程消防施工质量承担监理责任。"},{"i":13,"n":"第十三条","txt":"提供建设工程消防设计图纸技术审查、消防设施检测或者建设工程消防验收现场评定等服务的技术服务机构，应当按照建设工程法律法规、国家工程建设消防技术标准和国家有关规定提供服务，并对出具的意见或者报告负责。"},{"i":14,"n":"第十四条","txt":"具有下列情形之一的建设工程是特殊建设工程： 　　（一）总建筑面积大于二万平方米的体育场馆、会堂，公共展览馆、博物馆的展示厅； 　　（二）总建筑面积大于一万五千平方米的民用机场航站楼、客运车站候车室、客运码头候船厅； 　　（三）总建筑面积大于一万平方米的宾馆、饭店、商场、市场； 　　（四）总建筑面积大于二千五百平方米的影剧院，公共图书馆的阅览室，营业性室内健身、休闲场馆，医院的门诊楼，大学的教学楼、图书馆、食堂，劳动密集型企业的生产加工车间，寺庙、教堂； 　　（五）总建筑面积大于一千平方米的托儿所、幼儿园的儿童用房，儿童游乐厅等室内儿童活动场所，养老院、福利院，医院、疗养院的病房楼，中小学校的教学楼、图书馆、食堂，学校的集体宿舍，劳动密集型企业的员工集体宿舍； 　　（六）总建筑面积大于五百平方米的歌舞厅、录像厅、放映厅、卡拉ＯＫ厅、夜总会、游艺厅、桑拿浴室、网吧、酒吧，具有娱乐功能的餐馆"},{"i":15,"n":"第十五条","txt":"对特殊建设工程实行消防设计审查制度。 　　特殊建设工程的建设单位应当向消防设计审查验收主管部门申请消防设计审查，消防设计审查验收主管部门依法对审查的结果负责。 　　特殊建设工程未经消防设计审查或者审查不合格的，建设单位、施工单位不得施工。"},{"i":16,"n":"第十六条","txt":"建设单位申请消防设计审查，应当提交下列材料： 　　（一）消防设计审查申请表； 　　（二）消防设计文件； 　　（三）依法需要办理建设工程规划许可的，应当提交建设工程规划许可文件； 　　（四）依法需要批准的临时性建筑，应当提交批准文件。"},{"i":17,"n":"第十七条","txt":"特殊建设工程具有下列情形之一的，建设单位除提交本规定第十六条所列材料外，还应当同时提交特殊消防设计技术资料： 　　（一）国家工程建设消防技术标准没有规定的； 　　（二）消防设计文件拟采用的新技术、新工艺、新材料不符合国家工程建设消防技术标准规定的；  　　（三）因保护利用历史建筑、历史文化街区需要，确实无法满足国家工程建设消防技术标准要求的。 　　前款所称特殊消防设计技术资料，应当包括特殊消防设计文件，以及两个以上有关的应用实例、产品说明等资料。 　　特殊消防设计涉及采用国际标准或者境外工程建设消防技术标准的，还应当提供相应的中文文本。"},{"i":18,"n":"第十八条","txt":"特殊消防设计文件应当包括特殊消防设计必要性论证、特殊消防设计方案、火灾数值模拟分析等内容，重大工程、火灾危险等级高的应当包括实体试验验证内容。 　　特殊消防设计方案应当对两种以上方案进行比选，从安全性、经济性、可实施性等方面进行综合分析后形成。 　　火灾数值模拟分析应当科学设定火灾场景和模拟参数，实体试验应当与实际场景相符。火灾数值模拟分析结论和实体试验结论应当一致。"},{"i":19,"n":"第十九条","txt":"消防设计审查验收主管部门收到建设单位提交的消防设计审查申请后，对申请材料齐全的，应当出具受理凭证；申请材料不齐全的，应当一次性告知需要补正的全部内容。"},{"i":20,"n":"第二十条","txt":"对具有本规定第十七条情形之一的建设工程，消防设计审查验收主管部门应当自受理消防设计审查申请之日起五个工作日内，将申请材料报送省、自治区、直辖市人民政府住房和城乡建设主管部门组织专家评审。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市人民政府住房和城乡建设主管部门应当建立由具有工程消防、建筑等专业高级技术职称人员组成的专家库，制定专家库管理制度。"},{"i":22,"n":"第二十二条","txt":"省、自治区、直辖市人民政府住房和城乡建设主管部门应当在收到申请材料之日起十个工作日内组织召开专家评审会，对建设单位提交的特殊消防设计技术资料进行评审。 　　评审专家从专家库随机抽取，对于技术复杂、专业性强或者国家有特殊要求的项目，可以直接邀请相应专业的中国科学院院士、中国工程院院士、全国工程勘察设计大师以及境外具有相应资历的专家参加评审；与特殊建设工程设计单位有利害关系的专家不得参加评审。 　　评审专家应当符合相关专业要求，总数不得少于七人，且独立出具同意或者不同意的评审意见。特殊消防设计技术资料经四分之三以上评审专家同意即为评审通过，评审专家有不同意见的，应当注明。省、自治区、直辖市人民政府住房和城乡建设主管部门应当将专家评审意见，书面通知报请评审的消防设计审查验收主管部门。"},{"i":23,"n":"第二十三条","txt":"消防设计审查验收主管部门应当自受理消防设计审查申请之日起十五个工作日内出具书面审查意见。依照本规定需要组织专家评审的，专家评审时间不超过二十个工作日。"},{"i":24,"n":"第二十四条","txt":"对符合下列条件的，消防设计审查验收主管部门应当出具消防设计审查合格意见： 　　（一）申请材料齐全、符合法定形式； 　　（二）设计单位具有相应资质； 　　（三）消防设计文件符合国家工程建设消防技术标准(具有本规定第十七条情形之一的特殊建设工程，特殊消防设计技术资料通过专家评审)。 　　对不符合前款规定条件的，消防设计审查验收主管部门应当出具消防设计审查不合格意见，并说明理由。"},{"i":25,"n":"第二十五条","txt":"实行施工图设计文件联合审查的，应当将建设工程消防设计的技术审查并入联合审查。"},{"i":26,"n":"第二十六条","txt":"建设、设计、施工单位不得擅自修改经审查合格的消防设计文件。确需修改的，建设单位应当依照本规定重新申请消防设计审查。"},{"i":27,"n":"第二十七条","txt":"对特殊建设工程实行消防验收制度。 　　特殊建设工程竣工验收后，建设单位应当向消防设计审查验收主管部门申请消防验收；未经消防验收或者消防验收不合格的，禁止投入使用。"},{"i":28,"n":"第二十八条","txt":"建设单位组织竣工验收时，应当对建设工程是否符合下列要求进行查验： 　　（一）完成工程消防设计和合同约定的消防各项内容； 　　（二）有完整的工程消防技术档案和施工管理资料（含涉及消防的建筑材料、建筑构配件和设备的进场试验报告）； 　　（三）建设单位对工程涉及消防的各分部分项工程验收合格；施工、设计、工程监理、技术服务等单位确认工程消防质量符合有关标准； 　　（四）消防设施性能、系统功能联调联试等内容检测合格。 　　经查验不符合前款规定的建设工程，建设单位不得编制工程竣工验收报告。"},{"i":29,"n":"第二十九条","txt":"建设单位申请消防验收，应当提交下列材料： 　　（一）消防验收申请表； 　　（二）工程竣工验收报告； 　　（三）涉及消防的建设工程竣工图纸。 　　消防设计审查验收主管部门收到建设单位提交的消防验收申请后，对申请材料齐全的，应当出具受理凭证；申请材料不齐全的，应当一次性告知需要补正的全部内容。"},{"i":30,"n":"第三十条","txt":"消防设计审查验收主管部门受理消防验收申请后，应当按照国家有关规定，对特殊建设工程进行现场评定。现场评定包括对建筑物防（灭）火设施的外观进行现场抽样查看；通过专业仪器设备对涉及距离、高度、宽度、长度、面积、厚度等可测量的指标进行现场抽样测量；对消防设施的功能进行抽样测试、联调联试消防设施的系统功能等内容。"},{"i":31,"n":"第三十一条","txt":"消防设计审查验收主管部门应当自受理消防验收申请之日起十五日内出具消防验收意见。对符合下列条件的，应当出具消防验收合格意见： 　　（一）申请材料齐全、符合法定形式； 　　（二）工程竣工验收报告内容完备； 　　（三）涉及消防的建设工程竣工图纸与经审查合格的消防设计文件相符； 　　（四）现场评定结论合格。 　　对不符合前款规定条件的，消防设计审查验收主管部门应当出具消防验收不合格意见，并说明理由。"},{"i":32,"n":"第三十二条","txt":"实行规划、土地、消防、人防、档案等事项联合验收的建设工程，消防验收意见由地方人民政府指定的部门统一出具。"},{"i":33,"n":"第三十三条","txt":"其他建设工程，建设单位申请施工许可或者申请批准开工报告时，应当提供满足施工需要的消防设计图纸及技术资料。 　　未提供满足施工需要的消防设计图纸及技术资料的，有关部门不得发放施工许可证或者批准开工报告。"},{"i":34,"n":"第三十四条","txt":"对其他建设工程实行备案抽查制度，分类管理。 　　其他建设工程经依法抽查不合格的，应当停止使用。"},{"i":35,"n":"第三十五条","txt":"省、自治区、直辖市人民政府住房和城乡建设主管部门应当制定其他建设工程分类管理目录清单。 　　其他建设工程应当依据建筑所在区域环境、建筑使用功能、建筑规模和高度、建筑耐火等级、疏散能力、消防设施设备配置水平等因素分为一般项目、重点项目等两类。"},{"i":36,"n":"第三十六条","txt":"其他建设工程竣工验收合格之日起五个工作日内，建设单位应当报消防设计审查验收主管部门备案。 　　建设单位办理备案，应当提交下列材料： 　　（一）消防验收备案表； 　　（二）工程竣工验收报告； 　　（三）涉及消防的建设工程竣工图纸。 　　本规定第二十八条有关建设单位竣工验收消防查验的规定，适用于其他建设工程。"},{"i":37,"n":"第三十七条","txt":"消防设计审查验收主管部门收到建设单位备案材料后，对备案材料齐全的，应当出具备案凭证；备案材料不齐全的，应当一次性告知需要补正的全部内容。 　　一般项目可以采用告知承诺制的方式申请备案，消防设计审查验收主管部门依据承诺书出具备案凭证。"},{"i":38,"n":"第三十八条","txt":"消防设计审查验收主管部门应当对备案的其他建设工程进行抽查，加强对重点项目的抽查。 　　抽查工作推行“双随机、一公开”制度,随机抽取检查对象,随机选派检查人员。抽取比例由省、自治区、直辖市人民政府住房和城乡建设主管部门，结合辖区内消防设计、施工质量情况确定，并向社会公示。"},{"i":39,"n":"第三十九条","txt":"消防设计审查验收主管部门应当自其他建设工程被确定为检查对象之日起十五个工作日内，按照建设工程消防验收有关规定完成检查，制作检查记录。检查结果应当通知建设单位，并向社会公示。"},{"i":40,"n":"第四十条","txt":"建设单位收到检查不合格整改通知后，应当停止使用建设工程，并组织整改，整改完成后，向消防设计审查验收主管部门申请复查。 　　消防设计审查验收主管部门应当自收到书面申请之日起七个工作日内进行复查，并出具复查意见。复查合格后方可使用建设工程。"},{"i":41,"n":"第四十一条","txt":"违反本规定的行为，依照《中华人民共和国建筑法》《中华人民共和国消防法》《建设工程质量管理条例》等法律法规给予处罚；构成犯罪的，依法追究刑事责任。 　　建设、设计、施工、工程监理、技术服务等单位及其从业人员违反有关建设工程法律法规和国家工程建设消防技术标准，除依法给予处罚或者追究刑事责任外，还应当依法承担相应的民事责任。"},{"i":42,"n":"第四十二条","txt":"建设工程消防设计审查验收规则和执行本规定所需要的文书式样，由国务院住房和城乡建设主管部门制定。"},{"i":43,"n":"第四十三条","txt":"新颁布的国家工程建设消防技术标准实施之前，建设工程的消防设计已经依法审查合格的，按原审查意见的标准执行。"},{"i":44,"n":"第四十四条","txt":"住宅室内装饰装修、村民自建住宅、救灾和非人员密集场所的临时性建筑的建设活动，不适用本规定。"},{"i":45,"n":"第四十五条","txt":"省、自治区、直辖市人民政府住房和城乡建设主管部门可以根据有关法律法规和本规定，结合本地实际情况，制定实施细则。"},{"i":46,"n":"第四十六条","txt":"本规定自2020年6月1日起施行。"}],"jianshegongchengzhiliangjianceguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对建设工程质量检测的管理，根据《中华人民共和国建筑法》《建设工程质量管理条例》《建设工程抗震管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"从事建设工程质量检测相关活动及其监督管理，适用本办法。 本办法所称建设工程质量检测，是指在新建、扩建、改建房屋建筑和市政基础设施工程活动中，建设工程质量检测机构（以下简称检测机构）接受委托，依据国家有关法律、法规和标准，对建设工程涉及结构安全、主要使用功能的检测项目，进入施工现场的建筑材料、建筑构配件、设备，以及工程实体质量等进行的检测。"},{"i":3,"n":"第三条","txt":"检测机构应当按照本办法取得建设工程质量检测机构资质(以下简称检测机构资质)，并在资质许可的范围内从事建设工程质量检测活动。 未取得相应资质证书的，不得承担本办法规定的建设工程质量检测业务。"},{"i":4,"n":"第四条","txt":"国务院住房和城乡建设主管部门负责全国建设工程质量检测活动的监督管理。 县级以上地方人民政府住房和城乡建设主管部门负责本行政区域内建设工程质量检测活动的监督管理，可以委托所属的建设工程质量监督机构具体实施。"},{"i":5,"n":"第五条","txt":"检测机构资质分为综合类资质、专项类资质。 检测机构资质标准和业务范围，由国务院住房和城乡建设主管部门制定。"},{"i":6,"n":"第六条","txt":"申请检测机构资质的单位应当是具有独立法人资格的企业、事业单位，或者依法设立的合伙企业，并具备相应的人员、仪器设备、检测场所、质量保证体系等条件。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市人民政府住房和城乡建设主管部门负责本行政区域内检测机构的资质许可。"},{"i":8,"n":"第八条","txt":"申请检测机构资质应当向登记地所在省、自治区、直辖市人民政府住房和城乡建设主管部门提出，并提交下列材料： （一）检测机构资质申请表； （二）主要检测仪器、设备清单； （三）检测场所不动产权属证书或者租赁合同； （四）技术人员的职称证书； （五）检测机构管理制度以及质量控制措施。 检测机构资质申请表由国务院住房和城乡建设主管部门制定格式。"},{"i":9,"n":"第九条","txt":"资质许可机关受理申请后，应当进行材料审查和专家评审，在20个工作日内完成审查并作出书面决定。对符合资质标准的，自作出决定之日起10个工作日内颁发检测机构资质证书，并报国务院住房和城乡建设主管部门备案。专家评审时间不计算在资质许可期限内。"},{"i":10,"n":"第十条","txt":"检测机构资质证书实行电子证照，由国务院住房和城乡建设主管部门制定格式。资质证书有效期为5年。"},{"i":11,"n":"第十一条","txt":"申请综合类资质或者资质增项的检测机构，在申请之日起前一年内有本办法第三十条规定行为的，资质许可机关不予批准其申请。 取得资质的检测机构，按照本办法第三十五条应当整改但尚未完成整改的，对其综合类资质或者资质增项申请，资质许可机关不予批准。"},{"i":12,"n":"第十二条","txt":"检测机构需要延续资质证书有效期的，应当在资质证书有效期届满30个工作日前向资质许可机关提出资质延续申请。 对符合资质标准且在资质证书有效期内无本办法第三十条规定行为的检测机构，经资质许可机关同意，有效期延续5年。"},{"i":13,"n":"第十三条","txt":"检测机构在资质证书有效期内名称、地址、法定代表人等发生变更的，应当在办理营业执照或者法人证书变更手续后30个工作日内办理资质证书变更手续。资质许可机关应当在2个工作日内办理完毕。 检测机构检测场所、技术人员、仪器设备等事项发生变更影响其符合资质标准的，应当在变更后30个工作日内向资质许可机关提出资质重新核定申请，资质许可机关应当在20个工作日内完成审查，并作出书面决定。"},{"i":14,"n":"第十四条","txt":"从事建设工程质量检测活动，应当遵守相关法律、法规和标准，相关人员应当具备相应的建设工程质量检测知识和专业能力。"},{"i":15,"n":"第十五条","txt":"检测机构与所检测建设工程相关的建设、施工、监理单位，以及建筑材料、建筑构配件和设备供应单位不得有隶属关系或者其他利害关系。 检测机构及其工作人员不得推荐或者监制建筑材料、建筑构配件和设备。"},{"i":16,"n":"第十六条","txt":"委托方应当委托具有相应资质的检测机构开展建设工程质量检测业务。检测机构应当按照法律、法规和标准进行建设工程质量检测，并出具检测报告。"},{"i":17,"n":"第十七条","txt":"建设单位应当在编制工程概预算时合理核算建设工程质量检测费用，单独列支并按照合同约定及时支付。"},{"i":18,"n":"第十八条","txt":"建设单位委托检测机构开展建设工程质量检测活动的，建设单位或者监理单位应当对建设工程质量检测活动实施见证。见证人员应当制作见证记录，记录取样、制样、标识、封志、送检以及现场检测等情况，并签字确认。"},{"i":19,"n":"第十九条","txt":"提供检测试样的单位和个人，应当对检测试样的符合性、真实性及代表性负责。检测试样应当具有清晰的、不易脱落的唯一性标识、封志。 建设单位委托检测机构开展建设工程质量检测活动的，施工人员应当在建设单位或者监理单位的见证人员监督下现场取样。"},{"i":20,"n":"第二十条","txt":"现场检测或者检测试样送检时，应当由检测内容提供单位、送检单位等填写委托单。委托单应当由送检人员、见证人员等签字确认。 检测机构接收检测试样时，应当对试样状况、标识、封志等符合性进行检查，确认无误后方可进行检测。"},{"i":21,"n":"第二十一条","txt":"检测报告经检测人员、审核人员、检测机构法定代表人或者其授权的签字人等签署，并加盖检测专用章后方可生效。 检测报告中应当包括检测项目代表数量（批次）、检测依据、检测场所地址、检测数据、检测结果、见证人员单位及姓名等相关信息。 非建设单位委托的检测机构出具的检测报告不得作为工程质量验收资料。"},{"i":22,"n":"第二十二条","txt":"检测机构应当建立建设工程过程数据和结果数据、检测影像资料及检测报告记录与留存制度，对检测数据和检测报告的真实性、准确性负责。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人不得明示或者暗示检测机构出具虚假检测报告，不得篡改或者伪造检测报告。"},{"i":24,"n":"第二十四条","txt":"检测机构在检测过程中发现建设、施工、监理单位存在违反有关法律法规规定和工程建设强制性标准等行为，以及检测项目涉及结构安全、主要使用功能检测结果不合格的，应当及时报告建设工程所在地县级以上地方人民政府住房和城乡建设主管部门。"},{"i":25,"n":"第二十五条","txt":"检测结果利害关系人对检测结果存在争议的，可以委托共同认可的检测机构复检。"},{"i":26,"n":"第二十六条","txt":"检测机构应当建立档案管理制度。检测合同、委托单、检测数据原始记录、检测报告按照年度统一编号，编号应当连续，不得随意抽撤、涂改。 检测机构应当单独建立检测结果不合格项目台账。"},{"i":27,"n":"第二十七条","txt":"检测机构应当建立信息化管理系统，对检测业务受理、检测数据采集、检测信息上传、检测报告出具、检测档案管理等活动进行信息化管理，保证建设工程质量检测活动全过程可追溯。"},{"i":28,"n":"第二十八条","txt":"检测机构应当保持人员、仪器设备、检测场所、质量保证体系等方面符合建设工程质量检测资质标准,加强检测人员培训，按照有关规定对仪器设备进行定期检定或者校准，确保检测技术能力持续满足所开展建设工程质量检测活动的要求。"},{"i":29,"n":"第二十九条","txt":"检测机构跨省、自治区、直辖市承担检测业务的，应当向建设工程所在地的省、自治区、直辖市人民政府住房和城乡建设主管部门备案。 检测机构在承担检测业务所在地的人员、仪器设备、检测场所、质量保证体系等应当满足开展相应建设工程质量检测活动的要求。"},{"i":30,"n":"第三十条","txt":"检测机构不得有下列行为： （一）超出资质许可范围从事建设工程质量检测活动； （二）转包或者违法分包建设工程质量检测业务； （三）涂改、倒卖、出租、出借或者以其他形式非法转让资质证书； （四）违反工程建设强制性标准进行检测； （五）使用不能满足所开展建设工程质量检测活动要求的检测人员或者仪器设备； （六）出具虚假的检测数据或者检测报告。"},{"i":31,"n":"第三十一条","txt":"检测人员不得有下列行为： （一）同时受聘于两家或者两家以上检测机构； （二）违反工程建设强制性标准进行检测； （三）出具虚假的检测数据； （四）违反工程建设强制性标准进行结论判定或者出具虚假判定结论。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府住房和城乡建设主管部门应当加强对建设工程质量检测活动的监督管理，建立建设工程质量检测监管信息系统，提高信息化监管水平。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府住房和城乡建设主管部门应当对检测机构实行动态监管，通过“双随机、一公开”等方式开展监督检查。 实施监督检查时，有权采取下列措施： （一）进入建设工程施工现场或者检测机构的工作场地进行检查、抽测； （二）向检测机构、委托方、相关单位和人员询问、调查有关情况； （三）对检测人员的建设工程质量检测知识和专业能力进行检查； （四）查阅、复制有关检测数据、影像资料、报告、合同以及其他相关资料； （五）组织实施能力验证或者比对试验； （六）法律、法规规定的其他措施。"},{"i":34,"n":"第三十四条","txt":"县级以上地方人民政府住房和城乡建设主管部门应当加强建设工程质量监督抽测。建设工程质量监督抽测可以通过政府购买服务的方式实施。"},{"i":35,"n":"第三十五条","txt":"检测机构取得检测机构资质后，不再符合相应资质标准的，资质许可机关应当责令其限期整改并向社会公开。检测机构完成整改后，应当向资质许可机关提出资质重新核定申请。重新核定符合资质标准前出具的检测报告不得作为工程质量验收资料。"},{"i":36,"n":"第三十六条","txt":"县级以上地方人民政府住房和城乡建设主管部门对检测机构实施行政处罚的，应当自行政处罚决定书送达之日起20个工作日内告知检测机构的资质许可机关和违法行为发生地省、自治区、直辖市人民政府住房和城乡建设主管部门。"},{"i":37,"n":"第三十七条","txt":"县级以上地方人民政府住房和城乡建设主管部门应当依法将建设工程质量检测活动相关单位和人员受到的行政处罚等信息予以公开，建立信用管理制度，实行守信激励和失信惩戒。"},{"i":38,"n":"第三十八条","txt":"对建设工程质量检测活动中的违法违规行为，任何单位和个人有权向建设工程所在地县级以上人民政府住房和城乡建设主管部门投诉、举报。"},{"i":39,"n":"第三十九条","txt":"违反本办法规定，未取得相应资质、资质证书已过有效期或者超出资质许可范围从事建设工程质量检测活动的，其检测报告无效，由县级以上地方人民政府住房和城乡建设主管部门处5万元以上10万元以下罚款；造成危害后果的，处10万元以上20万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"检测机构隐瞒有关情况或者提供虚假材料申请资质，资质许可机关不予受理或者不予行政许可，并给予警告；检测机构1年内不得再次申请资质。"},{"i":41,"n":"第四十一条","txt":"以欺骗、贿赂等不正当手段取得资质证书的，由资质许可机关予以撤销；由县级以上地方人民政府住房和城乡建设主管部门给予警告或者通报批评，并处5万元以上10万元以下罚款；检测机构3年内不得再次申请资质；构成犯罪的，依法追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"检测机构未按照本办法第十三条第一款规定办理检测机构资质证书变更手续的，由县级以上地方人民政府住房和城乡建设主管部门责令限期办理；逾期未办理的，处5000元以上1万元以下罚款。 检测机构未按照本办法第十三条第二款规定向资质许可机关提出资质重新核定申请的，由县级以上地方人民政府住房和城乡建设主管部门责令限期改正；逾期未改正的，处1万元以上3万元以下罚款。"},{"i":43,"n":"第四十三条","txt":"检测机构违反本办法第二十二条、第三十条第六项规定的，由县级以上地方人民政府住房和城乡建设主管部门责令改正，处5万元以上10万元以下罚款；造成危害后果的，处10万元以上20万元以下罚款；构成犯罪的，依法追究刑事责任。 检测机构在建设工程抗震活动中有前款行为的，依照《建设工程抗震管理条例》有关规定给予处罚。"},{"i":44,"n":"第四十四条","txt":"检测机构违反本办法规定，有第三十条第二项至第五项行为之一的，由县级以上地方人民政府住房和城乡建设主管部门责令改正，处5万元以上10万元以下罚款；造成危害后果的，处10万元以上20万元以下罚款；构成犯罪的，依法追究刑事责任。 检测人员违反本办法规定，有第三十一条行为之一的，由县级以上地方人民政府住房和城乡建设主管部门责令改正，处3万元以下罚款。"},{"i":45,"n":"第四十五条","txt":"检测机构违反本办法规定，有下列行为之一的，由县级以上地方人民政府住房和城乡建设主管部门责令改正，处1万元以上5万元以下罚款： （一）与所检测建设工程相关的建设、施工、监理单位，以及建筑材料、建筑构配件和设备供应单位有隶属关系或者其他利害关系的； （二）推荐或者监制建筑材料、建筑构配件和设备的； （三）未按照规定在检测报告上签字盖章的； （四）未及时报告发现的违反有关法律法规规定和工程建设强制性标准等行为的； （五）未及时报告涉及结构安全、主要使用功能的不合格检测结果的； （六）未按照规定进行档案和台账管理的； （七）未建立并使用信息化管理系统对检测活动进行管理的； （八）不满足跨省、自治区、直辖市承担检测业务的要求开展相应建设工程质量检测活动的； （九）接受监督检查时不如实提供有关资料、不按照要求参加能力验证和比对试验，或者拒绝、阻碍监督检查的。"},{"i":46,"n":"第四十六条","txt":"检测机构违反本办法规定，有违法所得的，由县级以上地方人民政府住房和城乡建设主管部门依法予以没收。"},{"i":47,"n":"第四十七条","txt":"违反本办法规定，建设、施工、监理等单位有下列行为之一的，由县级以上地方人民政府住房和城乡建设主管部门责令改正，处3万元以上10万元以下罚款；造成危害后果的，处10万元以上20万元以下罚款；构成犯罪的，依法追究刑事责任： （一）委托未取得相应资质的检测机构进行检测的； （二）未将建设工程质量检测费用列入工程概预算并单独列支的； （三）未按照规定实施见证的； （四）提供的检测试样不满足符合性、真实性、代表性要求的； （五）明示或者暗示检测机构出具虚假检测报告的； （六）篡改或者伪造检测报告的； （七）取样、制样和送检试样不符合规定和工程建设强制性标准的。"},{"i":48,"n":"第四十八条","txt":"依照本办法规定，给予单位罚款处罚的，对单位直接负责的主管人员和其他直接责任人员处3万元以下罚款。"},{"i":49,"n":"第四十九条","txt":"县级以上地方人民政府住房和城乡建设主管部门工作人员在建设工程质量检测管理工作中，有下列情形之一的，依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人颁发资质证书的； （二）对符合法定条件的申请人不予颁发资质证书的； （三）对符合法定条件的申请人未在法定期限内颁发资质证书的； （四）利用职务上的便利，索取、收受他人财物或者谋取其他利益的； （五）不依法履行监督职责或者监督不力，造成严重后果的。"},{"i":50,"n":"第五十条","txt":"本办法自2023年3月1日起施行。2005年9月28日原建设部公布的《建设工程质量检测管理办法》（建设部令第141号）同时废止。"}],"luyinfadingxukefuchoubiaozhunzanxingguiding":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国著作权法》第三十七条的规定以录音的形式使用已发表的作品，依本规定向著作权人付酬，但著作权人声明不得使用的除外。"},{"i":2,"n":"第二条","txt":"录制发行录音制品采用版税的方式付酬，即录音制品批发价×版税率×录音制品发行数。"},{"i":3,"n":"第三条","txt":"录制发行录音制品付酬标准为： 不含文字的纯音乐作品版税率为百分之三点五； 歌曲、歌剧作品版税率为百分之三点五，其中音乐部分占版税所得百分之六十，文字部分占版税所得百分之四十； 纯文字作品（含外国文字）版税率为百分之三； 国家机关通过行政措施保障发行的录音制品（如教材）版税率为百分之十五。"},{"i":4,"n":"第四条","txt":"录音制品中涉及两个或两个以上作品的，按照版税的方式以及相对应的版税率计算出录音制品中所有作品的报酬总额，再根据每一作品在整个录音制品中所占时间比例，确定其具体报酬。"},{"i":5,"n":"第五条","txt":"使用改编作品进行录音，依第三条和第四条的规定确定具体报酬后，向作品的著作权人支付百分之七十，向原作品著作权人支付百分之三十。原作品已超过著作权保护期或不适用著作权法的，只按上述比例向被录制作品的著作权人付酬。"},{"i":6,"n":"第六条","txt":"本规定由国家版权局负责解释。 国家版权局关于《录音法定许可付酬标准暂行规定》的补充通知 (1994年10月7日国权〔1994〕65号公布 ) 1993年8月1日国家版权局颁布了《录音法定许可付酬标准暂行规定》，规定了以录音的形式使用已发表的作品的付酬标准。根据《中华人民共和国著作权法》第三十九条和第四十二条的规定，录音制作者经许可复制发行其他录音制作者制作的录音制品和广播电台制作的广播节目，均应当按照规定向著作权人和表演者支付报酬。对于上述两种复制发行情况的付酣标准，《录音法定许可付酬标准暂行规定》中没有做出规定，为此，特做如下补充规定： 除合同另有约定的，根据《中华人民共和国著作权法》第三十九条和第四十二条的规定，录音制作者经许可复制发行其他录音制作者制作的录音制品或复制发行广播电台制作的广播节目，向著作权人支付报酬的，适用《录音法定许可付酬标准暂行规定》第二条、第三条、第四条和第五"}],"zhengfucaigougongyingshangtousuchulibanfa":[{"i":1,"n":"第一条","txt":"为了防止和纠正违法的或者不当的政府采购行为，保护参加政府采购活动供应商的合法权益，维护国家利益和社会公共利益，建立规范高效的政府采购投诉处理机制，根据《中华人民共和国政府采购法》（以下简称政府采购法），制定本办法。"},{"i":2,"n":"第二条","txt":"供应商依法向财政部门提起投诉，财政部门受理投诉、作出处理决定，适用本办法。"},{"i":3,"n":"第三条","txt":"县级以上各级人民政府财政部门负责依法受理和处理供应商投诉。 财政部负责中央预算项目政府采购活动中的供应商投诉事宜。 县级以上地方各级人民政府财政部门负责本级预算项目政府采购活动中的供应商投诉事宜。"},{"i":4,"n":"第四条","txt":"各级财政部门应当在省级以上财政部门指定的政府采购信息发布媒体上公告受理投诉的电话、传真等方便供应商投诉的事项。"},{"i":5,"n":"第五条","txt":"财政部门处理投诉，应当坚持公平、公正和简便、高效的原则，维护国家利益和社会公共利益。"},{"i":6,"n":"第六条","txt":"供应商投诉实行实名制，其投诉应当有具体的投诉事项及事实根据，不得进行虚假、恶意投诉。"},{"i":7,"n":"第七条","txt":"供应商认为采购文件、采购过程、中标和成交结果使自己的合法权益受到损害的，应当首先依法向采购人、采购代理机构提出质疑。对采购人、采购代理机构的质疑答复不满意，或者采购人、采购代理机构未在规定期限内作出答复的，供应商可以在答复期满后15个工作日内向同级财政部门提起投诉。"},{"i":8,"n":"第八条","txt":"投诉人投诉时，应当提交投诉书，并按照被投诉采购人、采购代理机构（以下简称被投诉人）和与投诉事项有关的供应商数量提供投诉书的副本。 投诉书应当包括下列主要内容： （一）投诉人和被投诉人的名称、地址、电话等； （二）具体的投诉事项及事实依据； （三）质疑和质疑答复情况及相关证明材料； （四）提起投诉的日期。 投诉书应当署名。投诉人为自然人的，应当由本人签字；投诉人为法人或者其他组织的，应当由法定代表人或者主要负责人签字盖章并加盖公章。"},{"i":9,"n":"第九条","txt":"投诉人可以委托代理人办理投诉事务。代理人办理投诉事务时，除提交投诉书外，还应当向同级财政部门提交投诉人的授权委托书，授权委托书应当载明委托代理的具体权限和事项。"},{"i":10,"n":"第十条","txt":"投诉人提起投诉应当符合下列条件： （一）投诉人是参与所投诉政府采购活动的供应商； （二）提起投诉前已依法进行质疑； （三）投诉书内容符合本办法的规定； （四）在投诉有效期限内提起投诉； （五）属于本财政部门管辖； （六）同一投诉事项未经财政部门投诉处理； （七）国务院财政部门规定的其他条件。"},{"i":11,"n":"第十一条","txt":"财政部门收到投诉书后，应当在5个工作日内进行审查，对不符合投诉条件的，分别按下列规定予以处理： （一）投诉书内容不符合规定的，告知投诉人修改后重新投诉； （二）投诉不属于本部门管辖的，转送有管辖权的部门，并通知投诉人； （三）投诉不符合其他条件的，书面告知投诉人不予受理，并应当说明理由。 对符合投诉条件的投诉，自财政部门收到投诉书之日起即为受理。"},{"i":12,"n":"第十二条","txt":"财政部门应当在受理投诉后3个工作日内向被投诉人和与投诉事项有关的供应商发送投诉书副本。"},{"i":13,"n":"第十三条","txt":"被投诉人和与投诉事项有关的供应商应当在收到投诉书副本之日起5个工作日内，以书面形式向财政部门作出说明，并提交相关证据、依据和其他有关材料。"},{"i":14,"n":"第十四条","txt":"财政部门处理投诉事项原则上采取书面审查的办法。财政部门认为有必要时，可以进行调查取证，也可以组织投诉人和被投诉人当面进行质证。"},{"i":15,"n":"第十五条","txt":"对财政部门依法进行调查的，投诉人、被投诉人以及与投诉事项有关的单位及人员等应当如实反映情况，并提供财政部门所需要的相关材料。"},{"i":16,"n":"第十六条","txt":"投诉人拒绝配合财政部门依法进行调查的，按自动撤回投诉处理；被投诉人不提交相关证据、依据和其他有关材料的，视同放弃说明权利，认可投诉事项。"},{"i":17,"n":"第十七条","txt":"财政部门经审查，对投诉事项分别作出下列处理决定： （一）投诉人撤回投诉的，终止投诉处理； （二）投诉缺乏事实依据的，驳回投诉； （三）投诉事项经查证属实的，分别按照本办法有关规定处理。"},{"i":18,"n":"第十八条","txt":"财政部门经审查，认定采购文件具有明显倾向性或者歧视性等问题，给投诉人或者其他供应商合法权益造成或者可能造成损害的，按下列情况分别处理： （一）采购活动尚未完成的，责令修改采购文件，并按修改后的采购文件开展采购活动； （二）采购活动已经完成，但尚未签订政府采购合同的，决定采购活动违法，责令重新开展采购活动； （三）采购活动已经完成，并且已经签订政府采购合同的，决定采购活动违法，由被投诉人按照有关法律规定承担相应的赔偿责任。"},{"i":19,"n":"第十九条","txt":"财政部门经审查，认定采购文件、采购过程影响或者可能影响中标、成交结果的，或者中标、成交结果的产生过程存在违法行为的，按下列情况分别处理： （一）政府采购合同尚未签订的，分别根据不同情况决定全部或者部分采购行为违法，责令重新开展采购活动； （二）政府采购合同已经签订但尚未履行的，决定撤销合同，责令重新开展采购活动； （三）政府采购合同已经履行的，决定采购活动违法，给采购人、投诉人造成损失的，由相关责任人承担赔偿责任。"},{"i":20,"n":"第二十条","txt":"财政部门应当自受理投诉之日起30个工作日内，对投诉事项作出处理决定，并以书面形式通知投诉人、被投诉人及其他与投诉处理结果有利害关系的政府采购当事人。"},{"i":21,"n":"第二十一条","txt":"财政部门作出处理决定，应当制作投诉处理决定书，并加盖印章。投诉处理决定书应当包括下列主要内容： （一）投诉人和被投诉人的姓名或者名称、住所等； （二）委托代理人办理的，代理人的姓名、职业、住址、联系方式等； （三）处理决定的具体内容及事实根据和法律依据； （四）告知投诉人行政复议申请权和诉讼权利； （五）作出处理决定的日期。 投诉处理决定书的送达，依照民事诉讼法关于送达的规定执行。"},{"i":22,"n":"第二十二条","txt":"财政部门在处理投诉事项期间，可以视具体情况书面通知被投诉人暂停采购活动，但暂停时间最长不得超过30日。 被投诉人收到通知后应当立即暂停采购活动，在法定的暂停期限结束前或者财政部门发出恢复采购活动通知前，不得进行该项采购活动。"},{"i":23,"n":"第二十三条","txt":"财政部门应当将投诉处理结果在省级以上财政部门指定的政府采购信息发布媒体上公告。"},{"i":24,"n":"第二十四条","txt":"投诉人对财政部门的投诉处理决定不服或者财政部门逾期未作处理的，可以依法申请行政复议或者向人民法院提起行政诉讼。"},{"i":25,"n":"第二十五条","txt":"财政部门在处理投诉过程中，发现被投诉人及其工作人员、评标委员会成员、供应商有违法行为，本机关有权处理、处罚的，应当依法予以处理、处罚；本机关无权处理的，应当转送有权处理的机关依法处理。"},{"i":26,"n":"第二十六条","txt":"投诉人有下列情形之一的，属于虚假、恶意投诉，财政部门应当驳回投诉，将其列入不良行为记录名单，并依法予以处罚： （一）1年内3次以上投诉均查无实据的； （二）捏造事实或者提供虚假投诉材料的。"},{"i":27,"n":"第二十七条","txt":"被投诉人的违法行为给他人造成损失的，应当依照有关民事法律规定承担民事责任。"},{"i":28,"n":"第二十八条","txt":"财政部门工作人员在投诉处理过程中滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"财政部门处理投诉不得向投诉人和被投诉人收取任何费用。但因处理投诉发生的鉴定费用，应当按照“谁过错谁负担”的原则由过错方负担；双方都有过错的，由双方合理分担。"},{"i":30,"n":"第三十条","txt":"财政部门应当建立投诉处理档案管理制度，并自觉接受有关部门依法进行的监督检查。"},{"i":31,"n":"第三十一条","txt":"对在投诉处理过程中知悉的商业秘密及个人隐私，财政部门及知情人应当负保密责任。"},{"i":32,"n":"第三十二条","txt":"本办法自2004年9月11日起施行。"}],"jiaokeshufadingxukeshiyongzuopinzhifubaochoubanfa":[{"i":1,"n":"第一条","txt":"为保护文学、艺术和科学作品作者的著作权，规范编写出版教科书使用已发表作品的行为，根据《中华人民共和国著作权法》、《中华人民共和国著作权法实施条例》及《著作权集体管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于使用已发表作品编写出版九年制义务教育和国家教育规划教科书的行为。本办法所称教科书不包括教学参考书和教学辅导材料。 本办法所称九年制义务教育教科书和国家教育规划教科书，是指为实施义务教育、高中阶段教育、职业教育、高等教育、民族教育、特殊教育，保证基本的教学标准，或者为达到国家对某一领域、某一方面教育教学的要求，根据国务院教育行政部门或者省级人民政府教育行政部门制定的课程方案、专业教学指导方案而编写出版的教科书。"},{"i":3,"n":"第三条","txt":"在教科书中汇编已经发表的作品片断或者短小的文字作品、音乐作品或者单幅的美术作品、摄影作品，除作者事先声明不许使用的外，可以不经著作权人许可，但应当支付报酬，指明作者姓名、作品名称，并且不得侵犯著作权人依法享有的其他权利。 作品片断或者短小的文字作品，是指九年制义务教育教科书中使用的单篇不超过2000字的文字作品，或者国家教育规划（不含九年制义务教育）教科书中使用的单篇不超过3000字的文字作品。 短小的音乐作品，是指九年制义务教育和国家教育规划教科书中使用的单篇不超过5页面或时长不超过5分钟的单声部音乐作品，或者乘以相应倍数的多声部音乐作品。"},{"i":4,"n":"第四条","txt":"教科书汇编者支付报酬的标准如下： （一）文字作品：每千字300元，不足千字的按千字计算； （二）音乐作品：每首300元； （三）美术作品、摄影作品：每幅200元，用于封面或者封底的，每幅400元； （四）在与音乐教科书配套的录音制品教科书中使用的已有录音制品：每首50元。 支付报酬的字数按实有正文计算，即以排印的版面每行字数乘以全部实有的行数计算。占行题目或者末尾排印不足一行的，按一行计算。 诗词每十行按一千字计算；不足十行的按十行计算。 非汉字的文字作品，按照相同版面同等字号汉字数付酬标准的80%计酬。"},{"i":5,"n":"第五条","txt":"使用改编作品编写出版教科书，按照本办法第四条的规定确定报酬后，由改编作品的作者和原作品的作者协商分配，协商不成的，应当等额分配。 使用的作品有两个或者两个以上作者的，应当等额分配该作品的报酬，作者另有约定的除外。"},{"i":6,"n":"第六条","txt":"教科书出版发行存续期间，教科书汇编者应当按照本办法每年向著作权人支付一次报酬。 报酬自教科书出版之日起2个月内向著作权人支付。 教科书汇编者未按照前款规定向著作权人支付报酬，应当在每学期开学第一个月内将其应当支付的报酬连同邮资以及使用作品的有关情况交给相关的著作权集体管理组织。教科书汇编者支付的报酬到账后，著作权集体管理组织应当及时按相关规定向著作权人转付，并及时在其网站上公告教科书汇编者使用作品的有关情况。 著作权集体管理组织收转报酬，应当编制报酬收转记录。 使用作品的有关情况包括使用作品的名称、作者（包括原作者和改编者）姓名、作品字数、出版时间等。"},{"i":7,"n":"第七条","txt":"教科书出版后，著作权人要求教科书汇编者提供样书的，教科书汇编者应当向著作权人提供。 教科书汇编者按照本办法通过著作权集体管理组织转付报酬的，可以将样书交给相关的著作权集体管理组织，由其转交给著作权人。 转交样书产生的费用由教科书汇编者承担。"},{"i":8,"n":"第八条","txt":"教科书汇编者按照本办法第六条第三款规定将相应报酬转交给著作权集体管理组织后，对著作权人不再承担支付报酬的义务。"},{"i":9,"n":"第九条","txt":"教科书汇编者未按照本办法规定支付报酬的，应当承担停止侵权、消除影响、赔礼道歉、赔偿损失等民事责任。"},{"i":10,"n":"第十条","txt":"教科书汇编者向录音制作者支付报酬，适用本办法第六条、第八条和第九条规定。"},{"i":11,"n":"第十一条","txt":"本办法自2013年12月1日起施行。本办法施行前发布的其他有关规定与本办法不一致的，以本办法为准。"}],"wugonghainongchanpinguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强对无公害农产品的管理，维护消费者权益，提高农产品质量，保护农业生态环境，促进农业可持续发展，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称无公害农产品，是指产地环境、生产过程和产品质量符合国家有关标准和规范的要求，经认证合格获得认证证书并允许使用无公害农产品标志的未经加工或者初加工的食用农产品。"},{"i":3,"n":"第三条","txt":"无公害农产品管理工作，由政府推动，并实行产地认定和产品认证的工作模式。"},{"i":4,"n":"第四条","txt":"在中华人民共和国境内从事无公害农产品生产、产地认定、产品认证和监督管理等活动，适用本办法。"},{"i":5,"n":"第五条","txt":"全国无公害农产品的管理及质量监督工作，由农业部门、国家质量监督检验检疫部门和国家认证认可监督管理委员会按照“三定”方案赋予的职责和国务院的有关规定，分工负责，共同做好工作。"},{"i":6,"n":"第六条","txt":"各级农业行政主管部门和质量监督检验检疫部门应当在政策、资金、技术等方面扶持无公害农产品的发展，组织无公害农产品新技术的研究、开发和推广。"},{"i":7,"n":"第七条","txt":"国家鼓励生产单位和个人申请无公害农产品产地认定和产品认证。 实施无公害农产品认证的产品范围由农业部、国家认证认可监督管理委员会共同确定、调整。"},{"i":8,"n":"第八条","txt":"国家适时推行强制性无公害农产品认证制度。"},{"i":9,"n":"第九条","txt":"无公害农产品产地应当符合下列条件： （一）产地环境符合无公害农产品产地环境的标准要求； （二）区域范围明确； （三）具备一定的生产规模。"},{"i":10,"n":"第十条","txt":"无公害农产品的生产管理应当符合下列条件： （一）生产过程符合无公害农产品生产技术的标准要求； （二）有相应的专业技术和管理人员； （三）有完善的质量控制措施，并有完整的生产和销售记录档案。"},{"i":11,"n":"第十一条","txt":"从事无公害农产品生产的单位或者个人，应当严格按规定使用农业投入品。禁止使用国家禁用、淘汰的农业投入品。"},{"i":12,"n":"第十二条","txt":"无公害农产品产地应当树立标示牌，标明范围、产品品种、责任人。"},{"i":13,"n":"第十三条","txt":"省级农业行政主管部门根据本办法的规定负责组织实施本辖区内无公害农产品产地的认定工作。"},{"i":14,"n":"第十四条","txt":"申请无公害农产品产地认定的单位或者个人（以下简称申请人），应当向县级农业行政主管部门提交书面申请，书面申请应当包括以下内容： （一）申请人的姓名（名称）、地址、电话号码； （二）产地的区域范围、生产规模； （三）无公害农产品生产计划； （四）产地环境说明； （五）无公害农产品质量控制措施； （六）有关专业技术和管理人员的资质证明材料; （七）保证执行无公害农产品标准和规范的声明； （八）其他有关材料。"},{"i":15,"n":"第十五条","txt":"县级农业行政主管部门自收到申请之日起，在10个工作日内完成对申请材料的初审工作。 申请材料初审不符合要求的，应当书面通知申请人。"},{"i":16,"n":"第十六条","txt":"申请材料初审符合要求的，县级农业行政主管部门应当逐级将推荐意见和有关材料上报省级农业行政主管部门。"},{"i":17,"n":"第十七条","txt":"省级农业行政主管部门自收到推荐意见和有关材料之日起，在10个工作日内完成对有关材料的审核工作，符合要求的，组织有关人员对产地环境、区域范围、生产规模、质量控制措施、生产计划等进行现场检查。 现场检查不符合要求的，应当书面通知申请人。"},{"i":18,"n":"第十八条","txt":"现场检查符合要求的，应当通知申请人委托具有资质资格的检测机构，对产地环境进行检测。 承担产地环境检测任务的机构，根据检测结果出具产地环境检测报告。"},{"i":19,"n":"第十九条","txt":"省级农业行政主管部门对材料审核、现场检查和产地环境检测结果符合要求的，应当自收到现场检查报告和产地环境检测报告之日起，30个工作日内颁发无公害农产品产地认定证书，并报农业部和国家认证认可监督管理委员会备案。 不符合要求的，应当书面通知申请人。"},{"i":20,"n":"第二十条","txt":"无公害农产品产地认定证书有效期为3年。期满需要继续使用的，应当在有效期满90日前按照本办法规定的无公害农产品产地认定程序，重新办理。"},{"i":21,"n":"第二十一条","txt":"无公害农产品的认证机构，由国家认证认可监督管理委员会审批，并获得国家认证认可监督管理委员会授权的认可机构的资格认可后，方可从事无公害农产品认证活动。"},{"i":22,"n":"第二十二条","txt":"申请无公害产品认证的单位或者个人（以下简称申请人），应当向认证机构提交书面申请，书面申请应当包括以下内容： （一）申请人的姓名（名称）、地址、电话号码； （二）产品品种、产地的区域范围和生产规模； （三）无公害农产品生产计划； （四）产地环境说明； （五）无公害农产品质量控制措施； （六）有关专业技术和管理人员的资质证明材料; （七）保证执行无公害农产品标准和规范的声明； （八）无公害农产品产地认定证书； （九）生产过程记录档案； （十）认证机构要求提交的其他材料。"},{"i":23,"n":"第二十三条","txt":"认证机构自收到无公害农产品认证申请之日起，应当在15个工作日内完成对申请材料的审核。 材料审核不符合要求的，应当书面通知申请人。"},{"i":24,"n":"第二十四条","txt":"符合要求的，认证机构可以根据需要派员对产地环境、区域范围、生产规模、质量控制措施、生产计划、标准和规范的执行情况等进行现场检查。 现场检查不符合要求的，应当书面通知申请人。"},{"i":25,"n":"第二十五条","txt":"材料审核符合要求的、或者材料审核和现场检查符合要求的（限于需要对现场进行检查时），认证机构应当通知申请人委托具有资质资格的检测机构对产品进行检测。 承担产品检测任务的机构，根据检测结果出具产品检测报告。"},{"i":26,"n":"第二十六条","txt":"认证机构对材料审核、现场检查（限于需要对现场进行检查时）和产品检测结果符合要求的，应当在自收到现场检查报告和产品检测报告之日起，30个工作日内颁发无公害农产品认证证书。 不符合要求的，应当书面通知申请人。"},{"i":27,"n":"第二十七条","txt":"认证机构应当自颁发无公害农产品认证证书后30个工作日内，将其颁发的认证证书副本同时报农业部和国家认证认可监督管理委员会备案，由农业部和国家认证认可监督管理委员会公告。"},{"i":28,"n":"第二十八条","txt":"无公害农产品认证证书有效期为3年。期满需要继续使用的，应当在有效期满90日前按照本办法规定的无公害农产品认证程序，重新办理。 在有效期内生产无公害农产品认证证书以外的产品品种的，应当向原无公害农产品认证机构办理认证证书的变更手续。"},{"i":29,"n":"第二十九条","txt":"无公害农产品产地认定证书、产品认证证书格式由农业部、国家认证认可监督管理委员会规定。"},{"i":30,"n":"第三十条","txt":"农业部和国家认证认可监督管理委员会制定并发布《无公害农产品标志管理办法》。"},{"i":31,"n":"第三十一条","txt":"无公害农产品标志应当在认证的品种、数量等范围内使用。"},{"i":32,"n":"第三十二条","txt":"获得无公害农产品认证证书的单位或者个人，可以在证书规定的产品、包装、标签、广告、说明书上使用无公害农产品标志。"},{"i":33,"n":"第三十三条","txt":"农业部、国家质量监督检验检疫总局、国家认证认可监督管理委员会和国务院有关部门根据职责分工依法组织对无公害农产品的生产、销售和无公害农产品标志使用等活动进行监督管理。 （一）查阅或者要求生产者、销售者提供有关材料； （二）对无公害农产品产地认定工作进行监督； （三）对无公害农产品认证机构的认证工作进行监督； （四）对无公害农产品的检测机构的检测工作进行检查； （五）对使用无公害农产品标志的产品进行检查、检验和鉴定； （六）必要时对无公害农产品经营场所进行检查。"},{"i":34,"n":"第三十四条","txt":"认证机构对获得认证的产品进行跟踪检查，受理有关的投诉、申诉工作。"},{"i":35,"n":"第三十五条","txt":"任何单位和个人不得伪造、冒用、转让、买卖无公害农产品产地认定证书、产品认证证书和标志。"},{"i":36,"n":"第三十六条","txt":"获得无公害农产品产地认定证书的单位或者个人违反本办法，有下列情形之一的，由省级农业行政主管部门予以警告，并责令限期改正；逾期未改正的，撤销其无公害农产品产地认定证书： （一）无公害农产品产地被污染或者产地环境达不到标准要求的； （二）无公害农产品产地使用的农业投入品不符合无公害农产品相关标准要求的； （三）擅自扩大无公害农产品产地范围的。"},{"i":37,"n":"第三十七条","txt":"违反本办法第三十五条规定的，由县级以上农业行政主管部门和各地质量监督检验检疫部门根据各自的职责分工责令其停止，并可处以违法所得1倍以上3倍以下的罚款，但最高罚款不得超过3万元；没有违法所得的，可以处1万元以下的罚款。 法律、法规对处罚另有规定的，从其规定。"},{"i":38,"n":"第三十八条","txt":"获得无公害农产品认证并加贴标志的产品，经检查、检测、鉴定，不符合无公害农产品质量标准要求的，由县级以上农业行政主管部门或者各地质量监督检验检疫部门责令停止使用无公害农产品标志，由认证机构暂停或者撤销认证证书。"},{"i":39,"n":"第三十九条","txt":"从事无公害农产品管理的工作人员滥用职权、徇私舞弊、玩忽职守的，由所在单位或者所在单位的上级行政主管部门给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"从事无公害农产品的产地认定的部门和产品认证的机构不得收取费用。 检测机构的检测、无公害农产品标志按国家规定收取费用。"},{"i":41,"n":"第四十一条","txt":"本办法由农业部、国家质量监督检验检疫总局和国家认证认可监督管理委员会负责解释。"},{"i":42,"n":"第四十二条","txt":"本办法自发布之日起施行。"}],"wugonghainongchanpinguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对无公害农产品的管理，维护消费者权益，提高农产品质量，保护农业生态环境，促进农业可持续发展，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称无公害农产品，是指产地环境、生产过程和产品质量符合国家有关标准和规范的要求，经认证合格获得认证证书并允许使用无公害农产品标志的未经加工或者初加工的食用农产品。"},{"i":3,"n":"第三条","txt":"无公害农产品管理工作，由政府推动，并实行产地认定和产品认证的工作模式。"},{"i":4,"n":"第四条","txt":"在中华人民共和国境内从事无公害农产品生产、产地认定、产品认证和监督管理等活动，适用本办法。"},{"i":5,"n":"第五条","txt":"全国无公害农产品的管理及质量监督工作，由农业部门、国家质量监督检验检疫部门和国家认证认可监督管理委员会按照“三定”方案赋予的职责和国务院的有关规定，分工负责，共同做好工作。"},{"i":6,"n":"第六条","txt":"各级农业行政主管部门和质量监督检验检疫部门应当在政策、资金、技术等方面扶持无公害农产品的发展，组织无公害农产品新技术的研究、开发和推广。"},{"i":7,"n":"第七条","txt":"国家鼓励生产单位和个人申请无公害农产品产地认定和产品认证。 实施无公害农产品认证的产品范围由农业部、国家认证认可监督管理委员会共同确定、调整。"},{"i":8,"n":"第八条","txt":"国家适时推行强制性无公害农产品认证制度。"},{"i":9,"n":"第九条","txt":"无公害农产品产地应当符合下列条件： （一）产地环境符合无公害农产品产地环境的标准要求； （二）区域范围明确； （三）具备一定的生产规模。"},{"i":10,"n":"第十条","txt":"无公害农产品的生产管理应当符合下列条件： （一）生产过程符合无公害农产品生产技术的标准要求； （二）有相应的专业技术和管理人员； （三）有完善的质量控制措施，并有完整的生产和销售记录档案。"},{"i":11,"n":"第十一条","txt":"从事无公害农产品生产的单位或者个人，应当严格按规定使用农业投入品。禁止使用国家禁用、淘汰的农业投入品。"},{"i":12,"n":"第十二条","txt":"无公害农产品产地应当树立标示牌，标明范围、产品品种、责任人。"},{"i":13,"n":"第十三条","txt":"省级农业行政主管部门根据本办法的规定负责组织实施本辖区内无公害农产品产地的认定工作。"},{"i":14,"n":"第十四条","txt":"申请无公害农产品产地认定的单位或者个人（以下简称申请人），应当向县级农业行政主管部门提交书面申请，书面申请应当包括以下内容： （一）申请人的姓名（名称）、地址、电话号码； （二）产地的区域范围、生产规模； （三）无公害农产品生产计划； （四）产地环境说明； （五）无公害农产品质量控制措施； （六）有关专业技术和管理人员的资质证明材料； （七）保证执行无公害农产品标准和规范的声明； （八）其他有关材料。"},{"i":15,"n":"第十五条","txt":"县级农业行政主管部门自收到申请之日起，在10个工作日内完成对申请材料的初审工作。 申请材料初审不符合要求的，应当书面通知申请人。"},{"i":16,"n":"第十六条","txt":"申请材料初审符合要求的，县级农业行政主管部门应当逐级将推荐意见和有关材料上报省级农业行政主管部门。"},{"i":17,"n":"第十七条","txt":"省级农业行政主管部门自收到推荐意见和有关材料之日起，在10个工作日内完成对有关材料的审核工作，符合要求的，组织有关人员对产地环境、区域范围、生产规模、质量控制措施、生产计划等进行现场检查。 现场检查不符合要求的，应当书面通知申请人。"},{"i":18,"n":"第十八条","txt":"现场检查符合要求的，应当通知申请人委托具有资质资格的检测机构，对产地环境进行检测。 承担产地环境检测任务的机构，根据检测结果出具产地环境检测报告。"},{"i":19,"n":"第十九条","txt":"省级农业行政主管部门对材料审核、现场检查和产地环境检测结果符合要求的，应当自收到现场检查报告和产地环境检测报告之日起，30个工作日内颁发无公害农产品产地认定证书，并报农业部和国家认证认可监督管理委员会备案。 不符合要求的，应当书面通知申请人。"},{"i":20,"n":"第二十条","txt":"无公害农产品产地认定证书有效期为3年。期满需要继续使用的，应当在有效期满90日前按照本办法规定的无公害农产品产地认定程序，重新办理。"},{"i":21,"n":"第二十一条","txt":"无公害农产品的认证机构，由国家认证认可监督管理委员会审批，并获得国家认证认可监督管理委员会授权的认可机构的资格认可后，方可从事无公害农产品认证活动。"},{"i":22,"n":"第二十二条","txt":"申请无公害产品认证的单位或者个人（以下简称申请人），应当向认证机构提交书面申请，书面申请应当包括以下内容： （一）申请人的姓名（名称）、地址、电话号码； （二）产品品种、产地的区域范围和生产规模； （三）无公害农产品生产计划； （四）产地环境说明； （五）无公害农产品质量控制措施； （六）有关专业技术和管理人员的资质证明材料； （七）保证执行无公害农产品标准和规范的声明； （八）无公害农产品产地认定证书； （九）生产过程记录档案； （十）认证机构要求提交的其他材料。"},{"i":23,"n":"第二十三条","txt":"认证机构自收到无公害农产品认证申请之日起，应当在15个工作日内完成对申请材料的审核。 材料审核不符合要求的，应当书面通知申请人。"},{"i":24,"n":"第二十四条","txt":"符合要求的，认证机构可以根据需要派员对产地环境、区域范围、生产规模、质量控制措施、生产计划、标准和规范的执行情况等进行现场检查。 现场检查不符合要求的，应当书面通知申请人。"},{"i":25,"n":"第二十五条","txt":"材料审核符合要求的、或者材料审核和现场检查符合要求的（限于需要对现场进行检查时），认证机构应当通知申请人委托具有资质资格的检测机构对产品进行检测。 承担产品检测任务的机构，根据检测结果出具产品检测报告。"},{"i":26,"n":"第二十六条","txt":"认证机构对材料审核、现场检查（限于需要对现场进行检查时）和产品检测结果符合要求的，应当在自收到现场检查报告和产品检测报告之日起，30个工作日内颁发无公害农产品认证证书。 不符合要求的，应当书面通知申请人。"},{"i":27,"n":"第二十七条","txt":"认证机构应当自颁发无公害农产品认证证书后30个工作日内，将其颁发的认证证书副本同时报农业部和国家认证认可监督管理委员会备案，由农业部和国家认证认可监督管理委员会公告。"},{"i":28,"n":"第二十八条","txt":"无公害农产品认证证书有效期为3年。期满需要继续使用的，应当在有效期满90日前按照本办法规定的无公害农产品认证程序，重新办理。 在有效期内生产无公害农产品认证证书以外的产品品种的，应当向原无公害农产品认证机构办理认证证书的变更手续。"},{"i":29,"n":"第二十九条","txt":"无公害农产品产地认定证书、产品认证证书格式由农业部、国家认证认可监督管理委员会规定。"},{"i":30,"n":"第三十条","txt":"农业部和国家认证认可监督管理委员会制定并发布《无公害农产品标志管理办法》。"},{"i":31,"n":"第三十一条","txt":"无公害农产品标志应当在认证的品种、数量等范围内使用。"},{"i":32,"n":"第三十二条","txt":"获得无公害农产品认证证书的单位或者个人，可以在证书规定的产品、包装、标签、广告、说明书上使用无公害农产品标志。"},{"i":33,"n":"第三十三条","txt":"农业部、国家质量监督检验检疫总局、国家认证认可监督管理委员会和国务院有关部门根据职责分工依法组织对无公害农产品的生产、销售和无公害农产品标志使用等活动进行监督管理。 （一）查阅或者要求生产者、销售者提供有关材料； （二）对无公害农产品产地认定工作进行监督； （三）对无公害农产品认证机构的认证工作进行监督； （四）对无公害农产品的检测机构的检测工作进行检查； （五）对使用无公害农产品标志的产品进行检查、检验和鉴定； （六）必要时对无公害农产品经营场所进行检查。"},{"i":34,"n":"第三十四条","txt":"认证机构对获得认证的产品进行跟踪检查，受理有关的投诉、申诉工作。"},{"i":35,"n":"第三十五条","txt":"任何单位和个人不得伪造、冒用、转让、买卖无公害农产品产地认定证书、产品认证证书和标志。"},{"i":36,"n":"第三十六条","txt":"获得无公害农产品产地认定证书的单位或者个人违反本办法，有下列情形之一的，由省级农业行政主管部门予以警告，并责令限期改正；逾期未改正的，撤销其无公害农产品产地认定证书： （一）无公害农产品产地被污染或者产地环境达不到标准要求的； （二）无公害农产品产地使用的农业投入品不符合无公害农产品相关标准要求的； （三）擅自扩大无公害农产品产地范围的。"},{"i":37,"n":"第三十七条","txt":"违反本办法第三十五条规定的，由县级以上农业行政主管部门和各地质量监督检验检疫部门根据各自的职责分工责令其停止，并可处以违法所得1倍以上3倍以下的罚款，但最高罚款不得超过3万元；没有违法所得的，可以处1万元以下的罚款。 法律、法规对处罚另有规定的，从其规定。"},{"i":38,"n":"第三十八条","txt":"获得无公害农产品认证并加贴标志的产品，经检查、检测、鉴定，不符合无公害农产品质量标准要求的，由县级以上农业行政主管部门或者各地质量监督检验检疫部门责令停止使用无公害农产品标志，由认证机构暂停或者撤销认证证书。"},{"i":39,"n":"第三十九条","txt":"从事无公害农产品管理的工作人员滥用职权、徇私舞弊、玩忽职守的，由所在单位或者所在单位的上级行政主管部门给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"从事无公害农产品的产地认定的部门和产品认证的机构不得收取费用。 检测机构的检测、无公害农产品标志按国家规定收取费用。"},{"i":41,"n":"第四十一条","txt":"本办法由农业部、国家质量监督检验检疫总局和国家认证认可监督管理委员会负责解释。"},{"i":42,"n":"第四十二条","txt":"本办法自发布之日起施行。"}],"wuqizhuangbeikeyanshengchanxukeshishibanfa-2":[{"i":1,"n":"第一条","txt":"为了规范武器装备科研生产许可管理，根据《武器装备科研生产许可管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"从事武器装备科研生产许可目录（以下简称许可目录）所列的武器装备科研生产活动，应当依照本办法申请取得武器装备科研生产许可；未取得武器装备科研生产许可的，不得从事许可目录所列的武器装备科研生产活动。但是，经国务院、中央军委批准的，以及专门的武器装备科学研究活动除外。 本办法所称武器装备科研生产活动，是指武器装备的总体、系统、专用配套产品的科研生产活动。 本办法所称专门的武器装备科学研究活动，是指武器装备领域的理论性、基础性科学研究活动。"},{"i":3,"n":"第三条","txt":"武器装备科研生产许可管理，应当根据国防建设和武器装备发展需要，遵循统筹兼顾、合理布局、鼓励竞争、安全保密、严格管理、公平公正的原则。"},{"i":4,"n":"第四条","txt":"武器装备科研生产许可根据武器装备及其专用配套产品的重要程度，分为第一类许可和第二类许可，武器装备科研生产许可的具体分类在许可目录中规定。许可目录由国家国防科技工业局（以下简称国防科工局）会同中国人民解放军总装备部（以下简称总装备部）共同制定和发布，并适时调整。"},{"i":5,"n":"第五条","txt":"国防科工局负责全国的武器装备科研生产许可管理，履行下列职责： （一）制定武器装备科研生产许可管理的政策、规定； （二）会同总装备部制定许可目录； （三）受理、审查第一类许可的申请，审批、颁发、撤销、吊销武器装备科研生产许可证，办理武器装备科研生产许可证的变更、延续及注销； （四）组织开展武器装备科研生产许可监督检查。 国防科工局武器装备科研生产许可管理办公室负责日常工作。"},{"i":6,"n":"第六条","txt":"总装备部负责全国武器装备科研生产许可的协同管理。总装备部武器装备科研生产许可协同管理部门（以下简称总装备部许可协同管理部门）履行下列职责： （一）参与制定武器装备科研生产许可管理的政策、规定； （二）会同编制许可目录； （三）协同审查武器装备科研生产许可的申请、发放、变更、延续、撤销和注销，对行政处罚提出意见； （四）组织中国人民解放军派出的驻相关单位或者地区的军事代表机构（以下简称派驻军事代表机构）参与武器装备科研生产许可现场审查； （五）协同开展武器装备科研生产许可监督检查。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市人民政府国防科技工业管理部门（以下称地方国防科技工业管理部门）履行下列职责： （一）受理、审查本行政区域内的第二类许可申请，并提出审查意见； （二）负责本行政区域内取得第二类许可的武器装备科研生产单位的监督管理；调查核实本行政区域内违法从事武器装备科研生产的单位和行为，并向国防科工局提出处理建议； （三）协助国防科工局对本行政区域内申请第一类许可的单位进行现场审查； （四）协助国防科工局对本行政区域内取得第一类许可的武器装备科研生产单位进行监督管理。"},{"i":8,"n":"第八条","txt":"派驻军事代表机构按照军队内部职责分工协同地方国防科技工业管理部门开展派驻地区的武器装备科研生产许可审查和监督管理工作。"},{"i":9,"n":"第九条","txt":"国防科工局按照国家武器装备科研生产能力布局要求，根据武器装备科研生产的实际需要，经征求总装备部意见，对第一类许可实行数量限制。实行数量限制的具体专业或者产品和限制数量另行规定。"},{"i":10,"n":"第十条","txt":"申请武器装备科研生产许可的单位，应当具备《武器装备科研生产许可管理条例》第七条规定的条件。其中，申请武器装备总体和系统科研生产许可的，还应当具有相应的工程组织、协调能力。"},{"i":11,"n":"第十一条","txt":"申请武器装备科研生产许可的单位，应当提交《武器装备科研生产许可证申请书》，同时提交以下文件、材料（复印件）： （一）企业法人营业执照或者事业单位法人证书； （二）相应的质量管理体系认证证书； （三）安全生产达标证明文件（其中申请从事危险品生产的，提交安全生产许可证或者安全生产评价报告）； （四）保密资格证书； （五）法律、行政法规规定的环保、消防验收文件或者达标文件； （六）申请单位认为可以证明其能力条件的其他文件、材料。"},{"i":12,"n":"第十二条","txt":"申请武器装备科研生产许可的单位，按照下列规定提出申请： （一）申请第一类许可的，或者同时申请第一类、第二类许可的，向国防科工局提出申请，并提交申请材料一式三份（含电子版光盘）。 （二）申请第二类许可的，向其所在省、自治区、直辖市的国防科技工业管理部门提出申请，并提交申请材料一式三份（含电子版光盘）。 第一类许可、第二类许可的申请材料（含电子版光盘）应当同时报送总装备部许可协同管理部门一份。"},{"i":13,"n":"第十三条","txt":"国防科工局和地方国防科技工业管理部门应当依照《中华人民共和国行政许可法》第三十二条的规定进行审查，符合受理条件的，应当在5日内作出受理决定。申请材料不齐全或者不符合法定形式的，应当当场或者在5日内一次告知申请单位需要补正的全部内容。作出不予受理决定的，应当书面告知并说明理由。"},{"i":14,"n":"第十四条","txt":"总装备部许可协同管理部门对许可申请材料的审查意见，应当自收到申请材料之日起4日内向国防科工局或者地方国防科技工业管理部门反馈。"},{"i":15,"n":"第十五条","txt":"国防科工局和地方国防科技工业管理部门受理申请后，应当组织专家对武器装备科研生产许可申请进行现场审查，总装备部许可协同管理部门指派派驻军事代表机构参加。对因涉及国家核心机密不宜进行现场审查的，可以根据实际情况进行书面审查。专家现场审查所需时间不计算在本章规定的许可时限内。 武器装备科研生产许可现场审查和专家管理的具体办法，由国防科工局和总装备部另行制定。"},{"i":16,"n":"第十六条","txt":"地方国防科技工业管理部门负责组织对申请单位进行审查的，应当自受理申请之日起30日内完成审查和征求派驻军事代表机构意见的工作，并将审查意见和全部申请材料报送国防科工局，同时报送总装备部许可协同管理部门。"},{"i":17,"n":"第十七条","txt":"国防科工局应当自收到地方国防科技工业管理部门报送的审查意见和全部申请材料之日起30日内，作出许可决定。 国防科工局直接受理申请并组织进行审查的，应当自受理申请之日起60日内，作出许可决定。 国防科工局在作出许可决定前，应当书面征求总装备部的意见。总装备部应当在10日内反馈意见。 作出准予许可决定的，应当自作出决定之日起10日内向申请单位颁发武器装备科研生产许可证；作出不准予许可决定的，应当书面通知申请单位并说明理由。"},{"i":18,"n":"第十八条","txt":"武器装备科研生产许可证应当包括以下内容： （一）法人名称； （二）法定代表人； （三）注册地址； （四）科研生产场所地址； （五）许可的专业或者产品名称； （六）证书编号； （七）发证机关； （八）发证（换证）日期； （九）证书有效期限。"},{"i":19,"n":"第十九条","txt":"武器装备科研生产许可证的有效期限为5年。武器装备科研生产许可证由国防科工局统一印制。"},{"i":20,"n":"第二十条","txt":"取得武器装备科研生产许可的单位在武器装备科研生产许可证有效期限内，其法人名称、法定代表人、注册地址发生变更的，应当自发生变更之日起60日内向国防科工局提出武器装备科研生产许可证变更申请，同时抄送总装备部许可协同管理部门和原许可审查部门。"},{"i":21,"n":"第二十一条","txt":"申请变更法人名称或者注册地址的，应当提交其上级部门或者国家有关部门的批准文件，变更后的企业法人营业执照或者事业单位法人证书，以及变更后的保密资格证书等材料。 申请变更法定代表人的，应当提交法定代表人的任职文件或者其他有关证明文件，以及变更后的企业法人营业执照或者事业单位法人证书和保密资格证书。 其中，对因资产重组或者其他涉及资产变化问题，导致法人名称、注册地址或者法定代表人发生变化的，申请单位应当书面说明有关情况，并提供公司章程等相关证明材料。"},{"i":22,"n":"第二十二条","txt":"国防科工局收到变更申请后，应当依照法定条件和程序进行审查，必要时组织专家进行现场核查。符合变更条件的，由国防科工局自受理申请之日起30日内办理变更手续。专家现场核查所需时间不计算在本条规定的时限内。"},{"i":23,"n":"第二十三条","txt":"取得武器装备科研生产许可的单位在武器装备科研生产许可证有效期限内，申请增加武器装备科研生产许可专业或者产品的，应当按照本办法的规定重新提出申请。"},{"i":24,"n":"第二十四条","txt":"取得武器装备科研生产许可的单位拟申请延续武器装备科研生产许可期限的，应当在武器装备科研生产许可证有效期届满6个月前，按照本办法第十二条的规定提出许可延续申请。 国防科工局和地方国防科技工业管理部门应当在该许可有效期届满前，按照本办法规定的条件和程序对许可延续申请进行审查，由国防科工局按照本办法第十七条的规定作出是否准予延续的决定。作出准予延续决定的，应当换发武器装备科研生产许可证；作出不予延续决定的，应当书面告知申请单位并说明理由。"},{"i":25,"n":"第二十五条","txt":"取得武器装备科研生产许可的单位，拟不再延续武器装备科研生产许可期限的，应当在许可证有效期届满6个月前向国防科工局书面报告。在国防科工局商总装备部作出妥善安排前，不得擅自停止武器装备科研生产。"},{"i":26,"n":"第二十六条","txt":"国防科工局对全国从事许可目录所列的武器装备科研生产活动的单位实施监督，建立监督检查制度，组织开展监督检查工作，并对地方国防科技工业管理部门依法履行武器装备科研生产许可管理有关职责的情况实施监督检查。 总装备部协同对全国从事许可目录所列的武器装备科研生产活动的单位实施监督，并对派驻军事代表机构履行武器装备科研生产许可协同管理职责的情况进行监督。 地方国防科技工业管理部门应当按照本办法第七条的规定，对本行政区域内从事许可目录所列的武器装备科研生产活动的单位实施监督。 派驻军事代表机构对取得武器装备科研生产许可单位的武器装备科研生产许可条件保持情况和任务完成情况进行监督。发现问题的，应当及时逐级上报并告知国防科工局或者地方国防科技工业管理部门。 武器装备科研生产许可监督检查的具体办法，由国防科工局和总装备部另行制定。"},{"i":27,"n":"第二十七条","txt":"取得武器装备科研生产许可的单位，应当履行下列义务： （一）遵守法律、行政法规和本办法的规定； （二）妥善保管武器装备科研生产许可证，严格保密管理，不得泄露武器装备科研生产许可证载明的相关内容； （三）在已取得的武器装备科研生产许可的范围内从事武器装备科研生产活动； （四）保持与所从事的武器装备科研生产活动相适应的科研生产能力； （五）按照国家要求承担武器装备科研生产任务，接受国家武器装备科研生产订货，按照合同要求提供合格的科研成果和武器装备或者配套产品； （六）在武器装备科研生产合同、产品出厂证书上标注武器装备科研生产许可证编号； （七）建立年度自查制度，按照要求提交年度自查报告； （八）接受国防科工局、地方国防科技工业管理部门和总装备部、派驻军事代表机构的监督检查。"},{"i":28,"n":"第二十八条","txt":"取得武器装备科研生产许可的单位应当建立重大事项报告制度。在许可有效期内，发生上市、破产、歇业、改制、重组、科研生产场所搬迁、关键科研生产设备设施缺失等重大变化的，应当自发生变化之日起30日内向国防科工局书面报告变化情况，同时抄送总装备部许可协同管理部门和地方国防科技工业管理部门。国防科工局应当组织审查，根据审查情况商总装备部作出处理决定，并书面告知相关单位。 其中，取得武器装备科研生产许可的单位涉及外资进入资产重组或者境外上市的，应当在事前向国防科工局书面报告。经国防科工局商总装备部同意后，方可实施。"},{"i":29,"n":"第二十九条","txt":"取得武器装备科研生产许可的单位应当遵守国家保密法律、行政法规和有关规定，应当按照《武器装备科研生产许可管理条例》第三章的规定，建立健全保密管理制度，实行保密管理领导责任制，落实保密机构和人员，明确保密责任，进行保密培训，严格涉密人员管理，在保密要害部门、部位设置安全防护设施，保证涉密载体和国家秘密安全。"},{"i":30,"n":"第三十条","txt":"任何单位和个人不得伪造、变造武器装备科研生产许可证。取得武器装备科研生产许可的单位不得倒卖、出租、出借或者以其他形式转让武器装备科研生产许可证。武器装备科研生产许可证丢失、损毁的，应当及时向国防科工局报告有关情况并申请补发。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，国防科工局商总装备部后可以依法作出撤销武器装备科研生产许可的决定: （一）国防科工局和地方国防科技工业管理部门的工作人员滥用职权、玩忽职守作出准予许可决定的； （二）超越法定职权作出准予许可决定的； （三）违反法定程序作出准予许可决定的； （四）对不具备申请资格或者不符合法定条件的申请单位准予许可的； （五）依法可以撤销的其他情形。"},{"i":32,"n":"第三十二条","txt":"取得武器装备科研生产许可的单位有下列情形之一的，经商总装备部后，国防科工局依法办理许可注销手续，并告知有关部门： （一）武器装备科研生产许可有效期届满不再准予延续的； （二）武器装备科研生产许可证依法被吊销的； （三）武器装备科研生产许可依法被撤销的； （四）法人依法终止或者破产的； （五）依法应当注销的其他情形。"},{"i":33,"n":"第三十三条","txt":"国防科工局应当建立武器装备科研生产许可档案管理制度和武器装备科研生产许可管理数据库， 并与总装备部共享相关信息；编制并定向发布《武器装备科研生产许可证名录》，及时将武器装备科研生产许可证的发放、变更、延续、撤销、吊销、注销，以及对违法单位的行政处罚等情况通知相关部门。"},{"i":34,"n":"第三十四条","txt":"国防科工局和地方国防科技工业管理部门应当将办理武器装备科研生产许可的有关材料及时归档，妥善保管，严格保密。"},{"i":35,"n":"第三十五条","txt":"未依照本办法规定取得武器装备科研生产许可，擅自从事许可目录所列的武器装备科研生产活动的，责令改正，没收违法生产的产品，处违法生产产品货值金额1倍以上3倍以下的罚款；有违法所得的，没收违法所得。 其中，未经许可擅自从事武器装备总体或者枪支、弹药、放射性核材料和军用危险化学品等对社会公共安全有严重危害的武器装备科研生产活动的，处违法生产产品货值金额3倍的罚款；有违法所得的，没收违法所得。"},{"i":36,"n":"第三十六条","txt":"取得武器装备科研生产许可的单位在许可有效期内未能保持与所从事的武器装备科研生产活动相适应的科研生产能力和条件的，责令限期恢复；逾期未恢复的，根据其对武器装备科研生产任务影响的严重程度，给予警告或者处1万元以上3万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"取得武器装备科研生产许可的单位违反本办法规定，擅自停止武器装备科研生产或者拒绝依法承担相应的武器装备科研生产任务的，责令改正，给予警告；拒不改正的，处1万元以上3万元以下罚款。"},{"i":38,"n":"第三十八条","txt":"取得武器装备科研生产许可的单位出现本办法第二十八条所列的重大变化未按照规定时限报告的，给予警告，责令在10日内补报重大变化说明材料；经审查，不再符合许可条件的，由国防科工局商总装备部作出处理决定。"},{"i":39,"n":"第三十九条","txt":"取得武器装备科研生产许可的单位倒卖、出租、出借或者以其他形式转让武器装备科研生产许可证的，处10万元罚款；情节严重的，吊销武器装备科研生产许可证。违法接受并使用他人提供的武器装备科研生产许可证的，责令停止武器装备生产活动，没收违法生产的产品，处违法生产产品货值金额1倍以上3倍以下罚款；有违法所得的，没收违法所得。"},{"i":40,"n":"第四十条","txt":"取得武器装备科研生产许可的单位向本办法第二十七条规定的监督检查机关或者机构隐瞒有关情况、提供虚假材料或者拒绝接受监督检查的，以及未按照规定提交年度检查材料的，给予警告；情节严重的，处1万元以上3万元以下罚款。"},{"i":41,"n":"第四十一条","txt":"取得武器装备科研生产许可的单位违反《武器装备科研生产许可管理条例》第三章规定的，按照《武器装备科研生产许可管理条例》有关规定进行处理；对于造成国家秘密泄露的其他行为，处1万元以上3万元以下罚款。"},{"i":42,"n":"第四十二条","txt":"伪造、变造武器装备科研生产许可证的，责令停止违法行为，处10万元罚款；有违法所得的，没收违法所得。 丢失武器装备科研生产许可证造成泄密的，依照《中华人民共和国保守国家秘密法》有关规定处理。"},{"i":43,"n":"第四十三条","txt":"以欺骗、贿赂等不正当手段取得武器装备科研生产许可的，处5万元以上20万元以下罚款，并依照《中华人民共和国行政许可法》的有关规定作出处理。"},{"i":44,"n":"第四十四条","txt":"国防科工局和地方国防科技工业管理部门的工作人员违反本办法的规定，有下列情形之一的，由同级监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）对符合本办法规定条件的许可申请不予受理的； （二）申请单位提交的申请材料不齐全、不符合法定形式，不一次告知申请单位需要补正的全部内容的； （三）未依法说明不予许可的理由的。"},{"i":45,"n":"第四十五条","txt":"国防科工局和地方国防科技工业管理部门有下列情形之一的，由同级监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）对不符合本办法规定条件的申请单位准予许可或者超越法定职权作出准予许可决定的； （二）对符合本办法规定条件的申请单位不予许可或者不在法定期限内作出准予许可决定的； （三）发现未依照本办法规定申请取得武器装备科研生产许可而擅自从事许可目录所列的武器装备科研生产活动，不及时依法查处的。"},{"i":46,"n":"第四十六条","txt":"总装备部许可协同管理部门和派驻军事代表机构参与许可管理的工作人员违反本办法规定的，由总装备部会同军队有关部门依法作出处理。"},{"i":47,"n":"第四十七条","txt":"取得武器装备科研生产许可的单位违反本办法规定，被吊销武器装备科研生产许可证的，在3年内不得再次申请武器装备科研生产许可。"},{"i":48,"n":"第四十八条","txt":"武器装备科研生产许可申请单位隐瞒有关情况或者提供虚假材料造成许可现场审查终止的，给予警告；申请单位在1年内不得再次申请武器装备科研生产许可。"},{"i":49,"n":"第四十九条","txt":"本办法规定的行政处罚，由国防科工局实施。"},{"i":50,"n":"第五十条","txt":"本办法施行前已取得的《军工电子装备科研生产许可证》在证书有效期内继续有效，后续管理工作按照本办法规定执行。"},{"i":51,"n":"第五十一条","txt":"军队所属单位从事武器装备科研生产活动的许可管理办法另行制定。"},{"i":52,"n":"第五十二条","txt":"本办法自2010年5月10日起施行。2004年12月14日公布的《军工电子装备科研生产许可证管理办法》（中华人民共和国信息产业部令第32号）和2005年5月26日公布的《武器装备科研生产许可实施办法》（中华人民共和国国防科学技术工业委员会令第15号）同时废止。"}],"minzutongjigongzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为科学、有效、规范地组织民族统计工作，保障民族统计资料的真实性、准确性、完整性和及时性，充分发挥统计在民族工作中的重要作用，根据《中华人民共和国统计法》及其实施细则和《部门统计调查项目管理暂行办法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于各级民族工作部门单独或与其他部门联合组织实施的统计调查活动。"},{"i":3,"n":"第三条","txt":"民族统计工作的基本任务是对少数民族和民族自治地方经济社会发展情况进行统计调查，提供统计资料。"},{"i":4,"n":"第四条","txt":"民族统计工作实行统一领导、分级负责的管理体制。 国家民委是民族统计工作的主管部门，在国家统计局的业务指导下，对民族统计工作实行统一管理和组织协调。 地方各级民族工作部门在上级民族工作部门和同级人民政府统计部门的业务指导下，负责本行政区域内的民族统计工作。"},{"i":5,"n":"第五条","txt":"各级民族工作部门应当加强对民族统计工作的组织领导，确定专门负责此项工作的人员，建立工作责任机制，为统计工作提供必要的保障，定期检查并监督本办法的执行情况。"},{"i":6,"n":"第六条","txt":"加强民族统计科学研究，健全统计指标体系，提高统计的科学性与真实性。各级民族工作部门应重视统计信息化建设，为民族统计工作提供必要的技术装备和其他各项条件，推进统计信息的搜集、处理、传输和共享。"},{"i":7,"n":"第七条","txt":"各级民族工作部门应当按照有关规定如实提供有关统计资料，不得虚报、瞒报、拒报、迟报，不得伪造、篡改。对在民族统计工作中知悉的国家秘密、商业秘密和个人信息应当予以保密。"},{"i":8,"n":"第八条","txt":"各级民族工作部门应当在其内设机构中明确承担统计工作的职能，并指定统计工作负责人。"},{"i":9,"n":"第九条","txt":"国家民委统计机构履行以下职责: （一）健全统计工作制度，对全国民族统计工作进行管理、指导和监督；保障民族统计工作经费； （二）健全民族统计指标体系，制定全国少数民族和民族自治地方国民经济和社会发展统计报表制度，按程序报国家统计局审批或备案； （三）负责与国家统计局、教育部、科技部、民政部、住房城乡建设部、文化部、卫生计生委、新闻出版广电总局、体育总局等同级有关部门的统计业务合作，组织、指导、协调各级民族工作部门的统计工作； （四）搜集、整理、审核、发布全国民族统计资料； （五）统筹建设、管理民族地区经济社会运行监测系统； （六）组织或指导全国各级民族工作部门统计人员的业务培训； （七）开展全国民族地区统计分析和监测工作。"},{"i":10,"n":"第十条","txt":"地方各级民族工作部门统计机构履行以下职责: （一）完成上级民族工作部门部署的统计调查任务，审核并按时向上级民族工作部门报送本地区的民族统计数据和其他统计资料； （二）开展与本地区统计局等同级有关部门的统计业务合作，组织、指导、协调下级各民族工作部门的统计工作； （三）按照国家民委统计机构的统一部署，按要求及时填报民族地区经济社会运行监测系统； （四）组织开展本行政区域民族统计人员的业务培训。"},{"i":11,"n":"第十一条","txt":"各级民族工作部门统计机构和统计员应恪守职业道德、依法履行职责，如实搜集、录入、审核、报送统计资料，不得伪造、篡改统计资料。同时，认真审核调查对象或下级民族工作部门报送的原始资料，努力减少数据处理偏差。"},{"i":12,"n":"第十二条","txt":"各级民族工作部门要保障部门统计调查所需人力、物力和财力，合理配置统计员，不断充实统计力量。统计员队伍应保持相对稳定，因工作需要调离统计岗位时，应选派有能力承担规定责任的人员接替并做好统计工作交接，并及时告知上级民族工作部门。加强对统计人员的专业培训和职业道德教育。对不称职、不合格的统计人员及时进行调整。"},{"i":13,"n":"第十三条","txt":"统计指标的标准由国家统计局或国家统计局和国家民委共同制定，保障统计调查中采用的指标涵义、计算方法、分类目录、调查表式、统计编码等方面标准化。"},{"i":14,"n":"第十四条","txt":"各级民族工作部门向上级民族工作部门报送统计数据和其他统计材料，须经本部门主管领导审核、签署。对审核中发现的异常数据，应当逐级核实确认，并对数据中异常变动情况予以说明。"},{"i":15,"n":"第十五条","txt":"统计数据报出后，如发现内容有误，报送单位应按照国家有关规定及时进行更正并书面说明理由。"},{"i":16,"n":"第十六条","txt":"民族统计资料实行分级管理制度。全国民族统计资料由国家民委统计机构统一管理；地方各级民族统计资料由本部门统计机构统一管理。"},{"i":17,"n":"第十七条","txt":"国家民委按照法律法规和国家有关规定，管理和发布全国民族统计资料。地方各级民族工作部门按照法律法规和国家有关规定，管理和发布本行政区域民族统计资料。"},{"i":18,"n":"第十八条","txt":"尚未公布的民族统计资料，不得擅自对外提供，不得公开。属于国家秘密的统计资料，必须保密。"},{"i":19,"n":"第十九条","txt":"国家民委每年以办公厅的名义对在保障民族统计资料真实性、准确性、完整性、及时性方面作出显著成绩的统计员给予表彰。"},{"i":20,"n":"第二十条","txt":"各级民族工作部门负责人有下列行为之一的，依照《中华人民共和国统计法》第三十七条规定予以处理: （一）自行修改统计资料、编造虚假统计数据的； （二）要求统计机构、统计人员或者其他机构、人员伪造、篡改统计资料的； （三）对依法履行职责或者拒绝、抵制统计违法行为的统计人员打击报复的； （四）对本地方、本部门、本单位发生的严重统计违法行为失察的。"},{"i":21,"n":"第二十一条","txt":"各级民族工作部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依照《中华人民共和国统计法》第三十九条规定予以处理: （一）违法公布统计资料的； （二）违反国家有关规定，造成统计资料毁损、灭失的。"},{"i":22,"n":"第二十二条","txt":"各级民族工作部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依照《中华人民共和国统计法》第四十一条规定予以处理： （一）拒绝提供统计资料或者经催报后仍未按时提供统计资料的； （二）提供不真实或者不完整的统计资料的。"},{"i":23,"n":"第二十三条","txt":"本办法由国家民委负责解释。"},{"i":24,"n":"第二十四条","txt":"本办法自公布之日起施行。"}],"shuikudizhenjianceguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强和规范水库地震监测管理，提高水库地震监测能力，保障人民生命、财产安全和社会公共利益，根据《中华人民共和国防震减灾法》、《地震监测管理条例》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"水库地震监测台网的建设、运行和管理适用本办法。"},{"i":3,"n":"第三条","txt":"国务院地震工作主管部门负责全国水库地震监测的业务指导和监督管理工作。 县级以上地方人民政府负责管理地震工作的部门或者机构，负责本行政区域的水库地震监测的业务指导和监督管理工作。 水库建设单位负责水库地震监测台网的建设和运行管理。具体工作可以委托具备相关能力的单位承担。"},{"i":4,"n":"第四条","txt":"水库地震监测台网的建设资金和运行经费由水库建设单位承担。"},{"i":5,"n":"第五条","txt":"水库地震监测是我国地震监测的重要组成部分。 水库地震监测数据和资料属于国家基础科学数据，其保存和使用应当符合国家有关规定。 水库地震监测设施和地震观测环境依法受到保护。"},{"i":6,"n":"第六条","txt":"水库地震监测台网的建设，应当遵守法律、法规和国家有关标准，符合国家规定的固定资产投资项目建设程序，保证台网建设质量。"},{"i":7,"n":"第七条","txt":"外国的组织或者个人在中华人民共和国领域从事水库地震监测活动，必须经国务院地震工作主管部门会同有关部门批准，并采取与中华人民共和国有关部门或者单位合作的形式进行。 从事前款规定的活动，必须遵守中华人民共和国有关法律、法规的规定，并不得涉及国家秘密和危害国家安全。"},{"i":8,"n":"第八条","txt":"对在水库地震监测工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":9,"n":"第九条","txt":"坝高100米以上、库容5亿立方米以上的新建水库，应当建设水库地震监测台网，开展水库地震监测。 最高水位蓄水区及其外延10千米范围内有活动断层通过、遭受地震破坏后可能产生严重次生灾害的新建大型水库，应当设置必要的地震监测设施，密切监视水库地震活动。"},{"i":10,"n":"第十条","txt":"符合第九条规定的水库建设工程可行性研究报告，应当包括水库地震监测台网或者地震监测设施的内容。"},{"i":11,"n":"第十一条","txt":"符合第九条规定，未建设地震监测台网或者地震监测设施的已建水库，库区及周边地区地震活动有增强趋势的，经省、自治区、直辖市人民政府负责管理地震工作的部门或者机构评估，认为应当补充建设水库地震监测台网或者地震监测设施的，水库建设单位应当根据评估意见，补充建设水库地震监测台网或者地震监测设施，开展水库地震监测。"},{"i":12,"n":"第十二条","txt":"国务院地震工作主管部门和省、自治区、直辖市人民政府负责管理地震工作的部门或者机构，应当加强对水库地震监测台网和地震监测设施建设的指导，并为水库地震监测台网和地震监测设施的建设提供必要的基础资料和技术支持。"},{"i":13,"n":"第十三条","txt":"水库地震监测台网应当包括测震台网、强震动监测设施和数据汇集处理中心；根据需要增加地壳形变、地下流体、活动断层等监测内容。"},{"i":14,"n":"第十四条","txt":"测震台网应当至少有4个监测台站同时观测，其监测能力和定位精度应当达到：库首区和重点区域监测能力优于0.5级，定位精度优于1千米；库区及其外延10千米范围内监测能力达到1.5级, 定位精度优于3千米，2.5级以上地震速报时间不超过15分钟。"},{"i":15,"n":"第十五条","txt":"在水库地震监测台网和地震监测设施建设工程实施前，水库建设单位应当将水库地震监测台网和地震监测设施建设方案报所在地省、自治区、直辖市人民政府负责管理地震工作的部门或者机构备案，并同时抄报国务院地震工作主管部门。"},{"i":16,"n":"第十六条","txt":"水库地震监测台网和地震监测设施的建设，应当按照国务院地震工作主管部门的规定，采用符合国家标准、行业标准或者有关地震监测技术要求的设备。"},{"i":17,"n":"第十七条","txt":"水库地震监测台网和地震监测设施验收合格后，水库建设单位应当将竣工报告、验收意见，报所在地省、自治区、直辖市人民政府负责管理地震工作的部门或者机构备案，并同时抄报国务院地震工作主管部门。"},{"i":18,"n":"第十八条","txt":"水库地震监测台网和地震监测设施应当在水库蓄水一年前建成并投入运行。 水库地震监测台网和地震监测设施正式运行后，不得擅自中止或者终止。确需中止或者终止的，应当提前6个月报所在地省、自治区、直辖市人民政府负责管理地震工作的部门或者机构备案。"},{"i":19,"n":"第十九条","txt":"水库地震监测台网和地震监测设施的运行，应当符合国家有关标准和技术规范。地震监测信息的检测、传递、分析、处理、存贮、报送应当保证质量和安全。"},{"i":20,"n":"第二十条","txt":"水库地震监测台网和地震监测设施的运行管理，应当纳入所在地省级或者全国地震监测技术管理和质量检查。"},{"i":21,"n":"第二十一条","txt":"国务院地震工作主管部门和县级以上地方人民政府负责管理地震工作的部门或者机构，应当指导水库建设单位建立健全台网运行管理和技术管理制度，加强对从事水库地震监测工作人员的技术培训和业务指导。"},{"i":22,"n":"第二十二条","txt":"水库地震监测数据应当及时、完整报送所在地省、自治区、直辖市人民政府负责管理地震工作的部门或者机构。 省、自治区、直辖市人民政府负责管理地震工作的部门或者机构，负责确定水库地震监测数据的传送方式、内容和时限等，并将水库地震监测数据纳入地震科学数据共享范围。"},{"i":23,"n":"第二十三条","txt":"水库地震监测台网或者地震监测设施监测到库区有重要异常情况，水库建设单位应当立即报告所在地省、自治区、直辖市人民政府负责管理地震工作的部门或者机构。 省、自治区、直辖市人民政府负责管理地震工作的部门或者机构在接到报告后，应当会同水库建设单位及时组织调查核实和分析研究，必要时组织召开震情会商会，并将震情会商意见报本级人民政府。"},{"i":24,"n":"第二十四条","txt":"违反本办法的规定，有下列行为之一的，由国务院地震工作主管部门或者省、自治区、直辖市人民政府负责管理地震工作的部门或者机构责令改正，并要求采取相应的补救措施： （一）未按照有关法律、法规和国家有关标准进行水库地震监测台网和地震监测设施建设的； （二）未采用符合国家标准、行业标准或者有关地震监测技术要求的设备的； （三）擅自中止或者终止水库地震监测台网或者地震监测设施运行的； （四）水库地震监测台网和地震监测设施的运行不符合国家有关标准和技术规范的； （五）未按规定进行备案的； （六）未按规定报送水库地震监测数据和资料的。"},{"i":25,"n":"第二十五条","txt":"有下列违法行为之一的，按照《中华人民共和国防震减灾法》、《地震监测管理条例》的规定，追究法律责任： （一）破坏水库地震监测设施的； （二）危害水库地震观测环境的； （三）外国的组织或个人违法从事水库地震监测活动的。"},{"i":26,"n":"第二十六条","txt":"本办法自2011年5月1日起施行。"}],"xiemianjianchachubanfa":[{"i":1,"n":"第一条","txt":"为保守国家秘密，维护国家安全和利益，规范和加强保密行政管理部门泄密案件查处工作，根据《中华人民共和国保守国家秘密法》（以下简称保密法）及其实施条例等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"保密行政管理部门对公民举报、机关和单位报告、保密检查发现、有关部门移送的涉嫌泄露国家秘密的案件线索，依法调查或者组织、督促有关机关、单位调查处理，适用本办法。"},{"i":3,"n":"第三条","txt":"查处泄密案件，应当坚持教育和惩处相结合，以事实为依据，以法律为准绳，做到事实清楚，证据确实、充分，定性准确，程序合法，处理适当。"},{"i":4,"n":"第四条","txt":"本办法所称“泄露国家秘密”是指违反保密法律、法规和规章的下列行为之一： （一）使国家秘密被不应知悉者知悉的； （二）使国家秘密超出了限定的接触范围，而不能证明未被不应知悉者知悉的。"},{"i":5,"n":"第五条","txt":"存在下列情形之一的，按泄露国家秘密处理： （一）属于国家秘密的文件资料或者其他物品下落不明的，自发现之日起，绝密级10日内，机密级、秘密级60日内查无下落的； （二）未采取符合国家保密规定或者标准的保密措施，在互联网及其他公共信息网络、有线和无线通信中传递国家秘密的； （三）使用连接互联网或者其他公共信息网络的计算机、移动存储介质等信息设备存储、处理国家秘密，且该信息设备被远程控制的。"},{"i":6,"n":"第六条","txt":"泄密案件查处工作主要包括： （一）查明所泄露的国家秘密事项的内容与密级； （二）查明案件事实、主要情节和有关责任人员； （三）要求有关机关、单位采取必要的补救措施； （四）根据有关法律、法规和规章等对责任人员提出处理建议，并督促机关、单位作出处理； （五）针对案件暴露出的问题，督促机关、单位加强和改进保密工作。"},{"i":7,"n":"第七条","txt":"泄密案件查处实行分级办理、各负其责的工作制度。国家保密行政管理部门主管全国的泄密案件查处工作。地方各级保密行政管理部门在上级保密行政管理部门指导下，负责本行政区域的泄密案件查处工作。 有关机关、单位在保密行政管理部门的组织、督促、指导下，对泄密案件进行查处，并采取相应整改补救措施。"},{"i":8,"n":"第八条","txt":"上级保密行政管理部门对下级保密行政管理部门，地方保密行政管理部门对本行政区域内机关、单位泄密案件查处工作进行指导、监督。发现查处不当的，应当及时予以纠正。"},{"i":9,"n":"第九条","txt":"办案人员与案件有利害关系或者其他关系可能影响案件公正处理的，应当自行回避；案件当事人有权要求其回避。 办案人员的回避，由其所属保密行政管理部门决定。保密行政管理部门负责人的回避，由上一级保密行政管理部门决定。"},{"i":10,"n":"第十条","txt":"保密行政管理部门及其办案人员对案件查处工作中获取的国家秘密、工作秘密、商业秘密及个人隐私，应当保密。"},{"i":11,"n":"第十一条","txt":"泄密案件由泄密行为发生地县级以上保密行政管理部门管辖。由有关机关、单位所在地或者案件当事人居住地保密行政管理部门管辖更便于查处工作开展的，可以由有关机关、单位所在地或者案件当事人居住地保密行政管理部门管辖。 移交有关机关、单位所在地或者案件当事人居住地保密行政管理部门管辖的泄密案件，泄密行为发生地保密行政管理部门在移交前应当及时收集证据，并配合开展调查取证工作。"},{"i":12,"n":"第十二条","txt":"国家保密行政管理部门依法调查或者组织、督促查处下列泄密案件: （一）中央和国家机关发生的； （二）涉及多个省（自治区、直辖市）的； （三）全国范围内重大、复杂案件。"},{"i":13,"n":"第十三条","txt":"省（自治区、直辖市）保密行政管理部门依法调查或者组织、督促查处下列泄密案件： （一）省级机关及省（自治区、直辖市）直属机关发生的； （二）涉及本行政区域内多个市（地、州、盟）或者部门的； （三）中央和国家机关设在省（自治区、直辖市）的直属机构发生的； （四）本辖区内重大、复杂案件。"},{"i":14,"n":"第十四条","txt":"中央和国家机关认为本系统发生泄密案件的有关单位情况特殊，不宜由地方保密行政管理部门查处的，可以向国家保密行政管理部门提交书面材料说明理由，由国家保密行政管理部门决定。"},{"i":15,"n":"第十五条","txt":"对于重大、复杂的泄密案件，上级保密行政管理部门可以指定管辖；具有管辖权的保密行政管理部门由于特殊原因不能调查或者组织、督促查处的，可以报请上一级保密行政管理部门指定管辖；同级保密行政管理部门之间因管辖权发生争议的，应当本着有利于开展查处工作的原则协商解决，必要时报请共同的上级保密行政管理部门指定管辖。 上级保密行政管理部门应当在接到指定管辖申请之日起7个工作日内，作出指定管辖决定，并书面通知被指定管辖的保密行政管理部门和其他有关保密行政管理部门。原受理案件的保密行政管理部门收到上级保密行政管理部门书面通知后，应当立即将案卷材料移送被指定管辖的保密行政管理部门，并书面通知有关机关、单位。"},{"i":16,"n":"第十六条","txt":"保密行政管理部门发现案件不属于本部门管辖的，应当自发现之日起7个工作日内移送具有管辖权的保密行政管理部门或者其他部门。 接受移送的保密行政管理部门对管辖权有异议的，应当报请上一级保密行政管理部门指定管辖，不得再自行移送。"},{"i":17,"n":"第十七条","txt":"可以用于证明案件事实的材料，都是证据。证据包括： （一）物证； （二）书证； （三）证人证言； （四）案件当事人陈述； （五）视听资料、电子数据； （六）保密检查、勘验笔录，技术核查报告； （七）密级鉴定书。"},{"i":18,"n":"第十八条","txt":"保密行政管理部门在案件调查过程中，应当合法、及时、客观、全面地收集、调取证据材料，并予以审查、核实。"},{"i":19,"n":"第十九条","txt":"收集、调取的物证应当是原物。在原物不便搬运、不易保存，依法应当由有关机关、单位保管、处理或者依法应当返还时，可以拍摄或者制作足以反映原物外形或者内容的照片、录像。物证的照片、录像，经与原物核实无误或者经鉴定证明为真实的，可以作为证据使用。"},{"i":20,"n":"第二十条","txt":"收集、调取的书证应当是原件。在取得原件确有困难时，可以使用副本或者复制件。 书证的副本、复制件，经与原件核实无误的，可以作为证据使用。书证有更改或者更改迹象不能作出合理解释的，或者书证的副本、复制件不能反映书证原件及其内容的，不能作为证据使用。"},{"i":21,"n":"第二十一条","txt":"办案人员应当收集电子数据的原始载体。收集原始载体确有困难时，可以拷贝复制或者进行镜像备份。"},{"i":22,"n":"第二十二条","txt":"书证的副本、复制件，视听资料、电子数据的复制件，物证的照片、录像，应当附原件、原物存放处的文字说明。"},{"i":23,"n":"第二十三条","txt":"保密行政管理部门对公民举报、机关和单位报告、保密检查发现、有关部门移送的涉嫌泄露国家秘密的案件线索，应当依法及时受理。"},{"i":24,"n":"第二十四条","txt":"保密行政管理部门受理涉嫌泄露国家秘密的案件线索举报，举报人不愿意公开个人或者单位信息的，应当在受理登记时注明，并为其保密。 保密行政管理部门应当对举报人提供的有关证据材料、物品等进行登记，出具接收清单，并妥善保管；必要时，可以拍照、录音或者录像。"},{"i":25,"n":"第二十五条","txt":"保密行政管理部门受理涉嫌泄露国家秘密的案件线索，应当分别作出处理： （一）已经或者可能泄露国家秘密的，应当进行初查； （二）经核实，存在违反保密法律法规行为，但情节显著轻微，没有造成危害后果的，可以责成有关机关、单位对责任人员进行批评教育； （三）没有泄密事实或者案件线索无法核实的，不予处理。"},{"i":26,"n":"第二十六条","txt":"保密行政管理部门受理涉嫌泄露国家秘密的案件线索，发现需要采取补救措施的，应当立即责令有关机关、单位和人员停止违法行为，采取有效措施，防止泄密范围扩大。"},{"i":27,"n":"第二十七条","txt":"保密行政管理部门在决定是否立案前，应当对涉嫌泄露国家秘密的案件线索进行初查，了解是否存在泄密事实。初查内容包括： （一）案件线索涉及人员的主体身份及基本情况； （二）案件线索所反映的问题是否属实，是否造成国家秘密泄露，是否达到刑事立案标准。"},{"i":28,"n":"第二十八条","txt":"初查结束后，应当形成初查情况报告，内容包括案件线索情况、初查情况和处理建议。"},{"i":29,"n":"第二十九条","txt":"保密行政管理部门应当根据初查情况分别作出处理： （一）确有泄露国家秘密事实，且已经达到刑事立案标准的，应当移送有关部门查处； （二）确有泄露国家秘密事实，尚未达到刑事立案标准，且具有管辖权的，应当予以立案，不具有管辖权的，应当移交具有管辖权的保密行政管理部门处理； （三）确有泄露国家秘密事实，但案件线索内容不全或者有误，通知案件线索移送部门或者举报人、报告人补充，经补充案件线索内容仍不具备查处条件的，暂不予以立案，有关材料存档备查； （四）未造成国家秘密泄露，但存在违反保密法律法规事实的，应当督促、指导有关机关、单位进行调查处理，必要时保密行政管理部门可以直接调查； （五）未违反保密法律法规，但存在其他涉嫌违法或者违纪事实的，移交有关职能部门处理； （六）案件线索反映的情况失实的，不予处理，必要时可以向有关机关、单位和案件当事人说明情况。"},{"i":30,"n":"第三十条","txt":"初查时限为2个月，必要时可以延长1个月。重大、复杂的案件线索，在延长期内仍不能初查完毕的，经保密行政管理部门负责人批准后可以延长。 初查时限自接到案件线索之日算起，至呈报初查情况报告之日止。"},{"i":31,"n":"第三十一条","txt":"经初查应当予以立案的，办案人员应当填报立案表，并附案件线索材料、初查情况报告，报请保密行政管理部门负责人审批。"},{"i":32,"n":"第三十二条","txt":"保密行政管理部门在立案后，应当制作立案通知书，通知有关机关、单位；通知立案可能影响案件查处工作的，可以直接通知其上级主管部门。"},{"i":33,"n":"第三十三条","txt":"案件立案后，保密行政管理部门应当指派2名以上办案人员进行调查或者指导、督促有关机关、单位进行调查。 对于重大、复杂案件，保密行政管理部门可以组织相关部门成立专案组，开展案件调查。"},{"i":34,"n":"第三十四条","txt":"案件调查内容包括： （一）案件当事人的基本情况； （二）案件当事人是否实施违反保密法律法规行为； （三）实施违反保密法律法规行为的时间、地点、手段、后果以及其他情节； （四）有无法定从重、从轻、减轻或者免予处理的情形； （五）与案件有关的其他事实。"},{"i":35,"n":"第三十五条","txt":"保密行政管理部门直接调查、检查时，办案人员不得少于2人，并应当出示证件，表明身份。"},{"i":36,"n":"第三十六条","txt":"机关、单位应当积极配合案件调查工作，提供相关证据。 机关、单位应当对案件当事人出国（境）进行审查，可能影响案件查处的，不得批准其出国（境）。"},{"i":37,"n":"第三十七条","txt":"案件当事人应当自觉接受、配合调查，如实说明情况；不得与同案人或者知情人串通情况，不得对抗调查；不得将案件查处情况告知他人。"},{"i":38,"n":"第三十八条","txt":"办案人员在案件调查过程中可以询问案件当事人、证人或者其他案件关系人，并制作询问笔录。询问应当个别进行。"},{"i":39,"n":"第三十九条","txt":"询问内容应当包括： （一）被询问人的基本情况； （二）被询问人与案件当事人或者与案件的联系； （三）证明案件当事人是否负有责任以及责任轻重的事实； （四）所证明的事实发生的原因、时间、地点、手段、情节等； （五）其他与案件有关的内容。"},{"i":40,"n":"第四十条","txt":"询问笔录应当采取问答式，如实对办案人员的提问和被询问人的回答进行记录。记录被询问人的陈述应当详细具体，忠于原意。对于被询问人声明记忆不清的情节，笔录中应当如实反映。 询问笔录应当交被询问人核对，对没有阅读能力的，应当向其宣读。记录有误或者遗漏的，应当允许被询问人更正或者补充。被询问人确认笔录无误后，应当在询问笔录上逐页签名。拒绝签名的，询问人员应当在询问笔录中注明。 询问时，可以全程录音、录像，并保持录音、录像资料的完整性。"},{"i":41,"n":"第四十一条","txt":"案件当事人、证人或者其他案件关系人请求自行提供书面材料的，应当准许。必要时，办案人员也可以要求案件当事人、证人或者其他案件关系人自行书写。 案件当事人、证人或者其他案件关系人应当在其提供的书面材料结尾处签名。打印的书面材料应当逐页签名。办案人员收到书面材料后，应当在首页注明收到日期，并签名。"},{"i":42,"n":"第四十二条","txt":"询问案件当事人时，办案人员应当听取案件当事人的陈述和申辩。对其陈述和申辩，应当进行核查。"},{"i":43,"n":"第四十三条","txt":"办案人员在案件调查过程中可以查阅、复制与案件有关的文件资料、会议记录、工作笔记等材料，查阅、了解案件当事人的身份信息、现实表现情况等信息，有关机关、单位和个人应当予以配合。"},{"i":44,"n":"第四十四条","txt":"办案人员在案件调查过程中可以对与泄密案件有关的场所、物品进行检查。检查时，被检查人或者见证人应当在场。 办案人员可以根据检查情况制作检查笔录。检查笔录由办案人员、被检查人或者见证人签名；被检查人或者见证人不在场、拒绝签名的，办案人员应当在检查笔录中注明。"},{"i":45,"n":"第四十五条","txt":"在案件调查过程中对国家秘密载体或者相关设施、设备、文件资料等登记保存，依照《中华人民共和国行政强制法》相关规定进行。办案人员应当会同持有人或者见证人查点清楚，当场开列登记保存清单一式二份，写明登记保存对象的名称、规格、数量、特征、登记保存地点等，由办案人员和持有人或者见证人签名后，各执一份。 对于登记保存在有关机关、单位的设施、设备，应当采取足以防止有关证据灭失或者转移的措施。"},{"i":46,"n":"第四十六条","txt":"对涉及计算机、移动存储介质等信息设备的泄密案件，保密行政管理部门可以组织或者委托具有技术核查取证职能的部门或者单位进行技术核查取证。"},{"i":47,"n":"第四十七条","txt":"案件调查过程中，需要对有关事项是否属于国家秘密以及属于何种密级进行鉴定的，应当及时提请具有密级鉴定权的保密行政管理部门鉴定。"},{"i":48,"n":"第四十八条","txt":"案件调查过程中，保密行政管理部门发现有关机关、单位存在泄密隐患的，应当立即要求其采取措施，限期整改；对存在泄密隐患的设施、设备、场所，依法责令停止使用。"},{"i":49,"n":"第四十九条","txt":"经调查，证据不足无法认定存在泄密事实的，经保密行政管理部门负责人批准，应当作出撤销案件的决定。撤销案件的决定应当及时书面通知有关机关、单位。"},{"i":50,"n":"第五十条","txt":"经调查，保密行政管理部门认为案件当事人实施的违反保密法律法规行为涉嫌构成犯罪的，应当连同案件材料及时移送有关部门查处。"},{"i":51,"n":"第五十一条","txt":"调查结束后，保密行政管理部门认为存在泄密事实，需要追究责任的，应当向有关机关、单位提出人员处理建议。有关机关、单位应当及时将处理结果书面告知同级保密行政管理部门。 有关机关、单位对责任人员不依法给予处分的，保密行政管理部门应当依法建议纠正。对拒不纠正的，保密行政管理部门应当依法提请其上一级机关或者监察机关对该机关、单位负有责任的领导人员和直接责任人员依法予以处理。"},{"i":52,"n":"第五十二条","txt":"保密行政管理部门应当针对案件暴露出的问题，督促有关机关、单位采取整改措施，加强和改进保密工作。 机关、单位应当在规定时限内将整改情况书面报送保密行政管理部门。保密行政管理部门可以对机关、单位的整改情况进行复查。"},{"i":53,"n":"第五十三条","txt":"泄密案件调查终结应当具备下列条件： （一）泄露国家秘密的事实已经调查清楚； （二）已经采取必要的补救措施； （三）已经对案件相关责任人员作出处理，或者移送有关部门查处； （四）有关机关、单位已经采取整改措施。"},{"i":54,"n":"第五十四条","txt":"办案人员在案件调查处理工作完成后，应当提交结案报告，经立案的保密行政管理部门负责人批准后结案。结案报告应当包括以下内容： （一）泄密案件的发生、发现经过； （二）案件涉及国家秘密的密级、数量、载体形式以及概要内容； （三）泄密案件已经或者可能造成的危害； （四）案件发生的主要原因； （五）已经采取的补救措施； （六）责任人员处理情况； （七）有关机关、单位整改情况； （八）其他需要说明的情况。"},{"i":55,"n":"第五十五条","txt":"泄密案件查处时限为3个月，自立案之日起3个月未能查结的，经查处泄密案件的保密行政管理部门负责人批准可延长1个月。 在延长期内仍不能查结的，查处泄密案件的保密行政管理部门应当向上一级保密行政管理部门说明原因，逾期未说明原因或者理由不充分的，上一级保密行政管理部门应当予以检查、督促。"},{"i":56,"n":"第五十六条","txt":"省（自治区、直辖市）保密行政管理部门与中央和国家机关保密工作机构在泄密案件查处工作中应当相互配合。 设区的市、自治州一级及以下地方保密行政管理部门需要中央和国家机关保密工作机构配合工作的，应当报请所属省（自治区、直辖市）保密行政管理部门协调。"},{"i":57,"n":"第五十七条","txt":"保密行政管理部门应当加强与同级纪检监察、网信、审判、检察、公安、国家安全等机关的协调配合，建立健全协调配合机制，共同做好泄密案件查处工作。"},{"i":58,"n":"第五十八条","txt":"在泄密案件查处工作中需要军地双方配合的，军队相应保密工作部门和地方保密行政管理部门可以直接联系，相互之间应当支持配合。"},{"i":59,"n":"第五十九条","txt":"在泄密案件查处工作中，有关机关、单位及其工作人员拒不配合，弄虚作假，隐匿、销毁证据，以其他方式逃避、妨碍案件查处的，对直接负责的主管人员和其他直接责任人员依法给予处分。 企事业单位及其工作人员协助机关、单位逃避、妨碍案件查处的，由有关主管部门依法予以处罚。"},{"i":60,"n":"第六十条","txt":"保密行政管理部门办理泄密案件，未依法履行职责，或者滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"机关、单位工作人员实施保密法第四十八条规定的其他违法行为，保密行政管理部门可以参照本办法调查或者组织、督促机关、单位调查处理。"},{"i":62,"n":"第六十二条","txt":"执行本办法所需要的文书式样，由国家保密行政管理部门统一制定。国家保密行政管理部门没有制定式样，执法工作中需要的其他文书，省（自治区、直辖市）保密行政管理部门可以自行制定式样。"},{"i":63,"n":"第六十三条","txt":"本办法由国家保密局负责解释。"},{"i":64,"n":"第六十四条","txt":"本办法自2018年1月1日起施行。国家保密局1992年11月20日印发的《泄密事件查处办法（试行）》同时废止。"}],"paishengguojiamimidingmiguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范派生国家秘密定密（以下简称派生定密）管理，根据《中华人民共和国保守国家秘密法》及其实施条例，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于国家机关和涉及国家秘密的单位（以下简称机关、单位）开展派生定密的工作。"},{"i":3,"n":"第三条","txt":"本办法所称派生定密，是指机关、单位对执行或者办理已定密事项所产生的国家秘密，依法确定、变更和解除的活动。"},{"i":4,"n":"第四条","txt":"本办法所称保密要点（以下简称密点），是指决定一个事项具备国家秘密本质属性的关键内容，可以与非国家秘密以及其他密点明确区分。"},{"i":5,"n":"第五条","txt":"机关、单位开展派生定密，不受定密权限限制。无法定定密权的机关、单位可以因执行或者办理已定密事项，派生国家秘密。具有较低定密权的机关、单位可以因执行或者办理较高密级的已定密事项，派生超出本机关、单位定密权限的国家秘密。"},{"i":6,"n":"第六条","txt":"机关、单位负责人及其指定的人员为本机关、本单位的派生定密责任人，履行派生国家秘密确定、变更和解除的责任。"},{"i":7,"n":"第七条","txt":"机关、单位因执行或者办理已定密事项而产生的事项（以下简称派生事项），符合下列情形之一的，应当确定为国家秘密： （一）与已定密事项完全一致的； （二）涉及已定密事项密点的； （三）是对已定密事项进行概括总结、编辑整合、具体细化的； （四）原定密机关、单位对使用已定密事项有明确定密要求的。"},{"i":8,"n":"第八条","txt":"派生国家秘密的密级应当与已定密事项密级保持一致。已定密事项明确密点及其密级的，应当与所涉及密点的最高密级保持一致。"},{"i":9,"n":"第九条","txt":"派生国家秘密的保密期限应当按照已定密事项的保密期限确定，或者与所涉及密点的最长保密期限保持一致。已定密事项未明确保密期限的，可以征求原定密机关、单位意见后确定并作出标注，或者按照保密法规定的最长保密期限执行。"},{"i":10,"n":"第十条","txt":"派生国家秘密的知悉范围，应当根据工作需要确定，经本机关、本单位负责人批准。能够限定到具体人员的，限定到具体人员。 原定密机关、单位有明确规定的，应当遵守其规定。"},{"i":11,"n":"第十一条","txt":"派生国家秘密的确定应当按照国家秘密确定的法定程序进行。承办人依据已定密事项或者密点，拟定密级、保密期限和知悉范围，报定密责任人审核。定密责任人对承办人意见进行审核，作出决定。 派生定密应当作出书面记录，注明承办人、定密责任人和定密依据。定密依据应当写明依据的文件名称、文号、密级、保密期限等。"},{"i":12,"n":"第十二条","txt":"机关、单位所执行或者办理的已定密事项没有变更或者解密的，派生国家秘密不得变更或者解密；所执行或者办理的已定密事项已经变更或者解密的，派生国家秘密的密级、保密期限、知悉范围应当及时作出相应变更或者予以解密。 机关、单位认为所执行或者办理的已定密事项需要变更或者解密的，可以向原定密机关、单位或者其上级机关、单位提出建议。未经有关机关、单位同意，派生国家秘密不得擅自变更或者解密。"},{"i":13,"n":"第十三条","txt":"派生国家秘密的变更、解除程序应当履行国家秘密变更或者解除的法定程序。承办人依据已定密事项或者密点的变更、解除情况，提出派生国家秘密变更或者解除意见，报定密责任人审核批准，并作出书面记录。 书面记录应当注明承办人、定密责任人、已定密事项或者密点的变更或者解除情况，以及解密后作为工作秘密管理或者予以公开等。"},{"i":14,"n":"第十四条","txt":"派生事项不是对已定密事项内容或者密点进行概括总结、编辑整合、具体细化的，不应当派生定密。该事项是否需要定密，应当依照保密法律法规和国家秘密及其密级具体范围（以下简称保密事项范围）判断。"},{"i":15,"n":"第十五条","txt":"派生事项既包括已定密事项内容或者密点，也包括有关行业、领域保密事项范围规定事项的，应当同时依据已定密事项和有关保密事项范围进行定密。密级、保密期限应当按照已定密事项和保密事项范围规定事项的最高密级、最长保密期限确定。知悉范围根据工作需要限定到最小范围。"},{"i":16,"n":"第十六条","txt":"原定密机关、单位应当准确确定并规范标注国家秘密的密级、保密期限和知悉范围。对涉密国家科学技术、涉密科研项目、涉密工程、涉密政府采购以及其他可以明确密点的，应当确定密点并作出标注；不能明确标注的，可以附件、附注等形式作出说明。对无法明确密点的，可以编制涉密版和非涉密版，或者对执行、办理环节是否涉及国家秘密、工作秘密等提出明确要求。 原定密机关、单位发现其他机关、单位执行或者办理本机关、本单位已定密事项存在派生定密不当情形的，应当及时要求纠正或者建议纠正，必要时提起保密行政管理部门通知纠正或者责令整改。"},{"i":17,"n":"第十七条","txt":"机关、单位对已定密事项是否已变更或者解除以及派生事项是否涉及密点等情况不明确的，可以向原定密机关、单位请示或者函询，原定密机关、单位应当及时予以答复。"},{"i":18,"n":"第十八条","txt":"机关、单位应当依法履行派生定密主体责任，加强对本机关、本单位派生定密的监督管理，发现存在派生定密不当情形的，应当及时纠正。"},{"i":19,"n":"第十九条","txt":"上级机关、单位应当加强对下级机关、单位派生定密的指导和监督，发现下级机关、单位派生定密不当的，应当及时通知其纠正，也可以直接纠正。"},{"i":20,"n":"第二十条","txt":"各级保密行政管理部门应当依法对机关、单位派生定密进行指导、监督和检查，对发现的问题及时通知纠正或者责令整改。"},{"i":21,"n":"第二十一条","txt":"机关、单位发现定密责任人和承办人定密不当，有下列情形之一的，应当及时纠正并进行批评教育；造成严重后果的，依规依纪依法给予处分： （一）派生事项应当确定国家秘密而未确定的； （二）派生事项不应当确定国家秘密而确定的； （三）未按照法定程序派生定密的； （四）未按规定标注派生国家秘密标志的； （五）未按规定变更派生国家秘密的密级、保密期限、知悉范围的； （六）派生国家秘密不应当解除而解除的； （七）派生国家秘密应当解除而未解除的； （八）违反本办法的其他情形。"},{"i":22,"n":"第二十二条","txt":"本办法由国家保密局负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自2023年4月1日起施行。"}],"shewaidiaochaguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对涉外调查的规范和管理，维护国家安全和社会公共利益，保障调查机构和调查对象的合法权益，根据《中华人民共和国统计法》及其实施细则，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称涉外调查，包括： （一）受境外组织、个人或者境外组织在华机构委托、资助进行的市场调查和社会调查； （二）与境外组织、个人或者境外组织在华机构合作进行的市场调查和社会调查； （三）境外组织在华机构依法进行的市场调查； （四）将调查资料、调查结果提供给境外组织、个人或者境外组织在华机构的市场调查和社会调查。"},{"i":3,"n":"第三条","txt":"本办法所称市场调查，是指收集整理有关商品和商业服务在市场中的表现和前景信息的活动。 本办法所称社会调查，是指市场调查之外，以问卷、访谈、观察或者其他方式，收集、整理和分析有关社会信息的活动。 本办法所称境外，是指中华人民共和国关境外；境内，是指中华人民共和国关境内。 本办法所称境外组织在华机构，是指经我国政府批准，境外组织在境内设立的分支机构和常驻代表机构。 本办法所称涉外调查机构，是指依法取得涉外调查许可证的机构。"},{"i":4,"n":"第四条","txt":"国家统计局会同国务院有关部门负责对全国的涉外调查实施监督管理。县级以上地方各级人民政府统计机构会同同级人民政府有关部门负责对本行政区域内的涉外调查实施监督管理。"},{"i":5,"n":"第五条","txt":"国家统计局和省级人民政府统计机构及其工作人员对在涉外调查管理中知悉的商业秘密，负有保密义务。"},{"i":6,"n":"第六条","txt":"从事涉外调查，必须遵守我国法律、法规、规章和国家有关规定。"},{"i":7,"n":"第七条","txt":"任何组织、个人不得进行可能导致下列后果的涉外调查： （一）违背宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）窃取、刺探、收买、泄露国家秘密或者情报，危害国家安全、损害国家利益的； （四）违反国家宗教政策，破坏民族团结的； （五）扰乱社会经济秩序，破坏社会稳定，损害社会公共利益的； （六）宣传邪教、迷信的； （七）进行欺诈活动，侵害他人合法权益的； （八）法律、法规、规章和国家有关规定认定的其他情形。"},{"i":8,"n":"第八条","txt":"国家实行涉外调查机构资格认定制度和涉外社会调查项目审批制度。"},{"i":9,"n":"第九条","txt":"涉外市场调查必须通过涉外调查机构进行，涉外社会调查必须通过涉外调查机构报经批准后进行。 境外组织和个人不得在境内直接进行市场调查和社会调查，不得通过未取得涉外调查许可证的机构进行市场调查和社会调查。"},{"i":10,"n":"第十条","txt":"国家统计局和省、自治区、直辖市人民政府统计机构负责对申请涉外调查许可证的机构进行资格认定。 任何个人和未取得涉外调查许可证的组织，不得以任何形式进行涉外调查。"},{"i":11,"n":"第十一条","txt":"申请涉外调查许可证的机构，应当具备下列条件： （一）依法成立，具有法人资格； （二）经营范围或业务范围包含市场调查或者社会调查内容； （三）具有熟悉国家有关涉外调查管理规定的人员； （四）具备与所从事涉外调查相适应的调查能力； （五）在申请之日前一年内开展三项以上调查项目，或者调查营业额达到三十万元； （六）有严格、健全的资料保密制度； （七）在最近两年内无重大违法记录。"},{"i":12,"n":"第十二条","txt":"业务范围中含有市场调查内容的境外组织在华机构，具备第十一条第（三）、（六）、（七）项条件的，可以申请涉外调查许可证，在境内直接进行与本机构有关的商品或者商业服务的市场调查；但是，不得从事社会调查。"},{"i":13,"n":"第十三条","txt":"申请涉外调查许可证，应当提交下列文件： （一）涉外调查许可证申请表； （二）用以证明第十一条或者第十二条所列内容的其他材料。"},{"i":14,"n":"第十四条","txt":"申请涉外调查许可证的机构，调查范围跨省、自治区、直辖市行政区域的，向国家统计局提出；调查范围限于省、自治区、直辖市行政区域内的，向所在省、自治区、直辖市人民政府统计机构提出。 国家统计局或者省、自治区、直辖市人民政府统计机构应当自受理之日起二十日内，作出批准或者不批准的决定。逾期不能作出决定的，经本行政机关负责人批准，可以延长十日，并将延长期限的理由告知申请人。决定批准的，颁发涉外调查许可证；决定不批准的，应当书面通知申请人，并说明理由。"},{"i":15,"n":"第十五条","txt":"国家统计局颁发的涉外调查许可证，在全国范围内有效。省、自治区、直辖市人民政府统计机构颁发的涉外调查许可证，在本行政区域内有效。"},{"i":16,"n":"第十六条","txt":"涉外调查许可证应当注明调查机构的名称、登记类型、法定代表人或者主要负责人、住所和颁发机关、颁发日期、编号、许可范围、有效期等项内容。"},{"i":17,"n":"第十七条","txt":"涉外调查机构的名称、登记类型、法定代表人或者主要负责人、住所等发生变更的，应当向原颁发机关申请变更涉外调查许可证。"},{"i":18,"n":"第十八条","txt":"涉外调查许可证的有效期为三年。 涉外调查机构需要延续涉外调查许可证有效期的，应当在有效期届满三十日前向原颁发机关提出申请。逾期未提出的，将不再延续涉外调查许可证的有效期。"},{"i":19,"n":"第十九条","txt":"终止涉外调查业务的，应当在终止业务后三十日内，向原颁发机关缴回涉外调查许可证。 涉外调查许可证有效期届满的，应当在届满后三十日内，向原颁发机关缴回已过期的涉外调查许可证。"},{"i":20,"n":"第二十条","txt":"任何组织、个人不得伪造、冒用或者转让涉外调查许可证。"},{"i":21,"n":"第二十一条","txt":"国家统计局和省、自治区、直辖市人民政府统计机构负责对涉外社会调查项目的审批。"},{"i":22,"n":"第二十二条","txt":"涉外调查机构申请批准涉外社会调查项目时，应提交下列文件： （一）涉外社会调查项目申请表； （二）涉外调查许可证复印件； （三）委托、资助、合作的合同复印件； （四）调查方案，包括调查的目的、内容、范围、时间、对象、方式等； （五）调查问卷、表格或者访谈、观察提纲； （六）与调查项目有关的其他背景材料。"},{"i":23,"n":"第二十三条","txt":"涉外调查机构申请批准涉外社会调查项目，调查范围跨省、自治区、直辖市行政区域的，向国家统计局提出；调查范围限于省、自治区、直辖市行政区域内的，向所在省、自治区、直辖市人民政府统计机构提出。 国家统计局或者省、自治区、直辖市人民政府统计机构应当自受理之日起二十日内，作出批准或者不批准的决定。逾期不能作出决定的，经本行政机关负责人批准，可以延长十日，并将延长期限的理由告知申请人。决定批准的，发给涉外社会调查项目批准文件；决定不批准的，应当书面通知申请人，并说明理由。"},{"i":24,"n":"第二十四条","txt":"经批准的涉外社会调查项目，不得擅自变更；需要变更的，涉外调查机构应当就变更部分向原批准机关提出申请。 审批机关应当依据第二十三条第二款的规定作出批准或者不批准变更的决定。"},{"i":25,"n":"第二十五条","txt":"涉外调查应当遵循自愿的原则，调查对象有权自主决定是否接受调查，任何组织和个人不得强迫调查对象接受调查。 涉外调查机构进行涉外调查时，应当向调查对象说明调查目的，不得冒用其他机构的名义，不得进行误导。"},{"i":26,"n":"第二十六条","txt":"经批准进行的涉外社会调查，应当在调查问卷、表格或者访谈、观察提纲首页显著位置标明并向调查对象说明下列事项： 涉外调查许可证编号； 调查项目的批准机关、批准文号； 本调查为调查对象自愿接受的调查。"},{"i":27,"n":"第二十七条","txt":"涉外调查机构应当建立涉外调查业务档案。"},{"i":28,"n":"第二十八条","txt":"任何组织、个人不得伪造、冒用或者转让涉外社会调查项目批准文件。"},{"i":29,"n":"第二十九条","txt":"涉外调查机构和有关人员对在涉外调查中知悉的商业秘密和个人隐私，负有保密义务。"},{"i":30,"n":"第三十条","txt":"违反本办法第七条规定的，依照《中华人民共和国统计法实施细则》第三十四条的规定予以处罚。"},{"i":31,"n":"第三十一条","txt":"违反本办法规定，有下列情形之一的，由国家统计局或者省级人民政府统计机构责令改正。其调查活动属于非经营性的，可处以五百元至一千元的罚款；其调查活动属于经营性，有违法所得的，可处以相当于违法所得一至三倍但是不超过三万元的罚款；没有违法所得的，可处以三千元至一万元的罚款。构成犯罪的，依法追究刑事责任： （一）未通过取得涉外调查许可证的机构进行涉外调查的； （二）未取得涉外调查许可证进行涉外调查的； （三）伪造、冒用、转让涉外调查许可证、涉外社会调查项目批准文件的； （四）使用已超过有效期的涉外调查许可证从事涉外调查的； （五）超出许可范围从事涉外调查的。"},{"i":32,"n":"第三十二条","txt":"涉外调查机构和有关人员违反本办法规定，有下列情形之一的，由国家统计局或者省级人民政府统计机构责令改正。其调查活动属于非经营性的，可处以五百元至一千元的罚款。其调查活动属于经营性，有违法所得的，可处以相当于违法所得一至三倍但是不超过三万元的罚款；没有违法所得的，可处以三千元至一万元的罚款。构成犯罪的，依法追究刑事责任： （一）未经批准，擅自进行涉外社会调查的； （二）未经批准，擅自变更已批准的涉外社会调查项目的； （三）泄露调查对象商业秘密和个人隐私的； （四）强迫调查对象接受调查的； （五）冒用其他机构名义进行涉外调查的； （六）未建立涉外调查业务档案的； （七）拒绝接受管理机关检查的； （八）在接受管理机关检查时，拒绝提供情况和有关材料、提供虚假情况和材料的； （九）未标明、未向调查对象说明第二十六条规定事项的。"},{"i":33,"n":"第三十三条","txt":"涉外调查机构违反本办法规定，有下列情形之一的，由国家统计局或者省级人民政府统计机构责令改正，给予警告，可处以五百元至一千元的罚款： （一）涉外调查机构的名称、登记类型、法定代表人或者主要负责人、住所等发生变更，未依法申请变更涉外调查许可证的； （二）终止涉外调查业务，或者涉外调查许可证有效期届满后，未向原颁发机关缴回涉外调查许可证的。"},{"i":34,"n":"第三十四条","txt":"统计机构工作人员在涉外调查管理中玩忽职守、滥用职权的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"国家统计局和省级人民政府统计机构工作人员泄露在涉外调查管理中知悉的商业秘密，依法承担民事责任，并对负有直接责任的主管人员和其他直接责任人员依法给予行政处分。"},{"i":36,"n":"第三十六条","txt":"我国政府与外国政府及国际组织之间的合作项目中涉及的调查，依据国家有关规定执行。"},{"i":37,"n":"第三十七条","txt":"本办法规定的实施行政许可的期限以工作日计算，不含法定节假日。"},{"i":38,"n":"第三十八条","txt":"本办法自公布之日起施行。1999年7月16日国家统计局公布的《涉外社会调查活动管理暂行办法》同时废止。"}],"shemixinxixitongjichengzizhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强涉密信息系统集成资质管理，确保国家秘密安全，根据《中华人民共和国保守国家秘密法》、《中华人民共和国行政许可法》、《中华人民共和国行政处罚法》、《中华人民共和国保守国家秘密法实施条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称涉密信息系统集成（以下简称涉密集成），是指涉密信息系统的规划、设计、建设、监理和运行维护等活动。 涉密集成资质是指保密行政管理部门许可企业事业单位从事涉密信息系统集成业务的法定资格。"},{"i":3,"n":"第三条","txt":"涉密集成资质的申请、受理、审查、决定、使用和监督管理，适用本办法。"},{"i":4,"n":"第四条","txt":"从事涉密集成业务的企业事业单位应当依照本办法，取得涉密集成资质。 国家机关和涉及国家秘密的单位（以下简称机关、单位）应当选择具有涉密集成资质的单位（以下简称资质单位）承接涉密集成业务。"},{"i":5,"n":"第五条","txt":"涉密集成资质管理应当遵循依法管理、安全保密、科学发展、公平公正的原则。"},{"i":6,"n":"第六条","txt":"国家保密行政管理部门主管全国涉密集成资质管理工作，省级保密行政管理部门主管本行政区域内涉密集成资质管理工作。 省级以上保密行政管理部门根据工作需要，可以委托下一级保密行政管理部门开展审查工作，或者组织机构协助开展工作。"},{"i":7,"n":"第七条","txt":"省级以上保密行政管理部门应当指定专门机构承担保密资质管理日常工作。"},{"i":8,"n":"第八条","txt":"省级以上保密行政管理部门建立保密资质审查专家库，组织开展入库审查、培训考核等工作。"},{"i":9,"n":"第九条","txt":"实施涉密集成资质许可不收取任何费用，所需经费纳入同级财政预算。"},{"i":10,"n":"第十条","txt":"涉密集成资质分为甲级和乙级两个等级。 甲级资质单位可以从事绝密级、机密级和秘密级涉密集成业务；乙级资质单位可以从事机密级、秘密级涉密集成业务。"},{"i":11,"n":"第十一条","txt":"涉密集成资质包括总体集成、系统咨询、软件开发、安防监控、屏蔽室建设、运行维护、数据恢复、工程监理，以及国家保密行政管理部门许可的其他涉密集成业务。取得总体集成业务种类许可的，除从事系统集成业务外，还可从事软件开发、安防监控和所承建系统的运行维护业务。 资质单位应当在保密行政管理部门许可的业务种类范围内承接涉密集成业务。承接涉密系统咨询、工程监理业务的，不得承接所咨询、监理业务的其他涉密集成业务。"},{"i":12,"n":"第十二条","txt":"申请单位应当具备以下基本条件： （一）在中华人民共和国境内依法成立三年以上的法人； （二）无犯罪记录且近三年内未被吊销保密资质（资格），法定代表人、主要负责人、实际控制人未被列入失信人员名单； （三）法定代表人、主要负责人、实际控制人、董（监）事会人员、高级管理人员以及从事涉密集成业务人员具有中华人民共和国国籍，无境外永久居留权或者长期居留许可，与境外人员无婚姻关系，国家另有规定的除外； （四）具有从事涉密集成业务的专业能力； （五）法律、行政法规和国家保密行政管理部门规定的其他条件。"},{"i":13,"n":"第十三条","txt":"申请单位应当具备以下保密条件： （一）有专门机构或者人员负责保密工作； （二）保密制度完善； （三）从事涉密集成业务的人员经过保密教育培训，具备必要的保密知识和技能； （四）用于涉密集成业务的场所、设施、设备符合国家保密规定和标准； （五）有专门的保密工作经费； （六）法律、行政法规和国家保密行政管理部门规定的其他保密条件。"},{"i":14,"n":"第十四条","txt":"申请单位应当无外国投资者直接投资，且通过间接方式投资的外国投资者在申请单位中的出资比例最终不得超过20%；申请单位及其股东的实际控制人不得为外国投资者，外国投资者在申请单位母公司中的出资比例最终不得超过20%。 在新三板挂牌的企业申请资质以及资质有效期内的，还应当符合以下条件： （一）参与挂牌交易的股份比例不高于总股本的30%； （二）实际控制人在申请期间及资质有效期内保持控制地位不变。"},{"i":15,"n":"第十五条","txt":"申请单位应当建立完善的内部管理和信息披露制度，未经国务院有关主管部门或者省级人民政府有关主管部门批准，外国投资者不得接触、知悉国家秘密信息。"},{"i":16,"n":"第十六条","txt":"申请单位申请不同等级和业务种类的涉密集成资质，应当符合涉密集成资质具体条件的要求。"},{"i":17,"n":"第十七条","txt":"申请甲级资质的，应当向国家保密行政管理部门提出申请；申请乙级资质的，应当向注册地的省级保密行政管理部门提出申请。申请单位应当提交以下材料： （一）《涉密信息系统集成资质申请书》（以下简称申请书）； （二）企业营业执照或者事业单位法人证书； （三）在登记机关备案的章程； （四）法定代表人、主要负责人、实际控制人、董（监）事会人员、高级管理人员以及从事涉密集成业务的其他人员情况； （五）资本结构和股权情况； （六）生产经营和办公场所产权证书或者租赁合同； （七）近三年集成业务合同清单； （八）涉密集成业务场所和保密设施、设备情况； （九）基本管理制度、保密制度以及保密体系运行情况。 申请书及相关材料不得涉及国家秘密，申请单位应当对申请材料的真实性和完整性负责。"},{"i":18,"n":"第十八条","txt":"保密行政管理部门收到申请材料后，应当在五日内完成审查。申请材料齐全且符合法定形式的，应当受理并发出受理通知书；申请材料不齐全或者不符合法定形式的，应当一次告知申请单位十五日内补正材料；逾期未告知申请单位补正的，自收到申请材料之日起即为受理。申请单位十五日内不予补正的，视为放弃本次行政许可申请。"},{"i":19,"n":"第十九条","txt":"资质审查分为书面审查、现场审查。确有需要的，可以组织专家开展评审。"},{"i":20,"n":"第二十条","txt":"对作出受理决定的，保密行政管理部门应当对提交的申请材料进行书面审查。"},{"i":21,"n":"第二十一条","txt":"对书面审查合格的单位，保密行政管理部门应当指派两名以上工作人员，并可以结合工作实际指派一名以上审查专家，依据涉密集成资质审查细则和评分标准，对保密制度、保密工作机构、保密监督管理、涉密人员管理、保密技术防护以及从事涉密集成业务的专业能力等情况进行现场审查。 涉密集成资质审查细则和评分标准由国家保密行政管理部门另行规定。"},{"i":22,"n":"第二十二条","txt":"现场审查应当按照以下程序进行： （一）提前五日以传真、电子邮件等形式书面通知申请单位现场审查时间； （二）听取申请单位情况汇报和对有关事项的说明； （三）审查有关材料； （四）与主要负责人、保密工作负责人及有关人员谈话了解情况； （五）组织涉密人员进行保密知识测试； （六）对涉密场所、涉密设备等进行实地查看； （七）汇总现场审查情况，形成现场审查报告； （八）通报审查情况，申请单位法定代表人或者主要负责人在现场审查报告上签字确认。"},{"i":23,"n":"第二十三条","txt":"申请单位具有下列情形之一的，保密行政管理部门应当终止审查： （一）隐瞒有关情况或者提供虚假材料的； （二）采取贿赂、请托等不正当手段，影响审查工作公平公正进行的； （三）无正当理由拒绝按通知时间接受现场审查的； （四）现场审查中发现不符合评分标准基本项的； （五）其他违反保密法律法规的行为。"},{"i":24,"n":"第二十四条","txt":"申请单位书面审查、现场审查合格的，保密行政管理部门应当准予行政许可。 申请单位具有下列情形之一的，保密行政管理部门应当作出不予行政许可的书面决定，说明理由并告知申请单位相关权利: （一）书面审查不合格的； （二）现场审查不合格的； （三）终止审查的； （四）法律、行政法规规定的不予行政许可的其他情形。"},{"i":25,"n":"第二十五条","txt":"保密行政管理部门应当自受理申请之日起二十日内，对申请单位作出准予行政许可或者不予行政许可的决定。二十日内不能作出决定的，经本行政机关负责人批准，可以延长十日，并应当将延长期限的理由告知申请单位。 保密行政管理部门组织开展专家评审、鉴定所需时间不计入行政许可期限。"},{"i":26,"n":"第二十六条","txt":"保密行政管理部门作出准予行政许可的决定的，自作出决定之日起十日内向申请单位颁发《涉密信息系统集成资质证书》（以下简称《资质证书》）。"},{"i":27,"n":"第二十七条","txt":"《资质证书》有效期为五年，分为正本和副本，正本和副本具有同等法律效力。样式由国家保密行政管理部门统一制作，主要包括以下内容： （一）单位名称； （二）法定代表人； （三）注册地址； （四）证书编号； （五）资质等级； （六）业务种类； （七）发证机关； （八）有效期和发证日期。"},{"i":28,"n":"第二十八条","txt":"《资质证书》有效期满，需要继续从事涉密集成业务的，应当在有效期届满三个月前向保密行政管理部门提出延续申请，保密行政管理部门应当按照本办法有关规定开展审查，申请单位未按规定期限提出延续申请的，视为重新申请。 有效期届满且未准予延续前，不得签订新的涉密集成业务合同。对于已经签订合同但未完成的涉密业务，在确保安全保密的条件下可以继续完成。"},{"i":29,"n":"第二十九条","txt":"省级保密行政管理部门应当将许可的乙级资质单位报国家保密行政管理部门备案。 准予行政许可和注销、吊销、撤销以及暂停资质的决定，由作出决定的保密行政管理部门在一定范围内予以发布。"},{"i":30,"n":"第三十条","txt":"省级以上保密行政管理部门应当加强对下一级保密行政管理部门以及协助开展审查工作的专门机构的监督检查，及时纠正资质管理中的违法违规行为。"},{"i":31,"n":"第三十一条","txt":"保密行政管理部门应当开展“双随机”抽查、飞行检查等形式的保密检查，对资质单位从事涉密集成业务和保密管理情况进行监督。"},{"i":32,"n":"第三十二条","txt":"机关、单位委托资质单位从事涉密集成业务，应当查验其《资质证书》，签订保密协议，提出保密要求，采取保密措施，加强涉密业务实施现场的监督检查。"},{"i":33,"n":"第三十三条","txt":"资质单位与其他单位合作开展涉密集成业务的，合作单位应当具有相应的涉密集成资质且取得委托方书面同意。 资质单位不得将涉密集成业务分包或者转包给无相应涉密资质的单位。"},{"i":34,"n":"第三十四条","txt":"资质单位承接涉密集成业务的，应当在签订合同后三十日内，向业务所在地省级保密行政管理部门备案，接受保密监督管理。"},{"i":35,"n":"第三十五条","txt":"乙级资质单位拟在注册地的省级行政区域外承接涉密集成业务的，应当向业务所在地的省级保密行政管理部门备案，接受保密监督管理。"},{"i":36,"n":"第三十六条","txt":"资质单位实行年度自检制度，应当于每年3月31日前向作出准予行政许可决定的保密行政管理部门报送上一年度自检报告。"},{"i":37,"n":"第三十七条","txt":"资质单位下列事项发生变更的，应当在变更前向保密行政管理部门书面报告： （一）注册资本或者股权结构； （二）控股股东或者实际控制人； （三）单位性质或者隶属关系； （四）用于涉密集成业务的场所。 保密行政管理部门应当对资质单位变更事项进行书面审查。通过审查的，资质单位应当按照审定事项实施变更，并在变更完成后十日内提交情况报告。 拟公开上市的，应当资质剥离后重新申请；对影响或者可能影响国家安全的外商投资，应当按照外商投资安全审查制度进行安全审查。 资质单位发生控股股东或者实际控制人、单位性质或者隶属关系、用于涉密集成业务的场所等事项变更的，保密行政管理部门应当组织现场审查。"},{"i":38,"n":"第三十八条","txt":"资质单位下列事项发生变更的，应当在变更后十日内向保密行政管理部门书面报告： （一）单位名称； （二）注册地址或者经营地址； （三）经营范围； （四）法定代表人、董（监）事会人员或者高级管理人员。 资质单位变更完成需换发《资质证书》的，由保密行政管理部门审核后重新颁发。"},{"i":39,"n":"第三十九条","txt":"保密行政管理部门在现场审查、保密检查过程中，发现申请单位或者资质单位存在涉嫌泄露国家秘密的案件线索，应当根据工作需要，按照泄密案件管辖权限，经保密行政管理部门负责人批准，由具备执法资格的人员对有关设施、设备、载体等采取登记保存措施，依法开展调查工作。 保密行政管理部门调查结束后，认定申请单位或者资质单位存在违反保密法律法规事实的，违法行为发生地的保密行政管理部门应当按照本办法作出处理，并将违法事实、处理结果抄告受理申请或者准予行政许可的保密行政管理部门。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，作出准予行政许可决定的保密行政管理部门或者其上级保密行政管理部门，依据职权可以撤销行政许可： （一）保密行政管理部门滥用职权、玩忽职守作出准予行政许可决定的； （二）超越法定职权作出准予行政许可决定的； （三）违反法定程序作出准予行政许可决定的； （四）对不具备申请资格或者不符合法定条件的申请单位准予行政许可的； （五）依法可以撤销行政许可的其他情形。 资质单位采取欺骗、贿赂等不正当手段取得资质的，保密行政管理部门应当撤销其资质，停止其涉密业务。自撤销之日起，三年内不得再次申请。"},{"i":41,"n":"第四十一条","txt":"资质单位具有下列情形之一的，作出准予行政许可决定的保密行政管理部门应当注销其资质： （一）《资质证书》有效期届满未延续的； （二）法人资格依法终止的； （三）主动申请注销资质的； （四）行政许可依法被撤销、撤回，或者行政许可证件依法被吊销的； （五）因不可抗力导致行政许可事项无法实施的； （六）法律、行政法规规定的应当注销资质的其他情形。"},{"i":42,"n":"第四十二条","txt":"申请单位或者资质单位对保密行政管理部门作出的决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":43,"n":"第四十三条","txt":"资质单位违反本办法的，依照本办法有关规定处理；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"资质单位具有下列情形之一的，保密行政管理部门应当责令其在二十日内完成整改，逾期不改或者整改后仍不符合要求的，应当给予六个月以上十二个月以下暂停资质的处罚： （一）未经委托方书面同意，擅自与其他涉密集成资质单位合作开展涉密集成业务的； （二）超出行政许可的业务种类范围承接涉密集成业务的； （三）发生需要报告的事项，未及时报告的； （四）承接涉密集成业务，未按规定备案的； （五）未按本办法提交年度自检报告的； （六）不符合其他保密管理规定，存在泄密隐患的。"},{"i":45,"n":"第四十五条","txt":"资质单位不再符合申请条件，或者具有下列情形之一的，保密行政管理部门应当吊销其资质，停止其涉密业务： （一）涂改、出卖、出租、出借《资质证书》，或者以其他方式伪造、非法转让《资质证书》的； （二）将涉密集成业务分包或者转包给无相应涉密资质单位的； （三）发现国家秘密已经泄露或者可能泄露，未按法定时限报告的； （四）拒绝接受保密检查的； （五）资质暂停期间，承接新的涉密集成业务的； （六）资质暂停期满，仍不符合保密管理规定的； （七）发生泄密案件的； （八）其他违反保密法律法规的行为。"},{"i":46,"n":"第四十六条","txt":"申请单位隐瞒有关情况或者提供虚假材料的，保密行政管理部门应当作出不予受理或者不予行政许可的决定。自不予受理或者不予行政许可之日起，一年内不得再次申请。"},{"i":47,"n":"第四十七条","txt":"未经保密行政管理部门许可的单位从事涉密集成业务的，由保密行政管理部门责令停止违法行为，非法获取、持有的国家秘密载体，应当予以收缴；有违法所得的，由市场监督管理部门没收违法所得；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"机关、单位委托未经保密行政管理部门许可的单位从事涉密集成业务的，应当由有关机关、单位对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"保密行政管理部门及其工作人员未依法履行职责，或者滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予政务处分；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"机关、单位自行开展涉密信息系统集成业务，可以由本机关、单位内部信息化工作机构承担，接受同级保密行政管理部门监督指导。"},{"i":51,"n":"第五十一条","txt":"申请单位资本结构包含香港特别行政区、澳门特别行政区、台湾地区投资者以及定居在国外中国公民投资者的，参照本办法管理。国家另有规定的，从其规定。"},{"i":52,"n":"第五十二条","txt":"本办法规定的实施行政许可的期限以工作日计算，不含法定节假日。"},{"i":53,"n":"第五十三条","txt":"本办法由国家保密局负责解释。"},{"i":54,"n":"第五十四条","txt":"本办法自2021年3月1日起施行。国家保密局发布的《涉密信息系统集成资质管理办法》（国保发〔2013〕7号，国保发〔2019〕13号修订）同时废止。 附件：涉密信息系统集成资质具体条件 涉密信息系统集成资质具体条件 一、总体集成 （一）甲级资质 1. 注册资本以货币资金实缴额不少于3000万元人民币。 2. 近3年的信息系统集成收入总金额不少于4亿元人民币，其中至少含有3个不少于1000万元人民币的信息系统集成项目。 3. 从事信息系统集成业务的相关人员不少于200名，且在本单位依法缴纳社保一年以上的人员不少于160名。 4. 省级以上人力资源和社会保障部门或者其授权机构认可的计算机技术与软件（含信息安全）专业相关高级职称或者执业资格的人员不少于6名，其中在本单位依法缴纳社保一年以上的不少于4名。 5. 具有自有产权或者租赁期3年（含）以上的涉密业务场所，使用面积不少于100平方米，实"}],"dianboyingyuandianboyuanxianguanliguiding":[{"i":1,"n":"第一条","txt":"为促进电影产业健康繁荣发展，弘扬社会主义核心价值观，规范电影产业新业态，丰富人民群众精神文化生活，根据《中华人民共和国电影产业促进法》和《电影管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"从事点播影院、点播院线电影放映、发行活动，适用本规定。 本规定所称点播影院，是指在电影院和流动放映活动场所之外，为观众观看自选影片提供放映服务经营活动的文化娱乐场所。 本规定所称点播院线，是指由一定数量的点播影院组成，拥有一定数量影片的发行权，并对所辖点播影院的电影放映活动提供影片、实施运营管理的发行企业。"},{"i":3,"n":"第三条","txt":"从事点播影院、点播院线电影放映、发行活动，应当遵守宪法和有关法律、法规，坚持为人民服务、为社会主义服务，坚持社会效益优先，实现社会效益与经济效益相统一。"},{"i":4,"n":"第四条","txt":"国务院电影主管部门负责全国点播影院、点播院线电影放映、发行活动的监督管理工作。 县级以上地方人民政府电影主管部门负责本行政区域内点播影院、点播院线电影放映、发行活动的监督管理工作。"},{"i":5,"n":"第五条","txt":"企业、个体工商户设立点播影院，应当向所在地县级人民政府电影主管部门提出申请，并应当符合以下条件： （一）放映设备、放映质量和计费系统符合国务院电影主管部门规定的技术规范； （二）所设单个影厅的银幕宽度不超过6米，观众有效座位数不超过20个； （三）有拟加入的点播院线或者处于筹建期的点播院线； （四）法定代表人或者主要负责人未处于电影从业禁止期间。"},{"i":6,"n":"第六条","txt":"企业设立省内点播院线，应当向所在地省、自治区、直辖市人民政府电影主管部门提出申请；设立跨省点播院线，应当向国务院电影主管部门提出申请；并应当符合以下条件： （一）有与其业务相适应的影片来源； （二）计费系统符合国务院电影主管部门规定的技术规范； （三）法定代表人或者主要负责人未处于电影从业禁止期间； （四）省内点播院线所辖点播影院数量不少于30家，跨省点播院线所辖点播影院数量不少于60家。 只符合前款第一项至第三项条件的，由有关电影主管部门发给有效期为3个月的同意筹建证明文件。筹建期间内达到前款第四项条件的，方可向有关电影主管部门申请颁发许可证件。"},{"i":7,"n":"第七条","txt":"电影主管部门应当依照《中华人民共和国电影产业促进法》第二十五条的规定，对符合条件的点播影院，颁发电影放映经营许可证；对符合条件的点播院线，颁发电影发行经营许可证。"},{"i":8,"n":"第八条","txt":"点播影院变更其所加入的点播院线或者处于筹建期的点播院线的，应当向原发证机关重新申请核发电影放映经营许可证。"},{"i":9,"n":"第九条","txt":"点播影院的电影放映经营许可证和点播院线的电影发行经营许可证的有效期为2年。"},{"i":10,"n":"第十条","txt":"国务院电影主管部门建立全国点播影院经营管理信息系统和影片著作权授权信息公示查询系统。"},{"i":11,"n":"第十一条","txt":"县级人民政府电影主管部门应当自颁发电影放映经营许可证之日起10日内，向省、自治区、直辖市人民政府电影主管部门报送相关审批材料。 点播影院应当自经许可设立之日起10日内，将许可的相关信息报送所加入的点播院线。"},{"i":12,"n":"第十二条","txt":"点播院线负责在全国点播影院经营管理信息系统上办理注册登记，申请点播影院编码。 省、自治区、直辖市人民政府电影主管部门应当自收到相关材料之日起10日内，依据所报材料对全国点播影院经营管理信息系统所载点播影院相关信息进行核对。核对无误的，依点播院线申请向其发放所辖点播影院编码。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市人民政府以上电影主管部门应当自颁发电影发行经营许可证之日起10日内，在全国点播影院经营管理信息系统上办理注册登记，并向点播院线发放点播院线编码。"},{"i":14,"n":"第十四条","txt":"点播影院编码、点播院线编码是电影主管部门对点播影院、点播院线实施管理的唯一数字标识。"},{"i":15,"n":"第十五条","txt":"点播院线负责向所辖点播影院提供影片。 点播影院不得放映所加入的点播院线发行范围之外的影片。"},{"i":16,"n":"第十六条","txt":"点播影院放映和点播院线发行的影片，应当依法获得电影公映许可。"},{"i":17,"n":"第十七条","txt":"点播院线发行的影片，应当依法取得著作权人许可其在点播影院放映的授权。 点播院线应当及时将影片著作权授权状况上传至影片著作权授权信息公示查询系统。"},{"i":18,"n":"第十八条","txt":"电影著作权人对其作品由电影院进入点播影院放映的期间有限定的，点播院线在限定期间不得发行。"},{"i":19,"n":"第十九条","txt":"点播影院应当合理安排由境内法人、其他组织所摄制电影的放映场次和时段，并且放映的时长不得低于年放映电影时长总和的2/3。"},{"i":20,"n":"第二十条","txt":"点播影院不得在同一影厅内开展电影院的电影放映活动。"},{"i":21,"n":"第二十一条","txt":"点播影院应当遵守治安、消防、公共场所卫生等法律、法规规定，维护放映场所的公共秩序和环境卫生，保障观众的安全与健康。"},{"i":22,"n":"第二十二条","txt":"点播影院、点播院线应当加强计费系统和放映系统设备的日常维护，确保电影放映质量。"},{"i":23,"n":"第二十三条","txt":"点播院线负责对所辖点播影院的制度建设、放映内容和质量管理、技术系统建设和运行维护、数据报送、人员培训等运营活动实施管理。"},{"i":24,"n":"第二十四条","txt":"点播影院应当按照所加入点播院线的要求，按时报送相关经营数据。 点播院线应当按照国务院电影主管部门的要求，将所辖点播影院的经营数据上传至全国点播影院经营管理信息系统，纳入电影销售收入统计。"},{"i":25,"n":"第二十五条","txt":"电影主管部门应当加强对点播影院、点播院线的日常监督管理。 电影主管部门的工作人员依法履行监督检查职责时，点播影院、点播院线应当予以配合并提供必要的技术支持，不得拒绝、阻扰。"},{"i":26,"n":"第二十六条","txt":"电影主管部门应当记录监督检查情况和处理结果，并定期向社会公布有关执法情况。"},{"i":27,"n":"第二十七条","txt":"任何单位或者个人发现点播影院、点播院线有违反本规定行为的，有权向电影主管部门投诉、举报。"},{"i":28,"n":"第二十八条","txt":"电影主管部门应当分别建立点播影院、点播院线违法行为警示记录档案，并向社会公布；对列入警示记录的点播影院、点播院线，应当加大监督检查力度。"},{"i":29,"n":"第二十九条","txt":"点播影院、点播院线行业协会应当依照章程规定，制定行业自律规范，指导和推动点播影院、点播院线依法规范经营。"},{"i":30,"n":"第三十条","txt":"违反本规定，擅自从事点播影院、点播院线电影放映、发行活动的，依照《中华人民共和国电影产业促进法》第四十七条的规定予以处罚。 伪造、变造、出租、出借、买卖或者以其他形式非法转让有关电影放映、发行许可证件，或者以欺骗、贿赂等不正当手段取得上述许可证件的，依照《中华人民共和国电影产业促进法》第四十八条的规定予以处罚。"},{"i":31,"n":"第三十一条","txt":"违反本规定，放映、发行未获得电影公映许可的电影的，依照《中华人民共和国电影产业促进法》第四十九条的规定予以处罚。"},{"i":32,"n":"第三十二条","txt":"违反本规定，有下列行为之一的，依照《中华人民共和国电影产业促进法》第五十一条的规定予以处罚： （一）制造虚假交易、虚报瞒报销售收入，扰乱电影市场秩序的； （二）在电影开始放映之后至放映结束前放映广告的。"},{"i":33,"n":"第三十三条","txt":"违反本规定，有下列行为之一的，由县级以上人民政府电影主管部门责令限期改正，给予警告，可以并处3万元以下的罚款： （一）未按时办理点播影院编码、点播院线编码登记的； （二）点播影院放映所加入点播院线发行范围之外的影片的； （三）点播院线未按时报送经营数据的； （四）点播影院在同一影厅内开展电影院的电影放映活动的； （五）点播院线未有效履行运营管理职责，致使所辖点播影院出现违法行为的； （六）点播影院、点播院线未按照点播影院技术规范的要求选用计费系统和放映系统设备，放映质量不达标的。"},{"i":34,"n":"第三十四条","txt":"点播影院、点播院线违反著作权法律法规的，由著作权行政管理部门依法予以处罚；情节严重的，由原发证机关吊销许可证。"},{"i":35,"n":"第三十五条","txt":"本规定未尽事宜，适用《中华人民共和国电影产业促进法》和《电影管理条例》的有关规定。"},{"i":36,"n":"第三十六条","txt":"境外资本从事点播影院、点播院线电影放映、发行活动的，参照国家有关电影院、电影院线外资准入的规定执行。"},{"i":37,"n":"第三十七条","txt":"公益性点播影院、点播院线的业务许可、经营规范和监督管理参照本规定执行。"},{"i":38,"n":"第三十八条","txt":"本规定自2018年3月30日起施行。"}],"lieshigongjibanfa":[{"i":1,"n":"第一条","txt":"为了缅怀纪念烈士，传承和弘扬烈士精神，做好烈士公祭工作，根据有关法律法规和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"烈士公祭是国家缅怀纪念为争取民族独立和人民解放、实现国家富强和人民幸福、促进世界和平和人类进步而毕生奋斗、英勇牺牲的烈士的活动。"},{"i":3,"n":"第三条","txt":"在清明节、国庆节或者烈士纪念日等重大庆典日、重要纪念日，县级以上地方人民政府在本行政区域内举行的烈士公祭活动，适用本办法。 烈士公祭活动应当庄严、肃穆、隆重、节俭。"},{"i":4,"n":"第四条","txt":"举行烈士公祭活动，由县级以上地方人民政府退役军人工作主管部门提出建议和方案，报请同级人民政府组织实施。"},{"i":5,"n":"第五条","txt":"烈士公祭活动应当在烈士纪念场所举行。 上级地方人民政府与下级地方人民政府在同一烈士纪念场所举行烈士公祭活动，应当合并进行。"},{"i":6,"n":"第六条","txt":"烈士公祭活动方案应当包括以下内容： （一）烈士公祭活动时间、地点； （二）参加烈士公祭活动人员及其现场站位和着装要求； （三）烈士公祭仪式仪程； （四）烈士公祭活动的组织协调、宣传报道、交通和安全警卫、医疗保障、经费保障、礼兵仪仗、天气预报、现场布置和物品器材准备等事项的分工负责单位及负责人。"},{"i":7,"n":"第七条","txt":"烈士公祭活动应当安排党、政、军和人民团体负责人参加，组织烈士遗属代表、老战士和退役军人代表、学校师生代表、各界干部群众代表、军队人员代表等参加。"},{"i":8,"n":"第八条","txt":"参加烈士公祭活动人员着装应当庄重得体，可以按照规定穿着制式服装，佩戴获得的荣誉勋章、奖章、纪念章等。"},{"i":9,"n":"第九条","txt":"烈士公祭活动现场应当标明肃穆区域，设置肃穆提醒标志。 在肃穆区域内，应当言行庄重，不得喧哗。"},{"i":10,"n":"第十条","txt":"烈士公祭仪式由组织活动的地方人民政府或者其退役军人工作主管部门的负责人主持。 烈士公祭仪式不设主席台，参加烈士公祭仪式人员应当面向烈士纪念碑（塔）等设施肃立。"},{"i":11,"n":"第十一条","txt":"烈士公祭仪式一般应当按照下列程序进行： （一）礼兵就位； （二）主持人向烈士纪念碑（塔）等设施行鞠躬礼，宣布烈士公祭仪式开始； （三）奏唱《中华人民共和国国歌》； （四）宣读祭文； （五）少先队员献唱《我们是共产主义接班人》； （六）向烈士敬献花篮或者花圈，奏《献花曲》； （七）整理缎带或者挽联； （八）向烈士行三鞠躬礼； （九）瞻仰烈士纪念碑（塔）等设施。 向烈士行三鞠躬礼后可以邀请参加活动的代表发言。"},{"i":12,"n":"第十二条","txt":"在国庆节或者烈士纪念日等重大庆典日、重要纪念日进行烈士公祭的，可以采取向烈士纪念碑（塔）等设施敬献花篮的仪式，按照下列程序进行： （一）礼兵就位； （二）主持人向烈士纪念碑（塔）等设施行鞠躬礼，宣布敬献花篮仪式开始； （三）奏唱《中华人民共和国国歌》； （四）全体人员向烈士默哀； （五）少先队员献唱《我们是共产主义接班人》； （六）向烈士敬献花篮，奏《献花曲》； （七）整理缎带； （八）瞻仰烈士纪念碑（塔）等设施。"},{"i":13,"n":"第十三条","txt":"烈士公祭仪式中的礼兵仪仗、花篮花圈护送由组织活动的地方人民政府协调当地驻军有关部门负责安排解放军或者武警部队官兵担任。 烈士公祭仪式可以安排军乐队或者其他乐队演奏乐曲，也可以播放音乐。"},{"i":14,"n":"第十四条","txt":"烈士公祭活动的花篮或者花圈由党、政、军、人民团体及各界群众等敬献。 花篮的缎带或者花圈的挽联为红底黄字，上联书写烈士永垂不朽，下联书写敬献单位或个人。 整理缎带或者挽联按照先整理上联、后整理下联的顺序，双手整理。 默哀时应当脱帽，时间一般不少于一分钟。 瞻仰烈士纪念设施时一般按照顺时针方向绕行一周，活动人数较多的，也可以分别按顺时针或者逆时针方向绕行半周。"},{"i":15,"n":"第十五条","txt":"县级以上地方人民政府在组织烈士公祭活动时，可以根据实际情况，引导公民通过观看烈士公祭活动直播、瞻仰烈士纪念设施、集体宣誓等，铭记烈士事迹，传承和弘扬烈士精神。 各级各类学校应当组织学生以适当方式参加烈士公祭，加强爱国主义、集体主义、社会主义教育。"},{"i":16,"n":"第十六条","txt":"烈士纪念设施保护单位应当结合烈士公祭活动，采取多种形式广泛宣讲烈士英雄事迹和相关重大历史事件，配合有关单位开展爱国主义、集体主义、社会主义教育和其他主题教育活动。"},{"i":17,"n":"第十七条","txt":"烈士纪念设施保护单位应当创新工作方式方法，健全服务和管理工作规范，保持烈士纪念场所庄严、肃穆、清净的环境和气氛，做好服务接待工作；可以按照庄严、有序、便捷的原则组织开展网上祭奠活动，方便广大人民群众瞻仰、悼念烈士。"},{"i":18,"n":"第十八条","txt":"单位、个人在烈士纪念设施保护范围内组织开展缅怀纪念活动，应当文明有序，遵守有关祭扫礼仪规范，并接受烈士纪念设施保护单位管理。 单位组织开展集体缅怀纪念活动，可以参照本办法第十一条规定程序进行，也可以根据实际情况简化程序。"},{"i":19,"n":"第十九条","txt":"对影响烈士公祭活动的，或者在烈士纪念设施保护范围内从事有损纪念烈士环境和气氛的活动的，烈士纪念设施保护单位应当及时劝阻；不听劝阻的，由县级以上地方人民政府退役军人工作主管部门按照职责规定给予批评教育，责令改正。"},{"i":20,"n":"第二十条","txt":"任何单位和个人不得利用烈士公祭从事商业活动。"},{"i":21,"n":"第二十一条","txt":"违反本办法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"对安葬在国外的烈士，驻外使领馆应当结合驻在国实际情况，参照本办法规定组织开展烈士公祭等祭扫纪念活动。"},{"i":23,"n":"第二十三条","txt":"本办法自2023年5月1日起施行。"}],"lieshianzangbanfa":[{"i":1,"n":"第一条","txt":"为了褒扬和尊崇烈士，做好烈士安葬工作，根据《中华人民共和国英雄烈士保护法》、《烈士褒扬条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"烈士应当在烈士陵园或者烈士集中安葬墓区安葬。 烈士陵园、烈士集中安葬墓区是国家建立的专门安葬、纪念、宣传烈士的重要场所，受法律保护。"},{"i":3,"n":"第三条","txt":"确定烈士安葬地和安排烈士安葬活动，应当征求烈士遗属意见。 烈士可以在牺牲地、生前户籍所在地、遗属户籍所在地或者生前工作单位所在地安葬。烈士安葬地确定后，就近在安葬地的烈士陵园或者烈士集中安葬墓区安葬烈士。"},{"i":4,"n":"第四条","txt":"烈士骨灰盒或者灵柩应当覆盖中华人民共和国国旗。需要覆盖中国共产党党旗或者中国人民解放军军旗的，按照有关规定执行。 国旗、党旗、军旗不能同时覆盖，不得随遗体火化或者随骨灰盒、灵柩掩埋，安葬后由安葬地烈士纪念设施保护单位保存，也可以赠送给烈士遗属留作纪念。"},{"i":5,"n":"第五条","txt":"运送烈士骨灰或者遗体（骸），由烈士牺牲地、烈士安葬地县级以上地方人民政府共同安排，并举行送迎仪式。 送迎工作方案由烈士牺牲地、烈士安葬地县级以上地方人民政府退役军人工作主管部门商相关部门制定并报同级人民政府批准后实施。 送迎仪式一般按下列程序进行： （一）仪式开始； （二）整理烈士灵柩（骨灰盒）并覆盖国旗（或者党旗、军旗）； （三）奏国歌； （四）向烈士默哀； （五）起灵； （六）仪式结束。 烈士生前为现役军人的，烈士骨灰或者遗体（骸）运送任务可由烈士牺牲地县级以上地方人民政府会同军队有关单位承担。"},{"i":6,"n":"第六条","txt":"烈士安葬地县级以上地方人民政府应当举行庄严、肃穆、文明、节俭的烈士安葬仪式。 烈士安葬仪式应当邀请当地党委、政府和有关部门负责同志，烈士遗属代表、烈士生前所在单位代表，机关、团体、学校、企业事业单位、社会组织、军队等有关单位代表和退役军人代表参加。 烈士安葬仪式可以邀请解放军、武警部队官兵或者人民警察承担礼兵仪仗、花篮护送等任务；可以邀请军乐队或者其他乐队演奏乐曲，也可以播放音乐。"},{"i":7,"n":"第七条","txt":"烈士安葬仪式一般按下列程序进行： （一）仪式开始； （二）礼迎烈士； （三）奏国歌； （四）宣读烈士评定文件、烈士生平事迹并致悼词或者祭文； （五）向烈士默哀； （六）安葬烈士骨灰或者遗体（骸）； （七）向烈士敬献花篮（花圈）； （八）仪式结束。"},{"i":8,"n":"第八条","txt":"安葬烈士的方式包括： （一）将烈士骨灰安葬于烈士墓区或者烈士骨灰堂； （二）将烈士遗体（骸）安葬于烈士墓区； （三）其他安葬方式。 安葬烈士应当遵守国家殡葬管理有关规定，尊重少数民族的丧葬习俗，倡导绿色、节地、生态安葬方式。"},{"i":9,"n":"第九条","txt":"烈士墓穴、骨灰安放格位，由烈士纪念设施保护单位按照规定确定。"},{"i":10,"n":"第十条","txt":"安葬烈士骨灰的墓穴面积一般不超过1平方米。允许土葬的地区，安葬烈士遗体（骸）的墓穴面积一般不超过4平方米。"},{"i":11,"n":"第十一条","txt":"烈士墓碑碑文或者骨灰盒标识牌文字应当经烈士安葬地县级以上地方人民政府退役军人工作主管部门审定，内容应当包括烈士姓名、性别、民族、籍贯、出生年月、牺牲时间、单位、职务、简要事迹等基本信息，落款一般为安葬地县级以上地方人民政府。"},{"i":12,"n":"第十二条","txt":"烈士墓区应当规划科学、布局合理，环境整洁、肃穆。烈士墓和烈士骨灰存放设施应当形制统一、用料优良，确保施工建设质量。"},{"i":13,"n":"第十三条","txt":"烈士陵园、烈士集中安葬墓区的保护单位应当向烈士遗属发放烈士安葬证明书，载明烈士姓名、安葬时间和安葬地点等。没有烈士遗属的，应当将烈士安葬情况向烈士生前户籍所在地县级人民政府退役军人工作主管部门备案。 烈士生前有工作单位的，应当将安葬情况向烈士生前所在单位通报。"},{"i":14,"n":"第十四条","txt":"烈士在烈士陵园或者烈士集中安葬墓区安葬后，原则上不迁葬。 对未在烈士陵园或者烈士集中安葬墓区安葬的零散烈士墓，县级以上地方人民政府退役军人工作主管部门应当根据实际情况并征得烈士遗属同意，就近迁入烈士陵园或者烈士集中安葬墓区。"},{"i":15,"n":"第十五条","txt":"在生产生活或者相关工作中发现、发掘的疑似烈士遗骸，按照有关规定，经鉴定确认为烈士遗骸的，应当就近在烈士陵园或者烈士集中安葬墓区及时妥善安葬；已确认身份的，应当及时通知其亲属并邀请出席安葬仪式。"},{"i":16,"n":"第十六条","txt":"烈士牺牲后无法搜寻到遗体（骸）、无法查找到安葬地或者安葬地在境外的，可在烈士牺牲地、生前户籍所在地或者遗属户籍所在地烈士陵园、烈士集中安葬墓区英名墙，纪念相关战役（战争）烈士陵园英名墙等设施镌刻烈士姓名予以纪念，但不得在烈士陵园或者烈士集中安葬墓区建造衣冠冢或者空墓。"},{"i":17,"n":"第十七条","txt":"烈士陵园、烈士集中安葬墓区的保护单位应当建立烈士安葬信息档案，及时收集、整理、陈列有纪念意义的烈士遗物、事迹资料，烈士遗属、有关单位和个人应当予以配合。"},{"i":18,"n":"第十八条","txt":"在烈士纪念日等重要纪念日和节日时，机关、团体、学校、企业事业单位和军队有关单位应当组织开展烈士纪念活动，祭奠缅怀烈士，弘扬英烈精神。 烈士陵园、烈士集中安葬墓区的保护单位及所在地人民政府退役军人工作主管部门对前来祭扫的烈士遗属和社会群众，应当做好接待服务工作。"},{"i":19,"n":"第十九条","txt":"鼓励和支持社会殡仪专业服务机构等社会力量为烈士安葬提供专业化、规范化服务。"},{"i":20,"n":"第二十条","txt":"战时牺牲人员遗体收殓安葬、在境外搜寻发掘的烈士遗骸归国安葬按照有关规定执行。"},{"i":21,"n":"第二十一条","txt":"本办法自2023年2月1日起施行。"}],"lieshijiniansheshibaohuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强烈士纪念设施保护管理，传承弘扬英烈精神和爱国主义精神，更好发挥烈士纪念设施褒扬英烈、教育后人的红色资源作用，根据《中华人民共和国英雄烈士保护法》、《烈士褒扬条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称烈士纪念设施，是指在中华人民共和国境内按照国家有关规定为纪念缅怀英烈专门修建的烈士陵园、烈士墓、烈士骨灰堂、烈士英名墙、纪念堂馆、纪念碑亭、纪念塔祠、纪念塑像、纪念广场等设施。"},{"i":3,"n":"第三条","txt":"烈士纪念设施应当按照基础设施完备、保护状况优良、机构制度健全、服务管理规范、功能发挥显著的要求，加强保护管理工作。"},{"i":4,"n":"第四条","txt":"国务院退役军人工作主管部门负责指导全国烈士纪念设施的保护管理工作。县级以上地方人民政府退役军人工作主管部门负责本行政区域烈士纪念设施的保护管理工作。"},{"i":5,"n":"第五条","txt":"烈士纪念设施应当由县级以上人民政府退役军人工作主管部门报请同级人民政府确定保护单位，具体负责烈士纪念设施保护管理工作，加强工作力量，明确管理责任。不能确定保护单位的，应当由县级以上人民政府退役军人工作主管部门报请同级人民政府明确管理单位进行保护管理。"},{"i":6,"n":"第六条","txt":"县级以上人民政府退役军人工作主管部门会同财政、发展改革等部门安排烈士纪念设施保护管理和维修改造经费，用于烈士纪念设施维修改造、设备更新、环境整治、展陈宣传和祭扫纪念活动等工作，接受财政、审计部门和社会监督。"},{"i":7,"n":"第七条","txt":"国家对烈士纪念设施实行分级保护，根据其纪念意义、建设规模、保护状况等可分别确定为： （一）国家级烈士纪念设施； （二）省级烈士纪念设施； （三）设区的市级烈士纪念设施； （四）县级烈士纪念设施。 未确定保护级别的烈士纪念设施由所在地县级人民政府退役军人工作主管部门进行保护管理或者委托有关单位、组织或者个人进行保护管理。对于零散烈士墓应当集中迁移保护，确不具备集中保护条件的，应当明确保护力量和管理责任。"},{"i":8,"n":"第八条","txt":"符合下列基本条件之一的烈士纪念设施，可以申报国家级烈士纪念设施： （一）为纪念在中国革命、建设、改革等各个历史时期的重大事件、重要战役和主要革命根据地斗争中牺牲的烈士而修建的烈士纪念设施； （二）为纪念在全国有重要影响的著名烈士而修建的烈士纪念设施； （三）位于革命老区、民族地区的规模较大的烈士纪念设施； （四）为纪念为中国革命斗争牺牲的知名国际友人而修建的纪念设施； （五）规模较大、基础设施完备、规划建设特色明显，具有全国性知名度或较强区域影响力的其他烈士纪念设施。 地方各级烈士纪念设施的申报条件，由同级人民政府退役军人工作主管部门制定，报上一级人民政府退役军人工作主管部门备案。"},{"i":9,"n":"第九条","txt":"申报国家级烈士纪念设施，由省级人民政府退役军人工作主管部门提出申请，经国务院退役军人工作主管部门审核，报国务院批准后公布。 申报地方各级烈士纪念设施，由拟核定其保护级别的县级以上人民政府退役军人工作主管部门向本级人民政府提出申请，经本级人民政府批准后公布，并在公布后二十个工作日内报上一级人民政府退役军人工作主管部门备案。"},{"i":10,"n":"第十条","txt":"申报烈士纪念设施保护级别，应提供以下材料： （一）烈士纪念设施基本情况； （二）烈士纪念设施保护单位或者管理单位情况； （三）烈士纪念设施建设批准相关材料； （四）烈士纪念设施建设规划平面图； （五）土地使用权属（不动产权属）和保护范围证明； （六）主要纪念设施的现状照片； （七）需要提供的其他资料。"},{"i":11,"n":"第十一条","txt":"烈士纪念设施应当设立保护标志，由公布其保护级别的县级以上人民政府退役军人工作主管部门负责设立。 烈士纪念设施保护标志式样，由国务院退役军人工作主管部门统一制定。"},{"i":12,"n":"第十二条","txt":"烈士纪念设施应当纳入当地国民经济和社会发展规划等相关规划，发挥好爱国主义教育基地、国防教育基地作用。"},{"i":13,"n":"第十三条","txt":"烈士纪念设施保护单位和管理单位应当向所在地不动产登记机构申请办理不动产登记，确认烈士纪念设施不动产权属。"},{"i":14,"n":"第十四条","txt":"烈士纪念设施保护或管理单位的上级主管部门应当根据烈士纪念设施的类别、规模、保护级别以及周边环境等情况，提出划定烈士纪念设施保护范围的方案，报同级人民政府批准后公布，并报上一级人民政府退役军人工作主管部门备案。"},{"i":15,"n":"第十五条","txt":"新建、迁建、改扩建烈士纪念设施应当从严控制，未经批准不得建设。对于反映同一历史人物、同一历史事件，已建烈士纪念设施的，原则上不得重复建设。 涉及重大革命历史题材、已故领导同志、已故著名党史人物、已故著名党外人士、已故近代名人的烈士纪念设施的新建、迁建、改扩建，应当按规定逐级上报，经党中央、国务院批准后实施。 不涉及以上内容的，应当由所在地县级以上人民政府退役军人工作主管部门提出申请，经核定其保护级别的县级以上人民政府退役军人工作主管部门审核并报同级人民政府批准后实施。"},{"i":16,"n":"第十六条","txt":"新建、迁建、改扩建烈士纪念设施应当提出书面申请，申请材料包括项目名称、建设理由、建设内容、展陈内容、占地面积、建筑面积、用地性质、投资估算、资金来源等内容，并依法依规办理相关审批手续。新建烈士纪念设施的，应当同时提交申报保护级别文件。"},{"i":17,"n":"第十七条","txt":"烈士纪念设施名称应当严格按照核定保护级别时确定名称规范表述。 地方各级烈士纪念设施确需更名的，应由省级人民政府退役军人工作主管部门批准后公布，并报同级人民政府和国务院退役军人工作主管部门备案。 国家级烈士纪念设施确需更名的，由省级人民政府退役军人工作主管部门提出申请，经国务院退役军人工作主管部门批准后公布，并报国务院备案。"},{"i":18,"n":"第十八条","txt":"烈士纪念设施保护单位和管理单位应当保证设施设备外观完整、题词碑文字迹清晰，保持庄严、肃穆、清净的环境和氛围，为社会公众提供良好的瞻仰和教育场所。"},{"i":19,"n":"第十九条","txt":"烈士纪念设施应当免费向社会开放。"},{"i":20,"n":"第二十条","txt":"烈士纪念设施保护单位和管理单位应当按照国家有关规定，加强对烈士纪念设施中文物和历史建筑物的保护管理。 对属于不可移动文物的烈士纪念设施，依据文物保护法律法规划定保护范围和建设控制地带，并按照文物保护标准做好相关防护措施；对可移动文物，应当设立专门库房，分级建档，妥善保管。"},{"i":21,"n":"第二十一条","txt":"烈士纪念设施保护单位和管理单位应当开展英烈史料的收集整理、事迹编纂和陈列展示工作，挖掘研究英烈事迹和精神。"},{"i":22,"n":"第二十二条","txt":"烈士纪念设施保护单位和管理单位应当及时更新优化展陈，在保持基本陈列相对稳定的前提下，及时补充完善体现时代精神和新史料新成果的展陈内容，经审批可每5年进行一次局部改陈布展，每10年进行一次全面改陈布展。 地方各级烈士纪念设施改陈布展，由县级以上人民政府退役军人工作主管部门提出申请，基本陈列改陈布展大纲和版式稿经核定其保护级别的县级以上人民政府退役军人工作主管部门商有关部门审定。 国家级烈士纪念设施改陈布展，由省级人民政府退役军人工作主管部门报国务院退役军人工作主管部门审定。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府退役军人工作主管部门应当会同相关部门建立解说词研究审查制度，切实把好政治关、史实关，增强讲解的准确性、完整性和权威性。"},{"i":24,"n":"第二十四条","txt":"烈士纪念设施保护单位和管理单位应当协助配合机关、团体、乡村、社区、学校、企事业单位和军队有关单位开展烈士纪念日公祭活动和其他纪念活动，维护活动秩序，提高服务水平。"},{"i":25,"n":"第二十五条","txt":"烈士纪念设施保护单位和管理单位应当为烈士亲属和社会公众日常祭扫和瞻仰活动提供便利，创新服务方式，做好保障工作，推行文明绿色生态祭扫。 烈士纪念设施保护单位和管理单位应当配合接待异地祭扫的县级以上人民政府退役军人工作主管部门妥善安排祭扫活动，按照国家有关规定为自行前往异地祭扫的烈士亲属提供服务保障。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府退役军人工作主管部门应当指导烈士纪念设施保护单位和管理单位充分发挥红色资源优势，拓展宣传教育功能，扩大社会影响力。 烈士纪念设施保护单位和管理单位应当加强网络宣传教育，通过开设网站和利用新媒体平台，为社会公众提供网上祭扫和学习教育平台，宣传英烈事迹，弘扬英烈精神。"},{"i":27,"n":"第二十七条","txt":"烈士纪念设施保护单位和管理单位应当健全服务和管理工作规范，完善内部规章制度，提高管理和服务水平。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府退役军人工作主管部门应当加强对烈士纪念设施保护管理工作的监督考核。 省级人民政府退役军人工作主管部门应当会同有关部门每4年对本地区烈士纪念设施进行一次排查，建立排查档案。对保护不力、管理不善、作用发挥不充分的烈士纪念设施保护单位或管理单位进行通报批评，限期整改；情节严重的，依法依规追究责任。"},{"i":29,"n":"第二十九条","txt":"烈士纪念设施保护单位和管理单位应当根据事业发展和实际工作需要科学合理设置岗位，明确岗位职责，定期组织业务培训和学习交流。 烈士纪念设施保护单位应当配备研究馆员和英烈讲解员，并注重提高其专业素养，也可采取利用志愿者力量、购买服务等方式组织具有相关专业知识的人员和机构提供研究和讲解服务。"},{"i":30,"n":"第三十条","txt":"鼓励支持自然人、法人和非法人组织以捐赠财产等方式，参与烈士纪念设施保护管理工作。自然人、法人和非法人组织捐赠财产用于烈士纪念设施保护管理活动的，依法享受税收优惠。 县级以上人民政府退役军人工作主管部门应当会同文物部门指导烈士纪念设施保护单位和管理单位妥善保管捐赠的革命文物、烈士遗物等物品，建立健全捐赠档案，对捐赠的单位和个人按照国家有关规定给予精神鼓励或者物质奖励。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府退役军人工作主管部门可通过政府购买服务等方式加强烈士纪念设施保护管理工作力量。 烈士纪念设施保护单位和管理单位可以设立志愿服务站点，招募志愿者开展志愿服务，鼓励退役军人、烈士亲属、机关干部、专家学者和青年学生到烈士纪念设施担任义务讲解员、红色宣讲员、文明引导员，参与设施保护、讲解宣讲和秩序维护等工作。"},{"i":32,"n":"第三十二条","txt":"烈士纪念设施保护范围内的土地和设施受法律保护，任何组织和个人不得在烈士纪念设施保护范围内从事与纪念英烈无关或者有损纪念英烈环境和氛围的活动，不得侵占烈士纪念设施保护范围内的土地和设施，不得破坏、污损烈士纪念设施。"},{"i":33,"n":"第三十三条","txt":"在烈士纪念设施保护范围内从事有损纪念英烈环境和氛围活动的，烈士纪念设施保护单位和管理单位应当及时劝阻；不听劝阻的，由县级以上人民政府退役军人工作主管部门会同有关部门按照职责规定给予批评教育，责令改正。"},{"i":34,"n":"第三十四条","txt":"非法侵占烈士纪念设施保护范围内的土地、设施，破坏、污损烈士纪念设施，或者在烈士纪念设施保护范围内为不符合安葬条件的人员修建纪念设施、安葬或安放骨灰或者遗体的，由所在地县级以上人民政府退役军人工作主管部门责令改正，恢复原状、原貌；造成损失的，依法承担民事责任。"},{"i":35,"n":"第三十五条","txt":"烈士纪念设施保护单位和管理单位及其主管部门工作人员有下列行为之一的，由上级人民政府退役军人工作主管部门对其直接负责的责任人和其他主管人员进行批评教育，责令改正；情节严重的，依法依规追究责任： （一）滥用职权、玩忽职守、徇私舞弊，造成烈士纪念设施、史料遗物遭受损失的； （二）贪污、挪用烈士纪念设施保护管理经费的； （三）未经批准擅自新建、迁建、改扩建烈士纪念设施的； （四）其他违反相关法律法规行为的。"},{"i":36,"n":"第三十六条","txt":"违反本办法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"本办法自2022年3月1日起施行。"}],"huanjingbaohufaguijieshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范环境保护法律、行政法规和部门规章的解释工作(以下简称“法规解释”)，根据《全国人民代表大会常务委员会关于加强法律解释工作的决议》和《国务院办公厅关于行政法规解释权限和程序问题的通知》有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"环境保护法律的条文本身需要进一步明确界限或者作出补充规定的问题，按照《全国人民代表大会常务委员会关于加强法律解释工作的决议》办理。 环境保护行政法规的条文本身需要进一步明确界限或者作出补充规定的问题，按照《国务院办公厅关于行政法规解释权限和程序问题的通知》办理。"},{"i":3,"n":"第三条","txt":"环境保护法律、行政法规具体适用的问题，部门规章理解和执行中的问题，以及环境保护法律、行政法规授权国务院环境保护行政主管部门解释的问题，由国家环境保护总局解释。"},{"i":4,"n":"第四条","txt":"国家环境保护总局公布的法规解释，具有普遍执行的效力，可作为各级环境保护行政主管部门和其他依照法律规定行使环境保护监督管理权的部门的执法依据，可以在有关环境法律文书中直接引用。"},{"i":5,"n":"第五条","txt":"国家环境保护总局对地方各级环境保护行政主管部门执行国家环境法规解释的情况进行监督，发现执行国家环境法规解释的具体行政行为与解释相违背的，责成其改正或者依法予以撤销。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，国家环境保护总局应当作出法规解释： (一)地方环境保护行政主管部门向国家环境保护总局提出法规解释请示的； (二)其他国家机关建议或者商请国家环境保护总局作出法规解释的； (三)国家环境保护总局根据环境行政执法工作的实际情况，认为需要作出法规解释的； (四)需要作出法规解释的其他情形。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市环境保护行政主管部门（以下简称省级环境保护行政主管部门）在报请国家环境保护总局作出法规解释时，除提出请示解释的问题外，应当同时提出本部门的意见，并附送有关本案的主要背景材料。报请国家环境保护总局作出法规解释的请示，应当一事一请示。"},{"i":8,"n":"第八条","txt":"省级环境保护行政主管部门报请国家环境保护总局作出法规解释，应当以正式文件提出请示，以其他形式提出的请示，不作为办理法规解释的依据。"},{"i":9,"n":"第九条","txt":"省级以下的地方环境保护行政主管部门认为需要报请国家环境保护总局作出法规解释的，应当按程序报省级环境保护行政主管部门审核决定，并由省级环境保护行政主管部门向国家环境保护总局提出请示；因特殊情况必须越级请示的，应当抄送被越过的上级环境保护行政主管部门。"},{"i":10,"n":"第十条","txt":"国家环境保护总局法规部门管理和组织办理法规解释。 国家环境保护总局有关司(办)配合法规部门办理涉及其职责范围的法规解释。"},{"i":11,"n":"第十一条","txt":"法规解释按照以下程序进行： (一)根据本办法第六条所列情形，法规部门确定法规解释项目； (二)法规部门组织研究提出法规解释草案，涉及核安全法规解释的问题，由总局核安全部门提出解释草案； (三)法规部门组织论证，必要时可征求国家有关机关的意见，提出法规解释送审稿； (四)按照程序将解释送审稿报总局局长签发。"},{"i":12,"n":"第十二条","txt":"对已经确定的法规解释项目，应当在两个月内完成。 对于重大和复杂问题的解释，时限可以适当延长。"},{"i":13,"n":"第十三条","txt":"法规解释文件分别使用以下形式： (一)对环境保护法律、行政法规的解释，以国家环境保护总局文件的形式作出； (二)对环境保护部门规章的解释，以国家环境保护总局函的形式作出。"},{"i":14,"n":"第十四条","txt":"国家环境保护总局作出的法规解释，除发送提出请示的部门外，可视情况在全国公开发行的主要环境报刊上公布，必要时抄送国家有关机关。"},{"i":15,"n":"第十五条","txt":"国家环境保护总局和原国家环境保护局作出的法规解释，如与新颁布的环境保护法律、行政法规或者部门规章不一致的，原已作出的法规解释自动失效。"},{"i":16,"n":"第十六条","txt":"国家环境保护总局应适时对法规解释文件进行清理。对需要修改、补充或者废止的法规解释，参照本办法有关制定解释的程序办理。"},{"i":17,"n":"第十七条","txt":"环境保护国家标准、行业标准由国家环境保护总局负责解释，并由总局标准部门参照本办法规定的程序组织办理。"},{"i":18,"n":"第十八条","txt":"地方环境保护行政主管部门请示或者其他国家机关建议国家环境保护总局解释的问题，如不属于环境保护法规解释的范围，由有关司(办)按职责分工办理。"},{"i":19,"n":"第十九条","txt":"环境保护地方性法规、地方政府规章和地方标准的解释，由地方环境保护行政主管部门按规定的权限，参照本办法办理。"},{"i":20,"n":"第二十条","txt":"本办法自发布之日起施行。"}],"huanjingyingxiangpingjiashenchazhuanjiakuguanliban25c98a":[{"i":1,"n":"第一条","txt":"为了加强对环境影响评价审查专家库的管理，保证审查活动的公平、公正，根据《中华人民共和国环境影响评价法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于环境影响评价审查专家库（以下简称专家库）的设立和管理。"},{"i":3,"n":"第三条","txt":"专家库分为国家库和地方库。 国家库由生态环境部设立和管理。地方库由设区的市级以上地方人民政府环境保护行政主管部门设立和管理。"},{"i":4,"n":"第四条","txt":"专家库应当具备下列条件： （一）满足环境影响评价审查的专家专业、行业分类； （二）具备随机抽取专家的必要设施和管理系统软件；"},{"i":5,"n":"第五条","txt":"入选专家库的专家，应当具备下列条件： （一）在本专业或者本行业有较深造诣，熟悉本专业或者本行业的国内外情况和动态； （二）坚持原则，作风正派，能够认真、客观公正、廉洁地履行职责； （三）熟悉国家有关法律、法规和政策，掌握环境影响评价审查技术规范和要求； （四）具有高级专业技术职称，从事相关专业领域工作五年以上； （五）身体健康，能够承担审查工作。"},{"i":6,"n":"第六条","txt":"专家入选专家库，采取个人申请或者单位推荐方式向设立专家库的环境保护行政主管部门（以下简称设立部门）提出申请。采取推荐方式的，单位应当事先征得被推荐人同意。 个人申请书和单位推荐书应当附有符合本办法规定条件的证明材料。"},{"i":7,"n":"第七条","txt":"设立部门应当公布专家库入选需求信息与条件；对申请人或者被推荐人进行遴选，根据需要征求有关行业主管部门及其他有关部门或者专家的意见；对符合条件的申请人或者被推荐人，决定入选专家库，并予以公布。 对特殊需要的专家，经设立部门认可，可直接入选专家库。"},{"i":8,"n":"第八条","txt":"确定参加专项规划环境影响报告书审查小组的专家，应当根据所涉及的专业、行业，从专家库内的专家名单中随机抽取。"},{"i":9,"n":"第九条","txt":"参加审查小组的专家应当本着科学求实和负责的态度认真履行职责，在规定的期限内客观、公正地提出审查意见，并对审查结论负责。 参加审查小组的专家与为环境影响评价提供技术服务的机构存在利益关系，可能影响审查公正性的情况时，应当主动提出回避。"},{"i":10,"n":"第十条","txt":"参加审查小组的专家有权根据审查小组的分工和要求，独立发表意见，不受任何单位或者个人的干预。"},{"i":11,"n":"第十一条","txt":"设立部门应当为入选专家库的专家建立档案。 设立部门应对专家库实行动态管理，每2年进行一次调整，并公布调整结果。"},{"i":12,"n":"第十二条","txt":"入选专家库的专家有下列情形之一的，由设立部门予以警告；情节严重的，取消其入选专家库资格，并予以公告： （一）不负责任，弄虚作假，或者其他不客观、公正履行审查职责的； （二）无正当理由，不按要求参加审查工作两次以上的； （三）与为环境影响评价提供技术服务的机构存在利益关系，可能影响审查公正性的情况，未主动提出回避的； （四）泄露在审查过程中知悉的技术秘密、商业秘密以及其他不宜公开的情况的； （五）收受他人的财物或者其他好处的，影响客观、公正履行审查职责的。 有前款规定情形，违反国家有关法律、行政法规的，依法追究法律责任。"},{"i":13,"n":"第十三条","txt":"本办法自2003年9月1日起施行。"}],"dianliyewuxukezhengguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强电力业务许可证的管理，规范电力业务许可行为，维护电力市场秩序，保障电力系统安全、优质、经济运行，根据《中华人民共和国行政许可法》、《电力监管条例》和有关法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于电力业务许可证的申请、受理、审查、决定和管理。国家另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"国家电力监管委员会(以下简称电监会)负责电力业务许可证的颁发和管理。 电监会遵循依法、公开、公正、便民、高效的原则，建立电力业务许可证监督管理制度和组织管理体系。"},{"i":4,"n":"第四条","txt":"在中华人民共和国境内从事电力业务，应当按照本规定取得电力业务许可证。除电监会规定的特殊情况外，任何单位或者个人未取得电力业务许可证，不得从事电力业务。 本规定所称电力业务，是指发电、输电、供电业务。其中，供电业务包括配电业务和售电业务。"},{"i":5,"n":"第五条","txt":"取得电力业务许可证的单位(以下简称被许可人)按照本规定享有权利、承担义务，接受电监会及其派出机构(以下简称电力监管机构)的监督管理。被许可人依法开展电力业务，受法律保护。"},{"i":6,"n":"第六条","txt":"任何单位和个人不得伪造、变造电力业务许可证;被许可人不得涂改、倒卖、出租、出借电力业务许可证，或者以其他形式非法转让电力业务许可。"},{"i":7,"n":"第七条","txt":"电力业务许可证分为发电、输电、供电三个类别。 从事发电业务的，应当取得发电类电力业务许可证。 从事输电业务的，应当取得输电类电力业务许可证。 从事供电业务的，应当取得供电类电力业务许可证。 从事两类以上电力业务的，应当分别取得两类以上电力业务许可证。 从事配电或者售电业务的许可管理办法，由电监会另行规定。"},{"i":8,"n":"第八条","txt":"下列从事发电业务的企业应当申请发电类电力业务许可证： (一)公用电厂; (二)并网运行的自备电厂; (三)电监会规定的其他企业。"},{"i":9,"n":"第九条","txt":"下列从事输电业务的企业应当申请输电类电力业务许可证： (一)跨区域经营的电网企业; (二)跨省、自治区、直辖市经营的电网企业; (三)省、自治区、直辖市电网企业; (四)电监会规定的其他企业。"},{"i":10,"n":"第十条","txt":"下列从事供电业务的企业应当申请供电类电力业务许可证： (一)省辖市、自治州、盟、地区供电企业; (二)县、自治县、县级市供电企业; (三)电监会规定的其他企业。"},{"i":11,"n":"第十一条","txt":"申请电力业务许可证的，应当具备下列基本条件： (一)具有法人资格; (二)具有与申请从事的电力业务相适应的财务能力; (三)生产运行负责人、技术负责人、安全负责人和财务负责人具有3年以上与申请从事的电力业务相适应的工作经历，具有中级以上专业技术任职资格或者岗位培训合格证书; (四)法律、法规规定的其他条件。"},{"i":12,"n":"第十二条","txt":"申请发电类电力业务许可证的，除具备本规定第十一条所列基本条件外，还应当具备下列条件： (一)发电项目建设经有关主管部门审批或者核准; (二)发电设施具备发电运行的能力; (三)发电项目符合环境保护的有关规定和要求。"},{"i":13,"n":"第十三条","txt":"申请输电类电力业务许可证的，除具备本规定第十一条所列基本条件外，还应当具备下列条件： (一)输电项目建设经有关主管部门审批或者核准; (二)具有与申请从事的输电业务相适应的输电网络; (三)输电项目按照有关规定通过竣工验收; (四)输电项目符合环境保护的有关规定和要求。"},{"i":14,"n":"第十四条","txt":"申请供电类电力业务许可证的，除具备本规定第十一条所列基本条件外，还应当具备下列条件： (一)具有经有关主管部门批准的供电营业区; (二)具有与申请从事供电业务相适应的供电网络和营业网点; (三)承诺履行电力社会普遍服务义务; (四)供电项目符合环境保护的有关规定和要求。"},{"i":15,"n":"第十五条","txt":"申请电力业务许可证，应当向电监会提出，并按照规定的要求提交申请材料。"},{"i":16,"n":"第十六条","txt":"本规定第八条、第九条、第十条所列企业，具有法人资格的，由本企业提出申请;不具有法人资格的，按照隶属关系由其法人企业提出申请。"},{"i":17,"n":"第十七条","txt":"申请电力业务许可证的，应当提供下列材料： (一)法定代表人签署的许可证申请表; (二)法人营业执照副本及其复印件; (三)企业最近2年的年度财务报告;成立不足2年的，出具企业成立以来的年度财务报告; (四)由具有合格资质的会计师事务所出具的最近2年的财务状况审计报告和对营运资金状况的说明;成立不足2年的，出具企业成立以来的财务状况审计报告和对营运资金状况的说明; (五)企业生产运行负责人、技术负责人、安全负责人、财务负责人的简历、专业技术任职资格证书等有关证明材料。"},{"i":18,"n":"第十八条","txt":"申请发电类电力业务许可证的，除提供本规定第十七条所列材料外，还应当提供下列材料： (一)发电项目建设经有关主管部门审批或者核准的证明材料; (二)发电项目通过竣工验收的证明材料;尚未组织竣工验收的，提供发电机组通过启动验收的证明材料或者有关主管部门认可的质量监督机构同意整套启动的质量监督检查报告; (三)发电项目符合环境保护有关规定和要求的证明材料。"},{"i":19,"n":"第十九条","txt":"申请输电类电力业务许可证的，除提供本规定第十七条所列材料外，还应当提供下列材料： (一)输电项目建设经有关主管部门审批或者核准的证明材料; (二)输电项目通过竣工验收的证明材料; (三)输电项目符合环境保护有关规定和要求的证明材料; (四)电能质量和服务质量承诺书。"},{"i":20,"n":"第二十条","txt":"申请供电类电力业务许可证的，除提供本规定第十七条所列材料外，还应当提供下列材料： (一)供电营业区域的证明材料及其地理平面图; (二)供电网络分布概况; (三)设立的供电营业分支机构及其相应的供电营业区域概况; (四)履行电力社会普遍服务义务的承诺书; (五)供电项目符合环境保护有关规定和要求的证明材料。"},{"i":21,"n":"第二十一条","txt":"电监会对申请人提出的许可申请，应当根据下列情况分别作出处理： (一)申请事项不属于电监会职权范围,应当即时作出不予受理的决定,向申请人发出《不予受理通知书》，并告知申请人向有关行政机关申请; (二)申请材料存在可以当场更正的错误的，应当允许申请人当场更正; (三)申请材料不齐全或者不符合法定形式的，应当当场或者在5日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理; (四)申请材料齐全、符合法定形式的，向申请人发出《受理通知书》。"},{"i":22,"n":"第二十二条","txt":"电监会应当对申请人提交的申请材料进行审查。 电监会根据需要，可以对申请材料的实质内容进行核实。"},{"i":23,"n":"第二十三条","txt":"电监会作出电力业务许可决定，依法需要举行听证的，应当按照有关规定举行听证。"},{"i":24,"n":"第二十四条","txt":"电监会应当自受理申请之日起20日内作出许可决定。20日内不能作出决定的，经本机关负责人批准，可以延长10日，并将延长期限的理由告知申请人。 作出准予许可决定的，自作出决定之日起10日内向申请人颁发、送达许可证。 作出不予许可决定的，自作出决定之日起10日内以书面形式通知申请人，说明不予许可的理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":25,"n":"第二十五条","txt":"电力业务许可证由正文和附页组成。 正文载明许可证编号、登记名称、住所、法定代表人、许可类别、有效期限、发证机关、发证日期等内容。 附页包括许可证使用规定，被许可人的权利和义务，发电机组、输电网络或者供电营业区情况登记，检查情况记录，特别规定事项等内容。 电力业务许可证的有效期为20年。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，被许可人应当在规定时限内向电监会提出变更申请;经审查符合法定条件的，电监会应当依法办理变更手续： (一)新建、改建发电机组投入运营，取得或者转让已运营的发电机组，发电机组退役; (二)新建、改建输电线路或者变电设施投入运营，终止运营输电线路或者变电设施; (三)供电营业区变更。"},{"i":27,"n":"第二十七条","txt":"因新建、改建发电机组投入运营，申请变更许可事项的，应当提供下列材料： (一)变更申请表; (二)电力业务许可证; (三)发电项目建设经有关主管部门审批或者核准的证明材料; (四)有关主管部门认可的质量监督机构同意整套启动的质量监督检查报告; (五)发电项目符合环境保护有关规定和要求的证明材料。 因取得或者转让已运营机组，申请变更许可事项的，除提供前款第(一)项、第(二)项所列材料外，还应当提供机组所有权合法转移的证明材料。 因机组退役，申请变更许可事项的，除提供本条第一款第(一)项、第(二)项所列材料外，还应当提供机组退役符合国家有关规定的证明材料。"},{"i":28,"n":"第二十八条","txt":"因新建、改建输电线路或者变电设施投入运营，申请变更许可事项的，应当提供下列材料： (一)变更申请表; (二)电力业务许可证; (三)输电项目建设经有关主管部门审批或者核准的证明材料; (四)输电项目通过竣工验收的证明材料; (五)输电项目符合环境保护有关规定和要求的证明材料。 因终止运营输电线路或者变电设施，申请变更许可事项的，除提供前款第(一)项、第(二)项所列材料外，还应当提供有关主管部门批准终止运营输电线路或者变电设施的证明材料。"},{"i":29,"n":"第二十九条","txt":"因供电营业区变更，申请变更许可事项的，应当提供下列材料： (一)变更申请表; (二)电力业务许可证; (三)供电营业区变更的证明材料; (四)供电营业区变更的范围图例。"},{"i":30,"n":"第三十条","txt":"电力业务许可证有效期届满需要延续的，被许可人应当在有效期届满30日前向电监会提出申请。 电监会应当在电力业务许可证有效期届满前作出是否准予延续的决定。逾期未作出决定的，视为同意延续并补办相应手续。"},{"i":31,"n":"第三十一条","txt":"电力监管机构建立健全电力业务许可监督检查体系和制度，对被许可人按照电力业务许可证确定的条件、范围和义务从事电力业务的情况进行监督检查。 电力监管机构依法开展监督检查工作，被许可人应当予以配合。"},{"i":32,"n":"第三十二条","txt":"被许可人应当按照规定的时间，向电力监管机构提供反映其从事许可事项活动能力和行为的材料。 电力监管机构应当对被许可人所报送的材料进行核查，将核查结果予以记录;对核查中发现的问题，应当责令限期改正。"},{"i":33,"n":"第三十三条","txt":"电力监管机构依法对被许可人进行现场检查。检查中发现被许可人有违反本规定和不履行电力业务许可证规定义务的行为，应当责令其改正。"},{"i":34,"n":"第三十四条","txt":"电力监管机构进行监督检查工作的人员应当如实记录监督检查情况和处理结果。 电力监管机构可以将监督检查情况和处理结果向社会公布。"},{"i":35,"n":"第三十五条","txt":"任何组织和个人发现违反本规定的行为，有权向电力监管机构举报，电力监管机构应当进行核实，按照有关规定予以处理。"},{"i":36,"n":"第三十六条","txt":"未经电监会批准，取得输电类或者供电类电力业务许可的企业不得擅自停业、歇业。"},{"i":37,"n":"第三十七条","txt":"被许可人名称、住所或者法定代表人发生变化的，应当自变化之日起30日内到电监会办理相关手续。"},{"i":38,"n":"第三十八条","txt":"有下列情形之一的，电监会应当按照规定办理电力业务许可证的注销手续： (一)许可证有效期届满未延续的; (二)被许可人不再具有发电机组、输电网络或者供电营业区的; (三)被许可人申请停业、歇业被批准的; (四)被许可人因解散、破产、倒闭等原因而依法终止的; (五)电力业务许可证依法被吊销，或者电力业务许可被撤销、撤回的; (六)经核查，被许可人已丧失从事许可事项活动能力的; (七)法律、法规规定应当注销的其他情形。"},{"i":39,"n":"第三十九条","txt":"从事颁发和管理电力业务许可证的工作人员，违反法律、行政法规和本规定，擅自颁发电力业务许可证的，应当依法给予处分;构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"未依法取得电力业务许可证非法从事电力业务的，应当责令改正，没收违法所得，可以并处以违法所得5倍以下的罚款;构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"被许可人以欺骗、贿赂等不正当手段获得电力业务许可证的，应当给予警告，处以1万元以下的罚款;构成犯罪的，依法追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"被许可人超出许可范围或者超过许可期限，从事电力业务的，应当给予警告，责令改正，并向社会公告;构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"被许可人有下列情形之一的，应当给予警告，责令改正，并可向社会公告: (一)未经批准,擅自停业、歇业的; (二)未在规定的期限内申请变更的。"},{"i":44,"n":"第四十四条","txt":"被许可人有下列情形之一的，应当责令改正;拒不改正的，处以5万元以上50万元以下的罚款，对直接负责的主管人员和其他直接责任人员，依法给予处分;构成犯罪的，依法追究刑事责任： (一)拒绝或者阻碍电力监管工作人员依法履行监管职责的; (二)提供虚假或者隐瞒重要事实的文件、资料的。"},{"i":45,"n":"第四十五条","txt":"涂改、倒卖、出租、出借电力业务许可证或者以其他形式非法转让电力业务许可的，应当依法给予行政处罚;构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"本规定颁布实施前已经从事电力业务的企业，应当按照电监会规定的期限申请办理电力业务许可证。"},{"i":47,"n":"第四十七条","txt":"电力业务许可证由电监会统一印制和编号。"},{"i":48,"n":"第四十八条","txt":"本规定自2005年12月1日起施行。"}],"dianlishichangjianguanbanfa":[{"i":1,"n":"第一条","txt":"为了维护电力市场秩序，保证电力市场的统一、开放、竞争、有序，根据《电力监管条例》和有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内的电力市场监管。"},{"i":3,"n":"第三条","txt":"国家电力监管委员会(以下简称电监会)履行全国电力市场监管职责。 国家电力监管委员会区域监管局(以下简称区域电监局)负责辖区内电力市场监管工作。国家电力监管委员会城市监管办公室协助区域电监局从事电力市场监管工作。"},{"i":4,"n":"第四条","txt":"电力市场监管依法进行，并遵循公开、公正和效率的原则。"},{"i":5,"n":"第五条","txt":"电力市场主体、电力调度交易机构应当自觉遵守有关电力市场的法规、规章。"},{"i":6,"n":"第六条","txt":"任何单位和个人对违反本规定的行为有权向电力监管机构举报，电力监管机构应当及时处理，并为举报人保密。"},{"i":7,"n":"第七条","txt":"电力市场监管的对象包括电力市场主体和电力调度交易机构。电力市场主体包括按照有关规定取得电力业务许可证的发电企业、输电企业、供电企业，以及经电力监管机构核准的用户。电力调度交易机构包括区域电力调度交易中心和省、自治区、直辖市电力调度机构。 前款所称供电企业包括独立配售电企业;前款所称区域电力调度交易中心包括区域电力调度中心、区域电力交易中心。"},{"i":8,"n":"第八条","txt":"电力监管机构对电力市场主体和电力调度交易机构的下列情况实施监管： (一)履行电力系统安全义务的情况; (二)进入和退出电力市场的情况; (三)参与电力市场交易资质的情况; (四)执行电力市场运行规则的情况; (五)进行交易和电费结算情况; (六)披露信息的情况; (七)执行国家标准、行业标准的情况; (八)平衡资金账户管理和资金使用情况。"},{"i":9,"n":"第九条","txt":"除本办法第八条所列情况外，电力监管机构还对发电企业的下列情况实施监管： (一)在各电力市场中所占份额的比例; (二)新增装机、兼并、重组、股权变动或者租赁经营的情况; (三)不正当竞争、串通报价和违规交易行为; (四)执行调度指令的情况; (五)执行与用户签订的有关合同的情况。"},{"i":10,"n":"第十条","txt":"除本办法第八条所列情况外，电力监管机构还对输电企业的下列情况实施监管： (一)公平、无歧视开放电网和提供输电服务的情况; (二)电网互联的情况; (三)所属发电企业的发电情况; (四)执行输电价格的情况; (五)对有偿辅助服务补偿的情况。"},{"i":11,"n":"第十一条","txt":"除本办法第八条所列情况外，电力监管机构还对供电企业的下列情况实施监管： (一)执行配电价格、售电价格的情况; (二)按照国家规定的电能质量和供电服务质量标准向用户提供供电服务的情况。"},{"i":12,"n":"第十二条","txt":"除本办法第八条所列情况外，电力监管机构还对电力调度交易机构的下列情况实施监管： (一)公开、公平、公正地实施电力调度的情况; (二)执行电力调度规则的情况; (三)按照电力市场运营规则组织电力市场交易的情况; (四)对电力市场实施干预的情况; (五)对电力市场技术支持系统的建设、维护、运营和管理的情况; (六)执行市场限价的情况。"},{"i":13,"n":"第十三条","txt":"电力监管机构对用户履行与发电企业签订的有关合同的情况进行监管。"},{"i":14,"n":"第十四条","txt":"电力监管机构负责制定并组织实施电力市场运营规则。电力市场运营规则包括电力市场运营基本规则、区域电力市场运营规则和与区域电力市场运营规则相配套的相关细则。"},{"i":15,"n":"第十五条","txt":"电监会制定电力市场运营基本规则;区域电监局拟定区域电力市场运营规则，报电监会批准后执行;区域电监局制定与区域电力市场运营规则配套的有关细则，报电监会备案。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，电力监管机构应当修改电力市场运营规则： (一)法律或者国家政策发生重大调整的; (二)电力市场运行环境发生重大变化的; (三)电力市场主体或者电力调度交易机构提出修改的意见和建议，电力监管机构认为确有必要的; (四)电力监管机构认为必要的其他情形。"},{"i":17,"n":"第十七条","txt":"电力监管机构制定或者修改电力市场运营规则，应当充分听取电力市场主体、电力调度交易机构、相关利益主体和社会有关方面的意见。"},{"i":18,"n":"第十八条","txt":"电力市场实行注册管理制度。进入或者退出电力市场应当办理相应的注册手续。电力调度交易机构具体负责电力市场注册管理工作。"},{"i":19,"n":"第十九条","txt":"电力市场主体进入电力市场，应当向电力调度交易机构提出注册申请。经过批准后，方可参与电力市场交易。电力市场主体申请进入注册应当符合下列条件： (一)取得电力业务许可证并在工商行政管理部门登记、注册; (二)承诺遵守电力市场运营的法律法规并履行电力市场主体的责任和义务; (三)具有符合电力市场要求的技术条件。"},{"i":20,"n":"第二十条","txt":"电力市场主体申请进入注册应当提供与申请事项有关的经济、技术、安全等信息。"},{"i":21,"n":"第二十一条","txt":"电力市场主体变更注册或者撤销注册，应当按照区域电力市场运营规则的规定，向电力调度交易机构提出书面申请。经过批准后，方可变更或者撤销注册。"},{"i":22,"n":"第二十二条","txt":"电力调度交易机构应当按照电力市场运营规则规定的程序和时限，办理注册手续。注册审核情况应当向电力市场主体公布并报电力监管机构备案。"},{"i":23,"n":"第二十三条","txt":"电力调度交易机构为保证电力市场安全运营，依据电力市场运营规则，可以进行市场干预。电力调度交易机构进行市场干预应当向电力市场主体公布干预原因。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，电力调度交易机构可以进行市场干预： (一)电力系统出力不足，无法保证电力市场正常运行的; (二)电力系统内发生重大事故危及电网安全的; (三)电力市场技术支持系统、自动化系统、数据通信系统等发生故障导致交易无法正常进行的; (四)电力监管机构做出中止电力市场决定的; (五)电力监管机构规定的其他情形。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，电力监管机构可以做出中止电力市场的决定，并向电力市场主体公布中止原因： (一)电力市场未按照规则运行和管理的; (二)电力市场运营规则不适应电力市场交易需要，必须进行重大修改的; (三)电力市场交易发生恶意串通操纵市场的行为，并严重影响交易结果的; (四)电力市场技术支持系统、自动化系统、数据通信系统等发生重大故障，导致交易长时间无法进行的; (五)因不可抗力不能竞价交易的; (六)电力监管机构规定的其他情形。"},{"i":26,"n":"第二十六条","txt":"干预或者中止电力市场时，电力市场交易的方式按照区域电力市场运营规则执行。"},{"i":27,"n":"第二十七条","txt":"干预或者中止电力市场期间，电力调度交易机构应当采取措施保证电力系统安全，记录干预或者中止过程，并向电力监管机构报告。电力监管机构应当向电力市场主体公布干预或中止过程。"},{"i":28,"n":"第二十八条","txt":"电力市场主体之间、电力市场主体与电力调度交易机构之间因电力市场交易发生争议，由电力监管机构依法协调或者裁决。其中，因履行合同发生的争议，可以由电力监管机构按照电力争议调解的有关规定进行调解。"},{"i":29,"n":"第二十九条","txt":"电力市场主体、电力调度交易机构对电力监管机构的处理决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":30,"n":"第三十条","txt":"电力监管机构按照电力监管信息公开的有关规定向电力投资者、经营者、使用者和社会公众公开电力市场监管信息。"},{"i":31,"n":"第三十一条","txt":"电力市场主体、电力调度交易机构应当按照有关规定，及时、真实、准确和完整地披露有关信息。"},{"i":32,"n":"第三十二条","txt":"电力监管机构、电力市场主体、电力调度交易机构不得泄露影响公平竞争的交易秘密。"},{"i":33,"n":"第三十三条","txt":"电力监管机构从事监管工作的人员违反有关规定的，按照《电力监管条例》第二十九条的规定处理。"},{"i":34,"n":"第三十四条","txt":"电力市场主体违反本办法规定，有下列情形之一的，按照《电力监管条例》第三十一条的规定处理： (一)未按照规定办理电力市场注册手续的; (二)提供虚假注册资料的; (三)未履行电力系统安全义务的; (四)有关设备、设施不符合国家标准、行业标准的; (五)行使市场操纵力的; (六)有不正当竞争、串通报价等违规交易行为的; (七)不执行调度指令的; (八)发电厂并网、电网互联不遵守有关规章、规则的。"},{"i":35,"n":"第三十五条","txt":"供电企业未按照国家规定的电能质量和供电服务质量标准向用户提供供电服务的，按照《电力监管条例》第三十二条的规定处理。"},{"i":36,"n":"第三十六条","txt":"电力调度交易机构违反本办法规定，有下列情形之一的，按照《电力监管条例》第三十三条的规定处理： (一)未按照规定办理电力市场注册的; (二)未按照电力市场运行规则组织电力市场交易的; (三)未按照规定公开、公平、公正地实施电力调度的; (四)未执行电力调度规则的; (五)未按照规定对电力市场进行干预的; (六)泄露电力交易内幕信息的。"},{"i":37,"n":"第三十七条","txt":"电力企业、电力调度交易机构未按照本办法和电力市场运行规则的规定披露有关信息的，按照《电力监管条例》第三十四条的有关规定处理。"},{"i":38,"n":"第三十八条","txt":"电力业务许可证制度实施以前，电力企业进入电力市场的资格，由电力监管机构审查批准。"},{"i":39,"n":"第三十九条","txt":"区域电监局应当根据本办法制定实施办法，报电监会批准后实施。"},{"i":40,"n":"第四十条","txt":"本办法自2005年12月1日起施行。国家电力监管委员会2003年7月24日公布的《电力市场监管办法(试行)》同时废止。"}],"dianlishichangyunyingjibenguize":[{"i":1,"n":"第一条","txt":"为了规范电力市场行为，依法维护电力市场主体的合法权益，保证电力市场的统一、开放、竞争、有序，根据《电力监管条例》和有关法律、行政法规，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则适用于区域电力市场。"},{"i":3,"n":"第三条","txt":"国家电力监管委员会及其派出机构(以下简称电力监管机构)负责区域电力市场运营的监督管理。"},{"i":4,"n":"第四条","txt":"电力市场主体包括按照有关规定取得电力业务许可证的发电企业、输电企业、供电企业，以及经电力监管机构核准的用户。电力调度交易机构包括区域电力调度交易中心和省、自治区、直辖市电力调度机构。 前款所称供电企业包括独立配售电企业;前款所称区域电力调度交易中心包括区域电力调度中心、区域电力交易中心。"},{"i":5,"n":"第五条","txt":"发电企业、输电企业和供电企业按照有关规定取得电力业务许可证后，方可申请进入区域电力市场，参与区域电力市场交易。用户经电力监管机构核准后，可以参与区域电力市场交易。"},{"i":6,"n":"第六条","txt":"电力调度交易机构负责电力调度、电力市场交易、计量结算。"},{"i":7,"n":"第七条","txt":"电力市场交易类型包括电能交易、输电权交易、辅助服务交易等。"},{"i":8,"n":"第八条","txt":"电能交易按照合约交易、现货交易、期货交易等方式进行。 电能合约交易，是指电力市场主体通过签订电能买卖合同进行的电能交易。电能买卖合同约定的电价，可以由双方协商形成、通过市场竞价产生或者按照国家有关规定确定。 电能现货交易，是由发电企业通过市场竞价产生的次日或者未来24小时的电能交易，以及为保证电力供需的即时平衡而组织的实时电能交易。 电能期货交易，是指电力市场主体在规定的交易场所通过签订期货合同进行的电能交易。电能期货合同是指在确定的将来某时刻按照确定的价格购买或者出售电能的协议。 电能交易以合约交易为主、现货交易为辅，适时进行期货交易。"},{"i":9,"n":"第九条","txt":"电力市场具备规定的条件，并经电力监管机构批准，可以进行输电权交易、辅助服务交易等。"},{"i":10,"n":"第十条","txt":"电能合约交易可以由电力调度交易机构具体组织实施，也可以由电力市场主体双方协商进行。"},{"i":11,"n":"第十一条","txt":"电力调度交易机构按照区域电力市场运营规则对合约电量进行分解，其分解方法应当对电力市场主体公开。合约电量分解后因故需要修改的，电力调度交易机构应当及时向合约各方通报原因。"},{"i":12,"n":"第十二条","txt":"输电企业应当按照法律和国家政策的规定，优先与依法取得电力业务许可证的可再生能源发电企业签订合同，全额收购其上网电量。"},{"i":13,"n":"第十三条","txt":"电力调度交易机构应当按照区域电力市场运营规则组织电能现货交易。"},{"i":14,"n":"第十四条","txt":"发电企业进行电能现货交易，应当以单个机组为单位报价。经批准，同一发电厂的多个机组可以集中报价。由多个发电厂组成的发电企业不得集中报价。禁止发电企业串通报价。"},{"i":15,"n":"第十五条","txt":"电力市场价格形成机制应当有利于促进电力市场公平有效竞争、有利于输电阻塞管理。"},{"i":16,"n":"第十六条","txt":"所有电能交易必须通过电力调度交易机构安全校核后执行。"},{"i":17,"n":"第十七条","txt":"输电企业应当公平开放输电网，为电力市场主体提供安全、优质、经济的输电服务。"},{"i":18,"n":"第十八条","txt":"输电企业应当严格执行国家规定的输电电价，并接受电力监管机构的监督检查。"},{"i":19,"n":"第十九条","txt":"输电阻塞管理方法由电力监管机构根据电网结构和电力市场交易方式确定。"},{"i":20,"n":"第二十条","txt":"电力市场因规避输电阻塞风险的需要，经电力监管机构批准，可以组织开展输电权交易。"},{"i":21,"n":"第二十一条","txt":"电力市场主体应当按照有关规定提供用以维护电压稳定、频率稳定和电网故障恢复等方面的辅助服务。"},{"i":22,"n":"第二十二条","txt":"辅助服务分为基本辅助服务和有偿辅助服务。 基本辅助服务是电力市场主体应当无偿提供的辅助服务。有偿辅助服务是电力市场主体在基本辅助服务之外提供的其它辅助服务。有偿辅助服务在电力市场建设初期采取补偿机制，电力市场健全以后实行竞争机制。"},{"i":23,"n":"第二十三条","txt":"辅助服务的具体内容、技术标准、提供方式、考核方式，由国家电力监管委员会会同国务院有关部门另行规定。"},{"i":24,"n":"第二十四条","txt":"电力调度交易机构应当定期对电力市场主体提供辅助服务的能力进行测试。测试结果应当公布并向电力监管机构报告。电力市场主体不能按照要求提供辅助服务时，应当及时向电力调度交易机构报告，并按照有关规定接受考核。"},{"i":25,"n":"第二十五条","txt":"电力市场主体应当安装符合国家标准的电能计量装置，由电能计量检测机构检定后投入使用。 本规则所称电能计量检测机构，是指经政府计量行政部门认可、电能交易双方确认的电能计量检测机构。"},{"i":26,"n":"第二十六条","txt":"电能计量检测机构对电能计量装置实行定期校核。电力市场主体可以申请校核电能计量装置，经校核，电能计量装置误差达不到规定精度的，由此发生的费用由该电能计量装置的产权方承担;电能计量装置误差达到规定精度的，由此发生的费用由申请方承担。"},{"i":27,"n":"第二十七条","txt":"电能交易双方签订的电能交易合同应当明确电能的计量点。电能计量点位于交易双方的产权分界点，产权分界点不能安装电能计量装置的，由双方协商确定电能计量点。法定或者约定的计量点计量的电能作为电费结算的依据。电力市场主体以计量点为分界承担电能损耗和相关责任。"},{"i":28,"n":"第二十八条","txt":"电力调度交易机构应当建立并维护电能计量数据库，并按照有关规定向电力市场主体公布相关的电能计量数据。"},{"i":29,"n":"第二十九条","txt":"电力市场结算包括电能合约交易结算、电能现货交易结算、电能期货交易结算、辅助服务结算以及补偿金、违约金结算。"},{"i":30,"n":"第三十条","txt":"电力市场主体应当按照区域电力市场运营规则规定的电费结算方式和期限结算电费。"},{"i":31,"n":"第三十一条","txt":"电力市场主体应当执行有关电网运行管理的规程、规定，服从统一调度，加强设备维护，按照并网协议配备必要的安全设施，提供辅助服务，维护电力系统的安全稳定运行。"},{"i":32,"n":"第三十二条","txt":"电力调度交易机构应当严格执行电力调度规则，合理安排系统运行方式，及时向电力市场主体预报或者通报影响电力系统安全运行的信息，防止电网事故，保障电网运行安全。"},{"i":33,"n":"第三十三条","txt":"电力调度交易机构负责电力市场交易的安全校核，并公布校核方法、参数。"},{"i":34,"n":"第三十四条","txt":"电力调度交易机构应当根据电力供需形势、设备运行状况、安全约束条件和系统运行状况，统筹安排电力设备检修计划。发电机组运行考核办法由电力监管机构审定，电力调度交易机构执行。"},{"i":35,"n":"第三十五条","txt":"电力市场技术支持系统建设应当符合规定的性能指标。电力市场技术支持系统包括能量管理、交易管理、电能计量、结算系统、合同管理、报价处理、市场分析与预测、交易信息、监管系统等功能模块。"},{"i":36,"n":"第三十六条","txt":"电力市场技术支持系统建设应当以电力市场运行规则为基础。在同一电力市场内，电力市场技术支持系统应当统一规划、统一设计、统一管理、同步实施、分别维护。电力市场技术支持系统应当根据电力市场发展的需要及时更新。电力监管机构审定电力市场技术支持系统规划和设计方案，电力市场主体按照规定配备有关配套设施并负责日常维护管理。"},{"i":37,"n":"第三十七条","txt":"国务院价格主管部门、国家电力监管委员会制定电力市场最高、最低限价，维护电力市场安全。"},{"i":38,"n":"第三十八条","txt":"电力监管机构根据维护电力市场正常运作和电力系统安全的需要，应当制定电力市场干预、中止办法，规定电力市场干预、中止的条件和相关处理方法。"},{"i":39,"n":"第三十九条","txt":"国务院有关部门、国家电力监管委员会在用户侧开放前，建立电价平衡机制，制定销售电价、上网电价联动的具体办法。"},{"i":40,"n":"第四十条","txt":"电力市场主体应当按照有关规定向电力调度交易机构提供信息。"},{"i":41,"n":"第四十一条","txt":"电力调度交易机构应当遵循及时、真实、准确、完整的原则，定期向电力市场主体和社会公众披露电力市场运行信息。"},{"i":42,"n":"第四十二条","txt":"电力监管机构制定电力市场信息发布管理办法并监督实施。"},{"i":43,"n":"第四十三条","txt":"电力业务许可证制度实施以前，电力企业进入电力市场的资格，由电力监管机构审查批准。"},{"i":44,"n":"第四十四条","txt":"国家电力监管委员会区域监管局根据本规则拟定区域电力市场运营规则，报国家电力监管委员会批准后执行。"},{"i":45,"n":"第四十五条","txt":"本规则自2005年12月1日起施行。国家电力监管委员会2003年7月24日公布的《电力市场运营基本规则(试行)》同时废止。"}],"dianlijianguanbaogaobianzhifabuguiding":[{"i":1,"n":"第一条","txt":"为了完善电力监管制度，加强电力监管，规范电力监管报告编制和发布行为，根据《电力监管条例》和国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称电力监管报告，是指国家电力监管委员会及其派出机构(以下简称电力监管机构)履行电力监管职责向社会公开发布的文书。 电力监管报告适用于电力监管机构公布电力企业、电力调度交易机构和其他有关单位(以下统称监管相对人)执行有关电力监管法律、法规、规章和其他规范性文件的情况，违反有关电力监管法律、法规、规章和其他规范性文件的行为以及电力监管机构的处理结果。"},{"i":3,"n":"第三条","txt":"编制电力监管报告应当依法进行，坚持实事求是、客观公正的原则。"},{"i":4,"n":"第四条","txt":"编制和发布电力监管报告，应当依法保守国家秘密和企业商业秘密，并充分考虑可能产生的社会影响。"},{"i":5,"n":"第五条","txt":"电力监管机构根据年度监管工作重点，制定电力监管报告年度计划。 电力监管报告年度计划由电力监管机构主席(局长、专员)办公会议决定。 电力监管报告年度计划应当明确电力监管报告的名称、起草单位、资料来源、完成时间等。 根据监管工作需要，经电力监管机构主席(局长、专员)批准，可以增加电力监管报告年度计划项目。"},{"i":6,"n":"第六条","txt":"电力监管报告包括下列基本内容： (一)标题，统一称为“××××××监管报告”; (二)监管依据，即实施监管所依据的有关电力监管法律、法规、规章和其他规范性文件的具体规定; (三)基本情况，包括监管相对人的基本情况和监管相对人执行有关电力监管法律、法规、规章和其他规范性文件具体规定的基本情况; (四)监管评价，即电力监管机构对监管相对人执行有关电力监管法律、法规、规章和其他规范性文件具体规定情况的评价意见; (五)存在的违法违规问题，监管机构的处理结果和整改要求; (六)监管建议，即对不属于电力监管机构直接处理的事项，可以向监管相对人或者政府有关部门提出建议。"},{"i":7,"n":"第七条","txt":"电力监管报告由具体实施监管的部门、单位起草。 起草单位起草电力监管报告，应当如实反映监管相对人执行有关电力监管法律、法规、规章和其他规范性文件具体规定的情况，不得隐瞒实施监管中发现的监管相对人违反有关电力监管法律、法规、规章和其他规范性文件具体规定的行为。 起草单位引用监管相对人有关具体事实的，应当与监管相对人核实;发现相关信息事实不清或者相互矛盾的，应当进行调查。"},{"i":8,"n":"第八条","txt":"监管相对人应当按照国家有关规定和电力监管机构的要求，及时提供有关文件、资料，并对有关文件、资料的真实性、完整性负责;配合和协助电力监管机构进行现场检查、电力事故调查、违法行为立案调查以及有关事实或者行为核查。"},{"i":9,"n":"第九条","txt":"电力监管报告内容涉及其他单位或者部门职责的，起草单位应当征求相关单位或者部门的意见。"},{"i":10,"n":"第十条","txt":"电力监管报告由电力监管机构主席(局长、专员)办公会议决定。 国家电力监管委员会派出机构编制的电力监管报告，涉及跨区域或者在全国有重大影响的事项的，应当报国家电力监管委员会批准。"},{"i":11,"n":"第十一条","txt":"电力监管报告以监管公告发布。 监管公告由电力监管机构主席(局长、专员)签署。 监管公告应当载明序号、编制单位、电力监管报告名称、发布日期。"},{"i":12,"n":"第十二条","txt":"电力监管报告可以通过下列形式向社会公开发布： (一)广播、电视; (二)报纸、杂志等出版物; (三)政府门户网站; (四)新闻发布会; (五)其他形式。"},{"i":13,"n":"第十三条","txt":"电力监管机构向社会公开发布电力监管报告形成的有关材料，应当按照有关规定整理归档。"},{"i":14,"n":"第十四条","txt":"电力监管机构工作人员在编制发布电力监管报告工作中有下列情形之一的，依法追究其责任： (一)有意隐瞒或者夸大事实的; (二)玩忽职守造成信息、数据严重失实的; (三)违反规定擅自对外公布报告内容的; (四)违反国家有关保密规定的。"},{"i":15,"n":"第十五条","txt":"监管相对人有下列情形之一的，依法追究其责任： (一)拒绝或者阻碍电力监管机构依法履行监管职责的; (二)提供虚假或者隐瞒重要事实的文件、资料的。"},{"i":16,"n":"第十六条","txt":"国家电力监管委员会派出机构发布监管报告，报国家电力监管委员会备案。"},{"i":17,"n":"第十七条","txt":"本规定自2007年5月10日起施行。"}],"dianlijianguanjigouxianchangjianchaguiding":[{"i":1,"n":"第一条","txt":"为了加强电力监管，规范电力监管机构现场检查行为，维护电力投资者、经营者、使用者的合法权益和社会公共利益，根据《电力监管条例》和有关法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于国家电力监管委员会及其派出机构(以下简称电力监管机构)进入电力企业或者电力调度交易机构的工作场所、用户的用电场所或者其他有关场所，对电力企业、电力调度交易机构、用户或者其他有关单位(以下简称被检查单位)遵守国家有关电力监管规定的情况进行检查。 电力监管机构进行电力事故调查、对涉嫌违法行为的立案调查、对有关事实或者行为的核查，法律、法规、规章另有规定的，从其规定。 国务院决定或者批准进行的专项检查，其范围、内容、时限和程序另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"电力监管机构进行现场检查应当统筹安排、注重实效。"},{"i":4,"n":"第四条","txt":"电力监管机构进行现场检查应当事先拟定现场检查方案，经电力监管机构负责人审核批准后，制作现场检查通知书。 现场检查方案应当包括检查依据、检查时间、检查对象、检查事项等内容。 现场检查通知书应当包括检查依据、检查时间安排、检查事项、检查人员名单、被检查单位配合和协助的事项等内容。"},{"i":5,"n":"第五条","txt":"电力监管机构应当事先将现场检查通知书的内容告知被检查单位。必要时，可以持现场检查通知书直接进行现场检查。 电力监管机构进行现场检查时，应当出具现场检查通知书。"},{"i":6,"n":"第六条","txt":"电力监管机构进行现场检查时，检查人员不得少于2人。 检查人员进行现场检查时，应当出示电力监管执法证;未出示电力监管执法证的，被检查单位有权拒绝检查。"},{"i":7,"n":"第七条","txt":"电力监管机构可以根据需要聘请具有相关专业知识的人员协助检查。"},{"i":8,"n":"第八条","txt":"被检查单位及其工作人员应当配合和协助电力监管机构进行现场检查。"},{"i":9,"n":"第九条","txt":"检查人员可以根据需要，询问被检查单位的工作人员，要求其对有关事项作出说明。询问时，检查人员不得少于2人。 被询问人应当客观、如实地向检查人员作出说明，不得隐瞒、捏造事实。 检查人员应当做好询问笔录。询问结束时，被询问人应当当场校核询问笔录并签字。"},{"i":10,"n":"第十条","txt":"检查人员根据需要可以查阅、复制与检查事项有关的文件、资料，对可能被转移、隐匿、损毁的文件、资料予以封存。 被检查单位应当按照检查人员的要求提供有关资料、文件。 检查人员查阅、复制有关文件、资料，应当办理相关手续并妥善保存。"},{"i":11,"n":"第十一条","txt":"检查人员进行现场检查时，发现被检查单位有违反国家有关电力监管规定的行为的，应当责令其当场改正或者限期改正，并制作笔录，由检查人员和被检查单位负责人签字确认。 责令限期改正的，被检查单位应当在规定的期限内提交限期改正的情况报告。逾期未改正的，电力监管机构可以继续进行现场检查。"},{"i":12,"n":"第十二条","txt":"现场检查结束后，检查人员应当向电力监管机构提交现场检查报告。现场检查报告应当包括现场检查的基本情况、基本结论以及有关问题的处理情况等内容。"},{"i":13,"n":"第十三条","txt":"现场检查结束后，电力监管机构应当及时向被检查单位反馈检查结果;必要时，可以按照有关规定向社会公开检查结果。"},{"i":14,"n":"第十四条","txt":"电力监管机构对现场检查中发现的违法行为，依法应当给予行政处罚的，按照有关规定给予行政处罚。"},{"i":15,"n":"第十五条","txt":"检查人员应当严肃执法、廉洁奉公。 检查人员有下列情形之一的，根据情节轻重，给予批评教育或者行政处分;构成犯罪的，依法追究刑事责任： (一)违反规定的程序进行现场检查的; (二)干预被检查单位正常的生产经营活动的; (三)利用检查工作为本人、亲友或者他人谋取利益的; (四)泄露检查工作中知悉的国家秘密、商业秘密、个人隐私的; (五)其他违反现场检查规定的行为。"},{"i":16,"n":"第十六条","txt":"被检查单位及其工作人员有下列情形之一的，按照《电力监管条例》第三十四条和国家有关规定处理： (一)拒绝或者阻碍检查人员依法履行监管职责的; (二)提供虚假或者隐瞒重要事实的文件、资料的。"},{"i":17,"n":"第十七条","txt":"本规定自2006年5月15日起施行。"}],"dianzizhengwudianzirenzhengfuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范电子政务电子认证服务行为，对电子政务电子认证服务机构实施监督管理，保障电子政务安全可靠，维护有关各方合法权益，根据《中华人民共和国密码法》、《中华人民共和国电子签名法》和《商用密码管理条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设立电子政务电子认证服务机构、提供电子政务电子认证服务及其监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称电子政务电子认证服务，是指采用商用密码技术为政务活动提供电子签名认证服务，保证电子签名的真实性和可靠性的活动。"},{"i":4,"n":"第四条","txt":"从事电子政务电子认证服务的机构，应当经国家密码管理局认定，依法取得电子政务电子认证服务机构资质。"},{"i":5,"n":"第五条","txt":"国家密码管理局对全国电子政务电子认证服务活动实施监督管理。 县级以上地方各级密码管理部门对本行政区域的电子政务电子认证服务活动实施监督管理。"},{"i":6,"n":"第六条","txt":"取得电子政务电子认证服务机构资质，应当符合下列条件： （一）具有企业法人或者事业单位法人资格； （二）具有与从事电子政务电子认证服务活动及其使用密码相适应的资金； （三）具有与从事电子政务电子认证服务活动及其使用密码相适应的运营场所； （四）具有在境内设置、符合国家有关密码标准的电子认证服务系统等设备设施； （五）具有30名以上与从事电子政务电子认证服务活动及其使用密码相适应的专业技术人员、运营管理人员、安全管理人员和客户服务人员等专业人员； （六）具有为政务活动提供长期电子政务电子认证服务的能力，包括持续保持财务状况良好、运营资金充足、设备设施稳定运行、专业人员队伍稳定，没有重大违法记录或者不良信用记录等； （七）具有保证电子政务电子认证服务活动及其使用密码安全运行的管理体系。"},{"i":7,"n":"第七条","txt":"申请电子政务电子认证服务机构资质，应当向国家密码管理局提出书面申请，向国家密码管理局委托进行受理的省、自治区、直辖市密码管理部门提交下列材料： （一）电子政务电子认证服务机构资质申请表； （二）法人资格证书； （三）资金情况，包括注册资本、资本结构、股权结构、运营资金保障等情况； （四）运营场所情况； （五）电子认证服务系统相关技术材料及相关设备清单，包括电子认证服务系统建设工作报告、技术工作报告、安全性设计报告、安全管理策略和规范、标准符合性自评估报告，相关软件、硬件清单及其符合国家有关安全标准的情况等； （六）专业人员情况； （七）为用户提供长期服务和质量保障能力说明及承诺； （八）电子政务电子认证服务及其使用密码安全管理体系建立情况，包括业务运营管理、电子认证服务系统运行管理、人员管理、档案管理、安全保密管理等管理体系建立情况。"},{"i":8,"n":"第八条","txt":"受国家密码管理局委托进行受理的省、自治区、直辖市密码管理部门自收到申请材料之日起5个工作日内，对申请材料进行形式审查，根据下列情况分别作出处理：申请材料齐全、符合规定形式的，应当受理行政许可申请并出具受理通知书；申请材料不齐全或者不符合规定形式的，应当当场或者在5个工作日内一次告知需要补正的全部内容；不予受理的，应当出具不予受理通知书并说明理由。"},{"i":9,"n":"第九条","txt":"国家密码管理局应当自行政许可申请受理之日起20个工作日内，对行政许可申请进行审查，并依法作出是否许可的决定。准予许可的，颁发《电子政务电子认证服务机构资质证书》，并予以公开；不予许可的，应当出具不予行政许可决定书，说明理由并告知申请人相关权利。 需要对申请人进行技术评审的，技术评审所需时间不计算在本条规定的期限内。国家密码管理局应当将所需时间书面告知申请人。"},{"i":10,"n":"第十条","txt":"国家密码管理局根据技术评审需要和专业要求，可以委托专业机构或者组织专家实施技术评审。 技术评审包括电子认证服务系统安全性审查，运营场所、设备设施、管理体系建设实地查勘，专业人员能力考核等。 专业机构和专家应当独立、公正、科学、诚信地开展技术评审活动，对技术评审结论的真实性、符合性负责，并承担相应法律责任。国家密码管理局应当对技术评审活动进行监督，建立责任追究机制。"},{"i":11,"n":"第十一条","txt":"外商投资电子政务电子认证服务，影响或者可能影响国家安全的，应当依法进行外商投资安全审查。"},{"i":12,"n":"第十二条","txt":"《电子政务电子认证服务机构资质证书》有效期5年，内容包括：获证机构名称、证书编号、有效期限、发证机关和发证日期等。 《电子政务电子认证服务机构资质证书》由正本和副本组成，正本、副本具有同等法律效力。 禁止转让、出租、出借、伪造、变造、冒用、租借《电子政务电子认证服务机构资质证书》。"},{"i":13,"n":"第十三条","txt":"电子政务电子认证服务机构应当在其网站和运营场所公布并及时更新其《电子政务电子认证服务机构资质证书》的机构名称、证书编号、有效期限、发证机关和发证日期等内容。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，电子政务电子认证服务机构应当自变更之日起30日内向国家密码管理局办理变更手续： （一）机构名称、住所、法定代表人发生变更； （二）机构注册资本、资本结构、股权结构、法人性质或者单位隶属关系发生变更； （三）电子认证服务系统等设备设施发生变化，影响或者可能影响电子政务电子认证服务使用密码安全； （四）新建、搬迁电子认证服务系统； （五）依法需要办理变更的其他事项。 电子政务电子认证服务机构发生变更的事项影响其符合资质认定条件和要求的，国家密码管理局根据申请人的实际情况，采取书面或者现场形式开展审查。需要进行技术评审的，依照本办法第十条规定对其开展技术评审。"},{"i":15,"n":"第十五条","txt":"电子政务电子认证服务机构资质有效期届满需要延续的，应当在有效期届满60日前向国家密码管理局提出书面申请。国家密码管理局根据申请人的实际情况，采取书面或者现场形式进行审查，并在电子政务电子认证服务机构资质有效期届满前作出是否准予延续的决定。"},{"i":16,"n":"第十六条","txt":"电子政务电子认证服务机构应当按照国家密码管理局公布的电子政务电子认证业务规则规范等要求，制定本机构的电子政务电子认证业务规则和相应的电子签名认证证书策略，在提供电子政务电子认证服务前予以公布，并向住所地省、自治区、直辖市密码管理部门备案。 电子政务电子认证业务规则和电子签名认证证书策略发生变更的，电子政务电子认证服务机构应当予以公布，并自公布之日起30日内向住所地省、自治区、直辖市密码管理部门备案。 电子政务电子认证服务机构应当保持本机构已公布的电子政务电子认证业务规则和电子签名认证证书策略的可访问性。"},{"i":17,"n":"第十七条","txt":"电子政务电子认证服务机构应当按照本机构公布的电子政务电子认证业务规则提供电子政务电子认证服务。"},{"i":18,"n":"第十八条","txt":"电子政务电子认证服务机构应当保证提供下列服务： （一）电子签名认证证书注册、签发、更新、撤销等生命周期管理服务； （二）电子签名认证证书信息查询服务； （三）电子签名认证证书状态查询服务； （四）电子签名认证证书使用支持服务； （五）其他与电子签名认证相关的服务。"},{"i":19,"n":"第十九条","txt":"电子政务电子认证服务机构签发的电子签名认证证书应当载明下列内容： （一）电子政务电子认证服务机构名称； （二）电子签名认证证书持有人名称； （三）电子签名认证证书序列号； （四）电子签名认证证书有效期； （五）电子签名认证证书对应的证书策略对象标识符； （六）电子签名制作数据对应的电子签名验证数据； （七）电子政务电子认证服务机构的电子签名； （八）国家密码管理局规定的其他内容。"},{"i":20,"n":"第二十条","txt":"电子政务电子认证服务机构应当保证电子签名认证证书内容在有效期内完整、准确，并保证电子签名依赖方能够证实或者了解电子签名认证证书所载内容及其他有关事项。"},{"i":21,"n":"第二十一条","txt":"电子签名人向电子政务电子认证服务机构申请电子签名认证证书，应当提供真实、完整和准确的信息。 电子政务电子认证服务机构受理电子签名认证证书申请时，应当对申请人的身份进行查验，对有关申请材料进行审查，并向申请人告知电子签名认证证书和电子签名的使用条件、电子签名所产生的法律责任、保存和使用电子签名认证证书持有人信息的权限和责任、电子政务电子认证服务机构和电子签名认证证书持有人的责任范围等事项。 电子政务电子认证服务机构受理电子签名认证证书申请后，应当与申请人签订电子政务电子认证服务协议，明确双方的权利义务。"},{"i":22,"n":"第二十二条","txt":"电子政务电子认证服务机构应当遵守国家有关密码管理要求，保障电子政务电子认证服务使用密码安全。 电子政务电子认证服务机构提供的电子政务电子认证服务应当纳入统一的电子认证信任体系，遵守电子认证服务互信互认要求。"},{"i":23,"n":"第二十三条","txt":"电子政务电子认证服务机构应当建立完善的保密制度，对其在工作中知悉的国家秘密、商业秘密和个人隐私承担保密义务，采取相应的技术措施和其他必要措施保护有关信息和数据安全。"},{"i":24,"n":"第二十四条","txt":"电子政务电子认证服务机构应当完整记录和保存与电子签名认证相关的信息，保证认证过程和结果具有可追溯性，信息保存期限至少为电子签名认证证书失效后5年。"},{"i":25,"n":"第二十五条","txt":"电子政务电子认证服务机构委托其他机构开展电子签名认证证书注册业务的，应当自委托协议签订之日起30日内将受委托开展电子签名认证证书注册业务的机构（以下简称受委托机构）名称、负责人，电子签名认证证书注册业务办理地址，委托事项等情况向受委托机构住所地省、自治区、直辖市密码管理部门备案。备案内容发生变更的，电子政务电子认证服务机构应当自变更之日起30日内向受委托机构住所地省、自治区、直辖市密码管理部门备案。 电子政务电子认证服务机构应当对受委托机构开展电子签名认证证书注册业务的行为进行监督，并对该行为的后果承担法律责任。 受委托机构在委托范围内，以委托其开展电子签名认证证书注册业务的电子政务电子认证服务机构名义开展电子签名认证证书注册业务，不得再委托其他机构或者个人开展电子签名认证证书注册业务。"},{"i":26,"n":"第二十六条","txt":"电子政务电子认证服务机构应当自行或者委托专业机构每年至少进行一次电子政务电子认证服务合规性评估，对评估中发现的问题及时进行整改，并向住所地省、自治区、直辖市密码管理部门报送合规性评估报告。"},{"i":27,"n":"第二十七条","txt":"电子政务电子认证服务机构应当建立和完善投诉处理机制，公布投诉方式，畅通投诉渠道，及时受理并妥善处理有关投诉事项。"},{"i":28,"n":"第二十八条","txt":"电子政务电子认证服务机构应当对本单位及受委托机构的从业人员进行岗位培训，建立培训制度，制定培训计划，加强考核并做好培训记录。"},{"i":29,"n":"第二十九条","txt":"电子政务电子认证服务机构拟暂停或者终止电子政务电子认证服务的，应当在暂停或者终止服务60日前向国家密码管理局报告，并与其他电子政务电子认证服务机构就业务承接进行协商，作出妥善安排。 电子政务电子认证服务机构未能就业务承接事项与其他电子政务电子认证服务机构达成协议的，应当申请国家密码管理局安排其他电子政务电子认证服务机构承接其业务。 电子政务电子认证服务机构被依法吊销电子政务电子认证服务机构资质的，其业务承接事项的处理按照国家密码管理局的规定执行。 电子政务电子认证服务机构有根据国家密码管理局的安排承接其他机构开展的电子政务电子认证服务业务的义务。"},{"i":30,"n":"第三十条","txt":"密码管理部门依法对电子政务电子认证服务活动进行监督检查。监督检查可以采取书面检查、实地核查、网络监测等方式。"},{"i":31,"n":"第三十一条","txt":"密码管理部门依法实施监督检查时，可以进入电子政务电子认证服务活动场所实施现场检查，调查、了解有关情况，查阅、复制有关资料，并可以委托专业机构或者组织专家开展有关检测鉴定工作。 电子政务电子认证服务机构及受委托机构应当予以配合，并如实提供相关材料和技术支持。"},{"i":32,"n":"第三十二条","txt":"密码管理部门开展监督检查，不得妨碍电子政务电子认证服务机构及受委托机构的正常经营和服务活动，不得收取任何费用，不得泄露或者非法向他人提供在履行职责中知悉的商业秘密和个人隐私。"},{"i":33,"n":"第三十三条","txt":"电子政务电子认证服务机构有下列情形之一的，密码管理部门应当进行重点监督检查： （一）一年内在监督检查中发现存在严重问题； （二）因违反有关法律法规受到行政处罚； （三）其他需要进行重点监督检查的情形。"},{"i":34,"n":"第三十四条","txt":"电子政务电子认证服务机构应当保证其基本条件和能力能够持续符合资质认定条件和要求。"},{"i":35,"n":"第三十五条","txt":"电子政务电子认证服务机构应当于每年1月15日前向住所地省、自治区、直辖市密码管理部门报送上一年度工作报告，包括： （一）持续符合资质认定条件和要求的情况； （二）电子政务电子认证服务业务开展情况及相关统计数据； （三）行为规范执行情况； （四）电子认证服务系统安全运行情况； （五）电子政务电子认证服务及其使用密码安全管理体系执行情况。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一的，电子政务电子认证服务机构应当自发生之日起15日内向住所地省、自治区、直辖市密码管理部门报告： （一）重大安全风险和安全事件； （二）重要系统、关键设备事故； （三）关键岗位人员变动； （四）重大财产损失。"},{"i":37,"n":"第三十七条","txt":"未经认定从事电子政务电子认证服务的，由密码管理部门依据《中华人民共和国密码法》和《商用密码管理条例》有关规定进行处罚。"},{"i":38,"n":"第三十八条","txt":"电子政务电子认证服务机构违反《中华人民共和国密码法》、《商用密码管理条例》和本办法有关规定，有下列情形之一的，由密码管理部门责令改正或者停止违法行为，给予警告，没收违法所得；违法所得30万元以上的，可以并处违法所得1倍以上3倍以下罚款；没有违法所得或者违法所得不足30万元的，可以并处10万元以上30万元以下罚款；情节严重的，责令停业整顿，直至吊销电子政务电子认证服务机构资质： （一）超出批准范围开展电子政务电子认证服务； （二）转让、出租、出借、伪造、变造、冒用、租借《电子政务电子认证服务机构资质证书》； （三）未按照本机构公布的电子政务电子认证业务规则提供电子政务电子认证服务； （四）电子签名认证证书内容不符合规定要求； （五）电子签名认证证书申请受理未查验申请人身份、未审查有关申请材料、未向申请人告知有关事项，或者未与申请人签订电子政务电子认证服务协议； （六）泄露或者非法向他人提"},{"i":39,"n":"第三十九条","txt":"电子政务电子认证服务机构违反本办法有关规定，有下列情形之一的，由密码管理部门责令改正；逾期未改正或者改正后仍不符合要求的，处1万元以上10万元以下罚款： （一）未按照本办法第十四条规定办理变更手续； （二）未按照本办法第十六条、第二十五条规定进行备案； （三）未按照要求进行电子政务电子认证服务合规性评估，或者未对评估中发现的问题及时进行整改； （四）未建立投诉处理机制、公布投诉方式，或者未及时受理、妥善处理有关投诉事项； （五）未对本单位及受委托机构的从业人员进行岗位培训； （六）未按照要求报告暂停或者终止电子政务电子认证服务的情况； （七）未按照要求承接电子政务电子认证服务业务。"},{"i":40,"n":"第四十条","txt":"电子签名人或者电子签名依赖方因依据电子政务电子认证服务机构提供的电子签名认证服务在政务活动中遭受损失，电子政务电子认证服务机构不能证明自己无过错的，承担赔偿责任。"},{"i":41,"n":"第四十一条","txt":"从事电子政务电子认证服务监督管理工作的人员滥用职权、玩忽职守、徇私舞弊，或者泄露、非法向他人提供在履行职责中知悉的商业秘密、个人隐私、举报人信息的，依法给予处分。"},{"i":42,"n":"第四十二条","txt":"本办法自2024年11月1日起施行。"}],"dianyingqiyejingyingzigezhunruzanxingguiding":[{"i":1,"n":"第一条","txt":"为了充分调动社会力量，加快发展电影产业，培育市场主体，规范市场准入，增强电影业的整体实力和竞争力，促进社会主义电影业繁荣，满足广大人民群众的精神文化生活需求，根据《中华人民共和国中外合资经营企业法》、《中华人民共和国中外合作经营企业法》、《电影管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于境内公司、企业和其他经济组织经营电影制作、发行、放映、进出口业务及境外公司、企业和其他经济组织参与经营电影制作、放映业务的资格准入管理。"},{"i":3,"n":"第三条","txt":"国家对电影制作、发行、放映、进出口经营资格实行许可制度。"},{"i":4,"n":"第四条","txt":"国家广播电影电视总局（以下简称广电总局）为全国电影制片、发行、放映、进出口经营资格准入的行业行政管理部门。"},{"i":5,"n":"第五条","txt":"国家允许境内公司、企业和其他经济组织（不包括外商投资企业）设立电影制片公司。申请设立电影制片公司，由境内公司、企业和其他经济组织向广电总局提出申请。 （一）已取得《摄制电影许可证》的境内公司、企业和其他经济组织（不包括外商投资企业）联合设立电影制片公司的，需提交申请书、合同、章程、工商行政管理部门颁发的各方营业执照复印件、公司名称预核准通知书。 （二）未取得《摄制电影许可证》的境内公司、企业和其他经济组织（不包括外商投资企业），首次拍摄电影片时须设立影视文化公司，由影视文化公司申请领取《摄制电影片许可证（单片）》。取得《摄制电影片许可证（单片）》的申报条件及程序如下： 1.地（市）级以上工商行政管理部门注册的各类影视文化单位，均有资格申领《摄制电影片许可证（单片）》； 2.提交申请书、工商行政管理部门颁发的营业执照复印件、制作影片的资金来源证明、拟摄制影片的文学剧本（故事梗概）一式三份"},{"i":6,"n":"第六条","txt":"允许境内公司、企业和其他经济组织（以下简称中方）与境外公司、企业和其他经济组织（以下简称外方）合资、合作设立电影制片公司（以下简称合营公司）。申请设立合营公司，由中方向广电总局提出申请。申报条件及程序如下： （一）中方已取得《摄制电影许可证》的或已取得两个《摄制电影片许可证（单片）》的； （二）外资在注册资本中的比例不得超过49%； （三）符合（一）、（二）项的，由中方向广电总局提交项目申请书、可行性研究报告、合同、章程、合营各方注册登记证明（或身份证明）、公司名称预核准通知书等。广电总局依法予以审核。经审核合格的，出具核准文件并颁发《摄制电影许可证》； （四）符合（一）、（二）、（三）项的，由中方持广电总局出具的核准文件及本条（四）中所列文件，报商务部审批。商务部依法做出批准或不批准的决定。经批准的，颁发《外商投资企业批准证书》；不予批准的，书面回复理由； （五）申报单位持广电总局、"},{"i":7,"n":"第七条","txt":"按照本规定第五条、第六条，取得《摄制电影许可证》的电影制片公司，依照《电影管理条例》享有与国有电影制片单位同等的权利和义务。"},{"i":8,"n":"第八条","txt":"允许境内公司、企业和其他经济组织（不包括外商投资企业）设立电影技术公司，改造电影制片、放映基础设施和技术设备。申报条件及程序如下： （一）提交申请书、工商行政管理部门颁发的营业执照（联合设立电影技术公司的还要提供合同、章程、各方营业执照复印件）、公司名称预核准通知书； （二）符合（一）项的，申报单位持广电总局出具的批准文件到所在地工商行政管理部门办理相关手续，并报广电总局备案；不批准的，书面回复理由。"},{"i":9,"n":"第九条","txt":"允许境内公司、企业和其他经济组织（以下简称中方）与境外公司、企业和其他经济组织（以下简称外方）合资、合作设立电影技术公司，改造电影制片、放映基础设施和技术设备。申报条件及程序如下： （一）外资在注册资本中的比例不得超过49%，经国家批准的省市可以控股； （二）符合（一）项的，由中方向广电总局提交项目申请书、可行性研究报告、合同、章程、合营各方注册登记证明（或身份证明）、公司名称预核准通知书等。广电总局依法予以审核。经审核合格的，出具核准文件； （三）符合（一）、（二）项的，由中方持广电总局出具的核准文件及本条（二）中所列文件，报商务部审批。商务部依法做出批准或不批准的决定。经批准的，颁发《外商投资企业批准证书》；不予批准的，书面回复理由； （四）申报单位持广电总局、商务部的批准文件，到所在地工商行政管理部门办理相关手续。"},{"i":10,"n":"第十条","txt":"鼓励境内公司、企业和其他经济组织（不包括外商投资企业）设立专营国产影片发行公司。申报条件及程序如下： （一）受电影出品单位委托代理发行过两部电影片或受电视剧出品单位委托发行过两部电视剧； （二）提交申请书、工商行政管理部门颁发的营业执照复印件、公司名称预核准通知书、已代理发行影视片的委托证明等材料； （三）符合（一）、（二）项并向广电总局申请设立专营国产影片发行公司的，由广电总局在20个工作日内颁发全国专营国产影片的《电影发行经营许可证》；向当地省级电影行政管理部门申请设立专营国产影片发行公司的，由当地省级电影行政管理部门在20个工作日内颁发本省（区、市）专营国产影片的《电影发行经营许可证》。申报单位持电影行政管理部门出具的批准文件到所在地工商行政管理部门办理相关手续。不批准的，书面回复理由。"},{"i":11,"n":"第十一条","txt":"广电总局依照关于发行放映国产影片的年度考核的有关规定，对取得《电影发行经营许可证》的公司进行年度考核。"},{"i":12,"n":"第十二条","txt":"允许电影院线公司以紧密型或松散型进行整合。鼓励以跨省院线为基础，按条条管理的原则重新整合。不允许按行政区域整体兼并院线。院线整合报广电总局审批。 鼓励境内公司、企业和其他经济组织（不包括外商投资企业）投资现有院线公司或单独组建院线公司。 （一）以参股形式投资现有院线公司的，参股单位须在三年内投资不少于3000万元人民币，用于本院线中电影院的新建、改造；以控股形式投资现有院线公司的，控股单位须在三年内投资不少于4000万元人民币，用于本院线中电影院的新建、改造；单独组建省内或全国电影院线公司的，组建单位须在三年内投资不少于5000万元人民币用于本院线中电影院的新建、改造； （二）组建省（区、市）内院线公司的，由所在地省、自治区、直辖市人民政府电影行政管理部门在20个工作日内审批，并报广电总局备案；组建跨省院线公司的，由广电总局在20个工作日内审批。申报单位持电影行政管理部门出具的批准文件"},{"i":13,"n":"第十三条","txt":"鼓励境内公司、企业和其他经济组织（不包括外商投资企业）组建少年儿童电影发行放映院线。 （一）凡在省（区、市）内与20家以上中小学校、少年宫、儿童活动中心、影剧院、礼堂等签订电影供片协议的，可向当地省级电影行政管理部门申请，设立一条省（区、市）内少年儿童电影发行放映院线； （二）凡在不同省（区、市）与30家以上中小学校、少年宫、儿童活动中心、影剧院、礼堂等签订电影供片协议的，可向广电总局提出申请，设立一条跨省（区、市）的少年儿童电影发行放映院线； （三）组建省（区、市）内院线公司的，由所在地省、自治区、直辖市人民政府电影行政管理部门在20个工作日内审批，并报广电总局备案；组建跨省院线公司的，由广电总局在20个工作日内审批。申报单位持电影行政管理部门出具的批准文件到所在地工商行政管理部门办理相关手续。不批准的，书面回复理由。"},{"i":14,"n":"第十四条","txt":"鼓励境内公司、企业和其他经济组织及个人依照《电影管理条例》在全国农村以多种方式经营电影发行、放映业务，在城市社区、学校经营电影放映业务。"},{"i":15,"n":"第十五条","txt":"鼓励境内公司、企业和其他经济组织及个人投资建设、改造电影院。经营电影放映业务，须报县级以上地方电影行政管理部门批准，到所在地工商行政管理部门办理相关手续。 外商投资电影院依照《外商投资电影院暂行规定》管理。"},{"i":16,"n":"第十六条","txt":"电影进口经营业务由广电总局批准的电影进口经营企业专营。进口影片全国发行业务由广电总局批准的具有进口影片全国发行权的发行公司发行。"},{"i":17,"n":"第十七条","txt":"鼓励影片摄制单位多渠道出口取得《电影片公映许可证》的国产影片。"},{"i":18,"n":"第十八条","txt":"广电总局颁发的《摄制电影许可证》、《电影发行经营许可证》实行隔年检验制度。地方电影行政管理部门按照管理权限，对颁发的《电影发行经营许可证》、《电影放映经营许可证》实行年检制度。"},{"i":19,"n":"第十九条","txt":"本办法未作规定的，依照《电影管理条例》及有关规定执行。"},{"i":20,"n":"第二十条","txt":"本规定由广电总局、商务部负责解释。"},{"i":21,"n":"第二十一条","txt":"本规定自2004年11月10起施行。广电总局《电影制片、发行、放映经营资格准入暂行规定》（广电总局令第20号）、《关于取得〈摄制电影许可证（单片）〉资格认证制度的实施细则（试行）》（广发办字〔2001〕1483号）同时废止。 《电影企业经营资格准入暂行规定》的补充规定 （2005年3月7日国家广播电影电视总局、商务部令第50号公布　根据2015年8月28日《国家新闻出版广电总局关于修订部分规章和规范性文件的决定》修订）) 为了促进香港、澳门与内地建立更紧密经贸关系，鼓励香港、澳门服务提供者在内地设立发行国产电影片的企业，根据国务院批准的《<内地与香港关于建立更紧密经贸关系的安排>补充协议》及《<内地与澳门关于建立更紧密经贸关系的安排>补充协议》，现对《电影企业经营资格准入暂行规定》（国家广播电影电视总局商务部令第43号）作出如下补充规定： 一、自2005年1月1日起，允许香港、澳门服务"}],"dianyingjubenbeiandianyingpianguanliguiding":[{"i":1,"n":"第一条","txt":"为规范和改进电影剧本（梗概）备案和电影片管理制度，提高电影质量，繁荣电影创作，满足广大群众的精神文化需求，推进电影业健康发展，根据《电影管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"国家实行电影剧本（梗概）备案和电影片审查制度。未经备案的电影剧本（梗概）不得拍摄，未经审查通过的电影片不得发行、放映、进口、出口。"},{"i":3,"n":"第三条","txt":"本规定适用于在中华人民共和国境内公映的各类故事片、纪录片、科教片、动画片、专题片（含以上各类型的中外合拍片）等的电影剧本（梗概）备案、电影片审查和进口片审查。"},{"i":4,"n":"第四条","txt":"国家广播电影电视总局（以下简称广电总局）负责电影剧本（梗概）备案和电影片审查的管理工作。 广电总局电影审查委员会和电影复审委员会负责电影片的审查。 省级广播影视行政部门（以下简称省级广电部门），经申请可以受广电总局委托，成立电影审查机构，负责本行政区域内持有《摄制电影许可证》的制片单位摄制的部分电影片的审查工作（以下简称属地审查）。"},{"i":5,"n":"第五条","txt":"拟摄制电影的法人、其他组织（以下简称制片单位）应当在电影拍摄前，按照有关规定向相关电影主管部门申请办理电影剧本（梗概）的备案手续。 联合摄制电影片的，应当由其中的一个单位提前办理备案手续。"},{"i":6,"n":"第六条","txt":"办理电影剧本（梗概）备案手续，应当提供下列材料： （一）拟拍摄影片的备案报告； （二）不少于一千字的电影剧情梗概一份。凡影片主要人物和情节涉及外交、民族、宗教、军事、公安、司法、历史名人和文化名人等方面内容的（以下简称特殊题材影片），需提供电影文学剧本一式三份，并要征求省级或中央、国家机关相关主管部门的意见； （三）电影剧本（梗概）版权的协议（授权）书；"},{"i":7,"n":"第七条","txt":"电影剧本（梗概）备案的程序： （一）制片单位向广电总局或实行属地审查的省级广电部门提出备案； （二）广电总局或实行属地审查的省级广电部门按照《行政许可法》规定的期限，发给《电影剧本（梗概）备案回执单》（式样附后）。 如在二十个工作日内没有提出意见的，制片单位可按备案的电影剧本（梗概）进行拍摄； 如对备案的电影剧本（梗概）有修改意见或不同意拍摄的，应在二十个工作日内书面通知制片单位；　如电影剧本需另请相关主管部门和专家评审的，需延长二十个工作日，并书面告知制片单位。"},{"i":8,"n":"第八条","txt":"实行属地审查的省级广电部门，应将电影剧本（梗概）备案情况抄报广电总局；广电总局将定期在相关媒体公布电影剧本（梗概）备案情况。"},{"i":9,"n":"第九条","txt":"拍摄重大革命和重大历史题材影片，需报送剧本立项审查，按照广电总局关于重大革命和重大历史题材电影剧本立项及完成片的管理规定办理。"},{"i":10,"n":"第十条","txt":"拍摄重大文献纪录影片，需报送剧本立项审查，按照广电总局关于重大文献纪录影片的管理规定办理。"},{"i":11,"n":"第十一条","txt":"中外合作摄制影片，需报送剧本立项审查，按照广电总局关于中外合作摄制电影片的管理规定办理。"},{"i":12,"n":"第十二条","txt":"国家提倡创作思想性、艺术性、观赏性统一，贴近实际、贴近生活、贴近群众，有利于保护未成年人健康成长的优秀电影。大力发展先进文化，支持健康有益文化，努力改造落后文化，坚决抵制腐朽文化。"},{"i":13,"n":"第十三条","txt":"电影片禁止载有下列内容： （一）违反宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密，危害国家安全，损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，侵害民族风俗、习惯的； （五）违背国家宗教政策，宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力、教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德，诋毁民族优秀文化的； （十）有国家法律、法规禁止的其他内容的。"},{"i":14,"n":"第十四条","txt":"电影片有下列情形，应删剪修改： （一）曲解中华文明和中国历史，严重违背历史史实；曲解他国历史，不尊重他国文明和风俗习惯；贬损革命领袖、英雄人物、重要历史人物形象；篡改中外名著及名著中重要人物形象的； （二）恶意贬损人民军队、武装警察、公安和司法形象的； （三）夹杂淫秽色情和庸俗低级内容，展现淫乱、强奸、卖淫、嫖娼、性行为、性变态等情节及男女性器官等其他隐秘部位；夹杂肮脏低俗的台词、歌曲、背景音乐及声音效果等； （四）夹杂凶杀、暴力、恐怖内容，颠倒真假、善恶、美丑的价值取向，混淆正义与非正义的基本性质；刻意表现违法犯罪嚣张气焰，具体展示犯罪行为细节，暴露特殊侦查手段；有强烈刺激性的凶杀、血腥、暴力、吸毒、赌博等情节；有虐待俘虏、刑讯逼供罪犯或犯罪嫌疑人等情节；有过度惊吓恐怖的画面、台词、背景音乐及声音效果； （五）宣扬消极、颓废的人生观、世界观和价值观，刻意渲染、夸大民族愚昧落后或社会阴"},{"i":15,"n":"第十五条","txt":"电影片的署名、字幕等语言文字，应按《中华人民共和国著作权法》、《中华人民共和国国家通用语言文字法》等有关规定执行。"},{"i":16,"n":"第十六条","txt":"电影片技术质量按照国家有关电影技术标准审查。"},{"i":17,"n":"第十七条","txt":"摄制完成的电影片应当报相应的电影审查机构审查。送审电影片应当提供下列材料： （一）混录双片 1.混录双片一套（如用贝塔录像带代替混录双片送审，需另报广电总局批准），数字电影送高清数字节目带一套； 2.国产电影片送审报告单一式四份； 3.影片主创人员名单； 4.影片英文译名报告（一般提前申报）； 5.原著改编意见书； 6.联合摄制合同书； 7.完成台本一套； 8.《电影剧本（梗概）备案回执单》。 （二）标准拷贝 1.标准拷贝两套（广电总局和中国电影资料馆各一套）； 2.影片1/2录像带三套（中外合拍片四套）、贝塔录像带、贝塔宣传带、终混八轨带各一套； 3.送审标准拷贝技术鉴定书； 4.被定为民族语译制影片的音乐效果素材； 5.完成台本三套（民族语译制影片为四套）； 6.相关剧照。 数字电影的技术审查标准及需提交的材料，按照广电总局有关规定执行。"},{"i":18,"n":"第十八条","txt":"电影片的审查程序： （一）制片单位应向广电总局电影审查委员会提出审查申请； （二）广电总局电影审查委员会自收到混录双片及相关材料之日起二十个工作日内作出审查决定。审查合格的，发给《影片审查决定书》和《电影片公映许可证》片头。审查不合格或需要修改的，应在《影片审查决定书》中作出说明，并通知制片单位； （三）广电总局电影审查委员会自收到标准拷贝（数字节目带）及相关材料之日起十个工作日内作出审查决定。审查合格的，发给《电影片公映许可证》；审查不合格或需要修改的，应通知制片单位； （四）影片审查不合格需经修改后再次送审的，审查期限重新计算； （五）制片单位对电影片审查决定不服的，可以自收到《影片审查决定书》之日起三十个工作日内向广电总局电影复审委员会提出复审申请。广电总局电影复审委员会应在二十个工作日内作出复审决定。复审合格的，发给《电影片公映许可证》；不合格的，书面通知制片单位； （六）实行"},{"i":19,"n":"第十九条","txt":"实行属地审查的省级广电部门认为必要时，可以将送审影片提交广电总局电影审查委员会审查。 制片单位对省级广电部门的审查决定有异议的，可以向广电总局电影审查委员会申请重审。"},{"i":20,"n":"第二十条","txt":"联合摄制的电影片，由办理备案手续的制片单位按照本规定送相应的电影审查机构审查。"},{"i":21,"n":"第二十一条","txt":"重大革命和重大历史题材影片、重大文献纪录影片、特殊题材影片、中外合作摄制影片，由省级广电部门初审同意后，报广电总局电影审查机构审查。"},{"i":22,"n":"第二十二条","txt":"中央和国家机关所属的电影制片单位和所有持有《摄制电影片许可证（单片）》的单位摄制的影片，直接报广电总局电影审查委员会审查。"},{"i":23,"n":"第二十三条","txt":"进口电影片的审查，按照《电影管理条例》第四章关于电影进口和本规定第三章关于电影片审查的相关条款办理。"},{"i":24,"n":"第二十四条","txt":"对违反本规定的行为，依据《电影管理条例》和其他有关法律、法规进行处理。"},{"i":25,"n":"第二十五条","txt":"本规定自2006年6月22日起施行。1997年1月16日广播电影电视部发布的《电影审查规定》（广播电影电视部令第22号）、2004年7月6日广电总局发布的《电影剧本（梗概）立项、电影片审查暂行规定》（广电总局令第30号）同时废止。"}],"dianyingyishudanganguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强电影艺术档案的收集和管理，有效地保护和利用电影艺术档案，更好地为电影创作、生产、教学、研究和普及服务，根据《中华人民共和国档案法》、《中华人民共和国档案法实施办法》和《电影管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中国境内的电影摄制单位和电影艺术档案机构，以及与电影艺术档案相关的组织和个人。"},{"i":3,"n":"第三条","txt":"本规定所称电影艺术档案，是指在电影创作、生产、发行、放映过程中形成的文字、图片、标准拷贝、数字母版、影片素材等具有保存价值的资料。"},{"i":4,"n":"第四条","txt":"电影艺术档案是国家档案的重要组成部分，依法接受档案行政管理部门的统筹规划、组织协调和监督指导，实行统一管理。 国务院广播影视行政部门负责全国电影艺术档案工作。 省、自治区、直辖市人民政府广播影视行政部门负责本行政区域内的电影艺术档案工作，并应当督促本行政区域内的电影摄制单位，按照本规定履行电影艺术档案移交义务。"},{"i":5,"n":"第五条","txt":"国家鼓励和支持有关电影艺术档案保管、复制、修复方面的科学研究和实践活动。"},{"i":6,"n":"第六条","txt":"电影艺术档案从业人员的专业技术职称或者职务，按照国家档案系列专业技术人员的有关规定评定与聘任。"},{"i":7,"n":"第七条","txt":"有下列事迹之一的组织或者个人，由国务院广播影视行政部门给予奖励： （一）为发展电影艺术档案事业作出重要贡献的； （二）收集、整理、保管、修复电影艺术档案有显著成绩的； （三）提供电影艺术档案获得显著效益的； （四）将重要或者珍贵电影艺术档案捐赠给国家的。"},{"i":8,"n":"第八条","txt":"电影艺术档案由影片类和文字、图片类组成。"},{"i":9,"n":"第九条","txt":"影片类档案包括： 国产影片、与我国香港特别行政区、澳门特别行政区、台湾地区及外国合作摄制的影片的全新原底标准拷贝或者数字母版，画原底、画翻正、画翻底，片头、片尾、唱词等各类字幕原底，片头、片尾、衬景原底，十格小底片，光号卡，国际乐效，混录声底、混录光学声底等。"},{"i":10,"n":"第十条","txt":"文字、图片类档案包括： （一）文学剧本、分镜头剧本、译制片台本； （二）完成台本（含字幕表）； （三）对国外发行的国产影片各语种和国内民族语言的翻译本； （四）导演阐述； （五）影片审查决定书； （六）有关部门对影片的审查意见和决定； （七）影片海报、宣传画、工作照、剧照、说明书、特刊； （八）国产影片在国内外获奖的证件复印件及有关照片； （九）剧本内容的有关依据和历史考证材料，以及取材或者改编前的原作； （十）主创人员的创作设想和音乐总谱、歌词； （十一）场景气氛图，服装、化妆、道具设计图，演员定妆照； （十二）有关摄制决定； （十三）分场分景表； （十四）摄制工作日志； （十五）摄制工作总结； （十六）主创人员艺术创作总结； （十七）其他在电影创作、生产、发行、放映过程中形成的具有保存价值的资料。"},{"i":11,"n":"第十一条","txt":"本规定第九条、第十条的内容为故事影片艺术档案构成。其他片种可视工艺和工作程序不同参照执行。"},{"i":12,"n":"第十二条","txt":"国家设立中国电影资料馆等电影艺术档案机构，负责依法收集、整理、保管和利用电影艺术档案等工作。"},{"i":13,"n":"第十三条","txt":"电影艺术档案机构依法搜集电影创作、生产、发行、放映过程中形成的具有保存价值的电影艺术档案，接收有关组织或者个人通过移交、捐赠等方式提供的电影艺术档案，积极收集散失的国产影片艺术档案。 依据本规定移交电影艺术档案，电影艺术档案机构可以对有关单位予以适度补贴。"},{"i":14,"n":"第十四条","txt":"电影艺术档案机构应当具有适宜长久保存、合理利用电影艺术档案的场所、设备、条件和专业人员，并建立科学的管理制度，逐步实现保存与管理的科学化、标准化。 用于保存电影艺术档案的库房温度、湿度等应当符合国家规定的标准，并应当加强防火、防盗、防虫、防霉、防光、防尘、防水（潮）、防有害气体等安全保卫工作。"},{"i":15,"n":"第十五条","txt":"电影摄制单位应当设立专门部门或者指定专人负责电影艺术档案管理工作，切实履行电影艺术档案移交、保管义务。"},{"i":16,"n":"第十六条","txt":"电影艺术档案机构和电影摄制单位应当有计划地做好电影艺术档案编目和研究工作。"},{"i":17,"n":"第十七条","txt":"电影艺术档案机构应当逐步将电影艺术档案转换成数字化形式，加强档案的数字化修护和保护工作。"},{"i":18,"n":"第十八条","txt":"电影艺术档案机构和电影摄制单位应当定期检查档案保存状况，对破损或者变质的电影艺术档案应当及时修补、复制或者进行其他技术处理。"},{"i":19,"n":"第十九条","txt":"电影艺术档案机构应当确保易燃片基的安全，及时发现并消除隐患；对易燃片基进行单独的妥善保管，并有计划地转换复制成安全片基。"},{"i":20,"n":"第二十条","txt":"电影摄制单位应当在影片取得电影公映许可证后三个月内向中国电影资料馆移交下列电影艺术档案，并永久保存，国务院广播影视行政部门另有规定的除外： （一）影片类档案中的标准拷贝或者数字母版； （二）本规定第十条第（一）项至第（六）项规定的文字、图片类档案。 电影摄制单位应当在影片取得电影公映许可证后一年内向中国电影资料馆移交其他影片类档案；经依法审查未取得电影公映许可证的影片，电影摄制单位如不再重新报请审查，应当在接到审查决定后一年内向中国电影资料馆移交电影艺术档案。 其他电影艺术档案，电影摄制单位可以参照本条第一款、第二款的规定向中国电影资料馆移交。"},{"i":21,"n":"第二十一条","txt":"电影摄制单位应当依据本规定履行电影艺术档案移交义务，不得拒绝归档；电影艺术档案机构应当依据本规定履行电影艺术档案管理义务，为移交人提供服务。"},{"i":22,"n":"第二十二条","txt":"电影摄制单位注销或者合并时，应当将其保存的电影艺术档案移交中国电影资料馆或者新组建的电影摄制单位妥善保管。"},{"i":23,"n":"第二十三条","txt":"电影摄制组应当负责电影艺术档案的形成、积累，指定专人负责电影艺术资料的收集工作，并在影片摄制完成后将属于电影艺术档案归档范围的资料及时移交电影摄制单位档案部门归档。"},{"i":24,"n":"第二十四条","txt":"国家鼓励任何组织、个人向电影艺术档案机构捐赠、寄存其拥有的电影艺术档案。电影艺术档案机构可以按照电影艺术档案的保存价值，作出是否接受捐赠、寄存的决定。"},{"i":25,"n":"第二十五条","txt":"电影艺术档案机构应当依据捐赠协议、寄存协议，对捐赠、寄存的电影艺术档案，予以妥善保管，并依法维护捐赠人、寄存人的合法权益。 电影艺术档案机构可以向寄存人适当收取费用。"},{"i":26,"n":"第二十六条","txt":"电影艺术档案机构应当与电影艺术档案的捐赠人、寄存人，就档案利用事宜在捐赠、寄存协议中进行约定。"},{"i":27,"n":"第二十七条","txt":"向电影艺术档案机构捐赠、寄存电影艺术档案的组织、个人，对其档案有优先使用权。"},{"i":28,"n":"第二十八条","txt":"国家鼓励通过捐赠等方式设立电影艺术档案保护社会基金，专门用于电影艺术档案保护，任何组织、个人不得侵占、挪用。"},{"i":29,"n":"第二十九条","txt":"国家鼓励任何组织、个人积极开展对电影艺术档案的利用。电影艺术档案机构保存的电影艺术档案，应当向社会公众开放。 电影艺术档案机构应当定期向社会公布电影艺术档案目录，简化利用手续、减少利用限制，为电影艺术档案公益性利用创造条件，提供便利。 电影艺术档案机构在档案利用工作中，应当按照分类向社会提供使用；并应当依据国家有关法律、法规的规定，维护电影艺术档案有关著作权人的合法权益。 利用电影艺术档案机构的电影艺术档案，应当按照有关规定办理手续，缴纳费用。"},{"i":30,"n":"第三十条","txt":"对涉及国防、外交、国家安全等国家重大利益，以及可能对未成年人身心健康造成不良影响的电影艺术档案的利用，应当遵守国家有关法律、法规的规定。未经有关部门批准，任何组织、个人不得擅自利用上述电影艺术档案。"},{"i":31,"n":"第三十一条","txt":"未经有关部门批准，下列电影艺术档案不得携带出境： （一）构成限制出境的文物的； （二）涉及国家秘密的； （三）法律、法规规定限制出境的其他电影艺术档案。"},{"i":32,"n":"第三十二条","txt":"违反本规定，电影艺术档案机构在保管、利用属于国家所有的电影艺术档案过程中，有下列情形之一的，由省、自治区、直辖市以上人民政府广播影视行政部门责令改正，给予警告，对单位可以并处3万元以下的罚款，对个人可以并处5千元以下的罚款；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）电影艺术档案发生超额损伤的； （二）损毁、丢失和擅自销毁电影艺术档案的； （三）利用电影艺术档案谋取非法利益的； （四）未经批准利用电影艺术档案的。"},{"i":33,"n":"第三十三条","txt":"违反本规定，逾期未移交电影艺术档案的，由省、自治区、直辖市以上人民政府广播影视行政部门责令改正；情节严重的，对直接负责的主管人员和其他直接负责人员依法给予处分。"},{"i":34,"n":"第三十四条","txt":"本规定自2010年8月1日起施行。1994年6月20日广播电影电视部、国家档案局发布的《电影艺术档案管理规定》同时废止。"}],"dianwangdiaoduguanlitiaolishishibanfa":[{"i":1,"n":"第一条","txt":"根据《电网调度管理条例》(以下简称《条例》)第三十一条规定，特制定本实施办法。"},{"i":2,"n":"第二条","txt":"电网包括发电、供电(输电、变电、配电)、受电设施和为保证这些设施正常运行所需的继电保护和安全自动装置、计量装置、电力通信设施、电网调度自动化设施等。电网运行必须实行统一调度、分级管理，以保障电网安全、保护用户利益、适应经济建设和人民生活的用电需要。"},{"i":3,"n":"第三条","txt":"电网调度管理的任务是组织、指挥、指导和协调电网的运行，保证实现下列基本要求： (一)充分发挥本电网内发、供电设备能力，以有计划地满足本网的用电需要; (二)使电网按照有关规定连续、稳定、正常运行，保证供电可靠性; (三)使电网供电的质量(频率、电压和谐波分量等)指标符合国家规定的标准; (四)根据本电网的实际情况，充分合理利用一次能源，使全电网在供电成本最低或者发电能源消耗率及网损率最小的条件下运行; (五)按照有关合同或者协议，保护发电、供电、用电等各有关方面的合法权益。"},{"i":4,"n":"第四条","txt":"电网调度机构一般应当进行下列主要工作： (一)组织编制和执行电网的调度计划(运行方式); (二)指挥调度管辖范围内的设备的操作; (三)指挥电网的频率调整和电压调整; (四)指挥电网事故的处理，负责进行电网事故分析，制订并组织实施提高电网安全运行水平的措施; (五)编制调度管辖范围内的设备的检修进度表，批准其按计划进行检修; (六)负责本调度机构管辖的继电保护和安全自动装置以及电力通信和电网调度自动化设备的运行管理;负责对下级调度机构管辖的上述设备和装置的配置和运行进行技术指导; (七)组织电力通信和电网调度自动化规划的编制工作，组织继电保护及安全自动装置规划的编制工作; (八)参与电网规划编制工作，参与电网工程设计审查工作; (九)参加编制发电、供电计划，监督发电、供电计划执行情况，严格控制按计划指标发电、用电; (十)负责指挥全电网的经济运行; (十一)组织调度系统有关人员的业务培"},{"i":5,"n":"第五条","txt":"电网调度机构是电网运行的组织、指挥、指导和协调机构，各级调度机构分别由本级电网管理部门直接领导。调度机构既是生产运行单位，又是电网管理部门的职能机构，代表本级电网管理部门在电网运行中行使调度权。 电网调度机构分为五级，依次为： 国家电网调度机构; 跨省、自治区、直辖市电网调度机构; 省、自治区、直辖市级电网调度机构; 省辖市级电网调度机构; 县级电网调度机构。 各级调度机构在电网调度业务活动中是上、下级关系，下级调度机构必须服从上级调度机构的调度。"},{"i":6,"n":"第六条","txt":"调度系统值班人员应当由专业技术素质较高、工作能力较强和职业道德高尚的人员担任。调度系统值班人员在上岗值班之前必须经过培训，经考核取得合格证书并由相应主管部门批准后，方可正式上岗值班，并通知有关单位。"},{"i":7,"n":"第七条","txt":"各级电网调度机构的值班调度员在其值班期间是电网运行和操作的指挥人员，按照批准的调度管辖范围行使调度权。值班调度人员必须按照规定发布调度指令。 发布调度指令的值班调度员应当对其发布的调度指令的正确性负责。 本条所称“规定”，包括《条例》及电力行政主管部门、电网管理部门的规程、规范等，省、自治区、直辖市制定的小电网管理办法。下级电力行政主管部门(或者电网管理部门)颁布的规程、规范等，不得与《条例》以及上级电力行政主管部门(或者电网管理部门)的有关规程、规范等相抵触;省、自治区、直辖市制定的小电网管理办法不得与《条例》相抵触。"},{"i":8,"n":"第八条","txt":"下级调度机构的值班调度员、发电厂值班长、变电站值班长在电网调度业务方面受上级调度机构值班调度员的指挥，接受上级调度机构值班调度员的调度指令。 调度系统的值班人员，接受上级调度机构值班调度员的调度指令后，应当复诵调度指令，经核实无误后方可执行。 任何单位和个人不得违反《条例》，干预调度系统的值班人员发布或者执行调度指令。调度系统的值班人员依法执行公务，有权利和义务拒绝各种非法干预。 调度系统的值班人员不执行或者延迟执行上级调度机构值班调度员的调度指令，则未执行调度指令的值班人员以及不允许执行或者允许不执行调度指令的领导人均应当对此负责。"},{"i":9,"n":"第九条","txt":"调度系统值班人员在接到上级调度机构值班调度人员发布的调度指令时或者在执行调度指令过程中，认为调度指令不正确，应当立即向发布该调度指令的值班调度人员报告，由发令的值班调度员决定该调度指令的执行或者撤销。如果发令的值班调度员重复该指令时，接令值班人员原则上必须执行，但执行该指令确将危及人身、设备或者电网安全时，值班人员应当拒绝执行，同时将拒绝执行的理由及改正指令内容的建议报告发令的值班调度员和本单位直接领导人。"},{"i":10,"n":"第十条","txt":"电网管理部门的主管领导发布的一切有关调度业务的指示，应当通过调度机构负责人(指调度局(所)长(主任)、总工程师，调度处(科、组)长，下同)转达给值班调度员。非上述人员，不得直接要求值班调度人员发布任何调度指令。任何人均不得阻挠值班人员执行上级值班调度员的调度指令。 电网管理部门的负责人，调度机构的负责人以及发电厂、变电站的负责人，对上级调度机构的值班调度人员发布的调度指令有不同意见时，只能向上级电力行政主管部门(或者电网管理部门)或者上级调度机构提出，不得要求所属调度系统值班人员拒绝或者拖延执行调度指令;在上级电力行政主管部门(或者电网管理部门)或者上级调度机构对其所提意见未作出答复前，接令的值班人员仍然必须按照上级调度机构的值班调度人员发布的该调度指令执行;上级电力行政主管部门(或者电网管理部门)或者上级调度机构采纳或者部分采纳所提意见，由该调度机构的负责人将意见通知值班调度员，由值"},{"i":11,"n":"第十一条","txt":"除电力行政主管部门、电网管理部门、调度机构负责人所作出的不违反《条例》和其它有关法规、规程、规范等的指示以及调度机构内有关专业部门按规定所提的要求，并按本实施办法第十条规定的传达程序传达给值班调度员外，其它任何人直接对调度系统值班人员发布或者执行调度指令提出的任何要求，均视为非法干预。"},{"i":12,"n":"第十二条","txt":"发电厂、变电站等运行值班单位，必须按其所纳入的调度管辖范围，服从有直接调度管辖权的调度机构的调度。在电网出现《条例》第十八条所列紧急情况时，接到更高一级调度机构的调度指令，也必须执行，并且必须将执行情况分别报告发布指令的调度机构和直接管辖的调度机构的值班调度人员。"},{"i":13,"n":"第十三条","txt":"发电厂必须按照调度机构下达的调度计划(发电有功、无功功率或者电压曲线，机、炉开、停方式等)和规定的电压变化范围运行，并根据调度指令开、停机、炉，调整功率和电压。不允许以任何借口拒绝或者拖延执行调度指令或者不执行调度指令。 变电站必须严格执行调度机构下达的调度计划(运行方式)，依照规定或者调度指令调整(或者操作)电压(无功或者电压调节设备)。"},{"i":14,"n":"第十四条","txt":"各级调度机构必须按照调度管辖范围，按审批或者许可权限统一安排好发、供电设备的检修进度。 各发、供电单位必须按照相应调度机构统一安排的设备检修进度组织设备检修。未经调度机构的批准，不能自行改变检修进度。"},{"i":15,"n":"第十五条","txt":"属于调度管辖范围内的任何设备，未获相应调度机构值班调度员的指令，发电厂、变电站或者下级调度机构的值班人员均不得自行操作或者自行命令操作。但在电网出现紧急情况时上级调度机构值班调度员越级下令的，或者对人身、设备以及电网安全有威胁的除外。遇有危及人身、设备以及电网安全的情况时，发电厂、变电站的运行值班单位的值班人员应当按照有关规定处理，处理后应当立即报告有关调度机构的值班调度员。"},{"i":16,"n":"第十六条","txt":"在电网中出现了威胁电网安全，不采取紧急措施就可能造成严重后果的情况下，必要时值班调度员可以直接(或者通过下级调度机构的值班调度员)越级向电网内下级调度机构管辖的发电厂、变电站等运行值班单位发布调度指令。 下级调度机构的值班调度员发布的调度指令，不得与上级调度机构的值班调度员越级发布的调度指令相抵触。"},{"i":17,"n":"第十七条","txt":"跨省电网管理部门和省级电网管理部门应当编制本地区、电网和企业的年度发电、供电计划。 各地区年度发电预期计划，由各跨省电网、省电网管理部门负责商有关省、自治区、直辖市人民政府的有关部门进行编制，报国务院电力行政主管部门进行审核后报国家计划主管部门，并抄报国家经济综合主管部门，由国家计划主管部门审核下达。 各跨省电网的年度用电计划由各跨省电网管理部门组织有关省电网管理部门编制，报送国家计划主管部门、国家经济综合主管部门和国务院电力行政主管部门审核下达;其他省级电网的年度用电计划由该省级电网管理部门商所在省、自治区、直辖市人民政府有关部门编制下达，报国务院电力行政主管部门备案。 在现行体制下，本实施办法所称国务院电力行政主管部门是指电力工业部，跨省电网管理部门是指电业管理局，省级电网管理部门是指省电力工业局，国家计划主管部门是指国家计委，国家经济综合主管部门是指国家经贸委。"},{"i":18,"n":"第十八条","txt":"调度机构应当按年、月、日编制并下达发电调度计划。 凡由调度机构统一调度并纳入电网进行电力、电量平衡的发电设备，不论其产权归属和管理形式，均必须纳入发电调度计划的范围。 月度发电调度计划，须在年度发电预期计划的基础上，综合考虑用电负荷需求、月度水情、燃料供应、核燃料的燃耗、供热机组供热等情况和电网设备能力、设备检修情况等因素进行编制。 日发电调度计划在月发电调度计划的基础上，综合考虑日用电负荷需求、近期内水情、燃料供应情况和电网设备能力、设备检修情况等因素后，编制出日发电(有功、无功功率或者电压)曲线，下达各发电厂执行。"},{"i":19,"n":"第十九条","txt":"调度机构应当参与(或者负责)编制下达月度供电(电力、电量)计划。 实行省电网间联络运行控制的电网的调度机构，应当按跨省电网管理部门编制下达的计划，并根据电网实际情况按年、月、日编制联络线送(受)电力、电量调度计划。"},{"i":20,"n":"第二十条","txt":"任何单位和个人都应当按照跨省电网管理部门和省级电网管理部门编制下达的用电计划分配电力和电量，不得超分或者扣减(含不得留有缺口)。调度机构发现超计划分配电力或者电量时，应当立即报告计划下达部门，计划下达部门应当通知超分者限期纠正;对于拒不纠正者，计划下达部门应当通知有关调度机构不执行超分计划。 调度机构对因超计划分配电力或者电量而引起的超过跨省电网、省电网管理部门下达的用电计划用电的地区要实施限电，产生的后果，由分配电力或者电量的单位和个人负责。"},{"i":21,"n":"第二十一条","txt":"值班调度员根据电网运行情况，可以按照有关规定调整本调度机构下达的日发电、供电调度计划;需调整其他调度机构下达的日发电、供电调度计划时，必须事先征得下达该调度计划的调度机构的同意。调整之后，必须将调整的原因及数量等填入调度值班日志。"},{"i":22,"n":"第二十二条","txt":"跨省电网管理部门和省级电网管理部门编制发电、供电计划以及调度机构编制发电、供电调度计划时，对具有综合效益的水电厂(站)的水库，不论其产权归属和管理形式，均应当根据批准的水电厂(站)的设计文件，合理运用水库蓄水，保证其正常运用，不允许发生水库长期处于降低出力区运行的情况。 多年调节水库在蓄至正常蓄水位后，供水期末水位一般应当控制在年消落水位附近。遭遇连续枯水年时，需降至死水位运行，必须按规定报批。年调节水库一般在每年汛末应当蓄至正常蓄水位。多年调节水库和年调节水库的最低运行水位，均不允许低于死水位，不得破坏水库的调节能力。调节性能差的水库一般也不能低于死水位运行。"},{"i":23,"n":"第二十三条","txt":"跨省电网管理部门和省级电网管理部门编制发电、供电计划以及调度机构编制发电、供电调度计划时，应当留有备用发电设备容量，分配备用容量时应当考虑电网的送(受)电能力。备用容量包括负荷备用容量、事故备用容量、检修备用容量。电网的总备用容量不宜低于最大发电负荷的20%，各种备用容量宜采用如下标准： 1、负荷备用容量：一般为最大发电负荷的2%-5%，低值适用于大电网，高值适用于小电网; 2、事故备用容量：一般为最大发电负荷的10%左右，但不小于电网中一台最大机组的容量; 3、检修备用容量：一般应当结合电网负荷特点，水、火电比例，设备质量，检修水平等情况确定，一般宜为最大发电负荷的8%-15%。 电网如果不能按上述要求留足备用容量运行时，应当经电网管理部门同意。"},{"i":24,"n":"第二十四条","txt":"跨省电网管理部门和省级电网管理部门遇有下列情形之一，而且不能在短期内解决，需要调整年、月度发电、供电计划指标时，可以适当调整。调整后，应当立即通报有关地方人民政府的有关部门，并与上述有关部门共同研究协调，采取有效措施： 1、大、中型水电厂(站)水库实际来水与编制发电计划依据的来水预计相差较大; 2、火电厂的燃料库存低于规定的火电厂最低燃料库存量“警戒线”; 3、其他需调整发电、供电计划的情形。"},{"i":25,"n":"第二十五条","txt":"任何单位和个人均不得超过调度机构下达的供电调度计划指标使用电力、电量。调度机构对超计划使用电力或者电量的地区实施限电，由此产生的后果由超计划使用电力或者电量的单位和个人负责。"},{"i":26,"n":"第二十六条","txt":"省级电网管理部门、省辖市级电网管理部门、县级电网管理部门应当根据本级人民政府的生产调度部门的要求、用户的特点和电网安全运行的需要，提出事故及超计划用电的限电序位表，经本级人民政府的生产调度部门审核，报本级人民政府批准后(自报送本级人民政府的生产调度部门起，如果三十天内没有批复，即可按电网管理部门上报的序位表执行)，由有关电网调度机构执行，并抄送该电网管理部门的上一级电网管理部门。 事故和超计划用电限电序位表的负荷总量，应当满足电网安全运行的需要。 各级调度机构的值班调度员，可以在电网发生事故或者用电地区(单位)超计划用电时，分别按照事故和超计划用电限电序位表发布拉闸限电指令，受令单位必须立即执行，不得拒绝或者拖延执行。 事故限电序位表内所列负荷(或者线路)，应当包括自动限电负荷和人工限电负荷两部分，自动限电负荷包括装有低频减负荷装置与连锁切负荷装置等自动限电装置的负荷，装有低频减负荷装"},{"i":27,"n":"第二十七条","txt":"对于未列入超计划用电限电序位表的超用电单位，调度值班人员应当予以警告，责令其在十五分钟内自行限电;届时未自行限至计划值者，调度值班人员可以对其发布限电指令，当超计划用电威胁电网安全运行时，可以部分或者全部暂时停止其供电。"},{"i":28,"n":"第二十八条","txt":"并网运行的发电厂、机组、变电站均必须纳入调度管辖范围，服从调度机构的统一调度;两个或者两个以上电网并网运行，互联电网中必须确定一个最高电网调度机构，按统一调度、分级管理的原则，明确其他调度机构的层级关系，下级调度机构必须服从上级调度机构的统一调度。"},{"i":29,"n":"第二十九条","txt":"需要并网运行的发电厂、机组、变电站或者电网与所并入的电网之间，应当在并网前按国家有关法规，根据平等互利、协商一致的原则签订并网协议，只有签订了并网协议才能并网运行;并网运行的各方必须严格执行协议。 协商一致必须以服从统一调度为前提，以《条例》为依据，以电网安全、优质、经济运行为目的，并符合国家有关电网管理的法律、行政法规、电力行政主管部门和电网管理部门的规章制度、规程、规定、规范等。"},{"i":30,"n":"第三十条","txt":"需并网运行的发电厂、机组、变电站或者电网，在与有关电网管理部门签订并网协议之前，应当提出并网申请，由有关电网管理部门审查其是否符合并网运行的条件。 需并网运行的发电厂、机组、变电站或者电网必须具有接受电网统一调度的技术装备和管理设施，应当具备以下基本条件： (一)新投产设备已通过试运行和启动验收(必须有有关电网管理部门的代表参加); (二)接受电网统一调度的技术装备和管理设施齐备; (三)已向有关电网管理部门提交齐全的技术资料; (四)与有关电网调度机构间的通信通道符合规定，并已具备投运条件; (五)按电力行业标准、规程设计安装的继电保护、安全自动装置已具备投运条件，电网运行所需的安全措施已落实; (六)远动设施已按电力行业标准、规程设计建成，远动信息具备送入有关电网调度机构的电网调度自动化系统的条件; (七)与并网运行有关的计量装置安装齐备并经验收合格; (八)具备正常生产运行的其它"},{"i":31,"n":"第三十一条","txt":"满足并网运行条件的发电厂、机组、变电站或者电网申请并网运行，有关电网管理部门应当予以受理，按规定签订并网协议。并网协议应当包括以下基本内容： (一)经济内容： (1)电量购、销办法; (2)电价和结算办法; (3)计量和考核办法; (4)违约责任和奖惩办法; (5)意外灾害的处理办法; (6)纠纷处理办法; (7)并网双方协商一致的其他内容条款。 (二)调度内容： (1)界定调度管辖范围的条款; (2)按统一的规程、规章、规定施行调度和服从电网统一调度的条款; (3)有关运行方式的条款; (4)按规定履行调峰、调频、调压的义务条款; (5)设备检修的条款; (6)布置和实施电网安全稳定措施的条款; (7)编制和执行发电、送(受)电调度计划条款，该计划原则上应当能满足发电厂完成协议规定的发电量的运行条件(电厂自身原因除外); (8)通信、自动化设备运行及维护条款; (9)违约责任和奖惩条"},{"i":32,"n":"第三十二条","txt":"对违反《条例》规定的责任人员，其所在单位，即有人事管辖权的同级单位，依照《条例》第二十七条规定给予责任人行政处分。如果其所在单位不予处分，与其所在单位有行政隶属关系的上级单位可以直接给予责任人行政处分。 行政处分按行政管理权限作出，调度机构及其他单位和个人可以提出控告和建议。"},{"i":33,"n":"第三十三条","txt":"依照《条例》第二十八条规定，该条中所列的有关措施，调度机构是唯一的行使职权的单位。电力行政主管部门、电网管理部门，可以向调度机构提出要求或者建议，不可以超越或者代替调度机构行使该职权。"},{"i":34,"n":"第三十四条","txt":"对违反《条例》规定，未按照调度计划供电或者无故调减供电计划的，有关供电部门应当根据用户的需要补给少供的电力、电量。 各级电网调度机构应当模范遵守《条例》。调度系统的值班人员玩忽职守、徇私舞弊、以权谋私等，由电网调度机构或者电网管理部门或者其所在单位给予行政处分。"},{"i":35,"n":"第三十五条","txt":"违反《条例》规定，有构成违反治安管理行为的，由公安机关处罚;构成犯罪的，由司法机关依法追究刑事责任。 电力行政主管部门、电网管理部门、调度机构负责举报和提出追诉请求。"},{"i":36,"n":"第三十六条","txt":"各省、市、自治区人民政府依照《条例》制订的小电网管理办法，可以由当地电力行政主管部门与各有关部门共同参与协调，其内容不得违反《条例》规定。"},{"i":37,"n":"第三十七条","txt":"本实施办法自公布之日起施行。"}],"dianwangyunxingguize":[{"i":1,"n":"第一条","txt":"为了保障电力系统安全、优质、经济运行，维护社会公共利益和电力投资者、经营者、使用者的合法权益，根据《中华人民共和国电力法》、《电力监管条例》和《电网调度管理条例》，制定本规则。"},{"i":2,"n":"第二条","txt":"电网运行坚持安全第一、预防为主的方针。电网企业及其电力调度机构、电网使用者和相关单位应当共同维护电网的安全稳定运行。"},{"i":3,"n":"第三条","txt":"电网运行实行统一调度、分级管理。 电力调度应当公开、公平、公正。 本规则所称电力调度，是指电力调度机构(以下简称调度机构)对电网运行进行的组织、指挥、指导和协调。"},{"i":4,"n":"第四条","txt":"国家电力监管委员会及其派出机构(以下简称电力监管机构)依法对电网运行实施监管。"},{"i":5,"n":"第五条","txt":"本规则适用于省级以上调度机构及其调度管辖范围内的电网企业、电网使用者和相关规划设计、施工建设、安装调试、研究开发等单位。"},{"i":6,"n":"第六条","txt":"电力系统的规划、设计和建设应当遵守国家有关规定和有关国家标准、行业标准。"},{"i":7,"n":"第七条","txt":"电网与电源建设应当统筹考虑，合理布局，协调发展。 电网结构应当安全可靠、经济合理、技术先进、运行灵活，符合《电力系统安全稳定导则》和《电力系统技术导则》的要求。"},{"i":8,"n":"第八条","txt":"经政府有关部门依法批准或者核准的拟并网机组，电网企业应当按期完成相应的电网一次设备、二次设备的建设、调试、验收和投入使用，保证并网机组电力送出的必要网络条件。"},{"i":9,"n":"第九条","txt":"电力二次系统应当统一规划、统一设计，并与电力一次系统的规划、设计和建设同步进行。电网使用者的二次设备和系统应当符合电网二次系统技术规范。"},{"i":10,"n":"第十条","txt":"涉及电网运行的接口技术规范，由调度机构组织制定，并报电力监管机构备案后施行。拟并网设备应当符合接口技术规范。"},{"i":11,"n":"第十一条","txt":"电网企业和电网使用者应当采用符合国家标准、行业标准和相关国际标准，并经政府有关部门核准资质的检验机构检验合格的产品。"},{"i":12,"n":"第十二条","txt":"在采购与电网运行相关或者可能影响电网运行特性的设备前，业主方应当组织包括调度机构在内的有关机构和专家对技术规范书进行评审。"},{"i":13,"n":"第十三条","txt":"电网企业、电网使用者和受业主委托工作的相关单位，应当交换规划设计、施工调试等工作所需资料。"},{"i":14,"n":"第十四条","txt":"新建、改建、扩建的发电工程、输电工程和变电工程投入运行前，拟并网方应当按照要求向调度机构提交并网调度所必需的资料。资料齐备的，调度机构应当按照规定程序向拟并网方提供继电保护、安全自动装置的定值和调度自动化、电力通信等设备的技术参数。"},{"i":15,"n":"第十五条","txt":"新建、改建、扩建的发电工程、输电工程和变电工程投入运行前，调度机构应当对拟并网方的新设备启动并网提供有关技术指导和服务，适时编制新设备启动并网调度方案和有关技术要求，并协调组织实施。拟并网方应当按照新设备启动并网调度方案完成启动准备工作。"},{"i":16,"n":"第十六条","txt":"新建、改建、扩建的发电工程、输电工程和变电工程投入运行前，拟并网方的二次系统应当完成与调度机构的联合调试、定值和数据核对等工作，并交换并网调试和运行所必需的数据资料。"},{"i":17,"n":"第十七条","txt":"新建、改建、扩建的发电工程、输电工程和变电工程投入运行前，调度机构应当根据国家有关规定、技术标准和规程，组织认定拟并网方的并网基本条件。拟并网方不符合并网基本条件的，调度机构应当向拟并网方提出改进意见。"},{"i":18,"n":"第十八条","txt":"发电厂需要并网运行的，并网双方应当在并网前签订并网调度协议。 电网与电网需要互联运行的，互联双方应当在互联前签订互联调度协议。 并网双方或者互联双方应当根据平等互利、协商一致和确保电力系统安全运行的原则签订协议并严格执行。"},{"i":19,"n":"第十九条","txt":"发电厂、电网不得擅自并网或者互联，不得擅自解网。"},{"i":20,"n":"第二十条","txt":"新建、改建、扩建的发电机组并网应当具备下列基本条件： (一)新投产的电气一次设备的交接试验项目完整，符合有关标准和规程。 (二)发电机组装设符合国家标准或者行业标准的连续式自动电压调节器;100兆瓦以上火电机组、核电机组，50兆瓦以上水电机组的励磁系统原则上配备电力系统稳定器或者具备电力系统稳定器功能。 (三)发电机组参与一次调频。 (四)参与二次调频的100兆瓦以上的火电机组，40兆瓦以上非灯泡贯流式水电机组和抽水蓄能机组原则上具备自动发电控制功能，参与电网闭环自动发电控制;特殊机组根据其特性确定调频要求。 (五)发电机组具备进相运行的能力，机组实际进相运行能力根据机组参数和进相试验结果确定。 (六)拟并网方在调度机构的统一协调下完成发电机励磁系统、调速系统、电力系统稳定器、发电机进相能力、自动发电控制、自动电压控制、一次调频等调试，其性能和参数符合电网安全稳定运行需要;调试由具有资"},{"i":21,"n":"第二十一条","txt":"发电厂与电网连接处应当装设断路器。断路器的遮断容量、故障清除时间和继电保护配置应当符合所在电网的技术要求。 分、合操作频繁的抽水蓄能电厂的主断路器，其开断容量和开断次数应当具有比常规电厂的主断路器更大的设计裕量。"},{"i":22,"n":"第二十二条","txt":"主网直供用户并网应当具备下列基本条件： (一)主网直供用户向电网企业及其调度机构提供必要的数据，并能够向调度机构传送必要的实时信息。 (二)主网直供用户的电能量计量点设在并网线路的产权分界处，电能量计量点处安装计量上网电量和受网电量的具有双向、分时功能的有功、无功电能表，并能将电能量信息传输至调度机构。 (三)主网直供用户合理装设无功补偿装置、谐波抑制装置、自动电压控制装置、自动低频低压减负荷装置和负荷控制装置，并根据调度机构的要求整定参数和投入运行;主网直供用户的生产负荷与生活负荷在配电上分开，以满足负荷控制需要。"},{"i":23,"n":"第二十三条","txt":"继电保护、安全自动装置、调度自动化、电力通信等电力二次系统设备应当符合调度机构组织制定的技术体制和接口规范。电力二次系统设备的技术体制和接口规范报电力监管机构备案后施行。"},{"i":24,"n":"第二十四条","txt":"接入电网运行的电力二次系统应当符合《电力二次系统安全防护规定》和其他有关规定。"},{"i":25,"n":"第二十五条","txt":"电网互联双方应当联合进行频率控制、联络线控制、无功电压控制;根据联网后的变化，制定或者修正黑启动方案，修正本网的自动低频、低压减负荷方案;按照电网稳定运行需要协商确定安全自动装置配置方案。"},{"i":26,"n":"第二十六条","txt":"除发生事故或者实行特殊运行方式外，电力系统频率、并网点电压的运行偏差应当符合国家标准和电力行业标准。 在发生事故的情况下，发电机组和其他相关设备运行特性对频率变化的适应能力仍应当符合国家标准。"},{"i":27,"n":"第二十七条","txt":"电网使用者向电网注入的谐波应当不超过国家标准和电力行业标准。并入电网运行的电气设备应当能够承受国家标准允许的因谐波和三相不平衡导致的电压波形畸变。"},{"i":28,"n":"第二十八条","txt":"电网企业与电网使用者的设备产权和维护分界点应当根据有关电力法律、法规确定，并在有关协议中详细划分并网或者互联设备的所有权和安全责任。"},{"i":29,"n":"第二十九条","txt":"接入电网运行的设备调度管辖权，不受设备所有权或者资产管理权等的限制。"},{"i":30,"n":"第三十条","txt":"电网企业及其调度机构有责任保障电网频率电压稳定和可靠供电;调度机构应当合理安排运行方式，优化调度，维持电力平衡，保障电力系统的安全、优质、经济运行。 调度机构应当向电力监管机构报送年度运行方式。"},{"i":31,"n":"第三十一条","txt":"调度机构依照国家有关规定组织制定电力调度管理规程，并报电力监管机构备案。电网企业及其调度机构、电网使用者和相关单位应当执行电力调度管理规程。"},{"i":32,"n":"第三十二条","txt":"电网企业及其调度机构应当加强负荷预测，做好长期、中期、短期和超短期负荷预测工作，提高负荷预测准确率。"},{"i":33,"n":"第三十三条","txt":"主网直供用户应当根据有关规定，按时向所属调度机构报送其主要接装容量和年用电量预测，按时申报年度、月度用电计划。"},{"i":34,"n":"第三十四条","txt":"调度机构应当编制和下达发电调度计划、供(用)电调度计划和检修计划。"},{"i":35,"n":"第三十五条","txt":"编制发电调度计划、供(用)电调度计划应当依据省级人民政府下达的调控目标和市场形成的电力交易计划，综合考虑社会用电需求、检修计划和电力系统设备能力等因素，并保留必要、合理的备用容量。调度计划应当经过安全校核。"},{"i":36,"n":"第三十六条","txt":"水电调度运行应当充分利用水能资源，严格执行经审批的水库综合利用方案，确保大坝安全，防止发生洪水漫坝、水淹厂房事故。 水电厂应当及时、准确、可靠地向调度机构传输水库运行相关信息。 实施联合运行的梯级水库群，发电企业应当向调度机构提出优化调度方案。"},{"i":37,"n":"第三十七条","txt":"发电企业应当按照发电调度计划和调度指令发电;主网直供用户应当按照供(用)电调度计划和调度指令用电。 对于不按照调度计划和调度指令发电的，调度机构应当予以警告;经警告拒不改正的，调度机构可以暂时停止其并网运行。 对于不按照调度计划和调度指令用电的，调度机构应当予以警告;经警告拒不改正的，调度机构可以暂时部分或者全部停止向其供电。"},{"i":38,"n":"第三十八条","txt":"电网企业、电网使用者应当根据本单位电力设备的健康状况，向调度机构提出年度、月度检修预安排申请;调度机构应当在检修预安排申请的基础上根据电力系统设备的健康水平和运行能力，与申请单位协商，统筹兼顾，编制年度、月度检修计划。"},{"i":39,"n":"第三十九条","txt":"电网企业、电网使用者应当按照检修计划安排检修工作，加强设备运行维护，减少非计划停运和事故。 电网企业、电网使用者可以提出临时检修申请，调度机构应当及时答复，并在电网运行允许的情况下予以安排。"},{"i":40,"n":"第四十条","txt":"电网企业和电网使用者应当提供用于维护电压、频率稳定和电网故障后恢复等方面的辅助服务。辅助服务的调度由调度机构负责。"},{"i":41,"n":"第四十一条","txt":"电网的无功补偿实行分层分区、就地平衡的原则。调度机构负责电网无功的平衡和调整，必要时制定改进措施，由电网企业和电网使用者组织实施。调度机构按照调度管辖范围分级负责电网各级电压的调整、控制和管理。接入电网运行的发电厂、变电站等应当按照调度机构确定的电压运行范围进行调节。"},{"i":42,"n":"第四十二条","txt":"调度机构在电网出现有功功率不能满足需求、超稳定极限、电力系统故障、持续的频率降低或者电压超下限、备用容量不足等情况时，可以按照有关地方人民政府批准的事故限电序位表和保障电力系统安全的限电序位表进行限电操作。电网使用者应当按照负荷控制方案在电网企业及其调度机构的指导下实施负荷控制。"},{"i":43,"n":"第四十三条","txt":"发生威胁电力系统安全运行的紧急情况时，调度机构值班人员应当立即采取措施，避免事故发生和防止事故扩大。必要时，可以根据电力市场运营规则，通过调整系统运行方式等手段对电力市场实施干预，并按照规定向电力监管机构报告。"},{"i":44,"n":"第四十四条","txt":"调度机构负责电网的高频切机、低频自启动机组容量的管理，统一编制自动低频、低压减负荷方案并组织实施，定期进行系统实测。"},{"i":45,"n":"第四十五条","txt":"继电保护、安全自动装置、调度自动化、电力通信等二次系统设备的运行维护、统计分析、整定配合，按照所在电网的调度管理规程和现场运行管理规程进行。"},{"i":46,"n":"第四十六条","txt":"电网企业及其调度机构应当根据国家有关规定和有关国家标准、行业标准，制订和完善电网反事故措施、系统黑启动方案、系统应急机制和反事故预案。 电网使用者应当按照电网稳定运行要求编制反事故预案，并网发电厂应当制订全厂停电事故处理预案，并报调度机构备案。 电网企业、电网使用者应当按照设备产权和运行维护责任划分，落实反事故措施。 调度机构应当定期组织联合反事故演习，电网企业和电网使用者应当按照要求参加联合反事故演习。"},{"i":47,"n":"第四十七条","txt":"电网企业和电网使用者应当开展电力可靠性管理工作、安全性评价工作和技术监督工作，提高安全运行水平。"},{"i":48,"n":"第四十八条","txt":"地(市)级以下调度机构及其调度管辖范围内的电网企业、电网使用者和相关单位参照本规则执行。"},{"i":49,"n":"第四十九条","txt":"本规则所称电网使用者是指通过电网完成电力生产和消费的单位，包括发电企业(含自备发电厂)、主网直供用户等。 本规则所称主网直供用户是指与省(直辖市、自治区)级以上电网企业签订购售电合同的用户或者通过电网直接向发电企业购电的用户。"},{"i":50,"n":"第五十条","txt":"本规则自2007年1月1日起施行。"}],"shengbujikexuejishujiangliguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范省、部级科学技术奖励的设立和备案工作，加强对省、部级科学技术奖励工作的管理和指导，根据《国家科学技术奖励条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"省、部级科学技术奖应当制定公平、公开、公正的评审规则，建立科学的评价指标，严格规范推荐、评审、授奖程序，保障科学技术奖励的科学性、公正性和权威性，保证科学技术奖励的质量和水平。"},{"i":3,"n":"第三条","txt":"省、自治区、直辖市人民政府可以设立一项省级科学技术奖（以下称省级科学技术奖）。省级科学技术奖可以分类奖励在科学研究、技术创新与开发、推广应用先进科学技术成果以及实现高新技术产业化等方面取得重大科学技术成果或者做出突出贡献的个人和组织。 省、自治区、直辖市人民政府所属部门不再设立科学技术奖。"},{"i":4,"n":"第四条","txt":"省级科学技术奖励数额由省、自治区、直辖市人民政府根据本地区科技、经济、社会发展状况确定，应当严格控制奖励数额。"},{"i":5,"n":"第五条","txt":"省级科学技术奖根据本地区实际情况，可以自行设立奖励等级。"},{"i":6,"n":"第六条","txt":"省、自治区、直辖市人民政府可以成立以科学技术专家、学者为主的省级科学技术奖评审机构，负责评审工作。省、自治区、直辖市科学技术行政部门负责评审的组织工作和日常管理工作。"},{"i":7,"n":"第七条","txt":"中央、国务院各部委所属的科研院所、大专院校、企业等完成的科学技术成果及其完成人，可以在成果实施应用地或者本机构所在地参加省级科学技术奖的评审。省级科学技术奖的管理部门和评审机构应当积极受理、公正评审。"},{"i":8,"n":"第八条","txt":"省级科学技术奖应当实行异议制度，接受社会监督。"},{"i":9,"n":"第九条","txt":"省级科学技术奖由省、自治区、直辖市人民政府颁发获奖证书和奖金。 省级科学技术奖的奖励经费由地方财政列支。"},{"i":10,"n":"第十条","txt":"省级科学技术奖的推荐、评审、授奖的经费管理，按照国家有关规定执行。"},{"i":11,"n":"第十一条","txt":"根据国防、国家安全的特殊情况，国防科学技术工业委员会、公安部、国家安全部可以设立部级科学技术奖。部级科学技术奖的奖励范围只涉及国防和国家安全，并由于国家安全和保密不能公开的项目。 民用项目不属于部级科学技术奖的奖励范围。上述部门所属单位完成的民用项目可以参照本办法第七条的规定推荐省级科学技术奖。 中国人民解放军有关科学技术奖奖励办法可以参照本办法自行制定。 国务院所属其他部门不再设立部级科学技术奖。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市和中央、国务院其他部门所属单位完成的涉及国防、国家安全的项目，按项目所属专业领域向本办法第十一条规定的部门推荐部级科学技术奖。部级科学技术奖的管理部门和评审机构应当积极受理、公正评审。"},{"i":13,"n":"第十三条","txt":"部级科学技术奖实行异议制度，并按照有关保密规定，在适当范围内征求意见。"},{"i":14,"n":"第十四条","txt":"部级科学技术奖的其他工作，可以参照本办法有关省级科学技术奖的条款执行。"},{"i":15,"n":"第十五条","txt":"科学技术部负责省、部级科学技术奖的备案审查工作。 设立省、部级科学技术奖的具体办法应当按有关规定报科学技术部备案。 科学技术部在备案审查中，发现省、部级科学技术奖的设立、评审等与有关法律、行政法规相抵触、违背或者有矛盾的，可以责成制定机关进行修改，或者依照法律规定的权限，提请有关机关予以改变或者撤消。"},{"i":16,"n":"第十六条","txt":"省、部级科学技术奖的奖励情况，应当以年报形式报送国家科学技术奖励工作办公室。"},{"i":17,"n":"第十七条","txt":"本办法自发布之日起施行。"}],"shehuijuanzengyundongyuanjiaolianyuanjiangjinjiang676542":[{"i":1,"n":"第一条","txt":"为了加强对社会捐赠(赞助)运动员、教练员奖金、奖品的管理，更好地调动各方面的积极性，促进体育事业的健康发展，根据有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"社会捐赠(赞助)的奖金、奖品是指各类社会组织和个人捐赠(赞助)给运动员、教练员及其他有功人员的人民币、自由外汇及实物。"},{"i":3,"n":"第三条","txt":"社会捐赠(赞助)的奖金、奖品按下列程序接收和分配： (一)捐赠(赞助)者以亚洲及亚洲以上单项比赛或其他名义捐赠(赞助)给运动员、教练员及有功人员的奖金、奖品，由全国性单项体育协会接收并按下列原则分配：捐赠(赞助)的奖金按不低于70%奖励运动员、教练员及其他有功人员，其余部分留作单项体育协会发展基金；捐赠(赞助)的奖品由全国性单项体育协会制定具体处理办法。 (二)捐赠(赞助)给参加亚洲及亚洲以上综合性运动会运动员、教练员及有功人员的奖金、奖品，由中国奥委会设立的专门小组接收。其中：捐赠(赞助)给除运动员、教练员以外的有功人员的奖金、奖品，由专门小组制定办法并具体组织实施；捐赠(赞助)给运动员、教练员的奖金、奖品的分配办法由协会按第三条第(一)项的规定执行。"},{"i":4,"n":"第四条","txt":"获得社会捐赠(赞助)奖金、奖品的个人，应按国家有关规定，缴纳个人所得税。"},{"i":5,"n":"第五条","txt":"各训练单位、运动队和个人不得接收社会捐赠(赞助)的奖金、奖品。"},{"i":6,"n":"第六条","txt":"捐赠(赞助)方与接收捐赠(赞助)方应签订有关协议，并严格按协议规定执行。 捐赠(赞助)者要求举行捐赠(赞助)仪式或召开新闻发布会的，应在签定协议前，报请国家体委宣传司批准。"},{"i":7,"n":"第七条","txt":"全国性单项体育协会对本办法所规定的社会捐赠(赞助)奖金、奖品的分配、使用和管理要制定具体实施细则，报国家体委批准后实施。"},{"i":8,"n":"第八条","txt":"违反本规定的体育组织和个人，由中国奥委会或全国性单项体育协会收缴其违纪所得，并视情节轻重，给予处罚，必要时国家体委还将追究有关人员的行政责任。"},{"i":9,"n":"第九条","txt":"捐赠(赞助)给参加全国及全国以下各类比赛运动员、教练员及有功人员的奖金和奖品的接收、分配，由各省、自治区、直辖市体委结合本地区的实际情况，参照本办法的有关规定，制定具体办法，经主管部门批准后实施，并报国家体委备案。"},{"i":10,"n":"第十条","txt":"本办法由国家体委负责解释。"},{"i":11,"n":"第十一条","txt":"本办法自发布之日起施行"}],"jinzhifeiyixuexuyaodetaierxingbiejiandinghexuanzexa67d89":[{"i":1,"n":"第一条","txt":"为了贯彻计划生育基本国策，促进出生人口性别结构平衡，促进人口均衡发展，根据《中华人民共和国人口与计划生育法》、《中华人民共和国母婴保健法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"非医学需要的胎儿性别鉴定和选择性别人工终止妊娠，是指除经医学诊断胎儿可能为伴性遗传病等需要进行胎儿性别鉴定和选择性别人工终止妊娠以外，所进行的胎儿性别鉴定和选择性别人工终止妊娠。"},{"i":3,"n":"第三条","txt":"禁止任何单位或者个人实施非医学需要的胎儿性别鉴定和选择性别人工终止妊娠。 禁止任何单位或者个人介绍、组织孕妇实施非医学需要的胎儿性别鉴定和选择性别人工终止妊娠。"},{"i":4,"n":"第四条","txt":"各级卫生计生行政部门和食品药品监管部门应当建立查处非医学需要的胎儿性别鉴定和选择性别人工终止妊娠违法行为的协作机制和联动执法机制，共同实施监督管理。 卫生计生行政部门和食品药品监管部门应当按照各自职责，制定胎儿性别鉴定、人工终止妊娠以及相关药品和医疗器械等管理制度。"},{"i":5,"n":"第五条","txt":"县级以上卫生计生行政部门履行以下职责： （一）监管并组织、协调非医学需要的胎儿性别鉴定和选择性别人工终止妊娠的查处工作； （二）负责医疗卫生机构及其从业人员的执业准入和相关医疗器械使用监管，以及相关法律法规、执业规范的宣传培训等工作； （三）负责人口信息管理系统的使用管理，指导医疗卫生机构及时准确地采集新生儿出生、死亡等相关信息； （四）法律、法规、规章规定的涉及非医学需要的胎儿性别鉴定和选择性别人工终止妊娠的其他事项。"},{"i":6,"n":"第六条","txt":"县级以上工商行政管理部门（包括履行工商行政管理职责的市场监督管理部门，下同）对含有胎儿性别鉴定和人工终止妊娠内容的广告实施监管，并依法查处违法行为。"},{"i":7,"n":"第七条","txt":"食品药品监管部门依法对与胎儿性别鉴定和人工终止妊娠相关的药品和超声诊断仪、染色体检测专用设备等医疗器械的生产、销售和使用环节的产品质量实施监管，并依法查处相关违法行为。"},{"i":8,"n":"第八条","txt":"禁止非医学需要的胎儿性别鉴定和选择性别人工终止妊娠的工作应当纳入计划生育目标管理责任制。"},{"i":9,"n":"第九条","txt":"符合法定生育条件，除下列情形外，不得实施选择性别人工终止妊娠： （一）胎儿患严重遗传性疾病的； （二）胎儿有严重缺陷的； （三）因患严重疾病，继续妊娠可能危及孕妇生命安全或者严重危害孕妇健康的； （四）法律法规规定的或医学上认为确有必要终止妊娠的其他情形。"},{"i":10,"n":"第十条","txt":"医学需要的胎儿性别鉴定，由省、自治区、直辖市卫生计生行政部门批准设立的医疗卫生机构按照国家有关规定实施。 实施医学需要的胎儿性别鉴定，应当由医疗卫生机构组织三名以上具有临床经验和医学遗传学知识，并具有副主任医师以上的专业技术职称的专家集体审核。经诊断，确需人工终止妊娠的，应当出具医学诊断报告，并由医疗卫生机构通报当地县级卫生计生行政部门。"},{"i":11,"n":"第十一条","txt":"医疗卫生机构应当在工作场所设置禁止非医学需要的胎儿性别鉴定和选择性别人工终止妊娠的醒目标志；医务人员应当严格遵守有关法律法规和超声诊断、染色体检测、人工终止妊娠手术管理等相关制度。"},{"i":12,"n":"第十二条","txt":"实施人工终止妊娠手术的机构应当在手术前登记、查验受术者身份证明信息，并及时将手术实施情况通报当地县级卫生计生行政部门。"},{"i":13,"n":"第十三条","txt":"医疗卫生机构发生新生儿死亡的，应当及时出具死亡证明，并向当地县级卫生计生行政部门报告。 新生儿在医疗卫生机构以外地点死亡的，监护人应当及时向当地乡（镇）人民政府、街道办事处卫生计生工作机构报告；乡（镇）人民政府、街道办事处卫生计生工作机构应当予以核查，并向乡镇卫生院或社区卫生服务中心通报有关信息。"},{"i":14,"n":"第十四条","txt":"终止妊娠药品目录由国务院食品药品监管部门会同国务院卫生计生行政部门制定发布。 药品生产、批发企业仅能将终止妊娠药品销售给药品批发企业或者获准施行终止妊娠手术的医疗卫生机构。药品生产、批发企业销售终止妊娠药品时，应当按照药品追溯有关规定，严格查验购货方资质，做好销售记录。禁止药品零售企业销售终止妊娠药品。 终止妊娠的药品，仅限于在获准施行终止妊娠手术的医疗卫生机构的医师指导和监护下使用。 经批准实施人工终止妊娠手术的医疗卫生机构应当建立真实、完整的终止妊娠药品购进记录，并为终止妊娠药品使用者建立完整档案。"},{"i":15,"n":"第十五条","txt":"医疗器械销售企业销售超声诊断仪、染色体检测专用设备等医疗器械，应当核查购买者的资质，验证机构资质并留存复印件，建立真实、完整的购销记录；不得将超声诊断仪、染色体检测专用设备等医疗器械销售给不具有相应资质的机构和个人。"},{"i":16,"n":"第十六条","txt":"医疗卫生、教学科研机构购置可用于鉴定胎儿性别的超声诊断仪、染色体检测专用设备等医疗器械时，应当提供机构资质原件和复印件，交销售企业核查、登记，并建立进货查验记录制度。"},{"i":17,"n":"第十七条","txt":"违法发布非医学需要的胎儿性别鉴定或者非医学需要的选择性别人工终止妊娠广告的，由工商行政管理部门依据《中华人民共和国广告法》等相关法律法规进行处罚。 对广告中涉及的非医学需要的胎儿性别鉴定或非医学需要的选择性别人工终止妊娠等专业技术内容，工商行政管理部门可根据需要提请同级卫生计生行政部门予以认定。"},{"i":18,"n":"第十八条","txt":"违反规定利用相关技术为他人实施非医学需要的胎儿性别鉴定或者选择性别人工终止妊娠的，由县级以上卫生计生行政部门依据《中华人民共和国人口与计划生育法》等有关法律法规进行处理；对医疗卫生机构的主要负责人、直接负责的主管人员和直接责任人员，依法给予处分。"},{"i":19,"n":"第十九条","txt":"对未取得母婴保健技术许可的医疗卫生机构或者人员擅自从事终止妊娠手术的、从事母婴保健技术服务的人员出具虚假的医学需要的人工终止妊娠相关医学诊断意见书或者证明的，由县级以上卫生计生行政部门依据《中华人民共和国母婴保健法》及其实施办法的有关规定进行处理；对医疗卫生机构的主要负责人、直接负责的主管人员和直接责任人员，依法给予处分。"},{"i":20,"n":"第二十条","txt":"经批准实施人工终止妊娠手术的机构未建立真实完整的终止妊娠药品购进记录，或者未按照规定为终止妊娠药品使用者建立完整用药档案的，由县级以上卫生计生行政部门责令改正；拒不改正的，给予警告，并可处1万元以上3万元以下罚款；对医疗卫生机构的主要负责人、直接负责的主管人员和直接责任人员，依法进行处理。"},{"i":21,"n":"第二十一条","txt":"药品生产企业、批发企业将终止妊娠药品销售给未经批准实施人工终止妊娠的医疗卫生机构和个人，或者销售终止妊娠药品未查验购药者的资格证明、未按照规定作销售记录的，以及药品零售企业销售终止妊娠药品的，由县级以上食品药品监管部门按照《中华人民共和国药品管理法》的有关规定进行处理。"},{"i":22,"n":"第二十二条","txt":"医疗器械生产经营企业将超声诊断仪、染色体检测专用设备等医疗器械销售给无购买资质的机构或者个人的，由县级以上食品药品监管部门责令改正，处1万元以上3万元以下罚款。"},{"i":23,"n":"第二十三条","txt":"介绍、组织孕妇实施非医学需要的胎儿性别鉴定或者选择性别人工终止妊娠的，由县级以上卫生计生行政部门责令改正，给予警告；情节严重的，没收违法所得，并处5000元以上3万元以下罚款。"},{"i":24,"n":"第二十四条","txt":"鼓励任何单位和个人举报违反本规定的行为。举报内容经查证属实的，应当依据有关规定给予举报人相应的奖励。"},{"i":25,"n":"第二十五条","txt":"本规定自2016年5月1日起施行。2002年11月29日原国家计生委、原卫生部、原国家药品监管局公布的《关于禁止非医学需要的胎儿性别鉴定和选择性别的人工终止妊娠的规定》同时废止。"}],"kexuejishubaomiguiding":[{"i":1,"n":"第一条","txt":"为保障国家科学技术秘密安全，促进科学技术事业发展，根据《中华人民共和国保守国家秘密法》《中华人民共和国科学技术进步法》和《中华人民共和国保守国家秘密法实施条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称国家科学技术秘密，是指科学技术规划、计划、项目及成果中，关系国家安全和利益，依照法定程序确定，在一定时间内只限一定范围的人员知悉的事项。"},{"i":3,"n":"第三条","txt":"涉及国家科学技术秘密的国家机关、单位（以下简称机关、单位）以及个人开展保守国家科学技术秘密的工作（以下简称科学技术保密工作），适用本规定。"},{"i":4,"n":"第四条","txt":"科学技术保密工作坚持积极防范、突出重点、依法管理的方针，既保障国家科学技术秘密安全，又促进科学技术发展。"},{"i":5,"n":"第五条","txt":"科学技术保密工作应当与科学技术管理工作相结合，同步规划、部署、落实、检查、总结和考核，实行全程管理。"},{"i":6,"n":"第六条","txt":"国家科学技术行政管理部门管理全国的科学技术保密工作。省、自治区、直辖市科学技术行政管理部门管理本行政区域的科学技术保密工作。 中央国家机关在其职责范围内，管理或者指导本行业、本系统的科学技术保密工作。"},{"i":7,"n":"第七条","txt":"国家保密行政管理部门依法对全国的科学技术保密工作进行指导、监督和检查。县级以上地方各级保密行政管理部门依法对本行政区域的科学技术保密工作进行指导、监督和检查。"},{"i":8,"n":"第八条","txt":"机关、单位应当实行科学技术保密工作责任制，健全科学技术保密管理制度，完善科学技术保密防护措施，开展科学技术保密宣传教育，加强科学技术保密检查。"},{"i":9,"n":"第九条","txt":"关系国家安全和利益，泄露后可能造成下列后果之一的科学技术事项，应当确定为国家科学技术秘密： （一）削弱国家防御和治安能力； （二）降低国家科学技术国际竞争力； （三）制约国民经济和社会长远发展； （四）损害国家声誉、权益和对外关系。 国家科学技术秘密及其密级的具体范围（以下简称国家科学技术保密事项范围），由国家保密行政管理部门会同国家科学技术行政管理部门另行制定。"},{"i":10,"n":"第十条","txt":"国家科学技术秘密的密级分为绝密、机密和秘密三级。国家科学技术秘密密级应当根据泄露后可能对国家安全和利益造成的损害程度确定。 除泄露后会给国家安全和利益带来特别严重损害的外，科学技术原则上不确定为绝密级国家科学技术秘密。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的科学技术事项，不得确定为国家科学技术秘密： （一）国内外已经公开； （二）难以采取有效措施控制知悉范围； （三）无国际竞争力且不涉及国家防御和治安能力； （四）已经流传或者受自然条件制约的传统工艺。"},{"i":12,"n":"第十二条","txt":"中央国家机关、省级机关及其授权的机关、单位可以确定绝密级、机密级和秘密级国家科学技术秘密；设区的市、自治州一级的机关及其授权的机关、单位可以确定机密级、秘密级国家科学技术秘密。"},{"i":13,"n":"第十三条","txt":"国家科学技术秘密定密授权应当符合国家秘密定密管理的有关规定。中央国家机关作出的国家科学技术秘密定密授权，应当向国家科学技术行政管理部门和国家保密行政管理部门备案。省级机关，设区的市、自治州一级的机关作出的国家科学技术秘密定密授权，应当向省、自治区、直辖市科学技术行政管理部门和保密行政管理部门备案。"},{"i":14,"n":"第十四条","txt":"机关、单位负责人及其指定的人员为国家科学技术秘密的定密责任人，负责本机关、本单位的国家科学技术秘密确定、变更和解除工作。"},{"i":15,"n":"第十五条","txt":"机关、单位和个人产生需要确定为国家科学技术秘密的科学技术事项时，应当先行采取保密措施，并依照下列途径进行定密： （一）属于本规定第十二条规定的机关、单位，根据定密权限自行定密； （二）不属于本规定第十二条规定的机关、单位，向有相应定密权限的上级机关、单位提请定密；没有上级机关、单位的，向有相应定密权限的业务主管部门提请定密；没有业务主管部门的，向所在省、自治区、直辖市科学技术行政管理部门提请定密； （三）个人完成的符合本规定第九条规定的科学技术成果，应当经过评价、检测并确定成熟、可靠后，向所在省、自治区、直辖市科学技术行政管理部门提请定密。"},{"i":16,"n":"第十六条","txt":"实行市场准入管理的技术或者实行市场准入管理的产品涉及的科学技术事项需要确定为国家科学技术秘密的，向批准准入的国务院有关主管部门提请定密。"},{"i":17,"n":"第十七条","txt":"机关、单位在科学技术管理的以下环节，应当及时做好定密工作： （一）编制科学技术规划； （二）制定科学技术计划； （三）科学技术项目立项； （四）科学技术成果评价与鉴定； （五）科学技术项目验收。"},{"i":18,"n":"第十八条","txt":"确定国家科学技术秘密，应当同时确定其名称、密级、保密期限、保密要点和知悉范围。"},{"i":19,"n":"第十九条","txt":"国家科学技术秘密保密要点是指必须确保安全的核心事项或者信息，主要涉及以下内容： （一）不宜公开的国家科学技术发展战略、方针、政策、专项计划； （二）涉密项目研制目标、路线和过程； （三）敏感领域资源、物种、物品、数据和信息； （四）关键技术诀窍、参数和工艺； （五）科学技术成果涉密应用方向； （六）其他泄露后会损害国家安全和利益的核心信息。"},{"i":20,"n":"第二十条","txt":"国家科学技术秘密有下列情形之一的，应当及时变更密级、保密期限或者知悉范围： （一）定密时所依据的法律法规或者国家科学技术保密事项范围已经发生变化的； （二）泄露后对国家安全和利益的损害程度会发生明显变化的。 国家科学技术秘密的变更，由原定密机关、单位决定，也可由其上级机关、单位决定。"},{"i":21,"n":"第二十一条","txt":"国家科学技术秘密的具体保密期限届满、解密时间已到或者符合解密条件的，自行解密。出现下列情形之一时，应当提前解密： （一）已经扩散且无法采取补救措施的； （二）法律法规或者国家科学技术保密事项范围调整后，不再属于国家科学技术秘密的； （三）公开后不会损害国家安全和利益的。 提前解密由原定密机关、单位决定，也可由其上级机关、单位决定。"},{"i":22,"n":"第二十二条","txt":"国家科学技术秘密需要延长保密期限的，应当在原保密期限届满前作出决定并书面通知原知悉范围内的机关、单位或者人员。延长保密期限由原定密机关、单位决定，也可由其上级机关、单位决定。"},{"i":23,"n":"第二十三条","txt":"国家科学技术秘密确定、变更和解除应当进行备案： （一）省、自治区、直辖市科学技术行政管理部门和中央国家机关有关部门每年12月31日前将本行政区域或者本部门当年确定、变更和解除的国家科学技术秘密情况报国家科学技术行政管理部门备案； （二）其他机关、单位确定、变更和解除的国家科学技术秘密，应当在确定、变更、解除后20个工作日内报同级政府科学技术行政管理部门备案。"},{"i":24,"n":"第二十四条","txt":"科学技术行政管理部门发现机关、单位国家科学技术秘密确定、变更和解除不当的，应当及时通知其纠正。"},{"i":25,"n":"第二十五条","txt":"机关、单位对已定密事项是否属于国家科学技术秘密或者属于何种密级有不同意见的，按照国家有关保密规定解决。"},{"i":26,"n":"第二十六条","txt":"国家科学技术行政管理部门管理全国的科学技术保密工作。主要职责如下： （一）制定或者会同有关部门制定科学技术保密规章制度； （二）指导和管理国家科学技术秘密定密工作； （三）按规定审查涉外国家科学技术秘密事项； （四）检查全国科学技术保密工作，协助国家保密行政管理部门查处泄露国家科学技术秘密案件； （五）组织开展科学技术保密宣传教育和培训； （六）表彰全国科学技术保密工作先进集体和个人。 国家科学技术行政管理部门设立国家科技保密办公室，负责国家科学技术保密管理的日常工作。"},{"i":27,"n":"第二十七条","txt":"省、自治区、直辖市科学技术行政管理部门和中央国家机关有关部门，应当设立或者指定专门机构管理科学技术保密工作。主要职责如下： （一）贯彻执行国家科学技术保密工作方针、政策，制定本行政区域、本部门或者本系统的科学技术保密规章制度； （二）指导和管理本行政区域、本部门或者本系统的国家科学技术秘密定密工作； （三）按规定审查涉外国家科学技术秘密事项； （四）监督检查本行政区域、本部门或者本系统的科学技术保密工作，协助保密行政管理部门查处泄露国家科学技术秘密案件； （五）组织开展本行政区域、本部门或者本系统科学技术保密宣传教育和培训； （六）表彰本行政区域、本部门或者本系统的科学技术保密工作先进集体和个人。"},{"i":28,"n":"第二十八条","txt":"机关、单位管理本机关、本单位的科学技术保密工作。主要职责如下： （一）建立健全科学技术保密管理制度； （二）设立或者指定专门机构管理科学技术保密工作； （三）依法开展国家科学技术秘密定密工作，管理涉密科学技术活动、项目及成果； （四）确定涉及国家科学技术秘密的人员（以下简称涉密人员），并加强对涉密人员的保密宣传、教育培训和监督管理； （五）加强计算机及信息系统、涉密载体和涉密会议活动保密管理，严格对外科学技术交流合作和信息公开保密审查； （六）发生资产重组、单位变更等影响国家科学技术秘密管理的事项时，及时向上级机关或者业务主管部门报告。"},{"i":29,"n":"第二十九条","txt":"涉密人员应当遵守以下保密要求： （一）严格执行国家科学技术保密法律法规和规章以及本机关、本单位科学技术保密制度； （二）接受科学技术保密教育培训和监督检查； （三）产生涉密科学技术事项时，先行采取保密措施，按规定提请定密，并及时向本机关、本单位科学技术保密管理机构报告； （四）参加对外科学技术交流合作与涉外商务活动前向本机关、本单位科学技术保密管理机构报告； （五）发表论文、申请专利、参加学术交流等公开行为前按规定履行保密审查手续； （六）发现国家科学技术秘密正在泄露或者可能泄露时，立即采取补救措施，并向本机关、本单位科学技术保密管理机构报告； （七）离岗离职时，与机关、单位签订保密协议，接受脱密期保密管理，严格保守国家科学技术秘密。"},{"i":30,"n":"第三十条","txt":"机关、单位和个人在下列科学技术合作与交流活动中，不得涉及国家科学技术秘密： （一）进行公开的科学技术讲学、进修、考察、合作研究等活动； （二）利用互联网及其他公共信息网络、广播、电影、电视以及公开发行的报刊、书籍、图文资料和声像制品进行宣传、报道或者发表论文； （三）进行公开的科学技术展览和展示等活动。"},{"i":31,"n":"第三十一条","txt":"机关、单位和个人应当加强国家科学技术秘密信息保密管理，存储、处理国家科学技术秘密信息应当符合国家保密规定。任何机关、单位和个人不得有下列行为： （一）非法获取、持有、复制、记录、存储国家科学技术秘密信息； （二）使用非涉密计算机、非涉密存储设备存储、处理国家科学技术秘密； （三）在互联网及其他公共信息网络或者未采取保密措施的有线和无线通信中传递国家科学技术秘密信息； （四）通过普通邮政、快递等无保密措施的渠道传递国家科学技术秘密信息； （五）在私人交往和通信中涉及国家科学技术秘密信息； （六）其他违反国家保密规定的行为。"},{"i":32,"n":"第三十二条","txt":"对外科学技术交流与合作中需要提供国家科学技术秘密的，应当经过批准，并与对方签订保密协议。绝密级国家科学技术秘密原则上不得对外提供，确需提供的，应当经中央国家机关有关主管部门同意后，报国家科学技术行政管理部门批准；机密级国家科学技术秘密对外提供应当报中央国家机关有关主管部门批准；秘密级国家科学技术秘密对外提供应当报中央国家机关有关主管部门或者省、自治区、直辖市人民政府有关主管部门批准。 有关主管部门批准对外提供国家科学技术秘密的，应当在10个工作日内向同级政府科学技术行政管理部门备案。"},{"i":33,"n":"第三十三条","txt":"机关、单位开展涉密科学技术活动的，应当指定专人负责保密工作、明确保密纪律和要求，并加强以下方面保密管理： （一）研究、制定涉密科学技术规划应当制定保密工作方案，签订保密责任书； （二）组织实施涉密科学技术计划应当制定保密制度； （三）举办涉密科学技术会议或者组织开展涉密科学技术展览、展示应当采取必要的保密管理措施，在符合保密要求的场所进行； （四）涉密科学技术活动进行公开宣传报道前应当进行保密审查。"},{"i":34,"n":"第三十四条","txt":"涉密科学技术项目应当按照以下要求加强保密管理： （一）涉密科学技术项目在指南发布、项目申报、专家评审、立项批复、项目实施、结题验收、成果评价、转化应用及科学技术奖励各个环节应当建立保密制度； （二）涉密科学技术项目下达单位与承担单位、承担单位与项目负责人、项目负责人与参研人员之间应当签订保密责任书； （三）涉密科学技术项目的文件、资料及其他载体应当指定专人负责管理并建立台账； （四）涉密科学技术项目进行对外科学技术交流与合作、宣传展示、发表论文、申请专利等，承担单位应当提前进行保密审查； （五）涉密科学技术项目原则上不得聘用境外人员，确需聘用境外人员的，承担单位应当按规定报批。"},{"i":35,"n":"第三十五条","txt":"涉密科学技术成果应当按以下要求加强保密管理： （一）涉密科学技术成果在境内转让或者推广应用，应当报原定密机关、单位批准，并与受让方签订保密协议； （二）涉密科学技术成果向境外出口，利用涉密科学技术成果在境外开办企业，在境内与外资、外企合作，应当按照本规定第三十二条规定报有关主管部门批准。"},{"i":36,"n":"第三十六条","txt":"机关、单位应当按照国家规定，做好国家科学技术秘密档案归档和保密管理工作。"},{"i":37,"n":"第三十七条","txt":"机关、单位应当为科学技术保密工作提供经费、人员和其他必要的保障条件。国家科学技术行政管理部门，省、自治区、直辖市科学技术行政管理部门应当将科学技术保密工作经费纳入部门预算。"},{"i":38,"n":"第三十八条","txt":"机关、单位应当保障涉密人员正当合法权益。对参与国家科学技术秘密研制的科技人员，有关机关、单位不得因其成果不宜公开发表、交流、推广而影响其评奖、表彰和职称评定。 对确因保密原因不能在公开刊物上发表的论文，有关机关、单位应当对论文的实际水平给予客观、公正评价。"},{"i":39,"n":"第三十九条","txt":"国家科学技术秘密申请知识产权保护应当遵守以下规定： （一）绝密级国家科学技术秘密不得申请普通专利或者保密专利； （二）机密级、秘密级国家科学技术秘密经原定密机关、单位批准可申请保密专利； （三）机密级、秘密级国家科学技术秘密申请普通专利或者由保密专利转为普通专利的，应当先行办理解密手续。"},{"i":40,"n":"第四十条","txt":"机关、单位对在科学技术保密工作方面作出贡献、成绩突出的集体和个人，应当给予表彰；对于违反科学技术保密规定的，给予批评教育；对于情节严重，给国家安全和利益造成损害的，应当依照有关法律、法规给予有关责任人员处分，构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"涉及国防科学技术的保密管理，按有关部门规定执行。"},{"i":42,"n":"第四十二条","txt":"本规定由科学技术部和国家保密局负责解释。"},{"i":43,"n":"第四十三条","txt":"本规定自公布之日起施行，1995年颁布的《科学技术保密规定》（国家科学技术委员会、国家保密局令第20号）同时废止。"}],"kexuejishuhuodongweiguixingweichulizanxingguiding":[{"i":1,"n":"第一条","txt":"为规范科学技术活动违规行为处理，营造风清气正的良好科研氛围，根据《中华人民共和国科学技术进步法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"对下列单位和人员在开展有关科学技术活动过程中出现的违规行为的处理，适用本规定。 （一）受托管理机构及其工作人员，即受科学技术行政部门委托开展相关科学技术活动管理工作的机构及其工作人员； （二）科学技术活动实施单位，即具体开展科学技术活动的科学技术研究开发机构、高等学校、企业及其他组织； （三）科学技术人员，即直接从事科学技术活动的人员和为科学技术活动提供管理、服务的人员； （四）科学技术活动咨询评审专家，即为科学技术活动提供咨询、评审、评估、评价等意见的专业人员； （五）第三方科学技术服务机构及其工作人员，即为科学技术活动提供审计、咨询、绩效评估评价、经纪、知识产权代理、检验检测、出版等服务的第三方机构及其工作人员。"},{"i":3,"n":"第三条","txt":"科学技术部加强对科学技术活动违规行为处理工作的统筹、协调和督促指导。 各级科学技术行政部门根据职责和权限对科学技术活动实施中发生的违规行为进行处理。"},{"i":4,"n":"第四条","txt":"科学技术活动违规行为的处理，应区分主观过错、性质、情节和危害程度，做到程序正当、事实清楚、证据确凿、依据准确、处理恰当。"},{"i":5,"n":"第五条","txt":"受托管理机构的违规行为包括以下情形： （一）采取弄虚作假等不正当手段获得管理资格； （二）内部管理混乱，影响受托管理工作正常开展； （三）重大事项未及时报告； （四）存在管理过失，造成负面影响或财政资金损失； （五）设租寻租、徇私舞弊、滥用职权、私分受托管理的科研资金； （六）隐瞒、包庇科学技术活动中相关单位或人员的违法违规行为； （七）不配合监督检查或评估评价工作，不整改、虚假整改或整改未达到要求； （八）违反任务委托协议等合同约定的主要义务； （九）违反国家科学技术活动保密相关规定； （十）法律、行政法规、部门规章或规范性文件规定的其他相关违规行为。"},{"i":6,"n":"第六条","txt":"受托管理机构工作人员的违规行为包括以下情形： （一）管理失职，造成负面影响或财政资金损失； （二）设租寻租、徇私舞弊等利用组织科学技术活动之便谋取不正当利益； （三）承担或参加所管理的科技计划（专项、基金等）项目； （四）参与所管理的科学技术活动中有关论文、著作、专利等科学技术成果的署名及相关科技奖励、人才评选等； （五）未经批准在相关科学技术活动实施单位兼职； （六）干预咨询评审或向咨询评审专家施加倾向性影响； （七）泄露科学技术活动管理过程中需保密的专家名单、专家意见、评审结论和立项安排等相关信息； （八）违反回避制度要求，隐瞒利益冲突； （九）虚报、冒领、挪用、套取所管理的科研资金； （十）违反国家科学技术活动保密相关规定； （十一）法律、行政法规、部门规章或规范性文件规定的其他相关违规行为。"},{"i":7,"n":"第七条","txt":"科学技术活动实施单位的违规行为包括以下情形： （一）在科学技术活动的申报、评审、实施、验收、监督检查和评估评价等活动中提供虚假材料，组织“打招呼”“走关系”等请托行为； （二）管理失职，造成负面影响或财政资金损失； （三）无正当理由不履行科学技术活动管理合同约定的主要义务； （四）隐瞒、迁就、包庇、纵容或参与本单位人员的违法违规活动； （五）未经批准，违规转包、分包科研任务； （六）截留、挤占、挪用、套取、转移、私分财政科研资金； （七）不配合监督检查或评估评价工作，不整改、虚假整改或整改未达到要求； （八）不按规定上缴应收回的财政科研结余资金； （九）未按规定进行科技伦理审查并监督执行； （十）开展危害国家安全、损害社会公共利益、危害人体健康的科学技术活动； （十一）违反国家科学技术活动保密相关规定； （十二）法律、行政法规、部门规章或规范性文件规定的其他相关违规行为。"},{"i":8,"n":"第八条","txt":"科学技术人员的违规行为包括以下情形： （一）在科学技术活动的申报、评审、实施、验收、监督检查和评估评价等活动中提供虚假材料，实施“打招呼”“走关系”等请托行为； （二）故意夸大研究基础、学术价值或科技成果的技术价值、社会经济效益，隐瞒技术风险，造成负面影响或财政资金损失； （三）人才计划入选者、重大科研项目负责人在聘期内或项目执行期内擅自变更工作单位，造成负面影响或财政资金损失； （四）故意拖延或拒不履行科学技术活动管理合同约定的主要义务； （五）随意降低目标任务和约定要求，以项目实施周期外或不相关成果充抵交差； （六）抄袭、剽窃、侵占、篡改他人科学技术成果，编造科学技术成果，侵犯他人知识产权等； （七）虚报、冒领、挪用、套取财政科研资金； （八）不配合监督检查或评估评价工作，不整改、虚假整改或整改未达到要求； （九）违反科技伦理规范； （十）开展危害国家安全、损害社会公共利益、危害人"},{"i":9,"n":"第九条","txt":"科学技术活动咨询评审专家的违规行为包括以下情形： （一）采取弄虚作假等不正当手段获取咨询、评审、评估、评价、监督检查资格； （二）违反回避制度要求； （三）接受“打招呼”“走关系”等请托； （四）引导、游说其他专家或工作人员，影响咨询、评审、评估、评价、监督检查过程和结果； （五）索取、收受利益相关方财物或其他不正当利益； （六）出具明显不当的咨询、评审、评估、评价、监督检查意见； （七）泄漏咨询评审过程中需保密的申请人、专家名单、专家意见、评审结论等相关信息； （八）抄袭、剽窃咨询评审对象的科学技术成果； （九）违反国家科学技术活动保密相关规定； （十）法律、行政法规、部门规章或规范性文件规定的其他相关违规行为。"},{"i":10,"n":"第十条","txt":"第三方科学技术服务机构及其工作人员的违规行为包括以下情形： （一）采取弄虚作假等不正当手段获取科学技术活动相关业务； （二）从事学术论文买卖、代写代投以及伪造、虚构、篡改研究数据等； （三）违反回避制度要求； （四）擅自委托他方代替提供科学技术活动相关服务； （五）出具虚假或失实结论； （六）索取、收受利益相关方财物或其他不正当利益； （七）泄漏需保密的相关信息或材料等； （八）违反国家科学技术活动保密相关规定； （九）法律、行政法规、部门规章或规范性文件规定的其他相关违规行为。"},{"i":11,"n":"第十一条","txt":"对科学技术活动违规行为，视违规主体和行为性质，可单独或合并采取以下处理措施： （一）警告； （二）责令限期整改； （三）约谈； （四）一定范围内或公开通报批评； （五）终止、撤销有关财政性资金支持的科学技术活动； （六）追回结余资金，追回已拨财政资金以及违规所得； （七）撤销奖励或荣誉称号，追回奖金； （八）取消一定期限内财政性资金支持的科学技术活动管理资格； （九）禁止在一定期限内承担或参与财政性资金支持的科学技术活动； （十）记入科研诚信严重失信行为数据库。"},{"i":12,"n":"第十二条","txt":"违规行为涉嫌违反党纪政纪、违法犯罪的，移交有关机关处理。"},{"i":13,"n":"第十三条","txt":"对于第三方科学技术服务机构及人员违规的，可视情况将相关问题及线索移交具有处罚或处理权限的主管部门或行业协会处理。"},{"i":14,"n":"第十四条","txt":"受托管理机构、科学技术活动实施单位有组织地开展科学技术活动违规行为的，或存在重大管理过失的，按本规定第十一条第（八）项追究主要负责人、直接负责人的责任，具体期限与被处理单位的受限年限保持一致。"},{"i":15,"n":"第十五条","txt":"有证据表明违规行为已经造成恶劣影响或财政资金严重损失的，应直接或提请具有相应职责和权限的行政机关责令采取有效措施，防止影响或损失扩大，中止相关科学技术活动，暂停拨付相应财政资金，同时暂停接受相关责任主体申请新的财政性资金支持的科学技术活动。"},{"i":16,"n":"第十六条","txt":"采取本规定第十一条第（九）项处理措施的，违规行为未涉及科学技术活动核心关键任务、约束性目标或指标，但造成较大负面影响或财政资金损失，对违规单位取消2年以内（含2年）相关资格，对违规个人取消3年以内（含3年）相关资格。 上述违规行为涉及科学技术活动的核心关键任务、约束性目标或指标，并导致相关科学技术活动偏离约定目标，或造成严重负面影响或财政资金损失，对违规单位取消2至5年相关资格，对违规个人取消3至5年相关资格。 上述违规行为涉及科学技术活动的核心关键任务、约束性目标或指标，并导致相关科学技术活动停滞、严重偏离约定目标，或造成特别严重负面影响或财政资金损失，对违规单位和个人取消5年以上直至永久相关资格。"},{"i":17,"n":"第十七条","txt":"有以下情形之一的，可以给予从轻处理： （一）主动反映问题线索，并经查属实； （二）主动承认错误并积极配合调查和整改； （三）主动退回因违规行为所获各种利益； （四）主动挽回损失浪费或有效阻止危害结果发生； （五）通过全国性媒体公开作出严格遵守科学技术活动相关国家法律及管理规定、不再实施违规行为的承诺； （六）其他可以给予从轻处理情形。"},{"i":18,"n":"第十八条","txt":"有以下情形之一的，应当给予从重处理： （一）伪造、销毁、藏匿证据； （二）阻止他人提供证据，或干扰、妨碍调查核实； （三）打击、报复举报人； （四）有组织地实施违规行为； （五）多次违规或同时存在多种违规行为； （六）其他应当给予从重处理情形。"},{"i":19,"n":"第十九条","txt":"科学技术活动违规行为涉及多个主体的，应甄别不同主体的责任，并视其违规行为在负面影响或财政资金损失发生过程和结果中所起作用等因素分别给予相应处理。"},{"i":20,"n":"第二十条","txt":"科学技术活动违规行为认定后，视事实、性质、情节，按照本规定第十一条的处理措施作出相应处理决定，并制作处理决定书。"},{"i":21,"n":"第二十一条","txt":"作出处理决定前，应告知被处理单位或人员拟作出处理决定的事实、理由及依据，并告知其享有陈述与申辩的权利及其行使的方式和期限。被处理单位或人员逾期未提出陈述或申辩的，视为放弃陈述与申辩的权利；作出陈述或申辩的，应充分听取其意见。"},{"i":22,"n":"第二十二条","txt":"处理决定书应载明以下内容： （一）被处理主体的基本情况； （二）违规行为情况及事实根据； （三）处理依据和处理决定； （四）救济途径和期限； （五）作出处理决定的单位名称和时间； （六）法律、行政法规、部门规章或规范性文件规定的其他相关事项。"},{"i":23,"n":"第二十三条","txt":"处理决定书应送达被处理单位或人员，抄送被处理人员所在单位或被处理单位的上级主管部门，并可视情通知被处理人员或单位所属相关行业协会。 处理决定书可采取直接送达、委托送达、邮寄送达等方式；被送达人下落不明的，可公告送达。涉及保密内容的，按照保密相关规定送达。 对于影响范围广、社会关注度高的违规行为的处理决定，除涉密内容外，应向社会公开，发挥警示教育作用。"},{"i":24,"n":"第二十四条","txt":"被处理单位或人员对处理决定不服的，可自收到处理决定书之日起15个工作日内，按照处理决定书载明的救济途径向作出处理决定的相关部门或单位提出复查申请，写明理由并提供相关证据或线索。 处理主体应自收到复查申请后15个工作日内作出是否受理的决定。决定受理的，应当另行组织对处理决定所认定的事实和相关依据进行复查。 复查应制作复查决定书，复查原则上应自受理之日起90个工作日内完成并送达复查申请人。复查期间，不停止原处理决定的执行。"},{"i":25,"n":"第二十五条","txt":"被处理单位或人员也可以不经复查，直接依法申请复议或提起诉讼。"},{"i":26,"n":"第二十六条","txt":"采取本规定第十一条第（九）项处理措施的，取消资格期限自处理决定下达之日起计算，处理决定作出前已执行本规定第十五条采取暂停活动的，暂停活动期限可折抵处理期限。"},{"i":27,"n":"第二十七条","txt":"科学技术活动违规行为涉及多个部门的，可组织开展联合调查，按职责和权限分别予以处理。"},{"i":28,"n":"第二十八条","txt":"科学技术活动违规行为处理超出科学技术行政部门职责和权限范围内的，应将问题及线索移交相关部门、机构，并可以适当方式向相关部门、机构提出意见建议。"},{"i":29,"n":"第二十九条","txt":"科学技术行政部门委托受托管理机构管理的科学技术活动中，项目承担单位和人员出现的情节轻微、未造成明显负面影响或财政资金损失的违规行为，由受托管理机构依据有关科学技术活动管理合同、管理办法等处理。"},{"i":30,"n":"第三十条","txt":"各级科学技术行政部门已在职责和权限范围内制定科学技术活动违规行为处理规定且处理尺度不低于本规定的，可按照已有规定进行处理。"},{"i":31,"n":"第三十一条","txt":"科学技术活动违规行为处理属其他部门、机构职责和权限的，由有权处理的部门、机构依据法律、行政法规及其他有关规定处理。 科学技术活动违规行为涉事单位或人员属军队管理的，由军队按照其有关规定进行处理。"},{"i":32,"n":"第三十二条","txt":"法律、行政法规对科学技术活动违规行为及相应处理另有规定的，从其规定。 科学技术部部门规章或规范性文件相关内容与本规定不一致的，适用本规定。"},{"i":33,"n":"第三十三条","txt":"本规定自2020年9月1日起施行。"},{"i":34,"n":"第三十四条","txt":"本规定由科学技术部负责解释。"}],"kexuejishuhuodongweiguixingweidiaochachuliguiding":[{"i":1,"n":"第一条","txt":"为规范科学技术活动违规行为调查处理，营造风清气正的良好科研生态，根据《中华人民共和国科学技术进步法》等法律法规和国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"各级科学技术行政部门，各类科技计划项目、科技平台等科技活动的主管部门（以下统称“主管部门”）根据职责和权限对科学技术活动实施中发生的违规行为进行调查处理。 依据有关规定或程序，主管部门可以委托有关科学技术活动管理单位开展调查，过程中应当加强指导监督，调查完成后加强对调查结论的审核，并作出相应处理。 科学技术活动违规行为涉及多个主管部门的，可组织开展联合调查，按职责和权限分别予以处理。"},{"i":3,"n":"第三条","txt":"对下列单位和人员在开展科学技术活动过程中出现的违规行为的调查和处理，适用本规定。 （一）科学技术活动受托管理机构（以下简称“受托机构”）及其工作人员，即受主管部门委托，开展科学技术活动管理、监督等工作的机构及其工作人员； （二）科学技术活动实施单位（以下简称“实施单位”），即从事科学技术活动的科学技术研究开发机构、高等学校、企业事业单位和社会组织等； （三）科学技术人员，即直接从事科学技术活动的人员和为科学技术活动提供管理、服务的人员； （四）科学技术活动咨询评审专家（以下简称“评审专家”），即为科学技术活动提供咨询、评审、评估、评价、检查等意见的专业人员； （五）第三方科学技术服务机构（以下简称“第三方机构”）及其工作人员，即为科学技术活动提供审计、咨询、评估评价、经纪、知识产权代理、检验检测、出版等服务的第三方机构及其工作人员。 科学技术活动违规行为涉及行政管理部门及其人员的，由有"},{"i":4,"n":"第四条","txt":"科学技术活动违规行为的调查处理，应当综合考量主观过错、性质、情节和危害程度，做到程序正当、事实清楚、证据确凿、依据准确、处理恰当。"},{"i":5,"n":"第五条","txt":"受托机构的违规行为包括以下情形： （一）不履行委托协议、任务合同等约定的主要义务，影响受托工作正常开展； （二）管理和监督失职，造成负面影响或财政资金损失； （三）未按规定及时报告受托工作中的重大事项； （四）调查和处理不及时、不到位，或未按规定汇交调查处理数据； （五）无明确规定或事前约定，承担或参加所管理的科学技术活动； （六）采取不正当手段获得管理资格； （七）违规安排、使用财政资金； （八）隐瞒、包庇、纵容或参与科学技术活动中有关单位或人员的违规行为； （九）不配合主管部门或有关部门组织的科学技术活动监督检查、评估评价等工作，不整改、虚假整改或整改未达到要求； （十）其他科学技术活动违规行为。"},{"i":6,"n":"第六条","txt":"受托机构工作人员的违规行为包括以下情形： （一）工作失职，影响受托工作正常开展； （二）工作过失，造成负面影响或财政资金损失； （三）违反回避要求，隐瞒利害关系； （四）未经批准在有关科学技术活动实施单位兼职； （五）无明确规定或事前约定，承担或参加本单位管理的科学技术活动； （六）无明确规定或事前约定，参与本单位管理的科学技术活动有关论文、著作、专利、标准等科技成果的署名； （七）在有关科学技术活动组织管理过程中组织、协助、接受请托； （八）干预评审活动或向评审专家施加倾向性影响； （九）泄露申报材料、专家名单、专家意见、评审结论、立项安排等敏感信息； （十）设租寻租，利用组织科学技术活动之便谋取不当利益； （十一）不配合主管部门或有关部门组织的科学技术活动监督检查、评估评价等工作； （十二）其他科学技术活动违规行为。"},{"i":7,"n":"第七条","txt":"实施单位的违规行为包括以下情形： （一）不履行科学技术活动任务书、合同等约定的主要义务，影响科学技术活动正常开展； （二）管理和监督失职，造成负面影响或财政资金损失； （三）未按规定及时报告科学技术活动中的重大事项； （四）在科学技术活动的申报、评审、实施、验收、监督检查和评估评价等活动中弄虚作假； （五）违规转包、分包科研任务； （六）调查和处理不及时、不到位，或未按规定汇交调查处理数据； （七）在科学技术活动的申报、评审、实施、验收、监督检查和评估评价等活动中组织、协助请托； （八）隐瞒、迁就、包庇、纵容或参与本单位人员的科学技术活动违规行为； （九）不按规定上缴应缴的财政科研资金； （十）不配合主管部门或有关部门组织的科学技术活动监督检查、评估评价等工作，不整改、虚假整改或整改未达到要求； （十一）其他科学技术活动违规行为。"},{"i":8,"n":"第八条","txt":"科学技术人员的违规行为包括以下情形： （一）不履行科学技术活动任务书、合同等约定的主要义务，影响科学技术活动正常开展； （二）在科学技术活动的申报、评审、实施、验收、监督检查和评估评价等活动中弄虚作假； （三）夸大研究基础、学术价值或科技成果的技术价值、社会经济效益，隐瞒技术风险，造成负面影响或财政资金损失； （四）未按规定及时报告科学技术活动中的重大事项； （五）人才计划入选者、重大科技项目负责人在支持期内、聘期内或项目执行期内擅自变更工作单位； （六）违反回避要求，隐瞒利害关系； （七）在科学技术活动的申报、评审、实施、验收、监督检查和评估评价等活动中组织、实施、接受、协助请托； （八）擅自降低科学技术活动任务书、合同约定的目标任务要求； （九）提交有关科学技术活动实施周期外成果、不相关成果或虚假成果； （十）抄袭、剽窃、篡改他人科技成果； （十一）滥用人工智能等手段编造科学技术活"},{"i":9,"n":"第九条","txt":"评审专家的违规行为包括以下情形： （一）未遵守科学技术活动组织方规定的工作要求或未履行签订的工作承诺； （二）违反回避要求，隐瞒利害关系； （三）未经许可复制、泄露、留存、使用相关评审材料； （四）采取不正当手段获取评审专家资格； （五）组织、协助、接受请托，或未按规定及时报告收到的请托事项； （六）引导、游说其他专家或工作人员，影响咨询、评审、评估、评价、监督检查过程和结果； （七）利用评审专家身份谋取不当利益； （八）出具不当的咨询、评审、评估、评价、监督检查意见； （九）泄露咨询评审过程中的敏感信息； （十）抄袭、剽窃被评审对象的科技成果； （十一）不配合科学技术活动监督检查等工作； （十二）其他科学技术活动违规行为。"},{"i":10,"n":"第十条","txt":"第三方机构及其工作人员的违规行为包括以下情形： （一）未按合同、协议等履行应尽义务或未按规定程序、标准等提供科学技术活动相关服务，影响科学技术活动正常开展； （二）擅自委托其他方代替提供科学技术活动相关服务； （三）违反回避要求，隐瞒利害关系； （四）采取不正当手段谋取科学技术活动相关业务； （五）索取、收受利益相关方财物或利用服务便利谋取不当利益； （六）出具虚假或失实结论； （七）收取明显超出公允范围的服务费用或通过“补充合同”“阴阳合同”等方式变相提高服务费用； （八）泄露服务过程中的敏感信息； （九）不配合主管部门或有关部门组织的科学技术活动监督检查、评估评价等工作，不整改、虚假整改或整改未达到要求； （十）其他科学技术活动违规行为。"},{"i":11,"n":"第十一条","txt":"对受托机构的科学技术活动违规行为，可以单独或合并采取以下处理措施： （一）警告； （二）约谈； （三）责令改正； （四）一定范围内通报； （五）暂停拨付有关管理费或任务经费； （六）扣减、追回有关管理费或任务经费； （七）压减委托管理的任务数量； （八）中止、解除任务委托关系； （九）取消一定期限内财政资金支持的科学技术活动管理资格，并记入科研诚信严重失信行为数据库。"},{"i":12,"n":"第十二条","txt":"受托机构存在本规定第五条所列违规行为的，应当视情形轻重给予第十一条的相应处理。 对存在第五条第（一）项至第（四）项违规行为且带来较大负面影响或累计达到人民币30万元以上财政资金损失；以及存在第（五）项至第（九）项违规行为的，应当给予第十一条第（九）项的处理。 根据前款规定给予第十一条第（九）项处理的违规行为，未影响科学技术活动主要任务落实、核心关键目标或指标实现的，取消2年内（含2年）相关资格；影响科学技术活动主要任务落实、核心关键目标或指标实现，造成严重负面影响的，取消2至5年（含5年）相关资格；导致相关科学技术活动停滞、严重偏离约定目标或造成特别严重负面影响的，取消5年以上直至永久取消相关资格。"},{"i":13,"n":"第十三条","txt":"对受托机构工作人员的科学技术活动违规行为，可以单独或合并采取以下处理措施： （一）警告； （二）约谈； （三）责令改正； （四）一定范围内通报； （五）责令调离相关科学技术活动管理岗位； （六）取消一定期限内财政资金支持的科学技术活动管理资格，并记入科研诚信严重失信行为数据库。"},{"i":14,"n":"第十四条","txt":"受托机构工作人员存在本规定第六条所列违规行为的，应当视情形轻重给予第十三条的相应处理。 对存在第六条第（一）项至第（二）项违规行为且带来较大负面影响或累计达到人民币30万元以上财政资金损失；以及存在第（三）项至第（十一）项违规行为的，应当给予第十三条第（六）项的处理。 根据前款规定给予第十三条第（六）项处理的违规行为，未影响科学技术活动主要任务落实、核心关键目标或指标实现的，取消3年内（含3年）相关资格；影响科学技术活动主要任务落实、核心关键目标或指标实现，造成严重负面影响的，取消3至5年（含5年）相关资格；导致相关科学技术活动停滞、严重偏离约定目标或造成特别严重负面影响的，取消5年以上直至永久取消相关资格。"},{"i":15,"n":"第十五条","txt":"对实施单位的科学技术活动违规行为，可以单独或合并采取以下处理措施： （一）警告； （二）约谈； （三）责令改正； （四）一定范围内通报； （五）中止相关科学技术活动； （六）暂停有关财政资金的拨付与使用； （七）终止或撤销相关科学技术活动； （八）追回有关财政资金； （九）禁止在一定期限内承担或参与财政资金支持的科学技术活动，并记入科研诚信严重失信行为数据库。"},{"i":16,"n":"第十六条","txt":"实施单位存在本规定第七条所列违规行为的，应当视情形轻重给予第十五条的相应处理。 对存在第七条第（一）项至第（六）项违规行为且带来较大负面影响或累计达到人民币30万元以上财政资金损失；以及存在第（七）项至第（十）项违规行为的，应当给予第十五条第（九）项的处理。 根据前款规定给予第十五条第（九）项处理的违规行为，未影响科学技术活动主要任务落实、核心关键目标或指标实现的，禁止2年内（含2年）承担或参与财政资金支持的科学技术活动；影响科学技术活动主要任务落实、核心关键目标或指标实现，造成严重负面影响的，禁止2至5年（含5年）承担或参与财政资金支持的科学技术活动；导致相关科学技术活动停滞、严重偏离约定目标或造成特别严重负面影响的，禁止5年以上直至永久禁止承担或参与财政资金支持的科学技术活动。"},{"i":17,"n":"第十七条","txt":"对科学技术人员和评审专家的科学技术活动违规行为，可以单独或合并采取以下处理措施： （一）警告； （二）约谈； （三）责令改正； （四）一定范围内通报； （五）中止相关科学技术活动； （六）暂停有关财政资金的拨付与使用； （七）终止或撤销相关科学技术活动； （八）追回有关财政资金； （九）禁止在一定期限内承担或参与财政资金支持的科学技术活动，并记入科研诚信严重失信行为数据库。"},{"i":18,"n":"第十八条","txt":"科学技术人员和评审专家存在本规定第八条、第九条所列违规行为的，应当视情形轻重给予第十七条的相应处理。 对存在第八条第（一）项至第（五）项违规行为、第九条第（一）项违规行为且带来较大负面影响或累计达到人民币30万元以上财政资金损失；以及存在第八条第（六）项至第（十二）项违规行为、第九条第（二）项至第（十一）项违规行为的，应当给予第十七条第（九）项的处理。 根据前款规定给予第十七条第（九）项处理的违规行为，未影响科学技术活动主要任务落实、核心关键目标或指标实现的，禁止3年内（含3年）承担或参与财政资金支持的科学技术活动；影响科学技术活动主要任务落实、核心关键目标或指标实现，造成严重负面影响的，禁止3至5年（含5年）承担或参与财政资金支持的科学技术活动；导致相关科学技术活动停滞、严重偏离约定目标或造成特别严重负面影响的，禁止5年以上直至永久禁止承担或参与财政资金支持的科学技术活动。"},{"i":19,"n":"第十九条","txt":"对第三方机构及其工作人员的科学技术活动违规行为，可以单独或合并采取以下处理措施： （一）警告； （二）约谈； （三）责令改正； （四）一定范围内通报； （五）一定期限内不接受其提供的科学技术活动相关服务，并记入科研诚信严重失信行为数据库。"},{"i":20,"n":"第二十条","txt":"第三方机构及其工作人员存在本规定第十条所列违规行为的，应当视情形轻重给予第十九条的相应处理。 对存在第十条第（一）项至第（二）项违规行为且带来较大负面影响或累计达到人民币30万元以上财政资金损失；以及存在第（三）项至第（九）项违规行为的，应当给予第十九条第（五）项的处理。 根据前款规定给予第十九条第（五）项处理的第三方机构或其工作人员，其违规行为未影响科学技术活动主要任务落实、核心关键目标或指标实现的，对第三方机构取消2年内（含2年）相关资格，对相关工作人员取消3年内（含3年）相关资格；影响科学技术活动主要任务落实、核心关键目标或指标实现，造成严重负面影响的，对第三方机构取消2至5年（含5年）相关资格，对相关工作人员取消3至5年内（含5年）相关资格；导致相关科学技术活动停滞、严重偏离约定目标或造成特别严重负面影响的，对第三方机构或相关工作人员取消5年以上直至永久取消相关资格。"},{"i":21,"n":"第二十一条","txt":"受托机构、实施单位有组织实施科学技术活动违规行为的，或存在重大管理过失的，应当按第十一条第（九）项、第十五条第（九）项追究直接负责的主管人员和其他直接责任人员的责任，具体期限与被处理单位的受限年限保持一致。情节严重的，由受托机构、实施单位的上级主管部门对主要负责人依规依纪依法给予处分。"},{"i":22,"n":"第二十二条","txt":"有以下情形之一的，可以从轻处理： （一）主动反映问题线索，并经查属实； （二）主动承认错误并积极配合调查和整改； （三）主动退回因违规行为所获各种利益； （四）主动挽回损失浪费或有效阻止危害结果发生； （五）通过全国性媒体公开承诺严格遵守科学技术活动有关法律法规及管理规定、不再实施违规行为； （六）其他可以给予从轻处理的情形。"},{"i":23,"n":"第二十三条","txt":"有以下情形之一的，应当从重处理： （一）伪造、篡改、隐匿、销毁证据； （二）阻止他人提供证据，或干扰、妨碍调查核实； （三）打击、报复举报人、证人、调查人员； （四）有组织地实施违规行为； （五）多次违规或同时存在多种违规行为； （六）其他应当给予从重处理的情形。"},{"i":24,"n":"第二十四条","txt":"实施单位和科学技术人员的违规行为情节轻微、未造成明显负面影响或财政资金损失的，可以依据有关科学技术活动合同、管理办法等处置。"},{"i":25,"n":"第二十五条","txt":"主管部门对科学技术活动组织实施、监督管理过程中发现的，上级机关交办或其他执法执纪部门移送的科学技术活动违规行为问题线索，应当及时组织开展调查。 接到其他部门移送的科学技术活动违规行为问题线索或举报的，应当在15个工作日内决定是否受理；不予受理的，应当通知移送部门或实名举报人并说明理由。符合本规定第二章规定且属于本单位职责范围的，应当受理；不属于本单位职责范围的，转送有关单位或告知实名举报人。"},{"i":26,"n":"第二十六条","txt":"科学技术活动违规行为有关举报的受理，应当同时满足以下条件： （一）有明确的举报对象； （二）举报内容属于本规定第二章规定的范围； （三）有明确的违规事实； （四）有客观、明确的证据或可查证线索。 举报具有下列情形之一的，不予受理： （一）没有明确的举报对象； （二）举报内容不属于本规定第二章规定的范围； （三）没有明确的证据和可查证线索； （四）对同一对象重复举报且无新的证据、线索； （五）已经作出生效处理决定且无新的证据、线索。"},{"i":27,"n":"第二十七条","txt":"调查科学技术活动违规行为，可以采取以下措施和方式： （一）按规定和程序调阅、摘抄、复印有关技术文档、财务资料等； （二）现场查看实验室、设备、成果等，核实验证原始实验数据、研究过程等，必要时可以委托开展重复实验、测试、评估或评价； （三）与被调查人、证人等谈话，参与谈话的调查人员不得少于2人，谈话内容应当书面记录，并由参与谈话的调查人员和谈话对象签字确认，在履行告知程序后可以录音、录像； （四）涉及重大疑难复杂问题的，可以根据需要组成专家组，提供专业支撑； （五）法律、行政法规、部门规章或规范性文件规定的其他措施或方式。 严禁以威胁、引诱、欺骗以及其他非法手段收集证据。"},{"i":28,"n":"第二十八条","txt":"被调查单位、人员及证人等应当积极配合调查，如实说明情况、提供证据，不得伪造、篡改、隐匿、销毁证据材料。"},{"i":29,"n":"第二十九条","txt":"有证据证明违规行为已经造成恶劣影响或财政资金严重损失的，应当直接或提请具有相应职责和权限的行政机关采取有效措施，防止影响或损失扩大，中止相关科学技术活动，暂停拨付相应财政资金，同时暂停接受相关责任主体申请新的财政资金支持的科学技术活动。 调查中发现违规行为可能影响公众健康与安全或导致其他严重后果的，调查人员应当立即报告，或按程序移送有关部门或单位处理。"},{"i":30,"n":"第三十条","txt":"调查过程中发现暂不具备调查条件的，调查处理主体可以按程序中止调查。中止调查的原因消除后，应当及时恢复调查。"},{"i":31,"n":"第三十一条","txt":"调查处理应当严格执行回避制度。参与调查处理的工作人员与被调查人、调查事项存在利害关系或其他可能影响公正调查处理情形的，应当主动申请回避。"},{"i":32,"n":"第三十二条","txt":"调查中应当听取被调查人的陈述、申辩，对有关事实、理由和证据进行核实。 当事人对调查认定的事实无异议的，应当签字确认。当事人无正当理由拒不签字确认的，应当据实做好记录。"},{"i":33,"n":"第三十三条","txt":"调查结束后，应当及时形成调查报告。调查报告应当包括线索来源、调查内容、调查过程、事实认定以及有关当事人确认情况、调查结论、处理意见建议及依据等，并附证据材料。调查报告须由全体调查人员签字。需要补充调查的，应当根据补充调查情况重新形成调查报告。"},{"i":34,"n":"第三十四条","txt":"科学技术活动违规行为的调查处理应当自决定受理之日起6个月内完成。 因特别重大复杂在前款规定期限内仍不能完成调查的，经主管部门有关负责人批准后可以延长调查期限，但延长不得超过6个月。对上级机关交办或其他执法执纪部门移送的，调查延期情况应当向交办机关或移送部门报告。"},{"i":35,"n":"第三十五条","txt":"科学技术活动违规行为涉及多个主体的，应当甄别不同主体的责任，并视其违规行为在负面影响或财政资金损失发生过程和结果中所起作用等因素分别给予相应处理。"},{"i":36,"n":"第三十六条","txt":"对科学技术活动违规行为直接责任人作出处理时，应当同步调查其他有关主体的责任，存在本规定第五条至第十条违规行为的，应当一并作出处理。"},{"i":37,"n":"第三十七条","txt":"作出处理决定前，应当告知被处理单位或人员拟作出处理决定的事实、理由及依据，并告知其享有陈述、申辩的权利及其行使的方式和期限。被处理单位或人员提出陈述、申辩的，应当充分听取其意见；逾期未提出的，视为放弃陈述、申辩的权利。"},{"i":38,"n":"第三十八条","txt":"科学技术活动违规行为认定后，处理主体按程序作出处理决定，制作处理决定书，并按要求及时汇交调查处理数据。 处理决定书应当载明以下内容： （一）被处理主体的基本情况； （二）违规行为情况及事实根据； （三）处理依据和决定； （四）救济途径和期限； （五）作出处理决定的单位名称和时间； （六）法律、行政法规、部门规章或规范性文件规定的其他有关事项。"},{"i":39,"n":"第三十九条","txt":"处理决定书应当送达被处理单位或人员，抄送被处理人员所在单位或被处理单位的上级主管部门，并可以视情通知被处理人员或单位所属群团组织、社会组织等。 处理决定书可以采取直接送达、委托送达、邮寄送达等方式；被送达人下落不明或无法用上述方式送达的，公告送达，自公告之日起满30日，即视为送达。涉及保密内容的，按照保密有关规定送达。 对于影响范围广、社会关注度高的违规行为的处理决定，除涉及国家秘密、商业秘密、个人隐私及其他不宜公开的内容外，应当向社会公开。 按照有关规定，将科研诚信严重失信行为数据库中的相关数据共享至全国信用信息共享平台。"},{"i":40,"n":"第四十条","txt":"被处理单位或人员对处理决定不服的，可以自收到处理决定书之日起15日内，按照处理决定书载明的救济途径提出复查申请，写明理由并提供相关证据。 处理主体应当自收到复查申请后5个工作日内作出是否受理的决定。不予受理的，通知复查申请人并说明理由；决定受理的，另行组织对处理决定所认定的事实和相关依据进行复查，并自受理之日起60日内向复查申请人作出复查决定。复查期间，不停止原处理决定的执行。"},{"i":41,"n":"第四十一条","txt":"被处理单位或人员对处理决定不服的，可以依法申请行政复议或提起行政诉讼。 复查申请已经受理，被处理单位或人员在复查决定作出期限内又对处理决定申请行政复议或提起行政诉讼的，视为撤回复查申请。处理机关应当在知悉有关情况后及时终止复查，并书面告知复查申请人。"},{"i":42,"n":"第四十二条","txt":"采取本规定第十一条第（九）项、第十三条第（六）项、第十五条第（九）项、第十七条第（九）项和第十九条第（五）项处理措施的，有关限制期限自处理决定送达之日起计算，处理决定作出前已执行本规定第二十九条采取暂停活动的，暂停活动期限折抵处理期限。 处理决定生效后，被处理人对推动产生重大科技创新、技术变革以及对国家和社会作出重大贡献，且已纠正违规行为，完全履行处理决定要求整改义务的，作出处理决定的主管部门可根据被处理人申请对其作出减期处理。"},{"i":43,"n":"第四十三条","txt":"对科学技术活动违规行为相关责任主体的处理，超出本单位处理权限范围的，应当将调查结论、证据材料、处理意见等交由具有处理权限的单位依规作出处理。"},{"i":44,"n":"第四十四条","txt":"科学技术活动违规行为涉嫌违反党纪政纪的，将问题线索按规定移送有关纪检监察机关依规依纪处理；构成违法犯罪的，依法移交有关部门追究责任。"},{"i":45,"n":"第四十五条","txt":"参与调查处理的工作人员应当秉持客观公正，遵守工作纪律和保密纪律，主动接受监督，不得私自留存、隐匿、摘抄、复制或泄露问题线索和调查资料，未经批准不得透露或公开调查处理工作情况。 参与调查处理的工作人员存在索贿受贿、违反保密和回避制度、泄露信息等行为的，依规依纪依法严肃处理。"},{"i":46,"n":"第四十六条","txt":"调查处理应当保护举报人、被举报人、证人等的合法权益，不得泄露相关信息，不得将举报材料转给被举报人或被举报单位等利益相关方。 举报人捏造歪曲事实、诬告陷害他人的，依规依纪依法严肃处理。"},{"i":47,"n":"第四十七条","txt":"对于《中华人民共和国科学技术进步法》等法律法规中明确的有关单位和人员滥用职权、玩忽职守、徇私舞弊；虚报、冒领、贪污、挪用、截留用于科学技术活动的财政资金；进行危害国家安全、损害社会公共利益、危害人体健康、违背科研诚信和科技伦理的科学技术活动；虚构、伪造、侵占科研成果，发布、传播虚假科研成果，骗取科学技术奖励和荣誉称号，从事学术论文及其实验研究数据、科技计划项目申报验收材料等的买卖、代写、代投服务等违法行为，应当依法作出处理，相关行为调查处理的主体、程序等在符合有关法律规定的情况下，可以参照本规定开展调查处理。 主管部门已在职责和权限范围内制定有关科学技术活动违规行为处理规定，处理尺度不低于本规定的，可以按照已有规定处理。"},{"i":48,"n":"第四十八条","txt":"本规定中第十二条、第十四条、第十六条、第十八条、第二十条所称的带来较大负面影响的违规行为，是指在国家安全、社会公共利益、人民生命健康等方面造成或导致不良影响但尚未构成违法的行为。"},{"i":49,"n":"第四十九条","txt":"主管部门应当在相关科学技术活动管理中落实本规定各项要求，并在有关管理制度、委托管理协议、任务书、承诺书等中予以明确。"},{"i":50,"n":"第五十条","txt":"科学技术活动实施单位以及科学技术人员、评审专家所在单位应当落实法人主体责任，配合主管部门或有关部门开展相关调查和处理工作，对本单位及所属人员的科学技术活动违规行为及时开展调查，并按有关程序和要求进行处理。"},{"i":51,"n":"第五十一条","txt":"科学技术活动违规行为涉事单位或人员属于军队管理的，由军队按照其有关规定进行处理。"},{"i":52,"n":"第五十二条","txt":"本规定涉及期限的规定，注明工作日的，不包含法定节假日；未注明工作日的，为自然日。"},{"i":53,"n":"第五十三条","txt":"本规定自2026年3月20日起施行。《科学技术活动违规行为处理暂行规定》（科学技术部令第19号）同时废止。"},{"i":54,"n":"第五十四条","txt":"本规定由科学技术部负责解释。"}],"kexuejishubuxingzhengchufashishibanfa":[{"i":1,"n":"第一条","txt":"为了规范科学技术部（以下称科技部）行政处罚行为，保障和监督行政处罚的有效实施，维护公共利益和科技行政管理秩序，保护公民、法人和其他组织的合法权益，根据《中华人民共和国科学技术进步法》《中华人民共和国行政处罚法》《中华人民共和国行政强制法》等法律和行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织在中华人民共和国领域内违反科技行政管理秩序的行为，依照《中华人民共和国科学技术进步法》《中华人民共和国促进科技成果转化法》《中华人民共和国科学技术普及法》《中华人民共和国生物安全法》《中华人民共和国人类遗传资源管理条例》《国家科学技术奖励条例》等法律、行政法规、规章的规定，应当由科技部实施行政处罚的，适用本办法。"},{"i":3,"n":"第三条","txt":"科技部实施行政处罚，应当遵循公开公正、程序合法、宽严相济、过罚相当的原则，严格按照法定程序，规范行使裁量权，维护行政处罚决定执行的严肃性，依法保障当事人的陈述权、申辩权，以及要求听证、申请行政复议、提起行政诉讼等权利。"},{"i":4,"n":"第四条","txt":"科技部以及参与案件办理的有关人员对实施行政处罚过程中知悉的国家秘密、商业秘密和个人隐私应当依法予以保密。"},{"i":5,"n":"第五条","txt":"科技部在法定职权范围内实施行政处罚，科技部的内设机构和直属事业单位不得以自己的名义实施行政处罚。"},{"i":6,"n":"第六条","txt":"科技部各执法职能部门（以下称执法职能部门）按照职责分工，负责本业务领域行政处罚案件的立案、调查取证、实施查封扣押、提出处理意见、送达处罚决定、执行处罚决定等。 科技部法制机构负责对重大行政处罚决定进行法制审核，依法组织听证。 科技部政府信息公开工作机构会同执法职能部门负责行政处罚相关政府信息公开工作。"},{"i":7,"n":"第七条","txt":"科技部可以依照法律、行政法规、规章的规定，在法定职权范围内委托其他行政机关或者具有管理公共事务职能的组织（以下称受委托组织）实施行政处罚。 委托行政处罚应当采取书面方式，由执法职能部门报科技部负责人批准后制发委托书，并向社会公布。委托书应当载明委托的具体事项、权限、期限等内容。 受委托组织应当在委托范围内以科技部名义实施行政处罚，不得再委托其他组织或者个人实施行政处罚。"},{"i":8,"n":"第八条","txt":"执法职能部门应当对受委托组织实施相关行政处罚进行监督。发现受委托组织丧失委托条件、违法实施行政处罚或者有其他不宜继续委托情形的，执法职能部门应当报科技部负责人批准后解除委托。"},{"i":9,"n":"第九条","txt":"科技部可以根据工作需要依法制定行政处罚裁量权基准，依法合理细化具体情节、量化罚款幅度。 行政处罚裁量权基准应当包括违法行为、法定依据、裁量阶次、适用条件和具体标准等内容。 科技部制定的行政处罚裁量权基准应当向社会公布。行政处罚裁量权基准所依据的法律、行政法规、规章作出修改，或者客观情势发生重大变更的，应当及时进行调整。"},{"i":10,"n":"第十条","txt":"科技部实施行政处罚，应当以法律、行政法规、规章为依据，合理确定行政处罚的种类和幅度。 有行政处罚裁量权基准的，应当在行政处罚决定书中对行政处罚裁量权基准的适用情况予以明确。"},{"i":11,"n":"第十一条","txt":"科技部行政处罚应当由具有行政执法资格的执法人员实施。执法人员不得少于两人，法律另有规定的除外。 执法人员在进行案件调查、检查等直接面对当事人或者有关人员的活动中，应当主动出示行政执法证和调查、检查通知书等执法文书。"},{"i":12,"n":"第十二条","txt":"在实施行政处罚过程中，执法人员有下列情形之一的，应当主动回避，当事人及其代理人也有权申请其回避： （一）是案件当事人或者当事人近亲属的； （二）本人或者其近亲属与案件有利害关系的； （三）是案件的证人或者鉴定人的； （四）与案件有其他关系，可能影响公正处理的； （五）法律、行政法规规定应当回避的其他情形。"},{"i":13,"n":"第十三条","txt":"当事人或者其代理人对执法人员提出回避申请的，执法职能部门应当依法审查并提出是否回避的意见，报科技部负责人决定是否回避。回避决定作出前，不停止案件调查。"},{"i":14,"n":"第十四条","txt":"实施行政处罚过程中，作出影响公民、法人或者其他组织权利义务的决定，应当书面告知其获得救济的途径和期限。特殊情况下采取口头方式告知的，应当制作笔录。"},{"i":15,"n":"第十五条","txt":"执法职能部门应当对行政处罚过程进行文字记录，并根据行政处罚活动的环节、类别，采用相应音像记录形式： （一）对现场调查取证、举行听证、留置送达等易引起争议的环节，应当根据实际情况进行音像记录。 （二）对查封扣押财物等直接涉及当事人重大利益的现场执法活动，应当推行全程音像记录。"},{"i":16,"n":"第十六条","txt":"除涉及国家秘密、商业秘密、个人隐私等依法不得公开的情形外，科技部作出的具有一定社会影响的行政处罚决定应当依法公开，由执法职能部门会同政府信息公开工作机构在科技部网站公布。 公开的行政处罚决定被依法变更、撤销、确认违法或者确认无效的，执法职能部门应当在三个工作日内撤回行政处罚决定信息并公开说明理由。"},{"i":17,"n":"第十七条","txt":"已作出的行政处罚决定存在未载明非主要事项等遗漏情形，对当事人合法权益没有实质影响的，应当予以补正；存在文字或者计算错误等情形，对当事人合法权益没有实质影响的，应当予以更正。 作出补正或者更正的，执法职能部门应当制作补正或者更正文书，报科技部负责人批准后送达当事人。"},{"i":18,"n":"第十八条","txt":"执法职能部门在案件办理过程中获取的物品、设备、文字、视听资料、电子数据等证据材料应当及时进行登记并妥善保管。"},{"i":19,"n":"第十九条","txt":"执法职能部门在监督管理过程中发现违法线索，收到违法行为的举报、控告，或者收到其他机关移送的违法线索，应当进行登记。 科技部其他部门收到举报、控告或者其他机关移送的违法线索的，应当及时转交相关执法职能部门。"},{"i":20,"n":"第二十条","txt":"执法职能部门应当在线索登记之日起十五个工作日内，对线索进行初步核实，提出是否立案的建议，报科技部负责人决定是否立案；线索复杂的，经科技部负责人批准，可以延长十五个工作日。"},{"i":21,"n":"第二十一条","txt":"经初步核实认为存在应当给予行政处罚的违法行为，且科技部具有管辖权的，应当予以立案。 经核实没有发现违法行为、科技部不具有管辖权、违法行为已超过法定追究时效，或者存在其他依法不予立案情形的，不予立案。对科技部不具有管辖权的违法线索，应当及时移送有管辖权的机关。"},{"i":22,"n":"第二十二条","txt":"执法人员应当收集与案情有关的、能够证实违法行为性质和情节的证据。 证据类型包括书证、物证、视听资料、电子数据、证人证言、当事人陈述、鉴定意见、勘验笔录、现场笔录等。"},{"i":23,"n":"第二十三条","txt":"执法人员不得以胁迫、利诱、欺骗等不正当手段收集证据，不得伪造证据。"},{"i":24,"n":"第二十四条","txt":"执法人员进行调查取证，有权采取以下措施： （一）要求被调查单位或者个人提供与案件有关的文件资料，并就相关问题作出说明； （二）对当事人或者相关人员进行询问； （三）进入涉案现场进行检查、拍照、录音、摄像，查阅和复制相关材料； （四）对涉案物品、设施、场所进行先行登记保存； （五）对涉案场所、物品、资料进行查封、扣押； （六）法律、行政法规规定可以采取的其他措施。"},{"i":25,"n":"第二十五条","txt":"执法人员对当事人或者相关人员进行调查、询问时，应当制作《行政案件调查询问笔录》，如实完整记录调查询问的时间和地点、被调查人或者被询问人的基本信息、与案件有关的事实和经过、有关证据情况等。调查询问过程进行录音、录像的，应当事先告知被调查人、被询问人。 《行政案件调查询问笔录》应当由被调查人、被询问人核对无误后逐页签字或者盖章。被调查人、被询问人拒绝签字或者盖章的，执法人员应当在笔录上注明。笔录应当由在场的至少两名执法人员签字，并载明时间。"},{"i":26,"n":"第二十六条","txt":"调取的书证、物证应当是原件、原物。调取原件、原物确有困难的，可以调取复制件，注明“经核对与原件无异”字样或者相关文字说明。复制件及有关书证应当由证据提供人签字或者盖章，证据提供人拒绝签字或者盖章的，执法人员应当注明。 调取的视听资料、电子数据应当是原始载体或者备份介质。调取原始载体、备份介质确有困难的，可以调取复制件，注明复制件的制作方法、制作时间、制作人等情况。复制件应当由证据提供人签字或者盖章，证据提供人拒绝签字或者盖章的，执法人员应当注明。"},{"i":27,"n":"第二十七条","txt":"为查明案情，需要对案件中专门性问题进行检测、检验、检疫、鉴定的，执法职能部门应当委托具有法定资质的机构进行；没有法定资质机构的，可以委托其他具备条件的机构进行。"},{"i":28,"n":"第二十八条","txt":"执法人员收集证据时，发现证据可能灭失或者以后难以取得的，经所在执法职能部门报科技部负责人批准后可以先行登记保存。 依法对涉案相关物品先行登记保存的，执法职能部门应当制作《登记保存物品清单》，并向当事人或者物品持有人出具《登记保存物品通知书》。 执法人员实施先行登记保存时，应当通知当事人或者物品持有人到场，并在现场笔录中记载相关情况，必要时可以进行全程录音录像。"},{"i":29,"n":"第二十九条","txt":"执法职能部门对先行登记保存的证据，应当在七个工作日内根据具体情况作出下列处理决定： （一）需要采取证据保全措施的，应当采取记录、复制、拍照、录像等证据保全措施，返还登记保存物品； （二）需要检测、检验、检疫、鉴定的，送交具有相应资质或者条件的机构进行检测、检验、检疫、鉴定； （三）违法事实成立，依法应当予以没收的，应当作出行政处罚决定，没收非法财物； （四）违法事实不成立，或者违法事实成立但依法不应当予以没收的，解除先行登记保存。 逾期未作出处理决定的，应当及时解除先行登记保存。"},{"i":30,"n":"第三十条","txt":"下列证据不能作为行政处罚的定案依据： （一）以非法手段取得的证据； （二）被进行技术处理而无法辨明真伪的证据材料； （三）不能正确表达意思的证人提供的证言； （四）不具备真实性、合法性的其他证据材料； （五）法律、行政法规规定不能作为定案依据的其他证据材料。"},{"i":31,"n":"第三十一条","txt":"为制止违法行为、防止证据损毁、避免危害发生、控制危险扩大等，科技部可以依法采取查封场所、设施、财物或者扣押财物等行政强制措施。 查封、扣押限于涉案的场所、设施或者财物，不得查封、扣押与违法行为无关的场所、设施或者财物；不得查封、扣押公民个人及其扶养家属的生活必需品；不得对已被其他机关依法查封的场所、设施或者财物重复查封。"},{"i":32,"n":"第三十二条","txt":"执法职能部门认为需要依法实施查封、扣押的，应当报科技部负责人批准后实施。 查封、扣押应当严格按照《中华人民共和国行政强制法》第十八条的规定，由两名以上执法人员实施，制作并当场交付查封、扣押决定书和清单。"},{"i":33,"n":"第三十三条","txt":"查封、扣押的期限不得超过三十日。情况复杂的，经科技部负责人批准后可以延长，但是延长期限不得超过三十日，法律、行政法规另有规定的除外。延长查封、扣押决定应当及时书面告知当事人，并说明理由。 对查封、扣押的物品进行检测、检验、检疫或者鉴定的期间，不计算在查封、扣押期间内。"},{"i":34,"n":"第三十四条","txt":"采取查封、扣押措施后，应当及时查清事实，在规定期限内作出处理决定。 对违法事实清楚，依法应当没收的非法财物予以没收；法律、行政法规规定应当销毁的，依法销毁；应当解除查封、扣押的，及时作出解除查封、扣押决定。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一的，应当及时作出解除查封、扣押决定，并立即退还财物： （一）当事人没有违法行为的； （二）被查封、扣押的财物与违法行为无关的； （三）对违法行为已作出处理，不再需要查封、扣押的； （四）查封、扣押期限已经届满的； （五）不再需要采取查封、扣押措施的其他情形。"},{"i":36,"n":"第三十六条","txt":"案件调查结束后，执法职能部门应当制作调查报告。调查报告应当载明以下内容： （一）当事人的基本情况； （二）调查经过及采取强制措施的情况； （三）调查认定的事实及主要证据； （四）受调查行为的性质及后果； （五）其他需要说明的事项。"},{"i":37,"n":"第三十七条","txt":"确有应受行政处罚的违法行为的，执法职能部门应当根据情节轻重及具体情况，提出给予相应行政处罚的意见，报科技部负责人批准后，制作《行政处罚意见告知书》并送达当事人。 违法事实不成立，或者违法行为轻微，依法可以不予行政处罚的，执法职能部门应当提出不予行政处罚的意见，报科技部负责人批准后，制作《不予行政处罚意见告知书》并送达当事人。 违法行为涉嫌犯罪的，执法职能部门应当报科技部负责人批准后，移送司法机关。 案件情节复杂或者对重大违法行为给予行政处罚的，执法职能部门可以在报科技部负责人批准前，征求科技部法制机构意见。"},{"i":38,"n":"第三十八条","txt":"《行政处罚意见告知书》应当载明拟作出的行政处罚内容及事实、理由、依据，告知当事人依法享有陈述、申辩的权利。拟作出的行政处罚属于听证范围的，还应当告知当事人有要求听证的权利。 《不予行政处罚意见告知书》应当载明拟作出的不予行政处罚决定的事实、理由、依据，告知当事人依法享有陈述、申辩的权利。"},{"i":39,"n":"第三十九条","txt":"案件当事人行使陈述、申辩权的，应当自《行政处罚意见告知书》或者《不予行政处罚意见告知书》送达之日起五个工作日内向执法职能部门书面提出，逾期未提出的，视为放弃上述权利。"},{"i":40,"n":"第四十条","txt":"执法职能部门应当充分听取当事人的陈述、申辩，当事人的主张成立的，应当采纳。听取陈述申辩后，执法职能部门应当依照《中华人民共和国行政处罚法》第五十七条规定提出处理意见。不得因当事人的陈述、申辩而给予更重的处罚。"},{"i":41,"n":"第四十一条","txt":"科技部拟作出的行政处罚决定属于下列情形之一的，应当告知当事人有要求听证的权利。当事人要求听证的，应当组织听证： （一）对公民处以一万元以上罚款的； （二）对法人或者其他组织处以一百万元以上罚款的； （三）对公民处以没收违法所得和非法财物价值总额达到一万元以上的； （四）对法人或者其他组织处以没收违法所得和非法财物价值总额达到一百万元以上的； （五）降低资质等级、吊销许可证件的； （六）责令停产停业、责令关闭、限制从业的； （七）法律、行政法规规定应当听证的其他情形。 科技部制定的其他规章对前款第一至第四项所列数额标准另有规定的，从其规定。"},{"i":42,"n":"第四十二条","txt":"案件当事人要求听证的，应当自《行政处罚意见告知书》送达之日起五个工作日内向科技部法制机构书面提出并提交有关材料，逾期未提出的，视为放弃上述权利。 科技部法制机构收到听证申请后，应当制作《科技部行政处罚听证通知书》，载明听证的日期、地点等，并在举行听证七个工作日前送达当事人及有关人员。"},{"i":43,"n":"第四十三条","txt":"案件当事人可以亲自参加听证，也可以委托一至二人代理。委托他人代理参加听证的，应当提交书面委托书，载明委托事项及权限，并由委托人签字或者盖章。 案件当事人及其代理人无正当理由不出席听证或者未经许可中途退出听证的，视为放弃听证权利，听证依法终止。案件当事人中途主动要求终止听证的，应当准许。"},{"i":44,"n":"第四十四条","txt":"听证由科技部法制机构负责人或者其指定的人员主持，可以设一至二名听证员和一至二名记录员协助主持人进行听证。执法职能部门应当委派参与案件调查处理的两名以上执法人员参加听证。 参与案件调查处理的执法人员不得担任听证主持人、听证员和记录员。除涉及国家秘密、商业秘密或者个人隐私外，听证应当公开举行，允许公众旁听。"},{"i":45,"n":"第四十五条","txt":"听证实行回避制度。听证员、记录员的回避，由听证主持人决定；听证主持人的回避，由科技部法制机构主要负责人决定；听证主持人是科技部法制机构主要负责人的，其回避由科技部负责人决定。"},{"i":46,"n":"第四十六条","txt":"听证应按照下列程序进行： （一）听证主持人宣布听证开始； （二）听证主持人或者听证员宣读听证纪律； （三）执法人员就当事人的违法事实向听证主持人提出有关证据、依据和处理意见； （四）案件当事人或者代理人出示证据，进行申辩和质证； （五）听证双方就本案相关事实和认定进行辩论； （六）听证双方作最后陈述； （七）听证主持人或者听证员制作《科技部行政处罚听证笔录》，由听证双方核对无误后签字或者盖章，拒绝签字或者盖章的，听证主持人应当在笔录中注明。 听证结束后，执法职能部门应当根据听证笔录，依照《中华人民共和国行政处罚法》第五十七条规定提出处理意见。听证笔录应当及时归入行政处罚案卷。"},{"i":47,"n":"第四十七条","txt":"有下列情形之一的，在作出行政处罚决定前，应当进行法制审核： （一）涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）法律、行政法规规定应当法制审核的其他情形。"},{"i":48,"n":"第四十八条","txt":"属于本办法第四十七条规定情形的，执法职能部门应当将拟作出的行政处罚决定、调查报告、案件材料等送科技部法制机构进行法制审核。当事人对行政处罚意见告知提出陈述、申辩意见或者经过听证程序的，执法职能部门应当同时送交对当事人意见和证据复核采纳情况的书面说明。 科技部法制机构根据《中华人民共和国行政处罚法》《科技部法制审核工作暂行办法》等规定，对拟作出的行政处罚决定进行法制审核，并出具法制审核意见。 对应当开展法制审核而未经法制审核或者法制审核未通过的，不得作出行政处罚决定。"},{"i":49,"n":"第四十九条","txt":"拟作出的行政处罚决定经法制审核且审核通过的，由执法职能部门提交科技部党组会、部务会或者其他专题会议，经科技部负责人集体讨论后，形成行政处罚决定。 拟作出的行政处罚决定不属于本办法第四十七条规定情形的，不需要进行法制审核，由执法职能部门报科技部负责人批准后，形成行政处罚决定。"},{"i":50,"n":"第五十条","txt":"经科技部负责人批准或者集体讨论决定后，执法职能部门应当在七个工作日内制作《行政处罚决定书》或者《不予行政处罚决定书》，依照《中华人民共和国民事诉讼法》的规定送达当事人。 《行政处罚决定书》应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）违反法律、行政法规、规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）申请行政复议、提起行政诉讼的途径和期限； （六）作出决定的行政机关名称和决定日期； （七）法律、行政法规规定应当载明的其他事项。 《不予行政处罚决定书》应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）认定的事实、不予行政处罚的理由和依据； （三）申请行政复议、提起行政诉讼的途径和期限； （四）作出决定的行政机关名称和决定日期； （五）法律、行政法规规定应当载明的其他事项。"},{"i":51,"n":"第五十一条","txt":"行政处罚决定应当自立案之日起九十日内作出。案情复杂，不能在规定期限内作出行政处罚决定的，经科技部负责人批准，可以延长六十日。案情特别复杂，经延期仍不能作出行政处罚决定的，由科技部负责人集体讨论决定是否继续延期。决定延期的，应当同时确定延长的合理期限，但最长不得超过六十日。 案件办理过程中涉及的听证、公告、检测、检验、检疫、鉴定、审计、中止等时间不计入前款案件办理期限。 科技部制定的其他规章对案件办理期限另有规定的，从其规定。"},{"i":52,"n":"第五十二条","txt":"行政处罚决定作出后，当事人应当在《行政处罚决定书》载明的期限内履行。"},{"i":53,"n":"第五十三条","txt":"当事人确有经济困难，向科技部提出延期或者分期缴纳罚款的，应当在《行政处罚决定书》载明的履行期限内以书面方式提出申请。 执法职能部门收到当事人延期、分期缴纳罚款的申请后，应当在十个工作日内作出是否准许决定。"},{"i":54,"n":"第五十四条","txt":"当事人不履行行政处罚决定，且在法定期限内未申请行政复议、提起行政诉讼的，执法职能部门应当自期限届满之日起十个工作日内制发《履行行政处罚决定催告书》，书面催告当事人履行义务，并告知履行的期限和方式、依法享有的陈述权和申辩权。涉及金钱给付义务的，应当载明金额和给付方式。"},{"i":55,"n":"第五十五条","txt":"当事人收到《履行行政处罚决定催告书》后有权进行陈述、申辩。执法职能部门应当对当事人提出的陈述、申辩进行复核。当事人提出的事实、理由和证据成立的，应当予以采纳。"},{"i":56,"n":"第五十六条","txt":"经催告，当事人逾期仍不履行罚款的行政处罚决定且无正当理由的，执法职能部门可以提出每日按罚款数额的百分之三，总数额不超过罚款数额的加处罚款的行政强制执行建议，报科技部负责人批准后，作出行政强制执行决定，送达当事人。 科技部实施加处罚款超过三十日，经催告当事人仍不履行的，如已经依法采取查封、扣押措施，执法职能部门可以提出将已查封、扣押的财物依法拍卖抵缴罚款的行政强制执行建议，报科技部负责人批准后，作出行政强制执行决定，送达当事人。如未采取查封、扣押措施，应当向被执行人住所地或者被执行财产所在地的人民法院申请强制执行。"},{"i":57,"n":"第五十七条","txt":"科技部实施行政处罚，应当严格实行罚缴分离制度。罚款和违法所得应当由当事人按照《中华人民共和国行政处罚法》第六十七条的规定上缴国库。"},{"i":58,"n":"第五十八条","txt":"《履行行政处罚决定催告书》送达十个工作日后，当事人仍未履行非罚款的行政处罚决定的，执法职能部门报科技部负责人批准后，依照《中华人民共和国行政强制法》第五十三条的规定向人民法院申请强制执行。"},{"i":59,"n":"第五十九条","txt":"《履行行政处罚决定催告书》、行政强制执行决定书应当直接送达当事人。当事人拒绝接收或者无法直接送达当事人的，应当依照《中华人民共和国民事诉讼法》的有关规定进行送达。"},{"i":60,"n":"第六十条","txt":"对依法没收的非法物品，经科技部负责人批准，按照物品的不同性质分别作出下列处理： （一）按照国家有关规定公开拍卖，拍卖所得全部款项上缴国库； （二）没有价值或者价值轻微等无法拍卖的物品，统一登记造册后销毁； （三）违禁品、危险物品、特殊性质物品等禁止或者不宜流入市场的物品，按照有关规定统一登记造册后销毁或者交有关机构进行处理。"},{"i":61,"n":"第六十一条","txt":"执法职能部门及其执法人员有下列情形之一的，依法追究行政责任： （一）干扰、阻挠、拒绝行政执法监督的； （二）被举报、投诉经依法审查被确认违法的； （三）行政不作为造成严重不良影响的； （四）隐瞒案件事实、出具伪证、隐匿毁灭证据或者以权谋私的； （五）法律、行政法规、规章规定应当追究行政责任的其他情形。"},{"i":62,"n":"第六十二条","txt":"执法职能部门及其执法人员违反本办法规定，科技部视具体情况作出以下处理： （一）责令立即纠正或者限期改正； （二）责令履行法定职责； （三）撤销违法行政行为； （四）注销行政执法证； （五）对有关责任人员给予政务处分。"},{"i":63,"n":"第六十三条","txt":"违法实施行政处罚对当事人合法权益造成侵害的，科技部依法予以赔偿。"},{"i":64,"n":"第六十四条","txt":"实施行政处罚过程中，存在滥用职权、徇私舞弊、玩忽职守、贪污受贿等行为的，对负有责任的领导人员和直接责任人员依法依纪追究责任；构成犯罪的，依法追究刑事责任。"},{"i":65,"n":"第六十五条","txt":"本办法涉及期限的规定，注明为工作日的，不包含法定节假日；未注明为工作日的，为自然日。 本办法所称“以上”“不得超过”“不超过”“内”均包括本数或者本级。"},{"i":66,"n":"第六十六条","txt":"本办法由科技部负责解释。"},{"i":67,"n":"第六十七条","txt":"本办法自2023年4月20日起施行。"}],"kexuejishubuguizhangzhidingchengxudeguiding":[{"i":1,"n":"第一条","txt":"为了规范规章制定工作，提高工作效率，保证规章质量，根据《中华人民共和国立法法》和国务院《规章制定程序条例》的有关规定，结合科学技术部实际情况，制定本规定。"},{"i":2,"n":"第二条","txt":"科学技术部规章的制定、发布、解释、修改和废止等工作应当依照本规定。"},{"i":3,"n":"第三条","txt":"本规定所称“规章”，是指根据法律、法规和国务院的决定、命令，在科学技术部的职权范围内，由科学技术部或者科学技术部会同国务院有关部、委、局按规定程序制定，以科学技术部令形式发布的，用以规范科技管理工作、调整科技行政管理关系、具有普遍约束力的规范性文件。按其内容不同分别称“规定”、“办法”等。 对某一方面的行政工作所做的比较全面、系统的规范，称“规定”；对某一项行政工作所做的比较具体的规范，称“办法”。 工作规则、规程、标准、工作说明及图表、实施方案等规范性文件可以作为规章的附件或者单独发布，其效力由规章规定。"},{"i":4,"n":"第四条","txt":"下列文件不属于规章，不得以科学技术部令的形式发布： （一）不具有普遍约束力或者规范性的政策性文件； （二）内部工作规则、具体工作制度； （三）对具体事项的布告、公告、通知以及行政处理决定； （四）不具有普遍约束力或者规范性的其他文件。"},{"i":5,"n":"第五条","txt":"根据国家科技事业发展和科技工作的需要编制科学技术部规章制定规划和年度计划。"},{"i":6,"n":"第六条","txt":"规章制定规划和年度计划由科学技术部法制机构（以下简称法制机构）组织制定和执行。"},{"i":7,"n":"第七条","txt":"编制规章制定规划和年度计划，应在上一年年底以前拟订，由部内各单位提出规章制定建议，经法制机构汇总研究后，报部务会审定。 对于未列入年度计划，根据实际工作需要又必须制定的规章，经部务会审定后，可以作为补充项目实施。"},{"i":8,"n":"第八条","txt":"规章制定建议应当包括以下内容： （一）名称； （二）制定目的、依据和有关背景说明； （三）参考大纲或者参考文本； （四）进度安排； （五）主要起草单位、参加单位的建议。"},{"i":9,"n":"第九条","txt":"规章由业务主管单位负责起草。与多个单位的业务有关的规章，由主办单位牵头、有关单位共同参加起草。 法制机构在法律规范化方面进行指导。对于综合性、法律性较强以及其他重要的规章，可以由法制机构牵头起草。"},{"i":10,"n":"第十条","txt":"起草规章包括起草规章草案和规章草案的说明。 规章草案一般应当包括：制定宗旨和依据、适用范围、基本原则、管理机关、工作程序和具体规范、奖惩规定、施行日期等。规章草案的每条内容应有提示语，简要说明本条内容。 规章草案的说明主要包括：制定规章的必要性、宗旨和依据、指导思想和原则、起草过程、主要内容、实施和执行以及其他问题等。"},{"i":11,"n":"第十一条","txt":"规章应当结构严谨、条理清晰、用词准确、文字简练规范、标点符号正确。 起草规章，应当注意与有关行政法规、规章的衔接和协调。 起草规章，应当对内容相同的现行规章进行清理。如果现行规章将被起草的规章所代替，必须在规章草案中写明予以废止。"},{"i":12,"n":"第十二条","txt":"规章的内容分条文书写，冠以“第几条”字样，每条应当包含一项规则，可以分设款、项、目。款不冠数字，项冠以（一）、（二）、（三）等数字，目冠以１、２、３等数字。条、款、项、目均应当另起一行空二字书写。 规章内容繁杂或者条文较多的，可以分章、节。必要时，可以有目录、注释、附录、索引等附加部分。"},{"i":13,"n":"第十三条","txt":"起草单位在起草过程中应当征求部内有关单位和专家的意见，必要时并应当征求地方科技行政管理部门、科研机构等方面的意见。涉及国务院其他部门的职责或者与其他部门关系紧密的，还应当征求有关部门的意见。根据需要，起草单位可以组织专家对规章草案的内容进行论证。 起草单位根据征求意见和专家论证的情况，对规章征求意见稿进行修改，形成规章草案送审稿。经过协商不能取得一致意见或对重要意见未予采纳的，应当在报送规章草案送审稿时说明情况和理由。"},{"i":14,"n":"第十四条","txt":"规章草案定稿后，起草单位应当将送审报告、规章草案送审稿及其说明、各方面的意见及采纳情况，以及其他有关材料在提交部务会审议前正式报送法制机构审查。 报送审查的规章草案送审稿，应当由起草单位主要负责人签署；几个起草单位共同起草的规章送审稿，应当由参与起草的单位主要负责人共同签署。 规章草案送审稿的说明应当包括制定规章的背景和必要性、规定的主要措施等。 有关材料主要包括汇总的意见、听证会笔录、调研报告、国内外相关立法资料等。"},{"i":15,"n":"第十五条","txt":"规章草案送审稿由法制机构负责统一审查。"},{"i":16,"n":"第十六条","txt":"法制机构主要从以下方面对规章草案送审稿进行审查： （一）是否符合宪法、法律、行政法规和其他上位法的规定，是否与有关规章协调、衔接； （二）是否符合本规定第三条、第四条的规定； （三）是否正确处理有关单位、组织和公民对规章送审稿主要问题的意见； （四）是否符合立法技术要求； （五）需要审查的其他内容。"},{"i":17,"n":"第十七条","txt":"法制机构在审查中，认为需要进一步征求意见的，可以将规章草案送审稿或者规章草案送审稿涉及的主要问题发送有关单位、组织和专家征求意见，并可以根据需要深入基层进行实地调查研究。 规章草案送审稿直接涉及公民、法人或者其他组织切身利益，有关单位、组织或者公民对其有重大意见分歧的，经主管部长批准，法制机构可以向社会公布或者举行听证会征求社会各界的意见。"},{"i":18,"n":"第十八条","txt":"规章草案送审稿有下列情况之一的，由法制机构商起草单位予以修改： （一）内容与法律、行政法规、规章相抵触的； （二）不符合本规定第十条、第十一条和第十二条关于内容和形式要求的； （三）不符合本规定第十三条关于程序的规定的； （四）有关方面意见分歧大，需要作较大调整的； （五）条文内容不明确，适用性、可操作性差的。"},{"i":19,"n":"第十九条","txt":"规章草案送审稿有下列情况之一的，法制机构可以缓办或者退回起草单位： （一）制定规章的基本条件尚不成熟的； （二）有关机构或者部门对规章送审稿规定的主要制度存在较大争议，起草单位未与有关机构或者部门协商的； （三）上报送审稿不符合本规定第十四条规定的。"},{"i":20,"n":"第二十条","txt":"规章草案送审稿经法制机构审查通过后，形成报部务会审议的规章草案和对草案的说明以及提请部务会审议的建议。"},{"i":21,"n":"第二十一条","txt":"法制机构起草或者组织起草的规章草案，由法制机构主要负责人签署，提出提请部务会审议的建议。"},{"i":22,"n":"第二十二条","txt":"规章应当经部务会会议审议决定。 部务会审议规章草案时，由起草单位负责人或者法制机构负责人在会议上作起草说明。 部务会原则同意规章草案内容，并明确提出具体修改意见的，经起草单位和法制机构协商修改送各自主管部长核批后，报部长签署命令发布。部务会提出重大问题或者需要作大量修改的，经起草单位和法制机构论证、修改后，再次提交部务会审定。"},{"i":23,"n":"第二十三条","txt":"规章草案通过或批准后，由法制机构起草科学技术部令，报部长签署命令，公布规章。"},{"i":24,"n":"第二十四条","txt":"科学技术部令应当载明序号、规章名称、通过日期、施行日期、部长署名以及公布日期。 科学技术部联合国务院其他部门制定的联合规章，由科学技术部和其他部门首长共同签署公布。"},{"i":25,"n":"第二十五条","txt":"规章签署公布后应当及时在科学技术部公报和国务院公报上刊登，并应当在《科技日报》和科学技术部网站上刊登。"},{"i":26,"n":"第二十六条","txt":"规章应当自公布之日起三十日后施行。但是，涉及国家安全或者其他重大事项以及公布后不立即施行将有碍规章施行的，可以自公布之日起施行。"},{"i":27,"n":"第二十七条","txt":"自科学技术部令发布之日起三十日内，法制机构依照《立法法》和《法规规章备案条例》的规定向国务院备案。"},{"i":28,"n":"第二十八条","txt":"规章以及授权科学技术部解释的行政法规，由法制机构负责组织解释的起草工作。解释的内容需要与部内其他单位或国务院其他部委协商的，应当共同商定。 规章解释和对行政法规的解释应以书面形式进行，经部务会或部长审定后发布。"},{"i":29,"n":"第二十九条","txt":"规章的修改包括修订和修正。 对规章进行全面的修改，应当采取修订的形式。 规章有下列情况之一需要修改的，应当采取修正的形式： （一）基于政策或事实的需要，有必要增减内容的； （二）因有关法律、行政法规的修正或者废止而应作相应修改的； （三）规定的主管机关或者执行机关发生变更的； （四）同一事项在二个以上规章中有规定并且规定不一致的； （五）其他需要修改的情形。"},{"i":30,"n":"第三十条","txt":"规章有下列情况之一的，应予废止： （一）规定的事项已执行完毕，或者因情势变迁，无继续施行必要的； （二）因有关法律、行政法规的废止或者修订，失去立法依据的； （三）对同一事项已作出新规定的； （四）规章规定的施行期限届满的。"},{"i":31,"n":"第三十一条","txt":"规章的修改、废止，应当经法制机构审核，报部务会通过，由部长签署命令，予以公告。但因第三十条第三项和第四项废止的规章除外。 依前款程序废止的规章，自废止令发布之日起失效。"},{"i":32,"n":"第三十二条","txt":"国务院其他部门会同科学技术部制定联合规章，涉及科学技术部职能范围的部分，其起草、审查、审议、公布等工作参照本规定执行。"},{"i":33,"n":"第三十三条","txt":"国务院立法规划和计划中规定由科学技术部起草的法律、行政法规的起草工作，参照本规定执行。 法制机构会同部内有关单位组织法律、行政法规的起草工作。"},{"i":34,"n":"第三十四条","txt":"全国人大常委会和全国人大各专门委员会、国务院及国务院各部、委、直属机构征求科学技术部对法律、行政法规、规章草案意见的，由法制机构综合有关单位的意见后复函。涉及到重大问题或者重要事项的，报主管部长或部长审定后回复。"},{"i":35,"n":"第三十五条","txt":"法制机构负责有关法律、行政法规和规章的编纂、汇编工作。"},{"i":36,"n":"第三十六条","txt":"本规定自发布之日起施行。1988年12月27日发布的《国家科学技术委员会行政法规、规章发布办法》、1990年8月5日发布的《国家科委规章制定程序的规定》即行废止。"}],"kongjianwutidengjiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强国家对空间活动的管理，建立我国的空间物体登记制度，维护我国作为空间物体发射国的合法权益，有效履行《关于登记射入外层空间物体的公约》(以下简称《登记公约》)缔约国的义务，制订本办法。"},{"i":2,"n":"第二条","txt":"本办法所称空间物体是指进入外层空间的人造地球卫星、载人航天器、空间探测器、空间站、运载工具及其部件、以及其他人造物体。 短暂穿越外层空间的高空探测火箭和弹道导弹，不属于空间物体。"},{"i":3,"n":"第三条","txt":"本办法适用于在我国境内发射的所有空间物体，以及我国作为共同发射国在境外发射的空间物体。 发射国是指发射或促使发射空间物体的国家，以及从其领土或设施发射空间物体的国家。"},{"i":4,"n":"第四条","txt":"国家实行空间物体登记制度，所有从事发射或促成发射空间物体的政府部门、法人、其他组织和自然人均应依照本办法的规定履行登记义务。"},{"i":5,"n":"第五条","txt":"国防科学技术工业委员会(以下简称国防科工委)负责空间物体的国内登记管理工作，日常事务由国防科工委国际合作司负责。 涉及其他共同发射国的国内登记，必要时由国防科工委商外交部确定登记者。"},{"i":6,"n":"第六条","txt":"国家建立和保存空间物体国家登记册。国家登记册的主要内容包括：登记编号、登记者、空间物体所有者、空间物体名称、空间物体基本特性、空间物体发射者、运载器名称、发射日期、发射场名称、空间物体基本轨道参数、空间物体的发射及入轨情况等。 空间物体国家登记册登记表格式见附件。"},{"i":7,"n":"第七条","txt":"除本办法第八条规定外，空间物体应由空间物体的所有者进行国内登记。有多个所有者的空间物体由该物体的主要所有者代表全体所有者进行登记。 空间物体发射者应对该物体的国内登记提供必要的协助。"},{"i":8,"n":"第八条","txt":"在我国境内发射的空间物体的所有者为其他国家政府、法人、其他组织或自然人时，应由承担国际商业发射服务的公司进行国内登记。"},{"i":9,"n":"第九条","txt":"第七条和第八条所述空间物体登记者应在空间物体进入空间轨道60天内，按照本办法第六条所规定的内容，向国防科工委提交登记资料，履行登记手续。 依本办法所登记的空间物体的状态有重大改变(如轨道变化、解体、停止工作、返回及再入大气层等)时，空间物体登记者应在空间物体状态改变后60天内进行变更登记。"},{"i":10,"n":"第十条","txt":"在空间物体国家登记册中专设香港、澳门分册。香港特别行政区和澳门特别行政区拥有或发射的空间物体的具体登记办法另行制定。"},{"i":11,"n":"第十一条","txt":"空间物体国家登记册由国防科工委保存。 经国防科工委同意，国内有关政府部门和经政府主管部门批准的法人、其他组织和自然人可向登记册保存机关申请查询。"},{"i":12,"n":"第十二条","txt":"空间物体的国际登记，依照《登记公约》的有关规定，由国防科工委在空间物体国内登记后 60天内，通过外交部向联合国秘书处进行登记。"},{"i":13,"n":"第十三条","txt":"根据《登记公约》第四条第一款的规定，空间物体国际登记的主要内容包括：发射国国名、空间物体名称及登记号码、发射日期和地点、基本轨道参数、空间物体的一般功能等。"},{"i":14,"n":"第十四条","txt":"我国作为共同发射国的空间物体的国际登记，由外交部根据《登记公约》的有关规定商有关国家确定登记国。"},{"i":15,"n":"第十五条","txt":"本办法中涉及国内登记的有关规定由国防科工委负责解释；涉及《登记公约》条款及国际登记的有关规定由外交部负责解释。"},{"i":16,"n":"第十六条","txt":"本办法自发布之日起施行。"}],"tongjiyanzhongshixinqiyexinyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为推进统计领域信用建设，规范统计严重失信企业信用管理，按照党中央、国务院关于推进诚信建设、完善失信约束决策部署，根据《中华人民共和国统计法》《中华人民共和国统计法实施条例》等相关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于统计机构对企业的统计严重失信行为及其信息进行认定、记录、归集、共享、公开、惩戒和信用修复等活动。 本办法所称统计机构，是指国家统计局及其派出的调查机构、县级以上地方人民政府统计机构。 本办法所称企业，是指在各级人民政府、县级以上人民政府统计机构和有关部门组织实施的统计活动中，承担统计资料报送义务的企业。"},{"i":3,"n":"第三条","txt":"统计严重失信企业信用管理坚持“谁认定、谁管理、谁负责”的原则，按照依法依规、保护权益、审慎适度的总体思路组织实施。"},{"i":4,"n":"第四条","txt":"国家统计局统一领导全国统计严重失信企业信用管理工作。 县级以上地方人民政府统计机构负责本行政区域内统计严重失信企业的信用管理工作。国家统计局派出的调查机构组织实施的统计调查活动中发生的统计严重失信行为，由组织实施该项统计调查的调查机构负责有关企业的信用管理工作。 县级以上人民政府有关部门对其组织实施的统计调查活动中发现的统计严重失信行为线索，应当移送同级人民政府统计机构依法处理。"},{"i":5,"n":"第五条","txt":"统计机构应当归集、保存履职过程中采集的统计严重失信企业信息，按国家有关规定实施共享。"},{"i":6,"n":"第六条","txt":"企业有下列统计违法行为之一，且属于《中华人民共和国统计法实施条例》第五十条所列情节严重的，统计机构应当认定其为统计严重失信企业。 （一）拒绝提供统计资料或者经催报后仍未按时提供统计资料的； （二）提供不真实或者不完整的统计资料的； （三）拒绝答复或者不如实答复统计检查查询书的； （四）拒绝、阻碍统计调查、统计检查的； （五）转移、隐匿、篡改、毁弃或者拒绝提供原始记录和凭证、统计台账、统计调查表及其他相关证明和资料的； （六）其他统计严重失信行为。"},{"i":7,"n":"第七条","txt":"统计机构对符合统计严重失信认定条件的企业，应当在该企业行政处罚决定生效后5个工作日内制作统计严重失信企业认定告知书，告知事由、依据、后果以及享有的陈述、申辩权利，依照《中华人民共和国民事诉讼法》规定的送达方式送达。"},{"i":8,"n":"第八条","txt":"企业自收到统计严重失信认定告知书之日起5个工作日内，可以向作出认定的统计机构提出陈述、申辩。 统计机构认为企业提交的陈述、申辩材料不完整的，应当告知企业在规定时限内补充相关材料。 统计机构应当充分听取企业的意见，对企业提出的事实、理由和证据进行复核；企业提出的事实、理由或者证据成立的，统计机构应当采纳。"},{"i":9,"n":"第九条","txt":"统计机构应当在企业提交陈述、申辩材料时限截止之日起7个工作日内作出决定。统计机构认定企业为统计严重失信企业的，应当制作统计严重失信企业认定决定书，载明以下事项： 企业名称及其法定代表人或者负责人； 统一社会信用代码； 认定事由、依据； 公示渠道、期限和其他严重失信惩戒措施； 信用修复条件和程序； 申请行政复议和提起行政诉讼的途径和期限； 作出认定决定的统计机构名称和认定日期。 统计严重失信企业认定决定书应当依照《中华人民共和国民事诉讼法》规定的送达方式送达。"},{"i":10,"n":"第十条","txt":"统计机构应当自作出统计严重失信企业认定决定之日起10个工作日内向社会公示统计严重失信信息，包括： （一）企业基本信息，包括企业名称、地址、统一社会信用代码、法定代表人或者负责人等； （二）统计违法行为； （三）依法处理情况； （四）其他相关信息。"},{"i":11,"n":"第十一条","txt":"公示统计严重失信企业信息不得泄露国家秘密、商业秘密、个人隐私，不得危害国家安全和社会公共利益。"},{"i":12,"n":"第十二条","txt":"统计机构应当在本机构门户网站建立统计严重失信企业信息公示专栏公示统计严重失信企业信息，并将公示信息推送到上一级统计机构公示专栏。 未开通门户网站的统计机构，应当将本机构认定的统计严重失信企业信息在上一级统计机构公示专栏公示。 省级统计机构应当及时搜集本机构及市、县级统计机构认定的统计严重失信企业信息，按要求在认定后10个工作日内报送国家统计局，由国家统计局统一按规定推送至全国信用信息共享平台和国家企业信用信息公示系统，并在“信用中国”网站公示。"},{"i":13,"n":"第十三条","txt":"统计严重失信企业的公示期为1年。公示期限届满3日内，统计机构应当将统计严重失信信息移出统计机构门户网站，并同步将移出信息推送至全国信用信息共享平台和国家企业信用信息公示系统。 被认定为统计严重失信企业之日起2年内，企业再次被认定为统计严重失信企业的，自再次认定之日起公示3年。"},{"i":14,"n":"第十四条","txt":"公示期间，作出认定的统计机构应当加强对统计严重失信企业的日常监管，适当提高抽查频次，指导企业改正统计违法行为。"},{"i":15,"n":"第十五条","txt":"统计严重失信企业公示满6个月后，已经履行行政处罚决定、改正统计违法行为且未再发生统计违法行为的，可以向作出认定的统计机构提出信用修复申请。"},{"i":16,"n":"第十六条","txt":"申请信用修复的企业，应当向作出认定的统计机构提交信用修复申请书，包括履行行政处罚决定、整改到位证明材料及统计守信承诺等内容。"},{"i":17,"n":"第十七条","txt":"统计机构应当在收到企业信用修复申请书之日起20个工作日内，对统计严重失信企业的整改情况进行核实，并作出决定。 同意信用修复的，统计机构应当及时将统计严重失信信息移出统计机构门户网站，并同步将修复信息推送至全国信用信息共享平台和国家企业信用信息公示系统。 不同意信用修复的，统计机构应当书面告知企业，并说明理由。"},{"i":18,"n":"第十八条","txt":"统计严重失信企业弄虚作假骗取信用修复的，作出认定的统计机构应当撤销信用修复的决定，并自撤销之日起重新公示1年。"},{"i":19,"n":"第十九条","txt":"作出认定的统计机构发现统计严重失信企业认定的依据或者公示的信息不准确，应当在2个工作日内更正。 上级统计机构发现下级统计机构认定的依据或者公示的信息不准确，应当要求下级统计机构在2个工作日内更正。 统计严重失信企业有证据证明其被认定的依据或者公示的信息不准确，可以要求作出认定决定的统计机构进行更正。统计机构经核实确认信息不准确的，应当在2个工作日内更正。"},{"i":20,"n":"第二十条","txt":"统计严重失信企业对统计机构作出的认定决定或者信用修复决定不服，可以依法申请行政复议或者提起行政诉讼。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人有权举报企业统计严重失信行为和统计机构在统计严重失信企业信用管理工作中的违法行为。"},{"i":22,"n":"第二十二条","txt":"统计机构未按本办法履行职责的，由上一级统计机构责令改正；情节严重的，对负有责任的主管人员和其他直接责任人员依法依规追究责任。"},{"i":23,"n":"第二十三条","txt":"县级以上地方人民政府统计机构、国家统计局派出的调查机构，可以根据工作职责结合本地区、本系统实际情况对企业开展统计信用评价，实行信用分级管理。"},{"i":24,"n":"第二十四条","txt":"本办法由国家统计局负责解释。省级地方人民政府统计机构、国家统计局调查总队可以根据本办法制定本地区、本系统统计严重失信企业信用管理实施细则，并报国家统计局备案。"},{"i":25,"n":"第二十五条","txt":"本办法自公布之日起实施。《企业统计信用管理办法》（国统字〔2019〕33号）、《统计从业人员统计信用档案管理办法》（国统字〔2019〕34号）同时废止。"}],"tongjizhifajiandujianchabanfa":[{"i":1,"n":"第一条","txt":"为了规范统计执法监督检查工作，保护公民、法人和其他组织的合法权益，保障和提高统计数据质量，根据《中华人民共和国统计法》《中华人民共和国行政处罚法》和《中华人民共和国统计法实施条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于县级以上人民政府统计机构对执行统计法律法规规章情况的监督检查和对统计违法行为的查处。"},{"i":3,"n":"第三条","txt":"国家统计局统计执法监督局在国家统计局领导下，具体负责对全国统计执法监督检查工作的组织管理，指导监督地方统计机构和国家调查队统计执法监督检查机构工作，检查各地方、各部门统计法执行情况，查处重大统计违法行为。 省级及市级统计执法监督检查机构在所属统计局或者国家调查队领导下，具体负责指导监督本地区、本系统统计执法监督检查工作，对本地区、本系统统计法执行情况的检查和查处统计违法行为。县级统计执法监督检查机构或者执法检查人员在所属统计局或者国家调查队领导下，依据法定分工负责本地区、本系统统计执法监督检查工作。 地方统计机构和国家调查队应当建立统计执法监督检查沟通协作机制。"},{"i":4,"n":"第四条","txt":"县级以上人民政府有关部门在同级人民政府统计机构的组织指导下，负责监督本部门统计调查中执行统计法情况，对本部门统计调查中发生的统计违法行为，移交同级人民政府统计机构予以处理。"},{"i":5,"n":"第五条","txt":"各级人民政府统计机构应当建立行政执法监督检查责任制和问责制，切实保障统计执法监督检查所需的人员、经费和其他工作条件。"},{"i":6,"n":"第六条","txt":"统计执法监督检查应当贯彻有法必依、执法必严、违法必究的方针，坚持预防、查处和整改相结合，坚持教育与处罚相结合，坚持实事求是、客观公正、统一规范、文明执法、高效廉洁原则。 统计执法监督检查中，与执法监督检查对象有利害关系以及其他可能影响公正性的人员，应当回避。"},{"i":7,"n":"第七条","txt":"县级以上人民政府统计机构应当畅通统计违法举报渠道，公布统计违法举报电话、通信地址、网络专栏、电子邮箱等，认真受理、核实、办理统计违法举报。"},{"i":8,"n":"第八条","txt":"县级以上人民政府统计机构应当建立统计违法行为查处情况报告制度，定期向上一级统计机构报告统计违法举报、统计执法监督检查和统计违法行为查处情况。"},{"i":9,"n":"第九条","txt":"县级以上人民政府统计机构健全统计执法监督检查队伍，完善统计执法监督检查机制，建立统计执法骨干人才库，确保在库人员服从设库机构的调用。"},{"i":10,"n":"第十条","txt":"统计执法监督检查机构和执法检查人员的主要职责是： （一）起草制定统计法律法规规章和规范性文件； （二）宣传、贯彻统计法律法规规章； （三）组织、指导、监督、管理统计执法监督检查工作； （四）依法查处统计违法行为，防范和惩治统计造假、弄虚作假； （五）组织实施统计执法“双随机”抽查，受理、办理、督办统计违法举报； （六）建立完善统计信用制度，建立实施对统计造假、弄虚作假的联合惩戒机制； （七）监督查处涉外统计调查活动和民间统计调查活动中的违法行为； （八）法律、法规和规章规定的其他职责。"},{"i":11,"n":"第十一条","txt":"执法检查人员应当参加培训，经考试合格，取得由国家统计局统一颁发的统计执法证。 经县级以上人民政府统计机构批准，可以聘用专业技术人员参与统计执法监督检查。"},{"i":12,"n":"第十二条","txt":"统计执法监督检查机构应当加强对所属执法检查人员的法律法规、统计业务知识、职业道德教育和执法监督检查技能培训，健全管理、考核和奖惩制度。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府统计机构和有关部门应当建立统计执法监督检查工作机制和相关制度，综合运用“双随机”抽查、专项检查、重点检查、实地核查等方式，组织开展本地区、本部门、本单位统计执法监督检查工作。 按照国家有关规定，实施统计执法监督检查全过程记录制度。"},{"i":14,"n":"第十四条","txt":"统计执法监督检查事项包括： （一）地方各级人民政府、政府统计机构和有关部门以及各单位及其负责人遵守、执行统计法律法规规章和国家统计规则、政令情况； （二）地方各级人民政府、政府统计机构和有关部门建立防范和惩治统计造假、弄虚作假责任制和问责制情况； （三）统计机构和统计人员依法独立行使统计调查、统计报告、统计监督职权情况； （四）国家机关、企业事业单位和其他组织以及个体工商户和个人等统计调查对象遵守统计法律法规规章、统计调查制度情况； （五）依法开展涉外统计调查和民间统计调查情况； （六）法律法规规章规定的其他事项。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府统计机构对接到的举报应当严格按照规定予以受理，经审核可能存在统计违法行为的，应当采取立案查处、执法检查办理，市级以上人民政府统计机构也可以按照规定将举报转交下级统计机构办理。"},{"i":16,"n":"第十六条","txt":"县级以上人民政府统计机构在组织实施统计执法监督检查前应当拟定检查方案，明确检查的依据、时间、范围、内容和组织形式等。"},{"i":17,"n":"第十七条","txt":"统计执法监督检查机构或者执法检查人员组织实施执法监督检查前，应报所属人民政府统计机构负责人批准。"},{"i":18,"n":"第十八条","txt":"统计执法监督检查机构进行执法监督检查时，执法检查人员不得少于2名，并应当出示国家统计局统一颁发的统计执法证，告知检查对象和有关单位实施检查的人民政府统计机构名称，检查的依据、范围、内容和方式，以及相应的权利、义务和法律责任。未出示统计执法证的，有关单位和个人有权拒绝接受检查。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府统计机构调查统计违法行为或者核查统计数据时，依据《统计法》第三十五条的规定，行使统计执法监督检查职权。"},{"i":20,"n":"第二十条","txt":"检查对象和有关单位应当按照统计法律法规规定，积极配合执法监督检查工作，为检查工作提供必要的条件保障。有关人员应当如实回答询问、反映情况，提供相关证明和资料，核实笔录，并在有关证明、资料和笔录上签字，涉及单位的加盖公章。拒绝签字或者盖章的，由执法检查人员现场记录原因并录音录像。 有关地方、部门、单位应当及时通知相关人员按照要求接受检查。"},{"i":21,"n":"第二十一条","txt":"统计执法监督检查机构在执法监督检查过程中，应当及时按规定制作执法文书，如实记录执法检查人员询问情况和检查对象反映的情况以及提供的证明和资料，由执法检查人员在有关笔录上签名。"},{"i":22,"n":"第二十二条","txt":"县级以上人民政府统计机构和执法检查人员对在执法监督检查过程中知悉的国家秘密、商业秘密、个人信息资料和能够识别或者推断单个调查对象身份的资料，负有保密义务。"},{"i":23,"n":"第二十三条","txt":"统计执法监督检查机构应当在调查结束后，及时向所属人民政府统计机构提交监督检查报告，报告检查中发现的问题并提出处理建议。处理建议包括： （一）发现有统计违法行为，符合立案查处条件的，予以立案查处； （二）发现统计违法事实不清、证据不足或者程序错误的，应当及时补充或者重新调查； （三）按照违法行为性质、情节，提请上一级或者移交下级人民政府统计机构立案查处； （四）未发现统计违法行为或者统计违法事实轻微，依法不应追究法律责任的，不予处理。"},{"i":24,"n":"第二十四条","txt":"查处统计违法案件应当做到事实清楚，证据确凿，定性准确，处理恰当，适用法律正确，符合法定程序。"},{"i":25,"n":"第二十五条","txt":"国家统计局负责查处情节严重或影响恶劣的统计造假、弄虚作假案件，对国家重大统计部署贯彻不力的案件，重大国情国力调查中发生的严重统计造假、弄虚作假案件，其他重大统计违法案件。 省级统计局依法负责查处本行政区域内统计造假、弄虚作假案件，违反国家统计调查制度以及重要的地方统计调查制度的案件。但是国家调查总队组织实施的统计调查中发生的统计造假、弄虚作假案件，违反国家统计调查制度案件，由组织实施统计调查的国家调查总队进行查处。 市级、县级统计局和国家统计局市级、县级调查队，发现本行政区域内统计造假、弄虚作假违法行为的，应当及时报告省级统计机构依法查处；依法负责查处本行政区域内其他统计违法案件。"},{"i":26,"n":"第二十六条","txt":"统计执法监督检查机构具体负责查处统计违法行为，统计执法队接受所属统计机构委托开展有关执法检查工作。"},{"i":27,"n":"第二十七条","txt":"对下列统计违法行为，县级以上人民政府统计机构应当依法立案： （一）各地方、各部门、各单位及其负责人违反统计法律法规规章的； （二）县级以上人民政府统计机构及其工作人员违反统计法律法规规章的； （三）国家机关、企业事业单位和其他组织以及个体工商户等调查对象违反统计法律法规规章的； （四）违反国家统计规则、政令的； （五）违反涉外统计调查和民间统计调查有关法律法规规章的； （六）其他按照法律法规规章规定应当立案的。"},{"i":28,"n":"第二十八条","txt":"立案查处的统计违法行为，应当同时具备下列条件： （一）有明确的行为人； （二）有违反本办法第二十七条所列行为，依法应当追究法律责任； （三）属于人民政府统计机构职责权限和管辖范围。 统计执法监督检查机构或者执法检查人员按照前款规定的条件，对拟立案的有关材料进行初步审查并提出初步处理意见，报送所属人民政府统计机构负责人批准后，予以立案查处。"},{"i":29,"n":"第二十九条","txt":"立案查处的案件，一般案件执法检查人员不得少于2人，重大案件应当按规定组成执法检查组。"},{"i":30,"n":"第三十条","txt":"执法检查人员应当合法、客观、全面地收集证据。收集证据过程中，执法检查人员应当及时制作《现场检查笔录》《调查笔录》等文书，并整理制作《证据登记表》。 案件证据应当与本案件有关联，包括书证、物证、电子数据、视听资料、证人证言、当事人陈述、鉴定结论和勘验笔录等以及其他可证明违法事实的材料。"},{"i":31,"n":"第三十一条","txt":"调查结束后，执法检查组或者执法检查人员应当及时形成监督检查报告，报送所属人民政府统计机构负责人。 监督检查报告内容包括：立案依据、检查情况、违法事实、法律依据、违法性质、法律责任、酌定情形、处理意见等。"},{"i":32,"n":"第三十二条","txt":"统计执法监督检查机构应当及时组织召开会议，对案件进行讨论审理，确定统计违法行为性质和处理决定，报统计机构负责人审查。对情节复杂或者重大违法行为给予较重的行政处罚，应当集体讨论决定。 在审理过程中发现统计违法事实不清、证据不足或者程序错误的，应当责成执法检查组或者执法检查人员及时补充或者重新调查。"},{"i":33,"n":"第三十三条","txt":"统计违法案件审理终结，应当分别以下情况作出处理： （一）违反统计法律法规规章证据不足，或者统计违法事实情节轻微，依法不应追究法律责任的，即行销案； （二）违反统计法律法规规章事实清楚、证据确凿的，依法作出处理； （三）违反统计法律法规规章和国家统计规则、政令，应当给予处分的，移送任免机关或者纪检监察机关处理； （四）违反统计法律法规规章和国家统计规则、政令，被认定为统计严重失信的，按照国家有关规定进行公示和惩戒； （五）涉嫌违反其他法律法规规定的，移交有关行政机关处理； （六）涉嫌犯罪的，移送司法机关、监察机关处理。"},{"i":34,"n":"第三十四条","txt":"统计违法事实清楚、证据确凿，依法决定予以行政处罚的，应当在作出行政处罚决定前，制作《统计行政处罚决定告知书》，向处罚对象告知给予行政处罚的事实、理由、依据和处罚对象依法享有的权利。处罚对象对处罚决定进行陈述、申辩，提出不同意见时，统计执法监督检查机构应当认真听取。处罚对象提出新的事实、理由和证据，统计执法监督检查机构应当进行复核，复核成立的，予以采纳。"},{"i":35,"n":"第三十五条","txt":"县级以上人民政府统计机构作出对法人或者其他组织5万元以上罚款，对个体工商户作出2000元以上罚款的行政处罚决定前，应当告知处罚对象有要求举行听证的权利。处罚对象要求听证的，作出处罚决定的统计机构应当依法组织听证。 处罚对象应当在收到《统计行政处罚决定告知书》3日内向作出处罚决定的统计机构提出听证要求，作出处罚决定的统计机构应当在听证的7日前通知处罚对象举行听证的时间和地点。 听证由统计机构指定的非本案执法检查人员主持，处罚对象认为主持人与本案有直接利害关系的，有权申请回避。举行听证时，执法检查人员提出处罚对象违法的事实、证据和处罚建议，处罚对象进行申辩和质证。听证应当制作笔录，笔录应当交处罚对象审核无误后签字或者盖章。 听证结束后，统计机构依照本办法第三十三条作出处罚决定。"},{"i":36,"n":"第三十六条","txt":"统计违法行为应当给予行政处罚的，依法作出处罚决定，制作《统计行政处罚决定书》。《统计行政处罚决定书》应当载明下列事项： （一）处罚对象的名称或者姓名、地址； （二）违反统计法律法规规章的事实和证据； （三）统计行政处罚的种类和依据； （四）统计行政处罚的履行方式和期限； （五）不服统计行政处罚决定，申请行政复议或者提起行政诉讼的途径和期限； （六）作出统计行政处罚决定的统计机构名称和作出决定的日期。 统计行政处罚决定书必须盖有作出统计行政处罚决定的统计机构的印章。"},{"i":37,"n":"第三十七条","txt":"县级以上人民政府统计机构应当在《统计行政处罚决定书》作出后7日内送达处罚对象。处罚对象应当在送达回执上签字盖章，并注明签收日期。处罚对象拒绝接收的，应当在其他人员见证下，由送达人员、见证人员在送达回执上签字并注明理由，将《统计行政处罚决定书》留置；处罚对象不能接收的，应当在其他人员见证下，由送达人员、见证人员在送达回执上签字并注明理由。 邮寄送达的，应当通过中国邮政挂号寄送。"},{"i":38,"n":"第三十八条","txt":"统计行政处罚决定作出后，处罚对象应当在统计行政处罚决定的期限内予以履行。处罚对象对统计行政处罚决定不服，申请行政复议或者提起行政诉讼的，统计行政处罚不停止执行。 统计执法监督检查机构应当及时掌握统计行政处罚的执行情况。"},{"i":39,"n":"第三十九条","txt":"立案查处的统计违法行为，应当在立案后3个月内处理完毕；因特殊情况需要延长办理期限的，应当按规定报经批准，但延长期限不得超过3个月。"},{"i":40,"n":"第四十条","txt":"统计违法事实清楚并有法定依据，对法人或者其他组织予以警告或者警告并处1000元以下罚款行政处罚的，可以适用简易处罚程序，当场作出统计行政处罚决定。"},{"i":41,"n":"第四十一条","txt":"统计违法行为处理决定执行后，应当及时结案。 结案应当撰写结案报告，报送所属人民政府统计机构负责人同意，予以结案。"},{"i":42,"n":"第四十二条","txt":"县级以上人民政府统计机构在查处统计违法案件时，认为对有关国家工作人员应当给予处分处理的，应当按照有关规定提出处分处理建议，并将案件材料和处分处理建议移送具有管辖权的任免机关或者纪检机关、监察机关、组织（人事）部门。"},{"i":43,"n":"第四十三条","txt":"立案查处和执法检查的典型、严重统计违法案件，应当按照有关规定予以曝光。 对具有严重统计造假弄虚作假情形的，应当依法认定为统计上严重失信，按照有关规定予以公示和惩戒。"},{"i":44,"n":"第四十四条","txt":"县级以上人民政府统计机构负责人、执法检查人员及其相关人员在统计执法监督检查中有下列行为之一的，由统计机构予以通报，由任免机关或者纪检监察机关给予处分： （一）包庇、纵容统计违法行为； （二）瞒案不报，压案不查； （三）未按规定受理、核查、处理统计违法举报； （四）未按法定权限、程序和要求开展统计执法监督检查，造成不良后果； （五）违反保密规定，泄露举报人或者案情； （六）滥用职权，徇私舞弊； （七）其他违纪违法行为。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府统计机构负责人、执法检查人员及其相关人员在统计执法监督检查中，违反有关纪律的，依纪依法给予处分。"},{"i":46,"n":"第四十六条","txt":"县级以上人民政府统计机构负责人、执法检查人员及其相关人员泄露在检查过程中知悉的国家秘密、商业秘密、个人信息资料和能够识别或者推断单个调查对象身份的资料，依纪依法给予处分。"},{"i":47,"n":"第四十七条","txt":"本办法自公布之日起施行。"}],"tongjizhifazhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为保障统计执法工作顺利进行，规范统计执法证的颁发和管理工作，根据《中华人民共和国行政处罚法》《中华人民共和国统计法》《中华人民共和国统计法实施条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"统计执法证的申请、印制、核发、使用和监督管理适用本办法。"},{"i":3,"n":"第三条","txt":"统计执法证是统计执法人员依法从事统计执法活动时证明其身份的有效证件，是履行统计行政执法职责的凭证。"},{"i":4,"n":"第四条","txt":"从事统计执法工作的人员应当持有统计执法证。未取得统计执法证的，不得从事统计执法工作。 统计执法人员依法开展统计执法工作时，应当主动向统计检查对象出示统计执法证。"},{"i":5,"n":"第五条","txt":"国家统计局负责全国统计执法证的颁发和管理工作。 省级统计机构负责本地区、本系统统计执法证的申请、审核、管理工作。"},{"i":6,"n":"第六条","txt":"统计执法证由专用皮夹和内卡组成。 皮夹为横式黑色皮质，外部正面上部镂刻“中华人民共和国”字样、中间镂刻国徽图案、底部镂刻“统计执法证”字样，背面中部镂刻国家统计局标志、底部镂刻“国家统计局颁发”字样；内部放置内卡。 统计执法证内卡左侧为防伪塑封卡，标明“中华人民共和国统计执法证”字样和执法证号、持证人姓名、性别、照片、所在单位、发证机关、有效期限以及国家统计局印章，右侧为纸质卡片，标明执法人员职责、权限和监督电话。 国家对执法证制式有特殊规定的，从其规定。"},{"i":7,"n":"第七条","txt":"取得统计执法证，应当符合下列条件： （一）理想信念坚定，坚决执行组织决定； （二）坚持原则，作风正派，忠于职守，遵纪守法； （三）具备必要的法律知识，熟练掌握统计法律法规规章和相关行政法律法规的内容； （四）具备必要的统计业务知识，熟悉统计调查制度的主要内容； （五）熟练掌握统计执法流程和纪律规定； （六）法律、行政法规和规章规定的其他条件。"},{"i":8,"n":"第八条","txt":"取得统计执法证，应当具备下列资格： （一）县级以上人民政府统计机构中的公务员或者参照《中华人民共和国公务员法》管理的工作人员，且拟从事统计执法工作； （二）具有大专以上学历； （三）具备3年以上统计工作经验，或者具有法律专业本科以上学历且具备1年以上统计工作经验，或者在统计法治机构工作1年以上； （四）参加省级以上统计机构组织的统计执法培训，并且通过统计执法人员资格考试。"},{"i":9,"n":"第九条","txt":"有以下情形的人员不予颁发统计执法证： （一）3年内年度考核结果有不称职等次； （二）在统计工作中有违法记录； （三）因违反统计法律法规被处分； （四）因违反纪律受到党纪政务严重处分并在处分影响期。"},{"i":10,"n":"第十条","txt":"省级、市级、县级统计机构申请统计执法证，应当向省级以上统计执法机构提交拟颁发统计执法证人员的下列材料： （一）统计执法证申请表； （二）干部任免表； （三）学历证书复印件； （四）所在统计机构关于学历、编制、职务、年度考核结果的证明材料； （五）所在统计机构关于法律知识、统计业务知识、执法能力水平和无本办法第九条所列情形的证明材料。"},{"i":11,"n":"第十一条","txt":"统计机构对拟颁发统计执法证的人员应当依据本办法第七条、第八条、第九条规定进行初步审查。对符合条件和资格的，统计机构按照会议制度规定集体研究确定拟颁发统计执法证的人员名单，在《统计执法证申请表》相应栏目签署审查意见并加盖单位公章，报送省级统计机构审核。"},{"i":12,"n":"第十二条","txt":"省级统计执法机构收到《统计执法证申请表》后，按照本办法规定进行审核，对符合条件和资格的，提交省级统计机构按照会议制度规定集体研究确定拟颁发统计执法证人员，并报国家统计局统计执法监督局审定，由国家统计局颁发统计执法证。"},{"i":13,"n":"第十三条","txt":"国家统计局各单位申请统计执法证的，由司级机构依据本办法第七条、第八条、第九条规定对拟颁发统计执法证人员进行审核，对符合条件和资格的，在《统计执法证申请表》相应栏目签署审核意见并加盖单位公章，报送统计执法监督局。统计执法监督局按照本办法规定进行审核并集体研究确定拟颁发统计执法证的人员名单，报国家统计局领导审定。"},{"i":14,"n":"第十四条","txt":"国家统计局负责组织编制全国统计执法人员培训规划，制定培训大纲。 省级以上统计机构按照培训规划，组织开展统计执法人员岗位培训。"},{"i":15,"n":"第十五条","txt":"统计执法岗位培训分为资格培训和在岗培训，培训内容包括统计法律法规规章、相关行政法律法规、政策理论、统计专业知识、现场执法实务、党纪党规和工作制度等。"},{"i":16,"n":"第十六条","txt":"统计执法岗位培训师资应当是国家统计局、省级统计机构、国家统计局执法骨干人才库中的统计法治工作者、统计业务骨干，法律专家，具有丰富执法经验、熟练执法技能的人员。"},{"i":17,"n":"第十七条","txt":"国家统计局统计执法监督局负责制定统计执法人员资格考试大纲，建立考试题库。 省级以上统计机构按照考试大纲，负责组织本地区、本系统统计执法人员依据国家统计局统计执法监督局提供的试题进行资格考试，实行统一命题、统一制卷、统一阅卷。"},{"i":18,"n":"第十八条","txt":"统计执法人员资格考试包括法律基础知识、统计法律法规、相关法律法规、统计执法专业知识和其他相关知识。"},{"i":19,"n":"第十九条","txt":"省级以上统计机构应当严格按照国家统计局的规定，组织实施资格考试，确保参考人员严格遵守考场纪律。"},{"i":20,"n":"第二十条","txt":"省级以上统计机构应当免费组织开展统计执法人员岗位培训和资格考试。"},{"i":21,"n":"第二十一条","txt":"省级以上统计机构应当加强对持证人员的管理，建立统计执法证数据库并实行动态管理。 省级统计机构应当定期将本地区、本系统统计执法证使用情况报送国家统计局备案。"},{"i":22,"n":"第二十二条","txt":"省级以上统计机构应当通过政府网站向社会公布统计执法证的持有人姓名和所在单位、执法证号等信息，供社会公众查询。"},{"i":23,"n":"第二十三条","txt":"统计执法证由国家统计局统一印制，实行全国统一编号。 统计执法证由国家统计局统一核发。统计执法证自核发之日起，5年内有效。有效期届满的，应当依据本办法重新申请统计执法证。"},{"i":24,"n":"第二十四条","txt":"统计执法证限于持证人员从事统计执法工作使用。 持证人员应当依照法定职权使用统计执法证，不得涂改、复制、转借、抵押、赠送、买卖或者故意毁损，不得使用统计执法证进行非统计执法活动。"},{"i":25,"n":"第二十五条","txt":"持证人员应当妥善保管统计执法证，防止遗失、被盗或者损毁。 统计执法证遗失、被盗或者损毁的，持证人员应当及时报告所在单位，由所在单位按申请程序向原发证机关申请补办。持证人员所在单位和发证机关应当及时将遗失、被盗、损毁的统计执法证公告作废。"},{"i":26,"n":"第二十六条","txt":"持证人员有下列情况之一的，由所在单位收回其统计执法证并经省级统计机构审核后交发证机关注销： （一）退休； （二）辞职、被辞退； （三）不再从事统计执法工作； （四）统计执法证有效期届满； （五）因其他原因应当收回。"},{"i":27,"n":"第二十七条","txt":"国家统计局对统计执法证的申请、核发、管理和使用工作进行监督检查。 省级人民政府统计机构、国家统计局调查总队应当对本地区、本系统持证人员使用统计执法证的情况进行监督检查。"},{"i":28,"n":"第二十八条","txt":"建立统计执法证管理工作考核制度。国家统计局定期组织开展统计执法证管理工作抽查，每年对省级统计机构管理统计执法证工作情况进行考核。"},{"i":29,"n":"第二十九条","txt":"建立统计执法证人员抽查制度。国家统计局不定期抽取部分统计执法证持有人员，对资格考试试题范围内容进行复查。"},{"i":30,"n":"第三十条","txt":"持证人员有下列情形之一的，由省级以上统计机构批评教育，责令改正，可以暂扣其统计执法证： （一）超越法定权限执法或者违反法定程序执法，未造成严重后果； （二）将统计执法证用于非统计执法活动，未造成严重后果； （三）涉嫌违纪违法被立案审查，尚未做出结论； （四）其他原因应当暂扣。"},{"i":31,"n":"第三十一条","txt":"持证人员有下列情形之一的，由省级以上统计机构收缴其统计执法证： （一）超越法定权限执法或者违反法定程序执法，造成严重后果； （二）将统计执法证用于非统计执法活动，造成严重后果； （三）涂改、复制、转借、抵押、赠送、买卖或者故意毁损统计执法证； （四）利用职务上的便利，索取收受他人财物、收缴罚款据为己有或者进行其他违法活动； （五）有徇私舞弊、玩忽职守等渎职行为； （六）年度考核结果不称职； （七）受到行政拘留处罚、刑事拘留或者判处刑罚； （八）拒绝、阻碍统计执法检查，包庇、纵容统计违法行为； （九）受到党纪政务处分； （十）其他应当收缴统计执法证的情形。"},{"i":32,"n":"第三十二条","txt":"任何单位违反本办法规定，伪造、变造或者冒用统计执法证的，由国家统计局或者省级统计机构责令改正，予以警告，可以予以通报；其直接负责的主管人员和其他直接责任人员属于国家工作人员的，由任免机关或者纪检监察机关依照有关规定予以处分。"},{"i":33,"n":"第三十三条","txt":"违反本办法，擅自制作、发放统计执法证的，由国家统计局责令改正，予以警告，可以予以通报；其直接负责的主管人员和其他直接责任人员属于国家工作人员的，由任免机关或者纪检监察机关依照有关规定予以处分。"},{"i":34,"n":"第三十四条","txt":"违反本办法规定，构成违反治安管理行为的，依法予以治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"本办法自公布之日起施行。"}],"tongjidiaochazhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为保障政府统计调查工作顺利进行，规范统计调查证的颁发和管理工作，根据《中华人民共和国统计法》《中华人民共和国统计法实施条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"统计调查证是统计调查人员依法执行政府统计调查任务时证明其身份的有效证件。统计调查人员依法进行政府统计调查活动时，应当主动向统计调查对象出示统计调查证。 县级以上人民政府统计机构工作人员也可以持本单位颁发的工作证执行政府统计调查任务。 全国性普查的普查员和普查指导员，持普查员证或者普查指导员证依法执行普查任务。"},{"i":3,"n":"第三条","txt":"统计调查证由国家统计局统一格式，省级人民政府统计机构、国家统计局调查总队印制，县级以上地方人民政府统计机构、国家统计局各级调查队颁发。 省级人民政府统计机构、国家统计局调查总队依照本办法建立统计调查证核发和管理制度。"},{"i":4,"n":"第四条","txt":"统计调查证可以颁发给下列人员： （一）县级以上人民政府统计机构工作人员中，直接执行政府统计调查任务的调查人员； （二）县级以上人民政府统计机构聘用的调查人员。"},{"i":5,"n":"第五条","txt":"取得统计调查证的人员应当经过专业培训，具备相关的统计知识和调查技能。"},{"i":6,"n":"第六条","txt":"取得统计调查证，应当由本人填写登记表，经本人所在单位或者聘用单位审查，报省级人民政府统计机构或者国家统计局调查总队核准后，由本人所在单位或者聘用单位颁发。"},{"i":7,"n":"第七条","txt":"统计调查证应当标明下列内容： （一）持证人姓名、性别、出生年月； （二）持证人照片； （三）持证人所在单位或者聘用单位名称； （四）发证机关、证件编号； （五）发证日期、有效期限。"},{"i":8,"n":"第八条","txt":"持证人员的职责是： （一）宣传、执行统计法律、法规、规章和统计调查制度； （二）依法开展统计调查，如实搜集、报送统计资料； （三）要求有关统计调查对象依法真实、准确、完整、及时提供统计资料； （四）对其负责搜集、审核、录入的统计资料与统计调查对象报送的统计资料的一致性负责，依法要求统计调查对象改正不真实、不准确、不完整的统计资料。 持证人员对在政府统计调查中知悉的统计调查资料负有保密义务。"},{"i":9,"n":"第九条","txt":"发证机关应当加强对持证人员的管理。 持证人员不再从事政府统计调查活动或者统计调查证有效期届满的，由发证机关收回统计调查证。"},{"i":10,"n":"第十条","txt":"持证人员应当妥善保管统计调查证，不得涂改、转借、故意毁损统计调查证，不得使用统计调查证进行与政府统计调查无关的活动。"},{"i":11,"n":"第十一条","txt":"持证人员有下列情况之一的，由县级以上人民政府统计机构予以批评教育，并可以收缴统计调查证。情节较重，属于国家工作人员的，依纪依法给予处分；不属于国家工作人员的，解除聘用合同。构成违反治安管理行为的，依法予以治安管理处罚；构成犯罪的，依法追究刑事责任： （一）有统计违法行为； （二）将统计调查证转借他人使用； （三）利用统计调查证从事与政府统计调查无关的活动； （四）泄露统计调查资料。"},{"i":12,"n":"第十二条","txt":"任何单位违反本办法规定，伪造、变造或者冒用统计调查证的，由县级以上人民政府统计机构责令改正，予以警告，予以通报。对非经营活动中发生上述违法行为的，还可以处1000元以下的罚款。对经营活动中发生上述违法行为，有违法所得的，可以处违法所得1倍以上3倍以下但不超过3万元的罚款；没有违法所得，还可以处1万元以下的罚款。 对有前款违法行为的有关责任人员，由县级以上人民政府统计机构责令改正予以警告，可以予以通报，可以处1000元以下的罚款；构成违反治安管理行为的，依法予以治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":13,"n":"第十三条","txt":"对县级以上人民政府统计机构聘用的执行一次性统计调查任务的调查人员，可以颁发临时统计调查证。 临时统计调查证的颁发、管理由省级人民政府统计机构、国家统计局调查总队规定。"},{"i":14,"n":"第十四条","txt":"省级人民政府统计机构、国家统计局调查总队应当根据本办法制定本地区、本系统统计调查证管理实施办法。"},{"i":15,"n":"第十五条","txt":"本办法自2017年9月1日起实施。国家统计局2007年8月27日公布的《统计调查证管理办法》同时废止。"}],"tongjiweifaweijixingweichufenguiding":[{"i":1,"n":"第一条","txt":"为了加强统计工作，提高统计数据的准确性和及时性，惩处和预防统计违法违纪行为，促进统计法律法规的贯彻实施，根据《中华人民共和国统计法》、《中华人民共和国行政监察法》、《中华人民共和国公务员法》、《行政机关公务员处分条例》及其他有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"有统计违法违纪行为的单位中负有责任的领导人员和直接责任人员，以及有统计违法违纪行为的个人，应当承担纪律责任。属于下列人员的（以下统称有关责任人员），由任免机关或者监察机关按照管理权限依法给予处分： （一）行政机关公务员； （二）法律、法规授权的具有公共事务管理职能的事业单位中经批准参照《中华人民共和国公务员法》管理的工作人员； （三）行政机关依法委托的组织中除工勤人员以外的工作人员； （四）企业、事业单位、社会团体中由行政机关任命的人员。 法律、行政法规、国务院决定和国务院监察机关、国务院人力资源社会保障部门制定的处分规章对统计违法违纪行为的处分另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"地方、部门以及企业、事业单位、社会团体的领导人员有下列行为之一的，给予记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）自行修改统计资料、编造虚假数据的； （二）强令、授意本地区、本部门、本单位统计机构、统计人员或者其他有关机构、人员拒报、虚报、瞒报或者篡改统计资料、编造虚假数据的； （三）对拒绝、抵制篡改统计资料或者对拒绝、抵制编造虚假数据的人员进行打击报复的； （四）对揭发、检举统计违法违纪行为的人员进行打击报复的。 有前款第（三）项、第（四）项规定行为的，应当从重处分。"},{"i":4,"n":"第四条","txt":"地方、部门以及企业、事业单位、社会团体的领导人员，对本地区、本部门、本单位严重失实的统计数据，应当发现而未发现或者发现后不予纠正，造成不良后果的，给予警告或者记过处分；造成严重后果的，给予记大过或者降级处分；造成特别严重后果的，给予撤职或者开除处分。"},{"i":5,"n":"第五条","txt":"各级人民政府统计机构、有关部门及其工作人员在实施统计调查活动中，有下列行为之一的，对有关责任人员，给予记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）强令、授意统计调查对象虚报、瞒报或者伪造、篡改统计资料的； （二）参与篡改统计资料、编造虚假数据的。"},{"i":6,"n":"第六条","txt":"各级人民政府统计机构、有关部门及其工作人员在实施统计调查活动中，有下列行为之一的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级处分；情节严重的，给予撤职处分： （一）故意拖延或者拒报统计资料的； （二）明知统计数据不实，不履行职责调查核实，造成不良后果的。"},{"i":7,"n":"第七条","txt":"统计调查对象中的单位有下列行为之一，情节较重的，对有关责任人员，给予警告、记过或者记大过处分；情节严重的，给予降级或者撤职处分；情节特别严重的，给予开除处分： （一）虚报、瞒报统计资料的； （二）伪造、篡改统计资料的； （三）拒报或者屡次迟报统计资料的； （四）拒绝提供情况、提供虚假情况或者转移、隐匿、毁弃原始统计记录、统计台账、统计报表以及与统计有关的其他资料的。"},{"i":8,"n":"第八条","txt":"违反国家规定的权限和程序公布统计资料，造成不良后果的，对有关责任人员，给予警告或者记过处分；情节较重的，给予记大过或者降级处分；情节严重的，给予撤职处分。"},{"i":9,"n":"第九条","txt":"有下列行为之一，造成不良后果的，对有关责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）泄露属于国家秘密的统计资料的； （二）未经本人同意，泄露统计调查对象个人、家庭资料的； （三）泄露统计调查中知悉的统计调查对象商业秘密的。"},{"i":10,"n":"第十条","txt":"包庇、纵容统计违法违纪行为的，对有关责任人员，给予记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分。"},{"i":11,"n":"第十一条","txt":"受到处分的人员对处分决定不服的，依照《中华人民共和国行政监察法》、《中华人民共和国公务员法》、《行政机关公务员处分条例》等有关规定，可以申请复核或者申诉。"},{"i":12,"n":"第十二条","txt":"任免机关、监察机关和人民政府统计机构建立案件移送制度。 任免机关、监察机关查处统计违法违纪案件，认为应当由人民政府统计机构给予行政处罚的，应当将有关案件材料移送人民政府统计机构。人民政府统计机构应当依法及时查处，并将处理结果书面告知任免机关、监察机关。 人民政府统计机构查处统计行政违法案件，认为应当由任免机关或者监察机关给予处分的，应当及时将有关案件材料移送任免机关或者监察机关。任免机关或者监察机关应当依法及时查处，并将处理结果书面告知人民政府统计机构。"},{"i":13,"n":"第十三条","txt":"有统计违法违纪行为，应当给予党纪处分的，移送党的纪律检查机关处理。涉嫌犯罪的，移送司法机关依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"本规定由监察部、人力资源社会保障部、国家统计局负责解释。"},{"i":15,"n":"第十五条","txt":"本规定自2009年5月1日起施行。"}],"wangluoanquanshenchabanfa-2":[{"i":1,"n":"第一条","txt":"为了确保关键信息基础设施供应链安全,保障网络安全和数据安全,维护国家安全,根据《中华人民共和国国家安全法》、《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《关键信息基础设施安全保护条例》,制定本办法。"},{"i":2,"n":"第二条","txt":"关键信息基础设施运营者采购网络产品和服务,网络平台运营者开展数据处理活动,影响或者可能影响国家安全的,应当按照本办法进行网络安全审查。 前款规定的关键信息基础设施运营者、网络平台运营者统称为当事人。"},{"i":3,"n":"第三条","txt":"网络安全审查坚持防范网络安全风险与促进先进技术应用相结合、过程公正透明与知识产权保护相结合、事前审查与持续监管相结合、企业承诺与社会监督相结合,从产品和服务以及数据处理活动安全性、可能带来的国家安全风险等方面进行审查。"},{"i":4,"n":"第四条","txt":"在中央网络安全和信息化委员会领导下,国家互联网信息办公室会同中华人民共和国国家发展和改革委员会、中华人民共和国工业和信息化部、中华人民共和国公安部、中华人民共和国国家安全部、中华人民共和国财政部、中华人民共和国商务部、中国人民银行、国家市场监督管理总局、国家广播电视总局、中国证券监督管理委员会、国家保密局、国家密码管理局建立国家网络安全审查工作机制。 网络安全审查办公室设在国家互联网信息办公室,负责制定网络安全审查相关制度规范,组织网络安全审查。"},{"i":5,"n":"第五条","txt":"关键信息基础设施运营者采购网络产品和服务的,应当预判该产品和服务投入使用后可能带来的国家安全风险。影响或者可能影响国家安全的,应当向网络安全审查办公室申报网络安全审查。 关键信息基础设施安全保护工作部门可以制定本行业、本领域预判指南。"},{"i":6,"n":"第六条","txt":"对于申报网络安全审查的采购活动,关键信息基础设施运营者应当通过采购文件、协议等要求产品和服务提供者配合网络安全审查,包括承诺不利用提供产品和服务的便利条件非法获取用户数据、非法控制和操纵用户设备,无正当理由不中断产品供应或者必要的技术支持服务等。"},{"i":7,"n":"第七条","txt":"掌握超过100万用户个人信息的网络平台运营者赴国外上市,必须向网络安全审查办公室申报网络安全审查。"},{"i":8,"n":"第八条","txt":"当事人申报网络安全审查,应当提交以下材料： （一）申报书； （二）关于影响或者可能影响国家安全的分析报告； （三）采购文件、协议、拟签订的合同或者拟提交的首次公开募股（IPO）等上市申请文件； （四）网络安全审查工作需要的其他材料。"},{"i":9,"n":"第九条","txt":"网络安全审查办公室应当自收到符合本办法第八条规定的审查申报材料起10个工作日内,确定是否需要审查并书面通知当事人。"},{"i":10,"n":"第十条","txt":"网络安全审查重点评估相关对象或者情形的以下国家安全风险因素： （一）产品和服务使用后带来的关键信息基础设施被非法控制、遭受干扰或者破坏的风险； （二）产品和服务供应中断对关键信息基础设施业务连续性的危害； （三）产品和服务的安全性、开放性、透明性、来源的多样性,供应渠道的可靠性以及因为政治、外交、贸易等因素导致供应中断的风险； （四）产品和服务提供者遵守中国法律、行政法规、部门规章情况； （五）核心数据、重要数据或者大量个人信息被窃取、泄露、毁损以及非法利用、非法出境的风险； （六）上市存在关键信息基础设施、核心数据、重要数据或者大量个人信息被外国政府影响、控制、恶意利用的风险,以及网络信息安全风险； （七）其他可能危害关键信息基础设施安全、网络安全和数据安全的因素。"},{"i":11,"n":"第十一条","txt":"网络安全审查办公室认为需要开展网络安全审查的,应当自向当事人发出书面通知之日起30个工作日内完成初步审查,包括形成审查结论建议和将审查结论建议发送网络安全审查工作机制成员单位、相关部门征求意见；情况复杂的,可以延长15个工作日。"},{"i":12,"n":"第十二条","txt":"网络安全审查工作机制成员单位和相关部门应当自收到审查结论建议之日起15个工作日内书面回复意见。 网络安全审查工作机制成员单位、相关部门意见一致的,网络安全审查办公室以书面形式将审查结论通知当事人；意见不一致的,按照特别审查程序处理,并通知当事人。"},{"i":13,"n":"第十三条","txt":"按照特别审查程序处理的,网络安全审查办公室应当听取相关单位和部门意见,进行深入分析评估,再次形成审查结论建议,并征求网络安全审查工作机制成员单位和相关部门意见,按程序报中央网络安全和信息化委员会批准后,形成审查结论并书面通知当事人。"},{"i":14,"n":"第十四条","txt":"特别审查程序一般应当在90个工作日内完成,情况复杂的可以延长。"},{"i":15,"n":"第十五条","txt":"网络安全审查办公室要求提供补充材料的,当事人、产品和服务提供者应当予以配合。提交补充材料的时间不计入审查时间。"},{"i":16,"n":"第十六条","txt":"网络安全审查工作机制成员单位认为影响或者可能影响国家安全的网络产品和服务以及数据处理活动,由网络安全审查办公室按程序报中央网络安全和信息化委员会批准后,依照本办法的规定进行审查。 为了防范风险,当事人应当在审查期间按照网络安全审查要求采取预防和消减风险的措施。"},{"i":17,"n":"第十七条","txt":"参与网络安全审查的相关机构和人员应当严格保护知识产权,对在审查工作中知悉的商业秘密、个人信息,当事人、产品和服务提供者提交的未公开材料,以及其他未公开信息承担保密义务；未经信息提供方同意,不得向无关方披露或者用于审查以外的目的。"},{"i":18,"n":"第十八条","txt":"当事人或者网络产品和服务提供者认为审查人员有失客观公正,或者未能对审查工作中知悉的信息承担保密义务的,可以向网络安全审查办公室或者有关部门举报。"},{"i":19,"n":"第十九条","txt":"当事人应当督促产品和服务提供者履行网络安全审查中作出的承诺。 网络安全审查办公室通过接受举报等形式加强事前事中事后监督。"},{"i":20,"n":"第二十条","txt":"当事人违反本办法规定的,依照《中华人民共和国网络安全法》、《中华人民共和国数据安全法》的规定处理。"},{"i":21,"n":"第二十一条","txt":"本办法所称网络产品和服务主要指核心网络设备、重要通信产品、高性能计算机和服务器、大容量存储设备、大型数据库和应用软件、网络安全设备、云计算服务,以及其他对关键信息基础设施安全、网络安全和数据安全有重要影响的网络产品和服务。"},{"i":22,"n":"第二十二条","txt":"涉及国家秘密信息的,依照国家有关保密规定执行。 国家对数据安全审查、外商投资安全审查另有规定的,应当同时符合其规定。"},{"i":23,"n":"第二十三条","txt":"本办法自2022年2月15日起施行。2020年4月13日公布的《网络安全审查办法》（国家互联网信息办公室、国家发展和改革委员会、工业和信息化部、公安部、国家安全部、财政部、商务部、中国人民银行、国家市场监督管理总局、国家广播电视总局、国家保密局、国家密码管理局令第6号）同时废止。"}],"wangluoanquanshenchabanfa-5":[{"i":1,"n":"第一条","txt":"为了确保关键信息基础设施供应链安全，维护国家安全，依据《中华人民共和国国家安全法》《中华人民共和国网络安全法》，制定本办法。"},{"i":2,"n":"第二条","txt":"关键信息基础设施运营者（以下简称运营者）采购网络产品和服务，影响或可能影响国家安全的，应当按照本办法进行网络安全审查。"},{"i":3,"n":"第三条","txt":"网络安全审查坚持防范网络安全风险与促进先进技术应用相结合、过程公正透明与知识产权保护相结合、事前审查与持续监管相结合、企业承诺与社会监督相结合，从产品和服务安全性、可能带来的国家安全风险等方面进行审查。"},{"i":4,"n":"第四条","txt":"在中央网络安全和信息化委员会领导下，国家互联网信息办公室会同中华人民共和国国家发展和改革委员会、中华人民共和国工业和信息化部、中华人民共和国公安部、中华人民共和国国家安全部、中华人民共和国财政部、中华人民共和国商务部、中国人民银行、国家市场监督管理总局、国家广播电视总局、国家保密局、国家密码管理局建立国家网络安全审查工作机制。 网络安全审查办公室设在国家互联网信息办公室，负责制定网络安全审查相关制度规范，组织网络安全审查。"},{"i":5,"n":"第五条","txt":"运营者采购网络产品和服务的，应当预判该产品和服务投入使用后可能带来的国家安全风险。影响或者可能影响国家安全的，应当向网络安全审查办公室申报网络安全审查。 关键信息基础设施保护工作部门可以制定本行业、本领域预判指南。"},{"i":6,"n":"第六条","txt":"对于申报网络安全审查的采购活动，运营者应通过采购文件、协议等要求产品和服务提供者配合网络安全审查，包括承诺不利用提供产品和服务的便利条件非法获取用户数据、非法控制和操纵用户设备，无正当理由不中断产品供应或必要的技术支持服务等。"},{"i":7,"n":"第七条","txt":"运营者申报网络安全审查，应当提交以下材料： （一）申报书； （二）关于影响或可能影响国家安全的分析报告； （三）采购文件、协议、拟签订的合同等； （四）网络安全审查工作需要的其他材料。"},{"i":8,"n":"第八条","txt":"网络安全审查办公室应当自收到审查申报材料起，10个工作日内确定是否需要审查并书面通知运营者。"},{"i":9,"n":"第九条","txt":"网络安全审查重点评估采购网络产品和服务可能带来的国家安全风险，主要考虑以下因素： （一）产品和服务使用后带来的关键信息基础设施被非法控制、遭受干扰或破坏，以及重要数据被窃取、泄露、毁损的风险； （二）产品和服务供应中断对关键信息基础设施业务连续性的危害； （三）产品和服务的安全性、开放性、透明性、来源的多样性，供应渠道的可靠性以及因为政治、外交、贸易等因素导致供应中断的风险； （四）产品和服务提供者遵守中国法律、行政法规、部门规章情况； （五）其他可能危害关键信息基础设施安全和国家安全的因素。"},{"i":10,"n":"第十条","txt":"网络安全审查办公室认为需要开展网络安全审查的，应当自向运营者发出书面通知之日起30个工作日内完成初步审查，包括形成审查结论建议和将审查结论建议发送网络安全审查工作机制成员单位、相关关键信息基础设施保护工作部门征求意见；情况复杂的，可以延长15个工作日。"},{"i":11,"n":"第十一条","txt":"网络安全审查工作机制成员单位和相关关键信息基础设施保护工作部门应当自收到审查结论建议之日起15个工作日内书面回复意见。 网络安全审查工作机制成员单位、相关关键信息基础设施保护工作部门意见一致的，网络安全审查办公室以书面形式将审查结论通知运营者；意见不一致的，按照特别审查程序处理，并通知运营者。"},{"i":12,"n":"第十二条","txt":"按照特别审查程序处理的，网络安全审查办公室应当听取相关部门和单位意见，进行深入分析评估，再次形成审查结论建议，并征求网络安全审查工作机制成员单位和相关关键信息基础设施保护工作部门意见，按程序报中央网络安全和信息化委员会批准后，形成审查结论并书面通知运营者。"},{"i":13,"n":"第十三条","txt":"特别审查程序一般应当在45个工作日内完成，情况复杂的可以适当延长。"},{"i":14,"n":"第十四条","txt":"网络安全审查办公室要求提供补充材料的，运营者、产品和服务提供者应当予以配合。提交补充材料的时间不计入审查时间。"},{"i":15,"n":"第十五条","txt":"网络安全审查工作机制成员单位认为影响或可能影响国家安全的网络产品和服务，由网络安全审查办公室按程序报中央网络安全和信息化委员会批准后，依照本办法的规定进行审查。"},{"i":16,"n":"第十六条","txt":"参与网络安全审查的相关机构和人员应严格保护企业商业秘密和知识产权，对运营者、产品和服务提供者提交的未公开材料，以及审查工作中获悉的其他未公开信息承担保密义务；未经信息提供方同意，不得向无关方披露或用于审查以外的目的。"},{"i":17,"n":"第十七条","txt":"运营者或网络产品和服务提供者认为审查人员有失客观公正，或未能对审查工作中获悉的信息承担保密义务的，可以向网络安全审查办公室或者有关部门举报。"},{"i":18,"n":"第十八条","txt":"运营者应当督促产品和服务提供者履行网络安全审查中作出的承诺。 网络安全审查办公室通过接受举报等形式加强事前事中事后监督。"},{"i":19,"n":"第十九条","txt":"运营者违反本办法规定的，依照《中华人民共和国网络安全法》第六十五条的规定处理。"},{"i":20,"n":"第二十条","txt":"本办法中关键信息基础设施运营者是指经关键信息基础设施保护工作部门认定的运营者。 本办法所称网络产品和服务主要指核心网络设备、高性能计算机和服务器、大容量存储设备、大型数据库和应用软件、网络安全设备、云计算服务，以及其他对关键信息基础设施安全有重要影响的网络产品和服务。"},{"i":21,"n":"第二十一条","txt":"涉及国家秘密信息的，依照国家有关保密规定执行。"},{"i":22,"n":"第二十二条","txt":"本办法自2020年6月1日起实施，《网络产品和服务安全审查办法（试行）》同时废止。"}],"hangkongtiyuyundongguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对航空体育运动的管理，促进航空体育运动的发展，提高运动技术水平，保障飞行安全，根据《中华人民共和国飞行基本规则》、国务院《关于通用航空管理的暂行规定》和《中华人民共和国民用航空器适航管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内所有使用民用航空器和航空运动器材从事航空体育运动的单位和个人。 航空体育运动使用的民用航空器包括飞机、直升机、滑翔机、载人气球、飞艇等。 航空体育运动使用的航空运动器材包括降落伞、滑翔伞、悬挂滑翔机、航空模型以及绞盘车、收索机等牵引设备。"},{"i":3,"n":"第三条","txt":"航空体育运动实行国家体育运动委员会和省、自治区、直辖市体育运动委员会分级管理体制。"},{"i":4,"n":"第四条","txt":"国家体育运动委员会统一管理全国的航空体育运动。主要职责是： (一)贯彻实施国家法律、行政法规有关航空体育运动的规定，制定和实施航空体育运动的规章、制度。 (二)编制航空体育运动发展规划。 (三)制定各项航空体育运动的训练大纲、训练规则、竞赛规则和航空运动器材使用维护规定。审定航空体育运动教材、教学法和裁判法。 (四)制定航空体育运动项目教练员、运动员、裁判员技术标准，受理和组织专业技术岗位考核，颁发相应的证书。 (五)检查监督航空体育运动飞行安全。 (六)承办中国民用航空局(以下称民航局)和军事主管部门委托的与航空体育运动有关的工作。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市体委管理本地区的航空体育运动。主要职责人按照国家发布的航空法规及国家体育运动委员会、中国民用航空局发布的有关航空管理的规章制度，实施对本地区航空体育运动的管理。"},{"i":6,"n":"第六条","txt":"从事航空体育运动的单位(航空运动学校、航空运动训练基地、航空体育俱乐部等)和个人，除由省、自治区。直辖市体委主管外，还应根据开展不同的航空运动项目分别接受民航地区管理局有关通用航空时行业管理，接受当地空中交通管制、无线电管理等主管部门有关业务工作的管理。"},{"i":7,"n":"第七条","txt":"从事除航空模型普及活动以外的航空体育运动的单位和个人，必须向所在地区的省、自治区、直辖市体委报告并办理登记手续。 使民用航空器进行航空体育运动的，还应当按照国务院《关于通用航空管理的暂行规定》第四条规定，向民航地区管理局履行申请审批手续，取得通用航空许可证。"},{"i":8,"n":"第八条","txt":"从事航空体育运动的单位应具备下列条件： (一)担任航空器飞行教员的技术等级与其所担任的教学任务，应当与民航局签发的民用航空器飞行驾驶执照相符合。担任跳伞、悬挂滑翔教练员的，应持有国家体委颁发的教练员证书。 (二)所用航空器和航空器维修工作必须符合《中华人民共和国民用航空器适航管理条例》和民航局颁发的有关规定。 (三)训练场地必须符合所从事航空体育运动项目的技术要求。 (四)飞行区域和空域必须获得空中交通管制部门的批准。 (五)航空体育运动机场应与当地空中交通管制主管部门建立有线电通信联系。 (六)使用民用航空器从事经营性活动的，应当按照《中华人民共和国企业法人登记管理条例》及实施细则和《开办通用航空业审批程序》的有关规定，领取营业执照。使用航空运动器材从事以营利为目的经营性活动的，应当向当地体育行政主管部门申请登记，并向工商行政管理部门领取营业执照。"},{"i":9,"n":"第九条","txt":"航空体育运动单位和参加航空体育运动训练的人应当执行航空体育运动的教学大纲、训练规则、竞赛规则和航空器、运动器材使用维护规定。"},{"i":10,"n":"第十条","txt":"参加航空体育运动驾驶航空器飞行和使用航空运动器材升空的人，应符合下列规定： (一)参加飞机跳伞的必须年满十五周岁，单独驾驶航空器或悬挂滑翔机飞行的必须年满十六周岁。未满十六周岁驾驶航空器飞行的必须有教练员(教员)同乘，并对其安全负责。 (二)必须持有身体检查合格证明。 (三)必须持有民用航空器驾驶执服，学员在学习期间除外。 (四)必须持有所驾驶的航空器飞行手册。 (五)参加跳伞和悬挂滑翔运动的运动员应持有运动证书。"},{"i":11,"n":"第十一条","txt":"从事航空体育运动的教练员、运动员每年必须进行一次全面的空勤体格检查。领取民航局驾驶执照的驾驶员、飞行教员的体格只能在民航局认可的医疗单位进行。航空体育运动单位的航空医生负责飞行人员、跳伞员的医务监督和日常体检、治疗工作。 航空器维修人员每年进行一次例行的体格检查。"},{"i":12,"n":"第十二条","txt":"从事航空体育运动的飞行驾驶人员，必须经过系统的航空理论和驾驶技术培训，并按照民用航空器飞行人员执照制度的规定，向民航局申请办理各种航空器的驾驶员执照。 航行调度人员应当按照民航局的规定办理执照。 跳伞和悬挂滑翔的运动员应当按照国家体委的规定，申请办理相关的运动证书。"},{"i":13,"n":"第十三条","txt":"航空体育运动所用的航空器和航空器的使用、维修工作，必须遵守《中华人民共和国民用航空器适航管理条例》和民航局发布的有关适航管理规章中的有关规定，向民航局申请办理航空器国籍登记证、适航证、维修人员执照和维修许可证。 航空体育运动所用航空器的初始适航管理工作，由民航局统一归口管理。 体育系统航空体育运动所用二乘员以上(不含二乘员)航空器的持续适航管理工作，应当接受民航局和航空器所在地的民航地区管理局适航管理部门直接管理；其他航空器的持续适航管理，由民航局委任的特别委任适航代表按照民航局颁发或审定的有关持续适航管理的各项规章进行管理。 航空体育运动所使用的各种航空运动器材(航空模型除外)，必须具有经国家生产主管部门和体育主管部门审定签发的产品合格证和产品维护使用手册上可使用。各种航空运动器材的维修工作，应严格按照维护使用手册规定进行。"},{"i":14,"n":"第十四条","txt":"从事航空体育运动(航空模型项目除外)的单位和个人，应当向中国人民保险公司投保机身险和第三者责任险。飞行和跳伞人员应投保人身意外险。"},{"i":15,"n":"第十五条","txt":"航空体育运动单位，应当根据国家和民航局关于机场的有关规定使用、保护、管理机场。航空体育运动机场的修建、废弃、合用或改作他用都要按国家有关规定履行审批手续。 航空体育运动单位与军队、民航合用机场，应当遵守双方签订的协议，维护好机场净空和设施，维持好机场的空中和地面秩序。 禁止任何单位和个人侵占或破坏航空体育运动场地和设施。"},{"i":16,"n":"第十六条","txt":"航空体育运动单位的飞行活动应当按照规定向当地的空中交通管制部门申请，获准后方可飞行。航空体育运动单位的航行调度员具体负责本单位的航务管理工作。"},{"i":17,"n":"第十七条","txt":"国(境)外飞行人员及跳伞员在中华人民共和国境内参加航空体育运动的，必须履行下列批准手续： (一)属于中国航空运动协会邀请的，或国(境)外航空体育组织或个人向中国航空运动协会提出申请的，应向国家体委申报，由国家体委会同有关部门批准。 属于省、自治区、直辖市航空运动协会邀请的，或国(境)外航空体育组织或个人向省、自治区、直辖市航空运动协会提出申请的，应向省、自治区、直辖市体委申报，由省、自治区、直辖市体委报请省、自治区、直辖市人民政府及国家有关部门批准。 (二)国(境)外人员在我国境内飞行(含使用自带航空器)，主办单位应当按照国家有关规定办理申报手续，并抄报民航局和有关单位，获准后方可入境飞行。如使用民航机场和航路，应事先征得民航局同意。 (三)国(境)外人员使用自带航空器飞入或者飞出我国国界和在我国境内飞行，主办单位还应按照《外国民用航空器飞行管理规则》、《民用航空器飞行人员执照暂行规定"},{"i":18,"n":"第十八条","txt":"国(境)外飞行人员及跳伞运动员在中华人民共和国境内参加航空体育运动，须符合下列规定： (一)持有本国(地区)有效的驾驶执照(或运动证书)，所记载的技术标准应与其所从事的飞行活动内容相符合。驾驶执照须经民航局审核认可。 (二)持有有效的体检合格证明。 (三)持有人身保险证明。驾驶运动飞机、滑翔机、动力滑翔机、载人气球、悬挂滑翔机、超轻型飞机的，还应由主办单位或飞行者本人投保机身险和第三者责任险。 (四)自带航空器或降落伞参加航空体育运动的，其器材的安全可靠性由使用者本人负责、自带航空器的，其适航证应经民航局审核认可。"},{"i":19,"n":"第十九条","txt":"国(境)外飞行人员在中华人民共和国境内参加航空体育运动时，主办单位应向其讲解和说明中国有关飞行、无线电管理使用以及空中摄影的有关规定，并监督其执行。"},{"i":20,"n":"第二十条","txt":"航空体育运动使用航空器发生的飞行事故的调查，按照中国民用航空局颁发的《中国民用航空飞行事故调查条例》和民航局的委托进行。 一等飞行事故由国家体委派人参与省、自治区、直辖市体委组织调查处理，并向国家体委和民航局报告。二、三等飞行事故由省、自治区、直辖市体委负责调查处理，并报告国家体委和民航地区管理局。 跳伞和悬挂滑翔运动的一、二、三等事故，分别由省、自治区、直辖市体委组织或指定事故调查组调查处理，并报告国家体委。"},{"i":21,"n":"第二十一条","txt":"航空模型运动的管理办法，按照航空模型训练大纲、训练规则、竞赛规则的规定进行。 航空模型飞机的飞行高度和空域与其他航空器的飞行活动有关联时，主持航空模型活动的单位或个人应同机场当局或当地飞行管制部门取得联系，划定航空模型的飞行高度和区域。"},{"i":22,"n":"第二十二条","txt":"本办法由国家体委负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自发布之日起施行。"}],"yaopinjingyingzhiliangguanliguifan":[{"i":1,"n":"第一条","txt":"为加强药品经营质量管理，规范药品经营行为，保障人体用药安全、有效，根据《中华人民共和国药品管理法》、《中华人民共和国药品管理法实施条例》，制定本规范。"},{"i":2,"n":"第二条","txt":"本规范是药品经营管理和质量控制的基本准则。 企业应当在药品采购、储存、销售、运输等环节采取有效的质量控制措施，确保药品质量，并按照国家有关要求建立药品追溯系统，实现药品可追溯。"},{"i":3,"n":"第三条","txt":"药品经营企业应当严格执行本规范。 药品生产企业销售药品、药品流通过程中其他涉及储存与运输药品的，也应当符合本规范相关要求。"},{"i":4,"n":"第四条","txt":"药品经营企业应当坚持诚实守信，依法经营。禁止任何虚假、欺骗行为。"},{"i":5,"n":"第五条","txt":"企业应当依据有关法律法规及本规范的要求建立质量管理体系，确定质量方针，制定质量管理体系文件，开展质量策划、质量控制、质量保证、质量改进和质量风险管理等活动。"},{"i":6,"n":"第六条","txt":"企业制定的质量方针文件应当明确企业总的质量目标和要求，并贯彻到药品经营活动的全过程。"},{"i":7,"n":"第七条","txt":"企业质量管理体系应当与其经营范围和规模相适应，包括组织机构、人员、设施设备、质量管理体系文件及相应的计算机系统等。"},{"i":8,"n":"第八条","txt":"企业应当定期以及在质量管理体系关键要素发生重大变化时，组织开展内审。"},{"i":9,"n":"第九条","txt":"企业应当对内审的情况进行分析，依据分析结论制定相应的质量管理体系改进措施，不断提高质量控制水平，保证质量管理体系持续有效运行。"},{"i":10,"n":"第十条","txt":"企业应当采用前瞻或者回顾的方式，对药品流通过程中的质量风险进行评估、控制、沟通和审核。"},{"i":11,"n":"第十一条","txt":"企业应当对药品供货单位、购货单位的质量管理体系进行评价，确认其质量保证能力和质量信誉，必要时进行实地考察。"},{"i":12,"n":"第十二条","txt":"企业应当全员参与质量管理。各部门、岗位人员应当正确理解并履行职责，承担相应质量责任。"},{"i":13,"n":"第十三条","txt":"企业应当设立与其经营活动和质量管理相适应的组织机构或者岗位，明确规定其职责、权限及相互关系。"},{"i":14,"n":"第十四条","txt":"企业负责人是药品质量的主要责任人，全面负责企业日常管理，负责提供必要的条件，保证质量管理部门和质量管理人员有效履行职责，确保企业实现质量目标并按照本规范要求经营药品。"},{"i":15,"n":"第十五条","txt":"企业质量负责人应当由高层管理人员担任，全面负责药品质量管理工作，独立履行职责，在企业内部对药品质量管理具有裁决权。"},{"i":16,"n":"第十六条","txt":"企业应当设立质量管理部门，有效开展质量管理工作。质量管理部门的职责不得由其他部门及人员履行。"},{"i":17,"n":"第十七条","txt":"质量管理部门应当履行以下职责： （一）督促相关部门和岗位人员执行药品管理的法律法规及本规范； （二）组织制订质量管理体系文件，并指导、监督文件的执行； （三）负责对供货单位和购货单位的合法性、购进药品的合法性以及供货单位销售人员、购货单位采购人员的合法资格进行审核，并根据审核内容的变化进行动态管理； （四）负责质量信息的收集和管理，并建立药品质量档案； （五）负责药品的验收，指导并监督药品采购、储存、养护、销售、退货、运输等环节的质量管理工作； （六）负责不合格药品的确认，对不合格药品的处理过程实施监督； （七）负责药品质量投诉和质量事故的调查、处理及报告； （八）负责假劣药品的报告； （九）负责药品质量查询； （十）负责指导设定计算机系统质量控制功能； （十一）负责计算机系统操作权限的审核和质量管理基础数据的建立及更新； （十二）组织验证、校准相关设施设备； （十三）负责药品召回的管"},{"i":18,"n":"第十八条","txt":"企业从事药品经营和质量管理工作的人员，应当符合有关法律法规及本规范规定的资格要求，不得有相关法律法规禁止从业的情形。"},{"i":19,"n":"第十九条","txt":"企业负责人应当具有大学专科以上学历或者中级以上专业技术职称，经过基本的药学专业知识培训，熟悉有关药品管理的法律法规及本规范。"},{"i":20,"n":"第二十条","txt":"企业质量负责人应当具有大学本科以上学历、执业药师资格和3年以上药品经营质量管理工作经历，在质量管理工作中具备正确判断和保障实施的能力。"},{"i":21,"n":"第二十一条","txt":"企业质量管理部门负责人应当具有执业药师资格和3年以上药品经营质量管理工作经历，能独立解决经营过程中的质量问题。"},{"i":22,"n":"第二十二条","txt":"企业应当配备符合以下资格要求的质量管理、验收及养护等岗位人员： （一）从事质量管理工作的，应当具有药学中专或者医学、生物、化学等相关专业大学专科以上学历或者具有药学初级以上专业技术职称； （二）从事验收、养护工作的，应当具有药学或者医学、生物、化学等相关专业中专以上学历或者具有药学初级以上专业技术职称； （三）从事中药材、中药饮片验收工作的，应当具有中药学专业中专以上学历或者具有中药学中级以上专业技术职称；从事中药材、中药饮片养护工作的，应当具有中药学专业中专以上学历或者具有中药学初级以上专业技术职称；直接收购地产中药材的，验收人员应当具有中药学中级以上专业技术职称。 从事疫苗配送的，还应当配备2名以上专业技术人员专门负责疫苗质量管理和验收工作。专业技术人员应当具有预防医学、药学、微生物学或者医学等专业本科以上学历及中级以上专业技术职称，并有3年以上从事疫苗管理或者技术工作经历。"},{"i":23,"n":"第二十三条","txt":"从事质量管理、验收工作的人员应当在职在岗，不得兼职其他业务工作。"},{"i":24,"n":"第二十四条","txt":"从事采购工作的人员应当具有药学或者医学、生物、化学等相关专业中专以上学历，从事销售、储存等工作的人员应当具有高中以上文化程度。"},{"i":25,"n":"第二十五条","txt":"企业应当对各岗位人员进行与其职责和工作内容相关的岗前培训和继续培训，以符合本规范要求。"},{"i":26,"n":"第二十六条","txt":"培训内容应当包括相关法律法规、药品专业知识及技能、质量管理制度、职责及岗位操作规程等。"},{"i":27,"n":"第二十七条","txt":"企业应当按照培训管理制度制定年度培训计划并开展培训，使相关人员能正确理解并履行职责。培训工作应当做好记录并建立档案。"},{"i":28,"n":"第二十八条","txt":"从事特殊管理的药品和冷藏冷冻药品的储存、运输等工作的人员，应当接受相关法律法规和专业知识培训并经考核合格后方可上岗。"},{"i":29,"n":"第二十九条","txt":"企业应当制定员工个人卫生管理制度，储存、运输等岗位人员的着装应当符合劳动保护和产品防护的要求。"},{"i":30,"n":"第三十条","txt":"质量管理、验收、养护、储存等直接接触药品岗位的人员应当进行岗前及年度健康检查，并建立健康档案。患有传染病或者其他可能污染药品的疾病的，不得从事直接接触药品的工作。身体条件不符合相应岗位特定要求的，不得从事相关工作。"},{"i":31,"n":"第三十一条","txt":"企业制定质量管理体系文件应当符合企业实际。文件包括质量管理制度、部门及岗位职责、操作规程、档案、报告、记录和凭证等。"},{"i":32,"n":"第三十二条","txt":"文件的起草、修订、审核、批准、分发、保管，以及修改、撤销、替换、销毁等应当按照文件管理操作规程进行，并保存相关记录。"},{"i":33,"n":"第三十三条","txt":"文件应当标明题目、种类、目的以及文件编号和版本号。文字应当准确、清晰、易懂。 文件应当分类存放，便于查阅。"},{"i":34,"n":"第三十四条","txt":"企业应当定期审核、修订文件，使用的文件应当为现行有效的文本，已废止或者失效的文件除留档备查外，不得在工作现场出现。"},{"i":35,"n":"第三十五条","txt":"企业应当保证各岗位获得与其工作内容相对应的必要文件，并严格按照规定开展工作。"},{"i":36,"n":"第三十六条","txt":"质量管理制度应当包括以下内容： （一）质量管理体系内审的规定； （二）质量否决权的规定； （三）质量管理文件的管理； （四）质量信息的管理； （五）供货单位、购货单位、供货单位销售人员及购货单位采购人员等资格审核的规定； （六）药品采购、收货、验收、储存、养护、销售、出库、运输的管理； （七）特殊管理的药品的规定； （八）药品有效期的管理； （九）不合格药品、药品销毁的管理； （十）药品退货的管理； （十一）药品召回的管理； （十二）质量查询的管理； （十三）质量事故、质量投诉的管理； （十四）药品不良反应报告的规定； （十五）环境卫生、人员健康的规定； （十六）质量方面的教育、培训及考核的规定； （十七）设施设备保管和维护的管理； （十八）设施设备验证和校准的管理； （十九）记录和凭证的管理； （二十）计算机系统的管理； （二十一）药品追溯的规定； （二十二）其他应当规定的内容。"},{"i":37,"n":"第三十七条","txt":"部门及岗位职责应当包括： （一）质量管理、采购、储存、销售、运输、财务和信息管理等部门职责； （二）企业负责人、质量负责人及质量管理、采购、储存、销售、运输、财务和信息管理等部门负责人的岗位职责； （三）质量管理、采购、收货、验收、储存、养护、销售、出库复核、运输、财务、信息管理等岗位职责； （四）与药品经营相关的其他岗位职责。"},{"i":38,"n":"第三十八条","txt":"企业应当制定药品采购、收货、验收、储存、养护、销售、出库复核、运输等环节及计算机系统的操作规程。"},{"i":39,"n":"第三十九条","txt":"企业应当建立药品采购、验收、养护、销售、出库复核、销后退回和购进退出、运输、储运温湿度监测、不合格药品处理等相关记录，做到真实、完整、准确、有效和可追溯。"},{"i":40,"n":"第四十条","txt":"通过计算机系统记录数据时，有关人员应当按照操作规程，通过授权及密码登录后方可进行数据的录入或者复核；数据的更改应当经质量管理部门审核并在其监督下进行，更改过程应当留有记录。"},{"i":41,"n":"第四十一条","txt":"书面记录及凭证应当及时填写，并做到字迹清晰，不得随意涂改，不得撕毁。更改记录的，应当注明理由、日期并签名，保持原有信息清晰可辨。"},{"i":42,"n":"第四十二条","txt":"记录及凭证应当至少保存5年。疫苗、特殊管理的药品的记录及凭证按相关规定保存。"},{"i":43,"n":"第四十三条","txt":"企业应当具有与其药品经营范围、经营规模相适应的经营场所和库房。"},{"i":44,"n":"第四十四条","txt":"库房的选址、设计、布局、建造、改造和维护应当符合药品储存的要求，防止药品的污染、交叉污染、混淆和差错。"},{"i":45,"n":"第四十五条","txt":"药品储存作业区、辅助作业区应当与办公区和生活区分开一定距离或者有隔离措施。"},{"i":46,"n":"第四十六条","txt":"库房的规模及条件应当满足药品的合理、安全储存，并达到以下要求，便于开展储存作业： （一）库房内外环境整洁，无污染源，库区地面硬化或者绿化； （二）库房内墙、顶光洁，地面平整，门窗结构严密； （三）库房有可靠的安全防护措施，能够对无关人员进入实行可控管理，防止药品被盗、替换或者混入假药； （四）有防止室外装卸、搬运、接收、发运等作业受异常天气影响的措施。"},{"i":47,"n":"第四十七条","txt":"库房应当配备以下设施设备： （一）药品与地面之间有效隔离的设备； （二）避光、通风、防潮、防虫、防鼠等设备； （三）有效调控温湿度及室内外空气交换的设备； （四）自动监测、记录库房温湿度的设备； （五）符合储存作业要求的照明设备； （六）用于零货拣选、拼箱发货操作及复核的作业区域和设备； （七）包装物料的存放场所； （八）验收、发货、退货的专用场所； （九）不合格药品专用存放场所； （十）经营特殊管理的药品有符合国家规定的储存设施。"},{"i":48,"n":"第四十八条","txt":"经营中药材、中药饮片的，应当有专用的库房和养护工作场所，直接收购地产中药材的应当设置中药样品室（柜）。"},{"i":49,"n":"第四十九条","txt":"储存、运输冷藏、冷冻药品的，应当配备以下设施设备： （一）与其经营规模和品种相适应的冷库，储存疫苗的应当配备两个以上独立冷库； （二）用于冷库温度自动监测、显示、记录、调控、报警的设备； （三）冷库制冷设备的备用发电机组或者双回路供电系统； （四）对有特殊低温要求的药品，应当配备符合其储存要求的设施设备； （五）冷藏车及车载冷藏箱或者保温箱等设备。"},{"i":50,"n":"第五十条","txt":"运输药品应当使用封闭式货物运输工具。"},{"i":51,"n":"第五十一条","txt":"运输冷藏、冷冻药品的冷藏车及车载冷藏箱、保温箱应当符合药品运输过程中对温度控制的要求。冷藏车具有自动调控温度、显示温度、存储和读取温度监测数据的功能；冷藏箱及保温箱具有外部显示和采集箱体内温度数据的功能。"},{"i":52,"n":"第五十二条","txt":"储存、运输设施设备的定期检查、清洁和维护应当由专人负责，并建立记录和档案。"},{"i":53,"n":"第五十三条","txt":"企业应当按照国家有关规定，对计量器具、温湿度监测设备等定期进行校准或者检定。 企业应当对冷库、储运温湿度监测系统以及冷藏运输等设施设备进行使用前验证、定期验证及停用时间超过规定时限的验证。"},{"i":54,"n":"第五十四条","txt":"企业应当根据相关验证管理制度，形成验证控制文件，包括验证方案、报告、评价、偏差处理和预防措施等。"},{"i":55,"n":"第五十五条","txt":"验证应当按照预先确定和批准的方案实施，验证报告应当经过审核和批准，验证文件应当存档。"},{"i":56,"n":"第五十六条","txt":"企业应当根据验证确定的参数及条件，正确、合理使用相关设施设备。"},{"i":57,"n":"第五十七条","txt":"企业应当建立能够符合经营全过程管理及质量控制要求的计算机系统，实现药品可追溯。"},{"i":58,"n":"第五十八条","txt":"企业计算机系统应当符合以下要求： （一）有支持系统正常运行的服务器和终端机； （二）有安全、稳定的网络环境，有固定接入互联网的方式和安全可靠的信息平台； （三）有实现部门之间、岗位之间信息传输和数据共享的局域网； （四）有药品经营业务票据生成、打印和管理功能； （五）有符合本规范要求及企业管理实际需要的应用软件和相关数据库。"},{"i":59,"n":"第五十九条","txt":"各类数据的录入、修改、保存等操作应当符合授权范围、操作规程和管理制度的要求，保证数据原始、真实、准确、安全和可追溯。"},{"i":60,"n":"第六十条","txt":"计算机系统运行中涉及企业经营和管理的数据应当采用安全、可靠的方式储存并按日备份，备份数据应当存放在安全场所，记录类数据的保存时限应当符合本规范第四十二条的要求。"},{"i":61,"n":"第六十一条","txt":"企业的采购活动应当符合以下要求： （一）确定供货单位的合法资格； （二）确定所购入药品的合法性； （三）核实供货单位销售人员的合法资格； （四）与供货单位签订质量保证协议。 采购中涉及的首营企业、首营品种，采购部门应当填写相关申请表格，经过质量管理部门和企业质量负责人的审核批准。必要时应当组织实地考察，对供货单位质量管理体系进行评价。"},{"i":62,"n":"第六十二条","txt":"对首营企业的审核，应当查验加盖其公章原印章的以下资料，确认真实、有效： （一）《药品生产许可证》或者《药品经营许可证》复印件； （二）营业执照、税务登记、组织机构代码的证件复印件，及上一年度企业年度报告公示情况； （三）《药品生产质量管理规范》认证证书或者《药品经营质量管理规范》认证证书复印件； （四）相关印章、随货同行单（票）样式； （五）开户户名、开户银行及账号。"},{"i":63,"n":"第六十三条","txt":"采购首营品种应当审核药品的合法性，索取加盖供货单位公章原印章的药品生产或者进口批准证明文件复印件并予以审核，审核无误的方可采购。 以上资料应当归入药品质量档案。"},{"i":64,"n":"第六十四条","txt":"企业应当核实、留存供货单位销售人员以下资料： （一）加盖供货单位公章原印章的销售人员身份证复印件； （二）加盖供货单位公章原印章和法定代表人印章或者签名的授权书，授权书应当载明被授权人姓名、身份证号码，以及授权销售的品种、地域、期限； （三）供货单位及供货品种相关资料。"},{"i":65,"n":"第六十五条","txt":"企业与供货单位签订的质量保证协议至少包括以下内容： （一）明确双方质量责任； （二）供货单位应当提供符合规定的资料且对其真实性、有效性负责； （三）供货单位应当按照国家规定开具发票； （四）药品质量符合药品标准等有关要求； （五）药品包装、标签、说明书符合有关规定； （六）药品运输的质量保证及责任； （七）质量保证协议的有效期限。"},{"i":66,"n":"第六十六条","txt":"采购药品时，企业应当向供货单位索取发票。发票应当列明药品的通用名称、规格、单位、数量、单价、金额等；不能全部列明的，应当附《销售货物或者提供应税劳务清单》，并加盖供货单位发票专用章原印章、注明税票号码。"},{"i":67,"n":"第六十七条","txt":"发票上的购、销单位名称及金额、品名应当与付款流向及金额、品名一致，并与财务账目内容相对应。发票按有关规定保存。"},{"i":68,"n":"第六十八条","txt":"采购药品应当建立采购记录。采购记录应当有药品的通用名称、剂型、规格、生产厂商、供货单位、数量、价格、购货日期等内容，采购中药材、中药饮片的还应当标明产地。"},{"i":69,"n":"第六十九条","txt":"发生灾情、疫情、突发事件或者临床紧急救治等特殊情况，以及其他符合国家有关规定的情形，企业可采用直调方式购销药品，将已采购的药品不入本企业仓库，直接从供货单位发送到购货单位，并建立专门的采购记录，保证有效的质量跟踪和追溯。"},{"i":70,"n":"第七十条","txt":"采购特殊管理的药品，应当严格按照国家有关规定进行。"},{"i":71,"n":"第七十一条","txt":"企业应当定期对药品采购的整体情况进行综合质量评审，建立药品质量评审和供货单位质量档案，并进行动态跟踪管理。"},{"i":72,"n":"第七十二条","txt":"企业应当按照规定的程序和要求对到货药品逐批进行收货、验收，防止不合格药品入库。"},{"i":73,"n":"第七十三条","txt":"药品到货时，收货人员应当核实运输方式是否符合要求，并对照随货同行单（票）和采购记录核对药品，做到票、账、货相符。 随货同行单（票）应当包括供货单位、生产厂商、药品的通用名称、剂型、规格、批号、数量、收货单位、收货地址、发货日期等内容，并加盖供货单位药品出库专用章原印章。"},{"i":74,"n":"第七十四条","txt":"冷藏、冷冻药品到货时，应当对其运输方式及运输过程的温度记录、运输时间等质量控制状况进行重点检查并记录。不符合温度要求的应当拒收。"},{"i":75,"n":"第七十五条","txt":"收货人员对符合收货要求的药品，应当按品种特性要求放于相应待验区域，或者设置状态标志，通知验收。冷藏、冷冻药品应当在冷库内待验。"},{"i":76,"n":"第七十六条","txt":"验收药品应当按照药品批号查验同批号的检验报告书。供货单位为批发企业的，检验报告书应当加盖其质量管理专用章原印章。检验报告书的传递和保存可以采用电子数据形式，但应当保证其合法性和有效性。"},{"i":77,"n":"第七十七条","txt":"企业应当按照验收规定，对每次到货药品进行逐批抽样验收，抽取的样品应当具有代表性： （一）同一批号的药品应当至少检查一个最小包装，但生产企业有特殊质量控制要求或者打开最小包装可能影响药品质量的，可不打开最小包装； （二）破损、污染、渗液、封条损坏等包装异常以及零货、拼箱的，应当开箱检查至最小包装； （三）外包装及封签完整的原料药、实施批签发管理的生物制品，可不开箱检查。"},{"i":78,"n":"第七十八条","txt":"验收人员应当对抽样药品的外观、包装、标签、说明书以及相关的证明文件等逐一进行检查、核对；验收结束后，应当将抽取的完好样品放回原包装箱，加封并标示。"},{"i":79,"n":"第七十九条","txt":"特殊管理的药品应当按照相关规定在专库或者专区内验收。"},{"i":80,"n":"第八十条","txt":"验收药品应当做好验收记录，包括药品的通用名称、剂型、规格、批准文号、批号、生产日期、有效期、生产厂商、供货单位、到货数量、到货日期、验收合格数量、验收结果等内容。验收人员应当在验收记录上签署姓名和验收日期。 中药材验收记录应当包括品名、产地、供货单位、到货数量、验收合格数量等内容。中药饮片验收记录应当包括品名、规格、批号、产地、生产日期、生产厂商、供货单位、到货数量、验收合格数量等内容，实施批准文号管理的中药饮片还应当记录批准文号。 验收不合格的还应当注明不合格事项及处置措施。"},{"i":81,"n":"第八十一条","txt":"企业应当建立库存记录，验收合格的药品应当及时入库登记；验收不合格的，不得入库，并由质量管理部门处理。"},{"i":82,"n":"第八十二条","txt":"企业按本规范第六十九条规定进行药品直调的，可委托购货单位进行药品验收。购货单位应当严格按照本规范的要求验收药品，并建立专门的直调药品验收记录。验收当日应当将验收记录相关信息传递给直调企业。"},{"i":83,"n":"第八十三条","txt":"企业应当根据药品的质量特性对药品进行合理储存，并符合以下要求： （一）按包装标示的温度要求储存药品，包装上没有标示具体温度的，按照《中华人民共和国药典》规定的贮藏要求进行储存； （二）储存药品相对湿度为35%-75%； （三）在人工作业的库房储存药品，按质量状态实行色标管理，合格药品为绿色，不合格药品为红色，待确定药品为黄色； （四）储存药品应当按照要求采取避光、遮光、通风、防潮、防虫、防鼠等措施； （五）搬运和堆码药品应当严格按照外包装标示要求规范操作，堆码高度符合包装图示要求，避免损坏药品包装； （六）药品按批号堆码，不同批号的药品不得混垛，垛间距不小于5厘米，与库房内墙、顶、温度调控设备及管道等设施间距不小于30厘米，与地面间距不小于10厘米； （七）药品与非药品、外用药与其他药品分开存放，中药材和中药饮片分库存放； （八）特殊管理的药品应当按照国家有关规定储存； （九）拆除外包"},{"i":84,"n":"第八十四条","txt":"养护人员应当根据库房条件、外部环境、药品质量特性等对药品进行养护，主要内容是： （一）指导和督促储存人员对药品进行合理储存与作业。 （二）检查并改善储存条件、防护措施、卫生环境。 （三）对库房温湿度进行有效监测、调控。 （四）按照养护计划对库存药品的外观、包装等质量状况进行检查，并建立养护记录；对储存条件有特殊要求的或者有效期较短的品种应当进行重点养护。 （五）发现有问题的药品应当及时在计算机系统中锁定和记录，并通知质量管理部门处理。 （六）对中药材和中药饮片应当按其特性采取有效方法进行养护并记录，所采取的养护方法不得对药品造成污染。 （七）定期汇总、分析养护信息。"},{"i":85,"n":"第八十五条","txt":"企业应当采用计算机系统对库存药品的有效期进行自动跟踪和控制，采取近效期预警及超过有效期自动锁定等措施，防止过期药品销售。"},{"i":86,"n":"第八十六条","txt":"药品因破损而导致液体、气体、粉末泄漏时，应当迅速采取安全处理措施，防止对储存环境和其他药品造成污染。"},{"i":87,"n":"第八十七条","txt":"对质量可疑的药品应当立即采取停售措施，并在计算机系统中锁定，同时报告质量管理部门确认。对存在质量问题的药品应当采取以下措施： （一）存放于标志明显的专用场所，并有效隔离，不得销售； （二）怀疑为假药的，及时报告食品药品监督管理部门； （三）属于特殊管理的药品，按照国家有关规定处理； （四）不合格药品的处理过程应当有完整的手续和记录； （五）对不合格药品应当查明并分析原因，及时采取预防措施。"},{"i":88,"n":"第八十八条","txt":"企业应当对库存药品定期盘点，做到账、货相符。"},{"i":89,"n":"第八十九条","txt":"企业应当将药品销售给合法的购货单位，并对购货单位的证明文件、采购人员及提货人员的身份证明进行核实，保证药品销售流向真实、合法。"},{"i":90,"n":"第九十条","txt":"企业应当严格审核购货单位的生产范围、经营范围或者诊疗范围，并按照相应的范围销售药品。"},{"i":91,"n":"第九十一条","txt":"企业销售药品，应当如实开具发票，做到票、账、货、款一致。"},{"i":92,"n":"第九十二条","txt":"企业应当做好药品销售记录。销售记录应当包括药品的通用名称、规格、剂型、批号、有效期、生产厂商、购货单位、销售数量、单价、金额、销售日期等内容。按照本规范第六十九条规定进行药品直调的，应当建立专门的销售记录。 中药材销售记录应当包括品名、规格、产地、购货单位、销售数量、单价、金额、销售日期等内容；中药饮片销售记录应当包括品名、规格、批号、产地、生产厂商、购货单位、销售数量、单价、金额、销售日期等内容。"},{"i":93,"n":"第九十三条","txt":"销售特殊管理的药品以及国家有专门管理要求的药品，应当严格按照国家有关规定执行。"},{"i":94,"n":"第九十四条","txt":"出库时应当对照销售记录进行复核。发现以下情况不得出库，并报告质量管理部门处理： （一）药品包装出现破损、污染、封口不牢、衬垫不实、封条损坏等问题； （二）包装内有异常响动或者液体渗漏； （三）标签脱落、字迹模糊不清或者标识内容与实物不符； （四）药品已超过有效期； （五）其他异常情况的药品。"},{"i":95,"n":"第九十五条","txt":"药品出库复核应当建立记录，包括购货单位、药品的通用名称、剂型、规格、数量、批号、有效期、生产厂商、出库日期、质量状况和复核人员等内容。"},{"i":96,"n":"第九十六条","txt":"特殊管理的药品出库应当按照有关规定进行复核。"},{"i":97,"n":"第九十七条","txt":"药品拼箱发货的代用包装箱应当有醒目的拼箱标志。"},{"i":98,"n":"第九十八条","txt":"药品出库时，应当附加盖企业药品出库专用章原印章的随货同行单（票）。 企业按照本规范第六十九条规定直调药品的，直调药品出库时，由供货单位开具两份随货同行单（票），分别发往直调企业和购货单位。随货同行单（票）的内容应当符合本规范第七十三条第二款的要求，还应当标明直调企业名称。"},{"i":99,"n":"第九十九条","txt":"冷藏、冷冻药品的装箱、装车等项作业，应当由专人负责并符合以下要求： （一）车载冷藏箱或者保温箱在使用前应当达到相应的温度要求； （二）应当在冷藏环境下完成冷藏、冷冻药品的装箱、封箱工作； （三）装车前应当检查冷藏车辆的启动、运行状态，达到规定温度后方可装车； （四）启运时应当做好运输记录，内容包括运输工具和启运时间等。"},{"i":100,"n":"第一百条","txt":"企业应当按照质量管理制度的要求，严格执行运输操作规程，并采取有效措施保证运输过程中的药品质量与安全。"},{"i":101,"n":"第一百零一条","txt":"运输药品，应当根据药品的包装、质量特性并针对车况、道路、天气等因素，选用适宜的运输工具，采取相应措施防止出现破损、污染等问题。"},{"i":102,"n":"第一百零二条","txt":"发运药品时，应当检查运输工具，发现运输条件不符合规定的，不得发运。运输药品过程中，运载工具应当保持密闭。"},{"i":103,"n":"第一百零三条","txt":"企业应当严格按照外包装标示的要求搬运、装卸药品。"},{"i":104,"n":"第一百零四条","txt":"企业应当根据药品的温度控制要求，在运输过程中采取必要的保温或者冷藏、冷冻措施。 运输过程中，药品不得直接接触冰袋、冰排等蓄冷剂，防止对药品质量造成影响。"},{"i":105,"n":"第一百零五条","txt":"在冷藏、冷冻药品运输途中，应当实时监测并记录冷藏车、冷藏箱或者保温箱内的温度数据。"},{"i":106,"n":"第一百零六条","txt":"企业应当制定冷藏、冷冻药品运输应急预案，对运输途中可能发生的设备故障、异常天气影响、交通拥堵等突发事件，能够采取相应的应对措施。"},{"i":107,"n":"第一百零七条","txt":"企业委托其他单位运输药品的，应当对承运方运输药品的质量保障能力进行审计，索取运输车辆的相关资料，符合本规范运输设施设备条件和要求的方可委托。"},{"i":108,"n":"第一百零八条","txt":"企业委托运输药品应当与承运方签订运输协议，明确药品质量责任、遵守运输操作规程和在途时限等内容。"},{"i":109,"n":"第一百零九条","txt":"企业委托运输药品应当有记录，实现运输过程的质量追溯。记录至少包括发货时间、发货地址、收货单位、收货地址、货单号、药品件数、运输方式、委托经办人、承运单位，采用车辆运输的还应当载明车牌号，并留存驾驶人员的驾驶证复印件。记录应当至少保存5年。"},{"i":110,"n":"第一百一十条","txt":"已装车的药品应当及时发运并尽快送达。委托运输的，企业应当要求并监督承运方严格履行委托运输协议，防止因在途时间过长影响药品质量。"},{"i":111,"n":"第一百一十一条","txt":"企业应当采取运输安全管理措施，防止在运输过程中发生药品盗抢、遗失、调换等事故。"},{"i":112,"n":"第一百一十二条","txt":"特殊管理的药品的运输应当符合国家有关规定。"},{"i":113,"n":"第一百一十三条","txt":"企业应当加强对退货的管理，保证退货环节药品的质量和安全，防止混入假冒药品。"},{"i":114,"n":"第一百一十四条","txt":"企业应当按照质量管理制度的要求，制定投诉管理操作规程，内容包括投诉渠道及方式、档案记录、调查与评估、处理措施、反馈和事后跟踪等。"},{"i":115,"n":"第一百一十五条","txt":"企业应当配备专职或者兼职人员负责售后投诉管理，对投诉的质量问题查明原因，采取有效措施及时处理和反馈，并做好记录，必要时应当通知供货单位及药品生产企业。"},{"i":116,"n":"第一百一十六条","txt":"企业应当及时将投诉及处理结果等信息记入档案，以便查询和跟踪。"},{"i":117,"n":"第一百一十七条","txt":"企业发现已售出药品有严重质量问题，应当立即通知购货单位停售、追回并做好记录，同时向食品药品监督管理部门报告。"},{"i":118,"n":"第一百一十八条","txt":"企业应当协助药品生产企业履行召回义务，按照召回计划的要求及时传达、反馈药品召回信息，控制和收回存在安全隐患的药品，并建立药品召回记录。"},{"i":119,"n":"第一百一十九条","txt":"企业质量管理部门应当配备专职或者兼职人员，按照国家有关规定承担药品不良反应监测和报告工作。"},{"i":120,"n":"第一百二十条","txt":"企业应当按照有关法律法规及本规范的要求制定质量管理文件，开展质量管理活动，确保药品质量。"},{"i":121,"n":"第一百二十一条","txt":"企业应当具有与其经营范围和规模相适应的经营条件，包括组织机构、人员、设施设备、质量管理文件，并按照规定设置计算机系统。"},{"i":122,"n":"第一百二十二条","txt":"企业负责人是药品质量的主要责任人，负责企业日常管理，负责提供必要的条件，保证质量管理部门和质量管理人员有效履行职责，确保企业按照本规范要求经营药品。"},{"i":123,"n":"第一百二十三条","txt":"企业应当设置质量管理部门或者配备质量管理人员，履行以下职责： （一）督促相关部门和岗位人员执行药品管理的法律法规及本规范； （二）组织制订质量管理文件，并指导、监督文件的执行； （三）负责对供货单位及其销售人员资格证明的审核； （四）负责对所采购药品合法性的审核； （五）负责药品的验收，指导并监督药品采购、储存、陈列、销售等环节的质量管理工作； （六）负责药品质量查询及质量信息管理； （七）负责药品质量投诉和质量事故的调查、处理及报告； （八）负责对不合格药品的确认及处理； （九）负责假劣药品的报告； （十）负责药品不良反应的报告； （十一）开展药品质量管理教育和培训； （十二）负责计算机系统操作权限的审核、控制及质量管理基础数据的维护； （十三）负责组织计量器具的校准及检定工作； （十四）指导并监督药学服务工作； （十五）其他应当由质量管理部门或者质量管理人员履行的职责。"},{"i":124,"n":"第一百二十四条","txt":"企业从事药品经营和质量管理工作的人员，应当符合有关法律法规及本规范规定的资格要求，不得有相关法律法规禁止从业的情形。"},{"i":125,"n":"第一百二十五条","txt":"企业法定代表人或者企业负责人应当具备执业药师资格。 企业应当按照国家有关规定配备执业药师，负责处方审核，指导合理用药。"},{"i":126,"n":"第一百二十六条","txt":"质量管理、验收、采购人员应当具有药学或者医学、生物、化学等相关专业学历或者具有药学专业技术职称。从事中药饮片质量管理、验收、采购人员应当具有中药学中专以上学历或者具有中药学专业初级以上专业技术职称。 营业员应当具有高中以上文化程度或者符合省级食品药品监督管理部门规定的条件。中药饮片调剂人员应当具有中药学中专以上学历或者具备中药调剂员资格。"},{"i":127,"n":"第一百二十七条","txt":"企业各岗位人员应当接受相关法律法规及药品专业知识与技能的岗前培训和继续培训，以符合本规范要求。"},{"i":128,"n":"第一百二十八条","txt":"企业应当按照培训管理制度制定年度培训计划并开展培训，使相关人员能正确理解并履行职责。培训工作应当做好记录并建立档案。"},{"i":129,"n":"第一百二十九条","txt":"企业应当为销售特殊管理的药品、国家有专门管理要求的药品、冷藏药品的人员接受相应培训提供条件，使其掌握相关法律法规和专业知识。"},{"i":130,"n":"第一百三十条","txt":"在营业场所内，企业工作人员应当穿着整洁、卫生的工作服。"},{"i":131,"n":"第一百三十一条","txt":"企业应当对直接接触药品岗位的人员进行岗前及年度健康检查，并建立健康档案。患有传染病或者其他可能污染药品的疾病的，不得从事直接接触药品的工作。"},{"i":132,"n":"第一百三十二条","txt":"在药品储存、陈列等区域不得存放与经营活动无关的物品及私人用品，在工作区域内不得有影响药品质量和安全的行为。"},{"i":133,"n":"第一百三十三条","txt":"企业应当按照有关法律法规及本规范规定，制定符合企业实际的质量管理文件。文件包括质量管理制度、岗位职责、操作规程、档案、记录和凭证等，并对质量管理文件定期审核、及时修订。"},{"i":134,"n":"第一百三十四条","txt":"企业应当采取措施确保各岗位人员正确理解质量管理文件的内容，保证质量管理文件有效执行。"},{"i":135,"n":"第一百三十五条","txt":"药品零售质量管理制度应当包括以下内容： （一）药品采购、验收、陈列、销售等环节的管理，设置库房的还应当包括储存、养护的管理； （二）供货单位和采购品种的审核； （三）处方药销售的管理； （四）药品拆零的管理； （五）特殊管理的药品和国家有专门管理要求的药品的管理； （六）记录和凭证的管理； （七）收集和查询质量信息的管理； （八）质量事故、质量投诉的管理； （九）中药饮片处方审核、调配、核对的管理； （十）药品有效期的管理； （十一）不合格药品、药品销毁的管理； （十二）环境卫生、人员健康的规定； （十三）提供用药咨询、指导合理用药等药学服务的管理； （十四）人员培训及考核的规定； （十五）药品不良反应报告的规定； （十六）计算机系统的管理； （十七）药品追溯的规定； （十八）其他应当规定的内容。"},{"i":136,"n":"第一百三十六条","txt":"企业应当明确企业负责人、质量管理、采购、验收、营业员以及处方审核、调配等岗位的职责，设置库房的还应当包括储存、养护等岗位职责。"},{"i":137,"n":"第一百三十七条","txt":"质量管理岗位、处方审核岗位的职责不得由其他岗位人员代为履行。"},{"i":138,"n":"第一百三十八条","txt":"药品零售操作规程应当包括： （一）药品采购、验收、销售； （二）处方审核、调配、核对； （三）中药饮片处方审核、调配、核对； （四）药品拆零销售； （五）特殊管理的药品和国家有专门管理要求的药品的销售； （六）营业场所药品陈列及检查； （七）营业场所冷藏药品的存放； （八）计算机系统的操作和管理； （九）设置库房的还应当包括储存和养护的操作规程。"},{"i":139,"n":"第一百三十九条","txt":"企业应当建立药品采购、验收、销售、陈列检查、温湿度监测、不合格药品处理等相关记录，做到真实、完整、准确、有效和可追溯。"},{"i":140,"n":"第一百四十条","txt":"记录及相关凭证应当至少保存5年。特殊管理的药品的记录及凭证按相关规定保存。"},{"i":141,"n":"第一百四十一条","txt":"通过计算机系统记录数据时，相关岗位人员应当按照操作规程，通过授权及密码登录计算机系统，进行数据的录入，保证数据原始、真实、准确、安全和可追溯。"},{"i":142,"n":"第一百四十二条","txt":"电子记录数据应当以安全、可靠方式定期备份。"},{"i":143,"n":"第一百四十三条","txt":"企业的营业场所应当与其药品经营范围、经营规模相适应，并与药品储存、办公、生活辅助及其他区域分开。"},{"i":144,"n":"第一百四十四条","txt":"营业场所应当具有相应设施或者采取其他有效措施，避免药品受室外环境的影响，并做到宽敞、明亮、整洁、卫生。"},{"i":145,"n":"第一百四十五条","txt":"营业场所应当有以下营业设备： （一）货架和柜台； （二）监测、调控温度的设备； （三）经营中药饮片的，有存放饮片和处方调配的设备； （四）经营冷藏药品的，有专用冷藏设备； （五）经营第二类精神药品、毒性中药品种和罂粟壳的，有符合安全规定的专用存放设备； （六）药品拆零销售所需的调配工具、包装用品。"},{"i":146,"n":"第一百四十六条","txt":"企业应当建立能够符合经营和质量管理要求的计算机系统，并满足药品追溯的要求。"},{"i":147,"n":"第一百四十七条","txt":"企业设置库房的，应当做到库房内墙、顶光洁，地面平整，门窗结构严密；有可靠的安全防护、防盗等措施。"},{"i":148,"n":"第一百四十八条","txt":"仓库应当有以下设施设备： （一）药品与地面之间有效隔离的设备； （二）避光、通风、防潮、防虫、防鼠等设备； （三）有效监测和调控温湿度的设备； （四）符合储存作业要求的照明设备； （五）验收专用场所； （六）不合格药品专用存放场所； （七）经营冷藏药品的，有与其经营品种及经营规模相适应的专用设备。"},{"i":149,"n":"第一百四十九条","txt":"经营特殊管理的药品应当有符合国家规定的储存设施。"},{"i":150,"n":"第一百五十条","txt":"储存中药饮片应当设立专用库房。"},{"i":151,"n":"第一百五十一条","txt":"企业应当按照国家有关规定，对计量器具、温湿度监测设备等定期进行校准或者检定。"},{"i":152,"n":"第一百五十二条","txt":"企业采购药品，应当符合本规范第二章第八节的相关规定。"},{"i":153,"n":"第一百五十三条","txt":"药品到货时，收货人员应当按采购记录，对照供货单位的随货同行单（票）核实药品实物，做到票、账、货相符。"},{"i":154,"n":"第一百五十四条","txt":"企业应当按规定的程序和要求对到货药品逐批进行验收，并按照本规范第八十条规定做好验收记录。 验收抽取的样品应当具有代表性。"},{"i":155,"n":"第一百五十五条","txt":"冷藏药品到货时，应当按照本规范第七十四条规定进行检查。"},{"i":156,"n":"第一百五十六条","txt":"验收药品应当按照本规范第七十六条规定查验药品检验报告书。"},{"i":157,"n":"第一百五十七条","txt":"特殊管理的药品应当按照相关规定进行验收。"},{"i":158,"n":"第一百五十八条","txt":"验收合格的药品应当及时入库或者上架，验收不合格的，不得入库或者上架，并报告质量管理人员处理。"},{"i":159,"n":"第一百五十九条","txt":"企业应当对营业场所温度进行监测和调控，以使营业场所的温度符合常温要求。"},{"i":160,"n":"第一百六十条","txt":"企业应当定期进行卫生检查，保持环境整洁。存放、陈列药品的设备应当保持清洁卫生，不得放置与销售活动无关的物品，并采取防虫、防鼠等措施，防止污染药品。"},{"i":161,"n":"第一百六十一条","txt":"药品的陈列应当符合以下要求： （一）按剂型、用途以及储存要求分类陈列，并设置醒目标志，类别标签字迹清晰、放置准确。 （二）药品放置于货架（柜），摆放整齐有序，避免阳光直射。 （三）处方药、非处方药分区陈列，并有处方药、非处方药专用标识。 （四）处方药不得采用开架自选的方式陈列和销售。 （五）外用药与其他药品分开摆放。 （六）拆零销售的药品集中存放于拆零专柜或者专区。 （七）第二类精神药品、毒性中药品种和罂粟壳不得陈列。 （八）冷藏药品放置在冷藏设备中，按规定对温度进行监测和记录，并保证存放温度符合要求。 （九）中药饮片柜斗谱的书写应当正名正字；装斗前应当复核，防止错斗、串斗；应当定期清斗，防止饮片生虫、发霉、变质；不同批号的饮片装斗前应当清斗并记录。 （十）经营非药品应当设置专区，与药品区域明显隔离，并有醒目标志。"},{"i":162,"n":"第一百六十二条","txt":"企业应当定期对陈列、存放的药品进行检查，重点检查拆零药品和易变质、近效期、摆放时间较长的药品以及中药饮片。发现有质量疑问的药品应当及时撤柜，停止销售，由质量管理人员确认和处理，并保留相关记录。"},{"i":163,"n":"第一百六十三条","txt":"企业应当对药品的有效期进行跟踪管理，防止近效期药品售出后可能发生的过期使用。"},{"i":164,"n":"第一百六十四条","txt":"企业设置库房的，库房的药品储存与养护管理应当符合本规范第二章第十节的相关规定。"},{"i":165,"n":"第一百六十五条","txt":"企业应当在营业场所的显著位置悬挂《药品经营许可证》、营业执照、执业药师注册证等。"},{"i":166,"n":"第一百六十六条","txt":"营业人员应当佩戴有照片、姓名、岗位等内容的工作牌，是执业药师和药学技术人员的，工作牌还应当标明执业资格或者药学专业技术职称。在岗执业的执业药师应当挂牌明示。"},{"i":167,"n":"第一百六十七条","txt":"销售药品应当符合以下要求： （一）处方经执业药师审核后方可调配；对处方所列药品不得擅自更改或者代用，对有配伍禁忌或者超剂量的处方，应当拒绝调配，但经处方医师更正或者重新签字确认的，可以调配；调配处方后经过核对方可销售。 （二）处方审核、调配、核对人员应当在处方上签字或者盖章，并按照有关规定保存处方或者其复印件。 （三）销售近效期药品应当向顾客告知有效期。 （四）销售中药饮片做到计量准确，并告知煎服方法及注意事项；提供中药饮片代煎服务，应当符合国家有关规定。"},{"i":168,"n":"第一百六十八条","txt":"企业销售药品应当开具销售凭证，内容包括药品名称、生产厂商、数量、价格、批号、规格等，并做好销售记录。"},{"i":169,"n":"第一百六十九条","txt":"药品拆零销售应当符合以下要求： （一）负责拆零销售的人员经过专门培训； （二）拆零的工作台及工具保持清洁、卫生，防止交叉污染； （三）做好拆零销售记录，内容包括拆零起始日期、药品的通用名称、规格、批号、生产厂商、有效期、销售数量、销售日期、分拆及复核人员等； （四）拆零销售应当使用洁净、卫生的包装，包装上注明药品名称、规格、数量、用法、用量、批号、有效期以及药店名称等内容； （五）提供药品说明书原件或者复印件； （六）拆零销售期间，保留原包装和说明书。"},{"i":170,"n":"第一百七十条","txt":"销售特殊管理的药品和国家有专门管理要求的药品，应当严格执行国家有关规定。"},{"i":171,"n":"第一百七十一条","txt":"药品广告宣传应当严格执行国家有关广告管理的规定。"},{"i":172,"n":"第一百七十二条","txt":"非本企业在职人员不得在营业场所内从事药品销售相关活动。"},{"i":173,"n":"第一百七十三条","txt":"除药品质量原因外，药品一经售出，不得退换。"},{"i":174,"n":"第一百七十四条","txt":"企业应当在营业场所公布食品药品监督管理部门的监督电话，设置顾客意见簿，及时处理顾客对药品质量的投诉。"},{"i":175,"n":"第一百七十五条","txt":"企业应当按照国家有关药品不良反应报告制度的规定，收集、报告药品不良反应信息。"},{"i":176,"n":"第一百七十六条","txt":"企业发现已售出药品有严重质量问题，应当及时采取措施追回药品并做好记录，同时向食品药品监督管理部门报告。"},{"i":177,"n":"第一百七十七条","txt":"企业应当协助药品生产企业履行召回义务，控制和收回存在安全隐患的药品，并建立药品召回记录。"},{"i":178,"n":"第一百七十八条","txt":"本规范下列术语的含义是： （一）在职：与企业确定劳动关系的在册人员。 （二）在岗：相关岗位人员在工作时间内在规定的岗位履行职责。 （三）首营企业：采购药品时，与本企业首次发生供需关系的药品生产或者经营企业。 （四）首营品种：本企业首次采购的药品。 （五）原印章：企业在购销活动中，为证明企业身份在相关文件或者凭证上加盖的企业公章、发票专用章、质量管理专用章、药品出库专用章的原始印记，不能是印刷、影印、复印等复制后的印记。 （六）待验：对到货、销后退回的药品采用有效的方式进行隔离或者区分，在入库前等待质量验收的状态。 （七）零货：拆除了用于运输、储藏包装的药品。 （八）拼箱发货：将零货药品集中拼装至同一包装箱内发货的方式。 （九）拆零销售：将最小包装拆分销售的方式。 （十）国家有专门管理要求的药品：国家对蛋白同化制剂、肽类激素、含特殊药品复方制剂等品种实施特殊监管措施的药品。"},{"i":179,"n":"第一百七十九条","txt":"药品零售连锁企业总部的管理应当符合本规范药品批发企业相关规定，门店的管理应当符合本规范药品零售企业相关规定。"},{"i":180,"n":"第一百八十条","txt":"本规范为药品经营质量管理的基本要求。对企业信息化管理、药品储运温湿度自动监测、药品验收管理、药品冷链物流管理、零售连锁管理等具体要求，由国家食品药品监督管理总局以附录方式另行制定。"},{"i":181,"n":"第一百八十一条","txt":"麻醉药品、精神药品、药品类易制毒化学品的追溯应当符合国家有关规定。"},{"i":182,"n":"第一百八十二条","txt":"医疗机构药房和计划生育技术服务机构的药品采购、储存、养护等质量管理规范由国家食品药品监督管理总局商相关主管部门另行制定。 互联网销售药品的质量管理规定由国家食品药品监督管理总局另行制定。"},{"i":183,"n":"第一百八十三条","txt":"药品经营企业违反本规范的，由食品药品监督管理部门按照《中华人民共和国药品管理法》第七十八条的规定给予处罚。"},{"i":184,"n":"第一百八十四条","txt":"本规范自发布之日起施行，卫生部2013年6月1日施行的《药品经营质量管理规范》（中华人民共和国卫生部令第90号）同时废止。"}],"zhuzuoquanxingzhengchufashishibanfa":[{"i":1,"n":"第一条","txt":"为规范著作权行政管理部门的行政处罚行为，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》（以下称行政处罚法）、《中华人民共和国著作权法》（以下称著作权法）和其他有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国家版权局以及地方人民政府享有著作权行政执法权的有关部门（以下称著作权行政管理部门），在法定职权范围内就本办法列举的违法行为实施行政处罚。法律、法规另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"本办法所称的违法行为是指： （一）著作权法第四十七条列举的侵权行为，同时损害公共利益的； （二）《计算机软件保护条例》第二十四条列举的侵权行为，同时损害公共利益的； （三）《信息网络传播权保护条例》第十八条列举的侵权行为，同时损害公共利益的；第十九条、第二十五条列举的侵权行为； （四）《著作权集体管理条例》第四十一条、第四十四条规定的应予行政处罚的行为； （五）其他有关著作权法律、法规、规章规定的应给予行政处罚的违法行为。"},{"i":4,"n":"第四条","txt":"对本办法列举的违法行为，著作权行政管理部门可以依法责令停止侵权行为，并给予下列行政处罚： （一）警告； （二）罚款； （三）没收违法所得； （四）没收侵权制品； （五）没收安装存储侵权制品的设备； （六）没收主要用于制作侵权制品的材料、工具、设备等； （七）法律、法规、规章规定的其他行政处罚。"},{"i":5,"n":"第五条","txt":"本办法列举的违法行为，由侵权行为实施地、侵权结果发生地、侵权制品储藏地或者依法查封扣押地的著作权行政管理部门负责查处。法律、行政法规另有规定的除外。 侵犯信息网络传播权的违法行为由侵权人住所地、实施侵权行为的网络服务器等设备所在地或侵权网站备案登记地的著作权行政管理部门负责查处。"},{"i":6,"n":"第六条","txt":"国家版权局可以查处在全国有重大影响的违法行为，以及认为应当由其查处的其他违法行为。地方著作权行政管理部门负责查处本辖区发生的违法行为。"},{"i":7,"n":"第七条","txt":"两个以上地方著作权行政管理部门对同一违法行为均有管辖权时，由先立案的著作权行政管理部门负责查处该违法行为。 地方著作权行政管理部门因管辖权发生争议或者管辖不明时，由争议双方协商解决；协商不成的，报请共同的上一级著作权行政管理部门指定管辖；其共同的上一级著作权行政管理部门也可以直接指定管辖。 上级著作权行政管理部门在必要时，可以处理下级著作权行政管理部门管辖的有重大影响的案件，也可以将自己管辖的案件交由下级著作权行政管理部门处理；下级著作权行政管理部门认为其管辖的案件案情重大、复杂，需要由上级著作权行政管理部门处理的，可以报请上一级著作权行政管理部门处理。"},{"i":8,"n":"第八条","txt":"著作权行政管理部门发现查处的违法行为，根据我国刑法规定涉嫌构成犯罪的，应当由该著作权行政管理部门依照国务院《行政执法机关移送涉嫌犯罪案件的规定》将案件移送司法部门处理。"},{"i":9,"n":"第九条","txt":"著作权行政管理部门对违法行为予以行政处罚的时效为两年，从违法行为发生之日起计算。违法行为有连续或者继续状态的，从行为终了之日起计算。侵权制品仍在发行或仍在向公众进行传播的，视为违法行为仍在继续。 违法行为在两年内未被发现的，不再给予行政处罚。法律另有规定的除外。"},{"i":10,"n":"第十条","txt":"除行政处罚法规定适用简易程序的情况外，著作权行政处罚适用行政处罚法规定的一般程序。"},{"i":11,"n":"第十一条","txt":"著作权行政管理部门适用一般程序查处违法行为，应当立案。 对本办法列举的违法行为，著作权行政管理部门可以自行决定立案查处，或者根据有关部门移送的材料决定立案查处，也可以根据被侵权人、利害关系人或者其他知情人的投诉或者举报决定立案查处。"},{"i":12,"n":"第十二条","txt":"投诉人就本办法列举的违法行为申请立案查处的，应当提交申请书、权利证明、被侵权作品（或者制品）以及其他证据。 申请书应当说明当事人的姓名（或者名称）、地址以及申请查处所根据的主要事实、理由。 投诉人委托代理人代为申请的，应当由代理人出示委托书。"},{"i":13,"n":"第十三条","txt":"著作权行政管理部门应当在收到所有投诉材料之日起十五日内，决定是否受理并通知投诉人。不予受理的，应当书面告知理由。"},{"i":14,"n":"第十四条","txt":"立案时应当填写立案审批表，同时附上相关材料，包括投诉或者举报材料、上级著作权行政管理部门交办或者有关部门移送案件的有关材料、执法人员的检查报告等，由本部门负责人批准，指定两名以上办案人员负责调查处理。 办案人员与案件有利害关系的，应当自行回避；没有回避的，当事人可以申请其回避。办案人员的回避，由本部门负责人批准。负责人的回避，由本级人民政府批准。"},{"i":15,"n":"第十五条","txt":"执法人员在执法过程中，发现违法行为正在实施，情况紧急来不及立案的，可以采取下列措施： （一）对违法行为予以制止或者纠正； （二）对涉嫌侵权制品、安装存储涉嫌侵权制品的设备和主要用于违法行为的材料、工具、设备等依法先行登记保存； （三）收集、调取其他有关证据。 执法人员应当及时将有关情况和材料报所在著作权行政管理部门，并于发现情况之日起七日内办理立案手续。"},{"i":16,"n":"第十六条","txt":"立案后，办案人员应当及时进行调查，并要求法定举证责任人在著作权行政管理部门指定的期限内举证。 办案人员取证时可以采取下列手段收集、调取有关证据： （一）查阅、复制与涉嫌违法行为有关的文件档案、账簿和其他书面材料； （二）对涉嫌侵权制品进行抽样取证； （三）对涉嫌侵权制品、安装存储涉嫌侵权制品的设备、涉嫌侵权的网站网页、涉嫌侵权的网站服务器和主要用于违法行为的材料、工具、设备等依法先行登记保存。"},{"i":17,"n":"第十七条","txt":"办案人员在执法中应当向当事人或者有关人员出示由国家版权局或者地方人民政府制发的行政执法证件。"},{"i":18,"n":"第十八条","txt":"办案时收集的证据包括： （一）书证； （二）物证； （三）证人证言； （四）视听资料； （五）当事人陈述； （六）鉴定结论； （七）检查、勘验笔录。"},{"i":19,"n":"第十九条","txt":"当事人提供的涉及著作权的底稿、原件、合法出版物、作品登记证书、著作权合同登记证书、认证机构出具的证明、取得权利的合同，以及当事人自行或者委托他人以订购、现场交易等方式购买侵权复制品而取得的实物、发票等，可以作为证据。"},{"i":20,"n":"第二十条","txt":"办案人员抽样取证、先行登记保存有关证据，应当有当事人在场。对有关物品应当当场制作清单一式两份，由办案人员和当事人签名、盖章后，分别交由当事人和办案人员所在著作权行政管理部门保存。当事人不在场或者拒绝签名、盖章的，由现场两名以上办案人员注明情况。"},{"i":21,"n":"第二十一条","txt":"办案人员先行登记保存有关证据，应当经本部门负责人批准，并向当事人交付证据先行登记保存通知书。当事人或者有关人员在证据保存期间不得转移、损毁有关证据。 先行登记保存的证据，应当加封著作权行政管理部门先行登记保存封条，由当事人就地保存。先行登记保存的证据确需移至他处的，可以移至适当的场所保存。情况紧急来不及办理本条规定的手续时，办案人员可以先行采取措施，事后及时补办手续。"},{"i":22,"n":"第二十二条","txt":"对先行登记保存的证据，应当在交付证据先行登记保存通知书后七日内作出下列处理决定： （一）需要鉴定的，送交鉴定； （二）违法事实成立，应当予以没收的，依照法定程序予以没收； （三）应当移送有关部门处理的，将案件连同证据移送有关部门处理； （四）违法事实不成立，或者依法不应予以没收的，解除登记保存措施； （五）其他有关法定措施。"},{"i":23,"n":"第二十三条","txt":"著作权行政管理部门在查处案件过程中，委托其他著作权行政管理部门代为调查的，须出具委托书。受委托的著作权行政管理部门应当积极予以协助。"},{"i":24,"n":"第二十四条","txt":"对查处案件中的专业性问题，著作权行政管理部门可以委托专门机构或者聘请专业人员进行鉴定。"},{"i":25,"n":"第二十五条","txt":"调查终结后，办案人员应当提交案件调查报告，说明有关行为是否违法，提出处理意见及有关事实、理由和依据，并附上全部证据材料。"},{"i":26,"n":"第二十六条","txt":"著作权行政管理部门拟作出行政处罚决定的，应当由本部门负责人签发行政处罚事先告知书，告知当事人拟作出行政处罚决定的事实、理由和依据，并告知当事人依法享有的陈述权、申辩权和其他权利。 行政处罚事先告知书应当由著作权行政管理部门直接送达当事人，当事人应当在送达回执上签名、盖章。当事人拒绝签收的，由送达人员注明情况，把送达文书留在受送达人住所，并报告本部门负责人。著作权行政管理部门也可以采取邮寄送达方式告知当事人。无法找到当事人时，可以以公告形式告知。"},{"i":27,"n":"第二十七条","txt":"当事人要求陈述、申辩的，应当在被告知后七日内，或者自发布公告之日起三十日内，向著作权行政管理部门提出陈述、申辩意见以及相应的事实、理由和证据。当事人在此期间未行使陈述权、申辩权的，视为放弃权利。 采取直接送达方式告知的，以当事人签收之日为被告知日期；采取邮寄送达方式告知的，以回执上注明的收件日期为被告知日期。"},{"i":28,"n":"第二十八条","txt":"办案人员应当充分听取当事人的陈述、申辩意见，对当事人提出的事实、理由和证据进行复核，并提交复核报告。 著作权行政管理部门不得因当事人申辩加重处罚。"},{"i":29,"n":"第二十九条","txt":"著作权行政管理部门负责人应当对案件调查报告及复核报告进行审查，并根据审查结果分别作出下列处理决定： （一）确属应当予以行政处罚的违法行为的，根据侵权人的过错程度、侵权时间长短、侵权范围大小及损害后果等情节，予以行政处罚； （二）违法行为轻微并及时纠正，没有造成危害后果的，不予行政处罚； （三）违法事实不成立的，不予行政处罚； （四）违法行为涉嫌构成犯罪的，移送司法部门处理。 对情节复杂或者重大的违法行为给予较重的行政处罚，由著作权行政管理部门负责人集体讨论决定。"},{"i":30,"n":"第三十条","txt":"著作权行政管理部门作出罚款决定时，罚款数额应当依照《中华人民共和国著作权法实施条例》第三十六条、《计算机软件保护条例》第二十四条的规定和《信息网络传播权保护条例》第十八条、第十九条的规定确定。"},{"i":31,"n":"第三十一条","txt":"违法行为情节严重的，著作权行政管理部门可以没收主要用于制作侵权制品的材料、工具、设备等。 具有下列情形之一的，属于前款所称“情节严重”： （一）违法所得数额（即获利数额）二千五百元以上的； （二）非法经营数额在一万五千元以上的； （三）经营侵权制品在二百五十册（张或份）以上的； （四）因侵犯著作权曾经被追究法律责任，又侵犯著作权的； （五）造成其他重大影响或者严重后果的。"},{"i":32,"n":"第三十二条","txt":"对当事人的同一违法行为，其他行政机关已经予以罚款的，著作权行政管理部门不得再予罚款，但仍可以视具体情况予以本办法第四条所规定的其他种类的行政处罚。"},{"i":33,"n":"第三十三条","txt":"著作权行政管理部门作出较大数额罚款决定或者法律、行政法规规定应当听证的其他行政处罚决定前，应当告知当事人有要求举行听证的权利。 前款所称“较大数额罚款”，是指对个人处以两万元以上、对单位处以十万元以上的罚款。地方性法规、规章对听证要求另有规定的，依照地方性法规、规章办理。"},{"i":34,"n":"第三十四条","txt":"当事人要求听证的，著作权行政管理部门应当依照行政处罚法第四十二条规定的程序组织听证。当事人不承担组织听证的费用。"},{"i":35,"n":"第三十五条","txt":"著作权行政管理部门决定予以行政处罚的，应当制作行政处罚决定书。 著作权行政管理部门认为违法行为轻微，决定不予行政处罚的，应当制作不予行政处罚通知书，说明不予行政处罚的事实、理由和依据，并送达当事人；违法事实不成立的，应当制作调查结果通知书，并送达当事人。 著作权行政管理部门决定移送司法部门处理的案件，应当制作涉嫌犯罪案件移送书，并连同有关材料和证据及时移送有管辖权的司法部门。"},{"i":36,"n":"第三十六条","txt":"行政处罚决定书应当由著作权行政管理部门在宣告后当场交付当事人。当事人不在场的，应当在七日内送达当事人。"},{"i":37,"n":"第三十七条","txt":"当事人对国家版权局的行政处罚不服的，可以向国家版权局申请行政复议；当事人对地方著作权行政管理部门的行政处罚不服的，可以向该部门的本级人民政府或者其上一级著作权行政管理部门申请行政复议。 当事人对行政处罚或者行政复议决定不服的，可以依法提起行政诉讼。"},{"i":38,"n":"第三十八条","txt":"当事人收到行政处罚决定书后，应当在行政处罚决定书规定的期限内予以履行。 当事人申请行政复议或者提起行政诉讼的，行政处罚不停止执行。法律另有规定的除外。"},{"i":39,"n":"第三十九条","txt":"没收的侵权制品应当销毁，或者经被侵权人同意后以其他适当方式处理。 销毁侵权制品时，著作权行政管理部门应当指派两名以上执法人员监督销毁过程，核查销毁结果，并制作销毁记录。 对没收的主要用于制作侵权制品的材料、工具、设备等，著作权行政管理部门应当依法公开拍卖或者依照国家有关规定处理。"},{"i":40,"n":"第四十条","txt":"上级著作权行政管理部门作出的行政处罚决定，可以委托下级著作权行政管理部门代为执行。代为执行的下级著作权行政管理部门，应当将执行结果报告该上级著作权行政管理部门。"},{"i":41,"n":"第四十一条","txt":"本办法所称的侵权制品包括侵权复制品和假冒他人署名的作品。"},{"i":42,"n":"第四十二条","txt":"著作权行政管理部门应当按照国家统计法规建立著作权行政处罚统计制度，每年向上一级著作权行政管理部门提交著作权行政处罚统计报告。"},{"i":43,"n":"第四十三条","txt":"行政处罚决定或者复议决定执行完毕后，著作权行政管理部门应当及时将案件材料立卷归档。 立卷归档的材料主要包括：行政处罚决定书、立案审批表、案件调查报告、复核报告、复议决定书、听证笔录、听证报告、证据材料、财物处理单据以及其他有关材料。"},{"i":44,"n":"第四十四条","txt":"本办法涉及的有关法律文书，应当参照国家版权局确定的有关文书格式制作。"},{"i":45,"n":"第四十五条","txt":"本办法自2009年6月15日起施行。国家版权局2003年9月1日发布的《著作权行政处罚实施办法》同时废止，本办法施行前发布的其他有关规定与本办法相抵触的，依照本办法执行。"}],"zhuzuoquanzhiquandengjibanfa":[{"i":1,"n":"第一条","txt":"为规范著作权出质行为，保护债权人合法权益，维护著作权交易秩序，根据《中华人民共和国物权法》、《中华人民共和国担保法》和《中华人民共和国著作权法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家版权局负责著作权质权登记工作。"},{"i":3,"n":"第三条","txt":"《中华人民共和国著作权法》规定的著作权以及与著作权有关权利（以下统称“著作权”）中的财产权可以出质。 以共有的著作权出质的，除另有约定外，应当取得全体共有人的同意。"},{"i":4,"n":"第四条","txt":"以著作权出质的，出质人和质权人应当订立书面质权合同，并由双方共同向登记机构办理著作权质权登记。 出质人和质权人可以自行办理，也可以委托代理人办理。"},{"i":5,"n":"第五条","txt":"著作权质权的设立、变更、转让和消灭，自记载于《著作权质权登记簿》时发生效力。"},{"i":6,"n":"第六条","txt":"申请著作权质权登记的，应提交下列文件： （一）著作权质权登记申请表； （二）出质人和质权人的身份证明； （三）主合同和著作权质权合同； （四）委托代理人办理的，提交委托书和受托人的身份证明； （五）以共有的著作权出质的，提交共有人同意出质的书面文件； （六）出质前授权他人使用的，提交授权合同； （七）出质的著作权经过价值评估的、质权人要求价值评估的或相关法律法规要求价值评估的，提交有效的价值评估报告； （八）其他需要提供的材料。 提交的文件是外文的，需同时附送中文译本。"},{"i":7,"n":"第七条","txt":"著作权质权合同一般包括以下内容： （一）出质人和质权人的基本信息； （二）被担保债权的种类和数额； （三）债务人履行债务的期限； （四）出质著作权的内容和保护期； （五）质权担保的范围和期限； （六）当事人约定的其他事项。"},{"i":8,"n":"第八条","txt":"申请人提交材料齐全的，登记机构应当予以受理。提交的材料不齐全的，登记机构不予受理。"},{"i":9,"n":"第九条","txt":"经审查符合要求的，登记机构应当自受理之日起10日内予以登记，并向出质人和质权人发放《著作权质权登记证书》。"},{"i":10,"n":"第十条","txt":"经审查不符合要求的，登记机构应当自受理之日起10日内通知申请人补正。补正通知书应载明补正事项和合理的补正期限。无正当理由逾期不补正的，视为撤回申请。"},{"i":11,"n":"第十一条","txt":"《著作权质权登记证书》的内容包括： （一）出质人和质权人的基本信息； （二）出质著作权的基本信息； （三）著作权质权登记号； （四）登记日期。 《著作权质权登记证书》应当标明：著作权质权自登记之日起设立。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，登记机构不予登记： （一）出质人不是著作权人的； （二）合同违反法律法规强制性规定的； （三）出质著作权的保护期届满的； （四）债务人履行债务的期限超过著作权保护期的； （五）出质著作权存在权属争议的； （六）其他不符合出质条件的。"},{"i":13,"n":"第十三条","txt":"登记机构办理著作权质权登记前，申请人可以撤回登记申请。"},{"i":14,"n":"第十四条","txt":"著作权出质期间，未经质权人同意，出质人不得转让或者许可他人使用已经出质的权利。 出质人转让或者许可他人使用出质的权利所得的价款，应当向质权人提前清偿债务或者提存。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，登记机构应当撤销质权登记： （一）登记后发现有第十二条所列情形的； （二）根据司法机关、仲裁机关或行政管理机关作出的影响质权效力的生效裁决或行政处罚决定书应当撤销的； （三）著作权质权合同无效或者被撤销的； （四）申请人提供虚假文件或者以其他手段骗取著作权质权登记的； （五）其他应当撤销的。"},{"i":16,"n":"第十六条","txt":"著作权出质期间，申请人的基本信息、著作权的基本信息、担保的债权种类及数额、或者担保的范围等事项发生变更的，申请人持变更协议、原《著作权质权登记证书》和其他相关材料向登记机构申请变更登记。"},{"i":17,"n":"第十七条","txt":"申请变更登记的，登记机构自受理之日起10日内完成审查。经审查符合要求的，对变更事项予以登记。 变更事项涉及证书内容变更的，应交回原登记证书，由登记机构发放新的证书。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，申请人应当申请注销质权登记： （一）出质人和质权人协商一致同意注销的； （二）主合同履行完毕的； （三）质权实现的； （四）质权人放弃质权的； （五）其他导致质权消灭的。"},{"i":19,"n":"第十九条","txt":"申请注销质权登记的，应当提交注销登记申请书、注销登记证明、申请人身份证明等材料，并交回原《著作权质权登记证书》。 登记机构应当自受理之日起10日内办理完毕，并发放注销登记通知书。"},{"i":20,"n":"第二十条","txt":"登记机构应当设立《著作权质权登记簿》，记载著作权质权登记的相关信息，供社会公众查询。 《著作权质权登记证书》的内容应当与《著作权质权登记簿》的内容一致。记载不一致的，除有证据证明《著作权质权登记簿》确有错误外，以《著作权质权登记簿》为准。"},{"i":21,"n":"第二十一条","txt":"《著作权质权登记簿》应当包括以下内容： （一）出质人和质权人的基本信息； （二）著作权质权合同的主要内容； （三）著作权质权登记号； （四）登记日期； （五）登记撤销情况； （六）登记变更情况； （七）登记注销情况； （八）其他需要记载的内容。"},{"i":22,"n":"第二十二条","txt":"《著作权质权登记证书》灭失或者毁损的，可以向登记机构申请补发或换发。登记机构应自收到申请之日起5日内予以补发或换发。"},{"i":23,"n":"第二十三条","txt":"登记机构应当通过国家版权局官方网站公布著作权质权登记的基本信息。"},{"i":24,"n":"第二十四条","txt":"本办法由国家版权局负责解释。"},{"i":25,"n":"第二十五条","txt":"本办法自2011年1月1日起施行。1996年9月23日国家版权局发布的《著作权质押合同登记办法》同时废止。"}],"cangchuanfojiaoxuexianshouyubanfa":[{"i":1,"n":"第一条","txt":"为了规范藏传佛教学衔授予工作，促进藏传佛教人才培养，根据《宗教院校学位授予办法（试行）》以及国家有关法律法规，结合藏传佛教实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称藏传佛教院校，是指依据《宗教事务条例》、《宗教院校设立办法》设立，由中国佛教协会或省、自治区佛教团体举办，培养藏传佛教教职人员和专门人才的全日制高等院校。"},{"i":3,"n":"第三条","txt":"本办法所称藏传佛教学衔，是指藏传佛教院校学生在校学习期满，成绩合格，或寺庙学经班学员达到同等学力，经藏传佛教院校学衔评定委员会对其政治思想表现、宗教操守、课程考试和辩经考试、论文答辩等情况进行全面审查合格后，获取的学衔。"},{"i":4,"n":"第四条","txt":"中国佛教协会成立藏传佛教学衔工作指导委员会，负责指导藏传佛教学衔授予的相关工作。藏传佛教学衔工作指导委员会成员由中国佛教协会选聘，报国家宗教事务局备案后，由中国佛教协会颁发聘书。 藏传佛教学衔工作指导委员会日常工作由中国藏语系高级佛学院负责。"},{"i":5,"n":"第五条","txt":"国家宗教事务局和省、自治区人民政府宗教事务部门对藏传佛教学衔授予工作进行监督指导。"},{"i":6,"n":"第六条","txt":"藏传佛教学衔分初、中、高三级，分别为禅然巴、智然巴、拓然巴。"},{"i":7,"n":"第七条","txt":"禅然巴、智然巴学衔由省、自治区佛教团体举办的藏传佛教院校授予。拓然巴学衔由中国藏语系高级佛学院授予。 中国藏语系高级佛学院可以根据需要开办中级学衔班，授予智然巴学衔。"},{"i":8,"n":"第八条","txt":"藏传佛教院校设立学衔评定委员会，负责学衔评定授予工作。"},{"i":9,"n":"第九条","txt":"藏传佛教院校学衔评定委员会成员，经举办该院校的省、自治区佛教团体审定，分别报省、自治区人民政府宗教事务部门和藏传佛教学衔工作指导委员会备案。 中国藏语系高级佛学院学衔评定委员会成员，经中国佛教协会审定后，报国家宗教事务局备案。 藏传佛教院校学衔评定委员会成员，由该藏传佛教院校院长签发聘书。"},{"i":10,"n":"第十条","txt":"藏传佛教院校学衔评定委员会可以根据需要设立学衔申请人资格审查委员会、辩经考评委员会和论文答辩委员会，履行下列职责： （一）审查学衔申请人的有关情况，包括政治思想表现、宗教操守、学力证明、课程考试和辩经考试、论文答辩材料等； （二）组织学衔申请人的辩经考试； （三）组织学衔申请人的论文评审和答辩工作。"},{"i":11,"n":"第十一条","txt":"学衔申请人应当维护国家统一，反对民族分裂，爱国爱教，遵纪守法；严守戒律，正信正行；具有相应的佛学理论知识和讲经说法能力，完成教学计划或相应课程的学习和修持，成绩合格，符合相应学衔的申请条件。"},{"i":12,"n":"第十二条","txt":"申请禅然巴学衔,应当符合以下条件： （一）较好地掌握因明学《释量论》、般若学《现观庄严论》、中观学《入中论》和《俱舍论》； （二）初步具备从事佛教研究工作的能力； （三）具备从事佛教教务活动的基本能力。"},{"i":13,"n":"第十三条","txt":"申请智然巴学衔,应当符合以下条件： （一）系统掌握因明学《释量论》、般若学《现观庄严论》、中观学《入中论》和《俱舍论》、戒律学《戒律本论》，并在相应研究领域有较深的造诣； （二）具备从事佛教研究工作的能力； （三）具备从事佛教教务活动的能力； （四）能够运用国家通用语言文字进行简单交流和阅读。"},{"i":14,"n":"第十四条","txt":"申请拓然巴学衔,应当符合以下条件： （一）系统深入掌握因明学《释量论》、般若学《现观庄严论》、中观学《入中论》和《俱舍论》、戒律学《戒律本论》，并在相应研究领域有突出成果； （二）具备独立从事佛教研究工作的能力； （三）具备较强的从事佛教教务活动的能力； （四）能够较熟练地运用国家通用语言文字进行交流和阅读。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，不具备申请学衔的资格： （一）道德品质和持戒守法方面犯有严重错误的； （二）课程考试中作弊，情节严重的； （三）论文剽窃他人学术成果，情节严重的； （四）在校期间受过留校察看以上纪律处分的。"},{"i":16,"n":"第十六条","txt":"学衔申请人申请学衔应当向藏传佛教院校提交本人填写的《藏传佛教学衔申请表》。"},{"i":17,"n":"第十七条","txt":"符合本办法第十二条规定的藏传佛教院校毕业生和寺庙学经班达到同等学力的学员，可以分别向所就读的藏传佛教院校、寺庙所在地的省、自治区藏传佛教院校申请禅然巴学衔。 符合本办法第十三条规定的藏传佛教院校毕业生和寺庙学经班达到同等学力的学员，可以分别向所就读的藏传佛教院校、寺庙所在地的省、自治区藏传佛教院校申请智然巴学衔。 符合本办法第十四条规定的藏传佛教院校毕业生和寺庙学经班达到同等学力的学员，可以向中国藏语系高级佛学院申请拓然巴学衔。"},{"i":18,"n":"第十八条","txt":"藏传佛教院校学衔评定委员会应当对学衔申请人的政治思想表现、宗教操守、课程考试和辩经考试、论文答辩等情况进行全面评审，并召开学衔评定会议讨论通过学衔授予决定。会议有五分之四以上的成员参加方为有效。 学衔评定会议采取无记名投票方式进行表决，出席会议三分之二以上成员同意方可通过学衔授予决定。形成决定的，应当当场制作会议纪要，并由参加会议的成员审阅、签名。表决不得采取通讯方式。"},{"i":19,"n":"第十九条","txt":"经藏传佛教院校学衔评定委员会评审不合格的，一年之后可以再次提出学衔申请。 学衔申请人对藏传佛教院校学衔评定委员会的评审结果有异议的，可以请求受理其学衔申请的藏传佛教院校予以复审。"},{"i":20,"n":"第二十条","txt":"省、自治区藏传佛教院校学衔授予情况，由举办该院校的省、自治区佛教团体分别报省、自治区人民政府宗教事务部门和藏传佛教学衔工作指导委员会备案。 中国藏语系高级佛学院学衔授予情况，报藏传佛教学衔工作指导委员会备案。 藏传佛教院校授予学衔人员名单，由中国佛教协会报国家宗教事务局备案。"},{"i":21,"n":"第二十一条","txt":"经国家宗教事务局备案后，中国佛教协会将被授予藏传佛教学衔人员名单在中国藏语系高级佛学院网站公布。"},{"i":22,"n":"第二十二条","txt":"对已被授予藏传佛教学衔的人员，发现有违反本办法第三章有关规定情形的，由授予其学衔的藏传佛教院校学衔评定委员会撤销其学衔。"},{"i":23,"n":"第二十三条","txt":"藏传佛教院校学衔评定委员会成员有下列行为之一的，由藏传佛教学衔工作指导委员会根据情节轻重，责令改正、暂停或取消其藏传佛教院校学衔评定委员会成员资格： （一）泄露评定意见及投票情况的； （二）公布评定结果前，泄露评定结果的； （三）为学衔申请人拉票，试图影响评定结果的； （四）收受学衔申请人贿赂的。 藏传佛教院校学衔评定委员会成员有前款第(三)项或第(四)项行为的，由藏传佛教学衔工作指导委员会宣布违规授予的学衔无效。"},{"i":24,"n":"第二十四条","txt":"藏传佛教院校学衔评定委员会有违反学衔授予程序和规定行为的，由藏传佛教学衔工作指导委员会宣布违规授予的学衔无效，并根据情节轻重，责令整改、暂停学衔授予工作或重组藏传佛教院校学衔评定委员会。"},{"i":25,"n":"第二十五条","txt":"《藏传佛教学衔申请表》、《藏传佛教学衔证书》由藏传佛教学衔工作指导委员会统一印制。"},{"i":26,"n":"第二十六条","txt":"《藏传佛教学衔证书》由藏传佛教院校院长签发。"},{"i":27,"n":"第二十七条","txt":"在藏传佛教院校学习的境外留学生和从事研究工作的境外学者，其学衔授予按照本办法的规定办理。"},{"i":28,"n":"第二十八条","txt":"中国佛教协会和省、自治区佛教团体可以根据实际情况制定实施细则。"},{"i":29,"n":"第二十九条","txt":"本办法自2015年6月1日起施行。"}],"cangchuanfojiaosimiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为保障公民的宗教信仰自由，规范藏传佛教寺庙管理，根据《宗教事务条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于 依照《宗教事务条例》和《宗教活动场所设立审批和登记办法》设立的藏传佛教活动场所（本办法称寺庙）。"},{"i":3,"n":"第三条","txt":"寺庙、藏传佛教教职人员（以下简称教职人员）的合法权益受法律保护。"},{"i":4,"n":"第四条","txt":"寺庙、教职人员应当遵守宪法、法律、法规、规章，维护国家统一、民族团结和社会稳定，促进藏传佛教与社会主义社会相适应。"},{"i":5,"n":"第五条","txt":"寺庙不得恢复已被废除的宗教封建特权和压迫剥削制度，不得恢复寺庙之间的隶属关系。"},{"i":6,"n":"第六条","txt":"藏传佛教与其他宗教之间、藏传佛教内部不同教派寺庙之间应当互相尊重、和睦相处。"},{"i":7,"n":"第七条","txt":"任何组织和个人不得利用藏传佛教进行破坏社会秩序、损害公民身体健康、妨碍国家教育制度，以及其他损害国家利益、社会公共利益和公民合法权益的活动。 寺庙事务不受境外任何组织和个人的干涉和支配。"},{"i":8,"n":"第八条","txt":"寺庙应当通过协商成立民主管理组织。管理组织的成员一般由本寺庙的教职人员组成，也可以吸收所在地信教公民代表和当地村委会（居委会）代表参加。 寺庙管理组织成员实行任期制，每届任期3至5年，可连选连任。"},{"i":9,"n":"第九条","txt":"寺庙管理组织成员人选确定后，由寺庙管理组织报所在地县级以上人民政府宗教事务部门备案。县级以上人民政府宗教事务部门在审核备案材料时，应当征求寺庙所在地乡镇人民政府（街道办事处）意见。 寺庙管理组织成员在任期内如有变更，按前款规定的程序及时进行变更备案。"},{"i":10,"n":"第十条","txt":"寺庙管理组织成员应具备以下条件： （一）拥护宪法，遵守国家法律、法规、规章，拥护祖国统一、反对民族分裂，维护宗教和睦与社会和谐； （二）品德良好，在信教公民中有一定威望； （三）有较强的组织协调和管理能力，能热心为信教公民服务。"},{"i":11,"n":"第十一条","txt":"寺庙管理组织履行以下职责： （一）制定并组织实施本寺庙的管理制度； （二）组织本寺庙教务活动，维护宗教活动正常秩序； （三）管理本寺庙教职人员和其他工作人员，组织学习国家有关的法律、法规、规章以及国家的民族、宗教政策，加强民族团结宣传教育，组织开展对教职人员的教育培训； （四）教育引导信教公民遵守国家有关的法律、法规、规章； （五）管理本寺庙财产和文物； （六）组织开展寺庙自养产业和社会公益慈善事业； （七）维护本寺庙治安秩序、消防安全和环境卫生； （八）协调本寺庙与社会其他方面的关系，维护本寺庙和教职人员的合法权益； （九）处理本寺庙的其他事务。 寺庙管理组织可以下设相关机构负责履行上述职能。"},{"i":12,"n":"第十二条","txt":"寺庙事务由寺庙管理组织民主管理。重大事项由寺庙管理组织成员集体讨论、民主协商确定。"},{"i":13,"n":"第十三条","txt":"寺庙应当建立寺庙管理组织成员考核制度，对不称职的成员应当及时进行调整。"},{"i":14,"n":"第十四条","txt":"寺庙应当加强内部管理，依照有关法律、法规、规章及藏传佛教教义教规，建立健全教务活动、人员、财务、会计、治安、消防、文物、环境保护、卫生防疫等管理制度。"},{"i":15,"n":"第十五条","txt":"寺庙根据容纳能力、自养能力、自我管理能力、当地信教公民的供养能力确定定员数额。"},{"i":16,"n":"第十六条","txt":"寺庙定员数额由该寺庙管理组织向所在地佛教协会提出申请，并提交该寺庙具备本办法第十五条规定的相应能力的说明材料。所在地佛教协会审核同意后，报所在地县级人民政府宗教事务部门，由县级人民政府宗教事务部门逐级报省级人民政府宗教事务部门备案。"},{"i":17,"n":"第十七条","txt":"寺庙住寺教职人员人数不得超过该寺庙的定员数额。 寺庙管理组织应当将住寺教职人员登记造册，分别于每年的1月底和7月底前报所在地县级以上人民政府宗教事务部门备案。"},{"i":18,"n":"第十八条","txt":"寺庙接受住寺教职人员，须经该寺庙管理组织成员会议通过后，报县级以上人民政府宗教事务部门备案。 寺庙住寺教职人员的户籍实行集体管理。"},{"i":19,"n":"第十九条","txt":"住寺教职人员须符合《藏传佛教教职人员资格认定办法》的有关规定。 寺庙不得强迫未成年人住寺。"},{"i":20,"n":"第二十条","txt":"活佛一般应当住寺，并服从所在寺庙管理组织的管理。"},{"i":21,"n":"第二十一条","txt":"寺庙中的赤巴、堪布、经师、翁则、格贵等传统僧职人员，由寺庙管理组织成员会议提出人选，经所在地佛教协会同意后，报所在地县级以上人民政府宗教事务部门备案。"},{"i":22,"n":"第二十二条","txt":"寺庙教职人员异地从事教务活动，须经本寺庙管理组织和所在地佛教协会同意，并征得目的地佛教协会和寺庙管理组织同意后，由本人所在地佛教协会和目的地佛教协会分别报当地人民政府宗教事务部门备案。其中，跨县（市、区、旗）从事教务活动的，分别报县级人民政府宗教事务部门备案后，由本人所在地县级人民政府宗教事务部门报所在地设区的市级人民政府宗教事务部门备案。跨设区的市（地、州、盟）从事教务活动的，分别报设区的市级人民政府宗教事务部门备案后，由本人所在地设区的市级人民政府宗教事务部门报所在地省级人民政府宗教事务部门备案。跨省、自治区、直辖市从事教务活动的，分别报省级人民政府宗教事务部门备案。"},{"i":23,"n":"第二十三条","txt":"寺庙跨省、自治区、直辖市举行超过该寺庙容纳规模的大型宗教活动，或者在该寺庙外举行大型宗教活动，按照《宗教事务条例》等有关规定办理。 寺庙跨设区的市（地、州、盟）、县（市、区、旗）举行大型宗教活动，其管理办法由有关省、自治区制定。"},{"i":24,"n":"第二十四条","txt":"寺庙举办学经班须符合下列条件： （一）有举办学经班的传统和明确的办学宗旨； （二）有固定的学经场所和其他基础设施； （三）有具备资格的经师； （四）有完备的学经管理制度及合法的经费来源。"},{"i":25,"n":"第二十五条","txt":"寺庙需要举办学经班的，由寺庙管理组织提出意见，经所在地佛教协会审核同意后，报所在地县级人民政府宗教事务部门，县级人民政府宗教事务部门逐级报省级人民政府宗教事务部门备案。"},{"i":26,"n":"第二十六条","txt":"学经班经师必须持有经师资格证，并由寺庙管理组织聘任。 经师资格认定和聘任办法由中国佛教协会制定，报国家宗教事务局备案。"},{"i":27,"n":"第二十七条","txt":"寺庙学经班招收的学员，应当符合以下条件： （一）年龄一般应当在18周岁以上； （二）爱国爱教，遵守国家的法律、法规、规章； （三）受过沙弥、沙弥尼以上戒。"},{"i":28,"n":"第二十八条","txt":"举办学经班的寺庙接受其他寺庙教职人员学习，应当履行以下程序： （一）本人向所在寺庙管理组织提出书面申请； （二）寺庙管理组织同意后报所在地佛教协会； （三）佛教协会报所在地县级以上人民政府宗教事务部门备案，县级以上人民政府宗教事务部门进行审核，并征求申请人所在地乡镇人民政府（街道办事处）的意见后，同意备案的出具书面证明； （四）申请人持所在地县级以上人民政府宗教事务部门出具的书面证明向举办学经班的寺庙报名； （五）举办学经班的寺庙管理组织组织统一考试，按照考试成绩确定拟录取人员名单； （六）寺庙管理组织将拟录取人员名单报所在地佛教协会审核同意后，向所在地县级以上人民政府宗教事务部门备案； （七）申请人所在寺庙管理组织与举办学经班的寺庙管理组织签订协议，明确相关事宜； （八）学经班学员学习期满后，及时返回本人所在寺庙。"},{"i":29,"n":"第二十九条","txt":"寺庙教职人员跨省、自治区、直辖市学经，除符合本办法第二十七条规定的条件以及履行第二十八条规定的程序外，还须分别报本人所在地及学经班所在地省级人民政府宗教事务部门备案。"},{"i":30,"n":"第三十条","txt":"寺庙印刷宗教内部资料性出版物，须遵守《宗教事务条例》和国家有关出版、印刷方面的规定。 寺庙设立印经院，须逐级报省级人民政府宗教事务部门备案。"},{"i":31,"n":"第三十一条","txt":"寺庙的财务管理应当遵守《宗教事务条例》、《宗教活动场所财务监督管理办法（试行）》。 寺庙可以按照国家有关规定接受境内外组织和个人的捐赠，所接受的捐赠应当纳入寺庙的财务管理，用于与该寺庙宗旨相符的活动。 寺庙可以按照国家有关规定举办社会公益慈善等事业，所获收益应当纳入寺庙财务统一管理，用于与该寺庙宗旨相符的活动。"},{"i":32,"n":"第三十二条","txt":"寺庙应当建立安全责任制度，明确相关责任人，对寺庙的安全情况加强日常监督检查，发现隐患及时解决，防止因寺庙安全问题危害人员生命财产。"},{"i":33,"n":"第三十三条","txt":"寺庙应当防范本寺庙内发生重大事故或者发生违犯宗教禁忌等伤害信教公民宗教感情、破坏民族团结和祖国统一、影响社会稳定的事件。 发生前款所列事故或者事件时，该寺庙管理组织应当立即报告所在地县级以上人民政府宗教事务部门。"},{"i":34,"n":"第三十四条","txt":"寺庙邀请境外人员来访或者进行宗教学术交流、讲经传法，应当按照国家有关规定办理。未经允许，境外人员不得在寺庙授戒、灌顶、讲经、传法、主持宗教活动。"},{"i":35,"n":"第三十五条","txt":"寺庙应当接受人民政府宗教、公安、文物、建设、卫生等有关部门依法实施的监督检查。"},{"i":36,"n":"第三十六条","txt":"寺庙所在地乡镇（街道）、村（社区）可根据实际情况设立寺庙评议委员会，对寺庙管理组织的工作进行评议。"},{"i":37,"n":"第三十七条","txt":"人民政府宗教事务部门工作人员在宗教事务管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。 侵犯寺庙、教职人员合法权益的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"寺庙有下列行为之一的，由登记管理机关责令改正；情节严重的，由登记管理机关责令该寺庙撤换直接负责的主管人员： （一）违反本办法第八条、第九条有关成立寺庙管理组织规定的； （二）寺庙管理组织未履行本办法第十一条、第十三条、第十四条规定的职责的； （三）寺庙管理组织违反本办法第十二条规定未实行民主管理的； （四）违反本办法第十六条、第十七条有关寺庙定员的规定的； （五）违反本办法第十八条、第十九条规定接受住寺教职人员的； （六）违反本办法第二十四条至第二十八条规定举办学经班的； （七）违反本办法第五条、第三十条、第三十一条、第三十四条规定的。"},{"i":39,"n":"第三十九条","txt":"寺庙教职人员违反《宗教事务条例》和本办法第二十条、第二十二条、第二十九条规定的，依照《宗教事务条例》第四十五条的规定予以处罚。 寺庙教职人员被佛教协会取消教职人员身份的，所在寺庙应当将其除名。"},{"i":40,"n":"第四十条","txt":"佛教协会未履行本办法规定的职责的，由人民政府宗教事务部门责令改正；情节严重的，由人民政府宗教事务部门责令该佛教协会撤换相关负责人。"},{"i":41,"n":"第四十一条","txt":"寺庙、教职人员违反本办法规定，《宗教事务条例》等法律法规有相关处罚规定的，从其规定。"},{"i":42,"n":"第四十二条","txt":"有关省、自治区人民政府宗教事务部门可以依照本办法制定实施细则。"},{"i":43,"n":"第四十三条","txt":"本办法自2010年11月1日起施行。"}],"cangchuanfojiaohuofozhuanshiguanlibanfa":[],"jihuashengyutongjigongzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强计划生育统计工作，使计划生育统计工作规范化、制度化、科学化，保障计划生育统计资料的准确性和及时性，根据《中华人民共和国统计法》（以下简称《统计法》）的有关规定，结合计划生育统计工作的实际，制定本办法。"},{"i":2,"n":"第二条","txt":"国家计划生育委员会和地方各级计划生育行政部门（以下简称计划生育部门）、直属单位及其工作人员，计划生育统计工作所涉及的单位和个人，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称计划生育统计工作，是指有关计划生育统计制度的制定和执行，统计制度执行情况的检查与监督，统计调查的组织和实施，统计资料的收集、管理和使用，统计人员的培训等工作。"},{"i":4,"n":"第四条","txt":"计划生育统计工作的基本任务是： （一）贯彻执行《统计法》，制定并实施各项计划生育统计工作管理办法； （二）实行计划生育工作的定期统计报表制度，组织和管理计划生育专门统计调查； （三）制定并实施计划生育统计方案，制定计划生育统计标准，建立、健全计划生育统计指标体系； （四）收集、整理、保管和提供计划生育统计资料，建立并完善以计算机技术为基础的信息收集、处理、传输系统和数据库系统； （五）分析、研究人口与计划生育统计资料； （六）检查计划生育统计制度执行情况和统计数据质量，考核评估人口计划执行结果和计划生育工作目标管理责任制落实情况； （七）审批本系统其他业务部门和直属单位涉及计划生育的统计报表和统计调查。指导本系统其他业务部门和直属单位涉及计划生育的统计活动。"},{"i":5,"n":"第五条","txt":"计划生育统计工作实行统一管理、分级负责的管理体制。国家计划生育委员会负责对全国计划生育统计工作实行统一管理、业务指导和组织协调，国家计划生育委员会的统计部门承担具体工作。地方各级计划生育部门负责对本行政区域内的计划生育工作实行统一管理、业务指导和组织协调，地方各级计划生育统计部门承担具体工作。"},{"i":6,"n":"第六条","txt":"建立、健全基本的统计工作制度，包括：统计帐卡和报表制度、统计调查制度、统计例会制度、统计人员培训制度、统计检查、奖惩和举报制度、统计资料管理和公布制度、村级统计资料公开制度等。"},{"i":7,"n":"第七条","txt":"各级计划生育部门应当把统计工作的发展纳入计划生育事业发展规划，为统计工作顺利开展提供必要的经费等保护条件。"},{"i":8,"n":"第八条","txt":"各级计划生育统计部门和统计人员，在计划生育统计工作中依法独立行使统计调查权、统计报告权和统计监督权。"},{"i":9,"n":"第九条","txt":"各级计划生育部门及其工作人员必须依照有关统计法律、法规的规定，提供计划生育统计资料，不得虚报、瞒报、拒报、迟报或伪造、篡改统计资料。"},{"i":10,"n":"第十条","txt":"县以上各级计划生育部门应当设立专门的统计部门，并指定统计负责人。乡、镇、街道（以下简称乡）计划生育办公室设置统计人员，乡计划生育办公室应当委托村、居民委员会（以下简称村）指派专人负责计划生育统计工作。"},{"i":11,"n":"第十一条","txt":"各级计划生育统计人员应当具备一定的统计业务知识。村级计划生育统计人员应当具有初中以上文化程度，乡级应当具有中专以上文化程度，县级以上的应当具有大专以上文化程度。 各级计划生育统计部门应当有计划地对统计人员（含计算机人员）进行培训。 省以下各级计划生育统计部门新上岗的统计人员必须得到省级计生委颁发的上岗证后方可上岗。"},{"i":12,"n":"第十二条","txt":"县以上各级计划生育部门应当依照国家有关规定，配合、协调有关部门为计划生育统计专业人员评定专业技术职称。"},{"i":13,"n":"第十三条","txt":"各级计划生育部门的统计人员应当保持相对稳定。对不称职、不合格的统计人员应当及时进行调整。"},{"i":14,"n":"第十四条","txt":"统计帐卡和统计报表是计划生育统计数据的主要来源。帐卡和报表及其项目的设置应当严格控制，删繁就简，以实用为原则。 乡、村两级应当建立、健全计划生育统计帐卡，帐卡内容应当每月变更。村级实行月报告单制度，每月通过报告单将变更信息上报到乡。乡级为计划生育情况报表起报单位，实行月、季、半年、全年报表制度，逐级上报。"},{"i":15,"n":"第十五条","txt":"各级计划生育部门实行统计例会制度。乡级每月应召开一次统计例会。"},{"i":16,"n":"第十六条","txt":"统计报表包括由计划生育统计部门负责的计划生育情况报表和本系统其他业务部门和直属单位负责的事业统计报表。 计划生育情况报表的主要内容包括：育龄妇女的婚姻、生育、避孕节育等情况； 事业统计报表的主要内容包括：宣传教育、政策法规、技术服务、避孕药具供应、信访、人事、财务、协会等情况。"},{"i":17,"n":"第十七条","txt":"县以上各级计划生育统计部门可根据上一级主管部门的要求和工作需要，经同级统计局审批，设置本行政区域内的计划生育统计报表，或者转发上一级主管部门的统计报表。自行设计的报表项目不得少于上一级主管部门统计报表的项目，其指标涵义、计算方法、分类目录、统计期限、上报时间等不得与上一级主管部门的有关规定相抵触。"},{"i":18,"n":"第十八条","txt":"上报计划生育情况报表需经本单位统计负责人审核、签字并加盖公章。上报半年和全年统计报表的同时应当报送书面统计分析报告。"},{"i":19,"n":"第十九条","txt":"计划生育系统的其他业务部门和直属单位设置的事业统计报表及专门统计调查表须经同级计划生育统计部门审核、批准、备案、授颁统一表号后方可制发。"},{"i":20,"n":"第二十条","txt":"各种事业统计报表的汇总、分析、上报，由相应的业务主管部门负责。上报的报表和分析报告，须抄送同级计划生育统计部门。"},{"i":21,"n":"第二十一条","txt":"按规定程序批准的计划生育统计报表和调查表必须在表的右上角标明表号、制表机关、批准机关和批准文号。对未经批准或备案的计划生育统计调查表，各级计划生育部门有权废止，有关的统计调查对象有权拒绝填报。"},{"i":22,"n":"第二十二条","txt":"县以上各级计划生育部门根据工作需要可以组织专门统计调查。"},{"i":23,"n":"第二十三条","txt":"县以上各级计划生育部门实行统计检查制度，对本级和下级的统计制度执行情况和统计数据质量进行检查。 国家定期对各省的统计质量进行检查，并将检查结果向全国通报。省、地、县各级计划生育部门组织的统计质量检查，要从严掌握，其结果应向本级管辖的各单位通报，同时向上级计划生育统计部门报告。乡计划生育办公室对村级统计帐卡应经常进行抽查。"},{"i":24,"n":"第二十四条","txt":"计划生育系统的各单位与社会其他部门、机构合作进行有关计划生育的统计调查，必须经同级计划生育统计部门审批；与国外、境外的机构和个人合作进行有关计划生育的统计调查，不得涉及国家有关保密内容，并须报国家计划生育委员会统计部门审批。"},{"i":25,"n":"第二十五条","txt":"计划生育系统以外的单位和个人进行涉及计划生育情况和计划生育工作的调查，必须经调查工作所涉及的行政区域的县以上计划生育统计部门审批，涉外调查须报国家计划生育委员会统计部门审批。"},{"i":26,"n":"第二十六条","txt":"各类计划生育统计调查方案要明确调查目的，规定调查方法、统计范围、分类目录、指标解释、计算方法。调查对象和调查内容属于计划生育部门管辖范围内的，调查方案和调查表由计划生育部门分管统计的负责人批准制发，并报同级统计局备案；调查对象和调查内容超出计划生育部门管辖范围的，调查方案和调查表经计划生育统计部门审核后须报同级统计局审批。"},{"i":27,"n":"第二十七条","txt":"各级计划生育部门按照统一、规范的原则，妥善保管本行政区域内的计划生育统计资料。地方各级计划生育部门上报的统计资料本级必须备案、存档。"},{"i":28,"n":"第二十八条","txt":"计划生育统计人员调动工作或者离职，必须与接管人员办清统计资料的交接手续。一般统计人员办理交接手续，由计划生育统计部门负责人、统计主管人员监交。计划生育统计部门负责人、统计主管人员办理交接手续，由单位领导人监交。"},{"i":29,"n":"第二十九条","txt":"属于国家秘密资料和国家计划生育委员会确定的秘密资料，不得泄露。属于调查对象的私人、家庭单项调查资料，非经本人同意，不得泄露。"},{"i":30,"n":"第三十条","txt":"各级计划生育部门按照国家有关规定，定期公布本行政区域内主要计划生育统计数据。重要数据的公布要与同级统计局协商。 国家计划生育委员会负责审定、公布和出版全国计划生育统计资料。省以下各级计划生育部门负责审定、公布、出版本行政区域内的计划生育统计资料。 宣传、新闻和出版单位发布尚未公开的计划生育统计资料，属于全国性的，须经国家计划生育委员会核准；属于省以下的，须经同级计划生育统计部门核准。所有发表的计划生育统计资料必须注明来源。"},{"i":31,"n":"第三十一条","txt":"各级计划生育部门向计划生育系统以外的部门、机构和个人提供本级所辖范围的计划生育统计资料，须经本级计划生育统计部门审批；向国外、境外的机构和个人提供计划生育统计资料，须经省以上计划生育统计部门审批。"},{"i":32,"n":"第三十二条","txt":"各级计划生育统计部门应当做好统计信息咨询工作，充分利用可以公开的统计信息为社会服务。"},{"i":33,"n":"第三十三条","txt":"本办法第二十四条、第二十五条所述的调查，在公布调查结果前，组织调查的单位或者个人应当向批准其调查的计划生育部门通报拟公布的调查结果，涉及重要数据须经批准方可公布。"},{"i":34,"n":"第三十四条","txt":"各级计划生育部门应当采用现代计算机技术装备统计部门，建立、健全以育龄妇女信息管理、常住人口信息管理、流动人口信息管理和实现办公自动化等为主要内容的计划生育管理信息系统，实现统计工作管理手段和方式的现代化。"},{"i":35,"n":"第三十五条","txt":"各级计划生育统计部门应当根据工作需要，配备一定数量的计算机专业人员。各级计划生育部门要加强计算机人员的业务培训。"},{"i":36,"n":"第三十六条","txt":"各级计划生育部门要根据国家计划生育委员会的统一要求，有计划、有步骤地进行计算机的应用与推广，逐步建立和完善全国计算机信息管理网络。各地必须按照国家有关保密规定使用计算机网络传输信息。"},{"i":37,"n":"第三十七条","txt":"各级计划生育统计部门要配备必要的计算机硬件、软件，并投入一定的经费，保证管理信息系统建立和运行的需要。"},{"i":38,"n":"第三十八条","txt":"各级计划生育部门定期对所辖范围的统计部门和统计人员进行考核、评比。对于在执行统计法律、法规，改革计划生育统计制度，完善统计手段，完成统计调查任务，开展统计科学研究，以及在统计工作中抵制弄虚作假、纠正重大统计错误等方面作出突出贡献的，应当按照有关规定给予表彰或奖励。"},{"i":39,"n":"第三十九条","txt":"违反本办法规定，有下列行为之一的，由县以上计划生育部门对有关单位和责任人给予通报批评，由本级计划生育部门依法给予行政处分或者建议有关部门依法给予行政处分： （一）自行修改统计资料、编造虚假数据，或者强令、授意统计部门、统计人员篡改统计资料或者编造虚假数据的； （二）拒报、瞒报计划生育统计资料的； （三）未经批准，擅自发布尚未公布的计划生育统计资料的； （四）擅自下发统计报表，或者实施统计调查，窃取国家秘密、损害社会、公众利益或者进行欺诈活动的； （五）泄露国家秘密的计划生育统计资料，造成国家损失或社会不良影响的； （六）在统计调查中泄露私人、家庭的单项调查资料，造成不良后果的； （七）对拒绝、抵制篡改统计资料或编造虚假数据行为的统计人员进行打击报复的； （八）妨碍计划生育统计机构、统计人员执行公务的。 有上述各项所列行为之一，情节严重构成犯罪的，由司法机关依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"本办法中的“以上”、“以下”均包括本数（本级）在内。"},{"i":41,"n":"第四十一条","txt":"本办法由国家计划生育委员会负责解释。"},{"i":42,"n":"第四十二条","txt":"本办法自1999年7月1日起施行。1990年国家计划生育委员会、国家统计局颁布的《计划生育统计工作实施办法》同时废止。"}],"jisuanjiruanjianzhuzuoquandengjibanfa":[{"i":1,"n":"第一条","txt":"为贯彻《计算机软件保护条例》（以下简称《条例》）制定本办法。"},{"i":2,"n":"第二条","txt":"为促进我国软件产业发展，增强我国信息产业的创新能力和竞争能力，国家著作权行政管理部门鼓励软件登记，并对登记的软件予以重点保护。"},{"i":3,"n":"第三条","txt":"本办法适用于软件著作权登记、软件著作权专有许可合同和转让合同登记。"},{"i":4,"n":"第四条","txt":"软件著作权登记申请人应当是该软件的著作权人以及通过继承、受让或者承受软件著作权的自然人、法人或者其他组织。 软件著作权合同登记的申请人，应当是软件著作权专有许可合同或者转让合同的当事人。"},{"i":5,"n":"第五条","txt":"申请人或者申请人之一为外国人、无国籍人的，适用本办法。"},{"i":6,"n":"第六条","txt":"国家版权局主管全国软件著作权登记管理工作。 国家版权局认定中国版权保护中心为软件登记机构。 经国家版权局批准，中国版权保护中心可以在地方设立软件登记办事机构。"},{"i":7,"n":"第七条","txt":"申请登记的软件应是独立开发的，或者经原著作权人许可对原有软件修改后形成的在功能或者性能方面有重要改进的软件。"},{"i":8,"n":"第八条","txt":"合作开发的软件进行著作权登记的，可以由全体著作权人协商确定一名著作权人作为代表办理。著作权人协商不一致的，任何著作权人均可在不损害其他著作权人利益的前提下申请登记，但应当注明其他著作权人。"},{"i":9,"n":"第九条","txt":"申请软件著作权登记的，应当向中国版权保护中心提交以下材料： （一）按要求填写的软件著作权登记申请表； （二）软件的鉴别材料； （三）相关的证明文件。"},{"i":10,"n":"第十条","txt":"软件的鉴别材料包括程序和文档的鉴别材料。 程序和文档的鉴别材料应当由源程序和任何一种文档前、后各连续30页组成。整个程序和文档不到60页的，应当提交整个源程序和文档。除特定情况外，程序每页不少于50行，文档每页不少于30行。"},{"i":11,"n":"第十一条","txt":"申请软件著作权登记的，应当提交以下主要证明文件： （一）自然人、法人或者其他组织的身份证明； （二）有著作权归属书面合同或者项目任务书的，应当提交合同或者项目任务书； （三）经原软件著作权人许可，在原有软件上开发的软件，应当提交原著作权人的许可证明； （四）权利继承人、受让人或者承受人，提交权利继承、受让或者承受的证明。"},{"i":12,"n":"第十二条","txt":"申请软件著作权登记的，可以选择以下方式之一对鉴别材料作例外交存： （一）源程序的前、后各连续的30页，其中的机密部分用黑色宽斜线覆盖，但覆盖部分不得超过交存源程序的50%； （二）源程序连续的前10页，加上源程序的任何部分的连续的50页； （三）目标程序的前、后各连续的30页，加上源程序的任何部分的连续的20页。 文档作例外交存的，参照前款规定处理。"},{"i":13,"n":"第十三条","txt":"软件著作权登记时，申请人可以申请将源程序、文档或者样品进行封存。除申请人或者司法机关外，任何人不得启封。"},{"i":14,"n":"第十四条","txt":"软件著作权转让合同或者专有许可合同当事人可以向中国版权保护中心申请合同登记。申请合同登记时，应当提交以下材料： （一）按要求填写的合同登记表； （二）合同复印件； （三）申请人身份证明。"},{"i":15,"n":"第十五条","txt":"申请人在登记申请批准之前，可以随时请求撤回申请。"},{"i":16,"n":"第十六条","txt":"软件著作权登记人或者合同登记人可以对已经登记的事项作变更或者补充。申请登记变更或者补充时，申请人应当提交以下材料： （一）按照要求填写的变更或者补充申请表； （二）登记证书或者证明的复印件； （三）有关变更或者补充的材料。"},{"i":17,"n":"第十七条","txt":"登记申请应当使用中国版权保护中心制定的统一表格，并由申请人盖章（签名）。 申请表格应当使用中文填写。提交的各种证件和证明文件是外文的，应当附中文译本。 申请登记的文件应当使用国际标准A4型297mm×210mm（长×宽）纸张。"},{"i":18,"n":"第十八条","txt":"申请文件可以直接递交或者挂号邮寄。申请人提交有关申请文件时，应当注明申请人、软件的名称，有受理号或登记号的，应当注明受理号或登记号。"},{"i":19,"n":"第十九条","txt":"对于本办法第九条和第十四条所指的申请，以收到符合本办法第二章规定的材料之日为受理日，并书面通知申请人。"},{"i":20,"n":"第二十条","txt":"中国版权保护中心应当自受理日起60日内审查完成所受理的申请，申请符合《条例》和本办法规定的，予以登记，发给相应的登记证书，并予以公告。"},{"i":21,"n":"第二十一条","txt":"有下列情况之一的，不予登记并书面通知申请人： （一)表格内容填写不完整、不规范，且未在指定期限内补正的； （二）提交的鉴别材料不是《条例》规定的软件程序和文档的； （三）申请文件中出现的软件名称、权利人署名不一致，且未提交证明文件的； （四）申请登记的软件存在权属争议的。"},{"i":22,"n":"第二十二条","txt":"中国版权保护中心要求申请人补正其他登记材料的，申请人应当在30日内补正，逾期未补正的，视为撤回申请。"},{"i":23,"n":"第二十三条","txt":"国家版权局根据下列情况之一，可以撤销登记： （一）最终的司法判决； （二）著作权行政管理部门作出的行政处罚决定。"},{"i":24,"n":"第二十四条","txt":"中国版权保护中心可以根据申请人的申请，撤销登记。"},{"i":25,"n":"第二十五条","txt":"登记证书遗失或损坏的，可申请补发或换发。"},{"i":26,"n":"第二十六条","txt":"除本办法另有规定外，任何人均可查阅软件登记公告以及可公开的有关登记文件。"},{"i":27,"n":"第二十七条","txt":"软件登记公告的内容如下： （一）软件著作权的登记； （二）软件著作权合同登记事项； （三）软件登记的撤销； （四）其他事项。"},{"i":28,"n":"第二十八条","txt":"申请软件登记或者办理其他事项，应当交纳下列费用： （一）软件著作权登记费； （二）软件著作权合同登记费； （三）变更或补充登记费； （四）登记证书费； （五）封存保管费； （六）例外交存费； （七）查询费； （八）撤销登记申请费； （九）其他需交纳的费用。 具体收费标准由国家版权局会同国务院价格主管部门规定并公布。"},{"i":29,"n":"第二十九条","txt":"申请人自动撤回申请或者登记机关不予登记的，所交费用不予退回。"},{"i":30,"n":"第三十条","txt":"本办法第二十八条规定的各种费用，可以通过邮局或银行汇付，也可以直接向中国版权保护中心交纳。"},{"i":31,"n":"第三十一条","txt":"本办法规定的、中国版权保护中心指定的各种期限，第一日不计算在内。期限以年或者月计算的，以最后一个月的相应日为届满日；该月无相应日的，以该月的最后一日为届满日。届满日是法定节假日的，以节假日后的第一个工作日为届满日。"},{"i":32,"n":"第三十二条","txt":"申请人向中国版权保护中心邮寄的各种文件，以寄出的邮戳日为递交日。信封上寄出的邮戳日不清晰的，除申请人提出证明外，以收到日为递交日。中国版权保护中心邮寄的各种文件，送达地是省会、自治区首府及直辖市的，自文件发出之日满十五日，其他地区满二十一日，推定为收件人收到文件之日。"},{"i":33,"n":"第三十三条","txt":"申请人因不可抗力或其他正当理由，延误了本办法规定或者中国版权保护中心指定的期限，在障碍消除后三十日内，可以请求顺延期限。"},{"i":34,"n":"第三十四条","txt":"本办法由国家版权局负责解释和补充修订。"},{"i":35,"n":"第三十五条","txt":"本办法自发布之日起实施。"}],"bianjingxiaoemaoyihebianjingdiquduiwaijingjijishuhcfa646":[{"i":1,"n":"第一条","txt":"为加强对我国边境小额贸易和边境地区对外经济技术合作的规范管理，维护边境小额贸易和边境地区对外经济技术合作的正常经营秩序，促进边境贸易健康、稳定发展，根据《国务院关于边境贸易有关问题的通知》，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所指可以开展边境小额贸易和边境地区对外经济技术合作项目的地区（以下简称边境地区）系指我国与毗邻国家有陆地接壤的边境县（市、旗）和经国务院批准的边境开放城市的辖区。"},{"i":3,"n":"第三条","txt":"全国性的边境贸易和边境地区经济技术合作政策及宏观管理措施，由对外贸易经济合作部（以下简称外经贸部）会同国务院有关部门研究制定。"},{"i":4,"n":"第四条","txt":"本办法所指边境小额贸易系指我国边境地区经批准有边境小额贸易经营权的企业（以下简称边境小额贸易企业），通过国家指定的陆地边境口岸，与毗邻国家边境地区的企业或其它贸易机构之间进行的贸易活动。"},{"i":5,"n":"第五条","txt":"边境小额贸易企业通过指定边境口岸进口原产地在我国毗邻国家的产品，除烟、酒、化妆品以及国家规定必须照章征税的其它商品外，“九五”前3年（1996至1998年），进口关税和进口环节税按法定税率减半征收。国家规定必须照章征税的商品品种由海关总署公布下达。"},{"i":6,"n":"第六条","txt":"边境小额贸易企业，在外经贸部核定的总数内，根据外经贸部制定的条件，由各边境盛自治区外经贸主管部门进行审批，报外经贸部核准，并由外经贸部抄送海关总署及国务院有关部门备案。"},{"i":7,"n":"第七条","txt":"边境小额贸易企业总数的核定依据以下原则： （一）外经贸部将根据各边境盛自治区边境地区的国民生产总值和进出口贸易额及边境地区的实际情况，核定各边境盛自治区边境小额贸易企业总数； （二）已在边境地区工商行政管理部门登记注册，并已经外经贸部批准获得进出口经营权的外贸公司、易货贸易公司、边贸公司和自营进出口的生产企业，均可在批准的经营范围内经营边境小额贸易。"},{"i":8,"n":"第八条","txt":"边境小额贸易企业首先应是在边境地区工商行政管理部门登记注册的企业法人，并具备以下条件： （一）注册资金不得少于50万元人民币； （二）须有固定的营业场所和开展边贸必备的设施和资金； （三）有健全的组织机构和适应经营边贸的业务人员。"},{"i":9,"n":"第九条","txt":"各边境省、自治区边境小额贸易企业须通过以企业注册地为主及相毗邻的经国家批准正式对外开放的陆路边境口岸开展边境小额贸易（经国务院批准的江山、企沙、石头埠及果子山4个边地贸过货口岸包括在内）。"},{"i":10,"n":"第十条","txt":"各边境省、自治区可指定1—2家有经营实绩或经营能力的边境额贸易企业，通过指定边境口岸，经营向本盛自治区毗邻国家出口边境地区自产的国家组织统一联合经营的出口商品，以及进口国家核定公司经营的进口商品，经营企业名单报外经贸部核准，并由外经贸部抄送海关总署及国务院有关部门。"},{"i":11,"n":"第十一条","txt":"除国家规定实行统一联合经营和核定公司经营的进出口商品外，开展边境小额贸易可不受贸易方式和经营分工的限制。经批准享有边境小额贸易经营权的企业，均可经营除第十条以外的进出口业务。"},{"i":12,"n":"第十二条","txt":"边境小额贸易企业出口统一联合经营的出口商品、实行配额招标的出口商品、军民通用化学品、易制毒化学品及我在国际多、双边协议中承诺限量出口的商品，原则上按国家制定的现行办法办理。 各边境盛自治区属边境地区自产的国家统一联合经营的出口商品的品种及年度出口配额，1996年由外经贸部根据其前三年的生产数量、出口实绩和增长率进行核定下达，以后参照上年的出口量和增长率核定下达。 关于边境小额贸易中涉及出口配额招标商品将在招标管理办法中另行规定。"},{"i":13,"n":"第十三条","txt":"边境小额贸易企业经营出口除上述以外的配额、许可证管理商品，免领配额、许可证，但要接受外经贸部和国家计划委员会的宏观管理，在外经贸部下达的指标内，海关凭边境小额贸易企业出口合同及各边境盛自治区外经贸主管部门下达的文件验放。"},{"i":14,"n":"第十四条","txt":"边境小额贸易企业不得以任何形式允许其他企业以本企业名义经营边境小额贸易。"},{"i":15,"n":"第十五条","txt":"边境小额贸易企业不得通过边境口岸进口第三国的商品及经营向第三国出口业务。"},{"i":16,"n":"第十六条","txt":"为及时掌握和了解边境小额贸易进出口情况，各边境省、自治区外经贸主管部门应加强边境小额贸易进出口情况的统计、上报工作，须将本省区每季度边境小额贸易进出口情况上报外经贸部，并于每年1月底以前将上年边境小额贸易进出口情况汇总上报外经贸部。"},{"i":17,"n":"第十七条","txt":"边境小额贸易享受一般贸易出口退税政策，并按一般贸易出口退税办法办理出口退税手续。"},{"i":18,"n":"第十八条","txt":"本办法所指边境地区对外经济技术合作系指我国边境地区经外经贸部批准有对外经济技术合作经营权的企业（以下简称边境地区外经企业），与我国毗邻国家边境地区开展的承包工程和劳务合作项目。"},{"i":19,"n":"第十九条","txt":"边境地区外经企业须报外经贸部审批。边境地区外经企业的审批依据以下原则： （一）已经外经贸部批准的边境地区外经公司，均可开展与毗邻国家边境地区的承包工程和劳务合作业务； （二）经国家批准的一类边境口岸所在边境地区，可选择一家边境小额贸易企业，报外经贸部批准后，开展与毗邻国家边境地区的承包工程和劳务合作业务。"},{"i":20,"n":"第二十条","txt":"边境地区外经企业同毗邻国家边境地区签订的承包工程和劳务合作的合同须报外经贸主管部门备案，并申领《在毗邻国家开展承包工程和劳务合作进出口物品批准书》（以下简称《批准书》）。"},{"i":21,"n":"第二十一条","txt":"单项承包工程项目金额在100万美元（含100万）以下单项劳务合作项目在100人（含100人）以下的合同，报边境盛自治区外经贸主管部门备案，由其核发《批准书》。边境盛自治区外经贸主管部门每月将上述合同汇总后报外经贸部备案。 单项承包工程项目金额在100万美元以上或单项劳务合作项目在100人以上合同、由各边境盛自治区外经贸主管部门报外经贸部备案，由外经贸部核发《批准书》。 备案材料包括中外文合同及合同备案表各一式两份。"},{"i":22,"n":"第二十二条","txt":"边境地区外经企业与毗邻国家边境地区开展承包工程和劳务合作项下带出的设备、材料和劳务人员自用生活物品、除涉及实行配额招标的出口商品、军民通用化学品、易制毒化学品及我在国际多、双边协议中承诺限量出口的商品外，在合理范围内，不受经营分工和出口配额的限制，并免领出口许可证。海关凭按本办法第二十一条规定经外经贸主管部门备案的合同及其设备、材料、物品清单和《批准书》验放。"},{"i":23,"n":"第二十三条","txt":"承包工程和劳务合作项下带出的设备、材料和劳务人员自用物品，如涉及实行配额招标的出口商品、军民通用化学品、易制毒化学品及我在国际多、双边协议中承诺限量出口的商品，其合同不论金额大小，一律报外经贸部审批。海关凭经外经贸部批准的合同及其设备、材料、物品清单、《批准书》和出口许可证验放。"},{"i":24,"n":"第二十四条","txt":"边境地区外经企业与毗邻国家边境地区开展承包工程和劳务合作项下换回的原产于毗邻国家的物资，不受经营分工的限制，按项目合同规定的品种和数量进境。 开展承包工程和劳务合作项下换回的原产于毗邻国家的物资，不受经营分工的限制，按项目合同规定的品种和数量进境。海关凭有关外经贸主管部门批准备案的合同和《批准书》验放。"},{"i":25,"n":"第二十五条","txt":"边境地区外经企业毗邻国家边境地区开展承包工程和劳务合作项下进出境的货物，应从指定的边境口岸进出。"},{"i":26,"n":"第二十六条","txt":"边境地区外经企业与毗邻国家边境地区开展承包工程和劳务合作项下换回的原产于毗邻国家的物资，执行边境小额贸易的进口税收政策。 每批（次）物资进境时，边境地区外经企业须持有关外经贸主管部门批准备案的合同及《批准书》，向其项目备案（主管地）海关申请办理减税手续，经海关审核后，在核定的数量内签发减税证明书，通知进口地海关凭以验放。进口地海关应在《批准书》背面的有关项目栏内予以签注每批（次）实际进口品种、数量。在达到合同规定的品种和数量后，海关停止办理有关货物进口手续。"},{"i":27,"n":"第二十七条","txt":"对违反《海关法》及本办法规定的边境小额贸易企业和边境地区外经企业，外经贸部将视情节轻重给予必要的处分直至取消其边境小额贸易经营权或对外经济技术合作经营权；海关将依照《海关法》和《海关行政处罚实施细则》进行处理。"},{"i":28,"n":"第二十八条","txt":"各边境省、自治区人民政府应根据国家有关规定，结合本地区的实际情况，制定具体实施办法；各边境盛自治区外经贸主管部门应指定机构，负责统一指导和协调管理本盛自治区的边境贸易和边境地区对外经济技术合作业务；各边境盛自治区外经贸主管部门和各级海关要切实加强对边境贸易和边境地区对外经济技术合作的管理。坚决打击走私和违法经营活动，维护边境贸易的正常经营秩序。"},{"i":29,"n":"第二十九条","txt":"本办法由外经贸部、海关总署负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自1996年4月1日起执行。过去有关规定与本办法规定不一致的，以本办法为准。"}],"yundongyuanjiaolianyuanjianglishishibanfa":[{"i":1,"n":"第一条","txt":"为加快发展我国体育事业，调动运动员、教练员的积极性和创造性，提高运动技术水平，根据《国务院关于机关和事业单位工作人员工资制度改革问题的通知》[国发(1993)79号]和人事部、国家体委《关于印发〈体育运动员、教练员贯彻事业单位工作人员工资制度改革方案〉的实施意见的通知》[人薪发(1994)12号]的精神，结合体育运动队的实际情况，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于体育系统各级优秀运动队的运动员、教练员以及各类体校的教练员。 其他系统优秀运动队的运动员、教练员可参照执行。"},{"i":3,"n":"第三条","txt":"运动员、教练员的奖励应根据比赛(培训)成绩并结合政治思想、道德作风、法纪观念等方面的情况全面评定。"},{"i":4,"n":"第四条","txt":"各级体育运动委员会在同级人民政府领导下负责运动员、教练员的奖励工作。 全国单项运动协会负责本办法规定的运动员、教练员奖励的具体实施工作。 运动员、教练员应当发扬爱国主义和集体主义精神，为提高我国运动技术水平做出更大贡献。"},{"i":5,"n":"第五条","txt":"运动员名次奖： (一)运动员在奥运会、亚运会上获得奖励名次，执行附表一所列奥运会、亚运会奖金标准的上限； (二)运动员在世界锦标赛、世界杯赛、亚洲锦标赛上获得奥运会比赛项目奖励名次，执行附表一所列奥运会项目相应比赛层次资金的上限； (三)运动员在世界锦标赛、世界杯赛、亚洲锦标赛上获得非奥运会比赛项目奖励名次，执行附表一所列非奥运会项目相应比赛层次奖金标准的上限； (四)集体项目和团体(组)项目的非主力运动员，执行附表一(见表)所列相应比赛层次奖金标准的下限； (五)登山运动员执行附表二(见表)所列相应比赛层次奖金标准。"},{"i":6,"n":"第六条","txt":"运动员创世界、亚洲纪录奖： (一)运动员在奥运会上创世界纪录，执行奥运会第一名奖金标准的下限； (二)运动员在其他比赛上创奥运会比赛项目的世界纪录或亚洲纪录，分别执行奥运会项目世界锦标赛或亚洲锦标赛第一名奖金标准的下限； (三)运动员创非奥运会比赛项目的世界纪录或亚洲纪录，分别执行非奥运会项目世界锦标赛或亚洲锦标赛第一名奖金标准的下限。"},{"i":7,"n":"第七条","txt":"运动员每多获得一项奖励名次或每多创一项世界纪录、亚洲纪录，分别按该奖励名次奖金标准或创纪录奖金标准增发一份奖金。"},{"i":8,"n":"第八条","txt":"运动员获得奖励名次的同时创世界纪录、亚洲纪录的，其奖金除按奖励名次、创纪录两项奖金标准中较高的一项评定外，另按较低一项奖金标准的20%增发奖金。"},{"i":9,"n":"第九条","txt":"在运动员的奖励名次奖金和创纪录奖金数额内，应主要考虑获奖运动员，同时也要考虑为该运动员获得奖励名次和创纪录做出贡献的陪练等其他有关运动员。"},{"i":10,"n":"第十条","txt":"教练员所培训的运动员获得奖励名次或创纪录的，该教练员获得培训成绩奖。培训成绩奖金标准与所培训的运动员奖金标准相同。其中，个人项目的教练员按培训成绩奖金标准的一份评奖；团体(组)项目的教练员按培训成绩奖金标准的一至二份评奖；集体项目的教练员按培训成绩奖金标准的三份评奖。"},{"i":11,"n":"第十一条","txt":"教练员所培训的运动员(队)获得二个以上奖励名次或创二次以上纪录以及获得奖励名次的同时创纪录的，该教练员的评奖标准和办法与运动员相同。"},{"i":12,"n":"第十二条","txt":"在教练员的培训成绩奖金数额内，要根据培训该运动员的时间和实际贡献，具体评发现任主管教练员、输送教练员和本队其他有关教练员的奖金。"},{"i":13,"n":"第十三条","txt":"对首次获得世界冠军或创世界纪录的运动员的启蒙教练，由全国单项运动协会根据其贡献给予一次性奖励，具体奖励标准由全国单项运动协会自行制定。"},{"i":14,"n":"第十四条","txt":"业余体校教练员向优秀运动队输送运动员的输送奖，由各省、自治区、直辖市体委制定奖励办法，经当地人民政府批准后实施。"},{"i":15,"n":"第十五条","txt":"获得奥运会、世界锦标赛、世界杯赛、亚运会、亚洲锦标赛奖励名次和创世界纪录、亚洲纪录的运动员、教练员的奖金，由全国单项运动协会审核成绩，填写《运动员、教练员奖金审批表》(见附表三见表)，报国家体委审批。国家体委将奖金总额拨发给全国单项运动协会，由全国单项运动协会具体评发。 奥运会、亚运会的奖金在比赛结束后，即予审批发放；其他比赛的奖金，于下1年3月底以前审批发放。"},{"i":16,"n":"第十六条","txt":"启蒙教练奖由全国单项运动协会审批发放，所需经费由全国单项运动协会自行解决。"},{"i":17,"n":"第十七条","txt":"少数在国内外重大比赛中取得优异成绩并做出特殊贡献的运动员、教练员，除按本办法规定给予奖励外，国家体委可再适当增发一定数额的奖金。"},{"i":18,"n":"第十八条","txt":"运动员、教练员因政治思想、道德作风、遵纪守法等方面表现不好或受到处分的，由全国单项运动协会提出处理意见，经国家体委审批，可酌情减发奖金数额，直至取消奖励。"},{"i":19,"n":"第十九条","txt":"全国性比赛的奖金标准和奖励办法由各省、自治区、直辖市体委制定，经当地人民政府批准后实施，报国家体委备案。但奖金标准不得超过附表一所列亚运会相应奖励名次奖金标准的下限。"},{"i":20,"n":"第二十条","txt":"本办法所称的比赛奖励名次是指竞赛规程规定的奖励名次。创世界纪录、亚洲纪录是指经国际单项运动协会和亚洲单项运动协会批准的纪录。"},{"i":21,"n":"第二十一条","txt":"本办法所称登山运动员的奖励，是指经中国登山协会批准的登山活动获得成功后根据运动员的登山成绩实施的奖励。"},{"i":22,"n":"第二十二条","txt":"在个人项目比赛中即排列了个人奖励名次，又以个人比赛成绩累计加分重复计算出的奖励名次，一般不作为获奖名次评奖。"},{"i":23,"n":"第二十三条","txt":"参加世界锦标赛、世界杯赛和亚洲锦标赛的运动员、教练员，除按本办法规定获得奖励外，凡获得主办单位发给的奖金的，其资金的分配办法按国家体委现行的有关规定执行。"},{"i":24,"n":"第二十四条","txt":"国家体委和各省、自治区、直辖市体委可以将相当于每年度实际支付给运动员、教练员奖金总额的10%的经费，用于奖励为运动队创造优异成绩做出较大贡献的有功人员。具体奖励办法分别由国家体委和各省、自治区、直辖市体委另行制定。"},{"i":25,"n":"第二十五条","txt":"优秀运动员、教练员参加本办法规定之外的其他国际比赛获得奖励名次，业余运动员、教练员参加种类国际比赛(奥运会、亚运会除外)获得奖励名次或创纪录的，可由全国性体育运动协会根据实际情况给予奖励。具体奖励办法由各协会自行制定，所需经费由各协会自行解决。"},{"i":26,"n":"第二十六条","txt":"全国单项运动协会依据本办法制定具体奖励实施细则，报国家体委审批。"},{"i":27,"n":"第二十七条","txt":"本办法自1995年1月1日起实行。过去有关运动员、教练员奖励的规定与本办法不相符的，以本办法为准。"},{"i":28,"n":"第二十八条","txt":"本办法由人事部、国家体委负责解释。"}],"jinanhaiyuhuanjinggongnengquguanlibanfa":[{"i":1,"n":"第一条","txt":"为保护和改善近岸海域生态环境，执行《中华人民共和国海水水质标准》，规范近岸海域环境功能区的划定工作，加强对近岸海域环境功能区的管理，制定本办法。"},{"i":2,"n":"第二条","txt":"近岸海域环境功能区，是指为适应近岸海域环境保护工作的需要，依据近岸海域的自然属性和社会属性以及海洋自然资源开发利用现状，结合本行政区国民经济、社会发展计划与规划，按照本办法规定的程序，对近岸海域按照不同的使用功能和保护目标而划定的海洋区域。 近岸海域环境功能区分为四类： 一类近岸海域环境功能区包括海洋渔业水域、海上自然保护区、珍稀濒危海洋生物保护区等； 二类近岸海域环境功能区包括水产养殖区、海水浴场、人体直接接触海水的海上运动或娱乐区、与人类食用直接有关的工业用水区等； 三类近岸海域环境功能区包括一般工业用水区、海滨风景旅游区等； 四类近岸海域环境功能区包括海洋港口水域、海洋开发作业区等。 各类近岸海域环境功能区执行相应类别的海水水质标准. 本办法所称近岸海域是指与沿海省、自治区、直辖市行政区域内的大陆海岸、岛屿、群岛相毗连，《中华人民共和国领海及毗连区法》规定的领海外部界限向陆一侧的"},{"i":3,"n":"第三条","txt":"沿海县级以上地方人民政府环境保护行政主管部门对本行政区近岸海域环境功能区的环境保护工作实施统一监督管理。"},{"i":4,"n":"第四条","txt":"划定近岸海域环境功能区，应当遵循统一规划，合理布局，因地制宜，陆海兼顾，局部利益服从全局利益，近期计划与长远规划相协调，经济效益、社会效益和环境效益相统一，促进经济、社会可持续发展的原则。"},{"i":5,"n":"第五条","txt":"近岸海域环境功能区划方案应当包括以下主要内容： （一）本行政区近岸海域自然环境现状； （二）本行政区沿海经济、社会发展现状和发展规划； （三）本行政区近岸海域海洋资源开发利用现状、开发规划和存在的主要问题； （四）本行政区近岸海域环境状况变化预测； （五）近岸海域环境功能区的海水水质现状和保护目标； （六）近岸海域环境功能区的功能、位置和面积； （七）近岸海域环境功能区海水水质保护目标可达性分析； （八）近岸海域环境功能区的管理措施。"},{"i":6,"n":"第六条","txt":"任何单位和个人不得擅自改变近岸海域环境功能区划方案。确因需要必须进行调整的，由本行政区省辖市级环境保护行政主管部门按本办法第四条和第五条的规定提出调整方案，报原审批机关批准。"},{"i":7,"n":"第七条","txt":"各类近岸海域环境功能区应当执行国家《海水水质标准》(GB3097～1997)规定的相应类别的海水水质标准。 （一）一类近岸海域环境功能区应当执行一类海水水质标准。 （二）二类近岸海域环境功能区应当执行不低于二类的海水水质标准。 （三）三类近岸海域环境功能区应当执行不低于三类的海水水质标准。 （四）四类近岸海域环境功能区应当执行不低于四类的海水水质标准。"},{"i":8,"n":"第八条","txt":"沿海省、自治区、直辖市人民政府环境保护行政主管部门根据本行政区近岸海域环境功能区环境保护的需要，对国家海水水质标准中未作规定的项目，可以组织拟订地方海水水质补充标准，报同级人民政府批准发布。 沿海省、自治区、直辖市人民政府环境保护行政主管部门对国家污染物排放标准中未作规定的项目，可以组织拟订地方污染物排放标准；对国家污染物排放标准中已作规定的项目，可以组织拟订严于国家污染物排放标准的地方污染物排放标准，报同级人民政府批准发布。 地方海水水质补充标准和地方污染物排放标准应报国务院环境保护行政主管部门备案。 凡是向已有地方污染物排放标准的近岸海域环境功能区排放污染物的，应当执行地方污染物排放标准。"},{"i":9,"n":"第九条","txt":"对入海河流河口、陆源直排口和污水排海工程排放口附近的近岸海域，可确定为混合区。 确定混合区的范围，应当根据该区域的水动力条件，邻近近岸海域环境功能区的水质要求，接纳污染物的种类、数量等因素，进行科学论证。 混合区不得影响邻近近岸海域环境功能区的水质和鱼类洄游通道。"},{"i":10,"n":"第十条","txt":"在一类、二类近岸海域环境功能区内，禁止兴建污染环境、破坏景观的海岸工程建设项目。"},{"i":11,"n":"第十一条","txt":"禁止破坏红树林和珊瑚礁。 在红树林自然保护区和珊瑚礁自然保护区开展活动，应严格执行《中华人民共和国自然保护区条例》，禁止危害保护区环境的项目建设和其他经济开发活动。 禁止在红树林自然保护区和珊瑚礁自然保护区内设置新的排污口。本办法发布前已经设置的排污口，由县级以上地方人民政府环境保护行政主管部门依照《海洋环境保护法》第七十七条规定责令其关闭，并处二万元以上十万元以下的罚款。"},{"i":12,"n":"第十二条","txt":"向近岸海域环境功能区排放陆源污染物，必须遵守海洋环境保护有关法律、法规的规定和有关污染物排放标准。 对现有排放陆源污染物超过国家或者地方污染物排放标准的，限期治理。"},{"i":13,"n":"第十三条","txt":"在近岸海域环境功能区内可能发生重大海洋环境污染事故的单位和个人，应当依照国家规定制定污染事故应急计划。"},{"i":14,"n":"第十四条","txt":"沿海县级以上地方人民政府环境保护行政主管部门，有权对在本行政区近岸海域环境功能区内兴建海岸工程建设项目和排放陆源污染物的单位进行现场检查。被检查者应当如实反映情况,提供必要的资料。环境保护行政主管部门应当为被检查者保守技术秘密和业务秘密。"},{"i":15,"n":"第十五条","txt":"沿海县级以上地方人民政府环境保护行政主管部门，应当按照国务院环境保护行政主管部门的有关规定进行近岸海域环境状况统计，在发布本行政区的环境状况公报中列出近岸海域环境状况。"},{"i":16,"n":"第十六条","txt":"国务院环境保护行政主管部门对近岸海域环境质量状况定期组织检查和考核,并公布检查和考核结果。"},{"i":17,"n":"第十七条","txt":"在近岸海域环境功能区内，防治船舶、海洋石油勘探开发、向海洋倾倒废弃物污染的环境保护工作，由《中华人民共和国海洋环境保护法》规定的有关主管部门实施监督管理。"},{"i":18,"n":"第十八条","txt":"违反本办法规定的，由环境保护行政主管部门依照有关法律、法规的规定进行处罚。"},{"i":19,"n":"第十九条","txt":"本办法用语含义 （一）海洋渔业水域是指鱼虾类的产卵场、索饵场、越冬场、洄游通道。 （二）珍稀濒危海洋生物保护区是指对珍贵、稀少、濒临灭绝的和有益的、有重要经济、科学研究价值的海洋动植物，依法划出一定范围予以特殊保护和管理的区域。 （三）水产养殖区是指鱼虾贝藻类及其他海洋水生动植物的养殖区域。 （四）海水浴场是指在一定的海域内，有专门机构管理，供人进行露天游泳的场所。 （五）人体直接接触海水的海上运动或娱乐区是指在海上开展游泳、冲浪、划水等活动的区域。 （六）与人类食用直接有关的工业用水区是指从事取卤、晒盐、食品加工、海水淡化和从海水中提取供人食用的其他化学元素等的区域。 （七）一般工业用水区是指利用海水做冷却水、冲刷库场等的区域。 （八）滨海风景旅游区是指风景秀丽、气候宜人，供人观赏、旅游的沿岸或海洋区域。 （九）海洋港口水域是指沿海港口以及河流入海处附近，以靠泊海船为主的港口，包括港"},{"i":20,"n":"第二十条","txt":"本办法自公布之日起施行。"}],"bumentongjidiaochaxiangmuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强部门统计调查项目的规范性、统一性管理，提高统计调查的科学性和有效性，减轻统计调查对象负担，推进部门统计信息共享，根据《中华人民共和国统计法》及其实施条例和国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于国务院各部门制定的统计调查项目。"},{"i":3,"n":"第三条","txt":"本办法所称的统计调查项目，是指国务院有关部门通过调查表格、问卷、行政记录、大数据以及其他方式搜集整理统计资料，用于政府管理和公共服务的各类统计调查项目。"},{"i":4,"n":"第四条","txt":"国家统计局统一组织领导和协调全国统计工作，指导国务院有关部门开展统计调查，统一管理部门统计调查。"},{"i":5,"n":"第五条","txt":"国务院有关部门应当明确统一组织协调统计工作的综合机构，负责归口管理、统一申报本部门统计调查项目。"},{"i":6,"n":"第六条","txt":"国务院有关部门执行相关法律、行政法规、国务院的决定和履行本部门职责，需要开展统计活动的，应当制定相应的部门统计调查项目。"},{"i":7,"n":"第七条","txt":"制定部门统计调查项目，应当减少调查频率，缩小调查规模，降低调查成本，减轻基层统计人员和统计调查对象的负担。可以通过行政记录和大数据加工整理获得统计资料的，不得开展统计调查；可以通过已经批准实施的各种统计调查整理获得统计资料的，不得重复开展统计调查；抽样调查、重点调查可以满足需要的，不得开展全面统计调查。"},{"i":8,"n":"第八条","txt":"制定部门统计调查项目，应当有组织、人员和经费保障。"},{"i":9,"n":"第九条","txt":"制定部门统计调查项目，应当同时制定该项目的统计调查制度。 统计调查制度内容包括总说明、报表目录、调查表式、分类目录、指标解释、指标间逻辑关系，采用抽样调查方法的还应当包括抽样方案。 统计调查制度总说明应当对调查目的、调查对象、统计范围、调查内容、调查频率、调查时间、调查方法、组织实施方式、质量控制、报送要求、信息共享、资料公布等作出规定。 面向单位的部门统计调查，其统计调查对象应当取自国家基本单位名录库或者部门基本单位名录库。"},{"i":10,"n":"第十条","txt":"部门统计调查应当规范设置统计指标、调查表，指标解释和计算方法应当科学合理。"},{"i":11,"n":"第十一条","txt":"部门统计调查应当使用国家统计标准。无国家统计标准的，可以使用经国家统计局批准的部门统计标准。"},{"i":12,"n":"第十二条","txt":"新制定的部门统计调查项目或者对现行统计调查项目进行较大修订的，应当开展试填试报等工作。其中，重要统计调查项目应当进行试点。"},{"i":13,"n":"第十三条","txt":"部门统计调查项目涉及其他部门职责的，应当事先征求相关部门意见。"},{"i":14,"n":"第十四条","txt":"国务院有关部门制定的统计调查项目，统计调查对象属于本部门管辖系统或者利用行政记录加工获取统计资料的，报国家统计局备案；统计调查对象超出本部门管辖系统的，报国家统计局审批。 部门管辖系统包括本部门直属机构、派出机构和垂直管理的机构，省及省以下与部门对口设立的管理机构。"},{"i":15,"n":"第十五条","txt":"部门统计调查项目审批或者备案包括申报、受理、审查、反馈、决定等程序。"},{"i":16,"n":"第十六条","txt":"部门统计调查项目送审或者备案时，应当通过部门统计调查项目管理平台提交下列材料： （一）申请审批项目的部门公文或者申请备案项目的部门办公厅（室）公文； （二）部门统计调查项目审批或者备案申请表； （三）统计调查制度； （四）统计调查项目的论证报告、背景材料、经费保障等，修订的统计调查项目还应当提供修订说明； （五）征求有关地方、部门、统计调查对象和专家意见及其采纳情况； （六）制定机关按照会议制度集体讨论决定的会议纪要； （七）重要统计调查项目的试点报告； （八）由审批机关或者备案机关公布的统计调查制度的主要内容； （九）防范和惩治统计造假、弄虚作假责任规定。 前款第（一）项的公文应当同时提交纸质文件。"},{"i":17,"n":"第十七条","txt":"申请材料齐全并符合法定形式的，国家统计局予以受理。 申请材料不齐全或者不符合法定形式的，国家统计局应当一次告知需要补正的全部内容，制定机关应当按照国家统计局的要求予以补正。"},{"i":18,"n":"第十八条","txt":"统计调查制度应当列明下列事项： （一）向国家统计局报送的制定机关组织实施统计调查取得的具体统计资料清单； （二）主要统计指标公布的时间、渠道； （三）统计信息共享的内容、方式、时限、渠道、责任单位和责任人； （四）向统计信息共享数据库提供的统计资料清单； （五）统计调查对象使用国家基本单位名录库或者部门基本单位名录库的情况。"},{"i":19,"n":"第十九条","txt":"国家统计局对申请审批的部门统计调查项目进行审查，符合下列条件的部门统计调查项目，作出予以批准的书面决定： （一）具有法定依据或者确为部门公共管理和服务所必需； （二）与现有的国家统计调查项目和部门统计调查项目的主要内容不重复、不矛盾； （三）主要统计指标无法通过本部门的行政记录或者已有统计调查资料加工整理取得； （四）部门统计调查制度科学、合理、可行，并且符合本办法第八条、第九条和第十八条规定； （五）采用的统计标准符合国家有关规定； （六）符合统计法律法规和国家有关规定。 不符合前款规定的，国家统计局向制定机关提出修改意见；修改后仍不符合前款规定条件的，国家统计局作出不予批准的书面决定，并说明理由。"},{"i":20,"n":"第二十条","txt":"国家统计局对申请备案的部门统计调查项目进行审查，符合下列条件的部门统计调查项目，作出同意备案的书面决定： （一）统计调查项目的调查对象属于制定机关管辖系统，或者利用行政记录加工获取统计资料； （二）与现有的国家统计调查项目和部门统计调查项目的主要内容不重复、不矛盾； （三）部门统计调查制度科学、合理、可行，并且符合本办法第八条、第九条和第十八条规定。"},{"i":21,"n":"第二十一条","txt":"国家统计局在收到制定机关申请公文及完整的相关资料后，在20个工作日内完成审批，20个工作日内不能作出决定的，经审批机关负责人批准可以延长10日，并应当将延长审批期限的理由告知制定机关；在10个工作日内完成备案。完成时间以复函日期为准。 制定机关修改统计调查项目的时间，不计算在审批期限内。"},{"i":22,"n":"第二十二条","txt":"部门统计调查项目有下列情形之一的，国家统计局简化审批或者备案程序，缩短期限： （一）发生突发事件，需要迅速实施统计调查； （二）统计调查内容未做变动，统计调查项目有效期届满需要延长期限。"},{"i":23,"n":"第二十三条","txt":"部门统计调查项目实行有效期管理。审批的统计调查项目有效期为3年，备案的统计调查项目有效期为5年。统计调查制度对有效期规定少于3年的，从其规定。有效期以批准执行或者同意备案的日期为起始时间。 统计调查项目在有效期内需要变更内容的，制定机关应当重新申请审批或者备案。"},{"i":24,"n":"第二十四条","txt":"部门统计调查项目经国家统计局批准或者备案后，应当在统计调查表的右上角标明表号、制定机关、批准机关或者备案机关、批准文号或者备案文号、有效期限等标志。"},{"i":25,"n":"第二十五条","txt":"制定机关收到批准或者备案的书面决定后，在10个工作日内将标注批准文号或者备案文号和有效期限的统计调查制度发送到部门统计调查项目管理平台。"},{"i":26,"n":"第二十六条","txt":"国家统计局及时通过国家统计局网站公布批准或者备案的部门统计调查项目名称、制定机关、批准文号或者备案文号、有效期限和统计调查制度的主要内容。"},{"i":27,"n":"第二十七条","txt":"国务院有关部门应当健全统计工作流程规范，完善统计数据质量控制办法，夯实统计基础工作，严格按照国家统计局批准或者备案的统计调查制度组织实施统计调查。"},{"i":28,"n":"第二十八条","txt":"国务院有关部门在组织实施统计调查时，应当就统计调查制度的主要内容对组织实施人员进行培训；应当就法定填报义务、主要指标涵义和口径、计算方法、采用的统计标准和其他填报要求，向调查对象作出说明。"},{"i":29,"n":"第二十九条","txt":"国务院有关部门应当按《中华人民共和国统计法实施条例》的要求及时公布主要统计指标涵义、调查范围、调查方法、计算方法、抽样调查样本量等信息，对统计数据进行解释说明。"},{"i":30,"n":"第三十条","txt":"国务院有关部门组织实施统计调查应当遵守国家有关统计资料管理和公布的规定。"},{"i":31,"n":"第三十一条","txt":"部门统计调查取得的统计资料，一般应当在政府部门间共享。"},{"i":32,"n":"第三十二条","txt":"国务院有关部门建立统计调查项目执行情况评估制度，对实施情况、实施效果和存在问题进行评估，认为应当修改的，按规定报请国家统计局审批或者备案。"},{"i":33,"n":"第三十三条","txt":"国家统计局依法开展部门统计调查项目审批和备案工作，为国务院有关部门提供有关统计业务咨询、统计调查制度设计指导、统计业务培训等服务。"},{"i":34,"n":"第三十四条","txt":"国家统计局组织国务院有关部门共同维护、更新国家基本单位名录库，为部门统计调查提供调查单位名录和抽样框。"},{"i":35,"n":"第三十五条","txt":"国家统计局建立统计标准库，为部门统计调查提供国家统计标准和部门统计标准。"},{"i":36,"n":"第三十六条","txt":"国家统计局向国务院有关部门提供部门统计调查项目查询服务。"},{"i":37,"n":"第三十七条","txt":"国家统计局推动建立统计信息共享数据库，为国务院有关部门提供部门统计数据查询服务。"},{"i":38,"n":"第三十八条","txt":"国家统计局依法对部门统计调查制度执行情况进行监督检查，依法查处部门统计调查中的重大违法行为；县级以上地方人民政府统计机构依法查处本级和下级人民政府有关部门和统计调查对象执行部门统计调查制度中发生的统计违法行为。"},{"i":39,"n":"第三十九条","txt":"任何单位和个人有权向国家统计局举报部门统计调查违法行为。 国家统计局公布举报统计违法行为的方式和途径，依法受理、核实、处理举报，并为举报人保密。"},{"i":40,"n":"第四十条","txt":"县级以上人民政府有关部门积极协助本级人民政府统计机构查处统计违法行为，及时向县级以上人民政府统计机构移送有关统计违法案件材料。"},{"i":41,"n":"第四十一条","txt":"县级以上人民政府统计机构在调查部门统计违法行为或者核查部门统计数据时，有权采取《中华人民共和国统计法》第三十五条规定的下列措施： （一）发出检查查询书，向检查单位和调查对象查询部门统计调查项目有关事项； （二）要求检查单位和调查对象提供与部门统计调查有关的统计调查制度、调查资料、调查报告及其他相关证明和资料； （三）就与检查有关的事项询问有关人员； （四）进入检查单位和调查对象的业务场所和统计数据处理信息系统进行检查、核对； （五）经本机构负责人批准，登记保存检查单位与统计调查有关的统计调查制度、调查资料、调查报告及其他相关证明和资料； （六）对与检查事项有关的情况和资料进行记录、录音、录像、照相和复制。 县级以上人民政府统计机构进行监督检查时，监督检查人员不得少于2人，并应当出示执法证件；未出示的，有关部门有权拒绝检查。"},{"i":42,"n":"第四十二条","txt":"县级以上人民政府统计机构履行监督检查职责时，有关部门应当如实反映情况，提供相关证明和资料，不得拒绝、阻碍检查，不得转移、隐匿、篡改、毁弃与部门统计调查有关的统计调查制度、调查资料、调查报告及其他相关证明和资料。"},{"i":43,"n":"第四十三条","txt":"县级以上人民政府有关部门在组织实施部门统计调查活动中有下列行为之一的，由上级人民政府统计机构、本级人民政府统计机构责令改正，予以通报： （一）违法制定、实施部门统计调查项目； （二）未执行国家统计标准或者经依法批准的部门统计标准； （三）未执行批准和备案的部门统计调查制度； （四）在部门统计调查中统计造假、弄虚作假。"},{"i":44,"n":"第四十四条","txt":"县级以上人民政府有关部门及其工作人员有下列行为之一的，由上级人民政府统计机构、本级人民政府统计机构责令改正，予以通报： （一）拒绝、阻碍对部门统计调查的监督检查和对部门统计违法行为的查处； （二）包庇、纵容部门统计违法行为； （三）向存在部门统计违法行为的单位或者个人通风报信，帮助其逃避查处。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府统计机构在查处部门统计违法行为中，认为对有关国家工作人员依法应当给予处分的，应当提出给予处分的建议，将处分建议和案件材料移送该国家工作人员的任免机关或者监察机关。"},{"i":46,"n":"第四十六条","txt":"中央编办管理机构编制的群众团体机关、经授权代主管部门行使统计职能的国家级集团公司和工商领域联合会或者协会等开展的统计调查项目，参照部门统计调查项目管理。 县级以上地方人民政府统计机构对本级人民政府有关部门制定的统计调查项目管理，参照本办法执行。"},{"i":47,"n":"第四十七条","txt":"本办法自2017年10月1日起施行。国家统计局1999年公布的《部门统计调查项目管理暂行办法》同时废止。"}],"pushehaididianlanguandaoguanliguidingshishibanfa":[{"i":1,"n":"第一条","txt":"为实施《铺设海底电缆管道管理规定》（以下简称《规定》），加强对海底电缆、管道的管理和保护，制定本实施办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国的内海、领海及大陆架上进行海底电缆、管道铺设及以为铺设所进行的路由调查、勘测及其他有关活动的任何法人、自然人和其他经济实体。"},{"i":3,"n":"第三条","txt":"中华人民共和国国家海洋局及其所属分局以及沿海省、自治区、直辖市人民政府海洋管理机构（以下简称地方海洋管理机构）是实施本办法的主管机关。"},{"i":4,"n":"第四条","txt":"国家对铺设海底电缆、管道及其他有关活动的管理，实行统一领导、分级管理。 地方海洋管理机构负责其管理海城内海底电缆、管道的审批与监督管理（本条第五款第三项所指管道的审批除外）。 分局负责地方海洋管理机构管理海域之外的海底电缆、管道的审批与监督管理。跨省、自治区、直辖市管理海域和超出省、自治区、直辖市管理海城的海底电缆、管道，由分局商有关地方海洋管理机构审批，并负责监督管理。 下列海底电缆、管道由国家海洋局负责审批∶ 一、路经中国管辖海域和大陆架的外国海底电缆、管道; 二、由中国铺向其他国家和地区的国际海底电缆、管道; 三、国内长距离（二百公里以上）的海底管道和污水排放量为二十万吨/日以上的海底排污管道。"},{"i":5,"n":"第五条","txt":"海底电缆、管道的路由调查、勘测，所在者应依照《规定》第五条，将《路由调查、勘测申请书》一式五份按本办法第四条报相应的审批机关审批。 外国的公司、企业和其他经济组织或个人中国大陆架上进行上述活动的。所有者应在实施作业六十天前，将《规定》条五直条要求提供的资料一式五份按本办法第四条报相应的审批机关，其确定的调查、勘测路由需经主管机关同意。 《路由调查、勘测申请书》应附具以下资料∶ 一、调查、勘测路由选择依据的详细说明; 二、调查、勘测单位的基本情况; 三、《铺设海底管道工程对海洋资源和环境影响报告书》的编写大纲和评价单位的基本情况; 四、《污水排海工程可行性研究报告》;五、其他有关说明资料。"},{"i":6,"n":"第六条","txt":"海底电缆、管道的铺设施工，所有者应依照《规定》第六条，将所确定的路由及《路由调查、勘测报告》等有关资料一式五份，按本办法第四条报相应的审批机关审批。审批机关审批后发给铺设施工许可证。 外国的公司、企业和其他经济组织或个人在中国大陆架上进行上述活动的，所在者应在实施作业六十天前，将《规定》第六条要求提供的资料一式五份按本办法第四条报相应的审批机关，其确定的路由需经主管机关同意。"},{"i":7,"n":"第七条","txt":"所有者在选择海底电缆、管道路由时，应顾及其他海洋开发利用。当路由需穿越重要渔捞作业区、海洋油气开采区、军事区、锚地和海底电缆、管道等并发生矛盾时，所有者应与有关当事方协商或报请主管机关协调解决。 设置海底排污管道应充分考虑排放海域的使用功能，排污口的位置应选择在远离海洋自然保护区、重要渔业水域、海水浴场、海滨风景游览区等区域的具有足够水深、海面宽阔、水体交换能力强等条件适当的场点，并符合国家的有关规定和标准。"},{"i":8,"n":"第八条","txt":"《路由调查、勘测报告》应包括以下内容; 一、调查概况; 二、路由海区的气象与水文动力状况;三、路由海区的工程地质条件; 四、与该海底电缆、管道工程建设和维护有关的其他海洋开发活动和海底设施;五、有关政府机构在路由海区的开发利用规划;六、路由条件的综合评价及其结论;七、有关图件及其他调查资料。"},{"i":9,"n":"第九条","txt":"《铺设海底管道工程对海洋资源和环境影响报告书》的内容应包括; 一、海底管道途经简域海洋资源和环境的状况; 二、海底管道海上铺设施工作业阶段及其正常使用阶段对周围海域海洋资源和生态环境及其他海洋开发利用活动影响的综合评价及对上述影响的解决方法;三、海底管道事故状态对海洋资源和环境产生影响的评价及其应急措施。"},{"i":10,"n":"第十条","txt":"获准的海底电缆、管道路由调查、勘测和铺设施工。在实施作业前或实施作业中如需变动（包括;路由、作业时间、作业计划、作业方式等变动），所有者应及时报告主管机关。如路由等变动较大，应报经主管机关批准。海上作业者应持有主管机关签发的铺设施工许可证。"},{"i":11,"n":"第十一条","txt":"铺设海底电缆、管道及其他海上作业，需要移动、切断已铺设的海底电缆、管道时。应当先与所有者协商，就交越施工的技术处理及报失赔偿等问题达成协议，并报经主管机关批准后方可施工。在协商和执行过程中，双方如有纠纷，可由主管机关协调解决。"},{"i":12,"n":"第十二条","txt":"海底电缆、管道铺设施工完毕后九十天内，所有者应将海底电缆、管道准确路线图、位置表等说明资料一式五份报送主管机关备案，并抄送有关港务监督机关。"},{"i":13,"n":"第十三条","txt":"海底电缆、管道的维修、改造、拆除，所有者应在实施作业三十天前，将作业内容、原因、时间、海区及作业船只等情况书面报告主管机关。海底电缆、管道 的紧急修理，所有者可在维修船进入现场作业的同时，按上述内容向主管机关报告前说明紧急修理的理由。 外国船舶需要在中国内海、领海进行前款所述作业的，应经主管机关批准。海底电缆、管道路由变动较大的改造，所有者事先应报经主管机关批准。上述作业完毕后三十天内。所有者应将作业结果报告主管机关。"},{"i":14,"n":"第十四条","txt":"海底电缆、管道的废弃，所有者应当在六十天前向主管机关书面报告，内容应包括∶废弃的原因、废弃的准确时间、废弃部分的准确位置及处置办法、废弃部分对其他海洋开发利用可能产生的影响及采取的防治措施。 废弃的海底电缆、管道应当妥善处理，不得对正常的海洋开发利用活动构成威胁或妨碍。"},{"i":15,"n":"第十五条","txt":"海底电缆、管道的铺设、维修、拆除等海上施工作业，应兼顾其他海上正常开发利用活动，当两者在作业时间和作业海区等方面发生矛盾时，所有者应当与有关当事方协调解决。"},{"i":16,"n":"第十六条","txt":"主管机关应将所辖海区已铺设或废弃的海底电缆、管道的路由情况定期予以公告。"},{"i":17,"n":"第十七条","txt":"从事海上各种活动的作业者。应了解作业海区海底电缆、管道的布设情况。凡需在海底电缆、管道路由两侧各两海里（港内为两侧各一百米》范围内从事可能危及海底电缆、管道安全和使用效能的作业的，应事先与所有者协商并报经主管机关批准。"},{"i":18,"n":"第十八条","txt":"主管机关可对进行海底电缆、管道路由调查、勘测和铺设、维修、改造、拆除等活动的船舶进行监视或检查。进行上述活动的船舶应为主管机关海洋监察人员执行公务提供方便。 外国籍船舶在中国大陆架上进行前款所述的活动期间（包括作业、锚泊、检修、漂泊等》，应于每天02时（格林威治时间》向主管机关报告船位;在中国的内海、领海进行前款所述的活动期间（包括作业、锚泊、检修、漂泊等），应干每天、o8时（格林威治时间）向主管机关报告船位。"},{"i":19,"n":"第十九条","txt":"为海洋石油开发所铺设的海底电缆、管道，按下列要求报主管机关审批或备案; 一、对包含在油（气）田总体开发方案中的路由超出石油开发区的海底电缆、管道，所有者应在该方案审批前，将初选路由等资料一式五份按本办法第四条报相应的审批机关。由审批机关商国家能源部门审定。在实施上述路由调查、勘测六十天前，所有者应将《规定》第五条要求提供的资料报主管机关备案。在实施铺设施工六十天前，所有者应将最后确定的路由等资料一式五份，依照《规定》第六条的有关要求报主管机关批准，由主管机关发给铺设施工许可证。 二、对在石油开发区内铺设平台间或者平台与单点系泊间的海底电缆、管道，在实施路由调查、勘测和铺设施工六十天前，所有者应分别将《规定》第五条、第六条要求提供的资料报主管机关备案。 《规定》第五条未作规定的情况，所有者应按《规定》和本办法的其他有关条款 执行。"},{"i":20,"n":"第二十条","txt":"对违反《规定》及本办法的，主管机关有权依其情节轻重，给予下列一种或几种处罚∶警告、罚款和现令停止海上作业。 罚款分为以下几种∶ 一、凡有下列行为之一者，罚款最高额为人民币一万元; （一）海上作业者未持有主管机关已签发的铺设施工许可证的; （二）阻挠或妨碍主管机关海洋监察人员执行公务的; （三）未按本办法第十二条的要求，将有关资料报主管机关备案的。二、凡有下列行为之一者，罚款最高额为人民币五万元∶ （一）获准的路由调查、勘测或铺设施工发生变动，未按本办法第十条执行的;（二》海底电缆、管道的铺设、维修、改造、拆除和废弃，未按本办法第十三条、第十四条、第十五条执行的; （三）海底电缆、管道的铺设或者拆除等工程的遗留物未妥善处理，对正常的海洋开发利用活动构成威胁或妨碍的; （四》违反本办法第十一条，移动已铺设的海底电缆、管道的; （五》违反本办法第十七条，从事可能危及海底电缆、管道安全和使用效"},{"i":21,"n":"第二十一条","txt":"当事人对处罚决定不服的，可以在接到处罚通知之日起 15日内，向作出处罚决定的机关的上一级机关申请复议;对复议决定不服的，可以在接到复议决定书之日起 15日内，向人民法院起诉。当事人也可以在接到处罚通知之日起15日内直接向人民法院起诉。当事人逾期不申请复议，也不向人民法院起诉，又不履行处罚决定的，由作出处罚决定的机关申请人民法院强执行。"},{"i":22,"n":"第二十二条","txt":"违反《规定》的本办法，造成海洋资源、环境或海底电缆、管道等公私财产损害和海上正常秩序危害的，肇事者应承担赔偿责任。赔偿责任包括∶ 一、受害方经济收入的损失金额及被破坏海底电缆、管道的修复、更新费用;二、清除、治理由于海底管道遭受损害而引起的污染所支付的费用和由于污染而引起的海洋资源的损失金额及为防止损害所采取的应急措施所支付的费用; 三、调查、处理损害事件的费用。"},{"i":23,"n":"第二十三条","txt":"略偿责任和赔偿金额的纠纷。当事人可请求主管机关进行调解处理。当事人也可依照民事诉讼程序向人民法院提起诉讼。涉外案件可以按仲裁程序解决。 第二＋四条 请求赔偿的诉讼时效期间为二年，从受害方知道或应当知道受损害之日开始计算。 赔偿纠纷处理结束后，受害方不得就同一损害事件再次提出索赔要求。"},{"i":24,"n":"第二十五条","txt":"由于不可抗拒的自然灾害或仅为了保全人命或船舶的正当目的在采取避免破坏和损害的一切必要预防措施后，仍然发生了任何海底电缆、管道损坏的，可减轻或免除赔偿责任的决定。 请求免于承担或减轻责任的条件调查属实后，可作出免除或减轻赔偿责任的作业者，可向主管机关提交报告。主管机关对免除或减轻责任的条件调查属实后，可作出免弥或减轻赔偿责任的决定 完全是由于第三者的故意或过失造成海底电缆、管道破坏或损害的，由第三者承担赔偿责任。"},{"i":25,"n":"第二十六条","txt":"中国军用海底电缆、管道的铺设依照《规定》执行，具体实施办法由中国人民解放军根据《规定》和本办法制定。"},{"i":26,"n":"第二十七条","txt":"《规定》及本办法下列用语的含义是∶ 一、\"海底电缆、管道\"系指位于大潮高潮线以下的军用和民用的海底通信电缆（含光缆）和电力电缆及输水（含工业废水、城市污水等）、输气、输油和输送其他物质的管状设植。 二、\"内海\"系指领海基线内侧的全部海域（包括海博、海峡、海港、河口湾）;领海基线与海岸之间的海域;通过狭窄水道连接海洋的海域。 三、\"所有者\"系指对海底电缆、管道拥有产权和所有权的法人和其他经济实体，四、\"路由变动较大\"系指出于主观要求而非定位误差和施工技术手段的原因，而改变批准的或原有的路由，暂定为∶在潮间带五百米以上、领薄线以内一公里以上、领海线以外五公里以上。 五、\"移动\"系指海底电缆、管道的水平移位或垂直移位。"},{"i":27,"n":"第二十八条","txt":"本办法由国家海洋局负责解释。"},{"i":28,"n":"第二十九条","txt":"本办法自颁布之日起施行。"}],"fangzhihanduolvlianbendianlizhuangzhijiqifeiwuwura2da053":[{"i":1,"n":"第一条","txt":"为加强含多氯联苯电力装置及其废物的管理，防止多氯联苯污染环境，特制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的含多氯联苯电力装置及其废物是指以多氯联苯为介质的电力电容器、变压器及其他有关装置和由此产生的含多氯联苯的废物。"},{"i":3,"n":"第三条","txt":"本规定适用于含多氯联苯电力装置的使用和由此产生的含多氯联苯废物其废弃后的收集、贮存、运输、处理、装置以及污染管理和进出口活动。"},{"i":4,"n":"第四条","txt":"各人民政府的环境保护部门对所辖地区的多氯联苯污染防治工作实施统一监督管理。拥有含多氯联苯电力装置单位的主管部门，对本系统内含多氯联苯电力装置的污染防治实施监督管理。"},{"i":5,"n":"第五条","txt":"拥有含多氯联苯电力装置及多氯联苯废物的营运单位和个人对多氯联苯污染环境的全过程负责，承担相应责任。对造成多氯联苯污染的个人，地方各级环境保护部门可责令其限期治理。对造成多氯联苯污染的单位，地方各级环境保护部门可向地方人民政府建议对其进行限期治理，被限期治理的单位和个人必须如期完成治理任务。"},{"i":6,"n":"第六条","txt":"拥有含多氯联苯电力装置的营运单位和个人必须在市级环境保护部门规定的时间内向当地人民政府环境保护部门进行申报登记。如实填写《含多氯联苯电力装置登记表》(附件一)，申报单位须经上级主管部门核实后报当地环境保护部门，个人直接向当地环境部门申报登记。受理申报登记的环境保护部门，应在批准登记之日起一个月内向上级环境保护部门备案。转移、处理、处置含多氯联苯电力装置和多氯联苯废液，应提前五天申报并征得所在地环境保护部门的同意。"},{"i":7,"n":"第七条","txt":"正在使用含多氯联苯电力装置的单位必须采取措施防止多氯联苯泄露污染环境。使用单位及其主管部门应制定具体的管理办法。"},{"i":8,"n":"第八条","txt":"严禁任何单位和个人出售、收购、拆解含多氯联苯电力装置。"},{"i":9,"n":"第九条","txt":"任何单位和个人转移、运输含多氯联苯废电力装置及含多氯联苯废物，必须经市级以上人民政府环境保护部门批准后方可进行。跨行政区转移和运输的，须经共同的上级人民政府环境保护部门批准。转移和运输过程中，必须有防止泄漏的有效措施和应急措施，并符合国家危险物品运输规定。"},{"i":10,"n":"第十条","txt":"处理、处置含多氯联苯废物的活动，必须经市级主管部门和市级环境保护部门审查并经省级人民政府环境保护部门批准后方可进行。"},{"i":11,"n":"第十一条","txt":"含多氯联苯废电力装置，多氯联苯废液和受多氯联苯污染的物质，应进行集中封存管理。集中封存或在暂时贮存场所暂存的活动必须经省级人民政府环境保护部门批准，并在市级以上人民政府环境保护部门的监督下进行。"},{"i":12,"n":"第十二条","txt":"暂存库和集中封存库的选址和设计必须符合《含多氯联苯(PCBS)废物的暂存库和集中封存库设计规范》(附件二)。建设集中封存库必须进行环境影响评价。"},{"i":13,"n":"第十三条","txt":"集中封存和暂存场所必须建立管理制度，采取有效的安全保卫措施，设置明显的毒害标志，定期对存放场所及可能影响的范围进行监测。"},{"i":14,"n":"第十四条","txt":"人民政府环境保护部门应对集中封存场所周围的环境进行不定期监测。"},{"i":15,"n":"第十五条","txt":"对受多氯联苯污染的水体和土壤，参照《含多氯联苯(PCBS)水质、土壤污染控制值(暂定)进行使用和管理(附件三)。"},{"i":16,"n":"第十六条","txt":"地方各级人民政府环境保护部门应在人民政府的组织下协同有关部门采取有效措施，收缴流失在社会的含多氯联苯废电力装置和含多氯联苯的废物。"},{"i":17,"n":"第十七条","txt":"严禁我国管辖区外的含多氯联苯废电力装置、废液及受多氯联苯污染的物质入境。严格控制进口含多氯联苯介质的电力设备，特殊情况确须进口的，须经能源部和国家环境保护局审批。"},{"i":18,"n":"第十八条","txt":"一切单位和个人有权对造成多氯联苯污染的单位和个进行检举和控告。"},{"i":19,"n":"第十九条","txt":"对违反本规定，造成多氯联苯污染的单位和个人必须依法承担相应的法律责任。"},{"i":20,"n":"第二十条","txt":"本规定由国家环境保护局负责解释。"},{"i":21,"n":"第二十一条","txt":"本规定自1991年3月1日起施行。 　　 　　 　　附件一： 　　 含多氯联苯电力装置登记表 　　 　　登记号：＿＿＿＿＿＿ 　　登记单位名称（盖章）＿＿＿＿＿＿＿＿ 　　法定代表人 （盖章）＿＿＿＿＿＿＿＿ 　　地 址＿＿＿＿＿＿＿＿ 　　邮 政 编 码＿＿＿＿＿＿＿＿ 　　登 记 日 期＿＿＿＿＿＿＿＿ 　　国家环境保护局 　　 　　填 表 须 知 　　1.填报人员必须按照《含多氯联苯电力装置登记表》表（注）的规定和要求填写。 　　2.填报数据一律用阿拉伯数字，文字说明一律用汉字。 　　3.必须用钢笔，兰、黑墨水均可，不得使用圆珠笔或铅笔。要求书写工整、清晰，不得了草、涂改。 　　４.本表一式三份。报单位主管部门一份，报地方环境保护部门一份。如需增加份数，由各地环境保护部门确定。 　　 　　基 本 情 况－－－－－－－－－－ 　　部门细分类＿＿＿＿＿＿ 类型＿＿＿＿＿ 主管部门名称"}],"lushengyeshengdongwuziyuanbaohuguanlifeishoufeiban3244e2":[],"lingshouyaodianyiliaobaozhangdingdianguanlizanxinge7e2a7":[{"i":1,"n":"第一条","txt":"为加强和规范零售药店医疗保障定点管理，提高医疗保障基金使用效率，更好地保障广大参保人员权益，根据《中华人民共和国社会保险法》《中华人民共和国基本医疗卫生与健康促进法》及《中华人民共和国药品管理法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"零售药店医疗保障定点管理应坚持以人民健康为中心，遵循保障基本、公平公正、权责明晰、动态平衡的原则，加强医疗保障精细化管理，发挥零售药店市场活力，为参保人员提供适宜的药品服务。"},{"i":3,"n":"第三条","txt":"医疗保障行政部门负责制定零售药店定点管理政策，在定点申请、专业评估、协商谈判、协议订立、协议履行、协议解除等环节对医疗保障经办机构（以下简称“经办机构”）、定点零售药店进行监督。经办机构负责确定定点零售药店，并与定点零售药店签订医疗保障服务协议（以下简称“医保协议”），提供经办服务，开展医保协议管理、考核等。定点零售药店应当遵守医疗保障法律、法规、规章及有关政策，按照规定向参保人员提供药品服务。"},{"i":4,"n":"第四条","txt":"统筹地区医疗保障行政部门根据公众健康需求、管理服务需要、医疗保障基金收支、参保人员用药需求等确定本统筹地区定点零售药店的资源配置。"},{"i":5,"n":"第五条","txt":"取得药品经营许可证，并同时符合以下条件的零售药店均可申请医疗保障定点： （一）在注册地址正式经营至少3个月； （二）至少有1名取得执业药师资格证书或具有药学、临床药学、中药学专业技术资格证书的药师，且注册地在该零售药店所在地，药师须签订1年以上劳动合同且在合同期内； （三）至少有2名熟悉医疗保障法律法规和相关制度规定的专（兼）职医保管理人员负责管理医保费用，并签订1年以上劳动合同且在合同期内； （四）按药品经营质量管理规范要求，开展药品分类分区管理，并对所售药品设立明确的医保用药标识； （五）具有符合医保协议管理要求的医保药品管理制度、财务管理制度、医保人员管理制度、统计信息管理制度和医保费用结算制度； （六）具备符合医保协议管理要求的信息系统技术和接口标准，实现与医保信息系统有效对接，为参保人员提供直接联网结算，建立医保药品等基础数据库，按规定使用国家统一医保编码； （七）符合法律法"},{"i":6,"n":"第六条","txt":"零售药店向统筹地区经办机构提出医疗保障定点申请，至少提供以下材料： （一）定点零售药店申请表； （二）药品经营许可证、营业执照和法定代表人、主要负责人或实际控制人身份证复印件； （三）执业药师资格证书或药学技术人员相关证书及其劳动合同复印件； （四）医保专（兼）职管理人员的劳动合同复印件； （五）与医疗保障政策对应的内部管理制度和财务制度文本； （六）与医保有关的信息系统相关材料； （七）纳入定点后使用医疗保障基金的预测性分析报告； （八）省级医疗保障行政部门按相关规定要求提供的其他材料。"},{"i":7,"n":"第七条","txt":"零售药店提出定点申请，统筹地区经办机构应即时受理。对申请材料内容不全的，经办机构自收到材料之日起5个工作日内一次性告知零售药店补充。"},{"i":8,"n":"第八条","txt":"统筹地区经办机构应组织评估小组或委托符合规定的第三方机构，以书面、现场等形式开展评估。评估小组成员由医疗保障、医药卫生、财务管理、信息技术等专业人员构成。自受理申请材料之日起，评估时间不超过3个月，零售药店补充材料时间不计入评估期限。评估内容包括： （一）核查药品经营许可证、营业执照和法定代表人、企业负责人或实际控制人身份证； （二）核查执业药师资格证书或药学技术人员资格证书及劳动合同； （三）核查医保专（兼）职管理人员的劳动合同； （四）核查与医疗保障政策对应的内部管理制度和财务制度； （五）核查与医保有关的信息系统是否具备开展直接联网结算的条件； （六）核查医保药品标识。 评估结果包括合格和不合格。统筹地区经办机构应将评估结果报同级医疗保障行政部门备案。对于评估合格的，纳入拟签订医保协议的零售药店名单向社会公示。对于评估不合格的应告知其理由，提出整改建议。自结果告知送达之日起，整改"},{"i":9,"n":"第九条","txt":"统筹地区经办机构与评估合格的零售药店协商谈判，达成一致的，双方自愿签订医保协议。原则上由地市级及以上的统筹地区经办机构与零售药店签订医保协议并向同级医疗保障行政部门备案。医保协议应明确双方的权利、义务和责任。签订医保协议的双方应当严格执行医保协议约定。医保协议期限一般为1年。"},{"i":10,"n":"第十条","txt":"统筹地区经办机构向社会公布签订医保协议的定点零售药店信息，包括名称、地址等，供参保人员选择。"},{"i":11,"n":"第十一条","txt":"零售药店有下列情形之一的，不予受理定点申请： （一）未依法履行行政处罚责任的； （二）以弄虚作假等不正当手段申请定点，自发现之日起未满3年的； （三）因违法违规被解除医保协议未满3年或已满3年但未完全履行行政处罚法律责任的； （四）因严重违反医保协议约定而被解除医保协议未满1年或已满1年但未完全履行违约责任的； （五）法定代表人、企业负责人或实际控制人曾因严重违法违规导致原定点零售药店被解除医保协议，未满5年的； （六）法定代表人、企业负责人或实际控制人被列入失信人名单的； （七）法律法规规定的其他不予受理的情形。"},{"i":12,"n":"第十二条","txt":"定点零售药店具有为参保人员提供药品服务后获得医保结算费用，对经办机构履约情况进行监督，对完善医疗保障政策提出意见建议等权利。"},{"i":13,"n":"第十三条","txt":"定点零售药店应当为参保人员提供药品咨询、用药安全、医保药品销售、医保费用结算等服务。符合规定条件的定点零售药店可以申请纳入门诊慢性病、特殊病购药定点机构，相关规定由统筹地区医疗保障部门另行制定。 经办机构不予支付的费用、定点零售药店按医保协议约定被扣除的质量保证金及其支付的违约金等，定点零售药店不得作为医保欠费处理。"},{"i":14,"n":"第十四条","txt":"定点零售药店应当严格执行医保支付政策。鼓励在医疗保障行政部门规定的平台上采购药品，并真实记录“进、销、存”情况。"},{"i":15,"n":"第十五条","txt":"定点零售药店要按照公平、合理、诚实信用和质价相符的原则制定价格，遵守医疗保障行政部门制定的药品价格政策。"},{"i":16,"n":"第十六条","txt":"定点零售药店应当凭处方销售医保目录内处方药，药师应当对处方进行审核、签字后调剂配发药品。外配处方必须由定点医疗机构医师开具，有医师签章。定点零售药店可凭定点医疗机构开具的电子外配处方销售药品。"},{"i":17,"n":"第十七条","txt":"定点零售药店应当组织医保管理人员参加由医疗保障行政部门或经办机构组织的宣传和培训。 定点零售药店应当组织开展医疗保障基金相关制度、政策的培训，定期检查本单位医疗保障基金使用情况，及时纠正医疗保障基金使用不规范的行为。"},{"i":18,"n":"第十八条","txt":"定点零售药店在显著位置悬挂统一格式的定点零售药店标识。"},{"i":19,"n":"第十九条","txt":"定点零售药店应按要求及时如实向统筹地区经办机构上传参保人员购买药品的品种、规格、价格及费用信息，定期向经办机构上报医保目录内药品的“进、销、存”数据，并对其真实性负责。"},{"i":20,"n":"第二十条","txt":"定点零售药店应当配合经办机构开展医保费用审核、稽核检查、绩效考核等工作，接受医疗保障行政部门的监督检查，并按规定提供相关材料。"},{"i":21,"n":"第二十一条","txt":"定点零售药店提供药品服务时应核对参保人员有效身份凭证，做到人证相符。特殊情况下为他人代购药品的应出示本人和被代购人身份证。为参保人员提供医保药品费用直接结算单据和相关资料，参保人员或购药人应在购药清单上签字确认。凭外配处方购药的，应核验处方使用人与参保人员身份是否一致。"},{"i":22,"n":"第二十二条","txt":"定点零售药店应将参保人员医保目录内药品外配处方、购药清单等保存2年，以备医疗保障部门核查。"},{"i":23,"n":"第二十三条","txt":"定点零售药店应做好与医保有关的信息系统安全保障工作，遵守数据安全有关制度，保护参保人员隐私。定点零售药店重新安装信息系统时，应当保持信息系统技术接口标准与医保信息系统有效对接，并按规定及时全面准确向医保信息系统传送医保结算和审核所需的有关数据。"},{"i":24,"n":"第二十四条","txt":"经办机构有权掌握定点零售药店的运行管理情况，从定点零售药店获得医保费用稽查审核、绩效考核和财务记账等所需要的信息数据等资料。"},{"i":25,"n":"第二十五条","txt":"经办机构应当完善定点申请、组织评估、协议签订、协议履行、协议变更和解除等流程管理，制定经办规程，为定点零售药店和参保人员提供优质高效的经办服务。"},{"i":26,"n":"第二十六条","txt":"经办机构应做好对定点零售药店医疗保障政策、管理制度、支付政策、操作流程的宣传培训，提供医疗保障咨询、查询服务。"},{"i":27,"n":"第二十七条","txt":"经办机构应当落实医保支付政策，加强医疗保障基金管理。"},{"i":28,"n":"第二十八条","txt":"经办机构应当建立完善的内部控制制度，明确对定点零售药店医保费用的审核、结算、拨付、稽核等岗位责任及风险防控机制。完善重大医保药品费用支出集体决策制度。"},{"i":29,"n":"第二十九条","txt":"经办机构应当加强医疗保障基金支出管理，通过智能审核、实时监控、现场检查等方式及时审核医保药品费用。对定点零售药店进行定期和不定期稽查审核，按医保协议约定及时足额向定点零售药店拨付医保费用。原则上，应当在定点零售药店申报后30个工作日内拨付符合规定的医保费用。"},{"i":30,"n":"第三十条","txt":"定点零售药店经审查核实的违规医保费用，经办机构不予支付。"},{"i":31,"n":"第三十一条","txt":"经办机构应当依法依规支付参保人员在定点零售药店发生的药品费用。 参保人员应凭本人参保有效身份凭证在定点零售药店购药。不得出租（借）本人有效身份凭证给他人，不得套取医疗保障基金。在非定点零售药店发生的药品费用，医疗保障基金不予支付。"},{"i":32,"n":"第三十二条","txt":"经办机构向社会公开医保信息系统数据集和接口标准。定点零售药店自主选择与医保对接的有关信息系统的运行和维护供应商。经办机构不得以任何名义收取任何费用及指定供应商。"},{"i":33,"n":"第三十三条","txt":"经办机构应遵守数据安全有关制度，保护参保人员隐私，确保医疗保障基金安全。"},{"i":34,"n":"第三十四条","txt":"经办机构或其委托的第三方机构，对定点零售药店开展绩效考核，建立动态管理机制。考核结果与年终清算、质量保证金退还、医保协议续签等挂钩。绩效考核办法由国家医疗保障部门制定，省级医疗保障部门可制定具体考核细则，经办机构负责组织实施。"},{"i":35,"n":"第三十五条","txt":"经办机构发现定点零售药店存在违反医保协议约定情形的，可按医保协议约定相应采取以下处理方式： （一）约谈法定代表人、主要负责人或实际控制人； （二）暂停结算、不予支付或追回已支付的医保费用； （三）要求定点零售药店按照医保协议约定支付违约金； （四）中止或解除医保协议。"},{"i":36,"n":"第三十六条","txt":"经办机构违反医保协议的，定点零售药店有权要求纠正或者提请医疗保障行政部门协调处理、督促整改，也可以依法申请行政复议或者提起行政诉讼。 医疗保障行政部门发现经办机构存在违反医保协议约定的，可视情节相应采取以下处理方式：约谈主要负责人、限期整改、通报批评，对相关责任人员依法依规给予处分。 医疗保障行政部门发现经办机构违反相关法律法规和规章的，依法依规进行处理。"},{"i":37,"n":"第三十七条","txt":"定点零售药店的名称、法定代表人、企业负责人、实际控制人、注册地址和药品经营范围等重要信息发生变更的，应自有关部门批准之日起30个工作日内向统筹地区经办机构提出变更申请，其他一般信息变更应及时书面告知。"},{"i":38,"n":"第三十八条","txt":"续签应由定点零售药店于医保协议期满前3个月向经办机构提出申请或由经办机构统一组织。统筹地区经办机构和定点零售药店就医保协议续签事宜进行协商谈判，双方根据医保协议履行情况和绩效考核情况等决定是否续签。协商一致的，可续签医保协议；未达成一致的，医保协议解除。"},{"i":39,"n":"第三十九条","txt":"医保协议中止是指经办机构与定点零售药店暂停履行医保协议约定，中止期间发生的医保费用不予结算。中止期结束，未超过医保协议有效期的，医保协议可继续履行；超过医保协议有效期的，医保协议终止。 定点零售药店可提出中止医保协议申请，经经办机构同意，可以中止医保协议但中止时间原则上不得超过180日，定点零售药店在医保协议中止超过180日仍未提出继续履行医保协议申请的，原则上医保协议自动终止。定点零售药店有下列情形之一的，经办机构应中止医保协议： （一）根据日常检查和绩效考核，发现对医疗保障基金安全和参保人员权益可能造成重大风险的； （二）未按规定向医疗保障行政部门及经办机构提供有关数据或提供数据不真实的； （三）根据医保协议约定应当中止医保协议的； （四）法律法规和规章规定的应当中止的其他情形。"},{"i":40,"n":"第四十条","txt":"医保协议解除是指经办机构与定点零售药店之间的医保协议解除，协议关系不再存续，医保协议解除后产生的医药费用，医疗保障基金不再结算。定点零售药店有下列情形之一的，经办机构应解除医保协议，并向社会公布解除医保协议的零售药店名单： （一）医保协议有效期内累计2次及以上被中止医保协议或中止医保协议期间未按要求整改或整改不到位的； （二）发生重大药品质量安全事件的； （三）以弄虚作假等不正当手段申请取得定点的； （四）以伪造、变造医保药品“进、销、存”票据和账目、伪造处方或参保人员费用清单等方式，骗取医疗保障基金的； （五）将非医保药品或其他商品串换成医保药品，倒卖医保药品或套取医疗保障基金的； （六）为非定点零售药店、中止医保协议期间的定点零售药店或其他机构进行医保费用结算的； （七）将医保结算设备转借或赠与他人，改变使用场地的； （八）拒绝、阻挠或不配合经办机构开展智能审核、绩效考核等，情节恶"},{"i":41,"n":"第四十一条","txt":"定点零售药店主动提出中止医保协议、解除医保协议或不再续签的，应提前3个月向经办机构提出申请。地市级及以上的统筹地区经办机构与定点零售药店中止或解除医保协议，该零售药店在其他统筹区的医保协议也同时中止或解除。"},{"i":42,"n":"第四十二条","txt":"定点零售药店与统筹地区经办机构就医保协议签订、履行、变更和解除发生争议的，可以自行协商解决或者请求同级医疗保障行政部门协调处理，也可提起行政复议或行政诉讼。"},{"i":43,"n":"第四十三条","txt":"医疗保障行政部门对定点申请、申请受理、专业评估、协议订立、协议履行和解除等进行监督，对经办机构的内部控制制度建设、医保费用的审核和拨付等进行指导和监督。 医疗保障行政部门依法依规通过实地检查、抽查、智能监控、大数据分析等方式对定点零售药店的医保协议履行情况、医疗保障基金使用情况、药品服务等进行监督。"},{"i":44,"n":"第四十四条","txt":"医疗保障行政部门和经办机构应拓宽监督途径、创新监督方式，通过满意度调查、第三方评价、聘请社会监督员等方式对定点零售药店进行社会监督，畅通举报投诉渠道，及时发现问题并进行处理。"},{"i":45,"n":"第四十五条","txt":"医疗保障行政部门发现定点零售药店存在违约情形的，应当及时责令经办机构按照医保协议处理。定点零售药店违反法律法规规定的，依法依规处理。"},{"i":46,"n":"第四十六条","txt":"经办机构发现违约行为，应当及时按照医保协议处理。 经办机构作出中止或解除医保协议处理时，要及时报告同级医疗保障行政部门。 医疗保障行政部门发现定点零售药店存在违约情形的，应当及时责令经办机构按照医保协议处理，经办机构应当及时按照协议处理。 医疗保障行政部门依法查处违法违规行为时，认为经办机构移交相关违法线索事实不清的，可组织补充调查或要求经办机构补充材料。"},{"i":47,"n":"第四十七条","txt":"职工基本医疗保险、城乡居民基本医疗保险、生育保险、医疗救助、居民大病保险等医疗保障定点管理工作按照本办法执行。"},{"i":48,"n":"第四十八条","txt":"本办法中的经办机构是具有法定授权，实施医疗保障管理服务的职能机构，是医疗保障经办的主体。 零售药店是符合《中华人民共和国药品管理法》规定，领取药品经营许可证的药品零售企业。 定点零售药店是指自愿与统筹地区经办机构签订医保协议，为参保人员提供药品服务的实体零售药店。 医保协议是指由经办机构与零售药店经协商谈判而签订的，用于规范双方权利、义务及责任等内容的协议。"},{"i":49,"n":"第四十九条","txt":"国务院医疗保障行政部门制作并定期修订医保协议范本，国家医疗保障经办机构制定经办规程并指导各地加强和完善协议管理。地市级及以上的医疗保障行政部门及经办机构在此基础上，可根据实际情况分别细化制定本地区的协议范本及经办规程。协议内容应根据法律、法规、规章和医疗保障政策调整变化相一致，医疗保障行政部门予以调整医保协议内容时，应征求相关定点零售药店意见。"},{"i":50,"n":"第五十条","txt":"本办法由国务院医疗保障行政部门负责解释，自2021年2月1日起施行。"}],"zhenhoudizhenqushipandinggonggaoguiding":[{"i":1,"n":"第一条","txt":"为了加强对震后地震趋势判定公告的管理，根据《中华人民共和国防震减灾法》和《地震预报管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"震后地震趋势判定，是指对社会产生影响的地震事件发生后，对地震影响地区近期内地震活动形势的分析结果。震后地震事件的预报按《地震预报管理条例》执行。"},{"i":3,"n":"第三条","txt":"本规定所称对社会产生影响的地震事件主要指： （一）在人口稠密、经济发达地区发生的普遍有感地震； （二）破坏性地震； （三）严重破坏性地震。"},{"i":4,"n":"第四条","txt":"对社会产生影响的地震事件发生后，有关县级以上地方人民政府负责管理地震工作的机构应当组织召开震情会商会，对本辖区近期内地震活动形势进行综合分析研究，形成震后地震趋势判定意见。 市、县人民政府负责管理地震工作的机构形成的震后地震趋势判定意见，应当向省、自治区、直辖市人民政府负责管理地震工作的机构报告。 省、自治区、直辖市人民政府负责管理地震工作的机构应当将破坏性地震和严重破坏性地震后形成的震后地震趋势判定意见向国务院地震工作主管部门报告。"},{"i":5,"n":"第五条","txt":"在人口稠密、经济发达地区发生的普遍有感地震的震后地震趋势判定和破坏性地震的震后地震趋势判定，由有关县级以上地方人民政府负责管理地震工作的机构向本级人民政府报告，并可以适时向社会公告。"},{"i":6,"n":"第六条","txt":"严重破坏性地震发生后的震后地震趋势判定，由有关省、自治区、直辖市人民政府负责管理地震工作的机构向本级人民政府报告，并可以适时向社会公告。"},{"i":7,"n":"第七条","txt":"国务院地震工作主管部门根据社会需要，可以适时向社会公告地震事件的震后地震趋势判定。"},{"i":8,"n":"第八条","txt":"北京市发生对社会产生影响的地震事件后，由国务院地震工作主管部门和北京市人民政府负责管理地震工作的机构，组织召开震情会商会，形成统一的震后地震趋势判定意见，分别向国务院和北京市人民政府报告，国务院地震工作主管部门和北京市人民政府负责管理地震工作的机构可以适时向社会公告。"},{"i":9,"n":"第九条","txt":"其他任何组织和个人关于震后地震趋势判定的意见，应当向当地人民政府负责管理地震工作的机构或者国务院地震工作主管部门报告，不得擅自向社会公告。"},{"i":10,"n":"第十条","txt":"对违反本规定，擅自公告震后地震趋势判定，造成不良社会影响的组织和个人，由国务院地震工作主管部门或者省、自治区、直辖市人民政府负责管理地震工作的机构给予警告；扰乱社会正常秩序的，由公安机关依法给予治安管理处罚。"},{"i":11,"n":"第十一条","txt":"本规定自发布之日起施行。"}],"lingshirenzhengbanfa":[{"i":1,"n":"第一条","txt":"为了规范领事认证工作，维护领事认证公信力，促进对外交往，保障自然人、法人或者其他组织的合法权益，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于国内出具的需送往国外使用的文书和国外出具的需送至国内使用的文书的领事认证。"},{"i":3,"n":"第三条","txt":"本办法所称领事认证，是指领事认证机构根据自然人、法人或者其他组织的申请，对国内涉外公证书、其他证明文书或者国外有关文书上的最后一个印鉴、签名的真实性予以确认的活动。 前款所称领事认证机构，是指依照本办法办理领事认证的机构，包括外交部、外交部委托的地方人民政府外事部门（以下称地方外办）和驻外使馆、领馆以及外交部委托的其他驻外机构。 领事认证机构委托代办接件、录入、咨询等服务性事务的单位，应当在委托范围内从事相关活动。"},{"i":4,"n":"第四条","txt":"领事认证机构办理领事认证，应当遵守法律，坚持客观、真实的原则，不得损害国家利益和社会公共利益。"},{"i":5,"n":"第五条","txt":"外交部负责国家领事认证工作。"},{"i":6,"n":"第六条","txt":"领事认证分为国内文书的领事认证和国外文书的领事认证。 外交部和地方外办负责办理国内文书的领事认证。 驻外使馆、领馆以及外交部委托的其他驻外机构负责办理国外文书的领事认证。"},{"i":7,"n":"第七条","txt":"领事认证人员包括领事认证签署人员和领事认证协助人员。 领事认证签署人员负责审核、签署工作。 领事认证协助人员负责受理、制证、收费等事务性工作。"},{"i":8,"n":"第八条","txt":"外交部和驻外使馆、领馆以及外交部委托的其他驻外机构的领事认证签署人员应当为随员及以上外交职务或者领事随员及以上领事职务。 地方外办的领事认证签署人员应当为主任科员及以上职务。 领事认证签署人员应当具有3年以上外交或者外事工作经历，具备领事认证签署工作所需的专业知识和能力，并参加外交部组织的相应培训。 驻外使馆、领馆以及外交部委托的其他驻外机构和地方外办的领事认证签署人员应当报外交部备案，特殊情况应当报外交部批准。"},{"i":9,"n":"第九条","txt":"领事认证人员不得实施下列行为： （一）为本人及其近亲属办理领事认证或者办理与本人及其近亲属有利害关系的领事认证； （二）未按规定程序出具领事认证书； （三）故意毁损、篡改领事认证书或者领事认证档案； （四）侵占、盗窃领事认证防伪纸张、印章等专用物品； （五）利用办理领事认证的职务便利索取财物，或者牟取其他不正当利益； （六）其他法律、行政法规禁止的行为。"},{"i":10,"n":"第十条","txt":"领事认证的申请人以及其他个人或者组织不得实施下列行为： （一）利用领事认证书从事非法活动； （二）伪造、变造领事认证书； （三）伪造或者擅自变动、改动经领事认证的公证书或者其他证明文书。"},{"i":11,"n":"第十一条","txt":"领事认证机构在办理领事认证前应当依照本章规定对相应印鉴和签名式样进行备案。"},{"i":12,"n":"第十二条","txt":"国内公证机构以及其他证明机构应当将相应印鉴以及公证员、签署人的签名式样向外交部、地方外办进行备案。"},{"i":13,"n":"第十三条","txt":"地方外办应当将用于领事认证的印鉴以及领事认证签署人员的姓名、职务、签名式样送有关国家驻华领事机构备案。"},{"i":14,"n":"第十四条","txt":"外交部应当将用于领事认证的印鉴以及领事认证签署人员的姓名、衔级、签名式样送有关国家驻华使馆备案。"},{"i":15,"n":"第十五条","txt":"驻外使馆、领馆以及外交部委托的其他驻外机构应当对驻在国认证机构的印鉴和签署人员的姓名、职务和签名式样进行备案。"},{"i":16,"n":"第十六条","txt":"驻外使馆、领馆以及外交部委托的其他驻外机构、地方外办应当将领事认证签署人员的姓名、衔级（职务）、签名式样报外交部备案。"},{"i":17,"n":"第十七条","txt":"印鉴、签名式样自备案之日起10个工作日后生效。"},{"i":18,"n":"第十八条","txt":"领事认证签署人员不再行使签署职责的，有关机构应当及时将被取消签署权人员的姓名、衔级（职务）、取消签署权的日期等事项通知原备案机构。"},{"i":19,"n":"第十九条","txt":"国内出具的需送往国外使用的文书，文书使用国要求领事认证的，经国内公证机构公证或者证明机构证明后，应当送外交部或者地方外办办理领事认证，方可送文书使用国驻华使馆或者领事机构办理认证。 中国缔结或者参加的国际条约或者外交部另有规定的除外。"},{"i":20,"n":"第二十条","txt":"国外出具的需送至国内使用的文书，中国法律法规规定或者文书使用机构要求认证的，经文书出具国有关机构公证、认证后，应当由中国驻该国使馆、领馆或者外交部委托的其他驻外机构办理领事认证。 中国缔结或者参加的国际条约或者外交部另有规定的除外。"},{"i":21,"n":"第二十一条","txt":"申请办理领事认证，应当提交以下材料： （一）合法有效的身份证件； （二）填写真实、完整、准确的申请表； （三）申请领事认证的文书； （四）领事认证机构认为需要提交的其他材料。"},{"i":22,"n":"第二十二条","txt":"领事认证机构可以根据需要向申请人核实申办领事认证的目的和领事认证书的用途等情况，必要时可以要求申请人提交相关证明材料。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，领事认证机构不予办理领事认证： （一）文书的印鉴、签名不属实的； （二）文书的印鉴、签名未进行备案，或者与备案不相符的； （三）文书的印鉴、签名、装订、时效等不符合文书出具机构、文书使用机构规定和要求的； （四）可能损害国家利益和社会公共利益的； （五）不予办理领事认证的其他情形。"},{"i":24,"n":"第二十四条","txt":"申请人提交的办理领事认证的文书在两页及以上的，应当采用火漆加封、加盖骑缝章或者加盖钢印等不易被拆换的方式进行装订。"},{"i":25,"n":"第二十五条","txt":"领事认证机构经过审查，认为申请领事认证的文书符合要求的，应当自受理申请之日起10个工作日内出具领事认证书。 因不可抗力、补充证明材料或者需要核实有关情况的，所需时间不计算在前款规定的期限内。"},{"i":26,"n":"第二十六条","txt":"领事认证书应当包括下列内容： （一）领事认证书编号； （二）领事认证证词； （三）出具领事认证书的机构名称； （四）领事认证签署人员的签名； （五）出具领事认证书的日期。"},{"i":27,"n":"第二十七条","txt":"领事认证书自出具之日起生效。 领事认证书应当采用领事认证贴纸的形式粘贴在办理领事认证的文书上，具体式样、内容由外交部负责制定。"},{"i":28,"n":"第二十八条","txt":"领事认证书应当使用规范汉字。"},{"i":29,"n":"第二十九条","txt":"申请人申请办理领事认证应当按照国务院财政部门、价格主管部门的规定缴纳相关费用。"},{"i":30,"n":"第三十条","txt":"领事认证机构经过审查，认为申请办理领事认证的文书、手续或者其他材料不齐全的，应当一次性告知申请人需要履行的手续和补充的证明材料。"},{"i":31,"n":"第三十一条","txt":"领事认证是领事认证机构以国家名义对文书予以确认的活动，其目的是使一国出具的文书能在另一国境内得以承认，不会因为怀疑文书上的印鉴、签名的真实性而影响其域外的法律效力。 领事认证不对公证书或者其他证明文书证明的事项行使证明职能，不对文书内容本身的真实性、合法性负责，文书内容由文书出具机构负责。"},{"i":32,"n":"第三十二条","txt":"经领事认证的文书内容被更改、替换的，领事认证书无效。"},{"i":33,"n":"第三十三条","txt":"申请人和已经领事认证的文书内容的利害关系人，对领事认证机构出具的领事认证书有异议的，可以向出具该领事认证书的领事认证机构提出复查申请。"},{"i":34,"n":"第三十四条","txt":"领事认证机构收到复查申请后，应当进行审查、核实。对于领事认证书的编号、证词、出证日期等内容错误的，应当及时予以纠正。"},{"i":35,"n":"第三十五条","txt":"已经领事认证的公证书或者其他证明文书依法定程序确定有错误而进行更正的，原公证书或者其他证明文书上的领事认证书自动失效。申请人可以持更正后的公证书或者其他证明文书重新申请办理领事认证。 已经领事认证的公证书或者其他证明文书依法定程序撤销的，领事认证书自该公证书或者其他证明文书因撤销而失效之日起同时自动失效。"},{"i":36,"n":"第三十六条","txt":"领事认证人员有本办法第九条规定行为之一的，由有关机关依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"申请人以及其他个人或者组织有本办法第十条规定行为之一的，依法承担相应的法律责任。"},{"i":38,"n":"第三十八条","txt":"本办法所称文书，是指出生证、结婚证、学历证、原产地证、商业发票、含有非纸质材料的文件等各类证书以及文字材料等的总称。"},{"i":39,"n":"第三十九条","txt":"本办法自2016年3月1日起施行。"}],"yinyongshuishuiyuanbaohuquwuranfangzhiguanliguidin2e9abc-2":[{"i":1,"n":"第一条","txt":"为保障人民身体健康和经济建设发展，必须保护好饮用水水源。根据《中华人民共和国水污染防治法》特制订本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于全国所有集中式供水的饮用水地表水源和地下水源的污染防治管理。"},{"i":3,"n":"第三条","txt":"按照不同的水质标准和防护要求分级划分饮用水水源保护区。饮用水水源保护区一般划分为一级保护区和二级保护区，必要时可增设准保护区。各级保护区应有明确的地理界线。"},{"i":4,"n":"第四条","txt":"饮用水水源各级保护区及准保护区均应规定明确的水质标准并限期达标。"},{"i":5,"n":"第五条","txt":"饮用水水源保护区的设置和污染防治应纳入当地的经济和社会发展规划和水污染防治规划。跨地区的饮用水水源保护区的设置和污染防治应纳入有关流域、区域、城市的经济和社会发展规划和水污染防治规划。"},{"i":6,"n":"第六条","txt":"跨地区的河流、湖泊、水库、输水渠道，其上游地区不得影响下游饮用水水源保护区对水质标准的要求。"},{"i":7,"n":"第七条","txt":"饮用水地表水源保护区包括一定的水域和陆域，其范围应按照不同水域特点进行水质定量预测并考虑当地具体条件加以确定，保证在规划设计的水文条件和污染负荷下，供应规划水量时，保护区的水质能满足相应的标准。"},{"i":8,"n":"第八条","txt":"在饮用水地表水源取水口附近划定一定的水域和陆域作为饮用水地表水源一级保护区。一级保护区的水质标准不得低于国家规定的《地表水环境质量标准》Ⅱ类标准，并须符合国家规定的《生活饮用水卫生标准》的要求。"},{"i":9,"n":"第九条","txt":"在饮用水地表水源一级保护区外划定一定的水域和陆域作为饮用水地表水源二级保护区。二级保护区的水质标准不得低于国家规定的《地表水环境质量标准》Ⅲ类标准，应保证一级保护区的水质能满足规定的标准。"},{"i":10,"n":"第十条","txt":"根据需要可在饮用水地表水源二级保护区外划定一定的水域及陆域作为饮用水地表水源准保护区。准保护区的水质标准应保证二级保护区的水质能满足规定的标准。"},{"i":11,"n":"第十一条","txt":"饮用水地表水源各级保护区及准保护区内均必须遵守下列规定： 一、禁止一切破坏水环境生态平衡的活动以及破坏水源林、护岸林、与水源保护相关植被的活动。 二、禁止向水域倾倒工业废渣、城市垃圾、粪便及其它废弃物。 三、运输有毒有害物质、油类、粪便的船舶和车辆一般不准进入保护区，必须进入者应事先申请并经有关部门批准、登记并设置防渗、防溢、防漏设施。 四、禁止使用剧毒和高残留农药，不得滥用化肥，不得使用炸药、毒品捕杀鱼类。"},{"i":12,"n":"第十二条","txt":"饮用水地表水源各级保护区及准保护区内必须分别遵守下列规定： 一、一级保护区内 禁止新建、扩建与供水设施和保护水源无关的建设项目； 禁止向水域排放污水，已设置的排污口必须拆除； 不得设置与供水需要无关的码头，禁止停靠船舶； 禁止堆置和存放工业废渣、城市垃圾、粪便和其他废弃物； 禁止设置油库； 禁止从事种植、放养禽畜和网箱养殖活动； 禁止可能污染水源的旅游活动和其他活动。 二、二级保护区内 禁止新建、改建、扩建排放污染物的建设项目； 原有排污口依法拆除或者关闭； 禁止设立装卸垃圾、粪便、油类和有毒物品的码头。 三、准保护区内 禁止新建、扩建对水体污染严重的建设项目；改建建设项目，不得增加排污量。"},{"i":13,"n":"第十三条","txt":"饮用水地下水源保护区应根据饮用水水源地所处的地理位置、水文地质条件、供水的数量、开采方式和污染源的分布划定。"},{"i":14,"n":"第十四条","txt":"饮用水地下水源保护区的水质均应达到国家规定的《生活饮用水卫生标准》的要求。 各级地下水源保护区的范围应根据当地的水文地质条件确定，并保证开采规划水量时能达到所要求的水质标准。"},{"i":15,"n":"第十五条","txt":"饮用水地下水源一级保护区位于开采井的周围，其作用是保证集水有一定滞后时间，以防止一般病原菌的污染。直接影响开采井水质的补给区地段，必要时也可划为一级保护区。"},{"i":16,"n":"第十六条","txt":"饮用水地下水源二级保护区位于饮用水地下水源一级保护区外，其作用是保证集水有足够的滞后时间，以防止病原菌以外的其它污染。"},{"i":17,"n":"第十七条","txt":"饮用水地下水源准保护区位于饮用水地下水源二级保护区外的主要补给区，其作用是保护水源地的补给水源水量和水质。"},{"i":18,"n":"第十八条","txt":"饮用水地下水源各级保护区及准保护区内均必须遵守下列规定： 一、禁止利用渗坑、渗井、裂隙、溶洞等排放污水和其它有害废弃物。 二、禁止利用透水层孔隙、裂隙、溶洞及废弃矿坑储存石油、天然气、放射性物质、有毒有害化工原料、农药等。 三、实行人工回灌地下水时不得污染当地地下水源。"},{"i":19,"n":"第十九条","txt":"饮用水地下水源各级保护区及准保护区内必须遵守下列规定： 一、一级保护区内 禁止建设与取水设施无关的建筑物； 禁止从事农牧业活动； 禁止倾倒、堆放工业废渣及城市垃圾、粪便和其它有害废弃物； 禁止输送污水的渠道、管道及输油管道通过本区； 禁止建设油库； 禁止建立墓地。 二、二级保护区内 （一）对于潜水含水层地下水水源地 禁止建设化工、电镀、皮革、造纸、制浆、冶炼、放射性、印染、染料、炼焦、炼油及其它有严重污染的企业，已建成的要限期治理，转产或搬迁； 禁止设置城市垃圾、粪便和易溶、有毒有害废弃物堆放场和转运站，已有的上述场站要限期搬迁； 禁止利用未经净化的污水灌溉农田，已有的污灌农田要限期改用清水灌溉； 化工原料、矿物油类及有毒有害矿产品的堆放场所必须有防雨、防渗措施。 （二）对于承压含水层地下水水源地 禁止承压水和潜水的混合开采，作好潜水的止水措施。 三、准保护区内 禁止建设城市垃圾、粪便"},{"i":20,"n":"第二十条","txt":"各级人民政府的环境保护部门会同有关部门作好饮用水水源保护区的污染防治工作并根据当地人民政府的要求制定和颁布地方饮用水水源保护区污染防治管理规定。"},{"i":21,"n":"第二十一条","txt":"饮用水水源保护区的划定，由有关市、县人民政府提出划定方案，报省、自治区、直辖市人民政府批准；跨市、县饮用水水源保护区的划定，由有关市、县人民政府协商提出划定方案，报省、自治区、直辖市人民政府批准；协商不成的，由省、自治区、直辖市人民政府环境保护主管部门会同同级水行政、国土资源、卫生、建设等部门提出划定方案，征求同级有关部门的意见后，报省、自治区、直辖市人民政府批准。 跨省、自治区、直辖市的饮用水水源保护区，由有关省、自治区、直辖市人民政府商有关流域管理机构划定；协商不成的，由国务院环境保护主管部门会同同级水行政、国土资源、卫生、建设等部门提出划定方案，征求国务院有关部门的意见后，报国务院批准。 国务院和省、自治区、直辖市人民政府可以根据保护饮用水水源的实际需要，调整饮用水水源保护区的范围，确保饮用水安全。"},{"i":22,"n":"第二十二条","txt":"环境保护、水利、地质矿产、卫生、建设等部门应结合各自的职责，对饮用水水源保护区污染防治实施监督管理。"},{"i":23,"n":"第二十三条","txt":"因突发性事故造成或可能造成饮用水水源污染时，事故责任者应立即采取措施消除污染并报告当地城市供水、卫生防疫、环境保护、水利、地质矿产等部门和本单位主管部门。由环境保护部门根据当地人民政府的要求组织有关部门调查处理，必要时经当地人民政府批准后采取强制性措施以减轻损失。"},{"i":24,"n":"第二十四条","txt":"对执行本规定保护饮用水水源有显著成绩和贡献的单位或个人给予表扬和奖励。其奖励办法由市级以上（含市级）环境保护部门制定，报经当地人民政府批准实施。"},{"i":25,"n":"第二十五条","txt":"对违反本规定的单位或个人，应根据《中华人民共和国水污染防治法》及其实施细则的有关规定进行处罚。"},{"i":26,"n":"第二十六条","txt":"本规定由国家环境保护部门负责解释。"},{"i":27,"n":"第二十七条","txt":"本规定自公布之日起实施。"}],"yinyongshuishuiyuanbaohuquwuranfangzhiguanliguidin2e9abc":[{"i":1,"n":"第一条","txt":"为保障人民身体健康和经济建设发展，必须保护好饮用水水源。根据《中华人民共和国水污染防治法》特制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于全国所有集中式供水的饮用水地表水源和地下水源的污染防治管理。"},{"i":3,"n":"第三条","txt":"按照不同的水质标准和防护要求分级划分饮用水水源保护区。饮用水水源保护区一般划分为一级保护区和二级保护区，必要时可增设准保护区。各级保护区应有明确的地理界线。"},{"i":4,"n":"第四条","txt":"饮用水水源各级保护区及准保护区均应规定明确的水质标准并限期达标。"},{"i":5,"n":"第五条","txt":"饮用水水源保护区的设置和污染防治应纳入当地的经济和社会发展规划和水污染防治规划。跨地区的饮用水水源保护区的设置和污染治理应纳入有关流域、区域、城市的经济和社会发展规划和水污染防治规划。"},{"i":6,"n":"第六条","txt":"跨地区的河流、湖泊、水库、输水渠道，其上游地区不得影响下游饮用水水源保护区对水质标准的要求。"},{"i":7,"n":"第七条","txt":"饮用水地表水源保护区包括一定的水域和陆域，其范围应按照不同水域特点进行水质定量预测并考虑当地具体条件加以确定，保证在规划设计的水文条件和污染负荷下，供应规划水量时，保护区的水质能满足相应的标准。"},{"i":8,"n":"第八条","txt":"在饮用水地表水源取水口附近划定一定的水域和陆域作为饮用水地表水源一级保护区。一级保护区的水质标准不得低于国家规定的《地表水环境质量标准》Ⅱ类标准，并须符合国家规定的《生活饮用水卫生标准》的要求。"},{"i":9,"n":"第九条","txt":"在饮用水地表水源一级保护区外划定一定水域和陆域作为饮用水地表水源二级保护区。二级保护区的水质标准不得低于国家规定的《地表水环境质量标准》Ⅲ类标准，应保证一级保护区的水质能满足规定的标准。"},{"i":10,"n":"第十条","txt":"根据需要可在饮用水地表水源二级保护区外划定一定的水域及陆域作为饮用水地表水源准保护区。准保护区的水质标准应保证二级保护区的水质能满足规定的标准。"},{"i":11,"n":"第十一条","txt":"饮用水地表水源各级保护区及准保护区内均必须遵守下列规定： 一、禁止一切破坏水环境生态平衡的活动以及破坏水源林、护岸林、与水源保护相关植被的活动。 二、禁止向水域倾倒工业废渣、城市垃圾、粪便及其它废弃物。 三、运输有毒有害物质、油类、粪便的船舶和车辆一般不准进入保护区，必须进入者应事先申请并经有关部门批准、登记并设置防渗、防溢、防漏设施。 四、禁止使用剧毒和高残留农药，不得滥用化肥，不得使用炸药、毒品捕杀鱼类。"},{"i":12,"n":"第十二条","txt":"饮用水地表水源各级保护区及准保护区内必须分别遵守下列规定： 一、一级保护区内 禁止新建、扩建与供水设施和保护水源无关的建设项目； 禁止向水域排放污水，已设置的排污口必须拆除； 不得设置与供水需要无关的码头，禁止停靠船舶； 禁止堆置和存放工业废渣、城市垃圾、粪便和其他废弃物； 禁止设置油库； 禁止从事种植、放养畜禽和网箱养殖活动； 禁止可能污染水源的旅游活动和其他活动。 二、二级保护区内 禁止新建、改建、扩建排放污染物的建设项目； 原有排污口依法拆除或者关闭； 禁止设立装卸垃圾、粪便、油类和有毒物品的码头。 三、准保护区内 禁止新建、扩建对水体污染严重的建设项目；改建建设项目，不得增加排污量。"},{"i":13,"n":"第十三条","txt":"饮用水地下水源保护区应根据饮用水水源地所处的地理位置、水文地质条件、供水的数量、开采方式和污染源的分布划定。"},{"i":14,"n":"第十四条","txt":"饮用水地下水源保护区的水质均应达到国家规定的《生活饮用水卫生标准》的要求。 各级地下水源保护区的范围应根据当地的水文地质条件确定，并保证开采规划水量时能达到所要求的水质标准。"},{"i":15,"n":"第十五条","txt":"饮用水地下水源一级保护区位于开采井的周围，其作用是保证集水有一定滞后时间，以防止一般病原菌的污染。直接影响开采井水质的补给区地段，必要时也可划为一级保护区。"},{"i":16,"n":"第十六条","txt":"饮用水地下水源二级保护区位于饮用水地下水源一级保护区外，其作用是保证集水有足够的滞后时间，以防止病原菌以外的其它污染。"},{"i":17,"n":"第十七条","txt":"饮用水地下水源准保护区位于饮用水地下水源二级保护区外的主要补给区，其作用是保护水源地的补给水源水量和水质。"},{"i":18,"n":"第十八条","txt":"饮用水地下水源各级保护区及准保护区内均必须遵守下列规定： 一、禁止利用渗坑、渗井、裂隙、溶洞等排放污水和其它有害废弃物。 二、禁止利用透水层孔隙、裂隙、溶洞及废弃矿坑储存石油、天然气、放射性物质、有毒有害化工原料、农药等。 三、实行人工回灌地下水时不得污染当地地下水源。"},{"i":19,"n":"第十九条","txt":"饮用水地下水源各级保护区及准保护区内必须遵守下列规定： 一、一级保护区内 禁止建设与取水设施无关的建筑物； 禁止从事农牧业活动； 禁止倾倒、堆放工业废渣及城市垃圾、粪便和其它有害废弃物； 禁止输送污水的渠道、管道及输油管道通过本区； 禁止建设油库； 禁止建立墓地。 二、二级保护区内 （一）对于潜水含水层地下水水源地 禁止建设化工、电镀、皮革、造纸、制浆、冶炼、放射性、印染、染料、炼焦、炼油及其它有严重污染的企业，已建成的要限期治理，转产或搬迁； 禁止设置城市垃圾、粪便和易溶、有毒有害废弃物堆放场和转运站，已有的上述场站要限期搬迁； 禁止利用未经净化的污水灌溉农田，已有的污灌农田要限期改用清水灌溉； 化工原料、矿物油类及有毒有害矿产品的堆放场所必须有防雨、防渗措施。 （二）对于承压含水层地下水水源地 禁止承压水和潜水的混合开采，作好潜水的止水措施。 三、准保护区内 禁止建设城市垃圾、粪便"},{"i":20,"n":"第二十条","txt":"各级人民政府的环境保护部门会同有关部门作好饮用水水源保护区的污染防治工作并根据当地人民政府的要求制定和颁布地方饮用水 水源保护区污染 防治管理规定。"},{"i":21,"n":"第二十一条","txt":"饮用水水源保护区的划定，由有关市、县人民政府提出划定方案，报省、自治区、直辖市人民政府批准；跨市、县饮用水水源保护区的划定，由有关市、县人民政府协商提出划定方案，报省、自治区、直辖市人民政府批准；协商不成的，由省、自治区、直辖市人民政府环境保护主管部门会同同级水行政、国土资源、卫生、建设等部门提出划定方案，征求同级有关部门的意见后，报省、自治区、直辖市人民政府批准。 跨省、自治区、直辖市的饮用水水源保护区，由有关省、自治区、直辖市人民政府商有关流域管理机构划定；协商不成的，由国务院环境保护主管部门会同同级水行政、国土资源、卫生、建设等部门提出划定方案，征求国务院有关部门的意见后，报国务院批准。 国务院和省、自治区、直辖市人民政府可以根据保护饮用水水源的实际需要，调整饮用水水源保护区的范围，确保饮用水安全。"},{"i":22,"n":"第二十二条","txt":"环境保护、水利、地质矿产、卫生、建设等部门应结合各自的职责，对饮用水 水源保护区污染 防治实施监督管理。"},{"i":23,"n":"第二十三条","txt":"因突发性事故造成或可能造成饮用水水源污染时，事故责任者应立即采取措施消除污染并报告当地城市供水、卫生防疫、环境保护、水利、地质矿产等部门和本单位主管部门。由环境保护部门根据当地人民政府的要求组织有关部门调查处理，必要时经当地人民政府批准后采取强制性措施以减轻损失。"},{"i":24,"n":"第二十四条","txt":"对执行本规定保护饮用水水源有显著成绩和贡献的单位或个人给予表扬和奖励。奖励办法由市级以上（含市级）环境保护部门制定，报经当地人民政府批准实施。"},{"i":25,"n":"第二十五条","txt":"对违反本规定的单位或个人，应根据《中华人民共和国水污染防治法》及其实施细则的有关规定进行处罚。"},{"i":26,"n":"第二十六条","txt":"本规定由国家环境保护部门负责解释。"},{"i":27,"n":"第二十七条","txt":"本规定自公布之日起实施。"}],"zhuwaiwaijiaorenyuandashixianbaoliuyuzhongzhizanxiba0905":[{"i":1,"n":"第一条","txt":"为了规范驻外外交人员大使衔的保留与终止,根据 《中华人民共和国驻外外交人员法》，参照有关国际惯例，制定本规定。"},{"i":2,"n":"第二条","txt":"具有大使衔的驻外外交人员离任回国后，从事外交工作确有需要的，其大使衔予以保留。有下列情形之一的，其大使衔应当终止： （一）辞职或者被辞退的； （二）受到降级以上行政处分或依据《中国共产党纪律处分条例》开除党籍的； （三）被依法判处剥夺政治权利或者有期徒刑以上刑罚的； （四）其他需要终止大使衔的情形。"},{"i":3,"n":"第三条","txt":"终止驻外外交人员大使衔，由外交部办理有关手续并报国务院备案。"},{"i":4,"n":"第四条","txt":"本规定由外交部负责解释。"},{"i":5,"n":"第五条","txt":"本规定自2013年2月1日起施行。"}],"gaodengjibingyuanweishengwushiyanshijiansheshencha331e0b":[{"i":1,"n":"第一条","txt":"为规范三级、四级病原微生物实验室（以下简称实验室）建设审查，根据《病原微生物实验室生物安全管理条例》（国务院令第424号）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"新建、改建、扩建实验室或者生产、进口移动式实验室应当报科学技术部审查同意。"},{"i":3,"n":"第三条","txt":"向科学技术部申请建设实验室，应当符合下列条件： （一）符合国家生物安全实验室体系建设规划要求； （二）开展实验室建设确属必要； （三）具备保障实验室规范安全运行的能力和机制； （四）符合法律法规规定的其他条件。"},{"i":4,"n":"第四条","txt":"符合第三条规定的申请单位向科学技术部提交《高等级病原微生物实验室建设审查申请书》（以下简称《申请书》）。《申请书》应当经其所在地的省级人民政府或按照行政隶属关系经国务院有关部门盖章同意。"},{"i":5,"n":"第五条","txt":"科学技术部设立实验室建设审查专家委员会（以下简称专家委员会）。专家委员会由从事实验室管理及相关领域科研工作的专家组成，任期5年。 专家委员会对实验室建设审查工作提供咨询意见。 专家委员会专家受科学技术部委托组成专家组，对每个具体实验室建设申请进行审查并提出专家组审查意见。专家组一般不少于5人。"},{"i":6,"n":"第六条","txt":"科学技术部将组织专家组对实验室建设申请进行专家审查。基本程序包括： （一）资料审核； （二）申请单位陈述； （三）现场勘查（现场审查方式）； （四）专家提问； （五）讨论形成专家组审查意见。"},{"i":7,"n":"第七条","txt":"专家组成员应遵守诚信和回避制度，客观、公正地开展工作。"},{"i":8,"n":"第八条","txt":"科学技术部根据专家组审查意见，经科学技术部部务会审定同意后形成科学技术部审查决定。"},{"i":9,"n":"第九条","txt":"科学技术部自收到申请单位报送的申请材料后，应当在5个工作日内完成形式审查。申请材料不齐全或不符合规定形式的，科学技术部应当在5个工作日内退回申请单位。申请材料齐全并符合规定形式的，科学技术部自受理之日起20个工作日内作出批准或者不予批准的决定；不予批准的应当说明理由。因特殊原因无法在规定期限内做出审查决定的，经科学技术部负责人批准可以延长10个工作日，并将延长期限的理由告知申请单位。"},{"i":10,"n":"第十条","txt":"申请单位对科学技术部审查决定有异议的，可自收到通知之日起15个工作日内以书面形式向科学技术部申请复核。科学技术部将组织专家进行复核审查。"},{"i":11,"n":"第十一条","txt":"实验室建设申请单位在实验室建设审查过程中存在弄虚作假等行为的，科学技术部将终止对其申请的审查或撤销已作出的审查决定，书面通知申请单位，并根据情节轻重决定在1-3年内不再受理其申请。"},{"i":12,"n":"第十二条","txt":"实验室建设申请与审查过程中涉及国家秘密的，应严格按照有关保密规定执行。"},{"i":13,"n":"第十三条","txt":"通过建设审查的实验室建成后，依据《病原微生物实验室生物安全管理条例》，由有关部门根据相关规定进行建筑质量验收、建设项目竣工环境保护验收、实验室国家认可和实验活动审批及监管等，确保实验室安全。"},{"i":14,"n":"第十四条","txt":"实验室建设申请与审查工作不收取任何费用。"},{"i":15,"n":"第十五条","txt":"本办法自2018年10月31日起施行。"},{"i":16,"n":"第十六条","txt":"本办法由科学技术部负责解释。"}]};
